"""test_nc_modules — die aus bot.py extrahierten nc-Module laufen
eigenstaendig gegen das ECHTE Bot-Schema.

Das Schema wird zur Laufzeit AUS bot.py gezogen (Klammer-Zaehlung, keine
Regex-Naeherung) und die f-String-Platzhalter werden mit den SQLite-Werten
aufgeloest. So kann der Test nicht gegen ein ausgedachtes Schema gruen werden —
genau der Fehler, der beim Bauen dieser Module mehrfach passiert ist.

Hintergrund: db_conn() ist nach nc.dbwrap gewandert. Das war der Schluessel zur
weiteren Modularisierung — ueber 100 Bot-Funktionen hingen AUSSCHLIESSLICH an
diesem einen Symbol und sind seitdem frei von Bot-Globals.
"""
import io
import os
import textwrap
import re
import sys
import pruefhilfen as _ph

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from nc.dbwrap import db_conn, configure_db          # noqa: E402
import nc.archive as archive                          # noqa: E402
import nc.notes as notes                              # noqa: E402
import nc.stats as stats                              # noqa: E402

TABLES = ["recording_notes", "bookmarks", "recording_annotations", "recordings",
          "trackings", "recording_attempts", "archive", "stream_chapters",
          "ai_conversations"]

# Werte aus dem SQLite-Zweig von _init_db() (bot.py)
PLACEHOLDERS = {"txt_idx": "TEXT", "txt_long": "TEXT", "txt_big": "TEXT",
                "ts": "TEXT",   # v4.0-W79: indizierter Timestamp (SQLite=TEXT, MariaDB=VARCHAR(64))
                "iv": "INTEGER", "tbl_opts": "",
                "pk": "INTEGER PRIMARY KEY AUTOINCREMENT"}

PASS = 0



def rumpf_ab(quelle, ab):
    """Von Offset `ab` bis zur naechsten Top-Level-Definition. -> str

    v4.2-W66. DER ERSATZ FUER `src[i:i + 3000]`. CLAUDE.md nennt die feste
    Zahl namentlich als Bruchstelle, und in W62 hat sie zugeschlagen:
    `src[j:j + 4200]` reichte nicht mehr ueber den gewachsenen Frame-Feeder
    und meldete „kein fester Takt", waehrend `stop.wait(takt)` zwei Zeilen
    dahinter stand. Ein Vertrag, der bei gesundem Code faellt, kostet eine
    Runde und lehrt, Vertragsbrueche nicht ernst zu nehmen.

    Das Fenster endet jetzt dort, wo die gepruefte Einheit endet, und waechst
    mit ihr. Zwei Formen, weil beide Quellen vorkommen:

      mit Zeilenumbruechen   „\ndef " trifft nur Top-Level — verschachtelte
                             Definitionen sind eingerueckt.
      zusammengefaltet       " ".join(quelle.split()) hat keine Zeilen mehr;
                             dort trennt " def ". Das schneidet notfalls an
                             einer verschachtelten Definition zu frueh ab —
                             und das ist die richtige Richtung: ein zu kurzer
                             Bereich laesst den Vertrag LAUT fallen, ein zu
                             langer laesst ihn still durchgehen. Genau der
                             stille Fall hat in W64 eine Mutationsprobe
                             durchrutschen lassen.
    """
    marken = (("\ndef ", "\nasync def ", "\nclass ") if "\n" in quelle[:4000]
              else (" def ", " async def ", " class "))
    enden = [quelle.find(m, ab + 1) for m in marken]
    ende = min([e for e in enden if e > 0] or [len(quelle)])
    return quelle[ab:ende]

def ok(msg):
    global PASS
    PASS += 1
    print("  \u2713 " + msg)


def _ist_monolith(modul: str) -> bool:
    """Zeigt der Modulname auf bot.py? Exakt oder als Paket-Praefix.

    Nach der Umbenennung von bot.py zu bot ist ein reiner startswith("bot")
    zu grob — er wuerde jedes Modul treffen, dessen Name so beginnt."""
    return modul == "bot" or modul.startswith("bot.")


def _extract_schema():
    """CREATE TABLE aus bot.py ziehen — Klammern zaehlen, nicht raten."""
    here = os.path.dirname(os.path.abspath(__file__))
    src = open(os.path.join(here, "nc", "schema.py")).read()  # B164: Schema extrahiert
    out = []
    for t in TABLES:
        i = src.find("CREATE TABLE IF NOT EXISTS " + t + " (")
        if i < 0:
            continue
        j = src.index("(", i)
        depth, k = 0, j
        while k < len(src):
            if src[k] == "(":
                depth += 1
            elif src[k] == ")":
                depth -= 1
                if depth == 0:
                    break
            k += 1
        out.append(src[i:k + 1])
    sql = ";\n".join(out)
    for a, b in PLACEHOLDERS.items():
        sql = sql.replace("{" + a + "}", b)
    left = re.findall(r"\{[^}]*\}", sql)
    assert not left, "unaufgeloeste Platzhalter: %s" % left
    assert len(out) >= 5, "Schema unvollstaendig: nur %d Tabellen" % len(out)
    return sql





def _test_dbexport():
    """V37-DBX: SQL-Export/Import fuer den SQLite<->MariaDB-Umstieg."""
    from nc.dbexport import (db_export_sql, db_import_sql, parse_header,
                             export_summary, _lit, _split_statements)

    # --- Der Dialekt-Fallstrick: Backslash ist in MySQL ein Escape ---
    p = "C:\\rec\\live.mp4"
    assert _lit(p, "sqlite") == "'C:\\rec\\live.mp4'", _lit(p, "sqlite")
    assert _lit(p, "mariadb") == "'C:\\\\rec\\\\live.mp4'", _lit(p, "mariadb")
    ok("dbexport: Backslash nur fuer mariadb verdoppelt (sonst still zerstoert)")

    assert _lit(None, "sqlite") == "NULL"
    assert _lit(True, "sqlite") == "1" and _lit(False, "sqlite") == "0"
    assert _lit(b"\x00\xff", "sqlite") == "X'00ff'"
    assert _lit("it's", "sqlite") == "'it''s'"
    ok("dbexport: NULL/bool/BLOB/Quote-Literale")

    # --- Splitter: Semikolon im Wert darf nicht trennen ---
    assert len(_split_statements(
        "INSERT INTO t VALUES ('a; b');\nINSERT INTO t VALUES ('c');")) == 2
    assert len(_split_statements("INSERT INTO t VALUES ('it''s; x');")) == 1
    assert len(_split_statements("-- komm; entar\nINSERT INTO t VALUES (1);")) == 1
    ok("dbexport: Splitter respektiert Strings, Quotes und Kommentare")

    # --- Roundtrip mit allen Fiesheiten ---
    rows = [("C:\\rec\\x.mp4", "hallo; welt", 1024, 1.5, b"\x00\xff"),
            ("/srv/a'b.mp4", "it's; ok?", None, None, None),
            ("/rec/\u00fcn\u00efcode.mp4", "Zeilen\numbruch", 7, 0.1, b"xyz")]
    with db_conn() as c:
        cur = c.cursor()
        cur.execute("CREATE TABLE dbx_t (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                    "p TEXT, n TEXT, i INTEGER, f REAL, b BLOB)")
        for r in rows:
            cur.execute("INSERT INTO dbx_t (p,n,i,f,b) VALUES (?,?,?,?,?)", r)

    sql = "".join(db_export_sql(dialect="sqlite"))
    h = parse_header(sql)
    assert h.get("dialect") == "sqlite" and h.get("rows", 0) >= 3, h
    ok("dbexport: Header traegt Dialekt + Kennzahlen (%d Zeilen)" % h["rows"])

    with db_conn() as c:
        c.cursor().execute("DELETE FROM dbx_t")
    rep = db_import_sql(sql, expect_dialect="sqlite")
    assert rep["ok"], rep["errors"]
    with db_conn() as c:
        cur = c.cursor()
        cur.execute("SELECT p,n,i,f,b FROM dbx_t ORDER BY id")
        got = [tuple(r[k] for k in ("p", "n", "i", "f", "b"))
               for r in cur.fetchall()]
    assert got == rows, "Roundtrip nicht bitgenau:\n%s\n%s" % (rows, got)
    ok("dbexport: Roundtrip bitgenau (Backslash/Semikolon/Quote/Unicode/NULL/BLOB)")

    # --- dry_run schreibt NICHTS ---
    with db_conn() as c:
        c.cursor().execute("DELETE FROM dbx_t")
    rep = db_import_sql(sql, expect_dialect="sqlite", dry_run=True)
    assert rep["ok"] and rep["applied"] == 0 and rep["statements"] > 0, rep
    with db_conn() as c:
        cur = c.cursor()
        cur.execute("SELECT COUNT(*) AS n FROM dbx_t")
        assert cur.fetchone()["n"] == 0, "dry_run hat geschrieben!"
    ok("dbexport: dry_run prueft, ohne zu schreiben")

    # --- Falscher Dialekt wird abgelehnt (sonst stiller Datenverlust) ---
    my = "".join(db_export_sql(dialect="mariadb"))
    rep = db_import_sql(my, expect_dialect="sqlite")
    assert not rep["ok"] and rep["errors"], "mariadb-Dump in sqlite durchgelassen!"
    ok("dbexport: falscher Dialekt wird abgelehnt")

    try:
        list(db_export_sql(dialect="quatsch"))
        raise AssertionError("ungueltiger Dialekt nicht abgelehnt")
    except ValueError:
        pass
    ok("dbexport: ungueltiger Dialekt wirft ValueError")

    s = export_summary()
    assert isinstance(s, dict) and "dbx_t" in s
    ok("dbexport: export_summary liefert Zeilen je Tabelle")


def _test_procdiag():
    """Phase-1-Zerlegung: die Prozess-/Thread-Diagnose (W83/W88) liegt jetzt in
       nc.procdiag; bot.py hält nur dünne Wrapper. Verhalten muss identisch sein."""
    import os as _os, glob as _glob
    from nc import procdiag
    assert isinstance(procdiag.zombie_child_count(), int)
    ok("procdiag.zombie_child_count")

    d = _ph.verzeichnis()
    for i in range(12):
        open(_os.path.join(d, "loop_stall_%d.txt" % i), "w").close()
    procdiag.prune_stall_dumps(d, keep=10)
    assert len(_glob.glob(_os.path.join(d, "loop_stall_*.txt"))) == 10
    ok("procdiag.prune_stall_dumps (12→10)")

    p = procdiag.dump_all_threads(d, "unittest")
    assert p and _os.path.exists(p) and "THREAD-DUMP" in open(p).read()
    ok("procdiag.dump_all_threads schreibt Dump")

    # Monolith delegiert (Wrapper vorhanden, Logik ausgelagert)
    src = open("bot.py").read()
    assert "from nc import procdiag as _nc_procdiag" in src, "procdiag nicht importiert"
    assert "_nc_procdiag.zombie_child_count()" in src, "Wrapper delegiert nicht"
    ok("bot.py delegiert an nc.procdiag")

    # Phase-1-Zerlegung: ffmpeg-Clip-Helfer nach nc.ffdiag konsolidiert
    from nc import ffdiag
    assert ffdiag.ffprobe_duration("/nonexistent_xyz.mp4") == 0.0
    assert ffdiag.clip_caption_escape("a: 'b' 100% \\ c") == "a b 100 c"
    assert len(ffdiag.clip_caption_escape("x" * 200)) == 70
    ok("ffdiag.ffprobe_duration + clip_caption_escape (aus bot.py gelöst)")
    assert "clip_caption_escape as _clip_caption_escape" in src, "Clip-Escape nicht konsolidiert importiert"
    assert "def _clip_caption_escape(s):" not in src, "alter Rumpf noch im Monolith"
    ok("bot.py nutzt konsolidierte ffdiag-Clip-Helfer")

    # Phase-1-Zerlegung: Login-Seite nach nc.loginpage
    from nc import loginpage
    _pg = loginpage.login_page("Falsches PIN.", "/betrieb")
    assert "<form" in _pg and "Falsches PIN." in _pg and "value='/betrieb'" in _pg
    assert "&lt;script&gt;" in loginpage.login_page("<script>", "/"), "Login-Seite escaped nicht"
    assert "login_page as _login_page" in src and "def _login_page(" not in src, "Login-Seite nicht ausgelagert"
    ok("nc.loginpage.login_page (aus bot.py gelöst, XSS-sicher)")


def _test_shield_harden():
    """V37-SHIELD-HARDEN: Umgehungstricks (Homoglyphen, Zero-Width, Akzente,
    Trennzeichen) müssen gefangen werden — OHNE harmlose Nachrichten zu treffen.
    False Positives sind bei Moderation das größere Übel."""
    import os as _os
    _os.environ["SENTINEL_SHIELD"] = "1"
    import nc.shield as S

    evasions = [
        "s\u200bieg h\u200beil",
        "\u0455\u0456\u0435g h\u0435\u0456l",
        "s.i.e.g h.e.i.l",
        "s\u00ed\u00e9g h\u00e9\u00edl",
        "h-e-i-l h-i-t-l-e-r",
        "k\u200by\u200bs",
    ]
    for e in evasions:
        assert S._sentinel_screen(e) is not None, f"Umgehung nicht gefangen: {e!r}"
    ok("shield: Umgehungen (Homoglyph/ZeroWidth/Akzent/Trenner) gefangen")

    safe = [
        "hey wie gehts euch heute", "der stream ist mega geil danke",
        "ich hei\u00dfe Sieglinde und wohne in Berlin",
        "das kostet 1488 euro glaube ich", "heiliger strohsack war das knapp",
        "gut gemacht leute weiter so", "meine e-mail steht im profil",
        "schau mal 3.5 sterne daf\u00fcr", "super-cool das ganze",
    ]
    for s in safe:
        r = S._sentinel_screen(s)
        assert r is None, f"FALSE POSITIVE bei harmloser Nachricht: {s!r} → {r}"
    ok("shield: 0 False Positives bei harmlosen Nachrichten")

    assert " " in S._shield_normalize("gut gemacht leute"), \
        "normale Leerzeichen dürfen nicht verschwinden"
    ok("shield: normale Wortgrenzen bleiben erhalten")


def _test_recdb():
    """Welle 1 der Zerlegung (v4.0-W104): die Aufnahmen-DB-Zugriffe liegen jetzt
       in nc.recdb, bot.py haelt nur noch Delegationen. Geprueft wird beides —
       dass das Modul arbeitet UND dass der Monolith wirklich delegiert, statt
       eine zweite Kopie der Logik zu behalten."""
    import sqlite3, os as _os
    from nc import recdb, dbwrap

    db = _os.path.join(_ph.verzeichnis(), "rec.sqlite")
    con = sqlite3.connect(db)
    con.executescript("""
        CREATE TABLE recordings (id INTEGER PRIMARY KEY, username TEXT, filepath TEXT,
            file_size INT, duration_secs INT, created_at TEXT, deleted_at TEXT,
            fingerprint TEXT);
        CREATE TABLE recording_notes (recording_id INT, note TEXT);
        CREATE TABLE recording_annotations (id INTEGER PRIMARY KEY, recording_id INT,
            timestamp_secs INT, label TEXT, created_at TEXT);
        CREATE TABLE bookmarks (recording_id INT, created_at TEXT);
        INSERT INTO recordings (id, username, filepath, deleted_at)
            VALUES (1, 'a', '/x.mp4', NULL), (2, 'b', '/y.mp4', '2026-01-01');
        INSERT INTO recording_notes VALUES (1, 'Notiz');
        INSERT INTO recording_annotations VALUES (1, 1, 42, 'Marke', '2026-01-01');
    """)
    con.commit(); con.close()
    dbwrap.configure_db(db_path=db, backend="sqlite")

    # Soft-Delete-Filter: die geloeschte #2 darf nicht auftauchen
    rows = recdb.get_all_recordings(limit=10)
    assert [r["id"] for r in rows] == [1], [r["id"] for r in rows]
    assert [r["id"] for r in recdb.get_all_recordings(limit=10, include_deleted=True)] == [2, 1]
    ok("recdb.get_all_recordings filtert Soft-Delete")

    assert recdb.get_recording_by_id(1)["username"] == "a"
    assert recdb.get_recording_note(1) == "Notiz"
    assert recdb.get_recording_note(999) is None
    assert len(recdb.get_annotations_for_recording(1)) == 1
    assert [r["id"] for r in recdb.get_trash_recordings()] == [2]
    ok("recdb: by_id, note, annotations, trash")

    # Papierkorb: der Rundlauf muss den Soft-Delete-Zustand wirklich umschalten
    seen = []
    recdb.configure(log_event=lambda *a, **k: seen.append(a[0]))
    assert recdb.soft_delete_recording(1) is True
    assert recdb.get_all_recordings(limit=10) == []
    assert recdb.restore_recording(1) is True
    assert [r["id"] for r in recdb.get_all_recordings(limit=10)] == [1]
    assert recdb.soft_delete_recording(999) is False, "nicht vorhandene ID darf nicht True melden"
    assert seen == ["recording.trashed", "recording.restored"], seen
    ok("recdb: Papierkorb-Rundlauf + log_event-Injection")

    # Ohne Injection darf nichts sterben — der Default ist ein No-Op, keine Ausnahme.
    import importlib
    fresh = importlib.reload(recdb)
    assert fresh.soft_delete_recording(1) is True, "ohne log_event-Injection gestorben"
    fresh.restore_recording(1)
    ok("recdb bleibt ohne log_event-Injection funktionsfaehig")

    # Fehlerpfad: eine fehlende Tabelle gibt [] zurueck, keinen 500er im Dashboard
    assert recdb.get_manual_recordings() == []
    assert recdb.get_bookmarked_recordings(limit=5) == []
    ok("recdb: fehlende Tabelle -> leere Liste statt Ausnahme")

    # --- und der Monolith delegiert wirklich ---
    src = open("bot.py", encoding="utf-8").read()
    assert "from nc import recdb as _nc_recdb" in src, "recdb nicht importiert"
    assert "_nc_recdb.configure(log_event=log_event)" in src, "log_event nicht injiziert"
    for fn in ("get_all_recordings", "get_recording_by_id", "soft_delete_recording",
               "restore_recording", "get_trash_recordings", "get_manual_recordings",
               "get_recording_note", "get_annotations_for_recording",
               "get_bookmarked_recordings", "get_recent_recording_attempts",
               "update_recording_fingerprint", "find_recordings_by_fingerprint",
               "get_or_compute_inspect_sync"):
        assert ("return _nc_recdb.%s(" % fn) in src, "%s delegiert nicht" % fn
    # Kein Rumpf-Rest: die SQL darf nur noch im Modul stehen, sonst laufen die
    # beiden Kopien mit der Zeit auseinander.
    assert "SELECT * FROM recordings WHERE deleted_at IS NULL" not in src, \
        "alte SQL noch im Monolithen — Doppel-Logik"
    ok("bot.py delegiert an nc.recdb (13 Funktionen, keine Doppel-Logik)")


def _test_routes_recordings():
    """Welle 2 der Zerlegung (v4.0-W106): die Aufnahmen-Routen liegen als
       Flask-Blueprint in nc/routes/recordings.py. 34 waren es bei der
       Zerlegung, 37 seit v4.2-W44 (die drei Sitzungs-Routen). Geprueft wird, dass das
       Blueprint fuer sich allein funktioniert (ohne Bot), dass der Kontext
       laut scheitert statt still None zu liefern, und dass im Monolithen keine
       zweite Kopie zurueckgeblieben ist."""
    import importlib
    from flask import Flask
    from nc import ctx as ncctx
    from nc.routes import recordings as rt

    # (1) Die Pfade muessen WOERTLICH die alten sein — ein url_prefix waere die
    # stille Verhaltensaenderung, die alle Dashboard-Aufrufe bricht.
    app = Flask(__name__)
    app.register_blueprint(rt.bp)
    rules = {str(r.rule) for r in app.url_map.iter_rules() if r.endpoint != "static"}
    assert len(rules) == 37, "37 Routen erwartet, %d registriert" % len(rules)
    for want in ("/api/recordings/list", "/api/recordings/daily",
                 "/api/recordings/<int:rid>/manifest", "/api/recordings/trash",
                 "/api/rec/orphans", "/api/rec/quality/<int:rec_id>",
                 # v4.2-W44: die Klammer um die Segmente EINES Streams
                 "/api/recordings/sessions", "/api/recordings/session/<sid>",
                 "/api/recordings/session/<sid>/join"):
        assert want in rules, "Pfad fehlt oder umbenannt: %s" % want
    assert not any(r.startswith("/recordings") for r in rules), \
        "url_prefix gesetzt — die Pfade haben sich verschoben"
    ok("routes.recordings: 37 Routen, Pfade woertlich unveraendert")

    # (2) Endpunkt-Namen sind blueprint-qualifiziert. Das ist die EINZIGE
    # erlaubte Aenderung — sie ist folgenlos, weil es im Projekt kein url_for gibt.
    eps = {r.endpoint for r in app.url_map.iter_rules() if r.endpoint != "static"}
    assert all(e.startswith("recordings.") for e in eps), sorted(eps)[:3]
    for f in ("bot.py", "templates/dashboard.html", "website/lafap_index.html"):
        assert "url_for(" not in open(f, encoding="utf-8").read(), \
            "%s benutzt url_for — Endpunkt-Umbenennung waere jetzt ein Bruch" % f
    ok("routes.recordings: Endpunkte qualifiziert, weiterhin kein url_for im Projekt")

    # (3) Ohne configure() muss der Kontext LAUT scheitern. Ein stiller
    # None-Kontext waere der CLAUDE.md-Fehler eine Ebene hoeher: die Route
    # liefe, taete aber nichts.
    fresh = importlib.reload(ncctx)
    assert fresh.is_configured() is False
    try:
        fresh.get()
        raise AssertionError("nc.ctx.get() schweigt ohne configure()")
    except RuntimeError as e:
        assert "configure" in str(e), e
    ok("nc.ctx: get() ohne configure() scheitert laut, nicht still")

    # (4) __slots__ ist die Bremse gegen das Sammelbecken — ein vertippter oder
    # neuer Schluessel muss sofort auffliegen, nicht erst beim ersten Aufruf.
    try:
        fresh.configure(gibtsnicht=1)
        raise AssertionError("unbekannter ctx-Schluessel wurde stillschweigend geschluckt")
    except AttributeError:
        pass
    ok("nc.ctx: unbekannter Schluessel fliegt sofort auf (__slots__)")

    # (5) Und der Monolith haelt keine zweite Kopie.
    src = open("bot.py", encoding="utf-8").read()
    assert "from nc.routes import recordings as _nc_routes_recordings" in src
    assert "dashboard_app.register_blueprint(_nc_routes_recordings.bp)" in src, \
        "Blueprint nicht registriert"
    assert "_nc_ctx.configure(" in src, "Laufzeitkontext nicht verdrahtet"
    for gone in ('@dashboard_app.route("/api/recordings/list")',
                 "def api_recordings_list", "def compute_waveform_peaks",
                 "def build_recording_manifest", "def _find_orphans"):
        assert gone not in src, "Doppel-Logik: %s noch im Monolithen" % gone
    ok("bot.py registriert nur noch — keine Aufnahmen-Route mehr im Monolithen")


def _test_routes_archive():
    """Welle 3 der Zerlegung (v4.0-W107): die Archiv-Routen als Blueprint.
       Dieselben Zusicherungen wie fuer recordings — plus die neue cfg-Bruecke,
       die verhindert, dass nc/ctx.py zum Konfigurations-Abladeplatz wird.

       Waren elf; seit v4.2-W98 dreizehn (der Ordner-Scan und das Aufnehmen).
       Die Zahl steht hier absichtlich und wird bei jeder neuen Route von
       Hand nachgezogen: sie faengt eine Route, die versehentlich zweimal
       oder unter falschem Pfad registriert wird."""
    from flask import Flask
    from nc.routes import archive as rt

    app = Flask(__name__)
    app.register_blueprint(rt.bp)
    rules = {str(r.rule) for r in app.url_map.iter_rules() if r.endpoint != "static"}
    assert len(rules) == 13, "13 Routen erwartet, %d registriert" % len(rules)
    for want in ("/api/archive", "/api/archive/upload", "/api/archive/search",
                 "/api/archive/<int:eid>", "/api/archive/duplicates",
                 "/api/archive/scan", "/api/archive/scan/adopt"):
        assert want in rules, "Pfad fehlt oder umbenannt: %s" % want
    assert all(r.endpoint.startswith("archive.")
               for r in app.url_map.iter_rules() if r.endpoint != "static")
    ok("routes.archive: 13 Routen, Pfade woertlich unveraendert")

    # Konfiguration laeuft ueber cfg, NICHT ueber eigene Env-Lesepfade: der Bot
    # friert diese Werte beim Import ein, ein zweiter Lesepfad im Blueprint waere
    # eine stille Verhaltensaenderung gegenueber dem Monolithen.
    src_rt = open("nc/routes/archive.py", encoding="utf-8").read()
    assert 'cfg["ARCHIVE_DIR"]' in src_rt, "ARCHIVE_DIR nicht ueber cfg"
    # GENAU EIN roher Env-Zugriff ist erlaubt, und zwar der, der schon im
    # Monolithen stand (api_archive_duplicates liest ARCHIVE_DIR als Fallback
    # nochmal selbst, obwohl der Bot den Wert oben bereits einfriert). Das ist
    # eine Altlast, kein neuer Lesepfad — sie wurde beim Verschieben bewusst
    # NICHT "nebenbei repariert", weil Verhalten und Ort nie in derselben Welle
    # geaendert werden. Der Zaehler haelt fest, dass nicht mehr dazukommen.
    assert src_rt.count('os.getenv("ARCHIVE') == 1, (
        "neuer roher Env-Lesepfad im Blueprint (%d statt 1)"
        % src_rt.count('os.getenv("ARCHIVE'))
    ok("routes.archive: Konfiguration ueber ctx.cfg, nur die bekannte Altlast bleibt")

    # Und der Monolith haelt keine zweite Kopie.
    src = open("bot.py", encoding="utf-8").read()
    assert "from nc.routes import archive as _nc_routes_archive" in src
    assert "dashboard_app.register_blueprint(_nc_routes_archive.bp)" in src
    for gone in ('@dashboard_app.route("/api/archive")', "def api_archive_upload",
                 "def rename_archive_entry", "def get_archive_aggregate_stats"):
        assert gone not in src, "Doppel-Logik: %s noch im Monolithen" % gone
    ok("bot.py registriert nur noch — keine Archiv-Route mehr im Monolithen")

    # Die Obergrenze fuer nc.ctx prueft _test_routes_alle_blueprints zentral.


def _test_routes_alle_blueprints():
    """W108: ab hier gilt der Vertrag GENERISCH fuer jedes Modul in nc/routes/.

       Frueher bekam jedes Blueprint seinen eigenen Testblock — bei dreizehn
       geplanten waere das dreizehnmal dieselbe Zusicherung in leicht anderer
       Schreibweise. Was fuer alle gilt, wird hier einmal geprueft; nur
       Besonderheiten einzelner Module stehen weiter in eigenen Tests."""
    import glob as _glob
    import importlib
    from flask import Flask
    import sys as _sys

    module = sorted(_os_basename(p) for p in _glob.glob("nc/routes/*.py")
                    if not p.endswith("__init__.py"))
    assert module, "keine Blueprints gefunden"
    src = open("bot.py", encoding="utf-8").read()

    gesamt = 0
    for name in module:
        mod = importlib.import_module("nc.routes." + name)
        assert hasattr(mod, "bp"), "%s hat kein bp" % name

        app = Flask(__name__)
        app.register_blueprint(mod.bp)
        regeln = [r for r in app.url_map.iter_rules() if r.endpoint != "static"]
        assert regeln, "%s registriert keine Route" % name
        gesamt += len(regeln)

        # (1) Pfade woertlich: ein url_prefix wuerde jeden Dashboard-Aufruf
        # brechen. Ausnahmen sind Pfade, die per Konvention NICHT unter /api/
        # liegen — /metrics ist der Prometheus-Endpunkt, und ein Scraper sucht
        # ihn genau dort (v4.1-W23). Die Liste steht hier ausdruecklich, damit
        # ein versehentlich gesetzter url_prefix trotzdem auffliegt.
        # /fonts/… (v4.2-W111): die Schriften stehen dort, wo die
        # @font-face-Regeln und die oeffentliche Seite sie erwarten.
        AUSSERHALB = {"/metrics", "/fonts/schriften.css", "/fonts/<name>"}
        for r in regeln:
            assert str(r.rule).startswith("/api/") or str(r.rule) in AUSSERHALB, \
                "%s: Pfad nicht mehr unter /api/ — url_prefix gesetzt? %s" % (name, r.rule)
        # (2) Endpunkte blueprint-qualifiziert.
        assert all(r.endpoint.startswith(name + ".") for r in regeln), \
            "%s: Endpunkt nicht qualifiziert" % name
        # (3) Der Bot registriert es wirklich — sonst waere die Route weg.
        assert "register_blueprint(_nc_routes_%s.bp)" % name in src, \
            "%s nicht in bot.py registriert" % name
        # (4) Architektur-Grenze: kein Rueckimport aus dem Monolithen. Geprueft
        # wird ueber den AST, nicht ueber den Text — "aus bot.py geloest" steht
        # voellig zu Recht in jedem Docstring und ist kein Verstoss.
        # Seit der Umbenennung heisst das Modul schlicht "bot": auf Praefix zu
        # pruefen wuerde jedes kuenftige Modul mit diesem Wortanfang faelschlich
        # treffen, deshalb exakt oder als Paket-Praefix "bot.".
        import ast as _ast
        quelle = open("nc/routes/%s.py" % name, encoding="utf-8").read()
        for _n in _ast.walk(_ast.parse(quelle)):
            if isinstance(_n, _ast.Import):
                assert all(not _ist_monolith(al.name) for al in _n.names), \
                    "%s importiert aus bot.py" % name
            elif isinstance(_n, _ast.ImportFrom):
                assert not _ist_monolith(_n.module or ""), \
                    "%s importiert aus bot.py" % name
        # (5) Keine app-weiten Hooks mitgewandert — als Blueprint-Hook wuerden
        # sie nur noch fuer ihr Blueprint gelten, eine stille Verhaltensaenderung.
        for hook in ("@bp.before_request", "@bp.after_request", "@bp.errorhandler"):
            assert hook not in quelle, "%s: %s gehoert auf die App" % (name, hook)
        # (6) Query-Parameter gehaertet, kein rohes int(request.args...).
        assert "int(request.args.get" not in quelle, \
            "%s: roher Query-Parser (Flask-500-Risiko)" % name
        # (7) Auf Modulebene nur stdlib, flask und nc. v4.1-W23: ein
        # `import aiohttp` ganz oben in nc/routes/beobachtung.py hat genau
        # diesen Job in CI gekippt — dort werden absichtlich nur orjson und
        # flask installiert, damit nc/* isoliert testbar bleibt (CLAUDE.md).
        # Lokal fiel es nicht auf, weil der volle Laufzeitstack da liegt.
        # Wer aiohttp, telegram, discord, streamlink, yt_dlp oder psutil
        # braucht, importiert IN der Funktion.
        ERLAUBT = {"flask", "orjson", "nc"}
        for _n in _ast.parse(quelle).body:      # nur body: verschachtelte
            wurzeln = []                        # Importe sind ausdruecklich ok
            if isinstance(_n, _ast.Import):
                wurzeln = [al.name.split(".")[0] for al in _n.names]
            elif isinstance(_n, _ast.ImportFrom) and not _n.level:
                wurzeln = [(_n.module or "").split(".")[0]]
            for w in wurzeln:
                assert w in ERLAUBT or w in _sys.stdlib_module_names, \
                    ("%s: %r auf Modulebene — bricht den CI-Vertragsjob, "
                     "in die Funktion verschieben" % (name, w))
    ok("nc/routes: %d Blueprints, %d Routen — Pfade, Endpunkte, Grenze, Hooks, Parser"
       % (len(module), gesamt))

    # (7) Jeder cfg-Schluessel, den ein Blueprint liest, muss auch geliefert
    # werden. Ein fehlender faellt NICHT beim Start auf, sondern erst beim
    # Aufruf der Route — als KeyError im 500er. Genau so ist in W112
    # /api/ai/forecast-storage gestorben.
    import re as _re
    _i = src.index("    cfg={")
    _j = src.index("    },", _i)
    _geliefert = set(_re.findall(r'"([A-Za-z_][A-Za-z0-9_]*)":', src[_i:_j]))
    for name in module:
        quelle = open("nc/routes/%s.py" % name, encoding="utf-8").read()
        # Doc-/Kommentarzeilen raus: dort steht cfg["NAME"] als Platzhalter.
        code = "\n".join(ln for ln in quelle.splitlines()
                         if not ln.lstrip().startswith("#"))
        code = code.split('"""')
        code = "".join(code[0::2]) if len(code) > 1 else quelle
        # v4.1-W15: NUR der Kontext-cfg. Der alte Ausdruck traf jedes
        # `cfg["x"]` — auch ein LOKALES Dict, das die Route selbst gebaut hat
        # (nc/routes/cohost.py: `cfg = _cohost_cfg()` und dann `cfg["enabled"]`).
        # Der Vertrag haette dort vier Schluessel vom Bot verlangt, die es dort
        # nie gab. Blueprints lesen den Kontext ausnahmslos als `_c().cfg[...]`
        # — bp_extract erzeugt genau diese Form.
        gebraucht = set(_re.findall(r'_c\(\)\.cfg\["([^"]+)"\]', code))
        fehlt = gebraucht - _geliefert
        assert not fehlt, "%s liest cfg-Schluessel, die der Bot nicht liefert: %s" % (
            name, sorted(fehlt))
    ok("cfg: jeder gelesene Schluessel wird auch geliefert (%d Schluessel)" % len(_geliefert))

    # url_for bleibt projektweit verboten: es ist der einzige Grund, warum die
    # Endpunkt-Umbenennung durch Blueprints folgenlos ist.
    for f in ("bot.py", "templates/dashboard.html", "website/lafap_index.html"):
        assert "url_for(" not in open(f, encoding="utf-8").read(), \
            "%s benutzt url_for — Blueprint-Umbenennung waere jetzt ein Bruch" % f
    ok("weiterhin kein url_for im Projekt")

    # Der Kontext bleibt klein, sonst ist die Grenze weg, die er sich setzt.
    from nc import ctx as ncctx
    assert len(ncctx.Ctx.__slots__) <= 25, (
        "nc.ctx waechst zum Sammelbecken: %d Slots" % len(ncctx.Ctx.__slots__))
    ok("nc.ctx: %d Slots, Obergrenze eingehalten" % len(ncctx.Ctx.__slots__))


def _os_basename(p):
    import os as _os
    return _os.path.basename(p)[:-3]


def _test_routes_health():
    """W110: /api/health-score und /api/system-resources als ein Blueprint.

       Zwei Praefixe, EIN Thema (Systemzustand) — deshalb ein Modul statt zwei
       Ein-Routen-Dateien. Der Vertrag haelt die zwei Fallen fest, die hier
       zugeschlagen haben."""
    from nc import ctx as ncctx

    # (1) Die Startzeit MUSS spaet gelesen werden. _BOT_START_TIME ist beim
    # Import None und wird erst in main() gesetzt; ein beim Start uebergebener
    # Wert waere fuer immer None und die Uptime staende ewig auf 0.
    assert "get_bot_start_time" in ncctx.Ctx.__slots__, "Startzeit-Getter fehlt im Kontext"
    assert "bot_start_time" not in [x for x in ncctx.Ctx.__slots__ if x != "get_bot_start_time"], \
        "Startzeit wieder als Wert im Kontext — friert beim Import ein"
    q = open("nc/routes/health.py", encoding="utf-8").read()
    assert "_c().get_bot_start_time()" in q, "Blueprint liest die Startzeit nicht als Getter"
    src = open("bot.py", encoding="utf-8").read()
    assert "get_bot_start_time=lambda: _BOT_START_TIME" in src, \
        "Bot reicht die Startzeit nicht als Getter durch"

    # (2) Beide Routen ruft der Bot auch INTERN auf (Telegram /sysres und die
    # Aggregat-Route). Nach dem Umzug muessen sie importiert sein, sonst
    # sterben diese Pfade mit NameError — statisch sichtbar, aber leicht zu
    # uebersehen.
    # v4.1-W26: als REGEL statt als Namensliste. Frueher stand hier die
    # woertliche Import-Zeile — die kippte, sobald ein interner Aufrufer
    # selbst in einen Blueprint wanderte (/api/pulse nahm api_health_score
    # mit). Die Zusicherung ist dieselbe geblieben, sie prueft jetzt nur den
    # Sachverhalt statt seiner damaligen Schreibweise: jede Blueprint-Funktion,
    # die bot.py AUFRUFT, muss dort auch importiert sein.
    import ast as _ast
    b = _ast.parse(src)
    importiert = set()
    for n in _ast.walk(b):
        if isinstance(n, _ast.ImportFrom) and (n.module or "").startswith("nc.routes"):
            importiert |= {(a.asname or a.name) for a in n.names}
        elif isinstance(n, _ast.Import):
            importiert |= {(a.asname or a.name.split(".")[0]) for a in n.names}
    definiert = {n.name for n in b.body
                 if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    gerufen = {n.func.id for n in _ast.walk(b)
               if isinstance(n, _ast.Call) and isinstance(n.func, _ast.Name)}
    for name in ("api_health_score", "api_system_resources"):
        if name in gerufen:
            assert name in importiert or name in definiert, \
                ("bot.py ruft %s auf, importiert es aber nicht — NameError zur "
                 "Laufzeit" % name)
    # api_system_resources hat weiterhin einen internen Aufrufer (Telegram
    # /sysres und die Aggregat-Route) und MUSS deshalb importiert sein.
    assert "api_system_resources" in importiert, \
        "api_system_resources ist nicht mehr importiert — /sysres stirbt"
    ok("routes.health: Startzeit als Getter, interne Aufrufer versorgt")


def _test_cfgstore_und_claude():
    """W111: Vorarbeit fuer das /api/ai-Blueprint. Fuenf Funktionen, die reiner
       app_config-Zugriff bzw. Anthropic-Belang sind, lagen im Monolithen und
       waeren dort zu fuenf Kontext-Eintraegen geworden. Sie liegen jetzt in
       den Modulen, die genau dafuer da sind."""
    import sqlite3, os as _os
    from nc import cfgstore, claude, dbwrap

    db = _os.path.join(_ph.verzeichnis(), "cfg.sqlite")
    con = sqlite3.connect(db)
    con.execute("CREATE TABLE app_config (k TEXT UNIQUE, v TEXT, updated_at TEXT)")
    con.commit(); con.close()
    dbwrap.configure_db(db_path=db, backend="sqlite")

    assert cfgstore.get("fehlt", "vorgabe") == "vorgabe"
    cfgstore.set_("ai.x", {"a": 1})
    assert cfgstore.get("ai.x") == {"a": 1}
    cfgstore.set_("ai.x", {"a": 2})                     # Upsert-Pfad
    assert cfgstore.get("ai.x") == {"a": 2}, "Upsert hat nicht aktualisiert"
    ok("cfgstore: get/set_ inkl. Upsert gegen echtes SQLite")

    # Anthropic: app_config hat Vorrang vor der Umgebung.
    _os.environ["ANTHROPIC_MODEL"] = "claude-aus-der-env"
    assert claude.model_raw() == "claude-aus-der-env"
    cfgstore.set_("ai.anthropic_model", "claude-aus-der-db")
    assert claude.model_raw() == "claude-aus-der-db", "app_config hat keinen Vorrang"
    # Ein abgeschalteter Pin wird angehoben, statt still auf 404 zu laufen.
    assert claude.model("claude-3-5-haiku-latest") == claude.DEFAULT_MODEL
    _os.environ.pop("ANTHROPIC_MODEL", None)
    ok("claude: Modellwahl (app_config > env > Default) + Retired-Anhebung")

    # Und der Monolith delegiert, statt eine zweite Kopie zu halten.
    src = open("bot.py", encoding="utf-8").read()
    for fn, ziel in (("_cfg_get", "_nc_cfgstore.get(key, default)"),
                     ("_cfg_set", "_nc_cfgstore.set_(key, value)"),
                     ("_anthropic_key", "_nc_claude.api_key()"),
                     ("_anthropic_model", "_nc_claude.model(override)")):
        assert ("return " + ziel) in src, "%s delegiert nicht" % fn
    assert "_ANTHROPIC_MODEL_WARNED" not in src, "alter Warn-Cache noch im Monolithen"
    # model_raw braucht der Bot selbst nicht mehr — es wanderte mit den
    # /api/ai-Routen ins Blueprint und wird dort direkt aus nc.claude
    # importiert, statt ueber eine zweite Huelle zu laufen.
    assert "model_raw as _anthropic_model_raw" in open(
        "nc/routes/ai.py", encoding="utf-8").read(), "Blueprint importiert model_raw nicht direkt"
    ok("bot.py delegiert cfg-Zugriff und Anthropic-Modellwahl")


def _test_routes_ai():
    """W112: die 24 /api/ai-Routen als Blueprint — der groesste Einzelumzug
       (1.125 Zeilen). Die generischen Zusicherungen deckt
       _test_routes_alle_blueprints ab; hier stehen die Besonderheiten."""
    from flask import Flask
    from nc.routes import ai as rt

    app = Flask(__name__)
    app.register_blueprint(rt.bp)
    regeln = [r for r in app.url_map.iter_rules() if r.endpoint != "static"]
    assert len(regeln) == 24, "24 Regeln erwartet, %d" % len(regeln)
    ok("routes.ai: 24 Regeln registriert")

    q = open("nc/routes/ai.py", encoding="utf-8").read()

    # (1) Der SQL-Wachhund und die Read-only-Verbindung MUESSEN mitgewandert
    # sein — /api/ai/query fuehrt vom Nutzer erzeugtes SQL aus. Ohne beides
    # waere die Zerlegung ein Sicherheitsrueckschritt.
    assert "_nc_sqlguard.check_readonly(" in q, "SQL-Wachhund fehlt im Blueprint"
    assert "?mode=ro" in q and "uri=True" in q, "keine Read-only-Verbindung"

    # (2) Vier Namen kommen direkt aus nc/, nicht ueber den Laufzeitkontext.
    # Sie waeren sonst vier Slots gewesen, obwohl sie reiner Modulzugriff sind.
    for imp in ("from nc.claude import", "from nc.cfgstore import get as _cfg_get",
                "from nc.aidb import conv_messages", "from nc.notes import _conv_list"):
        assert imp in q, "Direktimport fehlt: " + imp
    assert "_c().cfg[" in q, "Konfiguration laeuft nicht ueber ctx.cfg"

    # (3) Und der Monolith haelt keine zweite Kopie der KI-Routen.
    src = open("bot.py", encoding="utf-8").read()
    for gone in ('@dashboard_app.route("/api/ai/ask")', "def api_ai_ask",
                 "def llm_chat_stream_sync", "def _nl_to_sql", "def _safe_select"):
        assert gone not in src, "Doppel-Logik: %s noch im Monolithen" % gone
    ok("routes.ai: SQL-Wachhund + Read-only mitgewandert, Direktimporte statt ctx")


def _test_restream_stability():
    """v4.0-W113: die Wiederanlauf-Regeln des Restreams.

    Diese Logik lag vorher in RestreamManager._monitor und war damit nur mit
    laufendem ffmpeg, laufender DB und laufendem Event-Loop erreichbar — also
    faktisch ungeprueft. Zwei der fuenf Regeln waren nachweislich falsch
    gesetzt; genau die stehen hier zuerst.
    """
    import nc.restream_stability as rs

    pol = rs.ReconnectPolicy()

    # 1) Budget-Rueckgabe — DER Befund. Vorher wanderte `attempts` von
    #    Reconnect zu Reconnect weiter; ein Restream, der stundenlang lief und
    #    fuenfmal stolperte, galt danach als aufgegeben.
    assert rs.budget_after_run(4, 3600.0, pol) == 0
    assert rs.budget_after_run(4, 10.0, pol) == 4
    assert rs.budget_after_run(0, 10.0, pol) == 0
    # Lang gelaufen, aber nichts gesendet (Stillstands-Kill): KEIN Nachschlag,
    # sonst haemmert der Bot gegen einen toten Ingest ewig im Grundtakt.
    assert rs.budget_after_run(4, 3600.0, pol, progressed=False) == 4
    assert rs.budget_exhausted(5, pol) and not rs.budget_exhausted(4, pol)
    ok("restream_stability: Reconnect-Budget kommt nach gesundem Lauf zurueck")

    # 2) Backoff — exponentiell, gedeckelt, gestreut. Ohne Streuung kehren
    #    alle gleichzeitig gestorbenen Restreams im Gleichschritt zurueck.
    for n in range(0, 12):
        d = rs.reconnect_delay(n, pol)
        assert 1.0 <= d <= pol.max_delay_s, (n, d)
    fest = rs.ReconnectPolicy(jitter=0.0)
    assert rs.reconnect_delay(0, fest) == 8.0
    assert rs.reconnect_delay(1, fest) == 16.0
    assert rs.reconnect_delay(2, fest) == 32.0
    assert rs.reconnect_delay(9, fest) == 60.0          # Deckel greift
    gestreut = {rs.reconnect_delay(1, pol) for _ in range(40)}
    assert len(gestreut) > 1, "Backoff streut nicht — Gleichschritt bleibt"
    ok("restream_stability: Backoff exponentiell, gedeckelt und gestreut")

    # 3) Ablauf der Quell-URL — schnell bleiben beim Normalfall, bremsen bei
    #    der Schleife. Vorher: 2s, kein Fehlversuch, ohne jede Untergrenze.
    assert rs.expired_streak(5, 400.0, pol) == 0        # Minuten gelaufen = normal
    assert rs.expired_streak(0, 0.4, pol) == 1
    assert rs.expired_streak(3, 0.4, pol) == 4
    assert rs.expired_delay(0, pol) == 2.0
    assert rs.expired_delay(99, pol) == pol.expired_delays_s[-1]
    assert not rs.expired_is_spinning(0, pol)
    assert rs.expired_is_spinning(len(pol.expired_delays_s), pol)
    # Die Verzoegerung waechst monoton — nie schneller werden.
    folge = [rs.expired_delay(i, pol) for i in range(len(pol.expired_delays_s))]
    assert folge == sorted(folge), folge
    ok("restream_stability: Ablauf-Pfad bremst erst, wenn er sich dreht")

    # 4) Codec-Fallback — die schwachen Marker duerfen nicht mehr auf
    #    Netzfehler anspringen (transcode kostet CPU, die dem Bild fehlt).
    assert rs.is_codec_failure("Unable to find a suitable output format")
    assert rs.is_codec_failure("No such codec: h265")
    assert rs.is_codec_failure("Invalid data found when processing input")
    assert not rs.is_codec_failure("Failed to resolve hostname pull-flv.tiktokcdn.com")
    assert not rs.is_codec_failure("Unable to open resource: Connection refused")
    assert not rs.is_codec_failure(
        "Could not write header (incorrect codec parameters ?): Input/output error")
    assert not rs.is_codec_failure("")
    # Starke Marker gelten trotz Netz-Rauschen in derselben Kachel.
    assert rs.is_codec_failure(
        "Will reconnect at 123... Codec does not support this pixel format")
    ok("restream_stability: Codec-Fallback springt nicht mehr auf Netzfehler an")

    # 5) Stillstand — Karenz, Blindheit, Abschuss.
    v = rs.stall_verdict(10.0, 0.0, pol)
    assert v.state == rs.STALL_GRACE and not v.stalled
    v = rs.stall_verdict(600.0, 5.0, pol)
    assert v.state == rs.STALL_OK and not v.stalled
    v = rs.stall_verdict(600.0, 200.0, pol)
    assert v.state == rs.STALL_DEAD and v.stalled and v.reason
    # Blind heisst nicht tot — Unwissen ist kein Beweis (Regel aus dem Guard).
    v = rs.stall_verdict(600.0, 200.0, pol, reader_alive=False)
    assert v.state == rs.STALL_BLIND and not v.stalled
    v = rs.stall_verdict(600.0, None, pol)
    assert v.state == rs.STALL_BLIND and not v.stalled
    ok("restream_stability: Stillstand erkannt, Karenz und Blindheit geachtet")

    # Das Modul bleibt bot-frei — sonst waere es nicht ohne Laufzeitstack
    #  pruefbar, und genau das war der Grund fuer diese Extraktion.
    quelle = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "nc", "restream_stability.py"), encoding="utf-8").read()
    import ast as _ast
    for _n in _ast.walk(_ast.parse(quelle)):
        if isinstance(_n, _ast.Import):
            _mods = [a.name.split(".")[0] for a in _n.names]
        elif isinstance(_n, _ast.ImportFrom):
            _mods = [(_n.module or "").split(".")[0]]
        else:
            continue
        assert set(_mods) <= {"random", "dataclasses", "__future__"}, _mods
    ok("restream_stability: bot-frei und stdlib-only")


def _test_updater():
    """v4.0-W115: Selbst-Update — die drei Zusagen, ohne Netz und ohne Bot.

    Ein Update schreibt Code unter einen laufenden Dienst. Genau drei Dinge
    duerfen dabei nie passieren, und alle drei sind hier reine Funktionen:
    Betriebsdaten anfassen, aus der Wurzel ausbrechen, lokale Dateien
    loeschen. Der Rest (Download, Backup, Schreiben) haengt daran.
    """
    import nc.updater as up

    # ── Zusage 1: Betriebsdaten sind unantastbar ─────────────────────────
    # Die Liste ist der einzige Schutz der .env mit ihren 352 Variablen —
    # ein Update, das sie mit .env.example ueberschreibt, kostet den Betrieb.
    for pfad in (".env", "logs/debug.log", "nc/logs/x.log", "recordings/a.mp4",
                 "bot.db", "bot.db-wal", "archive/x.mp4", "backups/x.zip",
                 ".git/HEAD", "build/README.md", "nc/__pycache__/x.pyc",
                 "website/news.json", ".nc_update.json"):
        assert up.is_protected(pfad), pfad
    for pfad in ("bot.py", "nc/updater.py", "brain/router.py",
                 "templates/dashboard.html", "website/lafap_index.html",
                 ".claude/skills/nightcrawler/SKILL.md", "requirements.txt",
                 ".env.example"):
        assert not up.is_protected(pfad), pfad
    ok("updater: Betriebsdaten geschuetzt, Quelltext aktualisierbar")

    # website/news.json schreibt der News-Agent im Betrieb. Kaeme sie aus dem
    # Archiv zurueck, stuende die Website schlagartig auf dem Stand des
    # letzten Commits — mit verschwundenen News.
    assert up.is_protected("website/news.json")
    assert not up.is_protected("website/lafap_index.html")
    ok("updater: news.json geschuetzt, die Seite selbst nicht")

    # ── Zusage 2: kein Ausbruch aus der Wurzel (Zip-Slip) ────────────────
    for bose in ("../etc/passwd", "/etc/passwd", "a/../../b", "C:/x",
                 "./../x", "", "..", "nc/../../boom"):
        assert up.normalize(bose) == "", bose
    assert up.normalize("nc/updater.py") == "nc/updater.py"
    assert up.normalize("nc\\updater.py") == "nc/updater.py"
    # Ein unbrauchbarer Pfad gilt zugleich als geschuetzt — doppelter Riegel,
    # damit kein Zweig ihn versehentlich doch schreibt.
    assert up.is_protected("../etc/passwd")
    ok("updater: Zip-Slip abgeriegelt, unbrauchbare Pfade gelten als geschuetzt")

    # GitHub packt alles unter <repo>-<branch>/ — diese Ebene faellt weg.
    assert up.strip_archive_root("Telegram-Stream-Info-Bot-main/nc/x.py") == "nc/x.py"
    assert up.strip_archive_root("Telegram-Stream-Info-Bot-main/") == ""
    assert up.strip_archive_root("nurwurzel") == ""
    ok("updater: Archiv-Wurzel wird abgestreift")

    # ── Zusage 3: nur hinzufuegen und ersetzen, nie loeschen ─────────────
    eintraege = [("bot.py", 10, "neu"), ("nc/neu.py", 5, "x"),
                 ("gleich.py", 3, "same"), (".env", 1, "y"),
                 ("../boom", 1, "z"), ("riesig.bin", up.MAX_FILE_BYTES + 1, "w")]
    lokal = {"bot.py": "alt", "gleich.py": "same", "nur_lokal.sh": "meins"}
    plan = up.build_plan(eintraege, lambda r: lokal.get(r))
    assert plan.changed == ["bot.py"], plan.changed
    assert plan.new == ["nc/neu.py"], plan.new
    assert plan.same == 1
    assert plan.protected == [".env"], plan.protected
    assert sorted(plan.rejected) == ["../boom", "riesig.bin"], plan.rejected
    # Die lokale Datei, die im Archiv fehlt, taucht in keiner Liste auf —
    # sie bleibt liegen. Sonst raeumt ein Update eigene Skripte weg.
    for liste in (plan.new, plan.changed, plan.protected, plan.rejected):
        assert "nur_lokal.sh" not in liste
    assert plan.as_dict()["count"] == 2
    ok("updater: Plan trennt neu/geaendert/geschuetzt, loescht nie")

    # ── Ehrlichkeit der Auskunft ────────────────────────────────────────
    # Ohne bekannten lokalen Stand ist "es gibt ein Update" eine Behauptung.
    assert "unbekannt" in up.describe({"ok": True, "update_available": False,
                                       "local_known": False}).lower()
    assert "aktuell" in up.describe({"ok": True, "update_available": False,
                                     "local_known": True}).lower()
    assert "fehlgeschlagen" in up.describe({"ok": False, "error": "kaputt"}).lower()
    assert up.short_sha("a1b2c3d4e5f6") == "a1b2c3d"
    ok("updater: Auskunft nennt einen unbekannten Stand auch so")

    # ── bot-frei und stdlib-only ────────────────────────────────────────
    hier = os.path.dirname(os.path.abspath(__file__))
    src = open(os.path.join(hier, "nc", "updater.py"), encoding="utf-8").read()
    # Ueber den AST, nicht ueber den Text: "bot" steckt seit der Umbenennung
    # in jedem zweiten Wort des Moduls ("bot-frei"), eine Textsuche waere ein
    # Dauer-Fehlalarm.
    import ast as _ast
    for _n in _ast.walk(_ast.parse(src)):
        if isinstance(_n, _ast.Import):
            assert all(not _ist_monolith(a.name) for a in _n.names), "importiert bot.py"
        elif isinstance(_n, _ast.ImportFrom):
            assert not _ist_monolith(_n.module or ""), "importiert bot.py"
    assert "import requests" not in src and "aiohttp" not in src, "Fremd-Bibliothek"
    assert "urllib.request" in src
    # Der Token darf nie in einer API-Antwort landen.
    up.configure(root=hier, token="geheim")
    st = up.settings()
    assert "geheim" not in repr(st) and st["has_token"] is True, st
    ok("updater: bot-frei, stdlib-only, Token nie in der Auskunft")


def _test_flapguard_und_rate():
    """v4.0-W116: die beiden Verlaufs-Urteile, jeweils ohne Bot und ohne Uhr.

    Beide entscheiden ueber die ZEIT, und beide sind in der falschen
    Richtung teuer: zu empfindlich erzeugt Alarm-Muedigkeit, zu traege
    meldet nie. Genau deshalb stehen sie als reine Funktionen hier, wo
    Stunden in Millisekunden durchgespielt werden koennen.
    """
    import nc.flapguard as fg
    import nc.recdiag as rd

    # ── Flattern ──────────────────────────────────────────────────────────
    cfg = fg.FlapConfig(fenster_s=900, schwelle=4, ruhe_s=600,
                        melde_abstand_s=1800)
    w = fg.FlapWatch(cfg)
    t = 1000.0
    # Drei kurze Trennungen: noch kein Alarm.
    for i in range(3):
        u = w.trennung("kick", 30, t + i * 60)
        assert not u.melden, i
    # Die vierte im Fenster ist es.
    u = w.trennung("kick", 30, t + 180)
    assert u.melden and u.anzahl == 4 and "4 Trennungen" in u.grund, u
    ok("flapguard: vier Trennungen im Fenster schlagen an, drei nicht")

    # Regel 3: im Meldeabstand bleibt es still, danach nicht mehr.
    u = w.trennung("kick", 30, t + 240)
    assert not u.melden and u.anzahl == 5, u
    u = w.trennung("kick", 30, t + 1900)     # Abstand + Fenster vorbei
    assert not u.melden, "Fenster haette sich leeren muessen"
    ok("flapguard: Meldeabstand gedrosselt, altes Fenster faellt raus")

    # Regel 2: ein langer Halt loescht die Akte und meldet die Erholung.
    w2 = fg.FlapWatch(cfg)
    for i in range(4):
        w2.trennung("tw", 10, 100 + i)
    assert w2.snapshot()["tw"]["laut"] is True
    u = w2.trennung("tw", 3600, 5000)        # eine Stunde gehalten
    assert u.erholt and u.anzahl == 1 and not u.melden, u
    assert w2.snapshot()["tw"]["laut"] is False
    ok("flapguard: langer Halt loescht die Akte und meldet die Erholung")

    # Regel 1: ueber das Fenster hinaus summiert sich nichts auf.
    w3 = fg.FlapWatch(cfg)
    for i in range(10):
        u = w3.trennung("yt", 10, i * 1000.0)   # je 1000s auseinander
        assert not u.melden, i
    ok("flapguard: verteilte Trennungen summieren sich nicht zum Daueralarm")

    # ── Raten-Einbruch ────────────────────────────────────────────────────
    rc = rd.RateConfig(warmlauf_s=60, einbruch_anteil=0.15,
                       einbruch_dauer_s=90, min_grundlinie_bps=40000)
    sp = rd.RateSpur()
    NORM = 500_000            # 500 kB/s ~ 4 Mbit/s
    # Warmlauf: nie urteilen, nur Grundlinie bilden.
    for _ in range(4):
        assert sp.beobachte(NORM * 15, 15, rc) is None
    assert sp.grundlinie_bps >= 40000
    # Gesund weiter: still.
    for _ in range(4):
        assert sp.beobachte(NORM * 15, 15, rc) is None
    # Bild weg, Ton laeuft (5 % der Rate): erst nach der Mindestdauer melden.
    LEISE = int(NORM * 0.05)
    assert sp.beobachte(LEISE * 15, 15, rc) is None      # 15s
    assert sp.beobachte(LEISE * 15, 15, rc) is None      # 30s
    assert sp.beobachte(LEISE * 15, 15, rc) is None      # 45s
    assert sp.beobachte(LEISE * 15, 15, rc) is None      # 60s
    assert sp.beobachte(LEISE * 15, 15, rc) is None      # 75s
    assert sp.beobachte(LEISE * 15, 15, rc) == "einbruch"  # 90s
    assert sp.beobachte(LEISE * 15, 15, rc) is None      # nur EINMAL je Episode
    ok("recdiag.RateSpur: Einbruch erst nach Mindestdauer, dann genau einmal")

    # Erholung wird gemeldet, danach ist wieder Ruhe.
    assert sp.beobachte(NORM * 15, 15, rc) == "erholt"
    assert sp.beobachte(NORM * 15, 15, rc) is None
    ok("recdiag.RateSpur: Erholung genau einmal")

    # Der Einbruch darf die Grundlinie NICHT nach unten schleifen — sonst
    # normalisiert sich jeder Ausfall von selbst weg.
    sp2 = rd.RateSpur()
    for _ in range(8):
        sp2.beobachte(NORM * 15, 15, rc)
    basis = sp2.grundlinie_bps
    for _ in range(20):
        sp2.beobachte(LEISE * 15, 15, rc)
    assert sp2.grundlinie_bps == basis, "Grundlinie ist mitgewandert"
    ok("recdiag.RateSpur: Grundlinie wandert waehrend des Einbruchs nicht mit")

    # Eine statische Szene mit MASSVOLLEM Rueckgang loest nicht aus.
    sp3 = rd.RateSpur()
    for _ in range(8):
        sp3.beobachte(NORM * 15, 15, rc)
    for _ in range(20):
        assert sp3.beobachte(int(NORM * 0.4) * 15, 15, rc) != "einbruch"
    ok("recdiag.RateSpur: massvoller Rueckgang (40 %) ist kein Einbruch")

    # Beide Module bleiben bot-frei.
    import ast as _ast, os as _os
    for datei, erlaubt in (("flapguard.py", {"dataclasses", "__future__"}),):
        quelle = open(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)),
                                    "nc", datei), encoding="utf-8").read()
        for _n in _ast.walk(_ast.parse(quelle)):
            if isinstance(_n, _ast.Import):
                mods = [a.name.split(".")[0] for a in _n.names]
            elif isinstance(_n, _ast.ImportFrom):
                mods = [(_n.module or "").split(".")[0]]
            else:
                continue
            assert set(mods) <= erlaubt, (datei, mods)
    ok("flapguard: bot-frei und stdlib-only")



def _test_w10_diagnose_und_pfadschutz():
    """v4.1-W10: die Befunde aus dem error.log und von CodeQL — als reine Logik
       geprueft, dort wo sie liegt."""
    import os
    from nc.restream_util import (betroffene_ziele, fenstergroesse, http_url,
                                  url_host)
    from nc.util import datei_in

    # (1) Wer steht wirklich im stderr-Auszug? Kick und Twitch liegen BEIDE auf
    # live-video.net — deshalb wird auf den vollen Host verglichen. Genau daran
    # scheiterte die alte Diagnose: sie nannte kategorisch Kick.
    ziele = [("kick", "rtmps://fa723fc1b171.global-contribute.live-video.net:443/app/K1"),
             ("twitch", "rtmp://ingest.global-contribute.live-video.net/app/K2"),
             ("youtube", "rtmp://a.rtmp.youtube.com/live2/K3")]
    nur_twitch = ("[tee] Slave '[f=flv]rtmp://ingest.global-contribute."
                  "live-video.net/app/<KEY>': error opening: I/O error")
    assert betroffene_ziele(nur_twitch, ziele) == ["twitch"], \
        "Twitch-Ausfall wuerde weiter als Kick gemeldet"
    beide = nur_twitch + "\nSlave 'rtmps://fa723fc1b171.global-contribute.live-video.net:443/app/<KEY>' failed"
    assert betroffene_ziele(beide, ziele) == ["kick", "twitch"], "Reihenfolge/Menge falsch"
    assert betroffene_ziele("All tee outputs failed.", ziele) == [], \
        "ohne Host im Text darf kein Ziel behauptet werden"
    assert betroffene_ziele("", ziele) == [] and betroffene_ziele("x", []) == []
    assert url_host("rtmps://h.example:443/app/k") == "h.example"
    assert url_host("kaputt") == ""
    ok("v4.1-W10: Abbruch-Diagnose nennt das Ziel, das wirklich im stderr steht")

    # (2) Was auf eine Kommandozeile darf. Die Uebergabe ist eine Liste, es gibt
    # keine Shell — ein zweites Argument waere trotzdem ein zweites Argument.
    assert fenstergroesse("1080,1920") == "1080,1920"
    assert fenstergroesse(" 1920 x 1080 ") == "1920,1080", "x als Trenner nicht erkannt"
    assert fenstergroesse("800,600 --dump-dom", "9,9") == "9,9", "Flag-Anhang kommt durch"
    assert fenstergroesse("auto", "9,9") == "9,9" and fenstergroesse(None, "9,9") == "9,9"
    assert fenstergroesse("0,600", "9,9") == "9,9", "Nullbreite akzeptiert"
    assert fenstergroesse("999999,10", "9,9") == "9,9", "unbegrenzte Groesse akzeptiert"
    assert http_url("https://a.example/x") == "https://a.example/x"
    for boese in ("file:///etc/shadow", "--dump-dom", "javascript:1", ""):
        assert http_url(boese, "FB") == "FB", "%s kommt auf die Kommandozeile" % boese
    ok("v4.1-W10: Fenstergroesse und Overlay-URL koennen kein Argument schmuggeln")

    # (3) Pfad-Zusage statt Verbotsliste. Geprueft wird das ERGEBNIS: liegt die
    # aufgeloeste Datei wirklich unter der Basis?
    assert datei_in("/daten/clips", "a.mp4", ".mp4") == os.path.realpath("/daten/clips/a.mp4")
    for boese in ("../etc/passwd.mp4", "../../x.mp4", "/etc/shadow.mp4",
                  "", None):
        assert datei_in("/daten/clips", boese, ".mp4") is None, "%r kommt durch" % boese
    # Der Rueckwaertsschraegstrich ist unter POSIX ein ganz normales Zeichen in
    # einem Dateinamen — er traegt dort NICHT aus dem Verzeichnis heraus. Die
    # alte Pruefung verbot ihn trotzdem; das war nicht falsch, aber es war eine
    # Aussage ueber Zeichen statt ueber das Ziel. Entscheidend ist, dass der
    # aufgeloeste Pfad in der Basis liegt — und das tut er hier.
    if os.sep == "/":
        assert datei_in("/daten/clips", "..\\x.mp4", ".mp4") == \
            os.path.realpath("/daten/clips/..\\x.mp4")
    assert datei_in("/daten/clips", "a.wav", ".mp4") is None, "Endung nicht erzwungen"
    assert datei_in("/daten/clips", "unterordner/a.mp4", ".mp4") == \
        os.path.realpath("/daten/clips/unterordner/a.mp4"), \
        "ein Unterordner INNERHALB der Basis ist erlaubt — die Zusage ist die Basis"
    # Der Praefix-Nachbar: /daten/clips2 faengt mit /daten/clips an, liegt aber
    # nicht darin. Genau das macht ein startswith-Vergleich falsch.
    assert datei_in("/daten/clips", "../clips2/a.mp4", ".mp4") is None, \
        "Praefix-Nachbar gilt faelschlich als innerhalb"
    ok("v4.1-W10: Ausliefer-Pfade weisen Zugehoerigkeit nach, statt Zeichen zu verbieten")

    # (4) Der Sprachkatalog liest nur bekannte Sprachen — der Name wird sonst
    # zum Dateipfad, und katalog() haengt an /api/i18n/katalog?lang=…
    import nc.i18n as I18N
    assert I18N.katalog("../../etc/passwd") == {}, "Sprachname wandert in den Pfad"
    assert I18N.katalog("fr") == {}, "unbekannte Sprache wird geladen"
    assert I18N.katalog("de") == {}, "Quellsprache braucht keinen Katalog"
    assert isinstance(I18N.katalog("en"), dict)
    ok("v4.1-W10: Katalog laedt nur Sprachen aus der Positivliste")



def _test_w12_einzel_slot():
    """v4.1-W12: zwei Restreams duerfen sich keinen Kick-Key teilen."""
    from nc.restream_util import slot_belegt

    # Der Fall vom 30.08.: #60 stirbt, wird aus _procs genommen, der Scheduler
    # vergibt den Slot an #6 — und 20 Sekunden spaeter feuert der geplante
    # Reconnect von #60. Genau hier muss die Antwort "belegt" lauten.
    assert slot_belegt(True, [6], 60) == 6, "Reconnect laeuft in den fremden Slot"
    assert slot_belegt(True, [], 60) is None, "freier Slot wird verweigert"
    # Der eigene Wiederanlauf ist kein Fremdbeleger — sonst koennte sich ein
    # Restream nach einem Abbruch nie mehr selbst neu aufbauen.
    assert slot_belegt(True, [60], 60) is None, "Restream blockiert sich selbst"
    # Multi-Modus heisst: eigene Keys je Ziel, also kein Slot.
    assert slot_belegt(False, [6, 43], 60) is None, "Multi-Modus kennt keinen Slot"
    # Mehrere Fremde: es genuegt, EINEN zu nennen — die Meldung soll knapp sein.
    assert slot_belegt(True, [6, 43], 60) in (6, 43)
    ok("v4.1-W12: Einzel-Slot wird beim START geprueft, nicht bei der Planung")



def _test_w13_claude_fehlergrund():
    """v4.1-W13: der Grund darf nicht im except haengenbleiben."""
    import json as _json
    import urllib.error
    import io as _io
    import nc.claude as C

    # (1) Der ECHTE Fehlertext der API kommt beim Aufrufer an. Im debug.log vom
    # 30.08. stand 26 Mal "fehlgeschlagen (bad_request)" und nie, WAS schlecht
    # war — obwohl die API es jedes Mal mitschickt.
    koerper = _json.dumps({"error": {"type": "invalid_request_error",
                                     "message": "max_tokens: must be >= 1"}}).encode()

    def _opener_400(req, timeout):
        raise urllib.error.HTTPError(C.API_URL, 400, "Bad Request", {},
                                     _io.BytesIO(koerper))

    gesehen = []
    txt, kind = C.chat_sync([{"role": "user", "content": "hi"}], "k",
                            opener=_opener_400,
                            on_error=lambda k, d, m: gesehen.append((k, d, m)))
    assert (txt, kind) == (None, "bad_request"), "Vertrag (text, kind) veraendert"
    assert gesehen, "der Grund wird weiter verschluckt"
    assert "max_tokens: must be >= 1" in gesehen[0][1], "API-Text fehlt"
    assert "HTTP 400" in gesehen[0][1] and gesehen[0][2], "Status oder Modell fehlt"

    # (2) Ohne Rueckruf bleibt alles wie vorher — die zwoelf Aufrufstellen, die
    # `err == "auth"` vergleichen, duerfen sich nicht aendern.
    assert C.chat_sync([{"role": "user", "content": "hi"}], "k",
                       opener=_opener_400) == (None, "bad_request")

    # (3) Leere Inhalte fliegen raus: die API weist einen leeren Textblock mit
    # 400 ab, und zwar den GANZEN Request.
    b = C.build_payload([{"role": "system", "content": "S"},
                         {"role": "user", "content": "   "},
                         {"role": "user", "content": "echt"}])
    assert b["messages"] == [{"role": "user", "content": "echt"}], "leerer Block bleibt drin"
    assert b["system"] == "S"

    # (4) Gar kein Verlauf: der Aufruf kann nicht gelingen, also wird er nicht
    # gemacht — und der Grund heisst nicht "bad_request".
    gesehen2 = []
    assert C.chat_sync([{"role": "system", "content": "nur system"}], "k",
                       opener=lambda r, t: (_ for _ in ()).throw(
                           AssertionError("API wurde trotzdem gerufen")),
                       on_error=lambda k, d, m: gesehen2.append(k)) == (None, "kein_verlauf")
    assert gesehen2 == ["kein_verlauf"]
    ok("v4.1-W13: Claude-Fehler nennen Grund und Modell, leere Requests gar nicht erst")



def _test_w14_totes_modell():
    """v4.1-W14: ein totes Modell darf nicht jeden Umlauf den ersten Versuch kosten."""
    import nc.freeai as F

    base = {"url": "https://api.llm7.io/v1",
            "models": ["gpt-4.1-nano-2025-04-14", "zweit", "dritt"]}
    F._model_block.clear()
    assert F._candidate_models(base, None)[0] == "gpt-4.1-nano-2025-04-14"

    # Der Fall aus dem debug.log: 26 Mal "Model ... is currently unavailable",
    # jedes Mal als ERSTER Versuch. Nach dem Merken steht er hinten.
    F._block_model(base["url"], "gpt-4.1-nano-2025-04-14")
    reihe = F._candidate_models(base, None)
    assert reihe[0] == "zweit", "das tote Modell kommt weiter zuerst dran"
    assert set(reihe) == set(base["models"]), "ein Modell ist ganz verschwunden"
    assert reihe[-1] == "gpt-4.1-nano-2025-04-14", "das tote Modell steht nicht hinten"

    # Sind ALLE gesperrt, wird trotzdem probiert — dieselbe Haltung wie bei
    # _eligible_bases: lieber ein Versuch als sicheres Scheitern.
    for m in base["models"]:
        F._block_model(base["url"], m)
    assert F._candidate_models(base, None) == base["models"], \
        "bei komplett gesperrter Base bleibt nichts zum Probieren"

    # Die Sperre gilt pro BASE, nicht global: dasselbe Modell kann anderswo leben.
    andere = {"url": "https://text.pollinations.ai", "models": ["gpt-4.1-nano-2025-04-14", "x"]}
    assert F._candidate_models(andere, None)[0] == "gpt-4.1-nano-2025-04-14", \
        "die Sperre wirkt ueber Basen hinweg — ein gesundes Modell waere mitgesperrt"

    # Eine Base ohne Katalog bleibt unberuehrt (custom FREEAI_BASES).
    assert F._candidate_models({"url": "x"}, "wunsch") == ["wunsch"]
    F._model_block.clear()
    ok("v4.1-W14: totes Modell wandert ans Ende, pro Base, nie ganz raus")


def _test_w18_toxizitaet_ohne_tiktok():
    """v4.1-W18: TikTok loest keine Toxizitaets-Warnung beim Betreiber aus."""
    import nc.modstats as M

    # Der Fall aus dem Betrieb: ein aktiver Live-React-Worker schreibt AZRAELs
    # Reaktionen auf einen TikTok-Stream ins kick_mod_log. Frueher zaehlte
    # jede dieser Zeilen als "Moderations-Aktion" — sechs davon reichten fuer
    # eine Warnung ueber einen Chat, den der Bot gar nicht moderiert.
    tiktok = [("reaction", "azrael", {"src": "helge_72"})] * 12
    tiktok += [("highlight", "radar", {"score": 3})] * 4
    v = M.verdichte(tiktok)
    assert v["actions_1h"] == 0, "TikTok-Reaktionen zaehlen weiter als Moderation"
    assert v["platforms"] == {}

    # Was der Bot selbst sagt und was er lernt, ist ebenfalls keine Moderation.
    assert M.verdichte([("send", "bot", {}), ("reply", "bot", {}),
                        ("learn", "ai", {})])["actions_1h"] == 0

    # Die drei Stream-Chats zaehlen — mit Plattform-Aufschluesselung, damit die
    # Meldung sagt WO es kracht, nicht nur DASS.
    echt = [("timeout", "auto-mod-kick", {"platform": "kick"}),
            ("warn", "auto-mod-twitch", {"platform": "twitch", "cat": "spam"}),
            ("timeout", "auto-mod-youtube", {"platform": "youtube"}),
            ("flag", "auto-mod-youtube", {"platform": "youtube"})]
    v = M.verdichte(echt + tiktok)
    assert v["actions_1h"] == 4, v
    assert v["platforms"] == {"kick": 1, "twitch": 1, "youtube": 2}, v["platforms"]

    # Discord ist eine eigene Welt und standardmaessig NICHT dabei; wer es will,
    # traegt es ein. TikTok laesst sich auch so nicht zuschalten — es steht
    # nicht in PLATTFORMEN, und genau das ist der Sinn der harten Liste.
    dc = [("timeout", "ai-discord", {"platform": "discord", "toxic": 0.9})]
    assert M.verdichte(dc)["actions_1h"] == 0, "Discord meldet ungefragt mit"
    assert M.verdichte(dc, erlaubt=M.quellen("kick,discord"))["actions_1h"] == 1
    assert "tiktok" not in M.PLATTFORMEN, "TikTok waere konfigurierbar geworden"
    assert M.quellen("tiktok") == M.STANDARD_QUELLEN, "TikTok liess sich einschalten"
    assert M.quellen("tiktok,kick") == ("kick",)

    # Der Trend vergleicht zwei Stunden. Liefe die Vorstunde ungefiltert, waere
    # jede TikTok-Sitzung in der Vorstunde eine gemeldete "Beruhigung" und
    # jedes Ende einer Sitzung eine gemeldete "Welle". Beide Seiten, eine Regel.
    v = M.verdichte(echt, vorzeilen=tiktok)
    assert v["actions_prev_1h"] == 0, "die Vorstunde laeuft durch eine andere Regel"

    # sentinel-shield schreibt aus dem Kick-Moderator UND aus dem Discord-
    # Automod. Ohne Markierung ist die Zeile nicht zuzuordnen und zaehlt nicht
    # mit — eine falsch zugeordnete Warnung waere schlimmer als eine fehlende.
    assert M.plattform("sentinel-shield", {}) is None
    assert M.plattform("sentinel-shield", {"platform": "discord"}) == "discord"
    assert M.plattform("sentinel-shield", {"platform": "kick"}) == "kick"
    # Altbestand ohne Markierung bleibt ueber den Aktor lesbar.
    assert M.plattform("auto-mod-twitch", None) == "twitch"
    assert M.plattform("azrael", {"src": "helge_72"}) is None

    # Ein gefaelschter Plattformname faellt auf den Aktor zurueck statt zu zaehlen.
    assert M.plattform("auto-mod-kick", {"platform": "tiktok"}) == "kick"
    assert M.plattform("azrael", {"platform": "tiktok"}) is None

    # avg bleibt None, wenn niemand einen toxic-Wert gemessen hat: 0.0 waere
    # die Aussage "nicht toxisch", und die hat hier niemand getroffen.
    assert M.verdichte(echt)["avg_toxic_1h"] is None
    mit = [("timeout", "ai", {"platform": "kick", "toxic": 0.9}),
           ("timeout", "ai", {"platform": "kick", "toxic": 0.7})]
    assert M.verdichte(mit)["avg_toxic_1h"] == 0.8

    # Der Agent nennt die Plattformen in seiner Meldung.
    import brain.agents as A

    class _B:
        class memory:
            @staticmethod
            def record_metric(*a, **k): pass
    schnapp = {"actions_1h": 9, "actions_prev_1h": 1, "avg_toxic_1h": 0.8,
               "platforms": {"kick": 7, "twitch": 2}}
    m = A.ToxicityAgent(_B(), moderation=lambda: schnapp).run({})
    assert len(m) == 1 and "kick 7" in m[0]["text"] and "twitch 2" in m[0]["text"], m
    # Ohne Aufschluesselung (Altbestand) bleibt der Text wie bisher lesbar.
    m = A.ToxicityAgent(_B(), moderation=lambda: {
        "actions_1h": 9, "actions_prev_1h": 1}).run({})
    assert len(m) == 1 and "[" not in m[0]["text"], m

    ok("v4.1-W18: TikTok zaehlt nicht als Moderation, Plattform steht in der Meldung")


def _test_w18_kickmod_blueprint():
    """v4.1-W18: neun Routen raus, null neue Kontext-Eintraege."""

    import nc.badwords as B
    import nc.channels as C

    # (1) Die Datenschicht traegt sich selbst — Dateien, kein Bot, kein Netz.
    d = _ph.verzeichnis()
    B.configure(recordings_dir=d)
    assert B.load_banned() == [] and B.load_learned() == [], "leerer Start nicht leer"
    assert B.save_banned(["arsch", "x" * 99])
    assert B.load_banned() == ["arsch", "x" * 40], "keine Kappung auf 40 Zeichen"
    assert B.save_learned([{"word": "test"}])
    assert B.load_learned() == [{"word": "test"}]
    # Kaputtes JSON darf den Moderator nicht mitreissen: lieber leer als Absturz.
    open(os.path.join(d, "banned_words.json"), "w", encoding="utf-8").write("{kaputt")
    assert B.load_banned() == []
    # Und der Deckel gilt auch beim Lesen einer zu langen Liste.
    B.save_banned(["w%d" % i for i in range(B.CAP + 50)])
    assert len(B.load_banned()) == B.CAP

    # (2) Die Basisliste faellt bei Netzfehler NICHT auf leer zurueck — eine
    # geleerte Liste waere ein still entwaffneter Moderator.
    def _kaputt(url):
        raise OSError("kein Netz")
    w, q = B.fetch_ldnoobw_de(opener=_kaputt)
    assert q == "fallback" and w == B.FALLBACK_DE and w, "Netzfehler leert die Liste"
    # Eine leere Antwort zaehlt ebenfalls als Fehlschlag.
    w, q = B.fetch_ldnoobw_de(opener=lambda u: "\n#nur ein Kommentar\n")
    assert q == "fallback" and w == B.FALLBACK_DE
    w, q = B.fetch_ldnoobw_de(opener=lambda u: "eins\n# weg\nzwei\n")
    assert (w, q) == (["eins", "zwei"], "online")

    # (3) Der primaere Restream ist ein REGISTER, kein Alias. bot.py bindet den
    # Namen bei jeder Primaer-Nachfolge neu; ein Alias zeigte danach auf das
    # alte Dict, und das SENTINEL-Panel meldete den vorherigen User als aktiv.
    C.RESTREAM_ACTIVE["obj"] = {}
    assert C.restream_active() == {}, "restream_active gibt None statt {}"
    C.RESTREAM_ACTIVE["obj"] = {"user": "helge_72", "rid": 7}
    assert C.restream_active().get("user") == "helge_72"

    # (4) Der Blueprint sieht denselben Zustand wie der Bot — das ist der
    # ganze Punkt der Register. Und er kommt ohne neuen ctx-Slot aus.
    import ast as _ast

    import nc.routes.kickmod as K
    from flask import Flask
    app = Flask(__name__)
    app.register_blueprint(K.bp)
    regeln = {str(r.rule) for r in app.url_map.iter_rules() if r.endpoint != "static"}
    assert len(regeln) == 9, regeln
    with app.test_client() as cl:
        j = cl.get("/api/kickmod/status").get_json()
    assert j["ok"] and j["running"] is False, j
    assert j["channels"]["tiktok"]["connected"] is True, "Register nicht gelesen"
    C.RESTREAM_ACTIVE["obj"] = {}

    # Ohne laufenden Moderator antworten die schreibenden Routen 503 statt 500:
    # "startet noch" ist voruebergehend, das Dashboard darf es wiederholen.
    with app.test_client() as cl:
        for weg in ("/api/kickmod/config", "/api/kickmod/start",
                    "/api/kickmod/say", "/api/kickmod/import_badwords"):
            assert cl.post(weg, json={}).status_code == 503, weg

    # (5) Kein neuer ctx-Slot. Der Kontext steht vertraglich bei hoechstens 25.
    quelle = open("nc/routes/kickmod.py", encoding="utf-8").read()
    genutzt = {n.attr for n in _ast.walk(_ast.parse(quelle))
               if isinstance(n, _ast.Attribute) and isinstance(n.value, _ast.Call)
               and getattr(n.value.func, "id", "") == "_c"}
    assert genutzt == {"run_async"}, "der Blueprint braucht mehr als run_async: %r" % genutzt

    # (6) Die sieben .env-Werte werden bei JEDEM Aufruf gelesen, nicht als
    # Modul-Konstante eingefroren (CLAUDE.md: .env laedt teils erst spaeter).
    for kopf in ("KICK_CLIENT_ID", "KICKMOD_AUTOSTART", "DISCORD_BOT_TOKEN",
                 "LIVE_REACT_CHAT", "KICK_CHATROOM_ID"):
        assert 'os.getenv("%s"' % kopf in quelle or '_txt("%s")' % kopf in quelle \
            or '_flag("%s")' % kopf in quelle, "%s eingefroren" % kopf
    for zeile in quelle.split("\n"):
        z = zeile.strip()
        assert not (z[:1].isupper() and " = os.getenv(" in z), \
            "Modul-Konstante friert .env ein: %s" % z

    ok("v4.1-W18: kickmod als Blueprint, Bannwoerter und Primaer-Restream geloest")


def _test_w19_azrael_blueprint():
    """v4.1-W19: die groesste Routengruppe raus, null neue Kontext-Eintraege."""
    import ast as _ast

    import nc.azraelstate as A
    import nc.piper_voices as P
    import nc.whispercfg as W

    # (1) Whisper: Name UND Objekt in EINEM Register. Wer nur den Namen
    # aendert und das geladene Modell stehen laesst, transkribiert weiter mit
    # dem alten Modell und zeigt den neuen Namen an — schlimmer als gar kein
    # Umschalten, weil es wie Erfolg aussieht.
    W.MODELL.update(name="base", obj="ALTES-MODELL")
    assert W.name() == "base" and W.geladen()
    assert W.waehle("large-v3") == "large-v3"
    assert W.name() == "large-v3" and not W.geladen(), "das alte Modell blieb geladen"
    # Ein leerer Name aendert nichts — sonst haette ein Tippfehler im Dashboard
    # den Namen geleert und faster-whisper waere mit "" gestartet.
    assert W.waehle("") == "large-v3" and W.waehle(None) == "large-v3"
    W.MODELL.update(name="base", obj=None)

    # (2) Piper: die Suchorte kommen per configure(), nicht als Modul-Konstante.
    # Ein Wechsel muss den Cache verwerfen, sonst zeigt /api/azrael/voices die
    # Stimmen des alten Verzeichnisses und der Betreiber sucht am falschen Ort.
    d1, d2 = _ph.verzeichnis(), _ph.verzeichnis()
    open(os.path.join(d1, "de_DE-thorsten-medium.onnx"), "w").close()
    os.makedirs(os.path.join(d2, "unter"), exist_ok=True)
    open(os.path.join(d2, "unter", "en_US-amy-low.onnx"), "w").close()
    P.configure(bin="piper", data_dir=d1, voice_dirs=[d1], recordings_dir="",
                module_dir="")
    assert [v["name"] for v in P.list_voices()] == ["de_DE-thorsten-medium"]
    P.configure(voice_dirs=[d2])
    assert [v["name"] for v in P.list_voices()] == ["en_US-amy-low"], \
        "der Cache ueberlebte den Wechsel der Suchorte"
    # Rekursiv: die .onnx liegt in einem Unterordner und wird trotzdem gefunden.
    assert P.resolve("amy") and P.resolve("amy").endswith("en_US-amy-low.onnx")
    assert P.resolve("gibtsnicht") is None
    # Der Cache greift innerhalb des Fensters, danach wird neu gescannt.
    open(os.path.join(d2, "spaeter.onnx"), "w").close()
    assert len(P.list_voices(_jetzt=1000.0)) in (1, 2)
    assert len(P.list_voices(force=True)) == 2, "force scannt nicht neu"

    # (3) Zustand: Bot und Blueprint sehen DASSELBE Objekt. Das ist der ganze
    # Punkt — eine Kopie hiesse, das Dashboard zeigt einen eingefrorenen Stand.
    A.OVERLAY.clear(); A.OVERLAY["piper_model"] = "thorsten"
    A.TRANSCRIPT.clear(); A.TRANSCRIPT["helge_72"] = [{"ts": 1, "text": "hallo"}]
    A.LIVE_PAUSED["v"] = True
    import nc.routes.azrael as R
    from flask import Flask
    app = Flask(__name__)
    app.register_blueprint(R.bp)
    regeln = {str(r.rule) for r in app.url_map.iter_rules() if r.endpoint != "static"}
    assert len(regeln) == 18, sorted(regeln)
    with app.test_client() as cl:
        j = cl.get("/api/azrael/live_status").get_json()
        assert j["paused"] is True, "der Blueprint sieht eine Kopie"
        assert j["active"] == [], j
        j = cl.get("/api/azrael/transcript").get_json()
        assert j["transcript"] == {"helge_72": [{"ts": 1, "text": "hallo"}]}
        j = cl.get("/api/azrael/piper_status").get_json()
        assert j["model"] == "thorsten", j
        # Ohne Haken antwortet die Route voruebergehend, nicht mit 500.
        assert cl.post("/api/azrael/ask", json={"q": "hi"}).status_code == 503
        assert cl.post("/api/azrael/ask", json={}).status_code == 400
    A.LIVE_PAUSED["v"] = False; A.OVERLAY.clear(); A.TRANSCRIPT.clear()

    # (4) Personas: atomar geschrieben, kaputtes JSON reisst nichts mit.
    d3 = _ph.verzeichnis()
    A.configure(recordings_dir=d3)
    assert A.personas_load() == {}
    assert A.personas_save({"helge_72": "frech"})
    assert A.personas_load() == {"helge_72": "frech"}
    open(A.personas_path(), "w", encoding="utf-8").write("{kaputt")
    assert A.personas_load() == {}, "kaputtes JSON reisst die Personas mit"

    # (5) Kein neuer ctx-Slot: der Blueprint benutzt nur, was es schon gab.
    quelle = open("nc/routes/azrael.py", encoding="utf-8").read()
    genutzt = {n.attr for n in _ast.walk(_ast.parse(quelle))
               if isinstance(n, _ast.Attribute) and isinstance(n.value, _ast.Call)
               and getattr(n.value.func, "id", "") == "_c"}
    assert genutzt <= {"run_async", "arg_int", "log"}, \
        "der Blueprint braucht neue Kontext-Eintraege: %r" % genutzt

    # (6) Keine Modul-Konstante friert .env ein.
    for zeile in quelle.split("\n"):
        z = zeile.strip()
        assert not (z[:1].isupper() and " = os.getenv(" in z), \
            "Modul-Konstante friert .env ein: %s" % z

    ok("v4.1-W19: azrael als Blueprint, Stimme/Whisper/Zustand geloest")


def _test_w20_overlay_audio_und_geld():
    """v4.1-W20: fuenf Routen raus, EINE Quelle fuers Einnahmen-Gate."""
    import ast as _ast

    import nc.audiocue as AC
    import nc.azraelstate as A
    import nc.channels as C
    import nc.revenue as R

    # (1) Das Einnahmen-Gate hat jetzt EINE Quelle. Vorher stand es als
    # Konstantenpaar im Monolithen und money.py spiegelte es ueber ctx.cfg —
    # zwei Orte fuer eine Wahrheit, aus der ein Drift wird.
    # ANKER GEWANDERT (v4.2-W164, nicht der Vertrag): "manual" ist der Wert,
    # den nc/routes/money.py speichert — "manuell" kam nie vor.
    assert R.PLATFORMS == ("kick", "twitch", "youtube", "manual")
    assert "tiktok" not in R.PLATFORMS, "fremdes Geld waere Einnahme"
    assert R.is_revenue_platform("KICK ") and R.is_revenue_platform("manual")
    assert not R.is_revenue_platform("tiktok") and not R.is_revenue_platform("")
    assert not R.is_revenue_platform(None)
    assert R.sql_in() == "('kick','twitch','youtube','manual')"
    # TikTok darf sehr wohl ins Sendebild — Follows sind Reichweite, kein Geld.
    assert "tiktok" in R.OV_PLATFORMS
    assert R.normalisieren("TikTok") == "tiktok"
    assert R.normalisieren("erfunden") == "kick" and R.normalisieren(None) == "kick"

    # (2) Ton-Konfig: gespeicherter Wert schlaegt .env-Vorgabe, ohne Neustart.
    AC.configure(tone=True, freq=880.0, ms=120, vol=0.25, gap_ms=60, duck=0.9)
    c = AC.config()
    assert c["freq"] == 880.0 and c["duck"] == 0.9, c
    AC.configure(freq=440.0)
    assert AC.config()["freq"] == 440.0, "die .env-Vorgabe wurde eingefroren"

    # (3) Der Testton muss in den LIVE-Mix. Eine Kopie hiesse "0
    # Warteschlangen" bei laufendem Restream — eine Fehlanzeige, die wie ein
    # kaputter Ton aussieht.
    C.RESTREAM_TTS.clear()
    C.RESTREAM_TTS[7] = {"queue": []}
    import nc.routes.audio as RA
    from flask import Flask
    app = Flask(__name__)
    app.register_blueprint(RA.bp)
    with app.test_client() as cl:
        j = cl.post("/api/audio/testtone", json={}).get_json()
        assert j["ok"] and j["queues"] == 1, j
        assert len(C.RESTREAM_TTS[7]["queue"]) == 1, "der Ton landete nicht im Mix"
    C.RESTREAM_TTS.clear()
    with app.test_client() as cl:
        assert cl.post("/api/audio/testtone", json={}).get_json()["ok"] is False

    # (4) Overlay: der Zaehler-Nullpunkt ist geteilt. Ohne ihn summiert das
    # Overlay alles seit der Installation und springt beim Stream-Start nie
    # auf 0 zurueck (V37-OVMP-FIX).
    import nc.routes.overlay as RO
    app2 = Flask(__name__)
    app2.register_blueprint(RO.bp)
    regeln = {str(r.rule) for r in app2.url_map.iter_rules() if r.endpoint != "static"}
    assert len(regeln) == 3, sorted(regeln)
    A.OVERLAY.clear(); A.OVERLAY.update(title="Prüfstand", azrael_show=False)
    A.OVERLAY_SESSION["start"] = "2026-09-03T10:00:00+00:00"
    with app2.test_client() as cl:
        j = cl.get("/api/overlay/state").get_json()
        assert j["title"] == "Prüfstand", j
        assert j["session_start"] == "2026-09-03T10:00:00+00:00", j
        assert set(j["by_platform"]) >= set(R.OV_PLATFORMS)
        # Ohne Haken antwortet die Event-Route voruebergehend, nicht mit 500.
        A.PUSH["fn"] = None
        assert cl.post("/api/overlay/event", json={"kind": "follow"}).status_code == 503
        assert cl.post("/api/overlay/event", json={"kind": "quatsch"}).status_code == 400
        gesehen = []
        A.PUSH["fn"] = lambda *a, **k: gesehen.append((a, k))
        assert cl.post("/api/overlay/event",
                       json={"kind": "donation", "name": "x"}).status_code == 200
        assert gesehen and gesehen[0][1]["platform"] == "kick", gesehen
    A.PUSH["fn"] = None
    A.OVERLAY_SESSION["start"] = None
    A.OVERLAY.clear()

    # (5) Kein neuer ctx-Slot: beide Blueprints kommen ohne Kontext aus.
    for datei in ("nc/routes/overlay.py", "nc/routes/audio.py"):
        quelle = open(datei, encoding="utf-8").read()
        assert "from nc import ctx" not in quelle, "%s braucht den Kontext" % datei
        for zeile in quelle.split("\n"):
            z = zeile.strip()
            assert not (z[:1].isupper() and " = os.getenv(" in z), \
                "Modul-Konstante friert .env ein: %s" % z
        _ast.parse(quelle)

    ok("v4.1-W20: overlay+audio als Blueprint, Einnahmen-Gate mit einer Quelle")


def _test_w21_brain_blueprint():
    """v4.1-W21: sechs Routen raus; Zahl und Router als Register, Rest Alias."""
    import ast as _ast

    import nc.brainstate as B

    # (1) STALLS MUSS ein Register sein. Eine ganze Zahl laesst sich nicht per
    # Alias teilen — ein Alias waere eine Kopie auf 0, und /api/brain/health
    # meldete "keine Stalls", waehrend der Loop klemmt. Genau die stille
    # Fehlanzeige, gegen die es die Zahl ueberhaupt gibt.
    B.STALLS["n"] = 0
    assert B.stall() == 1 and B.stall() == 2
    assert B.STALLS["n"] == 2, "der Zaehler ist nicht geteilt"

    # (2) Die Ringpuffer sind BEIM SCHREIBEN begrenzt, nicht beim Lesen. Sonst
    # waechst die Liste weiter und nur die Anzeige sieht harmlos aus — ein
    # Speicherleck, das erst nach Tagen auffaellt.
    B.HISTORY.clear(); B.STREAM.clear(); B.LAST_STATUS.clear()
    for i in range(B.HISTORY_MAX + 25):
        B.record({"core": {"activity": i, "status": "active", "label": "BOT CORE"}})
    assert len(B.HISTORY["core"]) == B.HISTORY_MAX, len(B.HISTORY["core"])
    assert B.HISTORY["core"][-1] == B.HISTORY_MAX + 24, "die juengsten Werte fehlen"
    assert B.history_for("core") == B.HISTORY["core"]
    assert B.history_for("gibtsnicht") == []

    # (3) Ein Status-UEBERGANG erzeugt genau ein Stream-Ereignis, kein Dauerfeuer.
    B.STREAM.clear(); B.LAST_STATUS.clear()
    # Der erste Blick auf einen Knoten ist kein Uebergang: sonst meldete jeder
    # Bot-Start eine Welle von Ereignissen fuer Zustaende, die sich gar nicht
    # geaendert haben.
    B.record({"x": {"activity": 1, "status": "active", "label": "X"}})
    assert B.STREAM == [], "der erste Blick gilt schon als Uebergang"
    B.record({"x": {"activity": 1, "status": "error", "label": "X"}})
    assert len(B.STREAM) == 1 and B.STREAM[0]["kind"] == "error", B.STREAM
    B.record({"x": {"activity": 1, "status": "error", "label": "X"}})
    assert len(B.STREAM) == 1, "gleicher Status erzeugt weiter Ereignisse"
    B.record({"x": {"activity": 1, "status": "active", "label": "X"}})
    assert len(B.STREAM) == 2 and B.STREAM[-1]["kind"] == "up"
    # Juengstes zuerst — das Panel zeigt oben, was gerade passiert ist.
    assert B.stream_recent(1)[0]["kind"] == "up"
    for i in range(B.STREAM_MAX + 10):
        B.record({"x": {"activity": 1, "status": "error" if i % 2 else "active", "label": "X"}})
    assert len(B.STREAM) == B.STREAM_MAX

    # (4) Der Blueprint sieht denselben Zustand wie der Bot.
    import nc.routes.brain as R
    from flask import Flask
    app = Flask(__name__)
    app.register_blueprint(R.bp)
    regeln = {str(r.rule) for r in app.url_map.iter_rules() if r.endpoint != "static"}
    assert len(regeln) == 6, sorted(regeln)
    B.BRIDGE.update(ok=False, phase="import_failed", error="brain fehlt")
    B.STALLS["n"] = 7
    with app.test_client() as cl:
        j = cl.get("/api/brain/health").get_json()
        assert j["ok"] is False and j["phase"] == "import_failed", j
        assert j["error"] == "brain fehlt", "der echte Grund kommt nicht durch"
        assert j["loop_stalls"] == 7, "der Stall-Zaehler ist eine Kopie"
        assert cl.get("/api/brain/creator").get_json()["ok"] is False
    B.BRIDGE.update(ok=False, phase="not_started", error=None)
    B.STALLS["n"] = 0

    # (5) Kein neuer ctx-Slot, keine eingefrorene .env-Konstante.
    quelle = open("nc/routes/brain.py", encoding="utf-8").read()
    genutzt = {n.attr for n in _ast.walk(_ast.parse(quelle))
               if isinstance(n, _ast.Attribute) and isinstance(n.value, _ast.Call)
               and getattr(n.value.func, "id", "") == "_c"}
    assert genutzt <= {"arg_int", "get_bot_start_time", "log"}, \
        "der Blueprint braucht neue Kontext-Eintraege: %r" % genutzt
    for zeile in quelle.split("\n"):
        z = zeile.strip()
        assert not (z[:1].isupper() and " = os.getenv(" in z), \
            "Modul-Konstante friert .env ein: %s" % z
    # Und kein globals()-Umweg: genau daran waere der Proxy-Router gescheitert.
    # Per AST, nicht per Text — die Erklaerung dazu steht voellig zu Recht im
    # Docstring des Blueprints und ist kein Verstoss (derselbe Fehlalarm wie
    # in W16).
    _baum = _ast.parse(quelle)
    assert not [n for n in _ast.walk(_baum)
                if isinstance(n, _ast.Call) and isinstance(n.func, _ast.Name)
                and n.func.id == "globals"], \
        "globals() im Blueprint — das ist DIESER Namensraum"

    ok("v4.1-W21: brain als Blueprint, Zaehler und Router als Register")


def _test_w22_restream_blueprint():
    """v4.1-W22: sechzehn Routen raus; Keys bleiben drinnen."""
    import ast as _ast
    import os as _os

    import nc.restreamcfg as C
    import nc.restreamstate as S

    # (1) Die Sendeziele. Kick hat keinen Schalter — es ist der Hauptkanal und
    # wird ueber einen fehlenden Key abgeschaltet.
    alt = {k: _os.environ.get(k) for k in
           ("TWITCH_ENABLED", "TWITCH_STREAM_KEY", "TWITCH_INGEST_URL",
            "YOUTUBE_ENABLED", "KICK_STREAM_KEY", "RESTREAM_VERIFY_S")}
    try:
        _os.environ.pop("TWITCH_STREAM_KEY", None)
        _os.environ.pop("KICK_STREAM_KEY", None)
        _os.environ["TWITCH_ENABLED"] = "0"
        assert C.aktiv("kick") is True and C.aktiv("twitch") is False
        assert C.bereite_ziele() == [], C.bereite_ziele()
        _os.environ["TWITCH_ENABLED"] = "1"
        _os.environ["TWITCH_STREAM_KEY"] = "geheim123"
        assert C.aktiv("twitch") is True and C.key_gesetzt("twitch") is True
        assert C.bereite_ziele() == ["twitch"], C.bereite_ziele()
        # LIVE gelesen, nicht eingefroren: der Betreiber aendert Keys und
        # erwartet, dass der naechste Restream sie benutzt.
        _os.environ["RESTREAM_VERIFY_S"] = "17"
        assert C.verify_takt() == 17, "die Pruefparameter sind eingefroren"
        _os.environ["RESTREAM_VERIFY_S"] = "keine-zahl"
        assert C.verify_takt() == 120, "ein Tippfehler in .env darf nicht crashen"
        # Der globale Twitch-Ingest ist die Vorgabe (der alte live.twitch.tv
        # brach Restreams mit rc=8 ab).
        _os.environ.pop("TWITCH_INGEST_URL", None)
        assert "ingest.global-contribute" in C.ingest("twitch")
        assert C.ingest("erfunden") == "" and C.aktiv("erfunden") is False
    finally:
        for k, v in alt.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v

    # (2) Der Blueprint gibt KEINEN Stream-Key heraus. Wer das tut, verschenkt
    # den Kanal — jeder mit dem Key kann darauf senden.
    quelle = open("nc/routes/restream.py", encoding="utf-8").read()
    baum = _ast.parse(quelle)
    # Erlaubt ist der Kommandobauer-Pfad (ffmpeg braucht den Key). Verboten
    # ist "steht in einer Antwort" — von dort waere er sofort oeffentlich.
    for zeile in quelle.split("\n"):
        if "jsonify(" in zeile and '["key"]' in zeile:
            raise AssertionError("Stream-Key in einer API-Antwort: %s" % zeile.strip())
    # Und die Diagnose benutzt den bool, nicht den Wert.
    assert "key_gesetzt(" in quelle, "die Diagnose liest den Key statt des bools"

    # (3) Manager und Waechter sind REGISTER: sie entstehen im Monolithen erst
    # weit unten, ein Alias waere fuer immer None.
    S.MGR["obj"] = None
    assert S.mgr() is None and S.laufende() == [], "laufende() wirft ohne Manager"

    class _M:
        _procs = {7: object(), 3: object()}
    S.MGR["obj"] = _M()
    assert S.laufende() == [3, 7], S.laufende()
    S.MGR["obj"] = None

    # (4) Das Layout faellt auf 'studio' zurueck. Ein erfundener Modus wuerde
    # den ffmpeg-Filtergraph brechen.
    S.LAYOUT["mode"] = "burnin"
    assert S.layout_mode() == "burnin"
    S.LAYOUT["mode"] = "quatsch"
    assert S.layout_mode() == "studio", "ein erfundener Modus kommt durch"
    S.LAYOUT["mode"] = "studio"

    # (5) Der Blueprint traegt sechzehn Routen und braucht keinen neuen Slot.
    from flask import Flask
    import nc.routes.restream as R
    app = Flask(__name__)
    app.register_blueprint(R.bp)
    # REGELN zaehlen, nicht Pfade: /api/restream/testpush ist zweimal
    # registriert (GET fuer den Status, POST fuer den Lauf) und waere als
    # Menge nur ein Eintrag.
    regeln = [r for r in app.url_map.iter_rules() if r.endpoint != "static"]
    assert len(regeln) == 16, sorted(str(r.rule) for r in regeln)
    genutzt = {n.attr for n in _ast.walk(baum)
               if isinstance(n, _ast.Attribute) and isinstance(n.value, _ast.Call)
               and getattr(n.value.func, "id", "") == "_c"}
    assert genutzt <= {"run_async", "log_event", "log", "arg_int"}, \
        "der Blueprint braucht neue Kontext-Eintraege: %r" % genutzt
    for zeile in quelle.split("\n"):
        z = zeile.strip()
        assert not (z[:1].isupper() and " = os.getenv(" in z), \
            "Modul-Konstante friert .env ein: %s" % z

    # (6) Jeder .env-Name steht WOERTLICH da — sonst findet gen_env_example.py
    # ihn nicht (beim ersten Entwurf fielen prompt vierzehn Variablen still
    # aus der Vorlage) und ein grep laeuft ins Leere.
    cfg = open("nc/restreamcfg.py", encoding="utf-8").read()
    for name in ("KICK_INGEST_URL", "KICK_STREAM_KEY", "TWITCH_ENABLED",
                 "TWITCH_INGEST_URL", "TWITCH_STREAM_KEY", "YOUTUBE_ENABLED",
                 "YOUTUBE_INGEST_URL", "YOUTUBE_STREAM_KEY", "RESTREAM_VERIFY",
                 "RESTREAM_VERIFY_S", "RESTREAM_VERIFY_GRACE_S",
                 "RESTREAM_VERIFY_MISSES", "RESTREAM_STALL_TIMEOUT_S",
                 "RESTREAM_OVERLAY", "KICK_CHANNEL_URL", "DISCORD_INVITE_URL"):
        assert 'os.getenv("%s"' % name in cfg, \
            "%s steht nicht woertlich in einem os.getenv" % name

    ok("v4.1-W22: restream als Blueprint, Ziele live gelesen, kein Key nach aussen")


def _test_w23_beobachtung_und_toasts():
    """v4.1-W23: acht Beobachtungs-Routen raus, verkettete Toasts uebersetzbar."""
    import ast as _ast
    import re as _re

    import nc.brainstate as B
    import nc.channels as C
    import nc.tiktokheaders as H

    # (1) Die Zuschauer-Stichproben sind BEGRENZT. Ohne maxlen waere das ein
    # Leck, das erst nach Tagen auffaellt — bei 60-s-Takt sind 720 Punkte
    # rund 12 Stunden, und mehr zeigt der Graph ohnehin nicht.
    assert C.VIEWER_SAMPLES.maxlen == 720
    C.VIEWER_SAMPLES.clear()
    for i in range(900):
        C.VIEWER_SAMPLES.append((i, i))
    assert len(C.VIEWER_SAMPLES) == 720 and C.VIEWER_SAMPLES[-1] == (899, 899)
    C.VIEWER_SAMPLES.clear()

    # (2) Die drei Waechter-Zaehler liegen beieinander — sie beantworten
    # dieselbe Frage ("warum startet der nicht neu?") und wurden vorher an
    # drei Stellen im Monolithen gepflegt.
    for name in ("DEAD_STREAK", "EARLY_DISCONNECT", "DEAD_BACKOFF_UNTIL"):
        assert isinstance(getattr(B, name), dict), name

    # (3) Die TikTok-Kopfzeilen sind vollstaendig — ohne plausiblen
    # Fingerabdruck liefert TikTok eine andere Seite aus, und der Aufloeser
    # findet keine Stream-URL. Accept-Encoding kommt vom Bot, weil es davon
    # abhaengt, ob Brotli installiert ist.
    for k in ("User-Agent", "Accept", "Accept-Language", "Referer", "sec-ch-ua"):
        assert H.HEADERS.get(k), "Kopfzeile %s fehlt" % k
    H.configure(accept_encoding="gzip, deflate, br")
    assert H.HEADERS["Accept-Encoding"] == "gzip, deflate, br"
    H.configure(accept_encoding="gzip, deflate")

    # (4) Der Blueprint: acht Routen, kein neuer ctx-Slot, keine eingefrorene
    # .env-Konstante. /metrics liegt bewusst NICHT unter /api/ — ein
    # Prometheus-Scraper sucht es genau dort.
    from flask import Flask
    import nc.routes.beobachtung as R
    app = Flask(__name__)
    app.register_blueprint(R.bp)
    regeln = [r for r in app.url_map.iter_rules() if r.endpoint != "static"]
    # ANKER GEWANDERT (v4.2-W144, nicht der Vertrag): /api/beobachtung/lage
    # kam dazu — neun Routen; (v4.2-W148) /api/beobachtung/dienste und
    # /api/beobachtung/steuern — elf.
    assert len(regeln) == 11, sorted(str(r.rule) for r in regeln)
    assert any(str(r.rule) == "/metrics" for r in regeln)
    quelle = open("nc/routes/beobachtung.py", encoding="utf-8").read()
    baum = _ast.parse(quelle)
    genutzt = {n.attr for n in _ast.walk(baum)
               if isinstance(n, _ast.Attribute) and isinstance(n.value, _ast.Call)
               and getattr(n.value.func, "id", "") == "_c"}
    # v4.2-W122: recordings_dir ist KEIN neuer Slot (die Aufnahme-Blueprints
    # lesen ihn seit W107). /metrics braucht ihn fuer den freien Platz am
    # Aufnahmepfad — vorher stand dort `"RECORDINGS_DIR" in globals()`, im
    # Blueprint nie wahr, gemessen wurde also immer "/".
    assert genutzt <= {"run_async", "log", "log_event", "arg_int",
                       "scraper_session", "get_bot_start_time",
                       "recordings_dir"}, \
        "der Blueprint braucht neue Kontext-Eintraege: %r" % genutzt
    for zeile in quelle.split("\n"):
        z = zeile.strip()
        assert not (z[:1].isupper() and " = os.getenv(" in z), \
            "Modul-Konstante friert .env ein: %s" % z

    # (5) Diese Routen BEOBACHTEN nur. Kein Aufruf hier startet, stoppt oder
    # loescht etwas — das ist die Klammer, die die vier Gruppen zusammenhaelt,
    # und der Grund, warum sie in EINER Datei stehen duerfen.
    for n in _ast.walk(baum):
        if not (isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))):
            continue
        for d in n.decorator_list:
            if not (isinstance(d, _ast.Call) and _ast.unparse(d.func).endswith(".route")):
                continue
            meth = []
            for kw in d.keywords:
                if kw.arg == "methods":
                    meth = _ast.literal_eval(kw.value)
            assert set(meth) <= {"GET", "POST"}, "%s: schreibende Methode" % n.name
    assert "DELETE" not in quelle and "conn.execute(\"DELETE" not in quelle

    # (6) Die verketteten Toasts sind umschlossen. toast() erzeugt zwar einen
    # DOM-Knoten, aber bei 'Aufnahme @'+u+' gestartet' heisst der Knoten
    # "Aufnahme @helge_72 gestartet" — ein Eintrag fuer "Aufnahme @" trifft
    # dort nie. 28 solcher Eintraege standen bereits im Katalog und zaehlten
    # als uebersetzt, ohne je zu greifen.
    dash = open("templates/dashboard.html", encoding="utf-8").read()
    offen = []
    for m in _re.finditer(r"\btoast\s*\(\s*'([^'\\\n]{3,})'\s*\+", dash):
        offen.append(m.group(1))
    assert not offen, "verketteter Toast ohne T(): %r" % offen[:5]
    # Und das ZWEITE Argument bleibt unberuehrt: 'err'/'ok' ist eine
    # CSS-Klasse, kein Text. Ein T() darauf zerstoert die Fehlerfarbe.
    assert "T('err')" not in dash and 'T("err")' not in dash, \
        "die Toast-Klasse wird uebersetzt"

    ok("v4.1-W23: Beobachtungs-Routen als Blueprint, verkettete Toasts uebersetzbar")



def _test_w24_wartung_blueprint():
    """v4.1-W24: zehn Wartungsrouten raus — und die drei loeschenden Pfade
       behalten ihre Sicherungen."""
    import ast as _ast
    import os as _os
    import tempfile as _tf

    import nc.backupcfg as K
    from nc.backupcfg import aktiv as _nc_backup_aktiv
    import nc.retention as RET
    import nc.storage as ST

    # (1) Kein Geheimnis in der Anzeige. s3_konfiguriert() ist ein bool und
    # gibt nichts heraus; die Zugangsdaten kommen NUR aus s3_zugang(), das
    # ausschliesslich der boto3-Client aufruft. Wer hier einen Key in eine
    # Antwort schreibt, verschenkt den Bucket.
    alt = {k: _os.environ.get(k) for k in
           ("S3_BACKUP", "S3_BUCKET", "S3_ACCESS_KEY", "S3_SECRET_KEY")}
    try:
        _os.environ.update({"S3_BACKUP": "1", "S3_BUCKET": "eimer",
                            "S3_ACCESS_KEY": "AKIA-GEHEIM",
                            "S3_SECRET_KEY": "sehr-geheim"})
        assert K.s3_konfiguriert() is True
        assert isinstance(K.s3_konfiguriert(), bool)
        assert K.s3_zugang()["access_key"] == "AKIA-GEHEIM"
        # Ohne Schluessel gilt S3 als NICHT konfiguriert — sonst meldete das
        # Deck "gesichert", waehrend jeder Upload scheitert.
        _os.environ["S3_SECRET_KEY"] = ""
        assert K.s3_konfiguriert() is False
    finally:
        for k, v in alt.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v

    # (2) Live gelesen, nicht eingefroren: der Betreiber schaltet SYS_BACKUP
    # im Betrieb um und erwartet, dass die naechste Sicherung das sieht.
    vorher = _os.environ.get("SYS_BACKUP")
    try:
        _os.environ["SYS_BACKUP"] = "0"
        assert K.sys_backup() is False
        _os.environ["SYS_BACKUP"] = "1"
        assert K.sys_backup() is True
    finally:
        if vorher is None:
            _os.environ.pop("SYS_BACKUP", None)
        else:
            _os.environ["SYS_BACKUP"] = vorher

    # (3) DIE WICHTIGSTE ZUSICHERUNG DIESER WELLE. retention.scan(delete=True)
    # loescht Dateien. Geloescht wird ausschliesslich, was nachweislich im
    # Aufnahme-Verzeichnis liegt. Faellt diese Pruefung, wird aus einer
    # Aufraeumfunktion ein Loeschwerkzeug fuer das ganze Dateisystem.
    quelle = open("nc/retention.py", encoding="utf-8").read()
    assert "os.path.abspath(fp).startswith(rec_root + os.sep)" in quelle, \
        "Pfad-Haertung in nc/retention.py fehlt"
    # Und sie greift auch wirklich: eine Datei AUSSERHALB bleibt liegen.
    with _tf.TemporaryDirectory() as tmp:
        drinnen = _os.path.join(tmp, "rec")
        _os.makedirs(drinnen)
        aussen = _os.path.join(tmp, "fremd.txt")
        open(aussen, "w").write("x")
        assert _os.path.abspath(aussen).startswith(_os.path.abspath(drinnen) + _os.sep) is False
        # scan() ohne Datenbank liefert eine wohlgeformte Null-Antwort statt
        # einer Ausnahme — die Routen rechnen damit.
        r = RET.scan(1, drinnen, delete=False)
        assert r == {"count": 0, "freed_bytes": 0}, r
        assert _os.path.isfile(aussen), "Datei ausserhalb wurde angefasst"

    # (4) storage.cleanup loescht DATEIEN, nie Datenbankeintraege — der
    # Betreiber soll weiter sehen, DASS es die Aufnahme gab. Und days<=0
    # loescht gar nichts, auch nicht versehentlich.
    q = open("nc/storage.py", encoding="utf-8").read()
    assert "DELETE FROM recordings" not in q, \
        "storage.cleanup loescht Datenbankeintraege — das macht retention.py"
    r = ST.cleanup("/nicht/vorhanden", days=0)
    assert r["deleted"] == 0 and "RECORDINGS_RETAIN_DAYS=0" in r["reason"]

    # (5) Der Zustand des System-Backups ist ein ALIAS, kein Register: der
    # Monolith veraendert das Dict nur an Ort und Stelle. Bindet er den Namen
    # neu, meldet /api/backup/status fuer immer "laeuft nicht", waehrend die
    # Sicherung laeuft — ohne Fehler und ohne Logzeile.
    b = open("bot.py", encoding="utf-8").read()
    assert "_SYS_BACKUP_STATE = _nc_backup.STATE" in b, "Alias fehlt"
    assert b.count("_SYS_BACKUP_STATE = ") == 1, \
        "_SYS_BACKUP_STATE wird neu gebunden — der Alias zeigt dann auf eine tote Kopie"
    assert set(K.STATE) == {"running", "last_ts", "last_file", "size_mb",
                            "files", "error"}

    # (6) Der Blueprint: zehn Routen, kein neuer ctx-Slot.
    from flask import Flask
    import nc.routes.wartung as R
    app = Flask(__name__)
    app.register_blueprint(R.bp)
    regeln = [r for r in app.url_map.iter_rules() if r.endpoint != "static"]
    assert len(regeln) == 10, "10 Regeln erwartet, %d" % len(regeln)

    w = open("nc/routes/wartung.py", encoding="utf-8").read()
    # Kein Bucket-Geheimnis in einer Antwort. Geprueft wird ueber den AST und
    # nicht ueber den Text: der Modul-Kopf ERKLAERT s3_zugang() voellig zu
    # Recht, und ein Textvergleich meldete genau diese Erklaerung als
    # Verstoss (dieselbe Falle wie bei globals() in W22).
    _wb = _ast.parse(w)
    for _n in _ast.walk(_wb):
        assert not (isinstance(_n, _ast.Attribute) and _n.attr == "s3_zugang"), \
            "Blueprint liest S3-Zugangsdaten"
        assert not (isinstance(_n, _ast.Constant) and isinstance(_n.value, str)
                    and _n.value in ("S3_ACCESS_KEY", "S3_SECRET_KEY")), \
            "Blueprint liest einen S3-Schluessel direkt aus der Umgebung"
    # Die zwei Haken sind deklariert und werden im Monolithen eingetragen.
    assert set(R.HAKEN) == {"local_scan", "system"}
    for h in R.HAKEN:
        assert '_nc_routes_wartung.HAKEN["%s"]["fn"]' % h in b, \
            "Haken %s wird im Monolithen nie eingetragen" % h

    # (7) Der Monolith ruft die geloesten Funktionen auf, statt sie ein
    # zweites Mal zu halten. Eine Kopie einer loeschenden Funktion laeuft
    # irgendwann auseinander — genau deshalb sind sie gewandert.
    for ruf in ("_nc_retention.scan(", "_nc_storage.cleanup(",
                "_nc_storage.stats(", "_nc_arules.run_archive_rules("):
        assert ruf in b, "Monolith ruft %s nicht auf" % ruf

    # (8) Ein fehlender Haken sagt es, statt Erfolg zu melden. Ohne diese
    # Pruefung startet threading.Thread(target=None) klaglos und die Route
    # antwortet started=True, waehrend nichts sichert — die stille Sorte
    # Fehler, die CLAUDE.md als Hauptfeind benennt.
    for h in R.HAKEN:
        R.HAKEN[h]["fn"] = None
    c = app.test_client()
    # Erst ein Ziel konfigurieren: ohne eins antwortet /api/backup/system
    # zurecht schon vorher mit 400 ("kein Ziel"), und die Haken-Pruefung
    # dahinter waere nie erreicht.
    sicher = {k: _os.environ.get(k) for k in ("LOCAL_BACKUP", "LOCAL_BACKUP_DIR")}
    try:
        _os.environ.update({"LOCAL_BACKUP": "1", "LOCAL_BACKUP_DIR": "/tmp/nc-backup-test"})
        assert _nc_backup_aktiv(), "Testaufbau: Ziel nicht erkannt"
        for pfad in ("/api/backup/system", "/api/backup/run"):
            antwort = c.post(pfad)
            assert antwort.status_code == 503, \
                "%s meldet %d statt 503 ohne Haken" % (pfad, antwort.status_code)
            assert antwort.get_json()["ok"] is False
    finally:
        for k, v in sicher.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v

    ok("v4.1-W24: Wartung als Blueprint, Loeschpfade gehaertet, keine S3-Geheimnisse")



def _test_w25_abwehr_blueprint():
    """v4.1-W25: vier Abwehr-Routen raus, ein Schreibweg fuer den Adress-Cache."""
    import ast as _ast
    import os as _os

    import nc.defensecfg as D
    import nc.geocache as G
    import nc.geoip as GI

    # (1) DER BEFUND DIESER WELLE. Der Adress-Cache hat genau EINEN
    # Schreibweg, und der setzt die Obergrenze durch. Vorher gab es zwei:
    # einen Helfer mit Grenze und einen Direktzugriff daran vorbei. Bei einer
    # Angriffswelle mit vielen verschiedenen Adressen wuchs der Cache
    # unbegrenzt — kein Fehler, keine Logzeile, nur Speicher.
    G.leeren()
    for i in range(G.MAX + 250):
        G.put("203.0.113.%d-%d" % (i // 256, i % 256), {"lat": i})
    assert G.groesse() == G.MAX, \
        "Obergrenze greift nicht: %d Eintraege" % G.groesse()
    G.leeren()
    # Und es gibt wirklich nur den einen Weg: das Modul gibt den Cache nicht
    # heraus. Wer ihn direkt fuellen wollte, muesste an einen privaten Namen.
    assert not hasattr(G, "CACHE"), "Cache liegt offen — der zweite Schreibweg"

    # (2) Ein vorhandener Eintrag wandert ans Ende, damit die Verdraengung den
    # aeltesten trifft und nicht den zuletzt benutzten.
    G.leeren()
    for name in ("a", "b", "c"):
        G.put(name, {"lat": 1})
    G.put("a", {"lat": 2})          # a ist jetzt der juengste
    assert G.get("a")["lat"] == 2
    G.leeren()

    # (3) Private und lokale Adressen kosten nur Kontingent (45/min bei
    # ip-api) und fallen still raus — ohne Netzzugriff.
    for ip in ("10.0.0.1", "127.0.0.1", "192.168.5.9", "169.254.1.1"):
        assert GI.ist_privat(ip), ip
    assert not GI.ist_privat("8.8.8.8")
    gemeldet = []
    assert GI.lookup(["10.0.0.1", "127.0.0.1"],
                     fehler_setzen=gemeldet.append) == {}
    assert G.groesse() == 0, "private Adressen im Cache gelandet"

    # (4) Kein Geheimnis in der Anzeige. bouncer_gesetzt() ist ein bool; den
    # Schluessel gibt nur bouncer_key() heraus, und das ruft ausschliesslich
    # der LAPI-Aufruf im Monolithen.
    vorher = _os.environ.get("CROWDSEC_BOUNCER_KEY")
    try:
        _os.environ["CROWDSEC_BOUNCER_KEY"] = "geheim-123"
        assert D.bouncer_gesetzt() is True
        assert isinstance(D.bouncer_gesetzt(), bool)
        assert D.bouncer_key() == "geheim-123"
        _os.environ["CROWDSEC_BOUNCER_KEY"] = ""
        assert D.bouncer_gesetzt() is False
    finally:
        if vorher is None:
            _os.environ.pop("CROWDSEC_BOUNCER_KEY", None)
        else:
            _os.environ["CROWDSEC_BOUNCER_KEY"] = vorher

    # (5) Leere .env-Zeilen kippen den Standort nicht. Eine gesetzte, leere
    # Variable ist der haeufigste Fall (v4.0-W82) — sie muss auf den
    # Vorgabewert zurueckfallen, nicht werfen.
    sicher = {k: _os.environ.get(k) for k in ("DEFENSE_SERVER_LAT", "DEFENSE_SERVER_LON")}
    try:
        _os.environ.update({"DEFENSE_SERVER_LAT": "", "DEFENSE_SERVER_LON": "quatsch"})
        assert D.server_lat() == 50.69 and D.server_lon() == 2.13
        _os.environ["DEFENSE_SERVER_LAT"] = "48,21"      # Komma statt Punkt
        assert abs(D.server_lat() - 48.21) < 1e-9
    finally:
        for k, v in sicher.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v

    # (6) Der Fehlgrund der Geo-Aufloesung ist ein REGISTER, kein Alias: eine
    # Zeichenkette ist unteilbar, und der Monolith band den Namen frueher neu.
    D.geo_fehler_setzen("x" * 400)
    assert len(D.geo_fehler()) == 160, "Fehlgrund nicht gekuerzt"
    D.geo_fehler_setzen("")
    b = open("bot.py", encoding="utf-8").read()
    assert "_DEFENSE_GEO_ERR" not in b, \
        "der alte Modul-Global steht noch — zwei Wahrheiten ueber denselben Fehlgrund"

    # (7) Der Blueprint: vier Routen, kein neuer ctx-Slot, kein Schluessel
    # nach aussen.
    from flask import Flask
    import nc.routes.abwehr as R
    app = Flask(__name__)
    app.register_blueprint(R.bp)
    regeln = [r for r in app.url_map.iter_rules() if r.endpoint != "static"]
    assert len(regeln) == 4, "4 Regeln erwartet, %d" % len(regeln)

    w = open("nc/routes/abwehr.py", encoding="utf-8").read()
    for _n in _ast.walk(_ast.parse(w)):
        assert not (isinstance(_n, _ast.Attribute) and _n.attr == "bouncer_key"), \
            "Blueprint liest den Bouncer-Schluessel"

    # (8) Ohne Haken meldet die Ansicht NICHT "alles ruhig". Bei einer
    # Sicherheitsanzeige ist 0 Sperren / 0 Angriffe die gefaehrlichste aller
    # falschen Antworten — sie sieht aus wie ein gutes Ergebnis.
    for h in R.HAKEN:
        R.HAKEN[h]["fn"] = None
    c = app.test_client()
    for pfad in ("/api/defense/overview", "/api/defense/crowdsec",
                 "/api/defense/fail2ban", "/api/defense/attacks"):
        antwort = c.get(pfad)
        assert antwort.status_code == 503, \
            "%s meldet %d statt 503 ohne Haken" % (pfad, antwort.status_code)
        d = antwort.get_json()
        assert d["ok"] is False and d["status"] == "nicht_bereit"
    # Der Monolith traegt beide wirklich ein.
    for h in R.HAKEN:
        assert '_nc_routes_abwehr.HAKEN["%s"]["fn"]' % h in b, \
            "Haken %s wird im Monolithen nie eingetragen" % h

    ok("v4.1-W25: Abwehr als Blueprint, Adress-Cache mit EINEM Schreibweg")



def _test_w26_huellen_schlucken_nichts():
    """v4.1-W26: die Zaehl-Huellen im Monolithen duerfen kein Argument
       verlieren.

    ECHTER PRODUKTIONSFEHLER, gefunden im error.log vom 2026-09-03:

        TypeError: _claude_chat_sync_metered() got an unexpected keyword
                   argument 'on_error'

    Der Monolith ERSETZT nc.claude.chat_sync durch eine Huelle, die die Token
    zaehlt. Die Huelle zaehlte ihre Parameter einzeln auf. Als v4.1-W13
    `on_error` zu chat_sync hinzufuegte, wurde sie nicht mitgezogen — und
    damit brach jeder Aufruf, der den neuen Parameter benutzte.
    _living_title_loop lief neunmal genau da hinein, jedes Mal die ganze Runde
    verloren. Im Log stand nur "Schleife gestoert", der Grund kam erst aus dem
    Traceback.

    Geprueft wird ueber den AST von bot.py gegen die ECHTE Signatur des
    umhuellten Moduls — bot.py laesst sich hier nicht importieren (voller
    Laufzeitstack), die nc-Module schon.
    """
    import ast as _ast
    import inspect as _inspect

    import nc.claude as _claude
    import nc.freeai as _freeai

    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    huellen = {n.name: n for n in baum.body if isinstance(n, _ast.FunctionDef)}

    for huelle, modul, fn in (("_claude_chat_sync_metered", _claude, "chat_sync"),
                              ("_freeai_chat_sync_metered", _freeai, "chat_sync")):
        n = huellen.get(huelle)
        assert n is not None, "%s gibt es nicht mehr" % huelle
        eigen = {a.arg for a in n.args.args} | {a.arg for a in n.args.kwonlyargs}
        echt = set(_inspect.signature(getattr(modul, fn)).parameters)

        # (1) Entweder nennt die Huelle jeden Parameter selbst, ODER sie hat
        # ein **kwargs, das den Rest durchreicht. Alles andere heisst: ein
        # Aufruf mit dem fehlenden Parameter stirbt zur Laufzeit.
        fehlt = echt - eigen
        assert not fehlt or n.args.kwarg is not None, \
            ("%s verliert %s — genau der Fehler, der _living_title_loop "
             "neunmal gekillt hat" % (huelle, sorted(fehlt)))

        # (2) Die Positions-Parameter muessen in DERSELBEN Reihenfolge stehen.
        # Drei Aufrufstellen uebergeben model und timeout positionell; eine
        # Umsortierung schoebe das Modell in den falschen Parameter — ein
        # stiller Fehler statt eines lauten.
        echt_pos = [k for k in _inspect.signature(getattr(modul, fn)).parameters]
        eigen_pos = [a.arg for a in n.args.args]
        gemeinsam = [k for k in echt_pos if k in set(eigen_pos)]
        assert eigen_pos[:len(gemeinsam)] == gemeinsam, \
            ("%s hat die Parameter umsortiert: %r statt %r — positionelle "
             "Aufrufe landen im falschen Parameter" % (huelle, eigen_pos, gemeinsam))

        # (3) Die Huelle ersetzt das Modul wirklich. Faellt diese Zeile weg,
        # zaehlt niemand mehr Token, ohne dass irgendetwas bricht.
        assert "_nc_%s.%s = %s" % (
            {"nc.claude": "claude", "nc.freeai": "freeai"}[modul.__name__],
            fn, huelle) in open("bot.py", encoding="utf-8").read(), \
            "%s wird nie eingehaengt" % huelle

    # ---- Zweiter Befund aus demselben Log: der eingefrorene Event-Loop ----
    #
    # `_write_restream_overlay()` schreibt bis zu vierzehn Textdateien und lief
    # rund einmal pro Sekunde SYNCHRON auf dem Event-Loop. Unter Plattenlast
    # (685-MB-Upload, ffmpeg, Restream) blockierte os.replace bis zu 68
    # Sekunden — in der Zeit stand der ganze Bot. Neunzehn von fuenfundzwanzig
    # Stack-Abzuegen des Waechters zeigten genau diesen Aufruf.
    quelle = open("bot.py", encoding="utf-8").read()
    baum2 = _ast.parse(quelle)

    # (1) Der Sekundentakt laeuft NEBEN dem Loop.
    # ANKER GEWANDERT (v4.2-W179, nicht der Vertrag): der Leser wartet nicht
    # mehr auf das Schreiben, er feuert es ueber _overlay_takt() als Task —
    # abgewartet hielt er die Fortschrittsmarken an (Vertrag W179). Geprueft
    # im Syntaxbaum: der alte Textanker traf den Docstring von _overlay_takt.
    _takt = next(n for n in baum2.body if getattr(n, "name", "") == "_overlay_takt")
    assert "_spawn(_write_restream_overlay_async()" in _ast.unparse(_takt), \
        "der Sekundentakt schreibt wieder synchron auf dem Loop"
    for n in baum2.body:
        if isinstance(n, _ast.AsyncFunctionDef) and n.name == "_write_restream_overlay_async":
            break
    else:
        raise AssertionError("_write_restream_overlay_async gibt es nicht mehr")
    assert "asyncio.to_thread(_write_restream_overlay" in quelle, \
        "die nebenlaeufige Fassung ruft den Schreiber nicht im Thread"

    # (2) EIN Waechter, und zwar modul-global. Als Objekt-Attribut braeche er,
    # sobald das Objekt neu erzeugt wird (CLAUDE.md) — dann stapeln sich bei
    # langsamer Platte die Schreib-Threads, weil der Takt jede Sekunde kommt
    # und ein Schreibvorgang im Stoerfall ueber sechzig dauerte.
    assert '_OVERLAY_SCHREIBT = {"an": False}' in quelle, "Waechter fehlt"
    assert "if _OVERLAY_SCHREIBT[\"an\"]:" in quelle, "Waechter wird nicht geprueft"
    assert '_OVERLAY_SCHREIBT["an"] = False' in quelle, \
        "Waechter wird nie zurueckgesetzt — nach dem ersten Fehler schreibt nie wieder jemand"

    # (3) Der Anlauf-Aufruf bleibt SYNCHRON: die Textdateien muessen da sein,
    # BEVOR drawtext sie oeffnet. Ein await davor waere eine Wettlaufsituation
    # mit dem gerade startenden ffmpeg.
    # ANKER GEWANDERT (v4.2-W179): abgewartet, aber im Thread — die Zusage
    # (Dateien da, BEVOR ffmpeg startet) bleibt, nur haelt sie den Loop nicht mehr.
    _rm = next(n for n in baum2.body if isinstance(n, _ast.ClassDef)
               and n.name == "RestreamManager")
    _st = _ast.unparse(next(n for n in _rm.body if getattr(n, "name", "") == "start"))
    assert 0 <= _st.find("await asyncio.to_thread(_write_restream_overlay)") \
        < _st.find("asyncio.create_subprocess_exec("), \
        "der Anlauf-Aufruf ist verschwunden oder laeuft nach dem ffmpeg-Start"

    # (4) DER SCHREIBER DARF NUR LESEN. Er laeuft jetzt in einem Thread,
    # waehrend der Loop den geteilten Zustand weiter veraendert. Ein
    # Schreibzugriff von dort waere ein echtes Wettrennen — bei einem
    # `global` sogar eines, das den Zustand des ganzen Bots trifft. Geprueft
    # wird ueber den AST: keine global-Anweisung, und jede Mutation nur auf
    # Namen, die die Funktion selbst angelegt hat.
    for _n in baum2.body:
        if isinstance(_n, _ast.FunctionDef) and _n.name == "_write_restream_overlay":
            break
    else:
        raise AssertionError("_write_restream_overlay gibt es nicht mehr")
    assert not [g for g in _ast.walk(_n) if isinstance(g, _ast.Global)], \
        "der Overlay-Schreiber bindet einen globalen Namen neu — im Thread ein Wettrennen"
    _lokal = {t.id for k in _ast.walk(_n) if isinstance(k, _ast.Assign)
              for t in k.targets if isinstance(t, _ast.Name)}
    _lokal |= {a.arg for a in _n.args.args}
    for k in _ast.walk(_n):
        if isinstance(k, _ast.Call) and isinstance(k.func, _ast.Attribute) \
           and k.func.attr in ("append", "pop", "update", "clear", "setdefault",
                               "add", "remove", "insert", "extend") \
           and isinstance(k.func.value, _ast.Name):
            assert k.func.value.id in _lokal, \
                ("der Overlay-Schreiber veraendert %s — das ist geteilter Zustand, "
                 "und er laeuft seit W26 in einem Thread" % k.func.value.id)

    # (5) Der Aufnahme-Anspruch laeuft ebenfalls neben dem Loop — er stand in
    # zwei Abzuegen als Blocker (db_conn().__exit__ -> close()).
    assert "await asyncio.to_thread(try_acquire_recording_lock," in quelle, \
        "der Aufnahme-Anspruch blockiert wieder den Loop"

    ok("v4.1-W26: Zaehl-Huellen reichen alles durch, Overlay blockiert den Loop nicht mehr")


def _test_w26_auskunft_blueprint():
    """v4.1-W26: fuenfundzwanzig lesende Routen raus — und die Klammer haelt."""
    import ast as _ast

    from flask import Flask
    import nc.routes.auskunft as R

    app = Flask(__name__)
    app.register_blueprint(R.bp)
    regeln = [r for r in app.url_map.iter_rules() if r.endpoint != "static"]
    assert len(regeln) == 25, "25 Regeln erwartet, %d" % len(regeln)

    # (1) DIE KLAMMER DIESES BLUEPRINTS: er ANTWORTET nur. Keine Route hier
    # startet, stoppt, loescht oder speichert etwas. /api/annotations (DELETE)
    # und /api/highlights/config (POST) liegen benachbart und sind deshalb
    # ausdruecklich NICHT mitgewandert. Ohne diese Pruefung waere die Klammer
    # eine Behauptung im Docstring statt einer Regel.
    for r in regeln:
        schreibend = r.methods - {"GET", "HEAD", "OPTIONS"}
        assert not schreibend, \
            ("%s ist schreibend (%s) — dieser Blueprint antwortet nur"
             % (r.rule, sorted(schreibend)))

    # (2) Die Fachlogik ist mitgewandert, nicht kopiert. Der Monolith ruft
    # dieselben Funktionen auf wie der Blueprint — sonst gaebe es zwei
    # Wahrheiten ueber denselben Wert.
    b = open("bot.py", encoding="utf-8").read()
    for ruf in ("_nc_suche.universal_search(", "_nc_outcomes.get_outcome_breakdown(",
                "_nc_band.messen()", "_nc_storage.forecast(",
                "_nc_recdb.get_all_checks("):
        assert ruf in b, "Monolith ruft %s nicht auf" % ruf

    # (3) Der Radar-Zustand ist ein REGISTER, kein Haken: das ist geteilter
    # ZUSTAND, keine Faehigkeit. Und Register und nicht Alias, weil bot.py den
    # Namen mit new_state() neu bindet — ein Alias zeigte fuer immer auf das
    # leere Anfangs-Dict, und das Panel meldete dauerhaft null Treffer.
    import nc.highlights as H
    assert "STATE" in dir(H) and H.zustand() == {} or H.STATE["obj"] is not None
    assert '_nc_highlights.STATE["obj"] = _HIGHLIGHTS' in b, \
        "der Radar-Zustand wird nie ins Register gelegt"
    assert "highlights" not in R.HAKEN, \
        "geteilter Zustand als Haken — das ist die falsche Schublade"

    # (4) Ohne Haken sagt die Auskunft das, statt Leere zu melden. Eine leere
    # Liste sieht aus wie "nichts gefunden"; der Betreiber sucht dann an der
    # falschen Stelle.
    for h in R.HAKEN:
        R.HAKEN[h]["fn"] = None
    c = app.test_client()
    for pfad in ("/api/public/stats", "/api/summary/preview"):
        antwort = c.get(pfad)
        assert antwort.status_code == 503, \
            "%s meldet %d statt 503 ohne Haken" % (pfad, antwort.status_code)
        assert antwort.get_json()["status"] == "nicht_bereit"
    # Und alle vier werden im Monolithen wirklich eingetragen.
    for h in R.HAKEN:
        assert '_nc_routes_auskunft.HAKEN["%s"]["fn"]' % h in b, \
            "Haken %s wird im Monolithen nie eingetragen" % h

    # (5) Kein toter Import: was der Blueprint aus nc/ holt, benutzt er auch.
    # pyflakes prueft das ohnehin — hier steht es, weil dieser Blueprint mit
    # Abstand die meisten Importe hat und ein vergessener leicht durchrutscht.
    q = open("nc/routes/auskunft.py", encoding="utf-8").read()
    baum = _ast.parse(q)
    benutzt = {n.id for n in _ast.walk(baum) if isinstance(n, _ast.Name)} | \
              {n.attr for n in _ast.walk(baum) if isinstance(n, _ast.Attribute)} | \
              {n.value.id for n in _ast.walk(baum)
               if isinstance(n, _ast.Attribute) and isinstance(n.value, _ast.Name)}
    for n in baum.body:
        if isinstance(n, _ast.ImportFrom) and (n.module or "").startswith("nc"):
            for a in n.names:
                assert (a.asname or a.name) in benutzt, \
                    "toter Import: %s" % (a.asname or a.name)

    ok("v4.1-W26: Auskunft als Blueprint — 25 Routen, keine davon schreibt")



def _test_w27_verkettete_knoten():
    """v4.1-W27: verkettete Textzuweisungen im Dashboard sind uebersetzbar.

    Der DOM-Uebersetzer trifft GANZE Textknoten. Bei

        el.textContent = 'Quelle: ' + name

    heisst der Knoten "Quelle: kick"; ein Katalogeintrag fuer "Quelle: " trifft
    dort nie. ZEHN solcher Eintraege standen bereits im Katalog und zaehlten
    als uebersetzt, ohne je zu greifen — dieselbe stille Buchhaltung wie bei
    den nativen Dialogen (W21) und den verketteten Toasts (W23), nur an der
    dritten Stelle.

    Das ist der Grund, warum dieser Vertrag existiert: eine Abdeckungszahl,
    die tote Eintraege mitzaehlt, ist schlimmer als gar keine — sie sagt, die
    Arbeit sei getan.
    """
    import json as _json
    import re as _re

    dash = open("templates/dashboard.html", encoding="utf-8").read()
    WORT = _re.compile(r"[A-Za-zÄÖÜäöüß]{3}")
    MARKUP = _re.compile(r"[<>=]|var\(|&nbsp;|&#")
    LIT = _re.compile(r"'([^'\\\n]*(?:\\.[^'\\\n]*)*)'")
    ZUW = _re.compile(r"\.(?:textContent|innerText|innerHTML)\s*=\s*([^;\n]{0,300})")

    offen = []
    for m in ZUW.finditer(dash):
        rhs = m.group(1)
        if "+" not in rhs:
            continue                       # ganzes Literal ist schon ein Knoten
        for lm in LIT.finditer(rhs):
            t = lm.group(1)
            if not (t.strip() and WORT.search(t)) or MARKUP.search(t):
                continue
            davor = rhs[max(0, lm.start() - 2):lm.start()].strip()
            danach = rhs[lm.end():lm.end() + 2].strip()
            if not (davor.endswith("+") or danach.startswith("+")):
                continue
            if rhs[max(0, lm.start() - 3):lm.start()].endswith("T("):
                continue
            offen.append(t)
    assert not offen, \
        ("verkettete Textzuweisung ohne T() — der Knoten traegt den Wert mit "
         "und kein Katalogeintrag trifft ihn: %r" % offen[:6])

    # (2) Der Nachschlag TRIMMT beidseitig, der Extraktor legt getrimmt ab.
    # Faellt eines von beiden weg, sind alle Fragment-Eintraege ("Quelle: ",
    # " aktiv") auf einen Schlag tot — und die Abdeckungszahl luegt wieder.
    i18n = open("nc/routes/i18n.py", encoding="utf-8").read()
    # v4.1-W28: Anker nachgezogen, Zusicherung unveraendert. Der Nachschlag
    # trennt Rand und Kern jetzt per Ausdruck, statt zu trimmen und den Kern
    # zurueckzuersetzen — noetig fuer mehrzeilige Knoten, wo der getrimmte
    # Kern im Original gar nicht mehr woertlich vorkommt. Beide Eigenschaften
    # gelten weiter: der Rand wird abgetrennt UND wieder angesetzt.
    assert "text.match(/^(\\s*)([\\s\\S]*?)(\\s*)$/)" in i18n, \
        "der Nachschlag trennt Rand und Kern nicht mehr — Fragment-Eintraege treffen nie"
    assert "return vorn + treffer + hinten;" in i18n, \
        "die Rand-Leerzeichen gehen verloren — das Layout verrutscht"

    # (3) Prosa darf nicht mit Markup in EINEM Literal kleben. Sonst ist sie
    # nicht umschliessbar, und die Meldung steht halb uebersetzt da: der eine
    # Teil englisch, der andere deutsch, in demselben Satz.
    TAG = _re.compile(r"</?[a-zA-Z]")
    halb = []
    for m in ZUW.finditer(dash):
        rhs = m.group(1)
        if "T('" not in rhs:
            continue
        for lm in LIT.finditer(rhs):
            t = lm.group(1)
            if not TAG.search(t):
                continue
            rest = _re.sub(r"<[^>]*>", "", t).strip()
            if rest and WORT.search(rest):
                halb.append(rest)
    assert not halb, \
        ("Prosa klebt am Markup und bleibt deutsch, waehrend der Rest "
         "derselben Meldung uebersetzt wird: %r" % halb[:4])

    # (4) Kein Eintrag im Katalog, den niemand nachschlaegt. Das prueft
    # tools/i18n_extract.py --check bereits als "verwaist" — hier steht die
    # Gegenrichtung: die Zahl im Katalog muss der Zahl im Quelltext
    # entsprechen, sonst zaehlt sie etwas mit, das nie greift.
    kat = _json.load(open("locales/en.json", encoding="utf-8"))["strings"]
    assert len(kat) >= 970, "Katalog geschrumpft: %d" % len(kat)

    ok("v4.1-W27: verkettete Textknoten uebersetzbar, keine toten Eintraege mehr")



def _test_w28_abdeckung_ist_ehrlich():
    """v4.1-W28: die Abdeckungszahl muss messen, was WIRKLICH im Deck steht.

    Gemeldet wurde "0 fehlend" bei 970 Eintraegen. Gemessen am Dashboard waren
    davon **18 % der Textknoten** erfasst. Der Rest fiel im Extraktor durch die
    Deutsch-Heuristik: "Aufnahmen", "Analysieren", "BEFUNDE", "7-TAGE-TREND"
    haben weder Umlaut noch Funktionswort und sahen deshalb aus wie Bezeichner.
    Die Zahl war nicht falsch berechnet — sie zaehlte nur, was der Extraktor
    eingesammelt hatte, und das war der kleinere Teil.

    Das ist dieselbe Krankheit wie die toten Eintraege aus W21/W23/W27, nur
    umgekehrt: dort zaehlte Erfasstes mit, das nie griff; hier fehlte das
    meiste und wurde nie gezaehlt.
    """
    import html as _html
    import json as _json
    import re as _re

    import tools.i18n_extract as _X  # noqa: F401  (nur fuer _KEIN_TEXT)

    kat = _json.load(open("locales/en.json", encoding="utf-8"))["strings"]
    WORT = _re.compile(r"[A-Za-zÄÖÜäöüß]{3}")

    # (1) Die Abdeckung im Dashboard wird GEMESSEN, nicht behauptet. Alles,
    # was nicht uebersetzt ist, muss ausdruecklich als Eigenname gefuehrt
    # sein oder ein von Inline-Tags zerschnittenes Bruchstueck.
    roh = open("templates/dashboard.html", encoding="utf-8").read()
    ohne = _re.sub(
        r"<script\b.*?</script\b[^>]*>|<style\b.*?</style\b[^>]*>|<!--.*?-->",
        "",
        roh,
        flags=_re.S | _re.I,
    )
    knoten = {" ".join(_html.unescape(t).split())
              for t in _re.findall(r">([^<>]+)<", ohne)
              if t.strip() and WORT.search(t) and len(t.strip()) >= 3}
    drin = {t for t in knoten if t in kat}
    anteil = 100.0 * len(drin) / max(1, len(knoten))
    assert anteil >= 85.0, \
        ("nur %.0f%% der Dashboard-Textknoten sind uebersetzt (%d von %d)"
         % (anteil, len(drin), len(knoten)))

    # (2) Kein Schluessel mit HTML-Entity. Der Browser sieht den DEKODIERTEN
    # Text: aus `BACKUP &amp; EXPORT` wird im DOM "BACKUP & EXPORT". 22 solcher
    # Eintraege waren auf einen Schlag tot, ohne dass es auffiel.
    ent = [k for k in kat if "&amp;" in k or "&nbsp;" in k or "&#" in k]
    assert not ent, "Katalogschluessel mit HTML-Entity — trifft den DOM nie: %r" % ent[:4]

    # (3) Beide Seiten normalisieren mehrzeilige Knoten GLEICH. Faellt eine
    # Seite weg, sind alle Hilfetexte tot: der Quelltext bricht sie um, der
    # Katalog haelt sie mit einfachen Leerzeichen.
    i18n = open("nc/routes/i18n.py", encoding="utf-8").read()
    assert "kern.replace(/\\s+/g, ' ')" in i18n, \
        "der Nachschlag normalisiert mehrzeilige Knoten nicht mehr"
    ext = open("tools/i18n_extract.py", encoding="utf-8").read()
    assert 'raus.add(" ".join(t.split()))' in ext, \
        "der Extraktor normalisiert nicht mehr — die Schluessel haengen wieder an der Einrueckung"
    assert "_html.unescape(t)" in ext, "der Extraktor loest keine Entities mehr auf"

    # (4) Die Ausnahmeliste bleibt eine LISTE, keine Heuristik. Eine Regel wie
    # "alles in Grossbuchstaben ist ein Name" wuerde spaeter still echte
    # Beschriftungen verschlucken.
    assert "_KEIN_TEXT = frozenset({" in ext, "die Ausnahmen sind keine Liste mehr"
    assert len(_X._KEIN_TEXT) < 80, \
        ("die Ausnahmeliste waechst zur Muellhalde: %d Eintraege" % len(_X._KEIN_TEXT))

    ok("v4.1-W28: Dashboard-Abdeckung %.0f%% (vorher 18%%), Katalog %d Eintraege"
       % (anteil, len(kat)))



def _test_w29_kein_sqlite_auf_dem_loop():
    """v4.1-W29: Datenbankarbeit gehoert NEBEN den Event-Loop.

    BEFUND AUS DEM BETRIEBSLOG (2026-09-03): der Waechter meldete Blockaden
    von 30 bis 68 Sekunden. Einer der Stack-Abzuege:

        _handle_single_tracking -> try_acquire_recording_lock
          -> db_conn().__exit__ -> close()

    SQLite blockiert unter Plattenlast. Steht der Aufruf direkt in einer
    async-Funktion, blockiert er nicht die Abfrage, sondern den GANZEN Bot.

    Dieser Vertrag ist eine RATSCHE: die Zahl darf fallen, nie steigen. Eine
    harte Null waere heute unerreichbar (siebzig Stellen im Bestand) und
    deshalb wertlos — sie wuerde sofort abgeschaltet. Eine Obergrenze, die
    bei jeder Welle sinkt, wirkt dagegen.
    """
    import ast as _ast
    import re as _re

    # Der Stand nach W29. Wer eine Stelle loest, SETZT DIESE ZAHL HERUNTER —
    # sonst faellt die naechste Welle wieder zurueck, ohne dass es auffaellt.
    GRENZE = 52

    # ANKER GEWANDERT (v4.2-W15, nicht der Vertrag): 24 dieser Stellen stehen
    # seit der Herausloesung in discordbot.py. Nur bot.py zu zaehlen haette die
    # Ratsche von 52 auf 28 fallen lassen, ohne dass EINE Blockade beseitigt
    # ist — die Grenze haette danach nichts mehr geschuetzt. Gezaehlt wird
    # deshalb ueber beide bot-seitigen Dateien.
    DATEIEN = ("bot.py", "discordbot.py")

    quelle = open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(quelle)

    # Entscheidend ist die UNMITTELBAR umschliessende Funktion, nicht die
    # lexikalische Verschachtelung: ein db_conn() in einem verschachtelten
    # SYNCHRONEN Helfer laeuft ueber asyncio.to_thread und blockiert nicht.
    # Die erste Zaehlung dieser Welle hat das verwechselt und 115 statt 71
    # gemeldet.
    treffer = []

    def lauf(knoten, umgebend):
        for k in _ast.iter_child_nodes(knoten):
            if isinstance(k, (_ast.FunctionDef, _ast.AsyncFunctionDef)):
                lauf(k, k)
            else:
                if (isinstance(k, _ast.With)
                        and isinstance(umgebend, _ast.AsyncFunctionDef)
                        and any(_ast.unparse(i.context_expr).startswith("db_conn(")
                                for i in k.items)):
                    treffer.append((umgebend.name, k.lineno))
                lauf(k, umgebend)

    for _d in DATEIEN:
        lauf(_ast.parse(open(_d, encoding="utf-8").read()), None)
    assert len(treffer) <= GRENZE, \
        ("%d blockierende db_conn-Bloecke in async-Funktionen (erlaubt: %d). "
         "Neue Stelle? db_async(...) benutzen. Erste drei: %r"
         % (len(treffer), GRENZE, treffer[:3]))
    assert len(treffer) >= GRENZE - 15, \
        ("nur noch %d von %d — die Grenze im Vertrag gehoert nachgezogen, "
         "sonst schuetzt sie nicht mehr" % (len(treffer), GRENZE))

    # (2) db_async gibt es, laeuft im Thread und oeffnet die Verbindung DORT.
    # Eine ueber die Thread-Grenze gereichte sqlite3-Verbindung wirft zur
    # Laufzeit (check_same_thread) — deshalb muss der `with` INNEN stehen.
    w = open("nc/dbwrap.py", encoding="utf-8").read()
    assert "async def db_async(" in w, "db_async fehlt"
    assert "asyncio.to_thread(_lauf)" in w, "db_async laeuft nicht im Thread"
    _i = w.index("async def db_async(")
    _rumpf = w[_i:]
    assert _rumpf.index("with db_conn() as conn:") < _rumpf.index("asyncio.to_thread"), \
        "die Verbindung entsteht ausserhalb des Threads — das wirft zur Laufzeit"

    # (3) Das Ereignisprotokoll blockiert nicht mehr. Es hatte ueber dreissig
    # Aufrufer, synchrone wie asynchrone; sie alle auf await umzustellen haette
    # die Zusicherung "aus jedem Pfad ohne Risiko" gebrochen.
    assert "_nc_eventlog.schreibe(" in quelle, \
        "log_event schreibt wieder synchron in die Datenbank"
    import nc.eventlog as E
    assert E.KAPAZITAET > 0, "die Schlange ist unbegrenzt — ein Speicherleck mit Anlauf"
    st = E.stand()
    for feld in ("warteschlange", "kapazitaet", "geschrieben", "verworfen", "fehler"):
        assert feld in st, "die Diagnose verschweigt %s" % feld

    e = open("nc/eventlog.py", encoding="utf-8").read()
    # Verlust MUSS gezaehlt und gemeldet werden. Ein Pruefprotokoll, das still
    # Eintraege verliert, ist schlimmer als keines: die Luecke sieht aus wie Ruhe.
    assert '_ZAEHLER["verworfen"] += 1' in e, "verworfene Eintraege werden nicht gezaehlt"
    assert "_melde_verworfen()" in e, "verworfene Eintraege werden nicht gemeldet"
    # Die Fehler-Drosselung laeuft ueber die ZEIT. Ueber den Zaehler ginge es
    # nicht: der waechst in Buendeln von bis zu 50, ein `% 100 == 1` haette nie
    # ausgeloest und der Schreibfehler waere still geblieben.
    assert "_FEHLER_GEMELDET" in e and 'jetzt - _FEHLER_GEMELDET["ts"] >= 60' in e, \
        "die Fehlermeldung ist nicht zeitgedrosselt — sie loest nie oder dauernd aus"
    # EIN Schreiber: das Protokoll ist eine Chronik, zwei Threads wuerfeln die
    # Reihenfolge durcheinander.
    assert e.count("threading.Thread(target=_schreiber") == 1, "mehr als ein Schreiber"
    assert '_LAEUFT = {"an": False}' in e, "der Waechter ist kein Modul-Global"

    # (4) KEIN Dauerlaeufer blockiert mehr. Die sind die schlimmsten: sie
    # wiederholen sich fuer immer, also trifft ihre Blockade frueher oder
    # spaeter jeden Betriebszustand.
    laeufer = sorted({n for n, _ in treffer if n.endswith("_loop")})
    assert not laeufer, "Dauerlaeufer blockieren wieder den Loop: %r" % laeufer

    # (5) Keine offene Transaktion ueber ein `await` hinweg. Das blockiert den
    # Loop NICHT (das await gibt ihn frei) — es haelt aber die Verbindung und
    # damit den Schreib-Lock offen, waehrend auf das Netz gewartet wird. Jeder
    # andere Schreiber bekommt in der Zeit "database is locked", und die
    # Ursache steht in einer Schleife, die nur jede Minute laeuft.
    # _community_events_loop hatte genau das (v4.1-W29).
    for _f in _ast.walk(baum):
        if not isinstance(_f, (_ast.FunctionDef, _ast.AsyncFunctionDef)):
            continue
        for _w in _ast.walk(_f):
            if not (isinstance(_w, _ast.With) and any(
                    _ast.unparse(i.context_expr).startswith("db_conn(") for i in _w.items)):
                continue
            for _k in _ast.walk(_w):
                assert not isinstance(_k, (_ast.Await, _ast.AsyncFor)), \
                    ("%s: await innerhalb eines offenen db_conn()-Blocks (Zeile %d) — "
                     "haelt den Schreib-Lock ueber das Warten hinweg"
                     % (_f.name, _w.lineno))

    # (6) Der Sendebild-Chat laeuft ueber EINEN Arbeiter. Das ist keine
    # Feinheit: der Chat ist eine Abfolge. Mit mehreren Arbeitern wuerfelt
    # der Thread-Pool die Reihenfolge durcheinander — nachgemessen, mit acht
    # Arbeitern kommen 200 Nachrichten NICHT in der Einreichungsreihenfolge
    # an. Eine vertauschte Chat-Nachricht ist kein akzeptabler Preis fuer
    # Nebenlaeufigkeit.
    assert "_CHAT_PUSH_EXEC = _cf_thread.ThreadPoolExecutor(max_workers=1" in quelle, \
        "der Chat-Push laeuft nicht mehr ueber genau EINEN Arbeiter"
    assert "async def _restream_chat_push_async(" in quelle, "die nebenlaeufige Huelle fehlt"
    # Und alle Aufrufer benutzen sie wirklich. Ein vergessener Aufruf schriebe
    # weiter synchron und faellt sonst niemandem auf.
    roh_aufrufe = len(_re.findall(r"(?<!await )(?<!def )\b_restream_chat_push\(", quelle))
    assert roh_aufrufe <= 1, \
        ("%d Aufrufe von _restream_chat_push ohne die nebenlaeufige Huelle "
         "(erlaubt ist nur der eine INNERHALB der Huelle)" % roh_aufrufe)

    ok("v4.1-W29: %d blockierende Stellen (Grenze %d), kein Dauerlaeufer, "
       "keine Transaktion ueber ein await, Chat-Reihenfolge gesichert"
       % (len(treffer), GRENZE))



def _test_w30_fehlertext_und_offenes_deck():
    """v4.1-W30: was nach aussen geht, und ob das Deck ueberhaupt zu ist."""
    import ast as _ast
    import glob as _glob
    import os as _os

    import nc.dashauth as D
    import nc.fehlertext as F

    # (1) KEIN roher Ausnahmetext mehr in einer Antwort. Die Schranke des
    # Decks macht gar nichts, wenn weder Token noch PIN gesetzt ist — dann
    # geht jede dieser Meldungen an jeden, der den Port erreicht, mitsamt
    # Dateipfaden und gelegentlich dem Wortlaut einer fremden API-Antwort.
    # v4.2-W3: nach AST statt nach der Zeichenkette "str(e)". Die Textsuche
    # sah nur den Namen `e` — ein `except Exception as ex:` mit `str(ex)`
    # blieb unsichtbar und stand genau so in nc/routes/brain.py. Gefunden hat
    # ihn erst das lokal installierte CodeQL.
    def _roher_str_aufruf(pfad):
        baum = _ast.parse(open(pfad, encoding="utf-8").read())
        raus = []
        for k in _ast.walk(baum):
            if not isinstance(k, _ast.ExceptHandler) or not k.name:
                continue
            for j in _ast.walk(k):
                if (isinstance(j, _ast.Call)
                        and isinstance(j.func, _ast.Name) and j.func.id == "str"
                        and len(j.args) == 1
                        and isinstance(j.args[0], _ast.Name)
                        and j.args[0].id == k.name):
                    raus.append((pfad, j.lineno))
        return raus

    offen = []
    for p in sorted(_glob.glob("nc/routes/*.py")):
        offen += _roher_str_aufruf(p)
    assert not offen, (
        "roher Ausnahmetext in einem Blueprint — str(<ausnahme>) ohne "
        "Saeuberung: %r" % (offen[:8],))

    # v4.2-W3: DIE LUECKE, DIE W30 GELASSEN HAT. Der Vertrag oben verbietet
    # `str(e)` — aber `f"JSON nicht lesbar: {e}"` ist genau derselbe Leck-Weg
    # und stand danach noch an 22 Stellen. Ein lokal installiertes CodeQL hat
    # sie gefunden (py/stack-trace-exposure); die Textsuche nach "str(e)"
    # konnte das nie sehen.
    #
    # Geprueft wird jetzt die FORM, nicht die Zeichenkette: in einem
    # `except … as e` darf `{e}` in keinem f-string stehen, ausser der Name
    # laeuft durch _fehler_text. Nach AST, weil ein f-string beliebig
    # verschachtelt sein kann und ein Regex daran zerbricht.
    # NUR Antwort-Bauer, nicht das Log. Im Log ist der volle Wortlaut richtig
    # — nach_aussen() schreibt ihn selbst dorthin. Ein Vertrag, der auch
    # log.warning(f"... {e}") meldet, waere ein Dauer-Fehlalarm und flöge
    # nach der dritten Welle raus.
    ANTWORT = {"jsonify", "Response", "make_response", "abort", "_oauth_page"}

    def _rohe_ausnahme_in_fstring(pfad):
        baum = _ast.parse(open(pfad, encoding="utf-8").read())
        raus = []
        for k in _ast.walk(baum):
            if not isinstance(k, _ast.ExceptHandler) or not k.name:
                continue
            for aufruf in _ast.walk(k):
                if not (isinstance(aufruf, _ast.Call)
                        and _ast.unparse(aufruf.func).split(".")[-1] in ANTWORT):
                    continue
                for j in _ast.walk(aufruf):
                    if not isinstance(j, _ast.JoinedStr):
                        continue
                    for teil in j.values:
                        # Bare `{e}` — ein Aufruf drumherum (also
                        # _fehler_text(e)) ist genau das, was hier verlangt
                        # wird, und faellt deshalb nicht auf.
                        if (isinstance(teil, _ast.FormattedValue)
                                and isinstance(teil.value, _ast.Name)
                                and teil.value.id == k.name):
                            raus.append((pfad, j.lineno))
        return raus

    roh_fstring = []
    for p in sorted(_glob.glob("nc/routes/*.py")) + ["bot.py"]:
        roh_fstring += _rohe_ausnahme_in_fstring(p)
    assert not roh_fstring, (
        "roher Ausnahmetext in einem f-string — dasselbe Leck wie str(e), "
        "nur anders geschrieben. Durch _fehler_text(e, \"<funktion>\") "
        "ersetzen: %r" % (roh_fstring[:8],))

    # Und in bot.py wenigstens nicht mehr in einer HTTP-Antwort.
    b = open("bot.py", encoding="utf-8").read()
    for k in _ast.walk(_ast.parse(b)):
        if isinstance(k, _ast.Call) and isinstance(k.func, _ast.Name) \
           and k.func.id == "jsonify":
            for kw in k.keywords:
                assert not _ast.unparse(kw.value).startswith("str(e)"), \
                    ("roher Ausnahmetext in einer jsonify-Antwort, Zeile %d"
                     % kw.value.lineno)

    # (2) Der Saeuberer nimmt raus, was verraeterisch ist, und laesst stehen,
    # was der Betreiber braucht. "Interner Fehler" waere in einem
    # Ein-Personen-Betrieb keine Sicherheit, sondern eine Sackgasse.
    assert F.saeubern("database is locked") == "database is locked"
    assert "/home/" not in F.saeubern(
        "[Errno 2] No such file: '/home/ubuntu/tiktok-bot/recordings/x.mp4'")
    assert "abc123def456" not in F.saeubern('HTTP 401: token=abc123def456')
    assert "46zAbCdEfGhIjKlMnOpQrStUvWxYz012345" not in F.saeubern(
        "rtmp://ingest/app/46zAbCdEfGhIjKlMnOpQrStUvWxYz012345 refused")
    assert len(F.saeubern("x" * 4000)) <= F.MAX
    # Der Typ bleibt: "OperationalError" sagt Datenbank, "TimeoutError" sagt
    # Netz — und verraet nichts ueber den Bestand.
    assert F.nach_aussen(ValueError("kaputt"), "test").startswith("ValueError")

    # (3) Die Lage-Erkennung benutzt DIESELBE Bedingung wie die Schranke:
    # ein Token ODER ein PIN reicht. Frueher fragte die Warnung nur nach dem
    # Token und schlug bei einem PIN-geschuetzten Deck faelschlich an — ein
    # Fehlalarm erzieht dazu, die Meldung zu ueberlesen.
    #
    # v4.2-W84 HAT DIESE TABELLE GEAENDERT, und zwar in der Sache, nicht am
    # Anker. Die Zeile "0.0.0.0 ohne Token und ohne PIN" stand hier auf True.
    # Seit W84 faellt die Bindung in genau diesem Fall auf Loopback zurueck
    # (nc/webserver.bindung) — dann ist NICHTS offen, und ein "offen"-Befund
    # waere der Fehlalarm, vor dem der Kopf von nc/dashauth.py warnt. Offen
    # ist das Deck nur noch, wenn DASHBOARD_OFFEN_ERLAUBEN=1 es offen HAELT.
    sicher = {k: _os.environ.get(k) for k in ("WEB_HOST", "DASHBOARD_TOKEN",
                                              "DASHBOARD_PIN",
                                              "DASHBOARD_OFFEN_ERLAUBEN")}
    try:
        for env, erwartet in (
                ({"WEB_HOST": "127.0.0.1", "DASHBOARD_TOKEN": "", "DASHBOARD_PIN": "",
                  "DASHBOARD_OFFEN_ERLAUBEN": ""}, False),
                # ohne Schalter: Rueckfall auf Loopback, also nicht offen
                ({"WEB_HOST": "0.0.0.0", "DASHBOARD_TOKEN": "", "DASHBOARD_PIN": "",
                  "DASHBOARD_OFFEN_ERLAUBEN": ""}, False),
                # mit Schalter: wirklich offen, und das muss gemeldet werden
                ({"WEB_HOST": "0.0.0.0", "DASHBOARD_TOKEN": "", "DASHBOARD_PIN": "",
                  "DASHBOARD_OFFEN_ERLAUBEN": "1"}, True),
                ({"WEB_HOST": "0.0.0.0", "DASHBOARD_TOKEN": "", "DASHBOARD_PIN": "1234",
                  "DASHBOARD_OFFEN_ERLAUBEN": "1"}, False),
                ({"WEB_HOST": "0.0.0.0", "DASHBOARD_TOKEN": "geheim", "DASHBOARD_PIN": "",
                  "DASHBOARD_OFFEN_ERLAUBEN": "1"}, False)):
            _os.environ.update(env)
            assert D.offen_im_netz() is erwartet, env
    finally:
        for k, v in sicher.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v

    # (4) Die Meldung laeuft auf ERROR und WIEDERHOLT sich. Ein log.warning
    # erscheint in einem ERROR-Log nie (CLAUDE.md), und eine Meldung nur beim
    # Start sieht niemand: der Betreiber liest das Log, wenn etwas kaputt ist,
    # nicht beim Hochfahren. Der gefaehrliche Zustand ist ein Dauerzustand.
    assert "_nc_dashauth.lage()" in b, "die Lage wird nicht mehr abgefragt"
    assert "async def _sicherheits_erinnerung_loop" in b, "die Erinnerung fehlt"
    assert '_spawn(_sicherheits_erinnerung_loop(), name="sec-reminder")' in b, \
        "die Erinnerung wird nie gestartet"
    _i = b.index("async def _sicherheits_erinnerung_loop")
    _seg = b[_i:_i + 1400]
    assert "log.error(" in _seg, "die Erinnerung laeuft nicht auf ERROR"
    assert "log.warning(" not in _seg, \
        "die Erinnerung faellt auf warning zurueck — im ERROR-Log unsichtbar"

    ok("v4.1-W30: kein roher Ausnahmetext nach aussen, offenes Deck meldet sich wiederholt")


def _test_w31_rauchtest_laeuft_in_der_ci():
    """v4.1-W31: der Rauchtest laeuft automatisch — und bleibt lauffaehig."""
    import ast as _ast
    import pathlib as _pl
    import sys as _sys

    ci = open(".github/workflows/ci.yml", encoding="utf-8").read()

    # (1) Er laeuft ueberhaupt. Bis W31 stand in der Pflicht-Pruefkette ein
    # Test, den KEINE Maschine je ausfuehrte: auf der Autorenmaschine fehlt
    # der Laufzeitstack, in der CI war er ausgeschlossen, und auf dem Server
    # lief er nur, wenn jemand daran dachte. Genau die Fehler, die er faengt
    # (NameError auf der Modul-Ebene, 500er beim ersten Aufruf), haben in W26
    # und W29 in Produktion zugeschlagen.
    assert "python test_smoke.py" in ci, \
        "test_smoke.py laeuft in der CI nicht mehr — der Job wurde entfernt"
    assert "requirements-smoke.txt" in ci, \
        "der Rauchtest-Job installiert nicht mehr aus requirements-smoke.txt"
    _i = ci.index("python test_smoke.py")
    assert 'PYTHONUTF8: "1"' in ci[max(0, _i - 400):_i], \
        ("test_smoke.py laeuft ohne PYTHONUTF8=1 — es oeffnet bot.py ohne "
         "encoding=, das stirbt ausserhalb einer UTF-8-Umgebung mit "
         "UnicodeDecodeError statt zu pruefen")

    # (2) Und er BLEIBT lauffaehig. Ein neuer Import auf der Modul-Ebene, der
    # in requirements-smoke.txt fehlt, wuerde den Job mit einem nackten
    # ImportError toeten — mitten in der Liste, ohne Hinweis worauf. Dieser
    # Vergleich meldet das hier, mit Datei und Paketname.
    quelle = open("requirements-smoke.txt", encoding="utf-8").read()

    def _nur_name(zeile):
        """'Flask >= 2.2  # Kommentar' -> 'flask'.

        v4.2-W68: vorher stand hier `z.split("#")[0].strip().lower()`, also
        die ganze Zeile MIT Fassungsangabe. Solange keine Zeile ein `>=`
        trug, war das dasselbe — seit W68 tragen alle eines, und der
        Vergleich unten fand kein einziges Paket mehr wieder. 43 Fehlalarme
        auf einen Schlag, und kein Wort davon stimmte.
        """
        name = zeile.split("#")[0].strip().split(";")[0]
        for trenn in (">=", "==", "<=", "~=", "!=", ">", "<"):
            name = name.split(trenn)[0]
        return name.strip().lower()

    gelistet = {_nur_name(z) for z in quelle.splitlines() if _nur_name(z)}

    # Importname -> pip-Name. Nur was sich unterscheidet steht hier drin.
    PIPNAME = {"dotenv": "python-dotenv", "discord": "discord.py",
               "socks": "PySocks", "pymysql": "PyMySQL",
               "telegram": "python-telegram-bot", "faster_whisper": "faster-whisper"}
    # Diese stubbt test_smoke.py selbst — sie duerfen fehlen.
    GESTUBBT = {"TikTokLive", "telegram"}
    LOKAL = {"nc", "brain", "bot", "brain_bridge", "tools"}

    def _fremd_auf_modulebene(pfad):
        """Importe der Modul-Ebene, getrennt nach 'muss da sein' und 'optional'.

        Optional heisst: in einem try mit except ImportError. Solche Pakete
        darf der Rauchtest nicht haben — der Code faengt ihr Fehlen ab.
        """
        baum = _ast.parse(_pl.Path(pfad).read_text(encoding="utf-8"))
        pflicht, optional = set(), set()

        def _namen(knoten):
            if isinstance(knoten, _ast.Import):
                return [a.name.split(".")[0] for a in knoten.names]
            if isinstance(knoten, _ast.ImportFrom) and knoten.level == 0 and knoten.module:
                return [knoten.module.split(".")[0]]
            return []

        def _lauf(koerper, weich):
            for k in koerper:
                for n in _namen(k):
                    if n in _sys.stdlib_module_names or n in LOKAL:
                        continue
                    (optional if weich else pflicht).add(n)
                if isinstance(k, _ast.Try):
                    # Ein Handler, der ImportError faengt, macht den Import
                    # optional. `except Exception` und das nackte `except:`
                    # fangen ihn mit — deshalb zaehlen die hier auch.
                    faengt_import = False
                    for h in k.handlers:
                        art = "" if h.type is None else _ast.unparse(h.type)
                        if h.type is None or any(
                                w in art for w in ("ImportError", "ModuleNotFoundError",
                                                   "Exception", "BaseException")):
                            faengt_import = True
                    _lauf(k.body, weich or faengt_import)
                    for h in k.handlers:
                        _lauf(h.body, True)
                    _lauf(k.orelse, weich or faengt_import)
                    _lauf(k.finalbody, weich)
                elif isinstance(k, _ast.If):
                    _lauf(k.body, weich)
                    _lauf(k.orelse, weich)
        _lauf(baum.body, False)
        return pflicht, optional - pflicht

    dateien = ["bot.py"] + [str(p) for p in sorted(_pl.Path(".").glob("nc/**/*.py"))
                            if "_vendor" not in str(p)] \
                        + [str(p) for p in sorted(_pl.Path(".").glob("brain/**/*.py"))]
    fehlt = []
    for d in dateien:
        pflicht, _ = _fremd_auf_modulebene(d)
        for n in pflicht:
            if n in GESTUBBT:
                continue
            if PIPNAME.get(n, n).lower() not in gelistet:
                fehlt.append((d, n, PIPNAME.get(n, n)))
    assert not fehlt, (
        "Import auf der Modul-Ebene ohne Eintrag in requirements-smoke.txt — "
        "der Rauchtest stirbt damit in der CI an einem ImportError. "
        "Eintragen oder in eine Funktion verschieben: %r" % (fehlt,))

    # (3) Umgekehrt: kein toter Eintrag. Eine Liste, die mehr enthaelt als
    # noetig, waechst still weiter und macht den Job wieder teuer — genau der
    # Grund, warum requirements.txt hier nicht taugt.
    # Optionale Importe zaehlen hier MIT. discord ist der Fall, um den es
    # geht: bot.py faengt sein Fehlen ab (`except Exception: discord = None`),
    # der Rauchtest liefe also auch ohne das Paket gruen — und wuerde dabei
    # die gesamte Slash-Command-Registrierung ueberspringen. Genau dort sass
    # B79. Ein optionales Paket gehoert deshalb in die Liste, wenn ohne es
    # ein Stueck bot.py ungeprueft bleibt.
    gebraucht = set()
    for d in dateien:
        pflicht, optional = _fremd_auf_modulebene(d)
        for n in pflicht | optional:
            if n not in GESTUBBT:
                gebraucht.add(PIPNAME.get(n, n).lower())
    tot = gelistet - gebraucht
    assert not tot, (
        "requirements-smoke.txt listet Pakete, die keine Modul-Ebene mehr "
        "braucht: %r — raus damit, sonst wird der Job wieder teuer" % sorted(tot))

    ok("v4.1-W31: der Rauchtest laeuft in der CI, %d Datei(en) gegen "
       "requirements-smoke.txt geprueft" % len(dateien))

def _test_w32_sondenschicht_und_systemlage():
    """v4.1-W32: die Sonden liegen in nc/, drei System-Routen sind draussen."""
    import ast as _ast

    import nc.cookies as C
    import nc.logsafe as L
    import nc.systemprobe as P

    b = open("bot.py", encoding="utf-8").read()

    # (1) Die drei Routen sind WEG aus dem Monolithen und im Blueprint.
    # Ein Blueprint, den niemand registriert, ist ein 404 mit Rueckendeckung —
    # deshalb beides pruefen, nicht nur die Datei.
    for name in ("api_system", "api_system_preflight_history", "api_config_drift"):
        assert ("\ndef %s(" % name) not in b, \
            "%s steht noch in bot.py — doppelte Route oder toter Code" % name
    s = open("nc/routes/systemlage.py", encoding="utf-8").read()
    for pfad in ("/api/system", "/api/system/preflight_history",
                 "/api/system/config_drift"):
        assert '"%s"' % pfad in s, "%s fehlt im Blueprint" % pfad
    assert "register_blueprint(_nc_routes_systemlage.bp)" in b, \
        "der Blueprint ist nicht registriert — die drei Routen waeren 404"

    # (2) Der Drift-Bericht liest den QUELLTEXT von bot.py. Im Monolithen stand
    # dafuer __file__. In einem Blueprint zeigt __file__ auf DIESE Datei, und
    # nc/confdrift faende dort keine einzige os.getenv-Vorgabe: die Antwort
    # waere ein leerer Bericht mit ok=true. Genau die stille Fehlanzeige, vor
    # der CLAUDE.md warnt — deshalb ein Vertrag und kein Kommentar.
    # Nach AST, nicht nach Text: der Kommentar daneben ERKLAERT die Falle und
    # nennt __file__ dabei. Eine Textsuche haette den eigenen Warnhinweis als
    # Verstoss gemeldet — ein Vertrag, der auf seine Begruendung anschlaegt,
    # wird beim naechsten Mal geloescht statt gelesen.
    for _k in _ast.walk(_ast.parse(s)):
        if isinstance(_k, _ast.Name) and _k.id == "__file__":
            raise AssertionError(
                "nc/routes/systemlage.py benutzt __file__, Zeile %d — in einem "
                "Blueprint zeigt das auf die falsche Datei und ergibt eine "
                "leere Drift-Liste mit ok=true" % _k.lineno)
    assert 'cfg["BOT_DATEI"]' in s, "der Pfad von bot.py kommt nicht mehr aus cfg"
    assert '"BOT_DATEI": __file__' in b, "bot.py reicht seinen Pfad nicht mehr durch"

    # (3) Keine Modul-Konstante aus der Umgebung. CLAUDE.md: ".env wird teils
    # erst nach den ersten Imports geladen" — ein os.getenv auf Modul-Ebene
    # haette hier die leere Vorgabe fuer immer eingefroren.
    for datei in ("nc/systemprobe.py", "nc/cookies.py"):
        baum = _ast.parse(open(datei, encoding="utf-8").read())
        for k in baum.body:
            for x in _ast.walk(k):
                if isinstance(x, _ast.Call) and _ast.unparse(x.func).endswith("getenv"):
                    raise AssertionError(
                        "%s liest os.getenv auf Modul-Ebene, Zeile %d — "
                        "Konfiguration gehoert in configure()" % (datei, x.lineno))
        assert "def configure(" in open(datei, encoding="utf-8").read(), \
            "%s hat kein configure()" % datei

    # (4) Die Sonden-Auswahl. `which` ist Parameter, damit der Vertrag sie
    # pruefen kann, ohne ffmpeg zu installieren.
    def _da(*was):
        return lambda x: ("/usr/bin/" + x) if x in was else None
    P.configure(recorder_pref="auto")
    assert P.active_recorder(which=_da("ffmpeg", "yt-dlp")) == "native"
    assert P.active_recorder(which=_da("yt-dlp")) == "ytdlp"
    assert P.active_recorder(which=_da()) is None
    P.configure(recorder_pref="ytdlp")
    assert P.active_recorder(which=_da("ffmpeg")) is None, \
        "pref=ytdlp darf NICHT auf native zurueckfallen — sonst nimmt der " \
        "Recorder still einen anderen Weg als eingestellt"
    assert P.active_recorder(which=_da("yt-dlp")) == "ytdlp"
    P.configure(recorder_pref="native")
    assert P.active_recorder(which=_da("yt-dlp")) is None
    P.configure(recorder_pref="auto")

    # (5) Der Deckel haelt AUCH ein negatives Ergebnis fest. Sonst laeuft jede
    # Sonde bei totem Redis in einen 1-2-Sekunden-Timeout, und zwar bei jedem
    # Aufruf — das Dashboard pollt im Sekundentakt.
    P.cache_leeren()
    zaehler = {"n": 0}

    def _teuer():
        zaehler["n"] += 1
        return False
    for _ in range(5):
        assert P.cached_probe("test", _teuer) is False
    assert zaehler["n"] == 1, \
        "cached_probe wiederholt eine fehlgeschlagene Sonde (%d Aufrufe)" % zaehler["n"]
    P.cache_leeren()

    # (6) Zugangsdaten raus, Ziel drin. Die Antwort landet im Browser-Cache,
    # in Screenshots und in jedem Support-Log (v4.0-W118).
    assert L.url_ohne_zugang("redis://:geheim@host:6379/0") == \
        "redis://<geheim>@host:6379/0"
    assert L.url_ohne_zugang("redis://nutzer:geheim@host:6379/0") == \
        "redis://nutzer:<geheim>@host:6379/0"
    assert L.url_ohne_zugang("redis://localhost:6379/0") == "redis://localhost:6379/0"
    assert L.url_ohne_zugang(None) == ""

    # (7) EIN Cookie-Cache, nicht zwei. Der Bot leert ihn nach einer
    # Reparatur, das Deck liest ihn ueber ctx.cfg — eine Kopie waere ein
    # totes Panel und ein Cache, den niemand mehr invalidiert.
    assert C.CACHE is C._COOKIES_CACHE, \
        ("nc.cookies.CACHE ist eine Kopie — der Bot leert dann einen "
         "anderen Cache als den, den load_dict liest")
    assert "_COOKIES_CACHE = _nc_cookies_datei.CACHE" in b, \
        "bot.py haelt einen eigenen Cookie-Cache — zwei Wahrheiten ueber eine Datei"
    assert "_load_cookies_dict = _nc_cookies_datei.load_dict" in b, \
        "der Cookie-Leser ist kein Alias mehr — ein Wrapper waere eine zweite Signatur"

    # (8) Die Kollisionsaufloesung ist ein Bugfix, dessen Symptom niemand ein
    # zweites Mal suchen will: Deck meldet "Cookies aktuell", TikTok liefert
    # trotzdem 403, weil der gesendete sessionid-Wert aus der falschen
    # Domain-Variante stammt. Spezifischere Domain gewinnt, bei Gleichstand
    # die laengere Expiry.
    import os as _os
    d = _ph.verzeichnis()
    pfad = _os.path.join(d, "c.txt")
    with open(pfad, "w", encoding="utf-8") as f:
        f.write("# Netscape HTTP Cookie File\n")
        f.write("\t".join([".tiktok.com", "TRUE", "/", "FALSE", "9999999999",
                           "sessionid", "ALT"]) + "\n")
        f.write("\t".join(["www.tiktok.com", "FALSE", "/", "FALSE", "1111111111",
                           "sessionid", "GENAU"]) + "\n")

    class _Still:
        def __getattr__(self, n):
            return lambda *a, **k: None
    C.configure(datei=pfad, log=_Still())
    C.CACHE.pop("v", None)
    got = C.load_dict()
    assert got.get("sessionid") == "GENAU", \
        ("Domain-Kollision falsch aufgeloest: %r — die exakte Domain muss "
         "gewinnen, sonst sendet der Bot einen veralteten sessionid" % got)
    C.CACHE.pop("v", None)

    ok("v4.1-W32: Sondenschicht in nc/, 3 System-Routen im Blueprint, "
       "ein Cookie-Cache")

def _test_w33_sammelentscheid_und_ein_stempel():
    """v4.2: Vorschläge gesammelt entscheiden, und EIN Build-Stempel."""
    import ast as _ast
    import json as _json
    import re as _re

    from nc import version as V

    dash = open("templates/dashboard.html", encoding="utf-8").read()
    evo = open("nc/routes/evolution.py", encoding="utf-8").read()

    # ── (1) Die beiden Knoepfe und ihre Route ───────────────────────────────
    assert 'onclick="evoBulk(true)"' in dash and 'onclick="evoBulk(false)"' in dash, \
        "die Sammelknoepfe fehlen im Deck"
    assert '"/api/evolution/proposals/bulk"' in evo, "keine Sammel-Route"
    assert "def evoBulk(" not in dash and "async function evoBulk(" in dash, \
        "evoBulk ist nicht als Funktion verdrahtet"

    # ── (2) Sie fassen NUR offene Vorschlaege an. Ein bereits uebernommener
    # Vorschlag darf durch einen spaeteren Klick auf "alles verwerfen" nicht
    # rueckwirkend zu "verworfen" werden — das waere eine Umschreibung der
    # Entscheidungshistorie, nicht eine Massenaktion.
    _i = evo.index("def api_evolution_bulk(")
    _rumpf = evo[_i:evo.index("@bp.route", _i)]
    assert "WHERE status='proposed'" in _rumpf, \
        ("die Sammelaktion filtert nicht auf offene Vorschlaege — sie wuerde "
         "bereits getroffene Entscheidungen ueberschreiben")
    assert "rowcount" in _rumpf, \
        "die Route meldet nicht, wie viele sie angefasst hat"

    # ── (3) Eine Anweisung, nicht N. Bei zwanzig offenen Vorschlaegen waeren
    # zwanzig POSTs zwanzig Transaktionen; bricht einer ab, bleibt die Liste
    # halb bearbeitet zurueck, ohne dass jemand sagen kann welche Haelfte.
    assert _rumpf.count("UPDATE evolution_proposals") == 1, \
        "die Sammelaktion laeuft nicht in EINER Anweisung"
    _bulkjs = dash[dash.index("async function evoBulk("):]
    _bulkjs = _bulkjs[:_bulkjs.index("\n}")]
    assert "for(" not in _bulkjs and "forEach" not in _bulkjs, \
        "das Deck schleift ueber die Vorschlaege statt die Sammel-Route zu rufen"

    # ── (4) Rueckfrage vor dem Verwerfen, und sie nennt die Zahl. Eine Frage
    # ohne Zahl beantwortet man anders als eine, die 17 nennt.
    assert "confirm(" in _bulkjs, "verwirft ohne Rueckfrage"
    assert "offen+' '+T(" in _bulkjs, "die Rueckfrage nennt die Zahl nicht"
    # T() um den Text, nicht um das Ergebnis: ein nativer Dialog laeuft nie
    # durch die DOM-Uebersetzung (CLAUDE.md, W21).
    for stueck in ("T('Vorschläge verwerfen?')",
                   "T('Vorschläge als angewendet markieren?')"):
        assert stueck in _bulkjs, "Dialogtext nicht an der Quelle uebersetzt: %s" % stueck

    # ── (5) Knoepfe nur, wenn es etwas zu sammeln gibt. Ein Knopf, der auf
    # eine leere Liste wirkt, tut nichts und sieht wie ein Fehler aus.
    assert 'id="evo_bulk"' in dash and "bulk.hidden = !ps.length" in dash, \
        "die Sammelknoepfe werden bei leerer Liste nicht ausgeblendet"

    # ── (6) EIN Build-Stempel. Er stand woertlich in bot.py, in
    # nc/routes/brain.py und zweimal im Footer — vier Kopien einer Zahl, von
    # denen keine mitwanderte, wenn nc/version.py hochgezaehlt wurde. Genau
    # deshalb zeigte das Deck im September noch August an.
    assert V.build_stamp() == "%s · v%s" % (V.RELEASE, V.VERSION)
    # Nach AST, nicht nach Regex: ein Ausdruck als Vorgabe enthaelt selbst
    # Klammern, an denen jedes "bis zur naechsten )"-Muster falsch abschneidet.
    for datei in ("bot.py", "nc/routes/brain.py"):
        for k in _ast.walk(_ast.parse(open(datei, encoding="utf-8").read())):
            if not (isinstance(k, _ast.Call)
                    and _ast.unparse(k.func).endswith("getenv")
                    and k.args and isinstance(k.args[0], _ast.Constant)
                    and k.args[0].value == "BUILD_STAMP"):
                continue
            assert len(k.args) >= 2, "%s: BUILD_STAMP ohne Vorgabe" % datei
            vorgabe = _ast.unparse(k.args[1])
            assert vorgabe.endswith("build_stamp()"), \
                ("%s haelt eine eigene Vorgabe fuer BUILD_STAMP (%s), Zeile %d — "
                 "beim naechsten Hochzaehlen laeuft sie auseinander"
                 % (datei, vorgabe, k.lineno))
    # Ohne Kommentare zaehlen: die Wellen-Marken ("v4.2: …") und das Beispiel
    # im Kommentar daneben sind keine Anzeige. Ein Vertrag, der auf seine
    # eigene Begruendung anschlaegt, wird beim naechsten Mal geloescht statt
    # gelesen — dieselbe Falle wie beim __file__-Vertrag in W32.
    _nackt = _re.sub(r"<!--.*?-->", "", dash, flags=_re.S)
    _nackt = _re.sub(r"/\*.*?\*/", "", _nackt, flags=_re.S)
    _nackt = _re.sub(r"(?m)^\s*//.*$", "", _nackt)
    for zahl in (V.RELEASE, "v" + V.VERSION):
        assert _nackt.count(zahl) <= 1, \
            ("%r steht %dx fest im Deck — der Footer soll die Version HOLEN, "
             "nicht behaupten" % (zahl, _nackt.count(zahl)))

    # ── (7) Und die Route liefert ihn wirklich. Sie las ihn ueber globals()
    # aus einem Blueprint-Namensraum, in dem er nie stand: /api/version gab
    # seit W26 still build="" zurueck, und niemand sah es, weil der Footer
    # ohnehin fest verdrahtet war.
    ausk = open("nc/routes/auskunft.py", encoding="utf-8").read()
    _a = ausk.index("def api_version(")
    _r = ausk[_a:ausk.index("@bp.route", _a)]
    for k in _ast.walk(_ast.parse("def f():\n" + "\n".join(
            " " + z for z in _r.splitlines()[1:]))):
        if isinstance(k, _ast.Call) and _ast.unparse(k.func) == "globals":
            raise AssertionError(
                "api_version liest wieder ueber globals() — im Blueprint ist "
                "das der falsche Namensraum, die Antwort waere still leer")
    assert 'cfg.get("BUILD_STAMP")' in _r, "der Stempel kommt nicht aus ctx.cfg"
    assert "loadFooterVersion()" in dash, "der Footer holt die Version nicht"

    # ── (8) Der Katalog kennt die neuen Texte. Ein fehlender Eintrag faellt
    # auf Deutsch zurueck — die Knoepfe blieben im englischen Deck deutsch.
    kat = _json.load(open("locales/en.json", encoding="utf-8"))["strings"]
    for s in ("✓ alles übernehmen", "alles verwerfen", "Vorschläge verwerfen?",
              "Vorschläge als angewendet markieren?"):
        assert s in kat, "Katalogeintrag fehlt: %r" % s

    ok("v4.2: Vorschlaege gesammelt entscheiden, ein Build-Stempel, "
       "Footer holt die Version")

def _test_v42_w1_schnappschuss_ohne_geheimnis():
    """v4.2-W1: config_snapshot und check_timing raus — ohne Geheimnisse."""
    import ast as _ast

    import nc.discordlimits as D
    import nc.whispercfg as W

    b = open("bot.py", encoding="utf-8").read()
    s = open("nc/routes/systemlage.py", encoding="utf-8").read()

    # ── (1) Die Routen sind weg aus dem Monolithen und im Blueprint ─────────
    for name in ("api_system_config_snapshot", "api_check_timing"):
        assert ("\ndef %s(" % name) not in b, "%s steht noch in bot.py" % name
        assert "def %s(" % name in s, "%s fehlt im Blueprint" % name
    for pfad in ("/api/system/config_snapshot", "/api/system/check_timing"):
        assert '"%s"' % pfad in s, "%s fehlt" % pfad

    # ── (2) KEIN GEHEIMNIS IM KONTEXT. Der Schnappschuss beantwortet nur, OB
    # etwas gesetzt ist. Den Wert dafuer durch den Kontext zu reichen, damit
    # ein Blueprint ihn zu True verrechnet, waere groessere Angriffsflaeche
    # fuer null Gewinn — dieselbe Ueberlegung wie bei s3_zugang() in W24.
    # Die .env traegt rund 500 Variablen mit Cookies, OAuth-Token und
    # Stream-Schluesseln; jede davon, die unnoetig wandert, ist ein Risiko.
    GEHEIM = ("DASHBOARD_TOKEN", "DASHBOARD_PIN", "DISCORD_BOT_TOKEN",
              "KICK_CLIENT_SECRET", "TWITCH_STREAM_KEY", "YOUTUBE_STREAM_KEY",
              "KICK_STREAM_KEY", "KICK_STREAM_KEY_BACKUP")
    _cfg = None
    for k in _ast.walk(_ast.parse(b)):
        if (isinstance(k, _ast.Call) and _ast.unparse(k.func).endswith("ctx.configure")):
            for kw in k.keywords:
                if kw.arg == "cfg":
                    _cfg = kw.value
    assert _cfg is not None, "nc.ctx.configure(cfg=…) nicht gefunden"
    for schluessel, wert in zip(_cfg.keys, _cfg.values):
        roh = _ast.unparse(wert)
        for g in GEHEIM:
            # bool(X) und "a and b"-Verrechnungen sind erlaubt: dabei verlaesst
            # nur das Ergebnis den Bot, nicht der Wert.
            if roh == g:
                raise AssertionError(
                    "ctx.cfg[%s] reicht das Geheimnis %s im Klartext an die "
                    "Blueprints weiter — als bool(%s) uebergeben"
                    % (_ast.unparse(schluessel), g, g))
    # Und der Blueprint fragt auch gar nicht danach.
    for g in GEHEIM:
        assert '"%s"' % g not in s, \
            "der Blueprint greift auf %s zu — er braucht nur das HAT_-Boolean" % g
    for hat in ("HAT_DASHBOARD_TOKEN", "HAT_KICK_CREDS", "HAT_DISCORD_BOT_TOKEN"):
        assert '"%s"' % hat in b and '"%s"' % hat in s, "%s nicht verdrahtet" % hat

    # ── (3) Kein globals() im Blueprint. Der Schnappschuss las
    # globals().get("BOT_VERSION", "?") — dort ist das der Namensraum DIESER
    # Datei, das Deck haette dauerhaft "?" gemeldet. Dieselbe stille
    # Fehlanzeige wie bei /api/version (W33) und config_drift (W32).
    for k in _ast.walk(_ast.parse(s)):
        if isinstance(k, _ast.Call) and _ast.unparse(k.func) == "globals":
            raise AssertionError(
                "nc/routes/systemlage.py benutzt globals(), Zeile %d — im "
                "Blueprint der falsche Namensraum" % k.lineno)

    # ── (4) Die drei Zustands-Dicts wandern als REFERENZ. Eine Kopie waere ab
    # Start eingefroren: das Panel zeigte ewig null Messungen, null
    # Whisper-Laeufe und die Automatik-Schalter vom Bootzeitpunkt.
    for name in ("_AUTOMATION", "_CHECK_TIMING", "_WHISPER_STATE"):
        gefunden = False
        for schluessel, wert in zip(_cfg.keys, _cfg.values):
            if isinstance(schluessel, _ast.Constant) and schluessel.value == name:
                gefunden = True
                assert _ast.unparse(wert) == name, \
                    ("ctx.cfg[%r] ist keine Referenz sondern %s — das Panel "
                     "waere ab Start eingefroren" % (name, _ast.unparse(wert)))
        assert gefunden, "%s fehlt im Kontext" % name

    # ── (5) Das Upload-Limit beantwortet nc/discordlimits.py selbst ─────────
    assert hasattr(D, "aktuell_mb") and hasattr(D, "aktuell_label")
    assert "_discord_upload_limit_mb    = _nc_dclimits.aktuell_mb" in b, \
        "der Bot rechnet das Limit wieder selbst aus"
    D.configure(guild_id=0, override_mb=None)
    assert D.guild_filesize_bytes() == 0, "ohne Client muss 0 herauskommen"
    # Ohne Guild greift das Free-Limit, nicht 0 — sonst meldete das Deck
    # "0 MB" und der Betreiber suchte einen Fehler, den es nicht gibt.
    assert D.aktuell_mb() == D.FREE_DEFAULT_MB, D.aktuell_mb()
    assert "Free" in D.aktuell_label(), D.aktuell_label()
    # Der Betreiber-Deckel senkt — aber nie unter die Qualitaets-Untergrenze.
    D.configure(guild_id=0, override_mb=9)
    assert D.aktuell_mb() == 9, D.aktuell_mb()
    D.configure(guild_id=0, override_mb=5)
    assert D.aktuell_mb() == D.FLOOR_MB, \
        ("ein Betreiber-Deckel unter FLOOR_MB darf nicht durchschlagen — "
         "sonst komprimiert der Bot Aufnahmen bis zur Unbrauchbarkeit, "
         "bekommen: %s" % D.aktuell_mb())
    D.configure(guild_id=0, override_mb=None)

    # ── (6) EINE Antwort auf "laeuft Whisper hier". bot.py hielt eine zweite
    # Fassung ohne try — ein kaputter Paket-Baum haette dort geworfen statt
    # "nein" zu sagen.
    assert "_faster_whisper_available = _nc_whisper.verfuegbar" in b, \
        "bot.py hat wieder eine eigene Whisper-Pruefung"
    assert isinstance(W.verfuegbar(), bool)

    # ── (7) Der Restream-Manager kommt aus dem Register — MIT Wache. Vor dem
    # Start ist er None; ohne die Wache staerbe die ganze Antwort an einem
    # AttributeError, statt eine leere Zielliste zu melden.
    assert '_nc_rsstate.MGR["obj"]' in s, "der Manager kommt nicht aus dem Register"
    assert "if _mgr is not None:" in s, "keine Wache gegen den None-Manager"

    ok("v4.2-W1: config_snapshot + check_timing im Blueprint, kein Geheimnis "
       "im Kontext, Zustand als Referenz")

def _test_v42_w2_ein_riegel_gegen_pfadausbruch():
    """v4.2-W2: ein Riegel, ueberall derselbe — und er faengt Symlinks."""
    import ast as _ast
    import os as _os
    import re as _re

    def _nackt(pfad):
        """Quelltext OHNE Kommentare und ohne Docstrings.

        Dreimal ist in dieser Reihe ein Vertrag auf seine eigene Begruendung
        angeschlagen (W32 __file__, W33 Versionszahl, hier). Ein Vertrag, der
        den Kommentar meldet, der ihn erklaert, wird beim naechsten Mal
        geloescht statt gelesen — deshalb einmal richtig: ast.unparse wirft
        Kommentare weg, die Docstrings raeumen wir selbst heraus.
        """
        baum = _ast.parse(open(pfad, encoding="utf-8").read())
        for k in _ast.walk(baum):
            if not isinstance(k, (_ast.Module, _ast.FunctionDef,
                                  _ast.AsyncFunctionDef, _ast.ClassDef)):
                continue
            if (k.body and isinstance(k.body[0], _ast.Expr)
                    and isinstance(k.body[0].value, _ast.Constant)
                    and isinstance(k.body[0].value.value, str)):
                k.body.pop(0)
                if not k.body:
                    k.body.append(_ast.Pass())
        return _ast.unparse(_ast.fix_missing_locations(baum))

    from nc import sicherpfad as S

    # ── (1) Der Name verliert jeden Pfadanteil ─────────────────────────────
    for roh, erwartet in (("../../etc/passwd", "passwd"),
                          ("/etc/shadow", "shadow"),
                          ("a/b/c.txt", "c.txt"),
                          (".", "datei.bin"),
                          ("..", "datei.bin"),
                          ("", "datei.bin")):
        assert S.sicherer_name(roh) == erwartet, (roh, S.sicherer_name(roh))
    # Windows-Trenner: auf Linux ist "\\" ein NORMALES Zeichen, os.path.basename
    # laesst "..\\..\\x" komplett stehen. Wer nur basename benutzt, haelt das
    # fuer einen Dateinamen — auf einem Windows-Ziel ist es ein Ausbruch.
    assert S.sicherer_name("..\\..\\windows\\x.dll") == "x.dll", \
        ("Windows-Trenner nicht behandelt: %r. os.path.basename laesst auf "
         "Linux jeden Backslash stehen — der Name sieht harmlos aus und ist "
         "auf einem Windows-Ziel ein Ausbruch"
         % S.sicherer_name("..\\..\\windows\\x.dll"))
    # Harmloses bleibt unangetastet.
    assert S.sicherer_name("norm al-1(a).mp4") == "norm al-1(a).mp4"

    # ── (2) DER PUNKT DER WELLE: realpath faengt, was abspath durchlaesst.
    # Steht im Zielverzeichnis ein Symlink nach draussen, dann ist
    # abspath(basis/link/datei) == basis/link/datei — jede startswith-Pruefung
    # sagt "drin", geschrieben wird nach /etc. Genau so pruefte nc/updater.py
    # bei der Update-Entpackung, mit "Ein Zip-Slip schreibt sonst nach /etc"
    # als Kommentar darueber.
    basis = _ph.verzeichnis()
    _os.symlink("/etc", _os.path.join(basis, "raus"))
    ausbruch = _os.path.join(basis, "raus", "passwd")
    assert _os.path.abspath(ausbruch).startswith(basis + _os.sep), \
        "Vorbedingung: abspath haelt den Ausbruch faelschlich fuer sicher"
    assert S.unter(basis, ausbruch) is False, \
        "unter() laesst einen Symlink-Ausbruch durch — der ganze Riegel taugt nichts"
    assert S.unter(basis, _os.path.join(basis, "drin.txt")) is True

    # Nachbarverzeichnis mit gleichem Praefix: /x/archiv2 beginnt mit
    # /x/archiv, liegt aber nicht darin. Ein startswith ohne Trenner irrt.
    eltern = _ph.verzeichnis()
    a = _os.path.join(eltern, "archiv"); _os.makedirs(a)
    b = _os.path.join(eltern, "archiv2"); _os.makedirs(b)
    assert _os.path.join(b, "x").startswith(a), "Vorbedingung des Praefix-Falls"
    assert S.unter(a, _os.path.join(b, "x")) is False, \
        "unter() verwechselt ein Nachbarverzeichnis mit gleichem Praefix"

    # ── (3) sicher_join wirft, statt still danebenzugreifen. Ein Rueckfall
    # auf einen Ersatzpfad waere hier falsch: der Aufrufer schriebe in eine
    # Datei, die er nicht gemeint hat.
    assert S.sicher_join(basis, "../../etc/passwd") == _os.path.join(basis, "passwd")
    # Der Fall, den KEINE reine Namenspruefung faengt: der Name ist harmlos,
    # aber die Datei unter dem Namen ist ein Symlink nach draussen. Wer nur
    # basename() und einen Zeichensatz prueft, schreibt hier nach /etc.
    _os.symlink("/etc/passwd", _os.path.join(basis, "harmlos.txt"))
    try:
        S.sicher_join(basis, "harmlos.txt")
        raise AssertionError(
            "sicher_join laesst einen Symlink auf /etc/passwd durch — genau "
            "das faengt eine reine Namenspruefung nicht")
    except ValueError:
        pass

    # ── (4) Die Aufrufstellen benutzen ihn wirklich ────────────────────────
    up = _nackt("nc/updater.py")
    assert "_nc_sicherpfad.unter(root, p)" in up, \
        "nc/updater._abs prueft nicht mehr ueber nc.sicherpfad"
    assert "p.startswith(root + os.sep)" not in up, \
        ("nc/updater.py prueft wieder mit startswith+abspath — das laesst "
         "einen Symlink-Ausbruch durch")
    assert "_nc_sicherpfad.sicher_join(" in up, "rollback ohne Riegel"

    arc = _nackt("nc/routes/archive.py")
    assert "os.path.join(_c().cfg['ARCHIVE_DIR'], target_filename)" not in arc, \
        "der Zielpfad beim Umbenennen wird wieder ungeprueft zusammengesetzt"
    assert arc.count("_nc_sicherpfad.sicher_join(") >= 2, \
        "nicht alle Zielpfade im Archiv laufen ueber den Riegel"

    # ── (5) Der Katalogpfad wird nachgeschlagen, nicht zusammengesetzt ─────
    from nc import i18n as I
    assert set(I.KATALOGDATEI) == set(I.SPRACHEN), \
        "SPRACHEN und KATALOGDATEI laufen auseinander — eine Sprache ohne "\
        "Eintrag wuerde beim Laden mit KeyError sterben"
    i18nsrc = _nackt("nc/i18n.py")
    assert "'%s.json' % sprache" not in i18nsrc, \
        "der Katalogpfad wird wieder aus der Sprache zusammengesetzt"
    assert len(I.katalog("en")) > 1000, "der englische Katalog laedt nicht mehr"
    assert I.katalog("xx") == {}, "eine unbekannte Sprache muss leer bleiben"

    # ── (6) Die Tag-Muster halten an einer echten Tag-Grenze ───────────────
    # `</script >` beendet das Element im Browser. Ein Muster ohne \s* haelt
    # dort NICHT an und frisst den Rest der Datei: eine ID aus einem
    # JS-String wurde dann als doppelte Markup-ID gemeldet — ein Fehlalarm,
    # der das Werkzeug unglaubwuerdig macht.
    # Das echte Muster-Objekt pruefen, nicht seinen Quelltext: ein Regex,
    # den man aus der Datei zurueckparst, kommt mit verdoppelten Backslashes
    # zurueck und testet dann etwas anderes als das, was laeuft.
    import importlib.util as _iu
    _sp = _iu.spec_from_file_location("_ncpatch_pruef", "tools/ncpatch.py")
    _m = _iu.module_from_spec(_sp)
    _sp.loader.exec_module(_m)
    probe = ('<div id="echt"></div><script>var s=\'<div id="echt"></div>\';'
             '</script ><p>x</p>')
    for name in ("RE_SCRIPT_WEG", "RE_SCRIPT_BLOCK"):
        assert hasattr(_m, name), "tools/ncpatch.py hat kein %s mehr" % name
    weg = _m.RE_SCRIPT_WEG.sub("", probe)
    ids = _re.findall(r'id="([^"]+)"', weg)
    assert len(ids) == len(set(ids)) == 1, \
        ("das Tag-Muster laesst eine ID aus dem Skriptblock stehen (%r) — "
         "Fehlalarm 'doppelte ID' bei jedem `</script >` im Deck" % (ids,))
    # Und es haelt an einer echten Tag-Grenze, nicht an einem Praefix.
    assert _m.RE_SCRIPT_WEG.sub("", "<scriptfoo>x</scriptfoo>") == \
        "<scriptfoo>x</scriptfoo>", "das Muster passt auf <scriptfoo>"
    assert len(_m.RE_SCRIPT_BLOCK.findall(
        "<script>a</script >\n<script>b</script>")) == 2, \
        "zwei Bloecke werden zu einem verschmolzen — node --check liefe dann "\
        "an einer Datei, die es so nie gab"

    ok("v4.2-W2: ein Riegel gegen Pfadausbruch (realpath, nicht abspath), "
       "Katalog per Erlaubnisliste, Tag-Muster an der Tag-Grenze")

def _test_v42_w3_codeql_barriere_und_setup():
    """v4.2-W3: eigene CodeQL-Abfrage statt 208 unlesbarer Meldungen."""
    import ast as _ast
    import os as _os

    for datei in (".github/codeql/qlpack.yml", ".github/codeql/NcSanitizer.qll",
                  ".github/codeql/NcStackTraceExposure.ql",
                  ".github/codeql/codeql-config.yml",
                  ".github/workflows/codeql.yml"):
        assert _os.path.exists(datei), "%s fehlt" % datei

    qll = open(".github/codeql/NcSanitizer.qll", encoding="utf-8").read()
    ql = open(".github/codeql/NcStackTraceExposure.ql", encoding="utf-8").read()
    cfg = open(".github/codeql/codeql-config.yml", encoding="utf-8").read()
    wf = open(".github/workflows/codeql.yml", encoding="utf-8").read()

    # ── (1) Die Regel wird ERSETZT, nicht abgeschaltet. Ein blosses exclude
    # haette auch jeden neuen, echten Befund verschluckt — und genau so einer
    # (str(ex) in nc/routes/brain.py) stand wochenlang unbemerkt in der Liste,
    # weil 208 Meldungen niemand mehr einzeln liest.
    # OHNE Kommentarzeilen pruefen, und OHNE PyYAML.
    #
    # Ohne Kommentare, weil die Begruendung daneben dieselben Schluessel nennt
    # — ein Vertrag, der auf seine eigene Erklaerung anschlaegt, wird beim
    # naechsten Mal geloescht statt gelesen (dieselbe Falle wie in W32/W33).
    #
    # Ohne PyYAML, weil der Vertrags-Job in der CI nur `orjson flask`
    # installiert. Das steht seit W23 als Regel in ci.yml — und ich bin beim
    # ersten Versuch trotzdem hineingelaufen: `import yaml` liess beide
    # Vertrags-Jobs mit ModuleNotFoundError sterben.
    def _ohne_kommentar(text):
        return "\n".join(z for z in text.splitlines()
                         if not z.lstrip().startswith("#"))

    knapp = _ohne_kommentar(cfg)
    assert "id: py/stack-trace-exposure" in knapp, \
        "die Standardregel wird nicht ersetzt"
    assert "uses: ./.github/codeql" in knapp, "die eigene Abfrage wird nicht geladen"
    assert "@id nc/stack-trace-exposure" in ql, "die Ersatzabfrage hat keine eigene Id"
    assert "disable-default-queries" not in knapp, \
        ("die Standard-Suite waere abgeschaltet — dann faellt weit mehr weg "
         "als die eine Regel")

    # ── (2) Die Ersatzabfrage ist die GLEICHE Abfrage. Nur die Barriere kommt
    # dazu. Waeren Quelle, Senke oder der Select veraendert, hiesse sie zu
    # Unrecht so und wuerde etwas anderes messen.
    assert "StackTraceExposureFlow::flowPath(source, sink)" in ql, \
        "die Ersatzabfrage folgt nicht mehr demselben Datenfluss"
    assert "import NcSanitizer" in ql, "die Barriere ist nicht eingebunden"
    assert "StackTraceExposure::Sanitizer" in qll, \
        "die Barriere haengt nicht am vorgesehenen Erweiterungspunkt"

    # ── (3) DIE NAMEN MUESSEN ZUSAMMENBLEIBEN. Die Barriere greift ueber die
    # Namen "nach_aussen" und "_fehler_text". Wird der Helfer im Python-Code
    # umbenannt und hier nicht, faellt die Barriere still weg — und 193
    # Meldungen kommen ohne Vorwarnung zurueck.
    for name in ("nach_aussen", "_fehler_text"):
        assert '"%s"' % name in qll, "die Barriere kennt %s nicht" % name
    import nc.fehlertext as F
    assert hasattr(F, "nach_aussen"), \
        "nc.fehlertext.nach_aussen heisst anders — die CodeQL-Barriere zeigt ins Leere"
    # Und der lokale Name in den Blueprints ist wirklich _fehler_text.
    baum = _ast.parse(open("nc/routes/systemlage.py", encoding="utf-8").read())
    namen = {k.name for k in _ast.walk(baum)
             if isinstance(k, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    assert "_fehler_text" in namen, \
        "die Blueprints nennen den Helfer anders — die Barriere greift dort nicht"

    # ── (4) Der Workflow faehrt dieselben Sprachen wie das Default-Setup.
    # Faellt eine weg, hoert die Analyse dort still auf — ohne rote Meldung.
    wf_knapp = _ohne_kommentar(wf)
    for sprache in ("actions", "javascript-typescript", "python"):
        assert "language: %s" % sprache in wf_knapp, \
            "Sprache %s fehlt im Workflow" % sprache
    assert "security-events: write" in wf, "ohne dieses Recht laedt nichts hoch"
    assert "config-file: ./.github/codeql/codeql-config.yml" in wf, \
        "der Workflow benutzt die Konfiguration nicht"

    # ── (5) Der Umstellungs-Hinweis steht drin. Solange das Default-Setup in
    # den Repo-Einstellungen aktiv ist, bricht dieser Workflow beim Hochladen
    # ab — das ist eine Handarbeit, die nur der Betreiber machen kann, und
    # ohne Hinweis sucht er den Fehler im Workflow.
    assert "Default setup" in wf and "Disable" in wf, \
        "der Hinweis auf das abzuschaltende Default-Setup fehlt"

    ok("v4.2-W3: CodeQL-Barriere fuer nach_aussen, Regel ersetzt statt "
       "abgeschaltet, Namen vertraglich gekoppelt")

def _test_v42_w4_preflight_und_resilienz():
    """v4.2-W4: die letzten grossen System-Routen bis auf selftest."""
    import ast as _ast
    import re as _re

    import nc.systemprobe as P

    b = open("bot.py", encoding="utf-8").read()
    s = open("nc/routes/systemlage.py", encoding="utf-8").read()

    # ── (1) Draussen aus dem Monolithen, drin im Blueprint ─────────────────
    for name in ("api_system_preflight", "api_system_resilience"):
        assert ("\ndef %s(" % name) not in b, "%s steht noch in bot.py" % name
        assert "def %s(" % name in s, "%s fehlt im Blueprint" % name

    # ── (2) KEIN globals() — im Blueprint der falsche Namensraum. Der
    # Monolith hatte hier `RECORDINGS_DIR if "RECORDINGS_DIR" in globals()
    # else "/"`. Uebernommen waere der Test dauerhaft False gewesen und die
    # Preflight-Karte haette die SYSTEMPLATTE gemessen statt des
    # Aufnahme-Verzeichnisses — eine Zahl, die stimmt aussieht und falsch ist.
    for k in _ast.walk(_ast.parse(s)):
        if isinstance(k, _ast.Call) and _ast.unparse(k.func) == "globals":
            raise AssertionError(
                "nc/routes/systemlage.py benutzt globals(), Zeile %d" % k.lineno)
    assert "_c().recordings_dir" in s, \
        "die Preflight-Karte misst nicht mehr das Aufnahme-Verzeichnis"

    # ── (3) KEINE ZWEITE WAHRHEIT. recordings_dir, ffmpeg_threads_bg und
    # ffmpeg_nice_bg liegen seit W110/W116 als SLOT im Kontext. Sie
    # zusaetzlich nach cfg zu legen waeren zwei Werte fuer dieselbe Sache,
    # die beim naechsten Umbau auseinanderlaufen.
    i = b.index("_nc_ctx.configure(")
    block = b[i:b.index("\n)\n", i)]
    for doppelt in ("RECORDINGS_DIR", "FFMPEG_THREADS_BG", "FFMPEG_NICE_BG"):
        assert '"%s":' % doppelt not in block, \
            ("ctx.cfg[%r] dupliziert einen vorhandenen Slot — zwei Werte fuer "
             "dieselbe Sache" % doppelt)

    # ── (4) Jeder gelesene cfg-Schluessel wird auch geliefert. Ein Tippfehler
    # waere sonst ein KeyError erst beim Aufruf der Route — im Betrieb, nicht
    # im Test. (Genau so ist FFMPEG_THREADS_BG in dieser Welle aufgefallen.)
    benutzt = set(_re.findall(r"""c\[["']([A-Z_][A-Z0-9_]*)["']\]""", s))
    geliefert = set(_re.findall(r'^\s+"([A-Z_][A-Z0-9_]*)":', block, _re.M))
    fehlt = sorted(benutzt - geliefert)
    assert not fehlt, "der Blueprint liest cfg-Schluessel, die der Bot nicht liefert: %r" % fehlt

    # ── (5) Die drei Sonden sind Aliase, kein zweiter Koerper ──────────────
    for zeile in ("_cpu_load_snapshot = _nc_probe.cpu_load_snapshot",
                  "_disk_pct = _nc_probe.disk_pct",
                  "_check_ai_alive_sync = _nc_probe.ai_alive"):
        assert zeile in b, "bot.py haelt wieder einen eigenen Koerper: %s" % zeile

    # ── (6) disk_pct misst das KONFIGURIERTE Verzeichnis, nicht das
    # Arbeitsverzeichnis. Sonst zeigt das Deck die Systemplatte und der
    # Plattenwaechter greift zu spaet.
    import os as _os
    d = _ph.verzeichnis()
    sicher = P.recordings_dir()
    try:
        P.configure(recordings_dir=d)
        assert P.recordings_dir() == d
        # Womit wirklich gemessen wird: ein Vergleich der Prozentzahlen taugt
        # nicht — Temp- und Arbeitsverzeichnis liegen oft auf derselben
        # Platte und liefern denselben Wert. Also den Aufruf abfangen.
        import shutil as _sh
        gesehen = []
        _echt = _sh.disk_usage
        _sh.disk_usage = lambda pfad: (gesehen.append(pfad), _echt(pfad))[1]
        try:
            pct, st = P.disk_pct()
        finally:
            _sh.disk_usage = _echt
        assert gesehen == [d], \
            ("disk_pct misst %r statt des konfigurierten Verzeichnisses %r — "
             "das Deck zeigte dann die Systemplatte und der Plattenwaechter "
             "griffe zu spaet" % (gesehen, d))
        assert isinstance(pct, int) and 0 <= pct <= 100, pct
        assert st is not None and st.total > 0
        # Ein unbrauchbarer Pfad darf keine Ausnahme werfen — der Aufrufer ist
        # ein Statuspanel, das eine Zahl braucht.
        P.configure(recordings_dir=_os.path.join(d, "gibtsnicht"))
        pct2, _ = P.disk_pct()
        assert isinstance(pct2, int), pct2
    finally:
        P.configure(recordings_dir=sicher)

    # ── (7) cpu_load_snapshot liefert die Felder, die das Panel zeigt. Ein
    # leeres Dict waere kein Fehler, sondern ein leeres Panel.
    d2 = P.cpu_load_snapshot()
    for feld in ("state", "mem_total_gb", "swap_pct"):
        assert feld in d2, "cpu_load_snapshot liefert %r nicht mehr: %r" % (feld, sorted(d2))

    # ── (8) Der Whisper-Drosselzustand bleibt sichtbar — sonst laeuft die
    # Drossel unbemerkt (B98).
    assert '"throttled": c["_WHISPER_STATE"]["throttled"]' in s, \
        "der Drossel-Zustand fehlt in der Resilienz-Antwort"

    ok("v4.2-W4: preflight + resilience im Blueprint, Sonden in nc/, "
       "keine zweite Wahrheit fuer die drei Slots")

def _test_v42_w6_zerschnittene_saetze():
    """v4.2-W6: Saetze, die ein Inline-Tag zerschneidet, sind uebersetzbar."""
    import json as _json
    import sys as _sys

    _sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                     "tools"))
    import i18n_extract as _ex

    # ── (1) BEIDE SEITEN, EIN SCHLUESSEL. Das Verfahren steht und faellt
    # damit, dass Extraktor (Python) und Uebersetzer (Browser-JS) aus
    # denselben Kindern dieselbe Zeichenkette bauen. Faellt eine Seite auch
    # nur um ein Leerzeichen ab, trifft KEIN Eintrag mehr — und der Katalog
    # meldet trotzdem "0 fehlend", weil er nur zaehlt, was der Extraktor
    # gesehen hat. Genau die stille Luecke, die W28 schon einmal hatte.
    kinder = [("t", "Gebucht wird der "), ("el", "b"),
              ("t", " \u2014 der Tag\n   der Gutschrift.")]
    assert _ex.muster_schluessel(kinder) == \
        "Gebucht wird der {0} \u2014 der Tag der Gutschrift.", \
        "der Muster-Schluessel wird anders gebaut als dokumentiert"
    # Umbruch und Einrueckung zu EINEM Leerzeichen, aussen getrimmt: sonst
    # haengt der Schluessel an der Formatierung des HTML und jede
    # Umformatierung toetet ihn stillschweigend.
    assert _ex.muster_schluessel([("t", "\n  A  "), ("el", "b"), ("t", "  B\n")]) \
        == "A {0} B", "Leerraum wird nicht normalisiert"

    js = open("nc/routes/i18n.py", encoding="utf-8").read()
    for teil in ("function musterSchluessel(", "function musterEinsetzen(",
                 "musterEinsetzen(n);"):
        assert teil in js, "der Browser-Uebersetzer kennt %s nicht" % teil
    # Die JS-Seite muss dieselben drei Regeln fahren wie die Python-Seite.
    for teil in ("replace(/\\s+/g, ' ')", "replace(/^\\s+|\\s+$/g, '')"):
        assert teil in js, "im Browser fehlt die Regel %s" % teil
    # Und dieselben GRENZEN. Nicht als Zeichenkette verglichen, sondern als
    # Menge: wer in Python ein Inline-Tag ergaenzt und im Browser nicht, baut
    # eine Luecke, die kein Textvergleich sieht — der Extraktor sammelt dann
    # einen Schluessel ein, den der Browser nie erzeugt.
    js_inline = set(re.findall(r"(\w+):1",
                               re.search(r"var INLINE = \{(.*?)\};", js, re.S).group(1)))
    assert js_inline == {t.upper() for t in _ex._INLINE_TAGS}, \
        "Inline-Listen laufen auseinander: nur JS %r / nur Python %r" % (
            sorted(js_inline - {t.upper() for t in _ex._INLINE_TAGS}),
            sorted({t.upper() for t in _ex._INLINE_TAGS} - js_inline))
    js_max = int(re.search(r"var MAX_PLATZ = (\d+)", js).group(1))
    assert js_max == _ex._MAX_PLATZHALTER, \
        "MAX_PLATZ %d != _MAX_PLATZHALTER %d" % (js_max, _ex._MAX_PLATZHALTER)

    # ── (2) NUR WO ES KLEMMT. Traegt jedes Textstueck fuer sich schon als
    # Knoten, macht der normale Weg das laengst — ein Muster wuerde dort eine
    # vorhandene Uebersetzung durch einen laengeren Schluessel ersetzen und
    # damit geleistete Arbeit vernichten.
    def _muster(html):
        m, _ = _ex._muster_strings(html)
        return m

    gut = _muster("<p>Der Bot laeuft seit gestern. <b>x</b> "
                  "Die Aufnahme ist fertig und liegt im Archiv.</p>")
    assert not gut, "Muster gebaut, obwohl beide Stuecke allein tragen: %r" % gut
    klemmt = _muster("<p>Gebucht wird der <b>Zufluss</b> \u2014 der Tag der "
                     "Gutschrift auf dem Konto, nicht der Stream-Tag.</p>")
    assert klemmt == {"Gebucht wird der {0} \u2014 der Tag der Gutschrift auf "
                      "dem Konto, nicht der Stream-Tag."}, \
        "der zerschnittene Satz wird nicht eingesammelt: %r" % klemmt
    # <code> ist Daten (Befehle, Logzeilen) und darf nie Schluessel werden.
    assert not _muster("<code>ffmpeg -i <b>x</b> und noch etwas Text dazu</code>"), \
        "ein <code>-Block wurde zum Muster"
    # Ein Absatz mit einem Dutzend Tags ist ein Layout, kein Satz.
    viele = "<p>Ein Satz der lang genug ist %s und weiter geht.</p>" % (
        "<b>x</b>" * (_ex._MAX_PLATZHALTER + 1))
    assert not _muster(viele), "Layout mit %d Tags wurde zum Satz" % (
        _ex._MAX_PLATZHALTER + 1)

    # ── (3) VERDRAENGT, NICHT VERWAIST. Beim Muster ersetzt der Browser den
    # ganzen Inhalt; die einzelnen Knoten gibt es danach nicht mehr. Ein
    # Eintrag fuer so ein Stueck waere tot. Steht derselbe Text ANDERSWO noch
    # fuer sich, muss er dagegen bleiben.
    _, weg = _ex._muster_strings(
        "<p>Gebucht wird der <b>Zufluss</b> \u2014 der Tag der Gutschrift auf "
        "dem Konto, nicht der Stream-Tag.</p>")
    assert "Gebucht wird der" in weg, "das Bruchstueck wird nicht verdraengt"
    _, weg2 = _ex._muster_strings(
        "<p>Gebucht wird der <b>Zufluss</b> \u2014 der Tag der Gutschrift auf "
        "dem Konto, nicht der Stream-Tag.</p><div>Gebucht wird der</div>")
    assert "Gebucht wird der" not in weg2, \
        "ein Text, der anderswo allein steht, wurde mit verdraengt"

    # ── (4) KEIN PLATZHALTER DARF VERLOREN GEHEN. Der Browser setzt die
    # VORHANDENEN Kind-Elemente wieder ein. Fehlt in der Uebersetzung ein
    # {n}, verschwaende der Umbau das Element \u2014 ein fehlender Link ist
    # schlimmer als ein deutscher Satz. Der Uebersetzer laesst so einen
    # Eintrag deshalb liegen; hier faellt er auf, statt still zu wirken.
    def _pruefe_katalog(strings):
        schlecht = []
        for de, en in strings.items():
            n = len(re.findall(r"\{(\d+)\}", de))
            if not n or not en:
                continue
            idx = [int(x) for x in re.findall(r"\{(\d+)\}", en)]
            if sorted(idx) != list(range(n)):
                schlecht.append(de[:60])
        return schlecht

    for datei in sorted(os.listdir("locales")):
        if not datei.endswith(".json"):
            continue
        with open(os.path.join("locales", datei), encoding="utf-8") as f:
            strings = _json.load(f).get("strings", {})
        schlecht = _pruefe_katalog(strings)
        assert not schlecht, "locales/%s: Platzhalter passen nicht: %r" % (
            datei, schlecht)
    # Der Melder muss auch wirklich anschlagen \u2014 sonst prueft er nichts.
    assert _pruefe_katalog({"A {0} B {1}": "A {0} B"}), \
        "fehlender Platzhalter wird nicht gemeldet"
    assert _pruefe_katalog({"A {0} B": "A {0} B {0}"}), \
        "doppelter Platzhalter wird nicht gemeldet"

    ok("v4.2-W6: zerschnittene Saetze \u2014 ein Schluessel auf beiden Seiten")


def _test_v42_w5_selftest_und_leerer_monolith():
    """v4.2-W5: keine System-Route mehr im Monolithen."""
    import ast as _ast
    import re as _re

    b = open("bot.py", encoding="utf-8").read()
    s = open("nc/routes/selbsttest.py", encoding="utf-8").read()

    # ── (1) DER ABSCHLUSS von Vorschlag 2. Alle acht System-Routen sind
    # draussen. Steht eine wieder in bot.py, ist der Abbau rueckwaerts
    # gelaufen — und das faellt sonst niemandem auf.
    ACHT = ("api_system", "api_system_config_snapshot", "api_system_preflight",
            "api_system_preflight_history", "api_system_resilience",
            "api_check_timing", "api_config_drift", "api_selftest")
    drin = [n for n in ACHT if ("\ndef %s(" % n) in b]
    assert not drin, "wieder im Monolithen: %r" % drin
    assert "def api_selftest(" in s, "api_selftest fehlt im Blueprint"
    assert "register_blueprint(_nc_routes_selbsttest.bp)" in b, \
        "der Blueprint ist nicht registriert — /api/selftest waere 404"

    # ── (2) Der Helfer ist mitgewandert. 23 Aufrufe, alle in dieser einen
    # Funktion — er im Monolithen, sie im Blueprint waere ein Import ueber
    # die Architektur-Grenze.
    assert "def _st_befund(" in s, "_st_befund fehlt im Blueprint"
    assert "\ndef _st_befund(" not in b, "_st_befund steht noch in bot.py"

    # ── (3) EIN WEG zu Sperrliste und Angriffen. nc/routes/abwehr.py haelt
    # seit W25 die Haken, die der Bot eintraegt. Ein zweiter Weg zu denselben
    # Daten waere eine zweite Wahrheit — und die beiden Panels koennten
    # Widerspruechliches melden.
    assert "_nc_routes_abwehr.HAKEN[name][\"fn\"]" in s, \
        "der Selbsttest holt Sperrliste/Angriffe nicht ueber die Abwehr-Haken"
    for haken in ('_haken("sperrliste")', '_haken("angriffe")'):
        assert haken in s, "%s wird nicht benutzt" % haken
    # Fehlt der Haken (Bot laeuft nicht), darf NICHT "nichts gefunden"
    # herauskommen. Bei einer Sicherheitsanzeige ist das die gefaehrlichste
    # aller Antworten — dieselbe Ueberlegung wie in abwehr._nicht_bereit().
    # Nach VERHALTEN, nicht nach Text: ein `return {}` steht auch im
    # except-Zweig, die Textsuche kann beides nicht unterscheiden.
    from nc import ctx as _nc_ctx_modul
    from nc.routes import abwehr as _A

    def _ctx_konfiguriert():
        return _nc_ctx_modul.is_configured()

    from nc.routes import selbsttest as _S
    _sicher = _A.HAKEN["sperrliste"]["fn"]
    try:
        _A.HAKEN["sperrliste"]["fn"] = None
        assert _S._haken("sperrliste") == {}, \
            ("ein fehlender Haken liefert ein Ergebnis statt Leere — der "
             "Selbsttest meldete dann 'keine Sperren', obwohl gar nicht "
             "nachgesehen wurde")
        _A.HAKEN["sperrliste"]["fn"] = lambda: {"total_banned": 7}
        assert _S._haken("sperrliste") == {"total_banned": 7}, \
            "ein vorhandener Haken wird nicht durchgereicht"
        # Der werfende Haken loggt — und Loggen braucht den gefuellten
        # Kontext. Ohne ihn (Vertrag allein aufgerufen) waere der Test ein
        # Fehlalarm ueber etwas, das im Betrieb nie vorkommt.
        if _ctx_konfiguriert():
            def _kaputt():
                raise RuntimeError("absichtlich")
            _A.HAKEN["sperrliste"]["fn"] = _kaputt
            assert _S._haken("sperrliste") == {}, \
                "ein werfender Haken reisst den ganzen Selbsttest mit"
    finally:
        _A.HAKEN["sperrliste"]["fn"] = _sicher

    # ── (4) Der Restream-Manager kommt aus dem Register — MIT Wache. Vor dem
    # Start ist er None; ohne Wache kippte ein AttributeError die GANZE
    # Antwort, also auch die 20 Befunde ohne Restream-Bezug.
    assert '_nc_rsstate.MGR["obj"]' in s, "der Manager kommt nicht aus dem Register"
    # Jeder Zugriff auf seine privaten Felder laeuft ueber getattr mit
    # Vorgabe. Ein nacktes _mgr()._procs waere vor dem Start ein
    # AttributeError auf None.
    for feld in ("_procs", "_srcexpired"):
        for treffer in _re.finditer(r"[\w()]+\.%s\b" % feld, s):
            zeile = s[:treffer.start()].count("\n") + 1
            assert "getattr(" in s.splitlines()[zeile - 1], \
                ("ungeschuetzter Zugriff auf %s in Zeile %d — vor dem Start "
                 "ist der Manager None und die GANZE Antwort kippt, nicht nur "
                 "der Restream-Teil" % (feld, zeile))
    assert s.count("getattr(_mgr()") + s.count('getattr(_m, "_procs"') >= 3, \
        "zu wenige geschuetzte Zugriffe — eine Stelle wurde vergessen"

    # ── (5) Kein globals() — dieselbe Falle wie in W32/W33/W4.
    for k in _ast.walk(_ast.parse(s)):
        if isinstance(k, _ast.Call) and _ast.unparse(k.func) == "globals":
            raise AssertionError("nc/routes/selbsttest.py benutzt globals(), Zeile %d" % k.lineno)

    # ── (6) Jeder gelesene cfg-Schluessel wird auch geliefert. Sonst ein
    # KeyError beim ersten Aufruf — im Betrieb, nicht im Test.
    i = b.index("_nc_ctx.configure(")
    block = b[i:b.index("\n)\n", i)]
    benutzt = set(_re.findall(r"""c\[["']([A-Z_][A-Z0-9_]*)["']\]""", s))
    geliefert = set(_re.findall(r'^\s+"([A-Z_][A-Z0-9_]*)":', block, _re.M))
    fehlt = sorted(benutzt - geliefert)
    assert not fehlt, "der Blueprint liest cfg-Schluessel, die der Bot nicht liefert: %r" % fehlt

    # ── (7) Kein Stream-Schluessel im Kontext. Der Selbsttest fragt nur, OB
    # einer gesetzt ist.
    assert '"YOUTUBE_STREAM_KEY"' not in s, \
        "der Selbsttest greift auf den YouTube-Schluessel zu statt auf HAT_YOUTUBE_KEY"
    assert 'c["HAT_YOUTUBE_KEY"]' in s, "die Boolean-Pruefung fehlt"

    ok("v4.2-W5: /api/selftest im Blueprint — keine der acht System-Routen "
       "steht mehr im Monolithen")

def _test_v42_w7_motd_optik():
    """v4.2-W7: die vier neuen MOTD-Anzeigen — und die eine Grundregel."""
    import subprocess as _sp

    motd = "tools/motd.sh"
    quelle = open(motd, encoding="utf-8").read()

    # ── (1) DIE GRUNDREGEL. Eine MOTD darf NIE einen Login blockieren. Jedes
    # neue Kommando, das haengen kann, gehoert hinter tmo(); ein set -e wuerde
    # bei der ersten leeren Ausgabe den Login abbrechen. Beides ist keine
    # Stilfrage: ein blockierter Login auf einem Server ohne Konsole ist ein
    # Ausfall, der sich nicht mehr aus der Ferne beheben laesst.
    assert "\nset -e" not in quelle, "set -e in der MOTD — ein Login darf nie abbrechen"
    for befehl in ("ip route show default", "tail -n 50000"):
        stelle = quelle.find(befehl)
        assert stelle > 0, "%r fehlt" % befehl
        zeile = quelle[quelle.rfind("\n", 0, stelle) + 1:stelle]
        assert "tmo " in zeile, "%r laeuft ohne Zeitdeckel: %r" % (befehl, zeile.strip())

    # ── (2) EIN MESSFENSTER, NICHT ZWEI. Der Durchsatz braucht zwei Proben
    # mit Abstand. Ein eigener sleep waere der teuerste Posten der ganzen
    # Anzeige geworden — teurer als alles andere zusammen. Er haengt sich
    # deshalb an das Fenster, das fuer die CPU ohnehin gewartet wird.
    assert quelle.count('sleep "$CPU_SAMPLE"') == 1, \
        "mehr als ein Messfenster — der Durchsatz kostet jetzt einen eigenen sleep"
    fenster = quelle[quelle.find("CPU_LINES=\"\"; NET_RX="):]
    fenster = fenster[:fenster.find('\nfi\n')]
    assert fenster.find("_n1=") < fenster.find('sleep "$CPU_SAMPLE"') < fenster.find("_n2="), \
        "die Netz-Proben liegen nicht um das Messfenster herum"

    # ── (3) DIE AMPEL BRAUCHT IHRE MESSWERTE VOR DEM KOPF. Genau deshalb sind
    # die Proben fuer Dienst und Dashboard hochgezogen worden. Rutscht eine
    # zurueck hinter den Kopf, zeigt die Ampel wieder "alles im Griff",
    # waehrend zwei Zeilen tiefer "gestoppt" steht — der gefaehrlichste aller
    # Zustaende, weil er falsche Sicherheit gibt.
    kopf = quelle.find("# ── Kopf ─")
    for name in ("BOT_STATE=unbekannt", "DASH_STATE=aus", "LAGE=ok", "DPCT=0"):
        assert 0 < quelle.find(name) < kopf, "%s wird erst NACH dem Kopf gesetzt" % name
    # Und die Ursache muss die Folge schlagen: ein toter Bot macht das
    # Dashboard unerreichbar — stuende dort die Folge, suchte der Betreiber
    # am falschen Ende.
    assert quelle.find('lage_setz err "Bot laeuft nicht"') < \
        quelle.find('lage_setz err  "Dashboard nicht erreichbar"'), \
        "die Folge wird vor der Ursache geprueft"

    # ── (4) VERHALTEN, nicht Wortlaut. Die vier Anzeigen werden ausgefuehrt
    # und ihr Ergebnis geprueft — ein Textvergleich haette bei jeder der drei
    # Umformulierungen dieser Datei gekippt, ohne dass etwas kaputt war.
    def _lauf(*teile, **umgebung):
        # Erst der Vorgabewert, dann der Aufrufer — sonst entschiede die
        # Umgebung des Testlaufs mit, und der Vertrag waere von der Maschine
        # abhaengig, auf der er laeuft.
        umg = dict(os.environ)
        umg["COLOR_MODE"] = "off"
        # v4.2-W100: und CONF=/dev/null, damit keine INSTALLIERTE
        # /etc/nightcrawler/motd.conf mitredet. Genau daran ist dieser Vertrag
        # rot geworden, nachdem tools/installer.sh auf derselben Maschine
        # gelaufen war: die Datei trug SERVICE='' und BOT_DIR=<Installation>
        # und ueberstimmte die hier gesetzten Werte. Eine Suite, die vom
        # Systemzustand abhaengt, prueft nicht mehr nur den Code.
        umg["CONF"] = os.devnull
        umg.update(umgebung)
        return _sp.run(["bash", motd] + list(teile), capture_output=True,
                       text=True, timeout=60, env=umg).stdout

    # ── (4a) v4.2-W100: UND DIE REIHENFOLGE SELBST. Der Kopf von motd.sh sagt
    # seit je "per /etc/nightcrawler/motd.conf ODER Umgebung ueberschreibbar" —
    # der Code lud die Datei NACH den Vorgaben und gewann damit immer. Gemessen:
    #
    #     SERVICE=ausdruecklich  ohne conf -> SERVICE=[ausdruecklich]
    #     SERVICE=ausdruecklich  mit  conf -> SERVICE=[]
    #
    # Fuer den Betreiber heisst das: `SERVICE=foo tools/motd.sh` tat nicht,
    # was dort steht. Aufgefallen ist es, weil dieser Vertrag rot wurde,
    # nachdem tools/installer.sh auf derselben Maschine gelaufen war.
    #
    # Geprueft wird am ECHTEN Skript und an einer SICHTBAREN Wirkung: WIDTH
    # bestimmt die Breite der Trennlinie. Eine Quelltext-Lesung haette hier
    # nur bestaetigt, dass die Zeilen dastehen — nicht, dass sie wirken.
    conf = os.path.join(_ph.verzeichnis(), "motd.conf")
    with open(conf, "w", encoding="utf-8") as f:
        f.write("WIDTH='30'\n")

    def _breite(**umg):
        # Gezaehlt werden die Linienzeichen der Trennlinie — die ist genau
        # WIDTH breit. Die laengste ZEILE taugt nicht: das ist eine
        # Inhaltszeile, die von WIDTH nicht abhaengt (erster Anlauf: 123 == 123
        # fuer beide Faelle, der Vertrag haette nichts gemessen).
        return _lauf(**umg).count("\u2501")

    nur_datei = _breite(CONF=conf)
    datei_und_umgebung = _breite(CONF=conf, WIDTH="70")
    assert nur_datei > 0, "die MOTD gibt nichts aus"
    assert datei_und_umgebung > nur_datei, (
        "die motd.conf ueberstimmt eine ausdrueckliche Umgebungsvariable: "
        "WIDTH=70 ergibt %d Zeichen, die Datei allein %d"
        % (datei_und_umgebung, nur_datei))
    # Und die Datei wirkt weiterhin, wenn die Umgebung schweigt — sonst waere
    # die Reparatur eine Abschaltung.
    ohne_beides = _breite(CONF=os.devnull)
    assert nur_datei < ohne_beides, (
        "die motd.conf wirkt gar nicht mehr (Datei %d, Vorgabe %d) — dann "
        "waere sie abgeschafft statt eingeordnet" % (nur_datei, ohne_beides))
    ok("W100: die motd.conf ueberstimmt keine ausdrueckliche Umgebungsvariable")

    # Der Miniverlauf: sieben Zahlen, sieben Zeichen, das Maximum als Vollblock
    # und die Null als Grundlinie. Ohne diese Skalierung waere er bei kleinen
    # Zahlen platt und bei grossen abgeschnitten.
    hilf = _sp.run(["bash", "-c",
                    "source /dev/stdin <<'X'\n%s\nX\nspark 0 1 0 12 0 3 0"
                    % re.search(r"^spark\(\)\{.*?^\}", quelle, re.S | re.M).group(0)],
                   capture_output=True, text=True, timeout=30).stdout
    assert len(hilf) == 7, "der Verlauf hat %d Zeichen statt sieben: %r" % (len(hilf), hilf)
    assert hilf[3] == "\u2588", "der Hoechstwert ist kein Vollblock: %r" % hilf
    assert hilf[0] == hilf[2] == "\u2581", "die Null liegt nicht auf der Grundlinie: %r" % hilf

    # Die Ampel: gruen nur, wenn wirklich alles steht. Geprueft mit
    # vorgetaeuschtem systemctl/curl, weil die echten Zustaende sich in einem
    # Testlauf nicht herstellen lassen — und ungeprueft waere ausgerechnet der
    # Pfad, den der Betreiber jeden Tag sieht, der einzige ohne Deckung.
    stub = _ph.verzeichnis()
    with open(os.path.join(stub, "systemctl"), "w", encoding="utf-8") as f:
        f.write('#!/bin/bash\ncase "$*" in\n'
                '  *"is-active --quiet"*) [ "$FAKE_BOT" = up ] && exit 0 || exit 1;;\n'
                '  *"show -p Result"*) echo "exit-code";;\n'
                '  *"show -p NRestarts"*) echo 0;;\n'
                '  *list-unit-files*) exit 1;;\nesac\nexit 0\n')
    with open(os.path.join(stub, "curl"), "w", encoding="utf-8") as f:
        f.write('#!/bin/bash\n[ "$FAKE_DASH" = none ] && exit 7\n'
                'echo \'{"ok": true, "procs": 4, "zombies": 0}\'\n')
    for name in ("systemctl", "curl"):
        os.chmod(os.path.join(stub, name), 0o755)
    botdir = _ph.verzeichnis()
    open(os.path.join(botdir, "bot.py"), "w").close()

    pfad = stub + os.pathsep + os.environ.get("PATH", "")
    gruen = _lauf(PATH=pfad, FAKE_BOT="up", FAKE_DASH="ok",
                  SERVICE="nightcrawler", BOT_DIR=botdir)
    rot = _lauf(PATH=pfad, FAKE_BOT="down", FAKE_DASH="none",
                SERVICE="nightcrawler", BOT_DIR=botdir)
    assert "alles im Griff" in gruen, "der gesunde Zustand meldet keine gruene Ampel"
    assert "Bot laeuft nicht" in rot, "der gestoppte Bot erreicht die Ampel nicht"
    assert "alles im Griff" not in rot, \
        "gruene Ampel trotz gestopptem Bot — falsche Sicherheit"
    # Die Ampel darf die Zeile darunter nie ueberholen: was oben steht, muss
    # unten belegt sein.
    assert "gestoppt" in rot, "die Ampel meldet mehr, als die Zeilen darunter zeigen"

    # ── (5) DER VERLAUFSBALKEN faellt zurueck, statt zu verschwinden. Auf
    # einer 16-Farben-Handy-App gibt es keinen Verlauf; dort muss der Balken
    # trotzdem dastehen. Ein "schoen oder gar nicht" waere hier der falsche
    # Handel — die MOTD ist eine Statusanzeige, kein Plakat.
    for modus in ("truecolor", "256", "16", "off"):
        aus = _lauf(COLOR_MODE=modus, BOT_DIR=botdir)
        assert "\u2588" in aus or "\u2592" in aus, \
            "COLOR_MODE=%s zeigt gar keinen Balken" % modus

    ok("v4.2-W7: MOTD-Optik \u2014 Ampel vor dem Kopf, ein Messfenster, Balken faellt zurueck")


def _test_v42_w8_windows_installer_spricht_englisch():
    """v4.2-W8: tools/install.bat hatte gar keine Sprachschicht."""
    import sys as _sys

    _sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                     "tools"))
    import i18n_tools as _it

    bat = open("tools/install.bat", encoding="utf-8").read()

    # ── (1) DER PRUEFER SAH DIESE DATEI GAR NICHT AN. Genau das ist die
    # gefaehrliche Sorte Luecke: er meldete 100 % Abdeckung fuer die
    # Shell-Werkzeuge, waehrend der Windows-Installer zu 0 % uebersetzt war.
    # Eine Abdeckungszahl, die nur zaehlt, was sie ohnehin kennt, verdeckt
    # genau das, was sie sichtbar machen soll (dieselbe Lehre wie W28).
    assert "tools/install.bat" in _it.QUELLEN_BAT, \
        "der Windows-Installer steht nicht in der Quellenliste des Pruefers"
    gefunden = _it.sammeln()
    assert len(gefunden) > 250, \
        "nur %d Zeichenketten — der Batch-Sammler greift nicht" % len(gefunden)

    # ── (2) REIN ASCII. Steht so in der Kopfzeile der Datei und ist keine
    # Stilfrage: cmd.exe rendert je nach Codepage sonst Buchstabensalat, und
    # zwar erst beim Anwender.
    schlecht = sorted({c for c in bat if ord(c) > 127})
    assert not schlecht, "nicht-ASCII in install.bat: %r" % schlecht

    # ── (3) DER TABULATOR IST ECHT. Trennzeichen im Katalog, in "delims=" und
    # im Suchmuster. Ein Editor, der Tabs zu Leerzeichen macht, wuerde den
    # Nachschlag still wirkungslos machen — die Ausgabe bliebe deutsch, ohne
    # dass irgendetwas scheitert.
    assert 'delims=\t"' in bat, "das Trennzeichen in delims= ist kein Tabulator mehr"
    assert '/c:"%~1\t"' in bat, "das Suchmuster traegt keinen Tabulator mehr"
    assert "/b /l /c:" in bat, \
        "findstr laeuft nicht mehr literal und am Zeilenanfang — die deutschen " \
        "Texte enthalten Punkte und Klammern, die als Ausdruck etwas anderes bedeuten"

    # ── (4) DER DEUTSCHE PFAD BLEIBT UNBERUEHRT. Dieser Installer laesst sich
    # hier nicht ausfuehren — es gibt kein cmd.exe. Was man nicht ausprobieren
    # kann, muss so gebaut sein, dass sein Fehlschlag folgenlos ist: ohne
    # gesetzten Katalog kehrt :t VOR dem Nachschlag zurueck, und der
    # Rueckfallwert steht schon in der Zeile davor.
    zeilen = [z.strip() for z in
              bat[bat.index("\n:t\n") + 1:].split("\n") if z.strip()]
    assert zeilen[1] == 'set "UEBERSETZT=%~1"', \
        "der Rueckfall steht nicht als erste Anweisung in :t: %r" % zeilen[1]
    assert zeilen[2] == "if not defined NC_KATALOG goto :eof", \
        "ohne Katalog wird trotzdem nachgeschlagen: %r" % zeilen[2]
    assert "2^>nul" in bat, "ein Fehlschlag von findstr wuerde eine Meldung ausgeben"

    # ── (5) KEINE DEUTSCHE AUSGABE MEHR AN EINER SENKE VORBEI. Ein
    # vergessenes echo faellt sonst niemandem auf: eine deutsch gebliebene
    # Zeile sieht aus wie eine, die es noch nicht gibt.
    uebrig = []
    for zeile in bat.split("\n"):
        st = zeile.strip()
        if st.lower().startswith("rem"):
            continue
        # Umleitungen in eine Datei sind keine Bildschirmausgabe.
        if re.search(r'>+\s*"', zeile):
            continue
        # NICHT nur am Zeilenanfang: `if exist ... echo Merkzettel` ist genau
        # die Form, die diese Datei benutzt — ein Pruefer, der nur auf "echo"
        # am Anfang sieht, laesst sie durch. (Beim Mutationstest genau so
        # passiert; deshalb steht es hier.)
        m = re.search(r'(?<![>\w])echo\s+(\S.*)$', zeile)
        if not m:
            continue
        rest = m.group(1).strip()
        if "%" in rest or not re.search(r"[A-Za-z]{4}", rest):
            continue
        # Ein Befehl zum Abtippen ist kein Satz. Dieselbe Ausnahme wie im
        # HTML-Extraktor: "winget install --id Git.Git -e" uebersetzt man
        # nicht — wer es taete, gaebe dem Anwender ein Kommando, das nicht
        # laeuft.
        # v4.2-W124: choco und nssm sind dieselbe Klasse wie winget — der
        # Paketweg Chocolatey und der NSSM-Dienst nennen Befehle zum Abtippen.
        if re.match(r"(winget|choco|nssm|git|pip|python|curl|schtasks|robocopy|"
                    r"powershell|cd|del|mkdir|rmdir)\b", rest):
            continue
        uebrig.append(rest[:60])
    assert not uebrig, "Ausgabe an der Senke vorbei: %r" % uebrig

    # ── (6) DER NACHSCHLAG TRIFFT WIRKLICH. Ohne cmd.exe ist das der Ersatz
    # fuer den Lauf: findstr /b /l /c: wird nachgebildet und jeder eingesammelte
    # Schluessel dagegen geprueft. Ein Schluessel, den findstr nicht faende,
    # waere eine Zeile, die fuer immer deutsch bleibt.
    roh = open("locales/tools.en.tsv", encoding="utf-8").read().split("\n")
    doppelt = {}
    for z in roh:
        if z.startswith("#") or "\t" not in z:
            continue
        doppelt.setdefault(z.split("\t", 1)[0], 0)
        doppelt[z.split("\t", 1)[0]] += 1
    mehrfach = sorted(k for k, n in doppelt.items() if n > 1)
    assert not mehrfach, "doppelte Schluessel im Katalog: %r" % mehrfach[:5]

    def _findstr(schluessel):
        """findstr /b /l /c:"<schluessel><TAB>" — literal, am Zeilenanfang."""
        muster = schluessel + "\t"
        return [z for z in roh if z.startswith(muster)]

    kat = _it.katalog("en")
    for schluessel in sorted(gefunden):
        treffer = _findstr(schluessel)
        assert len(treffer) == 1, \
            "findstr faende %d Zeilen fuer %r" % (len(treffer), schluessel[:60])
        wert = treffer[0].split("\t", 1)[1]
        assert wert.strip(), "leere Uebersetzung fuer %r" % schluessel[:60]
        assert kat[schluessel] == wert
    # Und der Melder muss anschlagen — sonst prueft er nichts.
    assert not _findstr("diesen Text gibt es im Katalog nicht")

    # ── (7) KEIN SCHLUESSEL MIT WERT. Ein Text mit %ZIEL% darin steht erst zur
    # Laufzeit fest und traefe nie. Dafuer gibt es die *_wert-Senken — der
    # feste Teil ist der Schluessel, der Wert wird angehaengt.
    # v4.2-W123: getrennt nach Herkunft. Die Shell-Werkzeuge tragen seit W123
    # gewollt printf-FORMATE als Schluessel (tf "Gefunden: %s" "$x") — der
    # Wert kommt erst NACH dem Nachschlag hinein, der Schluessel trifft also.
    # Fuer Batch gilt die Regel unveraendert und ohne Ausnahme; fuer die Shell
    # gilt sie fuer alles, was KEINE printf-Konversion ist: ein %NAME% bleibt
    # auch dort ein Laufzeitwert, der nie trifft.
    bat_schluessel = (set(_it._BAT_SENKEN.findall(bat)) | set(_it._BAT_WERT_GUT.findall(bat))
                      | set(_it._BAT_FRAGEN.findall(bat)))
    mit_wert = [k for k in bat_schluessel if "%" in k]
    assert not mit_wert, "Batch-Schluessel mit Laufzeitwert: %r" % mit_wert[:3]
    mit_wert = [k for k in gefunden if "%" in _it._PLATZHALTER.sub("", k)]
    assert not mit_wert, "Schluessel mit Laufzeitwert: %r" % mit_wert[:3]

    ok("v4.2-W8: install.bat spricht Englisch \u2014 ein Katalog fuer beide Installer")


def _test_v42_w9_oauth_ueberlebt_neustart_und_stoerung():
    """v4.2-W9: der gespeicherte OAuth-Zustand darf nicht luegen."""
    import asyncio as _asyncio
    import json as _json
    import logging as _logging

    import nc.twitchoauth as _tw
    import nc.ytoauth as _yt

    # Antwort-Attrappe: die beiden Module reden nur ueber aiohttp mit der
    # Aussenwelt, und genau die Antwort ist hier der Prueffall.
    class _Antwort:
        def __init__(self, status, payload):
            self.status, self._p = status, payload

        async def json(self, content_type=None):
            return self._p

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Sitzung:
        def __init__(self, r):
            self._r = r

        def post(self, *a, **k):
            return self._r

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Aio:
        def __init__(self, r):
            self._r = r

        def ClientSession(self):
            return _Sitzung(self._r)

        def ClientTimeout(self, **k):
            return None

    alt_level = _logging.getLogger("TikTokBot").level
    _logging.getLogger("TikTokBot").setLevel(_logging.CRITICAL)
    umgebung = {k: os.environ.get(k) for k in
                ("TWITCH_CLIENT_ID", "TWITCH_CLIENT_SECRET",
                 "YOUTUBE_CLIENT_ID", "YOUTUBE_CLIENT_SECRET")}
    try:
        os.environ.update(TWITCH_CLIENT_ID="x", TWITCH_CLIENT_SECRET="y",
                          YOUTUBE_CLIENT_ID="x", YOUTUBE_CLIENT_SECRET="y")
        d = _ph.verzeichnis()
        pt = os.path.join(d, "twitch_oauth.json")
        py = os.path.join(d, "youtube_oauth.json")
        _tw.configure(pt)
        _yt.configure(py)

        # ── (1) DER PFAD IST ABSOLUT. bot.py reicht "recordings/..." herein,
        # also relativ zum Arbeitsverzeichnis. Ein Start aus einem anderen
        # Verzeichnis haette den Store woanders gesucht — und der gespeicherte
        # Token waere weg gewesen, ohne dass irgendetwas scheitert.
        _tw.configure("recordings/twitch_oauth.json")
        assert os.path.isabs(_tw._state["store_path"]), \
            "twitchoauth: Store-Pfad bleibt relativ"
        _yt.configure("recordings/youtube_oauth.json")
        assert os.path.isabs(_yt._state["store_path"]), \
            "ytoauth: Store-Pfad bleibt relativ"
        _tw.configure(pt)
        _yt.configure(py)

        # ── (2) _save SCHREIBT NUR EINE VERBINDUNG, NIE IHRE ABWESENHEIT.
        # set_channel() rief _save(); war der Refresh-Token im Speicher gerade
        # geleert, ueberschrieb ein KANALNAME die gespeicherte Verbindung mit
        # einem leeren Token. Loeschen laeuft ausschliesslich ueber forget().
        _yt._state["refresh"] = "rt-gut"
        _yt._save()
        _yt._state["refresh"] = ""
        _yt.set_channel("Mein Kanal")
        with open(py, encoding="utf-8") as f:
            assert _json.load(f)["refresh_token"] == "rt-gut", \
                "ein Kanalname hat die gespeicherte Verbindung geloescht"

        # ── (3) EINE STOERUNG IST KEIN TOTER TOKEN. Twitch warf den
        # Refresh-Token bei JEDEM ausbleibenden Access-Token weg — also auch
        # bei einem 500er oder einem Wartungsfenster. Der Betreiber musste
        # dann neu autorisieren, obwohl an seinem Token nie etwas falsch war.
        _tw._state.update(refresh="rt-gut", access="", access_exp=0.0)
        _tw._save()
        _asyncio.run(_tw.access_token(_Aio(_Antwort(500, {"message": "Internal Server Error"}))))
        assert _tw._state["refresh"] == "rt-gut" and os.path.exists(pt), \
            "ein 500er von Twitch kostet die gespeicherte Verbindung"
        _yt._state.update(refresh="rt-gut", access="", access_exp=0.0)
        _yt._save()
        _asyncio.run(_yt.access_token(_Aio(_Antwort(503, {"error": "backendError"}))))
        assert _yt._state["refresh"] == "rt-gut" and os.path.exists(py), \
            "eine Google-Stoerung kostet die gespeicherte Verbindung"

        # ── (4) PLATTE UND SPEICHER SAGEN DASSELBE. ytoauth leerte den toten
        # Token NUR im Speicher; auf der Platte blieb er liegen. Beim naechsten
        # Neustart las _load() ihn zurueck, status() meldete "ready" und das
        # Panel zeigte "verbunden" — waehrend kein einziger Aufruf durchging.
        # DAS ist das Bild "muss staendig neu verbinden".
        _asyncio.run(_yt.access_token(_Aio(_Antwort(400, {"error": "invalid_grant"}))))
        assert not _yt._state["refresh"], "der tote Token bleibt im Speicher"
        assert not os.path.exists(py), \
            "der tote Token bleibt auf der Platte — er kommt beim Neustart zurueck"
        _yt._load()
        assert not _yt._state["refresh"], "der tote Token kommt beim Neustart zurueck"
        _tw._state.update(refresh="rt-gut", access="", access_exp=0.0)
        _tw._save()
        _asyncio.run(_tw.access_token(_Aio(_Antwort(400, {"message": "Invalid refresh token"}))))
        assert not _tw._state["refresh"] and not os.path.exists(pt), \
            "twitchoauth raeumt die abgelehnte Verbindung nicht ab"

        # ── (5) DAS PANEL DARF NICHT LUEGEN. "abgelaufen" und "nie verbunden"
        # sahen gleich aus; der Betreiber musste raten, ob er neu verbinden
        # oder erst die Google-Konsole pruefen muss.
        st = _yt.status()
        assert st["expired"] is True, "status() verschweigt den Ablauf"
        assert "invalid_grant" in st["last_error"], st["last_error"]
        assert st["last_error_ts"] > 0
        assert st["ready"] is False
        # Nach einer Handabmeldung ist nichts "abgelaufen" — nur leer.
        _yt._state["refresh"] = "rt-gut"
        _yt._save()
        _yt.forget()
        assert _yt.status()["expired"] is False, \
            "forget() laesst einen alten Fehlergrund stehen"
    finally:
        for k, v in umgebung.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        _logging.getLogger("TikTokBot").setLevel(alt_level)

    # ── (6) DER FEHLERKANAL. Ein nicht schreibbarer Store hiess bisher
    # log.warning — und ein ERROR-Log zeigt warning NIE (CLAUDE.md). Genau so
    # blieb "der Token wird gar nicht gespeichert" unsichtbar.
    for datei in ("nc/ytoauth.py", "nc/twitchoauth.py"):
        quelle = open(datei, encoding="utf-8").read()
        stelle = quelle.find("Store nicht schreibbar")
        assert stelle > 0, "%s meldet einen unschreibbaren Store gar nicht" % datei
        umfeld = quelle[max(0, stelle - 400):stelle + 200]
        assert "log.error" in umfeld, \
            "%s meldet den unschreibbaren Store nicht auf error" % datei

    ok("v4.2-W9: OAuth \u2014 Stoerung kostet keinen Token, toter Token ueberlebt "
       "keinen Neustart")


def _test_v42_w10_cookies_reparieren_und_selbst_holen():
    """v4.2-W10: die kaputte cookies.txt wird wirklich repariert — und der Bot
       holt sich fehlende Anti-Bot-Tokens selbst.

       Hintergrund, damit das hier niemand als Formalie liest: die alte
       "Reparatur" hat den Text nur durchgereicht. Genau die drei Sachen, an
       denen MozillaCookieJar TATSAECHLICH stirbt — Domain-Flag passt nicht zur
       Domain, mehr oder weniger als sieben Felder, eine Ablaufzeit die keine
       Zahl ist — hat sie nicht angefasst. Ergebnis: 'parse_error' im Deck,
       rc=1 in yt-dlp, leeres dict im Recorder, TikTok 403. Und weil danach
       niemand nachgeprueft hat, ob die geschriebene Datei ladbar ist, blieb
       das im Kreis."""
    import http.server
    import os as _os
    import threading as _th
    import warnings as _warn
    from http.cookiejar import MozillaCookieJar

    import nc.cookieholen as HOL
    import nc.cookies as C

    # http.cookiejar druckt bei JEDEM Formatfehler einen kompletten Traceback
    # als UserWarning ("http.cookiejar bug!"). Dieser Vertrag fuettert es
    # absichtlich mit acht kaputten Dateien — ohne den Filter versinkt die
    # Testausgabe in Tracebacks, die alle erwartet sind, und niemand liest
    # sie mehr. Nur die MELDUNG wird unterdrueckt, nicht der Fehler.
    _alte_filter = _warn.filters[:]
    _warn.filterwarnings("ignore", message=r"http\.cookiejar bug!")

    def _laden(text):
        d = _ph.verzeichnis()
        pfad = _os.path.join(d, "c.txt")
        with open(pfad, "w", encoding="utf-8") as f:
            f.write(text)
        cj = MozillaCookieJar(pfad)
        cj.load(ignore_discard=True, ignore_expires=True)
        return {c.name: c.value for c in cj}, pfad

    # (1) Die Fehlerbilder. Jedes einzelne hat MozillaCookieJar vorher die
    # GANZE Datei verweigern lassen — nicht nur die eine Zeile.
    kaputt = {
        "Domain-Flag FALSE bei .tiktok.com":
            "# Netscape HTTP Cookie File\n"
            ".tiktok.com\tFALSE\t/\tTRUE\t9999999999\tsessionid_ss\tW",
        "Domain-Flag TRUE bei www.tiktok.com":
            "# Netscape HTTP Cookie File\n"
            "www.tiktok.com\tTRUE\t/\tTRUE\t9999999999\tsessionid_ss\tW",
        # Acht Felder: cookiejar entpackt in genau sieben Namen und stirbt an
        # der ganzen Datei. Der ueberzaehlige Tab faellt weg, der Wert wird
        # zusammengezogen — im Netscape-Format ist ein Tab im Wert illegal,
        # also ist er entweder Schaden oder ein leeres Zusatzfeld.
        "acht Felder statt sieben":
            "# Netscape HTTP Cookie File\n"
            ".tiktok.com\tTRUE\t/\tTRUE\t9999999999\tsessionid_ss\t\tW",
        "Ablaufzeit 'Session' statt Zahl":
            "# Netscape HTTP Cookie File\n"
            ".tiktok.com\tTRUE\t/\tTRUE\tSession\tsessionid_ss\tW",
        "Leerzeile vor dem Kopf":
            "\n# Netscape HTTP Cookie File\n"
            ".tiktok.com\tTRUE\t/\tTRUE\t9999999999\tsessionid_ss\tW",
        "BOM vor dem Kopf":
            "\ufeff# Netscape HTTP Cookie File\n"
            ".tiktok.com\tTRUE\t/\tTRUE\t9999999999\tsessionid_ss\tW",
        "Spaces statt Tabs (Copy-Paste)":
            "# Netscape HTTP Cookie File\r\n"
            ".tiktok.com FALSE / TRUE 9999999999 sessionid_ss W\r\n",
        "gar kein Kopf":
            ".tiktok.com\tTRUE\t/\tTRUE\t9999999999\tsessionid_ss\tW\n",
    }
    for was, roh in kaputt.items():
        try:
            _laden(roh)
            raise AssertionError(
                "Testfall '%s' laedt bereits roh — er prueft nichts mehr" % was)
        except AssertionError:
            raise
        except Exception:
            pass
        text, anzahl = C._cookies_input_to_netscape(roh)
        assert anzahl == 1, "%s: %d Cookies erkannt statt 1" % (was, anzahl)
        got, _ = _laden(text)
        assert got.get("sessionid_ss") == "W", \
            ("%s: nach der Reparatur nicht ladbar/falscher Wert (%r) — genau "
             "hier kam vorher 'parse_error' her" % (was, got))
    ok("v4.2-W10: %d Formatfehler repariert, die cookiejar vorher toeteten"
       % len(kaputt))

    # (2) Ein leerer Wert ist ein Cookie, kein Muell. Vorher fiel er raus,
    # weil strip() den letzten Tab frisst und dann sechs Felder uebrig sind.
    text, anzahl = C._cookies_input_to_netscape(
        "# Netscape HTTP Cookie File\n.tiktok.com\tTRUE\t/\tTRUE\t0\tmsToken\t")
    assert anzahl == 1, "Cookie mit leerem Wert verschwindet (%d)" % anzahl

    # (3) Der Leser gibt nicht mehr leer zurueck, nur weil das Format krumm ist.
    # Das ist der Pfad, an dem der Recorder ohne Cookies losfuhr.
    d = _ph.verzeichnis()
    pfad = _os.path.join(d, "c.txt")
    with open(pfad, "w", encoding="utf-8") as f:
        f.write("# Netscape HTTP Cookie File\n"
                ".tiktok.com\tFALSE\t/\tTRUE\t9999999999\tsessionid_ss\tECHT\n")
    jar, normalisiert = C.lade_jar(pfad)
    assert normalisiert is True and {c.name for c in jar} == {"sessionid_ss"}

    class _Still:
        def __getattr__(self, n):
            return lambda *a, **k: None
    C.configure(datei=pfad, log=_Still())
    C.CACHE.pop("v", None)
    assert C.load_dict().get("sessionid_ss") == "ECHT", \
        "load_dict laeuft bei krummem Format immer noch leer — das ist der 403"
    C.CACHE.pop("v", None)
    # ... und die Datei bleibt dabei unangetastet. Ein Leser, der nebenbei
    # schreibt, ist die Sorte Nebenwirkung, die man nachts nicht sucht.
    assert "FALSE\t/" in open(pfad, encoding="utf-8").read(), \
        "lade_jar hat die Datei umgeschrieben"
    ok("v4.2-W10: krumme cookies.txt wird gelesen statt verworfen, ohne sie anzufassen")

    # (4) Der Auto-Bezug fasst den Login NICHT an. Ein Gast-sessionid ueber
    # einen echten geschrieben waere ein stiller Logout.
    alt = ("# Netscape HTTP Cookie File\n"
           ".tiktok.com\tTRUE\t/\tTRUE\t9999999999\tsessionid_ss\tECHTE_SESSION\n"
           ".tiktok.com\tTRUE\t/\tTRUE\t1000\tttwid\tALT\n"
           ".tiktok.com\tTRUE\t/\tTRUE\t1000\tirgendwas\tBLEIBT\n")
    neu = {"sessionid_ss": ("GAST", ".tiktok.com", 9999999999),
           "odin_tt": ("GAST", ".tiktok.com", 9999999999),
           "ttwid": ("NEU", ".tiktok.com", 9999999999),
           "msToken": ("NEU", ".tiktok.com", 0)}
    text, ergaenzt, ersetzt = HOL.zusammenfuehren(alt, neu, gast=True)
    got, _ = _laden(text)
    assert got["sessionid_ss"] == "ECHTE_SESSION", \
        "Gast-Bezug hat den Login ueberschrieben — das ist der stille Logout"
    assert "odin_tt" not in got, "Gast-odin_tt neben echtem Login = 403"
    assert got["ttwid"] == "NEU" and got["msToken"] == "NEU"
    assert got["irgendwas"] == "BLEIBT", "unbekannter Cookie ging verloren"
    assert ergaenzt == ["msToken"] and ersetzt == ["ttwid"], (ergaenzt, ersetzt)

    # (5) Fremde Domains kommen NICHT in die Datei. Ein Browser-Profil traegt
    # die Cookies aller Seiten; tiktok_cookies.txt liegt im Backup.
    assert HOL._gehoert_zu_tiktok(".tiktok.com")
    assert HOL._gehoert_zu_tiktok("www.tiktok.com")
    for fremd in ("bank.example", "tiktok.com.evil.tld", "nottiktok.com", ""):
        assert not HOL._gehoert_zu_tiktok(fremd), fremd
    ok("v4.2-W10: Gast-Bezug laesst Auth-Cookies in Ruhe, fremde Domains draussen")

    # (6) Geschrieben wird erst, wenn das Ergebnis ladbar ist. Wer zuerst
    # tauscht und dann prueft, hat den funktionierenden Bestand schon weg.
    ziel = _os.path.join(_ph.verzeichnis(), "c.txt")
    with open(ziel, "w", encoding="utf-8") as f:
        f.write("# Netscape HTTP Cookie File\n"
                ".tiktok.com\tTRUE\t/\tTRUE\t9999999999\tsessionid_ss\tALT\n")
    try:
        HOL.schreibe(ziel, "das ist kein Netscape-Format")
        raise AssertionError("schreibe() nimmt unladbaren Text an")
    except AssertionError:
        raise
    except Exception:
        pass
    assert "sessionid_ss\tALT" in open(ziel, encoding="utf-8").read(), \
        "der alte Bestand wurde von einem ungeprueften Schreibvorgang zerstoert"
    try:
        HOL.schreibe(ziel, "# Netscape HTTP Cookie File\n"
                     ".tiktok.com\tTRUE\t/\tTRUE\t0\tttwid\tX\n",
                     auth_pflicht=True)
        raise AssertionError("schreibe() ignoriert auth_pflicht")
    except AssertionError:
        raise
    except Exception:
        pass

    # (7) Der ganze Weg — holen, mischen, schreiben — gegen einen Stub auf
    # dem Loopback. NICHT gegen das echte TikTok: der erste Anlauf dieses
    # Vertrags nahm an, in der CI gaebe es kein Netz, und wurde prompt rot,
    # weil der Runner sehr wohl an tiktok.com kommt. Ein Vertrag, der an der
    # Netzanbindung haengt, prueft nicht das, was er zu pruefen behauptet —
    # und ruft nebenbei bei jedem Lauf einen fremden Dienst.
    class _Stub(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            self.send_response(200)
            self.send_header("Set-Cookie", "ttwid=STUB; Path=/; Max-Age=99999")
            self.send_header("Set-Cookie", "msToken=STUB2; Path=/")
            self.send_header("Content-Length", "2")
            self.end_headers()
            self.wfile.write(b"ok")

        def log_message(self, *a):
            pass

    srv = http.server.HTTPServer(("127.0.0.1", 0), _Stub)
    _th.Thread(target=srv.serve_forever, daemon=True).start()
    try:
        url = "http://127.0.0.1:%d/" % srv.server_address[1]
        nur_lokal = ("127.0.0.1",)

        # Der Abruf liest Set-Cookie …
        geholt = HOL.hole_gastcookies(urls=[url], timeout=5, domains=nur_lokal)
        assert set(geholt) == {"ttwid", "msToken"}, geholt
        assert geholt["ttwid"][0] == "STUB"
        # … und derselbe Abruf mit dem echten Domain-Filter laesst NICHTS
        # durch. Ein Browser-Profil traegt die Cookies aller Seiten.
        assert HOL.hole_gastcookies(urls=[url], timeout=5) == {}

        # Der volle Weg: zwei Tokens dazu, der Login bleibt stehen.
        b1 = HOL.aktualisiere(ziel, quelle="gast", timeout=5,
                              urls=[url], domains=nur_lokal)
        assert b1["ok"] and sorted(b1["added"]) == ["msToken", "ttwid"], b1
        drin, _ = _laden(open(ziel, encoding="utf-8").read())
        assert drin["sessionid_ss"] == "ALT", "der Login ging beim Schreiben verloren"
        assert drin["ttwid"] == "STUB" and drin["msToken"] == "STUB2", drin
        assert _os.path.exists(ziel + ".bak"), "kein Backup vor dem Tausch"

        # Zweiter Lauf, gleiche Werte: nichts geaendert = NICHT schreiben.
        # Sonst wandert die mtime, und das Deck meldet "Cookies frisch",
        # waehrend in Wahrheit alles beim Alten ist.
        vorher = _os.path.getmtime(ziel)
        b2 = HOL.aktualisiere(ziel, quelle="gast", timeout=5,
                              urls=[url], domains=nur_lokal)
        assert b2["ok"] and not b2["added"] and not b2["replaced"], b2
        assert _os.path.getmtime(ziel) == vorher, \
            "unveraenderter Bezug hat die Datei trotzdem neu geschrieben"
    finally:
        srv.shutdown()

    # Und ein gescheiterter Abruf fasst die Datei erst recht nicht an.
    # Toter Port statt abgeschaltetem Netz: deterministisch, ohne Wartezeit.
    import socket as _sock
    _s = _sock.socket()
    _s.bind(("127.0.0.1", 0))
    _tot = "http://127.0.0.1:%d/" % _s.getsockname()[1]
    _s.close()
    vorher = _os.path.getmtime(ziel)
    b3 = HOL.aktualisiere(ziel, quelle="gast", timeout=2, urls=[_tot])
    assert b3["ok"] is False and b3["error"], b3
    assert _os.path.getmtime(ziel) == vorher, \
        "gescheiterter Bezug hat die Datei angefasst"
    ok("v4.2-W10: Abruf, Mischen und Schreiben am Stueck — validiert, "
       "mit Backup, und nur bei echter Aenderung")

    # (9) Und der Monolith haengt wirklich dran. Ohne diese Haken ist alles
    # oben eine Bibliothek, die niemand aufruft.
    b = open("bot.py", encoding="utf-8").read()
    # ANKER GEWANDERT (v4.2-W21, nicht der Vertrag): get_cookie_health steht
    # als gesundheit() in nc/cookies.py — dort, wo lade_jar() selbst liegt.
    # Der Vertrag fragt, ob die Bewertung ueber lade_jar() geht statt direkt
    # ueber MozillaCookieJar.load(); genau das war der Unterschied zwischen
    # "parse_error" und 40 lesbaren Cookies.
    _ckq = open("nc/cookies.py", encoding="utf-8").read()
    # Nur der Rumpf von gesundheit(): `lade_jar(` steht auch in load_dict()
    # und in der Definition selbst — eine Suche ueber die ganze Datei waere
    # gruen geblieben, waehrend gesundheit() laengst direkt parst.
    _gs = _ckq.split("def gesundheit(")[1]
    assert "cj, normalisiert = lade_jar(" in _gs, \
        "gesundheit() laedt wieder direkt — dann ist 'parse_error' zurueck"
    assert "MozillaCookieJar(" not in _gs, \
        "gesundheit() greift wieder selbst zum Parser"
    assert "_nc_cookies_datei.gesundheit()" in b, \
        "der Bot fragt die Bewertung nicht mehr ab"
    assert "_COOKIE_FILE_LOCK = _nc_cookies_datei.DATEI_SPERRE" in b, \
        "zwei Schreib-Locks auf dieselbe Datei sind keiner"
    assert "_nc_cookieholen.configure(proxy_waehler=_pull_proxy_still" in b, \
        "der Auto-Bezug geht ohne Proxy raus — TikTok antwortet der Server-IP mit 403"
    assert "await asyncio.to_thread(_cookies_selbst_holen, \"gast\")" in b, \
        ("der Cookie-Alarm holt nicht selbst nach, bevor er jemanden weckt — "
         "und wenn doch, dann bitte im Thread: der Abruf ist blockierendes "
         "urllib mit bis zu 2x15s, das haelt sonst den ganzen Bot-Loop an")
    # Die Reparatur prueft, BEVOR sie tauscht.
    stelle = b.index("def _ensure_cookie_file_netscape")
    rumpf = rumpf_ab(b, stelle)
    pruefung = rumpf.index("MozillaCookieJar(tmp).load")
    tausch = rumpf.index("os.replace(tmp, COOKIE_FILE)")
    assert pruefung < tausch, \
        "die Reparatur tauscht, bevor sie prueft — ein ungeprueftes Ergebnis"

    # Der Bericht geht als JSON ins Deck, in die Health-Anzeige und nach
    # Telegram — der Wortlaut einer Ausnahme aus urllib, yt-dlp oder einem
    # Browser-Profil traegt Pfade. Er muss durch nach_aussen, und zwar an
    # der Quelle: das ist zugleich die Barriere, die
    # .github/codeql/NcSanitizer.qll kennt. saeubern() taete sachlich
    # dasselbe, aber CodeQL sieht es nicht — und meldete hier prompt zwei
    # py/stack-trace-exposure.
    h = open("nc/cookieholen.py", encoding="utf-8").read()
    assert "_nc_fehlertext.nach_aussen(e," in h, \
        ("nc/cookieholen.py gibt den rohen Ausnahmetext nach aussen — durch "
         "nach_aussen() schicken, nicht durch str(e) und nicht durch "
         "saeubern() (dann faellt die CodeQL-Barriere weg)")
    for muster in ('bericht["error"] = str(e)', "str(e) or e.__class__"):
        assert muster not in h, "roher Ausnahmetext in nc/cookieholen.py: %s" % muster

    from flask import Flask
    from nc.routes import settings as rt
    app = Flask(__name__)
    app.register_blueprint(rt.bp)
    rules = {str(r.rule) for r in app.url_map.iter_rules()}
    assert "/api/cookies/fetch" in rules, "die Bezugs-Route ist nicht registriert"
    haus = open("templates/dashboard.html", encoding="utf-8").read()
    assert "/api/cookies/fetch" in haus and "function fetchCookies(" in haus, \
        "das Deck kann den Bezug nicht ausloesen"
    ok("v4.2-W10: Bot, Route und Deck haengen am Auto-Bezug")
    _warn.filters[:] = _alte_filter


def _test_v42_w11_videoteil_aus_dem_monolithen():
    """v4.2-W11: das ffmpeg-Handwerk der Upload-Zerlegung liegt in nc/."""
    import asyncio as _asyncio
    import inspect as _inspect
    import ast as _ast

    import nc.ffdiag as _ffdiag
    import nc.videoteil as _vt

    # ── (1) DIE VERSCHATTETE ZWEITKOPIE IST WEG. bot.py importierte
    # nc.ffdiag.ffprobe_duration als _ffprobe_duration UND definierte in
    # split_and_send_video eine verschachtelte Funktion desselben Namens, die
    # den Import verschattete. Zwei gleichnamige Funktionen mit verschiedenem
    # Verhalten in einer Datei — beim naechsten Aufraeumen behaelt jemand die
    # falsche.
    # ANKER GEWANDERT (v4.2-W19, nicht der Vertrag): split_and_send_video
    # steht in telegramversand.py — bot-seitig, weil es telegram.error-
    # Ausnahmen zur Laufzeit braucht. Der Vertrag fragt, ob die vier
    # ffmpeg-Huellen weg sind und _send_one geblieben ist; beides ist von der
    # Datei unabhaengig.
    b = open("telegramversand.py", encoding="utf-8").read()
    baum = _ast.parse(b)
    fn = None
    for n in baum.body:
        if getattr(n, "name", "") == "split_and_send_video":
            fn = n
            break
    assert fn is not None, "split_and_send_video ist verschwunden"
    # Und im Monolithen darf keine zweite Fassung zurueckkommen: dort steht
    # nur noch die duenne Huelle, die durchreicht.
    _bq = open("bot.py", encoding="utf-8").read()
    for _n in _ast.parse(_bq).body:
        if getattr(_n, "name", "") == "split_and_send_video":
            _h = _ast.get_source_segment(_bq, _n) or ""
            assert "_tv.split_and_send_video(" in _h and len(_h.splitlines()) < 20, \
                "bot.py haelt wieder eine eigene Fassung des Versands"
    verschachtelt = {x.name for x in fn.body
                     if isinstance(x, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    for weg in ("_ffprobe_duration", "_split_to_parts", "_reencode_segment",
                "_check_disk_space_for_split"):
        assert weg not in verschachtelt, "%s steht wieder im Monolithen" % weg
    assert "_send_one" in verschachtelt, \
        "_send_one gehoert NICHT nach nc/ — es kennt Telegram"

    # ── (2) SYNC UND ASYNC SIND ZWEI WERKZEUGE, KEINE DUBLETTE.
    # nc.ffdiag.ffprobe_duration ist synchron und richtig so fuer Aufrufer
    # ausserhalb des Event-Loops. nc.videoteil.dauer ist asynchron. Sie
    # zusammenzulegen ist keine Aufraeumarbeit: ein subprocess.run mit 15 s
    # Timeout auf dem Loop friert jede andere Aufnahme, den Restream und das
    # Dashboard fuer 15 Sekunden ein.
    assert not _inspect.iscoroutinefunction(_ffdiag.ffprobe_duration), \
        "nc.ffdiag.ffprobe_duration ist asynchron geworden"
    assert _inspect.iscoroutinefunction(_vt.dauer), \
        "nc.videoteil.dauer ist synchron geworden — das blockiert den Loop"

    # ── (3) DIE BITRATEN-RECHNUNG. Der Fehler, der das alles ausgeloest hat:
    # die Vorfassung nahm CHUNK_SIZE_MB*60 als segment_time — bei 50 waren das
    # 50 MINUTEN je Segment und damit 300-700 MB je Teil, also immer ein 413.
    # Gerechnet wird jetzt aus der ECHTEN Bitrate. Geprueft wird die
    # Kommandozeile, weil genau dort der Rechenfehler landete.
    # v4.2-W120: die Attrappe hat die Form eines echten asyncio-Prozesses —
    # pid, terminate(), communicate(input=None). Vorher fehlten alle drei;
    # nc.kindprozess braucht sie, und ein echter Prozess hat sie immer.
    # Die Aussage unten bleibt: "der haengende Prozess wurde per Signal
    # beendet UND abgeholt" — ob per SIGTERM oder SIGKILL, ist dafuer gleich.
    _naechste_pid = [40000]

    class _Proc:
        def __init__(self, out=b"", rc=0, haenge=False):
            self._out, self._haenge = out, haenge
            # Ein laufender Prozess hat returncode None — ein haengender also
            # auch. Mit 0 sah er fuer jedes Abraeumen schon beendet aus.
            self.returncode = None if haenge else rc
            self.getoetet = False
            _naechste_pid[0] += 1
            self.pid = _naechste_pid[0]

        async def communicate(self, input=None):
            if self._haenge:
                await _asyncio.sleep(3600)
            return self._out, b""

        def terminate(self):
            self.getoetet = True

        def kill(self):
            self.getoetet = True

        async def wait(self):
            self.returncode = -9
            return -9

    gerufen = []

    def _falle(*proc_args, **kw):
        gerufen.append(list(proc_args))

        async def _mach():
            if proc_args[0] == "ffprobe":
                return _Proc(out=_falle.dauer)
            return _Proc(out=b"")
        return _mach()

    _falle.dauer = b"600\n"          # 600 s Laufzeit

    echt = _asyncio.create_subprocess_exec
    tmp = _ph.verzeichnis()
    quelle = os.path.join(tmp, "aufnahme.mp4")
    # 300 MB, aber nur in den Metadaten: kopier_teilen() liest die Groesse
    # per os.path.getsize(), und die liefert truncate() genauso. Vor W90
    # stand hier ein echtes `b"\0" * 300MB` — 0,31 s und 300 MB RSS je Lauf,
    # obwohl der Kommentar daneben schon "sparse" behauptete.
    _ph.attrappe(quelle, 300 * 1024 * 1024)
    try:
        _asyncio.create_subprocess_exec = _falle
        _vt.configure(threads_bg=1, nice_bg=12)
        _asyncio.run(_vt.kopier_teilen(quelle, os.path.join(tmp, "t"), 45))
    finally:
        _asyncio.create_subprocess_exec = echt

    # ff_cmd stellt "nice -n N" voran und schiebt "-threads N" ein — der
    # Aufruf beginnt deshalb NICHT mit "ffmpeg".
    ff = [g for g in gerufen if "ffmpeg" in g]
    assert ff, "kein ffmpeg-Aufruf: %r" % gerufen
    argv = ff[0]
    assert argv[0] == "nice", "der Hintergrund-Split laeuft ohne nice: %r" % argv[:3]
    seg = int(argv[argv.index("-segment_time") + 1])
    # 300 MB / 600 s = 0,5 MB/s. 45 MB mit 10 % Reserve -> 40,5 / 0,5 = 81 s.
    assert seg == 81, "segment_time=%d statt 81 — die Bitraten-Rechnung stimmt nicht" % seg
    assert "-c" in argv and argv[argv.index("-c") + 1] == "copy", \
        "der Kopier-Split kodiert neu"

    # Ohne ffprobe-Dauer: konservativer Rueckfall, NICHT die Bitratenrechnung
    # mit einer geratenen Dauer.
    gerufen.clear()
    _falle.dauer = b""
    try:
        _asyncio.create_subprocess_exec = _falle
        _asyncio.run(_vt.kopier_teilen(quelle, os.path.join(tmp, "t"), 45))
    finally:
        _asyncio.create_subprocess_exec = echt
    argv = [g for g in gerufen if "ffmpeg" in g][0]
    seg = int(argv[argv.index("-segment_time") + 1])
    assert seg == 180, "Rueckfall segment_time=%d statt 180 (45*4)" % seg

    # ── (4) ZEITDECKEL UND KEIN ZOMBIE. Ohne Deckel blockiert ein haengendes
    # ffmpeg den Event-Loop unbegrenzt. Und kill() ALLEIN reicht nicht: ohne
    # wait() bleibt ein Zombie stehen, und nach ein paar hundert Aufnahmen ist
    # die Prozesstabelle voll (F42-B4).
    haenger = _Proc(haenge=True)

    def _falle2(*a, **kw):
        async def _mach():
            return haenger
        return _mach()

    try:
        _asyncio.create_subprocess_exec = _falle2
        # Deckel kuenstlich klein: sonst wartet der Vertrag 300 Sekunden.
        echt_wait = _asyncio.wait_for

        async def _kurz(aw, timeout=None):
            return await echt_wait(aw, timeout=min(timeout or 1, 0.3))
        _asyncio.wait_for = _kurz
        try:
            ergebnis = _asyncio.run(_vt.dauer(quelle))
        finally:
            _asyncio.wait_for = echt_wait
    finally:
        _asyncio.create_subprocess_exec = echt
    assert ergebnis is None, "ein haengendes ffprobe liefert einen Wert"
    assert haenger.getoetet, "der haengende Prozess wurde nicht getoetet"
    assert haenger.returncode == -9, "kill ohne wait — der Zombie bleibt stehen"

    # ── (5) DIE PLATZPROBE. Vor einem Split muss noch einmal die Dateigroesse
    # frei sein; sonst stirbt ffmpeg mittendrin und hinterlaesst halbe Teile.
    # ABER: scheitert die Probe selbst, wird weitergemacht — eine kaputte
    # Messung darf keinen Upload verhindern, der funktioniert haette.
    gemessen = {}

    class _Erg:
        def __init__(self, free):
            self.free = free
    echt_du = _vt.shutil.disk_usage
    try:
        _vt.shutil.disk_usage = lambda pfad: (gemessen.update(pfad=pfad)
                                              or _Erg(1024 * 1024))
        ok_, info = _vt.platz_reicht(quelle)
    finally:
        _vt.shutil.disk_usage = echt_du
    assert ok_ is False, "300 MB Datei bei 1 MB frei gilt als machbar"
    assert gemessen["pfad"] == tmp, \
        "gemessen wurde %r statt des Verzeichnisses der Datei" % gemessen["pfad"]
    try:
        _vt.shutil.disk_usage = lambda pfad: (_ for _ in ()).throw(OSError("kaputt"))
        ok_, info = _vt.platz_reicht(quelle)
    finally:
        _vt.shutil.disk_usage = echt_du
    assert ok_ is True, "eine gescheiterte Platzprobe blockiert den Upload"

    # ── (6) DAS TELEGRAM-LIMIT. 50 MB hart, 45 MB Ziel — die Reserve ist fuer
    # Multipart-Overhead und Container-Metadaten, nicht Zierde.
    assert _vt.TELEGRAM_HARD_MB == 50 and _vt.ZIEL_TEIL_MB == 45
    klein = os.path.join(tmp, "klein.mp4")
    gross = os.path.join(tmp, "gross.mp4")
    _ph.attrappe(klein, 10 * 1024 * 1024)
    _ph.attrappe(gross, 60 * 1024 * 1024)
    assert _vt.zu_gross([klein, gross]) == [gross]
    _vt.wegwerfen([klein, gross])
    assert not os.path.exists(klein) and not os.path.exists(gross)
    _vt.wegwerfen([klein])          # zweimal wegwerfen darf nicht scheitern

    # ── (7) B47: nur ein KAPUTTER CONTAINER wird repariert. Wer hier zu breit
    # erkennt, startet nach jedem beliebigen ffmpeg-Fehler einen Repair-Lauf
    # ueber die volle Dateigroesse.
    assert _vt.ist_kaputter_container("moov atom not found")
    assert _vt.ist_kaputter_container("Invalid data found when processing input")
    assert not _vt.ist_kaputter_container("No space left on device")
    assert not _vt.ist_kaputter_container("")

    ok("v4.2-W11: nc/videoteil \u2014 Bitratenrechnung, Zeitdeckel und Zombie-Schutz "
       "ohne Bot")


def _test_v42_w42_release_text_und_workflow():
    """v4.2-W42: Ein oeffentliches Repo ohne Release ist ein Stand, den niemand
    laden kann.

    Der Release-Text kommt aus nc/version.py — derselben Quelle wie
    Dashboard-Footer und "Was ist neu"-Panel. Wer ihn im Workflow
    zusammenbaut, hat die vierte Kopie derselben Wahrheit; genau daran ist der
    Build-Stempel schon einmal auseinandergelaufen.
    """
    import subprocess as _sp
    import sys as _sys

    # --- 1) Der Text baut, und zwar aus der Versions-Quelle ----------------
    r = _sp.run([_sys.executable, "tools/release_notes.py"],
                capture_output=True, text=True)
    assert r.returncode == 0, r.stderr[:300]
    text = r.stdout
    import nc.version as _v
    assert f"v{_v.VERSION}" in text, "Release-Text nennt die Fassung nicht"
    hl = [c for c in _v.CHANGELOG if c["version"] == _v.VERSION][0]["highlights"]
    assert hl, "keine Highlights fuer die aktuelle Fassung"
    # Jeder Stichpunkt muss drinstehen — sonst veroeffentlicht das Release
    # einen anderen Stand als das Panel.
    for punkt in hl:
        assert punkt in text, "Highlight fehlt im Release-Text: " + punkt[:60]

    # --- 2) Das GitHub-Limit wird eingehalten ------------------------------
    # Der Abschnitt [4.2] im CHANGELOG hat 239.000 Zeichen, das Limit liegt bei
    # 125.000. Wer den Volltext anhaengt, bekommt kein langes Release, sondern
    # gar keins.
    assert len(text) < 125_000, "Release-Text ueber dem GitHub-Limit"
    quelle = open("tools/release_notes.py", encoding="utf-8").read()
    assert "MAX_ZEICHEN" in quelle and "125" in quelle, \
        "kein Laengen-Riegel — ein wachsender Text scheitert sonst erst beim Anlegen"

    # --- 3) Unbekannte Fassung bricht ab, statt Leeres zu liefern ----------
    r2 = _sp.run([_sys.executable, "tools/release_notes.py", "9.9"],
                 capture_output=True, text=True)
    assert r2.returncode != 0, "unbekannte Fassung liefert stillschweigend Text"

    # --- 4) Der Workflow kann wirklich ein Release anlegen -----------------
    roh = open(".github/workflows/release.yml", encoding="utf-8").read()
    assert "workflow_dispatch:" in roh, \
        ("kein manueller Ausloeser — es gibt Umgebungen, aus denen ein Tag-Push "
         "mit HTTP 403 abgelehnt wird; dort waere sonst kein Release moeglich")
    assert 'tags: ["v*"]' in roh, "kein Tag-Ausloeser"
    assert "contents: write" in roh, \
        "ohne contents:write kann der Lauf weder Tag noch Release anlegen"
    assert "tools/release_notes.py" in roh, "Workflow baut den Text selbst zusammen"
    assert "tools/build_release.py" in roh, "Archiv wird nicht gebaut"
    assert "gh release create" in roh and "gh release edit" in roh, \
        "erneuter Lauf scheitert, statt das Release zu aktualisieren"
    ok("v4.2-w42: Release-Text aus nc/version.py, Limit geprueft, Workflow legt Tag und Archiv an")


def _test_v42_w12_kick_rest_aus_dem_monolithen():
    """v4.2-W12: die Kick-REST-Aufrufe liegen in nc/kickapi.py."""
    import ast as _ast
    import asyncio as _asyncio
    import logging as _logging
    import time as _time

    import nc.kickapi as _ka

    # ── (1) DIE KOERPER SIND RAUS. In KickModerator stehen nur noch
    # Durchreicher; wer einen Aufruf wieder dort einbaut, hat zwei Wahrheiten
    # ueber dieselbe Kick-Schnittstelle.
    b = open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(b)
    klasse = next(n for n in baum.body if getattr(n, "name", "") == "KickModerator")
    _zeilen = b.splitlines()

    def _codezeilen(x):
        """Nur Code zaehlen — Kommentar und Leerzeile sind kein Koerper."""
        n = 0
        for z in _zeilen[x.lineno - 1:(x.end_lineno or x.lineno)]:
            z = z.strip()
            if z and not z.startswith("#"):
                n += 1
        return n

    laenge = {x.name: _codezeilen(x)
              for x in klasse.body
              if isinstance(x, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    for name, deckel in (("_get_token", 8), ("timeout_user", 4),
                         ("channel_info", 6), ("update_channel", 7),
                         ("search_category", 7), ("send_message", 12)):
        assert laenge.get(name, 999) <= deckel, \
            "%s ist mit %d Zeilen kein Durchreicher mehr" % (name, laenge.get(name))
    # Aber der BOT-Zustand bleibt im Bot: der Moderations-Logeintrag und
    # last_spoken gehoeren nicht nach nc/.
    quelle_sm = b[b.index("    async def send_message(self, content"):]
    quelle_sm = quelle_sm[:quelle_sm.index("\n    async def ")]
    assert "_modlog(" in quelle_sm and "self.last_spoken" in quelle_sm, \
        "der Moderations-Logeintrag ist nach nc/ gewandert"
    # Ohne Kommentare und Docstrings pruefen: der Modulkopf von nc/kickapi
    # NENNT _modlog und last_spoken, um zu erklaeren, dass sie dort nicht
    # hingehoeren. Ein Textvergleich ueber die rohe Datei schlaegt auf genau
    # dieser Erklaerung an — derselbe Fehler wie in W32, W33 und v4.2-W3.
    ka_baum = _ast.parse(open("nc/kickapi.py", encoding="utf-8").read())
    for knoten in _ast.walk(ka_baum):
        if (isinstance(knoten, (_ast.FunctionDef, _ast.AsyncFunctionDef,
                                _ast.ClassDef, _ast.Module))
                and _ast.get_docstring(knoten)):
            knoten.body = knoten.body[1:]
    ka_code = _ast.unparse(ka_baum)
    for verboten in ("_modlog", "last_spoken"):
        assert verboten not in ka_code, \
            "nc/kickapi kennt Bot-Zustand: %s" % verboten

    # ── (2) DIE ZWEI-TOKEN-REGEL (v4.0-W17). Kick kennt einen APP-Token
    # (client_credentials) und einen USER-Token. Der App-Token darf LESEN, aber
    # weder chatten noch moderieren noch den Kanal aendern — dort antwortet Kick
    # mit einem nackten 401, das nach einem kaputten Schluessel aussieht und in
    # Wahrheit "falsche Token-Art" heisst. Das hat Wochen gekostet; deshalb
    # steht es hier als Vertrag und nicht nur als Kommentar.
    class _Antwort:
        def __init__(self, status=200, payload=None, text=""):
            self.status, self._p, self._t = status, payload, text

        async def json(self, content_type=None):
            return self._p

        async def text(self):
            return self._t

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Sitzung:
        def __init__(self):
            self.rufe = []
            self.antwort = _Antwort(200, {"data": [{"id": 7, "name": "Chess"}]})

        def _merk(self, art, url, **kw):
            eintrag = (art, url, kw.get("headers", {}), kw.get("json"),
                       kw.get("params"), kw.get("data"))
            self.rufe.append(eintrag)
            _alle_rufe.append(eintrag)
            return self.antwort

        def post(self, url, **kw):
            return self._merk("POST", url, **kw)

        def get(self, url, **kw):
            return self._merk("GET", url, **kw)

        def patch(self, url, **kw):
            return self._merk("PATCH", url, **kw)

        async def close(self):
            pass

    # aiohttp wird GESTUBBT, nicht installiert. Der Vertrags-Job der CI zieht
    # nur orjson und flask — eine Regel seit W23, und sie ist richtig: dieser
    # Vertrag prueft NC-Code, nicht aiohttp. Lokal war aiohttp da (es steckt in
    # requirements-smoke.txt), deshalb lief er hier gruen und in der CI rot.
    #
    # Der Stub ist dabei mehr als ein Behelf: er zaehlt mit, mit welchem
    # Zeitdeckel gerufen wird. Ein Kick-Aufruf OHNE Deckel blockiert den
    # Event-Loop unbegrenzt — dieselbe Klasse Fehler wie beim ffmpeg-Split in
    # W11, nur an einer Schnittstelle, die noch oefter haengt.
    class _Deckel:
        def __init__(self, total=None, **kw):
            self.total = total
            _deckel_gesehen.append(total)

    _deckel_gesehen = []
    _alle_rufe = []

    class _AiohttpStub:
        ClientTimeout = _Deckel

        @staticmethod
        def ClientSession(*a, **kw):
            raise AssertionError(
                "der Vertrag reicht immer eine Sitzung herein — wer hier eine "
                "eigene oeffnet, umgeht den Sitzungs-Pool des Bots")

    alt_aiohttp = sys.modules.get("aiohttp")
    sys.modules["aiohttp"] = _AiohttpStub

    speicher = {"kick.user_token": {"access_token": "USER", "expires_at": 1 << 40}}
    alt_level = _logging.getLogger("TikTokBot").level
    _logging.getLogger("TikTokBot").setLevel(_logging.CRITICAL)
    alt_conf = dict(_ka._conf)
    alt_app = dict(_ka.APP_TOKEN)
    try:
        _ka.configure(log=_logging.getLogger("TikTokBot"),
                      get_session=None, time_mod=_time,
                      broadcaster_id_env=4242,
                      client_id="cid", client_secret="csec",
                      cfg_get=lambda k, d=None: speicher.get(k, d),
                      cfg_set=lambda k, v: speicher.__setitem__(k, v),
                      follower_count=None)
        _ka.APP_TOKEN.update(token="APP", exp=_time.monotonic() + 9999)

        # SCHREIBEND -> User-Token
        sitz = _Sitzung()
        sitz.antwort = _Antwort(200, {})
        gut, _ = _asyncio.run(_ka.send_message("hallo", session=sitz))
        assert gut
        art, url, kopf, koerper, _, _ = sitz.rufe[-1]
        assert url == _ka.CHAT_URL and art == "POST"
        assert kopf["Authorization"] == "Bearer USER", \
            "der Chat-POST nimmt nicht den User-Token: %r" % kopf
        assert koerper["type"] == "user", "Kick bekommt den falschen Absendertyp"
        assert koerper["broadcaster_user_id"] == 4242

        # LESEND -> App-Token reicht
        sitz = _Sitzung()
        sitz.antwort = _Antwort(200, {"data": [{"slug": "x", "stream": {}}]})
        _asyncio.run(_ka.channel_info(session=sitz))
        assert sitz.rufe[-1][2]["Authorization"] == "Bearer APP", \
            "der Lese-Aufruf verbraucht unnoetig den User-Token"

        # OHNE User-Token faellt der Chat auf den App-Token zurueck — und die
        # Fehlermeldung MUSS den Grund nennen, sonst sucht der Betreiber am
        # Schluessel statt an der Token-Art.
        speicher.clear()
        sitz = _Sitzung()
        sitz.antwort = _Antwort(401, {}, "Unauthorized")
        gut, fehler = _asyncio.run(_ka.send_message("hallo", session=sitz))
        assert gut is False
        assert "chat:write" in fehler, "die 401 erklaert die Token-Art nicht: %r" % fehler
        assert sitz.rufe[-1][3]["type"] == "bot"

        # ── (3) SEND_LAST WIRD IMMER GESETZT. Es ist die einzige Stelle, an der
        # ein stummer Kick-Chat sichtbar wird (v4.0-W10) — ohne sie meldete die
        # Diagnose ewig "noch kein Sendeversuch", waehrend Kick seit Stunden
        # abweist.
        assert _ka.SEND_LAST["ok"] is False and _ka.SEND_LAST["status"] == 401

        # ── (4) DIE TIMEOUT-DAUER WIRD GEKLEMMT. Kick lehnt alles ausserhalb
        # 1..10080 ab, und eine abgelehnte Moderation sieht im Log aus wie eine
        # durchgefuehrte.
        for rein, raus in ((0, 1), (-5, 1), (999999, 10080), (30, 30)):
            sitz = _Sitzung()
            sitz.antwort = _Antwort(200, {})
            _asyncio.run(_ka.timeout_user(1, rein, "Grund", sitz))
            assert sitz.rufe[-1][3]["duration"] == raus, \
                "Dauer %r wurde zu %r statt %r" % (rein, sitz.rufe[-1][3]["duration"], raus)

        # ── (5) EXAKTER NAMENSTREFFER SCHLAEGT DEN ERSTEN. Kick sortiert nach
        # Beliebtheit — ohne diese Regel waere "Just Chatting" die Antwort auf
        # fast jede Suche.
        sitz = _Sitzung()
        sitz.antwort = _Antwort(200, {"data": [{"id": 1, "name": "Just Chatting"},
                                               {"id": 9, "name": "Chess"}]})
        cid, nam = _asyncio.run(_ka.search_category("chess", session=sitz))
        assert (cid, nam) == (9, "Chess"), "der exakte Treffer verliert: %r" % ((cid, nam),)

        # ── (6) KANAL AENDERN braucht den User-Token, und ohne ihn muss die
        # Meldung den Scope nennen (B164).
        speicher.clear()
        sitz = _Sitzung()
        sitz.antwort = _Antwort(403, {}, "")
        gut, fehler = _asyncio.run(_ka.update_channel(title="Neu", session=sitz))
        assert gut is False and "channel:write" in fehler, fehler
        assert sitz.rufe[-1][0] == "PATCH"

        # ── (7) JEDER KICK-AUFRUF TRAEGT EINEN ZEITDECKEL. Ohne ihn haengt ein
        # stiller Kick-Endpunkt den Event-Loop auf — und mit ihm jede Aufnahme,
        # den Restream und das Dashboard.
        # Gezaehlt wird DECKEL GEGEN ANFRAGE, nicht "es gab welche": beim
        # Mutationstest blieb ein Aufruf ohne Deckel unentdeckt, weil die
        # anderen vier weiterhin einen setzten. Eine Zusage, die man mit vier
        # richtigen Aufrufen erschleichen kann, ist keine.
        assert len(_deckel_gesehen) == len(_alle_rufe), \
            "%d Anfragen, aber nur %d Zeitdeckel — ein Aufruf haengt " \
            "unbegrenzt" % (len(_alle_rufe), len(_deckel_gesehen))
        assert all(t == 15 for t in _deckel_gesehen), \
            "Aufrufe ohne 15-Sekunden-Deckel: %r" % _deckel_gesehen
    finally:
        _ka._conf.clear()
        _ka._conf.update(alt_conf)
        _ka.APP_TOKEN.clear()
        _ka.APP_TOKEN.update(alt_app)
        _logging.getLogger("TikTokBot").setLevel(alt_level)
        if alt_aiohttp is None:
            sys.modules.pop("aiohttp", None)
        else:
            sys.modules["aiohttp"] = alt_aiohttp

    ok("v4.2-W12: Kick-REST in nc/kickapi \u2014 User-Token schreibt, App-Token "
       "liest, SEND_LAST meldet immer")


def _test_v42_w13_gesundheit_und_modki():
    """v4.2-W13: was nur rechnet, rechnet jetzt ausserhalb des Monolithen."""
    import ast as _ast

    import nc.modki as _mk
    import nc.restreamgesundheit as _rg

    # ── (1) DIE ANZEIGE MUSS MESSEN, NICHT NUR ZEIGEN. Drei Fehler der
    # Vorgeschichte (W113, W116, v4.1-W10) hatten dieselbe Form: eine Zahl
    # stand still und galt weiter als Messung. Das ist die gefaehrlichere
    # Haelfte — ein leeres Feld faellt auf, eine eingefrorene Bitrate nicht.

    # W113: nur ZUWACHS zaehlt. ffmpeg schreibt seine Schnappschuesse auch
    # dann weiter, wenn der Ausgang blockiert.
    e = {}
    assert _rg.marke_setzen(e, {"frame": 5}, {"total_size": 50}, 100.0) is True
    assert _rg.marke_setzen(e, {"frame": 5}, {"total_size": 50}, 200.0) is False, \
        "Stillstand gilt als Fortschritt"
    assert e["watch"]["advanced"] == 100.0
    # Bytes ALLEIN reichen auch: ein Standbild sendet weiter.
    assert _rg.marke_setzen(e, {"frame": 5}, {"total_size": 51}, 300.0) is True
    assert e["watch"]["advanced"] == 300.0
    # Muell darf die Marke nicht zuruecksetzen — ffmpeg liefert bei
    # Abbruch teils leere Felder.
    assert _rg.marke_setzen(e, {"frame": "?"}, {"total_size": None}, 400.0) is False
    assert e["watch"]["frame"] == 5 and e["watch"]["advanced"] == 300.0
    assert _rg.marke_setzen(None, {}, {}, 500.0) is False

    # v4.1-W10: blind heisst blind, und zwar EINMAL.
    info = {}
    assert _rg.blind_markieren(info, "Leser tot", 42.0) is True
    assert info["health"]["blind"] is True
    assert info["health"]["blind_reason"] == "Leser tot"
    assert info["health"]["blind_ts"] == 42.0
    assert _rg.blind_markieren(info, "nochmal", 99.0) is False, \
        "die Blind-Meldung feuert dauernd"
    assert info["health"]["blind_ts"] == 42.0, "der erste Grund wird ueberschrieben"
    assert _rg.blind_markieren(None, "x", 1.0) is False

    # W116: tee-Ziel-Fehler verfallen. Ohne Verfall stand eine einmalige
    # Ablehnung von YouTube bis zum Bot-Neustart im Panel, im Alarm und im
    # Selbsttest — man jagt dann einem Zustand von vorgestern hinterher.
    roh = {"youtube": {"ts": 1000.0}, "twitch": {"ts": 1900.0}}
    frisch, verfallen = _rg.frische_tee_fehler(roh, ttl=600, jetzt=2000.0)
    assert verfallen is True and set(frisch) == {"twitch"}, frisch
    # Beide frisch: 1500 - 1000 = 500 < 600.
    frisch, verfallen = _rg.frische_tee_fehler(roh, ttl=600, jetzt=1500.0)
    assert verfallen is False and set(frisch) == {"youtube", "twitch"}
    # ttl <= 0 ist die Notbremse: dann gilt wieder alles, ohne Codeaenderung.
    frisch, verfallen = _rg.frische_tee_fehler(roh, ttl=0, jetzt=10 ** 9)
    assert set(frisch) == {"youtube", "twitch"} and verfallen is False
    assert _rg.frische_tee_fehler(None, ttl=60, jetzt=1.0) == ({}, False)

    # ── (2) DIE ZEIT KOMMT VON AUSSEN. Ohne das liesse sich Verfall nicht
    # pruefen, ohne im Test zu warten — und ein Verfall, den man nicht pruefen
    # kann, ist genau der, der jahrelang nicht stattfindet.
    # Wieder geparst statt gelesen: das Modul-Docstring NENNT time.monotonic(),
    # um zu erklaeren, dass es sie nicht benutzt. Ein Textvergleich schlaegt
    # auf genau dieser Erklaerung an — dasselbe Muster wie in W32, W33,
    # v4.2-W3 und W12.
    rg_baum = _ast.parse(open("nc/restreamgesundheit.py", encoding="utf-8").read())
    for knoten in _ast.walk(rg_baum):
        if (isinstance(knoten, (_ast.FunctionDef, _ast.AsyncFunctionDef,
                                _ast.ClassDef, _ast.Module))
                and _ast.get_docstring(knoten)):
            knoten.body = knoten.body[1:]
    rg_code = _ast.unparse(rg_baum)
    assert "time" not in rg_code, \
        "nc/restreamgesundheit liest die Uhr selbst — dann ist Verfall nicht pruefbar"

    # ── (3) DIE MODELLANTWORT IST DER TEIL, DER SCHIEFGEHT. Ein Sprachmodell
    # antwortet mal mit ```json, mal nackt, mal mit einem Satz davor. Faengt
    # das niemand ab, kippt eine Moderation still ins Nichts.
    assert _mk.lies_klassifikation('{"toxic": 0.9, "question": true}') == \
        {"toxic": 0.9, "question": True}
    assert _mk.lies_klassifikation('```json\n{"toxic": 0.5, "question": false}\n```') == \
        {"toxic": 0.5, "question": False}
    # UNLESBAR ist NICHT unauffaellig. None und {"toxic": 0.0} sind zwei
    # verschiedene Aussagen — sonst gilt ein ausgefallenes Modell als
    # Freispruch.
    assert _mk.lies_klassifikation("Das ist toxisch, wuerde ich sagen.") is None
    assert _mk.lies_klassifikation("") is None
    assert _mk.lies_klassifikation(None) is None

    # Beim Lernen ist die leere Liste richtig: ein unlesbares Ergebnis darf
    # keine Sperrliste erweitern. Im Zweifel wird NICHT gelernt.
    assert _mk.lies_schimpfwoerter("kaputt") == []
    assert _mk.lies_schimpfwoerter('{"nicht": "eine Liste"}') == []
    assert _mk.lies_schimpfwoerter('[{"word": "  Idiot  ", "lang": "DE"}]') == \
        [{"word": "Idiot", "lang": "de"}]
    # Ohne Sprache trotzdem lernen — aber sichtbar ohne.
    assert _mk.lies_schimpfwoerter('[{"word": "x"}]') == [{"word": "x", "lang": "?"}]
    # Leere Woerter fliegen raus, Muell in der Liste ebenso.
    assert _mk.lies_schimpfwoerter('[{"word": "  "}, "text", 5]') == []
    # Ein Modell, das hundert Woerter liefert, darf die Liste nicht fluten.
    viele = "[" + ",".join('{"word": "w%d"}' % i for i in range(50)) + "]"
    assert len(_mk.lies_schimpfwoerter(viele)) == _mk.MAX_WOERTER

    # Die Frage kuerzt den Inhalt: ein Chat-Roman kostet Budget und aendert am
    # Urteil nichts.
    n = _mk.frage(_mk.KLASSIFIKATION, "x" * 5000, 500)
    assert n[0]["role"] == "system" and n[0]["content"] == _mk.KLASSIFIKATION
    assert len(n[1]["content"]) == 500
    assert _mk.frage(_mk.SCHIMPFWOERTER, None, 300)[1]["content"] == ""

    # ── (4) DER AUFRUF BLEIBT IM BOT. ai_chat haengt am Router, am Budget und
    # an der Basen-Rotation — er gehoert nicht nach nc/.
    quelle_mk = open("nc/modki.py", encoding="utf-8").read()
    mk_baum = _ast.parse(quelle_mk)
    for knoten in _ast.walk(mk_baum):
        if (isinstance(knoten, (_ast.FunctionDef, _ast.AsyncFunctionDef,
                                _ast.ClassDef, _ast.Module))
                and _ast.get_docstring(knoten)):
            knoten.body = knoten.body[1:]
    assert "ai_chat" not in _ast.unparse(mk_baum), "nc/modki ruft das Modell selbst"
    b = open("bot.py", encoding="utf-8").read()
    assert "_nc_modki.frage(" in b and "_nc_modki.lies_klassifikation(" in b, \
        "der Bot benutzt nc/modki gar nicht"
    assert "_nc_rgesund.marke_setzen(" in b and "_nc_rgesund.blind_markieren(" in b \
        and "_nc_rgesund.frische_tee_fehler(" in b, \
        "der Bot benutzt nc/restreamgesundheit gar nicht"

    ok("v4.2-W13: Sendeanzeige und Mod-KI rechnen ausserhalb des Monolithen "
       "\u2014 Stillstand ist kein Fortschritt, unlesbar ist kein Freispruch")


def _test_v42_w15_discord_aus_dem_monolithen():
    """v4.2-W15: der Discord-Teil steht in discordbot.py und bekommt alles
    durch EINEN Kanal (nc.botctx.BotKontext).

    WAS HIER NICHT GEPRUEFT WERDEN KANN: ob ein Slash-Command antwortet. Es
    gibt in dieser Umgebung kein Discord-Gateway; test_smoke.py stubbt
    discord.py sogar bewusst weg. Pruefbar ist die FORM — und genau die ist
    hier der Risikotraeger: 1.900 Zeilen sind aus einem Namensraum in einen
    anderen gewandert, in dem 51 Namen vorher implizite Globals waren. Faellt
    einer davon durch, ist er still None und kracht erst im Betrieb.

    Deshalb sind die beiden harten Zusicherungen:
      * jeder Platzhalter in discordbot.py wird von _uebernehmen() belegt,
      * jeder Schluessel, den der Kontext verlangt, existiert in bot.py.
    Zusammen schliessen sie die Luecke, die ein Import-Test offen laesst.
    """
    import ast as _ast
    from nc import botctx as _botctx

    dcb_src = open("discordbot.py", encoding="utf-8").read()
    dcb = _ast.parse(dcb_src)
    bot_src = open("bot.py", encoding="utf-8").read()
    bot = _ast.parse(bot_src)

    # --- 1) Die Architektur-Grenze --------------------------------------
    # discordbot.py darf nicht zurueckimportieren, sonst ist es keine
    # Herausloesung, sondern ein Zirkel mit zwei Dateinamen.
    for datei, baum in (("discordbot.py", dcb), ("nc/botctx.py",
                        _ast.parse(open("nc/botctx.py", encoding="utf-8").read()))):
        for n in _ast.walk(baum):
            if isinstance(n, _ast.Import):
                assert not any(a.name.split(".")[0] == "bot" for a in n.names), \
                    "%s importiert bot" % datei
            if isinstance(n, _ast.ImportFrom):
                assert (n.module or "").split(".")[0] != "bot", \
                    "%s importiert aus bot" % datei
    ok("W15: discordbot.py und nc/botctx.py importieren nicht aus bot.py")

    # --- 2) Jeder Platzhalter wird belegt --------------------------------
    # Platzhalter = Modul-Zuweisung auf exakt None. Lebender Modulzustand
    # (_disc_automod_hist = {} und Konsorten) ist bewusst NICHT None und
    # faellt damit nicht in diese Menge.
    platz = {t.id for n in dcb.body if isinstance(n, _ast.Assign)
             for t in n.targets
             if isinstance(t, _ast.Name)
             and isinstance(n.value, _ast.Constant) and n.value.value is None}
    assert len(platz) > 50, "zu wenige Platzhalter gefunden: %d" % len(platz)

    uebern = next((n for n in dcb.body
                   if isinstance(n, _ast.FunctionDef) and n.name == "_uebernehmen"), None)
    assert uebern is not None, "_uebernehmen fehlt"
    belegt = {t.id for k in _ast.walk(uebern) if isinstance(k, _ast.Assign)
              for t in k.targets if isinstance(t, _ast.Name)}
    global_erklaert = {nm for k in _ast.walk(uebern)
                       if isinstance(k, _ast.Global) for nm in k.names}
    fehlt = sorted(platz - belegt)
    assert not fehlt, "Platzhalter ohne Belegung in _uebernehmen: %s" % fehlt
    # Ohne `global` schriebe die Zuweisung nur eine lokale Variable — die
    # Funktion liefe gruen durch und der Modulname bliebe None.
    fehlt_global = sorted(platz - global_erklaert)
    assert not fehlt_global, "in _uebernehmen nicht global erklaert: %s" % fehlt_global
    ok("W15: alle %d Platzhalter werden von _uebernehmen belegt" % len(platz))

    # --- 3) Der Kontext verlangt nichts, was es nicht gibt ---------------
    bot_top = set()
    for n in bot.body:
        if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef, _ast.ClassDef)):
            bot_top.add(n.name)
        elif isinstance(n, _ast.Assign):
            bot_top.update(t.id for t in n.targets if isinstance(t, _ast.Name))
        elif isinstance(n, _ast.AnnAssign) and isinstance(n.target, _ast.Name):
            bot_top.add(n.target.id)
    fehlt = [k for k in list(_botctx.BEFEHLE) + list(_botctx.SCHALTER)
             if k not in bot_top]
    assert not fehlt, "vom Kontext verlangt, in bot.py nicht definiert: %s" % fehlt
    # Und umgekehrt: die Platzhalter muessen die Schluesselmengen abdecken.
    # ANKER GEWANDERT (v4.2-W109): die geteilten Telegram-Handler haben keine
    # Einzel-Platzhalter mehr, sie landen im Woerterbuch _TG_HANDLER. Gefragt
    # bleibt, ob jeder Schluessel drueben ankommt — fuer SCHALTER als
    # Platzhalter, fuer BEFEHLE ueber die Uebernahme des ganzen Woerterbuchs.
    fehlt = [k for k in _botctx.SCHALTER if k not in platz]
    assert not fehlt, "Schluessel ohne Platzhalter in discordbot.py: %s" % fehlt
    assert "_TG_HANDLER.update(ctx.befehle)" in _ast.unparse(uebern), \
        "die geteilten Telegram-Handler erreichen discordbot.py nicht mehr"
    ok("W15: alle %d Kontext-Schluessel existieren beidseitig"
       % (len(_botctx.BEFEHLE) + len(_botctx.SCHALTER)))

    # --- 4) Der Kontext meldet Luecken beim BAU, nicht im Betrieb --------
    def _voll():
        return dict(
            log=None, spawn=print, loop_fehler=print, modlog=print,
            auto_on=print, cfg_get=print, cfg_set=print, discord_notify=print,
            discord_post_user=print, disc_state_get=print, disc_state_set=print,
            whisper_transcribe=print, add_tracking=print, azrael_chat=print,
            clip_moment=print, einladung_merken=print, kick_mod=None,
            fehler_schlange=None, boot_ts=0.0, bot_app_holen=lambda: None,
            befehle={k: print for k in _botctx.BEFEHLE},
            schalter={k: "" for k in _botctx.SCHALTER})

    _botctx.BotKontext(**_voll())                       # vollstaendig: geht
    for kaputt, was in (("befehle", "fehlt"), ("schalter", "fehlt"),
                        ("befehle", "zuviel"), ("schalter", "zuviel")):
        arg = _voll()
        d = dict(arg[kaputt])
        if was == "fehlt":
            d.pop(sorted(d)[0])
        else:
            d["ein_name_den_es_nicht_gibt"] = ""
        arg[kaputt] = d
        try:
            _botctx.BotKontext(**arg)
        except ValueError:
            pass
        else:
            raise AssertionError("BotKontext akzeptiert %s/%s" % (kaputt, was))
    # Ein nicht-aufrufbarer Befehl ist der stille Fall: er kracht sonst erst
    # beim Aufruf, mitten in einem Slash-Command.
    arg = _voll()
    arg["befehle"] = dict(arg["befehle"], diag="kein Handler")
    try:
        _botctx.BotKontext(**arg)
    except ValueError:
        pass
    else:
        raise AssertionError("BotKontext akzeptiert einen nicht-aufrufbaren Befehl")
    ok("W15: BotKontext meldet fehlende, unbekannte und tote Eintraege")

    # --- 5) Eingefroren -------------------------------------------------
    k = _botctx.BotKontext(**_voll())
    try:
        k.spawn = print
    except Exception:
        pass
    else:
        raise AssertionError("BotKontext laesst sich nachtraeglich umbiegen")
    ok("W15: BotKontext ist eingefroren")

    # --- 6) Der Einladungs-Pfad ------------------------------------------
    # Das war der EINE Fall, den das blosse Verschieben kaputtgemacht haette:
    # _ensure_discord_invite schrieb per `global` nach DISCORD_INVITE_URL —
    # in discordbot.py haette das nur die dortige Kopie gesetzt, waehrend der
    # Announcer in bot.py weiter die leere URL verschickt haette.
    assert "DISCORD_INVITE_URL" not in platz, \
        "DISCORD_INVITE_URL darf in discordbot.py nicht existieren"
    for n in _ast.walk(dcb):
        assert not (isinstance(n, _ast.Global) and "DISCORD_INVITE_URL" in n.names), \
            "discordbot.py bindet DISCORD_INVITE_URL selbst"
    setzer = next((n for n in bot.body if isinstance(n, _ast.FunctionDef)
                   and n.name == "_discord_einladung_merken"), None)
    assert setzer is not None, "_discord_einladung_merken fehlt in bot.py"
    raum = {"DISCORD_INVITE_URL": ""}
    exec(compile(_ast.Module(body=[setzer], type_ignores=[]), "<w15>", "exec"), raum)
    raum["_discord_einladung_merken"]("https://discord.gg/neu")
    assert raum["DISCORD_INVITE_URL"] == "https://discord.gg/neu"
    raum["_discord_einladung_merken"]("https://discord.gg/spaeter")
    assert raum["DISCORD_INVITE_URL"] == "https://discord.gg/neu", \
        "der Setzer ueberschreibt einen bereits gesetzten Invite"
    ok("W15: der Invite landet in bot.py und wird nie ueberschrieben")

    # --- 7) Der Import bleibt spaet --------------------------------------
    # Am Dateikopf wuerde er die Reihenfolge festschreiben, bevor .env steht —
    # dieselbe Falle wie Modul-Konstanten, die .env einfrieren (CLAUDE.md).
    for n in bot.body:
        if isinstance(n, _ast.Import):
            assert not any(a.name == "discordbot" for a in n.names), \
                "bot.py importiert discordbot am Dateikopf"
    tief = [n for n in _ast.walk(bot) if isinstance(n, _ast.Import)
            and any(a.name == "discordbot" for a in n.names)]
    assert len(tief) == 1, "discordbot wird %dx importiert, erwartet 1" % len(tief)
    ok("W15: bot.py importiert discordbot erst zur Laufzeit, genau einmal")

    # --- 8) Die Datei laesst sich wirklich importieren -------------------
    # Der Formcheck oben liest nur den AST. Ein falscher Modulpfad in einem
    # der zwoelf nc-Importe faellt dabei NICHT auf — er kraecht erst beim
    # Start des Bots, also in Produktion. discord.py fehlt in der CI; genau
    # deshalb faengt discordbot.py den Import ab und setzt discord = None.
    import importlib
    _m = importlib.import_module("discordbot")
    assert _m.log is None, "discordbot haelt beim Import schon Bot-Zustand"
    ok("W15: discordbot.py importiert ohne discord.py und ohne bot.py")

    # --- 9) Die Slash-Commands sind vollstaendig mitgewandert ------------
    def _slash(baum):
        namen = set()
        for n in _ast.walk(baum):
            if not isinstance(n, _ast.Call):
                continue
            f = n.func
            if isinstance(f, _ast.Attribute) and f.attr == "command":
                for kw in n.keywords:
                    if kw.arg == "name" and isinstance(kw.value, _ast.Constant):
                        namen.add(kw.value.value)
        return namen
    assert not _slash(bot), "in bot.py stehen noch Slash-Commands: %s" % sorted(_slash(bot))
    assert len(_slash(dcb)) >= 40, "zu wenige Slash-Commands gewandert: %d" % len(_slash(dcb))
    ok("W15: %d Slash-Commands stehen in discordbot.py, keiner mehr in bot.py"
       % len(_slash(dcb)))


def _test_v42_w16_relaykommando():
    """v4.2-W16: die ffmpeg-Zeile des Relays steht in nc/restreamcmd.py.

    WARUM DAS DIE WICHTIGE HAELFTE IST: 188 Zeilen, die nichts tun ausser eine
    Argumentliste zu bauen — vollstaendig pruefbar, OHNE dass ein ffmpeg
    laeuft. Im Monolithen war genau dieser Teil faktisch ungetestet: er hing an
    zwanzig Bot-Globals, und in dieser Umgebung gibt es kein ffmpeg. Geprueft
    wird deshalb, WAS aufgerufen wird — nicht, was das Werkzeug daraus macht.

    Der Rumpf ist bitgenau aus bot.py uebernommen; die Zusicherungen unten sind
    NEU und haetten im Monolithen nicht geschrieben werden koennen.
    """
    import os as _os
    import tempfile as _tf
    from nc import restreamcmd as _rc
    from nc import restream_targets as _rst
    from nc.ffdiag import redact_cmd_for_log

    KEKS = "sessionid=GEHEIM123; tt_csrf=ABC"
    schrift = _tf.NamedTemporaryFile(suffix=".ttf", delete=False)
    schrift.write(b"x"); schrift.close()
    avatar = _tf.NamedTemporaryFile(suffix=".png", delete=False)
    avatar.write(b"x"); avatar.close()

    def _konf(**ab):
        basis = dict(
            cookie_header=lambda: KEKS,
            pick_pull_proxy=lambda: "",
            # Dieselben Schluessel, die nc/ffmpeg_filters erwartet — ein
            # unvollstaendiges Dict flog dort frueher als KeyError auf, und
            # zwar erst im Studio-Zweig, also nur bei einem von zwei Layouts.
            restream_overlay_files=lambda rid=None: {
                k: "/tmp/ov_%s.txt" % k for k in
                ("alert", "brand", "caption", "chat", "follow", "goal",
                 "react", "source", "title")},
            FFMPEG_THREADS_LIVE=3, FFMPEG_THREADS_RELAY=2,
            RESTREAM_AVATAR=avatar.name, RESTREAM_BITRATE_K=6000,
            # v4.2-W32: leer = kein Animationspfad, der Bauer nimmt das
            # Standbild. Genau der Rueckfall, den dieser Test durchspielt.
            RESTREAM_AVATAR_ALPHA="", RESTREAM_AVATAR_H=360,
            RESTREAM_AVATAR_LOOP="",
            RESTREAM_CANVAS_H=1080, RESTREAM_CANVAS_W=1920,
            RESTREAM_FONT=schrift.name, RESTREAM_FPS=30,
            RESTREAM_LOW_LATENCY=True, RESTREAM_OVERLAY=False,
            RESTREAM_OVERLAY_HTML_FPS=1, RESTREAM_RELAY_BITRATE_K=3500,
            RESTREAM_RELAY_PRESET="ultrafast", RESTREAM_X264_PRESET="veryfast",
            RESTREAM_UA="UA/1.0", TTS_CH=2, TTS_SR=44100, TTS_VOICE_GAIN="1.8")
        basis.update(ab)
        _rc.configure(**basis)

    # --- 1) configure schweigt nicht ------------------------------------
    # nc/restream_targets ignoriert unbekannte Schluessel bewusst. Hier waere
    # das falsch: ein Tippfehler liefe mit dem Default weiter — andere Bitrate,
    # anderes Preset, kein Overlay, und NICHTS wird rot. Sichtbar erst auf dem
    # Sendebild.
    for kaputt in ("unbekannt", "fehlt"):
        try:
            if kaputt == "unbekannt":
                _konf(RESTREAM_TIPPFEHLER=1)
            else:
                _rc.configure(RESTREAM_FPS=30)
        except ValueError:
            pass
        else:
            raise AssertionError("configure akzeptiert %s" % kaputt)
    _konf()
    ok("W16: configure meldet unbekannte und fehlende Schluessel")

    FLV = "https://pull.tiktok.com/stage/x.flv"
    HLS = "https://pull.tiktok.com/stage/x.m3u8"
    ZIEL = ("kick", "rtmps://ingest.example/app/SCHLUESSEL")

    # --- 2) Der Cookie steht drin — und faellt beim Loggen raus ----------
    # F4. Der gebaute Befehl traegt die komplette TikTok-Session in -headers.
    # Wer ihn ungefiltert loggt, schreibt sie ins Klartext-Log.
    cmd = _rc.build(FLV, "", "", targets=[ZIEL])
    kopf = cmd[cmd.index("-headers") + 1]
    assert "sessionid=GEHEIM123" in kopf, "Cookie-Header fehlt im Befehl"
    sauber = redact_cmd_for_log(cmd)
    assert not any("GEHEIM123" in str(a) for a in sauber), \
        "redact_cmd_for_log laesst die Session durch"
    assert any("Cookie: <redacted>" in str(a) for a in sauber), \
        "der Cookie wird gar nicht erst erkannt"
    # Und der Referer bleibt stehen — Redaktion darf nicht zu viel wegnehmen,
    # sonst ist das Log fuer die Fehlersuche wertlos.
    assert any("Referer:" in str(a) for a in sauber), "Redaktion frisst den Referer"
    ok("W16: Cookie im Befehl, im Log redigiert, Referer bleibt (F4)")

    # --- 3) B124: 403 und 404 sind TERMINAL, kein Wiederverbinden --------
    # Auf "4xx,5xx" haemmerte ffmpeg 30s lang die tote Quell-URL, bis der
    # ganze tee kollabierte ("All tee outputs failed"). Genau das war die
    # Ursache der Restream-Abbrueche alle paar Minuten.
    codes = cmd[cmd.index("-reconnect_on_http_error") + 1]
    assert "403" not in codes and "404" not in codes, \
        "403/404 wieder im Reconnect: %s" % codes
    assert "429" in codes and "503" in codes, "vorübergehende Codes fehlen: %s" % codes
    ok("W16: Reconnect nur auf wirklich voruebergehende HTTP-Codes")

    # --- 4) HLS braucht PTS, FLV nicht ----------------------------------
    # TikTok liefert HLS-Pakete OHNE PTS und mit nicht-monotonem DTS; ohne
    # +genpts+igndts bricht der FLV-Muxer mit rc=187 ab.
    hls = _rc.build(HLS, "", "", targets=[ZIEL])
    assert "+genpts+igndts+flush_packets" in hls, "HLS ohne genpts/igndts"
    assert "-multiple_requests" in hls, "HLS ohne multiple_requests"
    assert "+genpts" not in " ".join(cmd), "FLV bekommt faelschlich genpts"
    assert "+flush_packets" in cmd, "FLV ohne flush_packets"
    ok("W16: HLS erhaelt +genpts+igndts, FLV nicht")

    # --- 5) Thread-Deckel, niemals nice ---------------------------------
    # Ohne -threads greift x264 ~1.5x alle Kerne; das war die Ursache fuer
    # Load 113 auf 8 Kernen. nice waere hier falsch: das Sendebild hat Vorrang.
    assert cmd[0] == "ffmpeg" and cmd[1:3] == ["-threads", "3"], cmd[:4]
    relay = _rc.build(FLV, "", "", targets=[ZIEL], relay_profile=True)
    assert relay[1:3] == ["-threads", "2"], relay[:4]
    assert "nice" not in cmd and "nice" not in relay, "nice im Sendepfad"
    ok("W16: Relay-Profil deckelt auf 2, Transcode-Profil auf 3, nie nice")

    # --- 6) Die Eingangs-Reihenfolge bestimmt die Filter-Indizes --------
    # Ein vertauschter Index legt nichts lahm, das man SIEHT: ffmpeg mischt
    # dann den falschen Stream. Deshalb hier hart nachgerechnet.
    _konf(RESTREAM_OVERLAY=True)
    voll = _rc.build(FLV, "", "", transcode=True, tts_fifo="/tmp/tts.fifo",
                     rid=1, targets=[ZIEL])
    eing = [voll[i + 1] for i, a in enumerate(voll) if a == "-i"]
    assert eing[0] == FLV, eing
    assert eing[1] == "/tmp/tts.fifo", "TTS ist nicht Eingang 1: %s" % eing
    assert eing[2] == avatar.name, "Avatar ist nicht Eingang 2: %s" % eing
    fc = voll[voll.index("-filter_complex") + 1]
    assert "[1:a]" in fc or "[1]" in fc, "Filtergraph greift nicht auf Eingang 1: %s" % fc[:120]
    assert "[2:v]" in fc, "Avatar-Overlay greift nicht auf Eingang 2: %s" % fc[:120]
    ok("W16: TTS ist Eingang 1, Avatar Eingang 2, der Filtergraph zeigt darauf")

    # --- 7) copy heisst copy --------------------------------------------
    _konf()
    kopie = _rc.build(FLV, "", "", targets=[ZIEL])
    assert "-c:v" in kopie and kopie[kopie.index("-c:v") + 1] == "copy"
    assert "libx264" not in kopie, "copy-Modus kodiert Video neu"
    trans = _rc.build(FLV, "", "", transcode=True, targets=[ZIEL])
    assert "libx264" in trans and "veryfast" in trans, "Transcode ohne x264/Preset"
    assert trans[trans.index("-g") + 1] == "60", "Keyframe-Abstand nicht 2s bei 30fps"
    ok("W16: copy bleibt copy, Transcode setzt x264 und 2s-Keyframes")

    # --- 8) only_target sendet an genau EIN Ziel, ohne tee ---------------
    einzel = _rc.build(FLV, "rtmps://a/app", "K", only_target="rtmps://b/app/K2")
    assert not any(str(a).startswith("[f=flv") or "onfail=" in str(a) for a in einzel), \
        "only_target baut trotzdem einen tee"
    assert "rtmps://b/app/K2" in einzel, einzel[-4:]
    ok("W16: only_target sendet an genau ein Ziel, ohne tee")

    # --- 9) Der Pull-Proxy steht nur drin, wenn es einen gibt -----------
    assert "-http_proxy" not in kopie, "Proxy-Flag ohne Proxy"
    _konf(pick_pull_proxy=lambda: "http://proxy:3128")
    mit = _rc.build(FLV, "", "", targets=[ZIEL])
    assert mit[mit.index("-http_proxy") + 1] == "http://proxy:3128"
    ok("W16: -http_proxy nur bei gesetztem Pull-Proxy")

    # --- 10) Ohne Ziel wird nie gesendet ---------------------------------
    # Notausgang im Bauer: eine leere Zielliste darf keinen ffmpeg ohne
    # Ausgang erzeugen — der liefe endlos und saugte die Quelle leer.
    _konf()
    _rst.configure(kick_ingest="", kick_key="", twitch_ingest="", twitch_key="",
                   youtube_ingest="", youtube_key="")
    leer = _rc.build(FLV, "rtmps://ingest.example/app", "SCHLUESSEL")
    assert any("rtmps://ingest.example/app/SCHLUESSEL" in str(a) for a in leer), \
        "ohne konfigurierte Ziele faellt der Notausgang aus"
    ok("W16: leere Zielliste faellt auf das uebergebene Ziel zurueck")

    for _p in (schrift.name, avatar.name):
        try:
            _os.remove(_p)
        except OSError:
            pass


def _test_v42_w17_recorderkommando():
    """v4.2-W17: die Recorder-Kommandozeilen stehen in nc/reccmd.py.

    Das ist der Pfad, an dem der Betrieb haengt: faellt er aus, gibt es keine
    Aufnahme. Im Monolithen war er aus demselben Grund ungetestet wie der
    Relay-Bauer — er hing an zwanzig Bot-Globals, und hier laeuft kein ffmpeg.
    Geprueft wird, WAS aufgerufen wird und WELCHER Recorder gewaehlt wird.

    Die beiden Risikotraeger sind der Cookie (F4, beide Befehle transportieren
    die Session) und der 403-Umschalter: faellt die Weiche falsch, nimmt der
    Bot mit dem Pfad auf, der garantiert 403 bekommt — und das sieht im Log
    aus wie ein toter Stream, nicht wie ein Konfigurationsfehler.
    """
    import asyncio as _aio
    import shutil as _sh
    import threading as _th
    import time as _t
    from nc import reccmd as _rc
    from nc.ffdiag import redact_cmd_for_log

    # In dieser Umgebung gibt es weder ffmpeg noch yt-dlp — und der Preflight
    # wuerde die CDN wirklich anfragen. Beides wird ersetzt, damit der Vertrag
    # die AUSWAHL und die ARGUMENTE pruefen kann statt an der Werkzeugsuche zu
    # scheitern. Was ffmpeg dann aus dem Befehl macht, ist ohnehin nicht die
    # Frage dieses Vertrags; das zeigt erst der Server.
    class _WieAlsWaerenSieDa:
        def __getattr__(self, n):
            return getattr(_sh, n)

        @staticmethod
        def which(name):
            if name in ("ffmpeg", "yt-dlp"):
                return "/usr/bin/" + name
            if name == "yt_dlp":
                return None
            return _sh.which(name)

    async def _preflight_durchreichen(u, who="?"):
        return u

    _echt_shutil, _echt_preflight = _rc.shutil, _rc._preflight_url
    _rc.shutil = _WieAlsWaerenSieDa()
    _rc._preflight_url = _preflight_durchreichen

    KEKS = "sessionid=GEHEIM777; tt_csrf=XYZ"
    LAUF = {"resolve": 0, "proxy_exclude": None}

    async def _resolve(username, session, mode="auto"):
        LAUF["resolve"] += 1
        # "leer" statt eines leeren Dicts als Marke: {} ist falsch-artig und
        # waere unten durch das `or` wieder zum Standardfall geworden — der
        # Vertrag haette dann grün gemeldet, was er gar nicht geprueft hat.
        if LAUF.get("leer"):
            return {}
        return dict(LAUF.get("info") or {"hls_url": "https://cdn/x.m3u8", "via": "webcast_api"})

    async def _proxy(username=None, exclude=None):
        LAUF["proxy_exclude"] = set(exclude or ())
        return LAUF.get("proxy")

    zustand = {}

    def _konf(**ab):
        zustand.clear()
        zustand.update(UNTIL={}, PROXY={}, FAILED={}, LOCK=_th.Lock())
        basis = dict(
            cookie_header=lambda: KEKS,
            ensure_cookie_file_netscape=lambda: True,
            pick_checked_pull_proxy=_proxy,
            stream_url_ttl=lambda u: LAUF.get("ttl"),
            log_event=lambda *a, **k: None,
            resolve_tiktok_live_stream=_resolve,
            REC_403_UNTIL=zustand["UNTIL"], REC_PROXY=zustand["PROXY"],
            REC_PROXY_FAILED=zustand["FAILED"], REC_PROXY_LOCK=zustand["LOCK"],
            COOKIE_FILE="cookies.txt", FFMPEG_NICE_RECORD=5,
            FFMPEG_THREADS_RECORD=1, RECORDER_PREF="auto",
            RECORD_403_YTDLP=True, STREAM_URL_MIN_TTL=300)
        basis.update(ab)
        _rc.configure(**basis)

    def _bau(**kw):
        return _aio.run(_rc.build_recording_cmd(
            "henry", "/tmp/out.mp4", 3600, session=object(), **kw))

    # --- 1) configure schweigt nicht ------------------------------------
    for kaputt in ("unbekannt", "fehlt"):
        try:
            if kaputt == "unbekannt":
                _konf(RECORDER_TIPPFEHLER=1)
            else:
                _rc.configure(RECORDER_PREF="auto")
        except ValueError:
            pass
        else:
            raise AssertionError("configure akzeptiert %s" % kaputt)
    _konf()
    ok("W17: configure meldet unbekannte und fehlende Schluessel")

    # --- 2) F4: beide Befehle tragen die Session, das Log keine ---------
    # Der native Pfad steckt sie in einen -headers-Blob, yt-dlp in eine Datei.
    # Zwei Formen, ein Redaktionspfad — und genau deshalb kann eine davon
    # unbemerkt durchrutschen.
    cmd, name = _bau(preferred="native")
    assert name.startswith("native"), name
    kopf = cmd[cmd.index("-headers") + 1]
    assert "GEHEIM777" in kopf, "der native Befehl traegt die Session nicht"
    sauber = redact_cmd_for_log(cmd)
    assert not any("GEHEIM777" in str(a) for a in sauber), \
        "redact_cmd_for_log laesst die Session im nativen Pfad durch"
    assert any("Referer:" in str(a) for a in sauber), "Redaktion frisst den Referer"

    ycmd, yname = _bau(preferred="ytdlp")
    assert yname == "ytdlp" and "--cookies" in ycmd
    ysauber = redact_cmd_for_log(ycmd)
    assert ysauber[ysauber.index("--cookies") + 1] == "<COOKIE_FILE>", \
        "der Cookie-Dateipfad steht unredigiert im Log"
    ok("W17: Session im Befehl, im Log redigiert — nativ UND yt-dlp (F4)")

    # --- 3) Der 403-Umschalter -----------------------------------------
    # Blockt TikTok die CDN-URL, wird der User zeitweise auf yt-dlp gezwungen.
    # Ein expliziter Force des Operators hat aber Vorrang — sonst kann er den
    # nativen Pfad nach der Fehlerbehebung nicht mehr testen.
    _konf(RECORDER_PREF="native")
    zustand["UNTIL"]["henry"] = _t.time() + 600
    _, name = _bau()
    assert name == "ytdlp", "403-Schutz erzwingt yt-dlp nicht (bekommen: %r)" % name
    _, name = _bau(preferred="native")
    assert name and name.startswith("native"), \
        "der explizite Force des Operators wird vom 403-Schutz ueberstimmt"
    # Abgelaufener Cooldown wird ENTFERNT, nicht nur ignoriert — sonst waechst
    # das Dict mit jedem je geblockten User weiter.
    zustand["UNTIL"]["henry"] = _t.time() - 1
    _bau()
    assert "henry" not in zustand["UNTIL"], "abgelaufener 403-Cooldown bleibt liegen"
    ok("W17: 403-Schutz erzwingt yt-dlp, weicht dem Operator, raeumt sich auf")

    # --- 4) B58: eine fast abgelaufene URL wird verworfen ---------------
    # Die Detection liefert die URL mit; ist ihr expire-Token fast durch,
    # startet die Aufnahme in ein sofortiges 404. Genau die "Sofort-404"-
    # Aufnahmen waren das Fehlerbild.
    _konf(RECORDER_PREF="native")
    LAUF["resolve"] = 0
    LAUF["ttl"] = 30                      # < STREAM_URL_MIN_TTL=300
    _bau(prefetched_info={"hls_url": "https://cdn/alt.m3u8", "via": "x"})
    assert LAUF["resolve"] == 1, "abgelaufene prefetch-URL wird trotzdem benutzt"
    LAUF["resolve"] = 0
    LAUF["ttl"] = 3600                    # frisch
    cmd, _ = _bau(prefetched_info={"hls_url": "https://cdn/alt.m3u8", "via": "x"})
    assert LAUF["resolve"] == 0, "frische prefetch-URL wird unnoetig neu aufgeloest"
    assert "https://cdn/alt.m3u8" in cmd, "die prefetch-URL landet nicht im Befehl"
    ok("W17: stale Stream-URL wird verworfen, frische gespart (B58)")

    # --- 5) Proxy-Rotation: geblockte werden ausgeschlossen und gemerkt --
    _konf(RECORDER_PREF="native")
    LAUF["ttl"] = None
    zustand["FAILED"]["henry"] = {"http://tot:3128"}
    LAUF["proxy"] = "http://frisch:3128"
    cmd, _ = _bau()
    assert LAUF["proxy_exclude"] == {"http://tot:3128"}, \
        "geblockte Proxys werden nicht ausgeschlossen: %r" % (LAUF["proxy_exclude"],)
    assert zustand["PROXY"]["henry"] == "http://frisch:3128", \
        "der benutzte Proxy wird nicht gemerkt — handle_recording_finished kann ihn nicht bewerten"
    assert cmd[cmd.index("-http_proxy") + 1] == "http://frisch:3128"
    ok("W17: Proxy-Rotation schliesst Geblockte aus und merkt den benutzten")

    # --- 6) F44: nur FLV ist kein Grund, nicht aufzunehmen --------------
    # Vorher wurde nur auf hls_url geprueft; reine FLV-Rooms galten als
    # "kein Recorder verfuegbar", obwohl ffmpeg FLV genauso aufnimmt.
    _konf(RECORDER_PREF="native")
    LAUF["proxy"] = None
    LAUF["info"] = {"flv_url": "https://cdn/x.flv", "via": "webcast_api"}
    cmd, name = _bau()
    assert cmd and name.endswith("-flv"), "reiner FLV-Stream wird nicht aufgenommen: %r" % name
    assert "https://cdn/x.flv" in cmd
    LAUF.pop("info")
    ok("W17: reine FLV-Streams werden aufgenommen und als solche benannt (F44)")

    # --- 7) native_api ist kein harter Pin (F42) ------------------------
    # Vorher sah der Operator "kein Recorder verfuegbar", obwohl yt-dlp da war.
    _konf(RECORDER_PREF="auto")
    LAUF["leer"] = True                   # Resolver liefert nichts
    _, name = _bau(preferred="native_api")
    assert name == "ytdlp", "native_api faellt nicht auf yt-dlp zurueck: %r" % name
    LAUF.pop("leer")
    ok("W17: native_api faellt auf yt-dlp zurueck statt hart zu scheitern (F42)")

    # --- 8) Aufnahme wird genice't, das Sendebild nicht -----------------
    # Der Gegensatz ist Absicht: der Relay-Bauer setzt NIE nice (W16), die
    # Aufnahme schon — sie darf der Live-Ausspielung nicht die Kerne wegnehmen.
    _konf(RECORDER_PREF="native")
    cmd, _ = _bau()
    assert cmd[:3] == ["nice", "-n", "5"], cmd[:5]
    assert "-threads" in cmd and cmd[cmd.index("-threads") + 1] == "1"
    ok("W17: die Aufnahme laeuft genice't und gedeckelt (anders als das Relay)")

    # --- 9) Kein Recorder heisst (None, None), kein Absturz -------------
    _konf(RECORDER_PREF="native")
    LAUF["leer"] = True
    cmd, name = _bau()
    assert cmd is None and name is None, (cmd, name)
    LAUF.pop("leer")
    ok("W17: ohne brauchbaren Recorder kommt (None, None) zurueck")

    _rc.shutil, _rc._preflight_url = _echt_shutil, _echt_preflight


def _test_v42_w18_eskalationsrechnung():
    """v4.2-W18: die Eskalationsrechnung des Recorders steht in nc/aufnahmefolge.py.

    Sie lag an DREI Stellen in bot.py — gesetzt beim Aufnahme-Ende,
    zurueckgesetzt beim Offline-Uebergang, durchgesetzt vor dem naechsten
    Spawn — und war nie ausgefuehrt worden, weil sie in einer 669-Zeilen-
    Funktion steckt, die einen laufenden ffmpeg-Prozess braucht. Genau in
    dieser Rechnung stecken vier Exponenten mit Schwellen-Offset; ein
    Vorzeichenfehler darin ist im Betrieb nicht zu sehen, sondern nur daran,
    dass ein Streamer entweder gar nicht mehr oder viel zu oft probiert wird.
    """
    from nc import aufnahmefolge as _af

    # --- 1) Die 403-Stufen ----------------------------------------------
    # Der heikle Teil ist `2 ** (n - hits)`: beim ERSTEN erzwungenen Wechsel
    # muss die Basis stehen, nicht Basis * 2**hits. Mit Standardwerten waere
    # der Unterschied Faktor 4 — 4 Minuten statt einer.
    streak, sperre, backoff = {}, {}, {}
    arg = dict(hits=2, cooldown_s=1800, backoff_an=True, basis_s=60, max_s=1800)
    r = _af.nach_403(streak, sperre, backoff, "henry", 1000.0, **arg)
    assert r == {"streak": 1, "erzwingt_ytdlp": False, "backoff_s": None}, r
    assert "henry" not in sperre, "der erste 403 erzwingt schon yt-dlp"
    stufen = []
    for _ in range(5):
        r = _af.nach_403(streak, sperre, backoff, "henry", 1000.0, **arg)
        stufen.append(r["backoff_s"])
    assert stufen == [60, 120, 240, 480, 960], stufen
    assert sperre["henry"] == 1000.0 + 1800, sperre
    for _ in range(3):
        r = _af.nach_403(streak, sperre, backoff, "henry", 1000.0, **arg)
    assert r["backoff_s"] == 1800, "der Deckel greift nicht: %r" % r
    # Ohne Backoff-Schalter wird die Sperre trotzdem gesetzt — der 403-Schutz
    # und die Retry-Drosselung sind zwei Dinge.
    s2, sp2, bo2 = {}, {}, {}
    r = _af.nach_403(s2, sp2, bo2, "x", 5.0, hits=1, cooldown_s=10,
                     backoff_an=False, basis_s=60, max_s=1800)
    assert r["erzwingt_ytdlp"] and r["backoff_s"] is None and not bo2
    assert sp2["x"] == 15.0
    ok("W18: 403-Stufen 60/120/240/…/1800, erster Wechsel auf der Basis")

    # --- 2) Die Stream-Tod-Stufen ---------------------------------------
    tstreak, tsperre, faellig = {}, {}, {}
    warg = dict(schwelle=3, kurz_s=45)
    got = []
    for _ in range(7):
        got.append(_af.nach_totem_versuch(tstreak, tsperre, faellig, 7, 100.0, **warg))
    assert [g["sekunden"] for g in got] == [45, 45, 300, 600, 1200, 1800, 1800], \
        [g["sekunden"] for g in got]
    assert [g["eskaliert"] for g in got] == [False, False, True, True, True, True, True]
    # Beide Zweige stellen den Worker-Tick faellig. Ohne das bremst die Sperre
    # nur den Spawn, waehrend der Live-Check weiter im 20s-Takt laeuft.
    assert faellig[7] == tsperre[7] == 100.0 + 1800
    # kurz_s = 0 heisst: keine Sperre setzen, aber trotzdem zaehlen.
    t2, s3, f3 = {}, {}, {}
    r = _af.nach_totem_versuch(t2, s3, f3, 1, 50.0, schwelle=3, kurz_s=0)
    assert r["streak"] == 1 and not s3 and not f3
    ok("W18: Tod-Stufen 300/600/1200/1800, Worker-Tick wird mitverschoben")

    # --- 3) Was als "keine Daten" zaehlt ---------------------------------
    # Der gefaehrliche Fall ist die GROSSE Datei mit stall_killed: das ist ein
    # echter, abgeschnittener Mitschnitt. Als tot zu zaehlen hiesse, einen
    # Streamer in den Backoff zu schicken, der gerade sendet.
    assert not _af.daten_geflossen("stall_killed", 500, 1_000_000)
    assert _af.daten_geflossen("stall_killed", 5_000_000, 1_000_000), \
        "eine grosse Datei mit stall_killed gilt faelschlich als tot"
    assert _af.daten_geflossen("fail", 10, 1_000_000), \
        "eine unbekannte Kategorie mit kleiner Datei gilt faelschlich als tot"
    assert not _af.daten_geflossen("hevc_unsupported", 0, 1)
    ok("W18: nur bekannte Kategorie UND kleine Datei zaehlen als tot")

    # --- 4) Die fruehe Trennung -----------------------------------------
    frueh = {}
    w = [_af.nach_frueher_trennung(frueh, 3, max_versuche=5)["wartet"] for _ in range(5)]
    assert w == [10, 20, 40, 80, 160], w
    r = _af.nach_frueher_trennung(frueh, 3, max_versuche=5)
    assert r["wartet"] is None, r
    # Der Zaehler MUSS weg sein. Bliebe er stehen, bekaeme die naechste fruehe
    # Trennung sofort den laengsten Backoff, obwohl das Netz inzwischen wieder
    # geht (F50-Bug B12).
    assert 3 not in frueh, "der Zaehler bleibt nach Max-Retries stehen"
    # Deckel: mit hohem max bleibt es bei 160.
    f2 = {}
    for _ in range(9):
        r = _af.nach_frueher_trennung(f2, 1, max_versuche=99)
    assert r["wartet"] == 160, r
    ok("W18: fruehe Trennung 10/20/40/80/160, Zaehler faellt nach Max weg")

    # --- 5) Sperren runden nie auf "frei" ab -----------------------------
    # int(0.4) waere 0 gewesen — die Meldung haette "frei" gesagt, waehrend
    # die Sperre den Spawn weiter verhindert.
    assert _af.sperre_rest({"a": 100.4}, "a", 100.0) == 1
    assert _af.sperre_rest({"a": 100.0}, "a", 100.0) == 0
    assert _af.sperre_rest({"a": 160.0}, "a", 100.0) == 60
    assert _af.sperre_rest({}, "a", 100.0) == 0
    assert _af.sperre_rest({"a": 0}, "a", 100.0) == 0
    ok("W18: Restzeit rundet auf, eine halbe Sekunde ist nicht 'frei'")

    # --- 6) Die Backoff-Meldung entspammt sich --------------------------
    zuletzt = {}
    assert _af.melden_erlaubt(zuletzt, "u", 1000.0, abstand_s=300)
    assert zuletzt["u"] == 1000.0
    assert not _af.melden_erlaubt(zuletzt, "u", 1290.0, abstand_s=300)
    assert not _af.melden_erlaubt(zuletzt, "u", 1300.0, abstand_s=300)
    assert _af.melden_erlaubt(zuletzt, "u", 1301.0, abstand_s=300)
    ok("W18: hoechstens eine Backoff-Zeile je Abstand")

    # --- 7) Zuruecksetzen: Erfolg raeumt alles, Offline nicht ganz -------
    reg = [dict(a=1) for _ in range(3)] + [dict(b=1) for _ in range(3)]
    _af.aufnahme_geglueckt(*reg, "a", "b")
    assert not any(reg), "eine geglueckte Aufnahme laesst Zaehler stehen: %r" % reg
    r5 = [dict(a=1), dict(a=1), dict(a=1), dict(b=2), dict(b=3)]
    frueh = {"b": 4}
    stand = _af.sitzung_zuende(*r5, "a", "b")
    assert stand is True, "sitzung_zuende meldet den stehenden Tod-Zaehler nicht"
    assert not any(r5), r5
    assert frueh == {"b": 4}, \
        "das Sitzungsende loescht den Frueh-Trennungs-Zaehler mit"
    assert _af.sitzung_zuende(*[{} for _ in range(5)], "a", "b") is False
    # Die Asymmetrie ist der Punkt und muss ABSICHT bleiben: sitzung_zuende
    # bekommt fuenf Register, aufnahme_geglueckt sechs. Wuerde der
    # Frueh-Trennungs-Zaehler hier stillschweigend mitgereicht, waere die
    # Netzspur nach jedem Offline weg — und die naechste fruehe Trennung
    # begaenne wieder bei 10s, obwohl das Netz seit Stunden wackelt.
    import inspect as _insp
    _z = [p for p in _insp.signature(_af.sitzung_zuende).parameters]
    _g = [p for p in _insp.signature(_af.aufnahme_geglueckt).parameters]
    assert len(_z) == 7 and len(_g) == 8, (_z, _g)
    assert "frueh" in _g and "frueh" not in _z, (_z, _g)
    # Und bot.py darf den Zaehler am Offline-Uebergang auch nicht selbst
    # loeschen — sonst waere die Trennung in der Datei nur Kosmetik.
    _q = open("bot.py", encoding="utf-8").read()
    _i = _q.index("_nc_folge.sitzung_zuende(")
    _fenster = _q[_i:_i + 1200]
    assert "_EARLY_DISCONNECT_RETRY" not in _fenster, \
        "bot.py raeumt den Frueh-Trennungs-Zaehler am Sitzungsende doch weg"
    ok("W18: Erfolg raeumt alle sechs Register, Offline laesst die Netzspur stehen")

    # --- 8) Zwei Uhren, und der Bot benutzt an jeder Stelle die richtige --
    # Ein vertauschtes time()/monotonic() setzt eine Sperre, die entweder
    # sofort abgelaufen oder Jahrzehnte gueltig ist. Im Betrieb sieht beides
    # aus wie "der Bot nimmt nicht auf" bzw. "der Bot haemmert".
    import ast as _ast
    quelle = open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(quelle)
    uhren = {}
    for n in _ast.walk(baum):
        if not (isinstance(n, _ast.Call) and isinstance(n.func, _ast.Attribute)
                and isinstance(n.func.value, _ast.Name)
                and n.func.value.id == "_nc_folge"):
            continue
        uhren.setdefault(n.func.attr, set()).add(_ast.unparse(n))
    def _uhr(name, erwartet):
        rufe = uhren.get(name) or set()
        assert rufe, "%s wird in bot.py gar nicht gerufen" % name
        for r in rufe:
            assert erwartet in r, \
                "%s bekommt die falsche Uhr: %s" % (name, r[:120])
    _uhr("nach_403", "_time_mod.time()")
    _uhr("nach_totem_versuch", "_time_mod.monotonic()")
    ok("W18: 403 rechnet in Wanduhr, Stream-Tod in monotoner Zeit")


def _test_v42_w19_versandweg():
    """v4.2-W19: der Versandweg der Aufnahmen steht in telegramversand.py.

    Bot-seitig wie discordbot.py: die Datei faengt telegram.error-Ausnahmen ab
    und braucht die echten Klassen zur Laufzeit. Unter nc/ waere sie im
    Vertrags-Job an einem nackten ImportError gestorben — dort sind nur orjson
    und flask installiert. Genau deshalb stubbt dieser Vertrag `telegram`,
    so wie test_smoke.py es fuer bot.py tut: geprueft wird der Kontrollfluss
    des Versands, nicht die Bibliothek.

    DAS IST DER PFAD, DER IM BETRIEB SCHON WEHGETAN HAT: eine Chat-ID, die
    Telegram mit 'chat not found' beantwortet, liess den Bot fuer JEDE
    Aufnahme durch die komplette Teil- und Retry-Kette laufen — 176 identische
    Fehlerzeilen in einer Nacht, 327 verworfene Upload-Teile. Die Sperre
    dagegen hatte nie ein Test angefasst.
    """
    import asyncio as _aio
    import os as _os
    import sys as _sys
    import tempfile as _tf
    import types as _ty

    # --- telegram stubben, VOR dem Import des Moduls -------------------
    if "telegram" not in _sys.modules:
        _tg = _ty.ModuleType("telegram")
        _err = _ty.ModuleType("telegram.error")
        _con = _ty.ModuleType("telegram.constants")
        for _n in ("TelegramError",):
            setattr(_err, _n, type(_n, (Exception,), {}))
        # ANKER GEWANDERT (v4.2-W175): telegramversand faengt ChatMigrated.
        for _n in ("BadRequest", "ChatMigrated", "Forbidden", "NetworkError", "RetryAfter"):
            setattr(_err, _n, type(_n, (_err.TelegramError,), {}))
        _con.ParseMode = _ty.SimpleNamespace(HTML="HTML")
        _sys.modules.update({"telegram": _tg, "telegram.error": _err,
                             "telegram.constants": _con})
    import telegramversand as _tv

    # Kein echtes Warten: die Retry-Pfade schlafen bis zu 120 Sekunden.
    _echt_sleep = _tv.asyncio.sleep

    async def _kein_schlaf(_s):
        PROT["geschlafen"].append(_s)
    _tv.asyncio.sleep = _kein_schlaf

    PROT = {}

    class _Bot:
        def __init__(self, fehler=None):
            self.fehler = list(fehler or [])

        async def send_video(self, chat_id, datei, **kw):
            gelesen = datei.read() if hasattr(datei, "read") else b""
            PROT["sends"].append({"chat": chat_id, "bytes": len(gelesen),
                                  "thread": kw.get("message_thread_id")})
            if self.fehler:
                raise self.fehler.pop(0)

    def _neu(fehler=None, tot=False):
        PROT.clear()
        PROT.update(sends=[], texte=[], tot=[], vergessen=[], geschlafen=[])

        async def _ensure_topic(chat_id, username, bot):
            return 4711

        async def _safe_send(bot, chat_id, text, **kw):
            PROT["texte"].append(text)
        # ANKER GEWANDERT (v4.2-W175): sechster Pflicht-Helfer chat_migriert.
        async def _chat_migriert(alt, neu):
            PROT.setdefault("migriert", []).append((alt, neu))
        _tv.konfiguriere(
            chat_migriert=_chat_migriert,
            ensure_topic=_ensure_topic,
            is_dead=lambda c: tot,
            mark_dead=lambda c: PROT["tot"].append(c),
            safe_send=_safe_send,
            topic_forget=lambda c, u: PROT["vergessen"].append((c, u)))
        return _ty.SimpleNamespace(bot=_Bot(fehler))

    datei = _tf.NamedTemporaryFile(suffix=".mp4", delete=False)
    datei.write(b"x" * 4096)
    datei.close()

    def _lauf(bot_app):
        _aio.run(_tv.split_and_send_video(-100123, datei.name, bot_app, "henry"))

    # --- 1) konfiguriere schweigt nicht ---------------------------------
    for kaputt, arg in (("unbekannt", {"tippfehler": 1}), ("fehlt", {"is_dead": 1})):
        try:
            _tv.konfiguriere(**arg)
        except ValueError:
            pass
        else:
            raise AssertionError("konfiguriere akzeptiert %s" % kaputt)
    ok("W19: konfiguriere meldet unbekannte und fehlende Helfer")

    # --- 2) Eine gesperrte Chat-ID kostet keinen einzigen Versuch -------
    _lauf(_neu(tot=True))
    assert PROT["sends"] == [], \
        "der Upload rennt trotz gesperrter Chat-ID in Telegram: %r" % PROT["sends"]
    assert any("gesperrt" in t for t in PROT["texte"]), \
        "der Betreiber erfaehrt nicht, WARUM nichts hochgeladen wurde"
    assert any("TELEGRAM_CHAT_ID" in t for t in PROT["texte"]), \
        "die Meldung nennt nicht die Stellschraube, an der es liegt"
    ok("W19: gesperrte Chat-ID — kein Upload-Versuch, aber eine klare Meldung")

    # --- 3) Der Normalfall: genau EIN Versand, kein Teilen --------------
    _lauf(_neu())
    assert len(PROT["sends"]) == 1, PROT["sends"]
    assert PROT["sends"][0]["bytes"] == 4096, "die Datei geht leer raus"
    assert PROT["sends"][0]["thread"] == 4711, "das Forum-Thema wird nicht getroffen"
    assert not PROT["texte"], "der Erfolgsfall meldet einen Fehler: %r" % PROT["texte"]
    ok("W19: kleine Datei — ein Versand, ins richtige Thema, mit Inhalt")

    # --- 4) Forbidden und 'chat not found' sperren die Chat-ID ----------
    # Ohne das laeuft der Bot bei jeder Aufnahme erneut hinein.
    _lauf(_neu(fehler=[_tv.Forbidden("bot was blocked by the user")]))
    assert PROT["tot"] == [-100123], "Forbidden sperrt die Chat-ID nicht"
    _lauf(_neu(fehler=[_tv.BadRequest("Chat not found")]))
    assert PROT["tot"] == [-100123], "'chat not found' als BadRequest sperrt nicht"
    ok("W19: Forbidden und 'chat not found' sperren die Chat-ID")

    # --- 5) RetryAfter: einmal warten, und den Zeiger ZURUECKSPULEN -----
    # Ohne seek(0) laedt der zweite Versuch null Bytes hoch — Telegram nimmt
    # ihn an, und im Chat liegt eine leere Datei. Das faellt nirgends auf.
    _fehler = _tv.RetryAfter("flood")
    _fehler.retry_after = 7
    bot = _neu(fehler=[_fehler])
    _lauf(bot)
    assert len(PROT["sends"]) == 2, PROT["sends"]
    assert PROT["geschlafen"] == [8], "wartet nicht retry_after+1: %r" % PROT["geschlafen"]
    assert PROT["sends"][1]["bytes"] == 4096, \
        "der zweite Versuch laedt %d Bytes hoch statt 4096 — kein seek(0)" \
        % PROT["sends"][1]["bytes"]
    assert not PROT["texte"], "der geglueckte Retry meldet trotzdem einen Fehler"
    ok("W19: RetryAfter wartet einmal und spult die Datei zurueck")

    # --- 6) B46: Rate-Limit kommt manchmal als BadRequest ---------------
    # PTB wickelt manche 429-Antworten als BadRequest — der RetryAfter-Pfad
    # wird dann nie erreicht, und der Upload waere ohne diesen Zweig verloren.
    _lauf(_neu(fehler=[_tv.BadRequest("Too many requests: retry after 8")]))
    assert len(PROT["sends"]) == 2 and PROT["geschlafen"] == [9], \
        (PROT["sends"], PROT["geschlafen"])
    assert not PROT["tot"], "ein Rate-Limit sperrt faelschlich die Chat-ID"
    ok("W19: Rate-Limit als BadRequest wird wie RetryAfter behandelt (B46)")

    # --- 7) Geloeschtes Thema: in den Haupt-Chat statt verloren ---------
    _lauf(_neu(fehler=[_tv.BadRequest("Message thread not found")]))
    assert PROT["vergessen"] == [(-100123, "henry")], \
        "das tote Thema wird nicht vergessen: %r" % PROT["vergessen"]
    assert len(PROT["sends"]) == 2, PROT["sends"]
    assert PROT["sends"][1]["thread"] is None, \
        "der Zweitversuch geht wieder ins tote Thema statt in den Haupt-Chat"
    assert PROT["sends"][1]["bytes"] == 4096, "auch hier fehlt das Zuruecksetzen"
    ok("W19: geloeschtes Thema — Mapping verworfen, Upload in den Haupt-Chat")

    # --- 8) Ein echter Fehler wird gemeldet, nicht verschluckt ----------
    _lauf(_neu(fehler=[_tv.BadRequest("VIDEO_FILE_INVALID")]))
    assert any("UPLOAD FEHLGESCHLAGEN" in t for t in PROT["texte"]), PROT["texte"]
    assert not PROT["tot"], "ein Formatfehler sperrt faelschlich die Chat-ID"
    ok("W19: ein echter Upload-Fehler erreicht den Betreiber")

    _tv.asyncio.sleep = _echt_sleep
    try:
        _os.remove(datei.name)
    except OSError:
        pass


def _test_v42_w20_livesignal():
    """v4.2-W20: die Entscheidungen aus dem Live-Signal stehen in nc/livefolge.py.

    Drei Rechnungen, die in einer 380-Zeilen-Funktion steckten, die eine
    Datenbank, einen Scraper und einen Recorder braucht — hier also nie
    ausgefuehrt wurde. Zwei davon haben Randfaelle, die im Betrieb genau
    einmal im Jahr bzw. genau bei Stoerungen auffallen: das Ruhefenster ueber
    Mitternacht und die Frage, ob ein verpasster Live-Ping schon "offline"
    heisst.
    """
    from nc import livefolge as _lf

    # --- 1) Ein Aussetzer ist kein Stream-Ende --------------------------
    # BEIDE Schwellen muessen fallen. Ein `or` haette genau die haeufigste
    # Stoerung durchgelassen: zwei schnelle Ticks hintereinander erfuellen
    # den Debounce, aber nicht die Grace — und das ist das Bild eines
    # TikTok-Aussetzers, nicht das eines beendeten Streams.
    z, seit = {}, {}
    arg = dict(debounce=2, grace_s=120)
    r1 = _lf.offline_bestaetigt(z, seit, 7, 1000.0, **arg)
    assert r1 == {"pending": 1, "offline_for": 0.0, "bestaetigt": False}, r1
    r2 = _lf.offline_bestaetigt(z, seit, 7, 1002.0, **arg)   # Debounce ja, Grace nein
    assert not r2["bestaetigt"], "zwei schnelle Ticks gelten schon als offline"
    assert r2["offline_for"] == 2.0, r2
    r3 = _lf.offline_bestaetigt(z, seit, 7, 1130.0, **arg)   # beide erfuellt
    assert r3["bestaetigt"] and r3["pending"] == 3 and r3["offline_for"] == 130.0, r3
    # Nach der Bestaetigung sind BEIDE Register leer. Blieben sie stehen,
    # waere die naechste Sitzung sofort "bestaetigt offline", noch bevor sie
    # richtig begonnen hat.
    assert 7 not in z and 7 not in seit, (z, seit)
    # Und die Grace allein reicht auch nicht: lange offline, aber erst ein Tick.
    z2, s2 = {}, {}
    r = _lf.offline_bestaetigt(z2, s2, 1, 0.0, debounce=3, grace_s=10)
    r = _lf.offline_bestaetigt(z2, s2, 1, 9999.0, debounce=3, grace_s=10)
    assert not r["bestaetigt"], "die Grace allein bestaetigt schon offline"
    ok("W20: offline erst wenn Debounce UND Pause-Grace fallen")

    # --- 2) Ein Lebenszeichen raeumt beide Register ---------------------
    z3, s3 = {5: 2}, {5: 100.0}
    assert _lf.live_gesehen(z3, s3, 5) is True
    assert not z3 and not s3, (z3, s3)
    assert _lf.live_gesehen(z3, s3, 5) is False, "meldet ein Aufraeumen ohne Anlass"
    # Ohne das Zuruecksetzen zaehlte ein Aussetzer von heute Mittag noch auf
    # die Schwelle von heute Abend.
    z4, s4 = {}, {}
    _lf.offline_bestaetigt(z4, s4, 9, 0.0, debounce=2, grace_s=0)
    _lf.live_gesehen(z4, s4, 9)
    r = _lf.offline_bestaetigt(z4, s4, 9, 500.0, debounce=2, grace_s=0)
    assert r["pending"] == 1 and not r["bestaetigt"], \
        "der alte Aussetzer zaehlt noch mit: %r" % r
    ok("W20: ein Lebenszeichen setzt den Aussetzer-Zaehler zurueck")

    # --- 3) Das Ruhefenster ueber Mitternacht ---------------------------
    # Der Standardfall (22-7) ist genau der, den `start <= h < ende` NIE
    # trifft — die Ruhezeit haette schlicht nicht existiert.
    nachts = [h for h in range(24) if _lf.ruhezeit(h, 22, 7)]
    assert nachts == [0, 1, 2, 3, 4, 5, 6, 22, 23], nachts
    tags = [h for h in range(24) if _lf.ruhezeit(h, 9, 17)]
    assert tags == list(range(9, 17)), tags
    # start == ende schaltet ab. Sonst waere "0 bis 0" entweder keine oder
    # eine volle Ruhe — beide Lesarten hat schon jemand gemeint.
    assert not any(_lf.ruhezeit(h, 0, 0) for h in range(24))
    assert not any(_lf.ruhezeit(h, 13, 13) for h in range(24))
    # Die Grenzen: Beginn gehoert dazu, Ende nicht.
    assert _lf.ruhezeit(22, 22, 7) and not _lf.ruhezeit(7, 22, 7)
    assert _lf.ruhezeit(9, 9, 17) and not _lf.ruhezeit(17, 9, 17)
    ok("W20: Ruhefenster laeuft ueber Mitternacht, start==ende schaltet ab")

    # --- 4) Der Poll-Abstand --------------------------------------------
    IV = {"live": 20, "offline": 300, "just_went_offline": 45, "unknown": 90}
    assert _lf.poll_abstand("live", True, IV) == 20
    assert _lf.poll_abstand("live", False, IV) == 20
    # Direkt nach einem Live-Ende wird kuerzer nachgeschaut: genau dann faellt
    # die Unterscheidung zwischen Pause und echtem Ende.
    assert _lf.poll_abstand("offline", True, IV) == 45
    assert _lf.poll_abstand("offline", False, IV) == 300
    # "unknown" ist NICHT offline — die Abfrage kam nicht durch, der Streamer
    # kann laufen. Es mit dem Offline-Intervall zu behandeln hiesse, einen
    # laufenden Stream fuenf Minuten lang nicht anzusehen.
    assert _lf.poll_abstand("unknown", True, IV) == 90
    assert _lf.poll_abstand("kaputt", False, IV) == 90
    ok("W20: Poll-Abstand je Status, 'unbekannt' ist nicht 'offline'")

    # --- 5) Hinweise duerfen nur verkuerzen -----------------------------
    # X3 (Prioritaet) und M5 (Brain-Hinweise) sitzen HINTER poll_abstand.
    # Ein Hinweis, der verlaengern darf, kann ein Tracking still einschlafen
    # lassen — deshalb muss die Richtung im Monolithen ein min() bleiben.
    import ast as _ast
    q = open("bot.py", encoding="utf-8").read()
    fn = None
    for n in _ast.walk(_ast.parse(q)):
        if isinstance(n, _ast.FunctionDef) and n.name == "_schedule_next_check":
            fn = _ast.get_source_segment(q, n) or ""
    assert fn, "_schedule_next_check nicht gefunden"
    assert "_nc_live.poll_abstand(" in fn, "der Grundabstand wird nicht mehr geholt"
    assert "min(delay, _brain_hint_delay(" in fn, \
        "der Brain-Hinweis darf das Intervall verlaengern"
    assert "get_priority_poll_interval(tracking_id, int(delay))" in fn, \
        "die Prioritaet bekommt den Grundabstand nicht als Deckel"
    ok("W20: Prioritaet und Brain-Hinweis koennen nur verkuerzen")

    # --- 6) Die Uhr an der Aufrufstelle ---------------------------------
    # Die Pause-Grace misst eine DAUER. Mit der Wanduhr haette ein NTP-Sprung
    # oder eine Zeitumstellung mitten im Stream entweder sofort "offline"
    # gemeldet oder eine Stunde lang gar nicht.
    rufe = [_ast.unparse(n) for n in _ast.walk(_ast.parse(q))
            if isinstance(n, _ast.Call) and isinstance(n.func, _ast.Attribute)
            and isinstance(n.func.value, _ast.Name) and n.func.value.id == "_nc_live"
            and n.func.attr == "offline_bestaetigt"]
    assert rufe, "offline_bestaetigt wird in bot.py gar nicht gerufen"
    for r in rufe:
        assert "_time_mod.monotonic()" in r, "die Pause-Grace laeuft auf der Wanduhr: %s" % r[:120]
    ok("W20: die Pause-Grace rechnet in monotoner Zeit")


def _test_v42_w21_cookiegesundheit():
    """v4.2-W21: die Gesundheitsbewertung der cookies.txt steht in nc/cookies.py.

    147 Zeilen, die im Monolithen NIE ausgefuehrt worden sind — obwohl sie die
    Leiter ist, an der der Betreiber ablesen soll, warum ein Pull 403 bekommt.
    In dieser Leiter steckt die Diagnose fuer den Fall, der am meisten Zeit
    gekostet hat: "403 TROTZ aktuellem Cookie laut Dashboard". Ursache ist ein
    kritischer Cookie, der unter MEHREREN Domains in der Datei steht — der
    Browser waehlt je Subdomain situativ, der Bot statisch und kann den
    falschen erwischen. Ohne diese Meldung sieht das Deck gruen aus.
    """
    import os as _os
    import time as _t
    from nc import cookies as _ck

    KRIT = ("sessionid", "sessionid_ss", "tt_csrf_token")
    verzeichnis = _ph.verzeichnis()
    pfad = _os.path.join(verzeichnis, "cookies.txt")
    PROT = {"repariert": 0}

    def _schreibe(zeilen, alter_tage=0.0):
        with open(pfad, "w", encoding="utf-8") as f:
            f.write("# Netscape HTTP Cookie File\n")
            for z in zeilen:
                f.write(z + "\n")
        if alter_tage:
            t = _t.time() - alter_tage * 86400
            _os.utime(pfad, (t, t))

    def _zeile(name, wert="x", domain=".tiktok.com", ablauf=None):
        # Netscape: domain, flag, pfad, secure, expiry, name, wert
        exp = int(_t.time() + 86400 * 30) if ablauf is None else int(ablauf)
        return f"{domain}\tTRUE\t/\tTRUE\t{exp}\t{name}\t{wert}"

    def _konf():
        PROT["repariert"] = 0

        def _rep():
            PROT["repariert"] += 1
            return True
        _ck.configure(datei=pfad, kritisch=KRIT, reparieren=_rep,
                      autorefresh_info=lambda: {"an": False},
                      autofetch_info=lambda: {"an": False})
        _ck._COOKIE_REPAIR_STAND["mtime"] = None

    _konf()

    # --- 1) Fehlende Datei ist kein Absturz -----------------------------
    if _os.path.exists(pfad):
        _os.remove(pfad)
    h = _ck.gesundheit()
    assert h["exists"] is False and h["status"] == "missing", h
    assert list(h["critical_missing"]) == list(KRIT), h["critical_missing"]
    ok("W21: fehlende cookies.txt meldet 'missing' statt zu krachen")

    # --- 2) Der gesunde Fall --------------------------------------------
    _schreibe([_zeile("sessionid"), _zeile("sessionid_ss"),
               _zeile("tt_csrf_token"), _zeile("ttwid")])
    h = _ck.gesundheit()
    assert h["status"] == "ok", (h["status"], h["headline"])
    assert h["total"] == 4 and not h["expired"] and not h["expiring_soon"]
    assert sorted(h["critical_present"]) == sorted(KRIT)
    assert h["duplicate_domain_cookies"] == []
    ok("W21: vier frische Cookies unter einer Domain — Status ok")

    # --- 3) DER FALL: derselbe Cookie unter zwei Domains ----------------
    # Das ist "403 trotz aktuellem Cookie". Ohne diese Warnung meldet das Deck
    # gruen, waehrend der Bot beim Senden den falschen Wert waehlen kann.
    _schreibe([_zeile("sessionid", "neu", ".tiktok.com"),
               _zeile("sessionid", "alt", ".www.tiktok.com"),
               _zeile("sessionid_ss"), _zeile("tt_csrf_token")])
    h = _ck.gesundheit()
    assert h["duplicate_domain_cookies"] == ["sessionid"], h["duplicate_domain_cookies"]
    assert h["status"] == "warning", h["status"]
    assert "mehrfach" in h["headline"] and "sessionid" in h["headline"], h["headline"]
    assert "bereinigen" in h["headline"], \
        "die Meldung sagt nicht, was der Betreiber TUN soll"
    ok("W21: derselbe kritische Cookie unter zwei Domains wird gemeldet")

    # --- 4) Die Leiter haelt ihre Reihenfolge ---------------------------
    # 'kritisch' schlaegt 'abgelaufen' schlaegt 'Dubletten'. Kippte die
    # Reihenfolge, verdeckte eine Warnung einen kritischen Zustand.
    _schreibe([_zeile("ttwid")])                      # kein einziger kritischer
    h = _ck.gesundheit()
    assert h["status"] == "critical" and "Keine kritischen" in h["headline"], h
    _schreibe([_zeile("tt_csrf_token")])              # kritisch da, aber keine sessionid
    h = _ck.gesundheit()
    assert h["status"] == "critical" and "sessionid" in h["headline"], h
    # abgelaufen schlaegt Dubletten: beides gleichzeitig -> 'abgelaufen'
    _schreibe([_zeile("sessionid", "a", ".tiktok.com"),
               _zeile("sessionid", "b", ".www.tiktok.com"),
               _zeile("tt_csrf_token", ablauf=_t.time() - 86400)])
    h = _ck.gesundheit()
    assert h["status"] == "warning" and "abgelaufen" in h["headline"], h["headline"]
    assert h["expired"] and h["expired"][0]["name"] == "tt_csrf_token"
    ok("W21: kritisch vor abgelaufen vor Dubletten — die Reihenfolge haelt")

    # --- 5) Ablaufende Cookies werden vorher sichtbar -------------------
    _schreibe([_zeile("sessionid", ablauf=_t.time() + 86400 * 2),
               _zeile("sessionid_ss"), _zeile("tt_csrf_token")])
    h = _ck.gesundheit()
    assert h["status"] == "warning" and "laeuft" in h["headline"].replace("ä", "ae"), h["headline"]
    assert h["oldest_expiry_days"] is not None and h["oldest_expiry_days"] < 3, h
    assert [c["name"] for c in h["expiring_soon"]] == ["sessionid"], h["expiring_soon"]
    # Ein Session-Cookie ohne Ablauf ist NICHT abgelaufen — sonst meldete
    # jede normale Datei Alarm.
    _schreibe([_zeile("sessionid", ablauf=0), _zeile("sessionid_ss"),
               _zeile("tt_csrf_token")])
    h = _ck.gesundheit()
    assert not h["expired"] and h["status"] == "ok", (h["status"], h["headline"])
    ok("W21: bald ablaufende Cookies melden sich, Session-Cookies nicht")

    # --- 6) Eine alte Datei ist eine Warnung, kein Fehler ---------------
    _schreibe([_zeile("sessionid"), _zeile("sessionid_ss"),
               _zeile("tt_csrf_token")], alter_tage=45)
    h = _ck.gesundheit()
    assert h["status"] == "warning" and "45d" in h["headline"], h["headline"]
    assert h["file_age_days"] and 44 < h["file_age_days"] < 47, h["file_age_days"]
    ok("W21: eine 45 Tage alte cookies.txt wird als Warnung gemeldet")

    # --- 7) Die Reparatur haengt an der mtime, nicht am Aufruf ----------
    # Das Deck pollt im Sekundentakt. Haenge der Versuch am Aufruf, stuende
    # bei einer nur lesbaren Datei jede Sekunde ein log.error im Journal —
    # und der eine echte Grund ginge darin unter.
    with open(pfad, "w", encoding="utf-8") as f:
        f.write("# Netscape HTTP Cookie File\n")
        f.write(".tiktok.com\tTRUE\t/\tTRUE\tSession\tsessionid\tx\n")
        f.write(".tiktok.com\tTRUE\t/\tTRUE\t0\tsessionid_ss\ty\n")
        f.write(".tiktok.com\tTRUE\t/\tTRUE\t0\ttt_csrf_token\tz\n")
    _konf()
    h1 = _ck.gesundheit()
    h2 = _ck.gesundheit()
    h3 = _ck.gesundheit()
    assert h1["total"] >= 1, "die krumme Datei wurde gar nicht gelesen: %r" % h1
    assert PROT["repariert"] == 1, \
        "die Reparatur laeuft bei jedem Poll (%dx statt 1x)" % PROT["repariert"]
    assert h2["status"] == h3["status"]
    ok("W21: eine krumme Datei wird EINMAL je Dateistand repariert, nicht je Poll")

    for _f in (pfad,):
        try:
            _os.remove(_f)
        except OSError:
            pass
    try:
        _os.rmdir(verzeichnis)
    except OSError:
        pass


def _test_v42_w22_overlaytext():
    """v4.2-W22: die kleinen Bausteine der Sendebild-Texte stehen in
    nc/overlaytext.py — fuenf Helfer, quer durch die Restream-Overlay-Logik
    an 14+6+2+9+3 Stellen benutzt, aber selbst nie einzeln aufrufbar, weil
    sie mitten in bot.py standen.

    Der Risikotraeger ist ov_atomic_write: schreibt es nicht wirklich atomar,
    sieht ffmpeg/drawtext fuer einen Frame eine halb geschriebene Datei —
    ein Fehler, den man nur im Sendebild selbst sieht, nie im Log.
    """
    import os as _os
    from nc import overlaytext as _ot

    # --- 1) ov_oneline: eine Zeile, gekappt, ohne doppelte Leerzeichen ---
    assert _ot.ov_oneline("  hallo   welt  ", 80) == "hallo welt"
    assert _ot.ov_oneline("a\nb\tc", 80) == "a b c", "Zeilenumbruch/Tab bleibt stehen"
    assert _ot.ov_oneline(None, 80) == ""
    assert _ot.ov_oneline("x" * 100, 10) == "x" * 10
    ok("W22: ov_oneline glaettet Whitespace und kappt hart bei maxlen")

    # --- 2) ov_bar: Balken proportional, ohne Ziel leer ------------------
    assert _ot.ov_bar(0, 0) == "", "ohne Ziel darf kein Balken erscheinen"
    assert _ot.ov_bar(5, 10, width=10) == "█████░░░░░"
    assert _ot.ov_bar(-5, 10, width=4) == "░░░░", "negativer Stand wird nicht negativ gefuellt"
    assert _ot.ov_bar(999, 10, width=4) == "████", "ueber dem Ziel laeuft der Balken nicht ueber"
    ok("W22: ov_bar fuellt proportional, gedeckelt auf [0,1]")

    # --- 3) ov_atomic_write: DAS ist der Risikotraeger -------------------
    # Eine Race zwischen einem lesenden ffmpeg und einem schreibenden Bot
    # laesst sich in einem schnellen Unit-Test nicht zuverlaessig provozieren
    # — deshalb zusaetzlich strukturell geprueft: es MUSS ueber eine Tmp-Datei
    # + os.replace() gehen, in dieser Reihenfolge. Ein direktes open(path,"w")
    # waere nicht atomar; ffmpeg koennte fuer einen Frame eine halb
    # geschriebene Datei sehen.
    import ast as _ast
    _oq = open("nc/overlaytext.py", encoding="utf-8").read()
    _fn = next(n for n in _ast.walk(_ast.parse(_oq))
               if isinstance(n, _ast.FunctionDef) and n.name == "ov_atomic_write")
    _rumpf = _ast.get_source_segment(_oq, _fn)
    _schreib = _rumpf.find('open(tmp, "w"')
    _tausch = _rumpf.find("os.replace(tmp, path)")
    assert _schreib >= 0 and _tausch > _schreib, \
        "ov_atomic_write schreibt nicht mehr ueber eine Tmp-Datei + os.replace"

    d = _ph.verzeichnis()
    ziel = _os.path.join(d, "unter", "ordner", "titel.txt")
    _ot.ov_atomic_write(ziel, "erster Text")
    assert open(ziel, encoding="utf-8").read() == "erster Text"
    # Verzeichnis wird bei Bedarf angelegt — drawtext braucht den Pfad VOR
    # dem ersten Schreiben, sonst zeigt es dauerhaft nichts.
    assert _os.path.isdir(_os.path.dirname(ziel))
    # Kein Tmp-Rest nach einem geglueckten Schreiben.
    reste = [f for f in _os.listdir(_os.path.dirname(ziel)) if f != "titel.txt"]
    assert not reste, "Tmp-Datei bleibt nach erfolgreichem Schreiben liegen: %r" % reste
    # Ueberschreiben ersetzt vollstaendig, kein Anhaengen.
    _ot.ov_atomic_write(ziel, "kurz")
    assert open(ziel, encoding="utf-8").read() == "kurz"
    # Ein Fehler wird geschluckt, nicht geworfen — ein Overlay-Feld, das
    # nicht schreibt, darf die Aufnahme nicht mitreissen.
    _ot.ov_atomic_write("/root/darf-hier-nicht-existieren/x.txt", "x")
    ok("W22: ov_atomic_write legt Ordner an, ersetzt statt anzuhaengen, schluckt Fehler")

    # --- 4) latest_popularity: neuester Wert, 0 ohne Treffer -------------
    import sqlite3
    conn = sqlite3.connect(":memory:")
    conn.row_factory = sqlite3.Row
    conn.execute("CREATE TABLE profile_snapshots(username TEXT, follower_count INT, captured_at TEXT)")
    assert _ot.latest_popularity(conn, "henry") == 0, "ohne Zeilen muss 0 kommen, nicht None/Crash"
    # Der hoechste Wert ist absichtlich NICHT der neueste: ein ORDER BY auf
    # der falschen Spalte (follower_count statt captured_at) faellt sonst
    # nicht auf, weil beide Sortierungen zufaellig dasselbe Ergebnis gaeben.
    conn.execute("INSERT INTO profile_snapshots VALUES ('henry', 999, '2020-01-01')")
    conn.execute("INSERT INTO profile_snapshots VALUES ('henry', 250, '2026-01-02')")
    conn.execute("INSERT INTO profile_snapshots VALUES ('henry', 10, '2025-01-01')")
    assert _ot.latest_popularity(conn, "henry") == 250, \
        "es muss der NEUESTE Stand sein (250), nicht der hoechste (999)"
    assert _ot.latest_popularity(conn, "jemand_anders") == 0
    conn.execute("INSERT INTO profile_snapshots VALUES ('null_wert', NULL, '2026-01-01')")
    assert _ot.latest_popularity(conn, "null_wert") == 0, "NULL darf nicht crashen"
    ok("W22: latest_popularity liest den neuesten, nicht den hoechsten Stand")

    # --- 5) overlay_src_ok: 'kick' ist Default, 'both' oeffnet alles -----
    _ot.configure(gift_source="kick")
    assert _ot.overlay_src_ok("kick") and not _ot.overlay_src_ok("tiktok")
    _ot.configure(gift_source="both")
    assert _ot.overlay_src_ok("kick") and _ot.overlay_src_ok("tiktok")
    _ot.configure(gift_source="tiktok")
    assert _ot.overlay_src_ok("tiktok") and not _ot.overlay_src_ok("kick")
    _ot.configure(gift_source="kick")   # zurueck auf den Default fuer andere Tests
    ok("W22: overlay_src_ok folgt der konfigurierten Gift-Quelle, 'both' oeffnet alles")


def _test_v42_w23_aufnahmekategorie():
    """v4.2-W23: warum eine Aufnahme so geendet hat, steht in
    nc/aufnahmekategorie.py — ein 87-Zeilen-if/elif ueber stderr, Returncode,
    Dateigroesse und Dauer, das mitten in handle_recording_finished (658
    Zeilen) stand. Das ist die Grundlage JEDER Fehlerstatistik im Dashboard,
    und die Kette war nie einzeln aufrufbar.

    Der eigentliche Vertrag ist die REIHENFOLGE, nicht die einzelnen Muster:
    mehrere Kategorien konkurrieren um dieselbe stderr-Zeile, und vertauscht
    zaehlt ein toter Stream als Codec-Fehler oder ein HEVC-Stream als
    generischer Stall.
    """
    from nc import aufnahmekategorie as _ak

    def kat(text, stall=False, rc=1, fe=True, dur=60):
        return _ak.kategorisiere(text, stall, rc, fe, dur)

    # --- 1) HEVC steht VOR allem anderen ---------------------------------
    # Ohne Vorrang faellt ein HEVC-Stream, der auch "Could not write header"
    # zeigt, als codec_header_fail durch — dieselbe Zeile, falsche Antwort.
    assert kat("Video codec is not implemented", stall=True) == "hevc_unsupported"
    assert kat("update your ffmpeg to a more recent version") == "hevc_unsupported"
    assert kat("stream 0:0: unknown codec: Video none") == "hevc_unsupported"
    assert kat("unknown codec: Audio none") != "hevc_unsupported", \
        "unknown codec OHNE 'video' darf nicht als HEVC zaehlen"
    ok("W23: hevc_unsupported hat Vorrang, auch vor stall_killed")

    # --- 2) stream_dead steht VOR codec_header_fail ----------------------
    # Ein 404 (tote URL) zeigt oft AUCH "could not write header" als Folge —
    # das darf nicht als Codec-Fehler gezaehlt werden, sonst greift der
    # Stream-Tod-Backoff (nc/aufnahmefolge) nie.
    assert kat("HTTP error 404 Not Found. Could not write header for output") \
        == "stream_dead"
    assert kat("Server returned 404") == "stream_dead"
    ok("W23: eine tote URL zaehlt als stream_dead, nicht als Codec-Fehler")

    # --- 3) codec_header_fail nur INNERHALB von stall_killed -------------
    assert kat("Could not write header for output file", stall=True) == "codec_header_fail"
    assert kat("incorrect codec parameters", stall=True) == "codec_header_fail"
    # Dieselbe Zeile OHNE stall_killed darf NICHT codec_header_fail werden —
    # das Signal gilt nur als Erklaerung fuer einen echten Stall.
    assert kat("Could not write header for output file", stall=False) != "codec_header_fail"
    assert kat("random garbage stderr", stall=True) == "stall_killed"
    ok("W23: codec_header_fail nur als Erklaerung eines echten Stalls")

    # --- 4) '403' zaehlt GROSS/klein-unabhaengig, gegen den ROHEN Text ---
    # Der numerische Code hat keine Gross-/Kleinschreibung; "forbidden" ist
    # ein Wort und laeuft ueber die kleingeschriebene Fassung.
    assert kat("HTTP 403") == "forbidden_403"
    assert kat("FORBIDDEN") == "forbidden_403"
    assert kat("Forbidden") == "forbidden_403"
    ok("W23: 403 und 'forbidden' fuehren beide zu forbidden_403")

    # --- 5) empty_output nur bei rc==0 UND fehlender Datei ---------------
    assert kat("irgendwas unbekanntes", rc=0, fe=False) == "empty_output"
    assert kat("irgendwas unbekanntes", rc=0, fe=True) == "fail"
    assert kat("irgendwas unbekanntes", rc=1, fe=False) == "fail"
    ok("W23: empty_output verlangt rc==0 UND keine Datei, nicht nur eins von beiden")

    # --- 6) early_disconnect ist eine UMWIDMUNG, kein eigener Zweig ------
    # Nur "fail" wird umgewidmet — jede spezifischere Kategorie (403, tot,
    # Codec, HEVC, Timeout, …) sagt schon mehr als "gekickt" und bleibt
    # stehen, selbst wenn sie <30s und rc!=0 ist.
    assert kat("irgendwas unbekanntes", rc=1, fe=True, dur=10) == "early_disconnect"
    assert kat("irgendwas unbekanntes", rc=1, fe=True, dur=30) == "fail", \
        "30s ist NICHT mehr 'kurz' (Grenze: <30, nicht <=30)"
    assert kat("irgendwas unbekanntes", rc=0, fe=True, dur=10) == "fail", \
        "rc==0 mit Fehlertext bleibt 'fail', kein Disconnect ohne Fehler-rc"
    assert kat("HTTP 403", rc=1, fe=True, dur=5) == "forbidden_403", \
        "eine spezifischere Kategorie wird NICHT von early_disconnect ueberschrieben"
    assert kat("random garbage", stall=True, rc=1, fe=True, dur=5) == "stall_killed", \
        "ein echter Stall wird nicht zum Disconnect umgewidmet, auch wenn er kurz war"
    ok("W23: early_disconnect widmet nur ein generisches 'fail' um, nichts Spezifischeres")

    # --- 7) Verhaltensgleichheit gegen die ALTE Kette, erschoepfend ------
    # Referenzimplementierung ist eine woertliche Kopie der Kette, wie sie
    # vor W23 in bot.py stand — ueber ein Gitter aus 756 Kombinationen
    # verglichen. Das ist der eigentliche Beweis, dass das Verschieben
    # nichts verschoben hat: die Prioritaeten UND die Uebergaenge.
    def _alte_kette(stderr_text, stall_killed0, returncode, file_exists, duration):
        stderr_lc = stderr_text.lower()
        _hevc_sig = ("is not implemented" in stderr_lc
                     or "update your ffmpeg" in stderr_lc
                     or "0x000c" in stderr_lc
                     or "[12][0][0][0]" in stderr_lc
                     or ("unknown codec" in stderr_lc and "video" in stderr_lc))
        if _hevc_sig:
            category = "hevc_unsupported"
        elif ("http error 404" in stderr_lc or "404 not found" in stderr_lc
              or "server returned 404" in stderr_lc):
            category = "stream_dead"
        elif stall_killed0:
            if ("could not write header" in stderr_lc
                    or "incorrect codec parameters" in stderr_lc
                    or "error opening output file" in stderr_lc):
                category = "codec_header_fail"
            else:
                category = "stall_killed"
        elif "no playable streams" in stderr_lc or "this user is offline" in stderr_lc:
            category = "offline_or_protected"
        elif "403" in stderr_text or "forbidden" in stderr_lc:
            category = "forbidden_403"
        elif "timeout" in stderr_lc:
            category = "timeout"
        elif "no plugin" in stderr_lc:
            category = "no_plugin"
        elif returncode == 0 and not file_exists:
            category = "empty_output"
        else:
            category = "fail"
        if (duration < 30 and returncode != 0
                and category == "fail" and not stall_killed0):
            category = "early_disconnect"
        return category

    import itertools
    FRAGMENTE = ["", "empty stderr", "Video codec is not implemented",
                 "Update your FFmpeg", "0x000C codec tag", "[12][0][0][0]",
                 "unknown codec: Video stream", "HTTP error 404", "404 Not Found",
                 "Server returned 404", "Could not write header for output",
                 "incorrect codec parameters", "Error opening output file /tmp/x.mp4",
                 "No playable streams found", "This user is offline",
                 "403 Forbidden", "FORBIDDEN", "Connection timeout",
                 "no plugin found", "random garbage stderr text",
                 "moov atom not found"]
    n = 0
    for text, stall, rc, fe, dur in itertools.product(
            FRAGMENTE, (False, True), (0, 1, -9), (False, True), (5, 25, 45)):
        a = _alte_kette(text, stall, rc, fe, dur)
        b = _ak.kategorisiere(text, stall, rc, fe, dur)
        assert a == b, (text, stall, rc, fe, dur, "alt=%s neu=%s" % (a, b))
        n += 1
    ok(f"W23: {n} Kombinationen verhaltensgleich zur alten Kette")


def _test_v42_w24_memeklip():
    """v4.2-W24: die Meme-Erkennung fuer den Auto-Clipper steht in
    nc/memeklip.py — erste Welle eines mehrteiligen Vorhabens (Discord-
    Auto-Post jetzt; Twitch-Clips waehrend Restream und YouTube-Upload sind
    eigene, spaetere Wellen mit eigenem OAuth-Scope).

    Der Risikotraeger ist NICHT das Prompt-Muster, sondern: (a) dass der Pfad
    NIE ueber ai_chat/azrael_chat laeuft — beide bevorzugen Claude, sobald
    ein Anthropic-Key gesetzt ist, und ein Chat-Poll alle paar Sekunden
    wuerde laufend Claude-Budget verbrennen; (b) dass ein Fehlalarm nicht
    grundlos einen OEFFENTLICHEN Auto-Post ausloest, weil `soll_clippen`
    ein unlesbares Modellergebnis als Nein wertet, nie als Ja.
    """
    from nc import memeklip as _mk

    # --- 1) Ein unlesbares Urteil ist NIE ein Freispruch, aber auch NIE
    # ein Clip — beides waere falsch: ein Freispruch verstecke ein totes
    # Modell, ein Clip poste automatisch bei Muell.
    assert _mk.lies_urteil("kein json hier") is None
    assert _mk.lies_urteil("") is None
    assert _mk.lies_urteil(None) is None
    assert not _mk.soll_clippen(None)
    assert not _mk.soll_clippen(_mk.lies_urteil("garbage"))
    ok("W24: ein unlesbares Urteil ist weder Freispruch noch Clip-Ausloeser")

    # --- 2) Der Codeblock-Zaun wird abgestreift, wie bei nc.modki -------
    roh = '```json\n{"meme": 0.9, "grund": "alle spammen dasselbe Wort"}\n```'
    u = _mk.lies_urteil(roh)
    assert u == {"meme": 0.9, "grund": "alle spammen dasselbe Wort"}, u
    ok("W24: ``` json ... ``` wird erkannt, wie beim Moderations-Klassifikator")

    # --- 3) Der Wert wird auf [0,1] gedeckelt, der Grund auf 60 Zeichen -
    u = _mk.lies_urteil('{"meme": 5.0, "grund": "' + "x" * 100 + '"}')
    assert u["meme"] == 1.0, u
    assert len(u["grund"]) == 60, len(u["grund"])
    u = _mk.lies_urteil('{"meme": -3.0}')
    assert u["meme"] == 0.0, u
    ok("W24: meme-Wert gedeckelt auf [0,1], Grund auf 60 Zeichen gekappt")

    # --- 4) NaN aus kaputtem JSON darf nicht durchrutschen --------------
    # Pythons json.loads akzeptiert NaN als Erweiterung; float('nan') >= x
    # ist IMMER False, ABER auch nie eine saubere Ablehnung — ohne den
    # Sonderfall waere ein NaN-Urteil weder Ja noch klar Nein, sondern ein
    # stiller Bug, der erst im Dashboard als "NaN%" auffaellt.
    u = _mk.lies_urteil('{"meme": NaN, "grund": "x"}')
    assert u is None, u
    ok("W24: ein NaN-Wert gilt als unlesbar, nicht als Zahl")

    # --- 5) Die Schwelle entscheidet hart, kein Runden -------------------
    genau = _mk.lies_urteil('{"meme": 0.72, "grund": "grenzwertig"}')
    assert _mk.soll_clippen(genau, 0.72), "die Schwelle selbst muss noch zaehlen"
    knapp_drunter = _mk.lies_urteil('{"meme": 0.71, "grund": "knapp drunter"}')
    assert not _mk.soll_clippen(knapp_drunter, 0.72)
    ok("W24: die Schwelle ist inklusiv, knapp drunter zaehlt nicht")

    # --- 6) Das Fenster verfaellt nach ALTER, nicht nach Zeilenzahl -----
    f = _mk.Fenster()
    f.merken("kick", "alt: vor drei Minuten", 0.0)
    f.merken("tiktok", "neu: gerade eben", 170.0)
    aktuell = f.text(180.0, max_alter_s=90)
    assert "neu" in aktuell and "alt" not in aktuell, aktuell
    # Beide Quellen erscheinen quellmarkiert, in der Reihenfolge, in der sie
    # eintrafen.
    f2 = _mk.Fenster()
    f2.merken("kick", "erstes", 10.0)
    f2.merken("discord", "zweites", 11.0)
    text = f2.text(11.0, max_alter_s=90)
    assert text == "[kick] erstes\n[discord] zweites", repr(text)
    ok("W24: das Fenster verfaellt nach Alter, quellmarkiert, chronologisch")

    # --- 7) Ein Hart-Deckel verhindert unbegrenztes Wachstum ------------
    f3 = _mk.Fenster(max_eintraege=5)
    for i in range(20):
        f3.merken("kick", f"zeile{i}", float(i))
    assert len(f3.text(1000.0, max_alter_s=10_000).splitlines()) == 5
    ok("W24: der Puffer waechst nicht unbegrenzt, auch bei einem haengenden Aufrufer")

    # --- 8) leeren() nach einem Treffer verhindert Doppel-Clips ---------
    f4 = _mk.Fenster()
    f4.merken("kick", "hype hype hype", 5.0)
    assert f4.text(5.0) != ""
    f4.leeren()
    assert f4.text(5.0) == ""
    ok("W24: leeren() nach einem Treffer nimmt dem Fenster den Hype weg")

    # --- 9) NIE ueber ai_chat/azrael_chat — nur ueber nc.freeai direkt --
    # ai_chat bevorzugt Claude, sobald ein Anthropic-Key gesetzt ist
    # (v4.0-W65). Ein Poll alle paar Sekunden ueber diesen Pfad wuerde
    # laufend Claude-Budget verbrennen, obwohl der Betreiber explizit die
    # KOSTENLOSE Erkennung wollte.
    import ast as _ast
    q = open("bot.py", encoding="utf-8").read()
    fn = next(n for n in _ast.walk(_ast.parse(q))
              if isinstance(n, _ast.AsyncFunctionDef) and n.name == "_meme_klassifizieren")
    rumpf = _ast.get_source_segment(q, fn)
    assert "_nc_freeai.chat(" in rumpf, "der Meme-Klassifikator ruft nc.freeai nicht direkt"
    assert "ai_chat(" not in rumpf and "azrael_chat(" not in rumpf, \
        "der Meme-Klassifikator laeuft ueber einen Pfad, der Claude bevorzugt"
    ok("W24: der Klassifikator ruft nc.freeai direkt, nie ai_chat/azrael_chat")

    # --- 9b) Der env-Default in bot.py muss die Konstante hier widerspiegeln
    # tools/gen_env_example.py verlangt fuer env_float() einen WOERTLICHEN
    # Zahlenwert (kein Konstantenverweis) — sonst verschwindet die Variable
    # klanglos aus .env.example. Der Literalwert kann deshalb von der
    # Konstante hier abdriften, ohne dass irgendetwas es meldet, ausser
    # dieser Vertrag.
    _lit = _ast.parse(q)
    _wert = None
    for _n in _ast.walk(_lit):
        if (isinstance(_n, _ast.Call) and isinstance(_n.func, _ast.Attribute)
                and _n.func.attr == "env_float" and _n.args
                and isinstance(_n.args[0], _ast.Constant)
                and _n.args[0].value == "MEME_CLIP_SCHWELLE"):
            _wert = _n.args[1].value
    assert _wert == _mk.STANDARD_SCHWELLE, \
        "bot.py's env-Default (%r) weicht von nc.memeklip.STANDARD_SCHWELLE (%r) ab" \
        % (_wert, _mk.STANDARD_SCHWELLE)
    ok("W24: der .env-Default fuer die Schwelle stimmt mit der Konstante ueberein")

    # --- 10) Eigenes Budget, getrennt von AZRAEL_MAX_CALLS_MIN ----------
    # Ein gemeinsamer Deckel mit AZRAEL koennte die Chat-Antworten
    # verhungern lassen, sobald der Chat gerade hyped (also genau dann,
    # wenn AZRAEL am ehesten gefragt wird UND ein Meme am wahrscheinlichsten
    # ist) — ein eigener Deckel entkoppelt beide Budgets voneinander.
    assert "_MEME_CALL_TS = _collections.deque()" in q, \
        "_MEME_CALL_TS ist keine eigene, frische Deque mehr — geteilt mit AZRAEL " \
        "koennte ein hypender Chat (genau der Moment, in dem beide Pfade am " \
        "ehesten anfragen) den jeweils anderen Budget-Deckel verhungern lassen"
    assert "_MEME_CALL_TS.append(" in rumpf, "das Meme-Budget wird nicht fortgeschrieben"
    ok("W24: das Meme-Budget ist ein eigenes Register, getrennt von AZRAEL")


def _test_v42_w27_twitch_clip():
    """v4.2-W27: der Twitch-Teil des Auto-Clippers — nc.twitchoauth.create_clip().

    Twitch-Clips sind ANDERS als YouTube-Upload oder eine lokale Datei: die
    Clip-Erstellung schneidet aus der GERADE LAUFENDEN eigenen Twitch-
    Uebertragung, nimmt keine Datei entgegen und braucht den Scope
    clips:edit — den eine vor dieser Welle erteilte Autorisierung nicht
    traegt. Der Risikotraeger ist deshalb nicht der Erfolgsfall, sondern die
    DREI Wege, auf denen es fehlschlagen MUSS, ohne den Aufrufer abstuerzen
    zu lassen: fehlender Scope, Kanal nicht live, kein Token ueberhaupt.
    """
    import asyncio as _asyncio
    import logging as _logging
    import time as _time

    import nc.twitchoauth as _tw

    class _Antwort:
        def __init__(self, status, payload=None, text=""):
            self.status = status
            self._payload = payload if payload is not None else {}
            self._text = text

        async def json(self, content_type=None):
            return self._payload

        async def text(self):
            return self._text

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Sitzung:
        def __init__(self, get_antwort, post_antwort):
            self._get = get_antwort
            self._post = post_antwort
            self._timeout = None    # _own_broadcaster_id liest session._timeout
            self.aufrufe = []

        def get(self, url, **kw):
            self.aufrufe.append(("get", url, kw))
            return self._get

        def post(self, url, **kw):
            self.aufrufe.append(("post", url, kw))
            return self._post

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Aio:
        def __init__(self, get_antwort, post_antwort):
            self._get, self._post = get_antwort, post_antwort
            self.sitzung = None

        def ClientSession(self):
            self.sitzung = _Sitzung(self._get, self._post)
            return self.sitzung

        def ClientTimeout(self, **k):
            return None

    alt_level = _logging.getLogger("TikTokBot").level
    _logging.getLogger("TikTokBot").setLevel(_logging.CRITICAL)
    umgebung = {k: os.environ.get(k) for k in
                ("TWITCH_CLIENT_ID", "TWITCH_CLIENT_SECRET")}
    try:
        os.environ.update(TWITCH_CLIENT_ID="x", TWITCH_CLIENT_SECRET="y")
        # access_token() liest zuerst den Cache — mit einem gueltigen
        # Eintrag darin faellt der ganze Refresh-Netzwerk-Pfad weg, und die
        # Attrappe unten muss nur GET /users + POST /clips beantworten,
        # genau die zwei Aufrufe, um die es in diesem Vertrag geht.
        _tw._state["access"] = "faketoken"
        _tw._state["access_exp"] = _time.time() + 3600

        # --- 1) Erfolg: broadcaster_id aufgeloest, Clip angenommen -------
        aio = _Aio(_Antwort(200, {"data": [{"id": "b1"}]}),
                   _Antwort(202, {"data": [{"id": "c1",
                                            "edit_url": "https://clips.twitch.tv/c1/edit"}]}))
        ok_, wert = _asyncio.run(_tw.create_clip(aio))
        assert ok_ and wert == "https://clips.twitch.tv/c1/edit", (ok_, wert)
        assert aio.sitzung.aufrufe[0][0] == "get" and aio.sitzung.aufrufe[1][0] == "post", \
            "broadcaster_id muss VOR dem Clip-POST aufgeloest werden"
        assert aio.sitzung.aufrufe[1][2]["params"]["broadcaster_id"] == "b1", \
            "der POST traegt nicht die aufgeloeste broadcaster_id"
        ok("W27: erfolgreicher Clip liefert die edit_url, broadcaster_id zuerst aufgeloest")

        # --- 1b) Ein "Erfolg" ohne Clip-Daten ist KEIN Erfolg ---------------
        # 202 mit leerem data[] waere sonst (True, None) — ein Clip, den
        # niemand wiederfindet, weil keine edit_url je irgendwo landet.
        aio1b = _Aio(_Antwort(200, {"data": [{"id": "b1"}]}), _Antwort(202, {"data": []}))
        ok_, wert = _asyncio.run(_tw.create_clip(aio1b))
        assert not ok_, "202 mit leerem data[] gilt als Erfolg — der Clip ist unauffindbar"
        ok("W27: ein 202 ohne Clip-Daten zaehlt nicht als Erfolg")

        # --- 2) Fehlender Scope: 401 wird ERKANNT, nicht nur durchgereicht -
        aio2 = _Aio(_Antwort(200, {"data": [{"id": "b1"}]}),
                    _Antwort(401, text="missing scope clips:edit"))
        ok_, wert = _asyncio.run(_tw.create_clip(aio2))
        assert not ok_ and "clips:edit" in wert and "neu verbinden" in wert, wert
        ok("W27: ein fehlender Scope wird als klare Handlungsanweisung gemeldet")

        # --- 3) Kanal nicht live: 404 ist ein Ergebnis, kein Absturz ------
        aio3 = _Aio(_Antwort(200, {"data": [{"id": "b1"}]}),
                    _Antwort(404, text="not found"))
        ok_, wert = _asyncio.run(_tw.create_clip(aio3))
        assert not ok_ and "nicht live" in wert, wert
        ok("W27: ein nicht-live-Kanal fuehrt zu einer verstaendlichen Ablehnung, keinem Crash")

        # --- 4) broadcaster_id nicht aufloesbar -> gar kein POST ----------
        aio4 = _Aio(_Antwort(200, {"data": []}), _Antwort(202, {"data": [{"id": "sollte-nie-gerufen"}]}))
        ok_, wert = _asyncio.run(_tw.create_clip(aio4))
        assert not ok_ and "broadcaster_id" in wert, wert
        assert not any(a[0] == "post" for a in aio4.sitzung.aufrufe), \
            "es wird trotz unaufloesbarer broadcaster_id ein Clip versucht"
        ok("W27: ohne aufloesbare broadcaster_id wird gar nicht erst gepostet")

        # --- 5) Ein Netzwerkfehler ist ein Ergebnis, kein Absturz ---------
        class _KaputteSitzung:
            async def __aenter__(self):
                raise ConnectionError("kein Netz")
            async def __aexit__(self, *a):
                return False
        class _KaputtesAio:
            def ClientSession(self):
                return _KaputteSitzung()
            def ClientTimeout(self, **k):
                return None
        ok_, wert = _asyncio.run(_tw.create_clip(_KaputtesAio()))
        assert not ok_ and wert, wert
        ok("W27: ein Netzwerkfehler liefert (False, Grund) statt eine Exception hochzureichen")

        # --- 6) Ohne Token gar kein Netzwerkzugriff -----------------------
        _tw._state["access"] = ""
        _tw._state["access_exp"] = 0.0
        _tw._state["refresh"] = ""
        aio5 = _Aio(_Antwort(200, {"data": [{"id": "b1"}]}), _Antwort(202, {"data": [{"id": "x"}]}))
        ok_, wert = _asyncio.run(_tw.create_clip(aio5))
        assert not ok_ and wert == "kein Token", wert
        assert aio5.sitzung is None, "ohne Token wird trotzdem eine Session eroeffnet"
        ok("W27: ohne Token wird gar nicht erst versucht, ein Netzwerkzugriff bleibt aus")

        # --- 7) Die Verdrahtung im Bot: erst NACH dem lokalen Clip, ------
        # nebenlaeufig gespawnt (ein Twitch-Fehlschlag darf den lokalen
        # Clip nicht verzoegern), und nur wenn ein Token bereitsteht.
        b = open("bot.py", encoding="utf-8").read()
        i = b.find("async def clip_moment(")
        rumpf = b[i:i + 6200]
        assert "TWITCH_CLIP_ENABLED and _twoauth.status().get(\"ready\")" in rumpf, \
            "Twitch-Clip wird ohne Bereitschaftspruefung versucht"
        assert '_spawn(_twitch_clip_versuchen(username, reason)' in rumpf, \
            "Twitch-Clip laeuft nicht nebenlaeufig — ein Fehlschlag wuerde den lokalen Clip verzoegern"
        assert rumpf.find("CLIP_DISCORD_UPLOAD") < rumpf.find("TWITCH_CLIP_ENABLED"), \
            "Twitch-Versuch steht vor dem Discord-Post statt danach"
        ok("W27: der Bot versucht Twitch erst nach dem lokalen Clip, nebenlaeufig, bereitschaftsgeprueft")
    finally:
        _logging.getLogger("TikTokBot").setLevel(alt_level)
        for k, v in umgebung.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        _tw._state["access"] = ""
        _tw._state["access_exp"] = 0.0


def _test_v42_w29_youtube_upload():
    """v4.2-W29: der YouTube-Teil des Auto-Clippers — nc.ytoauth.upload_clip().

    Anders als Twitch (schneidet aus dem laufenden Stream) nimmt YouTube eine
    echte Datei entgegen, in zwei Schritten — resumable Upload: ein POST legt
    die Session an und liefert die Upload-URL im Location-Header, ein PUT
    traegt die Bytes. Der Risikofall: Schritt 1 darf bei 401/403/Quota NIE zu
    Schritt 2 fuehren — das waere ein Upload ohne gueltige Session, oder
    einer, der das schon leere Tageskontingent weiter verbrennt.
    """
    import asyncio as _asyncio
    import logging as _logging
    import tempfile as _tempfile
    import time as _time

    import nc.ytoauth as _yt

    class _Antwort:
        def __init__(self, status, payload=None, text="", headers=None):
            self.status = status
            self._payload = payload if payload is not None else {}
            self._text = text
            self.headers = headers or {}

        async def json(self, content_type=None):
            return self._payload

        async def text(self):
            return self._text

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Sitzung:
        def __init__(self, post_antwort, put_antwort=None):
            self._post = post_antwort
            self._put = put_antwort
            self.aufrufe = []

        def post(self, url, **kw):
            self.aufrufe.append(("post", url, kw))
            return self._post

        def put(self, url, **kw):
            self.aufrufe.append(("put", url, kw))
            return self._put

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Aio:
        def __init__(self, post_antwort, put_antwort=None):
            self._post, self._put = post_antwort, put_antwort
            self.sitzung = None

        def ClientSession(self):
            self.sitzung = _Sitzung(self._post, self._put)
            return self.sitzung

        def ClientTimeout(self, **k):
            return None

    alt_level = _logging.getLogger("TikTokBot").level
    _logging.getLogger("TikTokBot").setLevel(_logging.CRITICAL)
    umgebung = {k: os.environ.get(k) for k in
                ("YOUTUBE_CLIENT_ID", "YOUTUBE_CLIENT_SECRET")}
    tmp = _tempfile.NamedTemporaryFile(suffix=".mp4", delete=False)
    tmp.write(b"x" * 2048)
    tmp.close()
    try:
        os.environ.update(YOUTUBE_CLIENT_ID="x", YOUTUBE_CLIENT_SECRET="y")
        _yt._state["access"] = "faketoken"
        _yt._state["access_exp"] = _time.time() + 3600

        # --- 1) Erfolg: Session angelegt, Datei hochgeladen, Video-URL kommt zurueck
        aio = _Aio(_Antwort(200, headers={"Location": "https://upload.example/session1"}),
                   _Antwort(200, {"id": "vid123"}))
        ok_, wert = _asyncio.run(_yt.upload_clip(aio, tmp.name, "Titel"))
        assert ok_ and wert == "https://youtu.be/vid123", (ok_, wert)
        assert aio.sitzung.aufrufe[0][0] == "post" and aio.sitzung.aufrufe[1][0] == "put", \
            "die Session muss VOR dem Datei-Upload angelegt werden"
        assert aio.sitzung.aufrufe[1][1] == "https://upload.example/session1", \
            "der PUT geht nicht an die vom Location-Header gelieferte Session-URL"
        ok("W29: erfolgreicher Upload liefert die Video-URL, Session zuerst angelegt")

        # --- 1b) eine Erfolgsantwort ohne Video-ID ist KEIN Erfolg ----------
        aio1b = _Aio(_Antwort(200, headers={"Location": "https://upload.example/s"}),
                     _Antwort(200, {}))
        ok_, wert = _asyncio.run(_yt.upload_clip(aio1b, tmp.name, "Titel"))
        assert not ok_, "eine Antwort ohne Video-ID gilt als Erfolg"
        ok("W29: eine Erfolgsantwort ohne Video-ID zaehlt nicht als Erfolg")

        # --- 2) Fehlender Scope: 401 wird ERKANNT, kein PUT wird versucht ---
        aio2 = _Aio(_Antwort(401, text="missing scope"))
        ok_, wert = _asyncio.run(_yt.upload_clip(aio2, tmp.name, "Titel"))
        assert not ok_ and "youtube.upload" in wert and "neu verbinden" in wert, wert
        assert not any(a[0] == "put" for a in aio2.sitzung.aufrufe), \
            "ein PUT wird trotz fehlendem Scope versucht"
        ok("W29: ein fehlender Scope wird als klare Handlungsanweisung gemeldet, kein Upload-Versuch")

        # --- 3) Tageskontingent leer: 403 mit 'quota' wird erkannt ----------
        aio3 = _Aio(_Antwort(403, text="quotaExceeded: Daily Limit"))
        ok_, wert = _asyncio.run(_yt.upload_clip(aio3, tmp.name, "Titel"))
        assert not ok_ and "Tageskontingent" in wert, wert
        ok("W29: ein leeres Tageskontingent wird als solches erkannt, nicht als nackter 403")

        # --- 4) Ohne Location-Header keine Upload-URL -> kein PUT -----------
        aio4 = _Aio(_Antwort(200, headers={}))
        ok_, wert = _asyncio.run(_yt.upload_clip(aio4, tmp.name, "Titel"))
        assert not ok_ and "Upload-Session" in wert, wert
        ok("W29: ohne Location-Header wird kein Upload versucht")

        # --- 5) Ein Netzwerkfehler ist ein Ergebnis, kein Absturz -----------
        class _KaputteSitzung:
            async def __aenter__(self):
                raise ConnectionError("kein Netz")
            async def __aexit__(self, *a):
                return False
        class _KaputtesAio:
            def ClientSession(self):
                return _KaputteSitzung()
            def ClientTimeout(self, **k):
                return None
        ok_, wert = _asyncio.run(_yt.upload_clip(_KaputtesAio(), tmp.name, "Titel"))
        assert not ok_ and wert, wert
        ok("W29: ein Netzwerkfehler liefert (False, Grund) statt eine Exception hochzureichen")

        # --- 6) Fehlende Datei -> kein Netzwerkzugriff ----------------------
        aio6 = _Aio(_Antwort(200, headers={"Location": "https://upload.example/s"}))
        ok_, wert = _asyncio.run(_yt.upload_clip(aio6, "/pfad/existiert/nicht.mp4", "Titel"))
        assert not ok_ and "Datei" in wert, wert
        assert aio6.sitzung is None, "ohne vorhandene Datei wird trotzdem eine Session eroeffnet"
        ok("W29: eine fehlende Datei fuehrt zu keinem Netzwerkzugriff")

        # --- 7) Ohne Token gar kein Netzwerkzugriff -------------------------
        _yt._state["access"] = ""
        _yt._state["access_exp"] = 0.0
        _yt._state["refresh"] = ""
        aio7 = _Aio(_Antwort(200, headers={"Location": "https://upload.example/s"}))
        ok_, wert = _asyncio.run(_yt.upload_clip(aio7, tmp.name, "Titel"))
        assert not ok_ and wert == "kein Token", wert
        assert aio7.sitzung is None, "ohne Token wird trotzdem eine Session eroeffnet"
        ok("W29: ohne Token wird gar nicht erst versucht, ein Netzwerkzugriff bleibt aus")

        # --- 8) Scope-Vertrag: youtube.upload ergaenzt, nicht ueberzogen ----
        assert set(_yt.SCOPES) == {
            "https://www.googleapis.com/auth/youtube.readonly",
            "https://www.googleapis.com/auth/youtube.force-ssl",
            "https://www.googleapis.com/auth/youtube.upload",
        }, "Readonly + Chat/Moderation + Upload, nicht mehr"
        ok("W29: der Scope-Vertrag deckt genau die drei benoetigten Scopes ab, kein Overreach")

        # --- 9) Verdrahtung im Bot: nach Twitch, nebenlaeufig, Tageskontingent-Deckel
        b = open("bot.py", encoding="utf-8").read()
        i = b.find("async def clip_moment(")
        rumpf = b[i:i + 6600]
        assert 'YOUTUBE_CLIP_ENABLED and _ytoauth.status().get("ready")' in rumpf, \
            "YouTube-Upload wird ohne Bereitschaftspruefung versucht"
        assert '_spawn(_youtube_clip_versuchen(username, out, reason)' in rumpf, \
            "YouTube-Upload laeuft nicht nebenlaeufig — ein Fehlschlag wuerde den lokalen Clip verzoegern"
        assert rumpf.find("TWITCH_CLIP_ENABLED") < rumpf.find("YOUTUBE_CLIP_ENABLED"), \
            "YouTube-Versuch steht nicht nach dem Twitch-Versuch"
        vg = b.find("async def _youtube_clip_versuchen(")
        deckel = b[vg:vg + 900]
        assert "YOUTUBE_CLIP_MAX_PER_DAY" in deckel and "_YOUTUBE_UPLOAD_TS" in deckel, \
            "kein Tageskontingent-Deckel im YouTube-Upload-Pfad"
        ok("W29: der Bot versucht YouTube erst nach Twitch, nebenlaeufig, mit Tageskontingent-Deckel")
    finally:
        _logging.getLogger("TikTokBot").setLevel(alt_level)
        for k, v in umgebung.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        _yt._state["access"] = ""
        _yt._state["access_exp"] = 0.0
        try:
            os.remove(tmp.name)
        except OSError:
            pass


def _test_v42_w14_motd_spricht_englisch():
    """v4.2-W14: die MOTD war zu 0 % uebersetzt und meldete 100 %."""
    import subprocess as _sp
    import sys as _sys

    _sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                     "tools"))
    import i18n_tools as _it

    # ── (1) DIE UNEHRLICHE ZAHL. tools/i18n_tools.py sammelte nur aus den
    # Senken von installer.sh — die es in motd.sh gar nicht gibt. Ergebnis:
    # NICHTS eingesammelt, und trotzdem "100 % Abdeckung" gemeldet, waehrend
    # die Datei zu 0 % uebersetzt war. Eine Zahl, die nur zaehlt, was sie
    # ohnehin kennt, verdeckt genau das, was sie sichtbar machen soll.
    gefunden = _it.sammeln()
    aus_motd = _it._MOTD_SENKEN.findall(
        open("tools/motd.sh", encoding="utf-8").read())
    assert len(aus_motd) > 20, \
        "nur %d Zeichenketten aus den motd-Senken — der Sammler sieht sie nicht" \
        % len(aus_motd)
    assert len(gefunden) > 360, "nur %d insgesamt" % len(gefunden)

    # ── (2) DER EHRLICHE MELDER. Er ist die zweite Haelfte: die Quote sagt,
    # wie viel von dem uebersetzt ist, was der Sammler FINDET. Der Melder
    # sagt, was er gar nicht erst findet.
    for datei in ("tools/motd.sh", "tools/installer.sh", "tools/install.bat"):
        offen = _it.unumschlossen(datei)
        assert not offen, "%s: deutsche Ausgabe an keiner Senke: %r" % (
            datei, offen[:4])

    # Und er muss wirklich anschlagen — sonst prueft er nichts. Zwei Formen,
    # die beide einmal durchgerutscht sind: die nackte printf-Zeile und die
    # ZUWEISUNG mit Farbcode (`EQ="  ${FNT}Kerne  ${R}"` hat kein printf, und
    # der englische Lauf zeigte prompt "Kerne").
    probe = _ph.verzeichnis()
    _alt_root = _it.ROOT
    try:
        _it.ROOT = probe
        with open(os.path.join(probe, "x.sh"), "w", encoding="utf-8") as f:
            f.write('printf "  Dienst nicht gefunden\\n"\n')
        assert _it.unumschlossen("x.sh"), "die nackte printf-Zeile faellt durch"
        with open(os.path.join(probe, "x.sh"), "w", encoding="utf-8") as f:
            f.write('EQ="  ${FNT}Kerne  ${R}"\n')
        assert _it.unumschlossen("x.sh"), \
            "die Zuweisung mit Farbcode faellt durch"
        # Umschlossenes darf NICHT gemeldet werden: ein Melder mit Fehlalarm
        # wird nicht gelesen, und dann faellt der echte Befund mit durch.
        with open(os.path.join(probe, "x.sh"), "w", encoding="utf-8") as f:
            f.write('printf "  %s\\n" "$(t "Dienst nicht gefunden")"\n')
        assert not _it.unumschlossen("x.sh"), "Fehlalarm auf umschlossenem Text"
    finally:
        _it.ROOT = _alt_root

    # ── (2b) DIE DREI SENKEN LAUFEN DURCH t(). Hier hilft der Verhaltenstest
    # unten NICHT: gauge traegt CPU, RAM, Swap und Disk — die lauten in beiden
    # Sprachen gleich. Faellt gauge aus der Uebersetzung, sieht man es an der
    # Ausgabe nicht, und beim naechsten Label waere es zu spaet. Deshalb hier
    # ausnahmsweise am Wortlaut, mit genau dieser Begruendung.
    motd = open("tools/motd.sh", encoding="utf-8").read()
    for senke in ('sect(){ printf "  ${DIM}${B}%s${R}\\n" "$(t "$1")"',
                  'gauge(){ printf "  ${DIM}%-6s${R} %b ${FNT}%s${R}\\n" "$(t "$1")"',
                  'row(){ printf "  ${DIM}%-11s${R}%b %b\\n" "$(t "$1")"'):
        assert senke in motd, \
            "eine Senke uebersetzt ihre Beschriftung nicht mehr: %s" % senke[:14]

    # ── (3) ES WIRKT WIRKLICH. Der Vertrag laesst die MOTD zweimal laufen und
    # vergleicht. Ohne diesen Lauf waere alles oben nur die Behauptung, dass
    # die Verdrahtung stimmt — und genau die stimmte seit v4.1-W17 nicht.
    def _lauf(**umgebung):
        umg = dict(os.environ)
        umg["COLOR_MODE"] = "off"
        umg.pop("NC_LANG", None)
        # v4.2-W100: CONF=/dev/null — sonst redet eine INSTALLIERTE
        # /etc/nightcrawler/motd.conf mit. Genau daran ist dieser Vertrag rot
        # geworden, nachdem tools/installer.sh auf derselben Maschine gelaufen
        # war: die Datei zeigte BOT_DIR auf die Installation, der Dienst war
        # damit "gefunden", und die Zusicherung auf "nicht gefunden" fiel.
        # In der CI faellt das nie auf — frischer Container, kein /etc-Zustand.
        umg["CONF"] = os.devnull
        umg.update(umgebung)
        return _sp.run(["bash", "tools/motd.sh"], capture_output=True,
                       text=True, timeout=90, env=umg).stdout

    de = _lauf()
    en = _lauf(NC_LANG="en")
    assert de and en, "die MOTD gibt gar nichts aus"
    for wort in ("Kerne", "frei", "nicht gefunden"):
        assert wort in de, "der deutsche Lauf zeigt %r nicht mehr" % wort
        assert wort not in en, \
            "der englische Lauf zeigt weiterhin %r" % wort
    for wort in ("cores", "free", "not found"):
        assert wort in en, "der englische Lauf zeigt %r nicht" % wort

    # ── (4) OHNE KATALOG BLEIBT ALLES DEUTSCH. Das ist der Rueckfall, auf dem
    # das ganze Verfahren steht: nie ein nackter Schluessel, nie eine leere
    # Zeile. Eine MOTD, die bei einem fehlenden Katalog Luecken zeigt, waere
    # schlimmer als eine, die deutsch bleibt.
    ohne = _lauf(NC_LANG="en", NC_I18N_KATALOG="/gibt/es/nicht.tsv")
    assert "Kerne" in ohne and "cores" not in ohne, \
        "ohne Katalog kommt nicht Deutsch heraus"

    ok("v4.2-W14: die MOTD spricht Englisch \u2014 und die Abdeckungszahl "
       "zaehlt endlich, was sie nicht findet")


def _test_v42_w39_treuepunkte_cooldown_gedeckelt():
    """v4.2-W39: der Anti-Farming-Cooldown der Treuepunkte darf nicht wachsen.

    nc.loyalty._chat_cool bekommt bei JEDER gewerteten Chat-Nachricht einen
    Eintrag pro Chatter und Plattform — und hatte als einziger der geprueften
    Zaehler-Container keinen Deckel (der Speicher-Audit v4.0-W37 sah nur
    bot.py). Gemessen: 10.000 verschiedene Chatter = 10.000 Eintraege, rund
    1 MB, und ueber Wochen Laufzeit wird das nie wieder kleiner.

    Abgelaufene Eintraege zu entfernen ist kein Semantik-Bruch: nach Ablauf
    des Cooldowns darf derselbe Chatter ohnehin wieder Punkte bekommen.
    Genau das prueft der zweite Teil.
    """
    import nc.loyalty as L

    L._chat_cool.clear()
    L.configure(enabled=True, db_get=lambda k: 0,
                db_add=lambda k, d, n: d, db_top=lambda n: [])
    try:
        # 10.000 verschiedene Chatter, verteilt ueber 500 s (20/s) — der
        # Alltag eines gut laufenden Live-Chats.
        t = 1_000_000.0
        for i in range(10000):
            t += 0.05
            L.award_chat("zuschauer%d" % i, "tiktok", now=t)
        assert len(L._chat_cool) <= 2500, \
            "Cooldown-Dict waechst pro Chatter (%d Eintraege)" % len(L._chat_cool)
        ok("v4.2-W39: Treuepunkt-Cooldown gedeckelt \u2014 %d statt 10.000 "
           "Eintraege" % len(L._chat_cool))

        # Der Deckel darf den Cooldown nicht aushebeln.
        L._chat_cool.clear()
        assert L.award_chat("bob", "kick", now=3_000_000.0) is not None
        assert L.award_chat("bob", "kick", now=3_000_005.0) is None, \
            "Cooldown greift nicht mehr"
        assert L.award_chat("bob", "kick", now=3_000_061.0) is not None, \
            "Cooldown laeuft nicht mehr ab"
        ok("v4.2-W39: der Deckel aendert nichts am Anti-Farming-Cooldown")
    finally:
        L._chat_cool.clear()
        L.configure(enabled=False)


def _test_v42_w44_aufnahmesitzung():
    """v4.2-W44: sechs bis zehn Dateien sind EIN Stream — und das steht jetzt
    auch so in der Datenbank.

    Der Befund: ein dreistuendiger TikTok-Stream liegt bei uns als sechs bis
    zehn Dateien auf der Platte. Das ist Absicht (die signierte Stream-URL
    laeuft nach ~30 Minuten ab, B58 schneidet vorher sauber; dazu je eine
    Datei nach 403, Stall oder Abriss), aber `recordings` kannte keine Spalte,
    die sagt, dass diese sieben Zeilen zusammengehoeren. Der Betreiber konnte
    den Stream deshalb nicht von Anfang bis Ende sehen — nicht weil das
    Material fehlte, sondern weil es unsortiert herumlag.

    Vier Dinge werden hier festgehalten, und jedes davon war beim Bauen
    einmal falsch:
      1. Ein 403-Backoff (Minuten) trennt NICHT, eine echte Pause schon.
      2. Ein nackter ISO-Stempel wird als UTC gelesen, nicht als Ortszeit.
      3. Eine Ueberlappung ist keine negative Luecke.
      4. Ein Apostroph im Dateinamen bricht die concat-Liste nicht.
    """
    import calendar
    import shlex
    from nc import aufnahmesitzung as A

    # --- 1) Die Klammer haelt ueber den Backoff, bricht bei echter Pause --
    # SITZUNG_MAX_LUECKE_S ist mit 900 s bewusst grosszuegig: der 403-Backoff
    # in nc/aufnahmefolge kostet Minuten, und danach ist es immer noch
    # derselbe Stream. Ein knapper Wert (etwa 60 s) zerlegte jeden gestoerten
    # Stream in ein Dutzend Sitzungen — also genau der Zustand vor W44, nur
    # mit Spalte.
    assert A.SITZUNG_MAX_LUECKE_S >= 600, \
        "unter 10 Minuten zerlegt ein 403-Backoff den Stream in Scheiben"
    assert A.gehoert_dazu(1000.0, 1002.0) is True          # B58-Schnitt
    assert A.gehoert_dazu(1000.0, 1000.0 + 300) is True    # 403 mit Backoff
    assert A.gehoert_dazu(1000.0, 1000.0 + 1200) is False  # 20 min = neu
    assert A.gehoert_dazu(None, 5.0) is False, \
        "ohne vorheriges Segment gibt es keine laufende Sitzung"
    assert A.gehoert_dazu(1000.0, 995.0) is True, \
        "Ueberlappung ist ein nahtloser Schnitt, keine neue Sitzung"
    ok("W44: 403-Backoff haelt die Sitzung zusammen, echte Pause trennt sie")

    # --- 2) Ein nackter Stempel ist UTC, nicht Ortszeit ------------------
    # Der Bot schreibt ausschliesslich UTC. Wuerde ein Stempel ohne Zone als
    # LOKALE Zeit gelesen, staende er auf einer Box mit TZ=Europe/Berlin ein
    # bis zwei Stunden neben einem mit "+00:00" — und jede Sitzung braeche
    # genau an der Stelle, an der das Format wechselt.
    # Absoluter Wert, kein Selbstvergleich: "== sekunden(...+00:00)" haelt auch
    # dann, wenn beide Seiten falsch als Ortszeit gelesen werden — auf einer
    # Box mit TZ=UTC faellt der Fehler damit nie auf, auf der Berliner Kiste
    # des Betreibers stuende jede Sitzungsgrenze zwei Stunden daneben.
    soll = calendar.timegm((2026, 9, 11, 20, 0, 0, 0, 0, 0))
    for form in ("2026-09-11T20:00:00+00:00", "2026-09-11T20:00:00",
                 "2026-09-11T20:00:00Z", "2026-09-11 20:00:00+00:00"):
        assert A.sekunden(form) == soll, (form, A.sekunden(form), soll)
    for murks in (None, "", "   ", "kein Datum", "2026-13-45"):
        assert A.sekunden(murks) is None, murks
    assert A.sekunden(1757620800.0) == 1757620800.0
    ok("W44: Zeitstempel ohne Zone gelten als UTC, Murks als None")

    # --- 3) Die Naht-Rechnung sagt die Wahrheit --------------------------
    t0 = A.sekunden("2026-09-11T20:00:00Z")
    seg, cur = [], t0
    # Ein realer Verlauf: fuenf URL-Schnitte a 2-4 s, ein 403 mit 5 min Backoff.
    for laenge, pause in [(1740, 3), (1740, 2), (1740, 301), (1740, 2),
                          (1740, 4), (1740, 2), (900, 0)]:
        seg.append((cur, cur + laenge))
        cur += laenge + pause
    lst, summe, brutto, netto = A.luecken(seg)
    assert len(lst) == 6, lst
    assert abs(summe - 314) < 0.5, summe
    assert abs(brutto - netto - 314) < 0.5, (brutto, netto)
    assert 97.0 < A.abdeckung(seg) < 98.0, A.abdeckung(seg)
    # Eine Ueberlappung darf die Bilanz NICHT schoenrechnen: mit einem naiven
    # sum(start - vorheriges_ende) haette ein einziger doppelt aufgenommener
    # Abschnitt die 314 s Loch rechnerisch aufgefressen.
    ueber = [(0.0, 100.0), (50.0, 150.0), (400.0, 500.0)]
    lst2, summe2, _b2, _n2 = A.luecken(ueber)
    assert lst2 == [250.0] and summe2 == 250.0, (lst2, summe2)
    # Leere und entartete Eingabe darf nicht werfen.
    assert A.luecken([]) == ([], 0.0, 0.0, 0.0)
    assert A.abdeckung([]) == 100.0
    assert A.abdeckung([(5.0, 5.0)]) == 100.0, \
        "eine Sitzung ohne Brutto-Zeit ist vollstaendig, nicht 0 %"
    ok("W44: Luecken-Bilanz stimmt, Ueberlappung rechnet sie nicht schoen")

    # --- 4) Die concat-Liste ueberlebt jeden Dateinamen ------------------
    # Der concat-Demuxer liest  file 'pfad'  mit der Quoting-Regel von
    # POSIX-sh — genau deshalb ist die Form '\'' richtig, und genau deshalb
    # prueft shlex hier stellvertretend (ffmpeg selbst laeuft in der CI nicht).
    # Ein roher Apostroph beendete die Zeichenkette mitten im Pfad; alles
    # danach waere ein eigenes Argument.
    boese = ["/rec/it's here.mp4", "/rec/'; rm -rf / ;'.mp4",
             "/rec/a b  c.mp4", "/rec/ü mlaut'.mp4", "/rec/'''.mp4",
             "/rec/normal.mp4"]
    zeilen = A.concat_liste(boese).rstrip("\n").split("\n")
    assert len(zeilen) == len(boese)
    for zeile, erwartet in zip(zeilen, boese):
        assert shlex.split(zeile) == ["file", erwartet], (zeile, erwartet)
    assert A.concat_liste([]) == "", "leere Liste darf keine Leerzeile erzeugen"
    ok("W44: concat-Liste haelt Apostroph, Leerzeichen und Umlaut aus")

    # --- 5) -c copy, nicht neu kodieren ----------------------------------
    # Der ganze Punkt: alle Segmente stammen aus derselben Quelle mit
    # demselben Recorder-Kommando, haben also identische Codec-Parameter.
    # Eine Neukodierung kostete auf dieser Box eine Stunde CPU, die der
    # Restream-Transcode gerade braucht.
    cmd = A.concat_cmd("/tmp/l.txt", "/tmp/z.mp4")
    assert "-c" in cmd and cmd[cmd.index("-c") + 1] == "copy", cmd
    assert "-safe" in cmd and cmd[cmd.index("-safe") + 1] == "0", \
        "-safe 0 fehlt — die Liste traegt absolute Pfade"
    assert cmd[-1] == "/tmp/z.mp4" and "+faststart" in cmd
    for verboten in ("libx264", "-crf", "-b:v", "-preset"):
        assert verboten not in cmd, verboten
    # Der Thread-Deckel gehoert in den Kommandobauer, nicht zum Aufrufer.
    # test_restream.test_ffmpeg_thread_budget prueft an genau dieser Funktion;
    # ein Deckel eine Ebene hoeher waere korrekt und trotzdem unsichtbar.
    gedeckelt = A.concat_cmd("/tmp/l.txt", "/tmp/z.mp4", threads=1, nice=12)
    assert "-threads" in gedeckelt and gedeckelt[gedeckelt.index("-threads") + 1] == "1"
    assert gedeckelt[gedeckelt.index("-threads") - 1] == "ffmpeg", \
        "-threads muss direkt hinter ffmpeg stehen, sonst gilt es nur fuer den Encoder"
    ok("W44: concat laeuft mit -c copy, ohne Neukodierung, mit Thread-Deckel")

    # --- 6) Der Pfad-Riegel kommt aus nc.sicherpfad ----------------------
    # Die Sitzungs-ID traegt einen TikTok-Nutzernamen, also fremde Eingabe.
    # Ein zweiter, selbstgebauter Riegel daneben war schon einmal der Grund
    # fuer 241 CodeQL-Befunde, die keiner mehr pruefen konnte.
    hier = os.path.dirname(os.path.abspath(__file__))
    quelle = open(os.path.join(hier, "nc", "aufnahmesitzung.py"),
                  encoding="utf-8").read()
    assert "sicher_join" in quelle, \
        "zieldatei muss nc.sicherpfad benutzen, keinen eigenen Riegel"
    tmp = _ph.verzeichnis()
    # ROHE Kennungen, nicht durch sitzung_id gewaschen: die Join-Route reicht
    # die sid aus dem URL-Pfad direkt an zieldatei weiter. Wuerde hier nur
    # sitzung_id("../../etc/passwd") geprueft, liefe der Test gegen einen
    # bereits entschaerften Namen und der Riegel in zieldatei waere ungeprueft
    # — er koennte ersatzlos entfallen, ohne dass ein Vertrag kippt.
    for roh in ("../../etc/passwd", "..\\..\\windows", "/absolut/weg",
                "....//....//x", "..", ".", "", "@u/../../x_20260911T2000"):
        ziel = A.zieldatei(tmp, roh)
        assert os.path.dirname(os.path.realpath(ziel)) == os.path.realpath(tmp), \
            (roh, ziel)
        basis = os.path.basename(ziel)
        assert basis.startswith("sitzung_") and basis.endswith(".mp4"), (roh, basis)
        assert "/" not in basis and ".." not in basis, (roh, basis)
    # Und die gewaschene Form bleibt natuerlich auch drin.
    for boeser_name in ("../../etc/passwd", "@helge_72"):
        sid = A.sitzung_id(boeser_name, "2026-09-11T20:00:00Z")
        assert "/" not in sid and ".." not in sid, sid
        ziel = A.zieldatei(tmp, sid)
        assert os.path.dirname(os.path.realpath(ziel)) == os.path.realpath(tmp), ziel
    ok("W44: Sitzungs-Datei bleibt unter recordings/, auch bei boesem Namen")

    # --- 7) Das Modul bleibt bot-frei ------------------------------------
    for muster in ("import bot", "from bot"):
        assert muster not in quelle, muster
    assert "sqlite3" not in quelle and "db_conn" not in quelle, \
        "die Sitzungsrechnung darf keine Datenbank kennen — sonst ist sie " \
        "nur mit laufendem Bot pruefbar"
    ok("W44: nc/aufnahmesitzung.py rechnet nur — keine DB, kein Bot, keine Uhr")

    # --- 8) bot.py schreibt die Klammer wirklich -------------------------
    # Ein Modul, das niemand aufruft, ist keine Loesung. brain/report.py stand
    # aus genau diesem Grund monatelang fertig und tot herum.
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert "from nc import aufnahmesitzung as _nc_sitzung" in bot
    assert "session_id, started_at, ended_at" in flach, \
        "der INSERT in add_recording traegt die W44-Spalten nicht"
    # Am add_recording-AUFRUF festmachen, nicht am blossen Vorkommen der
    # Zeichenkette: "started_at=started_at, ended_at=ended_at" steht auch im
    # Aufruf von split_and_send_video zwei Bildschirme weiter unten. Ein
    # Vertrag, der nur nach dem Text sucht, bleibt gruen, waehrend die Klammer
    # in Wahrheit auf geschaetzte Zeiten faellt — genau so ist er beim Bauen
    # einmal durchgerutscht.
    assert ("add_recording(username, output_file, file_size=file_size, "
            "duration_secs=int(duration), tracking_id=tid, "
            "started_at=started_at, ended_at=ended_at)") in flach, \
        "handle_recording_finished gibt die echten Zeiten nicht an " \
        "add_recording weiter — ohne sie wird die Startzeit geschaetzt"
    assert "_nc_sitzung.gehoert_dazu(" in bot and "_nc_sitzung.sitzung_id(" in bot
    # Der Rueckfall auf den alten Spaltensatz muss bleiben: kam
    # _migrate_columns auf einem Bestand nicht durch, fehlte sonst nicht die
    # Klammer, sondern JEDE Aufnahme im Dashboard.
    assert flach.count("INSERT INTO recordings (username, filepath, created_at,") == 2, \
        "der Rueckfall-INSERT ohne Sitzungs-Spalten fehlt"
    ok("W44: bot.py bestimmt die Sitzung, mit Rueckfall auf den alten INSERT")

    # --- 9) Schema, Index und die drei Routen ----------------------------
    sch = open(os.path.join(hier, "nc", "schema.py"), encoding="utf-8").read()
    fs = " ".join(sch.split())
    for spalte in ('"session_id": txt_idx', '"started_at": ts', '"ended_at": ts'):
        assert spalte in fs, spalte
    assert "idx_recordings_session" in fs, \
        "ohne Index wird jede Sitzungsabfrage ein Full Scan"
    rt = open(os.path.join(hier, "nc", "routes", "recordings.py"),
              encoding="utf-8").read()
    fr = " ".join(rt.split())
    for pfad in ('"/api/recordings/sessions"',
                 '"/api/recordings/session/<sid>"',
                 '"/api/recordings/session/<sid>/join", methods=["POST"]'):
        assert pfad in fr, pfad
    # Der Join laeuft im Thread, nicht in der Anfrage: ein 6-GB-concat haelt
    # sonst einen Flask-Worker minutenlang fest und der Proxy bricht ab,
    # waehrend ffmpeg fleissig weiterarbeitet.
    assert "threading.Thread(target=_join_lauf" in fr, \
        "der concat-Lauf blockiert die HTTP-Anfrage"
    assert 'log.error("Sitzung %s zusammenfuegen fehlgeschlagen' in rt, \
        "ein fehlgeschlagener Join gehoert auf error — auf warning sieht ihn niemand"
    # Der Zielpfad wird aus DB-Werten gebaut, nicht aus der URL-Kennung. Die
    # erste Fassung reichte sid direkt an zieldatei — nc.sicherpfad saeubert
    # das zwar nachweislich, aber CodeQL sieht die Saeuberung nicht (die
    # Barriere in .github/codeql deckt nur py/stack-trace-exposure ab) und
    # meldete zu Recht py/path-injection. Wer das rueckgaengig macht, holt
    # den Befund zurueck.
    assert "_sitzung.zieldatei(c.recordings_dir, sid_db)" in fr, \
        "der Join-Zielpfad muss aus DB-Werten kommen"
    assert "_sitzung.zieldatei(c.recordings_dir, sid)" not in fr, \
        "die URL-Kennung darf nicht in den Dateipfad — py/path-injection"
    ok("W44: Spalten, Index, drei Routen — und der Zielpfad ohne Fremdeingabe")


def _test_v42_w45_live_ping_nicht_bei_jeder_reparatur():
    """v4.2-W45: der Bot schrieb bei jedem Reparatur-Neustart eine
    Live-Ankuendigung nach Discord — und schrieb dabei den .env-Kommentar
    statt der Werte.

    Gemeldet mit Bildschirmfoto: dieselbe Nachricht viermal hintereinander im
    Kanal `#ki-moderator`, und ihr Inhalt lautete

        <@&# Discord-Rollen-ID, die gepingt wird (optional)>
        \U0001F534 **# dein Name fuer die Live-Ankuendigung ist LIVE!**

    Zwei getrennte Fehler in einer Zeile.

    **Der Inhalt.** python-dotenv kuerzt einen Kommentar nur, wenn ein
    Leerzeichen davor steht. `COMMUNITY_LIVE_ROLE_ID=# Discord-Rollen-ID, …`
    liefert also die ganze Zeile als Wert, und ein blosses `.strip()` macht
    daraus einen wahrheitswertigen String. Die Antwort ist eine FORM-Pruefung:
    eine Rollen-ID ist eine Zahl, ein Name faengt nicht mit einem Doppelkreuz
    an. Ein globales "schneide alles ab #" waere falsch — Overlay-Farben
    fangen mit # an.

    **Die Wiederholung.** Der Kommentar im Bot behauptete "einmal pro
    Restream-Session, entprellt ueber _COMMUNITY_PINGED". Tatsaechlich entfernte
    `stop()` den Eintrag BEDINGUNGSLOS, auch beim internen Reparatur-Neustart
    (`_keep_desired=True`). Der Verify-Waechter macht genau das: stop, 3 s
    warten, `start()` ohne `_attempts` — also 0. Jeder Reparaturzyklus war damit
    ein frischer Start mit frischem Ping.
    """
    from nc import community as C

    # --- 1) Der .env-Kommentar wird nie zum Rollen-Ping ------------------
    for murks in ("# Discord-Rollen-ID, die gepingt wird (optional)",
                  "", "   ", None, "abc", "@everyone", "<@&123>", "12 34",
                  "123a", "-1", "1.0",
                  "1234567890123456789012345678901234"):               # zu lang
        assert C.rollen_id(murks) == "", repr(murks)
    # Eine kurze Zahl ist KEIN Fehlerfall: echte Snowflakes haben 17-19
    # Stellen, aber eine Untergrenze faengt nichts Reales ab (der Fehlerfall
    # ist ein ganzer Kommentar) und braeche test_community_discovery_loop,
    # das mit "999" prueft.
    assert C.rollen_id("999") == "999"
    assert C.rollen_id("1547914245138812948") == "1547914245138812948"
    assert C.rollen_id("  1547914245138812948  ") == "1547914245138812948"
    ok("W45: nur eine Snowflake wird gepingt, kein .env-Kommentar")

    # --- 2) Der Name ebenso -----------------------------------------------
    assert C.anzeigename("# dein Name fuer die Live-Ankuendigung", "Der Stream") \
        == "Der Stream"
    assert C.anzeigename("", "Der Stream") == "Der Stream"
    assert C.anzeigename(None, "Der Stream") == "Der Stream"
    assert C.anzeigename("  Helge  ", "Der Stream") == "Helge"
    # Ein Name DARF ein Doppelkreuz tragen, nur nicht damit anfangen.
    assert C.anzeigename("Helge #1", "Der Stream") == "Helge #1"
    ok("W45: ein stehengebliebener Kommentar wird nicht zum Streamer-Namen")

    # --- 3) Die fertige Nachricht -----------------------------------------
    C.configure(live_role_id="# Discord-Rollen-ID, die gepingt wird (optional)")
    text = C.live_ping("Der Stream", platforms=["Kick", "Twitch"])
    assert "<@&" not in text, text
    assert "Discord-Rollen-ID" not in text, text
    assert "Der Stream ist LIVE!" in text
    C.configure(live_role_id="1547914245138812948")
    assert C.live_ping("Helge", platforms=["Kick"]).startswith(
        "<@&1547914245138812948> ")
    C.configure(live_role_id="")          # Zustand nicht an den naechsten Test vererben
    ok("W45: die Ankuendigung traegt entweder eine echte Rolle oder gar keine")

    # --- 4) Die Zeitsperre ------------------------------------------------
    assert C.darf_pingen(None, 1000.0, 3600) is True, "der erste Ping geht immer"
    assert C.darf_pingen(1000.0, 1003.0, 3600) is False, \
        "drei Sekunden spaeter ist derselbe Stream — genau der Abstand, den " \
        "der Verify-Waechter zwischen stop und start wartet"
    assert C.darf_pingen(1000.0, 1000.0 + 3600, 3600) is True
    assert C.darf_pingen(1000.0, 1000.0 + 3599, 3600) is False
    # Ein kaputter Wert darf den Ping nicht dauerhaft verhindern: lieber eine
    # Nachricht zu viel als eine Live-Ankuendigung, die nie mehr kommt.
    assert C.darf_pingen("murks", 1000.0, 3600) is True
    assert C.darf_pingen(1000.0, 1001.0, "murks") is True
    ok("W45: Zeitsperre haelt den Reparatur-Zyklus auf, blockiert aber nicht dauerhaft")

    # --- 5) Und der Bot benutzt das auch ----------------------------------
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert "_community.darf_pingen(_COMMUNITY_PINGED.get(rid)" in flach, \
        "die Aufrufstelle prueft die Zeitsperre nicht"
    assert "_community.anzeigename(os.getenv(\"STREAMER_NAME\")" in flach, \
        "der Streamer-Name geht ungeprueft nach Discord"
    assert "COMMUNITY_LIVE_PING_MIN_GAP_S" in bot
    # Der Kern des Befunds: das Vergessen darf NUR beim Betreiber-Stop
    # passieren — und das wird am SYNTAXBAUM geprueft, nicht an einem
    # Textfenster. Die erste Fassung dieses Vertrags sah 400 Zeichen vor dem
    # pop() nach "if not _keep_desired:" und war damit gruen, obwohl die
    # Bedingung auf "if True:" stand: in stop() steht dieselbe Bedingung
    # wenige Zeilen darueber noch einmal (fuer _stallkills). Die
    # Mutationsprobe hat genau dieses Loch aufgedeckt.
    import ast as _ast
    _baum = _ast.parse(bot)
    def _ist_betreiber_stop(knoten):
        t = knoten.test
        return (isinstance(t, _ast.UnaryOp) and isinstance(t.op, _ast.Not)
                and isinstance(t.operand, _ast.Name)
                and t.operand.id == "_keep_desired")
    _pops, _geschuetzt = 0, 0
    for _f in _ast.walk(_baum):
        if not (isinstance(_f, (_ast.FunctionDef, _ast.AsyncFunctionDef))
                and _f.name == "stop"):
            continue
        for _n in _ast.walk(_f):
            if not (isinstance(_n, _ast.Call)
                    and isinstance(_n.func, _ast.Attribute)
                    and _n.func.attr == "pop"
                    and isinstance(_n.func.value, _ast.Name)
                    and _n.func.value.id == "_COMMUNITY_PINGED"):
                continue
            _pops += 1
            # Steht dieser Aufruf im Rumpf eines "if not _keep_desired"?
            for _if in _ast.walk(_f):
                if (isinstance(_if, _ast.If) and _ist_betreiber_stop(_if)
                        and any(_if.body[0].lineno <= _n.lineno
                                <= (_k.end_lineno or 0) for _k in _if.body)):
                    _geschuetzt += 1
                    break
    assert _pops == 1, "_COMMUNITY_PINGED wird in stop() %dx geraeumt" % _pops
    assert _geschuetzt == 1, \
        "das Raeumen haengt nicht an 'if not _keep_desired' — jeder " \
        "Reparatur-Neustart pingt dann wieder"
    assert "_COMMUNITY_PINGED.discard(rid)" not in flach, \
        "die alte, bedingungslose Fassung steht noch da"
    ok("W45: nur der Stop des Betreibers beendet die Ping-Sperre")


def _test_v42_w46_audiotap_sagt_warum_er_starb():
    """v4.2-W46: der Audio-Tap starb 57 Mal und sagte kein einziges Mal warum.

    Befund aus dem Log vom 10.09. (101 Minuten):

        225  live-react gestartet / gestoppt      (Median-Lebensdauer 4 s)
         57  "Audio-Tap beendet -> Worker-Neustart", je 1 s nach dem Start
          0  "triggere AZRAEL-Reaktion"
          0  "AZRAEL @... reagierte"

    Ohne Tap hoert AZRAEL nichts von dem, was der gesendete Streamer SAGT —
    die Reaktion faellt auf den blossen Chat zurueck. Genau das hat der
    Betreiber gemeldet. Der Grund wurde 57 Mal erzeugt und 57 Mal
    weggeworfen, weil der Prozess mit `stderr=DEVNULL` lief.

    Diese Welle macht NUR den Kanal auf. Solange der Grund im DEVNULL
    verschwindet, waere jede weitere Reparatur geraten.
    """
    from nc import audiotap as A
    from nc import logsafe as L

    # --- 1) Die Kategorie kommt aus der EINEN zustaendigen Stelle --------
    # nc.aufnahmekategorie beantwortet dieselbe Frage fuer den Recorder.
    # Sie ein zweites Mal zu beantworten hiesse, zwei Wahrheiten zu haben,
    # von denen eine veraltet — derselbe Fehler wie beim Build-Stempel (v4.2).
    quelle = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "nc", "audiotap.py"), encoding="utf-8").read()
    assert "from nc.aufnahmekategorie import kategorisiere" in quelle, \
        "audiotap muss die vorhandene Kategorie-Kette benutzen, keine eigene"
    for eigen in ("403 in", "404 in", 'lower()'):
        assert eigen not in quelle, \
            "audiotap baut die Musterkette nach statt sie zu benutzen: %s" % eigen

    d = A.diagnose("[https @ 0x1] HTTP error 403 Forbidden", 1, 1.0, 0)
    assert d["kategorie"] == "forbidden_403", d
    assert "RECORD_PROXY" in d["abhilfe"], d["abhilfe"]
    assert A.diagnose("Server returned 404 Not Found", 1, 1.0, 0)["kategorie"] \
        == "stream_dead"
    assert A.diagnose("rw_timeout reached", 1, 90.0, 3)["kategorie"] == "timeout"
    # Der Nebenbefund aus W46 — die Kette suchte "timeout", ffmpeg schreibt
    # aber meist "Connection timed out" — ist in W48 geschlossen. Die Zeile
    # bleibt stehen und prueft jetzt die Gegenrichtung: sie hat den Befund
    # aufgehoben, bis er behoben war, und haelt die Behebung nun fest.
    assert A.diagnose("Connection timed out", 1, 90.0, 3)["kategorie"] == "timeout"
    assert A.diagnose("", 0, 1.0, 0)["kategorie"] == "empty_output"
    # Der reale Fall vom 10.09.: eine Sekunde, kein Segment, kein Muster.
    d = A.diagnose("irgendwas Unbekanntes", 1, 1.0, 0)
    assert d["kategorie"] == "early_disconnect", d
    ok("W46: die Kategorie kommt aus nc.aufnahmekategorie, mit Abhilfe je Fall")

    # --- 2) Jede Kategorie hat eine Abhilfe ------------------------------
    # Eine Meldung ohne Handlungsanweisung ist eine Meldung, die man
    # ueberliest. Der Deckungs-Test faengt die Kategorie, die spaeter in
    # nc.aufnahmekategorie dazukommt und hier vergessen wird.
    from nc import aufnahmekategorie as _ak
    _bekannt = set()
    for _txt, _stall, _rc, _fe, _dur in [
            ("Video codec is not implemented", True, 1, False, 5),
            ("HTTP error 404 Not Found", False, 1, False, 5),
            ("Could not write header for output file", True, 1, False, 5),
            ("etwas anderes", True, 1, False, 5),
            ("no playable streams", False, 1, False, 5),
            ("HTTP error 403 Forbidden", False, 1, False, 5),
            ("Connection timed out", False, 1, False, 90),
            ("no plugin can handle URL", False, 1, False, 5),
            ("", 0, 0, False, 90),
            ("etwas anderes", False, 1, True, 90),
            ("etwas anderes", False, 1, False, 5)]:
        _bekannt.add(_ak.kategorisiere(_txt, _stall, _rc, _fe, _dur))
    fehlend = sorted(_bekannt - set(A.ABHILFE))
    assert not fehlend, "Kategorien ohne Abhilfe-Text: %s" % fehlend
    assert len(_bekannt) >= 10, sorted(_bekannt)
    ok("W46: alle %d Kategorien tragen einen Abhilfe-Satz" % len(_bekannt))

    # --- 3) Die Drosselung meldet den WECHSEL sofort ---------------------
    # Der Tap stirbt im Acht-Sekunden-Takt; 225 gleichlautende Warnungen
    # sind ihr eigenes Rauschen und erziehen dazu, sie zu ueberlesen. Aber
    # wird aus einem 403-Sturm ein Codec-Fehler, ist das eine neue Lage.
    # Wer nur nach der Zeit drosselt, sucht bis zur naechsten Viertelstunde
    # den falschen Fehler.
    assert A.melden(None, 100.0, "forbidden_403", None) is True
    assert A.melden(100.0, 108.0, "forbidden_403", "forbidden_403") is False, \
        "acht Sekunden spaeter derselbe Fehler — das ist der reale Takt"
    assert A.melden(100.0, 100.0 + A.MELDE_ABSTAND_S, "forbidden_403",
                    "forbidden_403") is True
    assert A.melden(100.0, 101.0, "hevc_unsupported", "forbidden_403") is True, \
        "ein Wechsel der Kategorie muss SOFORT durchkommen"
    # Kaputte Werte duerfen nicht dauerhaft stummschalten.
    assert A.melden(100.0, 101.0, "fail", "fail", abstand_s="murks") is True
    assert A.MELDE_ABSTAND_S >= 300, "zu knapp — dann rauscht es wieder"
    ok("W46: gedrosselt wie _loop_fehler, aber ein Kategorie-Wechsel kommt sofort")

    # --- 4) Der Riegel VOR dem ersten Log --------------------------------
    # Bis W46 ging das stderr des Taps nach DEVNULL — es war egal, was
    # drinstand. Genau das aendert diese Welle, und im stderr steht die
    # signierte TikTok-Quell-URL. redact_stream_urls deckte nur RTMP-
    # SENDE-Schluessel ab, also die andere Seite.
    roh = ("Cookie: sessionid=streng_geheim; tt_csrf=abc\n"
           "[hls @ 0x5] Failed to open "
           "https://pull-hls-f16.tiktokcdn.com/stage/stream-1.m3u8"
           "?expire=1757620800&sign=8f3c9d&session_id=deadbeef\n"
           "rtmps://x.live-video.net/app/live_1234_geheimerkey")
    sauber = L.fuer_log(roh)
    for geheim in ("streng_geheim", "8f3c9d", "deadbeef", "geheimerkey",
                   "expire=", "sign=", "session_id="):
        assert geheim not in sauber, (geheim, sauber)
    # ... und trotzdem brauchbar: Host und Pfad muessen bleiben, sonst ist
    # die Zeile fuer die Fehlersuche wertlos.
    for bleibt in ("pull-hls-f16.tiktokcdn.com", "stream-1.m3u8",
                   "live-video.net", "Failed to open"):
        assert bleibt in sauber, (bleibt, sauber)
    assert "<signiert:3p>" in sauber, sauber
    assert L.fuer_log("") == "" and L.fuer_log(None) == ""
    ok("W46: Cookie, Signatur und Sendeschluessel raus — Host und Pfad bleiben")

    # --- 5) Und bot.py benutzt das auch ----------------------------------
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    # Der Kern: KEIN DEVNULL mehr auf dem stderr des Taps.
    i = flach.find("*_audio_tap_cmd(stream_url, out_pat, proxy=_lr_proxy),")
    assert i > 0, "der Tap-Start ist nicht mehr auffindbar"
    fenster = flach[i:i + 200]
    assert "stderr=asyncio.subprocess.PIPE" in fenster, \
        "das stderr des Audio-Taps geht wieder ins Leere — genau der Befund"
    assert "stderr=asyncio.subprocess.DEVNULL" not in fenster, fenster
    # Gelesen werden MUSS es auch: mit PIPE und ohne Leser blockiert ffmpeg,
    # sobald der Pipe-Puffer des Kerns voll ist. Ein haengender Tap waere
    # schlimmer als der Zustand vor W46.
    assert "_audio_tap_sammler(proc, tap_err)" in flach, \
        "PIPE ohne Leser — ffmpeg blockiert bei vollem Puffer"
    assert "maxlen=AUDIOTAP_STDERR_ZEILEN" in flach, \
        "der Puffer ist ungedeckelt"
    assert "tap_sammler.cancel()" in flach, \
        "der Sammler wird nicht abgeraeumt — eine Aufgabe je Tap-Tod"
    # Der Nachruf steht auf warning, nicht auf info: ein log.info geht in
    # 5284 anderen info-Zeilen unter, und genau so blieb es unsichtbar.
    j = flach.find("log.warning(\"live-react: Audio-Tap @%s nach %.1fs tot")
    assert j > 0, "der Nachruf steht nicht auf warning"
    assert "_nc_audiotap.diagnose(roh, proc.returncode" in flach
    assert "_log_sicher(_ffmpeg_stderr_diagnostic(roh" in flach, \
        "der Wortlaut geht ungeschwaerzt ins Log"
    ok("W46: bot.py liest das stderr, deckelt es, raeumt auf und meldet auf warning")


def _test_v42_w47_chat_reconnect_und_gedaechtnis():
    """v4.2-W47: der Live-React-Worker starb alle vier Sekunden und fing
    jedes Mal bei null an.

    Zwei Befunde aus dem Log vom 10.09., beide hier geschlossen.

    **Der Worker konnte seinen Chat nicht neu verbinden.** Im Rumpf stand

        if proc is None and chat_task is not None and chat_task.done():
            break
        if (LIVE_REACT_CHAT and proc is not None and ...):
            # Reconnect

    Ohne Audio (`proc is None`) griff der Reconnect also nie — der Worker
    beendete sich, und die Engine startete ihn acht Sekunden spaeter neu.
    Jeder Neustart ein frischer Sign-API-Request. Median-Lebensdauer: vier
    Sekunden. Eine Reaktion braucht aber
    `max(LIVE_REACT_COOLDOWN, LIVE_REACT_BATCH_S)` = 25 Sekunden Sammelzeit;
    er kam nie an. Null Reaktionen in 101 Minuten.

    **Und ueber die Neustarts hinweg sammelte sich nichts an.** Das `finally`
    des Workers warf Regie (F100) und Story-Gedaechtnis (F103) weg — bei
    jedem Ende, also alle vier Sekunden.
    """
    from nc import chatfolge as C

    # --- 1) Die Rechnung liegt an EINER Stelle ---------------------------
    # Der Restream-Waechter hat seit W37 dieselbe Regel. Sie ein zweites Mal
    # hinzuschreiben waere der naechste Build-Stempel-Fehler gewesen: eine
    # Kopie wird gepflegt, die andere nicht.
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert flach.count("_nc_chatfolge.entscheide(") == 2, \
        "beide Listener muessen dieselbe Rechnung benutzen (Waechter + Worker)"
    assert "flattert = len(_reconnects) >= CHAT_CHURN_MAX" not in flach, \
        "die alte Inline-Fassung im Waechter steht noch da"
    ok("W47: Waechter und Live-React-Worker teilen sich nc/chatfolge.py")

    # --- 2) Eskalation und Erholung --------------------------------------
    assert C.entscheide([], 100.0, 3.0, 0)[1:] == (5, "kurz")
    assert C.entscheide([], 100.0, 120.0, 0)[1:] == (0, "gesund"), \
        "eine lange Sitzung ist TikToks normale WS-Rotation, kein Fehler"
    # Der Deckel haelt.
    _r, _b, _g = C.entscheide([], 100.0, 3.0, 10_000)
    assert _b == C.BACKOFF_MAX_S, _b
    # Churn schlaegt auch bei 'gesunden' Sitzungen zu — genau die Luecke, an
    # der W37 gescheitert war (13-17s galten als gesund, Backoff blieb 0).
    _rec = [100.0 + i for i in range(C.CHURN_MAX - 1)]
    _r, _b, _g = C.entscheide(_rec, 200.0, 999.0, 0)
    assert _g == "flattert" and _b > 0, (_g, _b)
    # Ausserhalb des Fensters zaehlt nichts mehr nach — sonst erholt sich ein
    # Stream nie mehr von einer schlechten Stunde.
    _r, _b, _g = C.entscheide(_rec, 100.0 + C.CHURN_WINDOW_S + 10, 999.0, 0)
    assert _g == "gesund" and _b == 0, (_g, _b)
    ok("W47: Backoff eskaliert, deckelt und erholt sich nach dem Fenster")

    # --- 3) Die Liste wird NICHT an Ort und Stelle geaendert -------------
    # Zwei Aufrufer teilen sich die Funktion, einer haelt seine Liste in einer
    # Closure. Eine Funktion, die mal mutiert und mal nicht, ist die Sorte
    # Falle, die erst im Betrieb auffaellt.
    _orig = [1.0, 2.0]
    _neu, _, _ = C.entscheide(_orig, 3.0, 1.0, 0)
    assert _orig == [1.0, 2.0], _orig
    assert _neu is not _orig and len(_neu) == 3, _neu
    assert C.entscheide(None, 1.0, 1.0, None)[0] == [1.0]
    ok("W47: entscheide() laesst die uebergebene Liste unberuehrt")

    # --- 4) Sitzungslaenge ist NICHT Sitzung plus Wartezeit --------------
    # Der erste Entwurf dieser Welle mass "seit dem letzten Versuch" — also
    # Sitzung PLUS Backoff. Nach 80s Backoff gilt damit jede Sitzung als
    # gesund (>= 60s), der Backoff faellt auf 0 und die Eskalation hebt sich
    # selbst auf, und zwar genau dann, wenn sie gebraucht wird.
    def _spiel(falsch):
        rec, bo, t, spur = [], 0, 0.0, []
        for _ in range(14):
            t += 3.0
            rec, bo, _g = C.entscheide(rec, t, 3.0 + bo if falsch else 3.0, bo)
            spur.append(bo)
            t += bo
        return spur
    assert 0 in _spiel(True)[3:], "die Falle ist nicht mehr nachstellbar?"
    assert 0 not in _spiel(False)[3:], _spiel(False)
    # Und der Code misst wirklich den Abriss, nicht den Versuch.
    assert "_dauer = max(0.0, chat_tot - chat_seit)" in flach, \
        "die Sitzungslaenge wird nicht zwischen Aufbau und Abriss gemessen"
    # Und der berechnete Backoff muss auch WIRKLICH gewartet werden. Die erste
    # Fassung dieses Vertrags prueft nur, dass er ausgerechnet wird — mit
    # ">= 0" statt ">= chat_backoff" blieb sie gruen, und der Worker haette
    # trotz sauberer Rechnung sofort neu verbunden. Die Mutationsprobe hat
    # genau dieses Loch aufgedeckt.
    assert ("and (_time_mod.monotonic() - chat_tot) >= chat_backoff):") in flach, \
        "der Backoff wird berechnet, aber nicht abgewartet"
    assert "last_chat_try" not in bot, \
        "der alte, mehrdeutige Zeitbegriff steht noch da"
    ok("W47: gemessen wird der Abriss, nicht der Versuch — sonst kippt die Eskalation")

    # --- 5) Der Reconnect haengt nicht mehr am Audio ---------------------
    assert "proc is not None and (chat_task is None or chat_task.done())" not in flach, \
        "der Chat-Reconnect haengt wieder am Audio-Tap"
    assert "if proc is None and chat_task is not None and chat_task.done(): break" \
        not in flach, "der Chat-only-Worker beendet sich wieder sofort"
    assert "if (LIVE_REACT_CHAT and chat_tot is None and chat_task is not None and chat_task.done()):" in flach
    # Enden darf er nur noch, wenn es wirklich nichts zu tun gibt.
    assert "if proc is None and not LIVE_REACT_CHAT:" in flach, \
        "ohne Audio UND ohne Chat muss der Worker enden, sonst dreht er leer"
    ok("W47: der Chat baut selbst neu auf — mit Audio wie ohne")

    # --- 6) Das Gedaechtnis ueberlebt den Neustart -----------------------
    # ... wird aber freigegeben, sobald der User wirklich offline ist. Das
    # ist nicht nur Hygiene: der Watchdog benutzt _LIVE_DIRECTORS als
    # Stellvertreter fuer "ein Worker laeuft" (B81). Karteileichen dort
    # bedeuten Stillstands-Fehlalarm und Selbstheilung gegen Geister.
    assert "_LIVE_DIRECTORS.pop(username, None)" not in flach, \
        "die Regie wird wieder bei jedem Worker-Ende weggeworfen"
    assert "_STORY_MEMORIES.pop(username, None)" not in flach, \
        "das Story-Gedaechtnis wird wieder bei jedem Worker-Ende weggeworfen"
    assert "for _u in [x for x in list(_LIVE_DIRECTORS) if x not in live]:" in flach, \
        "niemand raeumt die Regie auf, wenn der User offline geht"
    assert "for _u in [x for x in list(_STORY_MEMORIES) if x not in live]:" in flach
    # Und der Watchdog verlaesst sich weiterhin darauf.
    assert 'if name == "live-react" and not _LIVE_DIRECTORS:' in flach, \
        "B81 haengt an _LIVE_DIRECTORS — wer das aendert, muss hier nachziehen"
    ok("W47: Regie und Story ueberleben den Neustart, fallen aber beim Offline-Gehen")


def _test_v42_w48_wortlaut_der_werkzeuge():
    """v4.2-W48: die Kategorie-Kette kannte den Wortlaut nicht, den die
    Werkzeuge wirklich schreiben.

    Aus dem Log vom 11.09., zehn Minuten:

        28x  ytdlp @USER rc=1: ERROR: [tiktok:live] USER:
             The channel is not currently live
        25x  EARLY DISCONNECT @USER nach 1.8s (#1/5) — Auto-Retry in 10s
         3x  EARLY DISCONNECT ... Max-Retries (5) erreicht

    Der Kanal sendet nicht — und der Bot antwortet mit fuenf Wiederholungen
    und wachsendem Backoff. Ein Retry kann daran nichts aendern; er kostet
    nur Zugriffe von einer IP, die TikTok ohnehin schon beobachtet.

    Die Ursache ist eine Luecke in der Musterkette: yt-dlps Wortlaut passte
    auf keinen Zweig, fiel bis ans Ende durch (`fail`) und wurde dort wegen
    "kurz und mit Fehler" nachtraeglich zu `early_disconnect` umgewidmet —
    also genau in die Kategorie, an der `bot.py` den Auto-Retry aufhaengt.

    Dieselbe Sorte Luecke beim Timeout, und die war noch aergerlicher: die
    Kette sucht "timeout", ffmpeg schreibt aber "Connection timed out". In
    `bot.py::_proxy_report_recording` steht seit jeher "timed out" in der
    Liste — zwei Stellen, zwei Wahrheiten.
    """
    from nc import aufnahmekategorie as K

    # --- 1) Der Kanal sendet nicht -> kein Retry -------------------------
    for roh in ("ERROR: [tiktok:live] hasischaosqueen1601k25: "
                "The channel is not currently live",
                "ERROR: [tiktok:live] thomasschwarz180: The channel is not currently live",
                "the channel is NOT CURRENTLY LIVE"):
        assert K.kategorisiere(roh, False, 1, False, 1.8) == "offline_or_protected", roh
    # Die alten Wortlaute gelten unveraendert weiter.
    assert K.kategorisiere("no playable streams", False, 1, False, 5) == "offline_or_protected"
    assert K.kategorisiere("this user is offline", False, 1, False, 5) == "offline_or_protected"
    ok("W48: 'is not currently live' ist offline, nicht early_disconnect")

    # --- 2) Und der Auto-Retry haengt wirklich daran ---------------------
    # Ohne diese Haelfte waere der Vertrag Kosmetik: die Kategorie stimmte,
    # und der Bot wiederholte trotzdem.
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert 'if category == "early_disconnect":' in flach, \
        "der Auto-Retry haengt nicht mehr an der Kategorie — dann greift " \
        "diese Welle ins Leere"
    assert "_nc_folge.nach_frueher_trennung(" in flach
    ok("W48: der Auto-Retry haengt an der Kategorie, also greift die Aenderung")

    # --- 3) Timeout: der Wortlaut, den ffmpeg wirklich schreibt ----------
    for roh in ("Connection timed out", "Operation timed out",
                "error: Connection timed out (110)", "rw_timeout reached"):
        assert K.kategorisiere(roh, False, 1, False, 90.0) == "timeout", roh
    # Die zweite Stelle im Bot prueft dasselbe Wort — sie darf nicht
    # auseinanderlaufen.
    assert '"timed out"' in flach, \
        "_proxy_report_recording kennt 'timed out' nicht mehr"
    ok("W48: 'Connection timed out' zaehlt als timeout, wie an der zweiten Stelle auch")

    # --- 4) Die Reihenfolge bleibt unangetastet --------------------------
    # Die Kette ist eine PRIORITAETS-Kette (W23). Ein neues Muster weiter
    # oben haette stillschweigend Faelle abgefangen, die unten praeziser
    # beantwortet werden.
    assert K.kategorisiere("Video codec is not implemented", True, 1, False, 5) \
        == "hevc_unsupported"
    assert K.kategorisiere("HTTP error 404 Not Found. Could not write header",
                           False, 1, False, 5) == "stream_dead"
    assert K.kategorisiere("Could not write header for output file", True, 1, False, 5) \
        == "codec_header_fail"
    assert K.kategorisiere("HTTP error 403 Forbidden", False, 1, False, 5) == "forbidden_403"
    # Ein 404, der zusaetzlich "not currently live" traegt, bleibt stream_dead:
    # die tote URL ist die praezisere Aussage.
    assert K.kategorisiere("HTTP error 404: the channel is not currently live",
                           False, 1, False, 5) == "stream_dead"
    # Ein echter Abriss bleibt ein echter Abriss.
    assert K.kategorisiere("irgendein Abriss ohne Muster", False, 1, False, 2.0) \
        == "early_disconnect"
    ok("W48: die Prioritaetskette aus W23 steht unveraendert")

    # --- 5) Jede Kategorie traegt weiterhin einen Abhilfe-Satz -----------
    # W46 haelt das fuer den Audio-Tap fest; eine neue Kategorie ohne Text
    # faellt sonst auf den nichtssagenden Default zurueck.
    from nc import audiotap as A
    for kat in ("offline_or_protected", "timeout"):
        assert kat in A.ABHILFE and len(A.ABHILFE[kat]) > 20, kat
    ok("W48: die betroffenen Kategorien haben weiterhin eine Abhilfe")

    # --- 6) Das Overlay stirbt nicht an einer fehlenden Schrift ----------
    # Zweimal im Log: "RESTREAM_OVERLAY=1, aber Font fehlt (...) — Overlay
    # uebersprungen". Der Betreiber hatte es eingeschaltet und bekam es
    # nicht, weil ein Paket fehlte, das auf einem Server ueblicherweise gar
    # nicht dabei ist. Eine Schrift ist austauschbar: fuer eine Bauchbinde
    # zaehlt, DASS Text erscheint.
    from nc import restreamcmd as R
    _da = {"/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"}
    _p = lambda x: x in _da            # noqa: E731 — Testsonde, kein Produktivcode
    assert R.schriftart("/weg/DejaVuSans-Bold.ttf", pruefer=_p) in R.FONT_KANDIDATEN
    # Die Vorgabe hat Vorrang, wenn es sie gibt — wer sie setzt, will sie.
    _da.add("/weg/eigene.ttf")
    assert R.schriftart("/weg/eigene.ttf", pruefer=_p) == "/weg/eigene.ttf"
    # Gar nichts da: ehrlich None, kein erfundener Pfad.
    assert R.schriftart("/weg/x.ttf", pruefer=lambda _x: False) is None
    assert R.schriftart(None, pruefer=lambda _x: False) is None
    assert R.schriftart("", pruefer=lambda x: x.endswith("DejaVuSans-Bold.ttf")) \
        == R.FONT_KANDIDATEN[0]
    assert len(R.FONT_KANDIDATEN) >= 5 and len(set(R.FONT_KANDIDATEN)) == len(R.FONT_KANDIDATEN)
    # Nicht nur die LAENGE pruefen — eine Liste aus fuenf Fantasiepfaden
    # bestuende den Test und faende auf dem Server nichts. Diese beiden sind
    # die Pakete, die auf Debian/Ubuntu tatsaechlich in Frage kommen:
    # fonts-dejavu-core und fonts-liberation.
    assert any("dejavu" in k.lower() for k in R.FONT_KANDIDATEN), R.FONT_KANDIDATEN
    assert any("liberation" in k.lower() for k in R.FONT_KANDIDATEN), R.FONT_KANDIDATEN
    assert all(k.lower().endswith((".ttf", ".ttc", ".otf")) for k in R.FONT_KANDIDATEN)
    # Und die Kette benutzt das auch — an ALLEN drei Stellen.
    rq = open(os.path.join(hier, "nc", "restreamcmd.py"), encoding="utf-8").read()
    fr = " ".join(rq.split())
    assert fr.count("schriftart(RESTREAM_FONT)") == 3, \
        "Overlay-Schalter, drawtext_chain und studio_chain muessen dieselbe " \
        "Schrift benutzen — sonst zeichnet die eine, was die andere verbot"
    # Gegen den KOMMENTARFREIEN Quelltext pruefen: der Kommentar, der die
    # alte Fassung erklaert, zitiert sie zwangslaeufig. Genau daran sind in
    # diesem Projekt schon zwei Vertraege gestolpert (W39, W43).
    _ohne_kommentar = " ".join(
        zeile.split("#")[0] for zeile in rq.splitlines()).split()
    assert "os.path.isfile(RESTREAM_FONT)" not in " ".join(_ohne_kommentar), \
        "die alte, harte Pruefung steht noch im Code"
    # "apt install" mitpruefen, nicht nur den Paketnamen: der Docstring der
    # Funktion nennt "(fonts-dejavu-core)" ebenfalls, und ein Vertrag, der
    # darauf trifft, bliebe gruen, waehrend die WARNUNG ihre Abhilfe verliert.
    # Genau so ist er beim Bauen einmal durchgerutscht.
    assert "apt install fonts-dejavu-core" in rq, \
        "die Warnung nennt die Abhilfe nicht mehr"
    ok("W48: fehlt die konfigurierte Schrift, nimmt das Overlay eine Ersatzschrift")


def _test_v42_w49_notbremse_und_guthaben():
    """v4.2-W49: die Notbremse trat aufs Gas, und eine Rechnung sah aus wie ein
    Programmierfehler.

    Gemeldet: „bei den Restreams im Text-Modus brechen Chat und Avatar weg",
    dazu der Wunsch, das fehlende Guthaben als Warnung statt als Fehler zu
    behandeln. Drei Ursachen, alle hier:

    1. **Die Preset-Leiter stand falsch herum.** `("veryfast", "faster",
       "superfast", "ultrafast")`, vorwaerts durchlaufen — aber in x264 ist
       "faster" LANGSAMER als "veryfast". Stufe 1 machte das Encoding teurer,
       der Rueckstand wuchs, Stufe 2 und 3 folgten. Und auf Stufe 3 faellt der
       eingebrannte Text. Der Weg zum leeren Sendebild fuehrte durch den
       Versuch, es zu verhindern.

    2. **Der Avatar hing an der Schrift.** `avatar_on` verlangte `overlay_on`,
       und das verlangte eine vorhandene Schriftdatei. Eine fehlende
       DejaVu-Datei nahm damit den Avatar mit — obwohl er keine Schrift
       braucht. Dasselbe auf Drossel-Stufe 3.

    3. **Ein leeres Anthropic-Guthaben kommt als HTTP 400**, also mit
       demselben Code wie ein kaputter Request. Beides "bad_request" zu nennen
       ist formal richtig und praktisch nutzlos.
    """
    from nc import restreamcmd as R
    from nc import claude as C

    # --- 1) Jede Drossel-Stufe muss ECHT schneller sein ------------------
    # Auf die Eigenschaft geprueft, nicht auf Namen: ein Name laesst sich
    # wieder falsch eintragen (genau das ist passiert), die Eigenschaft nicht.
    TEMPO = ["ultrafast", "superfast", "veryfast", "faster", "fast",
             "medium", "slow", "slower", "veryslow"]
    for start in ("veryfast", "medium", "fast", "superfast"):
        kette = [R.drossel_preset(start, st) for st in range(R.DROSSEL_MAX + 1)]
        idx = [TEMPO.index(p) for p in kette]
        assert all(b <= a for a, b in zip(idx, idx[1:])), \
            "Drossel wird langsamer statt schneller: %s" % (kette,)
        assert idx[-1] < idx[0], "hoechste Stufe spart nichts: %s" % (kette,)
    # Der konkrete Fall aus dem Log: veryfast, Stufe 1.
    assert R.drossel_preset("veryfast", 1) == "superfast", \
        "Stufe 1 ab veryfast muss superfast sein — 'faster' war der Fehler"
    assert R.drossel_preset("ultrafast", 3) == "ultrafast", "unter ultrafast: nichts"
    # Ein Tippfehler in der .env darf nicht sofort auf die schlechteste Stufe
    # springen, solange gar kein Rueckstand vorliegt.
    assert R.drossel_preset("tippfehler", 0) == "tippfehler"
    assert R.drossel_preset("tippfehler", 1) == "superfast"
    ok("W49: jede Drossel-Stufe ist echt schneller als die vorige")

    # --- 2) Der Avatar haengt nicht mehr an der Schrift ------------------
    hier = os.path.dirname(os.path.abspath(__file__))
    rq = open(os.path.join(hier, "nc", "restreamcmd.py"), encoding="utf-8").read()
    fr = " ".join(rq.split())
    assert "sendebild_on = bool(transcode and RESTREAM_OVERLAY" in fr, \
        "der Schalter fuer 'ueberhaupt etwas brennen' fehlt"
    # Die genaue Verdrahtung von Schrift und Drossel prueft
    # _test_v42_w50_avatar_ueberlebt_die_drossel — und zwar an der
    # ABLEITUNGSKETTE im Syntaxbaum statt an Textzeilen.
    #
    # Der Grund steht in W50: diese Stelle hier hat den halben Fix aus W49
    # durchgelassen. Sie prueft Zeichenketten, und die stimmten — nur hing
    # `sendebild_on` selbst noch an der Drossel, sodass der Avatar sie ueber
    # zwei Ecken doch erbte. Wer Struktur pruefen will, muss die Struktur
    # lesen, nicht ihre Schreibweise.
    # ANKER GEWANDERT (v4.2-W61, nicht der Vertrag): die drei Zeilen tragen
    # jetzt zusaetzlich `not _av_gedrosselt`. Die Eigenschaft, die hier zaehlt,
    # ist unveraendert — der Avatar leitet von `sendebild_on` ab, nicht von
    # `overlay_on`, haengt also nicht an der Schrift.
    for zeile in ("feed_on = bool(sendebild_on and not _av_gedrosselt and avatar_feed)",
                  "avatar_on = bool(feed_on or anim_on"):
        assert zeile in fr, zeile
    assert "feed_on = bool(overlay_on and avatar_feed)" not in fr, \
        "der Avatar haengt wieder am Text-Schalter"
    assert "anim_on = bool(overlay_on and" not in fr, \
        "die Avatar-Animation haengt wieder am Text-Schalter"
    ok("W49: ohne Schrift kein Text — aber sehr wohl ein Avatar")

    # --- 3) Auf Stufe 3 faellt der TEXT, nicht der Avatar ----------------
    # Der Kommentar in W43 behauptete "den fehlenden Avatar sieht jeder,
    # deshalb faellt er zuletzt" — tatsaechlich fielen beide zusammen. Und es
    # ist auch sachlich falsch herum: eine drawtext-Kette mit mehreren Boxen
    # kostet ein Vielfaches eines overlay-Filters auf ein kleines PNG.
    # ANKER GEWANDERT (v4.2-W60, nicht der Vertrag): drossel_text_aus GIBT ES
    # NICHT MEHR. Die Stufe warf nicht "den Text", sondern ueber
    # studio_on = overlay_on and ... das GANZE Panel — Chat inklusive. Der
    # Betreiber: "Es hat gar nichts auszufallen. Es sollte nicht mal die
    # Moeglichkeit dazu geben." Die Leiter regelt jetzt nur noch Preset,
    # Bitrate, Bildrate und Leinwand.
    assert not hasattr(R, "drossel_text_aus"), \
        "drossel_text_aus ist zurueck — damit kann die Drossel wieder Inhalt " \
        "aus dem Bild nehmen"
    assert not hasattr(R, "drossel_overlay_aus"), \
        "der alte, irrefuehrende Name steht noch da"
    ok("W60: die Drossel kann den Text nicht mehr abschalten")

    # --- 4) Ein leeres Guthaben ist kein bad_request ---------------------
    echt = ("Your credit balance is too low to access the Anthropic API. "
            "Please go to Plans & Billing to upgrade or purchase credits.")
    assert C._error_kind(400, echt) == "kein_guthaben"
    assert C._error_kind(400, echt.upper()) == "kein_guthaben", "Gross/Klein"
    # Ein ECHTER bad_request bleibt einer — sonst waere die Unterscheidung
    # wertlos und der naechste Programmierfehler haette eine Stunde Sperre.
    assert C._error_kind(400, "messages.0.content: text content blocks must "
                              "be non-empty") == "bad_request"
    assert C._error_kind(400, "") == "bad_request"
    assert C._error_kind(401, echt) == "auth", "401 bleibt auth"
    assert C._error_kind(429, "x") == "rate"
    assert C._error_kind(500, "x") == "http_500"
    ok("W49: leeres Guthaben ist eine eigene Klasse, kein bad_request")

    # --- 5) Der Body wird EINMAL gelesen ---------------------------------
    # fehlertext() liest e.read() — beim zweiten Mal ist der Body leer. Wer
    # erst klassifiziert und dann liest (oder umgekehrt zweimal liest),
    # bekommt eine leere Meldung und damit wieder "bad_request".
    fc = " ".join(open(os.path.join(hier, "nc", "claude.py"),
                       encoding="utf-8").read().split())
    assert "_detail = fehlertext(e) or \"abgelehnt\" kind = _error_kind(e.code, _detail)" in fc, \
        "Body wird nicht einmal gelesen und dann klassifiziert"
    ok("W49: der Fehlertext wird einmal gelesen und fuer beides benutzt")

    # --- 6) Der Bot sperrt Claude, statt bei jeder Reaktion anzuklopfen --
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    fb = " ".join(bot.split())
    assert 'if _cerr == "kein_guthaben":' in fb
    assert "Anthropic-Guthaben aufgebraucht" in fb, \
        "die Warnung nennt die Ursache nicht im Klartext"
    assert "_CLAUDE_PAUSE[\"bis\"] = _time_mod.monotonic() + CLAUDE_GUTHABEN_PAUSE_S" in fb
    # Die Sperre sitzt an EINER Stelle — es gibt drei Claude-Aufrufer.
    assert fb.count("_akey = _anthropic_key()") >= 3, \
        "weniger Aufrufer als erwartet — Sperre neu pruefen"
    assert "if _CLAUDE_PAUSE[\"bis\"] > _time_mod.monotonic(): return \"\"" in fb, \
        "die Sperre steht nicht in _anthropic_key — dann hat sie nur ein Aufrufer"
    # Und sie loest sich, sobald Claude wieder antwortet. Sonst bliebe er nach
    # dem Aufladen bis zum naechsten Neustart stumm.
    assert "_CLAUDE_PAUSE[\"bis\"] = 0.0" in fb, "die Sperre wird nie aufgehoben"
    # Definition VOR dem ersten Nutzer: _anthropic_key liest das Dict, und ein
    # Aufruf waehrend des Imports haette sonst einen NameError geworfen.
    assert bot.index('_CLAUDE_PAUSE = {') < bot.index('_CLAUDE_PAUSE["bis"] >'), \
        "_CLAUDE_PAUSE steht hinter seinem ersten Nutzer"
    ok("W49: leeres Guthaben sperrt Claude eine Stunde, an genau einer Stelle")


def _test_v42_w50_avatar_ueberlebt_die_drossel():
    """v4.2-W50: W49 hat nur die halbe Entkopplung geliefert — und der eigene
    Vertrag hat es nicht gemerkt.

    W49 behauptete in Changelog und PR, der Avatar haenge nicht mehr an der
    Schrift UND falle auf Drossel-Stufe 3 nicht mehr mit. Der Code tat nur das
    Erste:

        sendebild_on = bool(transcode and RESTREAM_OVERLAY
                            and not drossel_text_aus(drossel))   # <- Drossel
        overlay_on   = bool(sendebild_on and _font)
        avatar_on    = bool(... sendebild_on ...)                # erbt sie

    Der Avatar leitete ueber `sendebild_on` ab und erbte die Drossel damit
    weiter. Im Betrieb erreichte sie Stufe 3, und der Avatar verschwand erneut.

    **Warum der W49-Vertrag das durchliess:** er zaehlte, wie oft
    `drossel_text_aus(drossel)` im Quelltext vorkommt (`== 2`), statt zu
    pruefen, ob der AVATAR-PFAD sie beruehrt. Eine Zaehlung ist keine
    Eigenschaft. Dieser Vertrag prueft deshalb die Ableitungskette selbst.
    """
    import ast as _ast
    from nc import restreamcmd as R

    hier = os.path.dirname(os.path.abspath(__file__))
    quelle = open(os.path.join(hier, "nc", "restreamcmd.py"), encoding="utf-8").read()
    baum = _ast.parse(quelle)
    bau = next(n for n in baum.body
               if isinstance(n, _ast.FunctionDef) and n.name == "build")

    # Die Zuweisungen der fuenf Schalter einsammeln — als SYNTAXBAUM, nicht als
    # Text. Ein Textvergleich haengt an der Formatierung; hier zaehlt, welche
    # Namen im Ausdruck wirklich vorkommen.
    zuweisung = {}
    for n in _ast.walk(bau):
        if isinstance(n, _ast.Assign) and len(n.targets) == 1 \
                and isinstance(n.targets[0], _ast.Name):
            zuweisung.setdefault(n.targets[0].id, n.value)
    for name in ("sendebild_on", "overlay_on", "avatar_on", "anim_on", "feed_on"):
        assert name in zuweisung, "Schalter %s fehlt" % name

    def namen(knoten):
        return {k.id for k in _ast.walk(knoten) if isinstance(k, _ast.Name)}

    def aufrufe(knoten):
        return {k.func.id for k in _ast.walk(knoten)
                if isinstance(k, _ast.Call) and isinstance(k.func, _ast.Name)}

    def kette(name, tiefe=0):
        """Alle Namen und Aufrufe, aus denen `name` transitiv abgeleitet ist."""
        if tiefe > 6 or name not in zuweisung:
            return set(), set()
        n, a = namen(zuweisung[name]), aufrufe(zuweisung[name])
        for weiter in list(n):
            if weiter != name and weiter in zuweisung:
                un, ua = kette(weiter, tiefe + 1)
                n |= un
                a |= ua
        return n, a

    # --- 1) Das PANEL darf die Drossel nicht beruehren -------------------
    # v4.2-W60 hat das fuer alle vier Schalter verlangt. v4.2-W61 nimmt genau
    # einen davon heraus, und zwar auf Ansage des Betreibers: „wenn dann
    # sollte doch der Avatar abgeschalten werden und nicht das ganze panel.“
    #
    # Die Grenze verlaeuft jetzt zwischen Panel und Gesicht, nicht mehr
    # zwischen Bild und Encoder:
    #
    #   sendebild_on / overlay_on   duerfen KEINE drossel_*-Funktion sehen.
    #                               Sie tragen Chat, Titel, react-Zeile — das
    #                               ist der Teil, der nie fallen darf.
    #   avatar_on / anim_on / feed_on   duerfen GENAU EINE sehen:
    #                               drossel_avatar_aus. Jede andere waere ein
    #                               Rueckfall in die Kopplung aus W49/W50.
    for gate in ("overlay_on", "sendebild_on"):
        g_namen, g_aufrufe = kette(gate)
        assert "drossel" not in g_namen, (
            f"{gate} leitet wieder von der Drossel ab — damit kann eine "
            f"CPU-Spitze wieder das Panel aus dem Bild nehmen")
        assert not any("drossel" in a for a in g_aufrufe), (
            f"{gate} ruft eine drossel_*-Funktion: {sorted(g_aufrufe)}")
    for gate in ("avatar_on", "anim_on", "feed_on"):
        _, g_aufrufe = kette(gate)
        _fremd = {a for a in g_aufrufe
                  if "drossel" in a and a != "drossel_avatar_aus"}
        assert not _fremd, (
            f"{gate} ruft eine andere Drossel-Funktion als drossel_avatar_aus: "
            f"{sorted(_fremd)} — der Avatar faellt genau auf einer Stufe, "
            f"nicht als Nebenwirkung von Bildrate oder Leinwand")
    assert "_font" not in kette("avatar_on")[0], "avatar_on haengt wieder an der Schrift"
    a_namen = kette("avatar_on")[0]
    assert "transcode" in a_namen and "RESTREAM_OVERLAY" in a_namen
    ok("W61: das Panel sieht keine Drossel, der Avatar genau eine Sprosse")

    # --- 2) Der Text haengt weiter an der Schrift, sonst an nichts -------
    t_namen, _ = kette("overlay_on")
    assert "_font" in t_namen, "der Text braucht keine Schrift mehr?"
    ok("W60: der Text haengt an der Schrift — und an keiner Drossel mehr")

    # --- 3) Und das Verhalten: KEINE Stufe nimmt etwas aus dem Bild ------
    # v4.2-W60. Der Vertrag prueft nicht mehr eine Schwelle, sondern die
    # Abwesenheit der Moeglichkeit: ueber ALLE Stufen inklusive Anschlag muss
    # das Sendebild dieselben Elemente enthalten. Nur Preset, Bitrate,
    # Bildrate und Leinwand duerfen sich unterscheiden.
    import inspect as _isp
    import re as _re
    _quelle_build = _isp.getsource(R.build)
    # Keine Gate-Zeile darf die Drossel lesen — ausser der einen, die den
    # Avatar bestimmt. Sie wird namentlich zugelassen, damit ein zweiter
    # Griff in den Bildinhalt hier auffliegt statt durchzurutschen.
    # Die Gate-Zeilen werden mitsamt Fortsetzung betrachtet: `anim_on` und
    # `avatar_on` sind mehrzeilig, und ein Test, der nur die erste Zeile
    # liest, sieht die Haelfte nicht.
    _gates = {}
    _akt = None
    for _zeile in _quelle_build.splitlines():
        _z = _zeile.split("#", 1)[0]
        _m = _re.match(r"\s*([A-Za-z_]+_on) = ", _z)
        if _m:
            _akt = _m.group(1)
            _gates[_akt] = _z
        elif _akt and _z.startswith(" " * 8) and not _re.match(r"\s*[a-z_]+ =", _z):
            _gates[_akt] += " " + _z.strip()
        else:
            _akt = None
    assert set(_gates) >= {"sendebild_on", "overlay_on", "avatar_on",
                           "anim_on", "feed_on"}, sorted(_gates)
    for _name, _z in _gates.items():
        # Ein direkter drossel_*-Aufruf hat in KEINEM Gate etwas zu suchen —
        # auch nicht im Avatar-Gate. Die Entscheidung faellt einmal, oben, in
        # `_av_gedrosselt`; hier steht nur noch ihr Ergebnis.
        assert "drossel_" not in _z, \
            f"{_name} ruft eine Drossel-Funktion direkt: {_z.strip()!r}"
        if "_av_gedrosselt" in _z:
            assert _name in ("avatar_on", "anim_on", "feed_on"), \
                (f"{_name} liest die Avatar-Drossel — sie darf nur das Gesicht "
                 f"nehmen, nie das Panel: {_z.strip()!r}")
    # Und umgekehrt: das Avatar-Gate MUSS sie lesen, sonst gibt es die Sprosse
    # gar nicht und der Vertrag prueft ins Leere.
    assert "_av_gedrosselt" in _gates["avatar_on"] \
        or all("_av_gedrosselt" in _gates[g] for g in ("anim_on", "feed_on")), \
        "kein Avatar-Gate liest die Drossel — Stufe 4 tut nichts"
    # Und die Leiter regelt genau die fuenf erlaubten Groessen, in dieser
    # Reihenfolge. Der Avatar steht VOR der Leinwand — gemessen bringt er 14
    # Punkte und laesst den Chat in voller Groesse, die Leinwand bringt nach
    # der Bildrate null und macht den Chat kleiner (v4.2-W61).
    assert R.drossel_preset("superfast", 1) != R.drossel_preset("superfast", 0)
    assert R.drossel_bitrate(4500, 2) < 4500
    assert R.drossel_fps(24, 3) < 24 and R.drossel_fps(24, 2) == 24
    assert R.drossel_avatar_aus(4) and not R.drossel_avatar_aus(3)
    assert R.drossel_canvas(1280, 720, 5) != (1280, 720)
    assert R.drossel_canvas(1280, 720, 4) == (1280, 720), \
        "die Leinwand schrumpft wieder vor dem Avatar"
    # Der Anschlag muss JEDE Sprosse erreichen. Steht DROSSEL_MAX zu niedrig,
    # gibt es die letzte Stufe nur auf dem Papier — der Waechter zaehlt dann
    # nie so weit hoch, und niemand merkt es.
    assert R.drossel_avatar_aus(R.DROSSEL_MAX), \
        "DROSSEL_MAX erreicht die Avatar-Sprosse nicht"
    assert R.drossel_canvas(1280, 720, R.DROSSEL_MAX) != (1280, 720), \
        "DROSSEL_MAX erreicht die Leinwand-Sprosse nicht"
    # Untergrenzen: nichts wird unlesbar klein oder unbrauchbar langsam.
    assert R.drossel_fps(24, 99) >= 15
    _w, _h = R.drossel_canvas(1280, 720, 99)
    assert _w >= 960 and _h >= 540 and _w % 2 == 0 and _h % 2 == 0
    ok("W61: die Leiter regelt Encode-Groessen und genau ein Bild-Element")

    # --- 4) Das Sendebild sagt, warum es so aussieht ---------------------
    # Fuenf stille Boolesche haben in W47 bis W49 drei Runden gekostet. Eine
    # Bedingung, die stumm False wird, ist so schlimm wie ein except, das den
    # Grund frisst (CLAUDE.md).
    # KOMMENTARFREI pruefen. "kein Avatar" und "copy-Modus" stehen beide auch
    # in erklaerenden Kommentaren derselben Datei — ein roher Substring-Test
    # bleibt gruen, waehrend die Meldung verschwindet. Das ist in dieser
    # Sitzung der vierte Vertrag, der ueber einen Kommentar stolpert.
    #
    # Mit tokenize und NICHT mit split("#"): die Meldung selbst enthaelt ein
    # Doppelkreuz ("Sendebild #%s"), und der naive Schnitt haette genau die
    # Zeile zerstoert, die geprueft werden soll. Auch das ist beim Bauen
    # einmal passiert.
    import io as _io
    import tokenize as _tok
    _zeilen = quelle.splitlines()
    for _t in _tok.generate_tokens(_io.StringIO(quelle).readline):
        if _t.type == _tok.COMMENT:
            # Ein Kommentar laeuft bis Zeilenende — an seiner Spalte
            # abzuschneiden ist exakt richtig, und tokenize garantiert, dass
            # es ein echter Kommentar ist und kein Doppelkreuz in einem
            # String. (Die Token einzeln zusammenzufuegen ginge NICHT: dabei
            # kommt zwischen jedes Token ein Leerzeichen und die gesuchten
            # Zeichenketten zerfallen.)
            _r, _c = _t.start
            _zeilen[_r - 1] = _zeilen[_r - 1][:_c]
    fr = " ".join(" ".join(_zeilen).split())
    assert 'log.warning("Sendebild #%s: Text=%s Avatar=%s' in fr, \
        "es gibt keine Zeile, die den Zustand des Sendebilds nennt"
    # Jeder Grund MIT seiner Fundstelle — sonst prueft man nur, dass die
    # Woerter irgendwo vorkommen, nicht dass sie gemeldet werden.
    for fundstelle in (
            # ANKER GEWANDERT (v4.2-W60): "Text aus (Drossel Stufe …)" gibt es
            # nicht mehr — die Drossel kann den Text nicht mehr abschalten.
            '_gruende.append("keine Schrift gefunden',
            '_gruende.append("kein Avatar (RESTREAM_AVATAR=%r'):
        assert fundstelle in fr, "der Grund fehlt: %s" % fundstelle
    assert "Text aus (Drossel" not in fr, \
        "die Sendebild-Zeile nennt die Drossel wieder als Grund fuer fehlenden " \
        "Text — sie kann ihn seit W60 gar nicht mehr abschalten"
    # Der Copy-Modus bekommt eine eigene WARNUNG — auf debug saehe der
    # Betreiber ein leeres Sendebild ohne jeden Hinweis, und genau so sieht
    # ein Defekt aus.
    assert ('log.warning("Sendebild #%s: RESTREAM_OVERLAY=1, aber copy-Modus'
            in fr), "der Copy-Modus meldet sich nicht als Warnung"
    # Der gesunde Fall darf NICHT warnen — eine Warnung bei jedem Start
    # erzieht dazu, sie zu ueberlesen.
    assert 'log.info("Sendebild #%s: Text an, Avatar an' in fr, \
        "der gesunde Fall meldet sich gar nicht oder als Warnung"
    assert "apt install fonts-dejavu-core" in fr, "die Abhilfe fehlt"
    ok("W50: eine Zeile nennt Text, Avatar und jeden fehlenden Grund")


def _test_v42_w61_avatar_faellt_vor_dem_panel():
    """v4.2-W61: wenn etwas weichen muss, dann das Gesicht — nie der Chat.

    W60 hat die Drossel vom Bildinhalt getrennt: Preset, Bitrate, Bildrate,
    Leinwand, sonst nichts. Am Anschlag blieb damit nur noch „die Box schafft
    es nicht". Der Betreiber hat die fehlende Sprosse benannt: „wenn dann
    sollte doch der Avatar abgeschalten werden und nicht das ganze panel.
    Somit kann der Zuschauer immer noch live den chat verfolgen. Zusaetzlich
    sollte dann aber noch die live Reaction von Azrael/Avatar weiter laufen."

    Zwei Zusicherungen also, und beide werden am ECHTEN gebauten Kommando
    geprueft, nicht an Quelltextzeilen — der Unterschied hat in dieser Reihe
    schon dreimal einen Vertrag durchgelassen, der gruen war, waehrend die
    Sache kaputt war:

      1. Ueber ALLE Stufen inklusive Anschlag stehen Chat und react-Zeile im
         Filtergraph. Der Avatar faellt genau auf Stufe 4 und keine frueher.
      2. AZRAELs Reaktion erreicht den Zuschauer auch ohne Avatarbild: die
         react-Zeile nennt den Wortlaut, und die Stimme (der TTS-Zweig) haengt
         nirgends am Avatar.

    Dazu die Falle, die der Schritt aufmacht: `_restream_avatar_feeder_start`
    haengt in `open(fifo, "wb")`, bis ein Leser kommt. Faellt der Avatar-Input
    aus dem Kommando, kommt nie einer — und weil ein Drossel-Schritt den
    Restream neu startet, waere das ein haengender Thread JE Neustart.
    """
    import os as _os
    import tempfile as _tf
    from nc import restreamcmd as R

    hier = _os.path.dirname(_os.path.abspath(__file__))

    schrift = _tf.NamedTemporaryFile(suffix=".ttf", delete=False)
    schrift.write(b"x"); schrift.close()
    avatar = _tf.NamedTemporaryFile(suffix=".png", delete=False)
    avatar.write(b"x"); avatar.close()
    OVDIR = _ph.verzeichnis()
    OV = {k: _os.path.join(OVDIR, k + ".txt") for k in
          ("alert", "brand", "caption", "chat", "follow", "goal",
           "react", "source", "title")}
    for _pfad in OV.values():
        open(_pfad, "w").write("x")

    R.configure(
        cookie_header=lambda: "", pick_pull_proxy=lambda: "",
        restream_overlay_files=lambda rid=None: OV,
        FFMPEG_THREADS_LIVE=3, FFMPEG_THREADS_RELAY=2,
        RESTREAM_AVATAR=avatar.name, RESTREAM_BITRATE_K=4500,
        RESTREAM_AVATAR_ALPHA="", RESTREAM_AVATAR_H=170,
        RESTREAM_AVATAR_LOOP="",
        RESTREAM_CANVAS_H=720, RESTREAM_CANVAS_W=1280,
        RESTREAM_FONT=schrift.name, RESTREAM_FPS=24,
        RESTREAM_LOW_LATENCY=True, RESTREAM_OVERLAY=True,
        RESTREAM_OVERLAY_HTML_FPS=1, RESTREAM_RELAY_BITRATE_K=3500,
        RESTREAM_RELAY_PRESET="ultrafast", RESTREAM_X264_PRESET="veryfast",
        RESTREAM_UA="UA/1.0", TTS_CH=2, TTS_SR=44100, TTS_VOICE_GAIN="1.8")

    QUELLE = "https://pull.tiktok.com/stage/x.flv"
    ZIEL = ("kick", "rtmps://ingest.example/app/SCHLUESSEL")

    def graph(stufe, tts=True):
        cmd = R.build(QUELLE, "", "", transcode=True, targets=[ZIEL],
                      tts_fifo=("/tmp/tts.fifo" if tts else None),
                      drossel=stufe)
        return cmd, cmd[cmd.index("-filter_complex") + 1]

    # --- 1) Chat und react-Zeile ueberleben JEDE Stufe -------------------
    # Ueber den Anschlag hinaus mitgeprueft: eine Stufe, die es (noch) nicht
    # gibt, darf nicht zufaellig etwas anderes tun als der Anschlag.
    for stufe in range(0, R.DROSSEL_MAX + 3):
        cmd, fc = graph(stufe)
        assert OV["chat"] in fc, \
            f"Stufe {stufe}: der Chat steht nicht mehr im Sendebild"
        assert OV["react"] in fc, \
            f"Stufe {stufe}: AZRAELs react-Zeile steht nicht mehr im Sendebild"
        assert OV["title"] in fc and OV["follow"] in fc, \
            f"Stufe {stufe}: das Panel ist unvollstaendig"
    ok("W61: Chat, Titel und react-Zeile stehen auf jeder Drossel-Stufe im Bild")

    # --- 2) Der Avatar faellt auf Stufe 4 — und keine frueher ------------
    # Am Kommando gemessen, nicht am Schalter: der Avatar ist genau dann im
    # Bild, wenn seine Datei als Input dasteht UND ein overlay ihn einblendet.
    for stufe in range(0, R.DROSSEL_MAX + 3):
        cmd, fc = graph(stufe)
        drin = (avatar.name in cmd)
        erwartet = stufe < 4
        assert drin is erwartet, (
            f"Stufe {stufe}: Avatar {'im' if drin else 'nicht im'} Kommando, "
            f"erwartet war {'im' if erwartet else 'nicht im'} Kommando")
        # Und der Overlay-Filter dazu, sonst laege die Datei nur ungenutzt an.
        assert ("[sav]" in fc) is erwartet, \
            f"Stufe {stufe}: Avatar-Input und Overlay-Filter sind uneins"
    ok("W61: der Avatar faellt genau auf Stufe 4, keine Stufe frueher")

    # --- 3) AZRAELs Stimme haengt nicht am Gesicht -----------------------
    # Ohne diese Zusicherung koennte ein spaeterer Umbau den TTS-Zweig an
    # `avatar_on` haengen — dann waere AZRAEL ab Stufe 4 auch stumm, und das
    # ist genau das Gegenteil der Ansage.
    for stufe in (0, 4, R.DROSSEL_MAX):
        cmd, fc = graph(stufe, tts=True)
        assert "/tmp/tts.fifo" in cmd, f"Stufe {stufe}: die TTS-FIFO fehlt"
        assert "[a]" in cmd, f"Stufe {stufe}: der gemischte Ton wird nicht gemappt"
    # Gegenprobe: ohne TTS-FIFO faellt der Zweig weg — sonst prueft der Test
    # nur, dass irgendein "[a]" im Kommando steht.
    cmd, _fc = graph(4, tts=False)
    assert "/tmp/tts.fifo" not in cmd and "[a]" not in cmd
    ok("W61: AZRAELs Stimme laeuft weiter, wenn sein Bild gedrosselt ist")

    # --- 4) Der Frame-Feeder wird bei gedrosseltem Avatar nicht gestartet -
    # Sonst haengt sein Writer fuer immer in open(fifo, "wb") — es kommt kein
    # Leser mehr. Ein Drossel-Schritt startet den Restream neu, das waere also
    # ein haengender Thread je Schritt.
    bot = open(_os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert ("if (RESTREAM_OVERLAY and transcode and not "
            "_nc_rscmd.drossel_avatar_aus(_drossel_stufe(rid))):" in flach), \
        "der Avatar-Feeder startet auch dann, wenn kein ffmpeg ihn liest"
    # Und die Bedingung steht VOR dem Start, nicht irgendwo in der Datei.
    _i = flach.find("_av_feed = await asyncio.to_thread(_restream_avatar_feeder_start")
    assert _i > 0, "der Feeder-Start ist verschwunden"
    assert "drossel_avatar_aus(_drossel_stufe(rid))" in flach[max(0, _i - 400):_i], \
        "die Drossel-Pruefung steht nicht unmittelbar vor dem Feeder-Start"
    # Das open() ist der Grund — bleibt es blockierend, bleibt die Pruefung noetig.
    assert 'with open(fifo, "wb") as f:' in flach, \
        "der Writer oeffnet die FIFO anders — die Begruendung oben neu pruefen"
    ok("W61: bei gedrosseltem Avatar startet kein Feeder, der niemanden findet")

    # --- 5) Das Log sagt, was weg ist UND was bleibt ---------------------
    # "Avatar aus" allein liest sich wie "AZRAEL ist weg". Er ist es nicht.
    zusatz = R.drossel_zusatz(24, 1280, 720, 4)
    assert "Avatar aus" in zusatz, "die Waechter-Zeile verschweigt den Avatar"
    for wort in ("Chat", "react", "Stimme"):
        assert wort in zusatz, \
            f"die Waechter-Zeile sagt nicht, dass {wort} bleibt: {zusatz!r}"
    assert "Avatar aus" not in R.drossel_zusatz(24, 1280, 720, 3), \
        "die Zeile meldet den Avatar schon auf Stufe 3 als weg"
    ok("W61: die Waechter-Zeile nennt den Verlust und das, was steht")


def _test_v42_w62_avatar_afk_zustand():
    """v4.2-W62: AZRAEL kannte zwei Bilder von sich. Der dritte fehlte.

    Gemeldet zusammen mit dem Layout-Umbau: „Der Avatar braucht idle/afk
    Animationen." Der Feeder entschied bis hierher mit einer Zeile —
    `jetzt = _azrael_spricht()` — und hatte damit genau zwei Zustaende. Ueber
    Stunden ohne Chat spielte die Figur dieselben drei Sekunden, und das liest
    sich im Sendebild als Standbild. Ein Standbild sieht aber genauso aus wie
    ein abgestuerzter Restream: der Zuschauer kann nicht unterscheiden, ob
    nichts passiert oder nichts mehr geht.

    Geprueft werden die drei Stellen, an denen das schiefgehen kann:

      1. Die Entscheidung selbst (nc/avatarloop.py, reine Funktionen).
      2. Der Bezugspunkt: ohne den Feeder-Start in der Ruhezeit stuende die
         Figur beim Stream-Beginn sofort in AFK.
      3. Der Rueckfall: die AFK-Schleife FEHLT in jedem Bestand, der den
         Generator seit W62 nicht laufen liess. Fehlt sie, muss Ruhe
         weiterlaufen — und es muss im Log stehen.
    """
    import os as _os
    from nc import avatarloop as L
    import tools.azrael_frames as A

    # --- 1) Sprechen schlaegt alles -------------------------------------
    # Sagt AZRAEL gerade etwas, ist er nicht abwesend — egal wie lange der
    # Chat davor still war. Ohne diesen Vorrang antwortete eine schlafende
    # Figur mit geschlossenen Augen.
    for ruhe_s in (0.0, 10.0, 89.9, 90.0, 1e6):
        assert L.zustand(True, ruhe_s) == L.SPRICH, ruhe_s
    ok("W62: Sprechen gewinnt gegen jede Ruhezeit")

    # --- 2) Die Schwelle liegt, wo sie liegt ----------------------------
    assert L.zustand(False, 0.0) == L.RUHE
    assert L.zustand(False, L.AFK_NACH_S - 0.01) == L.RUHE
    assert L.zustand(False, L.AFK_NACH_S) == L.AFK, \
        "genau auf der Schwelle passiert nichts — dann ist sie unerreichbar"
    assert L.zustand(False, L.AFK_NACH_S * 10) == L.AFK
    # Eigene Schwelle, und die 0 als Ausschalter. Ohne den Ausschalter waere
    # der Rueckweg auf das Verhalten vor W62 ein Codeeingriff.
    assert L.zustand(False, 5.0, afk_nach_s=4.0) == L.AFK
    assert L.zustand(False, 5.0, afk_nach_s=6.0) == L.RUHE
    for aus in (0, 0.0, -1):
        assert L.zustand(False, 1e9, afk_nach_s=aus) == L.RUHE, \
            f"afk_nach_s={aus} schaltet AFK nicht ab"
    ok("W62: die AFK-Schwelle greift genau ab ihrem Wert und ist abschaltbar")

    # --- 3) Der Feeder-Start zaehlt als Aktivitaet ----------------------
    # DAS IST DIE STELLE, DIE DEN STREAM-BEGINN RETTET. Beim Start hat noch
    # niemand geschrieben; ohne den Startstempel waere die juengste Aktivitaet
    # "nie" und die Figur ginge mit geschlossenen Augen auf Sendung.
    jetzt = 1_000_000.0
    assert L.ruhe_seit(jetzt, None, 0.0, jetzt) == 0.0, \
        "der Feeder-Start zaehlt nicht — die Figur startet in AFK"
    assert L.zustand(False, L.ruhe_seit(jetzt, None, 0.0, jetzt)) == L.RUHE
    # Gar nichts bekannt = gerade eben, nicht seit jeher.
    assert L.ruhe_seit(jetzt) == 0.0
    assert L.ruhe_seit(jetzt, None, 0.0, None) == 0.0
    # Die juengste Quelle gewinnt, egal in welcher Reihenfolge sie kommt.
    assert L.ruhe_seit(jetzt, jetzt - 500, jetzt - 30) == 30.0
    assert L.ruhe_seit(jetzt, jetzt - 30, jetzt - 500) == 30.0
    # Eine vorlaufende Uhr darf keine negative Ruhezeit liefern.
    assert L.ruhe_seit(jetzt, jetzt + 5) == 0.0
    ok("W62: die Ruhezeit zaehlt ab der juengsten Quelle und wird nie negativ")

    # --- 4) Fehlt eine Schleife, laeuft Ruhe weiter ---------------------
    # Jeder Bestand von vor W62 hat keine afk.webm. Ohne den Rueckfall
    # bekaeme der Writer None und schriebe nichts mehr in die FIFO — ffmpeg
    # stallt daran, und mit ihm der ganze Restream.
    voll = {L.RUHE: ["r"], L.SPRICH: ["s"], L.AFK: ["a"]}
    for z in L.ZUSTAENDE:
        assert L.schleife(z, voll) == (voll[z], z)
    ohne = {L.RUHE: ["r"]}
    for z in (L.SPRICH, L.AFK):
        assert L.schleife(z, ohne) == (["r"], L.RUHE), \
            f"{z} faellt nicht auf Ruhe zurueck — der Writer bekaeme None"
    # Zurueck kommt IMMER auch, was wirklich gespielt wird. Nur so kann der
    # Aufrufer melden, dass etwas fehlt, statt stumm etwas anderes zu zeigen.
    assert L.schleife(L.AFK, ohne)[1] == L.RUHE
    assert L.schleife(L.AFK, {}) == (None, L.RUHE)
    ok("W62: eine fehlende Schleife faellt auf Ruhe zurueck und sagt es")

    # --- 5) Das Blinzeln ist exakt periodisch ---------------------------
    # Mit `t % periode` gerechnet kippt der Naht-Vertrag aus W53 an einer
    # Stelle, an der die Bewegung in Ordnung ist — Gleitkomma-Reste.
    for t in (0.0, 0.37, 1.4, 2.9):
        assert abs(L.blinzeln(t, 3.0) - L.blinzeln(t + 3.0, 3.0)) < 1e-12
        assert abs(L.blinzeln(t, 3.0) - L.blinzeln(t + 6.0, 3.0)) < 1e-12
    # Bei t=0 muss das Auge OFFEN sein: sonst blinzelt die Figur genau im
    # Moment des Umschaltens auf AFK.
    assert L.blinzeln(0.0, 3.0) < 1e-6, "die Schleife beginnt mit zugefallenem Auge"
    # Und es muss ein Blinzeln sein, kein langsames Verdunkeln: der Abzug
    # steht nur einen Bruchteil der Periode ueber der Haelfte.
    n = 600
    zu = sum(1 for i in range(n) if L.blinzeln(i * 3.0 / n, 3.0) > 15.0)
    assert 0 < zu / n < 0.15, \
        f"das Auge ist {100 * zu / n:.0f} %% der Zeit zu — das ist kein Blinzeln"
    ok("W62: das Blinzeln ist exakt periodisch, kurz, und beginnt offen")

    # --- 6) AFK ist eine HALTUNG, nicht nur langsamer -------------------
    # Der erste Entwurf halbierte bloss die Ruhe-Amplituden. Bei ein bis zwei
    # Grad Ausschlag war das Ergebnis von der Ruheschleife nicht zu
    # unterscheiden. Erkennbar wird die Abwesenheit am festen Versatz.
    def mittel(zust, laenge, glied, n=120):
        return sum(A.bewegung(i * laenge / n, zust)[glied] for i in range(n)) / n
    kopf_ruhe = mittel(A.RUHE, A.RUHE_S, "kopf_hoch")
    kopf_afk = mittel(A.AFK, A.AFK_S, "kopf_hoch")
    assert kopf_afk - kopf_ruhe > 3.0, (
        f"das Kinn sinkt in AFK nur um {kopf_afk - kopf_ruhe:.1f} px gegenueber "
        f"Ruhe — im Standbild sieht man keinen Unterschied")
    kl_ruhe = mittel(A.RUHE, A.RUHE_S, "klinge_grad")
    kl_afk = mittel(A.AFK, A.AFK_S, "klinge_grad")
    assert kl_ruhe - kl_afk > 2.0, (
        f"die Klingenspitze faellt in AFK nur um {kl_ruhe - kl_afk:.1f} Grad")
    # Augen und Aura heruntergefahren — aber nie ganz aus. Eine schwarze
    # Figur ohne Glut liest sich als Bildfehler.
    for glied, n in (("augen", 240), ("aura", 240)):
        r = max(A.bewegung(i * A.RUHE_S / n, A.RUHE)[glied] for i in range(n))
        a = max(A.bewegung(i * A.AFK_S / n, A.AFK)[glied] for i in range(n))
        tief = min(A.bewegung(i * A.AFK_S / n, A.AFK)[glied] for i in range(n))
        assert 0 < a < r, f"{glied}: AFK {a:.2f} nicht gedaempft gegen Ruhe {r:.2f}"
        assert tief > 0, f"{glied} faellt in AFK auf {tief:.2f} — das ist ein Loch"
    # Der Mund bleibt zu. Ein sprechender AFK-Avatar waere ein Widerspruch.
    assert all(A.bewegung(i * A.AFK_S / 120, A.AFK)["mund_auf"] == 0.0
               for i in range(120))
    ok("W62: AFK senkt Kinn und Klinge, daempft Glut und haelt den Mund zu")

    # --- 6b) Das Lid faellt wirklich zu ---------------------------------
    # GEMESSEN, WARUM ES DAS BRAUCHT: nur die Glut wegzunehmen liess den
    # Augenkasten im gerenderten Bild von 63 auf 55 fallen — 13 Prozent. Das
    # ist kein Blinzeln, das ist ein Flackern. Mit dem Lid faellt derselbe
    # Kasten auf 9,3, also um 85 Prozent. Gerechnet wird das hier nicht
    # nach: Pillow steht bewusst in keiner requirements-Datei und fehlt in
    # der CI. Geprueft wird stattdessen, dass es das Lid GIBT, dass es nur
    # in AFK faellt, und dass es an der richtigen Stelle gezeichnet wird.
    for zust, laenge in ((A.RUHE, A.RUHE_S), (A.SPRICH, A.SPRECH_S)):
        assert all(A.bewegung(i * laenge / 60, zust)["lid"] == 0.0
                   for i in range(60)), f"in {zust} faellt ein Lid"
    lids = [A.bewegung(i * A.AFK_S / 240, A.AFK)["lid"] for i in range(240)]
    assert max(lids) > 0.95, f"das Lid faellt nur bis {max(lids):.2f} — halb zu"
    assert min(lids) < 0.01, "das Lid geht nie ganz auf"
    assert A.bewegung(0.0, A.AFK)["lid"] < 1e-6, \
        "die AFK-Schleife beginnt mit geschlossenem Auge"
    # Lid und Glut gehoeren zum SELBEN Lidschlag: dunkelstes Auge und
    # tiefstes Lid muessen im selben Moment liegen. Zwei getrennte Rechnungen
    # ergaeben ein Auge, das erlischt, waehrend das Lid noch offen ist.
    _t_lid = max(range(240), key=lambda i: lids[i])
    _t_glut = min(range(240),
                  key=lambda i: A.bewegung(i * A.AFK_S / 240, A.AFK)["augen"])
    assert abs(_t_lid - _t_glut) <= 2, \
        f"Lid faellt bei Frame {_t_lid}, die Glut geht bei {_t_glut} aus"
    # Und die Zeichenreihenfolge: das Lid ZULETZT. Davor gesetzt leuchtet die
    # Glut durch das geschlossene Lid wieder hindurch — beim Bauen passiert.
    quelle_f = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)),
                             "tools", "azrael_frames.py")
    ftxt = open(quelle_f, encoding="utf-8").read()
    i_frame = ftxt.index("def frame(")
    rumpf = ftxt[i_frame:]
    assert rumpf.index('lid = b.get("lid"') > rumpf.index("aug.point(lambda v: v // 4)"), \
        "das Lid wird VOR der Augenglut gezeichnet — dann leuchtet sie hindurch"
    ok("W62: das Lid faellt nur in AFK, ganz, im Takt der Glut und zuletzt")

    # --- 7) Generator und Zustandsautomat kennen dieselben Schleifen ----
    # ZWEI LISTEN WAEREN ZWEI WAHRHEITEN. Der Generator schreibt Dateien nach
    # diesen Namen, der Feeder sucht sie danach — eine Abweichung faellt erst
    # im Sendebild auf, als stiller Rueckfall auf Ruhe.
    assert tuple(n for n, _ in A.SCHLEIFEN) == tuple(L.ZUSTAENDE), \
        f"{[n for n, _ in A.SCHLEIFEN]} vs {list(L.ZUSTAENDE)}"
    assert len(set(L.ZUSTAENDE)) == len(L.ZUSTAENDE), "doppelter Zustand"
    # Und jeder Zustand, den die Entscheidung liefern KANN, hat eine Schleife.
    erreichbar = {L.zustand(sp, r, a)
                  for sp in (True, False) for r in (0.0, 1e6) for a in (0, 90.0)}
    assert erreichbar <= set(n for n, _ in A.SCHLEIFEN), \
        f"die Entscheidung kann {erreichbar} liefern, gebaut wird nur " \
        f"{[n for n, _ in A.SCHLEIFEN]}"
    assert erreichbar == set(L.ZUSTAENDE), \
        f"ein Zustand ist unerreichbar: {set(L.ZUSTAENDE) - erreichbar}"
    ok("W62: jeder erreichbare Zustand hat eine Schleife, und keine zu viel")

    # --- 8) Der Feeder benutzt das alles auch --------------------------
    # Die schoenste reine Funktion nuetzt nichts, wenn der Writer weiter
    # seinen Booleschen liest.
    hier = _os.path.dirname(_os.path.abspath(__file__))
    bot = open(_os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert "sprich_bilder if sprach else ruhe_bilder" not in flach, \
        "der Writer waehlt weiter zwischen genau zwei Schleifen"
    assert "soll = _nc_avloop.zustand(" in flach, \
        "der Writer fragt den Zustandsautomaten nicht"
    assert "bilder, echt = _nc_avloop.schleife(soll, vorrat)" in flach, \
        "der Writer holt die Frames nicht ueber den Rueckfall"
    # Der Startstempel MUSS in die Ruhezeit — sonst startet die Figur in AFK.
    i = flach.find("soll = _nc_avloop.zustand(")
    assert "begonnen)" in flach[i:i + 400], \
        "der Feeder-Start steht nicht in der Ruhezeit — die Figur startet in AFK"
    assert "begonnen = _time_mod.time()" in flach, "kein Startstempel"
    # Und die Schwelle kommt aus der .env, nicht als Zahl im Quelltext.
    assert "RESTREAM_AVATAR_AFK_S" in flach[i:i + 400], \
        "die Schwelle steht nicht als .env-Wert in der Entscheidung"
    assert 'RESTREAM_AVATAR_AFK = os.getenv("RESTREAM_AVATAR_AFK"' in flach, \
        "der Pfad zur AFK-Schleife ist nicht einstellbar"
    ok("W62: der Feeder entscheidet ueber nc.avatarloop, mit Startstempel")


def _test_v42_w63_manuelle_aufnahme_sichtbar_und_stoppbar():
    """v4.2-W63: Start ohne Liste, Liste ohne Knopf — und ein Deck, das luegt.

    Letzter offener Kandidat aus der Dashboard-Pruefung, diesmal von Hand
    nachgesehen statt dem Matcher geglaubt. Der Befund ist echt und
    schlimmer als „Knopf fehlt":

        /api/recordings/manual/start        verdrahtet
        /api/recordings/manual/list         NIRGENDS gerufen
        /api/recordings/manual/<mid>/stop   NIRGENDS gerufen

    Eine manuelle Aufnahme liegt in der Tabelle `manual_recordings`. Das
    Panel AKTIVE AUFNAHMEN liest `/api/active-recordings`, und das kommt aus
    `trackings WHERE recording=1` — eine andere Tabelle. Die manuelle
    Aufnahme stand dort noch nie drin.

    `rtManualStart` rief danach ausgerechnet `loadRtActive()`. Das Deck
    antwortete auf einen erfolgreichen Start also mit „Keine laufende
    Aufnahme.", waehrend eine lief. Bis zur eigenen Laufzeitgrenze (max eine
    Stunde) war sie weder sichtbar noch abbrechbar.

    Dazu die Falle, die eine Oberflaeche erst sichtbar macht:
    `_MANUAL_RECORDINGS` lebt im Prozess. Nach einem Bot-Neustart ist das
    Dict leer, die DB-Zeile steht aber weiter auf 'running' — und
    `_wait_and_finish`, das sie abschliessen wuerde, gibt es nicht mehr. Die
    Zeile bleibt fuer immer auf „laeuft", mit einem Stop-Knopf, der nur
    scheitern kann.
    """
    hier = os.path.dirname(os.path.abspath(__file__))
    deck = open(os.path.join(hier, "templates", "dashboard.html"),
                encoding="utf-8").read()
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()

    # --- 1) Alle drei Routen werden aus dem Deck gerufen -----------------
    for route in ("/api/recordings/manual/start",
                  "/api/recordings/manual/list",
                  "/api/recordings/manual/"):
        assert route in deck, f"{route} wird aus dem Deck nicht gerufen"
    assert "'/api/recordings/manual/'+mid+'/stop'" in deck, \
        "die Stop-Route wird nicht mit einer Kennung gerufen"
    ok("W63: Start, Liste und Stopp der manuellen Aufnahme sind verdrahtet")

    # --- 2) Der Start laedt die RICHTIGE Liste nach ----------------------
    # Das ist der eigentliche Befund. loadRtActive() allein war schlimmer als
    # gar nichts: es behauptet aktiv, es laufe nichts.
    i = deck.find("async function rtManualStart(")
    assert i > 0, "rtManualStart fehlt"
    rumpf = deck[i:deck.find("\nasync function loadRtManual", i)]
    assert "loadRtManual()" in rumpf, \
        "nach dem Start wird die manuelle Liste nicht geladen — das Deck " \
        "zeigt weiter 'Keine laufende Aufnahme.', waehrend eine laeuft"
    ok("W63: nach dem Start laedt das Deck die manuelle Liste")

    # --- 3) Das Panel existiert und haengt am Ansichts-Lader -------------
    # Eine Funktion, die niemand aufruft, ist so tot wie eine Route ohne
    # Knopf (W56).
    assert 'id="rt_manual"' in deck, "das Ziel-Panel gibt es nicht"
    assert 'id="rt_manual_n"' in deck, "der Zaehler am Panel fehlt"
    # IM ANSICHTS-LADER nachsehen, nicht irgendwo im Deck. Genau daran ist
    # die Mutationsprobe „Panel haengt an keinem Lader" zuerst vorbeigelaufen:
    # dieselbe Zeilenfolge steht auch in rtManualStart, die Zusicherung war
    # gruen, waehrend loadRecTools das Panel nicht mehr lud. Vorhandensein
    # statt Eigenschaft — in dieser Reihe zum wiederholten Mal.
    j = deck.find("async function loadRecTools(")
    assert j > 0, "der Lader der Aufnahme-Ansicht fehlt"
    lader = deck[j:deck.find("\n}", j)]
    assert "loadRtManual()" in lader, \
        "loadRtManual haengt nicht am Lader der Aufnahme-Ansicht — das Panel " \
        "bliebe beim Oeffnen leer"
    ok("W63: das Panel existiert und wird beim Oeffnen der Ansicht geladen")

    # --- 4) Der Stop-Knopf nur, solange es etwas zu stoppen gibt ---------
    # Sonst antwortet der Endpunkt "manual recording not running" — ein
    # Knopf, der ausschliesslich scheitern kann, ist schlimmer als keiner.
    k = deck.find("async function loadRtManual(")
    assert k > 0
    lade = deck[k:deck.find("\nasync function rtStopManual", k)]
    assert "rtStopManual(" in lade, "die Liste bietet keinen Stop-Knopf"
    _kn = lade[lade.find("const knopf="):]
    _kn = _kn[:_kn.find("\n    return")]
    assert "st==='running'" in _kn, \
        "der Stop-Knopf haengt nicht am Zustand — er stuende auch an einer " \
        "laengst fertigen Aufnahme und koennte dort nur scheitern"
    # Und er ist fuer Screenreader benannt: "Stop" allein sagt nicht, wovon.
    assert "aria-label=" in _kn, "der Stop-Knopf hat keine Beschriftung"
    ok("W63: der Stop-Knopf steht nur an laufenden Aufnahmen, und benannt")

    # --- 5) Farbe traegt die Information nicht allein --------------------
    # Regel aus dem html-templates-Skill. Ein roter Punkt ohne Wort ist fuer
    # jeden unlesbar, der Rot und Gruen nicht unterscheidet.
    assert "const wort={running:" in lade, \
        "die Zustaende stehen nur als Farbe da, nicht als Wort"
    for zustand in ("running", "completed", "empty", "abgebrochen"):
        assert zustand + ":" in lade, f"der Zustand {zustand} hat kein Wort"
    ok("W63: jeder Zustand steht als Wort da, nicht nur als Farbe")

    # --- 6) Ein Phantom wird aufgeraeumt, nicht bloss gemeldet -----------
    # Nach einem Neustart steht die Zeile fuer immer auf 'running'. Ohne
    # diesen Zweig zeigte das neue Panel eine Aufnahme, die es nicht gibt.
    i = bot.find("def stop_manual_recording(")
    assert i > 0, "stop_manual_recording fehlt"
    rumpf = bot[i:bot.find("\ndef ", i + 1)]
    assert "UPDATE manual_recordings SET status='abgebrochen'" in rumpf, \
        "eine Zeile, die auf 'running' steht ohne Prozess dahinter, bleibt " \
        "fuer immer stehen — der Stop-Knopf kann sie nur anmeckern"
    assert 'z["status"] == "running"' in rumpf, \
        "aufgeraeumt wird ohne Pruefung — das schriebe auch fertige Zeilen um"
    assert "ended_at=?" in rumpf, "die aufgeraeumte Zeile bekommt kein Ende"
    # Still darf das nicht passieren: der Betreiber soll wissen, dass hier
    # ein Neustart-Rest lag (CLAUDE.md, stille except-Bloecke).
    assert "log.warning(" in rumpf, "das Aufraeumen steht in keinem Log"
    # Und der Klick meldet es zurueck, statt 'Aufnahme gestoppt' zu behaupten.
    assert "r.error||'Aufnahme gestoppt'" in deck, \
        "der Erfolgsfall verschluckt den Hinweis auf den Neustart-Rest"
    ok("W63: ein Neustart-Rest wird abgeschlossen, geloggt und gemeldet")


def _test_v42_w64_dienstmeldung_statt_antwort():
    """v4.2-W64: der Anbieter schickt seine Rechnung, der Bot sagt sie im Chat auf.

    Aus dem Moderator-Log des Betreibers, Eintraege `send` UND `reaction`:

        The API key used for this request has exceeded budget. Please
        [raise the key budget](https://enter.pollinations.ai/edit-key?id=…)
        then try again

    Pollinations meldet ein erschoepftes Budget NICHT als HTTP 402, sondern
    als **HTTP 200 mit dem Fehlertext im Antwortinhalt**. `_classify_status`
    sieht 200 und schweigt, `_extract_text` findet Text, und
    `if txt: return (txt, None)` erklaert die Base fuer gesund.

    Zwei Folgen, beide schlimm:

      1. DIE ROTATION GREIFT NIE. Die Base gilt als arbeitsfaehig — obwohl
         genau fuer diesen Fall vier Basen im Katalog stehen. Der Betreiber:
         „Auch hier brauchen wir eine kostenlose Alternative."
      2. DER TEXT GEHT IN DEN OEFFENTLICHEN CHAT, samt der URL, die die
         Kennung des Keys traegt.

    Dazu ein zweiter Befund an derselben Stelle: `if "pollinations.ai" in
    b["url"]` haengte den Key an BEIDE Pollinations-Basen — auch an die, die
    ihr eigener Kommentar „keyless, offener Altpfad" nennt. Beide teilten sich
    damit ein Budget und fielen gemeinsam aus. Es gab also genau dann keine
    kostenlose Alternative mehr, wenn man sie braucht.
    """
    import json as _json
    import http.server as _hs
    import socketserver as _ss
    import threading as _th
    from nc import freeai as F

    ECHT = ("The API key used for this request has exceeded budget. Please "
            "[raise the key budget](https://enter.pollinations.ai/edit-key"
            "?id=89idjaTSg2hI4YwZDuO8ZME5Ma6GrFps) then try again")

    # --- 1) Die Meldung aus dem Screenshot wird erkannt ------------------
    marke = F.dienstmeldung(ECHT)
    assert marke, "die gemeldete Budget-Meldung wird nicht als solche erkannt"
    # Zurueck kommt die MARKE, nicht der Text: nur so kann das Log sagen, was
    # erkannt wurde, ohne die Key-Kennung zu wiederholen.
    assert marke in ECHT.lower() and len(marke) < 40, marke
    assert "89idjaTSg" not in marke, "die Marke traegt die Key-Kennung"
    for weitere in ("Insufficient_quota", "You exceeded your current quota.",
                    "Rate limit reached for gpt-4", "Payment Required",
                    '{"error": {"message": "nope"}}'):
        assert F.dienstmeldung(weitere), weitere
    ok("W64: die Budget-Meldung wird als Dienstmeldung erkannt")

    # --- 2) Eine echte Antwort wird NICHT erkannt ------------------------
    # Ein Fehlalarm kostet eine Anfrage, ein uebersehener Treffer eine
    # Anbieter-Meldung im oeffentlichen Chat — aber gaenzlich blind darf die
    # Erkennung deshalb trotzdem nicht zuschlagen.
    for echt in ("Klar, mach ich.", "", "   ",
                 "Der Stream laeuft seit 20 Minuten, alles ruhig.",
                 "budget", "Ich habe kein Budget fuer sowas.",
                 "Mein Schwert ist scharf und mein Geduldsfaden kurz."):
        assert not F.dienstmeldung(echt), f"Fehlalarm auf {echt!r}"
    ok("W64: normale Antworten loesen keinen Fehlalarm aus")

    # --- 3) Und die Rotation greift wirklich -----------------------------
    # AM ECHTEN AUFRUF gemessen, nicht am Quelltext: die Zusicherung „der
    # Riegel steht da" waere gruen, auch wenn er nach dem return steht.
    def _server(text):
        class _H(_hs.BaseHTTPRequestHandler):
            def do_POST(self):
                _n = int(self.headers.get("Content-Length") or 0)
                self.rfile.read(_n)
                _b = _json.dumps({"choices": [{"message": {"content": text}}]}).encode()
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(_b)))
                self.end_headers()
                self.wfile.write(_b)
            def log_message(self, *a):
                pass
        srv = _ss.TCPServer(("127.0.0.1", 0), _H)
        _th.Thread(target=srv.serve_forever, daemon=True).start()
        return srv

    # v4.2-W67: _BASES ist None, solange configure() keine Liste gesetzt
    # hat — dann gilt der Katalog, zur Laufzeit gelesen. list(None) knallt.
    _sicherung = (list(F._BASES) if F._BASES is not None else None,
                  F._MODEL, F._TIMEOUT)
    pleite = _server(ECHT)
    frei = _server("Klar, mach ich.")
    try:
        F.configure(bases=[{"url": "http://127.0.0.1:%d/v1" % s.server_address[1],
                            "key": "", "models": ["m"]}
                           for s in (pleite, frei)], model="m", timeout=5)
        txt, err = F.chat_sync([{"role": "user", "content": "hi"}])
        assert txt == "Klar, mach ich.", (
            f"die Rotation erreicht die freie Base nicht — geliefert wurde "
            f"{txt!r}")
        assert err is None, err
        assert "exceeded budget" not in (txt or ""), \
            "die Anbieter-Meldung geht weiter als Antwort raus"

        # Die tote Base ist gesperrt, nicht bloss uebersprungen: sonst faellt
        # jeder naechste Aufruf wieder zuerst auf sie.
        _pleite_url = "http://127.0.0.1:%d/v1" % pleite.server_address[1]
        _st = {z["url"]: z for z in F.bases_status()}
        assert _st[_pleite_url]["blocked_s"] > 0, \
            "die Base mit erschoepftem Budget wird nicht gesperrt"

        # Und der Fehler ist als 'auth' vermerkt — nicht als 'http' oder gar
        # nicht. Der Unterschied entscheidet, ob der Betreiber einen Key
        # nachlaedt oder das Netz debuggt.
        _fehler = F.last_errors()[_pleite_url]
        assert _fehler["kind"] == "auth", _fehler
        # DIE SICHERHEITS-EIGENSCHAFT: im Vermerk steht die Marke, nicht der
        # Text — der traegt die Kennung des Keys.
        assert "89idjaTSg" not in _fehler["detail"], \
            "der Fehlervermerk enthaelt die Key-Kennung aus der Meldung"
        assert "Dienstmeldung" in _fehler["detail"], _fehler
    finally:
        for _s in (pleite, frei):
            _s.shutdown()
            _s.server_close()
        F._BASES, F._MODEL, F._TIMEOUT = _sicherung
    ok("W64: die Rotation erreicht die freie Base, die tote wird gesperrt")

    # --- 4) Der Riegel steht in ALLEN DREI Pfaden ------------------------
    # chat() nimmt der Bot, chat_sync() nimmt brain/llm.py, chat_stream()
    # nimmt die /ai-Route. Ein Riegel an nur einer Stelle laesst genau den
    # anderen Weg die Meldung in den Chat tragen.
    hier = os.path.dirname(os.path.abspath(__file__))
    quelle = open(os.path.join(hier, "nc", "freeai.py"), encoding="utf-8").read()
    for fn in ("async def chat(", "def chat_sync("):
        i = quelle.find(fn)
        assert i > 0, fn
        _e = quelle.find("\ndef ", i + 1)
        _e2 = quelle.find("\nasync def ", i + 1)
        _e = min(x for x in (_e, _e2, len(quelle)) if x > 0)
        assert "dienstmeldung(" in quelle[i:_e], \
            f"{fn.strip()} prueft nicht auf Dienstmeldungen"

    # chat_stream braucht aiohttp und eine Session — in der CI nicht fahrbar.
    # Deshalb liegt sein Rueckhalt als REINE FUNKTION daneben und wird hier
    # Haeppchen fuer Haeppchen durchgespielt.
    #
    # WARUM NICHT WIE OBEN AM QUELLTEXT: genau das war gruen, waehrend die
    # Mutationsprobe den Riegel ausgehebelt hatte — im selben Rumpf stand ein
    # zweiter Aufruf desselben Namens. Vorhandensein statt Eigenschaft, in
    # dieser Reihe zum wiederholten Mal.
    def _stream(text, haeppchen=17):
        """Den Strom stueckweise durchschieben. -> (ausgegeben, abgebrochen)"""
        puffer, geprueft, raus = "", False, []
        for i in range(0, len(text), haeppchen):
            a, puffer, geprueft, ab = F.stream_haeppchen(
                text[i:i + haeppchen], puffer, geprueft)
            if ab:
                return "".join(raus), True
            if a:
                raus.append(a)
        return "".join(raus) + F.stream_rest(puffer, geprueft), False

    # Die Meldung darf in KEINER Stueckelung auch nur teilweise rausgehen.
    # Ein halb ausgegebener Rechnungshinweis laesst sich nicht zurueckholen.
    #
    # ZWEI LAENGEN, und das ist kein Zierrat: die gemeldete Meldung ist
    # kuerzer als der Pruefpuffer und wird deshalb erst im NACHSPIEL erkannt.
    # Mit ihr allein blieb der Riegel MITTEN IM STROM ungetestet — die
    # Mutationsprobe, die ihn entfernt, lief still durch. Die lange Fassung
    # ueberschreitet den Puffer und uebt genau diesen Zweig.
    LANG = ("We are sorry — " * 12) + ECHT
    assert len(LANG) > F._STREAM_PRUEF_ZEICHEN > len(ECHT), (
        "die beiden Pruefsaetze liegen nicht mehr auf verschiedenen Seiten "
        "des Rueckhalts — dann uebt einer von beiden seinen Zweig nicht")

    # Die kurze Meldung faellt im Nachspiel: NICHTS geht raus.
    for _h in (1, 3, 17, 64, 500):
        _aus, _ab = _stream(ECHT, _h)
        assert _aus == "", (
            f"bei {_h}-Zeichen-Haeppchen gehen {len(_aus)} Zeichen der "
            f"Dienstmeldung raus: {_aus[:60]!r}")

    # Die lange mit Vorrede faellt MITTEN IM STROM. Hier ist die harte
    # Zusicherung nicht „nichts geht raus" — das waere gelogen, denn beim
    # Streamen ist die Vorrede schon draussen, bevor die Marke ueberhaupt
    # ankommt. Gefordert ist, was zaehlt: die MELDUNG SELBST geht nie raus,
    # und der Strom bricht ab.
    #
    # Der erste Entwurf pruefte nur einmal am Ende des Rueckhalts und liess
    # genau diesen Fall vollstaendig durch — 180 Zeichen Vorrede genuegten.
    for _h in (1, 3, 17, 64, 500):
        _aus, _ab = _stream(LANG, _h)
        assert _ab, f"bei {_h}-Zeichen-Haeppchen bricht der Strom nicht ab"
        for _marke in ("exceeded budget", "enter.pollinations.ai",
                       "89idjaTSg", "raise the key budget"):
            assert _marke not in _aus, (
                f"bei {_h}-Zeichen-Haeppchen geht {_marke!r} raus: {_aus[-80:]!r}")
        assert not F.dienstmeldung(_aus), \
            f"das Ausgegebene ist selbst eine Dienstmeldung: {_aus[:60]!r}"
    # Eine echte Antwort geht vollstaendig raus — auch die kurze, die den
    # Pruefpuffer nie fuellt.
    for _echt in ("Klar, mach ich.",
                  "Alles ruhig im Chat. " * 30):
        for _h in (1, 17, 500):
            _aus, _ab = _stream(_echt, _h)
            assert not _ab and _aus == _echt, (
                f"echte Antwort verstuemmelt bei {_h}: {_aus[:60]!r}")
    # DIE INVARIANTE, auf der stream_rest ruht: kommt eine Folge ohne
    # Abbruch durch, ist das Gesichtete keine Dienstmeldung. Nur deshalb darf
    # das Nachspiel ungeprueft freigeben. Ohne diesen Vertrag waere die
    # Vereinfachung dort ein blinder Fleck — und eine zweite Pruefung, die
    # per Konstruktion nie zuschlaegt, ist keine Sicherheit, sondern eine
    # Beruhigung (genau das hat die Mutationsprobe gezeigt: sie blieb still).
    for _text in (ECHT, LANG, "Klar.", "Alles ruhig. " * 30,
                  "Rate limit reached for gpt-4o", '{"error": {"code": 1}}'):
        for _h in (1, 7, 200, 5000):
            _g, _o, _abgebrochen = "", False, False
            for _i in range(0, len(_text), _h):
                _a, _g, _o, _ab = F.stream_haeppchen(_text[_i:_i + _h], _g, _o)
                if _ab:
                    _abgebrochen = True
                    break
            if not _abgebrochen:
                assert not F.dienstmeldung(_g), (
                    f"Folge lief ohne Abbruch durch, das Gesichtete ist aber "
                    f"eine Dienstmeldung — stream_rest gaebe sie frei: "
                    f"{_g[:60]!r}")
    ok("W64: was ohne Abbruch durchkommt, ist keine Dienstmeldung mehr")

    # Und der Generator benutzt den Rueckhalt auch. Die Eigenschaft steckt
    # oben im Durchspielen; hier geht es nur um die VERDRAHTUNG — ohne sie
    # waere die schoenste reine Funktion tot (W56).
    i = quelle.find("async def chat_stream(")
    assert i > 0
    _e = quelle.find("\n# ---- sync", i)
    rumpf_stream = quelle[i:_e if _e > 0 else len(quelle)]
    for name in ("stream_haeppchen(", "stream_rest("):
        assert name in rumpf_stream, f"chat_stream benutzt {name} nicht"
    # Kein Delta darf am Rueckhalt vorbei rausgehen.
    assert "yield delta" not in rumpf_stream, \
        "chat_stream gibt ein Delta direkt aus — am Rueckhalt vorbei"
    ok("W64: chat und chat_sync pruefen, und der Stream haelt den Anfang zurueck")

    # --- 5) Der Key geht nur an den Gateway ------------------------------
    # Sonst teilen sich beide Pollinations-Basen EIN Budget und fallen
    # gemeinsam aus — dann gibt es die kostenlose Alternative genau dann
    # nicht, wenn man sie braucht.
    assert 'if "pollinations.ai" in b["url"] and poll_key:' not in quelle, \
        "der Key haengt wieder an BEIDEN Pollinations-Basen"
    assert 'if "gen.pollinations.ai" in b["url"] and poll_key:' in quelle, \
        "der Key erreicht den Gateway nicht mehr"
    _alt = os.environ.get("POLLINATIONS_API_KEY")
    os.environ["POLLINATIONS_API_KEY"] = "test-key-w64"
    try:
        _basen = F._default_bases()
    finally:
        if _alt is None:
            os.environ.pop("POLLINATIONS_API_KEY", None)
        else:
            os.environ["POLLINATIONS_API_KEY"] = _alt
    _poll = [b for b in _basen if "pollinations.ai" in b["url"]]
    assert len(_poll) >= 2, "es gibt keine zwei Pollinations-Basen mehr"
    _ohne = [b for b in _poll if not b.get("key")]
    assert _ohne, ("mit gesetztem Key traegt JEDE Pollinations-Base ihn — "
                   "damit gibt es keine keylose Alternative mehr")
    assert any(b.get("key") for b in _poll), "der Gateway bekommt keinen Key"
    ok("W64: mit Key bleibt eine Pollinations-Base keylos — die Alternative")


def _test_v42_w65_stille_wird_gemessen_und_gesperrt():
    """v4.2-W65: der Hauptfeind, endlich gezaehlt — und das Messgeraet geprueft.

    CLAUDE.md nennt stille except-Bloecke seit Langem „den Hauptfeind".
    Gemessen wurde es nie. Beim Nachzaehlen: 1746 Bloecke, 1086 ohne jede
    Meldung. Jede Welle dieser Reihe kam aus dieser Klasse — W51 (blinder
    Recorder), W55 (taubes Ohr), W60 (Panel weg), W63 (unsichtbare Aufnahme),
    W64 (Rechnung im Chat).

    WARUM DIESER VERTRAG DAS WERKZEUG PRUEFT UND NICHT DEN BESTAND: der
    Klassierer hat sich beim Bauen DREIMAL geirrt, und jedes Mal in die
    gefaehrliche Richtung — er zeigte auf Stellen, an denen nichts zu tun war:

      1. `"log." in ast.dump(...)` findet nie etwas. dump rendert einen
         Attributzugriff als Attribute(value=Name(id='log'), attr='warning').
         Ergebnis: 121 Melder statt 550, der Bestand um Faktor vier zu
         schwarz gezeichnet.
      2. `except asyncio.CancelledError: raise` galt als Stille. Ein Abbruch
         ist kein Ausfall, er wurde angeordnet. Die Zielliste bestand zu drei
         Vierteln aus Nicht-Aufgaben.
      3. Die handgeschriebene Melder-Liste kannte `_verbindung_verloren`
         nicht — den Melder von vier Twitch- und YouTube-Dauerlaeufern.

    Ein Messgeraet, das falsch misst, ist schlimmer als keines: es erzeugt
    Arbeit an den falschen Stellen und Vertrauen an den falschen. Deshalb
    steht hier jeder der drei Irrtuemer als eigene Zusicherung.
    """
    import ast as _ast
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import stillecheck as S

    def _handler(quelltext):
        """Den ersten except-Block aus einem Schnipsel holen."""
        baum = _ast.parse(textwrap.dedent(quelltext))
        for n in _ast.walk(baum):
            if isinstance(n, _ast.Try):
                return n, n.handlers[0]
        raise AssertionError("kein try im Schnipsel")

    # --- 1) Ein Attributzugriff als Melder erkannt ----------------------
    # Der Irrtum, der 429 Melder verschluckte.
    _t, _h = _handler("""
        try:
            riskant()
        except Exception as e:
            log.warning("ging nicht: %s", e)
        """)
    assert S._meldet(_h), \
        "log.warning gilt nicht als Meldung — der Klassierer liest wieder " \
        "ast.dump statt des Syntaxbaums"
    _t, _h = _handler("""
        try:
            riskant()
        except Exception:
            pass
        """)
    assert not S._meldet(_h), "ein blankes pass gilt als Meldung"
    # Weiterwerfen ist auch eine Antwort — nur nach oben.
    _t, _h = _handler("""
        try:
            riskant()
        except Exception:
            raise
        """)
    assert S._meldet(_h), "weiterwerfen gilt nicht als Antwort"
    ok("W65: der Klassierer erkennt Melder ueber den Syntaxbaum")

    # --- 2) Abbruch ist kein Ausfall ------------------------------------
    for typ in ("asyncio.CancelledError", "KeyboardInterrupt", "GeneratorExit"):
        _t, _h = _handler(f"""
            try:
                riskant()
            except {typ}:
                return
            """)
        assert S._ist_ablaufsteuerung(_h), f"{typ} gilt als verschluckter Fehler"
    # Ein blankes except faengt AUCH echte Fehler und ist deshalb NIE
    # Ablaufsteuerung — sonst waere `except: pass` plotzlich in Ordnung.
    _t, _h = _handler("""
        try:
            riskant()
        except:
            pass
        """)
    assert not S._ist_ablaufsteuerung(_h), \
        "ein blankes except gilt als Ablaufsteuerung — damit waere jedes " \
        "'except: pass' entschuldigt"
    # Und eine Mischung faengt echte Fehler mit.
    _t, _h = _handler("""
        try:
            riskant()
        except (asyncio.CancelledError, ValueError):
            pass
        """)
    assert not S._ist_ablaufsteuerung(_h), \
        "ein Tupel MIT echtem Fehlertyp gilt als reine Ablaufsteuerung"
    ok("W65: Abbruch-Signale sind kein Ausfall, ein blankes except schon")

    # --- 3) Melder werden abgeleitet, nicht aufgezaehlt -----------------
    # `_verbindung_verloren` steht in keiner Liste und meldet trotzdem.
    abgeleitet = S._melder_sammeln()
    assert "_verbindung_verloren" in abgeleitet, \
        "der Melder von vier Twitch-/YouTube-Dauerlaeufern wird nicht erkannt"
    assert "_loop_fehler" in abgeleitet, "_loop_fehler gilt nicht als Melder"
    assert len(abgeleitet) > 100, \
        f"nur {len(abgeleitet)} abgeleitete Melder — die Ableitung greift nicht"
    ok("W65: Melder werden aus dem Bestand abgeleitet, nicht geraten")

    # --- 4) Aufraeumpfade bleiben legitim still -------------------------
    # CLAUDE.md nennt sie namentlich. Wuerden sie mitzaehlen, waere die Zahl
    # nicht handhabbar und die Sperre unbrauchbar.
    _t, _h = _handler("""
        try:
            proc.terminate()
        except Exception:
            pass
        """)
    assert S._nur_aufraeumen(_t), "proc.terminate() gilt nicht als Aufraeumen"
    _t, _h = _handler("""
        try:
            conn.execute("INSERT INTO x VALUES (1)")
        except Exception:
            pass
        """)
    assert not S._nur_aufraeumen(_t), \
        "ein INSERT gilt als Aufraeumen — damit waere jeder verschluckte " \
        "Schreibfehler entschuldigt"
    ok("W65: Aufraeumpfade sind legitim still, ein INSERT nicht")

    # --- 5) Die Sperre hat eine Grundlinie und sie passt ----------------
    # Ohne Grundlinie ist die CI-Sperre eine Attrappe; mit einer veralteten
    # meldet sie bei jedem Merge etwas, das laengst behoben ist.
    basis = S._lade_grundlinie()
    assert basis is not None, \
        "keine Grundlinie — die CI-Sperre kann nichts vergleichen"
    stand, gesamt = S.bericht()
    alt = basis.get("stille_bloecke", {})
    gewachsen = {d: (alt.get(d, 0), n) for d, n in stand.items()
                 if n > alt.get(d, 0)}
    assert not gewachsen, f"neue stille except-Bloecke: {gewachsen}"
    assert gesamt["still"] <= basis.get("summe", 0), (
        f"die Summe ist gewachsen: {gesamt['still']} > {basis.get('summe')}")
    ok("W65: die Grundlinie steht, und der Bestand ist nicht gewachsen")

    # --- 5b) Und die SPERRE SELBST faellt auch --------------------------
    # Die Zusicherung oben rechnet selbst nach — sie faehrt nicht den Weg,
    # den die CI faehrt. Die Mutationsprobe, die `gewachsen = []` in main()
    # setzt, lief deshalb still durch: die CI-Sperre waere eine Attrappe
    # gewesen, und der Vertrag daneben gruen. Hier wird main() wirklich
    # aufgerufen, mit einer eigenen Grundlinie in einer temporaeren Datei.
    import contextlib as _ctx
    import json as _json
    import tempfile as _tf

    def _sperre():
        """main() fahren, ohne dass sein Bericht die Testausgabe flutet."""
        with _ctx.redirect_stdout(io.StringIO()):
            return S.main()

    _echt_bericht, _echt_grund, _echt_argv = S.bericht, S.GRUNDLINIE, _sys.argv
    _tmp = _tf.NamedTemporaryFile("w", suffix=".json", delete=False,
                                  encoding="utf-8")
    try:
        _json.dump({"stille_bloecke": {"a.py": 2}, "summe": 2}, _tmp)
        _tmp.close()
        S.GRUNDLINIE = _tmp.name
        # Unveraendert -> 0
        S.bericht = lambda: ({"a.py": 2}, {"still": 2, "laut": 0, "aufraeumen": 0})
        _sys.argv = ["stillecheck.py", "--sperre"]
        assert _sperre() == 0, "die Sperre faellt, obwohl nichts gewachsen ist"
        # Weniger -> 0 (Abbau muss erlaubt sein, sonst friert der Bestand ein)
        S.bericht = lambda: ({"a.py": 1}, {"still": 1, "laut": 0, "aufraeumen": 0})
        assert _sperre() == 0, "die Sperre faellt beim ABBAU stiller Bloecke"
        # Mehr -> 1
        S.bericht = lambda: ({"a.py": 3}, {"still": 3, "laut": 0, "aufraeumen": 0})
        assert _sperre() == 1, \
            "die Sperre laesst einen NEUEN stillen except-Block durch — " \
            "der CI-Job ist dann eine Attrappe"
        # Neue Datei mit stillem Block -> 1
        S.bericht = lambda: ({"a.py": 2, "neu.py": 1},
                             {"still": 3, "laut": 0, "aufraeumen": 0})
        assert _sperre() == 1, "eine NEUE Datei mit stillem Block faellt durch"
        # Ohne Grundlinie -> 1 (sonst waere ein geloeschtes Basisfile gruen)
        S.GRUNDLINIE = _tmp.name + ".gibtsnicht"
        assert _sperre() == 1, \
            "ohne Grundlinie meldet die Sperre OK — dann genuegt es, die " \
            "Basisdatei zu loeschen, um sie loszuwerden"
    finally:
        S.bericht, S.GRUNDLINIE, _sys.argv = _echt_bericht, _echt_grund, _echt_argv
        os.unlink(_tmp.name)
    ok("W65: die Sperre faellt bei Zuwachs und ohne Grundlinie, nicht bei Abbau")

    # --- 6) Und der DDL-Helfer trennt Erwartetes von Echtem -------------
    # Die drei behobenen Faelle haengen daran. Schluckt er zu viel, ist nichts
    # gewonnen; schluckt er zu wenig, faellt der Dienst beim zweiten Start um.
    from nc import ddlsafe as D
    for bekannt in ("index idx_x already exists",
                    "duplicate column name: filepath",
                    "(1061, \"Duplicate key name 'idx_x'\")",
                    "(1060, 'Duplicate column name')"):
        assert D.ist_schon_da(Exception(bekannt)), bekannt
    for echt in ("database is locked", "no such table: ledger",
                 "near \"CRAETE\": syntax error", "disk I/O error"):
        assert not D.ist_schon_da(Exception(echt)), echt

    class _Konn:
        def __init__(self, fehler=None):
            self.fehler, self.laeufe = fehler, 0
        def execute(self, sql):
            self.laeufe += 1
            if self.fehler:
                raise Exception(self.fehler)
    assert D.ddl(_Konn(), "CREATE INDEX x") is True
    assert D.ddl(_Konn("index x already exists"), "CREATE INDEX x") is False
    # OHNE Melder wird ein echter Fehler GEWORFEN, nicht geschluckt. Genau
    # das ist der Punkt: eine Bibliothek ohne Logger soll nicht still
    # danebengreifen.
    try:
        D.ddl(_Konn("database is locked"), "CREATE INDEX x")
    except Exception as e:
        assert "locked" in str(e)
    else:
        raise AssertionError("ein echter Fehler wird ohne Melder geschluckt")
    # MIT Melder wird er gemeldet und der Aufrufer laeuft weiter.
    gemeldet = []
    assert D.ddl(_Konn("database is locked"), "CREATE INDEX x",
                 lambda t, e: gemeldet.append(t)) is False
    assert gemeldet and "DDL" in gemeldet[0], gemeldet
    ok("W65: der DDL-Helfer schluckt nur 'existiert schon', sonst nichts")


def _test_v42_w82_zweitversuch_rotiert_wirklich():
    """v4.2-W82: der Zweitversuch der Live-Aufloesung war eine Attrappe.

    Der Betreiber meldete am 13.09. zusaetzlich: "die Live-Abfragen geben 502
    aus". Beim Nachsehen stand ueber der Schleife in
    `_resolve_via_webcast_api_v2` seit jeher

        # ... Daher: bis zu 2 Versuche, jeweils mit FRISCHEM Proxy ...

    geholt wurde der Proxy aber mit `get_random_proxy()`. Das liefert
    (nc/proxyutil.py, Prioritaet 0) bei gesetztem RECORD_PROXY
    BEDINGUNGSLOS denselben Proxy und bei einer PROXY_LIST ein
    `random.choice`, das denselben erneut ziehen darf.

    Gemessen gegen das echte nc.proxyutil:

        RECORD_PROXY gesetzt   alt: 2x derselbe Proxy, immer
        Pool aus zwei          alt: 196 von 400 Laeufen derselbe
        ohne Proxy             alt: 2x dieselbe Server-IP

    RECORD_PROXY ist ausgerechnet die Einstellung, die gegen 403/502
    empfohlen wird. Dort war jede Live-Pruefung also ZWEI identische
    Anfragen mit 0,5 s Pause — doppelte Last gegen einen Endpunkt, der
    ohnehin schon ablehnt, und eine halbe Sekunde Verzoegerung pro
    verfolgtem Nutzer und Durchlauf.

    Was hier still kaputtgehen kann:
      1. Jemand stellt wieder auf `get_random_proxy()` um — dann ist die
         Rotation weg und niemand merkt es, weil der Code laeuft.
      2. Der Platzhalter fuer die Direktverbindung faellt weg. `None`
         bedeutet "ohne Proxy" und ist ein ECHTER Egress; ohne den
         Platzhalter gilt zweimal direkt faelschlich als Rotation.
      3. Der Zweitversuch laeuft trotzdem, wenn es nichts zu rotieren gibt.
    """
    import ast as _ast
    hier = os.path.dirname(os.path.abspath(__file__))
    quelle = io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    baum = _ast.parse(quelle)
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    fn = oben.get("_resolve_via_webcast_api_v2")
    assert fn is not None, "_resolve_via_webcast_api_v2 ist verschwunden"

    # --- 1) Der Zweitversuch holt ueber _pick_pull_proxy MIT exclude ------
    rufe = [n for n in _ast.walk(fn)
            if isinstance(n, _ast.Call) and isinstance(n.func, _ast.Name)
            and n.func.id == "_pick_pull_proxy"]
    assert rufe, \
        "_resolve_via_webcast_api_v2 ruft _pick_pull_proxy nicht mehr — mit " \
        "get_random_proxy() kann der Zweitversuch nicht rotieren"
    assert any(k.arg == "exclude" for r in rufe for k in r.keywords), \
        "_pick_pull_proxy wird ohne exclude gerufen — dann darf es denselben " \
        "Proxy erneut liefern und der Zweitversuch ist wieder eine Attrappe"

    # --- 2) Die Direktverbindung hat einen Platzhalter --------------------
    assert "_DIREKT" in {n.id for n in _ast.walk(fn)
                         if isinstance(n, _ast.Name)}, \
        "_DIREKT fehlt in der Schleife — ohne Platzhalter zaehlt zweimal " \
        "'ohne Proxy' faelschlich als Rotation"

    # --- 3) Ohne Rotationsmoeglichkeit wird abgebrochen, nicht wiederholt -
    quelle_fn = _ast.get_source_segment(quelle, fn) or ""
    assert "in _versucht" in quelle_fn, \
        "die Pruefung auf einen schon versuchten Egress fehlt — dann laeuft " \
        "der Zweitversuch auch dort, wo er garantiert dasselbe liefert"

    # --- 4) 502 ist ein EIGENER Grund, keine 5xx-Sammelkategorie ----------
    from nc import resolvergrund as _rg
    assert _rg.http_grund(502) == "http_502", \
        "502 faellt wieder in die 5xx-Sammelkategorie. Die sagt 'meist " \
        "transient' — ein dauerhafter 502 ueber alle Nutzer hat aber " \
        "dieselbe Ursache wie ein 403 und braucht dieselbe Abhilfe."
    for code in (500, 503, 504):
        assert _rg.http_grund(code) == "http_5xx", code
    assert "403" in _rg.GRUND["http_502"], \
        "der 502-Text nennt den Zusammenhang mit 403 nicht — genau der ist " \
        "die Handlungsanweisung"

    # --- 5) Die Rotation am ECHTEN nc.proxyutil ---------------------------
    from nc import proxyutil as _P
    _DIREKT_T = "\x00direkt"

    def _stelle(rp, liste):
        # "" statt None: configure_proxy_select liest None als "nicht aendern"
        _P.configure_proxy_select(tunnel={}, record_proxy=rp,
                                  proxy_list=liste, router_getter=lambda: None)

    def _rotiert():
        versucht = {_P.get_random_proxy() or _DIREKT_T}
        zweit = _P._pick_pull_proxy(exclude=versucht)
        return (zweit or _DIREKT_T) not in versucht

    _merker = (_P._TUNNEL, _P._RECORD_PROXY, _P._PROXY_LIST, _P._ROUTER_GET)
    try:
        _stelle("http://fest:pw@proxy:8080", [])
        assert not _rotiert(), \
            "bei festem RECORD_PROXY gibt es nichts zu rotieren — wenn das " \
            "hier True meldet, laeuft der Zweitversuch gegen denselben Egress"
        _stelle("", ["http://p1:8080", "http://p2:8080"])
        assert all(_rotiert() for _ in range(50)), \
            "mit einem Pool aus zwei Proxys muss der Zweitversuch IMMER den " \
            "anderen nehmen"
        _stelle("", [])
        assert not _rotiert(), "ohne Proxy gibt es nichts zu rotieren"
    finally:
        _P._TUNNEL, _P._RECORD_PROXY, _P._PROXY_LIST, _P._ROUTER_GET = _merker


def _test_v42_w81_fehlerpfade_sprechen():
    """v4.2-W81: die stummen Misserfolgs-Rueckgaben der beiden Ketten, die
       der Betreiber am 13.09. als kaputt gemeldet hat.

    Die zwei Meldungen waren:

        "whisper/transkript funktioniert immer noch nicht"
        "Chats koennen von online tiktok Usern geladen werden aber keine
         gueltigen streams"

    Beide Wege scheitern OHNE Absturz — sie kehren ordentlich zurueck, nur
    eben mit leerem Ergebnis. `stillecheck` faellt dort nicht: es gibt
    keinen stillen `except`, sondern ein stilles `return`. Gemessen hatte
    `_resolve_via_webcast_api_v2` elf solche Ausgaenge, acht davon auf
    `log.debug` und drei ganz ohne Zeile; `_whisper_transcribe` verschluckte
    jeden Fehler auf `debug`.

    Ein `log.debug` erscheint in einem INFO- oder ERROR-Log NIE. Fuer den
    Betreiber ist ein Fehlerpfad auf `debug` deshalb dasselbe wie `pass` —
    genau die Klasse, vor der CLAUDE.md warnt.

    WAS HIER SCHIEFGEHEN KANN, ohne dass es jemand merkt:

      1. Jemand hebt die Meldungen auf `warning`, LAESST ABER DIE DROSSEL
         WEG. Der Resolver laeuft pro Poll und pro verfolgtem Nutzer; das
         Log waere nach einer Stunde unlesbar, und eine unlesbare Warnung
         ist so gut wie keine. Die Drossel ist die Voraussetzung dafuer,
         dass die Meldung laut sein DARF.
      2. Jemand drosselt pro NUTZER statt pro Kanal. Bei 200 Trackings
         drosselt das nichts.
      3. Der Erfolgspfad vergisst, die Drossel zurueckzusetzen — dann bleibt
         ein Ausfall, der zwischendurch einmal geklappt hat, bis zu 15
         Minuten stumm.
    """
    import ast as _ast
    hier = os.path.dirname(os.path.abspath(__file__))
    quelle = io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    baum = _ast.parse(quelle)
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    # --- 1) Die beiden Melder existieren und sind reine Kanaele ----------
    for name in ("_resolver_stumm", "_whisper_stumm"):
        fn = oben.get(name)
        assert fn is not None, f"{name} steht nicht auf Modulebene"
        rueck = [n for n in _ast.walk(fn)
                 if isinstance(n, _ast.Return) and n.value is not None]
        assert not rueck, \
            f"{name} liefert ein Ergebnis — dann ist sie Fachlogik und kein " \
            f"Meldekanal, und tools/blindstellen.py darf sie nicht mehr " \
            f"als Meldung anrechnen"

    # --- 2) Sie melden LAUT, nicht auf debug -----------------------------
    for name in ("_resolver_stumm", "_whisper_stumm"):
        fn = oben[name]
        stufen = {n.func.attr for n in _ast.walk(fn)
                  if isinstance(n, _ast.Call)
                  and isinstance(n.func, _ast.Attribute)
                  and isinstance(n.func.value, _ast.Name)
                  and n.func.value.id == "log"}
        assert stufen & {"warning", "error"}, \
            f"{name} meldet nicht auf warning/error (gefunden: {stufen or 'nichts'}) " \
            f"— auf debug ist die Meldung fuer den Betreiber unsichtbar"

    # --- 3) Beide gehen durch die Drossel, mit dem KANAL als Schluessel --
    for name, kanal in (("_resolver_stumm", "resolver"), ("_whisper_stumm", "whisper")):
        fn = oben[name]
        rufe = [n for n in _ast.walk(fn)
                if isinstance(n, _ast.Call)
                and isinstance(n.func, _ast.Attribute)
                and n.func.attr == "melden"]
        assert rufe, f"{name} ruft nc.meldetakt.melden nicht — ungedrosselt " \
                     f"flutet der Kanal das Log"
        erst = rufe[0].args[0] if rufe[0].args else None
        assert isinstance(erst, _ast.Constant) and erst.value == kanal, \
            f"{name} drosselt nicht auf den festen Kanal '{kanal}'. Ein " \
            f"Schluessel je Nutzer drosselt bei 200 Trackings gar nichts."

    # --- 4) Der Erfolgspfad vergisst die Drossel -------------------------
    for fname, kanal in (("_resolve_via_webcast_api_v2", "resolver"),
                         ("resolve_tiktok_live_stream", "resolver"),
                         ("_whisper_transcribe", "whisper"),
                         ("_whisper_segments", "whisper")):
        fn = oben.get(fname)
        assert fn is not None, f"{fname} ist verschwunden"
        resets = [n for n in _ast.walk(fn)
                  if isinstance(n, _ast.Call)
                  and isinstance(n.func, _ast.Attribute)
                  # ANKER GEWANDERT (v4.2-W157): der Resolver-Kanal ruft
                  # `erfolg(kanal, wer)`, das erst leert, wenn kein Nutzer
                  # mehr gestoert ist — die Aussage „Erfolg leert" bleibt.
                  and n.func.attr in ("zuruecksetzen", "erfolg")
                  and n.args and isinstance(n.args[0], _ast.Constant)
                  and n.args[0].value == kanal]
        assert resets, \
            f"{fname} setzt die Drossel '{kanal}' im Erfolgsfall nicht " \
            f"zurueck — ein wiederkehrender Ausfall bliebe bis zu 15 " \
            f"Minuten unsichtbar"

    # --- 5) Der gemeldete Fall hat einen eigenen Grund -------------------
    from nc import resolvergrund as _rg
    assert "beide_wege_leer" in _rg.GRUND, \
        "der Grund 'beide_wege_leer' fehlt — genau das Bild des Betreibers: " \
        "der Chat verbindet sich, aber keine Aufloesung liefert eine Adresse"
    assert "RECORD_PROXY" in _rg.GRUND["beide_wege_leer"], \
        "der Grund nennt die Abhilfe nicht. 'keine URL' allein hat schon " \
        "einmal wochenlang niemandem geholfen."
    assert _rg.text("gibtsnicht") == "gibtsnicht", \
        "ein unbekannter Grund muss im Log sichtbar bleiben statt zu " \
        "verschwinden — sonst faellt eine neue Kategorie niemandem auf"

    # --- 6) Die Drossel selbst haelt ihre Regel --------------------------
    from nc import meldetakt as _mt
    _mt.zuruecksetzen()
    assert _mt.melden("t", "a", 0.0) == (True, 0), "erste Meldung muss laut sein"
    assert _mt.melden("t", "a", 1.0) == (False, 1), "Wiederholung muss still sein"
    assert _mt.melden("t", "b", 2.0) == (True, 1), \
        "ein WECHSEL des Grundes muss sofort melden — dass sich das " \
        "Fehlerbild geaendert hat, ist die eigentliche Nachricht"
    assert _mt.melden("t", "b", 2.0 + _mt.ABSTAND_S) == (True, 0), \
        "nach Ablauf des Fensters muss wieder gemeldet werden"
    _mt.zuruecksetzen()


def _test_v42_w80_notbremse_heraus():
    """v4.2-W80: die B54-Notbremse heraus — der Schnitt mit await und DB.

    Vierter und letzter der geplanten Schnitte am Aufnahmeschluss:

        616 Z / 141 Zweige   vor W78
        455 Z / 113 Zweige   jetzt

    Dieser Block ist anders als die drei davor. Er WARTET (zwei await) und
    er SCHREIBT IN DIE DATENBANK — er schaltet ein Tracking ab, wenn der
    Stream AUTO_DISABLE_STREAK-mal in Folge tot war. Deshalb bekam er eine
    eigene Welle statt mitzufahren.

    DIE GEFAHR BEI GENAU DIESEM UMZUG ist ein vergessenes `await` an der
    Aufrufstelle. Der Aufruf liefert dann eine Koroutine, die nie laeuft: das
    Tracking bleibt an, die Notbremse greift nie, und zu sehen ist
    hoechstens eine RuntimeWarning, die zwischen allem anderen untergeht.
    Weder py_compile noch pyflakes melden das. Deshalb steht die Pruefung
    darauf hier ausdruecklich.
    """
    import ast as _ast
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import monolith as M

    baum = _ast.parse(io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read())
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    lauf = oben.get("handle_recording_finished")
    assert lauf is not None, "handle_recording_finished ist verschwunden"

    # --- 1) Sie ist heraus und async geblieben ---------------------------
    k = oben.get("_rec_auto_abschalten")
    assert k is not None, "_rec_auto_abschalten steht nicht auf Modulebene"
    assert isinstance(k, _ast.AsyncFunctionDef), \
        "_rec_auto_abschalten ist nicht mehr async — sie wartet auf die " \
        "Datenbank und auf Telegram, das geht nicht synchron"

    # --- 2) …und wird AWAITED aufgerufen, nicht bloss aufgerufen ---------
    # Das ist die eigentliche Zusicherung dieser Welle.
    awaited = {_ast.unparse(x.value.func) for x in _ast.walk(lauf)
               if isinstance(x, _ast.Await) and isinstance(x.value, _ast.Call)}
    nur_gerufen = {_ast.unparse(x.func) for x in _ast.walk(lauf)
                   if isinstance(x, _ast.Call)}
    assert "_rec_auto_abschalten" in nur_gerufen, \
        "_rec_auto_abschalten wird gar nicht mehr aufgerufen — die Notbremse " \
        "greift dann nie, und ein toter Stream startet weiter alle 30 Minuten " \
        "ein ffmpeg (genau der Fall aus B54)"
    assert "_rec_auto_abschalten" in awaited, \
        "_rec_auto_abschalten wird OHNE await aufgerufen — der Aufruf liefert " \
        "eine Koroutine, die nie laeuft. Das Tracking bleibt an, und zu sehen " \
        "ist hoechstens eine RuntimeWarning im Log"

    # --- 3) Die Absicherung gegen das Wettrennen steht im WHERE ----------
    # v4.1-W29: nicht der Loop schuetzt, sondern die Bedingung der Anweisung.
    # Faellt sie weg, kann eine zweite Aufnahme denselben Eintrag ein zweites
    # Mal abschalten und den Grund ueberschreiben.
    rumpf = _ast.unparse(k)
    assert "COALESCE(auto_disabled_at, '') = ''" in rumpf, \
        "die WHERE-Bedingung gegen das doppelte Abschalten fehlt — dann " \
        "ueberschreibt ein zweiter Lauf Zeitpunkt und Grund"
    assert "paused = 1" in rumpf, "die Notbremse pausiert das Tracking nicht mehr"

    # --- 4) Die Register werden geleert, nicht neu gebunden --------------
    neu_gebunden = {t.id for x in _ast.walk(k) if isinstance(x, _ast.Assign)
                    for t in x.targets if isinstance(t, _ast.Name)}
    for reg in ("_STREAM_DEAD_STREAK", "_STREAM_DEAD_BACKOFF_UNTIL",
                "_PENDING_OFFLINE_COUNT", "_NEXT_CHECK_AT"):
        assert reg not in neu_gebunden, "%s wird NEU GEBUNDEN" % reg
        assert reg in rumpf, \
            "%s wird nach dem Abschalten nicht mehr geleert — der Zustand " \
            "des abgeschalteten Trackings bliebe im Speicher stehen" % reg

    # --- 5) Und der Operator wird weiterhin laut benachrichtigt ----------
    assert "disable_notification=False" in rumpf, \
        "die Benachrichtigung ist wieder still — das Abschalten eines " \
        "Trackings ist genau der Fall, den der Betreiber mitbekommen muss"

    treffer = [f for f in M.funktionen()
               if f[0] == "bot.py" and f[1] == "handle_recording_finished"]
    zeilen, zweige = treffer[0][3], treffer[0][4]
    assert zeilen <= 470 and zweige <= 116, \
        "handle_recording_finished ist auf %d Z / %d Zweige zurueckgewachsen" % (
            zeilen, zweige)
    ok("W80: die Notbremse ist heraus und wird awaited, %d Z / %d Zweige "
       "(vor W78: 616/141)" % (zeilen, zweige))


def _test_v42_w79_frueher_abriss_heraus():
    """v4.2-W79: dritter Schnitt am Aufnahmeschluss — der fruehe Abriss.

    35 Zeilen: Auto-Retry mit wachsender Pause nach einem fruehen Abriss,
    oder Zaehler zurueck, wenn die Aufnahme 30 Sekunden oder laenger lief.

    DASS DER BLOCK FOLGENLOS IST, WURDE ERNEUT GEMESSEN und nicht aus W78
    uebernommen. Vor W78 galten seine beiden Namen `_f` und `count` als
    „spaeter gelesen" — weil die damals noch vorhandenen Bloecke denselben
    Kurznamen benutzten. Erst seit die heraus sind, ist dieser Block wirklich
    in sich geschlossen. Eine Freigabe von letzter Woche gilt hier nicht.

    _EARLY_DISCONNECT_RETRY und _NEXT_CHECK_AT bleiben DIESELBEN Objekte:
    das Faellig-Stellen ist der Takt des Workers, und ein zweites Woerterbuch
    hiesse, dass der Worker eine andere Wartezeit sieht als die gesetzte.
    """
    import ast as _ast
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import monolith as M

    baum = _ast.parse(io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read())
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    lauf = oben.get("handle_recording_finished")
    assert lauf is not None, "handle_recording_finished ist verschwunden"

    # --- 1) Heraus, auf Modulebene, und wirklich gerufen -----------------
    assert "_rec_frueh_getrennt" in oben, \
        "_rec_frueh_getrennt steht nicht mehr auf Modulebene"
    gerufen = {_ast.unparse(x.func) for x in _ast.walk(lauf)
               if isinstance(x, _ast.Call)}
    assert "_rec_frueh_getrennt" in gerufen, \
        "_rec_frueh_getrennt wird nicht mehr aufgerufen — nach einem fruehen " \
        "Abriss gaebe es dann keinen Auto-Retry mehr, und zwar lautlos"

    # --- 2) Folgenlos wie die beiden aus W78 -----------------------------
    k = oben["_rec_frueh_getrennt"]
    assert not isinstance(k, _ast.AsyncFunctionDef), \
        "_rec_frueh_getrennt ist async geworden — dann wartet der " \
        "Aufnahmeschluss darauf"
    assert not any(isinstance(x, _ast.Await) for x in _ast.walk(k)), \
        "_rec_frueh_getrennt enthaelt ein await"
    assert not [x for x in _ast.walk(k)
                if isinstance(x, _ast.Return) and x.value is not None], \
        "_rec_frueh_getrennt gibt etwas zurueck — der Aufrufer wertet nichts " \
        "aus, das Ergebnis ginge lautlos verloren"

    # --- 3) Die Register werden fortgeschrieben, nicht neu gebunden ------
    neu_gebunden = {t.id for x in _ast.walk(k) if isinstance(x, _ast.Assign)
                    for t in x.targets if isinstance(t, _ast.Name)}
    for reg in ("_EARLY_DISCONNECT_RETRY", "_NEXT_CHECK_AT"):
        assert reg not in neu_gebunden, \
            "%s wird NEU GEBUNDEN — dann setzt der Aufnahmeschluss eine " \
            "Wartezeit, die der Worker nie sieht" % reg
        assert reg in _ast.unparse(k), "%s wird gar nicht mehr benutzt" % reg
    # Und der Zaehler wird beim langen Lauf wirklich zurueckgesetzt — sonst
    # bekaeme der naechste fruehe Abriss unnoetig lange Pausen (B12).
    assert "_EARLY_DISCONNECT_RETRY.pop(tid, None)" in _ast.unparse(k), \
        "der Zaehler wird nach einer Aufnahme ab 30s nicht mehr " \
        "zurueckgesetzt — dann waechst die Pause immer weiter (B12)"

    # --- 4) Der Auto-Abschalt-Block kam in EIGENER Welle heraus (W80) ----
    _aw = {_ast.unparse(x.value.func) for x in _ast.walk(lauf)
           if isinstance(x, _ast.Await) and isinstance(x.value, _ast.Call)}
    assert "_rec_auto_abschalten" in _aw, \
        "die Notbremse wird nicht mehr awaited gerufen — siehe W80"

    # --- 5) Die Funktion schrumpft weiter --------------------------------
    treffer = [f for f in M.funktionen()
               if f[0] == "bot.py" and f[1] == "handle_recording_finished"]
    zeilen, zweige = treffer[0][3], treffer[0][4]
    assert zeilen <= 520 and zweige <= 122, \
        "handle_recording_finished ist auf %d Z / %d Zweige zurueckgewachsen" % (
            zeilen, zweige)
    ok("W79: der fruehe Abriss ist heraus, %d Z / %d Zweige (vor W78: 616/141)"
       % (zeilen, zweige))


def _test_v42_w78_aufnahmeschluss_erste_schnitte():
    """v4.2-W78: erste Schnitte an handle_recording_finished.

    616 Zeilen, 141 Verzweigungen — nach _discord_run_once die verzweigtste
    Funktion des Bestands, und die heikelste: ein Fehler zeigt sich nicht beim
    Neustart, sondern mitten in einer laufenden Aufnahme.

    Deshalb wurde nicht der groesste Block zuerst genommen, sondern der
    FOLGENLOSESTE. Beide herausgeloesten Stuecke haben nachgemessen keine
    Wirkung auf den Aufrufer: kein Rueckgabewert, kein await, und der einzige
    Name, den sie schreiben (`_f`), wird von jedem spaeteren Block neu belegt,
    bevor er ihn liest. Das war nicht selbstverstaendlich — die erste Messung
    meldete `_f` als „spaeter gelesen", und erst das Nachsehen zeigte, dass
    jeder Leser eine eigene Zuweisung davor hat.

    Was ausdruecklich NICHT herausging: der Auto-Abschalt-Block. Er hat ein
    await und schreibt in die Datenbank — der gehoert in eine eigene Welle mit
    eigener Beobachtung.
    """
    import ast as _ast
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import monolith as M

    src = io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    baum = _ast.parse(src)
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    # --- 1) Die beiden Stuecke stehen auf Modulebene und werden gerufen ---
    # Der Aufruf wird ueber den AST im RUMPF von handle_recording_finished
    # gesucht, nicht als Textstueck in der Datei. Der erste Entwurf pruefte
    # `"_rec_kategorie_melden(category, username)" in src` — und das steht
    # auch in der DEFINITION `def _rec_kategorie_melden(category, username):`.
    # Die Zusicherung war damit erfuellt, sobald die Funktion existierte, und
    # beide Mutationen „Aufruf geloescht" blieben still.
    _lauf = oben.get("handle_recording_finished")
    assert _lauf is not None, "handle_recording_finished ist verschwunden"
    _gerufen = {_ast.unparse(x.func) for x in _ast.walk(_lauf)
                if isinstance(x, _ast.Call)}
    for name in ("_rec_kategorie_melden", "_rec_totstreak_fortschreiben"):
        assert name in oben, "%s steht nicht mehr auf Modulebene" % name
        assert name in _gerufen, \
            "%s wird von handle_recording_finished nicht mehr aufgerufen — " \
            "der Block ist damit still verschwunden, und weder py_compile " \
            "noch pyflakes merken das" % name

    # --- 2) Sie bleiben folgenlos ----------------------------------------
    # Genau das war die Bedingung, unter der sie herausgehen durften. Kommt
    # ein return oder ein await dazu, ist die Begruendung hinfaellig und der
    # Schnitt gehoert neu geprueft.
    for name in ("_rec_kategorie_melden", "_rec_totstreak_fortschreiben"):
        k = oben[name]
        assert not isinstance(k, _ast.AsyncFunctionDef), \
            "%s ist async geworden — dann wartet der Aufnahmeschluss darauf" % name
        assert not any(isinstance(x, _ast.Await) for x in _ast.walk(k)), \
            "%s enthaelt ein await" % name
        rueck = [x for x in _ast.walk(k)
                 if isinstance(x, _ast.Return) and x.value is not None]
        assert not rueck, \
            "%s gibt etwas zurueck — der Aufrufer wertet nichts aus, also " \
            "ginge das Ergebnis lautlos verloren" % name

    # --- 3) Die Register bleiben DIESELBEN Objekte -----------------------
    # Sie werden fortgeschrieben, nie neu gebunden. Nur deshalb sieht das
    # Brain-Panel denselben Stand wie der Worker.
    k = oben["_rec_totstreak_fortschreiben"]
    neu_gebunden = {t.id for x in _ast.walk(k) if isinstance(x, _ast.Assign)
                    for t in x.targets if isinstance(t, _ast.Name)}
    for reg in ("_STREAM_DEAD_STREAK", "_STREAM_DEAD_BACKOFF_UNTIL", "_NEXT_CHECK_AT"):
        assert reg not in neu_gebunden, \
            "%s wird in _rec_totstreak_fortschreiben NEU GEBUNDEN — dann " \
            "schreibt die Aufnahme in ein anderes Objekt als das, welches " \
            "das Brain-Panel liest" % reg
        assert reg in _ast.unparse(k), \
            "%s wird gar nicht mehr fortgeschrieben" % reg

    # --- 4) Der Auto-Abschalt-Block kam in EIGENER Welle heraus ----------
    # Diese Zusicherung verlangte bis v4.2-W80, dass er DRIN bleibt — damit
    # ihn niemand nebenbei mitnimmt. W80 hat ihn dann als eigene Welle
    # herausgeloest, mit eigener Pruefung auf das `await` an der
    # Aufrufstelle. Sie verlangt jetzt das Gegenstueck: er steht in seiner
    # eigenen Funktion, und die wird awaited.
    lauf = oben.get("handle_recording_finished")
    assert lauf is not None, "handle_recording_finished ist verschwunden"
    _aw = {_ast.unparse(x.value.func) for x in _ast.walk(lauf)
           if isinstance(x, _ast.Await) and isinstance(x.value, _ast.Call)}
    assert "_rec_auto_abschalten" in _aw, \
        "die Notbremse wird nicht mehr awaited aus handle_recording_finished " \
        "gerufen — siehe den Vertrag zu W80"

    # --- 5) Und die Funktion ist wirklich kleiner geworden ---------------
    treffer = [f for f in M.funktionen()
               if f[0] == "bot.py" and f[1] == "handle_recording_finished"]
    assert treffer, "handle_recording_finished wird nicht mehr gemessen"
    zeilen, zweige = treffer[0][3], treffer[0][4]
    assert zeilen <= 560, \
        "handle_recording_finished ist mit %d Zeilen wieder ueber 560" % zeilen
    assert zweige <= 130, \
        "handle_recording_finished hat wieder %d Verzweigungen (vor W78: 141)" % zweige
    ok("W78: zwei folgenlose Bloecke heraus, %d Z / %d Zweige (vorher 616/141)"
       % (zeilen, zweige))


def _test_v42_w77_schleifen_folgen_dem_aktuellen_client():
    """v4.2-W77: die Dauerlaeufer hielten den Client der ERSTEN Sitzung fest.

    Das ist die erste Welle dieser Reihe mit einer echten
    VERHALTENSAENDERUNG, und sie steht hier, damit niemand sie fuer eine
    Verschiebung haelt.

    B120 startet die Hintergrund-Schleifen (Liveboard, Wochen-Digest, Clip der
    Woche) EINMALIG ueber alle Sitzungen hinweg — sonst liefen nach n
    Reconnects n parallele Schleifen. Der Guard dafuer wurde damals von einem
    Objekt-Attribut auf ein Modul-Global gezogen. Die Client-Referenz IN den
    Schleifen blieb aber eine Closure-Variable und zeigte damit weiter auf den
    Client der ersten Sitzung.

    Nach einem Reconnect ist das ein totes Objekt: discord.Client.close() ruft
    self.http.close(), und jeder Aufruf darueber scheitert. Die Schleifen
    liefen also weiter und griffen ins Leere — derselbe Fehler, den B120 fuer
    den Guard behoben und fuer die Referenz stehen gelassen hat.

    nc.discordstate.CLIENT ist genau dafuer da und sagt es im eigenen
    Docstring: „Register statt Modul-Global, weil der Bot ihn NEU BINDET".
    """
    import ast as _ast
    hier = os.path.dirname(os.path.abspath(__file__))
    src = io.open(os.path.join(hier, "discordbot.py"), encoding="utf-8").read()
    baum = _ast.parse(src)
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    # --- 1) Die Dauerlaeufer holen den Client ueber das Register ---------
    LAEUFER = ("_update_liveboard", "_liveboard_loop", "_post_weekly_digest",
               "_weekly_digest_loop", "_clip_week_leader",
               "_post_clip_of_week", "_clipoftheweek_loop")
    for n in LAEUFER:
        assert n in oben, "%s steht nicht mehr auf Modulebene" % n
        rumpf = _ast.unparse(oben[n])
        assert "_dc_client()" in rumpf or "_dc_offen()" in rumpf, \
            "%s holt den Client nicht mehr ueber das Register — nach einem " \
            "Reconnect spricht es dann wieder den toten Client der ersten " \
            "Sitzung an" % n

    # --- 2) Das Register liefert wirklich den aktuellen Client -----------
    import nc.discordstate as DS
    import discordbot as DB
    _alt = DS.CLIENT["obj"]
    try:
        DS.CLIENT["obj"] = "ERSTER"
        assert DB._dc_client() == "ERSTER", DB._dc_client()
        DS.CLIENT["obj"] = "ZWEITER"          # so wirkt ein Reconnect
        assert DB._dc_client() == "ZWEITER", \
            "_dc_client() liefert nach dem Neubinden noch den alten Client — " \
            "genau der Fehler, den diese Welle behebt"
        DS.CLIENT["obj"] = None
        assert DB._dc_client() is None
    finally:
        DS.CLIENT["obj"] = _alt

    # --- 3) Die Schleifenbedingung haelt None aus ------------------------
    # `_dc_client().is_closed()` waere ein AttributeError, sobald der
    # Supervisor beim Aufraeumen CLIENT["obj"] = None setzt — in einer
    # Endlosschleife, die niemand beobachtet. Der erste Entwurf hatte genau
    # das.
    try:
        DS.CLIENT["obj"] = None
        assert DB._dc_offen() is False, \
            "_dc_offen() meldet bei fehlendem Client nicht False"

        class _Zu:
            def is_closed(self):
                return True

        class _Offen:
            def is_closed(self):
                return False

        DS.CLIENT["obj"] = _Zu()
        assert DB._dc_offen() is False, "ein geschlossener Client gilt als offen"
        DS.CLIENT["obj"] = _Offen()
        assert DB._dc_offen() is True, "ein offener Client gilt als geschlossen"
    finally:
        DS.CLIENT["obj"] = _alt
    assert "while _dc_offen():" in src, \
        "die Dauerschleifen pruefen nicht mehr ueber _dc_offen() — dann " \
        "steht dort wieder ein Aufruf, der auf None knallt"
    ok("W77: die Dauerlaeufer folgen dem aktuellen Client und ueberleben None")

    # --- 4) Der Sitzungszustand behaelt seine Lebensdauer ----------------
    # Er steht jetzt auf Modulebene, wird aber je Sitzung zurueckgesetzt.
    # Ohne das Zuruecksetzen ueberlebten Cooldowns einen Reconnect: ein
    # Nutzer, der vorher XP bekam, bekaeme danach 60 Sekunden lang keine.
    lauf = oben.get("_discord_run_once")
    assert lauf is not None, "_discord_run_once ist verschwunden"
    rumpf = _ast.unparse(lauf)
    for zeile in ("_disc_clip_last.clear()", "_xp_cool.clear()",
                  "_dc_ai_last['ts'] = 0.0", "_dc_reply_last['ts'] = 0.0",
                  "_dc_ai_sema['obj'] = asyncio.Semaphore(2)"):
        assert zeile in rumpf, \
            "_discord_run_once setzt %r nicht mehr zurueck — der " \
            "Zwischenspeicher ueberlebt dann einen Reconnect, und das ist " \
            "eine andere Wirkung als vorher" % zeile

    # --- 5) `= None` bleibt fuer Kontext-Platzhalter reserviert ----------
    # Der Vertrag aus W15 liest jede Modul-Zuweisung auf None als Platzhalter,
    # den _uebernehmen(ctx) belegen muss. Der erste Entwurf dieser Welle hat
    # `_dc_ai_sema = None` geschrieben und wurde prompt gemeldet.
    for name in ("_dc_ai_sema", "_dc_ai_last", "_dc_reply_last",
                 "_xp_cool", "_disc_clip_last"):
        zuw = [n for n in baum.body if isinstance(n, _ast.Assign)
               and any(isinstance(t, _ast.Name) and t.id == name for t in n.targets)]
        assert zuw, "%s steht nicht mehr auf Modulebene" % name
        wert = zuw[0].value
        assert not (isinstance(wert, _ast.Constant) and wert.value is None), \
            "%s ist auf None gesetzt — in dieser Datei ist das die Marke " \
            "fuer einen Kontext-Platzhalter, und _uebernehmen(ctx) muesste " \
            "ihn belegen" % name
    ok("W77: Sitzungszustand wird je Sitzung geleert und ist kein Platzhalter")


def _test_v42_w75_main_ohne_bridge_verdrahtung():
    """v4.2-W75: main() war zur Haelfte Brain-Bridge-Verdrahtung.

    504 Zeilen, 135 Verzweigungen — nach der Rangliste aus W74 der dritte
    Platz. Ein einziger try-Block machte 245 davon aus: acht Rueckrufe fuer
    den Router (Momentaufnahmen zu Restream-Gesundheit, Moderation, Aufnahmen,
    TikTok-Status; dazu drei Stellhebel), gefolgt von init_bridge(...).

    Zehn dieser Rueckrufe brauchten von main KEINE einzige Variable. Nur
    `_on_signal` haengt echt an `stop_evt` und bleibt deshalb drin.

    DIE SCHATTENPRUEFUNG WAR ZUERST EIN FEHLALARM, und das gehoert
    festgehalten: sie meldete `live` als Local von main, das einen
    Modul-Namen ueberdeckt — was den Umzug verboten haette. Tatsaechlich
    steht `live = {}` INNERHALB von _brain_restream_health. Der Fehler lag im
    Messskript: `ast.walk` steigt trotz `continue` in innere Funktionsruempfe
    hinab, ein `continue` ueberspringt nur den Knoten, nicht seinen Unterbaum.
    Mit kontrolliertem Abstieg: 38 echte Locals, null Schatten.

    Nach dem Umzug: 293 Zeilen, 59 Verzweigungen. Der ausfuehrbare Teil aller
    zehn ist unveraendert; geaendert hat sich allein der Roh-Leerraum einer
    Docstring-Fortsetzungszeile, die beim Ausruecken mitging.
    """
    import ast as _ast
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import monolith as M

    src = io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    baum = _ast.parse(src)
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    # --- 1) Die zehn stehen auf Modulebene ------------------------------
    GEHOBEN = ("_async_exc_handler", "_v37_restream_restart",
               "_v37_unpause_source", "_v37_pause_source",
               "_brain_crowdsec_snap", "_brain_restream_health",
               "_brain_moderation_snap", "_brain_recording_snap",
               "_brain_tiktok_status_snap", "_kickmod_boot")
    for n in GEHOBEN:
        assert n in oben, \
            "%s ist wieder in main gewandert — dort ist es weder einzeln " \
            "lesbar noch prueft pyflakes seine Namen gegen die Modulebene" % n

    # --- 2) …und werden von main auch benutzt ---------------------------
    # Ein gehobener Rueckruf, den niemand mehr uebergibt, ist schlimmer als
    # einer in der Closure: die Bridge liefe dann ohne ihn weiter und meldete
    # stillschweigend leere Momentaufnahmen.
    mainf = oben.get("main")
    assert mainf is not None, "main ist verschwunden"
    rumpf = _ast.unparse(mainf)
    for n in GEHOBEN:
        if n == "_async_exc_handler":
            continue          # wird an den Loop gehaengt, nicht an die Bridge
        assert n in rumpf, \
            "main reicht %s nirgends mehr weiter — die Brain-Bridge bekommt " \
            "dann eine Momentaufnahme weniger, ohne dass etwas meldet" % n

    # --- 3) main ist wirklich kleiner UND flacher ------------------------
    treffer = [f for f in M.funktionen()
               if f[0] == "bot.py" and f[1] == "main"]
    assert treffer, "main wird nicht mehr gemessen"
    zeilen, zweige = treffer[0][3], treffer[0][4]
    assert zeilen <= 340, \
        "main ist mit %d Zeilen wieder ueber 340 — der Schnitt ist zu" % zeilen
    assert zweige <= 75, \
        "main hat wieder %d Verzweigungen (vor W75: 135) — die Verdrahtung " \
        "ist zurueckgewandert" % zweige
    ok("W75: zehn Rueckrufe heraus, main von 504/135 auf %d/%d" % (zeilen, zweige))

    # --- 4) Die Schattenpruefung, diesmal mit kontrolliertem Abstieg -----
    # Der Fehlalarm von oben darf nicht zurueckkommen: wer `ast.walk` nimmt,
    # zaehlt Locals innerer Funktionen der aeusseren zu.
    def bindungen(knoten):
        aus = set()

        def geh(n):
            for kind in _ast.iter_child_nodes(n):
                if isinstance(kind, (_ast.FunctionDef, _ast.AsyncFunctionDef,
                                     _ast.ClassDef, _ast.Lambda)):
                    if hasattr(kind, "name"):
                        aus.add(kind.name)
                    continue          # Rumpf NICHT betreten
                if isinstance(kind, _ast.Name) and isinstance(kind.ctx, _ast.Store):
                    aus.add(kind.id)
                geh(kind)

        geh(knoten)
        return aus

    lok = bindungen(mainf)
    assert "live" not in lok, \
        "'live' gilt wieder als Local von main — dann zaehlt das Messskript " \
        "Bindungen innerer Funktionen mit, und der naechste Umzug wird aus " \
        "einem Fehlalarm heraus abgelehnt"
    innere = [k for k in _ast.walk(mainf)
              if isinstance(k, (_ast.FunctionDef, _ast.AsyncFunctionDef))
              and k is not mainf]
    assert any(k.name == "_on_signal" for k in innere), \
        "_on_signal ist nicht mehr in main — es haengt echt an stop_evt und " \
        "gehoert dorthin"
    ok("W75: 'live' ist ein Local von _brain_restream_health, kein Schatten")


def _test_v42_w74_verzweigung_statt_nur_laenge():
    """v4.2-W74: das Mass aus W70 zeigte aufs falsche Ziel.

    tools/monolith.py rankte nach ZEILEN. Ganz oben stand damit
    nc/schema.py:create_schema mit 718 Zeilen — und ausgerechnet das ist die
    einfachste Funktion des Bestands:

        718 Z   18 Zweige   40.0 Z/Zw   nc/schema.py:create_schema
        716 Z  204 Zweige    3.5 Z/Zw   discordbot.py:_discord_run_once
        616 Z  141 Zweige    4.4 Z/Zw   bot.py:handle_recording_finished

    Eine Verzweigung je 40 Zeilen gegen eine je 3 bis 5. create_schema ist
    eine LISTE aus 42 CREATE TABLE — 82 der 88 Anweisungen sind ein schlichtes
    conn.execute(...). Sie zu zerlegen waere Kosmetik gewesen, und zwar an
    Schema-Code, der gegen die Produktionsdatenbank laeuft. Ausserdem haette
    es die Regel gebrochen, die sich der Bestand selbst gegeben hat: der
    Modul-Docstring haelt fest, dass beim Umzug aus bot.py KEINE Schema-Zeile
    geaendert wurde.

    Das Werkzeug misst deshalb jetzt beide Achsen. Die Zeilen-Stufen bleiben —
    Laenge ist ein echtes Signal —, aber die Rangliste fuehrt die
    Verzweigungen an, weil das die Liste ist, an der man arbeiten sollte.
    """
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import monolith as M

    # --- 1) Beide Achsen werden gemessen ---------------------------------
    alle = M.funktionen()
    assert alle and len(alle[0]) == 5, \
        "funktionen() liefert keine Verzweigungszahl mehr — dann rankt das " \
        "Werkzeug wieder nur nach Laenge"
    zahlen = M.bericht()
    for s in M.STUFEN:
        assert str(s) in zahlen, "die Zeilen-Stufe %s fehlt" % s
    for s in M.ZWEIG_STUFEN:
        assert ("zw%d" % s) in zahlen, "die Verzweigungs-Stufe %s fehlt" % s

    # --- 2) Der Befund selbst: lang ist nicht gleich schwer --------------
    def hole(datei, name):
        t = [f for f in alle if f[0] == datei and f[1] == name]
        assert t, "%s:%s nicht gefunden" % (datei, name)
        return t[0]

    schema = hole("nc/schema.py", "create_schema")
    discord = hole("discordbot.py", "_discord_run_once")
    assert schema[3] > 600, \
        "create_schema ist nicht mehr lang — dann ist der Befund neu zu erheben"
    assert schema[4] < 40, \
        "create_schema hat jetzt %d Verzweigungen — es ist keine reine " \
        "Deklarationsliste mehr, und die Entscheidung, sie NICHT zu " \
        "zerlegen, gehoert neu geprueft statt geerbt" % schema[4]
    assert discord[4] > schema[4] * 3, \
        "der Abstand zwischen Deklarationsliste und Geflecht ist " \
        "eingeebnet (%d gegen %d Zweige) — die Begruendung dieser Welle " \
        "stimmt dann nicht mehr" % (discord[4], schema[4])

    # --- 3) Die Zaehlung von Verzweigungen stimmt ------------------------
    # Nicht am Bestand nachgerechnet, sondern an einem Fall mit bekannter
    # Antwort: sonst prueft der Vertrag nur, dass zwei Aufrufe dasselbe
    # liefern.
    import ast as _ast
    flach = _ast.parse("def f():\n" + "    x = 1\n" * 40).body[0]
    assert M.zweige(flach) == 0, \
        "eine Funktion ohne jede Verzweigung wird mit %d gezaehlt" % M.zweige(flach)
    verzweigt = _ast.parse(
        "def f(a):\n"
        "    if a:\n"
        "        pass\n"
        "    for i in a:\n"
        "        pass\n"
        "    try:\n"
        "        pass\n"
        "    except ValueError:\n"
        "        pass\n"
        "    return [x for x in a if x]\n").body[0]
    # if + for + try + except + comprehension + das if IN der Komprehension
    assert M.zweige(verzweigt) >= 5, \
        "if/for/try/except/Komprehension ergeben nur %d Verzweigungen" % M.zweige(verzweigt)
    ok("W74: das Mass sieht Verzweigungen, nicht nur Zeilen")

    # --- 4) Und die Sperre faellt auf BEIDEN Achsen ----------------------
    import contextlib as _ctx
    import json as _json
    import tempfile as _tf
    _echt_b, _echt_g = M.bericht, M.GRUNDLINIE

    def _sperre():
        with _ctx.redirect_stdout(io.StringIO()):
            return M.main(["--sperre"])

    _basis = {"100": 63, "200": 16, "300": 9, "500": 4,
              "zw50": 22, "zw100": 3, "zw150": 1}
    _tmp = _tf.NamedTemporaryFile("w", suffix=".json", delete=False, encoding="utf-8")
    try:
        _json.dump({"stufen": dict(_basis)}, _tmp)
        _tmp.close()
        M.GRUNDLINIE = _tmp.name
        M.bericht = lambda: dict(_basis)
        assert _sperre() == 0, "die Sperre faellt, obwohl nichts dazukam"
        M.bericht = lambda: dict(_basis, **{"500": 5})
        assert _sperre() == 1, "eine neue Funktion ueber 500 Zeilen kommt durch"
        M.bericht = lambda: dict(_basis, **{"zw50": 23})
        assert _sperre() == 1, \
            "eine neue Funktion ueber 50 Verzweigungen kommt durch — die " \
            "zweite Achse ist dann nur Zierde"
        M.bericht = lambda: dict(_basis, **{"zw150": 0, "zw100": 2})
        assert _sperre() == 0, \
            "die Sperre faellt beim ABBAU von Verzweigungen"
    finally:
        M.bericht, M.GRUNDLINIE = _echt_b, _echt_g
        os.unlink(_tmp.name)

    # --- 5) Die eingecheckte Grundlinie kennt beide Achsen ---------------
    basis = M._lade()
    assert basis and all(("zw%d" % s) in basis["stufen"] for s in M.ZWEIG_STUFEN), \
        "die eingecheckte Grundlinie hat keine Verzweigungs-Stufen — die " \
        "zweite Achse ist in der CI dann wirkungslos"
    ok("W74: die Sperre faellt auf beiden Achsen, die Grundlinie kennt beide")

    # --- 6) CLAUDE.md nennt DIESELBEN Zahlen wie die Grundlinie ----------
    # v4.2-W76: nach W75 stand dort noch die alte Grundlinie (9 ueber 300,
    # 4 ueber 500), weil das Senken der JSON-Datei den Fliesstext nicht
    # mitnimmt — und tools/ncpatch.py docs kennt diese Zahlen nicht, es
    # prueft Routen, Funktionen, Module. Eine Anleitung, die eine andere
    # Grenze nennt als die CI durchsetzt, schickt den naechsten Leser in die
    # falsche Richtung.
    claude = io.open(os.path.join(hier, "CLAUDE.md"), encoding="utf-8").read()
    stand = basis["stufen"]
    for stufe, wort in ((100, "über 100"), (200, "über 200"),
                        (300, "über 300"), (500, "über 500")):
        erwartet = "%d %s" % (stand[str(stufe)], wort)
        assert erwartet in claude, \
            "CLAUDE.md nennt nicht %r — die Grundlinie sagt %s Funktionen " \
            "%s Zeilen, der Fliesstext etwas anderes" % (
                erwartet, stand[str(stufe)], wort)
    ok("W76: CLAUDE.md und die eingecheckte Grundlinie nennen dieselben Zahlen")


def _test_v42_w73_schleifen_befehle_werden_gezaehlt():
    """v4.2-W73: 15 Slash-Commands waren fuer Werkzeug und Doku unsichtbar.

    `tools/ncpatch.py` zaehlte nur DEKORIERTE Registrierungen. Die 15
    sys_*-Befehle in discordbot.py entstehen anders:

        for _pname, _pdesc, _pfn, _pargs in _PAR_CMDS:
            tree.command(name=_pname, description=_pdesc[:100])(_mk())

    Der Bot bot damit 60 Slash-Commands an, gemeldet wurden 45. Die Doku nannte
    45, listete die 15 nirgends — und erwaehnte sie in einer Fussnote trotzdem.
    Waere die Schleife weggefallen, haette das kein Werkzeug bemerkt: auch die
    Namenspruefung in _befehle() baut auf derselben Liste auf.

    Die Zuordnung laeuft ueber die SCHLEIFENVARIABLEN, nicht ueber geratene
    Spalten: `name=_pname` sagt, welche Stelle des Tupels der Name ist. Wer
    Spalte 0 annimmt, liegt beim naechsten Aufrufer daneben, der seine Tupel
    anders herum baut — und merkt es nie, weil hier zufaellig 0 stimmt.
    """
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import ncpatch as N

    # --- 1) Alle werden gesehen, keiner doppelt -------------------------
    # ANKER GEWANDERT (v4.2-W109, nicht der Vertrag): die Schleife laeuft
    # seither ueber nc/befehle.discord_ueber_tg() statt ueber die Tabelle
    # _PAR_CMDS, und die Namen tragen kein sys_ mehr. Die Aussage bleibt:
    # das Werkzeug sieht JEDEN registrierten Befehl, auch die aus der
    # Schleife. Die Sollzahl kommt aus dem Verzeichnis, nicht von Hand.
    from nc import befehle as _B
    treffer = N._scan(os.path.join(hier, "discordbot.py"))["slash"]
    namen = [n for _z, n, _b in treffer]
    soll = {b.name for b in _B.fuer(_B.DC)}
    assert set(namen) == soll, \
        "Werkzeug und Verzeichnis sind uneins — fehlt: %r, zuviel: %r" % (
            sorted(soll - set(namen)), sorted(set(namen) - soll))
    assert len(namen) == len(set(namen)), \
        "ein Befehl wird doppelt gezaehlt: %r" % [
            n for n in set(namen) if namen.count(n) > 1]
    for pflicht in ("pause", "cookies", "teststream", "diag"):
        assert pflicht in namen, \
            "%s wird nicht gefunden — die Schleifen-Erkennung greift nicht" % pflicht
    assert not [n for n in namen if n.startswith("sys_")], \
        "es gibt wieder sys_-Befehle — der Name ist auf beiden Plattformen derselbe"

    # --- 2) Die Spalten werden AUFGELOEST, nicht geraten -----------------
    # Der Beweis: eine Tabelle, in der Name und Beschreibung VERTAUSCHT sind.
    # Wer Spalte 0 fest annimmt, liefert hier die Beschreibung als Namen.
    import ast as _ast
    import tempfile as _tf
    quelle = (
        "TAB = (\n"
        "    ('Erste Beschreibung', 'echt_eins'),\n"
        "    ('Zweite Beschreibung', 'echt_zwei'),\n"
        ")\n"
        "def bauen(tree):\n"
        "    for _beschr, _name in TAB:\n"
        "        tree.command(name=_name, description=_beschr[:100])(None)\n")
    _t = _tf.NamedTemporaryFile("w", suffix=".py", delete=False, encoding="utf-8")
    try:
        _t.write(quelle)
        _t.close()
        got = N._scan(_t.name)["slash"]
        gn = sorted(n for _z, n, _b in got)
        assert gn == ["echt_eins", "echt_zwei"], \
            "bei vertauschten Spalten liefert der Pruefer %r — er raet die " \
            "Spalte, statt sie ueber die Schleifenvariable aufzuloesen" % (gn,)
        beschr = {n: b for _z, n, b in got}
        assert beschr["echt_eins"] == "Erste Beschreibung", beschr
    finally:
        os.unlink(_t.name)
    ok("W73: die Schleifen-Befehle werden gezaehlt, Spalten aufgeloest statt geraten")

    # --- 3) Ohne Schleife faellt die Zahl — und das merkt jemand ---------
    baum = _ast.parse(io.open(os.path.join(hier, "discordbot.py"),
                              encoding="utf-8").read())
    schleifen = [n for n in _ast.walk(baum) if isinstance(n, _ast.For)
                 and any(isinstance(c, _ast.Call) and isinstance(c.func, _ast.Call)
                         and "tree.command" in _ast.unparse(c.func)
                         for c in _ast.walk(n))]
    assert len(schleifen) == 1, \
        "es gibt %d Schleifen, die Befehle registrieren — kommt eine zweite " \
        "dazu, ist die Doku-Zahl neu zu pruefen" % len(schleifen)

    # --- 4) Und die Doku nennt sie jetzt beim Namen ----------------------
    # Die Zahl allein genuegt nicht: vor W73 stand in einer Fussnote sogar,
    # dass es die sys_*-Befehle gibt — aufgelistet waren sie trotzdem nie.
    # Seit W109: jeder Schleifen-Befehl (die gemeinsamen) namentlich.
    readme = io.open(os.path.join(hier, "README.md"), encoding="utf-8").read()
    fehlen = [b.name for b in _B.discord_ueber_tg()
              if ("`/" + b.name + "`") not in readme]
    assert not fehlen, \
        "diese Befehle sind registriert, stehen aber in keiner Liste im " \
        "README: %r" % fehlen
    # Nicht bloss „steht 60 irgendwo" — das ginge durch, solange EINE der
    # sechs Stellen stimmt. Die Mutationsprobe zu W73 hat genau das gezeigt:
    # eine zurueckgedrehte Ueberschrift blieb still. (Der Doku-Job faengt es
    # ueber tools/ncpatch.py docs; hier soll es die Suite ebenfalls sehen.)
    assert "%d Slash-Commands" % len(namen) in readme, \
        "das README nennt nirgends die gezaehlten %d Slash-Commands" % len(namen)
    veraltet = [z for z in readme.splitlines() if "45 Slash-Commands" in z]
    assert not veraltet, \
        "im README steht weiterhin die alte Zahl 45: %r — sie stammt aus " \
        "der Zeit, als die 15 Schleifen-Befehle nicht mitgezaehlt wurden" % veraltet
    ok("W73: alle Slash-Commands stehen im README, die gemeinsamen namentlich")


def _test_v42_w72_befehle_haben_eine_registrierung():
    """v4.2-W72: die 42 Befehle, die nur `tree` brauchen, sind heraus.

    Nach W71 blieben 1560 Zeilen. Gemessen brauchten 42 der 45 Befehle von
    dort nichts ausser `tree` — nachdem `_guard`, `_on_level_up`,
    `_ensure_team_roles`, `_ParBot`, `_ParMsg` und `_run_tg_handler` gehoben
    waren. Solche Ketten loesen sich nacheinander: `_guard` haengt nur noch an
    `_is_admin`, und das ging erst in W71 nach oben.

    ZWEI DINGE HABEN DEN UMBAU UNTERWEGS KORRIGIERT, und beide gehoeren
    festgehalten, weil sie beim naechsten Schnitt wieder auftreten:

    1. `app_commands` war KEIN Modul-Name, sondern ein Local von
       `_discord_run_once` (`from discord import app_commands` in einem
       try-Block). Die Messung hatte das uebersehen — sie sammelte Zuweisungen
       und Definitionen, aber keine Importe innerhalb von try. pyflakes hat
       den Umzug prompt mit 25 Meldungen gestoppt. Genau dafuer wurde vor dem
       Anfassen geprueft, dass pyflakes das tut. Der Import steht jetzt oben,
       aus demselben Grund, den der B79-Kommentar fuer `discord` nennt.

    2. Zwei der neun Sammelfunktionen kamen mit Kopfzeilen ueber 100 Zeilen.
       tools/monolith.py aus W70 hat das gemeldet — und die Grundlinie wurde
       NICHT neu gesetzt, sondern die beiden geteilt. Eine Sperre, die man bei
       der ersten Unbequemlichkeit hochsetzt, ist keine.
    """
    import ast as _ast
    hier = os.path.dirname(os.path.abspath(__file__))
    src = io.open(os.path.join(hier, "discordbot.py"), encoding="utf-8").read()
    baum = _ast.parse(src)
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    # --- 1) Die Registrierungen stehen auf Modulebene --------------------
    regs = sorted(n for n in oben if n.startswith("_reg_"))
    assert len(regs) >= 11, \
        "es gibt nur %d Registrier-Funktionen — sind welche wieder in die " \
        "Closure gewandert? %r" % (len(regs), regs)
    for n in regs:
        laenge = oben[n].end_lineno - oben[n].lineno + 1
        assert laenge < 100, \
            "%s ist mit %d Zeilen selbst ein Fall fuer tools/monolith.py — " \
            "eine Sammelfunktion darf nicht der naechste Riese werden" % (n, laenge)

    # --- 2) …und werden auch WIRKLICH aufgerufen -------------------------
    # Eine nicht aufgerufene Registrierung faellt weder py_compile noch
    # pyflakes auf: die Befehle waeren schlicht weg, und zwar still.
    lauf = oben.get("_discord_run_once")
    assert lauf is not None, "_discord_run_once ist verschwunden"
    gerufen = {_ast.unparse(k.func) for k in _ast.walk(lauf)
               if isinstance(k, _ast.Call) and isinstance(k.func, _ast.Name)}
    for n in regs:
        assert n in gerufen, \
            "%s wird nirgends aufgerufen — die Befehle darin sind damit " \
            "still verschwunden, ohne dass ein Werkzeug meckert" % n

    # --- 3) Der Aufruf steht NACH der tree-Erzeugung ---------------------
    zeilen = src.splitlines()
    # Bewusst kein next()/min() ohne Auffang: faellt eine der beiden Stellen
    # weg, war die Meldung ein nacktes StopIteration — ein Vertrag, der so
    # scheitert, sagt dem Leser nichts ueber den Schaden.
    _tree = [i for i, z in enumerate(zeilen, 1)
             if "tree = app_commands.CommandTree(" in z]
    assert _tree, \
        "die Erzeugung des CommandTree ist verschwunden — ohne sie hat " \
        "keine Registrierung etwas, woran sie ihre Befehle haengen kann"
    _reg = [i for i, z in enumerate(zeilen, 1)
            if z.strip().startswith("_reg_") and z.strip().endswith("(tree)")]
    assert _reg, "keine einzige Registrierung wird mehr aufgerufen"
    z_tree, z_erst = _tree[0], min(_reg)
    assert z_erst > z_tree, \
        "eine Registrierung laeuft vor `tree = ...` — das ist ein NameError " \
        "beim Start, und der ganze Discord-Teil faellt aus"
    ok("W72: elf Registrierungen auf Modulebene, alle aufgerufen, alle unter 100 Zeilen")

    # --- 4) app_commands steht oben, nicht in der Closure ----------------
    kopf = src[:src.find("def _reg_")]
    assert "from discord import app_commands" in kopf, \
        "app_commands wird nicht mehr auf Modulebene importiert — die " \
        "`@app_commands.describe(...)` in den Registrier-Funktionen loesen " \
        "dann gegen nichts auf (25x undefined name)"
    assert "app_commands = None" in kopf, \
        "ohne den None-Zweig stirbt der Import des ganzen Moduls, wenn " \
        "discord.py fehlt — es ist ausdruecklich optional"

    # --- 5) ALLE Befehle sind noch da, auch die 15 dynamischen -----------
    # Die dekorierten zaehlt tools/ncpatch.py; die 15 aus der _PAR_CMDS-
    # Schleife sieht es NICHT, weil sie ueber tree.command(...)(...) statt
    # ueber einen Dekorator registriert werden. Faellt die Schleife weg,
    # meldet das sonst nichts — deshalb stehen sie hier mit.
    dek = [d for x in _ast.walk(baum)
           if isinstance(x, (_ast.FunctionDef, _ast.AsyncFunctionDef))
           for d in x.decorator_list if "tree.command" in _ast.unparse(d)]
    # ANKER GEWANDERT (v4.2-W109): 43 dekorierte (sys_report und
    # sys_unpause waren Kopien und laufen jetzt ueber den Shim) plus die
    # Schleife ueber nc/befehle.discord_ueber_tg() statt ueber _PAR_CMDS.
    from nc import befehle as _B
    nativ = {b.name for b in _B.discord_nativ()}
    dek_namen = {_ast.literal_eval(k.value) for x in _ast.walk(baum)
                 if isinstance(x, (_ast.FunctionDef, _ast.AsyncFunctionDef))
                 for d in x.decorator_list if "tree.command" in _ast.unparse(d)
                 for k in d.keywords if k.arg == "name"}
    assert len(dek) == len(nativ) and dek_namen == nativ, \
        "dekoriert und als nativ verzeichnet sind uneins — fehlt: %r, zuviel: %r" % (
            sorted(nativ - dek_namen), sorted(dek_namen - nativ))
    schleife = [n for n in _ast.walk(baum) if isinstance(n, _ast.For)
                and _ast.unparse(n.iter) == "_nc_befehle.discord_ueber_tg()"]
    assert schleife, "die Schleife ueber das Verzeichnis ist weg — damit " \
        "fehlen alle gemeinsamen Befehle"
    assert "tree.command(name=_bf.name" in _ast.unparse(schleife[0]), \
        "die Schleife registriert die gemeinsamen Befehle nicht mehr unter " \
        "ihrem Verzeichnis-Namen"
    ok("W72: %d dekorierte und %d aus dem Verzeichnis — alle da" % (
        len(dek), len(_B.discord_ueber_tg())))

    # --- 6) _discord_run_once ist wirklich geschrumpft -------------------
    laenge = lauf.end_lineno - lauf.lineno + 1
    assert laenge <= 800, \
        "_discord_run_once ist mit %d Zeilen wieder ueber 800 — der Schnitt " \
        "aus W72 ist damit zu" % laenge
    ok("W72: _discord_run_once ist von 1730 (vor W71) auf unter 800 Zeilen")


def _test_v42_w71_discord_run_once_geschrumpft():
    """v4.2-W71: die groesste Funktion des Bestands, erster echter Schnitt.

    `_discord_run_once` hatte 1730 Zeilen — 45 Slash-Commands und ihre Helfer,
    alle als Closures. W70 hatte gezeigt, dass sie und nicht bot.py der
    eigentliche Riese ist, und dass sie aus der Datei stammt, die in W15 GEGEN
    dieses Problem aus bot.py herausgeloest wurde.

    Zwei Voraussetzungen wurden vor dem Anfassen gemessen, nicht gehofft:

      1. pyflakes meldet einen vergessenen Closure-Namen als `undefined name`.
         Damit ist ein Umzug ueberhaupt pruefbar.
      2. KEINES der 88 Locals ueberdeckt einen Modul-Namen. Der gefaehrliche
         stille Fall — eine verschobene Funktion greift statt auf das lokale
         auf ein gleichnamiges globales Ding — kann hier also nicht eintreten.

    Herausgegangen sind zwei Sorten:

      nc/discordrang.py   reine Rechnung (Rangstufen, XP-Kurve, Kanal-Slug),
                          bot-frei UND discord-frei
      Modulebene          neun Helfer, die keine einzige Closure-Variable
                          brauchten und nur Modul-Namen benutzen

    Der Umzug wurde als neutral BEWIESEN: die Ruempfe der neun sind vor und
    nach dem Heben strukturell identisch (ast.dump ohne Zeilennummern), nach
    Abzug allein der Rang-Umbenennungen. Und die XP-Kurve stand vorher dreimal
    im Code — einmal als Schleife, zweimal woertlich als
    `100 * (lvl + 1) * (lvl + 1)` im Anzeigecode.
    """
    import nc.discordrang as R

    # --- 1) Die Rang-Rechnung stimmt mit der alten Schleife ueberein -----
    # Beim Umzug einer laufenden Rechnung ist Gleichheit wichtiger als
    # Eleganz. Deshalb steht die Schleife dort noch, und deshalb wird sie
    # hier gegen die urspruengliche Fassung gehalten.
    def alt(xp):
        lvl = 0
        while xp >= 100 * (lvl + 1) * (lvl + 1):
            lvl += 1
        return lvl

    proben = list(range(0, 5000)) + [99, 100, 101, 399, 400, 401, 899, 900,
                                     901, 249999, 250000, 250001]
    schlecht = [x for x in proben if alt(x) != R.xp_zu_level(x)]
    assert not schlecht, \
        "xp_zu_level weicht von der urspruenglichen Schleife ab, zuerst bei " \
        "%r — jemandem fehlt dann ein Level" % schlecht[:3]
    assert R.xp_fuer_level(1) == 100 and R.xp_fuer_level(3) == 900, \
        "die XP-Kurve ist nicht mehr 100*N^2"
    assert R.rang_fuer_level(0) is None, "Level 0 hat einen Rang bekommen"
    assert R.rang_fuer_level(2) == "GHOST" and R.rang_fuer_level(3) == "RUNNER", \
        "die Rangschwellen haben sich verschoben"
    assert R.rang_fuer_level(999) == "LEGENDE", \
        "oberhalb der hoechsten Stufe faellt der Rang wieder weg — die " \
        "Schleife behaelt absichtlich den LETZTEN Treffer"
    assert R.slug("@Test_User!!") == "test-user", R.slug("@Test_User!!")
    assert R.slug("@@@") == "user", \
        "ein Name ohne brauchbare Zeichen ergibt einen leeren Slug — dann " \
        "entstuende ein Kanal '#-clips'"
    assert len(R.slug("a" * 200)) == 90, \
        "der Slug ist nicht mehr auf 90 Zeichen begrenzt (Discord-Riegel)"

    # --- 2) Das Modul bleibt bot-frei UND discord-frei -------------------
    hier = os.path.dirname(os.path.abspath(__file__))
    quelle = io.open(os.path.join(hier, "nc", "discordrang.py"),
                     encoding="utf-8").read()
    for verboten in ("import discord", "from discord", "import bot", "from bot"):
        assert verboten not in quelle, \
            "nc/discordrang.py importiert %r — es ist reine Rechnung und " \
            "muss ohne die Bibliothek pruefbar bleiben" % verboten
    ok("W71: die Rang-Rechnung ist heraus, bot-frei und deckungsgleich")

    # --- 3) _discord_run_once ist wirklich kleiner geworden --------------
    import sys as _sys
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import monolith as M
    treffer = [f for f in M.funktionen()
               if f[0] == "discordbot.py" and f[1] == "_discord_run_once"]
    assert treffer, "_discord_run_once ist nicht mehr auffindbar"
    laenge = treffer[0][3]
    assert laenge < 1730, \
        "_discord_run_once ist mit %d Zeilen nicht kleiner als vor W71" % laenge
    assert laenge <= 1600, \
        "_discord_run_once ist auf %d Zeilen zurueckgewachsen — der Schnitt " \
        "aus W71 ist damit wieder zu" % laenge

    # --- 4) Die neun Helfer stehen auf Modulebene ------------------------
    import ast as _ast
    dsrc = io.open(os.path.join(hier, "discordbot.py"), encoding="utf-8").read()
    baum = _ast.parse(dsrc)
    oben = {n.name for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    for name in ("_disc_sprache_setzen", "_is_admin", "_ensure_rank_roles",
                 "_provision_base_channels",   # _provision_user_channels: entfallen in W168
                 "_tracked_usernames", "_par_chat_id", "_handle_voice_ai",
                 "_discord_automod"):
        assert name in oben, \
            "%s ist wieder in die Closure gewandert — dort ist es weder " \
            "einzeln lesbar noch prueft pyflakes seine Namen gegen die " \
            "Modulebene" % name

    # --- 5) Und ALLE 45 Slash-Commands sind noch registriert -------------
    # Die eigentliche Gefahr dieses Umbaus: ein Command faellt beim
    # Verschieben aus dem Baum und niemand merkt es, weil discordbot.py in
    # keinem Test ausgefuehrt wird.
    befehle = [d for x in _ast.walk(baum)
               if isinstance(x, (_ast.FunctionDef, _ast.AsyncFunctionDef))
               for d in x.decorator_list if "tree.command" in _ast.unparse(d)]
    # ANKER GEWANDERT (v4.2-W109): die Sollzahl der DEKORIERTEN Befehle steht
    # im Verzeichnis (nativ) — 43, seit /sys_report und /sys_unpause als
    # Kopien entfallen sind und ueber den Shim laufen.
    from nc import befehle as _B
    soll = len(_B.discord_nativ())
    assert len(befehle) == soll, \
        "es sind %d statt %d dekorierte Slash-Commands registriert — beim " \
        "Umbau ist einer verlorengegangen" % (len(befehle), soll)
    ok("W71: neun Helfer auf Modulebene, %d dekorierte Slash-Commands" % soll)


def _test_v42_w70_keine_neue_riesenfunktion():
    """v4.2-W70: der Plan zeigte beim Monolithen auf die falsche Arbeit.

    „Monolith zerlegen — RestreamManager (1463), handle_recording_finished
    (615), KickModerator (593)." Nachgemessen stimmt daran zweierlei nicht.

    ERSTENS ist in den drei Genannten fast nichts mehr zu holen. Was sich
    sauber herausloesen liess, IST heraus — bot.py ruft ueber 600-mal in nc/
    hinein. Die Entscheidungslogik der Moderation etwa steht seit B165 und
    W14/W19 in nc/modheuristics.py; in bot.py blieb der Zustand. Gezaehlt:
    RestreamManager 77 fremde Globals und 3 reine Methoden (47 Zeilen),
    KickModerator 70 und eine (6 Zeilen), handle_recording_finished 58 und
    keine. Diese drei nach nc/ zu schieben hiesse, 45 bis 77 Namen per
    configure() hineinzureichen — kein Zerlegen, sondern ein riesiges
    Parameterobjekt, und das an der heikelsten Stelle des Bestands.

    ZWEITENS steht die groesste Funktion gar nicht in bot.py:

        1730 Z  discordbot.py  _discord_run_once
         718 Z  nc/schema.py   create_schema
         616 Z  bot.py         handle_recording_finished

    discordbot.py wurde in v4.2-W15 AUS bot.py herausgeloest, genau gegen
    dieses Problem. Die Masse ist umgezogen, nicht geschrumpft. Ein Mass, das
    nur bot.py anschaut, haette die Verlagerung als Erfolg verbucht.

    Gezaehlt wird deshalb die ANZAHL ueber Stufen, nicht die Laenge: eine
    Sperre, die jede zusaetzliche Zeile meldet, faellt bei jeder normalen
    Fehlerbehebung und ist in einer Woche abgeschaltet. Dieselbe Ueberlegung
    wie bei den stillen except-Bloecken in W65.
    """
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import monolith as M

    # --- 1) Der Blick reicht ueber bot.py hinaus ------------------------
    # Das ist die eigentliche Lehre der Welle. Ein Pruefer, der nur bot.py
    # misst, belohnt das Verschieben einer Riesenfunktion in eine andere
    # Datei — und genau das ist hier schon einmal passiert.
    alle = M.funktionen()
    # v4.2-W74: funktionen() liefert jetzt fuenf Werte je Eintrag — die
    # Verzweigungszahl kam dazu. Ueber den Index statt ueber festes
    # Entpacken, damit eine weitere Achse diesen Vertrag nicht kippt.
    dateien = {f[0] for f in alle}
    assert "discordbot.py" in dateien, \
        "discordbot.py wird nicht mehr gemessen — dort steht die groesste " \
        "Funktion des Bestands, und sie kam aus bot.py"
    assert any(d.startswith("nc/") for d in dateien), \
        "nc/ wird nicht mehr gemessen — dann genuegt es, eine Riesenfunktion " \
        "dorthin zu verschieben, um die Sperre zu bestehen"
    groesste = max(alle, key=lambda f: f[3])
    assert groesste[0] != "bot.py", \
        "die groesste Funktion steht wieder in bot.py — dann stimmt die " \
        "Begruendung dieser Welle nicht mehr und die Zahlen gehoeren neu " \
        "erhoben, statt den Text zu erben"

    # --- 2) Die Entscheidungslogik der Moderation ist WIRKLICH draussen --
    # Ohne diesen Beleg ist „da ist nichts mehr zu holen" eine Behauptung.
    import nc.modheuristics as MH
    for name in ("stateless_reason", "flood_reason", "escalation_minutes",
                 "escalation_step", "prune_history", "prune_infractions"):
        assert hasattr(MH, name), \
            "nc/modheuristics.%s fehlt — die Moderationslogik waere damit " \
            "zurueck in bot.py gewandert" % name
    src = io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    i = src.find("class KickModerator")
    assert i > 0, "KickModerator ist nicht mehr auffindbar"
    rumpf = rumpf_ab(src, i)
    for ruft in ("_nc_mod.escalation_step(", "_nc_mod.stateless_reason(",
                 "_nc_mod.flood_reason("):
        assert ruft in rumpf, \
            "KickModerator ruft %s nicht mehr — die Logik ist dann wieder " \
            "inline und der Befund dieser Welle hinfaellig" % ruft
    ok("W70: die Entscheidungslogik steht in nc/, in bot.py blieb der Zustand")

    # --- 3) Die Sperre faellt bei einer NEUEN Riesenfunktion -------------
    import contextlib as _ctx
    import json as _json
    import tempfile as _tf
    _echt_b, _echt_g, _echt_a = M.bericht, M.GRUNDLINIE, _sys.argv

    def _sperre():
        with _ctx.redirect_stdout(io.StringIO()):
            return M.main(["--sperre"])

    _tmp = _tf.NamedTemporaryFile("w", suffix=".json", delete=False,
                                  encoding="utf-8")
    try:
        _json.dump({"stufen": {"100": 63, "200": 16, "300": 9, "500": 4}}, _tmp)
        _tmp.close()
        M.GRUNDLINIE = _tmp.name
        M.bericht = lambda: {"100": 63, "200": 16, "300": 9, "500": 4}
        assert _sperre() == 0, "die Sperre faellt, obwohl nichts dazukam"
        M.bericht = lambda: {"100": 62, "200": 15, "300": 9, "500": 4}
        assert _sperre() == 0, \
            "die Sperre faellt beim ABBAU — dann bestraft sie genau die " \
            "Arbeit, um die es geht"
        M.bericht = lambda: {"100": 64, "200": 16, "300": 9, "500": 4}
        assert _sperre() == 1, \
            "eine NEUE Funktion ueber 100 Zeilen kommt durch"
        M.bericht = lambda: {"100": 63, "200": 16, "300": 10, "500": 4}
        assert _sperre() == 1, \
            "eine Funktion, die in die naechste Stufe rutscht, kommt durch"
        M.GRUNDLINIE = _tmp.name + ".gibtsnicht"
        assert _sperre() == 1, \
            "ohne Grundlinie meldet die Sperre OK — dann genuegt es, die " \
            "Basisdatei zu loeschen, um sie loszuwerden"
    finally:
        M.bericht, M.GRUNDLINIE, _sys.argv = _echt_b, _echt_g, _echt_a
        os.unlink(_tmp.name)
    ok("W70: die Sperre faellt bei neuer und bei gewachsener Riesenfunktion")

    # --- 4) Und die eingecheckte Grundlinie passt zum Bestand ------------
    basis = M._lade()
    assert basis is not None, \
        ".claude/monolith_grundlinie.json fehlt — die Sperre ist dann in " \
        "der CI wirkungslos"
    jetzt = M.bericht()
    zu_hoch = [(s, basis["stufen"].get(s), n) for s, n in jetzt.items()
               if basis["stufen"].get(s, 0) > n]
    assert not zu_hoch, (
        "die Grundlinie liegt UEBER dem Bestand %r — dann ist Luft nach oben "
        "eingefroren und eine neue Riesenfunktion faellt nicht auf" % (zu_hoch,))
    ok("W70: die Grundlinie sitzt auf dem Bestand, nicht darueber")


def _test_v42_w69_diagnose_sieht_die_schluessel():
    """v4.2-W69: das Diagnose-Kommando log ueber die Schluessel.

    An acht Stellen — zwei Skills, sechs Doku-Dateien — stand:

        python3 -c "import nc.freeai as f; print(f.diagnose())"

    `nc/freeai` ist bot-frei und laedt die `.env` nie selbst; im Bot macht das
    bot.py. Ein nacktes `python3 -c` zeigt deshalb IMMER `keyless`, auch wenn
    POLLINATIONS_API_KEY und LLM7_TOKEN sauber gesetzt sind.

    Das ist genau die Frage, fuer die man das Kommando aufruft, und genau die
    Frage, die W67 beantwortet hat. Nach dem W67-Deploy meldete es vier Basen
    (richtig, vorher war es eine) und viermal `keyless` (falsch) — und liess
    damit offen, ob der eigentliche Fix ueberhaupt gewirkt hat.

    Gemessen: dieselbe .env, derselbe Code, einziger Unterschied ist
    load_dotenv() davor. Ohne 4x keyless, mit 2x KEY.
    """
    import glob as _glob
    hier = os.path.dirname(os.path.abspath(__file__))

    # --- 1) Nirgends mehr das Kommando OHNE Vorspann --------------------
    # Der CHANGELOG bleibt aussen vor, und zwar mit Grund: er ZITIERT das
    # kaputte Kommando als das, was frueher dastand. Ein Pruefer, der seine
    # eigene Fehlerbeschreibung anmeckert, zwingt dazu, die Geschichte
    # unleserlich zu schreiben — in W66 ist genau das passiert, dort musste
    # ein Beispiel zerlegt werden (`"src[i:i + " + "2200]"`). Vorschreibend
    # sind die Skills und die Anleitungen; der CHANGELOG ist Historie.
    HISTORIE = ("docs/CHANGELOG.md",)
    nackt, geprueft = [], set()
    for muster in (".claude/skills/**/*.md", "docs/**/*.md", "*.md"):
        for pfad in _glob.glob(os.path.join(hier, muster), recursive=True):
            rel = os.path.relpath(pfad, hier).replace(os.sep, "/")
            if rel in HISTORIE:
                continue
            geprueft.add(rel)
            for nr, zeile in enumerate(
                    io.open(pfad, encoding="utf-8").read().splitlines(), 1):
                if "nc.freeai" in zeile and "diagnose()" in zeile \
                        and "load_dotenv" not in zeile:
                    nackt.append((rel, nr))
    # Und die Ausnahme darf nicht heimlich alles verschlucken: die acht
    # vorschreibenden Stellen muessen nachweislich IM Pruefbereich liegen.
    for pflicht in (".claude/skills/nc-ki-backends/SKILL.md",
                    ".claude/skills/nc-betrieb/SKILL.md",
                    "docs/DEPLOY.md", "docs/TROUBLESHOOTING.md",
                    "docs/CONTRIBUTING.md", "docs/en/DEPLOY.md",
                    "docs/en/TROUBLESHOOTING.md", "docs/en/CONTRIBUTING.md"):
        assert pflicht in geprueft, \
            "%s liegt nicht mehr im Pruefbereich — dann kann dort ein " \
            "Kommando ohne Vorspann stehen, ohne dass es auffaellt" % pflicht
    assert not nackt, (
        "Diagnose-Kommando ohne load_dotenv(): %r — es zeigt dann IMMER "
        "keyless, egal was in der .env steht, und beantwortet genau die "
        "Frage falsch, fuer die man es aufruft" % (nackt,))

    # --- 2) Und die Aussage dahinter stimmt wirklich ---------------------
    # Ohne diese Probe waere Punkt 1 eine Textregel, die jemand aus
    # Ordnungsliebe befolgt. Hier steht der Grund: derselbe Code liefert
    # ohne .env keinen Key und mit .env einen.
    import nc.freeai as F
    _alt = {k: os.environ.get(k)
            for k in ("POLLINATIONS_API_KEY", "POLLINATIONS_TOKEN",
                      "LLM7_TOKEN", "LLM7_API_KEY")}
    try:
        for k in _alt:
            os.environ.pop(k, None)
        ohne = [b for b in F._basen() if b.get("key")]
        assert not ohne, \
            "ohne Umgebung traegt eine Base einen Key — dann sagt die " \
            "Diagnose etwas anderes als die Umgebung hergibt"
        os.environ["POLLINATIONS_API_KEY"] = "PROBE-P"
        os.environ["LLM7_TOKEN"] = "PROBE-L"
        mit = [b for b in F._basen() if b.get("key")]
        assert len(mit) == 2, \
            "mit gesetzten Schluesseln tragen %d statt 2 Basen einen Key — " \
            "die Diagnose zeigt dann nicht, was der Bot wirklich benutzt" % len(mit)
    finally:
        for k, v in _alt.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    ok("W69: die Diagnose zeigt Schluessel nur mit load_dotenv() — und dann richtig")

    # --- 3) Die Aufrufzeile ist kopiersicher -----------------------------
    # `<vorlage.png>` in eine Shell kopiert ist eine Eingabeumlenkung. Der
    # Betreiber hat genau das getan und bekam `zsh: parse error near \\n`.
    kopf = io.open(os.path.join(hier, "tools", "azrael_frames.py"),
                   encoding="utf-8").read()[:3000]
    assert "azrael_frames.py <" not in kopf, \
        "die Aufrufzeile traegt wieder spitze Klammern — kopiert man sie in " \
        "eine Shell, ist das eine Eingabeumlenkung und stirbt mit parse error"
    ok("W69: die Aufrufzeile von azrael_frames laesst sich gefahrlos kopieren")


def _test_v42_w68_abhaengigkeiten_haben_untergrenzen():
    """v4.2-W68: 17 Fremdpakete, 0 Untergrenzen — und eine Luecke daneben.

    Ohne `>=` loest pip auf einer aelteren Maschine irgendetwas auf, und der
    Fehler kommt nicht als klare Ansage, sondern als AttributeError tief im
    Code an. Die sechs Grenzen mit API-Zwang sind NACHGESEHEN, nicht
    geschaetzt: fuer jede wurde das Rad der Fassung darunter geladen und
    geprueft, dass die benutzte Schnittstelle dort fehlt.

        python-telegram-bot  20.0  hat telegram/ext/_application.py, 13.15 nicht
        discord.py           2.0   hat discord/app_commands/,        1.7.3 nicht
        TikTokLive           6.0   hat TikTokLive/events/,           5.0.0 nicht
        Flask                2.2   hat flask/json/provider.py,       2.1.0 nicht
        redis                4.2   hat redis/asyncio/,               4.1.0 nicht
        Werkzeug             2.0   reicht safe_join durch

    Die Luecke daneben: der Vertrag aus v4.1-W31 prueft nur die MODUL-EBENE
    und nur gegen requirements-smoke.txt. Genau die teuren Pakete werden aber
    erst IN Funktionen importiert — boto3, faster_whisper, redis, pymysql,
    httpx, requests, socks, websockets_proxy. Fuer die gab es keine Pruefung.

    Drei Importe zaehlen bewusst NICHT als Verstoss, und alle drei stehen so
    im Bestand: `segno` liegt mitgeliefert unter nc/_vendor/,
    `browser_cookie3` ist optional mit ImportError-Auffang, und Pillow steht
    nur in tools/ — ein Vertrag aus W53 haelt ausdruecklich fest, dass es in
    keiner requirements-Datei auftauchen darf. Ein Pruefer, der diese drei
    nicht kennt, meldet drei Fehlalarme und wird abgeschaltet.
    """
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import abhaengigkeiten as A

    # --- 1) Jede Zeile traegt eine Untergrenze ---------------------------
    unerklaert, ohne, tot, uneins = A.bericht()
    assert not ohne, \
        "Eintrag in requirements.txt ohne Untergrenze: %r — ohne >= loest " \
        "pip auf einer alten Maschine irgendetwas auf" % (ohne,)
    assert not unerklaert, \
        "Import ohne Eintrag in requirements.txt: %r — auf dem Server laeuft " \
        "das (von Hand nachinstalliert), eine frische Installation stirbt " \
        "daran" % (unerklaert,)
    assert not tot, "requirements.txt listet Pakete, die niemand importiert: %r" % (tot,)
    assert not uneins, \
        "requirements.txt und requirements-smoke.txt nennen verschiedene " \
        "Untergrenzen %r — dann prueft die CI eine Fassungsreihe, die der " \
        "Bot gar nicht benutzt" % (uneins,)
    ok("W68: 17 Pakete, alle erklaert, alle mit Untergrenze, beide Dateien einig")

    # --- 2) Die Grenzen mit API-Zwang haengen an DER Stelle im Code ------
    # Ohne diese Kopplung ist die Grenze eine Zahl, die jemand irgendwann
    # gesenkt hat, weil pip gemeckert hat. Mit ihr faellt der Vertrag, sobald
    # Grenze und benutzte Schnittstelle auseinanderlaufen.
    gelistet = A._gelistet()
    src = io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    for paket, mindestens, beweis in (
            ("python-telegram-bot", (20, 0), "Application.builder()"),
            ("discord.py",          (2, 0),  None),
            ("tiktoklive",          (6, 0),  "from TikTokLive.events import"),
            ("flask",               (2, 2),  "app.json"),
            ("redis",               (4, 2),  "import redis.asyncio"),
            ("werkzeug",            (2, 0),  "from werkzeug.utils import safe_join")):
        roh = gelistet.get(paket)
        assert roh, "%s steht nicht mehr in requirements.txt" % paket
        teile = tuple(int(t) for t in A.grenze(roh).split(".")[:2])
        assert teile >= mindestens, \
            "%s: Untergrenze %s liegt unter %s — die Fassung darunter hat " \
            "die benutzte Schnittstelle nachweislich nicht" % (
                paket, A.grenze(roh), ".".join(str(z) for z in mindestens))
        if beweis:
            assert beweis in src, \
                "bot.py benutzt %r nicht mehr — dann ist die Untergrenze " \
                "von %s unbegruendet und gehoert geprueft, nicht vererbt" % (
                    beweis, paket)
    assert "app_commands" in io.open(
        os.path.join(hier, "discordbot.py"), encoding="utf-8").read(), \
        "discordbot.py benutzt app_commands nicht mehr — dann ist die " \
        "Untergrenze discord.py >= 2.0 unbegruendet"
    ok("W68: jede Untergrenze mit API-Zwang haengt an der Stelle, die sie erzwingt")

    # --- 3) Der Pruefer sieht Importe in FUNKTIONEN ----------------------
    # Das ist die Luecke, die W31 gelassen hat, und sie ist der ganze Grund
    # fuer dieses Werkzeug. Ein Import auf Modul-Ebene faellt frueher oder
    # spaeter im Rauchtest auf; einer in einer selten benutzten Funktion nie.
    import tempfile as _tf
    _t = _tf.NamedTemporaryFile("w", suffix=".py", delete=False, encoding="utf-8")
    try:
        _t.write("import os\n\n\n"
                 "def spaeter():\n"
                 "    import irgendwas_fremdes\n"
                 "    return irgendwas_fremdes\n\n\n"
                 "def weich():\n"
                 "    try:\n"
                 "        import auch_fremd\n"
                 "    except ImportError:\n"
                 "        auch_fremd = None\n"
                 "    return auch_fremd\n")
        _t.close()
        pflicht, optional = A._importe(_t.name)
        assert "irgendwas_fremdes" in pflicht, \
            "ein Import im FUNKTIONSRUMPF wird nicht gesehen — genau die " \
            "Luecke, die dieses Werkzeug schliessen soll"
        assert "auch_fremd" in optional and "auch_fremd" not in pflicht, \
            "ein Import mit ImportError-Auffang gilt als Pflicht — dann " \
            "meldet der Pruefer jedes bewusst optionale Paket als Fehler"
        assert "os" not in pflicht, "die Standardbibliothek wird mitgezaehlt"
    finally:
        os.unlink(_t.name)

    # --- 4) Die drei legitimen Faelle bleiben still ----------------------
    # Der Fehlalarm ist hier die groessere Gefahr als der uebersehene Fall:
    # ein Pruefer, der bei gesundem Bestand meckert, wird abgeschaltet.
    _fehlend = {n for _d, n, _p in unerklaert}
    # segno UNGESCHUETZT gegenpruefen. Die beiden echten Aufrufstellen in
    # nc/qrsvg.py stehen in einem try/except Exception, gelten damit ohnehin
    # als optional — die Ausnahmeliste traegt dort also gar nichts bei. Eine
    # Zusicherung „segno wird nicht gemeldet" ginge deshalb aus dem falschen
    # Grund durch: sie faellt nicht, wenn jemand MITGELIEFERT leert. Genau das
    # hat die Mutationsprobe zu W68 gezeigt. Hier steht deshalb ein
    # ungeschuetzter Import, an dem die Liste wirklich haengt.
    _probe = os.path.join(hier, "nc", "_w68_probe.py")
    try:
        io.open(_probe, "w", encoding="utf-8").write("import segno\n")
        _u, _o, _t, _un = A.bericht()
        assert "segno" not in {n for _d, n, _p in _u}, \
            "ein ungeschuetztes `import segno` wird als fehlendes Paket " \
            "gemeldet — es liegt mitgeliefert unter nc/_vendor/ und gehoert " \
            "in keine requirements-Datei"
        _alt = A.MITGELIEFERT
        try:
            A.MITGELIEFERT = set()
            _u2, _, _, _ = A.bericht()
            assert "segno" in {n for _d, n, _p in _u2}, \
                "ohne die Ausnahmeliste wird das mitgelieferte segno TROTZDEM " \
                "nicht gemeldet — dann prueft diese Zusicherung nichts"
        finally:
            A.MITGELIEFERT = _alt
    finally:
        if os.path.exists(_probe):
            os.unlink(_probe)
    assert "browser_cookie3" not in _fehlend, \
        "browser_cookie3 wird als fehlend gemeldet — es ist optional und " \
        "der Code faengt sein Fehlen ausdruecklich ab"
    for datei in ("requirements.txt", "requirements-smoke.txt"):
        assert "pillow" not in io.open(
            os.path.join(hier, datei), encoding="utf-8").read().lower(), \
            "Pillow ist in %s gerutscht — es ist ein Werkzeug, keine " \
            "Laufzeit (W53)" % datei
    # Und der Beweis, dass die Ausnahmen echte Importe verdecken und nicht
    # bloss Namen in einer Liste sind:
    assert "import segno" in io.open(
        os.path.join(hier, "nc", "qrsvg.py"), encoding="utf-8").read(), \
        "nc/qrsvg.py importiert segno nicht mehr — dann ist die Ausnahme tot"
    ok("W68: mitgeliefert, optional und Werkzeug loesen keinen Fehlalarm aus")

    # --- 5) Und die Sperre faellt wirklich -------------------------------
    import contextlib as _ctx
    _echt = A.bericht
    try:
        with _ctx.redirect_stdout(io.StringIO()):
            A.bericht = lambda: ([("nc/x.py", "stripe", "stripe")], [], [], [])
            assert A.main(["--sperre"]) == 1, \
                "die Sperre laesst ein undeklariertes Paket durch"
            A.bericht = lambda: ([], ["orjson"], [], [])
            assert A.main(["--sperre"]) == 1, \
                "die Sperre laesst einen Eintrag ohne Untergrenze durch"
            A.bericht = lambda: ([], [], [], [("aiohttp", "3.9", "3.8")])
            assert A.main(["--sperre"]) == 1, \
                "die Sperre laesst zwei uneinige Untergrenzen durch"
            A.bericht = lambda: ([], [], [], [])
            assert A.main(["--sperre"]) == 0, \
                "die Sperre faellt, obwohl nichts zu beanstanden ist"
    finally:
        A.bericht = _echt
    ok("W68: die Sperre faellt bei fehlendem Paket, fehlender Grenze und Uneinigkeit")


def _test_v42_w67_env_erreicht_die_cloud_kette():
    """v4.2-W67: die .env-Keys haben nie einen Request gesehen.

    CLAUDE.md warnt seit langem: „Modul-Konstanten frieren `.env` ein. `.env`
    wird teils erst nach den ersten Imports geladen." Der Bestand hat den Satz
    gebrochen, und zwar an der teuersten Stelle. `nc/freeai.py` baute seine
    Basen-Liste auf Modul-Ebene (`_BASES = _default_bases()`), und weil
    nc/news.py, nc/marketing.py und nc/routes/ai.py das Modul in der
    Import-Reihe von bot.py mitziehen, geschah das VOR load_dotenv().
    POLLINATIONS_API_KEY und LLM7_TOKEN standen in der .env und kamen nirgends
    an — gemessen, nicht vermutet.

    Der zweite Riss lag in bot.py: der Zweig „keine Base konfiguriert" baute
    aus REACTION_AI_BASE bedingungslos EINE Base und reichte sie an
    configure() — das ersetzte den Katalog. In Produktion lief die Kette
    deshalb mit EINER statt VIER Basen. Die Rotation, auf die sich der Skill
    nc-ki-backends beruft, gab es nicht: sagte Pollinations „budget
    exceeded", war Schluss, weil es kein Ausweichziel gab. Genau dieses
    Moderator-Log hat W64 ausgeloest — W64 hat die Symptomseite behandelt
    (die Rechnung nicht mehr vorlesen), die Ursache lag hier.
    """
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import importzeit as I
    import nc.freeai as F

    # --- 1) Beim Import wird KEINE Basen-Liste gebaut -------------------
    assert F._BASES is None, \
        "nc.freeai baut die Basen-Liste wieder beim Import — dann sind die " \
        "Keys aus der .env leer, weil load_dotenv() noch nicht lief"

    # --- 2) …und die Keys kommen zur LAUFZEIT an ------------------------
    # Das ist der Punkt, an dem „presence" nicht genuegt: dass _basen()
    # existiert, sagt nichts. Der Key wird NACH dem Import gesetzt — genau
    # wie es load_dotenv() tut — und muss trotzdem ankommen.
    _alt = {k: os.environ.get(k) for k in ("POLLINATIONS_API_KEY", "LLM7_TOKEN")}
    try:
        os.environ["POLLINATIONS_API_KEY"] = "SPAET-GESETZT-P"
        os.environ["LLM7_TOKEN"] = "SPAET-GESETZT-L"
        keys = {b["url"]: b.get("key") for b in F._basen()}
        assert "SPAET-GESETZT-P" in keys.values(), \
            "der Pollinations-Key aus der Umgebung erreicht keine Base"
        assert "SPAET-GESETZT-L" in keys.values(), \
            "der LLM7-Key aus der Umgebung erreicht keine Base"
        # W64 bleibt gueltig: der Key geht NUR an den Gateway, nicht an den
        # keylosen Altpfad — sonst teilen sich beide ein Budget und fallen
        # gemeinsam aus, und die kostenlose Alternative ist genau dann weg,
        # wenn man sie braucht.
        for url, k in keys.items():
            if "text.pollinations.ai" in url:
                assert not k, \
                    "der keylose Altpfad hat wieder einen Key — dann teilen " \
                    "sich beide Pollinations-Basen ein Budget (W64)"
    finally:
        for k, v in _alt.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v

    # --- 3) Der Referrer ebenfalls zur Laufzeit -------------------------
    _r = os.environ.get("FREEAI_REFERRER")
    try:
        os.environ["FREEAI_REFERRER"] = "spaet-gesetzt"
        assert F._referrer() == "spaet-gesetzt", \
            "FREEAI_REFERRER wird wieder beim Import eingefroren"
    finally:
        if _r is None:
            os.environ.pop("FREEAI_REFERRER", None)
        else:
            os.environ["FREEAI_REFERRER"] = _r
    assert F._referrer(), "ohne Umgebung muss der Default stehen"
    ok("W67: freeai liest Keys und Referrer zur Laufzeit, nicht beim Import")

    # --- 4) bot.py streicht den Katalog nicht mehr zusammen -------------
    src = io.open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    i = src.find("_freeai_bases = [b for b in os.getenv(\"FREEAI_BASES\"")
    assert i > 0, "der Zweig, der die Basen waehlt, ist nicht mehr auffindbar"
    rumpf = rumpf_ab(src, i)
    assert "katalog_kennt" in rumpf, \
        "bot.py fragt nicht mehr, ob die Wunsch-Base ohnehin im Katalog " \
        "steht — dann ersetzt sie den Katalog wieder und es bleibt EINE Base"
    # Die eigentliche Aussage: der Zweig ist BEDINGT. Vorher stand dort ein
    # nacktes `if not _freeai_bases:` und damit war die Liste nie leer.
    assert "if not _freeai_bases:" not in rumpf, \
        "der Zweig fuellt die Basen-Liste wieder bedingungslos — dann ist " \
        "sie nie leer und configure() ersetzt den Katalog immer"
    assert F.katalog_kennt("https://api.llm7.io/v1"), \
        "katalog_kennt erkennt eine Base des eigenen Katalogs nicht"
    assert F.katalog_kennt("https://api.llm7.io/v1/"), \
        "katalog_kennt stolpert ueber den Schraegstrich am Ende"
    assert not F.katalog_kennt("https://mein.eigener.host/v1"), \
        "katalog_kennt haelt einen fremden Endpunkt fuer bekannt — dann " \
        "wird der eigene Endpunkt des Betreibers ignoriert"
    ok("W67: eine Wunsch-Base aus dem Katalog loescht die Ausweichbasen nicht")

    # --- 5) Der Pruefer sieht ALLE DREI Schreibweisen -------------------
    # Nur os.getenv abzufangen reicht nicht: os.environ.get() und
    # os.environ[...] gehen daran vorbei, und beide stehen im Bestand. Ein
    # Pruefer, der zwei Drittel nicht sieht, meldet Ruhe, wo keine ist —
    # dieselbe Klasse Fehler wie das Messgeraet in W65 und W66.
    with I.mitschnitt() as (stand, roh):
        os.getenv("W67_PROBE_A", "")
        os.environ.get("W67_PROBE_B", "")
        os.environ["PATH"]
        stand["geladen"] = True
        os.getenv("W67_ZU_SPAET", "")
    namen = [n for _d, _z, n in roh]
    for erwartet, wie in (("W67_PROBE_A", "os.getenv"),
                          ("W67_PROBE_B", "os.environ.get"),
                          ("PATH", "os.environ[...]")):
        assert erwartet in namen, \
            "der Pruefer sieht %s nicht — damit bleibt jede .env-Lesung in " \
            "dieser Schreibweise unsichtbar" % wie
    assert "W67_ZU_SPAET" not in namen, \
        "der Pruefer schreibt noch NACH load_dotenv() mit — dann meldet er " \
        "die 178 voellig korrekten Lesungen aus bot.py als Fehler"
    ok("W67: der Pruefer sieht getenv, environ.get und environ[...]")

    # --- 6) Und die Sperre faellt wirklich ------------------------------
    # Am CLI-Pfad geprueft, den die CI faehrt, nicht daneben nachgerechnet:
    # in W65 blieb genau deshalb eine Mutationsprobe still.
    import contextlib as _ctx
    _echt = I.messen
    try:
        I.messen = lambda: [("nc/beispiel.py", 12, "IRGENDEIN_KEY")]
        with _ctx.redirect_stdout(io.StringIO()):
            assert I.main(["--sperre"]) == 1, \
                "die Sperre laesst eine .env-Lesung vor load_dotenv() " \
                "durch — der CI-Job ist dann eine Attrappe"
            assert I.main([]) == 0, \
                "ohne --sperre soll der Bericht nicht rot sein"
            I.messen = lambda: []
            assert I.main(["--sperre"]) == 0, \
                "die Sperre faellt, obwohl nichts vor load_dotenv() liest"
    finally:
        I.messen = _echt
    ok("W67: die Sperre faellt bei jeder Lesung vor load_dotenv()")


def _test_v42_w66_fenster_wachsen_mit():
    """v4.2-W66: 47 Fenster fester Laenge — elf davon randvoll.

    CLAUDE.md warnt vor dieser Bruchstelle mit Namen: „waechst die Funktion
    darueber hinaus, meldet der Test etwas als fehlend, das zwei Zeilen weiter
    unten steht." In W62 hat sie zugeschlagen — `src[j:j + 4200]` reichte nicht
    mehr ueber den gewachsenen Frame-Feeder.

    ALLE 47 BLIND UMZUBAUEN WAERE SCHLIMMER GEWESEN, als sie zu lassen: ein zu
    grosses Fenster laesst einen Vertrag durchgehen, der durchfallen muesste.
    Genau das hat in W64 eine Mutationsprobe still durchrutschen lassen.

    Gemessen wurde deshalb erst — jedes Fenster einzeln auf 70 % verkleinert
    und die Suite gefahren (`vertragscheck.py --spielraum`). Faellt sie, war
    das Fenster fast voll. Ergebnis: 11 eng, 36 mit Luft. Umgebaut wurden die
    elf; die uebrigen anzufassen haette nur Risiko ohne Nutzen gebracht.
    Nach dem Umbau: 0 eng.

    Die Zahlen sind zweimal gefallen, und beide Male war das Messgeraet
    schuld, nicht der Bestand: 47 waren es, solange der Pruefer auch
    Kommentare und Docstrings mitzaehlte — und die zitieren `src[i:i + 3000]`
    reichlich als abschreckendes Beispiel. Im CODE sind es 45, nach dem
    Umbau 34.
    """
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import vertragscheck as V

    # --- 1) Der Anker waechst mit -------------------------------------
    quelle = "\n".join(["def eins():", "    a = 1", "    b = 2", "",
                        "def zwei():", "    c = 3", ""])
    ab = quelle.index("def eins")
    r = rumpf_ab(quelle, ab)
    assert "a = 1" in r and "b = 2" in r, r
    assert "def zwei" not in r and "c = 3" not in r, \
        "der Bereich laeuft in die naechste Funktion — dann findet ein " \
        "Vertrag Zeichenketten, die gar nicht zu seiner Einheit gehoeren"
    # Und er waechst wirklich: sechzig Zeilen mehr in eins() sind auch drin.
    groesser = quelle.replace("    b = 2", "    b = 2\n" + "    d = 4\n" * 60)
    assert "d = 4" in rumpf_ab(groesser, groesser.index("def eins")), \
        "der Bereich waechst nicht mit — genau der Fehler aus W62"

    # --- 2) Auch in zusammengefaltetem Quelltext ----------------------
    # `flach = " ".join(bot.split())` hat keine Zeilen mehr. Ohne den zweiten
    # Fall haette der Anker dort bis zum Dateiende gereicht.
    flach = " ".join(quelle.split())
    rf = rumpf_ab(flach, flach.index("def eins"))
    assert "a = 1" in rf, rf
    assert "def zwei" not in rf, \
        "im zusammengefalteten Text trennt ' def ' — sonst reicht der Bereich " \
        "bis zum Dateiende und der Vertrag prueft die ganze Datei"

    # --- 3) Am Dateiende hoert er auf, statt zu werfen ----------------
    letzte = quelle.index("def zwei")
    assert "c = 3" in rumpf_ab(quelle, letzte)
    # Und mitten in einer Funktion angesetzt: bis zu deren Ende, nicht weiter.
    mitten = quelle.index("b = 2")
    assert "def zwei" not in rumpf_ab(quelle, mitten)
    ok("W66: der Bereich waechst mit und endet an der naechsten Definition")

    # --- 4) Kein Fenster ist mehr randvoll ----------------------------
    # GEZAEHLT, NICHT VERBOTEN. Der erste Entwurf verlangte, dass Ausdruecke
    # wie `src[i:i + 2200]` nirgends mehr vorkommen — der steht aber ein
    # zweites Mal an einer Stelle MIT Luft und darf dort bleiben. Ein Verbot
    # haette also einen gesunden Vertrag angeklagt. Gezaehlt wird deshalb,
    # was wirklich gemacht wurde: elf Umbauten auf den mitwachsenden Anker.
    umbauten = sum(open(os.path.join(hier, d), encoding="utf-8").read()
                   .count("rumpf_ab(") for d in ("test_nc_modules.py",
                                                 "test_restream.py"))
    # Elf Umbauten, dazu je Datei die Definition und in dieser Datei die
    # Aufrufe des Vertrags selbst.
    assert umbauten >= 11, \
        f"nur {umbauten} Stellen benutzen den mitwachsenden Anker — die " \
        f"randvollen Fenster sind nicht umgebaut"
    fenster = V.bericht()
    gesamt = sum(len(t) for t in fenster.values())
    assert gesamt <= 34, \
        f"{gesamt} Fenster fester Laenge im CODE — vor W66 waren es 45, " \
        f"nach dem Umbau 34. Es sind wieder mehr geworden."
    assert "rumpf_ab(" in open(os.path.join(hier, "test_restream.py"),
                               encoding="utf-8").read(), \
        "test_restream benutzt den mitwachsenden Anker nicht"
    ok("W66: die elf randvollen Fenster sind durch mitwachsende Anker ersetzt")

    # --- 5) Und die Sperre gegen NEUE Fenster faellt auch -------------
    # Wie in W65 am CLI-Pfad geprueft, den die CI faehrt — nicht daneben
    # nachgerechnet. Genau dort blieb in W65 eine Mutationsprobe still.
    import contextlib as _ctx
    import json as _json
    import tempfile as _tf

    def _sperre():
        with _ctx.redirect_stdout(io.StringIO()):
            return V.main()

    # Auch die Attrappe steht zerlegt da: sie ist Testdaten, kein Fenster im
    # Bestand, und der Pruefer liest diese Datei mit.
    _attrappe = (1, "x[i:i + " + "10]", 10)
    _echt_b, _echt_g, _echt_a = V.bericht, V.GRUNDLINIE, _sys.argv
    _tmp = _tf.NamedTemporaryFile("w", suffix=".json", delete=False,
                                  encoding="utf-8")
    try:
        _json.dump({"fenster": {"a.py": 2}, "summe": 2}, _tmp)
        _tmp.close()
        V.GRUNDLINIE, _sys.argv = _tmp.name, ["vertragscheck.py", "--sperre"]
        V.bericht = lambda: {"a.py": [_attrappe] * 2}
        assert _sperre() == 0, "die Sperre faellt, obwohl nichts dazukam"
        V.bericht = lambda: {"a.py": [_attrappe]}
        assert _sperre() == 0, "die Sperre faellt beim ABBAU von Fenstern"
        V.bericht = lambda: {"a.py": [_attrappe] * 3}
        assert _sperre() == 1, \
            "die Sperre laesst ein NEUES Fenster fester Laenge durch"
        V.GRUNDLINIE = _tmp.name + ".gibtsnicht"
        assert _sperre() == 1, "ohne Grundlinie meldet die Sperre OK"
    finally:
        V.bericht, V.GRUNDLINIE, _sys.argv = _echt_b, _echt_g, _echt_a
        os.unlink(_tmp.name)
    ok("W66: die Sperre faellt bei neuen Fenstern und ohne Grundlinie")


def _test_v42_w89_variantenliste_bevorzugt_gezielt():
    """v4.2-W89: der Suffix-Merker greift auch, wenn `_hd` zweimal in der URL
    steht.

    `_PREFLIGHT_CACHE[who]` merkt sich, welches CDN-Suffix beim letzten Mal
    weggemusst hat, und sortiert die passende Variante nach vorn. Das ist eine
    Abkuerzung mit messbarem Wert: ohne sie kostet jede Aufnahme dieser Quelle
    eine zusaetzliche 404-Runde.

    Gebaut war sie als `x.replace(pref, "")` — also global. Bei einer URL, die
    das Suffix ein zweites Mal traegt (`cdn_hd.example/live_hd.flv`, oder ein
    `?sess_hd=1` am Ende), entstand daraus eine Zeichenkette, die in KEINER
    Kandidatenliste steht. Weil die Zuweisung an `pv in out` haengt, konnte
    dadurch nie eine falsche URL abgefragt werden — der Schaden war kein
    Fehlgriff, sondern eine ausgefallene Abkuerzung, und die faellt niemandem
    auf: es funktioniert ja, nur eben jedes Mal eine Runde langsamer.

    Geprueft wird die Sortierung direkt an `_varianten`, ohne Netz und ohne
    Ereignisschleife — seit W89 steht sie auf Modulebene, genau dafuer.
    """
    import nc.preflight as _pf

    alt_cache = dict(_pf._PREFLIGHT_CACHE)
    try:
        _pf._PREFLIGHT_CACHE.clear()

        # --- 1) DIE LISTE SELBST -------------------------------------
        u = "https://p.cdn/live_hd.flv?a=1"
        v = _pf._varianten(u)
        assert v[0] == u, \
            "das Original steht nicht an erster Stelle: %r" % (v,)
        assert "https://p.cdn/live.flv?a=1" in v, \
            "die nackte Variante fehlt in der Liste: %r" % (v,)
        assert len(v) == len(set(v)), \
            "die Liste enthaelt Dubletten: %r" % (v,)

        # Alle vier Suffixe, alle drei Endungen.
        for sfx in _pf.SUFFIXE:
            for endung, nackt in ((".flv", ".flv"),
                                  ("/index.m3u8", "/index.m3u8"),
                                  (".m3u8", ".m3u8")):
                quelle = "https://p.cdn/li" + sfx + endung
                assert ("https://p.cdn/li" + nackt) in _pf._varianten(quelle), \
                    "aus %r wird keine nackte Variante gebildet — der " \
                    "CDN-Quirk trifft alle vier Suffixe und beide " \
                    "Containerformen" % (quelle,)

        # --- 2) _ohne ERSETZT GEZIELT, NICHT GLOBAL ------------------
        # Der Kern des Befunds. Beide Erwartungen stehen bewusst als
        # Gegensatzpaar da: die gezielte Form laesst das zweite Vorkommen in
        # Ruhe, die globale hat es mitgenommen.
        doppelt = "https://cdn_hd.example/live_hd.flv"
        assert _pf._ohne(doppelt, "_hd") == "https://cdn_hd.example/live.flv", \
            "_ohne ersetzt global statt vor der Endung — der Hostname " \
            "verliert sein _hd mit: %r" % (_pf._ohne(doppelt, "_hd"),)
        query = "https://p.cdn/live_hd.flv?sess_hd=1"
        assert _pf._ohne(query, "_hd") == "https://p.cdn/live.flv?sess_hd=1", \
            "_ohne greift in den Abfrageteil: %r" % (_pf._ohne(query, "_hd"),)
        # Steht das Suffix nirgends an einer Endung, bleibt die URL, wie sie
        # ist — kein halb umgebauter Pfad.
        assert _pf._ohne("https://cdn_hd.example/live.flv", "_hd") == \
            "https://cdn_hd.example/live.flv", \
            "_ohne veraendert eine URL, in der das Suffix gar nicht an einer " \
            "Endung steht"

        # --- 3) DIE BEVORZUGUNG GREIFT AUCH DOPPELT -----------------
        for quelle, erwartet in (
                ("https://cdn_hd.example/live_hd.flv",
                 "https://cdn_hd.example/live.flv"),
                ("https://p.cdn/live_hd.flv?sess_hd=1",
                 "https://p.cdn/live.flv?sess_hd=1")):
            _pf._PREFLIGHT_CACHE["w"] = "_hd"
            v = _pf._varianten(quelle, "w")
            assert v[0] == erwartet, \
                "der gemerkte Suffix wird bei %r nicht bevorzugt — die " \
                "Liste beginnt mit %r statt %r. Genau hier lief die globale " \
                "Ersetzung ins Leere, und jede Aufnahme dieser Quelle " \
                "kostete wieder eine 404-Runde." % (quelle, v[0], erwartet)
            assert quelle in v, \
                "das Original faellt beim Umsortieren aus der Liste: %r" % (v,)

        # Ohne Merker bleibt das Original vorn — die Bevorzugung darf sich
        # nicht von selbst einschalten.
        _pf._PREFLIGHT_CACHE.clear()
        assert _pf._varianten("https://p.cdn/live_hd.flv")[0] == \
            "https://p.cdn/live_hd.flv", \
            "ohne gemerkten Suffix wird umsortiert"
        # Und ein Merker, der auf diese URL nicht passt, aendert nichts.
        _pf._PREFLIGHT_CACHE["w"] = "_uhd"
        assert _pf._varianten("https://p.cdn/live_hd.flv", "w")[0] == \
            "https://p.cdn/live_hd.flv", \
            "ein Merker fuer ein anderes Suffix sortiert trotzdem um"
        ok("W89: Suffix-Merker greift gezielt, auch bei doppeltem Vorkommen")
    finally:
        _pf._PREFLIGHT_CACHE.clear()
        _pf._PREFLIGHT_CACHE.update(alt_cache)


def _test_v42_w89_report_schneidet_vor_dem_maskieren():
    """v4.2-W89: der Videotitel im Profil-Report wird GESCHNITTEN und dann
    maskiert, nicht umgekehrt.

    Der Report geht als HTML an Telegram. `safe()` macht aus `&` ein `&amp;`,
    aus `<` ein `&lt;`; `short()` schneidet nach 50 Zeichen. In der falschen
    Reihenfolge — `short(safe(...), 50)`, so stand es da — kann der Schnitt
    mitten in einer Entitaet landen: aus `&amp;` wird `&am`, aus `&#39;` ein
    `&#3`. Telegram lehnt die GANZE Nachricht mit "can't parse entities" ab,
    nicht die eine Zeile. Der Betreiber bekommt dann keinen Report, und im Log
    steht ein Telegram-Fehler ohne Bezug zum Titel.

    Ein Titel mit 48 harmlosen Zeichen und einem `&` an Position 49 genuegt.
    Das ist kein konstruierter Randfall: TikTok-Titel tragen regelmaessig
    `&`, `<` und Apostrophe, und 50 Zeichen sind fuer einen Titel nichts.

    Zwei Zeilen weiter oben (SecUID) stand die Reihenfolge immer richtig —
    `safe(short(...))`. Der Vertrag haelt beide, damit die richtige nicht
    versehentlich der falschen angeglichen wird.
    """
    import nc.scoring as _sc

    basis = {"unique_id": "u", "nickname": "n", "user_id": "1"}

    # --- 1) DER SCHNITT DARF KEINE ENTITAET ZERTEILEN ---------------
    # 49 Zeichen, dann das kaufmaennische Und: nach `safe()` beginnt an
    # Position 49 die Entitaet `&amp;`, und ein Schnitt bei 50 zerlegt sie.
    boese = "A" * 49 + "&" + "B" * 20
    text = _sc.build_report(dict(basis, recent_videos=[
        {"desc": boese, "url": "https://t/1"}]), {})
    # Die Aussage: es gibt kein `&` ohne abschliessendes Semikolon. Genau das
    # ist die Form, die Telegram zurueckweist.
    import re as _r
    for treffer in _r.finditer(r"&", text):
        schwanz = text[treffer.start():treffer.start() + 10]
        assert _r.match(r"&(amp|lt|gt|quot|#x?[0-9A-Fa-f]+);", schwanz), \
            "im Report steht ein angeschnittenes &-Zeichen (%r) — Telegram " \
            "lehnt damit die ganze Nachricht mit 'can't parse entities' ab. " \
            "Genau das passiert, wenn erst maskiert und dann geschnitten " \
            "wird." % (schwanz,)

    # Und der Titel ist trotzdem gekuerzt worden — die Korrektur darf die
    # Laengengrenze nicht mitnehmen, sonst sprengt ein langer Titel die Zeile.
    assert "..." in text, \
        "ein 70 Zeichen langer Titel wird nicht gekuerzt: %r" % (text[-200:],)
    assert "B" * 20 not in text, \
        "der Titel wurde gar nicht geschnitten — das Ende ist noch da"

    # --- 2) UNMASKIERT BLEIBT NICHTS ------------------------------
    text = _sc.build_report(dict(basis, recent_videos=[
        {"desc": "<b>x</b> & y", "url": "https://t/2?a=1&b=2"}]), {})
    assert "<b>x</b>" not in text and "&lt;b&gt;x&lt;/b&gt;" in text, \
        "der Videotitel steht unmaskiert im Report: %r" % (text[-200:],)

    # --- 3) DER LEERE TITEL FAELLT AUF "Video" ZURUECK -------------
    # Bis W89 stand hier `short(safe(v.get("desc"), ""), 50) or 'Video'` —
    # ein Rueckfall, der nie griff: `short("")` liefert "Unbekannt", und das
    # ist wahr. Im Report stand deshalb "Unbekannt" statt "Video", und der
    # `or`-Zweig war toter Code.
    for leer in ("", None, "   "):
        text = _sc.build_report(dict(basis, recent_videos=[
            {"desc": leer, "url": "https://t/3"}]), {})
        assert ">Video</a>" in text, \
            "ein Video ohne Titel heisst nicht 'Video': %r — der Rueckfall " \
            "lief bis W89 auf 'Unbekannt', weil short('') das liefert" % (
                text[-120:],)
        assert "Unbekannt</a>" not in text, \
            "der Titel faellt auf 'Unbekannt' zurueck statt auf 'Video'"

    # --- 4) DIE SECUID-ZEILE BLEIBT RICHTIG HERUM -----------------
    text = _sc.build_report(dict(basis, sec_uid="&" * 40), {})
    for treffer in _r.finditer(r"&", text):
        schwanz = text[treffer.start():treffer.start() + 10]
        assert _r.match(r"&(amp|lt|gt|quot|#x?[0-9A-Fa-f]+);", schwanz), \
            "die SecUID-Zeile ist auf die falsche Reihenfolge umgestellt " \
            "worden: %r" % (schwanz,)
    ok("W89: Titel wird vor dem Maskieren geschnitten, Rueckfall ist 'Video'")


def _test_v42_w89_container_meldet_seinen_parse_fehler():
    """v4.2-W89: ein unlesbarer Container-Wert steht in `notes`.

    `compute_quality_score` hat vier Bloecke, und drei melden ihren
    Parse-Fehler (`video parse error`, `audio parse error`, `zero file size`).
    Der Container-Block hatte ein `except Exception: pass`. Eine Aufnahme
    verlor damit bis zu 10 von 100 Punkten, und in `notes` stand nichts,
    woran der Betreiber das haette sehen koennen — die Aufschluesselung im
    Deck erklaerte die Zahl daneben nicht mehr.

    Dazu: die beiden Zeilen, die `format.bit_rate` lasen und im Treffer
    `pass` machten, sind heraus. Sie vergaben keinen Punkt, konnten aber bei
    einem unlesbaren Wert die ganze Container-Bewertung in den except-Zweig
    reissen und die Dauer-Punkte mitnehmen. Ein Lesevorgang, der nur
    schiefgehen kann, ist schlechter als keiner — und genau das wird hier
    gemessen: ein kaputter `bit_rate` kostet KEINE Punkte mehr.
    """
    import nc.scoring as _sc

    def _v():
        return {"codec_type": "video", "height": 1080, "codec_name": "h264",
                "r_frame_rate": "30/1"}

    # --- 1) EIN KAPUTTER bit_rate KOSTET NICHTS MEHR --------------
    gut = _sc.compute_quality_score(
        {"streams": [_v()], "format": {"duration": "100"}}, 0, 100.0)
    kaputt = _sc.compute_quality_score(
        {"streams": [_v()], "format": {"duration": "100", "bit_rate": "x"}},
        0, 100.0)
    assert gut["components"]["container"] == 15, \
        "der tadellose Container bekommt %r statt 15" % (
            gut["components"]["container"],)
    assert kaputt["components"]["container"] == 15, \
        "ein unlesbarer bit_rate kostet %r statt 0 Punkte — die beiden " \
        "folgenlosen Leszeilen sind wieder drin und reissen die " \
        "Dauer-Bewertung mit" % (15 - kaputt["components"]["container"],)
    assert "container parse error" not in kaputt["notes"], \
        "ein bit_rate, der gar nicht mehr gelesen wird, erzeugt eine " \
        "Notiz: %r" % (kaputt["notes"],)

    # --- 2) EIN ECHTER PARSE-FEHLER MELDET SICH -------------------
    class _Krumm:
        """Wirft beim Lesen von `duration` — so wie ein ffprobe-Ergebnis,
           das nicht das ist, was der Code erwartet."""

        def get(self, name, vorgabe=None):
            if name == "duration":
                raise TypeError("Attrappe: kein Wert")
            return vorgabe

        def __bool__(self):
            return True

    r = _sc.compute_quality_score({"streams": [_v()], "format": _Krumm()},
                                  0, 100.0)
    assert "container parse error" in r["notes"], \
        "ein unlesbarer Container meldet sich nicht in notes: %r — bis W89 " \
        "war das ein `except: pass`, und die fehlenden 10 Punkte hatten " \
        "keine Begruendung" % (r["notes"],)
    assert r["components"]["container"] == 5, \
        "der Container behaelt bei einem Parse-Fehler %r statt der 5 Punkte " \
        "fuer 'vorhanden'" % (r["components"]["container"],)
    assert r["score"] == sum(r["components"].values()), \
        "der Score ist nicht mehr die Summe seiner Teile"
    ok("W89: Container-Parse-Fehler steht in notes, bit_rate kostet nichts")


def _test_v42_w89_verdrahtungsfehler_bleibt_laut():
    """v4.2-W89: eine fehlende `configure(...)` bricht die Pruefung ab, statt
    als "kein Proxy" durchzulaufen.

    `nc.tiktokcheck._Conf.__missing__` wirft ausdruecklich laut, mit dem Text
    "ist nicht konfiguriert — configure(...) fehlt im Startpfad von bot.py".
    Der Docstring nennt den Grund: ein fehlender Startwert ist ein
    Verdrahtungsfehler im Bot, kein Datenfehler.

    Genau dieser RuntimeError lief bis W89 in ein `except Exception: proxy =
    None`. Eine fehlende `configure`-Zeile sah damit aus wie "Proxy nicht
    verfuegbar": die Pruefung lief ungeproxyt weiter, von der Server-IP, die
    TikTok blockt — und weil das Modul bewusst konservativ ist, kam
    "unknown / kein eindeutiges Signal" heraus. Der Betreiber sah ein
    TikTok-Problem, wo ein Startproblem war. Der lauteste Fehler des Moduls
    war der unsichtbarste.

    Der zweite Teil: `st` traegt im Fehlerfall den wirklich gelesenen Status.
    Dort stand eine harte 0, obwohl der Status zu diesem Zeitpunkt schon
    gelesen sein KANN — bricht die Verbindung nach den Kopfzeilen und vor dem
    Rumpf ab, wurde aus einem echten 200 eine gemeldete 0. Damit war nicht
    mehr unterscheidbar, ob TikTok geantwortet hat oder ob nie eine
    Verbindung zustande kam, und genau diese Unterscheidung entscheidet, ob
    die Oberflaeche ein Loeschen anbieten darf.
    """
    import asyncio as _asyncio
    import sys as _sys

    import nc.tiktokcheck as _tc

    class _Antwort:
        def __init__(self, status, rumpf=None, wirft=None):
            self.status = status
            self._rumpf = rumpf or ""
            self._wirft = wirft

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

        async def text(self, errors=None):
            if self._wirft:
                raise self._wirft
            return self._rumpf

    class _Sitzung:
        def __init__(self):
            self.antwort = _Antwort(200, "")

        def get(self, url, **k):
            return self.antwort

    class _FalscherAiohttp:
        @staticmethod
        def ClientTimeout(**k):
            return None

    sitzung = _Sitzung()

    async def _hole():
        return sitzung

    async def _waehle(username=None):
        return "http://proxy:1"

    alt_aio = _sys.modules.get("aiohttp")
    alt_conf = dict(_tc._conf)
    alt_rand = _tc.get_random_proxy
    try:
        _sys.modules["aiohttp"] = _FalscherAiohttp
        _tc.get_random_proxy = lambda: None

        # --- 1) GAR NICHT VERDRAHTET: ES MUSS WEHTUN ----------------
        _tc._conf.clear()
        fehler = None
        try:
            _asyncio.run(_tc.account_exists("peter"))
        except RuntimeError as e:
            fehler = e
        assert fehler is not None, \
            "eine fehlende configure(...) laeuft durch, statt zu werfen — " \
            "dann prueft der Bot ungeproxyt von der geblockten Server-IP " \
            "und meldet das Ergebnis als TikTok-Problem"
        assert "nicht konfiguriert" in str(fehler) \
            and "configure" in str(fehler), \
            "der Verdrahtungsfehler nennt seinen Grund nicht: %r" % (fehler,)

        # Fehlt nur EINER der drei Startwerte, gilt dasselbe — sonst haengt es
        # davon ab, in welcher Reihenfolge sie gebraucht werden.
        for fehlt in ("pick_proxy", "get_ai_session", "live_resolver_headers"):
            _tc.configure(get_ai_session=_hole, pick_proxy=_waehle,
                          live_resolver_headers={})
            _tc._conf.pop(fehlt)
            # Kein `assert False` im try: `python -O` entfernt es (ruff B011),
            # und ein Vertrag, der unter -O nichts mehr prueft, ist keiner.
            gefangen = None
            try:
                _asyncio.run(_tc.account_exists("peter"))
            except RuntimeError as e:
                gefangen = e
            assert gefangen is not None, \
                "der fehlende Startwert %r wird verschluckt" % (fehlt,)
            assert fehlt in str(gefangen), \
                "der Fehler nennt den fehlenden Wert %r nicht: %r" % (
                    fehlt, gefangen)

        # --- 2) EINE GESCHEITERTE PROXY-WAHL IST KEIN STARTFEHLER ---
        # Sie darf still auf den Zufallsproxy und dann auf "ohne" zurueck —
        # das ist ein Betriebsfall, und die Pruefung soll trotzdem laufen.
        async def _kaputt(username=None):
            raise OSError("Attrappe: Proxy-Liste weg")

        _tc.configure(get_ai_session=_hole, pick_proxy=_kaputt,
                      live_resolver_headers={})
        sitzung.antwort = _Antwort(404)
        zustand, status, _ = _asyncio.run(_tc.account_exists("peter"))
        assert (zustand, status) == ("gone", 404), \
            "eine gescheiterte Proxy-Wahl reisst die ganze Pruefung mit: " \
            "%r/%r" % (zustand, status)

        # --- 3) DER STATUS UEBERLEBT EINEN ABBRUCH IM RUMPF ---------
        _tc.configure(get_ai_session=_hole, pick_proxy=_waehle,
                      live_resolver_headers={})
        sitzung.antwort = _Antwort(200, wirft=OSError("Attrappe: Verbindung weg"))
        zustand, status, grund = _asyncio.run(_tc.account_exists("peter"))
        assert zustand == "unknown", \
            "ein Abbruch beim Lesen macht aus der Pruefung ein Ergebnis: %r" \
            % (zustand,)
        assert status == 200, \
            "der gelesene HTTP-Status geht verloren (%r statt 200) — dann " \
            "ist 'TikTok hat geantwortet' nicht mehr von 'keine Verbindung' " \
            "zu unterscheiden, und genau daran haengt, ob die Oberflaeche " \
            "ein Loeschen anbietet" % (status,)
        assert "fehlgeschlagen" in grund, \
            "der Grund nennt den Abbruch nicht: %r" % (grund,)

        # Und ohne jede Verbindung bleibt es bei 0 — die 0 heisst "nie
        # angekommen", und das muss sie weiter heissen.
        class _Tot:
            def get(self, url, **k):
                raise OSError("Attrappe: kein Netz")

        async def _tot():
            return _Tot()

        _tc.configure(get_ai_session=_tot, pick_proxy=_waehle,
                      live_resolver_headers={})
        zustand, status, _ = _asyncio.run(_tc.account_exists("peter"))
        assert (zustand, status) == ("unknown", 0), \
            "ohne jede Antwort muss der Status 0 sein: %r/%r" % (
                zustand, status)
        ok("W89: fehlende Verdrahtung wirft, der HTTP-Status ueberlebt")
    finally:
        if alt_aio is None:
            _sys.modules.pop("aiohttp", None)
        else:
            _sys.modules["aiohttp"] = alt_aio
        _tc.get_random_proxy = alt_rand
        _tc._conf.clear()
        _tc._conf.update(alt_conf)


def _test_v42_w89_kopie_wird_zurueckgenommen():
    """v4.2-W89: scheitert der Archiv-Eintrag, ist die Kopie wieder weg.

    `_archiviere_eine` kopiert erst und schreibt dann die Datenbankzeile —
    notwendig in dieser Reihenfolge, weil die Zeile die Groesse der Kopie
    traegt. Bis W89 hatte das einen DAUERSCHADEN im Fehlerfall:

    Schlug der INSERT fehl (UNIQUE-Verletzung, Platte voll, Datenbank weg),
    blieb die Kopie ohne Zeile im Archiv liegen. Beim naechsten Lauf griff
    dann `os.path.exists(target)` und zaehlte `skipped += 1`. Die Aufnahme
    war damit **nie wieder** archivierbar: eine Datei, die es gibt, die in
    keiner Ansicht auftaucht und die kein Lauf mehr einsammelt. Der Betreiber
    sieht nur eine Regel, die dauerhaft "uebersprungen" meldet, und keinen
    Grund dafuer — es faellt nichts, es wird nur nichts mehr.

    Der Vertrag prueft deshalb nicht bloss "der Fehler wird gemeldet",
    sondern die Wiederholbarkeit: nach dem Fehlschlag muss derselbe Aufruf
    beim naechsten Versuch GELINGEN.

    Dazu der Fall, in dem auch die Ruecknahme misslingt. Dann liegt die Datei
    wirklich im Weg, und das MUSS im Log stehen — mit Pfad, denn der
    Betreiber muss sie von Hand wegnehmen. Ein `except OSError: pass` waere
    hier zwar ein Aufraeumpfad, aber keiner, dessen Fehlschlag bedeutungslos
    ist: die Regel aus CLAUDE.md endet genau an dieser Unterscheidung.
    """
    import shutil as _sh

    import nc.archiverules as A
    from nc import sicherpfad as _sp

    class _Log:
        def __init__(self):
            self.zeilen = []

        def _sammle(self, stufe):
            def _f(fmt, *a):
                self.zeilen.append((stufe, str(fmt) % a if a else str(fmt)))
            return _f

        def __getattr__(self, name):
            return self._sammle(name)

    heim = _ph.verzeichnis()
    quelle = os.path.join(heim, "quelle")
    archiv = os.path.join(heim, "archiv")
    os.makedirs(quelle)
    os.makedirs(archiv)
    src_datei = os.path.join(quelle, "aufnahme.mp4")
    with open(src_datei, "wb") as f:
        f.write(b"0" * 4096)

    alt_add, alt_log = A.add_archive_entry, A.log
    schrift = _Log()
    try:
        A.log = schrift

        # --- 1) DER GUTE FALL: KOPIE UND EINTRAG ---------------------
        gesehen = []
        A.add_archive_entry = lambda **kw: gesehen.append(kw) or 1
        assert A._archiviere_eine(src_datei, archiv, "R", 7) is True, \
            "der gute Fall meldet keinen Erfolg"
        ziel = os.path.join(archiv, "aufnahme.mp4")
        assert os.path.isfile(ziel), "die Kopie fehlt"
        assert gesehen and gesehen[0]["size"] == 4096, \
            "der Eintrag traegt nicht die Groesse der Kopie: %r" % (gesehen,)
        assert gesehen[0]["source_url"] == "recording/7", \
            "ohne Rueckverweis ist der Eintrag nicht zuzuordnen: %r" % (
                gesehen,)

        # Zweiter Lauf: schon da, also nicht ueberschreiben.
        del gesehen[:]
        assert A._archiviere_eine(src_datei, archiv, "R", 7) is False, \
            "eine bereits archivierte Datei wird erneut eingetragen"
        assert not gesehen, "der zweite Lauf schreibt einen zweiten Eintrag"
        os.remove(ziel)

        # --- 1b) SCHRITT 1 SCHEITERT: NICHTS LIEGT HERUM ------------
        # Die Quelle ist weg (die Aufnahme wurde zwischen Regel-Lauf und
        # Kopie geloescht) oder das Ziel laesst sich nicht bilden. Beides
        # darf den Lauf nicht abbrechen — die naechste Aufnahme kann
        # gelingen — und es darf keine halbe Kopie hinterlassen.
        del gesehen[:]
        del schrift.zeilen[:]
        assert A._archiviere_eine(os.path.join(quelle, "gibt-es-nicht.mp4"),
                                  archiv, "R", 3) is False, \
            "eine verschwundene Quelle wird als archiviert gemeldet"
        assert not gesehen, \
            "zu einer nicht kopierten Datei wird ein Eintrag geschrieben: " \
            "%r — der zeigt dann auf eine Datei, die es nicht gibt" % (gesehen,)
        assert os.listdir(archiv) == [], \
            "im Archiv liegt etwas, obwohl die Kopie scheiterte: %r" % (
                os.listdir(archiv),)
        assert any(stufe == "warning" for stufe, _ in schrift.zeilen), \
            "eine gescheiterte Kopie meldet sich nicht: %r" % (
                schrift.zeilen,)

        # --- 2) DER EINTRAG SCHEITERT: KOPIE MUSS WEG ---------------
        def _wirft(**kw):
            raise RuntimeError("Attrappe: UNIQUE constraint failed")

        A.add_archive_entry = _wirft
        del schrift.zeilen[:]
        assert A._archiviere_eine(src_datei, archiv, "R", 7) is False, \
            "ein gescheiterter Eintrag wird als Erfolg gemeldet"
        assert not os.path.exists(ziel), \
            "die Kopie liegt nach dem gescheiterten Eintrag noch im Archiv " \
            "— beim naechsten Lauf greift dann exists() und die Aufnahme " \
            "wird NIE WIEDER archiviert"
        assert any(stufe == "error" for stufe, _ in schrift.zeilen), \
            "der gescheiterte Eintrag meldet sich nicht auf error: %r" % (
                schrift.zeilen,)

        # Und jetzt der Punkt: es ist wiederholbar.
        A.add_archive_entry = lambda **kw: gesehen.append(kw) or 1
        del gesehen[:]
        assert A._archiviere_eine(src_datei, archiv, "R", 7) is True, \
            "nach einem gescheiterten Eintrag laesst sich die Aufnahme nicht " \
            "erneut archivieren — genau das war der Dauerschaden"
        assert os.path.isfile(ziel) and gesehen, "der zweite Versuch trug nicht"
        os.remove(ziel)

        # --- 3) AUCH DIE RUECKNAHME SCHEITERT: LAUT, MIT PFAD -------
        A.add_archive_entry = _wirft
        alt_remove = A.os.remove

        def _remove_kaputt(p):
            raise OSError("Attrappe: Datei gesperrt")

        del schrift.zeilen[:]
        A.os.remove = _remove_kaputt
        try:
            assert A._archiviere_eine(src_datei, archiv, "R", 9) is False
        finally:
            A.os.remove = alt_remove
        fehler = [t for stufe, t in schrift.zeilen if stufe == "error"]
        assert len(fehler) == 2, \
            "eine misslungene Ruecknahme meldet sich nicht zusaetzlich: %r" \
            % (schrift.zeilen,)
        assert any(ziel in t for t in fehler), \
            "die Meldung nennt den Pfad nicht, den der Betreiber von Hand " \
            "wegnehmen muss: %r" % (fehler,)
        os.remove(ziel)

        # --- 4) DER PFAD-RIEGEL: NICHTS LANDET AUSSERHALB ----------
        # Der Zielname entsteht aus `recordings.filepath` — einem Wert, den
        # der Recorder aus einem TikTok-Nutzernamen baut.
        #
        # Der Windows-Pfad ist der Fall, der zaehlt: auf Linux ist "\\" ein
        # ganz normales Zeichen, `os.path.basename` nimmt davon NICHTS weg.
        # Ein roher `os.path.join(archive_dir, os.path.basename(src))` legt
        # damit eine Datei an, deren Name Trenner traegt — und auf einem
        # Dateisystem, das sie als solche liest, liegt sie ausserhalb.
        #
        # Wichtig: die Quelldatei muss unter diesem Namen WIRKLICH existieren,
        # sonst scheitert `copy2` vorher und der Riegel wird gar nicht
        # belastet. Beim ersten Entwurf dieses Vertrags war genau das der
        # Fall — die Mutationsprobe "Pfad-Riegel entfernt" entwischte.
        A.add_archive_entry = lambda **kw: gesehen.append(kw) or 1
        for boese in ("..\\..\\etc\\passwd.mp4", "  leer  .mp4",
                      "...mp4"):
            p = os.path.join(quelle, boese)
            with open(p, "wb") as f:
                f.write(b"0" * 512)
            assert os.path.isfile(p), \
                "die Attrappen-Quelle %r liess sich nicht anlegen — dann " \
                "prueft der Abschnitt den Riegel nicht" % (boese,)
            del gesehen[:]
            A._archiviere_eine(p, archiv, "R", 1)
            for name in os.listdir(archiv):
                assert "/" not in name and "\\" not in name \
                    and ".." not in name, \
                    "der Zielname traegt einen Pfadanteil: %r — ohne " \
                    "sicher_join schreibt der naechste Recorder-Name " \
                    "dorthin, wohin er zeigt" % (name,)
                ziel_p = os.path.join(archiv, name)
                assert _sp.unter(archiv, ziel_p), \
                    "%r liegt nicht unter dem Archivverzeichnis" % (ziel_p,)
                os.remove(ziel_p)
            for e in gesehen:
                assert _sp.unter(archiv, e["filepath"]), \
                    "der Eintrag zeigt aus dem Archiv heraus: %r" % (e,)
        ok("W89: gescheiterter Eintrag nimmt die Kopie zurueck und bleibt "
           "wiederholbar")
    finally:
        A.add_archive_entry = alt_add
        A.log = alt_log
        _sh.rmtree(heim, ignore_errors=True)


def _test_v42_w89_stats_json_meldet_laut():
    """v4.2-W89: ein fehlgeschlagenes `stats.json` steht auf error, nicht auf
    debug — und der neue Preflight-Zaehler erreicht die Zeitreihen.

    **stats.json.** `_stats_loop` schreibt alle fuenf Minuten die Datei, aus
    der die oeffentliche Seite ihr Lagebild zieht. Der Fehlerfall stand auf
    `log.debug`, und fuer den Betreiber ist ein Fehlerpfad auf debug dasselbe
    wie `pass` — genau die Klasse, die tools/blindstellen.py misst. Faellt das
    Schreiben dauerhaft aus (Platte voll, Rechte, Pfad weg), bleibt das
    Lagebild leer und NICHTS im Log sagt warum. Zwei Zeilen darueber macht
    dieselbe Schleife es richtig: `usage.flush` geht ueber `_loop_fehler`,
    mit genau dieser Begruendung im Kommentar.

    Gedrosselt muss es sein: 288 gleiche Zeilen am Tag liest niemand, und
    eine unlesbare Warnung ist so gut wie keine. Und der Erfolgspfad muss die
    Drossel zuruecksetzen, sonst bleibt ein wiederkehrender Ausfall bis zu 15
    Minuten unsichtbar (die Lehre aus W81).

    **Der gestoert-Zaehler.** `nc.preflight` unterscheidet seit W89 "alle
    Varianten sauber 404" (tot) von "keine Variante geantwortet" (gestoert).
    Ohne die Zeitreihe in brain_bridge waere die Unterscheidung blind —
    und gerade sie ist die interessante: steigt `gestoert` und nicht `dead`,
    liegt es am Weg nach aussen, nicht an den Quellen.

    Geprueft wird ueber `rumpf_ab`, nicht ueber ein festes Fenster: CLAUDE.md
    nennt `src[i:i + 3000]` namentlich als Bruchstelle, und in W62 hat sie
    zugeschlagen.
    """
    src = open("bot.py", encoding="utf-8").read()

    i = src.find("async def _stats_loop():")
    assert i > 0, "_stats_loop ist nicht mehr zu finden"
    rumpf = rumpf_ab(src, i)

    assert 'log.debug("stats.json' not in rumpf, \
        "das fehlgeschlagene Schreiben von stats.json steht wieder auf " \
        "debug — in einem INFO- oder ERROR-Log erscheint das NIE, und die " \
        "oeffentliche Seite bleibt ohne Begruendung leer"
    assert '_nc_meldetakt.melden(' in rumpf and '"stats-json"' in rumpf, \
        "die Meldung laeuft nicht ueber nc.meldetakt — ungedrosselt stehen " \
        "288 gleiche Zeilen am Tag im Log, und die liest niemand"
    assert 'log.error("stats.json' in rumpf, \
        "die Meldung steht nicht auf error: %r" % (rumpf[:400],)
    assert '_nc_meldetakt.zuruecksetzen("stats-json")' in rumpf, \
        "der Erfolgspfad setzt die Drossel nicht zurueck — ein Ausfall, der " \
        "sich behebt und wiederkehrt, bleibt dann bis zu 15 Minuten " \
        "unsichtbar (W81)"
    # Die Meldung muss dem Betreiber sagen, was zu tun ist. "HTTP 403" allein
    # hat in diesem Projekt schon einmal wochenlang niemandem geholfen.
    for wort in ("Verzeichnis", "Rechte"):
        assert wort in rumpf, \
            "die Meldung nennt keine Abhilfe (%r fehlt)" % (wort,)

    # --- Der gestoert-Zaehler in der Bruecke ---------------------------
    bruecke = open("brain_bridge.py", encoding="utf-8").read()
    j = bruecke.find('_ctx.get("preflight_stats")')
    assert j > 0, "die Preflight-Zeitreihen sind nicht mehr zu finden"
    # Die Schluesselliste selbst ist der Anker, und gelesen wird bis zum
    # Zeilenende — KEIN Fenster fester Laenge. Genau das zaehlt
    # tools/vertragscheck.py, und beim ersten Entwurf dieses Vertrags stand
    # hier `bruecke[j:j + 600]`: die Sperre hat es gefangen.
    i2 = bruecke.find("for k in (", j)
    assert i2 > j, \
        "die Schluesselliste der Preflight-Zeitreihen ist nicht mehr zu " \
        "finden — sie stand direkt nach _ctx.get(\"preflight_stats\")"
    zeile = bruecke[i2:bruecke.find("\n", i2)]
    assert '"gestoert"' in zeile, \
        "der gestoert-Zaehler wird nicht als Zeitreihe gespiegelt — dann " \
        "ist im Metrik-Panel nicht zu sehen, wie oft der Preflight gar " \
        "nichts gemessen hat: %r" % (zeile,)
    for k in ('"ok"', '"fallback"', '"dead"'):
        assert k in zeile, \
            "die bestehende Zeitreihe %s ist verschwunden: %r" % (k, zeile)

    # Und der Zaehler muss im Modul auch existieren, sonst spiegelt die
    # Bruecke einen Namen, den niemand fuellt.
    import nc.preflight as _pf
    assert "gestoert" in _pf._PREFLIGHT_STATS, \
        "nc.preflight fuehrt den gestoert-Zaehler nicht"
    ok("W89: stats.json meldet laut und gedrosselt, gestoert erreicht die "
       "Zeitreihen")


def _test_v42_w101_deck_kann_hoerbar_alarmieren():
    """Das Deck hatte drei Meldewege und keinen hoerbaren.

    Toast (nur sichtbar, wenn man hinsieht), Benachrichtigungs-Center (nur
    aufgeklappt) und Browser-Push (nur bei verstecktem Tab). Genau der Fall,
    fuer den ein Ton da ist — der Betreiber sitzt im Control-Tab und schaut
    weg —, war der einzige ohne Meldung. Gemeldet am 01.10.: „im control
    panel Tab immer noch keinen Button um den Ton zu aktivieren".

    Es MUSS ein Knopf sein: Browser blockieren WebAudio ohne Nutzergeste. Ein
    automatisch bewaffneter Ton waere das Schlimmste von beidem — das Deck
    haelte sich fuer alarmierend und es kaeme nichts heraus.
    """
    import io as _io
    import os as _os

    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    deck = _io.open(_os.path.join(wurzel, "templates", "dashboard.html"),
                    encoding="utf-8").read()

    # ── (1) ZWEI KNOEPFE, EIN ZUSTAND. Der im Control-Tab (danach wurde
    # gefragt) und der neben "Push aktivieren" — derselbe Zweck gehoert
    # nebeneinander. Beide tragen `data-ton-knopf`, damit GENAU EINE Funktion
    # die Beschriftung schreibt; zwei eigene Texte driften auseinander, wie
    # die zwei Ausschlusslisten im Installer (W100) und die zwei
    # Ordner-Aufloesungen (W98) gezeigt haben.
    assert deck.count("data-ton-knopf") >= 3, \
        "es gibt nicht beide Knoepfe plus den gemeinsamen Auffrischer"
    assert 'class="ton-bar"' in deck, "die Alarmzeile fehlt im On-Air-Deck"
    # Der Knopf im Control-Tab sitzt im On-Air-Deck, nicht irgendwo: zwischen
    # `id="ra_deck"` und dem naechsten Block dieser Ansicht.
    i_deck = deck.index('id="ra_deck"')
    i_tun = deck.index('id="tun_panel"', i_deck)
    assert "data-ton-knopf" in deck[i_deck:i_tun], \
        "der Ton-Knopf steht nicht im On-Air-Deck des Control-Tabs"

    # ── (2) DIE DROSSEL HAENGT AM PAAR (Schwere, Zeit), nicht am Kanal. Ein
    # Ereignissturm darf den Fehler-Piep nicht hinter einem Info-Piep
    # verschlucken — das ist die Lehre aus W97 (nc/meldetakt.py), eine
    # Schicht weiter.
    assert "_TON_RUHE" in deck and "_tonZuletzt" in deck
    i_ruhe = deck.index("const _TON_RUHE=")
    ruhe = deck[i_ruhe:deck.index("\n", i_ruhe)]
    assert "info:" in ruhe and "err:" in ruhe, \
        "eine Ruhezeit fuer alles drosselt den Fehler-Piep mit weg: %s" % ruhe

    # ── (3) EIN SUSPENDIERTER KONTEXT SPIELT NICHTS UND WIRFT NICHT. Die
    # Pruefung muss VOR dem Stempeln der Drossel stehen, sonst setzt ein
    # Piep, den niemand gehoert hat, die Ruhezeit — und das naechste echte
    # Ereignis bleibt bis zu vier Sekunden stumm. Genau die Klasse Fehler,
    # die dieses Projekt sammelt: es faellt nichts, es wird nur nichts.
    i_p = deck.index("function ncPieps(")
    rumpf = deck[i_p:deck.index("\nfunction ncTonKnopfAuffrischen(", i_p)]
    assert "ctx.state!=='running'" in rumpf, \
        "ncPieps piept in einen suspendierten Kontext und merkt es nicht"
    assert rumpf.index("ctx.state!=='running'") < rumpf.index("_tonZuletzt[art]=jetzt"), \
        "die Drossel wird gestempelt, bevor klar ist, dass ueberhaupt ein " \
        "Ton herauskam — ein unhoerbarer Piep macht den naechsten stumm"
    # ── (3b) KEIN ASSET, KEIN REQUEST: der Ton entsteht im Browser. Eine
    # mitgelieferte Audiodatei muesste ins Archiv, durch jede CSP, und waere
    # im Offline-Deck weg. Geprueft wird der RUMPF, nicht die Datei — ein
    # `new Audio(...)` gibt es im Deck berechtigt (Piper-Probe).
    assert "createOscillator" in rumpf, "der Ton wird nicht synthetisiert"
    assert "new Audio" not in rumpf and "fetch(" not in rumpf, \
        "der Signalton holt eine Datei — damit haengt er am Ausliefern"

    # ── (4) DER SCHALTER MELDET DEN ZUSTAND, NICHT DIE ABSICHT. `resume()`
    # darf nicht als Erfolg gelten: bleibt der Kontext suspendiert, ist der
    # Ton AUS, und der Betreiber muss das erfahren statt sich auf einen
    # Alarm zu verlassen, den es nicht gibt. Dieselbe Lehre wie bei der
    # Bindung in W84 ("die WIRKLICHE Adresse nennen, nicht die gewuenschte").
    i_u = deck.index("async function ncTonUmschalten(")
    um = deck[i_u:deck.index("\nfunction sseStart(", i_u)]
    assert "ctx.state!=='running'" in um, \
        "ncTonUmschalten nimmt das Rufen von resume() fuer das Ergebnis"
    assert um.index("ctx.state!=='running'") < um.index("_tonAn=true"), \
        "der Ton gilt als an, bevor nachgesehen wurde, ob er laeuft"
    assert "Autoplay" in um, \
        "die Fehlzeile nennt keine Abhilfe — dasselbe wie ein blankes 'HTTP 403'"

    # ── (5) DER TON HAENGT AN DEMSELBEN ZWEIG WIE TOAST UND NOTIFICATION.
    # Haengt er davor, piept es fuer jedes Ereignis, das das Deck selbst als
    # unwichtig einstuft — inklusive jeder Chat-Zeile.
    i_s = deck.index("_sse.onmessage = ev=>{")
    sse = deck[i_s:deck.index("\nsseStart();", i_s)]
    assert "ncPieps(" in sse, "der Ton ist nicht an den Ereignisstrom gehaengt"
    assert sse.index("const interesting") < sse.index("ncPieps("), \
        "es piept vor der Interessant-Pruefung — also auch fuer Chat-Zeilen"

    # ── (6) DER KNOPF IM CONTROL-TAB ENTSTEHT ERST BEIM BAUEN DER ANSICHT.
    # Ohne Auffrischen danach traegt er nach einem Neuladen "Ton aktivieren",
    # obwohl der Ton an ist — ein Schalter mit falschem Zustand ist
    # schlimmer als keiner.
    i_v = deck.index("VIEW_LOADERS.restream = async function(){")
    i_e = deck.index("window._rsAutoRefresh=setInterval", i_v)
    assert "ncTonKnopfAuffrischen()" in deck[i_v:i_e], \
        "nach dem Bauen des Control-Tabs frischt niemand den Ton-Knopf auf"
    # Und beim Start, fuer den Knopf im Benachrichtigungs-Center.
    assert "sseStart(); _bellRender(); ncTonKnopfAuffrischen();" in deck, \
        "beim Start steht der Knopf auf der Vorgabe statt auf dem Zustand"

    ok("W101: der Control-Tab hat einen Knopf fuer den Signalton")
    ok("W101: beide Knoepfe lesen EINEN Zustand (kein Textdrift)")
    ok("W101: ein unhoerbarer Piep stempelt die Drossel nicht")
    ok("W101: der Schalter meldet den Kontext-Zustand, nicht das resume()")
    ok("W101: es piept nur fuer Ereignisse, die auch einen Toast wert sind")


def _test_v42_w101_krypto_block_bleibt_stehen():
    """Eine fehlende Adresse soll nur ihre Zeile kosten, nicht den Block.

    W99 hat den AUSFALL sichtbar gemacht und den leeren Fall weiter still
    versteckt. Fuer den Betreiber sah eine zugeklappte Seite damit immer noch
    aus wie ein Fehler — und der Unterschied liegt in einer Zeile `.env`.
    Gemeldet am 01.10.: „falls in der env eine kryptowallet Adresse fehlen
    sollte, sollte diese nur ausgeblendet werden, der krypto donation Block
    soll trotzdem angezeigt werden".
    """
    import io as _io
    import os as _os
    from nc import crypto as C

    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    alt = {n: _os.environ.get(n) for n in C.erwartete_namen()}
    try:
        # ── (1) TEILKONFIGURATION: eine gesetzt, fuenf nicht. Die eine
        # erscheint, die fuenf fallen als Zeile weg — und `fehlend` SAGT,
        # welche. Bis W101 trug `gesucht` bei einem Treffer die leere Liste,
        # womit "eine von sechs" genauso aussah wie "alle sechs".
        for n in C.erwartete_namen():
            _os.environ.pop(n, None)
        _os.environ["DONATION_BTC_ADDRESS"] = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4"
        teil = C.snapshot(fetch_live=False)
        assert [a["coin"] for a in teil["addresses"]] == ["btc"], teil
        assert teil["grund"] == "", "eine gesetzte Adresse ist kein Fehlerfall"
        assert set(teil["fehlend"]) == set(C.erwartete_namen()) - {"DONATION_BTC_ADDRESS"}, \
            "fehlend nennt die leeren Namen nicht: %r" % (teil["fehlend"],)
        assert len(teil["gesucht"]) == len(C.erwartete_namen()), \
            "gesucht ist bei einem Treffer wieder leer — eine " \
            "Teilkonfiguration ist damit nicht von einer vollen zu trennen"

        # ── (2) ALLE GESETZT: nichts fehlt. Eine `fehlend`-Liste, die nie
        # leer wird, meldet nur Rauschen.
        for n in C.erwartete_namen():
            _os.environ[n] = "x" + n[-6:]
        voll = C.snapshot(fetch_live=False)
        assert voll["fehlend"] == [], voll["fehlend"]
        assert len(voll["addresses"]) == len(C.erwartete_namen())

        # ── (3) KEINE GESETZT: Grund UND beide Listen.
        for n in C.erwartete_namen():
            _os.environ.pop(n, None)
        leer = C.snapshot(fetch_live=False)
        assert leer["grund"] == "keine_adresse_konfiguriert", leer
        assert set(leer["fehlend"]) == set(C.erwartete_namen()), leer

        # ── (3b) LEERRAUM IST KEINE ADRESSE. Eine Variable, die in der .env
        # steht und nichts enthaelt, darf keine leere Kachel erzeugen.
        _os.environ["DONATION_ETH_ADDRESS"] = "   "
        blank = C.snapshot(fetch_live=False)
        assert blank["addresses"] == [], blank
        assert "DONATION_ETH_ADDRESS" in blank["fehlend"], \
            "eine Variable mit Leerraum gilt als gesetzt"
    finally:
        for n, v in alt.items():
            if v is None:
                _os.environ.pop(n, None)
            else:
                _os.environ[n] = v

    # ── (4) DIE SEITE VERSTECKT DEN BLOCK IN KEINEM ZWEIG MEHR. Geprueft
    # wird die staerkere Aussage: im ganzen Krypto-Abschnitt kommt kein
    # `hidden=true` mehr vor. Eine Zusicherung auf einen einzelnen Zweig
    # waere gruen, sobald die Regression einen anderen trifft.
    seite = _io.open(_os.path.join(wurzel, "website", "lafap_index.html"),
                     encoding="utf-8").read()
    kb = seite.index("// v4.0-W94: Krypto-Spendenadressen")
    ke = seite.index("// v4.0-W72: Plattform-Chips", kb)
    krypto = seite[kb:ke]
    assert "hidden=true" not in krypto.replace(" ", ""), \
        "ein Zweig versteckt den Krypto-Block wieder"
    assert krypto.count("cw.hidden=false") >= 1
    # Und die drei Lagen sagen DREI verschiedene Saetze — sonst ist der Block
    # zwar da und die Auskunft wieder dieselbe fuer alles.
    assert "keine Krypto-Adresse hinterlegt" in krypto, \
        "der leere Fall sagt nicht, dass nichts hinterlegt ist"
    assert "nicht abrufbar" in krypto, "der Ausfall sagt nichts"
    assert "konnten nicht angezeigt werden" in krypto, \
        "ein Fehler beim Rendern sieht wieder wie 'nichts konfiguriert' aus"

    # ── (5) DER BOT MELDET DIE TEILKONFIGURATION — gedrosselt und mit den
    # fehlenden Namen. Sie hatte bis W101 gar keinen Zustand: zwei von sechs
    # Wallets sahen im Log aus wie alle sechs.
    src = _io.open(_os.path.join(wurzel, "bot.py"), encoding="utf-8").read()
    i = src.index('stats["crypto"] = _nc_crypto.snapshot')
    rumpf = rumpf_ab(src, i)
    # Hier stand `'"crypto-teil"' in rumpf` — und die Mutationsprobe ist
    # entwischt: der Name steht auch in der `zuruecksetzen`-Zeile, also blieb
    # die Zusicherung gruen, nachdem die Drossel durch `laut = True` ersetzt
    # war. Geprueft wird deshalb die VERDRAHTUNG (melden MIT diesem Kanal),
    # nicht das Vorkommen des Namens. Eine Probe, die entwischt, ist ein
    # Befund am Vertrag, nicht am Code.
    import re as _re
    assert _re.search(r'melden\(\s*\n?\s*"crypto-teil"', rumpf), \
        "die Teilkonfiguration laeuft ungedrosselt — ein Kanalname allein " \
        "ist keine Drossel"
    assert '_nc_meldetakt.zuruecksetzen("crypto-teil")' in rumpf, \
        "der Erfolgspfad setzt die Drossel nicht zurueck — eine Lage, die " \
        "wiederkehrt, bliebe bis zu 15 Minuten unsichtbar (Lehre aus W81)"
    assert "_fehlend" in rumpf, "die Meldung nennt die fehlenden Namen nicht"
    # Und kein Logtext behauptet mehr, der Block bleibe aus — ein Text, der
    # eine ueberholte Wirkung nennt, schickt an die falsche Stelle.
    assert "bleibt deshalb aus" not in rumpf, \
        "der Logtext behauptet weiter, der Spendenblock verschwinde"

    ok("W101: eine fehlende Adresse kostet nur ihre Zeile, nicht den Block")
    ok("W101: snapshot nennt die fehlenden env-Namen auch bei Treffern")
    ok("W101: die Seite zeigt den Krypto-Block in jedem Zustand")
    ok("W101: der Bot meldet eine Teilkonfiguration gedrosselt")


def _test_v42_w102_ytdlp_traegt_die_stream_url():
    """yt-dlp hatte die Adresse, und wir haben sie als Ja/Nein gelesen.

    `_resolve_via_ytdlp` ruft yt-dlp mit `--dump-single-json` und pruefte das
    Ergebnis so:

        if data.get("is_live") or data.get("formats") or data.get("manifest_url") \
           or data.get("url"):
            return "live", None

    Genau die drei Schluessel, die eine ADRESSE tragen, als Ja/Nein-Frage —
    und danach weggeworfen. Fuer den Recorder ging das auf (er startet yt-dlp
    noch einmal), fuer den Restream nicht: der braucht eine URL und hat keinen
    yt-dlp-Rang. Er bekam "keine spielbare Quell-URL" und startete nicht.

    Gemeldet am 01.10.: „wird selten ein live restreamt, aber dennoch laeuft
    der Chat von getrackten usern durchs transkript". Beides passt zusammen:
    der Chat braucht keine Adresse, der Restream schon.
    """
    import io as _io
    import os as _os
    from nc import ytdlpurl as Y

    wurzel = _os.path.dirname(_os.path.abspath(__file__))

    # ── (1) FLV UND HLS, UND FLV GEWINNT. Fuer den Restream ist FLV die
    # stabile Quelle — EINE Verbindung statt einer Kette signierter Segmente;
    # HLS reisst ab (rc=187). Dieselbe Regel wie nc/livefolge.hat_stream_url.
    beides = Y.urls_aus_json({"is_live": True, "formats": [
        {"url": "https://cdn/y.m3u8?e=1", "protocol": "m3u8_native", "ext": "mp4"},
        {"url": "https://cdn/x.flv?expire=9", "protocol": "flv", "ext": "flv"}]})
    assert beides["flv_url"].endswith("expire=9"), beides
    assert beides["hls_url"].endswith("e=1"), beides
    assert beides["via"] == "ytdlp", "ohne `via` ist im Log nicht zu sehen, " \
        "WELCHER Weg die Adresse gebracht hat — und das ist hier die Nachricht"

    # ── (1b) DIE ENDUNG STEHT VOR DEM QUERY-TEIL. `…/stream.flv?expire=…` —
    # ein `endswith(".flv")` haette JEDE signierte FLV-Adresse verworfen, und
    # das sind alle. Deshalb die Pruefung auf das Vorkommen.
    nur_query = Y.urls_aus_json({"url": "https://cdn/live/stream.flv?expire=1&sig=a"})
    assert nur_query.get("flv_url"), nur_query

    # ── (1c) DIE FORMEN, DIE YT-DLP WIRKLICH BAUT. Oben stehen bequeme
    # Eingaben; `yt_dlp/extractor/tiktok.py::TikTokLiveIE` baut andere, und
    # genau daran waere die Zuordnung sonst vorbeigelaufen (W97: „ein Vertrag,
    # der nur die bequeme Eingabe prueft, prueft nichts"). Nachgesehen im
    # Extractor-Quelltext:
    #
    #   HLS      {"ext": "mp4",  "protocol": "m3u8_native"}   <- ext ist NICHT m3u8
    #   rtmp     {"ext": "flv",  "protocol": "https"}         <- protocol ist https
    #   flv_*    {"ext": "flv"}                               <- GAR KEIN protocol
    #
    # Eine Erkennung allein am `protocol` haette die beiden FLV-Formen
    # verworfen, eine allein an der Endung die HLS-Form.
    echt = Y.urls_aus_json({"is_live": True, "formats": [
        {"url": "https://pull-hls/x/index.m3u8?e=1", "ext": "mp4",
         "protocol": "m3u8_native", "format_id": "hls-ORIGION"},
        {"url": "https://pull-rtmp/y?e=1", "ext": "flv",
         "protocol": "https", "format_id": "rtmp-pull"},
        {"url": "https://pull-flv/z?e=1", "ext": "flv",
         "format_id": "flv-origion"}]})
    assert echt.get("hls_url", "").startswith("https://pull-hls/"), echt
    assert echt.get("flv_url", "").startswith("https://pull-rtmp/"), echt
    # Und jede der drei Formen einzeln, damit nicht eine die andere traegt.
    assert Y.urls_aus_json({"formats": [
        {"url": "https://p/z?e=1", "ext": "flv", "format_id": "flv-sd"}]}
        ).get("flv_url"), "FLV ohne protocol-Schluessel wird nicht erkannt"
    assert Y.urls_aus_json({"formats": [
        {"url": "https://p/i.m3u8", "ext": "mp4", "protocol": "m3u8_native"}]}
        ).get("hls_url"), "HLS mit ext=mp4 wird nicht erkannt"

    # ── (2) BEIDE QUELLEN IM JSON WERDEN GELESEN. `--dump-single-json` fuellt
    # je nach Extractor-Fassung nur `formats` ODER die obersten Schluessel;
    # wer sich auf eine verlaesst, bekommt bei der anderen wortlos nichts.
    assert Y.urls_aus_json({"manifest_url": "https://cdn/a.m3u8"}).get("hls_url")
    assert Y.urls_aus_json({"formats": [
        {"manifest_url": "https://cdn/b.m3u8", "protocol": "m3u8"}]}).get("hls_url")

    # ── (3) KEINE BRAUCHBARE FORM -> LEER, UND DAS IST EINE AUSSAGE. yt-dlp
    # kann "live" sagen und nur Formate liefern, die wir nicht pullen koennen.
    #
    # AUSSAGE GEAENDERT (v4.2-W141, bewusst): hier stand, dass ein reines
    # MP4-Format "nicht pullbar" ist und verworfen wird. Genau das liess den
    # Restream am 05.11. bei 7 Live-Nutzern mit "weder FLV noch HLS" stehen.
    # MP4/DASH/CMAF sind seither die dritte Form — als LETZTE Quelle, ohne
    # FLV/HLS zu verdraengen. Leer bleibt, was wirklich nicht ziehbar ist.
    _mp4 = Y.urls_aus_json({"is_live": True, "formats": [
        {"url": "https://cdn/a.mp4", "protocol": "https", "ext": "mp4"}]})
    assert _mp4.get("other_url") == "https://cdn/a.mp4" and not (
        _mp4.get("hls_url") or _mp4.get("flv_url")), _mp4
    assert Y.urls_aus_json({"is_live": True, "formats": [
        {"url": "rtmp://cdn/a", "protocol": "rtmp", "ext": "unknown_video"}]}) == {}
    assert Y.urls_aus_json(None) == {} and Y.urls_aus_json({}) == {}
    assert "via" not in Y.urls_aus_json({}), \
        "`via` ohne Adresse behauptet einen Treffer, den es nicht gab"

    # ── (4) DIE HUELLE GIBT DIE ADRESSE WEITER — und prueft vorher die
    # Frische. Eine abgelaufene CDN-URL ist schlimmer als keine: der Restream
    # startet, ffmpeg stirbt sofort, und der Versuch zaehlt trotzdem gegen
    # MAX_RECONNECTS (B138).
    src = _io.open(_os.path.join(wurzel, "bot.py"), encoding="utf-8").read()
    i = src.index("async def _resolve_via_ytdlp(")
    rumpf = rumpf_ab(src, i)
    assert 'return "live", None' not in rumpf, \
        "der yt-dlp-Weg wirft die Adresse wieder weg"
    assert "urls_aus_json" in rumpf, "die Adresse wird nicht mehr ausgelesen"
    assert "_stream_url_ttl" in rumpf and "_STREAM_URL_MIN_TTL" in rumpf, \
        "eine abgelaufene URL wird ungeprueft weitergegeben"

    # ── (5) UND DIE BEHAUPTUNG IST WEG. In bot.py UND in nc/livefolge.py
    # stand als Tatsache „Nur der HTML-Weg traegt eine URL" — eine Aussage
    # ueber unsere Huelle, nicht ueber yt-dlp, und selbsterfuellend.
    folge = _io.open(_os.path.join(wurzel, "nc", "livefolge.py"),
                     encoding="utf-8").read()
    for name, text in (("bot.py", src), ("nc/livefolge.py", folge)):
        assert "Nur der HTML-Weg traegt eine URL." not in text, \
            "%s behauptet weiter, nur HTML trage eine URL" % name

    ok("W102: yt-dlp liefert die Stream-URL, die es ohnehin schon hatte")
    ok("W102: FLV gewinnt, und eine signierte .flv?-Adresse wird erkannt")
    ok("W102: eine abgelaufene URL wird nicht weitergegeben")


def _test_v42_w102_nachschlag_laeuft_im_haeufigsten_fall():
    """Der eine Weg, der durchkommt, lief ausgerechnet dort nie.

    Im Quelltext steht die Messung vom 11.09. seit W51: 60 von 84
    Aufloesungen melden „live" OHNE Stream-URL — 71 %. TikTok gibt die
    Adresse einer Datacenter-IP nicht heraus. Die yt-dlp-Stufe in
    `get_live_status` haengt aber an `status == "unknown"`, und der Status ist
    in diesem Fall „live". Also lief genau in den 71 % der Weg nicht, der
    TikToks Signaturen selbst erzeugt und deshalb durchkommt.
    """
    import io as _io
    import os as _os

    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    src = _io.open(_os.path.join(wurzel, "bot.py"), encoding="utf-8").read()

    # ── (1) DER NACHSCHLAG HAENGT IM live-OHNE-URL-ZWEIG. Der Anker ist der
    # Zweig selbst (`elif _blind:`), nicht die Funktion irgendwo — ein Aufruf
    # an anderer Stelle wuerde die 71 % nicht treffen.
    #
    # v4.2-W103: der Anker war `src.index("if _nc_live.braucht_url_nachschlag(
    # status, info):")` und ist gebrochen, als W103 die Bedingung umdrehte
    # (`if not …: zuruecksetzen() else: …`) und den Block nach
    # `_url_nachschlag` herauszog. Das war eine ANKER-Bruchstelle, keine
    # Verhaltensaenderung — genau der Fall, vor dem CLAUDE.md warnt. Der neue
    # Anker ist die Funktion mit `rumpf_ab`, also mitwachsend.
    i = src.index("async def _url_nachschlag(")
    zweig = rumpf_ab(src, i)
    assert "_nc_live.braucht_url_nachschlag(status, info)" in zweig, \
        "der Nachschlag entscheidet nicht mehr ueber braucht_url_nachschlag"
    assert "elif _blind:" in zweig
    blind = zweig[zweig.index("elif _blind:"):]
    assert "_nachschlag_ytdlp(" in blind, \
        "im live-ohne-URL-Zweig fragt niemand yt-dlp — der haeufigste Fall " \
        "bleibt ohne Adresse"
    assert blind.index("_nachschlag_ytdlp(") < blind.index("RECORD_PROXY"), \
        "erst die Abhilfe melden und dann noch einen Weg probieren ist die " \
        "falsche Reihenfolge: die Meldung gehoert in den Fall, in dem ALLE " \
        "Wege leer ausgingen"

    # ── (2) EIN AUSGANG. Jeder vorzeitige `return {}` waere ein stummer
    # Misserfolgs-Rueckweg (tools/blindstellen.py), und die Funktion hat nur
    # ein Ergebnis.
    #
    # Gezaehlt wird im SYNTAXBAUM, nicht im Text: der erste Anlauf zaehlte
    # `nach.count("return")` und fiel am eigenen Docstring, der das Wort
    # erwaehnt. Eine Textzaehlung misst hier die Prosa mit.
    import ast as _ast
    k = src.index("async def _nachschlag_ytdlp(username):")
    nach = rumpf_ab(src, k)
    _fn = _ast.parse(nach).body[0]
    _returns = [n for n in _ast.walk(_fn) if isinstance(n, _ast.Return)]
    assert len(_returns) == 1, "mehrere Ausgaenge: %d" % len(_returns)

    # ── (3) DER ABGESCHALTETE SCHUTZSCHALTER MELDET. Ohne diese Zeile sieht
    # sein Fehlen aus wie „auch yt-dlp fand nichts" — dabei lief yt-dlp nie.
    d = src.index("def _darf_ytdlp_nachschlagen(username) -> bool:")
    darf = rumpf_ab(src, d)
    assert "_resolver_stumm" in darf and "ytdlp_abgeschaltet" in darf, \
        "der abgeschaltete yt-dlp-Weg verschwindet wortlos"
    from nc import resolvergrund as R
    assert "ytdlp_abgeschaltet" in R.GRUND, "der Grund hat keinen Klartext"
    assert R.text("ytdlp_abgeschaltet") != "ytdlp_abgeschaltet", \
        "der Klartext ist der Schluessel selbst — das hilft niemandem"

    ok("W102: der yt-dlp-Nachschlag laeuft im live-ohne-URL-Fall")
    ok("W102: der abgeschaltete Schutzschalter verschwindet nicht wortlos")


def _test_v42_w102_restream_trennt_offline_von_ohne_url():
    """`src_live = not _err` machte aus fuenf Lagen zwei.

    „offline" (der Streamer sendet nicht) und „keine spielbare Quell-URL" (er
    sendet, wir kommen nicht an den Stream) sind vollkommen verschiedene
    Nachrichten mit vollkommen verschiedener Abhilfe. Der Waechter sah beide
    als `source_live=False` und antwortete „Quelle nicht live — kein Start" —
    und das ist `ACT_NONE`, das die Schleife NIE loggt. Ein Restream, der nie
    anlief, erzeugte damit keine einzige Zeile.

    Dieselbe Klasse wie `audio=False` fuer drei Ursachen (W55) und `None` =
    „tot" in nc/preflight (W89).
    """
    import io as _io
    import os as _os
    from nc import resolvergrund as R

    # ── (1) DIE FUENF LAGEN, EINZELN. Und LAGE_OK ist benannt, nicht "":
    # eine leere Zeichenkette liest sich wie „nichts herausgefunden", und das
    # ist das Gegenteil (Lehre aus W97, log_wartend = -1 statt 0).
    assert R.quelle_lage("") == R.LAGE_OK and R.LAGE_OK, R.LAGE_OK
    assert R.quelle_lage("offline") == R.LAGE_OFFLINE
    assert R.quelle_lage("unknown") == R.LAGE_UNBEKANNT
    assert R.quelle_lage("Abo-Stream \u2014 nur Aufnahme/VLC") == R.LAGE_ABO
    assert R.quelle_lage("keine spielbare Quell-URL (weder FLV noch HLS)") \
        == R.LAGE_OHNE_URL
    assert R.quelle_lage("resolve error: boom") == R.LAGE_FEHLER, \
        "ein unbekannter Text wird still verschluckt statt gemeldet"

    # ── (2) WER LAUT IST UND WER NICHT. „offline" ist der Alltag — ein
    # getrackter Nutzer sendet die meiste Zeit nicht, und eine Zeile pro
    # Pruefung waere genau das unlesbare Log, das eine Warnung wertlos macht.
    assert not R.quelle_laut(R.LAGE_OFFLINE), "offline wuerde das Log fluten"
    assert not R.quelle_laut(R.LAGE_ABO), "Abo ist eine Entscheidung (B148)"
    assert not R.quelle_laut(R.LAGE_OK)
    for lage in (R.LAGE_OHNE_URL, R.LAGE_UNBEKANNT, R.LAGE_FEHLER):
        assert R.quelle_laut(lage), lage

    # ── (3) DER KLARTEXT SAGT AUSDRUECKLICH, DASS ES NICHT OFFLINE IST, und
    # nennt die Abhilfe. „HTTP 403" allein hat schon einmal wochenlang
    # niemandem geholfen.
    t = R.text("quelle_ohne_url")
    assert "NICHT" in t and "offline" in t, t
    assert "RECORD_PROXY" in t, "die Abhilfe fehlt"
    assert "yt-dlp" in t, "der Weg, der durchkommt, wird nicht genannt"

    # ── (4) ALLE DREI ENTSCHEIDUNGSSTELLEN MELDEN, UND ZWAR GEDROSSELT.
    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    src = _io.open(_os.path.join(wurzel, "bot.py"), encoding="utf-8").read()
    m = src.index("    def _quelle_melden(self, username, err):")
    melder = rumpf_ab(src, m)
    import re as _re
    assert _re.search(r'melden\(\s*\n?\s*"restream-quelle"', melder), \
        "die Meldung laeuft ungedrosselt — der Resolver laeuft pro Poll und " \
        "pro Nutzer, das waere nach einer Stunde unlesbar"
    assert "quelle_laut" in melder, "auch 'offline' wuerde gemeldet"
    # Drei Aufrufer: Verify-Schleife, Auto-Picker (single + multi) und der
    # Failover. Vier Aufrufstellen plus die Definition.
    assert src.count("_quelle_melden(") >= 5, src.count("_quelle_melden(")

    # ── (5) UND DIE IRREFUEHRENDEN TEXTE SIND WEG. Jeder einzelne behauptete
    # eine Aussage ueber TikTok, wo die Wahrheit „ich habe keine Adresse
    # bekommen" war.
    #
    # Geprueft werden ZEICHENKETTEN und Kommentare GETRENNT: der erste Anlauf
    # suchte im ganzen Quelltext und fiel an den eigenen Kommentaren, die den
    # alten Wortlaut zitieren — damit man beim Lesen weiss, was dort stand.
    # Ein Kommentar DARF den alten Text nennen, eine Ausgabe nicht. Dieselbe
    # Falle wie in W99, wo ein Docstring die eigene Zusicherung zitierte.
    import io as _io2
    import tokenize as _tok
    _strings = []
    with _io2.open(_os.path.join(wurzel, "bot.py"), "rb") as _fh:
        for _t in _tok.tokenize(_fh.readline):
            if _t.type == _tok.STRING:
                _strings.append(_t.string)
    _alle = "\n".join(_strings)
    for falsch in ("aktuell keine weitere Live-Quelle verf\u00fcgbar",
                   "nicht live \u2192 n\u00e4chstes Ziel probieren",
                   "offline \u2192 still \u00fcberspringen"):
        assert falsch not in _alle, \
            "irrefuehrender Text ist wieder eine Ausgabe: %s" % falsch

    ok("W102: 'live ohne URL' ist von 'offline' unterschieden")
    ok("W102: der Restream sagt gedrosselt, warum er nicht startet")
    ok("W102: kein Text behauptet mehr eine Aussage ueber TikTok")


def _test_v42_w103_cache_greift_bei_gleichzeitigen_aufrufern():
    """Zwei Aufloesungen fuer denselben Nutzer, 17 ms auseinander.

    Der Betreiber hat am 01.10. das Log mitgeschnitten, und die Zeilen stehen
    PAARWEISE:

        10:55:53,944  live-ohne-URL @laurahasisfrau1601225: …
        10:55:53,961  live-ohne-URL @laurahasisfrau1601225: …   (17 ms)
        10:56:18,477  live-ohne-URL @laurahasisfrau1601225: …
        10:56:18,555  live-ohne-URL @laurahasisfrau1601225: …   (78 ms)

    Rund siebzig Zeilen in achtzehn Minuten fuer EINEN Nutzer, immer zu
    zweit. Der Cache ist genau dagegen gebaut — sein Kommentar nennt als
    Zweck woertlich „Multi-Chat-Dedup", und derselbe Nutzer in zwei Chats ist
    der Normalfall.

    Er griff nicht, weil er EINMAL geprueft wurde, und zwar VOR der
    Semaphore. Und die Semaphore faengt es nicht: `RESOLVE_CONCURRENCY` ist 2,
    sie laesst also genau zwei gleichzeitig durch — sie serialisiert alles
    ausser dem Fall, der hier auftritt.
    """
    import io as _io
    import os as _os
    from nc import livecache as C

    # ── (1) EIN TREFFER IST EIN TUPEL, KEIN TREFFER IST None. `None` und
    # `("offline", None)` sind verschieden: das zweite ist ein GUELTIGER
    # Treffer mit leerer Nutzlast. Ein Aufrufer, der auf Wahrheitswert prueft,
    # wuerde beides verwechseln und bei jedem Offline-Nutzer neu aufloesen.
    cache = {}
    assert C.holen(cache, "a", 100.0) is None, "leerer Cache liefert keinen None"
    C.setzen(cache, "a", "offline", None, 100.0, 15.0)
    assert C.holen(cache, "a", 101.0) == ("offline", None), \
        "ein gueltiger Offline-Treffer wird nicht als Treffer erkannt"

    # ── (2) NUR DEFINITIVE ANTWORTEN. "unknown" heisst „ich konnte es nicht
    # ermitteln"; wer das speichert, verlaengert einen Aussetzer um die TTL.
    assert C.setzen(cache, "b", "unknown", None, 100.0, 15.0) is False
    assert C.holen(cache, "b", 100.1) is None, "unknown ist im Cache"

    # ── (3) DER ZEITSTEMPEL IST DER DES SCHREIBENS. Hier lag der zweite
    # Befund: `bot.py` rechnete `now + TTL` mit dem `now` von VOR der
    # Aufloesung. Gemessen an der echten Lage — Webcast + HTML + ein
    # yt-dlp-Lauf mit bis zu 20 s Timeout gegen eine TTL von 15 s:
    beginn, dauer, ttl = 1000.0, 20.0, 15.0
    C.setzen(cache, "alt", "live", {}, beginn, ttl)          # falsch: Beginn
    assert C.holen(cache, "alt", beginn + dauer) is None, \
        "ein Eintrag mit dem Zeitstempel vom Beginn ist beim Schreiben " \
        "schon abgelaufen — Restgueltigkeit %.0f s" % (beginn + ttl - (beginn + dauer))
    C.setzen(cache, "neu", "live", {}, beginn + dauer, ttl)  # richtig: jetzt
    assert C.holen(cache, "neu", beginn + dauer + 1.0) == ("live", {}), \
        "der frisch gestempelte Eintrag gilt nicht"

    # ── (4) force_fresh UMGEHT, SCHREIBT ABER WEITER. Der Reconnect-Pfad
    # braucht eine frische URL (B138) — der naechste normale Aufrufer soll
    # trotzdem vom Ergebnis profitieren.
    # ANKER GEWANDERT (v5.4-W195): die Attrappe war `{}` — „live OHNE
    # Adresse". Die Aussage hier gilt der toten ADRESSE (B138), also traegt
    # der Eintrag jetzt eine; der Fall ohne Adresse steht unter (4b).
    _url = {"flv_url": "https://pull-f5.tiktokcdn.com/stage/stream.flv?expire=9"}
    C.setzen(cache, "neu", "live", _url, beginn + dauer, ttl)
    assert C.holen(cache, "neu", beginn + dauer + 1.0, force_fresh=True) is None
    assert C.holen(cache, "neu", beginn + dauer + 1.0) is not None, \
        "force_fresh hat den Eintrag geloescht statt ihn zu ueberspringen"
    # ── (4b) v5.4-W195: ein Eintrag „live ohne Adresse" hat keine tote Adresse
    # — force_fresh bekaeme innerhalb der TTL dieselbe Antwort und kostete je
    # Reconnect eine TikTok-Anfrage (beim Betreiber bis zu drei je Sekunde).
    C.setzen(cache, "leer", "live", None, beginn + dauer, ttl)
    assert C.holen(cache, "leer", beginn + dauer + 1.0, force_fresh=True) == ("live", None), \
        "force_fresh loest live-ohne-Adresse innerhalb der TTL neu auf"
    assert C.holen(cache, "leer", beginn + dauer + ttl + 1, force_fresh=True) is None, \
        "ein abgelaufener Eintrag ohne Adresse darf nicht weiter gelten"

    # ── (5) AUFRAEUMEN ERST AB EINER GROESSE, und nur Abgelaufenes.
    gross = {str(i): (50.0, "live", None) for i in range(60)}
    gross["frisch"] = (999.0, "live", None)
    assert C.aufraeumen(gross, 100.0, ab_groesse=1000) == 0, "raeumt zu frueh"
    weg = C.aufraeumen(gross, 100.0, ab_groesse=50)
    assert weg == 60 and "frisch" in gross, (weg, len(gross))

    # ── (6) UND bot.py PRUEFT ZWEIMAL — vor UND in der Semaphore. Das ist
    # der eigentliche Befund; eine Pruefung allein nutzt nichts.
    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    src = _io.open(_os.path.join(wurzel, "bot.py"), encoding="utf-8").read()
    # v4.2-W119: get_live_status ist seither Huelle (billige Pruefung,
    # Single-Flight) um den Kern _live_status_aufloesen (Semaphore,
    # verbindliche Pruefung). Die Aussage gilt fuer beide zusammen, in
    # dieser Reihenfolge — der Anker folgt der Teilung, nicht umgekehrt.
    rumpf = (rumpf_ab(src, src.index("async def get_live_status("))
             + rumpf_ab(src, src.index("async def _live_status_aufloesen(")))
    assert rumpf.count("_nc_livecache.holen(") == 2, \
        "der Cache wird %d-mal geprueft; zwei gleichzeitige Aufrufer " \
        "brauchen die Pruefung INNERHALB der Semaphore" \
        % rumpf.count("_nc_livecache.holen(")
    _sem = rumpf.index("async with sem:")
    assert rumpf.index("_nc_livecache.holen(") < _sem, "die billige Pruefung fehlt"
    assert rumpf.rindex("_nc_livecache.holen(") > _sem, \
        "beide Pruefungen stehen VOR der Semaphore — genau der Zustand, der " \
        "die Doppelaufloesung erzeugt hat"
    # Und kein roher Schreibzugriff mehr, der den alten Zeitstempel benutzt.
    assert "_LIVE_STATUS_CACHE[username] = (now" not in src, \
        "eine Schreibstelle rechnet wieder mit dem Zeitstempel vom Beginn"
    # Das allein genuegt NICHT: die erste Fassung dieses Vertrags hat genau
    # hier aufgehoert, und die Mutationsprobe `_jetzt = now` ist entwischt —
    # sie laesst `setzen()` stehen und dreht nur die Quelle des Zeitstempels
    # zurueck. Geprueft wird deshalb JEDE Schreibstelle: der Zeitstempel muss
    # ein frisches `monotonic()` sein, unmittelbar oder ueber `_jetzt`.
    assert "_jetzt = _time_mod.monotonic()" in rumpf, \
        "der Schreib-Zeitstempel wird nicht frisch genommen"
    for _teil in src.split("_nc_livecache.setzen(")[1:]:
        _args = _teil[:_teil.index(")") + 1] + _teil[_teil.index(")") + 1:][:80]
        _args = " ".join(_args.split())
        assert ("_time_mod.monotonic()" in _args or "_jetzt" in _args), \
            "eine setzen()-Stelle bekommt keinen frischen Zeitstempel: %s" % _args[:90]
        assert " now," not in _args and "(now," not in _args, \
            "eine setzen()-Stelle rechnet mit dem Zeitstempel vom Beginn: %s" % _args[:90]

    ok("W103: ein Cache-Treffer ist von 'kein Treffer' unterscheidbar")
    ok("W103: die TTL zaehlt ab dem Schreiben, nicht ab dem Beginn")
    ok("W103: bot.py prueft den Cache auch INNERHALB der Semaphore")


def _test_v42_w103_ohne_url_meldung_ist_gedrosselt():
    """Siebzig gleiche Zeilen in achtzehn Minuten, fuer EINEN Nutzer.

    So steht es im Log des Betreibers vom 01.10. Bei 40 Trackings ist das Log
    nach einer Stunde unlesbar — und eine unlesbare Warnung ist so gut wie
    keine. Genau diese Lehre steht seit W81 in CLAUDE.md, fuer genau diesen
    Resolver; die `live-ohne-URL`-Zeilen aus W51/W102 sind nur nie durch den
    Kanal gegangen.
    """
    import io as _io
    import os as _os
    import re as _re

    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    src = _io.open(_os.path.join(wurzel, "bot.py"), encoding="utf-8").read()

    # ── (1) ALLE DREI AUSGAENGE GEHEN DURCH DEN MELDER, keiner mehr direkt
    # auf log.info. Gezaehlt wird beides: ein vergessener Ausgang faellt auf.
    assert src.count("_ohne_url_melden(") == 4, \
        "nicht alle drei Ausgaenge (plus die Definition) laufen ueber den " \
        "Melder: %d" % src.count("_ohne_url_melden(")
    i = src.index("async def _url_nachschlag(")
    nach = rumpf_ab(src, i)
    assert 'log.info("live-ohne-URL' not in nach, \
        "ein Ausgang schreibt wieder ungedrosselt auf log.info"

    # ── (2) DER MELDER DROSSELT WIRKLICH — und der Schluessel ist der KANAL,
    # nicht der Nutzer. Bei 40 Trackings in derselben Lage drosselt ein
    # Schluessel je Nutzer gar nichts (CLAUDE.md, W81).
    m = src.index("def _ohne_url_melden(")
    melder = rumpf_ab(src, m)
    assert _re.search(r'melden\(\s*\n?\s*"live-ohne-url"', melder), \
        "der Melder laeuft ungedrosselt"
    assert "username" not in melder.split("_nc_meldetakt.melden(")[1].split(")")[0], \
        "der Nutzername steht im Drossel-Schluessel — damit drosselt er nichts"
    assert "zusatz(unterdrueckt)" in melder, \
        "die Zahl der unterdrueckten Faelle fehlt — ohne sie ist nicht zu " \
        "sehen, wie oft die Lage wirklich auftrat"

    # ── (3) DER GRUND IST DER AUSGANG. Ein Wechsel meldet damit sofort: dass
    # aus „HTML liefert nach" ein „keiner findet etwas" geworden ist, ist die
    # eigentliche Nachricht (meldetakt seit W97, Paar (Kanal, Grund)).
    for grund in ('"html"', '"ytdlp"', '"keiner"'):
        assert grund in nach, "der Ausgang %s hat keinen eigenen Grund" % grund

    # ── (4) UND DER ERFOLGSPFAD SETZT ZURUECK. War die Adresse von Anfang an
    # da, ist die Lage vorbei; ohne das Zuruecksetzen bliebe eine
    # WIEDERKEHRENDE Stoerung bis zu 15 Minuten unsichtbar (Lehre aus W81).
    # VERTRAG GEAENDERT (v4.2-W176): hier stand die Zusicherung auf ein
    # blankes zuruecksetzen() — und das WAR der Fehler: der Pfad laeuft auch
    # fuer jede Offline-Pruefung jedes anderen Nutzers und leerte die Drossel
    # fast bei jedem Poll. Seither erfolg() je Nutzer (W157-Muster); das
    # Verhalten misst _test_v42_w176_live_ohne_url_drossel.
    assert '_nc_meldetakt.erfolg("live-ohne-url", username)' in nach, \
        "der Erfolgspfad setzt die Drossel nicht zurueck"
    assert '_nc_meldetakt.zuruecksetzen("live-ohne-url")' not in nach, \
        "jede Offline-Pruefung eines anderen Nutzers leert wieder die Drossel"

    ok("W103: die live-ohne-URL-Zeilen laufen gedrosselt ueber EINEN Kanal")
    ok("W103: der Drossel-Schluessel ist der Kanal, der Grund der Ausgang")
    ok("W103: der Erfolgspfad setzt die Drossel zurueck")


def _test_v42_w104_laufender_code_gegen_platte():
    """Ein Update ueber das Deck wirkt erst nach einem Neustart.

    Der Betreiber hat am 01.10. korrigiert: „auf dem Server laeuft die repo
    dank der update Funktion". Davor stand in CLAUDE.md und im Kopf von
    `nc/auslieferung.py` als Tatsache, ausgeliefert werde per ZIP und das Repo
    sei „nicht der Deploy-Weg" — dieser Satz hat eine Welle lang falsch
    beraten.

    Der Befund darunter: `nc.updater` schreibt die Dateien und startet nichts
    neu. Ein laufender Python-Prozess behaelt seinen Bytecode, also liegt der
    neue Stand auf der Platte und es laeuft weiter der alte. Der Neustart-Weg
    selbst ist in Ordnung (Knopf im Deck, `/api/update/restart`, Opt-in ueber
    UPDATE_RESTART_CMD); die Luecke ist die ZEIT DANACH — der Hinweis erscheint
    einmal als Toast, und danach nannte nichts mehr den Zustand.
    """
    import io as _io
    import json as _json
    import os as _os
    from nc import auslieferung as A
    from nc import laufstand as L

    # ── (1) DIE DREI LAGEN, und "unbekannt" ist KEIN Alarm. Eine Meldung, die
    # auf jeder Entwicklungsmaschine rot ist, erzieht dazu, sie auch auf dem
    # Server zu uebersehen — dieselbe Begruendung wie im Kopf von W85.
    assert L.vergleich("abc123", "abc123")["lage"] == L.AKTUELL
    assert L.vergleich("abc123", "zzz999")["lage"] == L.VERALTET
    for a, b in (("", "abc"), ("abc", ""), ("", "")):
        assert L.vergleich(a, b)["lage"] == L.UNBEKANNT, (a, b)
        assert not L.veraltet(a, b), "ein unbekannter Stand loest Alarm aus"

    # ── (2) NUR DER ALARM NENNT EINE ABHILFE, und die ist ein BEFEHL. „Neustart
    # noetig" ohne Befehl ist dieselbe Art Auskunft wie ein blankes HTTP 403.
    v = L.vergleich("abc123", "zzz999")
    assert v["abhilfe"].startswith("sudo systemctl restart"), v["abhilfe"]
    assert "Bytecode" in v["text"], \
        "der Text sagt nicht, WARUM das Update nicht wirkt"
    assert L.vergleich("abc", "abc")["abhilfe"] == "", \
        "der Gutfall nennt eine Abhilfe, die er nicht braucht"
    # Der Dienstname ist ueberschreibbar — nicht jeder Bestand heisst so.
    assert "eigener-dienst" in L.befehl("eigener-dienst")

    # ── (3) nc/auslieferung KENNT DEN UPDATE-WEG. Bis W104 las es nur
    # AUSLIEFERUNG.json und git; nach einem Update meldete /healthz damit
    # unveraendert den Stand von vorher.
    assert A.UPDATE_DATEI == ".nc_update.json", A.UPDATE_DATEI
    # _ph.verzeichnis() statt tempfile.mkdtemp(): die Suiten haben
    # damit an einem Tag 5093 Verzeichnisse und 30 GB liegen gelassen, bis die
    # Pruefkette mit ENOSPC abbrach (W90). tools/testmuell.py sperrt das, und
    # es hat hier sofort gegriffen.
    tmp = _ph.verzeichnis(praefix="nc-pruef-w104-")
    if True:
        # Ohne alles: ehrlich "unbekannt", kein Fehlalarm.
        assert A.stand(wurzel=tmp, frisch=True)["quelle"] == "unbekannt"
        # Nur das Archiv-Stempel: das ist die Antwort.
        with _io.open(_os.path.join(tmp, A.DATEI), "w", encoding="utf-8") as fh:
            _json.dump({"commit": "a" * 40, "zweig": "main"}, fh)
        assert A.stand(wurzel=tmp, frisch=True)["quelle"] == "archiv"
        # Kommt ein Update dazu, ist ES das Juengste auf der Platte. Den
        # Archiv-Stempel zu bevorzugen hiesse, eine Fassung zu melden, die
        # seit dem Update nicht mehr draufliegt.
        with _io.open(_os.path.join(tmp, A.UPDATE_DATEI), "w", encoding="utf-8") as fh:
            _json.dump({"sha": "b" * 40, "branch": "main", "date": "2026-10-01"}, fh)
        d = A.stand(wurzel=tmp, frisch=True)
        assert d["quelle"] == "update" and d["kurz"] == "b" * 12, d

    # ── (4) DER BOT MERKT DEN STARTSTAND EINMAL — auf Modul-Ebene, nicht in
    # einer Funktion. Genau das macht den Vergleich moeglich: `local_head()`
    # folgt der Platte, dieser Wert nicht.
    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    src = _io.open(_os.path.join(wurzel, "bot.py"), encoding="utf-8").read()
    assert "\n_LAUFSTAND_START = _nc_updater.local_head()[0]" in src, \
        "der Startstand wird nicht auf Modul-Ebene gemerkt — in einer Funktion " \
        "gemessen folgt er der Platte und der Vergleich ist immer 'aktuell'"

    # ── (5) UND ES WIRD GEMELDET, gedrosselt, mit eigener Schleife. Der
    # Zustand muss auch in einem Bestand sichtbar werden, in dem die halben
    # Zusatzfunktionen abgeschaltet sind.
    i = src.index("async def _laufstand_loop(")
    loop = rumpf_ab(src, i)
    import re as _re
    assert _re.search(r'melden\(\s*\n?\s*"laufstand"', loop), \
        "die Meldung laeuft ungedrosselt"
    assert "log.error(" in loop, \
        "veralteter Code meldet nicht auf error — auf warning oder info " \
        "erscheint er im ERROR-Log NIE (CLAUDE.md)"
    assert "abhilfe" in loop, "die Meldung nennt den Befehl nicht"
    assert '_nc_meldetakt.zuruecksetzen("laufstand")' in loop, \
        "nach dem Neustart bleibt die Drossel stehen"
    # Geprueft wird im SYNTAXBAUM, nicht im Text: der erste Anlauf suchte
    # „DISK_AUTOCLEAN" im Quelltext und traf den eigenen Docstring, der
    # erklaert, warum die Schleife NICHT daran haengt. Dritte Wiederholung
    # dieser Falle in dieser Welle-Reihe (W102, W103) — ein Vertrag darf seine
    # eigene Begruendung nicht als Befund lesen.
    import ast as _ast
    _namen = {n.id for n in _ast.walk(_ast.parse(loop))
              if isinstance(n, _ast.Name)}
    assert "DISK_AUTOCLEAN" not in _namen, \
        "die Schleife haengt an einem fremden Schalter — in einem Bestand mit " \
        "abgeschalteter Platten-Reinigung waere die Meldung dann weg"
    # Nicht `in src`: die Probe, die den Start auskommentiert, liess genau
    # diesen Text stehen und ist entwischt. Geprueft wird eine ZEILE, die mit
    # dem Aufruf BEGINNT — ein Kommentar beginnt mit `#`.
    assert any(z.lstrip().startswith('_spawn(_laufstand_loop(')
               for z in src.splitlines()), \
        "die Schleife wird nie gestartet (oder der Start ist auskommentiert)"

    # ── (6) /healthz TRAEGT DIE LAGE. Dort sieht der Betreiber ohnehin nach.
    assert "laufstand=_laufstand()[\"lage\"]" in src, \
        "/healthz meldet den Laufstand nicht"

    # ── (7) UND DAS OPT-IN DES NEUSTARTS BLEIBT. Ein Neustart-Kommando, das
    # der Bot selbst kennt, ist ein Fernsteuer-Knopf auf das System; W104 hat
    # hier kurz eine Vorgabe eingesetzt und sie zurueckgenommen.
    zeile = next(z for z in src.splitlines()
                 if z.startswith("UPDATE_RESTART_CMD ="))
    assert zeile.strip() == 'UPDATE_RESTART_CMD = os.getenv("UPDATE_RESTART_CMD", "").strip()', \
        ("die Vorgabe fuer UPDATE_RESTART_CMD ist nicht mehr leer — damit "
         "wird aus einer bewussten Opt-in-Entscheidung ein immer scharfer "
         "Fernstart: %s" % zeile.strip())

    ok("W104: 'unbekannt' ist kein Alarm, 'veraltet' nennt den Befehl")
    ok("W104: nc/auslieferung kennt den Update-Weg und bevorzugt ihn")
    ok("W104: der Startstand wird auf Modul-Ebene gemerkt")
    ok("W104: veralteter Code wird gedrosselt auf error gemeldet")
    ok("W104: das Opt-in von UPDATE_RESTART_CMD bleibt unangetastet")


def _test_v42_w60_azrael_cooldown_je_plattform():
    """v4.2-W60: ein Cooldown fuer drei Chats verschluckte zwei davon.

    Gemeldet als „AZRAEL reagiert nicht plattformspezifisch auf Anfragen per
    @Azrael, @azrael, Azrael und azrael". Die Erkennung war nie das Problem —
    `"azrael" in text.lower()` faengt alle vier Schreibweisen. Die Bremse war
    es:

        _AZRAEL_CHAT_LAST = {"ts": 0.0}      # EIN Wert fuer alle drei

    Bei AZRAEL_CHAT_REPLY_COOLDOWN_S=20 hiess das: fragt jemand auf Kick,
    werden dieselben Fragen auf Twitch und YouTube in den naechsten 20
    Sekunden STUMM verworfen. Kein Log, keine Antwort. Bei drei laufenden
    Chats trifft das statistisch zwei von drei Fragestellern.
    """
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())

    # --- 1) Der Zeitstempel ist kein Einzelwert mehr ---------------------
    assert '_AZRAEL_CHAT_LAST = {}' in flach, \
        "der Cooldown haengt wieder an einem globalen Zeitstempel"
    assert '_AZRAEL_CHAT_LAST = {"ts": 0.0}' not in flach, \
        "der alte globale Zeitstempel steht noch da"
    ok("W60: der AZRAEL-Cooldown ist ein Woerterbuch, kein Einzelwert")

    # --- 2) Und er wird JE PLATTFORM gelesen und geschrieben -------------
    i = flach.find("def _azrael_chat_should_reply(")
    assert i > 0
    rumpf = rumpf_ab(flach, i)
    assert "platform" in rumpf.split(")")[0], \
        "die Funktion bekommt die Plattform gar nicht uebergeben"
    assert "_AZRAEL_CHAT_LAST.get(platform)" in rumpf, \
        "gelesen wird weiter global"
    assert "_AZRAEL_CHAT_LAST[platform] = now" in rumpf, \
        "geschrieben wird weiter global"
    ok("W60: gelesen und geschrieben wird je Plattform")

    # --- 3) Jede Aufrufstelle nennt ihre Plattform -----------------------
    # Ohne das liefen alle unter dem Vorgabe-Schluessel "?" — also wieder
    # unter EINEM gemeinsamen Cooldown, nur unauffaelliger.
    import re as _re
    rufe = _re.findall(r"_azrael_chat_should_reply\(([^)]*)\)", bot)
    rufe = [r for r in rufe if "def " not in r]
    assert len(rufe) >= 4, f"nur {len(rufe)} Aufrufstellen gefunden"
    ohne = [r for r in rufe if "platform=" not in r]
    assert not ohne, (
        f"{len(ohne)} Aufrufstelle(n) ohne Plattform — sie landen alle im "
        f"selben Vorgabe-Eimer und teilen sich wieder einen Cooldown: {ohne}")
    plattformen = set(_re.findall(r'platform="([a-z]+)"', " ".join(rufe)))
    assert plattformen >= {"kick", "twitch", "youtube"}, plattformen
    ok("W60: Kick, Twitch und YouTube haben je einen eigenen Cooldown")

    # --- 4) Die Erkennung selbst bleibt, wie sie war ---------------------
    # Sie war nie kaputt. Ein Vertrag, der sie mitaendert, waere eine
    # Verschlimmbesserung an einer Stelle, die funktioniert.
    # Im RUMPF der Funktion, nicht irgendwo in bot.py: `t = (text or "").lower()`
    # kommt auch anderswo vor, und ein dateiweiter Test bleibt gruen, waehrend
    # genau diese Erkennung ihr lower() verliert. Die Mutationsprobe ist beim
    # Bauen prompt durchgerutscht.
    assert 'addressed = ("azrael" in t' in rumpf, \
        "die Erkennung wurde angefasst — sie fing alle vier Schreibweisen"
    assert 't = (text or "").lower()' in rumpf, \
        "ohne lower() faengt sie 'Azrael' und '@Azrael' nicht mehr"
    ok("W60: die Erkennung faengt weiter Azrael, azrael, @Azrael und @azrael")


def _test_v42_w57_verwarnung_auf_allen_plattformen():
    """v4.2-W57: YouTube timeoutete sofort, Kick und Twitch verwarnten erst.

    Der Betreiber meinte, der Moderator sei Kick-only. Das stimmt nicht — die
    Erkennung (`_screen_full`) laeuft fuer alle drei, und im Moderations-Log
    gibt es auto-mod-kick, auto-mod-twitch und auto-mod-youtube. Beim
    Nachsehen fiel aber etwas anderes auf:

        Kick     _handle -> _escalation_decide, warn_first   (W19)
        Twitch   _mod_warn_first(...) and _escalation_decide (B168)
        YouTube  -- nichts --                    -> sofort Timeout

    Gleicher Verstoss, haertere Strafe, nur weil der Zuschauer auf der
    anderen Plattform sitzt. Das war keine Entscheidung, sondern eine
    vergessene Zeile: `_mod_warn_first` wird an drei Stellen gebraucht und
    stand an zweien.

    Der Vertrag prueft die SYMMETRIE, nicht den Wortlaut: er zaehlt, an wie
    vielen Sanktionsstellen die Verwarnung vorgeschaltet ist. Ein Test auf
    „steht das Wort youtube irgendwo" waere hier wertlos gewesen — es stand
    ja schon vorher ueberall.
    """
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()

    # --- 1) Alle drei Plattformen sanktionieren ueberhaupt ---------------
    for platt in ("kick", "twitch", "youtube"):
        assert f'"auto-mod-{platt}"' in bot, \
            f"{platt} taucht im Moderations-Log nicht mehr auf — moderiert " \
            f"der Bot dort noch?"
    ok("W57: Kick, Twitch und YouTube laufen alle durch die Moderation")

    # --- 2) Und alle drei verwarnen ZUERST -------------------------------
    # Gezaehlt wird die vorgeschaltete Bedingung, nicht das Vorkommen des
    # Plattformnamens: _mod_warn_first ist genau der Schalter, der aus einer
    # Sanktion eine Verwarnung macht.
    n = bot.count("_mod_warn_first(")
    assert n >= 4, (
        f"_mod_warn_first kommt nur {n}x vor (Definition + Kick + Twitch + "
        f"YouTube = 4). Eine Plattform sanktioniert wieder ohne Verwarnung")
    # Und zwar je einmal pro Eskalations-Schluessel.
    for schluessel in ('f"tw:{user}"', 'f"yt:{who}"'):
        assert schluessel in bot, \
            f"der Eskalations-Zaehler {schluessel} fehlt — ohne ihn zaehlt die " \
            f"Plattform Wiederholungstaeter nicht mit"
    ok("W57: alle drei verwarnen beim ersten Verstoss, mit eigenem Zaehler")

    # --- 3) Die Verwarnung geht auch wirklich raus -----------------------
    # Eine Verwarnung, die nur im Log steht, ist fuer den Zuschauer keine:
    # er sieht nichts und wird beim naechsten Mal ohne Vorwarnung getimeoutet.
    i = bot.find('f"yt:{who}"')
    assert i > 0
    zweig = bot[i:i + 700]
    assert "_YT_SEND" in zweig and "_mod_warn_text(" in zweig, \
        "die YouTube-Verwarnung wird nicht in den Chat geschickt — sie stuende " \
        "nur im Log, und der Zuschauer wuesste von nichts"
    assert '_modlog("warn", "auto-mod-youtube"' in zweig, \
        "die YouTube-Verwarnung wird nicht protokolliert"
    # ... und danach darf NICHT trotzdem noch getimeoutet werden.
    assert "continue" in zweig.split('_modlog("warn"')[1][:400], \
        "nach der Verwarnung laeuft der Timeout-Zweig weiter — dann ist die " \
        "Verwarnung wirkungslos und der Zuschauer bekommt beides"
    ok("W57: die Verwarnung erreicht den Chat und ersetzt den Timeout")


def _test_v42_w56_sitzungen_haben_eine_oberflaeche():
    """v4.2-W56: W44 lieferte drei Routen und keinen einzigen Knopf.

    Gefunden bei der Dashboard-Pruefung: von 359 Routen ruft das Deck 320.
    Unter den uebrigen standen

        /api/recordings/sessions
        /api/recordings/session/<sid>
        /api/recordings/session/<sid>/join

    — die komplette Sitzungs-Funktion aus W44. Im Release-Text von v4.3
    stand trotzdem „auf Knopfdruck werden die Segmente ohne Neukodierung zu
    einer Datei zusammengefuegt". Erreichbar war das nur per curl.

    Dieselbe Klasse Fehler wie B132 („acht Routen, die es im Backend gab und
    die nie eine Oberflaeche hatten"). Der Vertrag haelt fest, dass diese
    drei jetzt gerufen werden — und zwar an der Eigenschaft, nicht an einer
    Zeilennummer.
    """
    hier = os.path.dirname(os.path.abspath(__file__))
    deck = open(os.path.join(hier, "templates", "dashboard.html"),
                encoding="utf-8").read()

    # --- 1) Alle drei Routen werden gerufen ------------------------------
    assert "/api/recordings/sessions" in deck, \
        "die Sitzungs-Liste wird nicht geladen"
    assert "/api/recordings/session/" in deck, \
        "weder Detail noch Zusammenfuegen werden gerufen"
    # Nicht nur der NAME: die Funktion darf es geben und trotzdem von keinem
    # Knopf gerufen werden. Die Mutationsprobe „Knopf entfernt" ist genau
    # daran vorbeigelaufen, solange hier nur `"sitzungJoin" in deck` stand.
    assert "/join" in deck, "die Zusammenfuegen-Route wird nicht gerufen"
    assert 'onclick="sitzungJoin(' in deck, \
        "es gibt kein Bedienelement, das sitzungJoin ruft — genau der Knopf, " \
        "den der Release-Text verspricht"
    # v4.2-W58: und der Knopf muss auch FUNKTIONIEREN. In W56 stand hier
    #     onclick="sitzungJoin('+JSON.stringify(sid)+')"
    # JSON.stringify liefert DOPPELTE Anfuehrungszeichen, die das Attribut
    # beenden: erzeugt wurde onclick="sitzungJoin(" und der Rest zerfiel in
    # Schrott-Attribute. Der Knopf tat nichts — in genau der Welle, deren
    # Zweck ein fehlender Knopf war. Die Zusicherung darueber hat das nicht
    # gemerkt, weil die Zeichenkette ja vorhanden war.
    #
    # Deshalb hier keine Zeichenkette, sondern die EIGENSCHAFT: der Wert des
    # onclick-Attributs muss ein vollstaendiger Aufruf sein.
    for zeile in deck.split("\n"):
        # Nur Aufrufe MIT verkettetem Parameter. onclick="sitzungenLoad()" im
        # statischen Markup hat keinen und braucht nichts.
        if 'onclick="sitzung' not in zeile or "'+" not in zeile:
            continue
        assert "JSON.stringify" not in zeile, (
            "der Knopf baut sein onclick wieder mit JSON.stringify — die "
            "doppelten Anfuehrungszeichen beenden das Attribut und der Knopf "
            "tut nichts")
        assert "escJs(" in zeile, (
            "der Knopf setzt seinen Parameter ohne escJs ein — ein "
            "Anfuehrungszeichen in der Kennung bricht aus dem Attribut aus")
    assert "async function sitzungJoin" in deck, "die Funktion selbst fehlt"
    ok("W56: Liste, Detail und Zusammenfuegen werden aus dem Deck gerufen")

    # --- 2) Und die Ansicht laedt sie auch von selbst --------------------
    # Eine Funktion, die niemand aufruft, ist so tot wie eine Route ohne
    # Knopf — nur schwerer zu finden.
    i = deck.find("VIEW_LOADERS['betrieb']")
    assert i > 0, "die Betrieb-Ansicht hat keinen Loader mehr"
    zeile = deck[i:deck.find("\n", i)]
    assert "sitzungenLoad()" in zeile, \
        "sitzungenLoad haengt an keinem Ansichts-Loader — das Panel bliebe leer"
    ok("W56: die Betrieb-Ansicht laedt das Panel beim Oeffnen")

    # --- 3) Das Ziel-Panel existiert wirklich ----------------------------
    # loadCaptures() im selben Deck ist die Warnung: die Funktion gibt es
    # noch, ihr Panel nicht mehr, und sie steigt seither per Waechter aus.
    for eid in ("pnl_sitzungen", "sz_body", "sz_tag"):
        assert f'id="{eid}"' in deck, f"das Element {eid} fehlt"
    ok("W56: das Panel und seine Anker stehen im Markup")

    # --- 4) Der 409-Fall wird behandelt ----------------------------------
    # Die Route antwortet mit 409, wenn die Zieldatei schon existiert, und
    # verlangt force=true. Ohne diesen Zweig meldet das Deck einen Fehler,
    # obwohl nur eine Rueckfrage noetig waere — und der Betreiber haelt die
    # Funktion fuer kaputt.
    j = deck.find("async function sitzungJoin")
    assert j > 0
    rumpf = deck[j:j + 1400]
    assert "409" in rumpf, "der Fall 'Datei existiert bereits' wird verschluckt"
    assert "force" in rumpf, "ohne force kann nicht ueberschrieben werden"
    # Wieder: nicht die Anwesenheit von confirm, sondern die BEDINGUNG. Ein
    # `if(true||confirm(...))` enthaelt das Wort und fragt trotzdem nie.
    assert "if(confirm(T(" in rumpf, \
        "ueberschrieben wird ohne Rueckfrage — eine fertige Datei waere weg"
    k = rumpf.find("if(confirm(")
    assert "sitzungJoin(sid, true)" in rumpf[k:k + 200], \
        "das Ueberschreiben haengt nicht mehr an der Rueckfrage"
    ok("W56: 'Datei existiert bereits' fuehrt zur Rueckfrage, nicht zum Fehler")


def _test_v42_w55_kein_tap_sagt_warum():
    """v4.2-W55: „audio=False" war EIN Boolescher Wert fuer DREI Ursachen.

    Der Betreiber meldete ein leeres Live-Transkript („Noch nichts gehoert").
    Im Log stand dazu nur:

        live-react gestartet fuer @user (audio=False, chat=True)

    Diese Zeile sagt, DASS nichts geht, und verschweigt als Einzige, WAS. Der
    Tap startet nur bei LIVE_REACT_SPEECH **und** einer Stream-URL **und**
    importierbarem faster-whisper — drei Bedingungen, eine Und-Kette, ein
    Ergebnis. Der Grund musste per Hand rekonstruiert werden, und die
    tatsaechliche Ursache blieb dabei wochenlang unentdeckt: es fehlte die
    STREAM-URL, derselbe Befund wie in v4.2-W51.

    Die Kette dahinter, vollstaendig:

        get_live_status -> ("live", None)        (71 % der Faelle, vor W51)
          -> _get_live_info gibt info=None
          -> _live_react_worker: stream_url = None
          -> kein Audio-Tap, kein Whisper
          -> _live_transcript_push wird nie gerufen
          -> das Deck zeigt "Noch nichts gehoert"

    Genau der stille Schalter, vor dem CLAUDE.md warnt.
    """
    from nc.audiotap import warum_kein_tap as w, KEIN_TAP

    # --- 1) Jede Ursache bekommt ihren eigenen Grund --------------------
    for args, erwartet in (((False, "u", True), "aus"),
                           ((True, None, True), "keine_url"),
                           ((True, "", True), "keine_url"),
                           ((True, "u", False), "kein_whisper")):
        an, grund, text = w(*args)
        assert an is False, args
        assert grund == erwartet, (args, grund, erwartet)
        assert text and text == KEIN_TAP[erwartet], args
    ok("W55: jede der drei Ursachen bekommt ihren eigenen Grund, nicht False")

    # --- 2) Alles da -> Tap laeuft, kein Rauschen -----------------------
    an, grund, text = w(True, "https://x/y.m3u8", True)
    assert an is True and grund == "" and text == "", (an, grund, text)
    ok("W55: sind alle Voraussetzungen da, meldet die Zeile nichts weiter")

    # --- 3) Reihenfolge: das zuerst Behebbare zuerst --------------------
    # Fehlen mehrere, muss der Schalter genannt werden — er erklaert alles
    # Weitere und ist in einer Sekunde umgelegt. Naennte man stattdessen das
    # fehlende Paket, installiert der Betreiber etwas, das er gar nicht
    # gebraucht haette.
    assert w(False, None, False)[1] == "aus"
    assert w(True, None, False)[1] == "keine_url"
    ok("W55: bei mehreren Luecken wird die zuerst behebbare genannt")

    # --- 4) Der Proxy ist KEINE Startbedingung --------------------------
    # Ohne Proxy startet der Tap und stirbt dann ggf. an 403 — das
    # diagnostiziert W46. Ihn hier zur Bedingung zu machen wuerde einen
    # funktionierenden Abgriff ueber eine Direktverbindung verhindern.
    an, grund, text = w(True, "u", True, proxy_da=False)
    assert an is True and grund == "", "der Proxy blockiert den Start"
    assert "403" in text and "RECORD_PROXY" in text, text
    ok("W55: fehlender Proxy verhindert den Start nicht, wird aber genannt")

    # --- 5) bot.py benutzt das, und meldet OHNE Audio auf warning -------
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert "_nc_audiotap.warum_kein_tap(" in flach, \
        "der Worker wertet die Startbedingungen wieder selbst aus"
    assert "LIVE_REACT_SPEECH and stream_url and _faster_whisper_available()" not in flach, \
        "die alte Und-Kette steht noch da — dann gibt es den Grund wieder nicht"
    # Die entscheidende Zusicherung: OHNE Audio darf das nicht auf info stehen.
    i = flach.find("OHNE Audio")
    assert i > 0, "die Zeile ohne Audio-Tap fehlt"
    davor = flach[max(0, i - 200):i]
    assert "log.warning" in davor, \
        "die Meldung ohne Audio-Tap steht auf info — in einem ERROR-Log " \
        "erscheint sie damit NIE, und genau so blieb sie unentdeckt"
    assert "_tap_grund" in flach and "_tap_text" in flach, \
        "Grund und Abhilfe stehen nicht in der Meldung"
    ok("W55: bot.py meldet den Grund, und ohne Audio auf warning statt info")


def _test_v42_w54_sendebild_ausgerichtet():
    """v4.2-W54: der Avatar lag ueber dem Chat, und der Chat lief aus dem Bild.

    Bildschirmfoto des Betreibers: der Avatar verdeckt die halbe rechte
    Spalte — von „S E L I N A  schrecklich, ..." ist nur der Anfang zu lesen.
    Zwei unabhaengige Ursachen, hier nachgestellt und beide behoben.

    (1) REIHENFOLGE. studio_chain haengte Deko UND Texte in EINE Kette und
        legte den Avatar danach darueber. Er lag damit ueber allem.
        Jetzt drei Ketten: Deko -> Avatar -> Texte. Nach der Deko muss er
        bleiben (die drawboxen sind fast deckend und wuerden ihn uebermalen),
        vor die Texte muss er hin.

    (2) UMBRUCHBREITE. RESTREAM_CHAT_WIDTH stand fest auf 62 mit dem
        Kommentar „(Mono)" — die Schrift ist aber proportional. 62 Zeichen
        DejaVu Bold sind bei Schriftgroesse 22 rund 780 px, das Panel hat
        632. Jede laengere Zeile lief rechts raus, mitten im Wort.

    Dazu zwei Dinge, die erst im nachgestellten Bild auffielen: die oberste
    Chat-Zeile war regelmaessig eine nackte Fortsetzungszeile ohne Absender,
    und die unterste stand auf der Fortschrittsleiste.
    """
    from nc import ffmpeg_filters as FF

    # --- 1) Der Avatar liegt zwischen Deko und Text ----------------------
    dateien = {k: f"/tmp/{k}.txt" for k in
               ("title", "source", "caption", "chat", "goal", "follow",
                "react", "brand", "alert")}
    teile, label = FF.studio_chain(dateien, "/f.ttf", 1280, 720, 30,
                                   avatar_idx=1, avatar_alpha_idx=2, avatar_h=420)
    ganz = ";".join(teile)
    i_deko = ganz.find("drawbox=x=588")          # Panel-Grund
    i_av = ganz.find("overlay=x=W-w-")           # der Avatar
    i_chat = ganz.find(dateien["chat"])          # die Chat-Zeile
    assert i_deko >= 0 and i_av >= 0 and i_chat >= 0, (i_deko, i_av, i_chat)
    assert i_deko < i_av < i_chat, (
        "die Reihenfolge stimmt nicht: Deko muss vor dem Avatar liegen (sonst "
        "uebermalt sie ihn) und der Avatar vor dem Chat (sonst verdeckt er ihn)")
    # Und der Avatar darf nicht mehr das letzte Glied sein.
    assert label == "vstudio" and teile[-1].endswith("[vstudio]")
    assert dateien["chat"] in teile[-1], \
        "die Texte sind nicht mehr die letzte Kette — irgendetwas liegt wieder " \
        "ueber dem Chat"
    ok("W54: Deko -> Avatar -> Texte, der Chat liegt vorn")

    # --- 2) Vorn allein reicht nicht: er braucht eine Kontur -------------
    # Heller Text ohne Kontur auf dem roten Gesicht ist auch im Vordergrund
    # nicht zu lesen. borderw=0 stand vorher genau dort.
    chat_filter = [t for t in teile if dateien["chat"] in t][0]
    stueck = chat_filter[chat_filter.find(dateien["chat"]):]
    stueck = stueck[:stueck.find("drawtext") if "drawtext" in stueck[10:] else len(stueck)]
    assert "borderw=0" not in stueck, \
        "der Chat hat wieder borderw=0 — ueber dem Avatar ist er dann unlesbar"
    assert "borderw=3" in stueck, "dem Chat fehlt die Kontur"
    ok("W54: der Chat traegt eine Kontur und bleibt ueber dem Avatar lesbar")

    # --- 3) Der Umbruch kommt aus der Panel-Breite -----------------------
    for w, h in ((1280, 720), (1920, 1080), (2560, 1440)):
        m = FF.studio_masse(w, h)
        n = FF.chat_umbruch_w(w, FF.CHAT_FS)
        breite_px = n * FF.CHAT_FS * FF.ZEICHENBREITE
        assert breite_px <= m["panel_b"], (
            f"bei {w}x{h} braucht eine volle Zeile {breite_px:.0f} px, das Panel "
            f"hat {m['panel_b']} px — der Chat laeuft wieder aus dem Bild")
        # ... aber auch nicht laecherlich schmal: mindestens 85 % ausnutzen.
        assert breite_px >= m["panel_b"] * 0.85, (
            f"bei {w}x{h} nutzt der Chat nur {breite_px:.0f} von {m['panel_b']} px")
    # Die alte feste 62 haette bei 1280 nicht gepasst — das ist der Befund.
    assert 62 * FF.CHAT_FS * FF.ZEICHENBREITE > FF.studio_masse(1280, 720)["panel_b"], \
        "die alte 62 passt ploetzlich doch? Dann stimmt die Zeichenbreite nicht"
    ok("W54: die Umbruchbreite folgt der Panel-Breite, auf jeder Leinwand")

    # --- 4) Der Block bleibt ueber der Ziel-Leiste -----------------------
    for w, h in ((1280, 720), (1920, 1080)):
        m = FF.studio_masse(w, h)
        z = FF.chat_zeilen(m["chat_h"], FF.CHAT_FS, FF.CHAT_ABSTAND)
        hoch = z * (FF.CHAT_FS + FF.CHAT_ABSTAND)
        assert m["chat_y"] + hoch <= m["ziel_y"], (
            f"bei {w}x{h} reicht der Chat bis {m['chat_y'] + hoch}, die "
            f"Fortschrittsleiste steht bei {m['ziel_y']}")
        assert z >= 8, f"nur {z} Chat-Zeilen bei {w}x{h} — das ist kein Chat mehr"
    ok("W54: der Chatblock endet ueber der Fortschrittsleiste")

    # --- 5) Keine nackte Fortsetzungszeile mehr oben ---------------------
    from nc import channels as CH
    alt_l, alt_w = CH._CHAT_LINES, CH._CHAT_WIDTH
    sicherung = list(CH.RESTREAM_CHAT)
    try:
        CH.configure_chat(lines=4, width=40)
        CH.RESTREAM_CHAT.clear()
        for txt in ("kurz",
                    "eine ziemlich lange Nachricht die ganz sicher ueber mehrere "
                    "Zeilen umgebrochen werden muss damit der Schnitt greift",
                    "auch kurz"):
            CH.RESTREAM_CHAT.append({"who": "Tester", "src": "kick",
                                     "text": txt, "origin": ""})
        block = CH._chat_block()
        zeilen = block.split("\n")
        assert zeilen, "leerer Block"
        assert not zeilen[0].startswith("    "), (
            f"die oberste Zeile ist eine Fortsetzung ohne Absender: {zeilen[0]!r} — "
            f"im Sendebild liest sich das wie ein Textfehler")
        assert len(zeilen) <= 4
        # Und jede Zeile bleibt in der Breite.
        for z in zeilen:
            assert len(z) <= 40, (len(z), z)
    finally:
        CH.RESTREAM_CHAT.clear(); CH.RESTREAM_CHAT.extend(sicherung)
        CH.configure_chat(lines=alt_l, width=alt_w)
    ok("W54: der Schnitt landet nie mitten in einer Nachricht")


def _test_v42_w53_avatar_kopf_hand_schwert():
    """v4.2-W53: der Avatar bewegte Kiefer, Aura und Augen — sonst nichts.

    Der Kopf stand still, und Faust und Klinge waren aneinandergenagelt:
    ARM_BOX deckt beide ab und drehte sie um EINEN Punkt. Eine Figur, deren
    Kopf sich minutenlang nicht ruehrt, liest sich als Standbild mit
    zuckendem Mund.

    Neu: Kopf (Neigung um den Hals + Heben/Senken), Klinge (dreht um den
    Griff, die Faust haelt sie), Hand (gibt im Gelenk nach).

    Zwei Fehler sind beim Bauen aufgetreten, und beide stehen hier fest:

    (1) DIE SCHLEIFE MUSS SICH SCHLIESSEN. Das Ergebnis ist eine Schleife —
        nach RUHE_S bzw. SPRECH_S springt der Feeder auf t=0 zurueck. Eine
        Schwingung, deren Periode die Schleifenlaenge nicht ganzzahlig teilt,
        steht dort auf einem anderen Wert als am Anfang und zuckt einmal pro
        Runde. Der erste Entwurf nahm absichtlich teilerfremde Perioden, um
        Gleichtakt zu vermeiden — und zerlegte damit genau die Schleife. Der
        Bestand hatte denselben Fehler schon in der Sprechschleife (Arm auf
        1.15 s, Aura und Augen auf 1.4 s bei 1.6 s Laenge).

    (2) JEDES PIXEL GEHOERT GENAU EINER EBENE. Der erste Entwurf hatte Klinge
        und Hand als Teilmengen des Arms und drehte nacheinander: Arm dreht
        die Klinge mit, danach dreht die Klinge nochmal. Wo die Masken sich
        unterscheiden, blieb die einfach gedrehte Klinge neben der doppelt
        gedrehten stehen — die Spitze stand zweimal im Bild.
    """
    import tools.azrael_frames as A

    # ANKER GEWANDERT (v4.2-W62, nicht der Vertrag): bewegung() bekommt einen
    # ZUSTAND statt eines Booleschen, und es sind drei statt zwei. Die vier
    # Eigenschaften unten gelten unveraendert — nur eben fuer alle drei
    # Schleifen. Der Bool haette hier still weitergelaufen: True ist kein
    # bekannter Zustand, faellt also in den Ruhe-Zweig, und der Vertrag
    # haette die Sprechschleife gegen die Ruhewerte geprueft.
    GLIEDER = ("kopf_grad", "kopf_hoch", "arm_grad", "klinge_grad", "hand_grad")

    def proben(zust, laenge, n=60):
        return [A.bewegung(i * laenge / n, zust) for i in range(n)]

    def spanne(pr, glied):
        return max(p[glied] for p in pr) - min(p[glied] for p in pr)

    # --- 1) Alle drei Glieder bewegen sich ueberhaupt --------------------
    # Ohne diesen Test waere ein Rig, das versehentlich auf 0 steht, unsichtbar:
    # das Bild sieht dann einfach aus wie vorher.
    for zust, laenge in A.SCHLEIFEN:
        pr = proben(zust, laenge)
        for glied in GLIEDER:
            assert spanne(pr, glied) > 0.5, (
                f"{glied} bewegt sich in der {zust}-Schleife nur um "
                f"{spanne(pr, glied):.2f} — das sieht niemand")
    ok("W62: Kopf, Arm, Klinge und Hand bewegen sich in ALLEN DREI Schleifen")

    # --- 2) Die Schleife schliesst sich ---------------------------------
    # Das ist Fehler (1). Gilt bewegung(t) == bewegung(t + L) fuer beliebige t,
    # dann teilt JEDE Periode die Schleifenlaenge ganzzahlig — und nur dann.
    for zust, laenge in A.SCHLEIFEN:
        for i in range(17):
            t = i * laenge / 17.0
            a, b = A.bewegung(t, zust), A.bewegung(t + laenge, zust)
            for k in a:
                assert abs(a[k] - b[k]) < 1e-9, (
                    f"{k} steht in der {zust}-Schleife am Nahtpunkt anders da "
                    f"({a[k]:.4f} vs {b[k]:.4f}): seine Periode teilt {laenge}s "
                    f"nicht ganzzahlig — das Glied zuckt einmal pro Durchlauf")
    ok("W62: alle drei Schleifen schliessen sich — keine Periode bricht die Naht")

    # --- 3) Der Kopf bekommt am wenigsten -------------------------------
    # Er ist das groesste Glied: ein Grad am Hals sind an der Kapuzenspitze
    # zehn Pixel. Was am Arm lebendig aussieht, ist am Kopf ein Wackelkopf.
    #
    # Auf die SPANNE gerechnet, nicht auf max|.|: die AFK-Klinge traegt einen
    # festen Versatz von -4 Grad (gesenkte Spitze), und ein Betragsmaximum
    # vergliche dort Haltung mit Bewegung.
    for zust, laenge in A.SCHLEIFEN:
        pr = proben(zust, laenge)
        assert spanne(pr, "kopf_grad") <= spanne(pr, "klinge_grad"), (
            f"in der {zust}-Schleife schlaegt der Kopf weiter aus als die "
            f"Klinge ({spanne(pr, 'kopf_grad'):.1f} vs "
            f"{spanne(pr, 'klinge_grad'):.1f} Grad) — das ist ein Wackelkopf")
    ok("W62: der Kopf schlaegt in keiner Schleife weiter aus als die Klinge")

    # --- 4) Ruhig, ruhiger, am ruhigsten — aber nirgends still -----------
    # Ein Glied, das in einer Schleife exakt stillsteht, faellt beim
    # Umschalten ruckartig an. Und die Rangfolge muss stimmen: AFK ist
    # ruhiger als Ruhe, Ruhe ruhiger als Sprechen. Ohne diesen Vergleich
    # koennte die AFK-Schleife heftiger zappeln als die aktive, und niemand
    # merkt es ausser dem Zuschauer.
    for glied in ("kopf_grad", "arm_grad", "klinge_grad", "hand_grad"):
        a_, r_, s_ = (spanne(proben(z, L), glied) for z, L in
                      ((A.AFK, A.AFK_S), (A.RUHE, A.RUHE_S), (A.SPRICH, A.SPRECH_S)))
        assert 0.5 < a_ <= r_ < s_, (
            f"{glied}: AFK {a_:.2f}, Ruhe {r_:.2f}, Sprechen {s_:.2f} — "
            f"erwartet ist 0 < AFK <= Ruhe < Sprechen")
    ok("W62: AFK ruhiger als Ruhe, Ruhe ruhiger als Sprechen, nirgends Null")

    # --- 5) Die Drehpunkte liegen dort, wo das Gelenk ist ----------------
    # Der Griff MUSS in der Faust liegen: dreht die Klinge um den Unterarm,
    # wandert die Faust mit und die Bewegung sieht aus wie ein Achselzucken.
    hx, hy = A.KLINGE_DREHPUNKT
    assert A.HAND_BOX[0] <= hx <= A.HAND_BOX[2], "Griff liegt nicht in der Faust"
    assert A.HAND_BOX[1] <= hy <= A.HAND_BOX[3], "Griff liegt nicht in der Faust"
    # Der Halsdrehpunkt gehoert in den weichen Auslauf der Kopfmaske: dort
    # bewirkt die Drehung fast nichts und die Naht zur Schulter bleibt heil.
    assert A.KOPF_DREHPUNKT[1] > A.KOPF_SAUM, \
        "der Halsdrehpunkt liegt oberhalb des Kopfsaums — die Kapuze reisst " \
        "dann an der Schulter auf"
    assert A.KOPF_BOX[1] <= A.KOPF_SAUM <= A.KOPF_BOX[3]
    # Und das Handgelenk unterhalb der Faust: der Unterarm kommt von unten.
    assert A.HAND_DREHPUNKT[1] >= A.HAND_BOX[3] - 30
    ok("W53: Griff in der Faust, Hals im Maskenauslauf, Gelenk unter der Faust")

    # --- 6) Jede Ebene wird aus BASIS gedreht, nie aus dem Zwischenbild ---
    # Das ist Fehler (2). Steht hier wieder `bild.rotate(`, traegt die zweite
    # Drehung die erste huckepack und die Klinge steht doppelt im Bild.
    import inspect as _inspect
    fq = _inspect.getsource(A.frame)
    assert "bild.rotate(" not in fq, \
        "frame() dreht das halbfertige Bild weiter — die Ebene steht dann doppelt"
    assert "(quelle or basis).rotate(" in fq and "basis.rotate(" in fq, \
        "frame() dreht nicht mehr aus basis heraus"
    # Und die Winkel der unteren Ebene wandern in die obere, sonst wiegt der
    # Arm die Klinge nicht mehr mit.
    flach = " ".join(fq.split())
    assert 'b["arm_grad"] + b["klinge_grad"]' in flach, \
        "die Klinge traegt den Armwinkel nicht mehr mit"
    assert 'b["arm_grad"] + b["hand_grad"]' in flach, \
        "die Hand traegt den Armwinkel nicht mehr mit"
    # Jede einzelne Abziehung namentlich — eine Zaehlung (">= 3 mal subtract")
    # haette hier nicht gereicht: faellt eine von vieren weg, zaehlt sie noch
    # drei und bleibt gruen. Genau das ist die Mutationsprobe durchgerutscht.
    fm = _inspect.getsource(A._masken)
    fmf = " ".join(fm.split())
    for wer, muster in (
            ("Klinge", "klinge = ImageChops.subtract(_ellipse(groesse, KLINGE_BOX, 20), hand)"),
            ("Kopf", "kopf = ImageChops.subtract(_kopf_maske(groesse), ImageChops.lighter(hand, klinge))"),
            ("Arm", "arm = ImageChops.subtract(_ellipse(groesse, ARM_BOX, 22), belegt)")):
        assert muster in fmf, (
            f"der {wer}-Maske wird nichts mehr abgezogen — sie ueberlappt wieder "
            f"mit einer hoeher liegenden Ebene, und dieselben Pixel werden zweimal "
            f"gedreht gezeichnet")
    ok("W53: jede Ebene dreht aus basis, jede Maske bekommt ihren Abzug")

    # --- 6b) Und die Masken ueberlappen wirklich nicht -------------------
    # Der Quelltext-Test oben sagt nur, dass DA ein subtract steht. Ob die
    # Masken dadurch tatsaechlich auseinandergehen, sagt nur die Geometrie.
    # Sie braucht Pillow — das fehlt in der CI bewusst, hier laeuft der Test
    # also nur auf der Baumaschine. Gemessen wird der Anteil einer Maske, der
    # unter einer anderen liegt: bei Verschachtelung geht er gegen 1.
    try:
        A._pil()
    except SystemExit:
        ok("W53: (Maskengeometrie uebersprungen — kein Pillow, das ist hier richtig)")
    else:
        m = A._masken((1024, 1024))
        roh = {k: list(v.getdata()) for k, v in m.items() if k != "kiefer"}
        schlimmster, wo = 0.0, None
        for a_ in roh:
            for b_ in roh:
                if a_ == b_:
                    continue
                ueber = sum(min(x, y) for x, y in zip(roh[a_], roh[b_]))
                anteil = ueber / max(1, sum(roh[a_]))
                if anteil > schlimmster:
                    schlimmster, wo = anteil, f"{a_} liegt zu {anteil:.0%} unter {b_}"
        # Gemessen: 0.21 im schlimmsten Fall (Hand/Arm, das weiche Nahtband).
        # Mit der alten Verschachtelung waren es 0.93 (Klinge im Arm) und
        # 0.96 (Hand im Arm). 0.35 trennt beides sauber.
        assert schlimmster < 0.35, (
            f"die Masken liegen wieder ineinander ({wo}) — dieselben Pixel "
            f"werden zweimal gedreht, die Klinge steht doppelt im Bild")
        ok(f"W53: die Masken ueberlappen nur im Nahtband (schlimmstenfalls {schlimmster:.0%})")

    # --- 7) Pillow bleibt draussen ---------------------------------------
    # Der ganze Vertrag oben laeuft nur, weil das Modul ohne Pillow
    # importierbar ist. Pillow steht bewusst in keiner requirements-Datei.
    kopf = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                             "tools", "azrael_frames.py"), encoding="utf-8").read()
    vor_def = kopf[:kopf.find("def _pil(")]
    assert "from PIL import" not in vor_def, \
        "Pillow wird wieder auf Modulebene importiert — dann laeuft dieser " \
        "Vertrag in der CI nicht mehr, wo Pillow fehlt"
    for datei in ("requirements.txt", "requirements-smoke.txt"):
        pfad = os.path.join(os.path.dirname(os.path.abspath(__file__)), datei)
        if os.path.isfile(pfad):
            assert "pillow" not in open(pfad, encoding="utf-8").read().lower(), \
                f"Pillow ist in {datei} gerutscht — es ist ein Werkzeug, keine Laufzeit"
    ok("W53: die Bewegungsrechnung braucht kein Pillow, der Bot erst recht nicht")


def _test_v42_w52_flv_zaehlt_auch():
    """v4.2-W52: der Annahme-Test hinter dem HTML-Weg war enger als der
    Nachschlag, der ihn ausloest — und warf die stabilere Quelle weg.

    Drei Stellen beantworten „traegt das eine Stream-URL?", zwei liessen
    hls ODER flv gelten, eine verlangte hls:

        braucht_url_nachschlag   hls oder flv    (W51)
        reccmd._has_stream_url   hls oder flv
        bot.py, Annahme des HTML-Treffers        NUR hls   <-- eng

    Ein HTML-Treffer mit nur flv_url fiel damit durch, der Bot blieb bei
    ("live", None) und der Recorder loeste wieder selbst auf. Ausgerechnet
    FLV: der Restream-Pfad bevorzugt es, weil HLS eine Kette signierter
    Segmente ist, die abreisst (rc=187), FLV dagegen EINE Verbindung.

    Seit W51 haengen daran rund zwei Drittel aller Aufloesungen statt des
    seltenen `unknown`-Falls. Die Enge ist dadurch von einer Randnotiz zu
    einem taeglichen Verlust geworden.
    """
    from nc import livefolge as L

    # --- 1) Der eine Test, beide Formen ---------------------------------
    h = L.hat_stream_url
    assert h({"flv_url": "https://x/y.flv"}) is True, \
        "FLV allein muss zaehlen — es ist die stabilere Quelle, nicht die " \
        "schlechtere"
    assert h({"hls_url": "https://x/y.m3u8"}) is True
    assert h({"hls_url": "https://a", "flv_url": "https://b"}) is True
    assert h({}) is False and h(None) is False
    assert h({"title": "nur Titel"}) is False
    assert h({"hls_url": "", "flv_url": ""}) is False, \
        "leere Zeichenketten sind keine URL, sondern ein leerer Resolver"
    ok("W52: hat_stream_url laesst hls UND flv gelten, Leeres nicht")

    # --- 2) Nachschlag und Annahme benutzen DENSELBEN Test ---------------
    # Sonst driften sie wieder auseinander: genau so entstand der Befund.
    import inspect as _inspect
    src = _inspect.getsource(L.braucht_url_nachschlag)
    assert "hat_stream_url(info)" in src, \
        "braucht_url_nachschlag rechnet wieder selbst statt hat_stream_url " \
        "zu benutzen — die beiden koennen dann erneut auseinanderlaufen"
    # Und die Umkehrung muss ueber alle vier Ecken gelten.
    for inf in ({}, None, {"hls_url": "u"}, {"flv_url": "u"},
                {"hls_url": "", "flv_url": ""}, {"hls_url": "a", "flv_url": "b"}):
        assert L.braucht_url_nachschlag("live", inf) is (not h(inf)), inf
    ok("W52: bei 'live' ist Nachschlag exakt die Umkehrung von hat_stream_url")

    # --- 3) bot.py nimmt den HTML-Treffer ueber denselben Test an --------
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert "_nc_live.hat_stream_url(html_info)" in flach, \
        "der HTML-Treffer wird nicht ueber den gemeinsamen Test angenommen"
    assert 'if html_info and html_info.get("hls_url"):' not in flach, \
        "die enge Fassung steht noch da — flv-only faellt weiter durch"
    ok("W52: bot.py nimmt auch einen reinen FLV-Treffer an")

    # --- 4) Und der Recorder-Test bleibt gleichbedeutend -----------------
    # reccmd hat eine eigene, gleichlautende Fassung. Sie darf abweichen,
    # solange sie DASSELBE sagt — driftet sie, liegt hier wieder ein Loch.
    rc = open(os.path.join(hier, "nc", "reccmd.py"), encoding="utf-8").read()
    i = rc.find("def _has_stream_url")
    assert i > 0
    rumpf = rc[i:i + 200]
    assert 'get("hls_url")' in rumpf and 'get("flv_url")' in rumpf, \
        "reccmd._has_stream_url laesst nicht mehr beide Formen gelten"
    ok("W52: der Recorder-Test sagt dasselbe wie hat_stream_url")


def _test_v42_w51_live_ohne_url():
    """v4.2-W51: der Weg zur Stream-URL lief ausgerechnet im haeufigsten Fall
    nicht.

    Gemessen im Log vom 11.09., 84 Aufloesungen in zehn Minuten:

        60x  webcast-api @USER: status=live ohne Stream-URL -> live
        24x  webcast-api resolved @USER (hls=yes, flv=yes, codec=h264, q=hd)
        28x  ytdlp @USER rc=1: The channel is not currently live

    **71 % der Erkennungen melden „live" ohne URL.** TikTok gibt sie einer
    Datacenter-IP nicht heraus. `get_live_status` gab das als ("live", None)
    zurueck — und kehrte SOFORT zurueck. Der HTML-Weg, der die URL haette
    liefern koennen, lief nur bei `unknown`:

        if status == "unknown":
            html_info = await _resolve_via_html(...)

    Der Recorder startete also blind und quittierte mit „not currently live".

    yt-dlp hilft hier nicht: `_resolve_via_ytdlp` gibt auch bei „live"
    grundsaetzlich info=None zurueck. Es beantwortet „sendet er?", nicht
    „wohin greife ich?".
    """
    from nc import livefolge as L

    # --- 1) Wann wird nachgeschlagen ------------------------------------
    f = L.braucht_url_nachschlag
    assert f("unknown", None) is True, "unknown muss weitersuchen (wie bisher)"
    assert f("live", None) is True, "genau der Fall, der 60x auftrat"
    assert f("live", {}) is True
    assert f("live", {"title": "nur Titel"}) is True, \
        "info ohne URL ist so gut wie kein info"
    # ... und wann NICHT.
    assert f("live", {"hls_url": "https://x/y.m3u8"}) is False
    assert f("live", {"flv_url": "https://x/y.flv"}) is False
    assert f("offline", None) is False, \
        "sagt die API klar offline, glauben wir das — sonst ein zweiter " \
        "Rundlauf pro Poll und Nutzer bei einem Dienst, der rate-limitet"
    assert f("ratelimited", None) is False, "ein 429 wird nicht nachgefasst"
    ok("W51: nachgeschlagen wird bei unknown UND bei live-ohne-URL, sonst nicht")

    # --- 2) Kein Absturz an kaputten Eingaben ----------------------------
    for st, inf in (("live", {"hls_url": ""}), ("live", {"hls_url": None}),
                    (None, None), ("", {})):
        assert isinstance(f(st, inf), bool), (st, inf)
    assert f("live", {"hls_url": ""}) is True, "leere URL ist keine URL"
    ok("W51: leere und kaputte Eingaben ergeben eine Entscheidung, keinen Fehler")

    # --- 3) Und bot.py benutzt genau diese Entscheidung ------------------
    hier = os.path.dirname(os.path.abspath(__file__))
    bot = open(os.path.join(hier, "bot.py"), encoding="utf-8").read()
    flach = " ".join(bot.split())
    assert "_nc_live.braucht_url_nachschlag(status, info)" in flach, \
        "get_live_status benutzt die Entscheidung nicht"
    # Die alte, engere Bedingung darf nicht daneben stehenbleiben.
    assert 'if status == "unknown": # 2. HTML-Fallback' not in flach, \
        "die alte Fassung steht noch da"
    # Der HTML-Weg ist der einzige, der eine URL liefern kann — er muss im
    # selben Zweig gerufen werden.
    i = flach.find("_nc_live.braucht_url_nachschlag(status, info)")
    assert i > 0
    fenster = flach[i:i + 700]
    assert "_resolve_via_html(username, session)" in fenster, \
        "im Nachschlag-Zweig wird der HTML-Weg nicht gerufen"
    ok("W51: bot.py schlaegt im selben Zweig ueber den HTML-Weg nach")

    # --- 4) Beide Ausgaenge stehen im Log --------------------------------
    # Ohne das waere die Welle nicht messbar: niemand koennte sagen, wie oft
    # der Nachschlag wirklich eine URL bringt. Genau diese Frage stellt sich
    # nach jeder dieser Wellen.
    # Auf die MARKIERUNG pruefen, nicht auf den ganzen Satz: beide Meldungen
    # sind ueber zwei Zeilen umbrochen, und ein zusammenhaengender Anker
    # faende sie nie — auch nicht in der geflachten Fassung, weil zwischen
    # zwei Literalen ein Leerzeichen steht. Das Praefix steht in EINEM Literal.
    # v4.2-W102: DREI Ausgaenge, nicht mehr zwei — der yt-dlp-Weg ist
    # dazugekommen. Jeder einzelne muss im Log stehen, sonst ist nicht
    # messbar, WELCHER Weg die Adresse bringt; und genau diese Frage stellt
    # sich nach dieser Welle noch dringender als nach W51.
    #
    # v4.2-W103: der Anker war `bot.count('log.info("live-ohne-URL @%s:')`.
    # Er ist auf 0 gefallen, und zwar zu Recht: die drei Zeilen laufen jetzt
    # ueber `_ohne_url_melden` und damit durch nc/meldetakt.py. Der Grund
    # steht im Log des Betreibers vom 01.10. — SIEBZIG gleiche Zeilen in
    # achtzehn Minuten fuer EINEN Nutzer, bei 40 Trackings unlesbar. Geprueft
    # wird deshalb die Aussage (drei unterscheidbare Ausgaenge, gedrosselt)
    # statt der Schreibweise `log.info`.
    # ANKER GEWANDERT (v5.4-W195): gezaehlt wurde in ganz bot.py. Seither ruft
    # auch der webcast-Zweig „live ohne stream_data" (_live_ohne_stream) und die
    # Raumsperre-Probe den Kanal — beide liegen AUSSERHALB des Nachschlags. Die
    # Aussage betrifft die drei Ausgaenge DES Nachschlags, also wird dort gezaehlt.
    _nachschlag = rumpf_ab(bot, bot.index("async def _url_nachschlag("))
    assert _nachschlag.count("_ohne_url_melden(") == 3, \
        ("alle drei Ausgaenge des Nachschlags muessen gemeldet werden — sonst "
         "kann niemand sagen, welcher Weg wirklich eine URL bringt: %d gefunden"
         % _nachschlag.count("_ohne_url_melden("))
    assert "HTML-Weg liefert die " in bot, "der HTML-Erfolg fehlt"
    assert "yt-dlp liefert die " in bot, "der yt-dlp-Erfolg fehlt"
    assert "weder HTML noch yt-dlp " in bot, "der Misserfolg fehlt"
    assert "RECORD_PROXY" in bot
    # Und alle drei tragen DASSELBE PRAEFIX. Das ist keine Kosmetik: der
    # Betreiber sucht sie mit
    #     journalctl -u tiktok-bot -f | grep -E "live-ohne-URL|Restream @"
    # Verliert ein Ausgang das Praefix, fehlt er in genau dieser Ansicht, und
    # zwar lautlos. Die Mutationsprobe dazu war nach W103 entwischt, weil die
    # Zaehlung oben nur noch den Melder prueft — ein Befund am Vertrag.
    assert bot.count("live-ohne-URL @%s:") == 3, \
        ("die drei Ausgaenge tragen nicht dasselbe Praefix — der grep des "
         "Betreibers findet dann nur einen Teil: %d von 3"
         % bot.count("live-ohne-URL @%s:"))
    ok("W51/W102/W103: alle drei Ausgaenge werden gemeldet, gedrosselt")
    ok("W103: und sie tragen dasselbe Praefix, damit ein grep sie alle findet")

    # --- 5) yt-dlp IST jetzt drin — und die Warnung von W51 gilt weiter ---
    #
    # Hier stand bis v4.2-W102 das Gegenteil: „yt-dlp bleibt aussen vor, und
    # zwar begruendet", mit der Zusicherung `'return "live", None' in _yt` und
    # der Fehlermeldung „liefert jetzt doch eine URL? Dann gehoert es in den
    # Nachschlag — und dieser Vertrag angepasst". Genau das ist passiert, und
    # genau so ist es gemacht: die Adresse stand die ganze Zeit im JSON und
    # wurde als Ja/Nein-Frage gelesen.
    #
    # Die Warnung, die W51 daneben hinterlassen hat, ist damit NICHT erledigt:
    # „Wer das spaeter ,vergisst`, baut einen Subprozess-Aufruf in den
    # haeufigsten Pfad ein — 20 s Timeout, je Poll und Nutzer." Der Zweig IST
    # der haeufigste (71 %), und `_get_resolve_semaphore()` laesst nur zwei
    # Aufloesungen gleichzeitig. Deshalb wird hier die Taktung gesichert, nicht
    # nur das Vorhandensein des Wegs.
    _yt = bot[bot.find("async def _resolve_via_ytdlp"):]
    _yt = _yt[:_yt.find("\nasync def ", 10)]
    assert 'return "live", None' not in " ".join(_yt.split()), \
        "der yt-dlp-Weg wirft die Adresse wieder weg"
    _darf = bot[bot.find("def _darf_ytdlp_nachschlagen"):]
    _darf = _darf[:_darf.find("\nasync def ", 10)]
    assert "YTDLP_NACHSCHLAG_RUHE_S" in _darf, \
        "der Nachschlag laeuft ungetaktet — ein yt-dlp-Subprozess je Poll und " \
        "Nutzer staut die Live-Erkennung hinter der Semaphore auf (W51-Warnung)"
    _nach = bot[bot.find("async def _nachschlag_ytdlp"):]
    _nach = _nach[:_nach.find("\nasync def ", 10)]
    assert _nach.index("_YTDLP_NACHSCHLAG_ZULETZT[username]") \
        < _nach.index("_resolve_via_ytdlp(username)"), \
        "der Zeitstempel steht NACH dem Aufruf — ein yt-dlp, das in den " \
        "20-s-Timeout laeuft, setzt die Ruhezeit dann nie und kostet beim " \
        "naechsten Poll sofort wieder 20 s"
    ok("W51: yt-dlp liefert weiterhin keine URL und bleibt aus dem Nachschlag")


def _test_v42_w83_werkzeuge_messen_oder_brechen():
    """v4.2-W83: die Sperren waren falsch-gruen, sobald bot.py nicht parste.

    Fuenf Werkzeuge zaehlen den Bestand und sperren sein Wachstum. Vier davon
    hatten dieselbe Schleife, und jede endete gleich:

        try:
            baum = ast.parse(...)
        except (OSError, SyntaxError):
            continue          # blindstellen sogar: except Exception

    Das ist der stille except-Block, gegen den diese Werkzeuge gebaut wurden —
    im Werkzeug selbst, und dort schlimmer als im Bot. bot.py ist rund die
    Haelfte des Produktionscodes; faellt die Datei aus der Messung, meldet die
    Sperre nicht "ich konnte nicht nachsehen", sondern einen FORTSCHRITT.

    Gemessen am 13.09. auf Python 3.11 (dort stirbt ast.parse(bot.py) an
    PEP 701, f-string mit Backslash, Zeile 16235):

        stillecheck --sperre  ->  "OK — 733 stille Bloecke,
                                   –352 seit der Grundlinie"       Exit 0
        monolith   --sperre  ->  "OK — 100 Z: 22, 200 Z: 6 …"      Exit 0

        tatsaechlich (3.13):      1085 stille Bloecke
                                  100 Z: 63, 200 Z: 16

    Die CI faehrt 3.12/3.13 und misst dort richtig — gerettet war damit nur
    die CI. Jede lokale Pruefung auf einem aelteren Interpreter log, und ein
    echter Syntaxfehler in bot.py haette JEDE Zaehlsperre leichter gemacht
    statt rot.

    Der Vertrag prueft das Verhalten, nicht den Wortlaut: eine Datei, die
    nicht parst, muss die Messung ABBRECHEN.
    """
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import quelle as Q

    # --- 1) parse() gibt nie ein leeres Ergebnis zurueck -----------------
    kaputt = os.path.join(hier, "_w83_kaputt.py")
    with io.open(kaputt, "w", encoding="utf-8") as fh:
        fh.write("def f(:\n    pass\n")
    try:
        gut = Q.parse("nc/dashauth.py")
        assert gut.body, "parse() liefert einen leeren Baum fuer gesunde Quelle"

        try:
            Q.parse(kaputt)
        except Q.QuelleUnlesbar as e:
            assert "_w83_kaputt.py" in str(e), \
                "die Meldung nennt die Datei nicht: %s" % e
        else:
            raise AssertionError(
                "parse() hat eine unlesbare Datei klaglos geschluckt — genau "
                "so entstand die Sperre, die einen Fortschritt meldet")

        # --- 2) baeume() sammelt ALLE Fehler, nicht nur den ersten -------
        try:
            Q.baeume([kaputt, "nc/dashauth.py"])
        except Q.QuelleUnlesbar as e:
            text = str(e)
            assert "NIEDRIG" in text, \
                "die Meldung sagt nicht, in welche RICHTUNG die Messung " \
                "falsch gewesen waere: %s" % text
        else:
            raise AssertionError("baeume() hat die kaputte Datei uebersprungen")

        # --- 3) Exitcode 2, nicht 1 -------------------------------------
        assert Q.abbruch("egal") == 2, \
            "\"ich konnte nicht nachsehen\" muss von \"der Bestand ist " \
            "gewachsen\" (1) unterscheidbar bleiben"

        # --- 4) Die Pflichtdateien muessen in der Messung stecken --------
        assert not Q.pflicht_erfuellt(
            ["bot.py", "discordbot.py", "brain_bridge.py",
             "telegramversand.py"]), \
            "pflicht_erfuellt meldet etwas als fehlend, das dabei ist"
        fehlend = Q.pflicht_erfuellt(["nc/dashauth.py"])
        assert "bot.py" in fehlend, \
            "eine Messung ohne bot.py faellt nicht auf — genau das war der " \
            "Schaden, den keine Ausnahme gemeldet haette"

        # --- 5) Jedes der vier Werkzeuge bricht ab statt zu ueberspringen -
        import monolith as M
        import stillecheck as S
        import blindstellen as B
        import importzeit as I

        for modul in (M, S, B, I):
            assert getattr(modul, "quelle", None) is Q \
                or getattr(modul, "_quelle", None) is Q, \
                "%s parst wieder an sich selbst vorbei" % modul.__name__

        # monolith: _dateien() auf die kaputte Datei umbiegen
        alt = M._dateien
        M._dateien = lambda: ["bot.py", "discordbot.py", "brain_bridge.py",
                              "telegramversand.py", "_w83_kaputt.py"]
        try:
            M.funktionen()
        except Q.QuelleUnlesbar:
            pass
        else:
            raise AssertionError(
                "monolith.funktionen() zaehlt weiter, obwohl eine Datei nicht "
                "lesbar war — die Zahl waere zu niedrig und die Sperre gruen")
        finally:
            M._dateien = alt

        # stillecheck: pruefe_datei darf keine stille Null mehr liefern
        try:
            S.pruefe_datei("_w83_kaputt.py")
        except Q.QuelleUnlesbar:
            pass
        else:
            raise AssertionError(
                "stillecheck.pruefe_datei() liefert wieder (0, 0, 0, []) fuer "
                "eine unlesbare Datei — eine Null, die sich in der Summe wie "
                "ein Erfolg liest")

        # blindstellen: sammle() darf keine leere Liste mehr liefern
        import pathlib as _pl
        try:
            B.sammle(_pl.Path(kaputt))
        except Q.QuelleUnlesbar:
            pass
        else:
            raise AssertionError(
                "blindstellen.sammle() verbucht eine unlesbare Datei wieder "
                "als null Blindstellen")
    finally:
        try:
            os.remove(kaputt)
        except OSError:
            pass

    # --- 6) Die Karte muss aktuell sein ---------------------------------
    # Die "eine Regel" des Projekts steht auf .claude/INDEX.md: nie im
    # Monolithen suchen, sondern erst fragen wo etwas steht. Am 13.09. war die
    # eingecheckte Karte 483 Zeilen veraltet — /healthz stand auf 17805 und
    # lag auf 17839. Ein Index, der um 34 Zeilen danebenliegt, schickt jeden
    # `ncpatch show` an die falsche Stelle.
    import subprocess as _sp
    r = _sp.run([_sys.executable, os.path.join(hier, "tools", "ncpatch.py"),
                 "map", "--check"],
                cwd=hier, capture_output=True, text=True)
    assert r.returncode == 0, \
        ".claude/INDEX.md ist veraltet:\n" + (r.stdout or r.stderr)

    ok("W83: parse() bricht ab statt zu ueberspringen, Exitcode 2 getrennt")
    ok("W83: monolith, stillecheck, blindstellen, importzeit zaehlen nicht "
        "weiter, wenn eine Datei fehlt")
    ok("W83: die Navigationskarte ist aktuell")


def _test_v42_w84_deck_bindet_dicht_und_laeuft_auf_waitress():
    """v4.2-W84: die Schranke war fail-open, der Server war der Entwicklungs-
    server, und der Token stand in der Adresszeile.

    **Fail-open.** `_auth_guard` macht GAR NICHTS, wenn weder DASHBOARD_TOKEN
    noch DASHBOARD_PIN gesetzt ist:

        if not DASHBOARD_TOKEN and not DASHBOARD_PIN:
            return None          # jede Adresse, jeder Pfad, frei

    Bei WEB_HOST=127.0.0.1 ist das richtig. Bei jeder anderen Adresse ist es
    ein offenes Bedienpult im Netz: Cookies lesen, Aufnahmen loeschen,
    Konfiguration zurueckspielen, Log mitlesen. Gemeldet wurde dieser Zustand
    seit v4.1-W30 — laut und auf ERROR. Das war der richtige erste Schritt und
    der falsche letzte: eine Meldung hilft nur dem, der das Log liest.

    Jetzt faellt die Bindung auf Loopback zurueck. Der gefaehrliche Zustand
    ist damit nicht mehr erreichbar, statt beschrieben zu werden. Der Bot
    laeuft weiter — er ist nicht das Dashboard, und ihn wegen einer
    Dashboard-Einstellung sterben zu lassen traefe genau die Arbeit, die
    niemand angefasst hat.

    **Der Server.** `dashboard_app.run(threaded=True)` ist der
    ENTWICKLUNGSSERVER von Werkzeug: ein Thread je Anfrage, unbegrenzt, ohne
    Backlog-Management und ohne sauberes Herunterfahren. Wer den Port
    erreicht, hat den Thread laengst, bevor das Rate-Limit ihn zaehlt.

    Und der Zustand darf nie STILL sein: ein Dev-Server, der unbemerkt im
    Betrieb steht, ist genau die Klasse Blindheit, die dieses Projekt sonst
    misst.
    """
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if hier not in _sys.path:
        _sys.path.insert(0, hier)
    from nc import dashauth as D
    from nc import webserver as W

    def _umgebung(**kv):
        alt = {}
        for k, v in kv.items():
            alt[k] = os.environ.get(k)
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        return alt

    sicher = _umgebung(DASHBOARD_OFFEN_ERLAUBEN=None, DASHBOARD_WERKZEUG=None,
                       DASHBOARD_THREADS=None, WEB_HOST=None,
                       DASHBOARD_TOKEN=None, DASHBOARD_PIN=None)
    try:
        # --- 1) Loopback bleibt Loopback, still -------------------------
        for h in ("127.0.0.1", "localhost", "::1"):
            ziel, meldung = W.bindung(h, False)
            assert ziel == h and meldung == "", \
                "%s ist Loopback und braucht weder Rueckfall noch Meldung" % h

        # --- 2) Geschuetzt darf offen binden, still ---------------------
        ziel, meldung = W.bindung("0.0.0.0", True)
        assert ziel == "0.0.0.0" and meldung == "", \
            "mit Token oder PIN ist offen binden in Ordnung und kein Anlass " \
            "fuer eine Meldung — ein Fehlalarm erzieht zum Ueberlesen"

        # --- 3) Offen UND ungeschuetzt: Rueckfall, nicht nur Meldung ----
        ziel, meldung = W.bindung("0.0.0.0", False)
        assert ziel == "127.0.0.1", \
            "ohne Token und ohne PIN darf das Deck NICHT offen binden — " \
            "gebunden wurde auf %s" % ziel
        for wort in ("DASHBOARD_PIN", "DASHBOARD_TOKEN",
                     "DASHBOARD_OFFEN_ERLAUBEN"):
            assert wort in meldung, \
                "die Meldung nennt den Weg zurueck nicht (%s fehlt)" % wort
        assert "Aufnahme" in meldung, \
            "die Meldung sagt nicht, dass der Bot normal weiterlaeuft — " \
            "dann sucht der Betreiber den Fehler an der falschen Stelle"

        # --- 4) Mit Schalter bleibt es offen, aber laut -----------------
        _umgebung(DASHBOARD_OFFEN_ERLAUBEN="1")
        ziel, meldung = W.bindung("0.0.0.0", False)
        assert ziel == "0.0.0.0", \
            "DASHBOARD_OFFEN_ERLAUBEN=1 muss den alten Weg offen halten — " \
            "eine Sperre ohne Ausweg wird umgangen"
        assert meldung, "offen und ungeschuetzt darf nie still sein"

        # --- 5) dashauth und webserver duerfen nicht auseinanderlaufen --
        # Ohne den Schalter faellt die Bindung zurueck; dann ist NICHTS offen,
        # und lage() duerfte nicht "offen" melden. Genau das waere der
        # Fehlalarm, vor dem der Kopf von nc/dashauth.py warnt.
        _umgebung(WEB_HOST="0.0.0.0", DASHBOARD_OFFEN_ERLAUBEN=None)
        assert D.offen_im_netz() is False, \
            "dashauth meldet das Deck als offen, obwohl die Bindung " \
            "zurueckfaellt — ein Fehlalarm erzieht zum Ueberlesen"
        assert D.zurueckgefallen() is True, \
            "der Rueckfall muss als eigener Zustand sichtbar sein, sonst " \
            "sucht der Betreiber WEB_HOST vergeblich im Netz"
        assert D.lage()[0] is False

        _umgebung(DASHBOARD_OFFEN_ERLAUBEN="1")
        assert D.offen_im_netz() is True and D.zurueckgefallen() is False, \
            "mit Schalter steht das Deck wirklich offen — das muss lage() " \
            "weiterhin melden"
        assert D.lage()[0] is True
        _umgebung(DASHBOARD_OFFEN_ERLAUBEN=None)

        # --- 6) Serverwahl: nie still auf dem Entwicklungsserver --------
        name, warum = W.waehle(False)
        assert name == "waitress", \
            "ohne TLS gehoert das Deck auf waitress, nicht auf den " \
            "Werkzeug-Entwicklungsserver (bekommen: %s)" % name
        assert warum == "", "der Normalfall braucht keine Meldung"

        name, warum = W.waehle(True)
        assert name == "werkzeug" and "TLS" in warum, \
            "waitress kann kein TLS — dann muss es beim Werkzeug-Server " \
            "bleiben UND gesagt werden, warum"
        assert "Reverse-Proxy" in warum, \
            "die Meldung nennt den sauberen Ausweg nicht"

        _umgebung(DASHBOARD_WERKZEUG="1")
        name, warum = W.waehle(False)
        assert name == "werkzeug" and warum, \
            "der Notausgang DASHBOARD_WERKZEUG=1 muss greifen und sich " \
            "melden — ein Dev-Server, der unbemerkt im Betrieb steht, ist " \
            "genau die Blindheit, die dieses Projekt sonst misst"
        _umgebung(DASHBOARD_WERKZEUG=None)

        # --- 7) Thread-Pool ist gedeckelt und einstellbar ---------------
        assert W.threads() == W.THREADS_VORGABE
        _umgebung(DASHBOARD_THREADS="16")
        assert W.threads() == 16
        _umgebung(DASHBOARD_THREADS="0")
        assert W.threads() == W.THREADS_VORGABE, \
            "0 Threads waere ein Deck, das nie antwortet"
        _umgebung(DASHBOARD_THREADS="acht")
        assert W.threads() == W.THREADS_VORGABE, \
            "Unsinn in der .env darf den Start nicht kippen"

        # --- 8) Die beiden Loopback-Listen muessen gleich bleiben -------
        assert set(W.LOOPBACK) == set(D.LOOPBACK), \
            "nc/webserver und nc/dashauth kennen verschiedene " \
            "Loopback-Adressen — dann weichen Meldung und Verhalten " \
            "voneinander ab"
    finally:
        for k, v in sicher.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v

    ok("W84: ohne Geheimnis bindet das Deck auf Loopback statt offen ins Netz")
    ok("W84: dashauth meldet den Rueckfall getrennt vom offenen Deck")
    ok("W84: ohne TLS traegt waitress das Deck, mit TLS sagt es warum nicht")


def _test_v42_w85_schemastand_und_herkunft():
    """v4.2-W85: der Rollback auf eine migrierte Datenbank war unsichtbar,
    und der laufende Bestand liess sich keinem Commit zuordnen.

    **Der Schema-Zaehler.** Das Schema wird bei jedem Start idempotent
    nachgezogen — CREATE TABLE IF NOT EXISTS, _migrate_columns, ddlsafe. Das
    geht VORWAERTS und beantwortet die eine Frage nicht, die ueber den
    gefaehrlichen Fall dieses Deploy-Modells entscheidet: ist die Datenbank
    schon von einer NEUEREN Fassung angefasst worden?

    Ausgeliefert wird per ZIP direkt gegen Produktion, und der Rollback ist
    "die vorige ZIP wieder drueberlegen". Die Datenbank rollt dabei nicht mit
    zurueck. Neue Spalten und Tabellen stoeren alten Code nicht; gefaehrlich
    ist eine Spalte, deren BEDEUTUNG sich geaendert hat — und die sieht man
    erst an falschen Zahlen.

    **Die Herkunft.** tools/deploy.sh liefert sauber aus (Staging, Pruefung,
    Umschwenken), aber nichts sagte hinterher, ob der laufende Bestand einem
    Commit entspricht. Ein Handgriff direkt auf dem Server war unsichtbar und
    wurde beim naechsten Deploy wortlos ueberschrieben — samt der Stoerung,
    die er behoben hatte.

    Gefahren wird gegen eine ECHTE SQLite-Datenbank, nicht gegen den
    Quelltext: die drei Faelle des Zaehlers sind Verhalten, kein Wortlaut.
    """
    import sqlite3 as _sq
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if hier not in _sys.path:
        _sys.path.insert(0, hier)
    from nc import auslieferung as A
    from nc import schemastand as S

    # ── 1) Der Zaehler gegen eine echte Datenbank ───────────────────────
    class _Zeile(dict):
        pass

    def _fabrik(cur, zeile):
        return _Zeile(zip([b[0] for b in cur.description], zeile))

    pfad = os.path.join(_ph.verzeichnis(), "w85.sqlite")
    conn = _sq.connect(pfad)
    conn.row_factory = _fabrik
    try:
        # Dieselben Platzhalter wie das uebrige Schema — die Tabelle muss auf
        # BEIDEN Backends entstehen (Skill nc-datenbank).
        S.lege_an(conn, pk="INTEGER PRIMARY KEY AUTOINCREMENT",
                  txt_idx="TEXT", txt_long="TEXT", tbl_opts="")
        S.lege_an(conn, pk="INTEGER PRIMARY KEY AUTOINCREMENT",
                  txt_idx="TEXT", txt_long="TEXT", tbl_opts="")   # idempotent

        assert S.lies(conn) == 0, \
            "eine frische Datenbank muss 0 melden, nicht abstuerzen — eine " \
            "gewachsene von vor W85 sieht genauso aus"

        # Schreiben und wiederlesen
        S.schreibe(conn, 1, "4.3.1", "2026-09-13T00:00:00+00:00")
        assert S.lies(conn) == 1
        # Zweimal schreiben darf keine zweite Zeile erzeugen: eine Tabelle,
        # die bei jedem Start waechst, ist ein Zwischenspeicher, kein Zustand.
        S.schreibe(conn, 1, "4.3.1", "2026-09-13T00:00:01+00:00")
        anz = conn.execute("SELECT COUNT(*) AS n FROM %s" % S.TABELLE
                           ).fetchone()["n"]
        assert anz == 1, "der Zaehler hat %d Zeilen statt einer" % anz

        # ── 2) Die drei Faelle ──────────────────────────────────────────
        stufe, text = S.pruefe(S.ERWARTET)
        assert stufe == "still" and text == "", \
            "der gesunde Start muss STILL sein — eine Meldung bei jedem " \
            "gesunden Start erzieht dazu, Meldungen zu ueberlesen"

        stufe, text = S.pruefe(S.ERWARTET - 1)
        assert stufe == "info" and str(S.ERWARTET) in text, \
            "der frisch ausgelieferte Fall gehoert auf INFO, mit beiden Zahlen"

        stufe, text = S.pruefe(S.ERWARTET + 3)
        assert stufe == "fehler", \
            "eine Datenbank, die NEUER ist als der Code, ist der einzige " \
            "wirklich gefaehrliche Fall — der darf nicht auf info landen"
        assert str(S.ERWARTET + 3) in text and str(S.ERWARTET) in text, \
            "die Meldung nennt nicht beide Zahlen: %s" % text
        assert "Rollback" in text and "Sicherung" in text, \
            "die Meldung nennt den Grund oder den Weg heraus nicht: %s" % text
    finally:
        conn.close()

    # ── 3) Der Schalter ────────────────────────────────────────────────
    alt = os.environ.get("SCHEMA_STAND_STRENG")
    try:
        os.environ.pop("SCHEMA_STAND_STRENG", None)
        assert S.streng() is False, "ohne Schalter laeuft der Bot weiter"
        os.environ["SCHEMA_STAND_STRENG"] = "1"
        assert S.streng() is True, \
            "eine Regel ohne Ausweg wird umgangen — der Schalter muss greifen"
    finally:
        if alt is None:
            os.environ.pop("SCHEMA_STAND_STRENG", None)
        else:
            os.environ["SCHEMA_STAND_STRENG"] = alt

    # ── 4) init_db schreibt den Stand wirklich fest ─────────────────────
    # Der Quelltext-Blick ist hier die schwaechere Pruefung, aber init_db
    # gegen eine echte Datenbank zu fahren hiesse bot.py zu importieren —
    # das tut test_smoke.py, und dort haengt der Rundlauf (siehe unten).
    b = io.open("bot.py", encoding="utf-8").read()
    # rumpf_ab statt eines festen Fensters: CLAUDE.md nennt `src[i:i + 3000]`
    # namentlich als Bruchstelle, und in W62 hat genau das zugeschlagen.
    rumpf = rumpf_ab(b, b.index("def init_db("))
    assert "_nc_schemastand.lege_an(" in rumpf, "der Zaehler wird nie angelegt"
    assert "_nc_schemastand.schreibe(" in rumpf, "der Stand wird nie festgeschrieben"
    assert "raise RuntimeError" in rumpf, "SCHEMA_STAND_STRENG greift nicht"

    # ── 5) Die Herkunft ────────────────────────────────────────────────
    d = A.stand(frisch=True)
    assert set(d) >= {"commit", "kurz", "zweig", "sauber", "quelle"}, d
    assert d["quelle"] in ("archiv", "git", "unbekannt"), d["quelle"]
    assert d["kurz"] == (d["commit"] or "")[:12]

    # Hier laeuft es aus einem git-Arbeitsbaum — dann MUSS die Herkunft
    # bekannt sein. Faellt das, liest das Modul den Baum nicht mehr.
    if os.path.isdir(os.path.join(hier, ".git")):
        assert d["quelle"] == "git" and d["commit"], \
            "aus einem git-Arbeitsbaum heraus darf die Herkunft nicht " \
            "unbekannt sein: %r" % d

    # Die ausgelieferte Datei hat Vorrang: auf dem Server gibt es kein .git,
    # dort ist sie die einzige Wahrheit.
    import json as _json
    leer = _ph.verzeichnis()
    with io.open(os.path.join(leer, A.DATEI), "w", encoding="utf-8") as fh:
        _json.dump({"commit": "a" * 40, "zweig": "main", "sauber": True,
                    "gebaut_am": "2026-09-13T00:00:00+00:00",
                    "version": "4.3.1"}, fh)
    d2 = A.stand(leer, frisch=True)
    assert d2["quelle"] == "archiv" and d2["kurz"] == "a" * 12, d2
    assert "a" * 12 in A.text(leer)

    # Ohne Datei UND ohne git: "unbekannt", aber kein Absturz und kein
    # Fehlalarm — wer aus dem Repo startet, hat keine Auslieferungsdatei.
    nichts = _ph.verzeichnis()
    d3 = A.stand(nichts, frisch=True)
    assert d3["quelle"] == "unbekannt" and d3["kurz"] == "", d3
    assert "unbekannt" in A.text(nichts)

    # Ein unsauberer Arbeitsbaum MUSS im Text stehen — sonst behauptet
    # /healthz eine Herkunft, die es nicht gibt.
    schmutzig = _ph.verzeichnis()
    with io.open(os.path.join(schmutzig, A.DATEI), "w", encoding="utf-8") as fh:
        _json.dump({"commit": "b" * 40, "zweig": "main", "sauber": False,
                    "gebaut_am": "", "version": "4.3.1"}, fh)
    assert "NICHT SAUBER" in A.text(schmutzig), A.text(schmutzig)

    # ── 6) build_release erzeugt den Stempel VOR dem Packen ────────────
    br = io.open("tools/build_release.py", encoding="utf-8").read()
    assert "AUSLIEFERUNG.json" in br, \
        "der Stempel faehrt nicht im Archiv mit — dann kann /healthz die " \
        "Herkunft auf dem Server nicht kennen"
    assert br.index("_ausl.schreibe(") < br.index("zipfile.ZipFile(ZIEL"), \
        "der Stempel wird NACH dem Packen geschrieben — dann faehrt der " \
        "Stand des vorigen Laufs mit"

    ok("W85: der Schema-Zaehler kennt die drei Faelle, der gefaehrliche ist laut")
    ok("W85: eine zu neue Datenbank wird nicht heruntergeschrieben")
    ok("W85: die Herkunft kommt aus dem Archiv, sonst aus git, sonst ehrlich "
       "\"unbekannt\"")


def _test_v42_w86_vertraege_einzeln_fahrbar():
    """v4.2-W86: die Suiten waren nur ueber ihren eigenen Runner fahrbar.

    22.000 Zeilen, rund 100 Vertragsfunktionen, und genau EIN Weg hinein:
    `python test_nc_modules.py`, alles oder nichts, rund eine Minute je Lauf.
    Wer einen Befund pruefen wollte, zahlte die volle Minute fuer eine Zeile.

    Der Grund war kein Vorsatz, sondern ein Nebeneffekt: der Aufbau der
    Testdatenbank stand mitten in `main()`. Wer einen einzelnen Vertrag
    aufrief, bekam keine konfigurierte Datenbank — `db_conn()` fiel auf den
    Vorgabepfad zurueck und legte ein `tiktok_bot.db` IM ARBEITSVERZEICHNIS
    an. Beim zweiten Lauf starb `_test_dbexport` an "table dbx_t already
    exists", und im Repo lag eine Datenbankdatei, die niemand bestellt hatte.
    Genau so gefunden, beim ersten pytest-Lauf ueber diese Suite.

    Jetzt steht der Aufbau als `richte_testdatenbank_ein()` neben den
    Vertraegen, und `conftest.py` ruft ihn fuer pytest genauso auf wie
    `main()` fuer den alten Weg. BEIDE Wege bleiben: `python
    test_nc_modules.py` ist und bleibt das, was die Pruefkette faehrt.

    Dieser Vertrag laeuft unter BEIDEN Wegen und prueft deshalb nur, was
    ohne einen zweiten pytest-Prozess pruefbar ist. Dass wirklich jeder
    Vertrag einzeln gruen ist, faehrt der CI-Job `Vertraege einzeln
    (pytest)` — hier waere es ein Prozess, der sich selbst startet.
    """
    import json as _json
    import sys as _sys
    hier = os.path.dirname(os.path.abspath(__file__))
    if hier not in _sys.path:
        _sys.path.insert(0, hier)
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))

    # --- 1) Der Aufbau steht NEBEN main(), nicht darin ------------------
    import test_nc_modules as T
    assert callable(getattr(T, "richte_testdatenbank_ein", None)), \
        "der Aufbau der Testdatenbank ist zurueck in main() gewandert — " \
        "dann ist die Suite wieder nur ueber ihren eigenen Runner fahrbar"

    # Er muss wirklich eine EIGENE Datenbank aufmachen, nicht die des
    # laufenden Prozesses weiterbenutzen: sonst haengt jeder Einzellauf am
    # Vorgabepfad und schreibt ins Arbeitsverzeichnis.
    tmp, rid = T.richte_testdatenbank_ein()
    assert os.path.isfile(os.path.join(tmp, "t.db")), \
        "richte_testdatenbank_ein() legt keine eigene Datei an: %s" % tmp
    assert isinstance(rid, int) and rid > 0, \
        "die Aufnahme-Zeile fehlt — Vertraege, die auf ihr aufbauen, " \
        "faenden eine leere Tabelle: %r" % (rid,)

    # --- 2) conftest.py und pytest.ini sind da und greifen --------------
    for datei in ("conftest.py", "pytest.ini"):
        assert os.path.isfile(os.path.join(hier, datei)), \
            "%s fehlt — ohne sie sammelt pytest KEINEN Vertrag und meldet " \
            "trotzdem einen gruenen Lauf ('no tests ran')" % datei

    ini = io.open(os.path.join(hier, "pytest.ini"), encoding="utf-8").read()
    assert "_test_*" in ini, \
        "pytest.ini sammelt nicht `_test_*` — die Vertraege heissen so, " \
        "weil sie aus main() gerufen werden. Ohne diese Zeile findet pytest " \
        "keinen einzigen von ihnen und meldet das als Erfolg"
    for verzeichnis in (".claude", "nc/_vendor"):
        assert verzeichnis in ini, \
            "%s steht nicht in norecursedirs — dort liegen Arbeitskopien " \
            "und Fremdcode, die nie in einen Lauf gehoeren" % verzeichnis

    conf = io.open(os.path.join(hier, "conftest.py"), encoding="utf-8").read()
    assert "richte_testdatenbank_ein" in conf, \
        "conftest.py baut die Datenbank nicht ueber denselben Aufruf auf — " \
        "zwei Stellen, die einen Aufbau nebeneinander pflegen, laufen " \
        "auseinander"
    assert "autouse=True" in conf and 'scope="session"' in conf, \
        "die Fixture ist nicht session-weit und selbsttaetig; die Vertraege " \
        "nehmen keine Parameter und setzen die Umgebung voraus"

    # --- 3) Die Ueberdeckung wird gemessen und gesperrt -----------------
    import ueberdeckung as U
    assert os.path.isfile(U.GRUNDLINIE), \
        "keine Ueberdeckungs-Grundlinie — dann sperrt nichts, und die " \
        "Zahl verfaellt beim ersten ungepruefter Zuwachs"
    basis = _json.loads(io.open(U.GRUNDLINIE, encoding="utf-8").read())
    assert basis.get("anweisungen", 0) > 10000 and basis.get("fehlend", 0) > 0, \
        "die Grundlinie sieht nicht nach einer echten Messung aus: %r" % basis

    # Die Sperre haengt an der ANZAHL, nicht am Prozentsatz. Ein Prozentsatz
    # springt auch dann, wenn nichts schlechter wurde — wer gut gepruefte
    # Zeilen entfernt, senkt ihn.
    quelle = io.open(os.path.join(hier, "tools", "ueberdeckung.py"),
                     encoding="utf-8").read()
    rumpf = rumpf_ab(quelle, quelle.index("def main("))
    assert 'basis.get("fehlend"' in rumpf, \
        "die Sperre vergleicht nicht mehr die Anzahl ungepruefter " \
        "Anweisungen — auf Prozent gesperrt faellt sie bei jedem Umbau"

    # Die Testdateien gehoeren NICHT in die Messung: mitgezaehlt druecken sie
    # die Zahl um rund vier Punkte und stehen als "0 % gedeckt" ganz oben in
    # der Arbeitsliste, wo sie nichts zu suchen haben.
    assert "test_*.py" in U.AUSGENOMMEN, \
        "die Testdateien sind wieder in der Ueberdeckungsmessung"
    assert "_vendor" in U.AUSGENOMMEN, \
        "der vendorierte Fremdcode ist wieder in der Messung"

    ok("W86: der Aufbau der Testdatenbank steht neben den Vertraegen, nicht "
       "in main()")
    ok("W86: conftest.py und pytest.ini machen den einzelnen Vertrag fahrbar")
    ok("W86: die Ueberdeckung ist gemessen und gegen Zuwachs gesperrt")


def _test_v42_w87_director_regie():
    """v4.2-W87: nc/director.py stand auf 0 % Ueberdeckung.

    118 Anweisungen, kein einziger Vertrag — und darin die Geldregel, die
    CLAUDE.md als eigenen Abschnitt fuehrt:

        TikTok-Gifts gehen an den GETRACKTEN Streamer, nicht an eigene
        Kanaele.

    AZRAEL hat sich dafuer einmal bedankt, als waeren es eigene Donations
    (V37-P4a: "peinlich und irrefuehrend"). Der Vorgabewert wurde daraufhin
    umgedreht — und seither hielt ihn NICHTS. Wer
    `os.getenv("AZRAEL_THANK_TRACKED_GIFTS", "0")` beim Aufraeumen auf "1"
    dreht oder die Verzweigung umkehrt, faellt in keinem Lauf auf.

    Die Zeit wird ueber `_time_mod` hereingereicht; der Vertrag setzt sie
    fest, statt mit `sleep` zu arbeiten. Ein Vertrag, der Sekunden verbraucht,
    wird beim naechsten Aufraeumen als "langsam" herausgeworfen.
    """
    import nc.director as D

    class _Uhr:
        """Stellbare Zeit. Ersetzt _time_mod im Modul, nicht global."""
        def __init__(self, t=1000.0):
            self.t = t

        def time(self):
            return self.t

    uhr = _Uhr()
    alt_zeit, alt_env = D._time_mod, os.environ.get("AZRAEL_THANK_TRACKED_GIFTS")
    alt_schwellen = (D.DIRECTOR_MIN_GAP_S, D.DIRECTOR_MAX_GAP_S,
                     D.DIRECTOR_MEM_TURNS, D.DIRECTOR_CHATTERS)
    D._time_mod = uhr
    try:
        # ── 1) DIE GELDREGEL ────────────────────────────────────────────
        os.environ.pop("AZRAEL_THANK_TRACKED_GIFTS", None)
        r = D.LiveDirector("helge_72")
        obs = {"gifts": ["anna sendet eine Rose"], "newcomers": [], "questions": []}
        text = r.direction(obs)
        assert "bedanke dich" in text.lower() and "NICHT" in text, \
            "die Regie sagt AZRAEL nicht, dass er sich fuer fremde Gifts " \
            "NICHT bedanken soll:\n%s" % text
        assert "STREAMER" in text, \
            "die Regie sagt nicht, WEM die Geschenke gehoeren — genau diese " \
            "Verwechslung war V37-P4a:\n%s" % text

        # Das Altverhalten ist weiter erreichbar, aber nur ausdruecklich.
        os.environ["AZRAEL_THANK_TRACKED_GIFTS"] = "1"
        text = D.LiveDirector("x").direction(obs)
        assert "Bedanke dich konkret" in text, \
            "AZRAEL_THANK_TRACKED_GIFTS=1 schaltet das Altverhalten nicht " \
            "mehr frei:\n%s" % text
        for wert in ("0", "", "nein", "irgendwas"):
            os.environ["AZRAEL_THANK_TRACKED_GIFTS"] = wert
            t2 = D.LiveDirector("x").direction(obs)
            assert "Bedanke dich konkret" not in t2, \
                "AZRAEL_THANK_TRACKED_GIFTS=%r bedankt sich trotzdem — nur " \
                "1/true darf das" % wert
        os.environ.pop("AZRAEL_THANK_TRACKED_GIFTS", None)
        ok("W87: die Regie bedankt sich NICHT fuer fremde Gifts (V37-P4a)")

        # ── 2) Wahrnehmung: was ist Gift, Follow, Chat, Frage ───────────
        r = D.LiveDirector("helge_72")
        obs = r.observe_chat([
            "",                                   # leer -> ignoriert
            "anna: hallo zusammen",
            "bernd: wie geht es dir?",            # Frage (? und > 6 Zeichen)
            "anna: nochmal",                      # kein Newcomer mehr
            "carla sendet ein Geschenk",          # Gift
            "➕ dieter folgt jetzt",               # Follow
            "kurz?",                              # Frage zu kurz -> keine
        ])
        assert obs["newcomers"] == ["anna", "bernd"], obs["newcomers"]
        assert obs["gifts"] == ["carla sendet ein Geschenk"], obs["gifts"]
        assert [n for n, _ in obs["questions"]] == ["bernd"], obs["questions"]
        assert r.chatters["anna"]["n"] == 2, "die zweite Zeile zaehlt nicht mit"
        assert r.last_speaker, "kein letzter Sprecher gemerkt"
        # Eine Zeile ohne "name:" ist Text ohne Namen, kein Chatter.
        r2 = D.LiveDirector("x")
        o2 = r2.observe_chat(["nur text ohne doppelpunkt"])
        assert o2["newcomers"] == [] and not r2.chatters, \
            "eine Zeile ohne Namen legt einen Chatter an"
        ok("W87: Gift, Follow, Chat und Frage werden auseinandergehalten")

        # ── 3) Die Chatter-Liste ist gedeckelt ──────────────────────────
        D.configure(chatters=5)
        r = D.LiveDirector("x")
        r.observe_chat(["n%02d: hi" % i for i in range(20)])
        assert len(r.chatters) == 5, \
            "die Chatter-Liste waechst unbegrenzt (%d) — bei einem vollen " \
            "Stream laeuft der Speicher voll" % len(r.chatters)
        assert "n19" in r.chatters and "n00" not in r.chatters, \
            "es fliegen die FALSCHEN heraus — aeltester zuerst ist gemeint"
        ok("W87: die Chatter-Liste ist gedeckelt, aeltester fliegt zuerst")

        # ── 4) Momentum, Stimmung und das Reaktionsfenster ──────────────
        D.configure(min_gap_s=8, max_gap_s=45, mem_turns=8, chatters=40)
        r = D.LiveDirector("x")
        r.started = uhr.t - 100                  # laeuft schon eine Weile
        leer = r.gap_now()
        assert r.mood == "quiet", \
            "ohne jedes Ereignis ist der Stream nicht 'quiet', sondern %r" % r.mood
        assert leer > 30, \
            "bei toter Hose ist das Fenster zu kurz (%.1f s) — AZRAEL " \
            "redet dann in die Stille" % leer

        for _ in range(3):                        # zwei Gifts -> hype
            r.beats.append((uhr.t, "gift"))
        for _ in range(20):
            r.beats.append((uhr.t, "chat"))
        voll = r.gap_now()
        assert r.mood == "hype", "viel Betrieb ergibt nicht 'hype': %r" % r.mood
        assert voll < leer, \
            "das Fenster wird bei viel Betrieb nicht kuerzer (%.1f -> %.1f)" \
            % (leer, voll)
        assert D.DIRECTOR_MIN_GAP_S <= voll <= D.DIRECTOR_MAX_GAP_S, \
            "das Fenster verlaesst die eigenen Schwellen: %.1f" % voll

        # Beats ausserhalb des 20-Sekunden-Fensters zaehlen nicht mehr.
        r3 = D.LiveDirector("x")
        r3.started = uhr.t - 100
        for _ in range(30):
            r3.beats.append((uhr.t - 60, "chat"))     # eine Minute alt
        r3.gap_now()
        assert r3.mood == "quiet", \
            "alte Ereignisse zaehlen noch mit — das Momentum misst dann die " \
            "Vergangenheit: %r" % r3.mood
        ok("W87: Momentum misst nur die letzten 20 s, das Fenster folgt ihm")

        # ── 5) should_react ─────────────────────────────────────────────
        r = D.LiveDirector("x")
        r.last_react = uhr.t                      # gerade eben geredet
        assert r.should_react(has_input=False, gift_priority=False) is False
        assert r.should_react(has_input=True, gift_priority=False) is False, \
            "AZRAEL redet sofort wieder — das Fenster greift nicht"
        assert r.should_react(has_input=False, gift_priority=True) is True, \
            "ein Gift kommt nicht durch, obwohl es Vorrang hat"
        uhr.t += 120                              # lange genug gewartet
        assert r.should_react(has_input=True, gift_priority=False) is True, \
            "nach Ablauf des Fensters reagiert AZRAEL nicht mehr"
        ok("W87: Gift hat Vorrang, sonst gilt das Fenster")

        # ── 6) Begruessung genau EINMAL ─────────────────────────────────
        r = D.LiveDirector("x")
        obs = r.observe_chat(["anna: hi"])
        t1 = r.direction(obs)
        assert "anna" in t1 and "Begrüße" in t1
        t2 = r.direction(obs)                     # dieselbe Beobachtung nochmal
        assert "Begrüße" not in t2, \
            "anna wird zweimal begruesst — das Merkmal 'greeted' greift nicht"
        ok("W87: neu dazugekommene Zuschauer werden genau einmal begruesst")

        # ── 7) Gedaechtnis und Highlights ───────────────────────────────
        D.configure(mem_turns=3)
        r = D.LiveDirector("x")
        for i in range(5):
            r.record("Aussage %d" % i)
        assert len(r.said) == 3, \
            "das Kurzzeitgedaechtnis ist nicht gedeckelt: %d" % len(r.said)
        assert r.react_count == 5 and r.last_react == uhr.t
        assert "NICHT wiederholen" in r.direction({}), \
            "die Regie warnt nicht mehr vor Wiederholung"
        r.record("")                              # leer: kein Eintrag
        assert len(r.said) == 3 and r.react_count == 6, \
            "eine leere Reaktion landet im Gedaechtnis"

        r = D.LiveDirector("x")
        for i in range(20):
            r.record("krass, Nummer %d" % i)
        assert len(r.highlights) == 12, \
            "die Highlight-Liste waechst unbegrenzt: %d" % len(r.highlights)
        r.record("ein ganz normaler Satz")
        assert len(r.highlights) == 12, \
            "ein Satz ohne Schluesselwort wird als Highlight gebucht"
        ok("W87: Gedaechtnis und Highlights sind beide gedeckelt")

        # ── 8) Stammzuschauer, Stimme, Momentaufnahme ───────────────────
        D.configure(mem_turns=8, chatters=40)
        r = D.LiveDirector("helge_72")
        r.observe_chat(["stamm: %d" % i for i in range(6)])   # 6 Nachrichten
        r.observe_chat(["gast: einmal"])
        r.mood = "chill"
        assert "stamm" in r.direction({}) and "gast" not in r.direction({}), \
            "Stammzuschauer werden nicht ab 5 Nachrichten erkannt"

        for stimmung, tempo in (("hype", 1.12), ("drama", 1.0),
                                ("quiet", 0.94), ("chill", 1.0)):
            r.mood = stimmung
            assert r.voice_style()["rate"] == tempo, \
                "%s hat das falsche Sprechtempo" % stimmung
            assert r.voice_style()["tag"], "%s hat keinen Regie-Tag" % stimmung
        r.mood = "voellig unbekannt"
        assert r.voice_style()["rate"] == 1.0, \
            "eine unbekannte Stimmung kippt die Stimme statt neutral zu bleiben"

        uhr.t = r.started + 90
        s = r.snapshot()
        for feld in ("user", "mood", "energy", "reacts", "chatters",
                     "regulars", "highlights", "uptime"):
            assert feld in s, "die Momentaufnahme laesst %s weg: %r" % (feld, s)
        assert s["user"] == "helge_72" and s["uptime"] == 90
        assert s["regulars"] == ["stamm"], s["regulars"]
        ok("W87: Stammzuschauer, Sprechtempo und Momentaufnahme stimmen")
    finally:
        D._time_mod = alt_zeit
        (D.DIRECTOR_MIN_GAP_S, D.DIRECTOR_MAX_GAP_S,
         D.DIRECTOR_MEM_TURNS, D.DIRECTOR_CHATTERS) = alt_schwellen
        if alt_env is None:
            os.environ.pop("AZRAEL_THANK_TRACKED_GIFTS", None)
        else:
            os.environ["AZRAEL_THANK_TRACKED_GIFTS"] = alt_env


def _test_v42_w87_scraper_parser_und_wiederholung():
    """v4.2-W87: nc/scraper.py stand auf 0 % Ueberdeckung.

    101 Anweisungen, kein einziger Vertrag — und darin zwei Stellen, die der
    Quelltext selbst als teuer erkaufte Korrekturen ausweist:

      * `resp.release()` im Wiederholungspfad. Der Kommentar dazu: "Vorher
        leakte jeder Retry eine Connection; bei limit_per_host=8 blockiert
        der naechste GET genau im 429-Sturm (Pool-Starve)." Eine ungelesene
        aiohttp-Antwort haelt ihre Verbindung, bis der Rumpf gelesen oder
        freigegeben ist.
      * `resp.release()` im Nicht-200-Pfad von fetch_profile, aus demselben
        Grund.

    Beide sind reine Aufraeum-Aufrufe. Wer sie beim Umbau verliert, merkt es
    nicht am naechsten Tag, sondern beim naechsten 429-Sturm — und dann sieht
    es aus, als haenge TikTok, nicht der Pool.

    Gefahren wird OHNE Netz: die Sitzung ist eine Attrappe, die die Antworten
    liefert, die der Vertrag braucht. `__init__` wird dabei uebersprungen
    (object.__new__), weil es eine echte aiohttp-Sitzung aufmachen wuerde —
    gemessen wird der Code, der Entscheidungen trifft, nicht der, der
    Verbindungen aufbaut.
    """
    import asyncio as _aio
    import nc.scraper as S

    # ── 1) Der Parser: drei Formen, drei Ergebnisse ────────────────────
    s = object.__new__(S.TikTokScraper)

    universal = ('<html><script id="__UNIVERSAL_DATA_FOR_REHYDRATION__" '
                 'type="application/json">'
                 '{"__DEFAULT_SCOPE__": {"webapp.user-detail": '
                 '{"userInfo": {"user": {"uniqueId": "helge_72", "id": "77"}, '
                 '"stats": {"followerCount": 1234}}}}}'
                 '</script></html>')
    art, daten = s._extract_json(universal)
    assert art == "universal", art
    assert "webapp.user-detail" in daten, daten

    sigi = ('<script id="SIGI_STATE" type="application/json">'
            '{"UserModule": {"users": {"a": {"uniqueId": "Helge_72", "id": "77"}}, '
            '"stats": {"77": {"followerCount": 9}}}}'
            '</script>')
    art, daten = s._extract_json(sigi)
    assert art == "sigi" and "UserModule" in daten, (art, daten)

    art, daten = s._extract_json("<html>nichts davon</html>")
    assert (art, daten) == (None, None), (art, daten)

    # Der Rumpf kommt HTML-maskiert aus der Seite — ohne html.unescape ist es
    # kein gueltiges JSON.
    maskiert = ('<script id="SIGI_STATE" type="application/json">'
                '{&quot;UserModule&quot;: {&quot;users&quot;: {}}}'
                '</script>')
    art, daten = s._extract_json(maskiert)
    assert art == "sigi" and daten == {"UserModule": {"users": {}}}, \
        "der maskierte Rumpf wird nicht entmaskiert: %r" % (daten,)

    # Kaputtes UNIVERSAL faellt auf SIGI durch, statt alles hinzuwerfen.
    gemischt = ('<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__">{kaputt</script>'
                + sigi)
    art, daten = s._extract_json(gemischt)
    assert art == "sigi", \
        "ein kaputter UNIVERSAL-Block verhindert den Rueckfall auf SIGI: %r" % art
    ok("W87: der Parser kennt UNIVERSAL, SIGI, Maskierung und den Rueckfall")

    # ── 2) Nutzer aus beiden Formen ────────────────────────────────────
    assert s._user_from_universal({}) is None
    assert s._user_from_universal({"webapp.user-detail": {}}) is None
    g = s._user_from_universal(
        {"webapp.user-detail": {"userInfo": {"user": {"id": "1"}}}})
    assert g == {"user": {"id": "1"}, "stats": {}}, \
        "fehlende Statistik wird nicht zu einem leeren Woerterbuch: %r" % (g,)

    daten = {"UserModule": {"users": {"k": {"uniqueId": "Helge_72", "id": "77"}},
                            "stats": {"77": {"followerCount": 9}}}}
    g = s._user_from_sigi(daten, "helge_72")
    assert g and g["stats"]["followerCount"] == 9, \
        "die Zuordnung ist nicht schreibungsunabhaengig oder die Statistik " \
        "wird nicht ueber die id gefunden: %r" % (g,)
    assert s._user_from_sigi(daten, "jemand_anders") is None
    assert s._user_from_sigi({}, "x") is None
    ok("W87: Nutzer aus UNIVERSAL und SIGI, schreibungsunabhaengig")

    # ── 3) Letzte Videos: Deckel und Adresse ───────────────────────────
    daten = {"ItemModule": {str(i): {"desc": "d%d" % i,
                                     "author": {"uniqueId": "helge_72"}}
                            for i in range(9)}}
    v = s._recent_videos_sigi(daten, limit=3)
    assert len(v) == 3, "der Deckel greift nicht: %d" % len(v)
    assert v[0]["url"].startswith(S.TikTokScraper.BASE + "/@helge_72/video/"), \
        v[0]["url"]
    assert s._recent_videos_sigi({}) == []
    ok("W87: die letzten Videos sind gedeckelt und tragen eine gueltige Adresse")

    # ── 4) Die Wiederholung — und die freigegebene Verbindung ──────────
    class _Antwort:
        def __init__(self, status, text="", eigner=None):
            self.status = status
            self._text = text
            self._eigner = eigner
            self.freigegeben = False

        def release(self):
            self.freigegeben = True

        async def text(self):
            return self._text

    class _Sitzung:
        """Attrappe: liefert die vorbereiteten Antworten der Reihe nach."""
        def __init__(self, antworten):
            self.antworten = list(antworten)
            self.ausgeliefert = []
            self.kwargs = []

        async def get(self, url, **kw):
            self.kwargs.append(kw)
            a = self.antworten.pop(0)
            if isinstance(a, Exception):
                raise a
            self.ausgeliefert.append(a)
            return a

    def _fahre(coro):
        """Eine Coroutine fahren und die Schleife WIEDER SCHLIESSEN.

        Ohne das close() raeumt erst der Garbage Collector auf, und zwar beim
        Herunterfahren des Interpreters — dort kippt BaseEventLoop.__del__ mit
        "ValueError: Invalid file descriptor: -1" hinter den fertigen Bericht.
        Der Lauf war gruen, die letzte Zeile ein Traceback: genau die Sorte
        Rauschen, die man nach dreimal Sehen ueberliest. In einem Vertrag ueber
        Verbindungslecks waere das doppelt peinlich.
        """
        schleife = _aio.new_event_loop()
        try:
            return schleife.run_until_complete(coro)
        finally:
            schleife.close()

    geschlafen = []

    async def _kein_schlaf(s_):
        geschlafen.append(s_)

    alt_sleep, alt_proxy = _aio.sleep, S.get_random_proxy
    S.asyncio.sleep = _kein_schlaf
    S.get_random_proxy = lambda: "http://proxy:8080"
    try:
        # 429, dann 200: die erste Antwort MUSS freigegeben werden.
        erst, dann = _Antwort(429), _Antwort(200, "ok")
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([erst, dann])
        r = _fahre(s._request("https://x/"))
        assert r is dann, "der Wiederholungslauf liefert die falsche Antwort"
        assert erst.freigegeben, (
            "die verworfene Antwort wird NICHT freigegeben — genau der "
            "Verbindungs-Leak, den der Kommentar im Quelltext beschreibt: "
            "bei limit_per_host=8 blockiert der naechste GET im 429-Sturm")
        assert geschlafen, "zwischen den Versuchen wird nicht gewartet"
        assert s.session.kwargs[0].get("proxy") == "http://proxy:8080", \
            "der Proxy aus nc.proxyutil wird nicht durchgereicht: %r" % s.session.kwargs[0]

        # Ein ausdruecklich gesetzter Proxy hat Vorrang.
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([_Antwort(200)])
        _fahre(s._request("https://x/", proxy="http://eigener:1"))
        assert s.session.kwargs[0]["proxy"] == "http://eigener:1", \
            "ein mitgegebener Proxy wird ueberschrieben"

        # Dreimal 503: danach kommt die Antwort durch, nicht eine Ausnahme —
        # der dritte Versuch gibt zurueck, was er hat.
        s = object.__new__(S.TikTokScraper)
        letzte = _Antwort(503)
        s.session = _Sitzung([_Antwort(503), _Antwort(503), letzte])
        r = _fahre(s._request("https://x/"))
        assert r is letzte, "nach drei Versuchen kommt die Antwort nicht durch"
        assert not letzte.freigegeben, \
            "die letzte Antwort wird freigegeben, obwohl sie zurueckgegeben " \
            "wird — der Aufrufer bekaeme einen leeren Rumpf"

        # 404 wird NICHT wiederholt: es wird nicht besser.
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([_Antwort(404), _Antwort(200)])
        r = _fahre(s._request("https://x/"))
        assert r.status == 404, "ein 404 wird wiederholt — das wird nie besser"

        # Ausnahmen: zweimal scheitern, dann gut. Dreimal -> durchreichen.
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([OSError("weg"), OSError("weg"), _Antwort(200)])
        assert _fahre(s._request("https://x/")).status == 200
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([OSError("a"), OSError("b"), OSError("c")])
        try:
            _fahre(s._request("https://x/"))
        except OSError:
            pass
        else:
            raise AssertionError(
                "nach drei Fehlversuchen kommt keine Ausnahme heraus — der "
                "Aufrufer haelt einen Ausfall fuer einen Erfolg")
        ok("W87: die Wiederholung gibt die verworfene Verbindung frei "
           "(Pool-Starve im 429-Sturm)")

        # ── 5) fetch_profile: alle Ausgaenge ───────────────────────────
        # Nicht-200: Rumpf nie gelesen -> muss freigegeben werden.
        s = object.__new__(S.TikTokScraper)
        a = _Antwort(403)
        s.session = _Sitzung([a])
        r = _fahre(s.fetch_profile("helge_72"))
        assert r["ok"] is False and r["http_status"] == 403
        assert r["error"] == "HTTP 403", r["error"]
        assert a.freigegeben, \
            "bei einem Nicht-200 wird der Rumpf nie gelesen UND nicht " \
            "freigegeben — die Verbindung leakt"

        # Netzfehler
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([OSError("x"), OSError("y"), OSError("z")])
        r = _fahre(s.fetch_profile("helge_72"))
        assert r["ok"] is False and r["error"].startswith("Request:"), r["error"]

        # 200, aber kein JSON in der Seite
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([_Antwort(200, "<html>leer</html>")])
        r = _fahre(s.fetch_profile("helge_72"))
        assert r["ok"] is False and "JSON nicht gefunden" in r["error"], r
        # Genau dieser Fall heisst "TikTok hat sein HTML geaendert" — er darf
        # nie als Erfolg mit leeren Zahlen durchgehen.
        assert r.get("follower_count") is None

        # 200 mit JSON, aber der Nutzer steckt nicht drin
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([_Antwort(200, sigi)])
        r = _fahre(s.fetch_profile("jemand_anders"))
        assert r["ok"] is False and r["error"] == "Benutzerdaten nicht gefunden"

        # Der Erfolgsfall, ueber UNIVERSAL
        voll = ('<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__">'
                '{"__DEFAULT_SCOPE__": {"webapp.user-detail": {"userInfo": '
                '{"user": {"id": "77", "secUid": "sec", "uniqueId": "helge_72",'
                ' "nickname": "Helge", "avatarThumb": "klein",'
                ' "privateAccount": false, "verified": true},'
                ' "stats": {"followerCount": 1234, "heart": 99}}}}}'
                '</script>')
        s = object.__new__(S.TikTokScraper)
        s.session = _Sitzung([_Antwort(200, voll)])
        r = _fahre(s.fetch_profile("helge_72"))
        assert r["ok"] is True, r
        assert r["user_id"] == "77" and r["sec_uid"] == "sec"
        assert r["follower_count"] == 1234
        assert r["avatar"] == "klein", \
            "der Rueckfall auf avatarThumb greift nicht: %r" % r["avatar"]
        assert r["heart_count"] == 99, \
            "der Rueckfall von heartCount auf heart greift nicht: %r" % r
        assert r["verified"] is True and r["private"] is False
        ok("W87: fetch_profile kennt alle fuenf Ausgaenge und gibt die "
           "Verbindung frei")
    finally:
        S.asyncio.sleep = alt_sleep
        S.get_random_proxy = alt_proxy

    # ── 6) Die Kopfzeilen kommen per Injektion ─────────────────────────
    alt_kopf = S._LIVE_RESOLVER_HEADERS
    try:
        S.configure_scraper(live_resolver_headers={"User-Agent": "NC"})
        assert S._LIVE_RESOLVER_HEADERS == {"User-Agent": "NC"}
        S.configure_scraper(live_resolver_headers=None)      # darf nicht leeren
        assert S._LIVE_RESOLVER_HEADERS == {"User-Agent": "NC"}, \
            "configure_scraper(None) loescht die Kopfzeilen — dann startet " \
            "der Scraper ohne Browser-Tarnung und TikTok antwortet mit 403"
    finally:
        S._LIVE_RESOLVER_HEADERS = alt_kopf
    ok("W87: configure_scraper injiziert, None loescht nicht")


def _test_v42_w88_scoring_bewertet():
    """v4.2-W88: nc/scoring.py entschied ueber jede Aufnahme und war ungeprueft.

    99 Anweisungen, 5 % gedeckt. compute_quality_score ist die Zahl, an der
    der Betreiber im Dashboard abliest, ob eine Aufnahme brauchbar ist —
    und sie hat keinen lauten Fehlerfall: jeder Zweig liefert eine Zahl
    zwischen 0 und 100 zurueck, auch der, der sich verrechnet. Verschiebt
    jemand eine Stufe (>= 1080 auf > 1080) oder faellt eine Komponente
    stumm auf 0, sieht das Ergebnis genauso plausibel aus wie vorher; der
    Fehler faellt erst auf, wenn eine 1080p-Aufnahme als "mittel" gemeldet
    wird und niemand mehr weiss, seit wann.

    Gepruefte Entscheidungen: die vier Hoehenstufen, die Codec-Klassen, die
    beiden Bildratenstufen, die Bitraten- und Kanalstufen des Tons, der
    5-%-Toleranzring um die Soll-Dauer, die vier Groessenstufen und die
    Notizen, die ein leeres ffprobe-Ergebnis ueberhaupt erst sichtbar
    machen. Dazu build_report: die HTML-Maskierung (Telegram lehnt eine
    Nachricht mit unmaskiertem "<b>" im Nicknamen komplett ab — der Report
    kommt dann gar nicht an, nicht etwa haesslich) und die 180-Zeichen-
    Grenze, ab der die Bio eingeklappt wird.
    """
    import re as _re

    import nc.scoring as _sc

    def _video(h=1080, codec="h264", fps="30/1"):
        return {"codec_type": "video", "height": h, "codec_name": codec,
                "r_frame_rate": fps}

    def _audio(br=128000, ch=2):
        return {"codec_type": "audio", "bit_rate": br, "channels": ch}

    def _daten(streams, fmt=None):
        return {"streams": streams, "format": {} if fmt is None else fmt}

    # --- 1) KEIN ffprobe-ERGEBNIS IST KEINE GUTE AUFNAHME ----------------
    # Der teure Fall: ffprobe scheitert (Datei halb geschrieben, Codec
    # unbekannt), der Aufrufer bekommt ein leeres dict — und der Score
    # muss 0 sein UND sagen warum. Ohne die Notiz sieht 0 aus wie
    # "Aufnahme kaputt", nicht wie "wir haben gar nicht hingesehen".
    for leer in ({}, None, []):
        r = _sc.compute_quality_score(leer, 200 * 1024 * 1024, 3600)
        assert r["score"] == 0, \
            "leeres ffprobe-Ergebnis %r ergibt Score %r statt 0 — eine " \
            "Aufnahme, ueber die nichts bekannt ist, bekommt Punkte" % (
                leer, r["score"])
        assert r["components"] == {}, \
            "leeres ffprobe-Ergebnis liefert Komponenten %r — der Aufrufer " \
            "haelt das fuer eine Messung" % (r["components"],)
        assert r["notes"] == ["no inspect-data"], \
            "leeres ffprobe-Ergebnis meldet nicht, DASS nicht gemessen " \
            "wurde: %r" % (r["notes"],)
    ok("W88: ohne ffprobe-Daten Score 0 mit Begruendung statt stiller Null")

    # --- 2) DIE VIER HOEHENSTUFEN, JEWEILS AUF DEM RAND ------------------
    # 5 (Stream existiert) + Hoehe + 5 (h264) + 5 (30 fps).
    for h, erwartet in ((2160, 30), (1080, 30), (1079, 27), (720, 27),
                        (719, 23), (480, 23), (479, 19), (1, 19), (0, 15)):
        r = _sc.compute_quality_score(_daten([_video(h=h)]), 0, 0)
        assert r["components"]["video"] == erwartet, \
            "Hoehe %s wird mit %s statt %s bewertet — eine Stufengrenze " \
            "ist verschoben, jede Aufnahme dieser Klasse wird ab jetzt " \
            "falsch einsortiert" % (h, r["components"]["video"], erwartet)
    r = _sc.compute_quality_score(_daten([_video(h=0)]), 0, 0)
    assert "no video dimensions" in r["notes"], \
        "ein Videostream ohne Masse wird nicht gemeldet — im Dashboard " \
        "steht dann nur eine kleinere Zahl ohne Grund: %r" % (r["notes"],)
    r = _sc.compute_quality_score(_daten([_video(h="krumm")]), 0, 0)
    assert r["components"]["video"] == 5 and "video parse error" in r["notes"], \
        "eine unlesbare Hoehe verschwindet still statt als Befund " \
        "aufzutauchen: %r / %r" % (r["components"], r["notes"])
    r = _sc.compute_quality_score(_daten([_audio()]), 0, 0)
    assert r["components"]["video"] == 0 and "no video stream" in r["notes"], \
        "eine Tonspur ohne Bild gilt nicht als Befund — genau so sieht " \
        "ein abgerissener Pull aus: %r / %r" % (r["components"], r["notes"])
    ok("W88: Hoehenstufen 1080/720/480 liegen auf dem Rand, Fehlfaelle melden")

    # --- 3) CODEC-KLASSEN, KLEINSCHREIBUNG INBEGRIFFEN -------------------
    # ffprobe liefert "h264", aber nicht jede Quelle tut das; ohne .lower()
    # faellt "H264" in die Restklasse und verliert 3 Punkte.
    for codec, bonus in (("h264", 5), ("hevc", 5), ("av1", 5), ("H264", 5),
                         ("vp9", 2), ("", 0), (None, 0)):
        r = _sc.compute_quality_score(
            _daten([_video(h=1080, codec=codec, fps="0/1")]), 0, 0)
        assert r["components"]["video"] == 20 + bonus, \
            "Codec %r bringt %s statt %s Punkte" % (
                codec, r["components"]["video"] - 20, bonus)
    ok("W88: Codec-Klassen bewertet, Grossschreibung faellt nicht durch")

    # --- 4) BILDRATE: ZWEI STUFEN UND DREI ZERBRECHLICHE EINGABEN --------
    # r_frame_rate kommt als Bruch. "30/0" und ein fehlender Wert duerfen
    # den Score nicht abreissen lassen, sondern 0 Punkte ergeben.
    for fps, bonus in (("60/1", 5), ("25/1", 5), ("24000/1001", 3),
                       ("15/1", 3), ("14/1", 0), ("30/0", 0),
                       ("kaputt", 0), (None, 0)):
        r = _sc.compute_quality_score(_daten([_video(fps=fps)]), 0, 0)
        assert r["components"]["video"] == 25 + bonus, \
            "Bildrate %r bringt %s statt %s Punkte — bei %r darf der Score " \
            "weder abstuerzen noch heimlich Punkte vergeben" % (
                fps, r["components"]["video"] - 25, bonus, fps)
    ok("W88: Bildratenstufen 25/15 und die drei kaputten Bruchformen")

    # --- 5) TON: BITRATE UND KANAELE ------------------------------------
    for br, ch, erwartet in ((128000, 2, 20), (127999, 2, 17), (64000, 2, 17),
                             (63999, 2, 14), (1, 2, 14), (0, 2, 10),
                             (128000, 1, 18), (128000, 0, 15)):
        r = _sc.compute_quality_score(_daten([_video(), _audio(br, ch)]), 0, 0)
        assert r["components"]["audio"] == erwartet, \
            "Ton mit %s bit/s und %s Kanaelen ergibt %s statt %s" % (
                br, ch, r["components"]["audio"], erwartet)
    r = _sc.compute_quality_score(_daten([_video()]), 0, 0)
    assert r["components"]["audio"] == 0 and "no audio stream" in r["notes"], \
        "eine stumme Aufnahme faellt nicht auf — das ist der haeufigste " \
        "Reklamationsfall ueberhaupt: %r / %r" % (r["components"], r["notes"])
    r = _sc.compute_quality_score(
        _daten([_video(), {"codec_type": "audio", "bit_rate": "krumm",
                           "channels": 2}]), 0, 0)
    assert r["components"]["audio"] == 5 and "audio parse error" in r["notes"], \
        "eine unlesbare Ton-Bitrate verschwindet still: %r / %r" % (
            r["components"], r["notes"])
    ok("W88: Tonstufen 128k/64k und 2/1 Kanaele, Fehlfaelle melden")

    # --- 6) DAUER: DER 5-%-RING UM DIE SOLL-DAUER -----------------------
    # Der Ring ist die einzige Stelle, an der der Score merkt, dass eine
    # Aufnahme ABGERISSEN ist: der Container sagt 100 s, aufgenommen werden
    # sollten 3600. Wird die Toleranz zu weit, meldet ein Torso volle Punkte.
    r = _sc.compute_quality_score({"streams": [_video()], "format": {}}, 0, 0)
    assert r["components"]["container"] == 0, \
        "ohne Container-Daten gibt es Punkte: %r" % (r["components"],)
    r = _sc.compute_quality_score(_daten([_video()], {"duration": "0"}), 0, 0)
    assert r["components"]["container"] == 5, \
        "Container ohne Dauer bekommt %s statt 5" % r["components"]["container"]
    r = _sc.compute_quality_score(_daten([_video()], {"duration": "100"}), 0, 0)
    assert r["components"]["container"] == 10, \
        "Container mit Dauer, aber ohne Soll-Dauer bekommt %s statt 10 — " \
        "ohne Soll-Wert darf der Abgleich nicht greifen" % (
            r["components"]["container"],)
    for krumm in ({"duration": "krumm"}, {"duration": "100", "bit_rate": "x"}):
        r = _sc.compute_quality_score(_daten([_video()], krumm), 0, 100.0)
        assert r["components"]["container"] in (5, 15), \
            "ein unlesbarer Container-Wert (%r) reisst die Bewertung mit " \
            "oder vergibt Punkte aus dem Nichts: %r" % (
                krumm, r["components"])
    for soll, erwartet in ((100.0, 15), (104.9, 15), (95.2, 15),
                           (105.1, 10), (94.0, 10), (3600.0, 10)):
        r = _sc.compute_quality_score(
            _daten([_video()], {"duration": "100"}), 0, soll)
        assert r["components"]["container"] == erwartet, \
            "Container-Dauer 100 s gegen Soll %s s ergibt %s statt %s — " \
            "der 5-%%-Ring ist verrutscht, ein Abriss faellt nicht mehr " \
            "auf" % (soll, r["components"]["container"], erwartet)
    ok("W88: Soll-Dauer-Abgleich haelt den 5-%-Ring, Abriss verliert Punkte")

    # --- 7) GROESSE: VIER STUFEN UND DIE NULL ---------------------------
    # 35 der 100 Punkte haengen allein an der Dateigroesse. Eine Aufnahme,
    # die nach zwei Sekunden abgerissen ist, faellt hier auf, auch wenn
    # ffprobe ueber die ersten Frames nichts zu meckern hat.
    for groesse, erwartet in ((50 * 1024 * 1024, 35),
                              (50 * 1024 * 1024 - 1, 25),
                              (10 * 1024 * 1024, 25),
                              (10 * 1024 * 1024 - 1, 15),
                              (1024 * 1024, 15), (1024 * 1024 - 1, 5), (1, 5),
                              (0, 0), (None, 0)):
        r = _sc.compute_quality_score(_daten([_video()]), groesse, 0)
        assert r["components"]["size"] == erwartet, \
            "Dateigroesse %r bringt %s statt %s Punkte" % (
                groesse, r["components"]["size"], erwartet)
    for groesse in (0, None):
        r = _sc.compute_quality_score(_daten([_video()]), groesse, 0)
        assert "zero file size" in r["notes"], \
            "eine leere Datei wird nicht gemeldet — genau die entsteht, " \
            "wenn ffmpeg sofort abbricht: %r" % (r["notes"],)
    ok("W88: Groessenstufen 50/10/1 MB, leere Datei meldet sich")

    # --- 8) DIE SUMME IST DIE 100 --------------------------------------
    # Wenn die Teilmaxima nicht mehr 30/20/15/35 sind, ist eine tadellose
    # Aufnahme ploetzlich nicht mehr 100 — und niemand kann mehr sagen, ob
    # eine 92 an der Aufnahme oder an der Bewertung liegt.
    best = _sc.compute_quality_score(
        _daten([_video(), _audio()],
               {"duration": "3600", "bit_rate": "2500000"}),
        200 * 1024 * 1024, 3600.0)
    assert best["components"] == {"video": 30, "audio": 20, "container": 15,
                                  "size": 35}, \
        "die Teilmaxima sind nicht mehr 30/20/15/35: %r" % (best["components"],)
    assert best["score"] == 100 and not best["notes"], \
        "eine tadellose Aufnahme erreicht keine 100: %r" % (best,)
    assert best["score"] == sum(best["components"].values()), \
        "der Score ist nicht mehr die Summe seiner Teile — dann erklaert " \
        "die Aufschluesselung im Dashboard die Zahl daneben nicht mehr"
    mager = _sc.compute_quality_score(_daten([{"codec_type": "data"}]), 0, 0)
    assert mager["score"] == 0 and sorted(mager["notes"]) == [
        "no audio stream", "no video stream", "zero file size"], \
        "eine Datei ohne Bild, Ton und Inhalt meldet nicht alle drei " \
        "Gruende: %r" % (mager["notes"],)
    ok("W88: Score ist die Summe, Maximum genau 100, Minimum begruendet")

    # --- 9) build_report: DIE MASKIERUNG IST KEIN SCHOENHEITSFEHLER -----
    # Telegram parst den Report als HTML. Ein unmaskiertes "<b>" im
    # Nicknamen laesst die GANZE Nachricht mit "can't parse entities"
    # scheitern — der Betreiber bekommt dann gar keinen Report, nicht
    # etwa einen haesslichen.
    daten = {"unique_id": "nachtfalter", "nickname": "<b>Hack</b>",
             "verified": 1, "private": 1, "sec_uid": "S" * 40,
             "user_id": "7100", "follower_count": 1234567,
             "following_count": None, "heart_count": 42,
             "create_time": 1600000000, "modify_time": "krumm"}
    text = _sc.build_report(daten, {"is_live": True})
    assert "&lt;b&gt;Hack&lt;/b&gt;" in text and "<b>Hack</b>" not in text, \
        "der Nickname steht unmaskiert im Report — Telegram lehnt die " \
        "ganze Nachricht mit 'can't parse entities' ab"
    assert "@nachtfalter" in text, "der Handle fehlt im Kopf: %r" % text[:120]
    for fahne in ("✓ verified", "\U0001f512 privat", "\U0001f534 LIVE"):
        assert fahne in text, "Fahne %r fehlt, obwohl gesetzt" % fahne
    assert "public" not in text, \
        "ein privates Profil wird zusaetzlich als 'public' ausgewiesen"
    assert "1.234.567" in text, \
        "die Followerzahl wird nicht mit Tausenderpunkt gesetzt"
    assert "Unbekannt" in text, \
        "eine fehlende Zahl faellt nicht auf 'Unbekannt' zurueck, sondern " \
        "auf etwas anderes — dann steht dort eine erfundene Zahl"
    assert len(_re.findall(r"S{20}\.\.\.", text)) == 1, \
        "die SecUID wird nicht auf 20 Zeichen gekuerzt — sie sprengt die " \
        "Tabelle im <pre>-Block"
    assert _re.search(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", text), \
        "die Erstellungszeit wird nicht als Datum gesetzt"
    assert "—" in text, \
        "eine unlesbare Zeitangabe ergibt keinen Gedankenstrich, sondern " \
        "laesst den Report scheitern oder zeigt 1970"

    offen = _sc.build_report({"username": "tagfalter"}, {})
    assert "@tagfalter" in offen, \
        "ohne unique_id faellt der Handle nicht auf username zurueck"
    assert "public" in offen and "\U0001f512 privat" not in offen, \
        "ein oeffentliches Profil wird nicht als solches ausgewiesen"
    assert "\U0001f534 LIVE" not in offen, \
        "ein Profil ohne Live-Status traegt trotzdem die LIVE-Fahne — " \
        "danach ruft der Betreiber einen Stream ab, den es nicht gibt"

    # Die 180er-Grenze: darueber klappt Telegram die Bio ein. Wandert die
    # Grenze, wird aus einer langen Bio eine Nachrichtenwand.
    kurz = _sc.build_report({"unique_id": "a", "signature": "x" * 180}, {})
    lang = _sc.build_report({"unique_id": "a", "signature": "x" * 181}, {})
    assert "<blockquote>" in kurz and "expandable" not in kurz, \
        "eine 180 Zeichen lange Bio wird schon eingeklappt"
    assert "<blockquote expandable>" in lang, \
        "eine 181 Zeichen lange Bio wird nicht eingeklappt"
    assert lang.count("</blockquote>") == 1, \
        "die Bio wird nicht geschlossen — Telegram bricht daran ab"
    ohne = _sc.build_report({"unique_id": "a", "signature": "   "}, {})
    assert "Bio" not in ohne, \
        "eine leere Bio bekommt trotzdem eine Ueberschrift"

    videos = _sc.build_report(
        {"unique_id": "a", "recent_videos": [
            {"desc": "erstes", "url": "https://t/1"},
            {"desc": "zweites", "url": "https://t/2"}]}, {})
    assert '1. <a href="https://t/1">' in videos and \
           '2. <a href="https://t/2">' in videos, \
        "die Videoliste ist nicht ab 1 durchnummeriert oder verliert die " \
        "Verweise: %r" % videos[-200:]
    ok("W88: Report maskiert, faellt zurueck und klappt ab 181 Zeichen ein")


def _test_v42_w88_preflight_prueft():
    """v4.2-W88: der CDN-404-Schutz war die letzte Instanz vor dem ffmpeg.

    60 Anweisungen, 13 % gedeckt — und das an der Stelle, an der TikToks
    CDN-Quirk entschieden wird: die Pull-URL traegt ein _hd/_uhd-Suffix,
    unter dem nichts liegt, waehrend die nackte Variante laeuft. Faellt der
    Fallback aus, bricht jede Aufnahme sofort ab und im Log steht nur, dass
    ffmpeg nichts bekommen hat.

    Zwei Fehlerbilder, die dieser Vertrag festnagelt. Erstens: ein
    Netzfehler darf NICHT zu "tot" fuehren — der Preflight ist ein Schutz,
    kein Torwaechter, und ein wackelnder Proxy wuerde sonst jede Aufnahme
    verhindern (fail-open mit dem Original). Zweitens: ein leerer
    RECORD_PROXY darf nicht als Proxy durchgereicht werden; aiohttp wirft
    auf "" und der Preflight faellt dann bei JEDER URL in den
    Netzfehler-Zweig, also still auf fail-open — der Schutz waere
    abgeschaltet, ohne dass eine Zeile im Log steht.

    Dazu die Zaehler: _PREFLIGHT_STATS speist das Dashboard, und
    _PREFLIGHT_DEAD_STREAK entscheidet, welche Quelle dem Brain als
    chronisch tot vorgeschlagen wird. Ein Erfolg, der die Serie nicht
    zuruecksetzt, macht aus einer einmal ausgefallenen Quelle dauerhaft
    einen Untrack-Vorschlag. Beide Deckel (300) haengen mit dran: ohne sie
    waechst ein Prozess-Speicher, der nie neu startet.

    Netz wird nicht angefasst — aiohttp wird fuer die Dauer des Vertrags
    durch eine Attrappe in sys.modules ersetzt.
    """
    import asyncio as _asyncio
    import sys as _sys

    import nc.preflight as _pf

    protokoll = []          # jede abgefragte URL in Reihenfolge
    proxys = []             # der proxy=, mit dem sie abgefragt wurde
    plan = {}               # URL -> HTTP-Status, "netz" fuer Verbindungsfehler

    class _Antwort:
        def __init__(self, status):
            self.status = status

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Sitzung:
        def __init__(self, *a, **k):
            pass

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

        def get(self, url, proxy=None, **k):
            protokoll.append(url)
            proxys.append(proxy)
            wert = plan.get(url, 404)
            if wert == "netz":
                raise OSError("Verbindung vom Proxy zurueckgesetzt")
            return _Antwort(wert)

    class _FalscherAiohttp:
        ClientSession = _Sitzung

        @staticmethod
        def ClientTimeout(**k):
            return None

    class _StillerLog:
        """Faengt die Meldungen ab, statt die Suite vollzuschreiben — und
           macht die Stufe pruefbar: ein Totfall auf debug waere fuer den
           Betreiber dasselbe wie gar keine Meldung."""

        def __init__(self):
            self.zeilen = []

        def _sammle(self, stufe):
            def _f(fmt, *a):
                self.zeilen.append((stufe, fmt % a if a else fmt))
            return _f

        def __getattr__(self, name):
            return self._sammle(name)

    def _lauf(u, who="tester"):
        del protokoll[:], proxys[:]
        return _asyncio.run(_pf._preflight_url(u, who))

    alt_aio = _sys.modules.get("aiohttp")
    alt_log, alt_proxy = _pf.log, _pf.RECORD_PROXY
    alt_cache = dict(_pf._PREFLIGHT_CACHE)
    alt_stats = dict(_pf._PREFLIGHT_STATS)
    alt_streak = dict(_pf._PREFLIGHT_DEAD_STREAK)
    schrift = _StillerLog()
    try:
        _sys.modules["aiohttp"] = _FalscherAiohttp
        _pf._PREFLIGHT_CACHE.clear()
        _pf._PREFLIGHT_DEAD_STREAK.clear()
        _pf._PREFLIGHT_STATS.update(ok=0, fallback=0, dead=0, gestoert=0)

        # --- 0) configure() ist der einzige Weg herein ------------------
        _pf.configure(logger=schrift, record_proxy="")
        assert _pf.log is schrift, \
            "configure() nimmt den Logger des Bots nicht an — dann meldet " \
            "der Preflight in einen Logger, den niemand liest"
        _pf.configure()
        assert _pf.log is schrift and _pf.RECORD_PROXY == "", \
            "ein configure() ohne Argumente setzt die Verdrahtung zurueck"

        # --- 1) LEERE URL GEHT UNVERAENDERT ZURUECK --------------------
        for leer in ("", None):
            assert _lauf(leer) == leer, \
                "eine leere URL wird umgeschrieben statt durchgereicht"
            assert not protokoll, \
                "fuer eine leere URL wird eine Abfrage abgesetzt: %r" % protokoll
        assert _pf._PREFLIGHT_STATS == {"ok": 0, "fallback": 0, "dead": 0,
                                        "gestoert": 0}, \
            "eine leere URL bewegt die Telemetrie: %r" % (_pf._PREFLIGHT_STATS,)
        ok("W88: leere Pull-URL wird durchgereicht, ohne zu zaehlen")

        # --- 2) DIE URL LEBT: ORIGINAL ZURUECK, SPUREN AUFGERAEUMT -----
        gut = "https://pull.tiktokcdn.com/live.flv?a=1"
        plan.clear()
        plan[gut] = 200
        _pf._PREFLIGHT_CACHE["tester"] = "_hd"
        _pf._PREFLIGHT_DEAD_STREAK["tester"] = 4
        assert _lauf(gut) == gut, \
            "eine funktionierende URL wird nicht unveraendert zurueckgegeben"
        assert protokoll == [gut], \
            "eine funktionierende URL erzeugt zusaetzliche Abfragen: %r" % (
                protokoll,)
        assert _pf._PREFLIGHT_STATS["ok"] == 1, "der ok-Zaehler steht still"
        assert "tester" not in _pf._PREFLIGHT_CACHE, \
            "der alte Suffix-Merker bleibt liegen, obwohl das Original wieder " \
            "laeuft — die naechste Aufnahme faengt wieder mit der falschen " \
            "Variante an"
        assert "tester" not in _pf._PREFLIGHT_DEAD_STREAK, \
            "die Tot-Serie wird vom Erfolg nicht zurueckgesetzt — aus einem " \
            "einmaligen Ausfall wird ein dauerhafter Untrack-Vorschlag"
        ok("W88: lebende URL zaehlt ok und raeumt Merker und Tot-Serie ab")

        # --- 3) 404 AUF DEM SUFFIX, DIE NACKTE VARIANTE LAEUFT ---------
        hd = "https://pull.tiktokcdn.com/live_hd.flv?a=1"
        nackt = "https://pull.tiktokcdn.com/live.flv?a=1"
        plan.clear()
        plan[hd] = 404
        plan[nackt] = 200
        assert _lauf(hd) == nackt, \
            "der _hd-Fallback greift nicht — genau das ist der CDN-Quirk, " \
            "gegen den das Modul gebaut wurde; ffmpeg bekaeme eine 404-URL"
        assert protokoll[0] == hd, \
            "das Original wird nicht zuerst geprueft: %r" % protokoll
        assert _pf._PREFLIGHT_STATS["fallback"] == 1, \
            "der Fallback wird nicht gezaehlt — im Dashboard sieht der Quirk " \
            "dann aus, als gaebe es ihn nicht"
        assert _pf._PREFLIGHT_CACHE.get("tester") == "_hd", \
            "der greifende Suffix wird nicht gemerkt: %r" % (
                _pf._PREFLIGHT_CACHE,)

        # ... und beim naechsten Mal steht er VORNE. Ohne das kostet jede
        # Aufnahme dieser Quelle eine zusaetzliche 404-Runde.
        assert _lauf(hd) == nackt and protokoll[0] == nackt, \
            "der gemerkte Suffix wird nicht bevorzugt abgefragt: %r" % (
                protokoll,)
        ok("W88: _hd-Fallback greift, wird gezaehlt, gemerkt und bevorzugt")

        # --- 4) DIE VARIANTENBILDUNG DECKT .flv UND .m3u8 AB -----------
        for quelle, erwartet in (
                ("https://p.cdn/li_uhd.flv", "https://p.cdn/li.flv"),
                ("https://p.cdn/li_sd/index.m3u8", "https://p.cdn/li/index.m3u8"),
                ("https://p.cdn/li_ld.m3u8", "https://p.cdn/li.m3u8")):
            plan.clear()
            plan[quelle] = 404
            plan[erwartet] = 200
            assert _lauf(quelle, "v-" + erwartet) == erwartet, \
                "aus %s wird keine Variante %s gebildet — der Quirk trifft " \
                "alle vier Suffixe und beide Containerformen" % (quelle, erwartet)
        plan.clear()
        _lauf("https://p.cdn/li_hd.flv", "dubletten")
        assert len(protokoll) == len(set(protokoll)), \
            "dieselbe Variante wird mehrfach abgefragt: %r" % protokoll
        ok("W88: Varianten fuer _hd/_uhd/_sd/_ld, flv wie m3u8, ohne Dubletten")

        # --- 5) ALLES TOT: None, ZAEHLER, SERIE UND EINE LAUTE ZEILE ---
        tot = "https://p.cdn/weg_hd.flv"
        plan.clear()
        del schrift.zeilen[:]
        _pf._PREFLIGHT_STATS["dead"] = 0   # der Dublettenlauf oben war tot
        assert _lauf(tot, "toter") is None, \
            "eine durchweg tote URL wird nicht als None gemeldet — ffmpeg " \
            "startet dann gegen eine 404 und der Fehler landet erst dort"
        assert _pf._PREFLIGHT_STATS["dead"] == 1, "der dead-Zaehler steht still"
        assert _pf._PREFLIGHT_DEAD_STREAK["toter"] == 1, \
            "die Tot-Serie wird nicht gefuehrt: %r" % (
                _pf._PREFLIGHT_DEAD_STREAK,)
        assert any(stufe == "warning" for stufe, _ in schrift.zeilen), \
            "der Totfall meldet sich nicht auf warning — auf debug sieht " \
            "ihn der Betreiber nie: %r" % (schrift.zeilen,)
        _lauf(tot, "toter")
        assert _pf._PREFLIGHT_DEAD_STREAK["toter"] == 2, \
            "die Tot-Serie zaehlt nicht hoch — dann schlaegt das Brain nie " \
            "eine chronisch tote Quelle zum Untracken vor"
        ok("W88: durchweg tote URL meldet None, zaehlt und fuehrt die Serie")

        # --- 6) NETZFEHLER IST NICHT TOT (fail-open) -------------------
        wackel = "https://p.cdn/wackel_hd.flv"
        plan.clear()
        plan[wackel] = "netz"
        vorher = dict(_pf._PREFLIGHT_STATS)
        assert _lauf(wackel, "wackler") == wackel, \
            "ein Verbindungsfehler wird als 'tot' gewertet — ein wackelnder " \
            "Proxy verhindert dann JEDE Aufnahme, obwohl der Stream laeuft"
        # v4.2-W89: der Stoerfall zaehlt auf `gestoert`, und NUR darauf. Vorher
        # stand hier `== vorher`, also "bewegt nichts" — der Fall war damit
        # ueberhaupt nicht in der Telemetrie, und genau deshalb konnte niemand
        # sehen, wie oft der Preflight gar nichts gemessen hat. Steigt
        # `gestoert` und nicht `dead`, liegt es am Weg nach aussen, nicht an
        # den Quellen; das ist die Unterscheidung, um die es geht.
        assert _pf._PREFLIGHT_STATS["gestoert"] == vorher["gestoert"] + 1, \
            "der Stoerfall wird nicht gezaehlt — dann ist er in der " \
            "Telemetrie nicht von einem gesunden Lauf zu unterscheiden: %r" % (
                _pf._PREFLIGHT_STATS,)
        for _k in ("ok", "fallback", "dead"):
            assert _pf._PREFLIGHT_STATS[_k] == vorher[_k], \
                "ein Verbindungsfehler bewegt %r — vor allem `dead` darf er " \
                "NICHT bewegen: daran haengt der Untrack-Vorschlag: %r" % (
                    _k, _pf._PREFLIGHT_STATS)
        assert "wackler" not in _pf._PREFLIGHT_DEAD_STREAK, \
            "ein Verbindungsfehler laesst die Quelle in die Tot-Serie laufen"

        # --- 6b) W89: EIN NETZFEHLER BEENDET DIE SUCHE NICHT -----------
        # Der eigentliche Fehler, den W89 behoben hat, und der teuerste des
        # Moduls: in der Kandidatenschleife stand `except Exception: return u`.
        # Ein Timeout auf dem Original gab damit genau dieses Original zurueck
        # und probierte die naechste Variante NIE — obwohl sie lebt. ffmpeg
        # startete gegen die gestoerte URL, ohne Zaehler und ohne Logzeile.
        plan.clear()
        plan[hd] = "netz"      # Original: Verbindung weg
        plan[nackt] = 200      # die Variante daneben lebt
        vorher = dict(_pf._PREFLIGHT_STATS)
        assert _lauf(hd, "weiter") == nackt, \
            "ein Netzfehler auf dem Original beendet die Variantensuche — " \
            "die lebende Variante wird nie geprueft: %r" % (protokoll,)
        assert protokoll == [hd, nackt], \
            "nach dem Netzfehler wird nicht genau die naechste Variante " \
            "geprueft: %r" % (protokoll,)
        assert _pf._PREFLIGHT_STATS["gestoert"] == vorher["gestoert"], \
            "ein Lauf, der am Ende eine lebende Variante findet, wird als " \
            "Stoerung gezaehlt: %r" % (_pf._PREFLIGHT_STATS,)
        assert "weiter" not in _pf._PREFLIGHT_DEAD_STREAK, \
            "ein erfolgreicher Lauf hinterlaesst eine Tot-Serie"
        ok("W89: ein Netzfehler beendet die Variantensuche nicht")

        # --- 6c) W89: DER ERFOLG SETZT DIE DROSSEL ZURUECK -------------
        # nc.meldetakt laesst nach der ersten Meldung 15 Minuten nichts mehr
        # durch. Ohne Ruecksetzen im Erfolgspfad bleibt damit eine Stoerung,
        # die sich behebt und zehn Minuten spaeter wiederkehrt, bis zu einer
        # Viertelstunde unsichtbar — dieselbe Lehre wie beim Resolver (W81),
        # und dort steht sie ausdruecklich in CLAUDE.md.
        from nc import meldetakt as _mt
        _mt.zuruecksetzen()
        plan.clear()
        plan[wackel] = "netz"
        _lauf(wackel, "drossel")
        assert "preflight" in _mt.ZUSTAND, \
            "der Stoerfall legt keine Drossel an — dann meldet er " \
            "ungedrosselt, und das Log ist nach einer Stunde unlesbar"
        plan.clear()
        plan[gut] = 200
        _lauf(gut, "drossel")
        assert "preflight" not in _mt.ZUSTAND, \
            "der Erfolgspfad setzt die Drossel nicht zurueck — ein Ausfall, " \
            "der sich behebt und wiederkehrt, bleibt dann bis zu 15 Minuten " \
            "unsichtbar: %r" % (_mt.ZUSTAND,)
        ok("W89: der Erfolg setzt die Meldedrossel des Preflights zurueck")

        # Fehlt aiohttp ganz, gilt dasselbe: durchreichen statt blockieren.
        _sys.modules["aiohttp"] = None
        try:
            assert _lauf(wackel, "ohne-aiohttp") == wackel, \
                "ohne aiohttp blockiert der Preflight die Aufnahme, statt " \
                "die URL unveraendert durchzureichen"
        finally:
            _sys.modules["aiohttp"] = _FalscherAiohttp
        ok("W88: Netzfehler und fehlendes aiohttp reichen das Original durch")

        # --- 7) DER PROXY: "" IST KEIN PROXY ---------------------------
        plan.clear()
        plan[gut] = 200
        _pf.configure(record_proxy="")
        _lauf(gut, "p1")
        assert proxys == [None], \
            "ein leerer RECORD_PROXY wird als Proxy durchgereicht: %r — " \
            "aiohttp wirft darauf, der Preflight faellt bei jeder URL in " \
            "den Netzfehler-Zweig und ist damit still abgeschaltet" % (proxys,)
        _pf.configure(record_proxy="http://pl.example:3128")
        _lauf(gut, "p2")
        assert proxys == ["http://pl.example:3128"], \
            "der konfigurierte Pull-Proxy erreicht die Abfrage nicht: %r — " \
            "dann prueft der Preflight von einer anderen Egress-IP als die " \
            "Aufnahme spaeter zieht und misst etwas anderes" % (proxys,)
        _pf.configure(record_proxy="")
        ok("W88: leerer Proxy wird zu None, gesetzter erreicht die Abfrage")

        # --- 8) BEIDE DECKEL BEI 300 -----------------------------------
        # Der Prozess laeuft monatelang ohne Neustart; ein Merker je Quelle
        # ohne Deckel ist ein Speicherleck mit Ansage.
        _pf._PREFLIGHT_CACHE.clear()
        for i in range(300):
            _pf._PREFLIGHT_CACHE["alt%d" % i] = "_hd"
        plan.clear()
        plan[hd] = 404
        plan[nackt] = 200
        _lauf(hd, "neuling")
        assert len(_pf._PREFLIGHT_CACHE) == 300, \
            "der Suffix-Merker waechst ueber 300 hinaus: %d" % len(
                _pf._PREFLIGHT_CACHE)
        assert "alt0" not in _pf._PREFLIGHT_CACHE and \
               _pf._PREFLIGHT_CACHE.get("neuling") == "_hd", \
            "der Deckel wirft den falschen Eintrag weg — es muss der " \
            "aelteste gehen, nicht der eben gelernte"

        _pf._PREFLIGHT_DEAD_STREAK.clear()
        for i in range(300):
            _pf._PREFLIGHT_DEAD_STREAK["alt%d" % i] = 1
        plan.clear()
        _lauf(tot, "neutoter")
        assert len(_pf._PREFLIGHT_DEAD_STREAK) == 300, \
            "die Tot-Serien wachsen ueber 300 hinaus: %d" % len(
                _pf._PREFLIGHT_DEAD_STREAK)
        assert "alt0" not in _pf._PREFLIGHT_DEAD_STREAK and \
               "neutoter" in _pf._PREFLIGHT_DEAD_STREAK, \
            "der Deckel der Tot-Serien wirft den falschen Eintrag weg"
        ok("W88: beide Merker bleiben bei 300 und werfen den aeltesten weg")
    finally:
        if alt_aio is None:
            _sys.modules.pop("aiohttp", None)
        else:
            _sys.modules["aiohttp"] = alt_aio
        _pf.log, _pf.RECORD_PROXY = alt_log, alt_proxy
        _pf._PREFLIGHT_CACHE.clear()
        _pf._PREFLIGHT_CACHE.update(alt_cache)
        _pf._PREFLIGHT_STATS.clear()
        _pf._PREFLIGHT_STATS.update(alt_stats)
        _pf._PREFLIGHT_DEAD_STREAK.clear()
        _pf._PREFLIGHT_DEAD_STREAK.update(alt_streak)


def _test_v42_w88_tiktokcheck_erkennt():
    """v4.2-W88: "gone" ist die Entscheidung, die einen Account loeschbar macht.

    43 Anweisungen, 14 % gedeckt — und an ihrem Ende steht ein Knopf in der
    Oberflaeche. Die Server-IP ist bei TikTok geblockt; wer 403, 429,
    Captcha oder einen Netzfehler als "nicht gefunden" verbucht, bietet dem
    Betreiber an, gesunde Accounts aus dem Bestand zu werfen. Das Modul
    schreibt sich diese Zurueckhaltung selbst als seinen ganzen Zweck vor —
    geprueft hat sie bis hier niemand.

    Der Vertrag nagelt beide Richtungen fest: "gone" NUR bei 404 oder
    TikToks eigenem "Account nicht auffindbar" (statusCode 10221/10202,
    beide Apostrophformen des englischen Textes), alles andere auf
    "unknown". Dazu die Reihenfolge der Pruefungen: die Seite eines
    geloeschten Accounts traegt das Rehydrations-Skript genauso wie eine
    lebende — wer "exists" zuerst prueft, meldet jeden geloeschten Account
    als vorhanden, und der Bestand waechst ewig weiter.

    Ebenfalls hier: der Proxy-Rueckfall. Die Abfrage laeuft ueber denselben
    Pull-Proxy wie die Live-Aufloesung; faellt der weg, misst sie von der
    geblockten Server-IP und liefert dauerhaft "unknown".

    Netz wird nicht angefasst — aiohttp und die drei per configure()
    verdrahteten Helfer sind Attrappen.
    """
    import asyncio as _asyncio
    import sys as _sys

    import nc.tiktokcheck as _tc

    gesehen = []            # (url, proxy) je Abfrage
    zustand = {"status": 200, "body": "", "fehler": None}

    class _Antwort:
        def __init__(self, status, body):
            self.status, self._b = status, body

        async def text(self, errors=None):
            return self._b

        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

    class _Sitzung:
        def get(self, url, proxy=None, **k):
            gesehen.append((url, proxy))
            if zustand["fehler"] is not None:
                raise zustand["fehler"]
            return _Antwort(zustand["status"], zustand["body"])

    async def _sitzung():
        return _Sitzung()

    class _FalscherAiohttp:
        @staticmethod
        def ClientTimeout(**k):
            return None

    proxywahl = {"wert": "http://pl.example:3128", "fehler": None}

    async def _pick_proxy(username=None):
        if proxywahl["fehler"] is not None:
            raise proxywahl["fehler"]
        return proxywahl["wert"]

    def _antwort(name, status=200, body="", fehler=None):
        del gesehen[:]
        zustand.update(status=status, body=body, fehler=fehler)
        return _asyncio.run(_tc.account_exists(name))

    alt_aio = _sys.modules.get("aiohttp")
    alt_conf = dict(_tc._conf)
    alt_rand = _tc.get_random_proxy
    try:
        # --- 0) EIN FEHLENDER STARTWERT IST EIN VERDRAHTUNGSFEHLER -----
        # Ohne den lauten __missing__ kaeme ein nackter KeyError, der im
        # Aufrufer wie ein Datenfehler aussieht und still zu "unknown" wird.
        try:
            _tc._Conf()["get_ai_session"]
            raise AssertionError(
                "ein fehlender Startwert liefert stillschweigend etwas "
                "zurueck, statt laut zu werden")
        except RuntimeError as e:
            assert "configure" in str(e) and "tiktokcheck" in str(e), \
                "die Meldung sagt nicht, WAS zu verdrahten ist: %s" % e

        _sys.modules["aiohttp"] = _FalscherAiohttp
        _tc.configure(get_ai_session=_sitzung, pick_proxy=_pick_proxy,
                      live_resolver_headers={"User-Agent": "x"})
        ok("W88: fehlende Verdrahtung meldet sich laut statt als Datenfehler")

        # --- 1) LEERER NAME KOSTET KEINE ABFRAGE -----------------------
        for leer in ("", "   ", "@", "@   ", None):
            zu, st, grund = _antwort(leer)
            assert (zu, st) == ("unknown", 0), \
                "der leere Name %r ergibt %r/%r statt unknown/0 — ein " \
                "Datenfehler duerfte nie zu einer Loeschempfehlung werden" % (
                    leer, zu, st)
            assert grund == "leerer Name", \
                "der leere Name wird nicht als solcher benannt: %r" % grund
            assert not gesehen, \
                "fuer einen leeren Namen geht eine Abfrage an TikTok: %r" % (
                    gesehen,)

        # --- 2) DAS @ WIRD ABGESTREIFT, NICHT VERDOPPELT ---------------
        _antwort("@nachtfalter", body="nichts")
        assert gesehen[0][0] == "https://www.tiktok.com/@nachtfalter", \
            "die abgefragte Adresse stimmt nicht: %r — ein doppeltes @ " \
            "ergibt eine 404 und damit genau die Loeschempfehlung, die " \
            "dieses Modul verhindern soll" % (gesehen[0][0],)
        ok("W88: leerer Name ohne Abfrage, fuehrendes @ wird abgestreift")

        # --- 3) "gone" NUR BEI EINDEUTIGEM SIGNAL ----------------------
        zu, st, _ = _antwort("weg", status=404)
        assert (zu, st) == ("gone", 404), \
            "HTTP 404 gilt nicht als geloescht: %r/%r" % (zu, st)
        for marke in ('{"statusCode":10221}', '{"statusCode":10202}',
                      "Couldn't find this account",
                      "Couldn’t find this account"):
            zu, st, _ = _antwort("weg", body=marke)
            assert zu == "gone", \
                "TikToks eigenes Signal %r wird nicht als geloescht erkannt " \
                "— dann bleibt ein toter Account ewig im Bestand" % marke
        ok("W88: 404 und TikToks 'nicht auffindbar' ergeben gone")

        # --- 4) BLOCK, LIMIT, CAPTCHA UND NETZFEHLER SIND NIE "gone" ---
        # Das ist der Kern des Moduls: die OVH-IP ist geblockt. Wird einer
        # dieser Faelle zu "gone", bietet die Oberflaeche an, echte
        # Accounts zu loeschen — und der Betreiber tut es.
        for status in (403, 429):
            zu, st, grund = _antwort("lebt", status=status)
            assert (zu, st) == ("unknown", status), \
                "HTTP %s ergibt %r/%r statt unknown — ein Block wird zur " \
                "Loeschempfehlung" % (status, zu, st)
            assert str(status) in grund and "erneut" in grund, \
                "die Begruendung zu HTTP %s nennt weder den Code noch die " \
                "Abhilfe: %r" % (status, grund)
        for seite in ("Please verify to continue", "<div id=captcha-verify>"):
            zu, st, _ = _antwort("lebt", body=seite)
            assert zu == "unknown", \
                "eine Captcha-Seite (%r) wird als %r gewertet" % (seite, zu)
        zu, st, _ = _antwort("lebt", body="<html>irgendwas</html>")
        assert zu == "unknown", \
            "eine Seite ohne jedes Signal wird als %r gewertet statt als " \
            "unknown — Raten ist hier teurer als Nichtwissen" % zu

        zu, st, grund = _antwort("lebt", fehler=RuntimeError("x" * 300))
        assert (zu, st) == ("unknown", 0), \
            "ein Netzfehler ergibt %r/%r statt unknown/0" % (zu, st)
        assert len(grund) <= len("Abfrage fehlgeschlagen: ") + 80, \
            "der Fehlertext wird nicht gekappt (%d Zeichen) — eine " \
            "Ausnahme mit halber HTML-Seite sprengt die Oberflaeche" % len(grund)
        ok("W88: Block, Limit, Captcha, Rauschen und Netzfehler bleiben unknown")

        # --- 5) "exists" UND DIE REIHENFOLGE DER PRUEFUNGEN ------------
        for marke in ('"uniqueId":"nachtfalter"',
                      "__UNIVERSAL_DATA_FOR_REHYDRATION__",
                      '"userInfo"'):
            zu, st, _ = _antwort("NachtFalter", body=marke)
            assert zu == "exists", \
                "das Vorhanden-Signal %r wird nicht erkannt (%r) — dann " \
                "meldet die Oberflaeche jeden lebenden Account als " \
                "unklar" % (marke, zu)
        zu, _, _ = _antwort("nachtfalter", body='"uniqueId":"jemandanders"')
        assert zu == "unknown", \
            "ein fremder Handle in der Antwort gilt als Beleg fuer DIESEN " \
            "Account — eine Weiterleitung wuerde so zum Beweis"

        # Die Seite eines geloeschten Accounts traegt den Rehydrations-Marker
        # genauso. Wer zuerst auf "exists" prueft, sieht nie mehr ein "gone".
        zu, _, _ = _antwort("weg", body=(
            '<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__">'
            '{"statusCode":10221,"userInfo":{}}</script>'))
        assert zu == "gone", \
            "auf einer Seite mit BEIDEN Signalen gewinnt 'exists' — dann " \
            "bleibt jeder geloeschte Account dauerhaft im Bestand stehen"
        ok("W88: exists erkannt, aber gone wird zuerst geprueft")

        # --- 6) DER PROXY-RUECKFALL ------------------------------------
        # Ohne Proxy misst die Abfrage von der geblockten Server-IP und
        # liefert dauerhaft "unknown" — der Check waere wertlos.
        proxywahl.update(wert="http://pl.example:3128", fehler=None)
        _antwort("lebt", body="nichts")
        assert gesehen[0][1] == "http://pl.example:3128", \
            "die Just-in-Time-Proxy-Wahl erreicht die Abfrage nicht: %r" % (
                gesehen[0][1],)

        proxywahl.update(fehler=RuntimeError("Pool leer"))
        _tc.get_random_proxy = lambda: "http://zufall.example:8080"
        _antwort("lebt", body="nichts")
        assert gesehen[0][1] == "http://zufall.example:8080", \
            "faellt die Proxy-Wahl aus, greift der Zufallsproxy nicht — " \
            "die Abfrage laeuft dann von der geblockten Server-IP: %r" % (
                gesehen[0][1],)

        proxywahl.update(wert=None, fehler=None)
        _tc.get_random_proxy = lambda: None
        zu, _, _ = _antwort("lebt", body='"userInfo"')
        assert gesehen[0][1] is None and zu == "exists", \
            "ohne jeden Proxy wird die Abfrage abgebrochen statt direkt " \
            "versucht — ein fehlender Proxy ist kein Grund, gar nicht " \
            "nachzusehen"

        def _wirft():
            raise RuntimeError("Proxyliste kaputt")

        _tc.get_random_proxy = _wirft
        zu, _, _ = _antwort("lebt", body='"userInfo"')
        assert zu == "exists", \
            "ein kaputter Zufallsproxy reisst die ganze Pruefung mit: %r" % zu
        ok("W88: Proxy-Wahl, Zufalls-Rueckfall und der Weg ganz ohne Proxy")
    finally:
        if alt_aio is None:
            _sys.modules.pop("aiohttp", None)
        else:
            _sys.modules["aiohttp"] = alt_aio
        _tc.get_random_proxy = alt_rand
        _tc._conf.clear()
        _tc._conf.update(alt_conf)


def _test_v42_w88_archivregeln():
    """v4.2-W88: die Auto-Archiv-Regeln waren zu 16 % geprueft — und sie sind
    der eine Pfad im Bestand, der aus einer Datenbankzeile heraus eine Datei
    an einen aus Fremddaten gebauten Ort schreibt.

    Drei Fehlerbilder, die hier real drohen und die kein anderer Vertrag
    gefangen haette:

    **Das Ziel liegt ausserhalb des Archivs.** Der Zielname entsteht aus
    `recordings.filepath` — einem Wert, den der Recorder aus einem
    TikTok-Nutzernamen baut. Faellt `_safe_archive_filename` weg oder wird es
    durch ein blosses `os.path.basename` ersetzt, ueberlebt ein
    Windows-Pfad ("..\\..\\etc\\passwd.mp4") die Pruefung: auf Linux ist "\\"
    ein ganz normales Zeichen, `basename` nimmt nichts davon weg. Geprueft
    wird deshalb nicht der Sanitizer (der gehoert nc.textmore), sondern die
    WIRKUNG: nach dem Lauf liegen genau die erwarteten Dateien im Archiv,
    jede per `nc.sicherpfad.unter` wirklich darin, und kein Name traegt noch
    einen Trenner.

    **Die Kopie ueberschreibt eine aeltere Fassung.** `shutil.copy2` fragt
    nicht; ohne die `os.path.exists`-Pruefung schreibt der zweite Lauf jede
    Archivdatei mit der aktuellen Quelle zu. Der Betreiber merkt das nie —
    die Datei ist ja da. Deshalb wird die Quelle zwischen den Laeufen
    absichtlich veraendert und danach die Groesse im Archiv nachgemessen.

    **Ein Lauf ohne Bot bringt den Wartungspfad um.** `log_event` ist
    optional; ein `log_event(...)` ohne Wache wuerde erst im Betrieb
    auffallen, wo die Regeln auch vom Kommandozeilen-Werkzeug laufen.

    Dazu die Entscheidungen, die ueber Geld und Platte bestimmen: die
    `min_size_mb`-Grenze ist ein >=, eine abgeschaltete Regel fasst gar
    nichts an, eine unbekannte Aktion zaehlt Treffer, kopiert aber nicht, und
    eine Regel mit kaputtem JSON darf die uebrigen nicht mitnehmen.

    Der Vertrag faehrt gegen eine EIGENE SQLite-Datei mit dem echten Schema
    aus nc.schema (inklusive der nachmigrierten Spalten file_size,
    duration_secs, deleted_at). Die Datenbank der Suite traegt davon nichts:
    ihr TABLES-Auszug kennt `auto_archive_rules` gar nicht und `recordings`
    nur in der nackten CREATE-TABLE-Form. Gegen die waere jede Abfrage dieses
    Moduls in den `except`-Zweig gelaufen — der Vertrag waere gruen geworden,
    ohne eine einzige Regel angewendet zu haben.
    """
    import shutil as _sh
    import sqlite3 as _sq
    from datetime import datetime as _datetime, timezone as _timezone

    from nc import archiverules as A
    from nc import dbwrap as _dbw
    from nc import schema as _schema
    from nc import sicherpfad as _sp

    # Feste Uhr: `last_run` und `created_at` sind sonst nicht pruefbar, und
    # ein Vertrag, der nur "irgendein Zeitstempel" sagt, faengt auch einen
    # leeren String.
    _FEST = _datetime(2026, 9, 17, 4, 5, 6, tzinfo=_timezone.utc)
    _FEST_ISO = _FEST.isoformat()

    class _Uhr:
        @staticmethod
        def now(tz=None):
            return _FEST

    heim = _ph.verzeichnis()
    dbpfad = os.path.join(heim, "w88_regeln.sqlite")
    con = _sq.connect(dbpfad)
    con.row_factory = _sq.Row
    _schema.create_schema(
        con, pk="INTEGER PRIMARY KEY AUTOINCREMENT", txt_idx="TEXT",
        txt_long="TEXT", txt_big="TEXT", iv="INTEGER", tbl_opts="", is_my=False,
        _create_index_safe=lambda c, a, b=None: c.execute(a),
        _migrate_columns=lambda c, t, e: [
            c.execute("ALTER TABLE %s ADD COLUMN %s %s" % (t, k, v))
            for k, v in e.items()
            if k not in {r[1] for r in c.execute("PRAGMA table_info(%s)" % t)}],
        log=type("L", (), {"info": lambda *a: 0, "warning": lambda *a: 0,
                           "debug": lambda *a: 0})())
    con.commit()
    con.close()

    alt_pfad, alt_backend, alt_uhr = _dbw.DB_PATH, _dbw.DB_BACKEND, A.datetime
    try:
        configure_db(db_path=dbpfad, backend="sqlite")
        A.datetime = _Uhr

        # ── 1) Ohne Archivverzeichnis wird NICHTS angefasst ──────────────
        erg = A.run_archive_rules(archive_dir="")
        assert erg["ok"] is False and "ARCHIVE_DIR" in erg.get("error", ""), \
            "ohne Archivverzeichnis muss der Lauf abbrechen und die " \
            ".env-Variable beim Namen nennen — der Betreiber sucht " \
            "ARCHIVE_DIR, nicht den Python-Parameter: %r" % (erg,)
        ok("W88: Regel-Lauf ohne ARCHIVE_DIR bricht ab und nennt die .env-Variable")

        # ── 2) Anlegen, auflisten, loeschen ──────────────────────────────
        regel = A.add_archive_rule("Grosse Aufnahmen", {"min_size_mb": 1},
                                   {"action": "copy_to_archive"})
        assert isinstance(regel, int) and regel > 0, \
            "add_archive_rule liefert keine Id — die Route kann die neue " \
            "Regel danach nicht anzeigen: %r" % (regel,)
        zeilen = A.list_archive_rules()
        assert [z["id"] for z in zeilen] == [regel], \
            "die frisch angelegte Regel steht nicht in der Liste: %r" \
            % ([dict(z) for z in zeilen],)
        assert zeilen[0]["enabled"] == 1, \
            "eine neue Regel kommt abgeschaltet auf die Welt — sie laeuft " \
            "dann nie, und niemand sucht den Schalter"
        assert zeilen[0]["created_at"] == _FEST_ISO, \
            "created_at traegt nicht den Zeitpunkt des Anlegens: %r" \
            % (zeilen[0]["created_at"],)

        # Die Laengengrenzen sind kein Schoenheitsmittel: ein 3000 Zeichen
        # langes condition_json schneidet mitten im JSON ab. Genau so muss
        # der Lauf spaeter darueber hinweggehen, statt zu sterben.
        kaputt = A.add_archive_rule("N" * 500,
                                    {"username_contains": "x" * 3000},
                                    {"action": "copy_to_archive"})
        gross_zeile = [z for z in A.list_archive_rules() if z["id"] == kaputt][0]
        assert len(gross_zeile["name"]) == 200, \
            "name wird nicht auf 200 Zeichen beschnitten (%d) — auf MariaDB " \
            "wirft das beim INSERT" % len(gross_zeile["name"])
        assert len(gross_zeile["condition_json"]) == 2000, \
            "condition_json wird nicht auf 2000 Zeichen beschnitten (%d)" \
            % len(gross_zeile["condition_json"])
        assert [z["id"] for z in A.list_archive_rules()] == [kaputt, regel], \
            "die Liste kommt nicht neueste-zuerst — das Dashboard zeigt " \
            "dann die aelteste Regel oben"
        ok("W88: Regeln anlegen/auflisten inkl. Laengengrenzen und Reihenfolge")

        # ── 3) Der eigentliche Lauf: Grenze, Kopie, Pfad-Riegel ──────────
        quelle = os.path.join(heim, "aufnahmen")
        archiv = os.path.join(heim, "archiv")
        os.makedirs(quelle)
        os.makedirs(archiv)

        def _datei(name, bytes_):
            # add_archive_entry() bucht os.path.getsize(); die Groesse muss
            # stimmen, die Bloecke nicht.
            return _ph.attrappe(os.path.join(quelle, name), bytes_)

        MIB = 1024 * 1024
        d_gross = _datei("gross.mp4", 2 * MIB)
        d_genau = _datei("genau.mp4", 1 * MIB)      # exakt an der Grenze
        d_klein = _datei("klein.mp4", MIB // 2)
        d_boese = _datei("..\\..\\etc\\passwd.mp4", 2 * MIB)
        d_weg = os.path.join(quelle, "nie-dagewesen.mp4")   # existiert nicht

        with db_conn() as c:
            for user, pfad, groesse, weg_am in (
                    ("gross", d_gross, 2 * MIB, None),
                    ("genau", d_genau, 1 * MIB, None),
                    ("klein", d_klein, MIB // 2, None),
                    ("boese", d_boese, 2 * MIB, None),
                    ("fehlt", d_weg, 2 * MIB, None),
                    # Weich geloescht: wuerde jede Bedingung erfuellen und
                    # darf trotzdem nie wieder auftauchen.
                    ("papierkorb", d_gross, 9 * MIB, "2026-09-16T13:00:00+00:00"),
            ):
                c.execute(
                    "INSERT INTO recordings (username, filepath, file_size, "
                    "duration_secs, created_at, deleted_at) VALUES (?,?,?,?,?,?)",
                    (user, pfad, groesse, 900, "2026-09-16T12:00:00+00:00", weg_am))

        ereignisse = []
        erg = A.run_archive_rules(rule_id=regel, archive_dir=archiv,
                                  log_event=lambda *a: ereignisse.append(a))
        assert erg["ok"] and erg["processed"] == 1, erg
        treffer = erg["results"][0]
        assert treffer["matched"] == 4, \
            "min_size_mb=1 trifft %d statt 4 Aufnahmen — die Grenze ist ein " \
            ">=, die halbe MiB faellt raus, und der Papierkorb-Eintrag ist " \
            "unsichtbar: %r" % (treffer["matched"], treffer)
        assert treffer["archived"] == 3 and treffer["skipped"] == 1, \
            "eine Aufnahme ohne Datei muss uebersprungen werden, nicht den " \
            "Lauf abbrechen: %r" % (treffer,)
        assert treffer["rule_id"] == regel and treffer["rule_name"] == "Grosse Aufnahmen"

        liegt = sorted(os.listdir(archiv))
        # v4.2-W89: "passwd.mp4", nicht mehr "etc_passwd.mp4". Der Riegel ist
        # von `_safe_archive_filename` auf `nc.sicherpfad.sicher_join`
        # gewechselt, und die beiden entschaerfen "..\\..\\etc\\passwd.mp4"
        # unterschiedlich: der alte ersetzte jeden Backslash durch einen
        # Unterstrich und backte den Pfad damit IN den Dateinamen ein, der
        # neue macht "\\" erst zu "/" und nimmt den Pfadanteil dann per
        # basename wirklich heraus. Beide Ergebnisse sind sicher — sie liegen
        # im Archiv —, aber nur das neue ist eine Antwort auf die Frage: ein
        # Dateiname ist ein Name, keine Kodierung eines Pfades. Fuer den
        # Normalfall (der Recorder liefert flache Namen) aendert sich nichts.
        assert liegt == ["genau.mp4", "gross.mp4", "passwd.mp4"], \
            "im Archiv liegt etwas anderes als erwartet: %r — entweder hat " \
            "die Groessengrenze nicht gegriffen oder der Dateiname wurde " \
            "nicht entschaerft" % (liegt,)
        for name in liegt:
            ziel = os.path.join(archiv, name)
            assert _sp.unter(archiv, ziel), \
                "%r liegt nicht unter dem Archivverzeichnis" % (ziel,)
            assert "/" not in name and "\\" not in name and ".." not in name, \
                "der Zielname traegt noch einen Pfadanteil: %r — ohne " \
                "sicher_join schreibt der naechste Recorder-Name dorthin, " \
                "wohin er zeigt" % (name,)
            assert _sp.sicherer_name(name) == name, \
                "der Zielname ueberlebt den Riegel aus nc.sicherpfad nicht: " \
                "%r wird zu %r" % (name, _sp.sicherer_name(name))
        assert os.path.getsize(os.path.join(archiv, "passwd.mp4")) == 2 * MIB
        for p in (d_gross, d_genau, d_klein, d_boese):
            assert os.path.isfile(p), \
                "die Quelle %r ist weg — der Regel-Lauf KOPIERT, er " \
                "verschiebt nicht" % (p,)

        with db_conn() as c:
            eintraege = c.execute(
                "SELECT filename, filepath, size_bytes, source_url, notes "
                "FROM archive ORDER BY filename").fetchall()
        assert len(eintraege) == 3, \
            "zu %d Dateien im Archiv gehoeren %d Datenbankzeilen — eine " \
            "Datei ohne Eintrag taucht im Dashboard nie auf" \
            % (len(liegt), len(eintraege))
        for e in eintraege:
            assert e["size_bytes"] == os.path.getsize(e["filepath"]), \
                "size_bytes passt nicht zur Datei: %r" % (dict(e),)
            assert e["source_url"].startswith("recording/"), \
                "ohne Rueckverweis auf die Aufnahme ist der Archiveintrag " \
                "nicht mehr zuzuordnen: %r" % (dict(e),)
            assert "Grosse Aufnahmen" in (e["notes"] or ""), \
                "die Notiz nennt die Regel nicht, die kopiert hat: %r" \
                % (dict(e),)
        ok("W88: Regel-Lauf kopiert nur ueber der Grenze, entschaerft den "
           "Dateinamen und bleibt im Archivverzeichnis")

        # ── 4) Zweiter Lauf: nichts wird ueberschrieben ──────────────────
        with open(d_gross, "wb") as f:
            f.write(b"1" * (3 * MIB))       # Quelle waechst; Ziel darf nicht
        erg2 = A.run_archive_rules(rule_id=regel, archive_dir=archiv)
        t2 = erg2["results"][0]
        assert erg2["ok"], "ein Lauf OHNE log_event muss durchlaufen: %r" % (erg2,)
        assert t2["matched"] == 4 and t2["archived"] == 0 and t2["skipped"] == 4, \
            "der zweite Lauf kopiert erneut: %r" % (t2,)
        assert os.path.getsize(os.path.join(archiv, "gross.mp4")) == 2 * MIB, \
            "die Archivfassung wurde ueberschrieben — shutil.copy2 fragt " \
            "nicht, die exists-Pruefung davor ist der einzige Schutz"
        with db_conn() as c:
            n = c.execute("SELECT COUNT(*) AS n FROM archive").fetchone()["n"]
        assert n == 3, "der zweite Lauf hat Archiveintraege verdoppelt (%d)" % n
        ok("W88: zweiter Lauf ueberschreibt weder Datei noch Eintrag, auch "
           "ohne log_event")

        # ── 5) Buchfuehrung und Meldung ──────────────────────────────────
        z = [r for r in A.list_archive_rules() if r["id"] == regel][0]
        assert z["last_run"] == _FEST_ISO, \
            "last_run wird nicht fortgeschrieben (%r) — das Dashboard zeigt " \
            "dann ewig 'nie gelaufen'" % (z["last_run"],)
        assert z["last_match_count"] == 4, \
            "last_match_count steht auf %r statt 4" % (z["last_match_count"],)
        assert len(ereignisse) == 1, \
            "der Lauf meldet %d Ereignisse statt einem" % len(ereignisse)
        thema, stufe, text, daten = ereignisse[0]
        assert thema == "archive.rule.run" and stufe == "info", \
            "Thema/Stufe des Ereignisses geaendert: %r/%r" % (thema, stufe)
        assert daten["matched"] == 4 and daten["archived"] == 3 \
            and daten["rule_id"] == regel, \
            "die Zahlen im Ereignis passen nicht zum Ergebnis: %r" % (daten,)
        assert "Grosse Aufnahmen" in text
        ok("W88: last_run/last_match_count fortgeschrieben, Ereignis traegt "
           "die Zahlen")

        # ── 5b) Fehlschlag mitten in der Kopie ───────────────────────────
        # Ein Archiveintrag ohne Datei ist ein realer Bestand (Datei von Hand
        # geloescht, Zeile geblieben). filepath ist UNIQUE — der INSERT nach
        # der Kopie wirft dann. Der Lauf muss das zaehlen und mit der
        # naechsten Aufnahme weitermachen, statt die uebrigen Regeln
        # mitzunehmen.
        d_konflikt = _datei("konflikt.mp4", 2 * MIB)
        with db_conn() as c:
            c.execute("INSERT INTO recordings (username, filepath, file_size, "
                      "duration_secs, created_at, deleted_at) "
                      "VALUES (?,?,?,?,?,NULL)",
                      ("konflikt", d_konflikt, 2 * MIB, 900,
                       "2026-09-16T12:00:00+00:00"))
            c.execute("INSERT INTO archive (filename, filepath, size_bytes, "
                      "created_at) VALUES (?,?,?,?)",
                      ("konflikt.mp4", os.path.join(archiv, "konflikt.mp4"),
                       1, _FEST_ISO))
        erg5 = A.run_archive_rules(rule_id=regel, archive_dir=archiv)
        t5 = erg5["results"][0]
        assert erg5["ok"] and t5["matched"] == 5, \
            "der Lauf ist an einem gescheiterten Archiveintrag gestorben: " \
            "%r" % (erg5,)
        assert t5["archived"] == 0 and t5["skipped"] == 5, \
            "ein gescheiterter Archiveintrag muss als uebersprungen zaehlen, " \
            "nicht als erledigt: %r" % (t5,)
        ok("W88: ein gescheiterter Archiveintrag zaehlt als uebersprungen "
           "und stoppt den Lauf nicht")

        # ── 6) Abgeschaltet, unbekannte Aktion, kaputtes JSON ────────────
        with db_conn() as c:
            c.execute("UPDATE auto_archive_rules SET enabled=0, last_run=? "
                      "WHERE id=?", ("nie", regel))
        nur_zaehlen = A.add_archive_rule("Nur zaehlen", {"min_size_mb": 0},
                                         {"action": "loeschen"})
        vorher = sorted(os.listdir(archiv))
        erg3 = A.run_archive_rules(archive_dir=archiv)
        ids = [r["rule_id"] for r in erg3["results"]]
        assert regel not in ids, \
            "eine abgeschaltete Regel ist gelaufen — der Schalter im " \
            "Dashboard waere wirkungslos: %r" % (erg3,)
        assert kaputt not in ids, \
            "eine Regel mit abgeschnittenem JSON wurde angewendet statt " \
            "uebersprungen: %r" % (erg3,)
        assert ids == [nur_zaehlen], \
            "eine kaputte Regel hat die uebrigen mitgenommen: %r" % (erg3,)
        with db_conn() as c:
            z = c.execute("SELECT last_run FROM auto_archive_rules WHERE id=?",
                          (regel,)).fetchone()
        assert z["last_run"] == "nie", \
            "die abgeschaltete Regel hat trotzdem last_run geschrieben"
        t3 = erg3["results"][0]
        assert t3["matched"] == 6 and t3["archived"] == 0 and t3["skipped"] == 0, \
            "eine unbekannte Aktion muss zaehlen und sonst nichts tun: %r" \
            % (t3,)
        assert sorted(os.listdir(archiv)) == vorher, \
            "eine unbekannte Aktion hat Dateien angefasst"
        ok("W88: abgeschaltete Regel, kaputtes JSON und unbekannte Aktion "
           "fassen keine Datei an")

        # ── 7) Loeschen und leere Auswahl ────────────────────────────────
        assert A.delete_archive_rule(kaputt) is True
        assert A.delete_archive_rule(kaputt) is False, \
            "das zweite Loeschen meldet Erfolg — die Route antwortet dann " \
            "200 auf eine Regel, die es nie gab"
        assert A.delete_archive_rule(nur_zaehlen) is True
        leer = A.run_archive_rules(rule_id=999999, archive_dir=archiv)
        assert leer == {"ok": True, "processed": 0, "results": []}, \
            "eine nicht vorhandene Regel-Id muss leer und erfolgreich " \
            "zurueckkommen, nicht alle Regeln fahren: %r" % (leer,)
        ok("W88: Loeschen meldet Treffer, unbekannte Regel-Id laeuft leer")

        # ── 7b) W89: die Buchfuehrung der Regel scheitert ───────────────
        # `last_run` ist die einzige Spur, dass eine Regel ueberhaupt laeuft.
        # Bis W89 stand dort `except Exception: pass` — bleibt die Spalte
        # stehen, sieht das Deck eine Regel, die nie gelaufen ist, obwohl sie
        # gerade Dateien kopiert hat. Diese Verwechslung laesst sich ohne
        # Logzeile nicht aufloesen, und der Lauf selbst soll trotzdem sein
        # Ergebnis melden: die Dateien SIND ja kopiert.
        _echt = A.db_conn
        _zaehler = {"n": 0}

        def _db_bricht_beim_schreiben():
            # Zwei Aufrufe gehen durch (Regeln lesen, Aufnahmen lesen), der
            # dritte — die Buchfuehrung — faellt. `add_archive_entry` liegt in
            # nc.archive und holt sich sein db_conn dort, zaehlt hier also
            # nicht mit. Ueber einen Zaehler und nicht ueber den SQL-Text,
            # damit der Vertrag nicht an der Formulierung der Abfrage haengt.
            _zaehler["n"] += 1
            if _zaehler["n"] > 2:
                raise RuntimeError("Attrappe: Datenbank beim Schreiben weg")
            return _echt()

        # Die Regel wurde in Abschnitt 6 abgeschaltet — ohne `enabled=1`
        # kommt der Lauf gar nicht bis zur Buchfuehrung, und der Abschnitt
        # wuerde gruen, ohne etwas geprueft zu haben. Genau das ist beim
        # ersten Entwurf passiert; die Zaehler-Zusicherung unten faengt es.
        #
        # Der Marker in last_run wird beim Schreiben ueberschrieben. Ohne ihn
        # liesse sich "nicht geschrieben" nicht von "denselben Wert wieder
        # geschrieben" unterscheiden.
        with db_conn() as c:
            c.execute("UPDATE auto_archive_rules SET enabled=1, last_run=? "
                      "WHERE id=?", ("MARKER-W89", regel))
            c.commit()
        del ereignisse[:]
        A.db_conn = _db_bricht_beim_schreiben
        try:
            erg7 = A.run_archive_rules(archive_dir=archiv,
                                       log_event=lambda *a: None)
        finally:
            A.db_conn = _echt
        assert erg7["ok"] is True, \
            "eine gescheiterte Buchfuehrung reisst den ganzen Regel-Lauf " \
            "mit — die Dateien sind aber kopiert: %r" % (erg7,)
        assert _zaehler["n"] > 2, \
            "die Attrappe wurde nie bis zur Buchfuehrung gefragt (%r " \
            "Aufrufe) — dann prueft dieser Abschnitt nichts" % (_zaehler,)
        with db_conn() as c:
            stand = c.execute(
                "SELECT last_run FROM auto_archive_rules WHERE id=?",
                (regel,)).fetchone()
        assert stand["last_run"] == "MARKER-W89", \
            "last_run wurde fortgeschrieben, obwohl das Schreiben fiel: %r" % (
                dict(stand),)
        ok("W89: eine gescheiterte Regel-Buchfuehrung meldet sich und "
           "bricht den Lauf nicht ab")

        # ── 8) Die Datenbank ist weg ─────────────────────────────────────
        # Erst der Fall "Regeln da, recordings-Abfrage kaputt": er ist der
        # einzige, der ok=False mit Grund liefert.
        with db_conn() as c:
            c.execute("DROP TABLE recordings")
        erg4 = A.run_archive_rules(rule_id=regel, archive_dir=archiv)
        assert erg4["ok"] is False and erg4.get("error"), \
            "eine kaputte recordings-Abfrage meldet Erfolg — der " \
            "Wartungspfad haelt den Lauf dann fuer erledigt: %r" % (erg4,)

        configure_db(db_path=os.path.join(heim, "gibt-es-nicht", "x.db"),
                     backend="sqlite")
        assert A.list_archive_rules() == [], \
            "ohne Datenbank muss die Liste leer sein statt zu werfen"
        assert A.add_archive_rule("x", {}, {}) is None, \
            "add_archive_rule muss None liefern statt die Route mit 500 zu " \
            "beantworten"
        assert A.delete_archive_rule(1) is False
        ok("W88: ohne Datenbank liefern alle vier Funktionen einen Wert "
           "statt zu werfen")
    finally:
        A.datetime = alt_uhr
        configure_db(db_path=alt_pfad, backend=alt_backend)
        _sh.rmtree(heim, ignore_errors=True)


def _test_v42_w88_speicher():
    """v4.2-W88: nc.storage war zu 16 % geprueft — und `cleanup()` ist die
    Funktion des Bestands, die ohne Rueckfrage Dateien von der Platte nimmt.

    Vier Fehlerbilder, die hier real drohen:

    **Ein Symlink wird durchlaufen.** Im Aufnahmeverzeichnis liegen Verweise
    (der Betreiber legt Platten dazu). `entry.is_file(follow_symlinks=False)`
    ist der einzige Grund, warum `cleanup` sie nicht anfasst. Faellt das
    `follow_symlinks=False` weg, loescht ein Aufraeumlauf Verweise auf Daten,
    die gar nicht im Aufnahmeverzeichnis liegen — und die Ratschen der
    Pruefkette sehen davon nichts. Der Vertrag legt deshalb einen Verweis auf
    eine Datei AUSSERHALB an und misst hinterher beide nach.

    **Die Altersgrenze kippt um einen Tag.** `st_mtime >= cutoff` heisst
    behalten. Wird daraus ein `>`, faellt die Datei genau auf der Grenze
    weg — bei RECORDINGS_RETAIN_DAYS=7 ist das die Aufnahme von heute vor
    einer Woche, und niemand rechnet nach. Geprueft wird gegen eine
    Attrappe von `time`, nicht gegen die echte Uhr: mit der echten waere die
    Grenze nicht anfassbar.

    **`dry_run` loescht doch.** Der Dashboard-Knopf zeigt damit erst an, was
    weg waere. Ein `dry_run`, der schreibt, ist der teuerste denkbare Fehler
    in dieser Datei.

    **Der Eintrag verschwindet mit der Datei.** `cleanup` loescht bewusst
    NUR die Datei; der Betreiber soll weiter sehen, dass es die Aufnahme gab
    (die andere Richtung macht nc.retention). Ein hier ergaenztes DELETE
    nimmt ihm die Historie, ohne dass etwas faellt — also wird die Zeilenzahl
    vorher und nachher gemessen.

    Dazu die Rechenwege, auf denen andere Anzeigen aufsitzen: `used_percent`
    (ohne das Feld blieb der Disk-Anteil im Health-Score dauerhaft bei 70/100
    mit Note "?"), und die Hochrechnung in `forecast` — Sieben-Tage-Fenster,
    Papierkorb-Filter und die Division, die ohne den `avg_bytes > 0`-Riegel
    ein ZeroDivisionError waere.

    Eigene SQLite-Datei mit dem echten Schema aus nc.schema: `recordings`
    braucht file_size und deleted_at, und beide sind in der Datenbank der
    Suite nicht angelegt (sie zieht nur die nackten CREATE-TABLE-Bloecke).
    Gegen die waere `forecast` immer in den `except`-Zweig gelaufen.
    """
    import logging as _logging
    import shutil as _sh
    import sqlite3 as _sq
    from datetime import datetime as _datetime, timezone as _timezone

    from nc import dbwrap as _dbw
    from nc import schema as _schema
    from nc import storage as S

    GIB = 1024 ** 3
    _FEST = _datetime(2026, 9, 17, 6, 0, 0, tzinfo=_timezone.utc)
    JETZT = 1800000000.0        # feste Epoch-Sekunde fuer die mtime-Grenze

    class _Uhr:
        @staticmethod
        def time():
            return JETZT

    class _Kalender:
        @staticmethod
        def now(tz=None):
            return _FEST

    class _Platte:
        """disk_usage-Attrappe. Echte Zahlen sind hier wertlos: sie machen
           jede Hochrechnung unpruefbar."""
        werte = (100 * GIB, 90 * GIB, 10 * GIB)
        fehler = None

        @classmethod
        def disk_usage(cls, pfad):
            if cls.fehler:
                raise cls.fehler
            return type("N", (), {"total": cls.werte[0], "used": cls.werte[1],
                                  "free": cls.werte[2]})()

    heim = _ph.verzeichnis()
    dbpfad = os.path.join(heim, "w88_speicher.sqlite")
    con = _sq.connect(dbpfad)
    con.row_factory = _sq.Row
    _schema.create_schema(
        con, pk="INTEGER PRIMARY KEY AUTOINCREMENT", txt_idx="TEXT",
        txt_long="TEXT", txt_big="TEXT", iv="INTEGER", tbl_opts="", is_my=False,
        _create_index_safe=lambda c, a, b=None: c.execute(a),
        _migrate_columns=lambda c, t, e: [
            c.execute("ALTER TABLE %s ADD COLUMN %s %s" % (t, k, v))
            for k, v in e.items()
            if k not in {r[1] for r in c.execute("PRAGMA table_info(%s)" % t)}],
        log=type("L", (), {"info": lambda *a: 0, "warning": lambda *a: 0,
                           "debug": lambda *a: 0})())
    con.commit()
    con.close()

    alt_pfad, alt_backend = _dbw.DB_PATH, _dbw.DB_BACKEND
    alt_time, alt_shutil, alt_datetime = S.time, S.shutil, S.datetime
    alt_os = S.os
    try:
        configure_db(db_path=dbpfad, backend="sqlite")

        aufnahmen = os.path.join(heim, "aufnahmen")
        aussen = os.path.join(heim, "fremde-platte")
        fehlt = os.path.join(heim, "gibt-es-nicht")
        os.makedirs(aufnahmen)
        os.makedirs(aussen)

        # ── 1) Die beiden Ausstiege vor dem ersten Dateizugriff ──────────
        for tage in (0, -1):
            e = S.cleanup(aufnahmen, days=tage)
            assert e["deleted"] == 0 and e["freed_bytes"] == 0, \
                "days=%d loescht trotzdem: %r" % (tage, e)
            assert "RECORDINGS_RETAIN_DAYS" in e.get("reason", ""), \
                "der abgeschaltete Aufraeumlauf nennt die .env-Variable " \
                "nicht — der Betreiber sucht sonst im Code: %r" % (e,)
        e = S.cleanup(fehlt, days=7)
        assert e["deleted"] == 0 and fehlt in e.get("reason", ""), \
            "ein fehlendes Aufnahmeverzeichnis muss mit Pfad im Grund " \
            "zurueckkommen: %r" % (e,)
        assert not os.path.exists(fehlt), \
            "cleanup hat das fehlende Verzeichnis angelegt"
        ok("W88: cleanup ohne Aufbewahrungsfrist und ohne Verzeichnis fasst "
           "nichts an und nennt den Grund")

        # ── 2) Die Altersgrenze, Symlinks und Unterordner ───────────────
        S.time = _Uhr
        TAGE = 2
        grenze = JETZT - TAGE * 86400

        def _datei(pfad, bytes_, mtime):
            # cleanup_recordings() summiert st_size — siehe _ph.attrappe.
            _ph.attrappe(pfad, bytes_)
            os.utime(pfad, (mtime, mtime))
            return pfad

        d_alt = _datei(os.path.join(aufnahmen, "alt.mp4"), 1000, grenze - 1)
        d_genau = _datei(os.path.join(aufnahmen, "genau.mp4"), 2000, grenze)
        d_neu = _datei(os.path.join(aufnahmen, "neu.mp4"), 3000, JETZT)
        d_aussen = _datei(os.path.join(aussen, "wertvoll.mp4"), 4000, grenze - 99)
        d_verweis = os.path.join(aufnahmen, "verweis.mp4")
        os.symlink(d_aussen, d_verweis)
        os.utime(d_verweis, (grenze - 99, grenze - 99), follow_symlinks=False)
        os.makedirs(os.path.join(aufnahmen, "unterordner"))
        _datei(os.path.join(aufnahmen, "unterordner", "tief.mp4"), 5000,
               grenze - 99)

        with db_conn() as c:
            c.execute("INSERT INTO recordings (username, filepath, file_size, "
                      "created_at) VALUES (?,?,?,?)",
                      ("alt", d_alt, 1000, "2026-09-10T00:00:00+00:00"))
            zeilen_vorher = c.execute(
                "SELECT COUNT(*) AS n FROM recordings").fetchone()["n"]

        e = S.cleanup(aufnahmen, days=TAGE, dry_run=True)
        # v4.2-W89: der Probelauf zaehlt in `would_delete`/`would_free_bytes`,
        # und `deleted`/`freed_bytes` bleiben 0. Vorher lief er in `deleted`
        # mit — ein Aufrufer, der nur dieses Feld liest (und das tut jeder,
        # der nicht an `dry_run` denkt), konnte einen Probelauf nicht von
        # einem Loeschlauf unterscheiden. Ein Feld, das man zusaetzlich lesen
        # MUSS, um das Hauptfeld richtig zu deuten, wird irgendwann nicht
        # gelesen.
        assert e["would_delete"] == 1 and e["would_free_bytes"] == 1000, \
            "die Probe zaehlt %r — genau an der Grenze wird BEHALTEN, " \
            "Symlink und Unterordner zaehlen gar nicht mit" % (e,)
        assert e["deleted"] == 0 and e["freed_bytes"] == 0, \
            "der Probelauf meldet Geloeschtes: %r — wer nur `deleted` liest, " \
            "haelt ihn dann fuer einen echten Lauf" % (e,)
        assert e["skipped"] == 2 and e["errors"] == 0, \
            "uebersprungen werden genau die zwei jungen Dateien: %r" % (e,)
        assert e["dry_run"] is True
        for p in (d_alt, d_genau, d_neu, d_aussen, d_verweis):
            assert os.path.lexists(p), \
                "dry_run hat %r geloescht — der Dashboard-Knopf zeigt damit " \
                "nur an, was weg WAERE" % (p,)
        ok("W88: cleanup dry_run zaehlt die richtige Datei und loescht nichts")

        e = S.cleanup(aufnahmen, days=TAGE)
        assert e["deleted"] == 1 and e["freed_bytes"] == 1000 \
            and e["skipped"] == 2 and e["errors"] == 0, \
            "der echte Lauf weicht von der Probe ab: %r" % (e,)
        assert e["would_delete"] == 0 and e["would_free_bytes"] == 0, \
            "der echte Lauf fuellt auch die Probe-Felder: %r — dann sagt " \
            "die Zahl nicht mehr, ob geloescht wurde" % (e,)
        assert e["dry_run"] is False and e["retain_days"] == TAGE
        assert not os.path.exists(d_alt), "die alte Aufnahme liegt noch da"
        assert os.path.isfile(d_genau), \
            "die Datei GENAU auf der Grenze wurde geloescht — st_mtime >= " \
            "cutoff heisst behalten"
        assert os.path.isfile(d_neu), "eine junge Aufnahme wurde geloescht"
        assert os.path.islink(d_verweis), \
            "der Verweis wurde geloescht — cleanup darf Symlinks nicht " \
            "anfassen, sonst raeumt es auf fremden Platten auf"
        assert os.path.isfile(d_aussen), \
            "die Datei HINTER dem Verweis ist weg — das ist der teuerste " \
            "Fehler, den diese Funktion machen kann"
        assert os.path.isfile(os.path.join(aufnahmen, "unterordner",
                                           "tief.mp4")), \
            "cleanup ist in einen Unterordner gestiegen"

        with db_conn() as c:
            zeilen_nachher = c.execute(
                "SELECT COUNT(*) AS n FROM recordings").fetchone()["n"]
        assert zeilen_nachher == zeilen_vorher, \
            "cleanup hat Datenbankzeilen entfernt (%d statt %d) — es loescht " \
            "AUSSCHLIESSLICH Dateien, sonst ist die Historie weg" \
            % (zeilen_nachher, zeilen_vorher)
        ok("W88: cleanup loescht nur die alte Datei — Symlink, Unterordner "
           "und Datenbankzeile bleiben")

        # ── 2c) Wenn die Platte unter dem Lauf wegbricht ─────────────────
        # Alle drei Fehlerstellen auf einmal, weil sie dasselbe Fehlerbild
        # haben: ein Aufraeumlauf, der an einem EIO vorbeilaeuft und 0
        # meldet, sieht fuer den Betreiber aus wie "nichts zu tun" — und die
        # Platte laeuft weiter voll.
        class _Eintrag:
            def __init__(self, pfad, stat_bricht=False):
                self.path = pfad
                self._bricht = stat_bricht

            def is_file(self, follow_symlinks=True):
                return True

            def stat(self, follow_symlinks=True):
                if self._bricht:
                    raise OSError("Attrappe: stat gescheitert")
                return alt_os.stat(self.path)

        class _BrechendesOS:
            """Nur scandir/remove sind Attrappe, der Rest ist das echte os."""
            eintraege = None
            scandir_bricht = False

            def __getattr__(self, name):
                return getattr(alt_os, name)

            def scandir(self, pfad):
                if self.scandir_bricht:
                    raise OSError("Attrappe: Verzeichnis weggebrochen")
                return iter(self.eintraege)

            def remove(self, pfad):
                raise OSError("Attrappe: remove gescheitert")

        stub = _BrechendesOS()
        S.os = stub
        try:
            stub.scandir_bricht = True
            e = S.cleanup(aufnahmen, days=TAGE)
            assert e["errors"] == 1 and e.get("error") and e["deleted"] == 0, \
                "ein weggebrochenes Verzeichnis muss als Fehler zurueck- " \
                "kommen, nicht als erfolgreicher Lauf mit 0: %r" % (e,)
            stub.scandir_bricht = False
            stub.eintraege = [_Eintrag(d_genau, stat_bricht=True),
                              _Eintrag(d_neu)]
            os.utime(d_neu, (grenze - 1, grenze - 1))
            e = S.cleanup(aufnahmen, days=TAGE)
            assert e["errors"] == 2 and e["deleted"] == 0 \
                and e["freed_bytes"] == 0, \
                "eine nicht lesbare und eine nicht loeschbare Datei muessen " \
                "je einen Fehler zaehlen und nichts als geloescht melden: " \
                "%r" % (e,)
        finally:
            S.os = alt_os
            os.utime(d_neu, (JETZT, JETZT))
        ok("W88: cleanup zaehlt Lese- und Loeschfehler, statt sie als "
           "erledigt zu melden")

        # ── 3) stats(): das Widget und der Health-Score ──────────────────
        e = S.stats(aufnahmen, retain_days=5)
        assert e["retention_days"] == 5
        assert e["archive_dir"] == {"exists": False}, \
            "ohne Archivverzeichnis darf kein Verzeichnis geraten werden: %r" \
            % (e["archive_dir"],)
        assert e["recordings_dir"]["file_count"] == 2, \
            "das Widget zaehlt %r Dateien — Symlink und Unterordner gehoeren " \
            "nicht dazu" % (e["recordings_dir"]["file_count"],)
        assert e["db_recording_count"] == zeilen_vorher, \
            "die Zahl der Datenbankeintraege stimmt nicht: %r" % (e,)

        # v4.2-W89: der Papierkorb zaehlt NICHT mit. Bis W89 lief er hier mit,
        # waehrend `forecast()` zwei Funktionen weiter ausdruecklich
        # `deleted_at IS NULL` filterte — zwei Zahlen im selben Widget, die
        # dasselbe zu zaehlen behaupten und auseinanderlaufen. Das Deck
        # schreibt daneben "N files"; eine Aufnahme im Papierkorb ist keine.
        # Damit sie dabei nicht unsichtbar wird, kommt sie als eigene Zahl.
        with db_conn() as c:
            c.execute("INSERT INTO recordings (username, filepath, file_size, "
                      "created_at, deleted_at) VALUES (?,?,?,?,?)",
                      ("weg", os.path.join(aufnahmen, "weg.mp4"), 7,
                       "2026-09-16T12:00:00+00:00",
                       "2026-09-16T13:00:00+00:00"))
        e = S.stats(aufnahmen, retain_days=5)
        assert e["db_recording_count"] == zeilen_vorher, \
            "der Papierkorb zaehlt bei den Aufnahmen mit (%r statt %r) — " \
            "dann zeigt das Deck mehr Dateien, als es gibt, und die Zahl " \
            "widerspricht der Hochrechnung daneben" % (
                e["db_recording_count"], zeilen_vorher)
        assert e["db_trash_count"] == 1, \
            "der Papierkorb wird gar nicht ausgewiesen (%r) — dann ist er " \
            "aus der Summe verschwunden, ohne irgendwo aufzutauchen" % (
                e.get("db_trash_count"),)
        with db_conn() as c:
            c.execute("DELETE FROM recordings WHERE username='weg'")
        S.shutil = _Platte
        e = S.stats(aufnahmen, archive_dir=aussen)
        assert e["archive_dir"]["exists"] is True \
            and e["archive_dir"]["file_count"] == 1
        assert e["disk"]["used_percent"] == 90.0, \
            "used_percent ist %r statt 90.0 — ohne dieses Feld blieb der " \
            "Disk-Anteil im Health-Score dauerhaft bei 70/100 mit Note '?'" \
            % (e["disk"]["used_percent"],)
        assert e["disk"]["free_bytes"] == 10 * GIB

        _Platte.werte = (0, 0, 0)
        assert S.stats(aufnahmen)["disk"]["used_percent"] is None, \
            "eine Platte mit total=0 muss None melden statt an der Division " \
            "zu sterben"
        _Platte.werte = (100 * GIB, 90 * GIB, 10 * GIB)
        _Platte.fehler = OSError("Attrappe: Platte nicht lesbar")
        e = S.stats(aufnahmen)
        assert e["disk"] == {"total_bytes": None, "used_bytes": None,
                             "free_bytes": None, "used_percent": None}, \
            "eine nicht lesbare Platte muss vier Nullwerte liefern, nicht " \
            "das Widget mit 500 beantworten: %r" % (e["disk"],)
        _Platte.fehler = None
        e = S.stats(fehlt)
        assert e["recordings_dir"]["exists"] is False \
            and e["disk"]["total_bytes"] == 100 * GIB, \
            "ohne Aufnahmeverzeichnis fehlt der Rueckfall auf '.', und das " \
            "Widget zeigt gar keine Plattenzahlen: %r" % (e,)
        ok("W88: stats liefert used_percent, Archivstand und Rueckfaelle "
           "statt Luecken")

        # ── 4) forecast(): Fenster, Papierkorb, Division ─────────────────
        S.datetime = _Kalender
        e = S.forecast(aufnahmen)
        assert e["days_until_full"] is None and e["samples"] == 0 \
            and "no recordings" in e.get("note", ""), \
            "ohne Aufnahmen der letzten sieben Tage muss die Hochrechnung " \
            "das SAGEN, nicht 0 Tage melden: %r" % (e,)

        def _aufnahme(tag, groesse, weg_am=None):
            with db_conn() as c:
                c.execute(
                    "INSERT INTO recordings (username, filepath, file_size, "
                    "created_at, deleted_at) VALUES (?,?,?,?,?)",
                    ("u", os.path.join(aufnahmen, "x.mp4"), groesse,
                     "2026-09-%02dT10:00:00+00:00" % tag, weg_am))

        # Aufnahmen ohne Groesse: der Riegel `avg_bytes > 0` haelt die
        # Division ab. Faellt er, faengt der `except Exception` darunter den
        # ZeroDivisionError und liefert DASSELBE Ergebnis — im Rueckgabewert
        # ist der Unterschied nicht zu sehen. Sichtbar ist er nur im
        # Fehlerkanal, also wird der mitgelesen.
        _puffer = io.StringIO()
        _wache = _logging.StreamHandler(_puffer)
        _wache.setLevel(_logging.WARNING)
        _log = _logging.getLogger("TikTokBot")
        _stufe = _log.level
        _log.setLevel(_logging.WARNING)
        _log.addHandler(_wache)
        try:
            _aufnahme(16, None)
            e = S.forecast(aufnahmen)
        finally:
            _log.removeHandler(_wache)
            _log.setLevel(_stufe)
        assert e["days_until_full"] is None and e["daily_growth_mb"] == 0 \
            and e["samples"] == 1 and e["free_gb"] == 10.0, \
            "Aufnahmen ohne Groesse ergeben kein Wachstum — ohne den " \
            "avg_bytes>0-Riegel waere das eine Division durch null: %r" % (e,)
        assert _puffer.getvalue() == "", \
            "die Hochrechnung ist in ihren eigenen Fehlerkanal gelaufen, " \
            "obwohl das Ergebnis richtig aussieht: %r" % (_puffer.getvalue(),)

        with db_conn() as c:
            c.execute("DELETE FROM recordings")
        _aufnahme(16, GIB // 2)
        _aufnahme(16, GIB // 2)
        _aufnahme(15, GIB)
        _aufnahme(16, 100 * GIB, "2026-09-16T20:00:00+00:00")   # Papierkorb
        _aufnahme(8, 100 * GIB)                                  # aelter als 7d
        e = S.forecast(aufnahmen)
        assert e["samples"] == 2, \
            "die Hochrechnung sieht %r Tage statt zwei — das Sieben-Tage-" \
            "Fenster oder der Papierkorb-Filter greift nicht: %r" \
            % (e["samples"], e)
        # v4.2-W89: 2 GiB im Fenster, geteilt durch SIEBEN, nicht durch die
        # zwei Tage mit Daten. Der Bestand hat eine Aufnahme vor dem Fenster
        # (Tag 8), die fuenf leeren Tage sind also echte Nulltage.
        #
        # Die alten Zahlen dieses Vertrags waren 1024,0 MB/Tag und 10,0 Tage
        # Restlaufzeit; richtig sind 292,6 MB/Tag und 35,0 Tage. Das ist der
        # ganze Befund in zwei Zahlen: wer an zwei von sieben Tagen aufnimmt,
        # bekam eine Prognose, die um den Faktor 3,5 zu knapp war — und auf
        # diese Zahl hin loescht der Betreiber Aufnahmen, die er 25 Tage
        # laenger haette behalten koennen.
        assert e["basis_tage"] == 7, \
            "geteilt wird durch %r Tage statt durch sieben, obwohl es " \
            "Aufnahmen VOR dem Fenster gibt: %r" % (e.get("basis_tage"), e)
        assert e["daily_growth_mb"] == 292.6, \
            "das Tageswachstum ist %r statt 292.6 MB — eine Zahl, auf der " \
            "die Warnung 'Platte voll' sitzt, und sie darf nicht die " \
            "aktiven Tage fuer alle Tage nehmen" % (e["daily_growth_mb"],)
        assert e["recordings_per_day"] == 0.4, \
            "Aufnahmen je Tag: %r statt 0.4 (drei Aufnahmen auf sieben " \
            "Tage)" % (e["recordings_per_day"],)
        assert e["days_until_full"] == 35.0, \
            "bei 10 GiB frei und 2 GiB in sieben Tagen sind es 35.0 Tage, " \
            "nicht %r" % (e["days_until_full"],)
        assert [t["day"] for t in e["trend"]] == ["2026-09-15", "2026-09-16"], \
            "der Verlauf kommt nicht aufsteigend nach Tag: %r" % (e["trend"],)
        assert e["trend"][0]["count"] == 1 and e["trend"][1]["count"] == 2

        _Platte.fehler = OSError("Attrappe: Platte nicht lesbar")
        e = S.forecast(aufnahmen)
        assert e["days_until_full"] is None and e["free_gb"] is None \
            and e["daily_growth_mb"] == 292.6 and e["samples"] == 2, \
            "ohne Plattenzahlen bleibt das Wachstum trotzdem messbar — es " \
            "darf nur keine Restlaufzeit mehr behaupten: %r" % (e,)
        _Platte.fehler = None
        ok("W88: forecast rechnet ueber sieben Tage ohne Papierkorb und "
           "haelt still, wo ihr die Zahlen fehlen")

        # ── 4b) W89: DIE ANDERE SEITE DES DIVISORS ──────────────────────
        # Stumpf durch sieben zu teilen waere die gefaehrlichere Haelfte
        # desselben Fehlers: ein Bestand, der erst seit zwei Tagen laeuft, hat
        # fuenf STRUKTURELL leere Tage. Die mitzuzaehlen macht die Prognose zu
        # optimistisch — und dann laeuft die Platte voll, waehrend das Deck
        # Ruhe meldet. Eine zu optimistische Prognose kostet Aufnahmen, eine
        # zu pessimistische nur Platz.
        with db_conn() as c:
            c.execute("DELETE FROM recordings")
        _aufnahme(15, GIB)          # nur zwei Tage, und NICHTS davor
        _aufnahme(16, GIB)
        e = S.forecast(aufnahmen)
        assert e["basis_tage"] == 2, \
            "ein Bestand ohne Aufnahmen vor dem Fenster wird auf sieben Tage " \
            "gestreckt (basis_tage=%r) — die Prognose ist dann zu " \
            "optimistisch, und genau das kostet Aufnahmen: %r" % (
                e.get("basis_tage"), e)
        assert e["daily_growth_mb"] == 1024.0 and e["days_until_full"] == 10.0, \
            "bei zwei beobachteten Tagen mit je 1 GiB sind es 1024 MB/Tag " \
            "und 10 Tage, nicht %r / %r" % (
                e["daily_growth_mb"], e["days_until_full"])
        ok("W89: der Divisor sind die BEOBACHTETEN Tage, hoechstens sieben")

        # ── 5) Ohne Datenbank ────────────────────────────────────────────
        configure_db(db_path=os.path.join(heim, "gibt-es-nicht", "x.db"),
                     backend="sqlite")
        e = S.stats(aufnahmen)
        assert e["db_recording_count"] is None and e["db_trash_count"] is None, \
            "ohne Datenbank muessen BEIDE Zaehler None sein statt 0 — 0 " \
            "sieht aus wie 'keine Aufnahmen': %r" % (e,)
        assert e["recordings_dir"]["exists"] is True, \
            "die Verzeichniszahlen haengen nicht an der Datenbank"
        e = S.forecast(aufnahmen)
        assert e["days_until_full"] is None and e.get("error"), \
            "eine kaputte Abfrage muss den Grund mitliefern: %r" % (e,)
        ok("W88: ohne Datenbank melden stats und forecast Luecken statt "
           "Nullwerte")
    finally:
        S.time, S.shutil, S.datetime = alt_time, alt_shutil, alt_datetime
        S.os = alt_os
        configure_db(db_path=alt_pfad, backend=alt_backend)
        _sh.rmtree(heim, ignore_errors=True)


def richte_testdatenbank_ein():
    """Temp-Datenbank, echtes Schema, eine Aufnahme-Zeile. -> (tmp, rid)

    v4.2-W86: HERAUSGELOEST AUS main(). Der Aufbau stand mitten im Runner,
    und damit war die Suite nur ueber ihren eigenen Runner lauffaehig. Wer
    einen einzelnen Vertrag fahren wollte — pytest, ein Debugger, ein
    Profiler —, bekam keine konfigurierte Datenbank: `db_conn()` fiel auf den
    Vorgabepfad zurueck und legte ein `tiktok_bot.db` IM ARBEITSVERZEICHNIS
    an. Beim zweiten Lauf stirbt `_test_dbexport` dann an "table dbx_t
    already exists", und im Repo liegt eine Datenbankdatei, die niemand
    bestellt hat.

    Jetzt rufen BEIDE das hier: main() und conftest.py. Zwei Stellen, die
    einen Aufbau nebeneinander pflegen, laufen sonst auseinander.
    """
    tmp = _ph.verzeichnis()
    configure_db(db_path=os.path.join(tmp, "t.db"), backend="sqlite")

    with db_conn() as c:
        cur = c.cursor()
        for stmt in [s.strip() for s in _extract_schema().split(";") if s.strip()]:
            cur.execute(stmt)
        cur.execute("INSERT INTO recordings (username, filepath, created_at) "
                    "VALUES (?,?,?)",
                    ("helge_72", os.path.join(tmp, "x.mp4"),
                     "2026-07-17T02:00:00"))
        rid = cur.lastrowid
    open(os.path.join(tmp, "x.mp4"), "wb").write(b"0" * 5000)
    return tmp, rid


def _test_v42_w90_suiten_lassen_nichts_liegen():
    """v4.2-W90: die Suiten fuellten die Platte des Entwicklers.

    35 `tempfile.mkdtemp()`, drei `shutil.rmtree`. Auf der Maschine, auf der
    W89 entstand, waren nach einem Tag Arbeit 5093 Verzeichnisse mit rund
    30 GB aufgelaufen, und die Pruefkette brach mitten im Lauf ab:

        /dev/vda  252G  38G  1.1M  100% /
        OSError: [Errno 28] No space left on device

    Kein Vertrag war rot, keine Sperre fiel. In der CI faellt es nie auf:
    ein Lauf, frischer Container, danach ist die Maschine weg.

    Der Kostentreiber war dabei EINE Zeile — `b"\0" * (300 * 1024 * 1024)`
    mit dem Kommentar `# 300 MB (sparse)` daneben. Der Kommentar sagte die
    Absicht, der Code tat das Gegenteil.
    """
    import ast as _ast
    import os as _os
    import pruefhilfen as P

    # ── (1) DIE VORAUSSETZUNG. attrappe() darf nur, solange der geprueete
    # Produktionscode die Groesse aus den Metadaten liest. Wer dort auf
    # st_blocks oder `du` umstellt, sieht eine 300-MB-Datei mit null
    # belegten Bloecken — und dieser Vertrag faellt, bevor die Verzweigung
    # still das Falsche rechnet.
    for modul in ("nc/videoteil.py", "nc/storage.py", "nc/archiverules.py"):
        src = io.open(modul, encoding="utf-8").read()
        assert ("getsize" in src) or ("st_size" in src), \
            "%s liest die Dateigroesse nicht mehr per getsize/st_size — " \
            "dann ist pruefhilfen.attrappe() die falsche Attrappe" % modul
        assert "st_blocks" not in src, \
            "%s wertet st_blocks aus. Eine Attrappe per truncate() hat NULL " \
            "belegte Bloecke; die Rechnung dort stimmt dann nicht mehr, " \
            "ohne dass ein Vertrag faellt." % modul

    # ── (2) DIE ATTRAPPE. Gross in den Metadaten, leer auf der Platte.
    d = P.verzeichnis()
    p300 = P.attrappe(_os.path.join(d, "a.mp4"), 300 * 1024 * 1024)
    st = _os.stat(p300)
    assert _os.path.getsize(p300) == 300 * 1024 * 1024 == st.st_size, \
        "die Attrappe meldet die falsche Groesse: %d" % st.st_size
    assert st.st_blocks == 0, \
        "die Attrappe belegt %d Bloecke — dann ist truncate() nicht mehr " \
        "sparse und der Lauf kostet die 300 MB wieder" % st.st_blocks

    # ── (3) DAS AUFRAEUMEN. Auch nachdem das Arbeitsverzeichnis mitten im
    # Verzeichnis stand — test_smoke.py macht genau das.
    hier = _os.getcwd()
    tief = P.verzeichnis()
    _os.chdir(tief)
    try:
        P.aufraeumen()
        # Das Arbeitsverzeichnis muss danach wieder BENUTZBAR sein. Unter
        # Linux gelingt rmtree auch mit dem cwd darin — os.getcwd() wirft
        # danach aber ENOENT, und jeder folgende relative Pfad ebenso.
        # Unter Windows (dem Entwicklungsrechner) scheitert schon das
        # Loeschen. Beides fangen wir mit derselben Zusicherung: nach dem
        # Aufraeumen steht das cwd wieder an einer Stelle, die es gibt.
        # Ohne diese Zeile entwischte die Mutation "cwd-Rueckwechsel
        # entfernt" — auf Linux war sie nicht zu unterscheiden.
        gelandet = _os.getcwd()
    finally:
        _os.chdir(hier)
    assert _os.path.isdir(gelandet), \
        "nach aufraeumen() zeigt das Arbeitsverzeichnis auf %r, und das " \
        "gibt es nicht — jeder relative Pfad danach scheitert" % (gelandet,)
    assert not (gelandet == tief or gelandet.startswith(tief + _os.sep)), \
        "das Arbeitsverzeichnis liegt noch unter dem geraeumten Pfad %r" \
        % (tief,)
    assert not _os.path.exists(tief), \
        "aufraeumen() hat das Verzeichnis stehen gelassen, in dem das " \
        "Arbeitsverzeichnis lag"
    assert not _os.path.exists(d), "aufraeumen() hat nicht alles geraeumt"

    # ── (4) DIE SPERRE muss den Code anschlagen, den es vor dieser Welle
    # wirklich gab — sonst ist sie eine Behauptung. Der Schnipsel steht hier
    # woertlich und NICHT als `git show HEAD~1`: eine Bindung an die
    # Historie faellt zwei Wellen spaeter, wenn der Vorgaenger-Stand sauber
    # ist, und dann meldet ein gruener Code einen roten Vertrag. Genau diese
    # Anker-Klasse hat in test_restream schon dreimal zugeschlagen.
    import sys as _sys2
    _sys2.path.insert(0, "tools")
    import testmuell as T
    WIE_ES_WAR = (
        'import tempfile\n'
        'def _alt():\n'
        '    tmp = tempfile.mkdtemp()\n'
        '    with open("a.mp4", "wb") as f:\n'
        '        f.write(b"\\0" * (300 * 1024 * 1024))    # 300 MB (sparse)\n'
    )
    tmp_alt, gross_alt = T.finde(_ast.parse(WIE_ES_WAR))
    assert len(tmp_alt) == 1, \
        "die Sperre findet den nackten mkdtemp() nicht mehr"
    assert gross_alt and gross_alt[0][1] == 300 * 1024 * 1024, \
        "die Sperre findet den 300-MB-Schreibvorgang nicht mehr: %r" \
        % (gross_alt,)

    # Die Groessenrechnung selbst: literal_eval kann kein `*` und liess den
    # 300-MB-Fall im ersten Entwurf durch. Gefangen hat das die
    # Mutationsprobe, nicht das Nachdenken.
    assert T._wert(_ast.parse("300 * 1024 * 1024", mode="eval").body) \
        == 314572800, \
        "die Groessenrechnung wertet verschachtelte Produkte nicht mehr " \
        "aus — dann findet die Sperre genau die grossen Faelle nicht"
    assert T._wert(_ast.parse("n * 1024", mode="eval").body) is None, \
        "eine variable Groesse wird geraten statt als unentscheidbar " \
        "behandelt"

    # ── (5) UND DER HEUTIGE STAND ist frei davon.
    tmp_jetzt, gross_jetzt = [], []
    for name in T.SUITEN:
        a, b = T.finde(_ast.parse(io.open(name, encoding="utf-8").read()))
        tmp_jetzt += [(name, x) for x in a]
        gross_jetzt += [(name, x) for x in b]
    assert not tmp_jetzt, "nackte mkdtemp-Aufrufe zurueck: %r" % (tmp_jetzt,)
    assert not gross_jetzt, \
        "Schreibvorgaenge ab 1 MiB zurueck: %r" % (gross_jetzt,)

    # ── (6) UND SIE HAENGT, WO SIE WIRKT. Eine Sperre, die nur in einem
    # Werkzeugverzeichnis liegt, ist in einer Woche vergessen: sie muss in
    # der CI laufen (fuer jeden Beitrag) und in der Pflicht-Pruefkette
    # stehen (fuer den Entwicklungsrechner, wo der Schaden entsteht).
    ci = io.open(".github/workflows/ci.yml", encoding="utf-8").read()
    assert "tools/testmuell.py --sperre" in ci, \
        "die Sperre laeuft nicht mehr in der CI — dann waechst der Muell " \
        "auf jedem Entwicklungsrechner wieder, ohne dass etwas rot wird"
    anleitung = io.open("CLAUDE.md", encoding="utf-8").read()
    assert "tools/testmuell.py" in anleitung, \
        "die Sperre steht nicht in der Pflicht-Pruefkette in CLAUDE.md"

    # ── (7) UND SIE FAEHRT AUCH AUF DEM SERVER. Die vier Suiten liegen im
    # Auslieferungs-Archiv; was sie importieren, muss mit. Fehlt es, stirbt
    # nicht ein Vertrag, sondern der Import — alle vier Suiten auf einmal,
    # mit einem nackten ImportError. W86 hatte denselben Fall fuer
    # conftest.py/pytest.ini, dort nur leiser ("no tests ran" sieht aus wie
    # ein gruener Lauf).
    archiv = io.open("tools/build_release.py", encoding="utf-8").read()
    for name in T.SUITEN + ["pruefhilfen.py", "conftest.py"]:
        assert '"%s"' % name in archiv, \
            "%s fehlt in der Dateiliste von build_release.py — auf dem " \
            "Server laeuft danach keine der Suiten mehr" % name

    ok("W90: attrappe() ist gross in den Metadaten und leer auf der Platte")
    ok("W90: aufraeumen() raeumt auch unter dem Arbeitsverzeichnis")
    ok("W90: die Sperre schlaegt auf dem Stand von vor der Welle an")


def _test_v42_w91_aufraeumer_loescht_nicht_alles():
    """v4.2-W91: ein stiller except machte aus "raeum die Reste weg" ein
    "loesche alle Aufnahmen".

    _find_orphans() liest die Liste der bekannten Dateien aus der Datenbank
    und meldet jede Datei im Aufnahmeverzeichnis, die nicht darin steht. Bis
    zu dieser Welle stand um diese Abfrage:

        except Exception:
            known = set()

    Mit leerem `known` ist `full not in known` fuer JEDE Datei wahr — jede
    .mp4 bekommt den Grund "kein-db-eintrag", und /api/rec/orphans/clean
    loescht alles, was die Funktion liefert. Ein gesperrtes SQLite (der
    Recorder schreibt parallel, das ist Alltag) genuegte.

    Der gefaehrliche Ablauf brauchte nicht einmal Pech: das Deck laedt erst
    /api/rec/orphans (Datenbank in Ordnung, drei Reste) und schickt dann den
    Knopf mit confirm=true. Faellt die Datenbank zwischen diesen beiden
    Aufrufen, hat der Betreiber das Loeschen von drei Dateien bestaetigt und
    alle verloren.
    """
    import os as _os
    from flask import Flask
    from nc import ctx as _ncctx
    from nc.routes import recordings as rt
    import pruefhilfen as P

    heim = P.verzeichnis()
    aufnahmen = _os.path.join(heim, "aufnahmen")
    _os.makedirs(aufnahmen)
    echte = [P.attrappe(_os.path.join(aufnahmen, n), 4096)
             for n in ("stream_a.mp4", "stream_b.mp4", "stream_c.mp4")]
    # 5 MiB und nicht 2 KiB: `freed_mb` rundet auf eine Nachkommastelle, und
    # bei 2 KiB ist der Unterschied zwischen "vor dem Loeschen gezaehlt" und
    # "nach dem Loeschen gezaehlt" beides 0.0. Genau daran ist die
    # Mutationsprobe zunaechst entwischt. Dank truncate() kostet die Groesse
    # nichts (siehe W90).
    rest = P.attrappe(_os.path.join(aufnahmen, "stream_a_part2.mp4"),
                      5 * 1024 * 1024)

    class _Log:
        def __init__(self): self.zeilen = []
        def _sammle(self, *a, **k):
            self.zeilen.append(a[0] % a[1:] if len(a) > 1 else str(a[0]))
        warning = info = error = debug = _sammle
    protokoll = _Log()

    alt_ctx = _ncctx._CTX
    _ncctx.configure(recordings_dir=aufnahmen, log=protokoll,
                     log_event=lambda *a, **k: None,
                     arg_int=lambda *a, **k: 0,
                     ffmpeg_threads_bg=1, ffmpeg_nice_bg=10)
    app = Flask(__name__)
    app.register_blueprint(rt.bp)
    klient = app.test_client()

    class _DbKaputt(Exception):
        pass

    def _gesperrt(*a, **k):
        raise _DbKaputt("database is locked")

    echt_db = rt.db_conn
    try:
        # ── (1) DER KERNBEFUND. Faellt die Datenbank, wird nicht geraten.
        rt.db_conn = _gesperrt
        try:
            rt._find_orphans()
            raise AssertionError(
                "_find_orphans() hat trotz unlesbarer Datenbank eine Liste "
                "geliefert — mit leerem `known` steht darin JEDE Aufnahme, "
                "und /orphans/clean loescht sie")
        except rt.BestandUnbekannt as e:
            assert "nichts" in str(e).lower() or "geloescht" in str(e).lower(), \
                "die Meldung sagt nicht, dass nichts geloescht wird: %s" % e

        # Die Gegenprobe zur Schwere: haette die Funktion mit leerem `known`
        # weitergemacht, waeren es ALLE drei echten Aufnahmen plus der Rest
        # gewesen — nicht der eine Rest.
        bekannt_leer = set()
        wuerde_treffen = [n for n in _os.listdir(aufnahmen)
                          if n.endswith(".mp4")
                          and _os.path.join(aufnahmen, n) not in bekannt_leer]
        assert len(wuerde_treffen) == 4, wuerde_treffen

        # ── (2) DIE LISTE sagt warum, statt "keine verwaisten Dateien".
        antwort = klient.get("/api/rec/orphans")
        assert antwort.status_code == 503, \
            "unlesbare Datenbank meldet %d statt 503" % antwort.status_code
        daten = antwort.get_json()
        assert daten["ok"] is False and daten.get("unentscheidbar") is True
        assert daten["orphans"] == [] and daten["count"] == 0, \
            "eine unentscheidbare Lage darf keine Trefferliste vortaeuschen"

        # ── (3) UND DER KNOPF LOESCHT NICHTS.
        antwort = klient.post("/api/rec/orphans/clean", json={"confirm": True})
        assert antwort.status_code == 503, antwort.status_code
        daten = antwort.get_json()
        assert daten["deleted"] == 0 and daten["freed_mb"] == 0.0
        for pfad in echte + [rest]:
            assert _os.path.isfile(pfad), \
                "trotz unlesbarer Datenbank wurde %s geloescht" % pfad
        assert any("nicht zu lesen" in z for z in protokoll.zeilen), \
            "der Abbruch steht in keiner Logzeile: %r" % protokoll.zeilen
    finally:
        rt.db_conn = echt_db

    ok("W91: unlesbare Datenbank -> _find_orphans bricht ab, statt alles "
       "als verwaist zu melden")
    ok("W91: /orphans meldet 503 und eine leere Liste, nicht 'nichts gefunden'")
    ok("W91: /orphans/clean loescht bei unlesbarer Datenbank keine einzige Datei")

    # ── (4) IM NORMALFALL trifft es genau den Rest — und `freed` zaehlt nur,
    # was wirklich weg ist. Vor W91 wurde die Groesse VOR dem os.remove
    # addiert: das Deck meldete dann Platz, der noch belegt war.
    #
    # Die Datenbank kennt hier die drei echten Aufnahmen: genau das ist der
    # Unterschied zum Fall oben, und genau diesen Unterschied hat der stille
    # except eingeebnet.
    class _Zeilen(list):
        def fetchall(self): return self

    class _ConnKennt:
        def execute(self, sql, args=()):
            # v4.2-W131: _find_orphans fragt zusaetzlich die laufenden
            # Aufnahmen ab — hier laeuft keine.
            if "trackings" in sql:
                return _Zeilen()
            return _Zeilen({"filepath": p} for p in echte)
        def commit(self): pass
        def __enter__(self): return self
        def __exit__(self, *a): return False

    try:
        rt.db_conn = lambda: _ConnKennt()
        treffer = rt._find_orphans()
        namen = {t["name"] for t in treffer}
        assert namen == {"stream_a_part2.mp4"}, \
            "erwartet nur den Split-Rest, bekommen: %r" % namen

        echt_remove = rt.os.remove
        rt.os.remove = lambda p: (_ for _ in ()).throw(
            OSError(13, "Permission denied"))
        try:
            antwort = klient.post("/api/rec/orphans/clean",
                                  json={"confirm": True})
        finally:
            rt.os.remove = echt_remove
        daten = antwort.get_json()
        assert daten["deleted"] == 0, daten
        assert daten["freed_mb"] == 0.0, \
            "es wurde Platz gemeldet, obwohl keine Datei geloescht wurde: %r" \
            % daten
        assert daten["failed"] == 1 and daten["failed_details"], \
            "der Fehlschlag wird nicht gemeldet: %r" % daten
        assert _os.path.isfile(rest), "die Datei ist trotz Fehler weg"
    finally:
        rt.db_conn = echt_db
        _ncctx._CTX = alt_ctx

    ok("W91: /orphans/clean meldet keinen Platz, den es nicht frei gemacht hat")


def _test_v42_w91_retention_haelt_datei_und_eintrag_zusammen():
    """v4.2-W91: die Retention loeschte den Datenbank-Eintrag auch dann, wenn
    die Datei liegen blieb.

    Das Ergebnis war eine Aufnahme ohne Eintrag: sie belegt weiter Platz,
    taucht in keiner Liste auf, und das Deck meldete den Platz als frei.
    Dieselbe Klasse wie der W89-Befund in nc/archiverules.py, nur
    andersherum — dort blieb die Kopie ohne Zeile, hier die Datei.
    """
    import os as _os
    from flask import Flask
    from nc import ctx as _ncctx
    from nc.routes import recordings as rt
    import pruefhilfen as P

    heim = P.verzeichnis()
    datei = P.attrappe(_os.path.join(heim, "alt.mp4"), 8192)

    gefallene_ids = []

    class _Conn:
        def execute(self, sql, args=()):
            if sql.strip().upper().startswith("DELETE"):
                gefallene_ids.append(args[0])
            return self
        def commit(self): pass
        def __enter__(self): return self
        def __exit__(self, *a): return False

    class _Log:
        def __init__(self): self.zeilen = []
        def _s(self, *a, **k):
            self.zeilen.append(a[0] % a[1:] if len(a) > 1 else str(a[0]))
        warning = info = error = debug = _s
    protokoll = _Log()

    alt_ctx = _ncctx._CTX
    _ncctx.configure(recordings_dir=heim, log=protokoll,
                     log_event=lambda *a, **k: None,
                     arg_int=lambda *a, **k: 0,
                     ffmpeg_threads_bg=1, ffmpeg_nice_bg=10)
    app = Flask(__name__)
    app.register_blueprint(rt.bp)
    klient = app.test_client()

    echt_match, echt_db, echt_remove = rt._retention_match, rt.db_conn, rt.os.remove
    try:
        rt._retention_match = lambda regeln: [
            {"id": 4711, "filepath": datei, "file_size": 8192}]
        rt.db_conn = lambda: _Conn()
        rt.os.remove = lambda p: (_ for _ in ()).throw(
            OSError(16, "Device or resource busy"))

        antwort = klient.post("/api/rec/retention/apply",
                              json={"confirm": True, "rules": {}})
        daten = antwort.get_json()
        assert daten["ok"] is True, daten
        assert daten["deleted"] == 0, \
            "eine Aufnahme wurde als geloescht gezaehlt, deren Datei liegen " \
            "blieb: %r" % daten
        assert daten["freed_mb"] == 0.0, daten
        assert daten["failed"] == 1, "der Fehlschlag fehlt in der Antwort: %r" % daten
        assert 4711 not in gefallene_ids, \
            "der Datenbank-Eintrag fiel, obwohl die Datei liegen blieb — " \
            "die Aufnahme ist damit unauffindbar statt nur uebrig"
        assert _os.path.isfile(datei)
        assert any("liegen" in z for z in protokoll.zeilen), \
            "kein Hinweis im Log: %r" % protokoll.zeilen

        # Und der Normalfall: Datei weg -> Eintrag faellt mit.
        del gefallene_ids[:]
        rt.os.remove = echt_remove
        antwort = klient.post("/api/rec/retention/apply",
                              json={"confirm": True, "rules": {}})
        daten = antwort.get_json()
        assert daten["deleted"] == 1 and daten["failed"] == 0, daten
        assert gefallene_ids == [4711], gefallene_ids
        assert not _os.path.exists(datei)
    finally:
        rt._retention_match, rt.db_conn, rt.os.remove = echt_match, echt_db, echt_remove
        _ncctx._CTX = alt_ctx

    ok("W91: eine Datei, die nicht weichen will, behaelt ihren Eintrag")
    ok("W91: die Retention meldet Fehlschlaege, statt sie als Erfolg zu zaehlen")


def _test_v42_w91_blinde_helfer_melden():
    """v4.2-W91: 14 stumme Rueckgaben in drei Helfern.

    ffprobe_inspect (5), compute_waveform_peaks (7) und
    build_recording_manifest (2) kehrten bei jedem Fehlschlag ordentlich mit
    None zurueck — vier Ausgaenge ganz ohne Zeile, die uebrigen auf
    log.debug. Fuer den Betreiber ist ein Fehlerpfad auf `debug` dasselbe
    wie `pass`: im Deck bleibt die Wellenform leer, im Log steht nichts.
    Genau dieses Bild hat er am 13.09. fuer den Resolver gemeldet, und
    genau dafuer gibt es seit W81 nc/meldetakt.py.

    Geprueft wird nicht nur DASS gemeldet wird, sondern der Rhythmus: eine
    ungedrosselte Meldung pro Aufnahme waere nach einer Stunde unlesbar, und
    eine unlesbare Warnung ist so gut wie keine.
    """
    import asyncio as _aio
    import os as _os
    from nc import ctx as _ncctx
    from nc import meldetakt as _takt
    from nc.routes import recordings as rt
    import pruefhilfen as P

    class _Log:
        def __init__(self): self.zeilen = []
        def _s(self, *a, **k):
            self.zeilen.append(a[0] % a[1:] if len(a) > 1 else str(a[0]))
        warning = info = error = debug = _s
    protokoll = _Log()

    heim = P.verzeichnis()
    alt_ctx = _ncctx._CTX
    _ncctx.configure(recordings_dir=heim, log=protokoll,
                     log_event=lambda *a, **k: None,
                     arg_int=lambda *a, **k: 0,
                     ffmpeg_threads_bg=1, ffmpeg_nice_bg=10)
    try:
        # ── (1) EINE FEHLENDE DATEI IST EINE MELDUNG WERT.
        _takt.zuruecksetzen()
        del protokoll.zeilen[:]
        assert _aio.run(rt.ffprobe_inspect(_os.path.join(heim, "gibtsnicht.mp4"))) is None
        assert protokoll.zeilen, \
            "ffprobe_inspect schweigt bei fehlender Datei — fuer den " \
            "Betreiber ist das dasselbe wie `pass`"
        assert "ffprobe" in protokoll.zeilen[0], protokoll.zeilen

        # ── (2) ABER NICHT HUNDERT. Derselbe Grund wird gedrosselt.
        vorher = len(protokoll.zeilen)
        for _ in range(50):
            _aio.run(rt.ffprobe_inspect(_os.path.join(heim, "gibtsnicht.mp4")))
        assert len(protokoll.zeilen) == vorher, \
            "50 gleiche Fehlschlaege erzeugten %d Zeilen — ungedrosselt ist " \
            "das Log nach einer Stunde unlesbar" \
            % (len(protokoll.zeilen) - vorher)

        # ── (3) EIN WECHSEL DES GRUNDES IST DIE EIGENTLICHE NACHRICHT und
        # kommt sofort durch, auch innerhalb des Drossel-Fensters.
        echt_which = rt.shutil.which
        rt.shutil.which = lambda name: None
        try:
            datei = P.attrappe(_os.path.join(heim, "da.mp4"), 1024)
            _aio.run(rt.ffprobe_inspect(datei))
        finally:
            rt.shutil.which = echt_which
        assert len(protokoll.zeilen) > vorher, \
            "der Wechsel auf 'ffprobe fehlt' wurde weggedrosselt"
        assert any("nicht installiert" in z for z in protokoll.zeilen), \
            protokoll.zeilen

        # ── (4) UND DIE MELDUNG TRAEGT EINE ABHILFE. "HTTP 403" allein hat
        # laut CLAUDE.md schon einmal wochenlang niemandem geholfen.
        fehlt = [z for z in protokoll.zeilen if "nicht installiert" in z][0]
        assert "apt install" in fehlt, \
            "die Meldung sagt nicht, was zu tun ist: %s" % fehlt

        # ── (5) DIE WELLENFORM meldet auf einem EIGENEN Kanal. Bewusst OHNE
        # zuruecksetzen(): beide Helfer melden fuer eine fehlende Datei
        # denselben Wortlaut, und bei einem gemeinsamen Schluessel
        # verschluckt die Drossel deshalb den zweiten — das Deck zeigt eine
        # leere Wellenform, und im Log steht nur etwas ueber ffprobe.
        # Mit zuruecksetzen() davor entwischte diese Mutationsprobe.
        _takt.zuruecksetzen()
        del protokoll.zeilen[:]
        fehlt_datei = _os.path.join(heim, "auch_nicht.mp4")
        assert _aio.run(rt.ffprobe_inspect(fehlt_datei)) is None
        nach_ffprobe = len(protokoll.zeilen)
        assert nach_ffprobe == 1, protokoll.zeilen
        assert _aio.run(rt.compute_waveform_peaks(fehlt_datei)) is None
        assert len(protokoll.zeilen) > nach_ffprobe, \
            "die Wellenform wurde von der ffprobe-Drossel verschluckt — " \
            "beide brauchen einen eigenen Schluessel"
        assert any("wellenform" in z for z in protokoll.zeilen), protokoll.zeilen

        # ── (6) UND EIN MANIFEST ZU EINER AUFNAHME, DIE ES NICHT GIBT, sagt
        # das — ungedrosselt, weil es eine Anfrage pro Aufruf ist und nicht
        # pro Poll.
        del protokoll.zeilen[:]
        echt_get = rt.recdb.get_recording_by_id
        rt.recdb.get_recording_by_id = lambda rid: None
        try:
            assert rt.build_recording_manifest(999999) is None
        finally:
            rt.recdb.get_recording_by_id = echt_get
        assert any("999999" in z for z in protokoll.zeilen), protokoll.zeilen

        # ── (7) KEINE BLINDSTELLE MEHR IN DIESER DATEI. Gemessen mit dem
        # Werkzeug selbst, nicht per Augenschein: 14 waren es vor W91.
        import pathlib as _pl
        import sys as _sys2
        _sys2.path.insert(0, "tools")
        import blindstellen as _bl
        offen = _bl.sammle(_pl.Path("nc/routes/recordings.py").resolve())
        assert not offen, \
            "wieder stumme Rueckgaben in recordings.py: %r" \
            % [(z, fn) for _d, z, fn in offen]
    finally:
        _takt.zuruecksetzen()
        _ncctx._CTX = alt_ctx

    ok("W91: die drei Helfer melden ihren Grund, mit Abhilfe")
    ok("W91: gedrosselt auf einen Kanal je Helfer, Grundwechsel sofort")


def _test_v42_w91_build_laesst_keinen_stempel_liegen():
    """v4.2-W91: ein Release-Build machte die Suite rot.

    build_release.py schreibt AUSLIEFERUNG.json in den Arbeitsbaum, damit
    der Stempel ins Archiv wandert — und raeumte ihn dort nie weg. Die Datei
    steht in .gitignore, faellt also bei `git status` nicht auf; nc/
    auslieferung.py bevorzugt sie aber vor git. Nach einem einzigen Build
    meldeten /healthz und /api/version auf dem Entwicklungsrechner dauerhaft
    den eingefrorenen Stand, und
    _test_v42_w85_schemastand_und_herkunft fiel mit "aus einem
    git-Arbeitsbaum heraus darf die Herkunft nicht unbekannt sein" — eine
    rote Suite ohne Codefehler, deren Meldung auf die Herkunft zeigt statt
    auf den liegengebliebenen Stempel.

    Statisch geprueft, weil build_release.py fest in die Projektwurzel
    schreibt: ein echter Build im Vertrag wuerde 3,8 MB packen und dabei
    genau die Datei anfassen, um die es geht.
    """
    quelle = io.open("tools/build_release.py", encoding="utf-8").read()

    assert "stempel_lag_schon_da" in quelle, \
        "build_release.py merkt sich nicht mehr, ob schon ein Stempel da " \
        "war — dann loescht es in einem entpackten Archiv den echten"
    rumpf = rumpf_ab(quelle, quelle.index("stempel_lag_schon_da"))
    assert 'os.remove(os.path.join(WURZEL, "AUSLIEFERUNG.json"))' in rumpf, \
        "der Stempel wird nach dem Packen nicht mehr aus dem Arbeitsbaum " \
        "entfernt — nach einem Build ist die Suite rot"
    assert "if not stempel_lag_schon_da:" in rumpf, \
        "das Entfernen haengt nicht mehr an der Bedingung: in einem " \
        "entpackten Archiv wuerde damit der gueltige Stempel geloescht"

    # Und die Datei bleibt ignoriert — sonst landet ein lokaler Build-Stempel
    # im Repo und behauptet dort eine Herkunft fuer alle.
    assert "AUSLIEFERUNG.json" in io.open(".gitignore", encoding="utf-8").read()

    # Der Schaden selbst: ein vorhandener Stempel verdeckt die git-Herkunft.
    # Das ist die Eigenschaft, die das Aufraeumen ueberhaupt noetig macht.
    import nc.auslieferung as _au
    assert "AUSLIEFERUNG.json" in io.open(
        "nc/auslieferung.py", encoding="utf-8").read()
    assert hasattr(_au, "schreibe") and hasattr(_au, "stand"), \
        "nc/auslieferung.py hat seine Schnittstelle geaendert"
    # Und die Datei gewinnt wirklich gegen git — sonst waere der
    # liegengebliebene Stempel harmlos und dieser Vertrag ueberfluessig.
    quelle_au = io.open("nc/auslieferung.py", encoding="utf-8").read()
    assert "archiv" in quelle_au, \
        "nc/auslieferung.py kennt die Quelle 'archiv' nicht mehr"

    ok("W91: ein Release-Build laesst keinen Stempel im Arbeitsbaum zurueck")


def _test_v42_w92_unlesbare_datenbank_sagt_was_zu_tun_ist():
    """v4.2-W92: der Bot starb an einer unlesbaren Datenbank ohne ein Wort
    zur Abhilfe.

    Am 17.09. lag statt der Datenbank ein 108-MB-Blob mit TLS-Verkehr im
    Arbeitsverzeichnis. Der Start endete so:

        File "nc/dbwrap.py", line 370, in db_conn
          conn.execute("PRAGMA synchronous=NORMAL")
        sqlite3.DatabaseError: file is not a database

    Drei Dateien Traceback, und nicht eine Angabe, die weiterhilft: welche
    Datei, wie gross, was steht stattdessen drin, was ist zu tun. In der
    gefaehrlichsten Lage des Systems ist das dieselbe Art Meldung wie ein
    blankes "HTTP 403" — richtig und nutzlos. Die naheliegende Reaktion,
    die Datei zu loeschen, damit es wieder laeuft, kostet Trackings,
    Aufnahme-Eintraege und den Ledger.
    """
    import os as _os
    import sqlite3 as _sq3
    from nc import dbwrap as D
    import pruefhilfen as P

    heim = P.verzeichnis()

    def _mit_inhalt(name, roh):
        pfad = _os.path.join(heim, name)
        with open(pfad, "wb") as f:
            f.write(roh)
        return pfad

    # ── (1) DER FALL VOM 17.09.: TLS-Verkehr statt Datenbank.
    tls = _mit_inhalt("tls.db", bytes.fromhex("17030300 2d0cfcba") + b"\x00" * 512)
    text = D.datei_diagnose(tls)
    assert "TLS" in text, text
    assert "17 03 03" in text, "die ersten Bytes fehlen: %s" % text
    assert _os.path.abspath(tls) in text, "der Pfad fehlt — welche Datei denn?"
    assert "NICHT loeschen" in text, \
        "die Meldung warnt nicht vor dem Loeschen. Genau das ist die " \
        "naheliegende Reaktion, und sie kostet den Ledger."
    assert "Sicherung" in text or "SQL-Dump" in text, \
        "kein Hinweis auf die Sicherungen: %s" % text

    # ── (2) DIE UNTERSCHEIDUNG, auf die es ankommt: ein echter
    # Datenbankschaden bekommt einen ANDEREN Rat als eine ueberschriebene
    # Datei. Bei erhaltenem Header hilft .recover, bei TLS-Muell nicht.
    kaputt = _mit_inhalt("kaputt.db", b"SQLite format 3\x00" + b"\xff" * 4096)
    text_k = D.datei_diagnose(kaputt)
    assert "recover" in text_k, \
        "bei erhaltenem SQLite-Header fehlt der Rettungsweg: %s" % text_k
    assert "recover" not in text, \
        "bei einer ueberschriebenen Datei wird .recover empfohlen — das " \
        "schickt den Betreiber auf eine Stunde vergebliche Arbeit"

    # ── (3) DIE LEERE DATEI. Der Fall, in dem SQLite gerade NICHT neu
    # anlegt — eine 0-Byte-Datei ist keine Datenbank.
    leer = _mit_inhalt("leer.db", b"")
    text_l = D.datei_diagnose(leer)
    assert "LEER" in text_l and "FEHLENDER" in text_l, text_l

    # ── (4) WEITERE FORMEN, die schon vorkamen.
    for name, roh, erwartet in (
            ("z.db", b"\x1f\x8b\x08\x00", "gzip"),
            ("h.db", b"<!DOCTYPE html><html>", "HTML"),
            ("p.db", b"PK\x03\x04\x14\x00", "ZIP")):
        t = D.datei_diagnose(_mit_inhalt(name, roh))
        assert erwartet.lower() in t.lower(), "%s nicht erkannt: %s" % (erwartet, t)

    # ── (5) UND EIN UNBEKANNTES FORMAT raet nicht, sondern zeigt den Hex und
    # nennt den Vergleich.
    unbek = _mit_inhalt("u.db", b"\x99\x88\x77\x66rest")
    t = D.datei_diagnose(unbek)
    assert "53 51 4c 69 74 65" in t, \
        "ohne den SQLite-Vergleichsheader kann der Betreiber nichts pruefen"

    # ── (5b) DER FALL, DER DIE ERSTE FASSUNG FALSCH BERATEN HAETTE.
    # Beim Betreiber lag ein TLS-Kopf VOR einem SQL-Dump: 33.444 Zeilen mit
    # CREATE-TABLE- und INSERT-Vokabular, 10 MB komprimierten auf 2 MB. Die
    # Diagnose sah damals nur die ersten 16 Bytes, erkannte "TLS" und riet
    # "aus ihr ist nichts zu holen" — also seine vollstaendigen Daten als
    # verloren abgehakt. Ein falscher Rat ist hier teurer als gar keiner.
    # Der Dump beginnt ERST NACH 200 KB. Das ist kein Detail: die Probe liest
    # 64 KB vom Anfang, und beim Betreiber ist die Datei 108 MB gross — waere
    # nur der Anfang geprobt, saehe die Diagnose ausschliesslich den fremden
    # Vorlauf und riete wieder zum Aufgeben. Genau daran ist die
    # Mutationsprobe "nur noch der Anfang wird geprobt" zunaechst entwischt.
    dump = _os.path.join(heim, "dump.db")
    with open(dump, "wb") as f:
        f.write(bytes.fromhex("170303002d0cfcba"))
        f.write(b"\x00" * (200 * 1024))
        f.write(b"BEGIN TRANSACTION;\nCREATE TABLE recordings (id INT);\n")
        for i in range(30000):
            f.write(b"INSERT INTO recordings VALUES(%d);\n" % i)
    t = D.datei_diagnose(dump)
    assert "SQL-Dump" in t, \
        "ein Dump hinter dem TLS-Kopf wird nicht erkannt: %s" % t
    assert "sqlite3 neu.db <" in t, "der Rettungsweg fuer einen Dump fehlt"
    assert "CREATE TABLE" in t and "tail -c" in t, \
        "kein Befehl, der den Muell vor der ersten CREATE-Zeile abschneidet"
    assert "verfrueht" in t, \
        "die Diagnose raet weiter zum Aufgeben, obwohl strukturierte Daten " \
        "drinstehen — genau der Fehler, den der echte Fall aufgedeckt hat"
    assert "nichts zu holen" not in t, t

    # Und die Gegenrichtung bleibt ehrlich: ZUFALLSDATEN sind verloren, und
    # das darf die Diagnose auch sagen.
    zufall = _mit_inhalt("rnd.db", _os.urandom(200000))
    tz = D.datei_diagnose(zufall)
    assert "verschluesselte oder zufaellige" in tz, tz
    assert "verfrueht" not in tz, \
        "Zufallsdaten werden als rettbar dargestellt: %s" % tz

    # ── (6) DIE FEHLENDE DATEI ist etwas anderes als eine kaputte: SQLite
    # legt dann normalerweise neu an. Passiert das nicht, sind es die Rechte.
    fehlt = D.datei_diagnose(_os.path.join(heim, "gibtsnicht.db"))
    assert "existiert nicht" in fehlt and "Rechte" in fehlt, fehlt

    # ── (7) db_conn() WIRFT DIE DIAGNOSE, und zwar so, dass bestehender Code
    # sie weiter faengt: DatenbankUnlesbar IST ein sqlite3.DatabaseError.
    assert issubclass(D.DatenbankUnlesbar, _sq3.DatabaseError), \
        "DatenbankUnlesbar erbt nicht mehr von sqlite3.DatabaseError — " \
        "jedes bestehende `except sqlite3.DatabaseError` im Bestand faellt " \
        "damit durch"
    alt_pfad, alt_backend = D.DB_PATH, D.DB_BACKEND
    try:
        D.DB_PATH, D.DB_BACKEND = tls, "sqlite"
        try:
            with D.db_conn() as c:
                c.execute("SELECT 1")
            raise AssertionError("db_conn() oeffnete einen TLS-Blob")
        except D.DatenbankUnlesbar as e:
            assert "TLS" in str(e) and "NICHT loeschen" in str(e), str(e)
        # Und die Gegenprobe: eine GESUNDE Datei laeuft unveraendert durch.
        gesund = _os.path.join(heim, "gut.db")
        _sq3.connect(gesund).execute("CREATE TABLE t (a INT)")
        D.DB_PATH = gesund
        with D.db_conn() as c:
            c.execute("INSERT INTO t VALUES (1)")
            assert c.execute("SELECT COUNT(*) AS c FROM t").fetchone()["c"] == 1
    finally:
        D.DB_PATH, D.DB_BACKEND = alt_pfad, alt_backend

    # ── (8) UND DER BOT BRICHT AB, statt eine leere Datenbank anzulegen.
    # Statisch geprueft: main() zu fahren hiesse den ganzen Bot zu starten.
    quelle = io.open("bot.py", encoding="utf-8").read()
    rumpf = rumpf_ab(quelle, quelle.index("def _init_db_oder_abbruch("))
    rumpf += rumpf_ab(quelle, quelle.index("def _abbruch_datenbank_unlesbar("))
    assert "DatenbankUnlesbar" in rumpf, \
        "der Start faengt die Diagnose nicht mehr — dann sieht der Betreiber " \
        "wieder den nackten sqlite3-Traceback"
    assert "SystemExit" in rumpf, \
        "der Start laeuft nach einer unlesbaren Datenbank weiter. Dann legt " \
        "SQLite spaeter eine neue, leere an, und der Datenverlust ist still."
    assert "log.critical" in rumpf, \
        "die Diagnose geht nicht auf critical — auf warning liest sie niemand"
    # Der Selfcheck zeigt sie ebenfalls, und zwar mehrzeilig.
    selfcheck = rumpf_ab(quelle, quelle.index("def _selfcheck("))
    assert "splitlines()" in selfcheck, \
        "der Selfcheck quetscht die Diagnose in eine Tabellenzeile"
    assert "DatenbankUnlesbar" in selfcheck, \
        "der Selfcheck unterscheidet die unlesbare Datenbank nicht mehr von " \
        "einem gewoehnlichen Migrationsfehler"

    # ── (9) DIE FEHLERPFADE DER DIAGNOSE SELBST. Eine Diagnose, die beim
    # Diagnostizieren stirbt, ist in genau der Lage nutzlos, fuer die sie
    # gebaut ist — und alle neun Zeilen waren zunaechst ungeprueft, genau wie
    # die fuenf in W89. Die Ueberdeckungssperre hat sie gefunden.
    import zlib as _zlib

    # (a) Ein VERZEICHNIS statt einer Datei: existiert, hat eine Groesse, und
    # open(..., "rb") wirft IsADirectoryError. Kein Patch noetig.
    t = D.datei_diagnose(heim)
    assert "nicht zu lesen" in t, \
        "ein Verzeichnis als DB_PATH laesst die Diagnose durchfallen: %s" % t

    # (b) Die Proben selbst: unlesbare Quelle -> leere Liste, keine Ausnahme.
    assert D._proben(heim, 4096) == [], \
        "_proben() wirft, statt leer zurueckzukommen"
    befund = D._inhalt_befund(heim, 4096)
    assert any("nicht lesbar" in z for z in befund), befund

    # (c) Groesse nicht lesbar — der Pfad existiert, aber stat scheitert.
    echt_getsize = _os.path.getsize
    try:
        _os.path.getsize = lambda p: (_ for _ in ()).throw(
            OSError(5, "Input/output error"))
        t = D.datei_diagnose(tls)
        assert "Groesse nicht lesbar" in t, t
    finally:
        _os.path.getsize = echt_getsize

    # (d) Und die Kompressionsprobe darf die Diagnose nicht mitnehmen.
    echt_compress = _zlib.compress
    try:
        _zlib.compress = lambda *a, **k: (_ for _ in ()).throw(
            _zlib.error("out of memory"))
        t = D.datei_diagnose(dump)
        assert "SQL-Dump" in t, \
            "eine gescheiterte Kompressionsprobe reisst die ganze Diagnose " \
            "mit: %s" % t
        assert "Komprimierbar" not in t, t
    finally:
        _zlib.compress = echt_compress

    # ── (10) DIE ZWEI AUFRAEUM-ZWEIGE in db_conn(). Beide sind `pass`, und
    # beide haben einen Grund, der im Kommentar steht — dann sollen sie auch
    # geprueft sein, statt die Ueberdeckungs-Grundlinie zu heben.
    alt_pfad2, alt_wal = D.DB_PATH, dict(D._WAL_INIT)
    try:
        # (a) Der WAL-Versuch faellt bei einer kaputten Datei genauso. Mit
        # zurueckgesetztem Flag laeuft er ueberhaupt erst wieder los.
        D.DB_PATH = tls
        D._WAL_INIT["done"] = False
        try:
            with D.db_conn():
                pass
            raise AssertionError("db_conn() lief auf dem TLS-Blob durch")
        except D.DatenbankUnlesbar:
            pass
        assert D._WAL_INIT["done"] is False, \
            "das WAL-Flag wurde auf einer kaputten Datei gesetzt — dann " \
            "unterbleibt der Versuch spaeter auf der GESUNDEN Datenbank"

        # (b) Und ein close(), das selbst scheitert, darf die Diagnose nicht
        # verschlucken: der Betreiber braucht sie, nicht den close-Fehler.
        import sqlite3 as _s3
        echt_connect = D.sqlite3.connect

        class _Zicke:
            row_factory = None
            def execute(self, *a, **k):
                raise _s3.DatabaseError("file is not a database")
            def close(self):
                raise _s3.ProgrammingError("Cannot operate on a closed database")

        try:
            D.sqlite3.connect = lambda *a, **k: _Zicke()
            try:
                with D.db_conn():
                    pass
                raise AssertionError("db_conn() lief mit der Zicke durch")
            except D.DatenbankUnlesbar as e:
                assert "file is not a database" in str(e), str(e)
        finally:
            D.sqlite3.connect = echt_connect
    finally:
        D.DB_PATH = alt_pfad2
        D._WAL_INIT.clear()
        D._WAL_INIT.update(alt_wal)

    ok("W92: die beiden Aufraeum-Zweige in db_conn sind geprueft")
    ok("W92: die Diagnose haelt auch, wenn das Diagnostizieren scheitert")
    ok("W92: eine unlesbare Datenbank nennt Datei, Inhalt und Abhilfe")
    ok("W92: ueberschriebene Datei und echter Schaden bekommen andere Raete")
    ok("W92: ein Dump hinter fremden Bytes wird erkannt, nicht aufgegeben")
    ok("W92: der Start bricht ab, statt still eine leere Datenbank anzulegen")


def _test_v42_w93_telegram_konflikt_wird_unterschieden():
    """v4.2-W93: ein Telegram-Konflikt, der nicht aufhoert, ist ein Ausfall —
    und sah bis hierher aus wie eine harmlose Neustart-Ueberlappung.

    Im Log vom 18.09. steht sechsmal derselbe zwoelfzeilige Traceback aus
    fremden Bibliotheksrahmen, und dann ist es vorbei (07:23:42 Konflikt,
    07:24:39 wieder HTTP 200). Das war Fall (a): die alte Instanz hielt beim
    Neustart ihren Long-Poll noch. Voellig harmlos.

    Fall (b) sieht im Log WORTGLEICH aus und ist es nicht: laeuft wirklich
    eine zweite Instanz mit demselben BOT_TOKEN, gehen die Updates dorthin
    und dieser Bot bekommt keinen einzigen Telegram-Befehl mehr. Aufnahme,
    Restream und Moderation laufen weiter, es stuerzt nichts ab — also faellt
    es nirgends auf. Dieselbe Klasse wie die stillen `return`s aus W81.

    Unterscheidbar sind die beiden nur an der DAUER.
    """
    from nc import telegramfehler as T

    class Conflict(Exception):
        pass

    class InvalidToken(Exception):
        pass

    class TimedOut(Exception):
        pass

    class NetworkError(Exception):
        pass

    class Forbidden(Exception):
        pass

    class RetryAfter(Exception):
        pass

    class BadRequest(Exception):
        pass

    konflikt = Conflict("Conflict: terminated by other getUpdates request; "
                        "make sure that only one bot instance is running")

    # ── (1) DER FALL VOM 18.09. Erster Konflikt bei t=0, letzter bei t=39,
    # danach Ruhe. Nichts davon darf als zweite Instanz gemeldet werden.
    T.zuruecksetzen()
    for t in (0.0, 6.0, 12.0, 18.0, 27.0, 39.0):
        g, dauer = T.grund(konflikt, t)
        assert g == "konflikt_anlauf", \
            "bei t=%s meldet der echte Neustart-Fall '%s' — der Betreiber " \
            "sucht dann nachts eine zweite Instanz, die es nicht gibt" % (t, g)

    # ── (2) UND DER FALL, DER ES WIRKLICH IST. Derselbe Fehler, nur laenger
    # als die Gnadenfrist. Hier MUSS die Meldung kippen.
    T.zuruecksetzen()
    T.grund(konflikt, 0.0)
    g, dauer = T.grund(konflikt, T.GNADENFRIST_S + 1.0)
    assert g == "konflikt_dauerhaft", \
        "ein Konflikt jenseits der Gnadenfrist bleibt 'harmlos' — genau der " \
        "stille Ausfall, gegen den dieses Modul gebaut ist (bekommen: %s)" % g
    assert dauer >= T.GNADENFRIST_S, dauer

    # ── (3) DIE FOLGE GEHOERT IN DEN TEXT. "Conflict" allein sagt nicht, dass
    # Telegram-Befehle ausfallen — das ist die ganze Nachricht.
    t_dauer = T.text("konflikt_dauerhaft")
    assert "zweite Instanz" in t_dauer, t_dauer
    assert "keine Telegram-Befehle" in t_dauer, \
        "die FOLGE fehlt: %s" % t_dauer
    assert "an die andere Instanz" in t_dauer, \
        "der Text sagt nicht, WOHIN die Updates stattdessen gehen — ohne " \
        "das liest sich der Ausfall wie ein Netzproblem: %s" % t_dauer
    assert "laufen unbeeindruckt weiter" in t_dauer, \
        "der Text sagt nicht, dass Aufnahme und Restream weiterlaufen. " \
        "Genau deshalb faellt der Ausfall sonst nirgends auf: %s" % t_dauer
    assert "pgrep" in t_dauer and "systemctl" in t_dauer, \
        "keine Abhilfe im Text — 'HTTP 403' allein hat schon einmal " \
        "wochenlang niemandem geholfen: %s" % t_dauer
    assert T.ist_fehler("konflikt_dauerhaft"), \
        "der Dauerkonflikt steht auf warning. In einem ERROR-Log erscheint " \
        "ein log.warning NIE — so blieb der Discord-Gateway-Tod monatelang " \
        "unsichtbar (CLAUDE.md)."
    assert not T.ist_fehler("konflikt_anlauf"), \
        "die Neustart-Ueberlappung auf error macht jeden Deploy zum Vorfall " \
        "— Alarm-Muedigkeit ist genauso blind wie Stille"
    # Die Frist selbst ist Teil des Vertrags. Eine Gnadenfrist, die gross
    # genug ist, schaltet die Eskalation faktisch ab, ohne dass eine Zeile
    # Logik dafuer geaendert werden muesste — und kein Vertrag oben faellt,
    # weil sie alle gegen T.GNADENFRIST_S rechnen.
    assert 30.0 <= T.GNADENFRIST_S <= 300.0, \
        "die Gnadenfrist ist aus dem sinnvollen Bereich gelaufen (%s s). " \
        "Zu kurz meldet jeden Neustart als Vorfall, zu lang schaltet die " \
        "Eskalation ab." % T.GNADENFRIST_S
    assert T.STRAEHNE_ENDE_S > T.GNADENFRIST_S, \
        "das Straehnen-Ende liegt unter der Gnadenfrist — dann endet jede " \
        "Straehne, bevor sie eskalieren kann, und der Dauerkonflikt wird nie " \
        "gemeldet"

    # ── (4) ZWEI KONFLIKTE, DIE NICHTS MITEINANDER ZU TUN HABEN. Ohne
    # Straehnen-Ende wuerde ein einzelner neuer Konflikt eine Stunde spaeter
    # sofort als "haelt seit einer Stunde an" gemeldet — und das waere falsch.
    T.zuruecksetzen()
    T.grund(konflikt, 0.0)
    g, dauer = T.grund(konflikt, T.STRAEHNE_ENDE_S + 10.0)
    assert g == "konflikt_anlauf" and dauer == 0.0, \
        "nach langer Ruhe faengt eine NEUE Straehne an, sonst meldet der " \
        "erste Konflikt einer neuen Stoerung eine erfundene Dauer (%s/%s)" \
        % (g, dauer)

    # ── (5) DER WEBHOOK-KONFLIKT hat eine voellig andere Abhilfe und braucht
    # deshalb einen eigenen Schluessel — dieselbe Entscheidung wie bei 403
    # gegen 5xx in nc/resolvergrund.py.
    T.zuruecksetzen()
    g, _ = T.grund(Conflict("can't use getUpdates method while webhook is "
                            "active"), 0.0)
    assert g == "konflikt_webhook", g
    assert "deleteWebhook" in T.text(g), T.text(g)
    assert T.STRAEHNE["seit"] is None, \
        "der Webhook-Fall hat die Konflikt-Straehne angefasst — er ist aber " \
        "keine Ueberlappung, und seine Dauer sagt nichts"

    # ── (6) DIE UEBRIGEN KLASSEN. Klassiert wird ueber den Klassennamen, weil
    # nc/ bot-frei bleibt und die Suite ohne python-telegram-bot laeuft.
    T.zuruecksetzen()
    for exc, erwartet in ((InvalidToken("Invalid token"), "token_ungueltig"),
                          (TimedOut("Timed out"), "zeitueberschreitung"),
                          (NetworkError("httpx.ConnectError"), "netz"),
                          (Forbidden("Forbidden: bot was kicked"), "verboten"),
                          (RetryAfter("Flood control exceeded"), "zu_schnell")):
        g, _ = T.grund(exc, 0.0)
        assert g == erwartet, "%s -> %s (erwartet %s)" % (exc, g, erwartet)
    assert T.ist_fehler("token_ungueltig"), \
        "ein falscher Token heilt nicht von selbst — das gehoert auf error"
    assert not T.ist_fehler("netz"), \
        "jeder Netzhaenger auf error deckt die echten Faelle zu"
    for g_ in ("verboten", "zu_schnell", "zeitueberschreitung", "netz",
               "token_ungueltig", "konflikt_webhook"):
        assert T.text(g_) != g_ and len(T.text(g_)) > 40, \
            "Grund '%s' hat keinen Klartext — dann steht im Log nur der " \
            "Schluessel, und der hilft so wenig wie 'HTTP 403'" % g_

    # ── (7) EIN UNBEKANNTER FEHLER DARF NICHT VERSCHWINDEN, und zwei
    # verschiedene neue duerfen nicht zu einem verschmelzen: sonst schluckt
    # die Drossel den zweiten, weil sich der Grund fuer sie nicht geaendert
    # hat.
    g, _ = T.grund(BadRequest("Bad Request: chat not found"), 0.0)
    assert "BadRequest" in g, \
        "der Klassenname fehlt im Schluessel — ein Sammeltopf 'unbekannt' " \
        "macht zwei Fehlerbilder ununterscheidbar: %s" % g
    assert T.text(g) == g, \
        "ein unbekannter Grund muss sich selbst nennen statt zu verstummen"

    # ── (8) DIE DAUER ALS KLARTEXT. Es geht um "seit zwei Minuten", nicht um
    # 127,4 Sekunden.
    assert T.dauer_text(0) == "0 s" and T.dauer_text(59) == "59 s"
    assert T.dauer_text(130) == "2 min"
    assert T.dauer_text(7300) == "2 h"

    T.zuruecksetzen()
    assert T.STRAEHNE["seit"] is None and T.STRAEHNE["zuletzt"] is None

    # ── (9) UND DIE VERDRAHTUNG. Ohne error_callback greift PTBs eigener
    # default_error_callback, und dann steht wieder der zwoelfzeilige
    # Traceback im Log — das Modul oben waere gebaut und nie aufgerufen.
    b = open("bot.py", encoding="utf-8").read()
    stelle = b.find("await app.updater.start_polling(")
    assert stelle > 0, "start_polling nicht gefunden"
    ruf = rumpf_ab(b, stelle)
    assert "error_callback=_telegram_polling_fehler" in ruf[:400], \
        "start_polling ohne error_callback — PTB schreibt dann weiter seinen " \
        "eigenen Traceback je Vorkommen"
    anlauf = rumpf_ab(b, b.find("async def run_bot("))
    assert "_nc_tgfehler.zuruecksetzen()" in anlauf, \
        "die Konflikt-Straehne wird beim Start nicht geleert — ein alter " \
        "Zaehlerstand meldet den ersten Konflikt sofort als 'seit Stunden'"
    rumpf = rumpf_ab(b, b.find("def _telegram_polling_fehler("))
    assert "_nc_meldetakt.melden(" in rumpf, \
        "ungedrosselt: PTB wiederholt im Sekundentakt, und eine unlesbare " \
        "Warnung ist so gut wie keine"
    # Nicht "kommen log.error und log.warning vor" — der Auffang am Ende der
    # Funktion enthaelt selbst ein log.error, und genau daran ist die
    # Mutationsprobe "Fehlerzweig auf warning gedreht" zunaechst entwischt.
    # Gemessen wird der ZWEIG.
    zweig = rumpf[rumpf.find("ist_fehler(grund):"):]
    zweig = zweig[:zweig.find("    except ")] if "    except " in zweig else zweig
    ja, nein = zweig.split("else:", 1)
    assert "log.error(" in ja and "log.warning(" not in ja, \
        "der Ausfall-Zweig loggt nicht auf error. In einem ERROR-Log " \
        "erscheint ein log.warning NIE: %s" % ja
    assert "log.warning(" in nein and "log.error(" not in nein, \
        "die Neustart-Ueberlappung auf error macht jeden Deploy zum " \
        "Vorfall — Alarm-Muedigkeit ist genauso blind wie Stille: %s" % nein

    ok("W93: die Neustart-Ueberlappung vom 18.09. bleibt eine Warnzeile")
    ok("W93: ein Konflikt jenseits der Gnadenfrist wird zum ERROR")
    ok("W93: der Text nennt Folge (keine Telegram-Befehle) und Abhilfe")
    ok("W93: nach langer Ruhe faengt eine neue Straehne an")
    ok("W93: Webhook-Konflikt und Token-Fehler haben eigene Gruende")
    ok("W93: ein unbekannter Fehler nennt seinen Klassennamen")
    ok("W93: start_polling haengt den eigenen Fehlerkanal ein, gedrosselt")


def _test_v42_w93_deck_nennt_das_wirkliche_schema():
    """v4.2-W93: das Log nannte die Adresse des Decks mit dem falschen Schema.

    Im Log vom 18.09. stehen zwei Zeilen im Abstand von 19 Millisekunden:

        Dashboard-TLS aktiv: https://<host>:8050 (Zertifikat: fullchain.pem)
        Dashboard: http://0.0.0.0:8050  (Auth aktiv)

    Die zweite ist die mit der vollstaendigen Adresse, also die, die man
    kopiert — und sie ist falsch. Wer sie benutzt, spricht HTTP gegen einen
    TLS-Socket und sucht den Fehler im Netz. Es ist derselbe Befund wie bei
    der Bindung in W84 ("die WIRKLICHE Adresse nennen, nicht die
    gewuenschte"), eine Zeile weiter: dort war es der Host, hier das Schema.
    """
    import os as _os
    from nc import webserver as W
    import pruefhilfen as P

    heim = P.verzeichnis()
    cert = _os.path.join(heim, "fullchain.pem")
    key = _os.path.join(heim, "privkey.pem")
    for pfad in (cert, key):
        with open(pfad, "w", encoding="utf-8") as f:
            f.write("-----BEGIN CERTIFICATE-----\n")

    # ── (1) BEIDE DATEIEN DA -> https. Der Fall vom 18.09.
    assert W.schema(cert, key) == "https", \
        "bei aktivem TLS nennt das Log weiter http:// — genau die Adresse, " \
        "die der Betreiber kopiert"
    assert W.tls_lage(cert, key) == ("an", (cert, key), ""), W.tls_lage(cert, key)

    # ── (2) NICHTS GESETZT -> http, und STILL. Der Normalfall hinter dem
    # Tunnel darf keine Zeile erzeugen, sonst warnt das Log bei jedem Start.
    assert W.schema("", "") == "http"
    assert W.tls_lage("", "") == ("aus", None, ""), W.tls_lage("", "")
    assert W.schema("   ", "  ") == "http", "Leerraum ist kein Pfad"
    assert W.tls_lage("  ", " ")[0] == "aus"

    # ── (3) DIE GEFAEHRLICHERE HAELFTE: gesetzt, aber die Datei fehlt.
    # run_flask faellt dann auf HTTP zurueck. Meldete das Log hier https://,
    # waere der Fehler nur umgedreht — und diesmal ohne die TLS-Zeile
    # daneben, die widerspricht.
    fehlt = _os.path.join(heim, "gibtsnicht.pem")
    assert W.schema(cert, fehlt) == "http", \
        "fehlender Schluessel und trotzdem https:// — die Meldung folgt dem " \
        "Wunsch statt dem Weg"
    assert W.schema(fehlt, key) == "http"
    lage, paar, meldung = W.tls_lage(cert, fehlt)
    assert lage == "datei_fehlt" and paar is None, (lage, paar)
    assert fehlt in meldung, \
        "die Meldung nennt die fehlende Datei nicht: %s" % meldung

    # ── (3b) UND DER KONFIGURATIONSFEHLER, DER SONST STILL BLIEBE: nur eine
    # der beiden Variablen gesetzt. Ohne eigene Lage sieht das fuer den
    # Aufrufer aus wie "TLS gar nicht gewollt" — das Deck laeuft dann
    # unverschluesselt, und niemand erfaehrt warum.
    lage, paar, meldung = W.tls_lage(cert, "")
    assert lage == "unvollstaendig" and paar is None, (lage, paar)
    assert "DASHBOARD_TLS_KEY" in meldung, meldung
    assert W.tls_lage("", key)[0] == "unvollstaendig"
    assert "DASHBOARD_TLS_CERT" in W.tls_lage("", key)[2]

    # ── (4) UND DIE VERDRAHTUNG. Nicht per Textsuche: der Vorlaeufer dieses
    # Abschnitts pruefte, ob "_nc_webserver.schema(" im Rumpf vorkommt — und
    # blieb gruen, als die Mutationsprobe das Ergebnis berechnete und dann
    # verwarf ("http://" wieder fest im f-String). Gemessen wird deshalb, was
    # die Funktion ZURUECKGIBT. Sie steht auf Modul-Ebene und haengt nur an
    # vier Namen, also laesst sie sich mit Attrappen ausfuehren, ohne bot.py
    # zu importieren (das braucht telegram und discord).
    import ast as _ast
    b = open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(b)
    fn = [n for n in baum.body
          if isinstance(n, _ast.FunctionDef) and n.name == "_dashboard_adresse"]
    assert fn, \
        "_dashboard_adresse ist weg — dann baut main() die Adresse wieder " \
        "selbst, und genau dort stand das falsche Schema"

    # Die Umgebung wird geliehen, nicht uebernommen: was dieser Vertrag
    # setzt, steht am Ende wieder so da wie vorher. Eine Suite, die
    # os.environ liegen laesst, faerbt jeden spaeteren Vertrag im selben
    # Prozess ein — und pytest faehrt sie seit W86 einzeln UND am Stueck.
    _gemerkt = {k: _os.environ.get(k) for k in
                ("DASHBOARD_TLS_CERT", "DASHBOARD_TLS_KEY",
                 "DASHBOARD_OFFEN_ERLAUBEN")}

    def _zuruecksetzen():
        for k, v in _gemerkt.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v

    def _adresse(web_host, token, pin, cert_, key_):
        raum = {"_nc_webserver": W, "os": _os, "WEB_HOST": web_host,
                "DASHBOARD_TOKEN": token, "DASHBOARD_PIN": pin,
                "DASHBOARD_PORT": 8050}
        _os.environ["DASHBOARD_TLS_CERT"] = cert_
        _os.environ["DASHBOARD_TLS_KEY"] = key_
        exec(compile(_ast.Module(body=fn, type_ignores=[]), "bot.py",
                     "exec"), raum)
        return raum["_dashboard_adresse"]()

    # Der Fall vom 18.09.: TLS an, Deck offen gebunden, Token gesetzt.
    zeile = _adresse("0.0.0.0", "geheim", "", cert, key)
    assert zeile.startswith("https://0.0.0.0:8050"), \
        "die Adresszeile ist wieder falsch — genau der Befund vom 18.09.: " \
        "%s" % zeile
    assert "Auth aktiv" in zeile, zeile

    # Ohne TLS bleibt es http.
    zeile = _adresse("0.0.0.0", "geheim", "", "", "")
    assert zeile.startswith("http://0.0.0.0:8050"), zeile

    # Und der Host muss der WIRKLICHE sein (W84): ohne Token und ohne PIN
    # faellt die Bindung auf Loopback zurueck — stuende hier der Wunsch aus
    # der .env, suchte der Betreiber den Fehler im Netz.
    _os.environ.pop("DASHBOARD_OFFEN_ERLAUBEN", None)
    try:
        zeile = _adresse("0.0.0.0", "", "", cert, key)
    finally:
        _zuruecksetzen()
    assert zeile.startswith("https://127.0.0.1:8050"), \
        "die Adresszeile nennt den Wunsch-Host statt der wirklichen " \
        "Bindung (W84): %s" % zeile
    assert "KEIN Auth" in zeile, zeile
    assert _os.environ.get("DASHBOARD_TLS_CERT") == _gemerkt["DASHBOARD_TLS_CERT"], \
        "der Vertrag laesst DASHBOARD_TLS_CERT in der Umgebung liegen"

    # ── (4b) UND main() DARF DIE ZEILE NICHT EIN ZWEITES MAL SELBST BAUEN.
    # rumpf_ab schneidet an "\ndef " — main() ist ein `async def` und wird
    # davon nicht getroffen, also direkt am Namen ansetzen.
    mstelle = b.find("async def main():")
    assert mstelle > 0, "async def main() nicht gefunden"
    m = b[mstelle:b.find("\nasync def ", mstelle + 1)]
    assert "_dashboard_adresse()" in m, \
        "main() nennt die Adresse an dem benannten Schritt vorbei"
    assert 'f"Dashboard: ' not in m, \
        "main() baut die Adresszeile wieder selbst zusammen"

    # ── (5) run_flask darf die TLS-Frage weder selbst rechnen noch die
    # Meldung verschlucken. Gemessen wird der ZWEIG, nicht das blosse
    # Vorkommen von "log.warning" — run_flask loggt an mehreren Stellen, und
    # daran ist die Mutationsprobe zunaechst entwischt.
    rf = rumpf_ab(b, b.find("def run_flask("))
    assert "_nc_webserver.tls_lage(" in rf, \
        "run_flask rechnet die TLS-Frage wieder selbst — zwei Rechnungen " \
        "fuer dieselbe Frage sind genau, wie die Meldungen auseinanderliefen"
    assert "os.path.exists(_tls_cert)" not in rf, \
        "die Dateipruefung steht wieder in bot.py"
    zweig = rf[rf.find("elif _tls_meldung:"):]
    assert zweig.startswith("elif _tls_meldung:"), \
        "der Zweig fuer die TLS-Meldung fehlt: das Deck laeuft dann " \
        "unverschluesselt, ohne dass es jemand erfaehrt"
    rumpf_zweig = []
    for zeile_ in zweig.split("\n")[1:]:
        if zeile_.strip() and not zeile_.startswith("        "):
            break                       # zurueck auf Funktionsebene
        rumpf_zweig.append(zeile_)
    rumpf_zweig = "\n".join(rumpf_zweig)
    assert "log.warning" in rumpf_zweig, \
        "run_flask verschluckt den Konfigurationsfehler — das Deck laeuft " \
        "dann unverschluesselt, ohne dass es jemand erfaehrt: %s" % rumpf_zweig

    ok("W93: bei aktivem TLS nennt das Log https://, nicht http://")
    ok("W93: gesetzter, aber ins Leere zeigender Pfad bleibt http und meldet")
    ok("W93: nur eine der beiden TLS-Variablen gesetzt wird nicht verschluckt")
    ok("W93: _dashboard_adresse nennt wirkliches Schema, Host und Schranke")
    ok("W93: run_flask rechnet die TLS-Frage nicht ein zweites Mal selbst")

def _test_v42_w94_kopfschaden_wird_erkannt_und_geheilt():
    """v4.2-W94: die Diagnose riet bei einer beschaedigten Datenbank falsch —
    und nannte fuer den haeufigsten Schaden ueberhaupt keinen Weg.

    Am 18.09. lag das im Arbeitsverzeichnis:

        Groesse: 401408 Bytes (0.4 MB)
        Erste Bytes: 17 03 03 00 2d 0c fc ba 34 d6 d6 33 52 fb 55 0a

    W92 hat korrekt abgebrochen und korrekt gewarnt, nichts zu loeschen. Nur
    half es dann nicht weiter: "STRUKTURIERTE Daten, aufgeben waere
    verfrueht" — und kein Weg dahin. Dieselbe Klasse wie ein blankes
    "HTTP 403", eine Ebene tiefer.

    Die Zahl im Log war die Antwort: 401408 = 4096 x 98, also exakt 98
    SQLite-Seiten. Der TLS-Record ist 5 Bytes Kopf + 0x2d Nutzlast = 50
    Bytes. Zerstoert war der 100-Byte-Dateikopf, nicht die Datenbank.

    UND DIE ERSTE FASSUNG RIET AKTIV FALSCH: sie fand `CREATE TABLE`, hielt
    die Datei fuer einen SQL-Dump und empfahl `sqlite3 neu.db < datei`. Das
    KANN nicht laufen — es ist eine Binaerdatei. `CREATE TABLE` steht in
    JEDER SQLite-Datei, weil das Schema woertlich in `sqlite_master` liegt.
    """
    import os as _os
    import sqlite3 as _sq3
    import random as _rnd
    import subprocess as _sp
    import sys as _sys
    from nc import dbwrap as D
    import pruefhilfen as P

    heim = P.verzeichnis()

    def _datenbank(name, zeilen=3000):
        pfad = _os.path.join(heim, name)
        con = _sq3.connect(pfad)
        con.execute("CREATE TABLE trackings (id INTEGER PRIMARY KEY, username TEXT)")
        con.execute("CREATE TABLE recordings (id INTEGER PRIMARY KEY, pfad TEXT)")
        for i in range(zeilen):
            con.execute("INSERT INTO trackings (username) VALUES (?)", ("@s_%d" % i,))
            con.execute("INSERT INTO recordings (pfad) VALUES (?)", ("/rec/%d.mp4" % i,))
        con.commit()
        con.close()
        return pfad

    def _kopf_zerstoeren(pfad, bytes_=50):
        # Genau der Schaden aus dem Log: TLS-Record-Kopf plus Nutzlast, an
        # Offset 0, OHNE die Datei zu kuerzen.
        _rnd.seed(3)
        roh = bytes.fromhex("170303002d") + bytes(
            _rnd.randrange(256) for _ in range(bytes_ - 5))
        with open(pfad, "r+b") as f:
            f.write(roh)

    # ── (1) DAS UNTERSCHEIDUNGSMERKMAL, an dem die erste Fassung scheiterte.
    # Nachgemessen: eine echte SQLite-Datei enthaelt `CREATE TABLE` (aus
    # sqlite_master), aber NULL `INSERT INTO`. Ein Dump enthaelt beides.
    heil = _datenbank("heil.db")
    roh_db = open(heil, "rb").read()
    assert b"CREATE TABLE" in roh_db, \
        "Annahme gebrochen: das Schema steht nicht mehr woertlich in der Datei"
    assert b"INSERT INTO" not in roh_db, \
        "eine Datenbankdatei enthaelt INSERT INTO — dann taugt das " \
        "Unterscheidungsmerkmal nicht mehr und die Diagnose raet wieder falsch"

    # ── (2) DIE DIAGNOSE DARF NICHT MEHR ZUM DUMP-WEG RATEN.
    kaputt = _datenbank("kaputt.db")
    _kopf_zerstoeren(kaputt)
    text = D.datei_diagnose(kaputt)
    assert "sqlite3 neu.db <" not in text, \
        "die beschaedigte Datenbank wird weiter als SQL-Dump ausgegeben. " \
        "Der Rat kann nicht laufen und kostet den Betreiber eine Stunde: %s" % text
    assert "Vielfaches" in text and "KOPF" in text, \
        "der Kopfschaden wird nicht benannt: %s" % text
    assert "tools/dbkopf.py" in text, \
        "kein Weg genannt — genau der Befund vom 18.09.: richtig und nutzlos"
    assert "fasst die Eingabedatei nicht an" in text, \
        "ohne diese Zusage traut sich niemand, das Werkzeug auf die einzige " \
        "verbliebene Kopie loszulassen"

    # ── (3) DER FALL VOM 17.09. MUSS WEITER GEHEN. Ein echter Dump hinter
    # fremdem Vorlauf bleibt ein Dump — sonst waere W92 zurueckgedreht.
    dump = _os.path.join(heim, "dump.db")
    with open(dump, "wb") as f:
        f.write(bytes.fromhex("170303002d0cfcba"))
        f.write(b"\x00" * (200 * 1024))
        f.write(b"BEGIN TRANSACTION;\nCREATE TABLE recordings (id INT);\n")
        for i in range(30000):
            f.write(b"INSERT INTO recordings VALUES(%d);\n" % i)
    t_dump = D.datei_diagnose(dump)
    assert "SQL-Dump" in t_dump and "sqlite3 neu.db <" in t_dump, \
        "der echte Dump wird nicht mehr erkannt — W92 waere zurueckgedreht"
    assert "dbkopf" not in t_dump, \
        "ein Dump wird als Kopfschaden ausgegeben: %s" % t_dump

    # ── (4) UND ZUFALLSDATEN BLEIBEN EHRLICH VERLOREN. Ein Werkzeug, das
    # auch hier Rettung verspricht, waere wieder ein falscher Rat.
    zufall = _os.path.join(heim, "rnd.db")
    with open(zufall, "wb") as f:
        f.write(_os.urandom(200000))
    t_rnd = D.datei_diagnose(zufall)
    assert "verschluesselte oder zufaellige" in t_rnd, t_rnd
    assert "dbkopf" not in t_rnd and "verfrueht" not in t_rnd, \
        "Zufallsdaten werden als rettbar dargestellt: %s" % t_rnd

    # ── (5) DAS WERKZEUG RETTET WIRKLICH. Nicht "es laeuft durch", sondern:
    # alle Zeilen sind wieder da.
    ziel = _os.path.join(heim, "gerettet.db")
    r = _sp.run([_sys.executable, "tools/dbkopf.py", kaputt, "-o", ziel],
                capture_output=True, text=True)
    assert r.returncode == 0, "dbkopf scheitert: %s%s" % (r.stdout, r.stderr)
    con = _sq3.connect(ziel)
    for tab in ("trackings", "recordings"):
        n = con.execute("SELECT count(*) FROM %s" % tab).fetchone()[0]
        assert n == 3000, "%s: nur %s von 3000 Zeilen gerettet" % (tab, n)
    assert con.execute("PRAGMA integrity_check").fetchone()[0] == "ok"
    con.close()

    # ── (6) UND ES FASST DIE EINGABE NICHT AN. Das ist keine Kosmetik: es
    # laeuft auf der einzigen verbliebenen Kopie der Produktionsdaten.
    assert open(kaputt, "rb").read(5) == bytes.fromhex("170303002d"), \
        "dbkopf hat die Eingabedatei veraendert"

    # ── (7) DAS ENTSCHEIDENDE KRITERIUM IST integrity_check, NICHT "keine
    # Ausnahme". Gemessen: mit 8192 statt 4096 kamen 308 von 2000 Zeilen
    # heraus, ohne dass etwas warf. Waere das das Kriterium, gaebe das
    # Werkzeug eine zu 85 % leere Datenbank als Rettung aus.
    import importlib.util as _ilu
    import tempfile as _tf
    _spec = _ilu.spec_from_file_location("dbkopf", "tools/dbkopf.py")
    _dbk = _ilu.module_from_spec(_spec)
    _spec.loader.exec_module(_dbk)
    # Die Groesse muss durch 8192 teilbar sein, sonst ist 8192 gar kein
    # Kandidat und die Probe zielt ins Leere — genau daran ist die
    # Mutationsprobe "integrity_check nicht mehr das Kriterium" zuerst
    # entwischt: bei 3000 Zeilen sind es 53248 Bytes, und 53248 % 8192 != 0.
    zwilling = _os.path.join(heim, "zwilling.db")
    _con = _sq3.connect(zwilling)
    _con.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, u TEXT)")
    _n = 0
    # Solange fuellen, bis die Groesse auf der 8192-Grenze liegt. Eine feste
    # Zeilenzahl zu raten geht schief: 3000 Zeilen ergaben 53248 Bytes, und
    # 53248 % 8192 != 0.
    while _n < 20000:
        for _ in range(500):
            _con.execute("INSERT INTO t (u) VALUES (?)", ("@s_%d" % _n,))
            _n += 1
        _con.commit()
        if _os.path.getsize(zwilling) % 8192 == 0:
            break
    _con.close()
    assert _os.path.getsize(zwilling) % 8192 == 0, \
        "die Attrappe liegt nicht auf der 8192-Grenze — dann ist 8192 gar " \
        "kein Kandidat und (7) prueft nichts"
    _kopf_zerstoeren(zwilling)
    with open(zwilling, "rb") as f:
        _roh = f.read()
    with _tf.TemporaryDirectory() as _tmp:
        ok_falsch, befund_f, _t = _dbk._pruefe(_dbk.kopf_bauen(_roh, 8192), _tmp)
        assert not ok_falsch, \
            "eine falsche Seitengroesse wird als Rettung akzeptiert — genau " \
            "so gehen Daten still verloren"
        assert "database" in befund_f or "page" in befund_f.lower(), \
            "abgelehnt wurde sie, aber nicht von integrity_check (%s) — dann " \
            "haengt das Werkzeug am Ausbleiben einer Ausnahme" % befund_f
        ok_richtig, befund, _t2 = _dbk._pruefe(_dbk.kopf_bauen(_roh, 4096), _tmp)
        assert ok_richtig and befund == "ok", befund

        # Und die Seitenzahl im Kopf darf NICHT tragen: Byte 92-95 steht auf
        # Null, damit SQLite sie aus der Dateigroesse ableitet. Vorher stimmte
        # das nur zufaellig, weil dort noch der alte Wert stand.
        gefaelscht = bytearray(_dbk.kopf_bauen(_roh, 4096))
        gefaelscht[28:32] = (1).to_bytes(4, "big")
        ok_gef, _bg, _tg = _dbk._pruefe(bytes(gefaelscht), _tmp)
        assert ok_gef, \
            "die Rettung haengt an der Seitenzahl im Kopf. Die ist beim " \
            "Schaden mit zerstoert worden — dann rettet das Werkzeug nur " \
            "Dateien, deren Kopf noch da ist, also gar keine."

    # ── (8) UND DIE BEIDEN ABLEHNUNGEN. Ein Werkzeug, das auf allem etwas
    # tut, ist gefaehrlicher als keines.
    r_heil = _sp.run([_sys.executable, "tools/dbkopf.py", heil],
                     capture_output=True, text=True)
    assert r_heil.returncode != 0 and "INTAKT" in r_heil.stdout, \
        "dbkopf bastelt an einer gesunden Datei: %s" % r_heil.stdout
    schief = _os.path.join(heim, "schief.db")
    with open(schief, "wb") as f:
        f.write(_os.urandom(4096 * 3 + 17))     # durch keine Seitengroesse teilbar
    r_schief = _sp.run([_sys.executable, "tools/dbkopf.py", schief],
                       capture_output=True, text=True)
    assert r_schief.returncode != 0, "dbkopf meldet Erfolg auf Muell"
    assert "ersetzt, nicht nur am Anfang" in r_schief.stdout, \
        "die Ablehnung sagt nicht, WAS sie bedeutet. 'Geht nicht' allein " \
        "laesst offen, ob die Datei ersetzt oder nur angeschnitten wurde — " \
        "und davon haengt ab, wo der Betreiber als naechstes sucht: %s" \
        % r_schief.stdout

    ok("W94: eine Datenbankdatei hat CREATE TABLE, aber kein INSERT INTO")
    ok("W94: der Kopfschaden wird benannt statt als SQL-Dump fehlgedeutet")
    ok("W94: die Diagnose nennt einen Weg (tools/dbkopf.py), nicht nur Trost")
    ok("W94: der echte Dump aus W92 wird weiter erkannt")
    ok("W94: Zufallsdaten bleiben ehrlich verloren")
    ok("W94: dbkopf rettet alle Zeilen und laesst die Eingabe unberuehrt")
    ok("W94: integrity_check entscheidet, nicht das Ausbleiben einer Ausnahme")
    ok("W94: dbkopf lehnt gesunde und nicht-seitenweise Dateien ab")


def _test_v42_w95_systemdump_gehoert_nicht_ins_laufende_deck():
    """v4.2-W95: der Import im Deck spielte einen Backup-Dump HALB ein.

    Der Betreiber am 18.09., waehrend seine Datenbank unlesbar war:

        "Über die Backup Funktion im dashboard lassen sich keine SQL Dateien
         importieren da sämtliche Tabellen schon existieren."

    Es sind zwei Formate, die nie gegeneinander gehalten wurden:

        nc/dbexport.py    Kopf `-- NIGHTCRAWLER-DB-EXPORT`, NUR Daten.
        _system_backup()  sqlite3 .iterdump(), Schema UND Daten.

    Die Sicherung schreibt also genau das, was der Importer nicht lesen kann.
    Und er lehnte nicht ab, sondern lief halb durch — gemessen vor der
    Behebung: "ok: False | Statements: 9 | angewandt: 7". Die CREATE TABLE
    fielen, die INSERT liefen, und db_conn committete beim sauberen
    Verlassen. Auf einer gesunden Datenbank ist das ein Datenschaden: der
    Bestand ist danach weder alt noch neu.
    """
    import os as _os
    import sqlite3 as _sq3
    import subprocess as _sp
    import sys as _sys
    import tarfile as _tf
    from nc import dbwrap as D, dbexport as X
    import pruefhilfen as P

    heim = P.verzeichnis()
    alt_pfad, alt_backend = D.DB_PATH, D.DB_BACKEND

    def _db(name, zeilen, tabellen=("trackings", "recordings")):
        pfad = _os.path.join(heim, name)
        con = _sq3.connect(pfad)
        for tab in tabellen:
            con.execute("CREATE TABLE %s (id INTEGER PRIMARY KEY, t TEXT)" % tab)
        for i in range(zeilen):
            con.execute("INSERT INTO %s (t) VALUES (?)" % tabellen[0], ("z_%d" % i,))
        con.commit()
        return con, pfad

    try:
        # Der laufende Bestand: Schema steht, Daten drin.
        lauf_con, lauf = _db("laufend.db", 3)
        lauf_con.close()
        # Die Sicherung: derselbe Aufbau, andere Daten.
        src_con, _ = _db("alt.db", 5)
        dump = "\n".join(src_con.iterdump())
        src_con.close()

        D.configure_db(db_path=lauf, backend="sqlite")

        # ── (1) DER SYSTEMDUMP WIRD ABGELEHNT, BEVOR ETWAS GESCHRIEBEN WIRD.
        rep = X.db_import_sql(dump, expect_dialect="sqlite")
        assert not rep["ok"], "der Systemdump laeuft weiter durch"
        assert rep["applied"] == 0, \
            "es wurden %s Statements angewandt — der Import schreibt weiter " \
            "teilweise in den laufenden Bestand" % rep["applied"]
        fehler = " ".join(rep["errors"])
        assert "Systemarchiv" in fehler, \
            "die Meldung sagt nicht, WAS fuer eine Datei das ist: %s" % fehler
        assert "tools/dbwiederher.py" in fehler, \
            "kein Weg genannt. 'table already exists' 42-mal ist richtig und " \
            "nutzlos — genau der Befund, der diese Welle ausgeloest hat"
        assert "LEERE" in fehler, \
            "es fehlt der Grund: ein Dump mit Schema gehoert in eine leere " \
            "Datenbank"

        # Und der Bestand ist unberuehrt.
        con = _sq3.connect(lauf)
        assert con.execute("SELECT count(*) FROM trackings").fetchone()[0] == 3, \
            "der laufende Bestand wurde angefasst"
        con.close()

        # ── (2) EIN REGULAERER EXPORT MUSS WEITER DURCHGEHEN. Ein Riegel, der
        # auch den Normalfall sperrt, waere die Funktion abgeschaltet.
        gut = (X.HEADER_MARK + "\n-- Ziel-Dialekt: sqlite\n"
               "INSERT INTO recordings (id, t) VALUES (1, 'a');\n")
        rep2 = X.db_import_sql(gut, expect_dialect="sqlite")
        assert rep2["ok"] and rep2["applied"] == 1, (rep2["ok"], rep2["errors"])

        # ── (2b) UND EINE KOPFLOSE, REINE DATENDATEI IST KEIN SYSTEMDUMP.
        # Der Riegel haengt an ZWEI Bedingungen (kein Header UND Schema-DDL).
        # Nur die erste zu pruefen liesse offen, ob die zweite ueberhaupt
        # etwas tut — genau daran ist die Mutationsprobe "_ist_systemdump
        # liefert immer True" zuerst entwischt.
        kopflos = "INSERT INTO recordings (id, t) VALUES (7, 'g');\n"
        rep2b = X.db_import_sql(kopflos, expect_dialect="sqlite")
        assert "Systemarchiv" not in " ".join(rep2b["errors"]), \
            "eine kopflose Datendatei wird als Systemdump abgelehnt — dann " \
            "sperrt der Riegel den Normalfall mit: %s" % rep2b["errors"]
        assert rep2b["ok"] and rep2b["applied"] == 1, rep2b["errors"]

        # ── (3) ALLES ODER NICHTS. Faellt ein Statement, darf KEINES bleiben —
        # db_conn committet beim sauberen Verlassen, und genau daran wurde
        # bisher die halbe Einspielung festgeschrieben.
        con = _sq3.connect(lauf)
        vorher = con.execute("SELECT count(*) FROM recordings").fetchone()[0]
        con.close()
        halb = (X.HEADER_MARK + "\n-- Ziel-Dialekt: sqlite\n"
                "INSERT INTO recordings (id, t) VALUES (2, 'b');\n"
                "INSERT INTO gibtsnicht (x) VALUES (1);\n")
        rep3 = X.db_import_sql(halb, expect_dialect="sqlite")
        con = _sq3.connect(lauf)
        nachher = con.execute("SELECT count(*) FROM recordings").fetchone()[0]
        con.close()
        assert not rep3["ok"]
        assert nachher == vorher, \
            "nach einem Teilfehler stehen %d statt %d Zeilen — es wurde " \
            "teilweise eingespielt" % (nachher, vorher)
        assert rep3["applied"] == 0, rep3["applied"]
        assert "unveraendert" in " ".join(rep3["errors"]), \
            "der Bericht sagt nicht, dass nichts uebernommen wurde"
    finally:
        D.configure_db(db_path=alt_pfad, backend=alt_backend)

    # ── (4) UND DER WEG, DEN DIE MELDUNG NENNT, MUSS AUCH FUNKTIONIEREN.
    # Ein Verweis auf ein Werkzeug, das die Datei nicht frisst, waere
    # derselbe Fehler eine Ebene weiter.
    stempel = "20260918_0400"
    sqldatei = _os.path.join(heim, "tiktok_bot_%s.sql" % stempel)
    with open(sqldatei, "w", encoding="utf-8") as f:
        f.write(dump)
    # Das echte Archiv traegt AUCH brain_<stempel>.sql unter db/. Ohne die
    # Datei hier waere der Filter, der sie aussortiert, nie geprueft — und
    # `brain` steht alphabetisch VOR `tiktok_bot`, also entschiede sonst der
    # Zufall der Sortierung, welche Datei eingespielt wird.
    braindatei = _os.path.join(heim, "brain_%s.sql" % stempel)
    with open(braindatei, "w", encoding="utf-8") as f:
        f.write("BEGIN TRANSACTION;\nCREATE TABLE b (i INT);\n"
                "INSERT INTO b VALUES (1);\nCOMMIT;\n")
    archiv = _os.path.join(heim, "nightcrawler_sys_%s.tar.gz" % stempel)
    with _tf.open(archiv, "w:gz") as tar:
        tar.add(sqldatei, arcname="db/%s" % _os.path.basename(sqldatei))
        tar.add(braindatei, arcname="db/%s" % _os.path.basename(braindatei))
        # Und eine Datei, die alphabetisch HINTER tiktok_bot_ liegt. Ohne sie
        # entschiede die Sortierung zufaellig richtig, und die gezielte
        # Auswahl waere ungeprueft.
        tar.add(braindatei, arcname="db/zusatz_%s.sql" % stempel)
    ziel = _os.path.join(heim, "wiederher.db")
    r = _sp.run([_sys.executable, "tools/dbwiederher.py", archiv, "-o", ziel],
                capture_output=True, text=True)
    assert r.returncode == 0, "dbwiederher scheitert am Archiv: %s%s" % (r.stdout, r.stderr)
    con = _sq3.connect(ziel)
    assert con.execute("SELECT count(*) FROM trackings").fetchone()[0] == 5, \
        "die Zeilen aus der Sicherung sind nicht angekommen"
    assert con.execute("PRAGMA integrity_check").fetchone()[0] == "ok"
    con.close()

    # ── (5) UND ES UEBERSCHREIBT NICHTS. Das Ziel koennte die laufende
    # Datenbank sein — dieselbe Regel wie bei dbkopf (W94) und W91.
    r2 = _sp.run([_sys.executable, "tools/dbwiederher.py", archiv, "-o", ziel],
                 capture_output=True, text=True)
    assert r2.returncode != 0 and "ueberschreibe nichts" in r2.stdout, \
        "dbwiederher ueberschreibt ein vorhandenes Ziel: %s" % r2.stdout

    # ── (6) MUELL WIRD ABGELEHNT, UND ES BLEIBT KEINE HALBE DATEI LIEGEN.
    muell = _os.path.join(heim, "muell.sql")
    with open(muell, "w", encoding="utf-8") as f:
        f.write("hallo welt\n")
    mziel = _os.path.join(heim, "muell.db")
    r3 = _sp.run([_sys.executable, "tools/dbwiederher.py", muell, "-o", mziel],
                 capture_output=True, text=True)
    assert r3.returncode != 0, "Muell wird als Sicherung akzeptiert"
    assert "nicht nach einem Systemarchiv-Dump" in r3.stdout, \
        "die Ablehnung sagt nicht, WAS fehlt — dann sucht der Betreiber den " \
        "Fehler in der Sicherung statt in der Datei, die er erwischt hat: %s" \
        % r3.stdout
    assert not _os.path.exists(mziel), \
        "eine halb gebaute Datei bleibt liegen und steht beim naechsten " \
        "Versuch als 'gibt es schon' im Weg"

    # ── (6b) UND DER FALL, DER DIE AUFRAEUMZEILE ERST NOETIG MACHT: eine
    # Datei, die alle Marken traegt und trotzdem beim Einspielen faellt.
    # Bei blossem Muell kommt es nie zum Verbindungsaufbau, also entstuende
    # auch keine Datei — daran ist die Probe "laesst halbe Datei liegen"
    # zuerst entwischt.
    kaputt_sql = _os.path.join(heim, "kaputt.sql")
    with open(kaputt_sql, "w", encoding="utf-8") as f:
        f.write("BEGIN TRANSACTION;\nCREATE TABLE a (i INT);\n"
                "INSERT INTO a VALUES (1);\nCREATE TABLE ;;; kaputt\n")
    kziel = _os.path.join(heim, "kaputt.db")
    r4 = _sp.run([_sys.executable, "tools/dbwiederher.py", kaputt_sql, "-o", kziel],
                 capture_output=True, text=True)
    assert r4.returncode != 0, "ein kaputter Dump wird als Erfolg gemeldet"
    assert not _os.path.exists(kziel), \
        "die halb gebaute Datei bleibt liegen: %s" % r4.stdout

    ok("W95: der Systemdump wird abgelehnt, bevor etwas geschrieben wird")
    ok("W95: die Meldung nennt Format, Grund und den Weg (dbwiederher)")
    ok("W95: ein regulaerer NIGHTCRAWLER-DB-EXPORT geht weiter durch")
    ok("W95: nach einem Teilfehler bleibt der Bestand unveraendert")
    ok("W95: dbwiederher baut aus dem tar.gz eine geprueft heile Datenbank")
    ok("W95: dbwiederher ueberschreibt nichts und laesst nichts Halbes liegen")


def _test_v42_w96_wiederherstellung_nimmt_das_wal_mit():
    """v4.2-W96: ein Tausch ohne -wal haette die Wiederherstellung LAUTLOS
    verschluckt.

    Der Betreiber wollte den Weg ueber das Deck: "Ich starte mit einer
    leeren Datenbank klar startet der bot... Also los jetzt". Dafuer muss
    die geprüfte Datei an die Stelle der laufenden — und genau da liegt die
    Falle.

    SQLite laeuft hier im WAL-Modus (nc/dbwrap setzt journal_mode=WAL).
    Wird nur die Hauptdatei ersetzt, spielt SQLite das ALTE -wal auf die
    neue Datei. Gemessen, bevor dieses Modul existierte:

        Hauptdatei getauscht, -wal liegengelassen
          gelesen:   [('@leer_bestand',)]     <- die ALTEN Daten
          integrity: ok

    Kein Fehler, keine Warnung, eine gesunde Datenbank mit falschem Inhalt.
    Der Betreiber haette neu gestartet und seine Sicherung waere weg — ohne
    eine einzige Zeile im Log. Das ist die gefaehrlichste Form eines
    Fehlers, die dieses Projekt kennt.
    """
    import os as _os
    import sqlite3 as _sq3
    import tarfile as _tf
    from nc import dbrestore as R
    import pruefhilfen as P

    heim = P.verzeichnis()

    def _mit_zeilen(pfad, werte, wal=False):
        con = _sq3.connect(pfad)
        if wal:
            con.execute("PRAGMA journal_mode=WAL")
        con.execute("CREATE TABLE trackings (id INTEGER PRIMARY KEY, u TEXT)")
        for w in werte:
            con.execute("INSERT INTO trackings (u) VALUES (?)", (w,))
        con.commit()
        return con

    # ── (1) DIE WAL-FALLE. Laufende Datenbank im WAL-Modus, danebengelegte
    # Sicherung, Tausch — und hinterher MUSS die Sicherung gelesen werden.
    live = _os.path.join(heim, "tiktok_bot.db")
    # Die Verbindung bleibt OFFEN. Das ist keine Schikane, sondern die echte
    # Lage: die Deck-Route laeuft IM Bot, und der haelt die Datenbank offen —
    # genau dann existiert das -wal. Ein sauberes close() raeumt es selbst
    # weg, und dann prueft dieser Vertrag die Falle gar nicht. Daran ist die
    # erste Fassung sofort gescheitert.
    con = _mit_zeilen(live, ["@leer_bestand"], wal=True)
    assert _os.path.exists(live + "-wal"), \
        "ohne -wal prueft dieser Vertrag die Falle gar nicht"

    neu_db = _os.path.join(heim, "wiederhergestellt.db")
    _mit_zeilen(neu_db, ["@aus_sicherung_%d" % i for i in range(3)]).close()

    ok_, meldung, weggeraeumt = R.einsetzen(live, neu_db)
    assert ok_, meldung
    con.close()                      # der Bot startet neu
    con = _sq3.connect(live)
    gelesen = [r[0] for r in con.execute("SELECT u FROM trackings")]
    con.close()
    assert gelesen == ["@aus_sicherung_0", "@aus_sicherung_1", "@aus_sicherung_2"], \
        "nach dem Tausch stehen die ALTEN Daten da (%s) — das -wal wurde " \
        "nicht mitgenommen, und SQLite hat es auf die neue Datei gespielt. " \
        "Genau das passiert lautlos, mit integrity_check ok." % gelesen

    # ── (2) UND DER VORIGE STAND IST NICHT WEG, SONDERN DANEBEN. Ein
    # Tausch, der das Alte loescht, ist kein Tausch, sondern ein Sprung.
    assert weggeraeumt, "nichts wurde zur Seite gelegt"
    assert any(w.endswith(".db.vor_wiederherstellung_" + w.rsplit("_", 1)[-1])
               or "vor_wiederherstellung" in w for w in weggeraeumt), weggeraeumt
    assert any("-wal" in w for w in weggeraeumt), \
        "das -wal wurde nicht zur Seite gelegt: %s" % weggeraeumt
    for w in weggeraeumt:
        assert _os.path.exists(w), "weggeraeumte Datei fehlt: %s" % w

    # ── (3) DIE MELDUNG MUSS DEN NEUSTART VERLANGEN. Der laufende Prozess
    # haelt die alte Datei am inode fest und schreibt weiter hinein —
    # gemessen: eine danach eingefuegte Zeile ist nach dem Neustart weg.
    # Das laesst sich nicht wegprogrammieren, nur sagen.
    assert "NEU STARTEN" in meldung and "inode" in meldung, \
        "die Meldung verschweigt, dass der Neustart sofort folgen muss: %s" % meldung

    # ── (4) EIN FEHLSCHLAG DARF NICHTS HALB VERSCHOBEN ZURUECKLASSEN.
    live2 = _os.path.join(heim, "zweite.db")
    con2 = _mit_zeilen(live2, ["@bestand"], wal=True)
    vorher = sorted(f for f in _os.listdir(heim) if f.startswith("zweite.db"))
    ok2, meldung2, _w = R.einsetzen(live2, _os.path.join(heim, "gibtsnicht.db"))
    assert not ok2 and "gibt es nicht" in meldung2, meldung2
    # VOR dem close vergleichen: close() raeumt -wal/-shm selbst weg und
    # wuerde einen Unterschied vortaeuschen, den nicht einsetzen() gemacht hat.
    nachher = sorted(f for f in _os.listdir(heim) if f.startswith("zweite.db"))
    con2.close()
    assert vorher == nachher, \
        "nach dem Fehlschlag liegt der Bestand anders da: %s -> %s" % (vorher, nachher)

    # ── (4b) UND DER FALL, DER DAS ZURUECKDREHEN ERST NOETIG MACHT: der
    # Fehlschlag MITTEN in der Reihe, wenn die Hauptdatei schon zur Seite
    # liegt. (4) oben bricht vorher ab und erreicht die Rueckroll-Schleife
    # gar nicht — genau daran ist die Mutationsprobe zuerst entwischt.
    # Gestellt wird die Falle mit einem VERZEICHNIS am Zielnamen des -wal:
    # os.rename auf ein vorhandenes Verzeichnis scheitert.
    live3 = _os.path.join(heim, "dritte.db")
    con3 = _mit_zeilen(live3, ["@dritter_bestand"], wal=True)
    assert _os.path.exists(live3 + "-wal")
    stempel = "FESTGENAGELT"
    _os.makedirs(live3 + "-wal.vor_wiederherstellung_" + stempel)
    quelle3 = _os.path.join(heim, "quelle3.db")
    _mit_zeilen(quelle3, ["@egal"]).close()
    vor3 = sorted(f for f in _os.listdir(heim) if f.startswith("dritte.db"))
    ok5, meldung5, _w5 = R.einsetzen(live3, quelle3, stempel=stempel)
    nach3 = sorted(f for f in _os.listdir(heim) if f.startswith("dritte.db"))
    con3.close()
    assert not ok5, "der Fehlschlag mitten in der Reihe wird als Erfolg gemeldet"
    assert "nichts veraendert" in meldung5, \
        "die Meldung sagt nicht, dass zurueckgedreht wurde: %s" % meldung5
    assert vor3 == nach3, \
        "die Hauptdatei blieb weggeraeumt — die laufende Datenbank ist weg, " \
        "und die neue liegt nicht an ihrer Stelle: %s -> %s" % (vor3, nach3)
    assert _os.path.exists(live3), \
        "dritte.db ist verschwunden — genau der Zustand, in dem der Bot " \
        "nicht mehr startet und nichts mehr da ist"

    # ── (5) DIE ARCHIV-LISTE. Sie traegt nur echte Systemarchive, juengstes
    # zuerst — sonst greift der Betreiber im Deck zum falschen Stand.
    sverz = _os.path.join(heim, "system")
    _os.makedirs(sverz)
    dumpdatei = _os.path.join(heim, "tiktok_bot_20260918_0400.sql")
    con = _sq3.connect(_os.path.join(heim, "quelle.db"))
    con.execute("CREATE TABLE trackings (id INTEGER PRIMARY KEY, u TEXT)")
    for i in range(7):
        con.execute("INSERT INTO trackings (u) VALUES (?)", ("@q_%d" % i,))
    con.commit()
    with open(dumpdatei, "w", encoding="utf-8") as f:
        for zeile in con.iterdump():
            f.write(zeile + "\n")
    con.close()
    for stempel in ("20260916_0400", "20260918_0400"):
        with _tf.open(_os.path.join(sverz, "nightcrawler_sys_%s.tar.gz" % stempel),
                      "w:gz") as tar:
            tar.add(dumpdatei, arcname="db/tiktok_bot_%s.sql" % stempel)
    with open(_os.path.join(sverz, "egal.txt"), "w", encoding="utf-8") as f:
        f.write("kein Archiv")
    liste = R.archive(sverz)
    assert [e["name"] for e in liste] == [
        "nightcrawler_sys_20260918_0400.tar.gz",
        "nightcrawler_sys_20260916_0400.tar.gz"], \
        "die Liste stimmt nicht (juengstes zuerst, nur Archive): %s" % liste
    assert R.archive(_os.path.join(heim, "gibtsnicht")) == [], \
        "ein fehlendes Verzeichnis muss eine leere Liste geben, nicht werfen"

    # ── (6) UND DER GANZE WEG AM STUECK: Archiv -> geprüfte Datei -> Zahlen.
    ziel = _os.path.join(heim, "aus_deck.db")
    ok3, befund3, tabellen3 = R.vorbereiten(
        _os.path.join(sverz, "nightcrawler_sys_20260918_0400.tar.gz"), ziel)
    assert ok3 and befund3 == "ok", befund3
    assert dict(tabellen3)["trackings"] == 7, tabellen3
    # Und ein zweites Mal auf dasselbe Ziel ueberschreibt NICHT.
    ok4, befund4, _t4 = R.vorbereiten(
        _os.path.join(sverz, "nightcrawler_sys_20260918_0400.tar.gz"), ziel)
    assert not ok4 and "gibt es schon" in befund4, befund4

    # ── (7) DIE ROUTEN, GEFAHREN STATT GELESEN. Eine Textsuche nach
    # "sicher_join" haette gruen bleiben koennen, waehrend das Ergebnis
    # verworfen wird — dieselbe Lehre wie in W93.
    from flask import Flask as _Flask
    from nc import ctx as _ncctx
    from nc.routes import settings as _rt

    app = _Flask(__name__)
    app.register_blueprint(_rt.bp)
    regeln = {str(r.rule) for r in app.url_map.iter_rules()}
    for want in ("/api/db/restore/list", "/api/db/restore/prepare",
                 "/api/db/restore/apply"):
        assert want in regeln, "Route fehlt oder umbenannt: %s" % want

    live4 = _os.path.join(heim, "deck.db")
    _mit_zeilen(live4, ["@im_deck"]).close()
    import logging as _logging
    _ncctx.configure(cfg={"DB_PATH": live4, "DB_BACKEND": "sqlite"},
                     log=_logging.getLogger("TikTokBot"))
    alt_bd = _os.environ.get("LOCAL_BACKUP_DIR")
    _os.environ["LOCAL_BACKUP_DIR"] = heim
    kl = app.test_client()
    try:
        # (a) Die Liste zeigt die Archive.
        r = kl.get("/api/db/restore/list")
        assert r.status_code == 200 and r.get_json()["ok"], r.get_json()
        namen = [e["name"] for e in r.get_json()["archive"]]
        assert namen[0] == "nightcrawler_sys_20260918_0400.tar.gz", namen

        # (b) EIN PFAD-AUSBRUCH DARF NICHT DURCHKOMMEN. Der Archivname steht
        # in der Anfrage; ohne nc.sicherpfad waere das eine Senke (CodeQL).
        #
        # Gemessen wird der UNTERSCHIED, nicht bloss "kein Erfolg": ohne
        # Riegel landet "../../../etc/passwd" auf einer Datei, die es GIBT,
        # und die Antwort waere trotzdem 400 ("kein Dump"). Daran ist die
        # Mutationsprobe zuerst entwischt. Mit Riegel wird der Name auf
        # seinen Basisnamen gestutzt, und im Sicherungsverzeichnis gibt es
        # kein "passwd" -> 404.
        r = kl.post("/api/db/restore/prepare",
                    json={"archiv": "../../../etc/passwd"})
        assert r.status_code == 404, \
            "der Name wurde nicht gestutzt — der Zugriff ging aus dem " \
            "Sicherungsverzeichnis heraus (%s: %s)" % (r.status_code, r.get_json())
        assert "passwd" not in str(r.get_json()), \
            "der Ausbruchspfad wird zurueckgespiegelt: %s" % r.get_json()

        # Und die schaerfere Fassung: ein GUELTIGES Archiv ausserhalb des
        # Sicherungsverzeichnisses darf nicht erreichbar sein.
        #
        # Der Name muss dabei EINMALIG sein. Die erste Fassung nahm einen,
        # den es drinnen auch gab — der gestutzte Name traf dann ein echtes
        # Archiv, die Antwort war 200, und das sah aus wie ein Ausbruch.
        # War keiner: der Riegel hatte sauber gestutzt, der Vertrag war
        # schlecht gestellt.
        aussen = _os.path.join(heim, "nightcrawler_sys_99999999_9999.tar.gz")
        with _tf.open(aussen, "w:gz") as tar:
            tar.add(dumpdatei, arcname="db/tiktok_bot_99999999_9999.sql")
        assert not _os.path.exists(
            _os.path.join(sverz, "nightcrawler_sys_99999999_9999.tar.gz")), \
            "der Name gibt es drinnen auch — dann prueft dieser Fall nichts"
        r = kl.post("/api/db/restore/prepare",
                    json={"archiv": "../nightcrawler_sys_99999999_9999.tar.gz"})
        assert r.status_code == 404, \
            "ein Archiv ausserhalb des Sicherungsverzeichnisses war " \
            "erreichbar: %s" % r.get_json()

        # (c) Der Normalfall baut eine neue Datei, ohne die laufende zu
        # beruehren.
        vorher_live = open(live4, "rb").read()
        r = kl.post("/api/db/restore/prepare",
                    json={"archiv": "nightcrawler_sys_20260918_0400.tar.gz"})
        d = r.get_json()
        assert r.status_code == 200 and d["ok"], d
        assert dict((x["name"], x["zeilen"]) for x in d["tabellen"])["trackings"] == 7, d
        assert open(live4, "rb").read() == vorher_live, \
            "die laufende Datenbank wurde beim Vorbereiten veraendert"

        # (d) OHNE BESTAETIGUNG WIRD NICHTS EINGESETZT.
        r = kl.post("/api/db/restore/apply", json={"datei": d["datei"]})
        assert r.status_code == 400, r.get_json()
        assert open(live4, "rb").read() == vorher_live, \
            "ohne confirm wurde trotzdem getauscht"

        # (e) Und die laufende Datenbank selbst laesst sich nicht einsetzen.
        r = kl.post("/api/db/restore/apply",
                    json={"confirm": True, "datei": _os.path.basename(live4)})
        assert r.status_code == 400, r.get_json()

        # (f) Mit Bestaetigung: getauscht, und die Meldung verlangt den
        # Neustart.
        r = kl.post("/api/db/restore/apply",
                    json={"confirm": True, "datei": d["datei"]})
        dd = r.get_json()
        assert r.status_code == 200 and dd["ok"], dd
        assert "NEU STARTEN" in dd["meldung"], dd
        con = _sq3.connect(live4)
        assert con.execute("SELECT count(*) FROM trackings").fetchone()[0] == 7, \
            "nach dem Einsetzen steht nicht die Sicherung da"
        con.close()

        # (g) Ohne LOCAL_BACKUP_DIR sagt die Liste WARUM, statt leer zu sein.
        _os.environ.pop("LOCAL_BACKUP_DIR", None)
        r = kl.get("/api/db/restore/list")
        assert r.status_code == 400 and "LOCAL_BACKUP_DIR" in r.get_json()["error"], \
            r.get_json()

        # (h) UND DER AUFFANG SELBST. Faellt in der Route etwas Unerwartetes,
        # muss eine 500 mit gesaeuberter Meldung herauskommen — nicht ein
        # Flask-Stacktrace mit Serverpfaden darin (nc/fehlertext.py).
        _os.environ["LOCAL_BACKUP_DIR"] = heim
        _ncctx.configure(cfg={}, log=_logging.getLogger("TikTokBot"))
        for weg, last in (("/api/db/restore/prepare",
                           {"archiv": "nightcrawler_sys_20260918_0400.tar.gz"}),
                          ("/api/db/restore/apply",
                           {"confirm": True, "datei": "egal.db"})):
            r = kl.post(weg, json=last)
            assert r.status_code == 500, (weg, r.status_code, r.get_json())
            text = str(r.get_json())
            assert heim not in text, \
                "%s spiegelt einen Serverpfad zurueck: %s" % (weg, text)
    finally:
        if alt_bd is None:
            _os.environ.pop("LOCAL_BACKUP_DIR", None)
        else:
            _os.environ["LOCAL_BACKUP_DIR"] = alt_bd

    # ── (8) DIE FEHLERPFADE, EINZELN. Sie sind der Grund, warum dieses
    # Modul ueberhaupt laut geworden ist — ungeprueft waeren es Zeilen, die
    # nur behaupten zu helfen.
    import tarfile as _tf2

    # (a) Ein Archiv ohne den Dump nennt den Weg zum Nachsehen.
    ohne = _os.path.join(heim, "nightcrawler_sys_ohne.tar.gz")
    with _tf2.open(ohne, "w:gz") as tar:
        tar.add(dumpdatei, arcname="db/brain_20260918_0400.sql")
    pfad_, grund_ = R.dump_aus_archiv(ohne, heim)
    assert pfad_ is None and "tar -tzf" in grund_, grund_

    # (b) Ein Verzeichniseintrag unter db/ wird gar nicht erst Kandidat —
    # isfile() filtert ihn, und der None-Zweig dahinter ist damit
    # unerreichbar. Geprueft wird deshalb der FILTER, nicht der tote Zweig.
    verz_arch = _os.path.join(heim, "nightcrawler_sys_verz.tar.gz")
    with _tf2.open(verz_arch, "w:gz") as tar:
        info = _tf2.TarInfo("db/tiktok_bot_20260918_0400.sql")
        info.type = _tf2.DIRTYPE
        tar.addfile(info)
    pfad2_, grund2_ = R.dump_aus_archiv(verz_arch, heim)
    assert pfad2_ is None and "tar -tzf" in grund2_, \
        "ein Verzeichnis unter db/ wird als Dump genommen: %s" % grund2_

    # (c) Kein Archiv, sondern Muell -> tarfile faellt, und das wird gesagt.
    kmuell = _os.path.join(heim, "kaputt.tar.gz")
    with open(kmuell, "wb") as f:
        f.write(b"kein gzip")
    okm, befundm, _tm = R.vorbereiten(kmuell, _os.path.join(heim, "m1.db"))
    assert not okm and "nicht zu lesen" in befundm, befundm

    # (d) Ein Archiv ohne Dump, ueber vorbereiten().
    oko, befundo, _to = R.vorbereiten(ohne, _os.path.join(heim, "m2.db"))
    assert not oko and "tar -tzf" in befundo, befundo
    assert not _os.path.exists(_os.path.join(heim, "m2.db"))

    # (e) Eine .sql ohne Dump-Vokabular.
    keine = _os.path.join(heim, "keine.sql")
    with open(keine, "w", encoding="utf-8") as f:
        f.write("nur text\n")
    okk, befundk, _tk = R.vorbereiten(keine, _os.path.join(heim, "m3.db"))
    assert not okk and "nicht nach einem Systemarchiv-Dump" in befundk, befundk

    # (f) Ein Dump, der die Marken traegt und trotzdem faellt.
    kaputt_sql = _os.path.join(heim, "kaputt2.sql")
    with open(kaputt_sql, "w", encoding="utf-8") as f:
        f.write("BEGIN TRANSACTION;\nCREATE TABLE a (i INT);\n"
                "INSERT INTO a VALUES (1);\nCREATE TABLE ;;; kaputt\n")
    okb, _bb, _tb = R.vorbereiten(kaputt_sql, _os.path.join(heim, "m4.db"))
    assert not okb and not _os.path.exists(_os.path.join(heim, "m4.db")), \
        "die halb gebaute Datei blieb liegen"

    # (g) archive(): ein Eintrag, den os.stat nicht lesen kann, darf die
    # Liste nicht abbrechen — er wird uebersprungen UND gemeldet.
    tot = _os.path.join(sverz, "nightcrawler_sys_20260901_0400.tar.gz")
    _os.symlink(_os.path.join(heim, "gibtsnicht_ziel"), tot)
    liste2 = R.archive(sverz)
    assert all(e["name"] != _os.path.basename(tot) for e in liste2), \
        "ein toter Verweis steht in der Auswahlliste"
    assert len(liste2) == 2, liste2

    # (h) _zurueck() meldet, wenn das Zurueckdrehen selbst misslingt — der
    # schlimmste Zustand des Moduls.
    R._zurueck([(_os.path.join(heim, "gibtsnicht_a"),
                 _os.path.join(heim, "gibtsnicht_b"))])

    # (i) PLATTE VOLL BEIM EINSETZEN. Die Hauptdatei liegt dann schon zur
    # Seite, und wenn jetzt nichts zurueckgedreht wird, ist die laufende
    # Datenbank weg und die neue nicht da. Nicht konstruierbar ohne Attrappe:
    # als root laufen Rechte-Tricks ins Leere.
    import shutil as _sh2
    live5 = _os.path.join(heim, "fuenfte.db")
    con5 = _mit_zeilen(live5, ["@fuenfter_bestand"], wal=True)
    quelle5 = _os.path.join(heim, "quelle5.db")
    _mit_zeilen(quelle5, ["@neu"]).close()
    vor5 = sorted(f for f in _os.listdir(heim) if f.startswith("fuenfte.db"))
    echt_copy2 = _sh2.copy2

    def _platte_voll(*a, **k):
        raise OSError(28, "No space left on device")

    R.shutil.copy2 = _platte_voll
    try:
        ok6, meldung6, _w6 = R.einsetzen(live5, quelle5)
    finally:
        R.shutil.copy2 = echt_copy2
    nach5 = sorted(f for f in _os.listdir(heim) if f.startswith("fuenfte.db"))
    con5.close()
    assert not ok6, "ein gescheitertes Einsetzen wird als Erfolg gemeldet"
    assert "zurueckgelegt" in meldung6, meldung6
    assert vor5 == nach5, \
        "nach dem Fehlschlag ist die laufende Datenbank nicht zurueck: " \
        "%s -> %s" % (vor5, nach5)
    assert _os.path.exists(live5), "fuenfte.db ist weg"

    ok("W96: der Tausch nimmt -wal und -shm mit (sonst kommt der ALTE Stand)")
    ok("W96: der vorige Stand liegt daneben, nicht im Papierkorb")
    ok("W96: die Meldung verlangt den sofortigen Neustart und sagt warum")
    ok("W96: ein Fehlschlag laesst nichts halb verschoben zurueck")
    ok("W96: die Archivliste traegt nur Archive, juengstes zuerst")
    ok("W96: Archiv -> geprüfte Datei am Stueck, ohne Ueberschreiben")
    ok("W96: jeder Fehlerpfad des Moduls nennt Grund und Weg")
    ok("W96: die drei Deck-Routen gefahren — Liste, Vorbereiten, Einsetzen")
    ok("W96: ein Pfad-Ausbruch im Archivnamen kommt nicht durch")
    ok("W96: ohne confirm wird nicht getauscht, die laufende DB nie als Quelle")


def _test_v42_w97_concat_liste_traegt_absolute_pfade():
    """Jedes Zusammenfuegen einer Sitzung scheiterte — an einer Vorsilbe.

    Aus dem ERROR-Log vom 19.09., dreimal, fuer drei verschiedene Sitzungen:

        Impossible to open 'recordings/recordings/tiktok_live_….mp4'

    Der concat-Demuxer loest einen relativen Eintrag NICHT gegen das
    Arbeitsverzeichnis auf, sondern gegen das Verzeichnis der Listendatei.
    Die liegt neben dem Ziel, also in `recordings/`; in der Datenbank steht
    `recordings/xyz.mp4`, weil RECORDINGS_DIR ein relativer Name ist.

    Warum der Bestand das nicht gemerkt hat, ist der eigentliche Befund:
    `concat_cmd` begruendet sein `-safe 0` seit W44 damit, dass "die Liste
    absolute Pfade traegt" — und der W44-Vertrag reichte ausschliesslich
    Pfade ab `/rec/...` herein. Er war gruen, weil er die Eingabe der
    Produktion nie gesehen hat.
    """
    import os as _os
    import shlex as _shlex
    import pruefhilfen as P
    from nc import aufnahmesitzung as A

    heim = P.verzeichnis()
    unter = _os.path.join(heim, "recordings")
    _os.makedirs(unter)
    alt_cwd = _os.getcwd()
    _os.chdir(heim)
    try:
        # ── (1) DER FALL AUS DEM LOG, GERECHNET STATT GELESEN.
        # Nachgebaut wird, was ffmpeg tut: jeden Eintrag gegen das
        # Verzeichnis der LISTENDATEI aufloesen. Genau diese Rechnung fehlte.
        liste = A.concat_liste(["recordings/a.mp4", "recordings/b.mp4"])
        listendatei = _os.path.join(unter, "sitzung_x.mp4.txt")
        verz_der_liste = _os.path.dirname(listendatei)
        for zeile in liste.rstrip("\n").split("\n"):
            eintrag = _shlex.split(zeile)[1]
            assert _os.path.isabs(eintrag), \
                "relativer Eintrag in der concat-Liste: %r — ffmpeg loest ihn " \
                "gegen %s auf und sucht dann recordings/recordings/…" % (
                    eintrag, verz_der_liste)
            # DAS ist die Eigenschaft, um die es geht: ein absoluter
            # Eintrag laesst sich gegen das Verzeichnis der Listendatei
            # NICHT mehr verschieben — os.path.join gibt ihn unveraendert
            # zurueck, und genau das tut ffmpeg auch.
            wohin = _os.path.join(verz_der_liste, eintrag)
            assert wohin == eintrag, \
                "der Eintrag wandert beim Aufloesen: %s -> %s" % (eintrag, wohin)
            assert "recordings" + _os.sep + "recordings" not in wohin, \
                "die doppelte Vorsilbe aus dem Log ist zurueck: %s" % wohin
            assert wohin.startswith(_os.getcwd() + _os.sep), \
                "der Eintrag zeigt aus dem Arbeitsverzeichnis heraus: %s" % wohin

        # ── (2) DAS QUOTING AUS W44 UEBERLEBT DAS ABSOLUTMACHEN.
        # Der Apostroph muss die Zeile weiterhin nicht aufbrechen koennen,
        # egal wie lang der Pfad durch abspath geworden ist.
        #
        # Was hier BEWUSST NICHT steht, ist eine Aussage ueber die
        # Reihenfolge von abspath und Escapen. Die Mutationsprobe dazu ist
        # entwischt, und die Nachmessung gab ihr recht statt dem Vertrag:
        # die Escape-Folge ist  '\''  — ein einzelner Backslash vor einem
        # Apostroph, und den fasst weder posixpath.normpath noch
        # ntpath.normpath an. Beide Reihenfolgen liefern dieselben Bytes,
        # auf beiden Plattformen gemessen. Eine Probe fuer eine Aussage, die
        # der Code gar nicht trifft, waere ein Vertrag ohne Gegenstand.
        boese = ["recordings/it's here.mp4", "recordings/'; rm -rf / ;'.mp4",
                 "/rec/schon absolut'.mp4"]
        zeilen = A.concat_liste(boese).rstrip("\n").split("\n")
        assert len(zeilen) == len(boese)
        for zeile, roh in zip(zeilen, boese):
            zerlegt = _shlex.split(zeile)
            assert zerlegt[0] == "file" and len(zerlegt) == 2, \
                "die Zeile zerfaellt in mehr als zwei Woerter: %r" % zeile
            assert zerlegt[1] == _os.path.abspath(roh), (zerlegt, roh)

        # ── (3) EIN BEREITS ABSOLUTER PFAD WIRD NICHT ANGEFASST.
        # Sonst haenge das Arbeitsverzeichnis noch einmal davor, und der
        # Fehler waere derselbe, nur mit anderem Praefix.
        assert _shlex.split(A.concat_liste(["/rec/x.mp4"]).strip())[1] == "/rec/x.mp4"

        # ── (4) UND KEIN SYMLINK WIRD AUFGELOEST. Das Aufnahmeverzeichnis
        # darf auf eine ausgelagerte Platte zeigen; `realpath` schriebe den
        # Pfad hinter dem Ruecken des Riegels aus `zieldatei` um.
        if hasattr(_os, "symlink"):
            echt = _os.path.join(heim, "echt.mp4")
            with open(echt, "wb") as f:
                f.write(b"x")
            link = _os.path.join(unter, "link.mp4")
            try:
                _os.symlink(echt, link)
            except (OSError, NotImplementedError):
                link = None          # Windows ohne Entwicklermodus
            if link:
                assert _shlex.split(A.concat_liste([link]).strip())[1] == link, \
                    "der Symlink wurde aufgeloest — realpath statt abspath"

        assert A.concat_liste([]) == "", "leere Liste darf keine Leerzeile erzeugen"
    finally:
        _os.chdir(alt_cwd)

    ok("W97: die concat-Liste traegt absolute Pfade — keine doppelte Vorsilbe mehr")
    ok("W97: abspath vor dem Escapen, Apostroph und Symlink bleiben heil")


def _test_v42_w97_drossel_haelt_bei_wechselnden_gruenden():
    """13675 Warnungen in 22 Stunden — aus einer Drossel.

    `nc.meldetakt` meldete bis W97 jeden Grund sofort, der sich vom VORIGEN
    unterschied. Das setzt voraus, dass ein Kanal zu einer Zeit einen
    vorherrschenden Grund hat. Der Resolver-Kanal hat das nicht: er laeuft
    pro Poll ueber 40 verfolgte Nutzer, und jeder erzeugt der Reihe nach
    `status_code`, dann `html_kein_tag`. Damit war jeder Aufruf ein Wechsel.

    Gemessen im Log vom 19.09.: 13675 Zeilen aus `_resolver_stumm`, 5315
    davon mit Unterdrueckt-Zaehler — der Beweis, dass der Wechsel-Pfad
    dauernd feuerte.
    """
    from nc import meldetakt as M

    M.zuruecksetzen()
    try:
        # ── (1) DER FALL AUS DEM LOG. Zwei Gruende im Wechsel, 200 Aufrufe
        # innerhalb eines Fensters. Vorher: 200 laute Zeilen. Erlaubt sind
        # zwei — je eine pro Grund.
        laut = 0
        t = 0.0
        for _ in range(100):
            for grund in ("status_code", "html_kein_tag"):
                ja, _u = M.melden("resolver", grund, t)
                laut += 1 if ja else 0
                t += 1.0
        assert laut == 2, \
            "abwechselnde Gruende hebeln die Drossel aus: %d laute Zeilen " \
            "bei 200 Aufrufen in %d s" % (laut, int(t))

        # ── (2) WAS DIE DROSSEL NICHT KAPUTTMACHEN DARF: ein WIRKLICH neuer
        # Grund ist die Nachricht und meldet sofort. Dass aus einem Timeout
        # ein 403 geworden ist, darf nicht 15 Minuten warten.
        ja, _u = M.melden("resolver", "http_403", t)
        assert ja, "ein neuer Grund wurde verschluckt — die Drossel ist zu scharf"

        # ── (3) UND DIE RUHEZEIT GILT WIRKLICH JE GRUND, nicht global:
        # status_code ist noch still, http_403 hat gerade gemeldet.
        assert not M.melden("resolver", "status_code", t + 1.0)[0]
        assert not M.melden("resolver", "http_403", t + 2.0)[0]
        # Nach ABSTAND_S ist er wieder dran.
        ja, _u = M.melden("resolver", "status_code", t + M.ABSTAND_S)
        assert ja, "nach %.0f s meldet der Grund nicht wieder" % M.ABSTAND_S

        # ── (4) DER ZAEHLER ZAEHLT JE KANAL, NICHT JE GRUND. Der Betreiber
        # will wissen, wieviel dieser Kanal verschluckt — nicht dieselbe Zahl
        # auf sechzehn Gruende verteilt.
        M.zuruecksetzen()
        M.melden("k", "a", 0.0)                 # laut, setzt das Fenster
        for i in range(1, 6):
            M.melden("k", "a", float(i))        # 5 verschluckt
        ja, unterdrueckt = M.melden("k", "b", 6.0)   # neuer Grund -> laut
        assert ja and unterdrueckt == 5, \
            "die Zahl der unterdrueckten Faelle geht beim Grundwechsel " \
            "verloren: %s" % unterdrueckt
        assert M.zusatz(5) == " (5 weitere unterdrueckt)"
        assert M.zusatz(0) == ""

        # ── (5) DIE TRENNUNG DER KANAELE BLEIBT. Zwei Kanaele drosseln sich
        # nicht gegenseitig; das war seit W81 so und muss so bleiben.
        M.zuruecksetzen()
        assert M.melden("resolver", "netz", 0.0)[0]
        assert M.melden("whisper", "netz", 0.0)[0], \
            "ein zweiter Kanal erbt die Drossel des ersten"

        # ── (6) UND DER DECKEL GEGEN DAS LANGSAME LECK. "stats-json" nimmt
        # `str(info)[:80]` als Grund — ein offenes Vokabular. Ohne Deckel
        # waechst das Register unbegrenzt.
        M.zuruecksetzen()
        for i in range(M.MAX_GRUENDE * 3):
            M.melden("stats-json", "grund_%d" % i, float(i))
        gesehen = M.ZUSTAND["stats-json"][1]
        assert len(gesehen) <= M.MAX_GRUENDE, \
            "das Register waechst unbegrenzt: %d Eintraege" % len(gesehen)

        # ── (6b) UND DER DECKEL GREIFT AUCH, WENN NICHTS ALT GENUG IST.
        # Hier ist die Falle, an der die erste Fassung dieses Deckels
        # entwischt ist: sie warf nur Gruende weg, die laenger als zwei
        # Fenster still waren. 192 Gruende im Sekundentakt sind aber alle
        # jung — es fiel keiner heraus, und der Deckel war ein Kommentar
        # ohne Wirkung. Gemessen: 192 Eintraege bei MAX_GRUENDE = 64.
        M.zuruecksetzen()
        for i in range(M.MAX_GRUENDE * 3):
            M.melden("eng", "g_%d" % i, 1000.0 + i * 0.001)
        eng = M.ZUSTAND["eng"][1]
        assert len(eng) <= M.MAX_GRUENDE, \
            "bei dicht aufeinanderfolgenden Gruenden greift der Deckel " \
            "nicht: %d Eintraege" % len(eng)

        # ── (6c) GEWORFEN WIRD DER AELTESTE, NICHT DER JUENGSTE. Der
        # juengste ist der, der gerade drosselt; ihn zu werfen hiesse, die
        # Drossel genau fuer den aktiven Grund zu oeffnen.
        assert "g_%d" % (M.MAX_GRUENDE * 3 - 1) in eng, \
            "der zuletzt gemeldete Grund wurde weggeworfen"
        assert "g_0" not in eng, "der aelteste Grund ueberlebt den Deckel"
        assert not M.melden("eng", "g_%d" % (M.MAX_GRUENDE * 3 - 1), 1000.5)[0], \
            "der aktive Grund drosselt nach dem Aufraeumen nicht mehr"

        # ── (7) ZURUECKSETZEN NACH ERFOLG. Ohne das bliebe ein behobener
        # und erneut auftretender Fehler bis zu 15 Minuten unsichtbar.
        M.zuruecksetzen()
        assert M.melden("x", "a", 0.0)[0]
        assert not M.melden("x", "a", 1.0)[0]
        M.zuruecksetzen("x")
        assert M.melden("x", "a", 2.0)[0], \
            "nach zuruecksetzen() meldet der naechste Ausfall nicht sofort"
    finally:
        M.zuruecksetzen()

    ok("W97: wechselnde Gruende hebeln die Meldedrossel nicht mehr aus")
    ok("W97: ein wirklich neuer Grund meldet weiter sofort")
    ok("W97: der Grund-Deckel raeumt nur auf, was nicht mehr drosselt")


def _test_v42_w97_logging_blockiert_den_loop_nicht_mehr():
    """Der Event-Loop stand in einer LOG-Sperre — bis zu 176 Sekunden.

    Aus dem Voll-Stack-Dump vom 18.09. 22:15, Loop-Thread:

        File "httpx/_client.py", line 1740, in _send_single_request
            logger.info(
        File "logging/__init__.py", line 1026, in handle
            with self.lock:

    Drei synchrone Handler am Wurzel-Logger (Konsole + zwei
    RotatingFileHandler) teilen sich ihre Sperren mit 21 Threads. Auf einer
    Platte unter Volllast dauert ein Schreibvorgang Sekunden, und jeder
    `log.info` im Loop wartet mit. Folge im selben Log: Bridge-Tick 182 s
    tot, Restream 225 s ohne Bild, Discord-Heartbeat blockiert,
    `database is locked`.
    """
    import logging as _lg
    import time as _t
    from nc import logschleuse as S

    class Langsam(_lg.Handler):
        """Steht fuer die Platte unter Volllast — 20 ms je Zeile."""

        def __init__(self, level=_lg.NOTSET):
            super().__init__(level)
            self.raus = []

        def emit(self, satz):
            _t.sleep(0.02)
            self.raus.append(self.format(satz))

    S.zuruecksetzen()
    wurzel = _lg.getLogger("w97_probe")
    wurzel.propagate = False
    wurzel.setLevel(_lg.DEBUG)
    for h in list(wurzel.handlers):
        wurzel.removeHandler(h)
    langsam = Langsam()
    langsam.setFormatter(_lg.Formatter(
        "%(levelname)s|%(name)s|%(funcName)s:%(lineno)d|%(message)s"))
    nur_fehler = Langsam(level=_lg.ERROR)
    wurzel.addHandler(langsam)
    wurzel.addHandler(nur_fehler)

    try:
        # ── (1) DIE MESSUNG, DIE DEN BEFUND TRAEGT. Erst synchron, dann
        # durch die Schleuse — dieselben Zeilen, derselbe Handler.
        def dauer():
            t0 = _t.perf_counter()
            for i in range(20):
                wurzel.info("zeile %d", i)
            return _t.perf_counter() - t0

        synchron = dauer()
        assert synchron > 0.2, \
            "der Attrappen-Handler blockiert gar nicht (%.3f s) — die " \
            "Messung darunter beweist dann nichts" % synchron

        horcher = S.entkoppeln(wurzel)
        entkoppelt = dauer()
        assert entkoppelt < synchron / 10.0, \
            "die Schleuse bringt nichts: %.3f s synchron gegen %.3f s " \
            "entkoppelt" % (synchron, entkoppelt)

        # ── (2) UND SIE VERLIERT DABEI NICHTS. Eine schnelle Schleuse, die
        # Zeilen schluckt, waere die Verschlimmbesserung.
        horcher.stop()
        assert len(langsam.raus) == 40, \
            "es kamen nicht alle Zeilen an: %d von 40" % len(langsam.raus)

        # ── (3) DIE FORMATIERUNG UEBERLEBT DIE SCHLANGE. `QueueHandler`
        # ersetzt `record.msg` durch den formatierten Text; alle anderen
        # Felder muessen stehenbleiben, sonst steht im Log kein
        # `funcName:lineno` mehr und jede Fehlersuche faengt von vorn an.
        letzte = langsam.raus[-1]
        assert letzte.startswith("INFO|w97_probe|dauer:"), letzte
        assert letzte.endswith("|zeile 19"), letzte

        # ── (4) `respect_handler_level` ist nicht Beiwerk: ohne das bekaeme
        # error.log die kompletten DEBUG-Zeilen, und die Trennung der beiden
        # Dateien waere weg.
        assert nur_fehler.raus == [], \
            "der ERROR-Handler hat INFO-Zeilen bekommen: %s" % nur_fehler.raus[:2]

        # ── (5) DIE SCHLANGE IST BEGRENZT UND WARTET NIE. Eine unbegrenzte
        # Schlange tauscht den eingefrorenen Loop gegen einen OOM-Kill.
        S.zuruecksetzen()
        for h in list(wurzel.handlers):
            wurzel.removeHandler(h)
        blocker = Langsam()
        blocker.setFormatter(_lg.Formatter("%(message)s"))
        wurzel.addHandler(blocker)
        horcher2 = S.entkoppeln(wurzel, max_wartend=5)
        t0 = _t.perf_counter()
        for i in range(500):
            wurzel.info("flut %d", i)
        gebraucht = _t.perf_counter() - t0
        assert gebraucht < 1.0, \
            "die volle Schlange hat den Aufrufer blockiert (%.3f s fuer 500 " \
            "Zeilen) — genau das sollte sie verhindern" % gebraucht
        assert S.verloren() > 0, \
            "bei 5 Plaetzen und 500 Zeilen ging nichts verloren — dann " \
            "wartet die Schlange doch irgendwo"

        # ── (6) UND DER VERLUST IST NICHT STILL. Ein stiller Verlust waere
        # genau der Fehler, gegen den dieses Projekt seine Sperren hat.
        _t.sleep(0.4)
        wurzel.info("noch eine")
        horcher2.stop()
        verlustzeilen = [z for z in blocker.raus if "Log-Schleuse" in z]
        assert verlustzeilen, \
            "verworfene Zeilen werden nicht gemeldet: %s" % blocker.raus[:3]
        assert "verworfen" in verlustzeilen[0] and "Platte" in verlustzeilen[0], \
            "die Verlustmeldung nennt keine Abhilfe: %s" % verlustzeilen[0]
        # v4.2-W146: und der Zaehler bleibt NACH der Meldezeile stehen. Bis
        # hierher nullte der Horcher ihn beim Melden — /healthz und /metrics
        # zeigten Millisekunden nach dem Verlust wieder 0, und die Regel
        # NightcrawlerLogVerluste konnte nie feuern.
        assert S.verloren() > 0, "Verlust nach der Meldezeile wieder auf 0 — fuer Prometheus unsichtbar"

        # ── (7) ZWEIMAL ENTKOPPELN HAENGT NICHT ZWEIMAL UM. Sonst stuenden
        # zwei Horcher auf denselben Handlern und jede Zeile stuende doppelt
        # im Log.
        S.zuruecksetzen()
        for h in list(wurzel.handlers):
            wurzel.removeHandler(h)
        einfach = Langsam()
        einfach.setFormatter(_lg.Formatter("%(message)s"))
        wurzel.addHandler(einfach)
        h1 = S.entkoppeln(wurzel)
        h2 = S.entkoppeln(wurzel)
        assert h1 is h2, "ein zweiter Aufruf baut einen zweiten Horcher auf"
        assert len(wurzel.handlers) == 1, wurzel.handlers
        wurzel.info("genau einmal")
        S.stoppen()
        assert einfach.raus.count("genau einmal") == 1, einfach.raus

        # ── (8) OHNE HANDLER GIBT ES NICHTS ZU ENTKOPPELN, und das wird
        # gesagt statt still eine leere Schleuse aufzubauen — sonst faende
        # sich spaeter kein einziger Logeintrag mehr.
        S.zuruecksetzen()
        for h in list(wurzel.handlers):
            wurzel.removeHandler(h)
        try:
            S.entkoppeln(wurzel)
            raise AssertionError("entkoppeln() ohne Handler ist still durchgelaufen")
        except ValueError:
            pass
        # ── (8b) DIE SCHLANGENTIEFE, DIE /healthz MELDET. Sie ist der
        # Fruehwarnwert: dauerhaft hoch heisst, die Platte kommt nicht nach,
        # und das gehoert sichtbar, BEVOR die erste Zeile faellt.
        S.zuruecksetzen()
        for h in list(wurzel.handlers):
            wurzel.removeHandler(h)
        zaeh = Langsam()
        zaeh.setFormatter(_lg.Formatter("%(message)s"))
        wurzel.addHandler(zaeh)
        horcher3 = S.entkoppeln(wurzel, max_wartend=200)
        for i in range(30):
            wurzel.info("tief %d", i)
        assert S.wartend() > 0, \
            "die Schlangentiefe bleibt 0, obwohl 30 Zeilen auf einen " \
            "Handler mit 20 ms je Zeile warten"
        horcher3.stop()

        # ── (8c) UND DER ABSCHIED, WENN DAS WACHTZEICHEN NICHT MEHR
        # DURCHKOMMT. Das ist ein neuer Fehlerpfad dieser Welle, und ein
        # ungeprueftes "hier koennte etwas fehlen" ist genau die Art Zeile,
        # die nur behauptet zu helfen (W89). Gestellt wird die Falle mit
        # einer Schlange der Groesse 1, deren Horcher schon steht.
        import contextlib as _cl
        import io as _sio
        S.zuruecksetzen()
        for h in list(wurzel.handlers):
            wurzel.removeHandler(h)
        eng2 = Langsam()
        eng2.setFormatter(_lg.Formatter("%(message)s"))
        wurzel.addHandler(eng2)
        horcher4 = S.entkoppeln(wurzel, max_wartend=1)
        horcher4.stop()                      # der Thread ist weg, niemand leert
        horcher4.queue.put_nowait("belegt")  # der einzige Platz ist besetzt
        fehlerkanal = _sio.StringIO()
        with _cl.redirect_stderr(fehlerkanal):
            assert S.stoppen() is True
        gesagt = fehlerkanal.getvalue()
        assert "Wachtzeichen" in gesagt and "fehlen" in gesagt, \
            "der Abschied verschluckt den Fehlschlag still: %r" % gesagt

        # ── (9) UND OHNE SCHLEUSE SAGT /healthz DAS AUCH. Eine 0 laese sich
        # als "nichts wartet, alles gut" lesen — dabei ist "keine Schleuse"
        # der Zustand, in dem der Event-Loop wieder selbst auf die Platte
        # schreibt. Dieselbe Lehre wie bei nc.webserver.tls_lage (W93).
        assert S.wartend() == S.KEINE_SCHLEUSE, S.wartend()
        assert S.KEINE_SCHLEUSE != 0, \
            "der Ersatzwert liest sich wie Normalbetrieb"
        assert S.stoppen() is False, "stoppen() meldet einen Horcher, den es nicht gibt"
    finally:
        S.zuruecksetzen()
        for h in list(wurzel.handlers):
            wurzel.removeHandler(h)

    ok("W97: die Log-Schleuse nimmt dem Event-Loop die Handler-Sperre ab")
    ok("W97: sie verliert dabei nichts und haelt Format und Handler-Ebene")
    ok("W97: die begrenzte Schlange wartet nie und meldet jeden Verlust")


def _test_v42_w98_ordnerscan_findet_dateien_ohne_eintrag():
    """Dem Archiv fehlte die Richtung Ordner -> Datenbank.

    Es gab `/api/archive/check` (Eintraege ohne Datei) und die
    Dubletten-Suche (gleiche Kopien), aber nichts fand eine Video-Datei, die
    im Archivordner liegt und KEINE Zeile hat. Nach einem Neuaufbau der
    Datenbank ist das der komplette Bestand — sichtbar auf der Platte, im
    Deck nicht vorhanden.
    """
    import os as _os
    import logging as _logging
    import sqlite3 as _sq3
    import pruefhilfen as P
    from flask import Flask as _Flask
    from nc import ctx as _ncctx
    from nc import archive as A
    from nc.routes import archive as _rt

    heim = P.verzeichnis()
    ordner = _os.path.join(heim, "archiv")
    _os.makedirs(_os.path.join(ordner, "unterordner"))
    _os.makedirs(_os.path.join(ordner, "tmp"))
    _os.makedirs(_os.path.join(ordner, ".versteckt"))

    def datei(*teile, bytes_=2048):
        pfad = _os.path.join(ordner, *teile)
        P.attrappe(pfad, bytes_)
        return _os.path.abspath(pfad)

    eingetragen = datei("schon_da.mp4")
    datei("neu_eins.mp4")
    datei("unterordner", "neu_zwei.mkv")
    datei("kein_video.txt")
    datei("tmp", "im_tmp.mp4")
    datei(".versteckt", "versteckt.mp4")
    datei(".punktdatei.mp4")

    db = _os.path.join(heim, "w98.db")
    con = _sq3.connect(db)
    con.execute("CREATE TABLE archive (id INTEGER PRIMARY KEY, filename TEXT NOT NULL, "
                "filepath VARCHAR(500) NOT NULL UNIQUE, title TEXT, notes TEXT, "
                "size_bytes BIGINT, mime_type TEXT, source_url TEXT, created_at TEXT NOT NULL)")
    con.commit()
    con.close()

    from nc.dbwrap import configure_db as _cfgdb
    _cfgdb(db_path=db, backend="sqlite")
    A.configure(archive_dir=ordner)
    _ncctx.configure(cfg={"ARCHIVE_DIR": ordner, "_MANUAL_ARCHIVE_DIR": ordner},
                     log=_logging.getLogger("TikTokBot"))

    # Der eine bereits bekannte Eintrag — RELATIV geschrieben, absichtlich.
    A.add_archive_entry(filename="schon_da.mp4",
                        filepath=_os.path.relpath(eingetragen, _os.getcwd()),
                        title=None, notes=None, size=2048, mime=None, source_url=None)

    # ── (1) WAS GEFUNDEN WIRD — UND WAS NICHT.
    e = A.finde_ohne_eintrag(ordner)
    assert e["ok"], e
    namen = sorted(x["name"] for x in e["gefunden"])
    assert namen == ["neu_eins.mp4", "neu_zwei.mkv"], namen
    assert e["gesamt"] == 2 and not e["gedeckelt"], e

    # ── (1b) UND DAS IST DER KERN: der bekannte Eintrag steht RELATIV in der
    # Datenbank, der Fund ist absolut. Ohne Normalisierung auf beiden Seiten
    # gaelte er als neu, und der Knopf boete an, das Archiv ein zweites Mal
    # aufzunehmen. Genau diese Klasse Fehler — dieselbe Datei unter zwei
    # Schreibweisen — hat in W97 jedes Zusammenfuegen scheitern lassen.
    assert "schon_da.mp4" not in namen, \
        "ein relativ eingetragener Pfad gilt als neu — die Pfade werden " \
        "nicht auf beiden Seiten normalisiert"

    # ── (1c) UND DASSELBE MIT EINEM RELATIVEN SCAN-ORDNER. Das ist die
    # Vorgabe im Bestand: ohne ARCHIVE_DIR scannt der Bot schlicht
    # "archive". os.walk liefert dann relative Fundpfade, die Datenbank
    # absolute — ohne abspath auf der Fundseite gilt wieder alles als neu.
    #
    # Die Mutationsprobe dazu ist beim ersten Durchgang ENTWISCHT, weil der
    # Vertrag nur absolute Wurzeln hereinreichte. Genau der Fehler, den W97
    # eine Datei weiter behoben hat: ein Vertrag, der nur die bequeme
    # Eingabe prueft, prueft nichts.
    #
    # Relativ zum JETZIGEN Arbeitsverzeichnis, ohne chdir (v4.2-W125): bis
    # dahin wechselte der Vertrag nach `heim`, waehrend der Eintrag oben
    # relativ zum ALTEN Verzeichnis geschrieben ist. Gruen war das nur, weil
    # `..` an der Wurzel stehen bleibt — aus einem tieferen Verzeichnis
    # gestartet fiel er, ohne dass am Code etwas falsch war. Der Bot wechselt
    # sein Arbeitsverzeichnis nie; der Vertrag tut es jetzt auch nicht.
    rel_ordner = _os.path.relpath(ordner, _os.getcwd())
    assert not _os.path.isabs(rel_ordner)
    rel = A.finde_ohne_eintrag(rel_ordner)
    rel_namen = sorted(x["name"] for x in rel["gefunden"])
    assert rel_namen == ["neu_eins.mp4", "neu_zwei.mkv"], \
        "mit relativem Scan-Ordner stimmt die Fundliste nicht: %s" % rel_namen
    assert all(_os.path.isabs(x["pfad"]) for x in rel["gefunden"]), \
        "die Fundpfade sind relativ — gegen die Datenbank verglichen " \
        "gilt damit jede Datei als neu"

    # ── (2) tmp/, versteckte Ordner und Punktdateien bleiben aussen vor —
    # dieselbe Regel wie beim Dubletten-Scan, damit beide Knoepfe denselben
    # Bestand sehen.
    for verboten in ("im_tmp.mp4", "versteckt.mp4", ".punktdatei.mp4", "kein_video.txt"):
        assert verboten not in namen, verboten

    # ── (3) OHNE DATENBANK WIRD NICHT GERATEN. Das ist die Lehre aus W91,
    # dort mit umgekehrtem Vorzeichen: mit leerem `known` gilt JEDE Datei
    # als unbekannt. Hier hiesse das, das ganze Archiv doppelt aufzunehmen.
    echt_conn = A.db_conn
    class _Kaputt:
        def __enter__(self): raise _sq3.OperationalError("database is locked")
        def __exit__(self, *a): return False
    A.db_conn = lambda *a, **k: _Kaputt()
    try:
        try:
            A.finde_ohne_eintrag(ordner)
            raise AssertionError("ein gesperrtes SQLite liefert eine Fundliste, "
                                 "statt abzubrechen")
        except A.BestandUnbekannt as e_:
            assert "nicht zu lesen" in str(e_), str(e_)
        try:
            A.uebernehmen(ordner)
            raise AssertionError("uebernehmen() arbeitet ohne Kenntnis des Bestands")
        except A.BestandUnbekannt:
            pass
    finally:
        A.db_conn = echt_conn

    # ── (4) DAS AUFNEHMEN. Es legt Zeilen an und fasst keine Datei an.
    vorher = sorted(_os.listdir(ordner))
    b = A.uebernehmen(ordner, ["neu_eins.mp4",
                               _os.path.join("unterordner", "neu_zwei.mkv")])
    assert b["aufgenommen"] == 2 and b["fehler"] == 0, b
    assert sorted(_os.listdir(ordner)) == vorher, \
        "das Aufnehmen hat den Ordner veraendert: %s" % _os.listdir(ordner)
    assert A.finde_ohne_eintrag(ordner)["gesamt"] == 0, \
        "nach dem Aufnehmen gilt eine Datei weiter als ohne Eintrag"

    # ── (5) EIN ZWEITER LAUF LEGT KEINE DUBLETTEN AN. Auf archive.filepath
    # liegt ein UNIQUE; der Fall muss als "uebersprungen" gezaehlt werden,
    # nicht als Fehler und erst recht nicht als zweiter Eintrag.
    # Schon eingetragen heisst: sie stehen nicht mehr in der Fundliste. Das
    # ist kein Fehler am Code, aber es muss BENANNT werden — sonst waehlt der
    # Betreiber fuenf aus, drei landen im Archiv und nichts sagt warum.
    b2 = A.uebernehmen(ordner, ["neu_eins.mp4",
                                _os.path.join("unterordner", "neu_zwei.mkv")])
    assert b2["aufgenommen"] == 0 and b2["fehler"] == 2, b2
    assert all("steht nicht in der Fundliste" in m for m in b2["meldungen"]), b2
    with A.db_conn() as conn:
        n = conn.execute("SELECT count(*) AS n FROM archive").fetchone()["n"]
    assert n == 3, "die Archivtabelle hat %d Zeilen statt 3" % n

    # ── (6) EINE DATEI AUSSERHALB DES ORDNERS KOMMT NICHT HINEIN — und zwar
    # nicht, weil ein Riegel sie abweist, sondern weil aus der Anfrage
    # ueberhaupt kein Pfad mehr in eine Pfadoperation laeuft. `uebernehmen`
    # scannt selbst; die Namen sind ein Filter per Zeichenketten-Vergleich.
    #
    # Die erste Fassung reichte Pfade herein und riegelte mit
    # nc.sicherpfad.unter() ab. Das war dicht — dieser Vertrag fing den
    # `../`-Ausbruch —, aber CodeQL meldete zwei High-Severity-Befunde
    # "Uncontrolled data used in path expression" auf os.path.isfile und
    # os.path.getsize, weil die Datenflussanalyse den Riegel nicht sieht.
    # CLAUDE.md hat fuer genau diesen Fall eine Regel (W98 / recordings-join):
    # den Pfad gar nicht erst aus Fremdeingabe bauen.
    #
    # Geprueft wird deshalb die staerkere Aussage: kein Name, wie boese auch
    # immer, bringt eine Datei von aussen ins Archiv.
    aussen = _os.path.join(heim, "fremd.mp4")
    P.attrappe(aussen, 1024)
    boese_namen = [aussen,
                   _os.path.join("..", "fremd.mp4"),
                   "../fremd.mp4",
                   "/etc/passwd",
                   _os.path.join("..", "..", "etc", "passwd")]
    b3 = A.uebernehmen(ordner, boese_namen)
    assert b3["aufgenommen"] == 0, b3
    # Gezaehlt wird je VERSCHIEDENER Name: die Auswahl ist eine Menge, und
    # os.path.join("..", "fremd.mp4") ist auf POSIX woertlich "../fremd.mp4".
    assert b3["fehler"] == len(set(boese_namen)), b3
    assert all("Fundliste" in m for m in b3["meldungen"]), b3["meldungen"]
    with A.db_conn() as conn:
        pfade_in_db = [r["filepath"] for r in
                       conn.execute("SELECT filepath FROM archive").fetchall()]
    for pf in pfade_in_db:
        assert _os.path.abspath(pf).startswith(_os.path.abspath(ordner) + _os.sep), \
            "ein Pfad ausserhalb des Archivordners steht in der Tabelle: %s" % pf

    # ── (7) DER DECKEL MELDET SICH SELBST. Ein gekuerztes Ergebnis, das
    # seine Unvollstaendigkeit verschweigt, ist schlimmer als keines.
    for i in range(5):
        datei("deckel_%d.mp4" % i)
    e2 = A.finde_ohne_eintrag(ordner, max_treffer=2)
    assert len(e2["gefunden"]) == 2 and e2["gesamt"] == 5 and e2["gedeckelt"], e2

    # ── (7b) EINE DATEI, DIE SICH NICHT LESEN LAESST, VERSCHWINDET NICHT
    # STILL AUS DER LISTE. Der harmlose Fall ist "zwischen listdir und stat
    # geloescht"; derselbe Zweig faengt aber ein Rechteproblem, und dann
    # sucht der Betreiber dauerhaft eine Aufnahme, die er auf der Platte
    # sieht. Die Zahl gehoert in die Antwort, nicht nur ins Log.
    from nc import meldetakt as _M
    echt_stat = A.os.stat
    def _stat_faellt(pfad, *a, **k):
        if str(pfad).endswith("nicht_lesbar.mp4"):
            raise PermissionError(13, "Permission denied")
        return echt_stat(pfad, *a, **k)
    datei("nicht_lesbar.mp4")
    _M.zuruecksetzen("archiv-scan")
    A.os.stat = _stat_faellt
    try:
        e4 = A.finde_ohne_eintrag(ordner)
    finally:
        A.os.stat = echt_stat
        _M.zuruecksetzen("archiv-scan")
    assert e4["unlesbar"] == 1, \
        "eine nicht lesbare Datei wird nicht gezaehlt: %s" % e4
    assert "nicht_lesbar.mp4" not in [x["name"] for x in e4["gefunden"]]
    assert e4["gesamt"] == len(e4["gefunden"]), \
        "die nicht lesbare Datei zaehlt trotzdem als Fund: %s" % e4

    # ── (8) EIN FEHLENDER ORDNER WIRFT NICHT, ER SAGT ES.
    e3 = A.finde_ohne_eintrag(_os.path.join(heim, "gibtsnicht"))
    assert not e3["ok"] and e3["grund"] == "verzeichnis_fehlt", e3

    # ── (8b) DIE FEHLERPFADE DES AUFNEHMENS, EINZELN. Sie sind neu in
    # dieser Welle, und ein ungeprueftes "hier koennte etwas fehlen" ist
    # genau die Art Zeile, die nur behauptet zu helfen (W89).

    # (a) Kein Scan-Verzeichnis -> jeder gewuenschte Name zaehlt als Fehler,
    # mit Grund. Stumm eine leere Bilanz zu melden hiesse "nichts zu tun".
    b4 = A.uebernehmen(_os.path.join(heim, "gibtsnicht"), ["neu_eins.mp4"])
    assert b4["fehler"] == 1 and b4["aufgenommen"] == 0, b4
    assert any("Scan-Verzeichnis fehlt" in m for m in b4["meldungen"]), b4

    # (b) Die Datei ist zwischen Anzeige und Knopfdruck verschwunden. Das ist
    # der Normalfall bei einem Deck, das Minuten offen steht — und der Grund,
    # warum `uebernehmen` selbst neu scannt statt der Anfrage zu glauben.
    weg = datei("verschwindet.mp4")
    assert A.finde_ohne_eintrag(ordner)["gesamt"] > 0
    _os.remove(weg)
    b5 = A.uebernehmen(ordner, ["verschwindet.mp4"])
    assert b5["fehler"] == 1 and b5["aufgenommen"] == 0, b5
    assert any("Fundliste" in m for m in b5["meldungen"]), b5

    # (c) Und der INSERT selbst faellt. Der haeufigste echte Fall ist die
    # UNIQUE-Kollision auf archive.filepath; entscheidend ist, dass EINE
    # gescheiterte Datei die anderen nicht mitnimmt.
    datei("heikel.mp4")
    datei("harmlos.mp4")
    echt_add = A.add_archive_entry
    def _add_faellt(**kw):
        if kw.get("filepath", "").endswith("heikel.mp4"):
            raise RuntimeError("UNIQUE constraint failed: archive.filepath")
        return echt_add(**kw)
    A.add_archive_entry = _add_faellt
    try:
        b6 = A.uebernehmen(ordner, ["heikel.mp4", "harmlos.mp4"])
    finally:
        A.add_archive_entry = echt_add
    assert b6["fehler"] == 1 and b6["aufgenommen"] == 1, \
        "eine gescheiterte Datei nimmt die anderen mit: %s" % b6
    assert any("heikel.mp4" in m and "UNIQUE" in m for m in b6["meldungen"]), b6

    # (d) UND DER DECKEL GILT BEIM AUFNEHMEN NICHT. `finde_ohne_eintrag`
    # deckelt die ANZEIGE bei 2000; wuerde `uebernehmen` denselben Deckel
    # erben, nahme "alles aufnehmen" bei 2001 Dateien stillschweigend 2000
    # und meldete Erfolg.
    import inspect as _insp
    quelle_u = _insp.getsource(A.uebernehmen)
    assert "max_treffer=None" in quelle_u, \
        "uebernehmen() erbt den Anzeige-Deckel — dann nimmt 'alles' nicht alles"

    # ── (9) UND DIE ROUTEN, GEFAHREN STATT GELESEN.
    app = _Flask(__name__)
    app.register_blueprint(_rt.bp)
    regeln = {str(r.rule) for r in app.url_map.iter_rules()}
    for want in ("/api/archive/scan", "/api/archive/scan/adopt"):
        assert want in regeln, "Route fehlt oder umbenannt: %s" % want
    kl = app.test_client()

    # Wieviele noch offen sind, rechnet der Vertrag aus dem Modul statt eine
    # Zahl zu verdrahten: die Faelle oben legen je nach Ausgang Dateien an
    # und nehmen sie auf: eine feste Zahl waere ein Anker, der bei jeder
    # zusaetzlichen Probe kippt, ohne dass am Code etwas falsch ist (die
    # Lehre aus den 34 Fenstern in test_restream, CLAUDE.md).
    offen = A.finde_ohne_eintrag(ordner)["gesamt"]
    assert offen > 0, "es ist nichts mehr offen — der Vertrag prueft dann nichts"
    r = kl.get("/api/archive/scan")
    d = r.get_json()
    assert r.status_code == 200 and d["ok"] and d["gesamt"] == offen, (offen, d)
    assert d["scan_root"] == _os.path.abspath(ordner), d
    assert d["unlesbar"] == 0, d

    # (9b) DIE ANTWORT ENTHAELT KEINEN SERVERPFAD. Das Deck waehlt ueber den
    # relativen Namen aus; den vollen Pfad braucht es nicht, und was nicht
    # hinausgeht, kann auch nicht zurueckgeschickt werden.
    assert all("rel" in x for x in d["gefunden"]), d["gefunden"][:1]

    # (9c) Der Sammel-Knopf scannt SELBST neu, statt der Anfrage zu glauben.
    r = kl.post("/api/archive/scan/adopt", json={"alle": True})
    d = r.get_json()
    assert r.status_code == 200 and d["ok"] and d["aufgenommen"] == offen, (offen, d)
    assert kl.get("/api/archive/scan").get_json()["gesamt"] == 0

    # (9d) Leere Auswahl ist eine 400, kein stiller Erfolg.
    assert kl.post("/api/archive/scan/adopt", json={"namen": []}).status_code == 400
    assert kl.post("/api/archive/scan/adopt", json={"namen": "nein"}).status_code == 400

    # (9e) UND DER 503-FALL AM STUECK: die Route muss "ich weiss es nicht"
    # von "kaputt" unterscheiden, sonst liest der Betreiber einen Defekt,
    # wo nur die Datenbank gerade belegt war.
    A.db_conn = lambda *a, **k: _Kaputt()
    try:
        r = kl.get("/api/archive/scan")
        assert r.status_code == 503, (r.status_code, r.get_json())
        r = kl.post("/api/archive/scan/adopt", json={"alle": True})
        assert r.status_code == 503, (r.status_code, r.get_json())
        text = str(r.get_json())
        assert heim not in text, "die Antwort spiegelt einen Serverpfad: %s" % text
    finally:
        A.db_conn = echt_conn

    # (9f) EIN FEHLENDER ORDNER IST EINE 404 MIT ABHILFE, keine leere Liste.
    # Eine leere Liste hiesse "alles eingetragen" — die beruhigendste
    # moegliche Falschaussage.
    _ncctx.configure(cfg={"ARCHIVE_DIR": ordner,
                          "_MANUAL_ARCHIVE_DIR": _os.path.join(heim, "weg")},
                     log=_logging.getLogger("TikTokBot"))
    for weg_, last_ in (("GET", None), ("POST", {"alle": True})):
        r = (kl.get("/api/archive/scan") if weg_ == "GET"
             else kl.post("/api/archive/scan/adopt", json=last_))
        assert r.status_code == 404, (weg_, r.status_code, r.get_json())
        assert "ARCHIVE_DIR" in str(r.get_json()["error"]), r.get_json()
    _ncctx.configure(cfg={"ARCHIVE_DIR": ordner, "_MANUAL_ARCHIVE_DIR": ordner},
                     log=_logging.getLogger("TikTokBot"))

    # (9g) UND DER AUFFANG FUER DAS UNERWARTETE. 500 mit gesaeuberter
    # Meldung, nicht ein Flask-Stacktrace mit Serverpfaden darin.
    #
    # Jede Route bekommt ihre EIGENE Naht: die Scan-Route ruft
    # finde_ohne_eintrag, die Adopt-Route ruft uebernehmen (und das scannt
    # intern selbst). Beide ueber denselben Namen zu brechen liess die zweite
    # Probe ins Leere laufen — sie antwortete 200, und der Vertrag hielt das
    # fuer einen Erfolg des Auffangs.
    def _wirft(*a, **k):
        raise RuntimeError("etwas ganz anderes in %s" % heim)
    for name, weg, last in (("finde_ohne_eintrag", "GET", None),
                            ("uebernehmen", "POST", {"alle": True})):
        echt = getattr(_rt, name)
        setattr(_rt, name, _wirft)
        try:
            r = (kl.get("/api/archive/scan") if weg == "GET"
                 else kl.post("/api/archive/scan/adopt", json=last))
            assert r.status_code == 500, (name, r.status_code, r.get_json())
            assert heim not in str(r.get_json()), \
                "die 500 spiegelt einen Serverpfad: %s" % r.get_json()
        finally:
            setattr(_rt, name, echt)

    ok("W98: der Ordnerscan findet Video-Dateien ohne Archiv-Eintrag")
    ok("W98: Pfade werden auf beiden Seiten normalisiert — keine Scheinfunde")
    ok("W98: ohne lesbare Datenbank bricht er ab, statt alles als neu zu melden")
    ok("W98: das Aufnehmen legt nur Zeilen an und erzeugt keine Dubletten")
    ok("W98: eine Datei ausserhalb des Ordners kommt nicht ins Archiv")
    ok("W98: eine nicht lesbare Datei wird gezaehlt und gemeldet, nicht verschluckt")
    ok("W98: eine gescheiterte Datei nimmt die anderen nicht mit")
    ok("W98: ein fehlender Ordner ist eine 404 mit Abhilfe, keine leere Liste")
    ok("W98: beide Routen gefahren, 503 bleibt von 500 unterscheidbar")


def _test_v42_w99_env_vorlage_kennt_auch_die_listen_namen():
    """Acht Variablen fehlten in der Vorlage, darunter ALLE sechs Wallets.

    Der Betreiber am 30.09.: „Website im Website Ordner rendert nicht richtig.
    Es fehlen saemtliche krypto wallet Adressen."

    `tools/gen_env_example.py` sucht nach woertlichem `os.getenv("NAME")`.
    `nc/crypto.py` liest aber

        for coin, label, env in _COINS:
            a = os.getenv(env, "")

    — der Name steht in einer Schleifenvariablen und war damit unsichtbar.
    `.env.example` wird aber als Vorlage ALLER Variablen gefuehrt; wer seine
    .env daraus neu aufbaut, verliert saemtliche Spendenadressen, und die
    oeffentliche Seite versteckt den Block danach STILL.

    Es ist der dritte Fall derselben Klasse (nach `_BERECHNET` fuer gerechnete
    Vorgaben und `_ohne_kommentar` fuer '#' im Default). Deshalb prueft dieser
    Vertrag nicht die sechs Namen, sondern den WEG: jede Lesestelle wird
    erreicht, und eine, die es nicht ist, faellt auf.
    """
    import io as _io
    import os as _os
    import sys as _sys

    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    if wurzel not in _sys.path:
        _sys.path.insert(0, wurzel)
    _sys.path.insert(0, _os.path.join(wurzel, "tools"))
    try:
        import gen_env_example as G
    finally:
        _sys.path.pop(0)

    from nc import crypto as C

    # ── (1) DIE SECHS NAMEN SIND AUFLOESBAR — aus der Liste, nicht aus dem
    # Aufruf. Geprueft wird am echten Modul, nicht an einer Attrappe.
    quelle = _io.open(_os.path.join(wurzel, "nc", "crypto.py"), encoding="utf-8").read()
    namen, luecken = G.dynamische_namen("nc/crypto.py", quelle)
    assert not luecken, "nc/crypto.py hat eine unaufgeloeste Lesestelle: %s" % luecken
    assert set(C.erwartete_namen()) <= namen, \
        "der Generator findet die Wallet-Namen nicht: %s fehlt" % (
            set(C.erwartete_namen()) - namen)
    assert len(C.erwartete_namen()) == 6, C.erwartete_namen()

    # ── (2) UND SIE STEHEN AUCH WIRKLICH IN DER VORLAGE. Der Generator kann
    # sie finden und sie trotzdem nicht schreiben — das ist zweierlei.
    vorlage = _io.open(_os.path.join(wurzel, ".env.example"), encoding="utf-8").read()
    for name in C.erwartete_namen():
        assert ("\n%s=" % name) in vorlage or ("\n# %s=" % name) in vorlage, \
            "%s fehlt in .env.example — genau der Befund vom 30.09." % name

    # ── (3) EIN PARAMETER IST KEINE LUECKE. nc/envnum und nc/cfgnorm bekommen
    # den Namen vom Aufrufer; dort steht das Literal und die alten Muster
    # sehen es. Wuerde der Pruefer die mitmelden, waere er unbrauchbar —
    # 15 Fehlalarme, und die Sperre waere in einer Woche abgeschaltet.
    for datei in ("nc/envnum.py", "nc/cfgnorm.py", "nc/dashauth.py"):
        q = _io.open(_os.path.join(wurzel, datei), encoding="utf-8").read()
        _n, l = G.dynamische_namen(datei, q)
        assert not l, "%s wird faelschlich als Luecke gemeldet: %s" % (datei, l)

    # ── (4) DER GANZE BESTAND IST LUECKENFREI — und DAS ist die Sperre.
    # Ein neuer Fall dieser Klasse bricht den Generator ab (Exitcode 2), statt
    # eine Variable lautlos fallen zu lassen.
    G.LUECKEN.clear()
    try:
        erkannt = G.collect()
        assert not G.LUECKEN, \
            "unaufgeloeste env-Lesestellen im Bestand: %s" % G.LUECKEN[:5]
        assert len(erkannt) >= 538, "nur %d Variablen erkannt" % len(erkannt)
        # ── (4b) UND DIE VORLAGE IST WIRKLICH AKTUELL. Das ist genau, was
        # `gen_env_example.py --check` tut — hier im Vertrag gefahren, damit
        # es nicht davon abhaengt, ob jemand das Werkzeug aufruft. Eine Sperre,
        # die niemand faehrt, ist keine.
        assert G.render(erkannt) == vorlage, \
            "`.env.example` ist veraltet — python3 tools/gen_env_example.py"
    finally:
        G.LUECKEN.clear()

    # ── (5) DIE PRAEFIX-FAMILIEN SIND EINE ENTSCHEIDUNG, KEIN VERSEHEN.
    # BRAIN_ACT_<REGEL> und BRAIN_AGENT_<NAME> entstehen erst zur Laufzeit;
    # sie stehen als Muster in der Vorlage und namentlich in der Ausnahme.
    assert len(G.DYNAMISCH_ERLAUBT) == 2, G.DYNAMISCH_ERLAUBT
    for (_datei, praefix), (platz, vorgabe, grund) in G.DYNAMISCH_ERLAUBT.items():
        assert grund.strip(), "eine Ausnahme ohne Begruendung ist keine"
        assert platz.startswith("<") and vorgabe != "", (platz, vorgabe)
        # Die Vorlage bekommt diese Zeile AUS demselben Dict — Ausnahme und
        # Dokumentation sind dieselbe Tatsache. Beim ersten Anlauf waren sie
        # zwei: BRAIN_ACT_ stand (durch zwei konkrete Regeln) drin,
        # BRAIN_AGENT_ gar nicht, und von den Agent-Schaltern konnte niemand
        # wissen. Der Vertrag hat das gemeldet, nicht das Nachdenken.
        assert ("# %s%s=%s" % (praefix, platz, vorgabe)) in vorlage, \
            "%s ist ausgenommen, steht aber nicht als Muster in der Vorlage" % praefix
        assert grund.split(".")[0] in vorlage.replace("\n# ", " ").replace("\n", " "), \
            "das Muster %s steht ohne Begruendung in der Vorlage" % praefix

    # ── (6) UND EINE ERFUNDENE LUECKE WIRD WIRKLICH GEMELDET. Ohne diese
    # Probe waere (4) auch auf einem Pruefer gruen, der nie etwas findet.
    boese = ("import os\n"
             "def f(x):\n"
             "    schluessel = 'A' + x\n"
             "    return os.getenv(schluessel, '')\n")
    _n2, l2 = G.dynamische_namen("erfunden.py", boese)
    assert l2 and l2[0][0] == 4, \
        "eine nicht aufloesbare Lesestelle wird NICHT gemeldet: %s" % l2

    ok("W99: der Generator loest env-Namen auch aus Listen auf")
    ok("W99: alle sechs Wallet-Namen stehen in .env.example")
    ok("W99: Durchleitungs-Helfer gelten nicht als Luecke (keine 15 Fehlalarme)")
    ok("W99: der Bestand ist rundum aufgeloest — ein neuer Fall bricht ab")
    ok("W99: die zwei Praefix-Familien sind begruendet und dokumentiert")


def _test_v42_w99_leerer_spendenblock_sagt_warum():
    """Eine leere Adressliste war nicht von einem Ausfall zu unterscheiden.

    Drei stille Schichten hintereinander: `except Exception:
    stats["crypto"] = {"addresses": []}` im Server, `catch(e){}` in der Seite,
    und ein `crypto-wrap`, das im HTML `hidden` ist und nur bei Treffern
    sichtbar wird. Ergebnis: der Block verschwindet, und niemand kann sagen,
    ob nichts konfiguriert ist oder etwas kaputt.
    """
    import io as _io
    import os as _os
    from nc import crypto as C

    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    alt = {n: _os.environ.get(n) for n in C.erwartete_namen()}
    try:
        # ── (1) OHNE ADRESSE: leere Liste MIT Grund und mit den Namen.
        for n in C.erwartete_namen():
            _os.environ.pop(n, None)
        leer = C.snapshot(fetch_live=False)
        assert leer["addresses"] == [], leer
        assert leer["grund"] == "keine_adresse_konfiguriert", leer
        assert set(leer["gesucht"]) == set(C.erwartete_namen()), leer
        assert "DONATION_BTC_ADDRESS" in leer["gesucht"], \
            "die Meldung nennt die gesuchten Namen nicht — dasselbe wie ein " \
            "blankes 'HTTP 403'"

        # ── (2) MIT ADRESSE: kein Grund, kein Rauschen, und ein QR dabei.
        _os.environ["DONATION_BTC_ADDRESS"] = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4"
        voll = C.snapshot(fetch_live=False)
        assert len(voll["addresses"]) == 1 and voll["grund"] == "", voll
        # v4.2-W101: hier stand `voll["gesucht"] == []` — „bei Treffern
        # braucht niemand die Namen". Das war falsch, sobald eine
        # TEILkonfiguration im Spiel ist, und das ist der Normalfall: wer nur
        # Bitcoin annimmt, hat fuenf leere Namen, und eine Konfiguration mit
        # einer von sechs Adressen sah damit genauso aus wie eine
        # vollstaendige. `gesucht` traegt jetzt immer alle sechs, `fehlend`
        # die leeren. Geprueft wird deshalb die Aussage statt der Schreibweise.
        assert set(voll["gesucht"]) == set(C.erwartete_namen()), voll["gesucht"]
        assert voll["fehlend"] == [n for n in C.erwartete_namen()
                                   if n != "DONATION_BTC_ADDRESS"], voll["fehlend"]
        a = voll["addresses"][0]
        assert a["coin"] == "btc" and a["address"].startswith("bc1q")
        assert a["qr"].lstrip().startswith("<svg"), \
            "ohne QR ist die Kachel leer — segno fehlt oder wirft"

        # ── (2b) UND DER QR TRAEGT BIP21, nicht die rohe Adresse: ein Scanner
        # soll die Wallet oeffnen, nicht Text anzeigen.
        assert "bitcoin:" in C._qrsvg.qr_svg("bitcoin:" + a["address"]) or True
        roh = C._qrsvg.qr_svg(a["address"])
        assert roh != a["qr"], \
            "der BTC-QR ist derselbe wie fuer die rohe Adresse — BIP21 fehlt"
    finally:
        for n, v in alt.items():
            if v is None:
                _os.environ.pop(n, None)
            else:
                _os.environ[n] = v

    # ── (3) DER SERVER MELDET DEN LEEREN FALL — mit den Namen im Text.
    src = _io.open(_os.path.join(wurzel, "bot.py"), encoding="utf-8").read()
    # rumpf_ab statt eines Fensters fester Laenge: CLAUDE.md nennt die feste
    # Zahl namentlich als Bruchstelle, und tools/vertragscheck.py sperrt neue.
    # Der erste Anlauf dieses Vertrags trug eines, und die Sperre hat es
    # gemeldet — samt dem Kommentar, der das Muster woertlich zitierte.
    i = src.index('stats["crypto"] = _nc_crypto.snapshot')
    rumpf = rumpf_ab(src, i)
    assert "_nc_crypto.erwartete_namen()" in rumpf, \
        "die Meldung nennt die gesuchten env-Namen nicht"
    assert 'melden(\n                "crypto-leer"' in rumpf or '"crypto-leer"' in rumpf, \
        "der leere Fall laeuft ungedrosselt oder gar nicht"
    assert 'stats["crypto"] = {"addresses": []}' not in rumpf, \
        "der stille Auffang ist zurueck"

    # ── (4) UND DIE SEITE VERSTECKT DEN BLOCK NICHT MEHR STUMM, wenn das
    # Lagebild fehlt. W88 hat das fuer die zweite Tafel gelernt; hier war es
    # derselbe Fehler eine Kachel weiter.
    seite = _io.open(_os.path.join(wurzel, "website", "lafap_index.html"),
                     encoding="utf-8").read()
    assert "keine_adresse_konfiguriert" in seite, \
        "die Seite unterscheidet 'nichts konfiguriert' nicht von 'Ausfall'"
    assert "nicht abrufbar" in seite, "die Seite sagt bei Ausfall nichts"
    # Der Anker sitzt am KRYPTO-Block und nicht an einem beliebigen
    # `}catch(e){}` — es gibt sechs davon in der Datei, und der erste Anlauf
    # dieses Vertrags hing am PayPal-Block. Ein Vertrag, der die falsche
    # Stelle prueft, ist gruen ohne Aussage.
    kb = seite.index("// v4.0-W94: Krypto-Spendenadressen")
    ke = seite.index("// v4.0-W72: Plattform-Chips", kb)
    krypto = seite[kb:ke]
    # Geprueft wird der AEUSSERE Auffang, also das Ende des Blocks. Innen
    # steht ein berechtigt stiller: der Klemmbrett-Rueckfall
    # (`document.execCommand('copy')`) — schlaegt der fehl, bestaetigt der
    # Knopf eben nicht, und das ist bedeutungslos. Eine Zusicherung, die
    # beide in einen Topf wirft, ist zu grob und meldet Fehlalarm.
    assert not krypto.rstrip().endswith("}catch(e){}"), \
        "der stille catch um den Krypto-Block ist zurueck"
    assert "konnten nicht angezeigt werden" in krypto, \
        "ein Fehler beim Rendern sieht weiter wie 'nichts konfiguriert' aus"

    # ── (5) UND stats.json GEHOERT NIE INS ARCHIV. Sie entsteht zur Laufzeit;
    # mitgepackt ueberschreibt der Deploy das LIVE-Lagebild mit dem Stand des
    # Entwicklungsrechners — dieselbe Falle wie AUSLIEFERUNG.json in W91.
    bauer = _io.open(_os.path.join(wurzel, "tools", "build_release.py"),
                     encoding="utf-8").read()
    # Die ZEILE, nicht ein Byte-Fenster: `AUS = {...}` ist eine einzelne
    # Zuweisung, und eine feste Laenge waere hier genau die Bruchstelle, die
    # vertragscheck sperrt.
    aus_zeile = next(z for z in bauer.splitlines() if z.startswith("AUS = {"))
    assert "stats.json" in aus_zeile, \
        "stats.json faehrt im Auslieferungsarchiv mit: %s" % aus_zeile
    assert "news.json" not in aus_zeile, \
        "news.json ist Inhalt und muss MITfahren: %s" % aus_zeile

    ok("W99: ein leerer Spendenblock nennt Grund und die gesuchten env-Namen")
    ok("W99: mit Adresse kommt ein BIP21-QR, nicht die rohe Adresse")
    ok("W99: die Seite unterscheidet 'nichts konfiguriert' von 'nicht abrufbar'")
    ok("W99: stats.json faehrt nicht im Archiv mit")


def _test_v42_w100_installer_liefert_kopierbare_zeilen():
    """Der Bericht druckte einen Befehl, der nicht laufen kann.

    Aus einer echten Installation (tools/installer.sh --unattended):

        Selbsttest  /home/user/ncbuild/.venv/bin/python/bot.py --selfcheck

    Ein Schraegstrich statt eines Leerzeichens — und genau diese Zeile kopiert
    der Betreiber aus ~/nightcrawler-installation.txt. Dieselbe Klasse wie die
    Dashboard-Adresse in W93: die Zeile mit der vollstaendigen Angabe ist die,
    die man kopiert, und sie war falsch.
    """
    import io as _io
    import os as _os
    import subprocess as _sp

    wurzel = _os.path.dirname(_os.path.abspath(__file__))
    inst = _io.open(_os.path.join(wurzel, "tools", "installer.sh"),
                    encoding="utf-8").read()

    # ── (1) DER BEFEHL IM BERICHT. Geprueft wird die printf-Vorlage: zwischen
    # dem Interpreter und bot.py muss ein LEERZEICHEN stehen.
    # v4.2-W123: die Notiz laeuft ueber nz (uebersetzt) statt printf — der
    # Anker sucht beide Formen. Und weil die Vorlage jetzt ein Schluessel ist,
    # gilt dieselbe Zusicherung fuer JEDE Uebersetzung: der Fehler aus W100
    # koennte sonst in der englischen Notiz still wiederkommen.
    zeile = next(z for z in inst.splitlines()
                 if "Selbsttest" in z and ("printf" in z or z.lstrip().startswith("nz ")))
    assert "%s bot.py --selfcheck" in zeile, \
        "der Bericht druckt den Selbsttest-Befehl falsch: %s" % zeile.strip()
    assert "%s/bot.py" not in zeile, \
        "Schraegstrich statt Leerzeichen — die Zeile kann nicht laufen"
    for _z in _io.open(_os.path.join(wurzel, "locales", "tools.en.tsv"), encoding="utf-8"):
        if _z.startswith("  Selbsttest  %s"):
            assert "%s bot.py --selfcheck" in _z.split("\t", 1)[1], \
                "die Uebersetzung druckt den Selbsttest-Befehl falsch: %r" % _z

    # ── (2) UND SIE IST SYNTAKTISCH GUELTIG. Ein Installer, der nicht parst,
    # ist schlimmer als keiner: er bricht mitten im Eingriff ab.
    r = _sp.run(["bash", "-n", _os.path.join(wurzel, "tools", "installer.sh")],
                capture_output=True, text=True)
    assert r.returncode == 0, "installer.sh parst nicht: %s" % r.stderr[:300]

    # ── (3) EINE Ausschlussliste, von rsync UND tar benutzt. Vorher stand sie
    # zweimal da und wich von der des Auslieferungsarchivs ab; gemessen an
    # einer Installation aus einem Arbeitsbaum wanderten .coverage,
    # .pytest_cache/, .ruff_cache/ und ein 4-MB-Release-ZIP mit. Dieselbe
    # Lehre wie bei den zwei Ordner-Aufloesungen in W98.
    assert "AUS_KOPIE=(" in inst, "die gemeinsame Ausschlussliste fehlt"
    i = inst.index("AUS_KOPIE=(")
    liste = inst[i:inst.index(")", i)]
    for muster in ("'.git'", "'.venv'", "'.env'", "'*.db'", "'recordings'",
                   "'logs'", "'__pycache__'", "'.pytest_cache'",
                   "'.ruff_cache'", "'.coverage'", "'*.zip'",
                   "'AUSLIEFERUNG.json'"):
        assert muster in liste, "%s fehlt in der Ausschlussliste" % muster
    # Beide Wege ziehen daraus — und keiner fuehrt noch eine eigene Liste.
    kopierteil = inst[inst.index("AUS_KOPIE=("):inst.index("gut \"Quelltext liegt in")]
    assert "${AUS_KOPIE[@]}" in kopierteil
    assert kopierteil.count("${AUS_KOPIE[@]}") == 2, \
        "rsync und tar muessen BEIDE aus derselben Liste lesen"
    assert "--exclude '.git'" not in kopierteil and "--exclude='.git'" not in kopierteil, \
        "eine zweite, handgeschriebene Liste ist zurueck"

    # ── (4) UND DIE STREUDATEI IST WEG. "-- No entries --" lag in der Wurzel
    # und IM GIT; der Installer kopiert den ganzen Baum, also landete sie in
    # jeder Installation. Inhalt: ein curl-Aufruf der Totmann-Meldung von
    # einem Fehllauf am 27.08. — Muell, aber Muell mit einem Token darin.
    assert not _os.path.exists(_os.path.join(wurzel, "-- No entries --")), \
        "die Streudatei '-- No entries --' ist zurueck"
    verfolgt = _sp.run(["git", "-C", wurzel, "ls-files", "-z"],
                       capture_output=True, text=True)
    if verfolgt.returncode == 0:
        namen = [n for n in verfolgt.stdout.split("\0") if n]
        assert "-- No entries --" not in namen, \
            "die Streudatei steht wieder im Git"

    ok("W100: der Bericht druckt einen Selbsttest-Befehl, der laeuft")
    ok("W100: eine Ausschlussliste fuer rsync und tar, Caches bleiben draussen")
    ok("W100: die Streudatei '-- No entries --' ist aus dem Bestand")


def _test_v42_w100_cookiebezug_nennt_die_abhilfe():
    """„<urlopen error Tunnel connection failed: 403 Forbidden>" — und dann?

    Der Gast-Abruf ist der Weg, mit dem sich der Bot seine rotierenden
    Anti-Bot-Tokens selbst holt. Scheitert er, stand im Log nur der Wortlaut
    von urllib: richtig und nutzlos, genau wie ein blankes „HTTP 403" (W81).
    Der Betreiber sieht daran nicht, dass sein Egress tiktok.com nicht
    durchlaesst und dass es dafuer RECORD_PROXY gibt.
    """
    import io as _io
    import logging as _logging
    import os as _os
    import pruefhilfen as P
    from nc import cookieholen as H

    # ── (1) ES GIBT EINE ABHILFE JE WEG, UND SIE SAGT ETWAS.
    assert set(H.ABHILFE) == {"gast", "browser"}, sorted(H.ABHILFE)
    assert "tiktok.com" in H.ABHILFE["gast"] and "RECORD_PROXY" in H.ABHILFE["gast"], \
        "die Gast-Abhilfe nennt weder die Probe noch den Ausweg"
    assert "Browser-Profil" in H.ABHILFE["browser"], H.ABHILFE["browser"]
    for weg, text in H.ABHILFE.items():
        assert text.startswith("Abhilfe:") and len(text) > 80, (weg, text[:60])

    # ── (2) UND SIE STEHT IM BERICHT UND IN DER ZEILE. Ein Text, den niemand
    # ausgibt, ist dasselbe wie keiner.
    heim = P.verzeichnis()
    ziel = _os.path.join(heim, "cookies.txt")

    class Sammler(_logging.Handler):
        def __init__(self):
            super().__init__()
            self.zeilen = []

        def emit(self, satz):
            self.zeilen.append(self.format(satz))

    prot = _logging.getLogger("w100_cookie")
    prot.propagate = False
    prot.setLevel(_logging.DEBUG)
    sam = Sammler()
    sam.setFormatter(_logging.Formatter("%(message)s"))
    prot.addHandler(sam)
    try:
        # Eine Adresse, die es nicht gibt: der Abruf MUSS scheitern, und zwar
        # ohne zu werfen — die Aufrufer sind eine Route, ein Telegram-Befehl
        # und eine Dauerschleife.
        b = H.aktualisiere(ziel, quelle="gast", timeout=2,
                           urls=["http://127.0.0.1:1/"],
                           domains=("127.0.0.1",), log=prot)
    finally:
        prot.removeHandler(sam)

    assert b["ok"] is False and b["error"], b
    assert b.get("abhilfe") == H.ABHILFE["gast"], \
        "der Bericht traegt die Abhilfe nicht: %s" % b.get("abhilfe")
    gemeldet = [z for z in sam.zeilen if "fehlgeschlagen" in z]
    assert gemeldet, "der Fehlschlag wurde nicht gemeldet: %s" % sam.zeilen
    assert "RECORD_PROXY" in gemeldet[-1], \
        "die Logzeile nennt die Abhilfe nicht: %s" % gemeldet[-1]
    assert not _os.path.exists(ziel), \
        "ein gescheiterter Abruf hat die Cookie-Datei angelegt"

    # ── (3) DER ERFOLGSFALL TRAEGT KEINE ABHILFE. Ein Hinweis, der immer da
    # steht, wird nicht gelesen.
    q = _io.open(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)),
                               "nc", "cookieholen.py"), encoding="utf-8").read()
    i = q.index('bericht["abhilfe"]')
    vorher = q[:i]
    assert vorher.rstrip().endswith('_nc_fehlertext.nach_aussen(e, "cookieholen.aktualisiere")'), \
        "die Abhilfe wird nicht nur im Fehlerzweig gesetzt"

    ok("W100: ein gescheiterter Cookie-Bezug nennt Probe und Ausweg")
    ok("W100: die Abhilfe steht im Bericht UND in der Logzeile")


def _test_v42_w105_stream_url_formen():
    """TikTok liefert die Pull-Adresse in drei Formen — wir lasen eine.

    Der Betreiber am 01.10.: „da sich die tiktok streams ja in hls Pullen
    lassen. Das selbe in mp4". Nachgesehen gegen `yt_dlp/extractor/tiktok.py`
    (TikTokLiveIE, Z1278-1356) statt gegen eine bequeme Eingabe — und zwar
    GENAU DESHALB, weil dieser Bestand denselben Fehler schon zweimal gemacht
    hat: `concat_cmd` begruendete sein `-safe 0` mit absoluten Pfaden, die die
    Liste nie trug (W101), und zwei Kommentare behaupteten „Nur der HTML-Weg
    traegt eine URL", was eine Aussage ueber die eigene Huelle war (W102).

    Was fehlte:
      * `stream_url.rtmp_pull_url` — bei yt-dlp ext=flv/protocol=https.
      * `stream_url.flv_pull_url` als WOERTERBUCH {Qualitaet: URL}. Wir haben
        es als Zeichenkette weitergereicht, und `nc.livefolge.hat_stream_url`
        fragt nur `bool(...)` — ein Woerterbuch ist wahr. Damit galt „URL
        vorhanden", und was in den ffmpeg-Aufruf ging, war keine.

    Dazu die Lehre aus B64, eine Ebene tiefer: im Woerterbuch steht der Codec
    in `flv_pull_url_params`, und HEVC-origin ist der Produktionsfehler vom
    2026-05-29 (ffmpeg demuxt bytevc1 im FLV-Container nicht → 0-Byte-Datei).
    Eine Auswahl, die im Woerterbuch blind origin nimmt, baut ihn nach.
    """
    import json as _json
    from nc import streamsel as S
    from nc.livefolge import hat_stream_url

    # ── (1) DER TYPRIEGEL, und seine Grenze ist NICHT erfunden: es ist die
    # Erlaubnisliste von yt-dlps `url_or_none` — des Werkzeugs, das
    # nachweislich an TikToks Live-Adressen herankommt. Zwei Entscheidungen
    # haengen daran, und ein selbstgebauter Riegel haette beide verfehlt.
    for gut in ("https://a/b.flv", "rtmp://a/b", "  https://a/b.m3u8  ",
                "RTMPS://A/B"):
        assert S._als_url(gut) == gut.strip(), gut
    # (a) OHNE Schema, protokollrelativ — gilt. Ein eigener Riegel auf
    # `"://" in u` haette das verworfen, und eine verworfene Adresse ist genau
    # das Fehlerbild dieser Welle: „live, aber keine Stream-URL".
    assert S._als_url("//cdn.tiktok.com/x.flv") == "//cdn.tiktok.com/x.flv"
    # (b) Es ist eine ERLAUBNISLISTE. Was hier durchkommt, geht als Eingabe in
    # ffmpeg/streamlink — ein `file://` aus einer fremden API hat dort nichts
    # zu suchen.
    for boese in ("file:///etc/passwd", "javascript:alert(1)", "data:,x"):
        assert S._als_url(boese) is None, boese
    for schlecht in ({"ld": "https://a/b"}, None, 7, "", "nicht-eine-url", []):
        assert S._als_url(schlecht) is None, repr(schlecht)

    # ── (2) DAS WOERTERBUCH. Der Rueckgabewert MUSS eine Zeichenkette sein —
    # das ist die Aussage, nicht bloss "irgendwas ist da".
    wb = {"flv_pull_url": {"ORIGION": "https://cdn/o.flv",
                           "HD1": "https://cdn/hd.flv"},
          "flv_pull_url_params": {"ORIGION": _json.dumps({"VCodec": "bytevc1"}),
                                  "HD1": _json.dumps({"VCodec": "h264"})}}
    r = S.extract_urls_from_streamurl_node(wb)
    assert isinstance(r["flv_url"], str), \
        "aus dem Woerterbuch kommt keine Zeichenkette: %r" % (r["flv_url"],)
    assert hat_stream_url(r), "das Woerterbuch liefert keine brauchbare URL"
    # H.264 vor HEVC, auch hier (B64).
    assert r["flv_url"] == "https://cdn/hd.flv", r
    assert r.get("vcodec") == "h264", r
    # Mit PREFER_H264=0 gilt die Qualitaet — ORIGION ist die beste.
    assert S.extract_urls_from_streamurl_node(
        wb, prefer_h264=False)["flv_url"] == "https://cdn/o.flv"

    # ── (3) DIE UMKEHRUNG, und sie ist der eigentliche Befund: VOR W105 waere
    # `flv_url` hier das Woerterbuch selbst gewesen und `hat_stream_url` wahr.
    # Kein Weg darf etwas durchlassen, was keine Zeichenkette ist.
    for form in ({"flv_pull_url": {"ld": "https://a/b.flv"}},
                 {"hls_pull_url": {"ld": "https://a/b.m3u8"}},
                 {"flv_pull_url": {}},
                 {"liveCoreSDKData": {"pull_data": {"stream_data": _json.dumps(
                     {"data": {"origin": {"main": {"hls": {"x": "y"},
                                                   "flv": None}}}})}}}):
        erg = S.extract_urls_from_streamurl_node(form)
        if erg is None:
            continue
        for schluessel in ("hls_url", "flv_url"):
            wert = erg.get(schluessel)
            assert wert is None or isinstance(wert, str), (form, erg)

    # ── (4) rtmp_pull_url, die dritte Form. Als FLV, weil es derselbe
    # Container ist — und als LETZTE, weil sie keine Qualitaet mitbringt.
    assert S.extract_urls_from_streamurl_node(
        {"rtmp_pull_url": "rtmp://push/live"})["flv_url"] == "rtmp://push/live"
    vorrang = S.extract_urls_from_streamurl_node(
        {"flv_pull_url": "https://cdn/a.flv", "rtmp_pull_url": "rtmp://b"})
    assert vorrang["flv_url"] == "https://cdn/a.flv", vorrang

    # ── (5) REGRESSION. Die gewoehnliche Form muss bitgenau bleiben.
    assert S.extract_urls_from_streamurl_node(
        {"hls_pull_url": "https://cdn/a.m3u8",
         "flv_pull_url": "https://cdn/a.flv"}) == {
            "hls_url": "https://cdn/a.m3u8", "flv_url": "https://cdn/a.flv"}

    # ── (6) Und der Kopf des Moduls darf nicht mehr „verbatim" behaupten.
    # Ein Modul, das „bitgenau wie vorher" sagt und es nicht ist, zeigt bei
    # der naechsten Fehlersuche in die falsche Richtung.
    kopf = (S.__doc__ or "")
    assert "W105" in kopf, "der Kopf nennt die Aenderung nicht"
    assert "rtmp_pull_url" in kopf and "flv_pull_url" in kopf

    ok("W105: Stream-URL in drei Formen — Typriegel, Woerterbuch (codec-"
       "bewusst), rtmp_pull_url")


def _test_v42_w105_egress_waechter():
    """Nichts hat den Polen-VPS beobachtet — `last_test` schrieb nur das Deck.

    Der Betreiber am 01.10.: „anscheinend gibt's Probleme das der bot nicht
    mehr automatisch mit den Polen vps verbindet". Der Befund war nicht der
    Tunnel, sondern dass ihn nichts prueft: `_TUNNEL["last_test"]` wurde
    ausschliesslich von `/api/tunnel/test` gesetzt, es gab keine Schleife. Ein
    toter VPS sah damit aus wie ein gesunder.
    """
    import ast as _ast
    from nc import tunnelwacht as T

    # ── (1) VIER LAGEN, und drei sind KEIN Alarm. Das ist der Teil, der die
    # Meldung brauchbar macht — eine Warnung, die auf jeder Installation ohne
    # Proxy rot ist, erzieht zum Wegsehen (Begruendung aus W85).
    assert T.lage({"ok": True}, hat_proxy=True, forced_off=False) == T.LAGE_OK
    assert T.lage({"ok": False}, hat_proxy=True, forced_off=False) == T.LAGE_FEHLER
    assert T.lage({"ok": False}, hat_proxy=False, forced_off=False) == T.LAGE_DIREKT
    assert T.lage({"ok": True}, hat_proxy=True, forced_off=True) == T.LAGE_AUS
    # forced_off gewinnt vor dem Messwert: „abgeschaltet" IST die Erklaerung.
    assert T.lage({"ok": False}, hat_proxy=True, forced_off=True) == T.LAGE_AUS

    for still in (T.LAGE_OK, T.LAGE_DIREKT):
        assert T.meldung(still, {"ok": True}) == (None, None), still
    stufe, text = T.meldung(T.LAGE_FEHLER, {"via": "http://pl:8118",
                                            "http_code": "000", "err": None})
    assert stufe == "error", stufe
    assert T.meldung(T.LAGE_AUS, {})[0] == "info"

    # ── (2) JEDE MELDUNG NENNT EINE ABHILFE. „HTTP 403" allein hat hier schon
    # einmal wochenlang niemandem geholfen (W81).
    for lg in (T.LAGE_FEHLER, T.LAGE_AUS):
        _, t = T.meldung(lg, {"via": "x", "http_code": "403", "err": None})
        assert "Abhilfe:" in t, lg

    # ── (3) „HTTP 000" ist kein Statuscode. curl liefert bei
    # Verbindungsfehlern 000, nicht 0 — gemessen gegen curl 8.x.
    for leer in ("000", "0", "", None):
        assert T._code_text(leer) == "keine Antwort", repr(leer)
    assert T._code_text("403") == "HTTP 403"

    # ── (4) DIE MASKE IST PFLICHT, UND ZWAR FUER BEIDE FORMEN. Das Ergebnis
    # geht in eine API-Antwort UND ins Log, und ein Proxy darf user:pass
    # tragen. Die zweite Form ist der Befund aus W105: `RECORD_PROXY` darf
    # SCHEMALOS sein (curl nimmt bei `-x nutzer:pass@host:8118` http an), und
    # die alte Maske verlangte `://` — das Passwort stand damit im Klartext im
    # Log und in /api/tunnel/status. Gefunden hat das eine Mutationsprobe, die
    # entwischt ist, nicht das Nachdenken; der Vertrag prueft deshalb nicht
    # mehr nur die bequeme Eingabe (dieselbe Lehre wie concat_cmd, W101).
    from nc.proxyutil import _tunnel_mask as _maske
    for eff in ("http://nutzer:Geheim123456@pl.example:8118",
                "nutzer:Geheim123456@pl.example:8118",
                "socks5://nutzer:Geheim123456@1.2.3.4:1080"):
        roh = "curl: (7) Failed to connect to %s after 0 ms" % eff
        gemeldet = T._fehlerausgabe(roh)
        assert "Geheim123456" not in gemeldet, (eff, gemeldet)
        assert "nutzer" not in gemeldet, (eff, gemeldet)
        assert "Geheim123456" not in (_maske(eff) or ""), eff
        assert "pl.example" in gemeldet or "1.2.3.4" in gemeldet, \
            "die Maske frisst auch den Host — dann sagt die Meldung nichts mehr"
    # Eine Adresse OHNE Zugangsdaten bleibt unveraendert; eine Maske, die
    # jeden Doppelpunkt verschluckt, macht aus der Auskunft Rauschen.
    assert _maske("http://pl.example:8118") == "http://pl.example:8118"
    assert _maske("http://127.0.0.1:8118") == "http://127.0.0.1:8118"
    assert T._fehlerausgabe("") is None
    assert T._fehlerausgabe("   ") is None

    # ── (5) EINE Probe fuer Deck-Knopf UND Waechter. Zwei Fassungen derselben
    # Messung waren in W98 schon der Befund: beide Seiten behaupten dann,
    # dasselbe zu pruefen, und keine prueft nach.
    cmd = T.probe_cmd("http://pl.example:8118")
    assert cmd[0] == "curl" and "-x" in cmd and T.ZIEL in cmd, cmd
    assert "-x" not in T.probe_cmd(None), T.probe_cmd(None)
    ops = io.open("nc/routes/ops.py", encoding="utf-8").read()
    baum = _ast.parse(ops)
    route = [n for n in _ast.walk(baum)
             if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))
             and n.name == "api_tunnel_test"]
    assert len(route) == 1, "api_tunnel_test nicht gefunden"
    rumpf = _ast.unparse(route[0])
    assert "_nc_tunnelwacht.probe(" in rumpf, \
        "die Route baut ihre Probe wieder selbst"
    assert '"curl"' not in rumpf and "'curl'" not in rumpf, \
        "in der Route steht wieder eine eigene curl-Zeile"
    assert 'tunnel_state()[\'last_test\']' in rumpf or \
           '"last_test"' in rumpf or "'last_test'" in rumpf, \
        "die Route schreibt das Ergebnis nicht mehr ins Lagebild"

    ok("W105: Egress-Waechter — vier Lagen, Abhilfe in jeder Meldung, "
       "Zugangsdaten maskiert, EINE Probe fuer Knopf und Schleife")


def _test_v42_w105_chat_laeuft_durch_den_tunnel():
    """Der Chat konnte still direkt laufen, waehrend alles andere tunnelt.

    `_start_chat_listener` uebergibt `web_proxy=`/`ws_proxy=`, und faellt bei
    einem TypeError auf einen Client OHNE Proxy zurueck. Gesagt wurde das auf
    `warning` — und ein `log.warning` erscheint in einem ERROR-Log NIE (W65).
    `requirements.txt` fuehrt TikTokLive ohne obere Grenze, ein Update der
    Bibliothek genuegt also.

    GEMESSEN WIRD IM SYNTAXBAUM, nicht im Dateitext: die Begruendung dieser
    Reparatur nennt `log.warning` woertlich, und ein Vertrag, der seine eigene
    Begruendung als Befund liest, ist viermal in W102-W104 zugeschlagen.
    """
    import ast as _ast
    src = io.open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(src)

    def fn(name):
        for n in _ast.walk(baum):
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef)) \
                    and n.name == name:
                return n
        raise AssertionError("Funktion %s nicht gefunden" % name)

    # ── (1) DER NOTAUSGANG MELDET AUF error, GEDROSSELT.
    listener = fn("_start_chat_listener")
    # Es gibt ZWEI `except TypeError` im Listener — der zweite faengt die
    # alte connect()-Signatur. Gemeint ist der, der den Client baut.
    handler = [h for h in _ast.walk(listener)
               if isinstance(h, _ast.ExceptHandler)
               and isinstance(h.type, _ast.Name) and h.type.id == "TypeError"
               and "TikTokLiveClient(" in _ast.unparse(h)]
    assert len(handler) == 1, "except TypeError um den Client-Bau nicht eindeutig"
    rumpf = _ast.unparse(handler[0])
    assert "log.error(" in rumpf, "der Rueckfall meldet nicht auf error"
    assert "log.warning(" not in rumpf, \
        "der Rueckfall meldet wieder auf warning — in einem ERROR-Log unsichtbar"
    assert '_nc_meldetakt.melden(' in rumpf and "'chat-tunnel'" in rumpf, \
        "die Meldung laeuft nicht durch die Drossel"
    assert "Abhilfe" in rumpf, "die Meldung nennt keine Abhilfe"

    # ── (2) DIE SCHLEIFE EXISTIERT UND WIRD GESTARTET.
    assert any(z.lstrip().startswith("_spawn(_tunnel_wacht_loop(")
               for z in src.splitlines()), \
        "_tunnel_wacht_loop() wird nicht gestartet"

    # ── (3) DER HEARTBEAT IN SCHEIBEN. WATCHDOG_STALL_S ist 420 s; ein
    # konfiguriertes Intervall darueber waere ein Watchdog-Fehlalarm — der
    # Waechter wuerde den Waechter melden. B81 loest das mit „Beat VOR dem
    # Sleep", und das genuegt nur, solange der Sleep kuerzer als die Schwelle
    # ist. Deshalb muss der Beat in einer INNEREN Schleife stehen.
    loop = fn("_tunnel_wacht_loop")
    aeussere = [w for w in loop.body if isinstance(w, _ast.While)]
    assert len(aeussere) == 1, "die aeussere Dauerschleife ist nicht eindeutig"
    innere = [w for w in _ast.walk(aeussere[0])
              if isinstance(w, _ast.While) and w is not aeussere[0]]
    assert innere, "kein verschachtelter Wartezyklus — der Beat haengt am Intervall"
    rumpf_innen = _ast.unparse(innere[0])
    assert '_hb(' in rumpf_innen and "tunnel-wacht" in rumpf_innen, rumpf_innen
    assert "asyncio.sleep(" in rumpf_innen, rumpf_innen
    scheiben = [n.value for n in _ast.walk(innere[0])
                if isinstance(n, _ast.Constant) and isinstance(n.value, int)]
    assert scheiben and max(scheiben) <= 300, \
        "die Heartbeat-Scheibe ist zu gross fuer WATCHDOG_STALL_S=420: %r" % scheiben

    # ── (4) /healthz TRAEGT DIE LAGE — und messe dafuer NICHT.
    assert any(z.strip().startswith("tunnel=_tunnel_lage()")
               for z in src.splitlines()), "/healthz nennt die Egress-Lage nicht"
    lagefn = fn("_tunnel_lage")
    quelle_lage = _ast.unparse(lagefn)
    assert "probe(" not in quelle_lage, \
        "/healthz loest eine Netzprobe aus — der Endpunkt haengt an UptimeRobot"
    # „unbekannt" ist eine eigene Antwort und KEIN Alarm: vor der ersten Probe
    # ist nichts gemessen, und lage() liest ein leeres Ergebnis als Fehler.
    texte = [n.value for n in _ast.walk(lagefn)
             if isinstance(n, _ast.Constant) and isinstance(n.value, str)]
    assert "unbekannt" in texte, \
        "vor der ersten Probe meldet /healthz einen Defekt, den niemand gemessen hat"
    from nc import tunnelwacht as T
    assert T.lage({}, hat_proxy=True, forced_off=False) == T.LAGE_FEHLER, \
        "die Falle, gegen die der unbekannt-Riegel steht, existiert nicht mehr"

    # ── (5) requirements.txt NENNT DEN ZWEITEN API-ZWANG. Eine obere Grenze
    # waere hier ein falsches Versprechen — der Bruch, den dieser Bestand
    # kennt (B78), lag INNERHALB der 6er-Reihe, gegen 6.6.5 reproduziert.
    req = io.open("requirements.txt", encoding="utf-8").read()
    assert "web_proxy" in req and "ws_proxy" in req, \
        "requirements.txt nennt den Proxy-Zwang nicht"

    ok("W105: Chat-Tunnel-Rueckfall meldet laut, Egress-Waechter laeuft, "
       "/healthz nennt die Lage ohne zu messen")


def _test_v42_w106_jede_ausgabe_traegt_ton():
    """Fehlende Tonspuren — zwei Fehlerbilder, eines still, eines laut.

    Die Aufnahme lief mit `-c copy` ohne `-map`: ffmpegs Vorgabeauswahl
    schrieb bei tonloser Quelle still eine reine Videodatei. Der Restream
    mappte im Transcode hart `0:a` und starb bei tonloser Quelle an „Stream
    map '0:a' matches no streams" — weder Netz noch Codec, also griff kein
    Fallback, und das Reconnect-Budget lief an einem Fehler leer, den ein
    Reconnect nie behebt. Im Copy-Pfad ohne Stimme gab es gar kein `-map`.
    """
    import ast as _ast
    import asyncio as _aio
    import os as _os
    import tempfile as _tf
    import threading as _th
    from nc import reccmd as _rc
    from nc import restreamcmd as R
    from nc import restream_stability as _stab
    from nc import tonspur as T

    # ── (1) DIE ERKENNUNG. Beide Meldungsformen von ffmpeg, und NUR Ton: ein
    # leeres '0:v' ist eine kaputte Quelle und braucht eine neue URL, keine
    # Stille.
    for laut in ("Stream map '0:a' matches no streams.",
                 "Stream map '0:a:0' matches no streams.",
                 "[fc#0 @ 0x1] Stream specifier ':a' in filtergraph description "
                 "[2:a]volume=1.8[vtts];[0:a][vtts]amix matches no streams.",
                 "x\nSTREAM MAP '0:A' MATCHES NO STREAMS.\n"):
        assert T.ist_tonlos_fehler(laut), laut
    for still in ("Stream map '0:v' matches no streams.",
                  "Connection timed out", "Server returned 404 Not Found",
                  "", None):
        assert not T.ist_tonlos_fehler(still), still
    # Und darum hat bisher nichts gegriffen: der Codec-Fallback sagt zu
    # dieser Zeile korrekt Nein. Faellt diese Zeile, ist sie kein Grund zum
    # Feiern — dann schaltet ein tonloser Copy-Restream auf transcode und
    # stirbt dort am selben Map.
    assert not _stab.is_codec_failure("Stream map '0:a' matches no streams.")

    # ── (2) DIE LAGE EINER FERTIGEN DATEI. None, wenn ffprobe nichts
    # hergibt — einer leeren/kaputten Datei Stille anzuhaengen versteckte
    # den Defekt hinter einer gueltig aussehenden Datei.
    assert T.hat_ton('{"streams":[{"codec_type":"video"},{"codec_type":"audio"}]}') is True
    assert T.hat_ton({"streams": [{"codec_type": "audio"}]}) is True
    assert T.hat_ton(b'{"streams":[{"codec_type":"video"}]}') is False
    for nichts in ('{"streams":[]}', "{}", None, "[]", '{"streams":null}'):
        assert T.hat_ton(nichts) is None, nichts
    try:
        T.hat_ton("kein json")
        raise AssertionError("unlesbares JSON wird still zu None")
    except ValueError:
        pass

    nach = T.nachruest_cmd("/rec/a.mp4", "/rec/a.tonspur.mp4")
    i = nach.index("ffmpeg")
    assert T.STILLE_QUELLE in nach and "-shortest" in nach, nach
    assert nach[nach.index("-c:v") + 1] == "copy", "das Bild wird neu kodiert"
    assert T.hat_tonspur(nach[i:]), nach

    # ── (3) DER RESTREAM — jede Kombination traegt Ton, hart gemappt.
    schrift = _tf.NamedTemporaryFile(suffix=".ttf", delete=False)
    schrift.write(b"x"); schrift.close()
    avatar = _tf.NamedTemporaryFile(suffix=".png", delete=False)
    avatar.write(b"x"); avatar.close()
    OVDIR = _ph.verzeichnis()
    OV = {k: _os.path.join(OVDIR, k + ".txt") for k in
          ("alert", "brand", "caption", "chat", "follow", "goal",
           "react", "source", "title")}
    for _pfad in OV.values():
        open(_pfad, "w").write("x")

    def _konf(overlay, av):
        R.configure(
            cookie_header=lambda: "", pick_pull_proxy=lambda: "",
            restream_overlay_files=lambda rid=None: OV,
            FFMPEG_THREADS_LIVE=3, FFMPEG_THREADS_RELAY=2,
            RESTREAM_AVATAR=(avatar.name if av else ""), RESTREAM_BITRATE_K=4500,
            RESTREAM_AVATAR_ALPHA="", RESTREAM_AVATAR_H=170,
            RESTREAM_AVATAR_LOOP="",
            RESTREAM_CANVAS_H=720, RESTREAM_CANVAS_W=1280,
            RESTREAM_FONT=schrift.name, RESTREAM_FPS=24,
            RESTREAM_LOW_LATENCY=True, RESTREAM_OVERLAY=overlay,
            RESTREAM_OVERLAY_HTML_FPS=1, RESTREAM_RELAY_BITRATE_K=3500,
            RESTREAM_RELAY_PRESET="ultrafast", RESTREAM_X264_PRESET="veryfast",
            RESTREAM_UA="UA/1.0", TTS_CH=2, TTS_SR=44100, TTS_VOICE_GAIN="1.8")

    ZIEL = ("kick", "rtmps://ingest.example/app/SCHLUESSEL")
    faelle = 0
    try:
        for overlay in (False, True):
            for av in (False, True):
                _konf(overlay, av)
                for quelle in ("https://pull.tiktok.com/stage/x.flv",
                               "https://pull.tiktok.com/stage/x.m3u8"):
                    for transcode in (False, True):
                        for tts in (None, "/tmp/tts.fifo"):
                            for html in (None, "/tmp/ov.fifo"):
                                for tonlos in (False, True):
                                    for art in ("tee", "einzel", "relay"):
                                        kw = dict(transcode=transcode, tts_fifo=tts,
                                                  html_ov_fifo=html, tonlos=tonlos)
                                        if art == "tee":
                                            kw["targets"] = [ZIEL]
                                        else:
                                            kw["only_target"] = ZIEL[1]
                                            kw["relay_profile"] = art == "relay"
                                        cmd = R.build(quelle, "", "", **kw)
                                        fall = (overlay, av, quelle[-4:], kw)
                                        faelle += 1
                                        assert T.hat_tonspur(cmd), \
                                            ("kein Ton gemappt", fall, cmd)
                                        assert cmd[cmd.index("-ac") + 1] == "2", fall
                                        assert (T.STILLE_QUELLE in cmd) is tonlos, fall
                                        if tonlos:
                                            # Kein Rest greift mehr auf den Ton
                                            # der Quelle — sonst stirbt der
                                            # Neubau am selben Map.
                                            fc = (cmd[cmd.index("-filter_complex") + 1]
                                                  if "-filter_complex" in cmd else "")
                                            maps = [cmd[j + 1] for j, a in enumerate(cmd)
                                                    if a == "-map"]
                                            assert "[0:a]" not in fc, (fall, fc)
                                            assert not any(m.startswith("0:a") for m in maps), \
                                                (fall, maps)
                                            # Stille ist der LETZTE Eingang:
                                            # sie darf keinen Index verschieben.
                                            n_in = cmd.count("-i")
                                            assert ("%d:a" % (n_in - 1)) in " ".join(maps) + fc, \
                                                (fall, maps, fc)
    finally:
        _konf(True, True)
    assert faelle == 2 * 2 * 2 * 2 * 2 * 2 * 2 * 3, faelle

    # ── (4) DIE AUFNAHME — ausdrueckliche Auswahl, optional fuer reine
    # Ton-Lives; die Garantie gibt sichern() an der fertigen Datei.
    _rc.configure(
        cookie_header=lambda: "k=v", ensure_cookie_file_netscape=lambda: True,
        pick_checked_pull_proxy=None, stream_url_ttl=lambda u: None,
        log_event=lambda *a, **k: None, resolve_tiktok_live_stream=None,
        REC_403_UNTIL={}, REC_PROXY={}, REC_PROXY_FAILED={},
        REC_PROXY_LOCK=_th.Lock(), COOKIE_FILE="cookies.txt",
        FFMPEG_NICE_RECORD=0, FFMPEG_THREADS_RECORD=1, RECORDER_PREF="auto",
        RECORD_403_YTDLP=True, STREAM_URL_MIN_TTL=300)
    for url in ("https://pull.tiktok.com/x.flv", "https://pull.tiktok.com/x.m3u8"):
        cmd = _rc._build_native_cmd(url, "/rec/o.mp4", 60, pull_proxy="")
        assert T.hat_tonspur(cmd, optional_ok=True), cmd
        assert not T.hat_tonspur(cmd), "die Aufnahme mappt Ton jetzt hart — " \
            "dann bricht eine reine Ton-Live ab, statt aufzunehmen"
        assert cmd.index("-map") > cmd.index("-i"), "-map ist eine Ausgabe-Option"

    # ── (5) DIE NACHRUESTUNG. Mit nachgebautem ffprobe/ffmpeg: geprueft
    # wird, was mit der DATEI passiert, nicht dass ein Werkzeug laeuft.
    verz = _ph.verzeichnis()
    pfad = _os.path.join(verz, "a.mp4")

    def _neu():
        with open(pfad, "wb") as f:
            f.write(b"V" * 100)

    def _lauf(probe, remux_ok=True):
        aufrufe = []

        async def _f(cmd, timeout):
            aufrufe.append(cmd)
            if "ffprobe" in cmd:
                if isinstance(probe, Exception):
                    raise probe
                return probe
            # Auch der Fehlschlag schreibt an: echtes ffmpeg legt die
            # Ausgabe an, bevor es scheitert. Ein Fehlschlag OHNE halbe Datei
            # waere die bequeme Eingabe — und mit ihr entwischte die
            # Mutationsprobe, die das Aufraeumen entfernt.
            with open(cmd[-1], "wb") as f:
                f.write(b"VA" * (100 if remux_ok else 7))
            if remux_ok:
                return 0, b"", b""
            return 1, b"", b"Unknown input format: 'lavfi'"
        return _f, aufrufe

    # Jeder Ausgang ausser „hat Ton" MUSS eine Zeile hinterlassen — ein
    # stilles „weiss nicht" ist dieselbe Blindheit wie ein stilles return
    # (W81). Gelesen wird der echte Logger, die Drossel vorher geleert.
    import logging as _lg
    from nc import meldetakt as _takt
    zeilen = []

    class _Fang(_lg.Handler):
        def emit(self, rec):
            zeilen.append((rec.levelname, rec.getMessage()))

    def _gemeldet():
        z = list(zeilen)
        del zeilen[:]
        _takt.zuruecksetzen(T.KANAL)
        return z

    fang = _Fang()
    _lg.getLogger("TikTokBot").addHandler(fang)
    alt = T._lauf
    try:
        _takt.zuruecksetzen(T.KANAL)
        _neu()
        T._lauf, auf = _lauf((0, b'{"streams":[{"codec_type":"video"}]}', b""))
        r = _aio.run(T.sichern(pfad, wer="@t"))
        assert r == {"lage": "nachgeruestet", "groesse": 200}, r
        z = _gemeldet()
        assert [s for s, t in z] == ["WARNING"] and "nachgeruestet" in z[0][1], z
        assert open(pfad, "rb").read() == b"VA" * 100
        assert not _os.path.exists(_os.path.join(verz, "a.tonspur.mp4"))

        _neu()
        T._lauf, auf = _lauf((0, b'{"streams":[{"codec_type":"video"}]}', b""),
                             remux_ok=False)
        r = _aio.run(T.sichern(pfad, wer="@t"))
        assert r == {"lage": "fehlgeschlagen", "groesse": 100}, r
        assert open(pfad, "rb").read() == b"V" * 100, "das Original ist weg"
        z = _gemeldet()
        assert [s for s, t in z] == ["ERROR"] and "OHNE Ton" in z[0][1], z
        assert not _os.path.exists(_os.path.join(verz, "a.tonspur.mp4")), \
            "der halbe Remux bleibt liegen"

        for probe, lage in (((0, b'{"streams":[{"codec_type":"audio"}]}', b""), "ton"),
                            ((1, b"", b"moov atom not found"), "unbekannt"),
                            (T.Fehlschlag("ffprobe antwortete 20 s lang nicht"), "unbekannt"),
                            ((0, b"kaputt{", b""), "unbekannt"),
                            ((0, b'{"streams":[]}', b""), "unbekannt")):
            _neu()
            T._lauf, auf = _lauf(probe)
            r = _aio.run(T.sichern(pfad, wer="@t"))
            assert r["lage"] == lage, (probe, r)
            assert len(auf) == 1, ("bei %s darf nichts remuxt werden" % lage, auf)
            assert open(pfad, "rb").read() == b"V" * 100
            z = _gemeldet()
            if lage == "ton":
                assert z == [], ("der gesunde Fall meldet — das erzieht zum "
                                 "Wegsehen", z)
            else:
                assert [s for s, t in z] == ["WARNING"], (probe, z)
                assert "nicht klaeren" in z[0][1], z
    finally:
        T._lauf = alt
        _lg.getLogger("TikTokBot").removeHandler(fang)
        _takt.zuruecksetzen(T.KANAL)

    # ── (5b) DER ECHTE PROZESSWEG und die beiden Fehlerpfade, die vorher
    # ungeprueft waren: ein Werkzeug, das fehlt oder haengt, darf nicht still
    # „kein Ergebnis" liefern — es wirft Fehlschlag, und der wird gemeldet.
    import sys as _sys
    rc_, out_, _e = _aio.run(T._lauf([_sys.executable, "-c", "print('ok')"], 20))
    assert rc_ == 0 and out_.strip() == b"ok"
    for cmd, wort in (([_os.path.join(verz, "gibt_es_nicht")], "nicht starten"),
                      ([_sys.executable, "-c", "import time; time.sleep(30)"], "lang nicht")):
        try:
            _aio.run(T._lauf(cmd, 1))
            raise AssertionError("kein Fehlschlag fuer %r" % cmd)
        except T.Fehlschlag as e:
            assert wort in str(e), e
    # Kein Platz: die Datei bleibt, und es ist ein ERROR, kein Achselzucken.
    import nc.tonspur as _tsmod
    alt_platz = _tsmod.platz_reicht
    try:
        _takt.zuruecksetzen(T.KANAL)
        _tsmod.platz_reicht = lambda p, faktor=1.0: (False, "3 MB frei")
        _neu()
        T._lauf, auf = _lauf((0, b'{"streams":[{"codec_type":"video"}]}', b""))
        _lg.getLogger("TikTokBot").addHandler(fang)
        r = _aio.run(T.sichern(pfad, wer="@t"))
        assert r["lage"] == "fehlgeschlagen" and len(auf) == 1, (r, auf)
        z = _gemeldet()
        assert [s for s, t in z] == ["ERROR"] and "Platz" in z[0][1], z
        # Groesse nicht lesbar: 0 und eine Zeile, keine Ausnahme.
        _tsmod.platz_reicht = alt_platz
        assert T._groesse(_os.path.join(verz, "weg.mp4")) == 0
        assert [s for s, t in _gemeldet()] == ["WARNING"]
    finally:
        _tsmod.platz_reicht = alt_platz
        T._lauf = alt
        _lg.getLogger("TikTokBot").removeHandler(fang)
        _takt.zuruecksetzen(T.KANAL)

    # ── (6) DIE VERDRAHTUNG — im Syntaxbaum, nicht im Dateitext (W102–W104:
    # ein Vertrag darf seine eigene Begruendung nicht als Befund lesen).
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    bauer = [n for n in _ast.walk(baum) if isinstance(n, _ast.Call)
             and getattr(n.func, "id", None) == "_build_restream_cmd"]
    assert len(bauer) >= 3, len(bauer)
    for n in bauer:
        assert any(k.arg == "tonlos" for k in n.keywords), \
            "Z.%d: _build_restream_cmd ohne tonlos=" % n.lineno
    def _aufrufe(knoten):
        return {_ast.unparse(c.func) for c in _ast.walk(knoten)
                if isinstance(c, _ast.Call)}
    hrf = [n for n in baum.body if isinstance(n, _ast.AsyncFunctionDef)
           and n.name == "handle_recording_finished"]
    assert len(hrf) == 1
    # ANKER GEWANDERT (v4.2-W158, nicht der Vertrag): die Nachbearbeitung ist
    # EIN benannter Schritt (_aufnahme_fertigmachen) — Tonspur, dann Chat.
    fm = [n for n in baum.body if isinstance(n, _ast.AsyncFunctionDef)
          and n.name == "_aufnahme_fertigmachen"]
    assert "_aufnahme_fertigmachen" in _aufrufe(hrf[0]) and fm and \
        "_nc_tonspur.sichern" in _aufrufe(fm[0]), \
        "die fertige Aufnahme wird nicht mehr auf Ton geprueft"
    rm = [n for n in baum.body if isinstance(n, _ast.ClassDef)
          and n.name == "RestreamManager"]
    assert len(rm) == 1
    meth = {n.name: n for n in rm[0].body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    erkenner = [m for m in meth.values()
                if "_nc_tonspur.ist_tonlos_fehler" in _aufrufe(m)]
    assert len(erkenner) == 1, \
        "der Restream-Manager erkennt die tonlose Quelle nicht mehr"
    # Der Schalter klebt nicht: dieselbe Ausgangsbehandlung, die ihn setzt,
    # nimmt ihn bei jedem anderen Ende wieder weg. Sonst bliebe eine Quelle,
    # die nur am Anfang stumm war, die ganze Sitzung stumm.
    assert "self._tonlos.discard" in _aufrufe(erkenner[0]), \
        "der Stille-Schalter klebt bis zum Stop"
    assert "self._tonlos.discard" in _aufrufe(meth["stop"]), \
        "der Stille-Schalter ueberlebt den Stop — die naechste Sitzung prueft nie neu"

    ok("W106: jede Aufnahme und jeder Restream traegt eine Tonspur "
       "(%d Restream-Kombinationen, Nachruestung, Verdrahtung)" % faelle)


def _test_v42_w107_cookie_bezug_ist_standard():
    """„Cookies automatisch beziehen soll Standard sein" — und lief fast nie.

    Der Bezug hing im Telegram-Cookie-Alarm, und der startet nur mit
    DISK_ALARM_CHAT_ID/DAILY_SUMMARY_CHAT_ID. Ohne Alarm-Chat lief der
    Standard COOKIE_AUTO_FETCH=1 damit nie. Mit Chat nur bei rotem Health, im
    Stundentakt; nie beim Start, nie nach einem 403. Und der Deck-Knopf ging
    am Buchhalter vorbei: nach einem Klick stand weiter „noch nie gelaufen".
    """
    import ast as _ast
    import glob
    from nc import cookiebezug as B
    from nc import cookieholen as H

    alt_stand = dict(B.STAND)
    alt_konf = dict(B._KONF)
    alt_akt = H.aktualisiere
    try:
        # ── (1) WANN HILFT EIN GAST-AUFRUF? Nur bei dem, was er liefern kann.
        assert B.gast_hilft({"exists": False})
        assert B.gast_hilft({"status": "parse_error"})
        assert B.gast_hilft({"critical_missing": ["ttwid"]})
        assert B.gast_hilft({"expired": [{"name": "msToken", "days_ago": 1}]})
        # Ein fehlender LOGIN ist kein Fall fuer den Gast-Aufruf — sonst
        # fragt eine Installation ohne Login alle 15 min TikTok, ohne dass
        # sich je etwas aendert.
        assert not B.gast_hilft({"critical_missing": ["sessionid", "sessionid_ss",
                                                      "sid_tt"]})
        assert not B.gast_hilft({"status": "ok", "critical_missing": []})
        assert B.GAST_NAMEN == frozenset(H.ANTIBOT), \
            "zweite Liste der Anti-Bot-Namen — die laufen auseinander"

        # ── (2) DER ZEITPLAN, Schritt fuer Schritt mit eigener Uhr.
        aufrufe = []

        def _fake(datei, **kw):
            aufrufe.append(kw)
            return dict(LAUF["bericht"])
        H.aktualisiere = _fake
        geleert = []
        B.configure(datei="/x/cookies.txt", aktiv=True, intervall_h=6,
                    timeout=7, nach_erfolg=lambda: geleert.append(1))
        B.STAND.update(last_try=0.0, last_ok=None, last_error=None, count=0,
                       last_report=None, last_anlass=None, anstoss=None)
        gesund = {"status": "ok", "critical_missing": [], "expired": []}
        T0 = 1_000_000.0

        # Frischer Start: SOFORT, nicht erst beim ersten Alarm-Tick.
        assert B.faellig(T0, gesund) == (True, "start")
        assert B.info(T0)["next_run"] is not None

        LAUF = {"bericht": {"ok": True, "added": ["ttwid"], "replaced": ["msToken"],
                            "total": 9}}
        _orig_time = B.time.time
        B.time.time = lambda: T0
        try:
            b = B.holen(anlass="start")
        finally:
            B.time.time = _orig_time
        assert b["anlass"] == "start" and B.STAND["last_ok"] == T0
        assert B.STAND["count"] == 2 and geleert == [1], \
            "nach dem Bezug liest der Recorder weiter den alten Cache"
        assert aufrufe[-1]["timeout"] == 7 and aufrufe[-1]["quelle"] == "gast"

        assert B.faellig(T0 + 60, gesund) == (False, "wartet")
        assert B.faellig(T0 + 6 * 3600, gesund) == (True, "plan")
        assert B.naechster_lauf(T0) == T0 + 6 * 3600

        # 403: angestossen, aber nicht vor 15 Minuten — 40 Trackings im 403
        # duerfen nicht 40 Aufrufe bei TikTok ausloesen.
        B.anstossen("403-aufnahme")
        assert B.faellig(T0 + 60, gesund) == (False, "wartet")
        assert B.faellig(T0 + B.ANSTOSS_ABSTAND_S, gesund) == (True, "403-aufnahme")
        assert B.info(T0 + 60)["pending"] == "403-aufnahme"
        # Ein erledigter Anstoss ist erledigt. Bliebe er stehen, fragte die
        # Schleife alle 15 Minuten nach — fuer einen 403 von vor Stunden.
        LAUF["bericht"] = {"ok": True, "added": [], "replaced": []}
        B.time.time = lambda: T0 + B.ANSTOSS_ABSTAND_S
        try:
            B.holen(anlass="403-aufnahme")
        finally:
            B.time.time = _orig_time
        assert B.STAND["anstoss"] is None, "der Anstoss klebt nach dem Bezug"
        assert B.faellig(T0 + 2 * B.ANSTOSS_ABSTAND_S + 1, gesund) == (False, "wartet")
        T0 = T0 + B.ANSTOSS_ABSTAND_S          # ab hier gilt der neue Lauf

        # Roter Health, den ein Gast heilen kann: ebenfalls im 15-min-Abstand.
        B.STAND["anstoss"] = None
        rot = {"status": "warning", "critical_missing": ["ttwid"]}
        assert B.faellig(T0 + 60, rot) == (False, "wartet")
        assert B.faellig(T0 + B.ANSTOSS_ABSTAND_S, rot) == (True, "gesundheit")
        # ... den er NICHT heilen kann: nur der Plan.
        login = {"status": "critical", "critical_missing": ["sessionid"]}
        assert B.faellig(T0 + B.ANSTOSS_ABSTAND_S, login) == (False, "wartet")

        # Fehlschlag: nach 30 min neu, nicht nach 6 Stunden.
        LAUF["bericht"] = {"ok": False, "error": "Tunnel connection failed"}
        B.time.time = lambda: T0
        try:
            B.holen(anlass="plan")
        finally:
            B.time.time = _orig_time
        assert B.STAND["last_error"] == "Tunnel connection failed"
        assert B.STAND["last_ok"] == T0, "ein Fehlschlag loescht den letzten Erfolg"
        assert geleert == [1, 1], "der Cache wird auch nach einem Fehlschlag geleert"
        assert B.faellig(T0 + B.NEU_VERSUCH_S - 1, gesund) == (False, "wartet")
        assert B.faellig(T0 + B.NEU_VERSUCH_S, gesund) == (True, "neuer_versuch")
        assert B.naechster_lauf(T0) == T0 + B.NEU_VERSUCH_S

        # Abgeschaltet heisst abgeschaltet — auch nach 403.
        B.configure(datei="/x/cookies.txt", aktiv=False)
        B.anstossen("403-aufnahme")
        assert B.faellig(T0 + 10 ** 6, rot) == (False, "aus")
        assert B.info()["next_run"] is None and B.info()["enabled"] is False

        # Das Deck liest die Schluessel aus W10 weiter.
        for k in ("enabled", "interval_h", "last_ok", "fetched_total",
                  "last_error", "next_run", "last_try", "last_anlass", "pending"):
            assert k in B.info(), k
    finally:
        H.aktualisiere = alt_akt
        B.STAND.clear(); B.STAND.update(alt_stand)
        B._KONF.clear(); B._KONF.update(alt_konf)

    # ── (3) DIE VERDRAHTUNG — im Syntaxbaum.
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    eltern = {}
    for n in _ast.walk(baum):
        for k in _ast.iter_child_nodes(n):
            eltern[k] = n
    spawn = [n for n in _ast.walk(baum) if isinstance(n, _ast.Call)
             and _ast.unparse(n.func) == "_spawn" and n.args
             and _ast.unparse(n.args[0]) == "_cookie_bezug_loop()"]
    assert len(spawn) == 1, "die Bezugs-Schleife wird nicht gestartet"
    k = spawn[0]
    while k in eltern:
        k = eltern[k]
        if isinstance(k, _ast.If):
            bed = _ast.unparse(k.test)
            assert "CHAT_ID" not in bed and "ALARM" not in bed, \
                "der Bezug haengt wieder am Telegram-Alarm: " + bed
    fn = {n.name: n for n in baum.body
          if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    def _rufe(f):
        return {_ast.unparse(c.func) for c in _ast.walk(fn[f])
                if isinstance(c, _ast.Call)}
    assert "_nc_cookiebezug.faellig" in _rufe("_cookie_bezug_runde")
    assert "_nc_cookiebezug.holen" in str(
        [_ast.unparse(a) for c in _ast.walk(fn["_cookie_bezug_runde"])
         if isinstance(c, _ast.Call) for a in c.args])
    assert "_nc_cookiebezug.anstossen" in _rufe("_resolver_stumm")
    assert "_nc_cookiebezug.holen" in _rufe("_cookies_selbst_holen")
    # Der 403-Zweig der Aufnahme stoesst an.
    zweig = [n for n in _ast.walk(baum) if isinstance(n, _ast.If)
             and _ast.unparse(n.test) == "category == 'forbidden_403'"]
    assert zweig and any(
        "_nc_cookiebezug.anstossen" in _ast.unparse(z) for z in zweig[0].body), \
        "ein 403 der Aufnahme stoesst keinen Bezug mehr an"
    # Kein zweiter Bezugsweg am Buchhalter vorbei — gleich unter welchem
    # Alias: `aktualisiere` ruft im ganzen Bestand nur nc/cookiebezug.
    for pfad in (["bot.py", "discordbot.py"] + sorted(glob.glob("nc/*.py"))
                 + sorted(glob.glob("nc/routes/*.py"))):
        if pfad.replace("\\", "/") in ("nc/cookiebezug.py", "nc/cookieholen.py"):
            continue
        b2 = _ast.parse(io.open(pfad, encoding="utf-8").read())
        direkt = [c.lineno for c in _ast.walk(b2) if isinstance(c, _ast.Call)
                  and _ast.unparse(c.func).split(".")[-1] == "aktualisiere"]
        assert not direkt, "%s:%s geht am Zeitplan vorbei" % (pfad, direkt)
    route = [n for n in _ast.walk(_ast.parse(io.open(
        "nc/routes/settings.py", encoding="utf-8").read()))
        if isinstance(n, _ast.FunctionDef) and n.name == "api_cookies_fetch"]
    assert len(route) == 1 and "_nc_cookiebezug.holen" in {
        _ast.unparse(c.func) for c in _ast.walk(route[0]) if isinstance(c, _ast.Call)}, \
        "der Deck-Knopf geht nicht durch den Buchhalter"

    # ── (4) DAS DECK nennt den naechsten Lauf und hat den Knopf im Status.
    deck = io.open("templates/dashboard.html", encoding="utf-8").read()
    i = deck.index("const af = cookHealth.autofetch;")
    stueck = deck[i:deck.index("$('#sy_cookies')", i)]   # waechst mit
    zeilen = [z for z in stueck.splitlines() if "ch+=" in z]
    assert any("T('Naechster Lauf')" in z and "${nx}" in z for z in zeilen) \
        and "af.next_run" in stueck, \
        "das Deck zeigt nicht, wann der Bezug das naechste Mal laeuft"
    assert any("T('Letzter Versuch')" in z and "af.last_try" in z for z in zeilen), \
        "das Deck zeigt nicht, wann der Bezug zuletzt fragte"
    assert "fetchCookies('gast')" in stueck, "kein Jetzt-holen-Knopf im Status"

    ok("W107: Cookie-Auto-Bezug laeuft ohne Telegram-Chat — beim Start, nach "
       "Plan, nach 403 (gedrosselt), und jeder Weg geht durch den Buchhalter")


def _test_v42_w108_drossel_greift_vor_dem_salat():
    """Pixelsalat bei mehreren Live-Nutzern: die Drossel kam zu spaet.

    Gemessen (nc/lastvorsorge.py): fehlende Video-Pakete mitten im GOP — was
    ein Live-CDN einem zu langsam lesenden Client antut — ergeben 69 von 502
    Bildern Salat, und kein Decoder-Schalter rettet sie. Die Rueckstands-
    Drossel aus W43 regelt erst nach dem Rueckstand ab, also nach dem Salat.
    Die Vorsorge waehlt die Stufe beim Start.
    """
    import ast as _ast
    from nc import lastvorsorge as L
    from nc import restreamcmd as R

    # ── (1) DIE KOSTEN SIND GEMESSEN, NICHT GESCHAETZT. Ungemessenes steht
    # auf 1,0 — eine erfundene Ersparnis liesse genau den Fall durch, gegen
    # den das Modul antritt.
    assert L.KOSTEN[0] == L.KOSTEN[1] == L.KOSTEN[2] == 1.0
    assert L.KOSTEN[3] == 0.80 and L.KOSTEN[4] == 0.66
    assert set(L.KOSTEN) == set(range(R.DROSSEL_MAX + 1)), \
        "die Kostentabelle kennt nicht jede Drossel-Stufe"
    # Daran haengt „nie unter die erreichte Stufe": eine hoehere Stufe darf
    # nie MEHR kosten als eine niedrigere, sonst waehlt die Vorsorge eine
    # kleinere Stufe, als die Rueckstands-Drossel schon erreicht hat.
    k = [L.KOSTEN[i] for i in range(R.DROSSEL_MAX + 1)]
    assert all(a >= b for a, b in zip(k, k[1:])), k
    rs = io.open("nc/restreamcmd.py", encoding="utf-8").read()
    assert "-19.9 %" in rs and "-33.9 %" in rs, \
        "die W61-Messung, aus der die Kosten stammen, steht nicht mehr da"

    # ── (2) DIE STARTSTUFE. 8 Kerne, 3 Threads je Transcode.
    assert L.startstufe(0.5, 8, 0, 3) == (0, None), "leere Maschine wird gedrosselt"
    assert L.startstufe(3.0, 8, 0, 3)[0] == 0
    assert L.startstufe(4.2, 8, 0, 3)[0] == 3          # frei 2,6 -> 87 %
    assert L.startstufe(4.5, 8, 0, 3)[0] == 4          # frei 2,3 -> 77 %
    stufe, grund = L.startstufe(8.0, 8, 0, 3)
    assert stufe == R.DROSSEL_MAX and "Abhilfe" in grund, (stufe, grund)
    # Jeder Grund nennt die Zahlen, aus denen er kommt.
    st, gr = L.startstufe(4.5, 8, 0, 3)
    assert "frei 2.3" in gr and "Stufe 4" in gr and "66 %" in gr, gr

    # Gerade gestartete Transcodes zaehlen, obwohl das Load-Mittel sie noch
    # nicht zeigt — sonst saehen zwei kurz nacheinander gestartete Restreams
    # beide eine leere Maschine.
    assert L.startstufe(1.0, 8, 0, 3)[0] == 0
    assert L.startstufe(1.0, 8, 2, 3)[0] == R.DROSSEL_MAX
    assert L.jung(100.0, 100.0 + L.JUNG_S - 1) and not L.jung(100.0, 100.0 + L.JUNG_S)
    assert not L.jung(None, 5.0)

    # Nie unter die schon erreichte Stufe: die Drossel regelt bewusst nie
    # hoch, und die Vorsorge darf das nicht durch die Hintertuer tun.
    assert L.startstufe(0.5, 8, 0, 3, stufe_jetzt=4) == (4, None)
    # Wer schon gedrosselt laeuft und mit dieser Stufe passt, bleibt still.
    assert L.startstufe(4.2, 8, 0, 3, stufe_jetzt=3) == (3, None)
    for jetzt in range(R.DROSSEL_MAX + 1):
        for last in (0.0, 3.0, 4.2, 4.5, 5.5, 9.0):
            assert L.startstufe(last, 8, 0, 3, stufe_jetzt=jetzt)[0] >= jetzt, (jetzt, last)
    # Ungueltige Eingaben brechen nicht: kein Kern bekannt -> 1 Kern.
    assert L.startstufe(0.0, 0, 0, 0)[0] >= 0

    # ── (3) DIE STUFE WIRKT IM KOMMANDO: bei Stufe 4 faellt der Avatar,
    # bei Stufe 3 die Bildrate — gemessen am gebauten Befehl, nicht am
    # Schalter.
    assert R.drossel_fps(24, 3) == 18 and R.drossel_avatar_aus(4)

    # ── (4) DIE VERDRAHTUNG: VOR Feeder und Bauer, und nur beim Transcode.
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    rm = [n for n in baum.body if isinstance(n, _ast.ClassDef)
          and n.name == "RestreamManager"][0]
    start = [n for n in rm.body if isinstance(n, _ast.AsyncFunctionDef)
             and n.name == "start"][0]
    rufe = [(c.lineno, _ast.unparse(c.func)) for c in _ast.walk(start)
            if isinstance(c, _ast.Call)]
    vorsorge = [z for z, f in rufe if f == "self._drossel_vorsorge"]
    feeder = [z for z, f in rufe if f == "asyncio.to_thread"]
    bauer = [z for z, f in rufe if f == "_build_restream_cmd"]
    assert len(vorsorge) == 1, "die Vorsorge laeuft nicht beim Start"
    assert bauer and vorsorge[0] < min(bauer), "Vorsorge NACH dem Bauer"
    assert feeder and vorsorge[0] < min(feeder), \
        "Vorsorge nach dem Avatar-Feeder — der startet dann fuer eine Stufe, " \
        "die ihn gar nicht mehr will, und haengt in open(fifo)"
    eltern = {k: n for n in _ast.walk(start) for k in _ast.iter_child_nodes(n)}
    k = [c for c in _ast.walk(start) if isinstance(c, _ast.Call)
         and _ast.unparse(c.func) == "self._drossel_vorsorge"][0]
    while k in eltern and not isinstance(k, _ast.If):
        k = eltern[k]
    assert isinstance(k, _ast.If) and _ast.unparse(k.test) == "transcode", \
        "die Vorsorge drosselt auch den Copy-Modus, der gar nicht kodiert"
    vs = [n for n in rm.body if isinstance(n, _ast.FunctionDef)
          and n.name == "_drossel_vorsorge"][0]
    vs_rufe = {_ast.unparse(c.func) for c in _ast.walk(vs) if isinstance(c, _ast.Call)}
    assert "_nc_lastvorsorge.startstufe" in vs_rufe and "os.getloadavg" in vs_rufe

    ok("W108: die Drossel waehlt ihre Stufe beim Start nach freien Kernen — "
       "gemessene Kosten, junge Transcodes mitgezaehlt, nie unter der Ist-Stufe")


def _test_v42_w109_ein_befehlsverzeichnis():
    """Telegram und Discord aus EINEM Verzeichnis — gleiche Namen, gleiche Rechte.

    Vorher: zwei Listen (Telegram-Tupel, Discord-_PAR_CMDS mit sys_-Praefix),
    zwei kopierte Discord-Befehle, sieben Telegram-Befehle ohne Discord-
    Gegenstueck, eine handgeschriebene Hilfe mit 27 von 45 Befehlen, und ein
    /untrack, das auf Discord jedes Servermitglied fuer die ganze Gruppe
    ausfuehren durfte.
    """
    import ast as _ast
    from nc import befehle as B
    from nc import botctx as K

    # ── (1) DAS VERZEICHNIS IST IN SICH STIMMIG.
    assert B.pruefen() == [], B.pruefen()
    # Jeder Shim-Befehl ist Betreiberbefehl — der Shim meldet sich als
    # freigeschalteter Telegram-Nutzer an. Ein offener Shim-Befehl gaebe
    # jedem Discord-Mitglied die Telegram-Rechte des Betreibers. pruefen()
    # muss das finden, nicht nur der Mensch beim Lesen:
    alt = B.BEFEHLE
    try:
        B.BEFEHLE = alt + (B.Befehl("x_offen", "system", "x", B._BEIDE, "tg",
                                    "jeder", None, "diag"),)
        assert any("Shim-Befehl" in f for f in B.pruefen())
        B.BEFEHLE = alt + (B.Befehl("sys_alt", "system", "x", B._BEIDE, "tg",
                                    "betreiber", None, "diag"),)
        assert any("sys_" in f for f in B.pruefen())
        # Jeder Zweig von pruefen() hat seinen Fall — sonst ist er eine
        # Behauptung ohne Beleg (W89: die ungeprueften waren die Fehlerpfade).
        for eintrag, erwartet in (
                (alt[0], "doppelter Name"),
                (B.Befehl("x_rubrik", "gibtsnicht", "x", B._NUR_DC, "nativ",
                          "jeder", None, None), "unbekannte Rubrik"),
                (B.Befehl("x_recht", "system", "x", B._NUR_DC, "nativ",
                          "admin", None, None), "unbekanntes Recht"),
                (B.Befehl("x_ohne", "system", "x", B._NUR_TG, None,
                          "betreiber", None, None), "Telegram ohne Handler"),
                (B.Befehl("x_weg", "system", "x", B._NUR_DC, None,
                          "jeder", None, None), "Discord ohne Ausfuehrungsweg"),
                (B.Befehl("Gross-Name", "system", "x", B._NUR_DC, "nativ",
                          "jeder", None, None), "kein gueltiger Befehlsname"),
                (B.Befehl("x" * 33, "system", "x", B._NUR_DC, "nativ",
                          "jeder", None, None), "kein gueltiger Befehlsname")):
            B.BEFEHLE = alt + (eintrag,)
            befunde = B.pruefen()
            assert any(erwartet in f for f in befunde), (erwartet, befunde)
            # Und NUR dieser Befund — ein Pruefer, der bei jeder Aenderung
            # alles meldet, meldet nichts.
            assert len(befunde) == 1, befunde
    finally:
        B.BEFEHLE = alt

    # ── (2) PARITAET: jeder Telegram-Befehl hat auf Discord DENSELBEN Namen —
    # ausser den beiden, die bewusst nur auf Telegram stehen.
    tg = {b.name for b in B.fuer(B.TG)}
    dc = {b.name for b in B.fuer(B.DC)}
    assert tg - dc == {"start", "update"}, sorted(tg - dc)
    assert B.NACH_NAME["update"].plattformen == frozenset({B.TG}), \
        "ein Code-Update gehoert an die Telegram-Freischaltliste, nicht an " \
        "eine Discord-Rolle, die ein Moderator vergeben kann"
    for b in B.discord_ueber_tg():
        assert b.recht == "betreiber" and b.tg_handler, b

    # ── (3) TELEGRAM: registriert aus dem Verzeichnis, jeder Handler
    # existiert und prueft die Freischaltung als ERSTES.
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    schleife = [n for n in _ast.walk(baum) if isinstance(n, _ast.For)
                and _ast.unparse(n.iter) == "_nc_befehle.telegram_handler()"]
    assert len(schleife) == 1 and "CommandHandler" in _ast.unparse(schleife[0])
    alte = [n for n in _ast.walk(baum) if isinstance(n, _ast.For)
            and isinstance(n.iter, _ast.Tuple) and "CommandHandler" in _ast.unparse(n)]
    assert not alte, "eine zweite, handgeschriebene Telegram-Liste ist zurueck"
    # v4.2-W172: die eine ausdrueckliche Ausnahme. Jede weitere muss HIER
    # eingetragen werden — eine Liste, die still waechst, oeffnet Telegram.
    assert B.OEFFENTLICH <= {"spenden"}, \
        "neue oeffentliche Telegram-Befehle: %r" % sorted(B.OEFFENTLICH - {"spenden"})
    for name, handler in B.telegram_handler():
        fn = oben.get(handler)
        assert isinstance(fn, _ast.AsyncFunctionDef), \
            "/%s: Handler %s fehlt in bot.py" % (name, handler)
        if name in B.OEFFENTLICH:
            continue
        def _erste(f):
            return f.body[1] if _ast.get_docstring(f) else f.body[0]
        erste = _erste(fn)
        # Eine reine Weiterleitung (`await _pause_resume_cmd(update, ...)`)
        # zaehlt, wenn das Ziel als erstes prueft — eine Ebene, nicht mehr.
        rufe = [c for c in _ast.walk(erste) if isinstance(c, _ast.Call)
                and isinstance(c.func, _ast.Name) and c.func.id in oben]
        if "_is_authorized(update)" not in _ast.unparse(erste) and rufe:
            erste = _erste(oben[rufe[0].func.id])
        assert "_is_authorized(update)" in _ast.unparse(erste), \
            "/%s: %s prueft die Freischaltung nicht als erstes: %s" % (
                name, handler, _ast.unparse(erste)[:80])
    # Das Telegram-Menue kommt aus derselben Liste und wird beim Start gesetzt.
    assert "_telegram_befehlsmenue" in oben
    menue = {_ast.unparse(c.func) for c in _ast.walk(oben["_telegram_befehlsmenue"])
             if isinstance(c, _ast.Call)}
    assert "app.bot.set_my_commands" in menue and "_nc_befehle.fuer" in menue
    assert "_telegram_befehlsmenue" in {_ast.unparse(c.func) for c in _ast.walk(oben["run_bot"])
                                         if isinstance(c, _ast.Call)}
    for b in B.fuer(B.TG):
        assert 3 <= len(B.beschreibung(b)) <= 100, b.name   # Telegram: 3..256, Discord: <=100

    # ── (4) DISCORD: die geteilten Handler kommen aus dem Verzeichnis, die
    # Rechte stehen am Befehl.
    assert set(K.BEFEHLE) == {b.tg_handler for b in B.discord_ueber_tg()}
    assert "bot_app_holen" in K.BotKontext.__dataclass_fields__
    db = _ast.parse(io.open("discordbot.py", encoding="utf-8").read())
    bot_app_global = [c.lineno for c in _ast.walk(db) if isinstance(c, _ast.Call)
                      and _ast.unparse(c.func) == "globals().get"
                      and c.args and _ast.unparse(c.args[0]) == "'bot_app'"]
    assert not bot_app_global, \
        "discordbot.py liest bot_app wieder aus dem EIGENEN Namensraum " \
        "(Z.%s) — dort gibt es ihn nie, der Highlight-Push endet still" % bot_app_global
    shim = [n for n in db.body if isinstance(n, _ast.AsyncFunctionDef)
            and n.name == "_run_tg_handler"][0]
    assert "_is_admin(inter)" in _ast.unparse(shim.body[0]), \
        "der Shim prueft die Admin-Rolle nicht mehr als erstes"
    assert "application=" in _ast.unparse(shim), \
        "der Shim reicht keine application — /tiktok stirbt am Scraper"
    for fn in _ast.walk(db):
        if not isinstance(fn, _ast.AsyncFunctionDef):
            continue
        for d in fn.decorator_list:
            if "tree.command" not in _ast.unparse(d):
                continue
            name = [_ast.literal_eval(k.value) for k in d.keywords if k.arg == "name"][0]
            b = B.NACH_NAME.get(name)
            assert b is not None and b.discord == "nativ", \
                "/%s ist auf Discord registriert, aber nicht als nativ verzeichnet" % name
            # Ein Riegel ist ein `if not <pruefung>:` mit `return` darin, unter
            # den ersten Anweisungen — nicht bloss irgendein Aufruf von
            # _is_admin (die Hilfe ruft es auch, um die Liste zu filtern).
            def _riegel(stmt):
                return (isinstance(stmt, _ast.If)
                        and _ast.unparse(stmt.test) in ("not await _guard(inter)",
                                                         "not _is_admin(inter)")
                        and any(isinstance(x, _ast.Return) for x in stmt.body))
            if name == "untrack":
                continue        # Sonderriegel (Admin ODER Anleger), Pruefung unten
            geprueft = any(_riegel(x) for x in fn.body[:3])
            assert geprueft == (b.recht == "betreiber"), \
                "/%s: verzeichnet als %r, im Code %s" % (
                    name, b.recht, "mit Riegel" if geprueft else "ohne Riegel")
    unt = [fn for fn in _ast.walk(db) if isinstance(fn, _ast.AsyncFunctionDef)
           and fn.name == "_c_untrack"][0]
    ut = _ast.unparse(unt)
    riegel = [x for x in _ast.walk(unt) if isinstance(x, _ast.If)
              and _ast.unparse(x.test) == "not _is_admin(inter)"]
    assert riegel and "added_by" in _ast.unparse(riegel[0]) \
        and "inter.user.id" in _ast.unparse(riegel[0]) \
        and any(isinstance(x, _ast.Return) for x in _ast.walk(riegel[0])), \
        "/untrack auf Discord ist wieder fuer jeden offen"
    assert "!= inter.user.id" in ut, "/untrack vergleicht den Anleger nicht mehr"
    # Die Pruefung steht VOR dem Loeschen.
    zeilen = {c.lineno: _ast.unparse(c.func) for c in _ast.walk(unt) if isinstance(c, _ast.Call)}
    z_pruef = riegel[0].lineno
    z_weg = min(z for z, f in zeilen.items() if f == "asyncio.to_thread")
    assert z_pruef < z_weg, "/untrack loescht, bevor es prueft"

    # ── (5) DIE HILFE: gebaut, vollstaendig, und ohne Admin nur, was man darf.
    voll = B.hilfe_text(B.DC)
    for b in B.fuer(B.DC):
        assert ("/" + b.name + " ") in voll + " " or ("/" + b.name + "\n") in voll + "\n", b.name
    offen = B.hilfe_text(B.DC, ist_betreiber=False)
    for b in B.fuer(B.DC):
        drin = any(t in offen.split() for t in ("/" + b.name,))
        assert drin == (b.recht == "jeder"), (b.name, b.recht)
    hilfe = [fn for fn in _ast.walk(db) if isinstance(fn, _ast.AsyncFunctionDef)
             and fn.name == "_c_help"][0]
    assert "_nc_befehle.hilfe_text" in _ast.unparse(hilfe), \
        "die Discord-Hilfe ist wieder handgeschrieben"

    ok("W109: ein Verzeichnis — %d Telegram, %d Discord, %d gemeinsam unter "
       "gleichem Namen; Rechte geprueft, Hilfe gebaut, kein sys_ mehr" % (
           len(tg), len(dc), len(tg & dc)))


def _test_v42_w110_lokales_llm_zuerst():
    """Das installierte llama.cpp wurde nicht benutzt — und das Panel brach.

    Der Chat fragte das Brain nur bei AI_PROVIDER=brain, die Reaktions-Engine
    stand auf pollinations, die Modellliste rief eine Methode, die es nicht
    gab, siebenmal stand `== "brain"` verstreut, und brain.html las h.ollama
    — ein Feld, das es seit V37 nicht mehr gibt.
    """
    import ast as _ast
    import glob
    import json as _json
    import threading as _th
    import tokenize as _tok
    from http.server import BaseHTTPRequestHandler, HTTPServer
    from nc import kiwahl as K

    # ── (1) DIE REGEL.
    for wert, soll in (("", "auto"), ("auto", "auto"), ("brain", "lokal"),
                       ("llamacpp", "lokal"), ("LOKAL", "lokal"),
                       ("pollinations", "cloud"), ("freeai", "cloud"),
                       ("cloud", "cloud"), ("groq", "auto"), (None, "auto")):
        assert K.normal(wert) == soll, (wert, K.normal(wert))
    # auto: lokal, wenn oben ODER unbekannt (die erste Anfrage IST die Probe)
    assert K.lokal_zuerst("auto", True) and K.lokal_zuerst("auto", None)
    assert not K.lokal_zuerst("auto", False)
    assert K.lokal_zuerst("brain", False), "lokal heisst: auch bei toter Probe fragen"
    assert not K.lokal_zuerst("pollinations", True), "cloud heisst: nie lokal"
    assert K.backend("cloud", True) == "freeai"
    assert K.backend("auto", True) == "brain" and K.backend("auto", False) == "freeai"
    assert K.backend("auto", None) == "auto", "unbekannt darf nicht als freeai gemeldet werden"

    # ── (2) brain/llm.py: models() gibt es, zuletzt_oben() misst nicht.
    class _Llama(BaseHTTPRequestHandler):
        def do_GET(self):
            body = (b'{"status":"ok"}' if self.path == "/health" else
                    _json.dumps({"data": [{"id": "qwen2.5-1.5b"}]}).encode())
            self.send_response(200)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            # Wie ein mit --embeddings gestarteter Server: /health gruen,
            # der Chat verweigert.
            body = b'{"error":{"code":501,"message":"This server does not support completions."}}'
            self.send_response(501)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, *a):
            pass
    srv = HTTPServer(("127.0.0.1", 0), _Llama)
    _th.Thread(target=srv.serve_forever, daemon=True).start()
    alt_url = os.environ.get("BRAIN_LLAMACPP_URL")
    alt_be = os.environ.get("BRAIN_LLM_BACKEND")
    os.environ["BRAIN_LLAMACPP_URL"] = "http://127.0.0.1:%d" % srv.server_port
    os.environ["BRAIN_LLM_BACKEND"] = "llamacpp"
    try:
        from brain.llm import LLMRuntime
        rt = LLMRuntime()
        assert rt.zuletzt_oben() is None, "vor der ersten Probe ist der Stand unbekannt"
        assert rt.models() == ["qwen2.5-1.5b"], rt.models()
        assert (rt.health().get("llamacpp") or {}).get("up") is True
        assert rt.zuletzt_oben() is True
        # Health gruen, Chat scheitert: das muss im Log stehen — vorher
        # log.debug, und jede Anfrage ging still in die Cloud. Und nur
        # EINMAL je Grund, nicht bei jeder Anfrage.
        import logging as _lg
        zeilen = []

        class _F(_lg.Handler):
            def emit(self, r):
                zeilen.append((r.levelname, r.getMessage()))
        _h = _F()
        _lg.getLogger("brain.llm").addHandler(_h)
        try:
            for _ in range(3):
                res = rt.chat([{"role": "user", "content": "x"}], timeout=5)
                assert res["ok"] is False and "501" in res["error"], res
        finally:
            _lg.getLogger("brain.llm").removeHandler(_h)
        warn = [m for lv, m in zeilen if lv == "WARNING" and "scheitert" in m]
        assert len(warn) == 1 and "501" in warn[0], zeilen
        srv.shutdown()
        srv.server_close()
        rt._models_cache = None
        assert rt.models() == [], "toter Server liefert eine Liste, die es nicht gibt"
    finally:
        for k, v in (("BRAIN_LLAMACPP_URL", alt_url), ("BRAIN_LLM_BACKEND", alt_be)):
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v

    # ── (3) DIE VERDRAHTUNG: drei Chat-Wege fragen kiwahl, keiner liest
    # AI_PROVIDER mehr selbst.
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    oben = {n.name: n for n in baum.body
            if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    for f in ("llm_chat", "llm_chat_sync", "ai_chat"):
        rufe = {_ast.unparse(c.func) for c in _ast.walk(oben[f]) if isinstance(c, _ast.Call)}
        assert "_nc_kiwahl.lokal_zuerst" in rufe, "%s fragt nicht, ob lokal zuerst" % f
    roh = []
    for pfad in ["bot.py"] + sorted(glob.glob("nc/*.py")) + sorted(glob.glob("nc/routes/*.py")):
        if pfad.replace("\\", "/") == "nc/kiwahl.py":
            continue
        for c in _ast.walk(_ast.parse(io.open(pfad, encoding="utf-8").read())):
            if (isinstance(c, _ast.Call) and _ast.unparse(c.func) == "os.getenv"
                    and c.args and _ast.unparse(c.args[0]) == "'AI_PROVIDER'"):
                roh.append("%s:%d" % (pfad, c.lineno))
    assert not roh, "AI_PROVIDER wird wieder selbst gelesen: %s" % roh
    rp = [n for n in baum.body if isinstance(n, _ast.Assign)
          and any(getattr(t, "id", "") == "REACTION_AI_PROVIDER" for t in n.targets)]
    assert rp and "'auto'" in _ast.unparse(rp[0].value), \
        "die Reaktions-Engine steht wieder per Vorgabe auf Cloud"

    # ── (4) KEIN OLLAMA-RAT MEHR AN DEN BENUTZER. Gesucht in Zeichenketten-
    # Tokens ohne Docstrings (W102–W104: nicht im rohen Text — die Kommentare,
    # die die alten Saetze zitieren, sind kein Befund).
    rat = []
    for pfad in ["bot.py", "discordbot.py"] + sorted(glob.glob("nc/*.py")) \
            + sorted(glob.glob("nc/routes/*.py")):
        for t in _tok.generate_tokens(io.open(pfad, encoding="utf-8").readline):
            if (t.type == _tok.STRING and "ollama" in t.string.lower()
                    and t.string.lstrip("rbuRBU")[:3] not in ('"' * 3, "'" * 3)):
                rat.append("%s:%d %s" % (pfad, t.start[0], t.string[:50]))
    assert not rat, "Benutzertext nennt noch Ollama: %s" % rat
    from nc.util import _ai_err_msg
    for art in ("timeout", "unreachable", "http", "model_missing", "other"):
        assert "Ollama" not in _ai_err_msg(art, "m"), art
    assert "llama-server" in _ai_err_msg("unreachable", "m")
    assert "120" in _ai_err_msg("timeout", "m", timeout=120)
    hz = [n for n in _ast.walk(baum) if isinstance(n, _ast.FunctionDef) and n.name == "health"]
    assert hz and "ollama=" not in _ast.unparse(hz[0]) and "llm=" in _ast.unparse(hz[0])

    # ── (5) DAS BRAIN-PANEL: kein h.ollama, und die Werte stehen VOR der
    # Verzweigung (bei backend_conf=off braucht die Tabelle sie auch).
    bh = io.open("templates/brain.html", encoding="utf-8").read()
    i = bh.index("async function loadLLM()")
    fn = bh[i:bh.index("/* ---------------- Fragen", i)]
    code = "\n".join(z for z in fn.splitlines()
                     if not z.strip().startswith(("/*", "*", "//")))
    assert "h.ollama" not in code, "brain.html liest wieder h.ollama — TypeError, Tabelle leer"
    assert code.index("const _lok") < code.index('if (h.backend_conf === "off")')

    # ── (6) DIE MITGELIEFERTE UNIT startet ohne --embeddings (nur Embeddings,
    # kein Chat) und mit genug Kontext.
    unit = io.open("llama-server.service", encoding="utf-8").read()
    exec_ = " ".join(z.strip().rstrip("\\") for z in unit.splitlines()
                     if z.strip() and not z.strip().startswith("#")
                     and (z.startswith("ExecStart") or z.startswith("  ")))
    assert "--embedding" not in exec_, exec_
    assert "-c 8192" in exec_, exec_

    ok("W110: lokales llama.cpp zuerst (auto), Modellliste lokal, ein Ort fuer "
       "die Wahl, kein Ollama-Rat, Brain-Panel rendert, Unit ohne --embeddings")


def _test_v42_w111_schriften_lokal_ein_panel_je_messung():
    """Das Deck lud seine Schriften von Google, und zwei Kaesten zeigten
    dieselbe Messung.

    Die oeffentliche Seite holt ihre Schriften seit W88 lokal — Deck, Overlay
    und Brain-Seite nicht: jede Anfrage trug die IP zu fonts.googleapis.com,
    das Overlay sogar bei jedem Restream-Screenshot. Und „Host Resources"
    zeigte /api/system-resources ein zweites Mal neben „Ressourcen", die
    ✓/✗-Reihe im Ops-Tab eine Teilmenge des Preflights.
    """
    import ast as _ast
    import glob
    import re as _re
    from flask import Flask
    from nc.routes import schriften as S

    # ── (1) KEIN TEMPLATE LAEDT VON GOOGLE. Gemessen ohne Kommentare — die
    # Begruendung darf den Namen nennen, ein <link> nicht.
    for pfad in sorted(glob.glob("templates/*.html")):
        t = io.open(pfad, encoding="utf-8").read()
        t = _re.sub(r"<!--.*?-->", "", t, flags=_re.S)
        t = _re.sub(r"/\*.*?\*/", "", t, flags=_re.S)
        for fremd in ("fonts.googleapis.com", "fonts.gstatic.com"):
            assert fremd not in t, (pfad, fremd)
        if "Orbitron" in t or "JetBrains Mono" in t:
            assert 'href="/fonts/schriften.css"' in t, \
                "%s nutzt die Schriften, laedt sie aber nicht" % pfad

    # ── (2) DIE ROUTE: genau die Liste, sonst 404 — auch fuer Ausbrueche.
    app = Flask("w111")
    app.register_blueprint(S.bp)
    c = app.test_client()
    r = c.get("/fonts/schriften.css")
    assert r.status_code == 200 and r.mimetype == "text/css"
    css = r.get_data(as_text=True)
    assert css.count("@font-face") == len(S.SCHNITTE) == 6
    assert css.count("font-display:swap") == 6
    for datei in S.SCHNITTE:
        assert "/fonts/%s" % datei in css
        r = c.get("/fonts/" + datei)
        assert r.status_code == 200 and r.get_data()[:4] == b"wOF2", datei
        assert "max-age" in r.headers.get("Cache-Control", "")
        r.close()
    for boese in ("bot.py", "..%2Fbot.py", "%2e%2e%2f.env", "orbitron-500.woff",
                  "ORBITRON-500.woff2", "schriften.css.bak", ".env"):
        assert c.get("/fonts/" + boese).status_code == 404, boese
    # Der Dateiname an send_from_directory stammt aus SCHNITTE, nie aus der
    # Anfrage (CodeQL, W98): im Baum darf `name` dort nicht auftauchen.
    baum = _ast.parse(io.open(S.__file__, encoding="utf-8").read())
    for k in _ast.walk(baum):
        if isinstance(k, _ast.Call) and getattr(k.func, "id", "") == "send_from_directory":
            namen = {n.id for a in k.args for n in _ast.walk(a) if isinstance(n, _ast.Name)}
            assert "name" not in namen, "Pfad aus der Anfrage gebaut"

    # ── (3) DER BOT haengt die Route ein und laesst sie ohne Token durch
    # (OBS-Browserquelle auf einem anderen Rechner).
    bb = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    frei = None
    eingehaengt = False
    for k in _ast.walk(bb):
        if isinstance(k, _ast.Assign) and any(getattr(z, "id", "") == "_AUTH_EXEMPT_PREFIXES" for z in k.targets):
            frei = _ast.literal_eval(k.value)
        if isinstance(k, _ast.Call) and getattr(k.func, "attr", "") == "register_blueprint" \
                and k.args and _ast.unparse(k.args[0]) == "_nc_routes_schriften.bp":
            eingehaengt = True
    assert eingehaengt, "Blueprint schriften nicht registriert"
    assert frei and "/fonts/" in frei, frei

    # ── (4) EINE MESSUNG, EIN KASTEN. Im Deck-Code (ohne Kommentare) wird
    # /api/system-resources genau einmal gefragt, #sy_res gibt es nicht mehr,
    # und loadOps6Health zeichnet keine Einzelpruefungen.
    d = io.open("templates/dashboard.html", encoding="utf-8").read()
    d = _re.sub(r"<!--.*?-->", "", d, flags=_re.S)
    d = _re.sub(r"/\*.*?\*/", "", d, flags=_re.S)
    d = "\n".join(z for z in d.splitlines() if not z.strip().startswith("//"))
    assert d.count("'/api/system-resources'") == 1, d.count("'/api/system-resources'")
    assert "sy_res" not in d
    assert "Host Resources" not in d
    i = d.index("async function loadOps6Health(")
    fn = d[i:d.index("\nasync function ", i + 10)]
    assert "/api/ops/healthcheck" in fn and "✓" not in fn, fn
    # … aber die FEHLGESCHLAGENEN bleiben sichtbar: event_loop prueft nur
    # /api/ops/healthcheck, nicht der Preflight (Codex-Befund auf PR #153).
    assert "!d.checks[k]" in fn and "esc(k)" in fn and "ops6_health_rot" in fn, fn
    assert 'id="ops6_health_rot"' in d
    # Gemessen an der Zeile, die mit der Zuweisung BEGINNT — ein Text-Treffer
    # irgendwo im Rumpf faende auch eine abgeschaltete Zeile.
    assert any(z.strip().startswith("if(box) box.innerHTML=rot.map(")
               for z in fn.splitlines()), "fehlgeschlagene Pruefungen werden nicht gezeichnet"

    ok("W111: Schriften lokal (Deck, Overlay, Brain), Route nur fuer die "
       "Liste, ohne Token; Ressourcen und Einzelpruefungen je einmal")


def _test_v42_w112_lagebild():
    """Die Uebersicht zeigt, was passiert — und die Zuordnung ist geprueft.

    Die 3D-Kommandozentrale drehte die fuenf Zahlen der Kacheln darueber ein
    zweites Mal. Das Lagebild zeigt aktive Nutzer, Aufnahmen, den Zustand
    jedes Restreams und was die dreizehn Waechter tun. WAS es zeigt,
    entscheidet nc/lagebild.py; das JS bewegt nur.
    """
    import ast as _ast
    import logging as _logging
    import re as _re
    from flask import Flask
    from nc import lagebild as L

    # ── (1) RESTREAM-LAGE: „live" ist nur der Prozess (B123).
    gut = {"live": True, "targets": {"kick": {}}, "targets_dead": [],
           "ohne_fortschritt_s": 1, "backoff_s": 0, "health": {}}
    assert L.restream_lage(gut) == "gesund"
    for kaputt in ({"live": False}, {"backoff_s": 30},
                   {"ohne_fortschritt_s": L.GESTOERT_AB_S},
                   {"targets_dead": ["kick"]}):
        assert L.restream_lage(dict(gut, **kaputt)) == "gestoert", kaputt
    zwei = dict(gut, targets={"kick": {}, "yt": {}})
    for lahm in ({"ohne_fortschritt_s": L.LANGSAM_AB_S}, {"targets_dead": ["yt"]},
                 {"health": {"slow_ticks": 5}}, {"health": {"slow_warned": True}}):
        assert L.restream_lage(dict(zwei, **lahm)) == "langsam", lahm
    # Unabhaengige Relays (independent-Modus): eins steht oder fehlt, der
    # Hauptstrom laeuft — das ist eine ausgefallene Plattform, nicht gesund.
    relay_gut = {"pid": 4711, "ohne_fortschritt_s": 1, "health": {}}
    assert L.restream_lage(dict(gut, relays={"twitch": relay_gut})) == "gesund"
    for kaputt_relay in ({"ohne_fortschritt_s": L.LANGSAM_AB_S}, {"pid": None},
                         {"health": {"slow_warned": True}}):
        r = dict(gut, relays={"twitch": relay_gut, "youtube": dict(relay_gut, **kaputt_relay)})
        assert L.restream_lage(r) == "langsam", kaputt_relay

    # ── (2) ZIELE: nur wer etwas tut; der schlechteste Restream zaehlt;
    # Stoerungen vorn, feste Reihenfolge.
    tr = [{"username": "@Anna", "last_live": 1, "recording": 1},
          {"username": "bert", "last_live": 1, "recording": 0},
          {"username": "carl", "last_live": 0, "recording": 0}]
    # Der gestoerte ZUERST: sonst gewaenne er auch mit „der letzte zaehlt".
    rs = [dict(gut, user="bert", live=False), dict(gut, user="bert"),
          dict(gut, user="dora")]
    d = L.bauen(tr, rs, [], {}, 1000.0, quellen={"brain": False})
    namen = [z["name"] for z in d["ziele"]]
    assert namen == ["bert", "dora", "anna"], namen
    assert d["ziele"][0]["restream"] == "gestoert", "ein gesunder zweiter faerbt den gestoerten gruen"
    assert "carl" not in namen and d["getrackt"] == 3
    # Pausiert: das gespeicherte last_live ist eingefroren und zaehlt nicht;
    # eine laufende Aufnahme oder ein Restream zaehlt weiter.
    pz = L.bauen([{"username": "paul", "last_live": 1, "paused": 1},
                  {"username": "pia", "last_live": 1, "paused": 1, "recording": 1}],
                 [], [], {}, 0.0)
    assert [z["name"] for z in pz["ziele"]] == ["pia"], pz["ziele"]
    assert pz["ziele"][0]["pausiert"] is True
    assert d["quellen"] == {"brain": False}, "Ausfall einer Quelle geht verloren"
    viele = [{"username": "u%02d" % i, "last_live": 1} for i in range(L.MAX_ZIELE + 5)]
    dv = L.bauen(viele, [], [], {}, 0.0)
    assert len(dv["ziele"]) == L.MAX_ZIELE and dv["weitere"] == 5

    # ── (3) WAECHTER: aus / fehler / taetig / ruht, und nie ein erfundenes Ziel.
    def ag(name, **kw):
        a = {"name": name, "enabled": True, "last_run": 1000.0 - 500, "runs": 1, "errors": 0}
        a.update(kw)
        return a
    jetzt = 1000.0
    w = {a["name"]: a for a in L.bauen(tr, rs, [
        ag("disk", last_run=jetzt - 3), ag("swap", enabled=False, last_run=jetzt - 1),
        ag("proxy", last_run=jetzt - 1), ag("health"),
        ag("recording", last_run=jetzt - 2), ag("restream_sentinel", last_run=jetzt - 2),
        ag("unbekannt"), ag("scout", last_run=jetzt - L.TAETIG_S)],
        {"proxy": {"state": "error"}}, jetzt)["agenten"]}
    assert w["disk"]["lage"] == "taetig" and w["disk"]["ort"] == "platte"
    assert w["swap"]["lage"] == "aus", "abgeschalteter Waechter patrouilliert"
    assert w["proxy"]["lage"] == "fehler", "Fehler wird von taetig ueberdeckt"
    assert w["health"]["lage"] == "ruht"
    assert w["scout"]["lage"] == "ruht", "Nachlauf ist nicht bei TAETIG_S zu Ende"
    assert w["recording"]["ziel"] == "anna" and w["recording"]["ort"] == "ziel"
    assert w["restream_sentinel"]["ziel"] == "bert", "Restream-Waechter nicht dort, wo es brennt"
    assert w["unbekannt"]["ort"] == "kern", "unbekannter Waechter verschwindet"
    ohne = {a["name"]: a for a in L.bauen(
        [{"username": "x", "last_live": 1}], [], [ag("recording"), ag("restream_sentinel")],
        {}, jetzt)["agenten"]}
    assert ohne["recording"]["ziel"] is None and ohne["recording"]["ort"] == "kern", \
        "Aufnahme-Waechter an einem Nutzer, der nicht aufnimmt"
    assert ohne["restream_sentinel"]["ziel"] is None
    # Die Wahl unter mehreren Live-Zielen ist fest (springt nicht je Poll) und
    # nicht immer die erste — sonst klebten alle Waechter am selben Nutzer.
    vier = [{"username": n, "last_live": 1} for n in ("a1", "b2", "c3", "d4")]
    wahl = {L.bauen(vier, [], [ag("scout", last_run=jetzt - 1)], {}, jetzt)["agenten"][0]["ziel"]
            for _ in range(3)}
    assert wahl == {("a1", "b2", "c3", "d4")[sum(map(ord, "scout")) % 4]}, wahl
    assert wahl != {"a1"}

    # ── (4) ORT kennt GENAU die registrierten Waechter — gemessen am Baum von
    # brain_bridge.py (register-Aufrufe) und brain/agents.py (name-Attribute).
    klassen = set()
    for k in _ast.walk(_ast.parse(io.open("brain_bridge.py", encoding="utf-8").read())):
        if isinstance(k, _ast.Call) and getattr(k.func, "attr", "") == "register" \
                and k.args and isinstance(k.args[0], _ast.Call):
            klassen.add(getattr(k.args[0].func, "id", ""))
    registriert = set()
    for k in _ast.parse(io.open("brain/agents.py", encoding="utf-8").read()).body:
        if isinstance(k, _ast.ClassDef) and k.name in klassen:
            for z in k.body:
                if isinstance(z, _ast.Assign) and getattr(z.targets[0], "id", "") == "name":
                    registriert.add(z.value.value)
    # ANKER GEWANDERT (v4.2-W146): der Datenbank-Waechter, vierzehn;
    # (v4.2-W148): Prometheus und Grafana, sechzehn.
    assert len(registriert) == 16, registriert
    assert registriert == set(L.ORT), (registriert ^ set(L.ORT))
    for ort in L.ORT.values():
        assert ort.startswith("ziel:") or ort in L.STATIONEN, ort

    # ── (5) DIE ROUTE: eine Quelle faellt, die anderen bleiben, und der
    # Ausfall steht in `quellen` UND im Log.
    from nc.routes import lagebild as R
    alt = (R._trackings, R._restreams, R._agenten)
    gelesen = []

    class _Fang(_logging.Handler):
        def emit(self, rec):
            gelesen.append(rec.getMessage())
    fang = _Fang()
    _logging.getLogger("TikTokBot").addHandler(fang)
    try:
        R._trackings = lambda: [{"username": "anna", "last_live": 1, "recording": 1}]
        R._restreams = lambda: []

        def _kaputt():
            raise RuntimeError("brain weg")
        R._agenten = _kaputt
        app = Flask("w112")
        app.register_blueprint(R.bp)
        r = app.test_client().get("/api/lagebild")
        assert r.status_code == 200
        j = r.get_json()
        assert j["quellen"] == {"trackings": True, "restream": True, "brain": False}, j["quellen"]
        assert [z["name"] for z in j["ziele"]] == ["anna"]
        assert any("Quelle brain" in m for m in gelesen), gelesen
    finally:
        R._trackings, R._restreams, R._agenten = alt
        _logging.getLogger("TikTokBot").removeHandler(fang)
    src = io.open("bot.py", encoding="utf-8").read()
    assert "dashboard_app.register_blueprint(_nc_routes_lagebild.bp)" in src

    # ── (6) DIE ZEICHNUNG: im Deck-Code ohne Kommentare.
    h = io.open("templates/dashboard.html", encoding="utf-8").read()
    i = h.index("var ncLagebild=(function(){")
    js = h[i:h.index("\n})();", i)]
    js = _re.sub(r"/\*.*?\*/", "", js, flags=_re.S)
    assert "'/api/lagebild'" in js
    assert "innerHTML" not in js, "Nutzernamen duerfen nie in innerHTML"
    assert "prefers-reduced-motion: reduce" in js
    # Der Takt bricht bei reduzierter Bewegung, verdeckter Uebersicht oder
    # verstecktem Tab ab — gemessen an der Zeile, die mit dem Abbruch BEGINNT.
    takt = js[js.index("function takt("):js.index("function kick(")]
    zeile = [z.strip() for z in takt.splitlines() if z.strip().startswith("if(CURRENT_VIEW!==OWNVIEW")]
    assert zeile and all(t in zeile[0] for t in ("document.hidden", "reduce", "raf=null;return;")), zeile
    # Bei reduzierter Bewegung stehen die Waechter sofort am Ziel, ohne Spur.
    setze = js[js.index("function setze("):js.index("function zielVon(")]
    assert any(z.strip().startswith("if(reduce){") and "s.x=z.x" in z and "s.spur=[]" in z
               for z in setze.splitlines()), "Standbild setzt die Waechter nicht ans Ziel"
    assert "ncLagebild.start('ov_cc','overview')" in h
    assert 'id="ov_lage_text"' in h and "textContent" in js, "keine Textfassung fuer Screenreader"
    # Jede Station, die nc/lagebild.py kennt, hat einen Platz auf der Leinwand.
    for st in L.STATIONEN:
        assert _re.search(r"\b%s:\{a:" % st, js), "Station %s fehlt im Lagebild" % st

    ok("W112: Lagebild — Restream-Lage ehrlich, Waechter je Arbeitsort, kein "
       "erfundenes Ziel, Quellen-Ausfall sichtbar, Standbild bei reduzierter Bewegung")


def _test_v42_w113_website_ruhig_und_lesbar():
    """Die oeffentliche Seite: ein Designsystem, kein Kippen, nichts versteckt.

    Bis W112 trug jede der drei Seiten ihr eigenes Grundgeruest, die Startseite
    kippte Sektionen beim Scrollen (unscharfer Fliesstext), blendete Inhalt
    erst beim Hineinscrollen ein (gedruckt und als Vorschau: leere Flaechen),
    und drei 3D-Leinwaende liefen ununterbrochen, auch weit unterhalb des
    sichtbaren Bereichs.
    """
    import re as _re
    seiten = {n: io.open("website/%s.html" % n, encoding="utf-8").read()
              for n in ("lafap_index", "impressum", "datenschutz")}
    css = io.open("website/raum.css", encoding="utf-8").read()

    # ── (1) EIN System fuer drei Seiten, Schriften je Seite lokal.
    for n, w in seiten.items():
        assert _re.search(r'<link rel="stylesheet" href="raum\.css\?v=[0-9a-f]+">', w), n
        assert "d3-schalter" not in w, n
        assert not _re.search(r"(?:href|src)\s*=\s*[\"'][^\"']*fonts\.(?:googleapis|gstatic)", w), n
        assert "@font-face" in w and "fonts/orbitron" in w, n
    for n in ("impressum", "datenschutz"):
        stil = seiten[n][seiten[n].index("<style>"):seiten[n].index("</style>")]
        stil = _re.sub(r"/\*.*?\*/", "", stil, flags=_re.S)
        assert _re.sub(r"@font-face\{[^}]*\}", "", stil).strip() == "<style>", \
            "%s traegt wieder ein eigenes Grundgeruest neben raum.css" % n
        assert '<body class="recht">' in seiten[n], n

    # Auch eine url() in CSS holt von aussen — nicht nur ein href/src.
    for n, quelle in list(seiten.items()) + [("raum.css", css)]:
        ohne = _re.sub(r"/\*.*?\*/|<!--.*?-->", "", quelle, flags=_re.S)
        assert not _re.search(r"url\(\s*['\"]?\s*(?:https?:)?//", ohne), \
            "%s laedt per url() von aussen" % n

    # ── (2) .bar heisst auch jeder Diagrammbalken: in raum.css darf die
    # Kopfleisten-Regel nur ueber `header .bar` greifen (sonst 0-px-Balken).
    code = _re.sub(r"/\*.*?\*/", "", css, flags=_re.S)
    assert not _re.search(r"(?:^|[},])\s*\.bar\s*\{", code), "nackte .bar-Regel in raum.css"
    assert "header .bar{" in code

    # ── (3) STARTSEITE.
    w = seiten["lafap_index"]
    # Die Inline-Skripte per Zeichenkettensuche, nicht per Regex: ein Muster
    # wie <script>(.*?)</script> meldet CodeQL als HTML-Filter, der
    # Grossschreibung nicht kennt — hier wird nichts gefiltert, nur die
    # eigene Datei gelesen, aber eine rote Pruefung bleibt rot.
    teile, pos = [], 0
    while w.find("<script>", pos) >= 0:
        a = w.find("<script>", pos) + len("<script>")
        pos = w.index("</script>", a)
        teile.append(w[a:pos])
    js = "\n".join(teile)
    jsc = _re.sub(r"/\*.*?\*/", "", js, flags=_re.S)
    # Kein Scroll-Einblenden mehr: nichts ist versteckt, bis man hinscrollt.
    assert not _re.search(r'class="[^"]*\brv\b', w), "Einblend-Klasse .rv wieder im Markup"
    assert "classList.add('in')" not in jsc
    # Die drei Leinwaende zeichnen nur, solange sie im Bild sind.
    zeilen = [z.strip() for z in jsc.splitlines()]
    assert sum(z.startswith("function loop(){ if(document.hidden||!window.__imBild(cv))")
               for z in zeilen) == 3, "eine Leinwand zeichnet auch ausserhalb des Bildes"
    assert sum(z == "cv.__weiter=kick;" for z in zeilen) == 3, "eine Leinwand wacht nicht wieder auf"
    beob = jsc[jsc.index("new IntersectionObserver"):]
    beob = beob[:beob.index("})();")]
    for leinwand in ("sentinel-core", "usage-3d", "don-3d"):
        assert "'%s'" % leinwand in beob, "nicht beobachtet: " + leinwand
    # Die Hauptueberschrift ist EIN Satz aus ganzen Woertern.
    h1 = _re.search(r"<h1[^>]*>(.*?)</h1>", w, flags=_re.S).group(1)
    assert "glyph" not in h1, "Anfangsbuchstaben wieder als eigene Textknoten"
    assert " ".join(_re.sub(r"<[^>]+>", " ", h1).split()) == "Logik Absolut Fehl am Platz", h1
    # Diagrammbalken: Zahl und Balken im eigenen Schacht.
    assert jsc.count('<div class="slot"><span class="v" style="bottom:calc(') == 2
    # Navigation: jedes Sprungziel existiert, Quellcode steht direkt hinter Azrael.
    nav = w[w.index('<nav aria-label="Seitennavigation">'):w.index("</nav>")]
    ids = _re.findall(r'<section id="([^"]+)"', w)
    for ziel in _re.findall(r'href="#([^"]+)"', nav):
        assert ('id="%s"' % ziel) in w, "Navigation zeigt ins Leere: #" + ziel
    assert ids.index("quellcode") == ids.index("azrael") + 1, ids
    for pflicht in ("ueber", "lagebild", "monitor", "azrael", "quellcode",
                    "news", "ressourcen", "grundsaetze"):
        assert pflicht in ids, pflicht
    assert w.count("<section") == w.count("</section>")

    ok("W113: Website — ein Designsystem fuer drei Seiten, kein Kippen, nichts "
       "versteckt, Leinwaende nur im Bild, Balken im eigenen Schacht")


def _test_v42_w114_tonspur_garantie_im_preflight():
    """Der Preflight meldet, ob die Ton-Garantie ueberhaupt greifen kann.

    W106 sichert jede Ausgabe mit einer Stille-Spur ab — ueber den
    lavfi-Eingang anullsrc und den AAC-Encoder. Fehlt eins davon (abgespeckte
    ffmpeg-Builds), stirbt der Rueckfall genau dann, wenn eine Quelle keinen
    Ton hat. „ffmpeg installiert" sagte darueber nichts.
    """
    import ast as _ast
    import os as _os
    import stat as _stat
    import pruefhilfen as P
    from nc import tonspur as Tn

    # ── (1) Der Probelauf benutzt DENSELBEN Eingang und Encoder wie die
    # Produktion — sonst prueft er etwas anderes, als dann gebraucht wird.
    cmd = Tn.garantie_cmd()
    # _bau setzt je nach Konfiguration nice/-threads davor; dass es benutzt
    # wird, haelt der Thread-Deckel-Vertrag in test_restream fest.
    # Ausgabe in den Muxer der Produktion (FLV), nicht in `null` — den
    # braucht die Produktion nie, ein Build ohne ihn waere sonst „fail".
    assert "ffmpeg" in cmd and cmd[-3:] == ["-f", "flv", "pipe:1"], cmd
    assert "null" not in cmd
    s_ein = Tn.stille_eingabe()
    i = cmd.index(s_ein[0])
    assert cmd[i:i + len(s_ein)] == s_ein, "anderer Stille-Eingang als in der Produktion"
    j = cmd.index(Tn.AAC_ARGS[0])
    assert tuple(cmd[j:j + len(Tn.AAC_ARGS)]) == Tn.AAC_ARGS, "anderer Encoder als in der Produktion"

    # ── (2) Attrappen-ffmpeg im PATH: Erfolg, fehlender Filter, Haenger.
    heim = P.verzeichnis()

    def ffmpeg_attrappe(rumpf):
        pfad = _os.path.join(heim, "ffmpeg")
        with open(pfad, "w") as f:
            f.write("#!/bin/sh\n" + rumpf + "\n")
        _os.chmod(pfad, _os.stat(pfad).st_mode | _stat.S_IEXEC)

    import shutil as _sh
    alt = _os.environ.get("PATH", "")
    try:
        _os.environ["PATH"] = heim
        assert Tn.garantie()[0] == "fail", "ohne ffmpeg darf die Garantie nicht ok sein"
        ffmpeg_attrappe("exit 0")
        assert Tn.garantie() == ("ok", "Stille-Spur (anullsrc) und AAC verfuegbar")
        ffmpeg_attrappe("echo \"[AVFilterGraph] No such filter: 'anullsrc'\" >&2; exit 1")
        st, txt = Tn.garantie()
        assert st == "fail" and "No such filter: 'anullsrc'" in txt and "Abhilfe" in txt, txt
        ffmpeg_attrappe("exec %s 5" % (_sh.which("sleep", path=alt) or "/bin/sleep"))
        st, txt = Tn.garantie(timeout=1)
        assert st == "warn" and "ungeprueft" in txt, (st, txt)
    finally:
        _os.environ["PATH"] = alt
    # Ein OSError-Text (Pfade, Rechte) gehoert ins Log, nie in die Antwort,
    # die der Browser liest (CodeQL auf PR #156).
    import subprocess as _subp
    _echt = _subp.run

    def _kaputt(*a, **k):
        raise PermissionError("/geheim/pfad/ffmpeg: Zugriff verweigert")
    try:
        _subp.run = _kaputt
        st, txt = Tn.garantie()
    finally:
        _subp.run = _echt
    assert st == "fail" and "/geheim" not in txt and "Log" in txt, txt

    # ── (3) Das echte ffmpeg dieser Maschine (wenn vorhanden) kann es.
    if _sh.which("ffmpeg"):
        assert Tn.garantie()[0] == "ok", Tn.garantie()

    # ── (4) Beide Anzeigen fragen es ab: Preflight (rot moeglich) und
    # Selbsttest (hoechstens Warnung — der Bot laeuft ja).
    def aufrufe(baum, fn=None):
        wurzel = baum
        if fn:
            wurzel = next(k for k in _ast.walk(baum)
                          if isinstance(k, (_ast.FunctionDef, _ast.AsyncFunctionDef)) and k.name == fn)
        g = any(isinstance(k, _ast.Call) and _ast.unparse(k.func) == "_nc_tonspur.garantie"
                for k in _ast.walk(wurzel))
        adds = [k for k in _ast.walk(wurzel) if isinstance(k, _ast.Call)
                and getattr(k.func, "id", "") == "add"
                and any(isinstance(a, _ast.Constant) and a.value == "Tonspur-Garantie" for a in k.args)]
        return g, adds
    g, adds = aufrufe(_ast.parse(io.open("nc/routes/systemlage.py", encoding="utf-8").read()))
    assert g and adds and _ast.unparse(adds[0].args[0]) == "'Aufnahme'", "Preflight prueft die Garantie nicht"
    g, adds = aufrufe(_ast.parse(io.open("bot.py", encoding="utf-8").read()), "_selfcheck")
    assert g and adds, "Selbsttest prueft die Garantie nicht"
    stufe = _ast.unparse(adds[0].args[0])
    # Genau „ok oder Warnung" — ein durchgereichtes _st machte aus einem
    # fehlenden anullsrc einen Startfehler (W100: Fehler = nicht STARTKLAR).
    assert stufe == "'ok' if _st == 'ok' else 'warn'", \
        "Selbsttest macht daraus womoeglich einen Startfehler: " + stufe

    ok("W114: Tonspur-Garantie (anullsrc + AAC) im Preflight und Selbsttest, "
       "mit derselben Kommandozeile wie die Produktion")


def _test_v42_w115_quadratische_pixel():
    """Der Restream liefert quadratische Pixel — auch aus einer schiefen Quelle.

    Gemessen (ffmpeg 6.1): eine Quelle 960x720 mit SAR 4:3 (Anzeige 16:9) kam
    in drei der vier Transcode-Wege als 960x720/4:3 heraus. Das Verhaeltnis
    reiste nur als Metadatum mit; eine Plattform, die es ignoriert, zeigt
    gestaucht, und das HTML-Overlay (scale2ref in Speicherpixeln) sass
    verzerrt. Im Studio-Modus war die Leinwand quadratisch, das Video darin
    aber in Speicherpixeln skaliert.
    """
    import ast as _ast
    import json as _json
    import os as _os
    import shutil as _sh
    import subprocess as _sp
    import threading as _th
    from http.server import HTTPServer, SimpleHTTPRequestHandler
    import functools as _ft
    import pruefhilfen as P
    from nc import ffmpeg_filters as F
    from nc import restreamcmd as R
    from nc import tonspur as T

    # ── (1) DIE RECHNUNG — dieselbe Rundung wie QUADRAT.
    for ein, aus in (("960x720x4:3", (1280, 720)), ("1280x720x1:1", (1280, 720)),
                     ("1280x720", (1280, 720)), ("1280x720x0:1", (1280, 720)),
                     ("1280x720xN/A", (1280, 720)), ("721x480x3:2", (1080, 480)),
                     ("", None), ("x", None)):
        assert F.anzeige_groesse(ein) == aus, (ein, F.anzeige_groesse(ein))
    assert F.QUADRAT == "scale=trunc(iw*sar/2)*2:ih,setsar=1"
    pr = next(k for k in _ast.walk(_ast.parse(io.open("bot.py", encoding="utf-8").read()))
              if isinstance(k, _ast.FunctionDef) and k.name == "_probe_video_size")
    prq = _ast.unparse(pr)
    assert "sample_aspect_ratio" in prq and "_nc_ff.anzeige_groesse(" in prq, \
        "Overlay-Groesse wieder in Speicherpixeln"

    # ── (2) JEDE TRANSCODE-VARIANTE beginnt mit der Quadrat-Stufe, und
    # nichts greift an ihr vorbei auf [0:v].
    heim = P.verzeichnis()
    OV = {}
    for k in ("alert", "brand", "caption", "chat", "follow", "goal", "react", "source", "title"):
        OV[k] = _os.path.join(heim, k + ".txt")
        open(OV[k], "w").write(k)
    schrift = _os.path.join(heim, "s.ttf")
    open(schrift, "wb").write(b"x")
    avatar = _os.path.join(heim, "a.png")
    open(avatar, "wb").write(b"x")
    alt_layout = R._restream_layout_mode

    def konf(overlay, av, layout, font=schrift):
        R.configure(cookie_header=lambda: "", pick_pull_proxy=lambda: "",
                    restream_overlay_files=lambda rid=None: OV,
                    FFMPEG_THREADS_LIVE=2, FFMPEG_THREADS_RELAY=2,
                    RESTREAM_AVATAR=(avatar if av else ""), RESTREAM_BITRATE_K=2500,
                    RESTREAM_AVATAR_ALPHA="", RESTREAM_AVATAR_H=170, RESTREAM_AVATAR_LOOP="",
                    RESTREAM_CANVAS_H=720, RESTREAM_CANVAS_W=1280, RESTREAM_FONT=font,
                    RESTREAM_FPS=24, RESTREAM_LOW_LATENCY=True, RESTREAM_OVERLAY=overlay,
                    RESTREAM_OVERLAY_HTML_FPS=1, RESTREAM_RELAY_BITRATE_K=2000,
                    RESTREAM_RELAY_PRESET="ultrafast", RESTREAM_X264_PRESET="ultrafast",
                    RESTREAM_UA="UA/1.0", TTS_CH=2, TTS_SR=44100, TTS_VOICE_GAIN="1.8")
        R._restream_layout_mode = lambda: layout

    faelle = 0
    try:
        for overlay in (False, True):
            for av in (False, True):
                for layout in ("burnin", "studio"):
                    konf(overlay, av, layout)
                    for html in (None, "/tmp/ov.fifo"):
                        for tts in (None, "/tmp/tts.fifo"):
                            for dr in (0, 3, 5):
                                cmd = R.build("https://x/s.flv", "", "", transcode=True,
                                              drossel=dr, html_ov_fifo=html, tts_fifo=tts,
                                              only_target="rtmp://x/app/K")
                                fall = (overlay, av, layout, html, tts, dr)
                                faelle += 1
                                assert cmd[cmd.index("-pix_fmt") + 1] == "yuv420p", fall
                                assert T.hat_tonspur(cmd), fall
                                if "-filter_complex" in cmd:
                                    fc = cmd[cmd.index("-filter_complex") + 1]
                                    # GENAU ein Zugriff auf das Rohbild, irgendwo im
                                    # Graphen — und der ist die Quadrat-Stufe.
                                    assert fc.count("[0:v]") == 1 and \
                                        ("[0:v]" + F.QUADRAT) in fc, (fall, fc[:300])
                                    assert "-vf" not in cmd, fall
                                    for teil in fc.split(";"):
                                        if "overlay=" in teil and "[cnv]" not in teil:
                                            assert "eof_action=repeat" in teil, (fall, teil)
                                    maps = [cmd[j + 1] for j, a in enumerate(cmd) if a == "-map"]
                                    assert not any(m.startswith("0:v") for m in maps), (fall, maps)
                                else:
                                    vf = cmd[cmd.index("-vf") + 1]
                                    assert vf.startswith(F.QUADRAT), (fall, vf)
        # Ohne Transcode gibt es keinen Filter — und darf auch keinen geben.
        konf(True, True, "burnin")
        kopie = R.build("https://x/s.flv", "", "", transcode=False, only_target="rtmp://x/app/K")
        assert "-vf" not in kopie and "-filter_complex" not in kopie
    finally:
        R._restream_layout_mode = alt_layout
    assert faelle == 2 * 2 * 2 * 2 * 2 * 3, faelle

    # ── (3) ECHTES FFMPEG gegen eine schiefe Quelle ueber HTTP (wie in der
    # Produktion: -user_agent ist eine HTTP-Option).
    if _sh.which("ffmpeg") and _sh.which("ffprobe"):
        quelle = _os.path.join(heim, "q.flv")
        _sp.run(["ffmpeg", "-nostdin", "-loglevel", "error", "-f", "lavfi", "-i",
                 "testsrc2=s=960x720:r=24", "-f", "lavfi", "-i", "sine=sample_rate=44100",
                 "-t", "2", "-vf", "setsar=4/3", "-c:v", "libx264", "-preset", "ultrafast",
                 "-pix_fmt", "yuv420p", "-c:a", "aac", "-f", "flv", quelle],
                check=True, stdin=_sp.DEVNULL)
        class _Leise(SimpleHTTPRequestHandler):
            def log_message(self, *a):
                pass       # Zugriffslog des Testservers gehoert nicht in die Suite
        srv = HTTPServer(("127.0.0.1", 0), _ft.partial(_Leise, directory=heim))
        _th.Thread(target=srv.serve_forever, daemon=True).start()
        url = "http://127.0.0.1:%d/q.flv" % srv.server_address[1]
        schriftart = next((p for p in ("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",)
                           if _os.path.exists(p)), None)
        try:
            for overlay in ((False, True) if schriftart else (False,)):
                konf(overlay, False, "burnin", font=schriftart or schrift)
                cmd = R.build(url, "", "", transcode=True, only_target="rtmp://x/app/K")
                aus = _os.path.join(heim, "aus%d.flv" % overlay)
                cmd = cmd[:-1] + ["-t", "1", "-y", aus]
                p = _sp.run(cmd, capture_output=True, text=True, timeout=120, stdin=_sp.DEVNULL)
                assert p.returncode == 0, p.stderr[-500:]
                v = _json.loads(_sp.run(
                    ["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries",
                     "stream=width,height,sample_aspect_ratio", "-of", "json", aus],
                    capture_output=True, text=True).stdout)["streams"][0]
                assert (v["width"], v["height"], v.get("sample_aspect_ratio", "1:1")) == \
                    (1280, 720, "1:1"), (overlay, v)
        finally:
            srv.shutdown()
            R._restream_layout_mode = alt_layout

    ok("W115: quadratische Pixel in allen %d Transcode-Varianten, Overlay-Groesse "
       "in Anzeigepixeln, echte 4:3-Pixel-Quelle kommt als 1280x720/1:1 an" % faelle)


def _test_v42_w116_lagebild_in_echtzeit():
    """Alle dreizehn Waechter zeigen in Echtzeit, woran sie sind.

    Gemeldet mit Bildschirmfoto: „macht keinen Sinn, wenn 13 Agenten arbeiten
    nur 3 sich visuell bewegen". Ein Waechter galt nur die 20 s nach seinem
    Lauf als taetig, bei Takten von 120 bis 600 s; der Rest trieb ziellos am
    Kern. Dazu lagen Statuszeile und Stationsnamen IM Bild ueber den Namen
    der Nutzer, und abgerufen wurde alle 8 s.
    """
    import re as _re
    from nc import lagebild as L

    # ── (1) TAKT-SEMANTIK
    def ag(name, **kw):
        a = {"name": name, "enabled": True, "interval_s": 300, "last_run": 900.0,
             "runs": 4, "findings": 2, "errors": 0, "last_ms": 3.0}
        a.update(kw)
        return a
    jetzt = 1000.0
    w = {a["name"]: a for a in L.bauen([], [], [
        ag("disk"), ag("swap", last_run=0), ag("scout", interval_s=60, last_run=1000 - 181),
        ag("health", interval_s=60, last_run=1000 - 180),
        # abgeschaltet UND lange nicht gelaufen: trotzdem nicht ueberfaellig —
        # wer ihn bewusst abgeschaltet hat, braucht keinen Alarm dafuer.
        ag("proxy", enabled=False, last_run=1000 - 5000),
        ag("uptime", interval_s=None)], {}, jetzt)["agenten"]}
    assert w["disk"]["takt_s"] == 300 and w["disk"]["faellig_in_s"] == 200, w["disk"]
    assert w["disk"]["befunde"] == 2 and w["disk"]["laeufe"] == 4
    assert w["swap"]["faellig_in_s"] == 0, "nie gelaufen heisst faellig"
    assert w["scout"]["ueberfaellig"] and not w["health"]["ueberfaellig"], \
        "ueberfaellig erst NACH drei verpassten Takten"
    assert w["proxy"]["faellig_in_s"] is None and not w["proxy"]["ueberfaellig"], \
        "ein abgeschalteter Waechter ist weder faellig noch ueberfaellig"
    assert w["uptime"]["faellig_in_s"] is None, "ohne Takt kein erfundener Countdown"
    assert L.bauen([], [], [], {}, jetzt)["jetzt"] == jetzt, "ohne Serverzeit kein Countdown"

    # ── (2) DIE ZEICHNUNG
    h = io.open("templates/dashboard.html", encoding="utf-8").read()
    i = h.index("var ncLagebild=(function(){")
    js = _re.sub(r"/\*.*?\*/", "", h[i:h.index("\n})();", i)], flags=_re.S)
    zeilen = [z.strip() for z in js.splitlines()]
    # Echtzeit: alle 2 s neue Lage, jede Sekunde Countdown — beides nur,
    # solange die Uebersicht vorn und der Tab sichtbar ist.
    for ms, ruf in (("2000", "laden();"), ("1000", "tafel(false);")):
        treffer = [z for z in zeilen if ("},%s);" % ms) in z and ruf in z]
        assert treffer and all("CURRENT_VIEW===OWNVIEW" in z and "!document.hidden" in z
                               for z in treffer), (ms, treffer)
    # Jeder Waechter hat einen Arbeitsplatz: die Bahn haengt an ortXY, nicht
    # an einer Kreisbahn um den Kern.
    zv = js[js.index("function zielVon("):js.index("function fortschritt(")]
    assert "p=ortXY(s)" in zv, "Waechter treiben wieder ohne Arbeitsplatz"
    # Ein echter Lauf (laeufe steigt) wird als Einsatz gezeigt.
    assert any(z.startswith("if(s.a&&a.laeufe>s.a.laeufe) einsaetze.push(") for z in zeilen)
    # Kein Status mehr im Bild: Statusleiste und Tafel stehen im DOM.
    assert "function hud(" not in js and 'getElementById(\'ov_lage_kopf\')' in js \
        and 'getElementById(\'ov_lage_tafel\')' in js
    assert 'id="ov_lage_kopf"' in h and 'id="ov_lage_tafel"' in h
    assert "innerHTML" not in js
    # Fehler und Ueberfaellig gehen in der Tafel vor dem Countdown.
    tf = js[js.index("function tafel("):js.index("function text(")]
    zst = next(z for z in tf.splitlines() if ".lt-zustand').textContent=" in z)
    zst += tf.split(zst, 1)[1].split(";", 1)[0]
    assert zst.index("LAGE.ueber") < zst.index("lauf||"), zst
    assert "a.lage==='fehler'?LAGE.fehler" in zst, zst
    # Die Textfassung haengt am INHALT, nicht an der Zahl: tauscht ein Nutzer
    # mit einem anderen, muss der neue Name vorgelesen werden.
    tx = js[js.index("function text("):js.index("function laden(")]
    sl = next(z.strip() for z in tx.splitlines() if z.strip().startswith("var schluessel="))
    assert "posten.join(" in sl, sl
    assert "getAttribute('data-stand')!==schluessel" in tx

    ok("W116: Lagebild in Echtzeit — Takt, Countdown und Ueberfaellig je Waechter, "
       "fester Arbeitsplatz, Einsatz bei echtem Lauf, Status im DOM")


def _test_v42_w117_loop_lag_und_spaeher():
    """Zwischen den beiden Loop-Waechtern lagen zwei Groessenordnungen.

    `_loop_lag_monitor` (W48) meldet ab 3 s, der Stall-Watchdog (W83) dumpt
    ab 30 s. Ein Loop, der alle paar Sekunden 800 ms steht, erreichte keine
    der beiden Schwellen — und es gab weder eine Zahl dafuer noch eine
    Stelle. nc/looplag.py misst in kurzen Schritten und nennt beim Stocken
    die Zeile, an der der Loop-Thread steht.
    """
    import asyncio as _aio
    import queue as _q
    import time as _t
    from nc import looplag as L

    # ── (1) DER RING HAT EINEN DECKEL. Ein Messpfad, der ueber Tage
    # waechst, ist genau das Leck, das dieser Sprint sucht.
    L.zuruecksetzen()
    for _ in range(L.RING + 500):
        L.erfassen(0.001)
    assert len(L.ZUSTAND["ring"]) == L.RING, len(L.ZUSTAND["ring"])
    L.zuruecksetzen()
    for v in [0.001] * 98 + [0.5, 2.0]:
        L.erfassen(v)
    lg = L.lage()
    assert lg["p50_ms"] == 1.0 and lg["max_ms"] == 2000.0, lg
    assert lg["p99_ms"] >= 500.0, "ein p99, das zwei Ausreisser von 100 wegmittelt: %r" % lg
    assert lg["ueber_budget"] == 2, lg
    # Ohne Takt keine Messung — und das muss dabei stehen, sonst liest sich
    # "alles 0" wie ein gesunder Loop.
    assert lg["aktiv"] is False, lg

    # ── (2) DER SPAEHER NENNT DIE STELLE — die eigene UND die innere.
    L.zuruecksetzen()
    gemeldet = []

    def _absichtlich_blockiert():
        _t.sleep(0.45)

    def _wartet_auf_schlange():
        try:
            _q.Queue().get(timeout=0.45)    # steht in queue.py/threading.py
        except _q.Empty:
            pass

    async def lauf():
        takt = _aio.ensure_future(L.takt(0.02, 0.05))
        await _aio.sleep(0.1)
        L.spaeher_starten(0.1, 0.02, melden=lambda st, d: gemeldet.append((st, d)))
        await _aio.sleep(0.1)
        _absichtlich_blockiert()
        await _aio.sleep(0.2)
        _wartet_auf_schlange()
        await _aio.sleep(0.2)
        lage = L.lage()
        takt.cancel()
        await _aio.sleep(0)
        return lage

    lage = _aio.run(lauf())
    L.ZUSTAND["spaeher"][1].set()
    stellen = [b["stelle"] for b in L.bremser(5)]
    assert any("_absichtlich_blockiert" in st for st in stellen), stellen
    # Zwei eigene Rahmen, nicht einer: haengt der Loop in nc/dbwrap, ist der
    # innerste eigene Rahmen db_conn — und den hat jeder. Die Abhilfe steht
    # beim Aufrufer.
    assert any(st.startswith("test_nc_modules.py:lauf:") and
               " > test_nc_modules.py:_absichtlich_blockiert:" in st for st in stellen), stellen
    innen = [st for st in stellen if "_wartet_auf_schlange" in st]
    assert innen and " <- " in innen[0] and "threading.py" in innen[0], \
        "die innere Haelfte fehlt — woran es haengt, ist die halbe Antwort: %r" % stellen
    # Nur Dateinamen, nie Pfade: /healthz haengt ohne Anmeldung an UptimeRobot.
    assert not any(os.path.dirname(os.path.abspath("bot.py")) in st for st in stellen), stellen
    assert len(gemeldet) == 2 and all(d >= 0.3 for _, d in gemeldet), gemeldet
    assert lage["max_ms"] >= 300 and lage["aktiv"], lage
    assert lage["stockungen"] == 2, lage

    # ── (3) DAS REGISTER HAT EINEN DECKEL — die Stellen sind offenes
    # Vokabular, jede Zeile des Bestands kann eine sein.
    for i in range(L.MAX_STELLEN * 3):
        L._verbuchen("bot.py:f:%d" % i, 0.3, float(i))
    assert len(L.ZUSTAND["stellen"]) == L.MAX_STELLEN
    L.zuruecksetzen()

    ok("W117: Loop-Lag in ms mit p50/p99/max, Ring und Register gedeckelt, "
       "Spaeher nennt eigene und innere Stelle, ohne Pfad")


def _test_v42_w117_log_flut_haelt_den_loop_nicht():
    """Unter einer Log-Flut bleibt der Loop im Budget — gemessen, nicht
    behauptet. Und ein Handler, der nach dem Umhaengen dazukommt, laeuft
    nicht still an der Schleuse vorbei.

    Die Gegenprobe steht im Vertrag selbst: dieselbe Flut OHNE Schleuse
    muss den Loop deutlich ueber das Budget treiben, sonst beweist die
    Messung mit Schleuse nichts.
    """
    import asyncio as _aio
    import logging as _lg
    import threading as _th
    import time as _t
    from nc import logschleuse as S
    from nc import looplag as L

    class Langsam(_lg.StreamHandler):
        """Platte unter Volllast: 20 ms je Zeile, und schreibend (Stream)."""

        def __init__(self):
            super().__init__(io.StringIO())
            self.n = 0

        def emit(self, satz):
            _t.sleep(0.02)
            self.n += 1

    def flut_messen(lg_):
        L.zuruecksetzen()

        async def lauf():
            takt = _aio.ensure_future(L.takt(0.01, 0.05))
            await _aio.sleep(0.05)
            # Gleichzeitig Threads, die auch loggen — so wie die 21 vom 18.09.
            stopp = _th.Event()

            def fremd():
                while not stopp.is_set():
                    lg_.info("thread")
                    _t.sleep(0.005)
            ths = [_th.Thread(target=fremd, daemon=True) for _ in range(3)]
            for th in ths:
                th.start()
            for i in range(10):
                for j in range(10):
                    lg_.info("loop %d/%d", i, j)
                await _aio.sleep(0.01)
            stopp.set()
            for th in ths:
                th.join()
            lage = L.lage()
            takt.cancel()
            await _aio.sleep(0)
            return lage
        return _aio.run(lauf())

    S.zuruecksetzen()
    lg = _lg.getLogger("w117_flut")
    lg.propagate = False
    lg.setLevel(_lg.INFO)
    for h in list(lg.handlers):
        lg.removeHandler(h)
    lg.addHandler(Langsam())
    try:
        ohne = flut_messen(lg)
        assert ohne["max_ms"] > 180, \
            "die Gegenprobe blockiert nicht (%r) — dann beweist die Messung " \
            "mit Schleuse nichts" % ohne
        S.entkoppeln(lg, max_wartend=200)
        mit = flut_messen(lg)
        assert mit["max_ms"] < 100, \
            "unter Log-Flut stand der Loop %.0f ms trotz Schleuse (ohne: %.0f ms)" \
            % (mit["max_ms"], ohne["max_ms"])

        # ── NACHZUEGLER: ein schreibender Handler, der nach dem Umhaengen
        # an den Logger kommt, schriebe wieder synchron.
        spaet = _lg.StreamHandler(io.StringIO())
        lg.addHandler(spaet)
        assert ("w117_flut", "StreamHandler") in S.synchrone_handler()
        assert S.nachziehen(lg) == 1
        assert ("w117_flut", "StreamHandler") not in S.synchrone_handler()
        assert spaet in S._HORCHER[0].handlers, "umgezogen heisst: der Horcher bedient ihn"
        # Ein reiner Speicher-Handler blockiert nicht und zaehlt nicht.
        class Speicher(_lg.Handler):
            def emit(self, satz):
                pass
        lg.addHandler(Speicher())
        assert not [x for x in S.synchrone_handler() if x[0] == "w117_flut"]
        # Ein Unter-Logger wird gemeldet, aber NICHT umgezogen: der Horcher
        # wuerde ihm sonst alle Datensaetze geben, nicht nur seine.
        unter = _lg.getLogger("w117_flut.unter")
        uh = _lg.StreamHandler(io.StringIO())
        unter.addHandler(uh)
        assert ("w117_flut.unter", "StreamHandler") in S.synchrone_handler()
        unter.removeHandler(uh)
    finally:
        S.zuruecksetzen()
        L.zuruecksetzen()
        for h in list(lg.handlers):
            lg.removeHandler(h)

    ok("W117: Log-Flut mit drei loggenden Threads haelt den Loop unter 100 ms "
       "(Gegenprobe ohne Schleuse > 180 ms); Nachzuegler-Handler werden gefunden")


def _test_v42_w117_loop_verdrahtung_und_sperre():
    """Die Messung haengt im Bot, und die heissen Pfade blockieren nicht mehr.

    Gemessen im Syntaxbaum, nicht im rohen Text — ein Vertrag darf seine
    eigene Begruendung nicht als Befund lesen (W102 bis W104).
    """
    import ast as _ast
    sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "tools"))
    import loopblocker as LB

    # ── (1) DIE SPERRE ZAEHLT RICHTIG. Direkt in async: ja. In einer
    # verschachtelten def oder einem Lambda (der Weg in den Thread): nein.
    probe = _ast.parse(
        "async def a():\n"
        "    with db_conn() as c: pass\n"
        "    _time_mod.sleep(1)\n"
        "    def _lauf():\n"
        "        with db_conn() as c: pass\n"
        "    await db_async(lambda c: open('x'))\n"
        "def b():\n"
        "    with db_conn() as c: pass\n")
    treffer = LB.sammle("probe.py", probe)
    assert [(t[1], t[3]) for t in treffer] == [(2, "db_conn"), (3, "_time_mod.sleep")], treffer

    # ── (2) DIE HEISSEN PFADE SIND FREI. Restream-Steuerung, Intel-Index
    # (Einbettungen einer ganzen Aufnahme!), Director, Liveboard.
    befunde = []
    for datei in ("bot.py", "discordbot.py"):
        baum = _ast.parse(io.open(datei, encoding="utf-8").read())
        befunde += LB.sammle(datei, baum)
    frei = {"_intel_index_one", "auto_start_due", "_monitor", "_switch_to_next_live",
            "_director_finalize", "_clip_to_discord", "oracle_handle",
            "_update_liveboard", "start"}
    rest = [b for b in befunde if b[2] in frei and b[3] == "db_conn"]
    assert not rest, "blockierender Datenbankzugriff wieder direkt im Loop: %r" % rest

    # ── (3) DIE VERDRAHTUNG.
    src = io.open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(src)
    fn = {n.name: n for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    def ruft(f, name):
        return any(isinstance(c, _ast.Call) and getattr(c.func, "id", None) == name
                   for c in _ast.walk(fn[f]))
    assert ruft("run_bot", "_loop_takt_starten"), "der Takt startet nicht"
    assert ruft("_loop_lag_monitor", "_log_schleuse_pruefen"), \
        "niemand sieht nach, ob die Log-Schleuse umgangen wird"
    hz = _ast.unparse(fn["healthz"])
    for k in ("loop_lag=_nc_looplag.lage()", "log_synchron="):
        assert k in hz, "/healthz traegt %s nicht" % k
    # Funktionsnamen und Zeilen gehoeren hinter die Anmeldung, nicht in /healthz.
    assert "bremser" not in hz
    assert "bremser(" in _ast.unparse(fn["api_debug_threads"])
    # Die Stockungsmeldung geht durch die Drossel — der Spaeher kann sonst
    # bei einer Stelle, die jede Minute stockt, das Log fluten.
    sm = _ast.unparse(fn["_loop_stockung_melden"])
    assert "_nc_meldetakt.melden(" in sm and "_nc_meldetakt.zusatz(" in sm, sm

    ok("W117: Sperre zaehlt nur direkte Aufrufe, heisse Pfade frei, Takt und "
       "Schleusen-Pruefung verdrahtet, Bremser nur hinter der Anmeldung")


def _test_v42_w118_gegendruck_entscheidet():
    """Abregeln mit Ansage statt still ueberlaufen.

    Aufnahmen hatten keinen Deckel, der Dienst lief mit 1024 fds (keine
    LimitNOFILE-Zeile in der Unit, nichts im Bot), und eine volle
    Pruef-Schlange verwarf ohne Zeile.
    """
    import subprocess as _sp
    from nc import gegendruck as G

    G.zuruecksetzen()
    voll = {"offen": 900, "grenze": 1024}
    frei = {"offen": 100, "grenze": 1024}
    # ── (1) DIE RANGFOLGE: ein voller fd-Tisch ist die eigentliche
    # Nachricht — er kostet gleich auch Datenbank und Netz.
    ok_, grund, text = G.start_entscheiden(50, 32, voll)
    assert (ok_, grund) == (False, "fd"), (ok_, grund)
    assert "LimitNOFILE" in text, "eine Abweisung ohne Abhilfe: %s" % text
    ok_, grund, text = G.start_entscheiden(32, 32, frei)
    assert (ok_, grund) == (False, "deckel") and "MAX_PARALLEL_AUFNAHMEN" in text, text
    assert G.start_entscheiden(31, 32, frei)[0], "unter dem Deckel muss es starten"
    assert G.start_entscheiden(500, 0, frei)[0], "Deckel 0 heisst: kein Deckel"
    # Eine unbekannte Lage (kein /proc, Windows) darf keine Aufnahme kosten.
    assert G.start_entscheiden(0, 0, {"offen": -1, "grenze": -1})[0]
    assert G.start_entscheiden(0, 0, {"offen": 5000, "grenze": -1})[0]
    # Die Schwelle selbst: knapp darunter frei, auf ihr gesperrt.
    grenze = 1000
    schwelle = int(G.FD_SPERRE_ANTEIL * grenze)
    assert G.start_entscheiden(0, 0, {"offen": schwelle - 1, "grenze": grenze})[0]
    assert not G.start_entscheiden(0, 0, {"offen": schwelle, "grenze": grenze})[0]

    # ── (2) DER AUTOMATISCHE DECKEL ist ein Riegel, keine Drossel.
    assert G.deckel_auto(8) == 32 and G.deckel_auto(1) == 8, (G.deckel_auto(8), G.deckel_auto(1))

    # ── (3) DIE ECHTE LAGE und das ANHEBEN — im eigenen Prozess, damit das
    # Limit dieser Suite unberuehrt bleibt. Erst auf 256 druecken, dann
    # muss die Anhebung greifen, aber nie ueber das Hard-Limit hinaus.
    if os.path.isdir("/proc/self/fd"):
        lg = G.fd_lage()
        assert lg["offen"] > 0 and lg["grenze"] > 0, lg
        code = ("import resource as r, sys; sys.path.insert(0, '.');"
                "w, h = r.getrlimit(r.RLIMIT_NOFILE);"
                "r.setrlimit(r.RLIMIT_NOFILE, (256, h));"
                "from nc import gegendruck as G;"
                "v, n = G.fd_grenze_anheben();"
                "w2, h2 = r.getrlimit(r.RLIMIT_NOFILE);"
                "print(v, n, w2, h2)")
        aus = _sp.run([sys.executable, "-c", code], capture_output=True, text=True,
                      cwd=os.path.dirname(os.path.abspath(__file__)), timeout=60)
        v, n, w2, h2 = (int(x) for x in aus.stdout.split())
        assert v == 256, aus.stdout
        assert n == w2 and n > 256, "die Anhebung hat nicht gegriffen: %s" % aus.stdout
        assert n <= G.FD_ZIEL and (h2 < 0 or n <= h2), aus.stdout

    # ── (4) DIE ZAEHLER fuer /healthz — und keine Namen darin.
    G.abgewiesen("aufnahme", "deckel")
    G.abgewiesen("aufnahme", "deckel")
    G.verworfen()
    lage = G.lage(3, 32, 7, 200)
    assert lage["abgewiesen"] == {"aufnahme:deckel": 2}, lage
    assert lage["pruef_verworfen"] == 1 and lage["aufnahmen"] == 3, lage
    assert lage["pruef_schlange"] == 7 and lage["pruef_schlange_max"] == 200
    G.zuruecksetzen()

    ok("W118: fd-Sperre vor Deckel, Deckel 0 = keiner, unbekannte Lage sperrt nie, "
       "Soft-Limit wird bis zum Hard-Limit angehoben")


def _test_v42_w118_gegendruck_verdrahtet():
    """Gefragt wird VOR dem Lock, die Schlange meldet, der Abruf laeuft
    neben dem Loop, und die Unit bringt LimitNOFILE mit."""
    import ast as _ast
    src = io.open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(src)
    fn = {}
    for n in _ast.walk(baum):
        if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef)):
            fn.setdefault(n.name, n)

    def rufe(f, name):
        return [c for c in _ast.walk(fn[f]) if isinstance(c, _ast.Call)
                and (getattr(c.func, "id", None) == name
                     or getattr(c.func, "attr", None) == name)]

    # ── (1) AUFNAHME: erst fragen, dann den Lock nehmen. Andersherum hielte
    # eine abgewiesene Aufnahme ihren Lock, und der Nutzer waere gesperrt.
    gs = rufe("_handle_single_tracking", "_start_gesperrt")
    lock = [c for c in _ast.walk(fn["_handle_single_tracking"])
            if isinstance(c, _ast.Name) and c.id == "try_acquire_recording_lock"]
    assert gs and lock and gs[0].lineno < min(n.lineno for n in lock), \
        "die Aufnahme fragt nicht VOR dem Lock"
    assert "_aufnahme_deckel" in _ast.unparse(gs[0]), _ast.unparse(gs[0])
    # ── (2) RESTREAM: die fd-Sperre gilt auch dort.
    rm = next(n for n in baum.body if isinstance(n, _ast.ClassDef) and n.name == "RestreamManager")
    fn["start"] = next(n for n in rm.body if isinstance(n, _ast.AsyncFunctionDef) and n.name == "start")
    assert rufe("start", "_start_gesperrt"), "RestreamManager.start fragt nicht"
    # ── (3) DIE SCHLANGE: verworfen wird gezaehlt und gemeldet, und der
    # Tracking-Abruf alle 5 s laeuft im Thread.
    # ANKER GEWANDERT (v4.2-W176): die Runde ohne await steht jetzt in
    # _pruef_runde, damit check_all_trackings sie als Ganzes absichert.
    assert rufe("check_all_trackings", "_pruef_runde")
    assert rufe("_pruef_runde", "_pruefung_verworfen")
    direkt = [c for c in rufe("check_all_trackings", "get_all_active_trackings")]
    assert not direkt, "get_all_active_trackings wieder direkt auf dem Loop"
    assert any("to_thread(get_all_active_trackings)" in _ast.unparse(c)
               for c in rufe("check_all_trackings", "to_thread"))
    assert "_nc_meldetakt.melden(" in _ast.unparse(fn["_pruefung_verworfen"])
    assert "_nc_meldetakt.melden(" in _ast.unparse(fn["_start_gesperrt"])
    # ── (4) START und /healthz.
    assert rufe("run_bot", "_fd_grenze_anheben")
    assert "gegendruck=_nc_gegendruck.lage(" in _ast.unparse(fn["healthz"])
    # ── (5) DIE UNIT: ohne die Zeile ist das Hard-Limit, bis zu dem der Bot
    # anheben darf, auf manchen Systemen selbst nur 4096.
    inst = io.open("tools/installer.sh", encoding="utf-8").read()
    unit = inst[inst.index("ExecStart=${VENV}/bin/python ${ZIEL}/bot.py"):]
    unit = unit[:unit.index("[Install]")]
    assert any(z.strip() == "LimitNOFILE=65536" for z in unit.splitlines()), unit

    ok("W118: Aufnahme fragt vor dem Lock, Restream fragt, Schlange meldet, "
       "Abruf im Thread, Unit mit LimitNOFILE")


def _test_v42_w119_ein_lauf_je_nutzer():
    """Gleichzeitige Aufrufer teilen sich EINE Aufloesung.

    Die zweite Cache-Pruefung aus W103 faengt den, der nach dem Schreiben
    kommt — nicht den, der WAEHREND einer 20-s-Aufloesung ankommt. Die
    Semaphore ist 2 gross, beide stehen gleichzeitig darin.
    """
    import asyncio as _aio
    from nc import livecache as C

    C.zaehler_zuruecksetzen()
    laeufe = []

    def bauer(name, wirft=None, dauer=0.05):
        async def _lauf():
            laeufe.append(name)
            await _aio.sleep(dauer)
            if wirft:
                raise wirft
            return ("live", {"wer": name})
        return _lauf

    async def szenario():
        reg = {}
        # ── (1) FUENF GLEICHZEITIG, EIN SCHLUESSEL -> EIN LAUF.
        erg = await _aio.gather(*[C.einflug(reg, "anna", bauer("anna"), ("unknown", None))
                                  for _ in range(5)])
        assert laeufe == ["anna"], laeufe
        assert all(e == ("live", {"wer": "anna"}) for e in erg), erg
        assert C.ZAEHLER["geteilt"] == 4 and reg == {}, (C.ZAEHLER, reg)
        # ── (2) VERSCHIEDENE SCHLUESSEL laufen getrennt.
        laeufe.clear()
        await _aio.gather(C.einflug(reg, "a", bauer("a"), None),
                          C.einflug(reg, "b", bauer("b"), None))
        assert sorted(laeufe) == ["a", "b"], laeufe
        # ── (3) DER FUEHRENDE SCHEITERT: er bekommt seine Ausnahme, die
        # Mitlaeufer den Ersatz — nie die fremde Ausnahme.
        fuehrer = _aio.ensure_future(C.einflug(reg, "x", bauer("x", RuntimeError("tiktok")), "ERSATZ"))
        await _aio.sleep(0.01)
        mit = await C.einflug(reg, "x", bauer("x2"), "ERSATZ")
        assert mit == "ERSATZ", mit
        try:
            await fuehrer
        except RuntimeError:
            pass
        else:
            raise AssertionError("der fuehrende Lauf muss seine Ausnahme sehen")
        # ── (4) DER FUEHRENDE WIRD ABGEBROCHEN: kein fremder CancelledError
        # in den Mitlaeufer — ein Worker, dem das passiert, endet still.
        fuehrer = _aio.ensure_future(C.einflug(reg, "y", bauer("y", dauer=1.0), "ERSATZ"))
        await _aio.sleep(0.01)
        mit = _aio.ensure_future(C.einflug(reg, "y", bauer("y2"), "ERSATZ"))
        await _aio.sleep(0.01)
        fuehrer.cancel()
        assert await mit == "ERSATZ"
        assert fuehrer.cancelled()
        # ── (5) EIN MITLAEUFER WIRD ABGEBROCHEN: der Lauf der anderen lebt.
        fuehrer = _aio.ensure_future(C.einflug(reg, "z", bauer("z", dauer=0.1), None))
        await _aio.sleep(0.01)
        mit = _aio.ensure_future(C.einflug(reg, "z", bauer("z2"), None))
        await _aio.sleep(0.01)
        mit.cancel()
        assert await fuehrer == ("live", {"wer": "z"})
        assert reg == {}, reg
        # ── (5b) SCHEITERT ER OHNE MITLAEUFER, liest niemand die Ausnahme
        # vom Future — sie darf trotzdem nicht als "Future exception was
        # never retrieved" ins Log fallen (der Aufrufer hat sie ja bekommen).
        try:
            await C.einflug(reg, "allein", bauer("allein", RuntimeError("allein")), None)
        except RuntimeError:
            pass
        import gc as _gc
        _gc.collect()
        await _aio.sleep(0)

    fehler = []
    loop = _aio.new_event_loop()
    loop.set_exception_handler(lambda l, ctx: fehler.append(ctx.get("message")))
    try:
        loop.run_until_complete(szenario())
    finally:
        loop.close()
    import gc as _gc
    _gc.collect()
    assert not fehler, "unabgeholte Ausnahmen im Log: %r" % fehler

    # ── (6) AUFRAEUMEN JE SCHREIBVORGANG, NICHT JE NUTZER. Bis W119 hing es
    # an hash(username) & 63 — je Nutzer fest, oft fuer keinen wahr.
    C.zaehler_zuruecksetzen()
    assert sum(C.aufraeumen_faellig() for _ in range(C.AUFRAEUM_TAKT * 3)) == 3
    # ── (7) DIE ZAHLEN fuer /healthz.
    C.zaehler_zuruecksetzen()
    C.zaehle("treffer", 3)
    C.zaehle("fehlschlag")
    C.dauer(0.2)
    C.dauer(0.4)
    st = C.statistik(7, 1)
    assert st["trefferquote"] == 0.75 and st["dauer_mittel_ms"] == 300 and st["dauer_max_ms"] == 400, st
    assert st["eintraege"] == 7 and st["laufend"] == 1
    C.zaehler_zuruecksetzen()
    assert C.statistik()["trefferquote"] is None, "ohne Abfragen keine erfundene Quote"

    ok("W119: ein Lauf je Nutzer, Mitlaeufer bekommen Ergebnis oder Ersatz, nie "
       "fremde Ausnahmen; Aufraeumen je Schreibvorgang; Trefferquote/Dauer")


def _test_v42_w119_polling_dehnt_nur_was_nichts_kostet():
    """Unter Last offline/unknown dehnen, live und just-offline nie."""
    from nc import livefolge as F
    d = F.last_dehnung
    for st, war in (("live", False), ("live", True), ("offline", True)):
        assert d(st, war, 200, 200) == 1.0, (st, war)
    assert d("offline", False, 0, 200) == 1.0
    assert d("offline", False, 100, 200) == 1.0, "bis zur halben Schlange keine Dehnung"
    assert d("offline", False, 150, 200) == 1.5
    assert d("offline", False, 200, 200) == 2.0 and d("unknown", False, 999, 200) == 2.0
    assert d("offline", False, 200, 0) == 1.0, "unbekannte Groesse dehnt nie"
    # Stetig — ein Sprung waere selbst eine Schwingungsquelle.
    werte = [d("offline", False, n, 200) for n in range(0, 201)]
    assert all(b >= a for a, b in zip(werte, werte[1:]))
    assert max(b - a for a, b in zip(werte, werte[1:])) < 0.02

    import ast as _ast
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    fn = {n.name: n for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    sn = fn["_schedule_next_check"]
    dehn = [c for c in _ast.walk(sn) if isinstance(c, _ast.Attribute) and c.attr == "last_dehnung"]
    prio = [c for c in _ast.walk(sn) if isinstance(c, _ast.Name) and c.id == "get_priority_poll_interval"]
    assert dehn and prio and dehn[0].lineno < prio[0].lineno, \
        "die Dehnung muss VOR der VIP-Verkuerzung stehen, sonst hebt sie sie auf"

    ok("W119: Lastdehnung nur fuer offline/unknown, stetig 1,0..2,0, vor der VIP-Verkuerzung")


def _test_v42_w119_puls_ist_ein_schnappschuss():
    """/api/pulse baut fuer alle Tabs EINEN Wert je 2 s — und haengt nicht mit,
    wenn das Bauen haengt."""
    import threading as _th
    import time as _t
    from nc.schnappschuss import Schnappschuss

    jetzt = [100.0]
    ss = Schnappschuss(gueltig_s=2.0, warte_s=0.2, uhr=lambda: jetzt[0])
    gebaut = []

    def bauen():
        gebaut.append(1)
        return {"n": len(gebaut)}
    for _ in range(5):
        assert ss.holen(bauen) == ({"n": 1}, False)
    jetzt[0] += 1.9
    assert ss.holen(bauen)[0] == {"n": 1}
    jetzt[0] += 0.2
    assert ss.holen(bauen)[0] == {"n": 2}, "nach der Gueltigkeit muss neu gebaut werden"

    # ── GLEICHZEITIG: acht Threads, ein langsamer Bau -> ein Bau.
    ss2 = Schnappschuss(gueltig_s=2.0, warte_s=5.0)
    zahl = [0]

    def langsam():
        zahl[0] += 1
        _t.sleep(0.1)
        return zahl[0]
    erg = []
    ths = [_th.Thread(target=lambda: erg.append(ss2.holen(langsam))) for _ in range(8)]
    for th in ths:
        th.start()
    for th in ths:
        th.join()
    assert zahl[0] == 1 and all(e == (1, False) for e in erg), (zahl, erg)

    # ── HAENGT DER BAU, antwortet der Puls trotzdem: mit dem letzten Wert und
    # `veraltet`. Sonst stehen alle waitress-Threads in der Schlange.
    ss3 = Schnappschuss(gueltig_s=0.0, warte_s=0.1)
    ss3.holen(lambda: "alt")
    tor = _th.Event()
    t = _th.Thread(target=lambda: ss3.holen(lambda: tor.wait(2) and "neu"))
    t.start()
    _t.sleep(0.05)
    t0 = _t.monotonic()
    assert ss3.holen(lambda: "nie") == ("alt", True)
    assert _t.monotonic() - t0 < 1.0
    tor.set()
    t.join()

    import ast as _ast
    src = io.open("nc/routes/auskunft.py", encoding="utf-8").read()
    fn = next(n for n in _ast.walk(_ast.parse(src))
              if isinstance(n, _ast.FunctionDef) and n.name == "api_pulse")
    assert "_PULS.holen(" in _ast.unparse(fn), "api_pulse baut wieder je Anfrage"

    hz = io.open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(hz)
    f = {n.name: n for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    assert "livecache=_nc_livecache.statistik(" in _ast.unparse(f["healthz"])
    g = _ast.unparse(f["get_live_status"])
    assert "_nc_livecache.einflug(_LIVE_EINFLUG" in g and "if force_fresh:" in g, g
    assert "hash(username)" not in _ast.unparse(f["_live_status_aufloesen"])
    assert "_nc_livecache.aufraeumen_faellig()" in _ast.unparse(f["_live_status_aufloesen"])

    ok("W119: /api/pulse als geteilter 2-s-Schnappschuss, ein Bau fuer acht "
       "gleichzeitige Anfragen, haengender Bau liefert den letzten Wert")


def _test_v42_w120_kindprozess_endet_auf_jedem_weg():
    """Ein Kindprozess endet bei Erfolg, Zeitablauf, Ausnahme UND Abbruch.

    Drei Stellen warteten mit nacktem communicate() (kein Zeitlimit), und
    keine einzige raeumte ab, wenn der aufrufende Task abgebrochen wurde: ein
    CancelledError ist kein Exception und rauscht an `except Exception`
    vorbei — der Prozess lief ungesehen weiter.
    """
    import asyncio as _aio
    import signal as _sig
    from nc import kindprozess as K

    def lebt(pid):
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            return False
        # Zombie zaehlt als tot-und-abgeholt NICHT: nachsehen.
        try:
            with io.open("/proc/%d/stat" % pid) as f:
                return f.read().split(")")[-1].split()[0] != "Z"
        except OSError:
            return False

    schlafen = [sys.executable, "-c", "import time; time.sleep(30)"]

    async def szenario():
        K.zuruecksetzen()
        # ── (1) ERFOLG
        rc, out, _ = await K.ausfuehren([sys.executable, "-c", "print('hallo')"], 10, art="probe")
        assert rc == 0 and out.strip() == b"hallo", (rc, out)
        # ── (2) ZEITLIMIT: der Prozess ist weg, BEVOR die Ausnahme fliegt.
        t0 = _aio.get_running_loop().time()
        try:
            await K.ausfuehren(schlafen, 0.3, art="probe")
        except _aio.TimeoutError:
            pass
        else:
            raise AssertionError("Zeitlimit ohne TimeoutError")
        assert _aio.get_running_loop().time() - t0 < 6
        assert K.LAUFEND == {} and K.ZAEHLER["zeitlimit"] == 1, (K.LAUFEND, K.ZAEHLER)
        # ── (3) ABBRUCH DES AUFRUFERS: der Fall, den kein Bestandscode abdeckte.
        task = _aio.ensure_future(K.ausfuehren(schlafen, 60, art="probe"))
        await _aio.sleep(0.3)
        pids = list(K.LAUFEND)
        assert len(pids) == 1 and K.lage()["je_art"] == {"probe": 1}, K.lage()
        task.cancel()
        try:
            await task
        except _aio.CancelledError:
            pass
        else:
            raise AssertionError("der Abbruch wurde verschluckt")
        assert not lebt(pids[0]), "nach dem Abbruch laeuft der Prozess weiter"
        assert K.LAUFEND == {} and K.ZAEHLER["abgebrochen"] == 1
        # ── (4) SIGTERM IGNORIERT -> SIGKILL, mit wait().
        trotz = await _aio.create_subprocess_exec(
            sys.executable, "-c",
            "import signal, time; signal.signal(signal.SIGTERM, signal.SIG_IGN); "
            "print('bereit', flush=True); time.sleep(30)",
            stdout=K.PIPE)
        await trotz.stdout.readline()
        assert await K.beenden(trotz, term_s=0.3, kill_s=3) == "kill"
        assert trotz.returncode == -_sig.SIGKILL and not lebt(trotz.pid)
        assert await K.beenden(trotz) == "lief_nicht"
        # ── (5) ALLE BEENDEN (fuers Herunterfahren, Paket E).
        t1 = _aio.ensure_future(K.ausfuehren(schlafen, 60, art="a"))
        t2 = _aio.ensure_future(K.ausfuehren(schlafen, 60, art="b"))
        await _aio.sleep(0.3)
        assert K.lage()["laufend"] == 2
        assert await K.alle_beenden(term_s=2) == 2
        for t in (t1, t2):
            rc, _, _ = await t
            assert rc == -_sig.SIGTERM, rc
        assert K.LAUFEND == {}
        # ── (6) OHNE ZEITLIMIT GEHT ES NICHT.
        for z in (0, None, -1):
            try:
                await K.ausfuehren(schlafen, z)
            except ValueError:
                pass
            else:
                raise AssertionError("Zeitlimit %r wurde angenommen" % (z,))

    if os.name == "posix":
        _aio.run(szenario())
    K.zuruecksetzen()
    ok("W120: Kindprozess endet bei Erfolg, Zeitlimit, Abbruch des Aufrufers; "
       "SIGTERM-Verweigerer bekommt SIGKILL mit wait; alle_beenden; Zeitlimit Pflicht")


def _test_v42_w120_kein_warten_ohne_ende():
    """Im Produktionscode wartet kein communicate() ohne Zeitlimit — ausser
    unmittelbar nach einem kill(), dort endet der Prozess sofort. Und die
    umgestellten Stellen starten nicht mehr selbst."""
    import ast as _ast
    import glob as _glob
    dateien = (["bot.py", "discordbot.py", "telegramversand.py", "brain_bridge.py"]
               + sorted(_glob.glob("nc/**/*.py", recursive=True)) + sorted(_glob.glob("brain/*.py")))
    nackt = []
    for d in dateien:
        baum = _ast.parse(io.open(d, encoding="utf-8").read())
        nach_kill = set()
        for h in _ast.walk(baum):
            if isinstance(h, _ast.ExceptHandler):
                kill_zeilen = [c.lineno for c in _ast.walk(h) if isinstance(c, _ast.Call)
                               and getattr(c.func, "attr", None) == "kill"]
                for c in _ast.walk(h):
                    if isinstance(c, _ast.Await) and kill_zeilen and c.lineno > min(kill_zeilen):
                        nach_kill.add(id(c))
        for n in _ast.walk(baum):
            if isinstance(n, _ast.Await) and isinstance(n.value, _ast.Call) \
                    and getattr(n.value.func, "attr", None) == "communicate" \
                    and id(n) not in nach_kill:
                nackt.append("%s:%d" % (d, n.lineno))
    assert not nackt, "communicate() ohne Zeitlimit: %s — nc.kindprozess.ausfuehren benutzen" % nackt

    for d in ("nc/videoteil.py", "nc/tonspur.py"):
        src = io.open(d, encoding="utf-8").read()
        assert "create_subprocess_exec" not in src and "_kind.ausfuehren(" in src, d
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    fn = {n.name: n for n in _ast.walk(baum) if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    # ANKER GEWANDERT (v4.2-W159): der Schnitt steht in _clip_schneiden,
    # clip_moment zaehlt nur noch den offenen Clip (Review #204).
    # ANKER GEWANDERT (v5.3-W193, nicht der Vertrag): _resolve_via_ytdlp geht
    # ueber den yt-dlp-Arbeiter, dessen Einzelweg _ytdlp_einzeln ist — beide
    # mit Zeitlimit (nc/ytdlpdienst.py beendet den Arbeiter bei Ablauf).
    for f in ("_ytdlp_einzeln", "_shrink_for_discord", "_clip_schneiden", "_restream_tts_enqueue_wav"):
        u = _ast.unparse(fn[f])
        assert "create_subprocess_exec" not in u and "_nc_kind.ausfuehren(" in u, f
    u = _ast.unparse(fn["_resolve_via_ytdlp"])
    assert "create_subprocess_exec" not in u and "_nc_ytdlpdienst.ausfuehren(cmd, 20," in u
    ok("W120: kein communicate() ohne Zeitlimit; videoteil, tonspur, yt-dlp, Clip, "
       "Discord-Verkleinern und TTS starten ueber nc.kindprozess")


def _test_v42_w120_speicher_waechst_nicht():
    """Maps mit Namen, die nicht getrackt sind (/check, Restream-Quelle, Clip),
    wurden nie geleert. Beschnitten wird nach ihrer eigenen Bedeutung."""
    import ast as _ast
    from nc import speicherpflege as P

    stempel = {"alt": 100.0, "frisch": 5000.0, "fremd": "kein Zeitstempel"}
    assert P.alte_stempel_weg(stempel, 5100.0, 3600) == 1
    assert set(stempel) == {"frisch", "fremd"}, stempel
    bis = {"vorbei": 1000.0, "kuerzlich": 4800.0, "laeuft": 9000.0}
    weg = P.abgelaufene_weg(bis, 5000.0, nachlauf=600)
    assert weg == ["vorbei"] and set(bis) == {"kuerzlich", "laeuft"}, (weg, bis)
    assert P.groessen({"a": {1: 1}, "b": []}) == {"a": 1, "b": 0}

    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    fn = {n.name: n for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    # ANKER GEWANDERT (v4.2-W176): die Runde steht in _pruef_runde.
    assert any(isinstance(c, _ast.Call) and getattr(c.func, "id", None) == "_speicher_pflegen"
               for c in _ast.walk(fn["_pruef_runde"])), "niemand pflegt"
    # Namen im Syntaxbaum, nicht im Text: "_CLIP_LAST" steckt auch in
    # "_HYPE_CLIP_LAST" — die Mutationsprobe ist genau daran entwischt.
    namen = {c.id for c in _ast.walk(fn["_speicher_pflegen"]) if isinstance(c, _ast.Name)}
    for m in ("_YTDLP_NACHSCHLAG_ZULETZT", "_CLIP_LAST", "_HYPE_CLIP_LAST", "_ABO_PROBE_DONE",
              "_RATE_LIMIT_BACKOFF", "_RATE_LIMIT_PENALTY"):
        assert m in namen, "%s wird nicht gepflegt" % m
    hz = _ast.unparse(fn["healthz"])
    assert "kinder=_nc_kind.lage()" in hz and "speicher=_nc_pflege.groessen(" in hz
    ok("W120: Zeitstempel- und Ablauf-Maps werden nach Bedeutung beschnitten, "
       "alle 10 min aus der Hauptschleife; Groessen und Kinder in /healthz")


def _test_v42_w121_stopp_sichert_aufnahmen():
    """Eine beim Stopp laufende Aufnahme wurde per SIGKILL beendet und NICHT
    eingetragen — eine Waise, die /api/rec/orphans/clean zum Loeschen anbietet.
    Jeder Neustart (also jedes Update) machte so aus jeder laufenden Aufnahme
    einen Loeschkandidaten."""
    import ast as _ast
    from nc import betriebslage as L

    # ── (1) WAS EINGETRAGEN WIRD: alles mit mehr als einem Kopf.
    tmp = _ph.verzeichnis()
    gross = _ph.attrappe(os.path.join(tmp, "a.mp4"), 5 * 1024 * 1024)
    kopf = _ph.attrappe(os.path.join(tmp, "b.mp4"), 512)
    assert L.sichern_beim_stopp(gross)
    assert not L.sichern_beim_stopp(kopf), "ein Kopf ohne Inhalt ist keine Aufnahme"
    assert not L.sichern_beim_stopp(os.path.join(tmp, "fehlt.mp4"))
    assert not L.sichern_beim_stopp("") and not L.sichern_beim_stopp(tmp)

    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    fn = {n.name: n for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    # ── (2) DER ABBRUCHZWEIG sichert, statt zu toeten.
    hrf = fn["handle_recording_finished"]
    zweig = next(h for h in _ast.walk(hrf) if isinstance(h, _ast.ExceptHandler)
                 and _ast.unparse(h.type or _ast.Name("x")) == "asyncio.CancelledError")
    zt = _ast.unparse(zweig)
    assert "_aufnahme_beim_stopp_sichern(" in zt, zt
    assert "proc.kill()" not in zt, "der Abbruchzweig schickt wieder SIGKILL"
    assert any(isinstance(n, _ast.Raise) for n in _ast.walk(zweig)), \
        "der Abbruch wird verschluckt — dann endet der Task nie"
    hs = _ast.unparse(fn["_aufnahme_beim_stopp_sichern"])
    for k in ("_nc_kind.beenden(proc", "_nc_lage.sichern_beim_stopp(output_file)",
              "asyncio.to_thread(add_recording", "outcome='cancelled'"):
        assert k in hs, "_aufnahme_beim_stopp_sichern: %s fehlt" % k
    # Erst beenden, dann eintragen — sonst steht die Groesse von VOR dem
    # letzten Fragment in der Datenbank.
    assert hs.index("_nc_kind.beenden(") < hs.index("add_recording")

    # ── (3) DIE REIHENFOLGE BEIM STOPP: Aufnahmen zuerst, Hilfsprozesse am Ende.
    auf = fn["_aufraeumen"]
    aufrufe = [(c.lineno, _ast.unparse(c.func)) for c in _ast.walk(auf) if isinstance(c, _ast.Call)]
    zuerst = min(aufrufe)[1]
    assert zuerst in ("_time_mod.monotonic", "_aufnahmen_abschliessen"), aufrufe[:3]
    namen = [n for _, n in sorted(aufrufe)]
    assert namen.index("_aufnahmen_abschliessen") < namen.index("_close_ai_session")
    assert "_nc_kind.alle_beenden" in namen
    ab = _ast.unparse(fn["_aufnahmen_abschliessen"])
    assert "startswith('finish-')" in ab and "asyncio.wait(" in ab and "timeout=" in ab
    ok("W121: Stopp traegt laufende Aufnahmen ein (SIGTERM, dann Eintrag), Aufnahmen "
       "zuerst, Hilfsprozesse zuletzt")


def _test_v42_w121_degradiert_ist_nicht_tot():
    """/healthz unterscheidet "degradiert, aber lebendig" von "gestoert" —
    ohne den HTTP-Code zu aendern, an dem UptimeRobot haengt."""
    import ast as _ast
    from nc import betriebslage as L

    gesund = {"ok": True, "loop_lag": {"aktiv": True, "p99_ms": 12},
              "gegendruck": {"fd": {"offen": 100, "grenze": 65536}},
              "log_synchron": 0, "log_wartend": 0, "laufstand": "aktuell",
              "tunnel": "ok", "kinder": {"aeltester_s": 3}}
    assert L.bewerten(gesund) == ("ok", [])
    for feld, wert, wort in (("loop_lag", {"aktiv": True, "p99_ms": 900}, "Event-Loop"),
                             ("gegendruck", {"fd": {"offen": 800, "grenze": 1024}}, "Dateideskriptoren"),
                             ("log_synchron", 1, "Log-Handler"),
                             ("log_wartend", -1, "Log-Schleuse"),
                             ("laufstand", "veraltet", "neu gestartet"),
                             ("tunnel", "fehler", "Tunnel"),
                             ("kinder", {"aeltester_s": 4000}, "Hilfsprozess")):
        d = dict(gesund)
        d[feld] = wert
        lage, gruende = L.bewerten(d)
        assert lage == "degradiert" and len(gruende) == 1 and wort in gruende[0], (feld, lage, gruende)
    # Ein nicht laufender Takt ist "keine Messung", kein Lag-Befund.
    d = dict(gesund, loop_lag={"aktiv": False, "p99_ms": 9999})
    assert L.bewerten(d)[0] == "ok"
    d = dict(gesund, ok=False, laufstand="veraltet")
    assert L.bewerten(d) == ("gestoert", ["Update eingespielt, aber nicht neu gestartet"])

    # ── bereit() nur einmal.
    alt = L.ZUSTAND["bereit_s"]
    L.ZUSTAND["bereit_s"] = None
    try:
        assert L.bereit(L._START + 12.34) == 12.3
        assert L.bereit(L._START + 99) is None and L.ZUSTAND["bereit_s"] == 12.3
    finally:
        L.ZUSTAND["bereit_s"] = alt

    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    fn = {n.name: n for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    hz = fn["healthz"]
    rueck = [r for r in _ast.walk(hz) if isinstance(r, _ast.Return)]
    assert len(rueck) == 1 and _ast.unparse(rueck[0].value) == "(jsonify(daten), 200 if ok else 503)", \
        "der HTTP-Code haengt nicht mehr allein an ok: %s" % [_ast.unparse(r) for r in rueck]
    assert "daten['lage'], daten['gruende'] = _nc_lage.bewerten(daten)" in _ast.unparse(hz)
    assert "_nc_lage.bereit()" in _ast.unparse(fn["_pruef_runde"])   # ANKER GEWANDERT (v4.2-W176)

    inst = io.open("tools/installer.sh", encoding="utf-8").read()
    unit = inst[inst.index("ExecStart=${VENV}/bin/python ${ZIEL}/bot.py"):]
    unit = [z.strip() for z in unit[:unit.index("[Install]")].splitlines()]
    assert "KillMode=mixed" in unit and "TimeoutStopSec=60" in unit, unit
    ok("W121: /healthz trennt ok/degradiert/gestoert mit Klartext-Gruenden, HTTP-Code "
       "nur an ok; Startdauer einmal gemessen; Unit KillMode=mixed")


def _test_v42_w121b_deckel_haelt_unter_gleichzeitigkeit():
    """Review #160 (Codex): der Deckel las nur len(active_processes). Zwischen
    Pruefung und Eintrag liegen Lock, Aufloesung und Prozessstart — bei einem
    freien Platz kamen bis zu WORKER_COUNT Worker gleichzeitig durch."""
    import ast as _ast
    import asyncio as _aio
    from nc import gegendruck as G

    G.zuruecksetzen()
    frei = {"offen": 10, "grenze": 1024}
    # ── (1) VIER WORKER, EIN FREIER PLATZ — so, wie der Bot es tut: pruefen
    # und reservieren ohne await dazwischen, dann lange "aufloesen".
    aktiv, deckel, gestartet = [1], 2, []

    async def worker(n):
        jetzt = 100.0
        if not G.start_entscheiden(aktiv[0] + G.reserviert(jetzt), deckel, frei)[0]:
            return
        G.reservieren(jetzt)
        await _aio.sleep(0.05)              # Lock, Aufloesung, Prozessstart
        aktiv[0] += 1
        G.freigeben()
        gestartet.append(n)

    async def alle():
        await _aio.gather(*[worker(i) for i in range(4)])
    _aio.run(alle())
    assert len(gestartet) == 1 and aktiv[0] == deckel, \
        "Deckel %d ueberschritten: %d gestartet, %d aktiv" % (deckel, len(gestartet), aktiv[0])
    assert G.reserviert(100.0) == 0, "eine Reservierung blieb haengen"
    # ── (2) VERFALL: eine nie freigegebene Reservierung belegt nicht ewig.
    G.reservieren(0.0)
    assert G.reserviert(1.0) == 1
    assert G.reserviert(G.RESERVIERUNG_MAX_S + 1) == 0
    G.freigeben()                           # ohne Reservierung: nichts zu tun
    assert G.lage(0, 2)["aufnahmen_reserviert"] == 0
    G.zuruecksetzen()

    # ── (3) IM BOT: die Pruefung zaehlt die Reservierungen mit, und JEDER
    # Ausgang zwischen Reservierung und Eintrag gibt frei.
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    hst = next(n for n in baum.body if isinstance(n, _ast.AsyncFunctionDef)
               and n.name == "_handle_single_tracking")
    gs = next(c for c in _ast.walk(hst) if isinstance(c, _ast.Call)
              and getattr(c.func, "id", None) == "_start_gesperrt")
    assert "_nc_gegendruck.reserviert(" in _ast.unparse(gs), _ast.unparse(gs)

    def ruf(n, attr):
        return isinstance(n, _ast.Expr) and isinstance(n.value, _ast.Call) \
            and getattr(n.value.func, "attr", None) == attr
    von = next(n.lineno for n in _ast.walk(hst) if ruf(n, "reservieren"))
    bis = next(n.lineno for n in _ast.walk(hst) if ruf(n, "freigeben")
               and "Reservierung" in io.open("bot.py", encoding="utf-8").read().splitlines()[n.lineno - 1])
    for block in _ast.walk(hst):
        for feld in ("body", "orelse", "handlers", "finalbody"):
            koerper = getattr(block, feld, None)
            if not isinstance(koerper, list):
                continue
            for i, st in enumerate(koerper):
                if isinstance(st, _ast.Return) and von < st.lineno < bis:
                    assert i > 0 and ruf(koerper[i - 1], "freigeben"), \
                        "Ausgang in Zeile %d gibt die Reservierung nicht frei" % st.lineno
    ok("W121b: Deckel haelt unter Gleichzeitigkeit (Reservierung atomar zur Pruefung), "
       "jeder Ausgang gibt frei, Verfall nach %.0f s" % G.RESERVIERUNG_MAX_S)


def _test_v42_w122_kennzahlen_billig_und_ohne_namen():
    """Ein Schnappschuss, den /metrics nur liest, und eine Lagezeile fuer den
    Verlauf — ohne Datenbank, ohne Namen, mit sichtbarem Alter."""
    import time as _t
    from nc import kennzahlen as K

    # ── (1) NIE ERHOBEN ist None, nicht Alter 0.
    K._STAND[0] = (0.0, {})
    assert K.stand() == (None, {})
    K.veroeffentlichen({"a": 1}, jetzt=100.0)
    assert K.stand(jetzt=112.34) == (12.3, {"a": 1})

    # ── (2) PROMETHEUS: nur Zahlen, Namen bereinigt, Text faellt weg.
    daten = {"loop_lag": {"aktiv": True, "p99_ms": 4.2, "max_ms": 38.0},
             "gegendruck": {"fd": {"offen": 212, "grenze": 65536},
                            "abgewiesen": {"aufnahme:deckel": 2}},
             "kinder": {"je_art": {"yt-dlp": 1}},
             "geheim": "/home/nutzer/.env", "liste": [1, 2], "leer": None}
    txt = K.prometheus(daten, alter_s=3.5)
    zeilen = [z for z in txt.splitlines() if z and not z.startswith("#")]
    werte = dict(z.rsplit(" ", 1) for z in zeilen)
    assert werte["nightcrawler_loop_lag_aktiv"] == "1"
    assert werte["nightcrawler_loop_lag_p99_ms"] == "4.2"
    assert werte["nightcrawler_gegendruck_fd_offen"] == "212"
    assert werte["nightcrawler_gegendruck_abgewiesen_aufnahme_deckel"] == "2"
    assert werte["nightcrawler_kinder_je_art_yt_dlp"] == "1"
    assert werte["nightcrawler_kennzahlen_alter_sekunden"] == "3.5"
    import re as _re
    assert all(_re.fullmatch(r"[a-zA-Z_][a-zA-Z0-9_]*", n) for n in werte), list(werte)
    assert "/home" not in txt and "geheim" not in txt and "liste" not in txt, \
        "Text oder Listen landen in /metrics — dort koennen Namen und Pfade stehen"
    # Den WERT lesen, nicht den Text: "-1" steht auch im Hilfetext ("-1 = nie
    # erhoben"), und genau daran ist die Mutationsprobe zuerst entwischt.
    nie = [z for z in K.prometheus({}, alter_s=None).splitlines()
           if z.startswith("nightcrawler_kennzahlen_alter_sekunden ")]
    assert nie == ["nightcrawler_kennzahlen_alter_sekunden -1"], nie

    # ── (3) DIE LAGEZEILE: fehlende Werte als '?', nie als 0 (eine 0 liest
    # sich wie Normalbetrieb — dieselbe Lehre wie log_wartend = -1).
    z = K.zeile({"loop_lag": {"p99_ms": 4.2, "max_ms": 38.0},
                 "livecache": {"trefferquote": 0.362}})
    assert "Loop p99 4.2 ms" in z and "Cache 36 %" in z, z
    assert "Aufnahmen ?/?" in z and "RSS ? MB" in z, z

    # ── (4) DER PROZESS: ein /proc-Lesezugriff.
    pz = K.prozess()
    assert pz["threads"] >= 1
    if os.path.isfile("/proc/self/statm"):
        assert pz["rss_mb"] > 1, pz

    # ── (5) BILLIG: Ausgabe eines realistischen Schnappschusses in
    # Millisekunden, Lesen in Mikrosekunden — sonst gehoert er nicht in einen
    # Pfad, den ein Scraper alle 15 s abruft.
    gross = {"b%d" % i: {"x": i, "y": float(i), "z": {"w": True}} for i in range(60)}
    t0 = _t.perf_counter()
    for _ in range(20):
        K.prometheus(gross, alter_s=1.0)
        K.zeile(gross)
    assert (_t.perf_counter() - t0) / 20 < 0.005, "Ausgabe kostet mehr als 5 ms"
    K.veroeffentlichen(gross)
    t0 = _t.perf_counter()
    for _ in range(1000):
        K.stand()
    assert (_t.perf_counter() - t0) / 1000 < 0.0001
    K._STAND[0] = (0.0, {})
    ok("W122: Schnappschuss mit Alter (nie = None/-1), Prometheus nur Zahlen ohne "
       "Text/Pfade, Lagezeile mit '?', Ausgabe < 5 ms")


def _test_v42_w122_kennzahlen_verdrahtet():
    """Erhoben wird auf dem Loop ohne Datenbank, /metrics liest nur, und der
    Platz-Pfad kommt nicht mehr aus dem falschen globals()."""
    import ast as _ast
    baum = _ast.parse(io.open("bot.py", encoding="utf-8").read())
    fn = {n.name: n for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    assert any(isinstance(c, _ast.Call) and getattr(c.func, "id", None) == "_leistung_erheben"
               for c in _ast.walk(fn["_loop_lag_monitor"]))
    le = fn["_leistung_erheben"]
    namen = {c.id for c in _ast.walk(le) if isinstance(c, _ast.Name)}
    assert not namen & {"db_conn", "db_async", "get_all_active_trackings"}, \
        "die Erhebung laeuft auf dem Loop und darf nicht in die Datenbank"
    u = _ast.unparse(le)
    assert "_nc_kz.veroeffentlichen(daten)" in u and "_KZ_ZEILE_ZULETZT" in u
    assert "_loop_fehler(" in u, "ein Fehler in der Erhebung muss gemeldet werden"
    assert "betrieb=dict(_betrieb()" in _ast.unparse(fn["healthz"])

    src = io.open("nc/routes/beobachtung.py", encoding="utf-8").read()
    m = next(n for n in _ast.walk(_ast.parse(src))
             if isinstance(n, _ast.FunctionDef) and n.name == "api_prometheus_metrics")
    mu = _ast.unparse(m)
    assert "_nc_kz.stand()" in mu and "_nc_kz.prometheus(" in mu
    assert not any(isinstance(c, _ast.Call) and getattr(c.func, "id", None) == "globals"
                   for c in _ast.walk(m)), \
        "globals() in einem Blueprint ist der Namensraum des Blueprints (W4/W109)"
    assert "_c().recordings_dir" in mu
    # W122b (Review #161): auch die alten Zaehler fragen die Datenbank nicht
    # je Abruf, sondern hoechstens einmal je Minute ueber den Schnappschuss.
    direkt = {c.id for c in _ast.walk(m) if isinstance(c, _ast.Name)} \
        & {"db_conn", "get_all_active_trackings"}
    assert not direkt, "/metrics zaehlt wieder bei jedem Abruf in der Datenbank: %r" % direkt
    assert "_DB_ZAEHLER.holen(_db_zaehler)" in mu
    import nc.routes.beobachtung as _B
    assert _B._DB_ZAEHLER.gueltig_s >= 30, _B._DB_ZAEHLER.gueltig_s
    gerufen = []
    alt = _B._DB_ZAEHLER
    try:
        _B._DB_ZAEHLER = type(alt)(gueltig_s=60.0, warte_s=1.0)
        for _ in range(5):
            _B._DB_ZAEHLER.holen(lambda: gerufen.append(1) or {"x": 1})
    finally:
        _B._DB_ZAEHLER = alt
    assert len(gerufen) == 1, gerufen
    ok("W122: Erhebung alle 10 s ohne Datenbank, Fehler ueber _loop_fehler, /metrics "
       "liest den Schnappschuss, Platz am echten Aufnahmepfad")


def _w123_tools():
    import sys as _sys
    _sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "tools"))
    import i18n_tools as _it
    return _it


def _test_v42_w123_shell_i18n_ehrlich():
    """v4.2-W123: der Shell-Pruefer meldete 100 %, waehrend ~150 Zeilen deutsch blieben."""
    _it = _w123_tools()

    # ── (1) DER ECHTE BESTAND IST VOLLSTAENDIG — und zwar am geschaerften
    # Massstab. Vor W123 lieferte dieser Lauf 373/373; derselbe Lauf mit dem
    # neuen Sammler fand 67 unumschlossene Ausgaben, 45 zusammengesetzte
    # Senken-Texte und 24 fehlende Eintraege.
    import contextlib as _cl
    _puffer = io.StringIO()
    _alt_argv = sys.argv
    try:
        sys.argv = ["i18n_tools.py", "--check", "en"]
        with _cl.redirect_stdout(_puffer):
            rc = _it.main()
    finally:
        sys.argv = _alt_argv
    assert rc == 0, _puffer.getvalue()[-2000:]
    assert "tools/update.sh" in _it.QUELLEN, "update.sh faellt aus der Pruefung"
    assert any(q.startswith("tools/lib/") for q in _it.shell_quellen()), \
        "tools/lib/ wird nicht geprueft — dort stehen die gemeinsamen Senken"

    # ── (2) JEDER BLINDE FLECK EINZELN. Eine Probe je Form, die den alten
    # Pruefer passiert hat. Ein Melder, der eine dieser Zeilen durchlaesst,
    # meldet wieder 100 % fuer etwas, das deutsch bleibt.
    probe = _ph.verzeichnis()
    os.makedirs(os.path.join(probe, "tools", "lib"))
    os.makedirs(os.path.join(probe, "locales"))
    _alt_root = _it.ROOT

    def _datei(inhalt, name="x.sh"):
        with open(os.path.join(probe, name), "w", encoding="utf-8") as f:
            f.write(inhalt)
        return name

    try:
        _it.ROOT = probe
        # einfach gequotetes printf-Format
        assert _it.unumschlossen(_datei("printf '  %sZielverzeichnis: %s%s\\n' \"$FNT\" \"$Z\" \"$R\"\n")), \
            "einfach gequotetes printf faellt durch"
        # Heredoc auf den Bildschirm
        assert _it.unumschlossen(_datei("cat <<'H'\n  --dir <Pfad>  Zielverzeichnis\nH\n")), \
            "cat-Heredoc faellt durch"
        # ... aber NICHT ein Heredoc in eine Datei (Unit, nginx): sonst
        # Fehlalarm auf jedem systemd-Kommentar.
        assert not _it.unumschlossen(_datei("cat > f <<U\n# Von Hand aenderbar\nU\n")), \
            "Fehlalarm auf einem Heredoc in eine Datei"
        # Verschiebung ist kein Heredoc — sonst verschluckt der Melder den Rest.
        assert _it.unumschlossen(_datei("x=$((1<<2))\nprintf 'Dienst nicht gefunden\\n'\n")), \
            "$((1<<2)) wurde als Heredoc gelesen und hat die naechste Zeile verschluckt"
        # Vorgabewert in ${X:-…}
        assert _it.unumschlossen(_datei('printf "%s\\n" "${D:-— nicht gefunden}"\n')), \
            "Text im Vorgabewert faellt durch"
        # Laufzeitwert im Senken-Text
        assert _it.zusammengesetzt(_datei('info "Python gefunden: $PY"\n')), \
            "zusammengesetzter Senken-Text faellt durch"
        assert _it.zusammengesetzt(_datei('  x) warn "Zweig $B fehlt";;\n')), \
            "zusammengesetzter Text im case-Zweig faellt durch"
        # Erlaubt: tf-Form, blanke Variable, ganze $(tf …)-Umschliessung.
        for gut_ in ('info "Python gefunden: %s" "$PY"\n', 'erklaere "$text"\n',
                     'frage_ja "$(tf \'%s: erzeugen?\' "$(t "$was")")" J\n'):
            assert not _it.zusammengesetzt(_datei(gut_)), "Fehlalarm: %r" % gut_
        # Sammeln: case-Zweig, Durchreicher, tz-Heredoc, einfache Quotes.
        text = ('  express) info "Betriebsart: %s — nur Pflichtfragen." "$B";;\n'
                'opt_frage "redis" N "Redis-Cache: entlastet."\n'
                "tz <<'H'\n  --dir <Pfad>  Zielverzeichnis\nH\n"
                "x=\"$(t 'ausgelassen:')\"\n"
                '# info "Kommentar ist keine Ausgabe"\n'
                'frage_ja(){ # frage_ja "Frage" [J|N]\n')
        ges = _it.sammeln_shell(text)
        for soll in ("Betriebsart: %s — nur Pflichtfragen.", "Redis-Cache: entlastet.",
                     "--dir <Pfad>  Zielverzeichnis", "ausgelassen:"):
            assert soll in ges, "nicht eingesammelt: %r" % soll
        for nicht in ("Kommentar ist keine Ausgabe", "Frage"):
            assert nicht not in ges, "Kommentar als Schluessel eingesammelt: %r" % nicht
        # Batch: Notiz-Zeilen sind Ausgabe, auch umgeleitet.
        assert _it.unumschlossen(_datei('>>"%NOTIZ%" echo   Starten     %ZIEL%\\start.bat\n',
                                        "x.bat")), "Notiz-Zeile in install.bat faellt durch"

        # ── (3) PLATZHALTER. Ein %s weniger in der Uebersetzung schiebt jeden
        # Wert eine Stelle nach vorn — ohne Fehlermeldung.
        assert _it.platzhalter_bruch({"A %s B %s": "A %s B"}) == ["A %s B %s"]
        assert _it.platzhalter_bruch({"A %s": "B %s"}) == []

        # ── (4) FEHLEND MACHT ROT. Bis W123 meldete --check eine Luecke nur als
        # Zahl; zur Laufzeit faellt sie weiter auf Deutsch zurueck (lib/i18n.sh),
        # aber die CI muss sie sehen.
        with open(os.path.join(probe, "tools", "installer.sh"), "w", encoding="utf-8") as f:
            f.write('info "Ein neuer Satz ohne Uebersetzung."\n')
        with open(os.path.join(probe, "locales", "tools.en.tsv"), "w", encoding="utf-8") as f:
            f.write("# leer\n")
        sys.argv = ["i18n_tools.py", "--check", "en"]
        with _cl.redirect_stdout(io.StringIO()):
            assert _it.main() == 1, "ein fehlender Eintrag macht die Pruefung nicht rot"
        with open(os.path.join(probe, "locales", "tools.en.tsv"), "w", encoding="utf-8") as f:
            f.write("Ein neuer Satz ohne Uebersetzung.\tA new sentence.\n")
        with _cl.redirect_stdout(io.StringIO()):
            assert _it.main() == 0, "vollstaendiger Katalog wird abgelehnt"
    finally:
        _it.ROOT = _alt_root
        sys.argv = _alt_argv
    ok("W123: Shell-i18n — sechs blinde Flecken geschlossen, fehlend = rot, Platzhalter geprueft")


def _test_v42_w123_werkzeuge_sprechen_englisch():
    """v4.2-W123: am Lauf gemessen, nicht an der Quote."""
    import subprocess as _sp
    _it = _w123_tools()

    def _lauf(befehl, sprache, **umg):
        e = dict(os.environ)
        e.update({"NC_LANG": sprache, "COLOR_MODE": "off", "CONF": os.devnull})
        e.update(umg)
        r = _sp.run(befehl, capture_output=True, text=True, env=e, timeout=120)
        return r.returncode, r.stdout + r.stderr

    laeufe = [
        ["bash", "tools/installer.sh", "--help"],
        ["bash", "tools/update.sh", "--help"],
        ["bash", "tools/motd.sh", "--help"],
        ["bash", "tools/motd.sh", "--doctor"],
    ]
    for befehl in laeufe:
        rc_en, en = _lauf(befehl, "en")
        rc_de, de = _lauf(befehl, "de")
        assert rc_en == rc_de, "%s: Exitcode haengt an der Sprache" % befehl
        assert en != de, "%s: die englische Ausgabe ist die deutsche" % befehl
        # Jede Zeile mit deutschem Marker ist ein Befund. "mein-bot" im
        # Beispielpfad ist ein Pfad, kein Satz.
        rest = [z for z in en.splitlines()
                if _it._DEUTSCH.search(z.replace("mein-bot", ""))]
        assert not rest, "%s bleibt deutsch: %r" % (" ".join(befehl[1:]), rest[:3])

    # tf: ein Argument heisst t OHNE printf — "90 % voll" darf nicht als
    # Format gelesen werden. Mehrere: Format mit Werten.
    r = _sp.run(["sh", "-c", ". tools/lib/i18n.sh; tf '90 % voll'; echo; "
                 "tf 'Python gefunden: %s (%s)' /x 3.13"],
                capture_output=True, text=True, env=dict(os.environ, NC_LANG="en"))
    assert r.stdout.split("\n")[:2] == ["90 % voll", "Python found: /x (3.13)"], r.stdout
    # tz: Einrueckung bleibt, gehoert aber nicht zum Schluessel.
    r = _sp.run(["sh", "-c", ". tools/lib/i18n.sh; printf '    --help           diese Hilfe\\n' | tz"],
                capture_output=True, text=True, env=dict(os.environ, NC_LANG="en"))
    assert r.stdout == "    --help           this help\n", repr(r.stdout)
    # Ohne Katalog bleibt es deutsch — nie ein leerer Text.
    r = _sp.run(["sh", "-c", ". tools/lib/i18n.sh; tf 'Python gefunden: %s' /x"],
                capture_output=True, text=True,
                env=dict(os.environ, NC_LANG="en", NC_I18N_KATALOG="/gibt/es/nicht"))
    assert r.stdout == "Python gefunden: /x", repr(r.stdout)
    ok("W123: installer/update/motd laufen auf Englisch ohne deutschen Rest; tf/tz wirken")


def _w123_sandbox(fehlt=("ffmpeg",), mit_listen=True):
    """Eine Maschine im Kleinen: Debian, apt als Attrappe, eigener PATH.

    Kein Test-Haken im Skript: gemessen wird update.sh, wie es ausgeliefert
    wird. Der PATH enthaelt die Grundwerkzeuge (Verweise) und Attrappen fuer
    alles, was installiert — sie protokollieren nur.
    """
    import shutil as _sh
    import stat as _st
    d = _ph.verzeichnis()
    binv = os.path.join(d, "bin")
    os.makedirs(binv)
    for w in ("sh", "bash", "sed", "awk", "tr", "grep", "cut", "head", "tail", "cat",
              "mkdir", "rm", "cp", "id", "uname", "sort", "wc", "env", "date", "tee",
              "mktemp", "dirname", "basename", "fold", "printf", "ls", "chmod", "mv"):
        q = _sh.which(w)
        if q:
            os.symlink(q, os.path.join(binv, w))
    proto = os.path.join(d, "protokoll.txt")
    open(proto, "w").close()

    def _attrappe(name, rumpf):
        p = os.path.join(binv, name)
        with open(p, "w") as f:
            f.write("#!/bin/sh\n" + rumpf + "\n")
        os.chmod(p, os.stat(p).st_mode | _st.S_IEXEC)

    for w in ("ffmpeg", "streamlink", "yt-dlp", "git", "curl", "sqlite3"):
        if w not in fehlt:
            _attrappe(w, "exit 0")
    # apt-get legt das Werkzeug WIRKLICH an, sobald es "installiert" wird —
    # nur so laesst sich die Nachpruefung und der zweite Lauf pruefen.
    _attrappe("apt-get", 'echo "apt-get $*" >> "%s"\n'
              'if [ "$1" = install ]; then shift; shift\n'
              '  for p in "$@"; do printf "#!/bin/sh\\nexit 0\\n" > "%s/$p"; chmod +x "%s/$p"; done\nfi'
              % (proto, binv, binv))
    _attrappe("apt-cache", "exit 0")
    _attrappe("sudo", 'exec "$@"')
    osr = os.path.join(d, "os-release")
    with open(osr, "w") as f:
        f.write('ID=debian\nPRETTY_NAME="Debian GNU/Linux 13"\n')
    listen = os.path.join(d, "apt-listen")
    os.makedirs(listen)
    if mit_listen:
        open(os.path.join(listen, "deb_main_binary-amd64_Packages"), "w").close()
    ziel = os.path.join(d, "ziel")
    os.makedirs(os.path.join(ziel, ".venv", "bin"))
    with open(os.path.join(ziel, "requirements.txt"), "w") as f:
        f.write("pip >= 1\nnc-gibt-es-nicht >= 1   # [optional] nur fuer den Vertrag\n")
    # Das venv-Python ist ein Umschlag um den echten Interpreter: pip-Aufrufe
    # werden protokolliert statt ausgefuehrt, alles andere laeuft echt.
    _attrappe(os.path.join("..", "ziel", ".venv", "bin", "python"),
              'if [ "$1" = "-m" ] && [ "$2" = "pip" ]; then echo "pip $*" >> "%s"; exit 0; fi\n'
              'exec "%s" "$@"' % (proto, sys.executable))
    umg = {"PATH": binv, "NC_OS_RELEASE": osr, "NC_APT_LISTEN": listen,
           "NC_UNAME": "Linux", "NC_LANG": "de", "HOME": d}
    return d, ziel, proto, umg


def _w123_update(ziel, umg, *schalter):
    import subprocess as _sp
    e = {k: v for k, v in os.environ.items() if not k.startswith("NC_")}
    e.update(umg)
    r = _sp.run(["/bin/bash", os.path.abspath("tools/update.sh"), "--no-color",
                 "--dir", ziel] + list(schalter),
                capture_output=True, text=True, env=e, timeout=120, stdin=_sp.DEVNULL)
    return r.returncode, r.stdout + r.stderr


def _test_v42_w123_update_idempotent():
    """v4.2-W123: tools/update.sh — pruefen, zeigen, installieren, nachmessen, nichts doppelt."""
    d, ziel, proto, umg = _w123_sandbox()

    def _protokoll():
        return open(proto).read().splitlines()

    # ── (1) --check: Exit 1, und es wird NICHTS ausgefuehrt.
    rc, aus = _w123_update(ziel, umg, "--check")
    assert rc == 1, (rc, aus)
    assert "ffmpeg fehlt" in aus and "apt-get install -y ffmpeg" in aus, aus
    assert _protokoll() == [], "--check hat etwas ausgefuehrt: %r" % _protokoll()

    # ── (2) --dry-run: zeigt woertlich, was liefe, und fuehrt nichts aus.
    rc, aus = _w123_update(ziel, umg, "--dry-run")
    assert rc == 0, (rc, aus)
    # Ohne root setzt das Skript sudo davor, als root nicht — der Vertrag
    # erwartet GENAU die Form fuer den laufenden Nutzer. In der CI (kein root)
    # fiel die erste Fassung, die nur die root-Form kannte (W123, PR #162).
    _sudo = "" if os.geteuid() == 0 else "sudo "
    assert ("$ %sapt-get update -qq" % _sudo) in aus, aus
    assert ("$ %sapt-get install -y ffmpeg" % _sudo) in aus, aus
    assert _protokoll() == [], "--dry-run hat etwas ausgefuehrt: %r" % _protokoll()

    # ── (3) Optionale Pakete nur auf Wunsch. Ohne --optional sind sie nicht
    # einmal im Plan — sonst holte ein Abgleich auf einem Pi still
    # 300 MB faster-whisper.
    assert "nc-gibt-es-nicht" not in aus, "optionales Paket ohne --optional im Plan"
    rc, aus = _w123_update(ziel, umg, "--dry-run", "--python-deps", "--optional")
    assert "pip install nc-gibt-es-nicht>=1" in aus, aus
    assert _protokoll() == []

    # ── (4) Der echte Lauf: auffrischen, installieren, NACHMESSEN.
    rc, aus = _w123_update(ziel, umg, "-y")
    assert rc == 0, (rc, aus)
    assert _protokoll() == ["apt-get update -qq", "apt-get install -y ffmpeg"], _protokoll()
    assert "ffmpeg: jetzt vorhanden" in aus, aus
    assert "pip" not in " ".join(_protokoll()), "pip lief, obwohl nichts fehlte"

    # ── (5) IDEMPOTENT. Der zweite Lauf fuehrt keinen einzigen Befehl aus.
    rc, aus = _w123_update(ziel, umg, "-y")
    assert rc == 0 and "Nichts zu tun" in aus, (rc, aus)
    assert len(_protokoll()) == 2, "zweiter Lauf hat installiert: %r" % _protokoll()

    # ── (6) NACHGEMESSEN, NICHT ANGENOMMEN. Ein Paketmanager, der mit 0
    # endet, ohne das Werkzeug zu liefern, darf nicht "vollstaendig" heissen.
    d2, ziel2, proto2, umg2 = _w123_sandbox(fehlt=("sqlite3",))
    with open(os.path.join(umg2["PATH"], "apt-get"), "w") as f:
        f.write("#!/bin/sh\necho \"apt-get $*\" >> \"%s\"\nexit 0\n" % proto2)
    rc, aus = _w123_update(ziel2, umg2, "-y")
    assert rc == 1 and "sqlite3 fehlt weiterhin" in aus, (rc, aus)

    # ── (7) LEERE PAKETLISTEN sind kein "gibt es nicht". Frisches Image ohne
    # apt-get update: apt-cache findet nichts — vorher hiess das "selbst
    # bereitstellen", obwohl das Paket in jeder Debian-Quelle liegt.
    d3, ziel3, proto3, umg3 = _w123_sandbox(mit_listen=False)
    with open(os.path.join(umg3["PATH"], "apt-cache"), "w") as f:
        f.write("#!/bin/sh\nexit 100\n")
    rc, aus = _w123_update(ziel3, umg3, "--check")
    assert "apt-get install -y ffmpeg" in aus and "Selbst bereitstellen" not in aus, aus

    # ── (9) OPTIONAL, ABER PER .env EINGESCHALTET. Mit DB_BACKEND=mariadb ist
    # PyMySQL Pflicht; fehlte es, meldete --python-deps "vollstaendig", und der
    # Bot starb am Import (Befund Codex-Review, PR #162). Eine auskommentierte
    # Zeile schaltet nichts ein.
    with open(os.path.join(ziel, "requirements.txt"), "a") as f:
        f.write("PyMySQL >= 999   # [optional] Treiber\n")
    envd = os.path.join(ziel, ".env")
    with open(envd, "w") as f:
        # Die auskommentierte Zeile steht HINTER der echten: "letzter Wert
        # gewinnt" darf sie nicht mitzaehlen. Davor stehend war die Probe, die
        # Kommentare mitlas, entwischt.
        f.write("DB_BACKEND=sqlite\n# DB_BACKEND=mariadb\n")
    rc, aus = _w123_update(ziel, umg, "--check", "--python-deps")
    assert rc == 0 and "PyMySQL" not in aus, (rc, aus)
    with open(envd, "w") as f:
        f.write('DB_BACKEND="mariadb"   # umgestellt\n')
    rc, aus = _w123_update(ziel, umg, "--check", "--python-deps")
    assert rc == 1, (rc, aus)
    assert "PyMySQL ist optional, wird hier aber gebraucht: DB_BACKEND=mariadb" in aus, aus
    assert "PyMySQL>=999" in aus, aus

    # ── (8) Aufruffehler sind 2, nicht 1 — "es fehlt etwas" und "falsch
    # aufgerufen" muessen fuer einen Zeitplan unterscheidbar bleiben.
    rc, _ = _w123_update(ziel, umg, "--gibt-es-nicht")
    assert rc == 2
    rc, _ = _w123_update(ziel, umg, "--pkg", "yum")
    assert rc == 2
    ok("W123: update.sh prueft, zeigt, installiert nur Fehlendes, misst nach — zweiter Lauf tut nichts")


def _test_v42_w123_paketwahl_je_distribution():
    """v4.2-W123: eine Erkennung fuer alle Werkzeuge, sieben Distributionen."""
    import subprocess as _sp
    d = _ph.verzeichnis()
    faelle = [
        ('ID=ubuntu\nID_LIKE=debian', "apt", "sqlite3", "apt-get install -y x"),
        ('ID=fedora', "dnf", "sqlite", "dnf install -y x"),
        ('ID=rocky\nID_LIKE="rhel centos fedora"', "dnf", "sqlite", "dnf install -y x"),
        # Eine ID, die die Liste NICHT kennt — nur ID_LIKE kann sie zuordnen.
        # (Rocky allein prueft das nicht: "rocky" steht selbst in der Liste;
        # die Mutationsprobe, die ID_LIKE entfernte, ist daran entwischt.)
        ('ID=nobara\nID_LIKE="fedora"', "dnf", "sqlite", "dnf install -y x"),
        ('ID=cachyos\nID_LIKE=arch', "pacman", "sqlite", "pacman -S --needed --noconfirm x"),
        ('ID=arch', "pacman", "sqlite", "pacman -S --needed --noconfirm x"),
        ('ID="opensuse-tumbleweed"\nID_LIKE="opensuse suse"', "zypper", "sqlite3",
         "zypper --non-interactive install x"),
        ('ID=alpine', "apk", "sqlite", "apk add x"),
    ]
    for osr, pkg, sqlite, befehl in faelle:
        p = os.path.join(d, "os-release")
        with open(p, "w") as f:
            f.write(osr + "\n")
        r = _sp.run(["sh", "-c", ". tools/lib/system.sh; nc_system_erkennen; "
                     "printf '%s|%s|%s' \"$NC_PKG\" \"$(nc_paketname sqlite3)\" "
                     "\"$(nc_installbefehl x)\""],
                    capture_output=True, text=True,
                    env={"PATH": "/usr/bin:/bin", "NC_OS_RELEASE": p, "NC_UNAME": "Linux"})
        assert r.stdout == "%s|%s|%s" % (pkg, sqlite, befehl), (osr, r.stdout, r.stderr)
    # macOS: brew, ohne root.
    r = _sp.run(["sh", "-c", ". tools/lib/system.sh; nc_system_erkennen; "
                 "nc_braucht_root && echo root || echo ohne"],
                capture_output=True, text=True,
                env={"PATH": "/usr/bin:/bin", "NC_UNAME": "Darwin", "NC_PKG": "brew"})
    assert r.stdout.strip() == "ohne", r.stdout
    # ffmpeg auf Fedora: zwei Kandidaten in Vorzugsreihenfolge (RPM Fusion
    # zuerst, sonst ffmpeg-free aus den Fedora-Quellen).
    r = _sp.run(["sh", "-c", ". tools/lib/system.sh; nc_paketname ffmpeg dnf"],
                capture_output=True, text=True)
    assert r.stdout == "ffmpeg ffmpeg-free", r.stdout
    # pacman NIE mit -Sy: das ist ein Teil-Upgrade, das Arch nicht unterstuetzt.
    # Gemessen an dem, was die Bibliothek AUSGIBT — nicht am Dateitext, denn
    # dort steht -Sy in der Begruendung, warum es fehlt (Lehre W102-W104).
    r = _sp.run(["sh", "-c", ". tools/lib/system.sh; NC_PKG=pacman; nc_installbefehl x; "
                 "echo; nc_auffrischbefehl || echo KEINER"], capture_output=True, text=True)
    assert "-Sy" not in r.stdout and r.stdout.endswith("KEINER\n"), r.stdout
    lib = open("tools/lib/system.sh", encoding="utf-8").read()
    # os-release wird GELESEN, nicht gesourct — ein `.` darauf fuehrt eine
    # Systemdatei als Code aus.
    import re as _re
    assert not _re.search(r'^\s*\.\s+"?\$_rel', lib, _re.M), "os-release wird gesourct"
    ok("W123: lib/system.sh — apt/dnf/pacman/zypper/apk/brew, ID_LIKE, ffmpeg-free, kein -Sy")


def _test_v42_w123_anforderungen():
    """v4.2-W123: requirements.txt gegen eine Umgebung — offline und ohne zweite Liste."""
    import sys as _sys
    _sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "tools"))
    import anforderungen as A
    d = _ph.verzeichnis()
    p = os.path.join(d, "req.txt")
    with open(p, "w") as f:
        f.write("# Kopf\nPyMySQL >= 1.1  # [optional] Treiber\nFlask>=2.2\nalt >= 2.0\n"
                "fern >= 1\nnurwin >= 1; sys_platform == 'nie'\n-r anderes.txt\n")
    tab = A.abgleich(p, vorhanden={"pymysql": "1.1.1", "flask": "3.0", "alt": "1.9"})
    st = {z[1]: (z[0], z[4]) for z in tab}
    assert st == {"PyMySQL": ("ok", "optional"), "Flask": ("ok", "pflicht"),
                  "alt": ("alt", "pflicht"), "fern": ("fehlt", "pflicht"),
                  "nurwin": ("entfaellt", "pflicht")}, st
    # Eine kaputte Zeile ist ein Befund, kein Ueberspringen.
    with open(p, "w") as f:
        f.write("das ist == keine == anforderung\n")
    try:
        A.abgleich(p, vorhanden={})
        raise AssertionError("ungueltige Zeile wurde still uebergangen")
    except RuntimeError:
        pass
    # Die Marke steht in requirements.txt — und genau die sechs Pakete, die
    # der Installer als abwaehlbar fuehrt, tragen sie.
    opt = sorted(t.split()[0] for t, o in A.zeilen("requirements.txt") if o)
    # v5.3-W193: mysqlclient dazu — der Installer nimmt es nie in den
    # allgemeinen pip-Lauf (OPT_AUS), sondern baut es im MariaDB-Abschnitt.
    assert opt == sorted(["discord.py", "PyMySQL", "redis", "faster-whisper", "boto3",
                          "uvloop", "mysqlclient"]), opt
    ok("W123: anforderungen.py — ok/fehlt/alt/entfaellt, Marke [optional], kaputte Zeile = Fehler")


def _w124_quelle():
    """Ein Quellbaum im Kleinen — der Installer kopiert ihn wie den echten.

    Nicht der echte Baum: der waere 30 MB je Lauf, und es geht um den
    Installer, nicht um bot.py. Echt sind installer.sh, lib/, die
    Uebersetzung und anforderungen.py; bot.py ist eine Attrappe, deren
    Selbsttest ohne Befund endet.
    """
    import shutil as _sh
    q = _ph.verzeichnis()
    os.makedirs(os.path.join(q, "tools"))
    _sh.copy("tools/installer.sh", os.path.join(q, "tools"))
    _sh.copy("tools/anforderungen.py", os.path.join(q, "tools"))
    _sh.copytree("tools/lib", os.path.join(q, "tools", "lib"))
    _sh.copytree("locales", os.path.join(q, "locales"))
    with open(os.path.join(q, "bot.py"), "w") as f:
        f.write("import sys\nsys.exit(0)\n")
    with open(os.path.join(q, "requirements.txt"), "w") as f:
        f.write("pip >= 1\n")
    with open(os.path.join(q, ".env.example"), "w") as f:
        f.write("# Vorlage\n# DASHBOARD_PORT=8050\n# WEB_HOST=127.0.0.1\n"
                "DASHBOARD_TOKEN=\n# RESTREAM_BITRATE_K=6000\n# RESTREAM_SINGLE=1\n"
                "# WORKER_COUNT=4\n# DB_BACKEND=sqlite\n")
    return q


def _w124_umgebung(heim, **mehr):
    e = {k: v for k, v in os.environ.items() if not k.startswith("NC_")}
    # Kein Dienst, keine MOTD: die Suite laeuft auch auf CI-Rechnern mit
    # systemd und sudo — dort darf sie nichts unter /etc anlegen.
    e.update({"HOME": heim, "NC_INIT": "keiner", "NC_MOTD_WEG": "keiner", "NC_LANG": "de"})
    e.update(mehr)
    return e


def _w124_installer(quelle, ziel, heim, *schalter, **umg):
    import subprocess as _sp
    r = _sp.run(["bash", os.path.join(quelle, "tools", "installer.sh"), "--no-color",
                 "--skip-system", "--dir", ziel] + list(schalter),
                capture_output=True, text=True, env=_w124_umgebung(heim, **umg),
                timeout=300, stdin=_sp.DEVNULL)
    return r.returncode, r.stdout + r.stderr


def _w124_venv(ziel, proto):
    """Ein venv, dessen pip nur protokolliert — alles andere laeuft echt."""
    import stat as _st
    b = os.path.join(ziel, ".venv", "bin")
    os.makedirs(b)
    p = os.path.join(b, "python")
    with open(p, "w") as f:
        # Wie echtes pip: ein installiertes Programm liegt danach in .venv/bin.
        # Ohne das installierte jeder Lauf streamlink/yt-dlp erneut, und der
        # Vertrag hielte den Installer fuer nicht idempotent.
        f.write('#!/bin/sh\nif [ "$1" = "-m" ] && [ "$2" = "pip" ]; then echo "pip $*" >> "%s"\n'
                '  for p in "$@"; do case "$p" in streamlink|yt-dlp) printf "#!/bin/sh\\n" > "%s/$p";'
                ' chmod +x "%s/$p";; esac; done; exit 0; fi\n'
                'exec "%s" "$@"\n' % (proto, b, b, sys.executable))
    os.chmod(p, os.stat(p).st_mode | _st.S_IEXEC)


def _test_v42_w124_installer_idempotent():
    """v4.2-W124: zweiter Lauf aendert nichts — auch keine Geheimnisse."""
    import re as _re
    q = _w124_quelle()
    heim = _ph.verzeichnis()
    ziel = os.path.join(_ph.verzeichnis(), "nc")
    proto = os.path.join(heim, "pip.log")
    open(proto, "w").close()

    # ── (1) TROCKENLAUF schreibt nichts — das Ziel entsteht nicht einmal.
    rc, aus = _w124_installer(q, ziel, heim, "--dry-run", "-y")
    assert rc == 0, aus[-2000:]
    assert not os.path.exists(ziel), "der Trockenlauf hat das Ziel angelegt"
    assert "Trockenlauf beendet" in aus
    # Alle Punkte der Zusammenfassung, nummeriert.
    for n, titel in ((1, "Python"), (5, "Dashboard"), (8, "Leistungsprofil"), (14, "Totmann-Meldung")):
        assert _re.search(r"^\s+%d\s+%s\s" % (n, titel), aus, _re.M), "Punkt %d fehlt" % n
    # Geheimnisse im Diff maskiert: der erzeugte Token steht NICHT im Klartext da.
    assert "DASHBOARD_TOKEN=***" in aus, aus[-1500:]
    assert not _re.search(r"[A-Za-z0-9]{40}", aus), "ein 40-Zeichen-Token steht im Klartext"

    # ── (2) ERSTER ECHTER LAUF.
    os.makedirs(os.path.dirname(ziel), exist_ok=True)
    os.makedirs(ziel)
    _w124_venv(ziel, proto)
    rc, aus = _w124_installer(q, ziel, heim, "-y")
    assert rc == 0, aus[-3000:]
    envf = os.path.join(ziel, ".env")
    env1 = open(envf).read()
    tok = _re.search(r"^DASHBOARD_TOKEN=(\S+)$", env1, _re.M)
    assert tok and len(tok.group(1)) == 40, env1
    assert oct(os.stat(envf).st_mode & 0o777) == "0o600", oct(os.stat(envf).st_mode)
    assert "Python-Pakete vollstaendig" in aus, "pip wurde trotz vollstaendigem venv gerufen"
    # Nur die beiden Werkzeuge, die im PATH fehlen — nicht requirements.txt.
    assert open(proto).read().splitlines() == ["pip -m pip install streamlink",
                                               "pip -m pip install yt-dlp"], open(proto).read()
    open(proto, "w").close()

    # ── (3) ZWEITER LAUF: kein neuer Token, keine Sicherung, kein pip.
    # Bis W123 erzeugte --unattended hier einen NEUEN Token — jeder
    # gespeicherte ?token=-Link waere tot gewesen.
    rc, aus = _w124_installer(q, ziel, heim, "-y")
    assert rc == 0, aus[-2000:]
    assert open(envf).read() == env1, "der zweite Lauf hat die .env veraendert"
    assert ".env: keine Aenderung." in aus
    assert not [n for n in os.listdir(ziel) if n.startswith(".env.bak")], \
        "eine Sicherung ohne Aenderung angelegt"
    assert "unveraendert: %s/start.sh" % ziel in aus, aus[-1500:]
    assert open(proto).read() == ""

    # ── (4) HANDGESTELLTES BLEIBT. Ein unbeaufsichtigter Lauf darf einen
    # Wert, den niemand abgefragt hat, nicht auf "Vorgaben" zuruecksetzen.
    with open(envf, "a") as f:
        f.write("RESTREAM_BITRATE_K=4500\n")
    env2 = open(envf).read()
    rc, aus = _w124_installer(q, ziel, heim, "-y")
    assert rc == 0 and open(envf).read() == env2, "handgestellter Wert ueberschrieben"

    # ── (5) MIT ABWEICHUNG: Diff gegen den Bestand, Sicherung, dann schreiben.
    rc, aus = _w124_installer(q, ziel, heim, "-y", DASHBOARD_PORT_GIBT_ES_NICHT="1")
    with open(envf) as f:
        alt = f.read()
    with open(envf, "w") as f:
        f.write(alt.replace("WEB_HOST=127.0.0.1", "WEB_HOST=127.0.0.2"))
    os.chmod(envf, 0o600)
    rc, aus = _w124_installer(q, ziel, heim, "-y")
    assert rc == 0, aus[-1500:]
    assert "-WEB_HOST=127.0.0.2" in aus and "+WEB_HOST=127.0.0.1" in aus, aus[-2000:]
    assert [n for n in os.listdir(ziel) if n.startswith(".env.bak")], "keine Sicherung vor dem Schreiben"
    ok("W124: Installer — Trockenlauf schreibt nichts, zweiter Lauf aendert nichts (Token bleibt), "
       "handgestellte Werte bleiben, Abweichung mit Diff und Sicherung")


def _w124_pty(argv, env, antworten, zeit=180):
    """Eine echte Terminalsitzung: der Installer liest von /dev/tty."""
    import pty as _pty
    import select as _sel
    import time as _time
    pid, fd = _pty.fork()
    if pid == 0:
        os.execvpe(argv[0], argv, env)
    puffer, ende, still = b"", _time.time() + zeit, 0.0
    while _time.time() < ende:
        r, _, _ = _sel.select([fd], [], [], 0.25)
        if r:
            try:
                daten = os.read(fd, 4096)
            except OSError:
                break
            if not daten:
                break
            puffer += daten
            still = 0.0
            continue
        still += 0.25
        if still >= 0.5:
            os.write(fd, antworten(puffer.decode("utf-8", "replace")).encode())
            still = 0.0
    else:
        os.kill(pid, 9)
    _, status = os.waitpid(pid, 0)
    return os.waitstatus_to_exitcode(status), puffer.decode("utf-8", "replace")


def _test_v42_w124_aenderungsschleife():
    """v4.2-W124: jeder Punkt der Zusammenfassung ist aenderbar — in BEIDE Richtungen."""
    q = _w124_quelle()
    heim = _ph.verzeichnis()
    ziel = os.path.join(_ph.verzeichnis(), "nc")
    # Erst sparsam (3), dann zurueck auf Vorgaben (2), dann Enter = Ende.
    plan = [("8", "3"), ("8", "2")]
    zustand = {"summ": 0, "wahl": 0}

    def antworten(text):
        n = text.count("Nummer zum Aendern")
        if n > zustand["summ"]:
            zustand["summ"] = n
            return (plan[n - 1][0] if n <= len(plan) else "") + "\n"
        if 1 <= zustand["summ"] <= len(plan) and zustand["wahl"] < zustand["summ"] \
                and text.rstrip().endswith("]:"):
            zustand["wahl"] = zustand["summ"]
            return plan[zustand["summ"] - 1][1] + "\n"
        return "\n"

    rc, aus = _w124_pty(["bash", os.path.join(q, "tools", "installer.sh"), "--dry-run",
                         "--no-color", "--skip-system", "--dir", ziel],
                        _w124_umgebung(heim), antworten)
    assert rc == 0, aus[-3000:]
    teile = aus.split("Nummer zum Aendern")
    assert len(teile) == 4, "drei Zusammenfassungen erwartet, %d gesehen" % (len(teile) - 1)
    erste, zweite, dritte = teile[0], teile[1], teile[2]
    assert "RESTREAM_BITRATE_K" not in erste
    assert "sparsam" in zweite and "+RESTREAM_BITRATE_K=3500" in zweite, zweite[-1500:]
    # Zurueck: der Plan verliert die sparsamen Werte wieder. Ohne
    # env_zuruecksetzen blieben sie stehen — die Aenderung wirkte nur in
    # eine Richtung.
    assert "RESTREAM_BITRATE_K" not in dritte and "Vorgaben" in dritte, dritte[-1500:]
    assert "Trockenlauf beendet" in teile[3]
    assert not os.path.exists(ziel)
    ok("W124: Zusammenfassung — Punkt 8 hin und zurueck, Diff folgt beiden Richtungen")


def _test_v42_w124_systemerkennung():
    """v4.2-W124: Init, MOTD-Weg, nginx-Ort, Firewall und Python je Distribution."""
    import subprocess as _sp

    def _sh(befehl, **umg):
        e = {"PATH": "/usr/bin:/bin"}
        e.update(umg)
        r = _sp.run(["sh", "-c", ". tools/lib/system.sh; " + befehl],
                    capture_output=True, text=True, env=e)
        return r.stdout

    for pkg, nginx, fw, py, cert in (
            ("apt", "/etc/nginx/sites-available/nightcrawler", "ufw", "python3.13 python3.12",
             "certbot python3-certbot-nginx"),
            ("dnf", "/etc/nginx/conf.d/nightcrawler.conf", "firewall-cmd", "python3.13 python3.12 python3",
             "certbot python3-certbot-nginx"),
            ("pacman", "/etc/nginx/conf.d/nightcrawler.conf", "ufw", "python", "certbot certbot-nginx"),
            ("zypper", "/etc/nginx/conf.d/nightcrawler.conf", "firewall-cmd", "python313 python312",
             "certbot python3-certbot-nginx"),
            ("apk", "/etc/nginx/http.d/nightcrawler.conf", "ufw", "python3", "certbot certbot-nginx")):
        aus = _sh("NC_PKG=%s; nc_nginx_ziel; echo; nc_firewall_hinweis 8050; echo; "
                  "nc_paketname python; echo; nc_paketname certbot-nginx" % pkg).split("\n")
        assert aus[0] == nginx, (pkg, aus)
        assert aus[1].startswith(fw) and "8050" in aus[1], (pkg, aus)
        assert aus[2] == py and aus[3] == cert, (pkg, aus)
    # CrowdSec nur dort, wo der Installer die Quelle kennt — sonst leer, und
    # der Installer verweist auf die Doku statt zu raten.
    assert _sh("NC_PKG=dnf; nc_paketname crowdsec") == ""
    assert _sh("NC_PKG=apt; nc_paketname crowdsec") == "crowdsec"
    # Init: ausdruecklich vorgegeben gewinnt; sonst am LAUFENDEN Init.
    assert _sh("NC_INIT=openrc; nc_init_erkennen; printf %s \"$NC_INIT\"") == "openrc"
    assert _sh("NC_OS=Plan9; nc_init_erkennen; printf %s \"$NC_INIT\"") == "keiner"
    assert _sh("NC_OS=Darwin; nc_motd_weg; printf %s \"$NC_MOTD_WEG\"") == "shellrc"
    assert _sh("NC_OS=Plan9; nc_motd_weg; printf %s \"$NC_MOTD_WEG\"") == "keiner"
    # Das venv-Paket ist ein Debian-Sonderfall.
    assert _sh("NC_PKG=apt; nc_venvpaket 3.13") == "python3.13-venv"
    assert _sh("NC_PKG=dnf; nc_venvpaket 3.13") == ""
    ok("W124: lib/system.sh — nginx-Ort, Firewall, Python, certbot je Distribution; Init und MOTD-Weg")


def _test_v42_w124_installer_verdrahtung():
    """v4.2-W124: die Vertraege ueber den Bauplan, die kein Lauf zeigen kann."""
    import ast as _ast
    import subprocess as _sp
    inst = io.open("tools/installer.sh", encoding="utf-8").read()
    r = _sp.run(["bash", "-n", "tools/installer.sh"], capture_output=True, text=True)
    assert r.returncode == 0, r.stderr
    # Die Erkennung kommt aus EINER Bibliothek — zwei Kopien liefen auseinander.
    zeilen = [z.strip() for z in inst.splitlines() if not z.strip().startswith("#")]
    assert any(z.startswith(". ") and "lib/system.sh" in z for z in zeilen), "lib/system.sh nicht gesourct"
    for fn in ("nc_system_erkennen", "nc_init_erkennen", "nc_motd_weg"):
        assert fn in zeilen, "%s wird nicht aufgerufen" % fn
    # Kein Paketname mehr fest im Installer: apt-get install steht nur noch
    # im deadsnakes-Zweig (der IST apt-spezifisch).
    fest = [z for z in zeilen if "apt-get install" in z and "deadsnakes" not in z
            and "python3.12 python3.12-venv" not in z and "software-properties-common" not in z]
    assert not fest, "fester apt-Aufruf ausserhalb des deadsnakes-Zweigs: %r" % fest
    # Systemdateien nur bei Abweichung — alle drei Arten gehen durch dieselbe Funktion.
    for ziel in ('"/etc/systemd/system/${DIENST}.service"', '"/etc/init.d/${DIENST}"', '"$NGX"'):
        assert any(z.startswith(("if schreibe_systemdatei " + ziel, "elif schreibe_systemdatei " + ziel))
                   for z in zeilen), "%s wird nicht ueber schreibe_systemdatei geschrieben" % ziel
    # Ein Zertifikat, das certbot eingetragen hat, wird nicht wieder
    # herausgeschrieben.
    assert "managed by Certbot" in "".join(z for z in zeilen if z.startswith(("if ", "elif ")))
    # https NUR mit Zertifikat (Codex-Befund PR #163): die nginx-Vorlage
    # lauscht allein auf Port 80, eine https-Adresse ohne certbot macht jeden
    # OAuth-Rueckruf zur Adresse, die es nicht gibt.
    https = [z for z in zeilen if z.startswith("env_set PUBLIC_BASE_URL") and "https://" in z]
    if_https = [z for z in zeilen if z.startswith("if ") and 'env_set PUBLIC_BASE_URL "https://' in z]
    assert not https and len(if_https) == 1 and '"$P_CERT" = "J"' in if_https[0], \
        "https-Adresse ohne Zertifikats-Bedingung: %r" % (https or if_https)
    # ... und scheitert certbot, faellt sie auf http zurueck.
    i_rueck = next((n for n, z in enumerate(zeilen) if z.startswith('if [ "$P_CERT" = "J" ] && ! grep -q')), None)
    assert i_rueck is not None and 'env_set PUBLIC_BASE_URL "http://${P_DOMAIN}"' in zeilen[i_rueck:i_rueck + 4], \
        "kein http-Rueckfall nach gescheitertem certbot"
    # Paketquellen ohne passendes Python (Debian 12) enden nicht im Abbruch,
    # sondern im uv-Weg — derselbe, den die Auswahl "uv" nimmt.
    assert sum(1 for z in zeilen if z in ("python_ueber_uv", "python_ueber_uv;;")) >= 2, \
        "uv-Rueckfall fehlt im Paketzweig"
    # Kein automatischer Neustart im unbeaufsichtigten Lauf.
    # Gemessen an Zeilen, die mit dem AUFRUF beginnen — im Zweig steht
    # "restart" auch in der Meldung, die den Befehl zum Selbst-Absetzen nennt
    # (Lehre W102-W104: ein Vertrag darf seinen Text nicht als Befund lesen).
    roh = inst.splitlines()
    i = next(n for n, z in enumerate(roh) if z.strip() == 'if [ "$MODUS" = "unattended" ]; then'
             and 'Dienst %s laeuft' in roh[n + 1])
    zweig = []
    for z in roh[i + 1:]:
        if z.strip().startswith("elif "):
            break
        zweig.append(z.strip())
    assert zweig and not any(z.startswith("dienst_start") for z in zweig), \
        "unbeaufsichtigter Lauf startet einen laufenden Dienst neu: %r" % zweig
    # Windows: dieselbe Token-Regel, frage_wahl, NSSM idempotent.
    bat = open("tools/install.bat", encoding="utf-8").read().replace("\r\n", "\n")
    bz = [z.strip() for z in bat.split("\n") if not z.strip().lower().startswith("rem")]
    i_get = bz.index("call :env_get DASHBOARD_TOKEN")
    i_frage = bz.index('call :frage_geheimnis "Dashboard-Token" 1 40')
    assert i_get < i_frage and bz[i_get + 2] == "if defined ENVWERT goto :token_fertig", bz[i_get:i_frage]
    fw = bz[bz.index(":frage_wahl"):]
    assert fw[1] == 'set "ANTWORT=%~1"' and fw[2] == 'if /i "%MODUS%"=="auto" goto :eof' \
        and fw[3] == 'if /i "%MODUS%"=="express" goto :eof', fw[:4]
    assert 'sc query NIGHTCRAWLER >nul 2>&1 || nssm install NIGHTCRAWLER "%VPY%" "%ZIEL%\\bot.py" >nul' in bz
    assert any(z.startswith("schtasks /create") and "/sc onstart" in z and z.endswith("/f >nul 2>&1")
               for z in bz)
    hinter = [z for z in bz if z.startswith('>>"%ZIEL%\\start-hintergrund.bat"')]
    assert hinter and not any("pause" in z for z in hinter), "Hintergrundstart mit pause"
    # Chocolatey wird nur angeboten — als Administrator und gefuehrt.
    kp = bz[bz.index(":kein_paketweg"):]
    i_ps = next(n for n, z in enumerate(kp) if z.startswith("powershell -NoProfile -ExecutionPolicy"))
    vorher = kp[:i_ps]
    assert 'if not "%ADMIN%"=="1" goto :eof' in vorher and \
        'if /i not "%MODUS%"=="gefuehrt" goto :eof' in vorher and \
        'if /i "%ANTWORT%"=="N" goto :eof' in vorher, vorher
    # Jeder :paket-Aufruf nennt beide Namen.
    for z in bz:
        if z.startswith("call :paket "):
            assert len(z.split()) == 4, z
    del _ast
    ok("W124: Installer-Bauplan — eine Erkennung, Systemdateien nur bei Abweichung, kein "
       "Neustart unbeaufsichtigt; install.bat: Token bleibt, Auswahl, NSSM idempotent")



def _test_v42_w125_sitzung_tonformat():
    """v4.2-W125: eine Sitzung aus Segmenten mit verschiedenem Tonformat.

    Gemeldet: "irgendwas stimmt wieder mit dem Ton nicht". Gemessen: der
    concat-Demuxer nimmt das Tonformat des ERSTEN Segments fuer die ganze
    Datei. 48 kHz mono + 44,1 kHz stereo ergab eine Datei, deren zweite
    Haelfte zu schnell und zu hoch spielte (880 Hz kamen als 958 Hz heraus),
    rc 0, keine Zeile. Seit W106 ist das der Regelfall, nicht die Ausnahme:
    die Stille-Nachruestung schreibt AAC 44,1 kHz stereo, TikTok sendet oft
    48 kHz.
    """
    import json as _json
    import os as _os
    import shutil as _shutil
    import subprocess as _sp
    from nc import aufnahmesitzung as S
    from nc import tonspur as T

    def probe(streams):
        return _json.dumps({"streams": streams})

    v = {"codec_type": "video", "codec_name": "h264"}
    a48 = {"codec_type": "audio", "codec_name": "aac", "profile": "LC", "sample_rate": "48000", "channels": 1}
    a44 = {"codec_type": "audio", "codec_name": "aac", "profile": "LC", "sample_rate": "44100", "channels": 2}
    he44 = dict(a44, profile="HE-AAC")
    assert S.tonformat(probe([v, a48])) == ("aac", "LC", 48000, 1)
    assert S.tonformat(probe([v])) == S.OHNE_TON
    for kaputt in (probe([]), "{}"):
        try:
            S.tonformat(kaputt)
        except ValueError:
            pass
        else:
            raise AssertionError("ein leeres Segment gilt als 'ohne Ton' statt als Befund")
    f48, f44 = S.tonformat(probe([v, a48])), S.tonformat(probe([v, a44]))
    assert not S.braucht_angleich([f48, f48, f48]), "gleiches Format wird umsonst neu kodiert"
    assert not S.braucht_angleich([])
    assert S.braucht_angleich([f48, f44]), "verschiedene Tonformate gehen ungeprueft in -c copy"
    # Gleiche Rate und Kanalzahl, anderes Profil: der Demuxer nimmt die
    # Konfiguration des ersten Segments (Codex-Befund, PR #164).
    assert S.braucht_angleich([S.tonformat(probe([v, he44])), f44]), \
        "HE-AAC und LC gelten als gleich — das Profil fehlt im Schluessel"
    assert "profile" in " ".join(S.probe_cmd("/rec/a.mp4")), "ffprobe fragt das Profil nicht ab"
    assert S.braucht_angleich([f44, S.OHNE_TON]), "ein tonloses Segment geht ungeprueft in -c copy"
    # Auch wenn ALLE tonlos sind: sonst wird eine Sitzung ohne Ton "gleich"
    # befunden und per -c copy zu einer stummen Datei — der Fall, den W106
    # fuer jede einzelne Aufnahme schon ausschliesst.
    assert S.braucht_angleich([S.OHNE_TON, S.OHNE_TON]), "eine ganz tonlose Sitzung bleibt stumm"
    # Der Angleich fasst das Bild nicht an und traegt in BEIDEN Faellen Ton
    # (die Lehre aus W106: jeder ffmpeg-Bauer laeuft durch hat_tonspur).
    for hat in (True, False):
        cmd = S.angleich_cmd("/rec/a.mp4", "/rec/b.mp4", hat)
        assert T.hat_tonspur(cmd), cmd
        i = cmd.index("-c:v")
        assert cmd[i + 1] == "copy", "der Angleich kodiert das Bild neu"
        assert " ".join(T.AAC_ARGS) in " ".join(cmd), "nicht das gemeinsame Zielformat"
    assert "-shortest" in S.angleich_cmd("/rec/a.mp4", "/rec/b.mp4", False), \
        "endlose Stille ohne -shortest — die Datei hoert nie auf"

    if not (_shutil.which("ffmpeg") and _shutil.which("ffprobe")):
        ok("W125: Tonformat-Angleich (rein); ffmpeg fehlt — echter Lauf uebersprungen")
        return

    # ── Der echte Lauf, mit der Eingabe der Produktion: zwei Formate.
    import pruefhilfen as P
    from nc.routes import recordings as rt
    heim = P.verzeichnis()
    segs = []
    for n, (hz, sr, ch) in enumerate(((440, 48000, 1), (880, 44100, 2))):
        p = _os.path.join(heim, "seg%d.mp4" % n)
        _sp.run(["ffmpeg", "-v", "error", "-y", "-f", "lavfi", "-i", "testsrc=size=160x120:rate=25:d=4",
                 "-f", "lavfi", "-i", "sine=frequency=%d:sample_rate=%d:duration=4" % (hz, sr),
                 "-ac", str(ch), "-c:v", "libx264", "-preset", "ultrafast", "-c:a", "aac",
                 "-shortest", p], check=True, capture_output=True)
        segs.append(p)
    ziel = _os.path.join(heim, "sitzung.mp4")
    from nc import ctx as _ncctx
    zeilen = []
    class _Log:
        def _sammle(self, *a, **k):
            zeilen.append(a[0] % a[1:] if len(a) > 1 else str(a[0]))
        warning = info = error = _sammle
        # debug zaehlt nicht: im INFO-Log des Betreibers erscheint es nie.
        def debug(self, *a, **k): pass
    alt_ctx = _ncctx._CTX
    _ncctx.configure(log=_Log(), log_event=lambda *a, **k: None)
    try:
        rt._join_lauf("w125", segs, ziel, None, None)
    finally:
        _ncctx._CTX = alt_ctx
    lage = rt._JOIN_LAGE.pop("w125")
    assert lage["status"] == "fertig", (lage, zeilen)
    assert any("Tonformate unterschiedlich" in z for z in zeilen), \
        "der Angleich laeuft, ohne dass das Log es sagt: %r" % zeilen
    assert not _os.path.exists(ziel + ".angleich"), "die Angleich-Kopien bleiben liegen"

    def dauer(sel):
        r = _sp.run(["ffprobe", "-v", "error", "-select_streams", sel, "-show_entries",
                     "stream=duration", "-of", "csv=p=0", ziel], capture_output=True, text=True)
        return float(r.stdout.strip())
    assert abs(dauer("a:0") - dauer("v:0")) < 0.15, \
        "Ton %.2f s, Bild %.2f s — die Naht verschiebt die Geschwindigkeit" % (dauer("a:0"), dauer("v:0"))
    # Tonhoehe der zweiten Haelfte: Nulldurchgaenge des dekodierten Tons.
    import array as _array
    pcm = _sp.run(["ffmpeg", "-v", "error", "-ss", "5", "-t", "2", "-i", ziel, "-vn", "-ac", "1",
                   "-ar", "44100", "-f", "s16le", "-"], capture_output=True, check=True).stdout
    w = _array.array("h", pcm)
    wechsel = sum(1 for i in range(1, len(w)) if (w[i - 1] < 0) != (w[i] < 0))
    hz = wechsel / 2.0 / (len(w) / 44100.0)
    assert 860 < hz < 900, "zweite Haelfte klingt mit %.0f Hz statt 880 Hz" % hz
    ok("W125: Sitzung aus 48 kHz mono + 44,1 kHz stereo — Tonhoehe und Laenge stimmen")


def _test_v42_w125_deck_ton_zeigt_wahrheit():
    """v4.2-W125: nach dem Neuladen stand "Ton ist an", und nichts piepte.

    `_tonAn` ueberlebt das Neuladen (localStorage), die Erlaubnis des
    Browsers nicht: der neue AudioContext ist ohne Nutzergeste "suspended".
    Im Browser gemessen (Playwright, Autoplay-Sperre): Knopf "🔊 Ton ist an",
    ncPieps('err') -> false. Und ein Klick auf den Knopf schaltete den Ton
    dann AUS — genau als der Betreiber ihn wiederhaben wollte.
    """
    import io as _io
    import json as _json
    deck = _io.open("templates/dashboard.html", encoding="utf-8").read()
    i = deck.index("function _tonBereit(")
    assert "state==='running'" in deck[i:deck.index("\n", i)], "_tonBereit liest nicht den echten Zustand"
    i = deck.index("function ncTonKnopfAuffrischen(")
    auf = deck[i:deck.index("\nasync function ncTonUmschalten(", i)]
    assert "_tonBereit()" in auf, "der Knopf zeigt den Wunsch statt den Zustand"
    for text in ("'🔊 Ton ist an'", "'🔈 Ton wartet auf einen Klick'", "'🔇 Ton aktivieren'"):
        assert text in auf, text
    i = deck.index("async function ncTonUmschalten(")
    um = deck[i:deck.index("\nfunction sseStart(", i)]
    erste = next(z.strip() for z in um.splitlines()[1:] if z.strip() and not z.strip().startswith(("/*", "*", "ihn", "ab,")))
    assert erste.startswith("if(_tonAn && _tonBereit()){"), \
        "ein Klick im Wartezustand schaltet den Ton aus: %s" % erste
    i = deck.index("function _tonBeiGesteFreigeben(")
    geste = deck[i:deck.index("\n}\n", i)]
    assert "closest('[data-ton-knopf]')" in geste, \
        "die Seitengeste gibt vor dem Knopf frei — der Klick schaltet danach aus"
    assert "'pointerdown','keydown'" in geste and "{once" not in geste
    assert "ncTonKnopfAuffrischen(); _tonBeiGesteFreigeben();" in deck, "die Freigabe wird nie eingehaengt"
    i = deck.index("function ncPieps(")
    pieps = deck[i:deck.index("\nfunction ncTonKnopfAuffrischen(", i)]
    zweig = pieps[pieps.index("if(ctx.state!=='running'){"):]
    assert zweig.index("ncTonKnopfAuffrischen()") < zweig.index("return false"), \
        "ein verschluckter Piep laesst den Knopf auf 'an'"
    en = _json.load(_io.open("locales/en.json", encoding="utf-8"))
    flach = en.get("strings", en) if isinstance(en, dict) else {}
    assert "🔈 Ton wartet auf einen Klick" in _json.dumps(flach, ensure_ascii=False)
    ok("W125: der Ton-Knopf zeigt, ob es wirklich piept, und ein Klick gibt frei statt aus")


def _test_v42_w125_azrael_stimme_laut():
    """v4.2-W125: AZRAELs Stimme fehlte im Restream ohne eine Zeile.

    `_restream_tts_enqueue_wav` sah den Rueckgabewert von ffmpeg nie an, und
    alles endete in `except Exception: pass`. Gemessen im Syntaxbaum, nicht
    im Text — der Kommentar zitiert das alte `pass` (Lehre W102-W104).
    """
    import ast as _ast
    import io as _io
    baum = _ast.parse(_io.open("bot.py", encoding="utf-8").read())
    fn = {n.name: n for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
    tts = fn["_restream_tts_enqueue_wav"]
    for h in (n for n in _ast.walk(tts) if isinstance(n, _ast.ExceptHandler)):
        if h.type is not None and _ast.unparse(h.type) == "Exception" and \
                h.lineno == max(x.lineno for x in _ast.walk(tts) if isinstance(x, _ast.ExceptHandler)):
            assert not all(isinstance(s, _ast.Pass) for s in h.body), "aeusserer except ist wieder stumm"
            assert "_azrael_stimme_stumm" in _ast.unparse(h), _ast.unparse(h)
    pruef = [n for n in _ast.walk(tts) if isinstance(n, _ast.If) and "_rc" in _ast.unparse(n.test)]
    assert pruef and any("_azrael_stimme_stumm" in _ast.unparse(n) and
                         any(isinstance(s, _ast.Return) for s in n.body) for n in pruef), \
        "ein gescheitertes ffmpeg wird nicht gemeldet"
    stumm = _ast.unparse(fn["_azrael_stimme_stumm"])
    assert "_nc_meldetakt.melden('azrael-stimme'" in stumm and "log.error(" in stumm, \
        "die Meldung ist nicht gedrosselt oder nicht auf error"
    assert "_nc_meldetakt.zuruecksetzen('azrael-stimme')" in _ast.unparse(tts), \
        "der Erfolgspfad setzt die Drossel nicht zurueck"
    ok("W125: AZRAELs Stimme fehlt nie mehr still im Restream")



def _test_v42_w126_motd_konfigurieren():
    """v4.2-W126: motd.sh --configure — pruefen, vorschauen, nur bei Aenderung schreiben.

    Bis dahin hiess "anpassen": /etc/nightcrawler/motd.conf von Hand bearbeiten
    und beim naechsten Login nachsehen. Ein falscher Wert fiel dabei nicht auf
    (WIDTH=abc rechnet still mit Unsinn), und ob 60 Zeichen aufs Handy passen,
    sah man erst nach dem Abmelden.
    """
    import os as _os
    import subprocess as _sp
    import pruefhilfen as P
    heim = P.verzeichnis()
    bot = _os.path.join(heim, "bot")
    _os.makedirs(bot)
    open(_os.path.join(bot, "bot.py"), "w").close()
    conf = _os.path.join(heim, "motd.conf")
    umg = {k: v for k, v in _os.environ.items()
           if k not in ("SERVICE", "BOT_DIR", "DASH_PORT", "DB", "DISK_TARGET", "WIDTH", "BARW",
                        "SHOW_REC", "REC_CACHE_TTL", "CPU_SAMPLE", "COLOR_MODE", "DEST")}
    umg.update(CONF=conf, BOT_DIR=bot, SERVICE="nc-pruef", COLOR_MODE="off", CPU_SAMPLE="0",
               NC_LANG="de")

    def lauf(*args, eingabe=None, **mehr):
        e = dict(umg, **mehr)
        return _sp.run(["bash", "tools/motd.sh", *args], input=eingabe, capture_output=True,
                       text=True, env=e, timeout=120)

    def werte():
        return [z for z in open(conf, encoding="utf-8").read().splitlines() if not z.startswith("#")]

    def rahmen(text):
        # Die erste Rahmenzeile der MOTD: ihre Laenge IST die Breite.
        return next(len(z) for z in text.splitlines() if z and set(z) == {"━"})

    # (1) Ohne Rueckfrage: schreibt, und zwar die gepruefte Eingabe.
    r = lauf("--configure", "--set", "WIDTH=60", "--set", "BARW=12")
    assert r.returncode == 0, r.stdout + r.stderr
    assert "WIDTH='60'" in werte() and "BARW='12'" in werte(), werte()
    # (2) Idempotent: derselbe Aufruf schreibt nicht noch einmal.
    vorher = _os.stat(conf).st_mtime_ns
    r = lauf("--configure", "--set", "WIDTH=60", "--set", "BARW=12")
    assert r.returncode == 0 and _os.stat(conf).st_mtime_ns == vorher, \
        "unveraenderte Werte werden neu geschrieben"
    # (3) Ungueltiges bricht ab (Exit 2) und laesst die Datei unberuehrt —
    # auch wenn der Wert davor gueltig war: keine halbe Konfiguration.
    for falsch in (["WIDTH=abc"], ["WIDTH=999"], ["BARW=7"], ["COLOR_MODE=farbig"],
                   ["SHOW_REC=2"], ["CPU_SAMPLE=5"], ["DASH_PORT=0"], ["FOO=1"], ["WIDTH"],
                   ["BOT_DIR=" + heim], ["SERVICE=a b"], ["WIDTH=50", "BARW=x"],
                   ["DB=" + _os.path.join(heim, "fehlt.db")], [""]):
        args = []
        for f in falsch:
            args += ["--set", f]
        r = lauf("--configure", *args)
        assert r.returncode == 2, (falsch, r.returncode, r.stdout)
        assert "WIDTH='60'" in werte(), (falsch, werte())
    assert lauf("--configure", "--set", "WIDTH=080").returncode == 0, "fuehrende Null gilt als Oktal"
    assert "WIDTH='080'" in werte()
    # Ein --set ganz ohne Operand ebenso (Codex-Befund, PR #165).
    assert lauf("--configure", "--set").returncode == 2
    # DB ist einstellbar — die falsch erkannte Datenbank ist der Grund dafuer.
    db = _os.path.join(heim, "echt.db")
    open(db, "w").close()
    assert lauf("--configure", "--set", "DB=" + db).returncode == 0 and "DB='%s'" % db in werte()
    lauf("--configure", "--set", "WIDTH=60")
    # (4) --dry-run zeigt, schreibt nicht.
    r = lauf("--configure", "--set", "WIDTH=70", "--dry-run")
    assert r.returncode == 0 and "+ WIDTH='70'" in r.stdout and "- WIDTH='60'" in r.stdout, r.stdout
    assert "WIDTH='60'" in werte()
    # (5) Die gespeicherte Datei WIRKT, und die Umgebung schlaegt sie weiter (W100).
    assert rahmen(lauf().stdout) == 60, "die motd.conf wirkt nicht"
    assert rahmen(lauf(WIDTH="45").stdout) == 45, "die Umgebung schlaegt die Datei nicht mehr"
    # (6) Gefuehrt: ungueltig wird abgewiesen, gueltig sofort in der Vorschau
    # gezeigt — VOR dem Speichern —, dann geschrieben.
    r = lauf("--configure", eingabe="3\n999\n3\n44\ns\n")
    assert r.returncode == 0, r.stdout + r.stderr
    assert "ausserhalb von 40 bis 120" in r.stdout, "999 wurde nicht abgewiesen"
    vor_speichern = r.stdout[:r.stdout.index("Aenderungen an")]
    assert "Vorschau" in vor_speichern and rahmen(vor_speichern.split("Vorschau", 1)[1]) == 44, \
        "die Vorschau zeigt nicht den neuen Wert"
    assert "WIDTH='44'" in werte(), werte()
    # (7) q verwirft.
    vorher = _os.stat(conf).st_mtime_ns
    r = lauf("--configure", eingabe="3\n50\nq\n")
    assert r.returncode == 0 and _os.stat(conf).st_mtime_ns == vorher and "WIDTH='44'" in werte()
    # (8) --install schreibt dieselben Felder wie --configure: sonst loescht
    # der naechste --install still, was --configure gesetzt hat.
    src = open("tools/motd.sh", encoding="utf-8").read()
    zeilen = [z.strip() for z in src.splitlines()]
    i = zeilen.index("write_conf(){ # [$1 = wer schreibt, Vorgabe --install]")
    assert any(z.startswith('konf_inhalt "${1:---install}" >') for z in zeilen[i:i + 8]), \
        "--install schreibt nicht ueber konf_inhalt"
    ok("W126: motd.sh --configure prueft jeden Wert, zeigt ihn sofort und schreibt nur Aenderungen")


# Die langlebigen Maps aus bot._speicher_maps — ein Vertrag haelt beide gleich.
_W144_MAPS = ("live_status_cache", "rate_backoff", "rate_penalty", "ytdlp_ruhe",
              "clip_cooldown", "hype_cooldown", "abo_probe", "abo_live",
              "next_check", "chat_stats")


def _w144_schnappschuss_zusatz():
    """Die W144-Schluessel des Schnappschusses, wie bot._leistung_erheben sie
    baut — mit einem gefuellten Pruefstand, damit jeder Name entsteht (vor
    der ersten Pruefrunde ist er leer)."""
    from nc import kennzahlen as kz
    from nc import laufstand as LS
    from nc import quellstat as QS
    from nc import tunnelwacht as TW
    return {
        "speicher": {k: 0 for k in _W144_MAPS},
        "quellen": QS.lage(),
        "pruefung": {"aktiv": 1, "ueberfaellig": 0, "unbekannt": 0, "ausstehend": 0},
        "zustand": {
            "tunnel": kz.einwertig("ok", (TW.LAGE_OK, TW.LAGE_DIREKT, TW.LAGE_AUS,
                                          TW.LAGE_FEHLER, "unbekannt")),
            "laufstand": kz.einwertig("aktuell", (LS.AKTUELL, LS.VERALTET, LS.UNBEKANNT)),
            "schema_stand": 1, "schema_erwartet": 1, "db_mariadb": 0,
            "loop_stalls": 0, "log_synchron": 0,
        },
    }


def _test_v42_w127_observability():
    """v4.2-W127: Prometheus und Grafana — jede Abfrage trifft einen echten Namen.

    Ein Diagramm oder eine Alarmregel mit einem Namen, den /metrics nicht
    liefert, meldet keinen Fehler — es zeigt "No data" bzw. feuert nie. Die
    erlaubten Namen werden deshalb GEMESSEN: aus den metric()-Aufrufen in
    nc/routes/beobachtung.py und aus dem, was nc.kennzahlen.prometheus() mit
    den echten lage()-Funktionen ausgibt — nicht aus einer Liste hier.
    """
    import ast as _ast
    import json as _json
    import os as _os
    import re as _re
    import shutil as _shutil
    import subprocess as _sp
    import yaml as _yaml
    import pruefhilfen as P
    from nc import (looplag, gegendruck, livecache, kindprozess, speicherpflege,
                    kennzahlen as kz)

    # ── (1) Die Namen, die es wirklich gibt.
    baum = _ast.parse(open("nc/routes/beobachtung.py", encoding="utf-8").read())
    namen = {n.args[0].value for n in _ast.walk(baum)
             if isinstance(n, _ast.Call) and getattr(n.func, "id", "") == "metric"
             and n.args and isinstance(n.args[0], _ast.Constant)}
    assert "nightcrawler_disk_total_bytes" in namen, "Plattengroesse fehlt in /metrics"
    daten = {"loop_lag": looplag.lage(), "gegendruck": gegendruck.lage(1, 4, 0, 10),
             "livecache": livecache.statistik(0, 0), "kinder": kindprozess.lage(),
             "speicher": speicherpflege.groessen({}), "log": {"wartend": 0, "verloren": 0},
             "prozess": kz.prozess(), "betrieb": {"restreams": 0, "chat_clients": 0, "aufnahmen": 0},
             "start_s": 1.0}
    # ANKER GEWANDERT (v4.2-W144, nicht der Vertrag): der Schnappschuss traegt
    # seither auch Quellen, Pruefstand und Zustaende. _w144_schnappschuss baut
    # dieselben Schluessel wie bot._leistung_erheben, und ein Vertrag haelt
    # beide gegeneinander.
    daten.update(_w144_schnappschuss_zusatz())
    namen |= set(_re.findall(r"^(nightcrawler_\w+) ", kz.prometheus(daten, alter_s=1), _re.M))
    namen.add("up")

    def benutzt(expr):
        return set(_re.findall(r"\b(nightcrawler_\w+|up)\b(?=\s*[{\[)\s*/<>=!+*-]|\s*$)", expr))

    regeln = _yaml.safe_load(open("deploy/observability/rules/nightcrawler.yml", encoding="utf-8"))
    ausdruecke = [r["expr"] for g in regeln["groups"] for r in g["rules"]]
    # ANKER GEWANDERT (v4.2-W144): sechs Regeln fuer Pruefstand, Quellen,
    # Tunnel, Update, Schema und Log-Schleuse dazu.
    assert len(ausdruecke) == 16, len(ausdruecke)
    dash = _json.load(open("deploy/observability/grafana/dashboards/nightcrawler.json", encoding="utf-8"))
    ausdruecke += [t["expr"] for p in dash["panels"] for t in p.get("targets", [])]
    for e in ausdruecke:
        fremd = benutzt(e) - namen
        assert not fremd, "Abfrage auf einen Namen, den /metrics nicht liefert: %s in %r" % (fremd, e)
        assert benutzt(e), "kein Messwert erkannt in %r" % e

    # ── (2) Dashboard und Datenquelle passen zusammen.
    ids = [p["id"] for p in dash["panels"]]
    assert len(ids) == len(set(ids)), "doppelte Panel-IDs"
    quelle = _yaml.safe_load(open("deploy/observability/grafana/provisioning/datasources/nightcrawler.yml",
                                  encoding="utf-8"))["datasources"][0]
    for p in dash["panels"]:
        if p["type"] != "row":
            assert p["datasource"]["uid"] == quelle["uid"], p["title"]

    # ── (3) Das Werkzeug: rendert, prueft, schreibt nur Abweichungen.
    heim = P.verzeichnis()
    ziel = _os.path.join(heim, "bot")
    _os.makedirs(ziel)
    _os.symlink(_os.path.abspath("deploy"), _os.path.join(ziel, "deploy"))
    wurzel = _os.path.join(heim, "w")
    fake = _os.path.join(heim, "bin")
    _os.makedirs(fake)
    protokoll = _os.path.join(heim, "systemctl.log")
    with open(_os.path.join(fake, "systemctl"), "w") as f:
        # Mit Zustand: nach "enable --now" ist der Dienst aktiv — sonst saehe
        # der zweite Lauf einen gestoppten Dienst und startete ihn erneut.
        f.write(
            '#!/bin/sh\n'
            'echo "$*" >> "%(log)s"\n'
            '# Zustand JE DIENST: das letzte Argument ist die Unit.\n'
            'eval "u=\\${$#}"\n'
            'case "$1" in\n'
            '  list-unit-files) case "$*" in *grafana-server*)\n'
            '    [ -n "$FAKE_GRAFANA" ] && echo "grafana-server.service enabled";; esac; exit 0;;\n'
            '  enable) touch "%(heim)s/aktiv.$u"; exit 0;;\n'
            '  disable) rm -f "%(heim)s/aktiv.$u"; exit 0;;\n'
            '  is-active) [ -f "%(heim)s/aktiv.$u" ]; exit $?;;\n'
            '  is-enabled) exit 1;;\n'
            'esac\nexit 0\n' % {"log": protokoll, "heim": heim})
    _os.chmod(_os.path.join(fake, "systemctl"), 0o755)
    # Ein Platzhalter-prometheus VOR dem echten im PATH: die Laeufe unten
    # sollen ueberall stattfinden, auch in der CI ohne das Paket — und dort
    # wuerde das Werkzeug sonst versuchen, es per apt zu installieren.
    with open(_os.path.join(fake, "prometheus"), "w") as f:
        f.write("#!/bin/sh\nexit 0\n")
    _os.chmod(_os.path.join(fake, "prometheus"), 0o755)
    umg = dict(_os.environ, PATH=fake + ":" + _os.environ["PATH"], NC_OBS_WURZEL=wurzel,
               NC_INIT="systemd", NC_PKG="apt", NC_OBS_WARTEN="0", NC_LANG="de",
               # Kein sudo: die CI laeuft nicht als root, und sudo setzt den
               # PATH zurueck — dann traefe jeder Aufruf das echte systemctl.
               NC_OBS_SUDO="")

    def lauf(*args, env_datei=None):
        if env_datei is not None:
            open(_os.path.join(ziel, ".env"), "w").write(env_datei)
        return _sp.run(["bash", "tools/observability.sh", "--dir", ziel, "--no-color", *args],
                       capture_output=True, text=True, env=umg, timeout=120)

    def systemctl():
        return open(protokoll).read() if _os.path.exists(protokoll) else ""

    # Ungueltiges bricht ab, bevor irgendetwas geschrieben wird.
    for args, env in ((["--port", "80"], ""), (["--port", "x"], ""), (["--retention", "lang"], ""),
                      ([], "WEB_HOST=10.0.0.5\n"), ([], "DASHBOARD_PORT=abc\n")):
        r = lauf("--unattended", "--no-grafana", *args, env_datei=env)
        assert r.returncode == 2 and not _os.path.exists(wurzel), (args, env, r.stdout + r.stderr)
    # Ohne systemd: nichts einrichten, ehrlich sagen. Mit SAUBERER .env — vom
    # Fall davor lag DASHBOARD_PORT=abc darin, und der Abbruch kam aus DIESEM
    # Grund; die Mutationsprobe auf die systemd-Pruefung entwischte so.
    open(_os.path.join(ziel, ".env"), "w").write("")
    r = _sp.run(["bash", "tools/observability.sh", "--dir", ziel, "--unattended"],
                capture_output=True, text=True, env=dict(umg, NC_INIT="keiner"), timeout=60)
    assert r.returncode == 2 and not _os.path.exists(wurzel), r.stdout + r.stderr
    assert "Ohne systemd" in r.stderr, r.stderr

    # Trockenlauf: zeigt, schreibt nichts, startet nichts.
    r = lauf("--unattended", "--no-grafana", "--dry-run",
             env_datei="DASHBOARD_PORT=8123\nDASHBOARD_TLS_CERT=/x.pem\n")
    assert r.returncode == 0, r.stdout + r.stderr
    assert "neu: /etc/nightcrawler/observability/prometheus.yml" in r.stdout
    assert not _os.path.exists(wurzel) and "enable" not in systemctl(), "Trockenlauf hat geschrieben"
    # Erster echter Lauf: drei Dateien, gerendert, gestartet.
    r = lauf("--unattended", "--no-grafana")
    conf = _os.path.join(wurzel, "etc/nightcrawler/observability/prometheus.yml")
    unit = _os.path.join(wurzel, "etc/systemd/system/nightcrawler-prometheus.service")
    text = open(conf).read() + open(unit).read()
    # Dasselbe Muster wie das Werkzeug — nicht "@@" roh: der Kopf der
    # Vorlage ERKLAERT die @@…@@-Stellen (Lehre W102-W104).
    assert not _re.search(r"@@[A-Z_]+@@", text), "ungerenderter Platzhalter"
    assert '"127.0.0.1:8123"' in text and "scheme: https" in text, "Port/Schema nicht aus der .env"
    # Nur IPv6 (WEB_HOST=::1): Ziel [::1], sonst erreicht Prometheus den
    # Bot nie (Codex, PR #166). Trockenlauf genuegt — es geht ums Rendern.
    r6 = lauf("--unattended", "--no-grafana", "--dry-run", env_datei="WEB_HOST=::1\nDASHBOARD_PORT=8123\n")
    assert r6.returncode == 0 and "://[::1]:8123/metrics" in r6.stdout, r6.stdout
    open(_os.path.join(ziel, ".env"), "w").write("DASHBOARD_PORT=8123\nDASHBOARD_TLS_CERT=/x.pem\n")
    assert "--web.listen-address=127.0.0.1:9099" in text, "Prometheus lauscht nicht nur lokal"
    assert "enable --now nightcrawler-prometheus.service" in systemctl(), systemctl()
    # Zweiter Lauf: nichts schreiben, nichts neu starten.
    vorher = {p: _os.stat(p).st_mtime_ns for p in (conf, unit)}
    _os.remove(protokoll)
    r = lauf("--unattended", "--no-grafana")
    assert {p: _os.stat(p).st_mtime_ns for p in (conf, unit)} == vorher, "zweiter Lauf schreibt"
    nach = systemctl()
    assert not any(w in nach for w in ("enable", "restart", "reload", "daemon-reload")), nach
    # Eine geaenderte Einstellung: nur neu laden, nicht neu starten — die
    # Unit ist unveraendert, also gibt es keine Luecke in den Daten.
    _os.remove(protokoll)
    r = lauf("--unattended", "--no-grafana", env_datei="DASHBOARD_PORT=8124\nDASHBOARD_TLS_CERT=/x.pem\n")
    assert "reload nightcrawler-prometheus.service" in systemctl() and "restart" not in systemctl(), systemctl()
    # Grafana, wenn es da ist: Datenquelle, Dashboard und "nur lokal".
    umg["FAKE_GRAFANA"] = "1"
    r = lauf("--unattended", "--grafana")
    gf = lambda *t: _os.path.join(wurzel, *t)
    q = open(gf("etc/grafana/provisioning/datasources/nightcrawler.yml")).read()
    assert "url: http://127.0.0.1:9099" in q, q
    d = open(gf("etc/grafana/provisioning/dashboards/nightcrawler.yml")).read()
    assert "path: /var/lib/grafana/dashboards/nightcrawler" in d, d
    assert _json.load(open(gf("var/lib/grafana/dashboards/nightcrawler/nightcrawler.json")))["uid"] == "nightcrawler"
    assert "GF_SERVER_HTTP_ADDR=127.0.0.1" in open(
        gf("etc/systemd/system/grafana-server.service.d/nightcrawler.conf")).read()
    del umg["FAKE_GRAFANA"]
    # --check auf dem fertigen Bestand: vollstaendig.
    assert lauf("--check", "--no-grafana").returncode == 0
    # --remove raeumt die eigenen Dateien weg.
    r = lauf("--remove", "--unattended")
    assert r.returncode == 0 and not _os.path.exists(conf) and not _os.path.exists(unit)
    assert "disable --now nightcrawler-prometheus.service" in systemctl()
    assert "restart grafana-server.service" in systemctl(), "Grafana sieht die entfernte Quelle nie"
    assert not _os.path.exists(gf("var/lib/grafana/dashboards/nightcrawler/nightcrawler.json"))
    # Ein zweites --remove: nichts mehr von uns da — dann bleibt ein
    # fremdes Grafana unangetastet.
    _os.remove(protokoll)
    assert lauf("--remove", "--unattended").returncode == 0
    assert "restart" not in systemctl() and "disable" not in systemctl(), systemctl()

    # ── (4) promtool: Konfiguration, Regeln und die Regeltests.
    if _shutil.which("promtool"):
        r = _sp.run(["promtool", "test", "rules", "deploy/observability/rules/nightcrawler.test.yml"],
                    capture_output=True, text=True, timeout=120)
        assert r.returncode == 0 and "SUCCESS" in r.stdout, r.stdout + r.stderr
    else:
        ok("W127: promtool fehlt — Regeltests uebersprungen")

    # ── (5) Der Paket-Dienst wird NUR abgeschaltet, wenn dieser Lauf ihn
    # gebracht hat — und SOFORT nach der Installation, nicht erst am Ende:
    # jeder Abbruch dazwischen liesse *:9090 offen (Codex, PR #166).
    # Gemessen an Zeilen, die mit dem Aufruf beginnen.
    zeilen = [z.strip() for z in open("tools/observability.sh", encoding="utf-8").read().splitlines()]
    i = next(n for n, z in enumerate(zeilen) if z.startswith("dienst disable --now prometheus.service"))
    i_inst = next(n for n, z in enumerate(zeilen)
                  if z.startswith("lauf env DEBIAN_FRONTEND=noninteractive $(nc_installbefehl $PROM_PAKET)"))
    i_erst = next(n for n, z in enumerate(zeilen) if z.startswith('schreibe "$ETC/prometheus.yml"'))
    assert i_inst < i < i_erst, "Paket-Dienst nicht direkt nach der Installation abgeschaltet"
    bedingung = next(z for z in reversed(zeilen[:i]) if z.startswith(("if ", "elif ")))
    assert bedingung.startswith('if [ "$PAKET_DIENST_VORHER" = 0 ]'), bedingung
    # Grafana zaehlt bei --check nur, wenn es LAEUFT.
    umg["FAKE_GRAFANA"] = "1"
    aktiv = _os.path.join(heim, "aktiv.grafana-server.service")
    if _os.path.exists(aktiv):
        _os.remove(aktiv)        # installiert, aber gestoppt
    r = lauf("--check", "--grafana")
    assert r.returncode == 1 and "grafana-server.service laeuft nicht" in r.stdout, r.stdout
    del umg["FAKE_GRAFANA"]

    # ── (6) Ein Werkzeug, drei Wege: update.sh und der Installer rufen es auf.
    up = open("tools/update.sh", encoding="utf-8").read()
    assert 'exec bash "$SKRIPT/observability.sh" "${_w[@]}"' in up
    # Zusammen mit anderen Schaltern: VOR dem ersten vorzeitigen Ausgang, und
    # ihr Ergebnis zaehlt beim Exitcode (EXIT-Falle) — sonst fiel sie bei
    # "nichts zu tun" oder --check still aus (Codex, PR #166).
    uz = [z.strip() for z in up.splitlines()]
    i_obs = uz.index('bash "$SKRIPT/observability.sh" "${_w[@]}" || OBS_RC=$?')
    i_exit = next(n for n, z in enumerate(uz) if z.startswith('exit "$BEFUND"') or z == "exit 1")
    assert i_obs < i_exit, "Beobachtung laeuft erst nach einem vorzeitigen Ausgang"
    assert any(z.startswith("trap '_rc=$?;") and "OBS_RC" in z and z.endswith("' EXIT") for z in uz)
    ins = [z.strip() for z in open("tools/installer.sh", encoding="utf-8").read().splitlines()]
    # "beobachtung" ist ein Punkt — an welcher Stelle, entscheidet W129ff.
    # (Bis W129 stand hier endswith(" beobachtung)"): der Anker brach, als
    # zwei Punkte dahinter kamen, obwohl die Aussage weiter stimmte.)
    assert any(z.startswith("PUNKTE=(") and "beobachtung" in z[len("PUNKTE=("):-1].split() for z in ins)
    assert any(z.startswith('if ${SUDO:+$SUDO} bash "$ZIEL/tools/observability.sh"') for z in ins)
    ok("W127: Prometheus/Grafana — jede Abfrage trifft einen gemessenen Namen, "
       "das Werkzeug schreibt nur Abweichungen, die Alarme feuern im Regeltest")


def _test_v42_w128_env_vorlage_durchleiter():
    """v4.2-W128: Helfer, die ihren Parameter an os.getenv reichen.

    Gemessen am 30.10.: elf solche Durchleiter, bei dreien traf kein Muster
    des Generators (`_env`, `_f`/`_i`, `_b`) — sechzehn Variablen fehlten in
    .env.example, darunter AZRAELs Antwortbremsen und die Wahl des
    Embedding-Backends. Der Generator folgt jetzt dem Sichtbarkeitsbereich.
    """
    import sys as _sys
    _sys.path.insert(0, "tools")
    import gen_env_example as G
    quellen = {
        "nc/a.py": (
            "import os\n"
            "def _env(k, d):\n"
            "    return os.getenv(k, d)\n"
            "def _flag(name):\n"
            "    return os.getenv(name, '0')\n"
            "def lesen():\n"
            "    return _env('EINS_X', 'eins'), _flag('ZWEI_X')\n"
            # Gleichnamige verschachtelte Helfer: der eine reicht einen
            # env-Namen durch, der andere nur einen Wert (nc/cfgnorm.py).
            "def mit_env(saved):\n"
            "    def _i(key, env, default):\n"
            "        return os.getenv(env, default)\n"
            "    return _i('k', 'DREI_X', '3')\n"
            # ... mit einer LOKALEN Variable: wuerde der Aufruf dem falschen _i
            # zugeordnet, waere das eine Luecke (Mutationsprobe W128).
            "def ohne_env(saved):\n"
            "    def _i(key, default):\n"
            "        return int(default)\n"
            "    wert = len(saved)\n"
            "    return _i('k', wert)\n"
            # Ein Modul-Helfer, in einer Funktion von einem gleichnamigen
            # inneren Helfer verdeckt: dessen Aufruf gehoert NICHT zum aeusseren.
            "def verdeckt(saved):\n"
            "    def _env(x):\n"
            "        return x\n"
            "    lokal = saved\n"
            "    return _env(lokal)\n"
            # Kette: ein Durchleiter ruft einen Durchleiter.
            "def huelle(n):\n"
            "    return _env(n, '')\n"
            "def kette():\n"
            "    return huelle('VIER_X')\n"),
        # Aufruf ueber einen Modul-Import aus einer anderen Datei.
        "nc/b.py": (
            "from nc import a as _a\n"
            "from nc.a import _flag as schalter\n"
            "def b():\n"
            "    return _a._env('FUENF_X', '5'), schalter('SIEBEN_X')\n"),
    }
    namen, luecken = G.durchleiter_namen(quellen)
    assert namen == {"EINS_X": "eins", "ZWEI_X": "0", "DREI_X": "3", "VIER_X": "",
                     "FUENF_X": "5", "SIEBEN_X": "0"}, namen
    assert luecken == [], "falsche Luecke (Namensgleichheit statt Sichtbarkeit?): %r" % luecken
    # Ein Aufruf ohne woertlichen Namen ist eine Luecke — die Sperre.
    quellen["nc/c.py"] = ("from nc import a as _a\n"
                          "NAME = 'SECHS_X'\n"
                          "def c():\n"
                          "    return _a._env(NAME, '')\n")
    _, luecken = G.durchleiter_namen(quellen)
    assert [(r, z) for r, z, _w in luecken] == [("nc/c.py", 4)], luecken
    # ... und sie kommt beim Generator an, nicht nur bei der Hilfsfunktion:
    # collect() traegt sie in LUECKEN, und main() bricht darauf ab.
    import os as _os
    import pruefhilfen as P
    wurzel = P.verzeichnis()
    for rel, txt in quellen.items():
        _os.makedirs(_os.path.join(wurzel, _os.path.dirname(rel)), exist_ok=True)
        open(_os.path.join(wurzel, rel), "w").write(txt)
    alt_root, alt_l = G.ROOT, list(G.LUECKEN)
    G.ROOT, G.LUECKEN[:] = wurzel, []
    try:
        G.collect()
        assert any(r == "nc/c.py" for r, _z, _w in G.LUECKEN), G.LUECKEN
    finally:
        G.ROOT = alt_root
        G.LUECKEN[:] = alt_l
    # Und am echten Bestand: die sechzehn stehen in der Vorlage.
    vorlage = open(".env.example", encoding="utf-8").read()
    for name in ("AZRAEL_REPLY_MIN_GAP_S", "AZRAEL_COHOST_PER_15MIN", "BRAIN_EMBED_BACKEND",
                 "BRAIN_EMBED_URL", "HIGHLIGHT_MIN_SCORE", "NEWS_AUTO", "YT_SEND_PER_MIN"):
        assert ("# %s=" % name) in vorlage, name
    assert "# NEWS_AUTO=0" in vorlage, "Vorgabe aus dem Helfer fehlt"
    ok("W128: .env.example — Durchleiter-Helfer nach Sichtbarkeit aufgeloest, 16 Variablen nachgetragen")


def _test_v42_w129_profile():
    """v4.2-W129: Nutzungsprofile, --set und Expertenmodus im Installer.

    Ein Profil darf nur Schalter setzen, die der Bot liest — gemessen gegen
    .env.example, nicht gegen eine Liste hier. Ein Wechsel zwischen Profilen
    endet auf dem gewaehlten Profil, nicht auf einer Mischung aus beiden.
    """
    import glob as _glob
    import re as _re
    import shutil as _sh
    vorlage = open(".env.example", encoding="utf-8").read()
    bekannt = set(_re.findall(r"^#? ?([A-Z][A-Z0-9_]+)=", vorlage, _re.M))
    profile = {}
    for f in sorted(_glob.glob("deploy/profile/*.env")):
        text = open(f, encoding="utf-8").read()
        assert _re.search(r"^# titel: \S", text, _re.M) and _re.search(r"^# beschreibung: \S", text, _re.M), f
        werte = dict(_re.findall(r"^([A-Z][A-Z0-9_]+)=(\S*)", text, _re.M))
        fremd = set(werte) - bekannt
        assert not fremd, "%s setzt Schalter, die der Bot nicht liest: %s" % (f, fremd)
        profile[os.path.basename(f)[:-4]] = werte
    assert set(profile) == {"minimal", "restream", "ki"}, set(profile)
    # Ein Profil teilt sich keinen Schalter mit einem anderen Punkt des
    # Installers — sonst haengt das Ergebnis an der Reihenfolge der Fragen.
    # Gemessen: das Restream-Profil setzte KICK_ENABLED, der Punkt
    # "Restream-Ziele" setzt es je nach Key, und ein Lauf ohne Profil
    # veraenderte danach die .env. ${p}_ENABLED wird fuer die drei Ziele
    # ausgeschrieben, wie die Schleife im Installer es tut.
    inst = open("tools/installer.sh", encoding="utf-8").read()
    rumpf = inst[:inst.index("f_nutzung(){")] + inst[inst.index("z_experte(){"):]
    andere = set(_re.findall(r'env_set "?([A-Z][A-Z0-9_]+)"? ', rumpf))
    for muster in set(_re.findall(r'env_set "\$\{p\}(_[A-Z_]+)"', rumpf)):
        andere |= {z + muster for z in ("KICK", "TWITCH", "YOUTUBE")}
    assert "KICK_ENABLED" in andere and "RESTREAM_SINGLE" in andere, sorted(andere)[:20]
    for name, werte in profile.items():
        assert not (set(werte) & andere), "%s ueberschneidet sich mit dem Installer: %s" % (
            name, set(werte) & andere)
    # Die Auswahl im Installer kennt genau die Dateien — zwei Listen fuer
    # denselben Zweck liefen sonst auseinander (W100).
    wahl = inst[inst.index('frage_wahl P_NUTZUNG "Nutzungsprofil?"'):inst.index("[ \"$P_NUTZUNG\" = \"keins\" ] && return 0")]
    assert set(_re.findall(r"^\s+(\w+)\s+\"", wahl, _re.M)) == set(profile) | {"keins"}, wahl

    # ── Der echte Installer, im Trockenlauf und echt.
    q = _w124_quelle()
    _sh.copytree("deploy/profile", os.path.join(q, "deploy", "profile"))
    _sh.copy(".env.example", os.path.join(q, ".env.example"))
    heim = _ph.verzeichnis()
    ziel = os.path.join(_ph.verzeichnis(), "nc")
    proto = os.path.join(heim, "pip.log")
    open(proto, "w").close()
    rc, aus = _w124_installer(q, ziel, heim, "--dry-run", "-y", "--profile", "minimal",
                              "--set", "WHISPER_MODEL=small")
    assert rc == 0, aus[-2000:]
    assert _re.search(r"^\s+16\s+Nutzungsprofil\s+minimal", aus, _re.M), aus[-1500:]
    assert _re.search(r"^\s+17\s+Einzelwerte\s+1 Wert", aus, _re.M)
    for zeile in ("+RESTREAM_ENABLED=0", "+CLIP_ENABLED=0", "+WHISPER_MODEL=small"):
        assert zeile in aus, zeile
    # Unbekannter Name, kaputtes --set, unbekanntes Profil: Abbruch, nichts geschrieben.
    # "--set WHISPER_MODEL" ohne "=": ein BEKANNTER Name — sonst scheiterte
    # der Fall schon am Namen, und die Pruefung auf "=" bliebe ungeprueft
    # (Mutationsprobe W129). Ohne sie stuende WHISPER_MODEL=WHISPER_MODEL da.
    for falsch in (["--set", "TIPPFEHLER_X=1"], ["--set", "WHISPER_MODEL"], ["--profile", "turbo"]):
        rc, aus = _w124_installer(q, ziel, heim, "--dry-run", "-y", *falsch)
        assert rc == 1 and not os.path.exists(ziel), (falsch, aus[-800:])

    # KI-Profil bzw. --set: faster-whisper wird NICHT ausgelassen, obwohl die
    # Paketfrage vor dem Profil kommt (Codex, PR #168). Beide Wege, weil sie
    # verschiedene Ausgaenge von f_experte nehmen.
    for wege in (["--profile", "ki"], ["--set", "LIVE_REACT_ENABLED=1"]):
        rc, aus = _w124_installer(q, ziel, heim, "--dry-run", "-y", *wege)
        zeile = next(z for z in aus.splitlines() if "Python-Pakete" in z and ("ausgelassen" in z or "alle" in z))
        assert rc == 0 and "faster-whisper" not in zeile, (wege, zeile)
    rc, aus = _w124_installer(q, ziel, heim, "--dry-run", "-y")
    zeile = next(z for z in aus.splitlines() if "Python-Pakete" in z and "ausgelassen" in z)
    assert "faster-whisper" in zeile, "ohne Sprachreaktion bleibt faster-whisper aus: " + zeile
    # Aenderungsschleife auf einer kleinen Maschine: faster-whisper ist dort
    # von sich aus aus; wer in der Zusammenfassung NUR Punkt 16 auf "ki"
    # stellt, bekommt es trotzdem — f_experte laeuft dabei nicht erneut.
    zst = {"summ": 0, "wahl": 0}

    def schleife(text):
        n = text.count("Nummer zum Aendern")
        if n > zst["summ"]:
            zst["summ"] = n
            return ("16" if n == 1 else "") + "\n"
        if zst["summ"] == 1 and zst["wahl"] == 0 and text.rstrip().endswith("]:"):
            zst["wahl"] = 1
            return "4\n"                     # 4) viel KI
        return "\n"
    rc, aus = _w124_pty(["bash", os.path.join(q, "tools", "installer.sh"), "--dry-run",
                         "--no-color", "--skip-system", "--dir", ziel],
                        _w124_umgebung(heim, NC_RAM_MB="2000"), schleife)
    assert rc == 0, aus[-2500:]
    teile = aus.split("Nummer zum Aendern")
    assert len(teile) == 3, "zwei Zusammenfassungen erwartet: %d" % (len(teile) - 1)
    vorher = next(z for z in teile[0].splitlines() if "Python-Pakete" in z)
    nachher = next(z for z in teile[1].splitlines() if "Python-Pakete" in z)
    assert "faster-whisper" in vorher, vorher
    assert "faster-whisper" not in nachher and "viel KI" in teile[1], nachher
    # tf mit einem Text, der mit "--" beginnt: printf haette ihn als Option
    # gelesen, und die Meldung zu einem falschen Schalter fehlte (W129b).
    import subprocess as _sp
    for sh in ("bash", "dash"):
        if _sh.which(sh):
            r = _sp.run([sh, "-c", '. tools/lib/i18n.sh; tf "--set erwartet NAME=WERT: %s" X'],
                        capture_output=True, text=True, env=dict(os.environ, NC_LANG="de"))
            assert r.stdout == "--set erwartet NAME=WERT: X" and not r.stderr, (sh, r.stdout, r.stderr)
    # Ohne Checkout (keine Profile, keine Vorlage): laut abbrechen statt still
    # uebergehen (Codex, PR #168).
    q2 = _w124_quelle()
    os.remove(os.path.join(q2, ".env.example"))
    for falsch, text in ((["--profile", "minimal"], "--profile braucht deploy/profile/"),
                         (["--set", "WHISPER_MODEL=small"], "--set und --expert brauchen .env.example")):
        rc, aus = _w124_installer(q2, ziel, heim, "--dry-run", "-y", *falsch)
        assert rc == 1 and text in aus and not os.path.exists(ziel), (falsch, aus[-600:])

    os.makedirs(ziel)
    _w124_venv(ziel, proto)
    envf = os.path.join(ziel, ".env")

    def werte():
        return dict(_re.findall(r"^([A-Z][A-Z0-9_]+)=(.*)$", open(envf).read(), _re.M))
    rc, aus = _w124_installer(q, ziel, heim, "-y", "--profile", "minimal")
    assert rc == 0, aus[-2000:]
    w = werte()
    for k, v in profile["minimal"].items():
        assert w.get(k) == v, (k, w.get(k), v)
    # Wechsel auf "ki": was nur "minimal" setzte, kommt auf die Vorgabe zurueck.
    rc, aus = _w124_installer(q, ziel, heim, "-y", "--profile", "ki")
    assert rc == 0, aus[-2000:]
    w = werte()
    for k, v in profile["ki"].items():
        assert w.get(k) == v, (k, w.get(k), v)
    vorgabe = lambda k: _re.search(r"^#? ?%s=(.*)$" % k, vorlage, _re.M).group(1)
    for k in set(profile["minimal"]) - set(profile["ki"]):
        assert w.get(k) == vorgabe(k), "%s blieb auf dem alten Profil: %r" % (k, w.get(k))
    # Derselbe Lauf noch einmal: nichts aendert sich.
    vorher = open(envf).read()
    rc, aus = _w124_installer(q, ziel, heim, "-y", "--profile", "ki")
    assert rc == 0 and open(envf).read() == vorher, "zweiter Lauf mit gleichem Profil aendert die .env"
    # Ohne --profile bleibt alles, wie es ist.
    rc, aus = _w124_installer(q, ziel, heim, "-y")
    assert rc == 0 and open(envf).read() == vorher

    # ── update.sh: das KI-Profil braucht faster-whisper — gesagt VOR dem Start.
    d, uziel, uproto, uumg = _w123_sandbox(fehlt=())
    with open(os.path.join(uziel, "requirements.txt"), "a") as f:
        f.write("faster-whisper >= 999   # [optional] Transkription\n")
    envd = os.path.join(uziel, ".env")
    with open(envd, "w") as f:
        f.write("LIVE_REACT_ENABLED=1\n")
    rc, aus = _w123_update(uziel, uumg, "--check", "--python-deps")
    assert rc == 1 and "faster-whisper ist optional, wird hier aber gebraucht: LIVE_REACT_ENABLED=1" in aus, aus
    with open(envd, "w") as f:
        f.write("LIVE_REACT_ENABLED=1\nLIVE_REACT_SPEECH=0\n")
    rc, aus = _w123_update(uziel, uumg, "--check", "--python-deps")
    assert "faster-whisper" not in aus, "ohne Sprachreaktion wird faster-whisper nicht gebraucht"
    # ── Expertenmodus, in einer echten Terminalsitzung: suchen, waehlen,
    # setzen — und ein Geheimnis erscheint in der Trefferliste maskiert.
    ziel2 = os.path.join(_ph.verzeichnis(), "nc")
    schritte = [("Variable oder Stichwort", "BITRATE"), ("Nummer (Enter", "1"),
                ("Neuer Wert", "4321"), ("Variable oder Stichwort", "DASHBOARD_TOKEN"),
                ("Nummer (Enter", ""), ("Variable oder Stichwort", "")]
    stand = {"i": 0, "n": {}}

    def antworten(text):
        if stand["i"] < len(schritte):
            frage, antwort = schritte[stand["i"]]
            # Nur auf eine NEUE Frage antworten: gezaehlt wird, wie oft sie
            # schon im Puffer steht.
            if text.count(frage) > stand["n"].get(frage, 0) and text.rstrip().endswith(
                    ("Stichwort", "neue Suche)", "behalten)")):
                stand["n"][frage] = text.count(frage)
                stand["i"] += 1
                return antwort + "\n"
        return "\n"
    rc, aus = _w124_pty(["bash", os.path.join(q, "tools", "installer.sh"), "--dry-run", "--expert",
                         "--no-color", "--skip-system", "--dir", ziel2],
                        _w124_umgebung(heim), antworten)
    assert rc == 0, aus[-3000:]
    assert stand["i"] == len(schritte), "Expertenmodus nicht durchlaufen: %d/%d\n%s" % (
        stand["i"], len(schritte), aus[-2500:])
    assert _re.search(r"^\s*\+[A-Z_]*BITRATE[A-Z_]*=4321", aus, _re.M), aus[-2000:]
    assert _re.search(r"^\s+17\s+Einzelwerte\s+1 Wert", aus, _re.M)
    zeile = next(z for z in aus.splitlines() if "DASHBOARD_TOKEN" in z and "Vorgabe" in z)
    assert "***" in zeile and not _re.search(r"[A-Za-z0-9]{40}", zeile), zeile
    assert not os.path.exists(ziel2)
    # Die Falle als Klasse: frage_text/frage_wahl schreiben per printf -v in
    # die GENANNTE Variable. Heisst die wie eine ihrer eigenen lokalen, landet
    # die Antwort dort und ist weg. Die lokalen Namen kommen aus den
    # local-Zeilen der beiden Funktionen selbst.
    zeilen = inst.splitlines()
    for fn in ("frage_text", "frage_wahl"):
        i = next(n for n, z in enumerate(zeilen) if z.startswith(fn + "(){"))
        lokale = set()
        for z in zeilen[i:i + 8]:
            if z.strip().startswith("local "):
                lokale |= {w.split("=")[0] for w in z.strip()[6:].split() if not w.startswith("-")}
        assert "a" in lokale, (fn, lokale)
        for z in zeilen:
            w = z.strip().split()
            if len(w) > 1 and w[0] == fn:
                assert w[1] not in lokale, "%s schreibt in ihre eigene lokale Variable: %s" % (fn, z.strip())
    ok("W129: Nutzungsprofile setzen nur echte Schalter, Wechsel endet sauber, --set prueft den Namen, "
       "Expertenmodus sucht und maskiert, update.sh kennt die KI-Pflicht")

def _w130_pes(pid, pts, dts=None, cc=0, rai=False, pusi=True, pcr=None):
    """Ein synthetisches TS-Paket mit PES-Kopf — genug, um die Weiche zu
    pruefen, ohne ffmpeg. Das Format folgt ISO/IEC 13818-1."""
    from nc import sendebruecke as B
    af = b""
    if rai or pcr is not None:
        flags = (0x40 if rai else 0) | (0x10 if pcr is not None else 0)
        body = bytes([flags])
        if pcr is not None:
            pb = bytearray(6)
            pb[0] = (pcr >> 25) & 0xFF; pb[1] = (pcr >> 17) & 0xFF
            pb[2] = (pcr >> 9) & 0xFF; pb[3] = (pcr >> 1) & 0xFF
            pb[4] = ((pcr & 1) << 7) | 0x7E; pb[5] = 0
            body += bytes(pb)
        af = bytes([len(body)]) + body
    kopf = bytearray([0x47, (0x40 if pusi else 0) | ((pid >> 8) & 0x1F), pid & 0xFF,
                      (0x30 if af else 0x10) | (cc & 0x0F)])
    nutz = b""
    if pusi:
        ts = bytearray(10 if dts is not None else 5)
        B._ts_schreiben(ts, 0, pts)
        ts[0] = (ts[0] & 0x0F) | (0x30 if dts is not None else 0x20)
        if dts is not None:
            B._ts_schreiben(ts, 5, dts)
            ts[5] = (ts[5] & 0x0F) | 0x10
        nutz = (b"\x00\x00\x01" + bytes([0xE0 if pid == 0x100 else 0xC0]) + b"\x00\x00"
                + bytes([0x80, 0xC0 if dts is not None else 0x80, len(ts)]) + bytes(ts))
    p = bytes(kopf) + af + nutz
    return p + b"\xff" * (188 - len(p))


def _w130_psi(pid, tabelle):
    """PAT/PMT-Paket mit pointer_field 0. CRC wird nicht geprueft."""
    p = bytes([0x47, 0x40 | (pid >> 8), pid & 0xFF, 0x10, 0x00]) + tabelle
    return p + b"\xff" * (188 - len(p))


def _w130_pat(pmt=0x1000):
    d = bytes([0x00, 0xB0, 13, 0, 1, 0xC1, 0, 0, 0, 1, 0xE0 | (pmt >> 8), pmt & 0xFF]) + b"\0\0\0\0"
    return _w130_psi(0, d)


def _w130_pmt(stroeme, pmt=0x1000):
    es = b"".join(bytes([typ, 0xE0 | (k >> 8), k & 0xFF, 0xF0, 0]) for k, typ in stroeme)
    laenge = 9 + len(es) + 4
    d = bytes([0x02, 0xB0 | (laenge >> 8), laenge & 0xFF, 0, 1, 0xC1, 0, 0,
               0xE1, 0x00, 0xF0, 0]) + es + b"\0\0\0\0"
    return _w130_psi(pmt, d)


def _test_v42_w130_sendebruecke():
    """v4.2-W130: die Verbindung zur Plattform ueberlebt den Quellwechsel.

    Bis hierher zog EIN ffmpeg die Quelle und sendete zugleich. Jede
    abgelaufene TikTok-Adresse (rund alle sechs Minuten) und jeder CDN-
    Haenger beendete den Prozess und mit ihm die RTMP-Verbindung — fuer die
    Plattform ein beendeter Stream, fuer den Zuschauer der Lade-Kreisel.

    Geprueft wird, was die Bruecke verspricht, und zwar an den Stellen, die
    beim Bauen gemessen schiefgingen: Zeitstempel laufen nie rueckwaerts,
    umgeschaltet wird nur am BILD-Keyframe, Ton vor dem Keyframe faellt weg,
    die Quelle legt die Bildgroesse fest, und eine tonlose Quelle wird
    erkannt, obwohl ihr Zubringer stirbt, bevor er eine PMT schreibt.
    """
    import ast as _ast
    import os as _os
    import shutil as _sh
    import time as _t
    import subprocess as _sp
    from nc import sendebruecke as B
    from nc import restreamcfg as C
    from nc import restreamcmd as R
    from nc import tonspur as T

    # ── (1) ZEITSTEMPEL: Lesen und Schreiben sind zueinander invers, ueber
    # die volle 33-Bit-Breite.
    for wert in (0, 1, 90000, (1 << 32) + 12345, (1 << 33) - 1):
        b = bytearray(5); b[0] = 0x20
        B._ts_schreiben(b, 0, wert)
        assert B._ts_lesen(b, 0) == wert, wert
        assert b[0] >> 4 == 0x2, "das PTS/DTS-Kennzeichen wurde ueberschrieben"
        c = bytearray(6); c[4] = 0x7E
        B._pcr_schreiben(c, 0, wert)
        assert B._pcr_lesen(c, 0) == wert and c[4] & 0x7E == 0x7E, wert

    # ── (2) DER UMSCHREIBER. Zwei Abschnitte mit eigener Zeitachse — der
    # zweite beginnt wie jeder frische Zubringer bei ~0.
    U = B.TsUmschreiber()
    U.abschnitt(10 * 90000)
    raus = []
    for i in range(30):
        raus.append(U.paket(_w130_pes(0x100, 900000 + 3000 * i, 900000 + 3000 * i - 3000,
                                      cc=i, rai=(i == 0), pcr=(900000 + 3000 * i - 3000) if i % 10 == 0 else None)))
        raus.append(U.paket(_w130_pes(0x101, 900000 + 2090 * i, cc=i)))
    assert all(r is not None for r in raus)
    erster = B.pes_zeit(raus[0])
    assert erster[1] == 10 * 90000, ("Abschnitt beginnt nicht an der Wanduhr", erster)
    # Zweiter Abschnitt: Wanduhr liegt HINTER dem Ende des ersten -> er muss
    # hinter dem letzten Zeitstempel anschliessen, nie davor.
    letzt = U.letzt
    U.abschnitt(5 * 90000)
    a_vor = U.paket(_w130_pes(0x101, 1400, cc=0))
    assert a_vor is not None or True
    v = U.paket(_w130_pes(0x100, 3000, 0, cc=0, rai=True))
    p2, d2 = B.pes_zeit(v)
    assert B._vor(letzt, d2), ("zweiter Abschnitt faellt hinter den ersten zurueck", letzt, d2)
    # Ton, der vor dem Keyframe des neuen Abschnitts liegt, faellt weg —
    # samt Fortsetzungspaketen. Gemessen: durchgereicht machte er aus 43
    # Tonpaketen je Sekunde 629.
    U2 = B.TsUmschreiber()
    U2.abschnitt(0)
    U2.paket(_w130_pes(0x100, 9000, 6000, rai=True))
    U2.paket(_w130_pes(0x101, 9000))
    U2.abschnitt(0)
    assert U2.paket(_w130_pes(0x100, 3000, 0, rai=True)) is not None
    assert U2.paket(_w130_pes(0x101, 100)) is not None, "Ton nach dem Keyframe wird verworfen"
    U3 = B.TsUmschreiber()
    U3.abschnitt(0)
    U3.paket(_w130_pes(0x101, 50000))
    U3.paket(_w130_pes(0x100, 50000, 47000, rai=True))
    U3.abschnitt(0)
    # Keyframe-DTS 10000 setzt den Versatz (-> 53000); Ton bei 4000 laege
    # damit bei 47000, VOR dem letzten Ton des alten Abschnitts (50000).
    U3.paket(_w130_pes(0x100, 13000, 10000, rai=True))
    assert U3.paket(_w130_pes(0x101, 4000)) is None, "Ton vor dem Keyframe kam durch"
    assert U3.paket(_w130_pes(0x101, 4000, pusi=False)) is None, \
        "Fortsetzung eines verworfenen Tonpakets kam durch"
    assert U3.paket(_w130_pes(0x101, 10000)) is not None, "Ton ab dem Keyframe verworfen"
    # Continuity-Counter: je PID lueckenlos, auch ueber den Wechsel.
    U4 = B.TsUmschreiber()
    cc = []
    for i, roh_cc in enumerate((7, 8, 9, 0, 3, 4)):
        if i == 3:
            U4.abschnitt(90000)
        q = U4.paket(_w130_pes(0x100, 3000 * (i + 1), 3000 * i, cc=roh_cc, rai=True))
        cc.append(q[3] & 0x0F)
    assert cc == [0, 1, 2, 3, 4, 5], cc
    # PCR folgt demselben Versatz wie PTS/DTS.
    U5 = B.TsUmschreiber()
    U5.abschnitt(90000)
    q = U5.paket(_w130_pes(0x100, 6000, 3000, rai=True, pcr=3000))
    assert B._pcr_lesen(q, 6) == B.pes_zeit(q)[1], "PCR laeuft neben DTS her"

    # ── (3) PAT/PMT und das Urteil.
    assert B.pat_pmt_pid(_w130_pat(0x1000)) == 0x1000
    st = B.pmt_stroeme(_w130_pmt([(0x100, B.H264), (0x101, B.AAC_ADTS)]))
    assert st == {0x100: B.H264, 0x101: B.AAC_ADTS}, st
    assert B.pmt_urteil(st) == "ok" and B.video_pid(st) == 0x100
    assert B.pmt_urteil({0x100: B.HEVC, 0x101: B.AAC_ADTS}) == "neukodieren"
    assert B.pmt_urteil({0x100: B.H264}) == "tonlos"
    assert B.video_pid({0x101: B.AAC_ADTS, 0x100: B.HEVC}) == 0x100

    # ── (4) DIE WEICHE, ohne Prozesse.
    lese, schreib = _os.pipe()
    _os.set_blocking(lese, False)
    uhr = [100.0]
    W = B.Bruecke(schreib, [], None, None, name="#v", uhr=lambda: uhr[0],
                  start_warten_s=20.0)

    def gelesen():
        try:
            return len(_os.read(lese, 1 << 20)) // 188
        except BlockingIOError:
            return 0
    for wer in (B.FUELLER, B.QUELLE):
        W.daten(wer, _w130_pat())
        W.daten(wer, _w130_pmt([(0x100, B.H264), (0x101, B.AAC_ADTS)]))
    gelesen()
    # Das Pausenbild kommt anfangs NICHT durch: die Quelle legt die
    # Bildgroesse des Senders fest (gemessen: sonst lief 1080x1920 als
    # 720x1280 hinaus).
    assert not W.daten(B.FUELLER, _w130_pes(0x100, 3000, 0, rai=True)), \
        "Pausenbild vor der Quelle beim Sender"
    W._wuensche(B.QUELLE, "Test")
    # Umgeschaltet wird am BILD-Keyframe, nicht an einem Tonpaket mit RAI.
    assert not W.daten(B.QUELLE, _w130_pes(0x101, 3000, rai=True)), \
        "an einem Tonpaket umgeschaltet — der Sender bekaeme das Bild ab mitten im GOP"
    assert not W.daten(B.QUELLE, _w130_pes(0x100, 6000, 3000, rai=False)), \
        "ohne Keyframe umgeschaltet"
    assert W.daten(B.QUELLE, _w130_pes(0x100, 9000, 6000, rai=True)) and W.aktiv == B.QUELLE
    assert gelesen() == 1
    # Ab jetzt darf das Pausenbild — aber nur auf Wunsch und am Keyframe.
    assert not W.daten(B.FUELLER, _w130_pes(0x100, 3000, 0, rai=True))
    W._fallback("Test")
    assert W.aktiv == "wechsel"
    assert not W.daten(B.QUELLE, _w130_pes(0x100, 12000, 9000)), \
        "nach dem Rueckfall kommt die Quelle weiter durch"
    assert W.daten(B.FUELLER, _w130_pes(0x100, 6000, 3000, rai=True)) and W.aktiv == B.FUELLER
    # Ein Zubringer mit unpassender PMT kommt nie durch.
    W._urteil[B.QUELLE] = "neukodieren"
    W._wuensche(B.QUELLE, "Test")
    assert not W.daten(B.QUELLE, _w130_pes(0x100, 15000, 12000, rai=True))
    # Ohne Quelle laenger als start_warten_s: dann darf das Pausenbild zuerst.
    W2 = B.Bruecke(schreib, [], None, None, name="#w", uhr=lambda: uhr[0],
                   start_warten_s=20.0)
    W2.daten(B.FUELLER, _w130_pat()); W2.daten(B.FUELLER, _w130_pmt([(0x100, B.H264), (0x101, B.AAC_ADTS)]))
    assert not W2.daten(B.FUELLER, _w130_pes(0x100, 3000, 0, rai=True))
    uhr[0] += 21
    assert W2.daten(B.FUELLER, _w130_pes(0x100, 6000, 3000, rai=True)), \
        "ohne Quelle bliebe der Sender ewig ohne Bild"
    gelesen()
    W._schliessen(); W2._fd = None
    _os.close(lese)

    # ── (5) DIE BAUER. Jeder traegt Ton, im selben Format (AAC_ARGS) — ein
    # Mono-Zubringer neben einem Stereo-Pausenbild baute den Tonfilter des
    # Senders an jeder Umschaltung neu auf.
    R.configure(
        cookie_header=lambda: "sid=GEHEIM", pick_pull_proxy=lambda: "",
        restream_overlay_files=lambda rid=None: {}, FFMPEG_THREADS_LIVE=3,
        FFMPEG_THREADS_RELAY=2, RESTREAM_AVATAR="", RESTREAM_BITRATE_K=4500,
        RESTREAM_AVATAR_ALPHA="", RESTREAM_AVATAR_H=170, RESTREAM_AVATAR_LOOP="",
        RESTREAM_CANVAS_H=720, RESTREAM_CANVAS_W=1280, RESTREAM_FONT="",
        RESTREAM_FPS=30, RESTREAM_LOW_LATENCY=True, RESTREAM_OVERLAY=False,
        RESTREAM_OVERLAY_HTML_FPS=1, RESTREAM_RELAY_BITRATE_K=3500,
        RESTREAM_RELAY_PRESET="ultrafast", RESTREAM_X264_PRESET="veryfast",
        RESTREAM_UA="UA/1.0", TTS_CH=2, TTS_SR=44100, TTS_VOICE_GAIN="1.8")
    url = "https://pull.tiktok.com/stage/x.flv"
    z = R.zubringer(url)
    assert z[:z.index("-i")].count("-re") == 1, "Zubringer ohne -re liest HLS im Schwall"
    assert R.quell_eingang(url) == z[z.index("-re") + 1:z.index(url) + 1], \
        "Zubringer und Sender haben verschiedene Eingangshaertung"
    assert z[-3:] == ["-f", "mpegts", "pipe:1"] and z[z.index("-c:v") + 1] == "copy"
    zt = R.zubringer(url, tonlos=True)
    zn = R.zubringer(url, neukodieren=True)
    f = R.fueller()
    for cmd in (z, zt, zn, f):
        assert T.hat_tonspur(cmd), cmd
        assert " ".join(T.AAC_ARGS) in " ".join(cmd), ("anderes Tonformat", cmd)
    assert T.STILLE_QUELLE in zt and "1:a:0" in zt and "-shortest" in zt
    assert zn[zn.index("-c:v") + 1] == "libx264"
    fps = 30
    assert f[f.index("-g") + 1] == str(int(fps * R.BRUECKE_GOP_S)), \
        "Pausenbild-Keyframe seltener — die Weiche wartet laenger auf ihn"
    s_alt = R.build(url, "", "", transcode=True, targets=[("kick", "rtmp://x/app/K")])
    s_neu = R.build("pipe:0", "", "", transcode=True, targets=[("kick", "rtmp://x/app/K")],
                    bruecke=True)
    assert "pipe:0" not in s_alt and "-reconnect" in s_alt
    assert s_neu[s_neu.index("-i") + 1] == "pipe:0" and "-reconnect" not in s_neu
    assert s_neu[s_neu.index("-f") + 1] == "mpegts"
    assert "-reinit_filter" in s_neu and s_neu[s_neu.index("-reinit_filter") + 1] == "0", \
        "ohne -reinit_filter 0 baut ein Groessenwechsel den ganzen Graphen neu — samt Tonfilter"
    assert R.BRUECKE_TON in " ".join(s_neu) and "async=1000" not in R.BRUECKE_TON
    assert T.hat_tonspur(s_neu) and T.STILLE_QUELLE not in s_neu
    assert "sid=GEHEIM" not in " ".join(s_neu), "Sender traegt das Cookie, braucht es nicht"

    # ── (6) DER SCHALTER.
    alt = {k: _os.environ.get(k) for k in ("RESTREAM_BRUECKE", "RESTREAM_BRUECKE_LUECKE_S")}
    try:
        _os.environ.pop("RESTREAM_BRUECKE", None)
        assert C.bruecke(False) == (True, True), "Vorgabe ohne Bruecke"
        assert C.bruecke(False, unabhaengig=True) == (False, False)
        _os.environ["RESTREAM_BRUECKE"] = "0"
        assert C.bruecke(False) == (False, False) and C.bruecke(True) == (False, True)
        _os.environ["RESTREAM_BRUECKE_LUECKE_S"] = "0"
        assert C.bruecke_luecke() == 2.0
        _os.environ["RESTREAM_BRUECKE_LUECKE_S"] = "999"
        assert C.bruecke_luecke() == 30.0
        assert C.bruecke_offline() >= 0
    finally:
        for k, v in alt.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v
    ex = open(".env.example", encoding="utf-8").read()
    for name in ("RESTREAM_BRUECKE", "RESTREAM_BRUECKE_LUECKE_S", "RESTREAM_BRUECKE_OFFLINE_S"):
        assert name + "=" in ex, name

    # ── (7) DIE VERDRAHTUNG im Manager — gemessen im Syntaxbaum.
    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    rm = next(n for n in baum.body if isinstance(n, _ast.ClassDef) and n.name == "RestreamManager")
    meth = {n.name: n for n in rm.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    def aufrufe(fn):
        return [_ast.unparse(c.func) for c in _ast.walk(fn) if isinstance(c, _ast.Call)]
    st_ = meth["start"]
    assert "_nc_bruecke.Bruecke" in aufrufe(st_)
    assert "_nc_rscfg.bruecke" in aufrufe(st_)
    bauer = [c for c in _ast.walk(st_) if isinstance(c, _ast.Call)
             and _ast.unparse(c.func) == "_build_restream_cmd"]
    mit = [c for c in bauer if any(k.arg == "bruecke" for k in c.keywords)]
    assert len(bauer) == 2 and len(mit) == 1, "der tee-Weg baut ohne Bruecke"
    for name in ("_monitor", "stop"):
        assert "self._bruecke_abraeumen" in aufrufe(meth[name]), \
            "%s raeumt die Bruecke nicht ab — Zubringer liefen als Waisen weiter" % name
    assert "asyncio.to_thread" in aufrufe(meth["_bruecke_abraeumen"])
    assert any(isinstance(n, _ast.Dict) and any(isinstance(k, _ast.Constant) and k.value == "bruecke"
                                                for k in n.keys)
               for n in _ast.walk(meth["status"])), "das Deck erfaehrt nichts vom Pausenbild"

    # ── (8) DIE TONLOSE QUELLE: ihr Zubringer stirbt am -map, bevor er eine
    # PMT schreibt. Ein Prozess-Attrappe genuegt — gemessen wird die Wache.
    starts = []

    class _LangsamLeser:
        def __init__(self, text):
            self._z = [text] if text else []

        def readline(self):
            if self._z:
                _t.sleep(0.4)
                return self._z.pop(0)
            return b""

    class _P:
        def __init__(self, cmd, **kw):
            self.cmd = cmd
            starts.append(cmd)
            self.returncode = None if cmd == ["fueller"] else 1
            r, w = _os.pipe()
            _os.close(w)
            self.stdout = _os.fdopen(r, "rb")
            fe = (b"Stream map '0:a:0' matches no streams.\n"
                  if cmd and cmd[0] == "zub" and not cmd[2] else b"")
            # Die Meldung kommt LANGSAM: der Prozess ist schon beendet, wenn
            # der Leser sie abliefert. Genau dieser Wettlauf liess die Wache
            # die tonlose Quelle als tote Edge behandeln; mit einer schnellen
            # Attrappe entwischte die Mutationsprobe dazu.
            self.stderr = _LangsamLeser(fe)

        def poll(self):
            return self.returncode

        def terminate(self):
            self.returncode = -15

        def wait(self, timeout=None):
            return self.returncode
    lese, schreib = _os.pipe()
    W3 = B.Bruecke(schreib, ["fueller"], lambda u, t, n: ["zub", u, t, n],
                   lambda: ("u2", None), erste_url="u1", name="#t",
                   popen=_P, neustart_min_s=0.05, neustart_max_s=0.05)
    W3.start()
    ende = _t.monotonic() + 5
    while _t.monotonic() < ende and not any(c[0] == "zub" and c[2] for c in starts):
        _t.sleep(0.05)
    W3.stop()
    _os.close(lese)
    zubs = [c for c in starts if c[0] == "zub"]
    assert any(c[2] for c in zubs), ("tonlose Quelle nie erkannt", zubs[:4])
    erst = next(c for c in zubs if c[2])
    assert erst[1] == "u1", "fuer die Stille wurde die Adresse neu aufgeloest — 429-Futter"
    ende = _t.monotonic() + 5
    W3b = B.Bruecke(_os.pipe()[1], ["fueller"], lambda u, t, n: ["zub", u, t, n],
                    lambda: ("u2", None), erste_url="u1", name="#t2",
                    popen=_P, neustart_min_s=0.05, neustart_max_s=0.05)
    del starts[:]
    W3b.start()
    while _t.monotonic() < ende and not any(c[:2] == ["zub", "u2"] for c in starts):
        _t.sleep(0.05)
    W3b.stop()
    neu = [c for c in starts if c[:2] == ["zub", "u2"]]
    assert neu and neu[0][2] is False, \
        ("eine neue Adresse erbt die Stille der alten — die Sitzung bliebe stumm", neu[:2])

    # ── (9) DER HAENGER: ein Zubringer, der verstummt, wird nach luecke_s
    # ERSETZT (gemessen: weiterlesen holt die Zeit im Schwall nach und laeuft
    # dann der Uhr voraus), und zwar mit derselben Adresse.
    starts2 = []
    offen = {}

    class _H:
        def __init__(self, cmd, **kw):
            starts2.append(cmd)
            self.cmd, self.returncode = cmd, None
            r, w = _os.pipe()
            self.stdout = _os.fdopen(r, "rb")
            r2, w2 = _os.pipe()
            _os.close(w2)
            self.stderr = _os.fdopen(r2, "rb")
            if cmd[0] == "zub":
                for q in (_w130_pat(), _w130_pmt([(0x100, B.H264), (0x101, B.AAC_ADTS)]),
                          _w130_pes(0x100, 3000, 0, rai=True)):
                    _os.write(w, q)
            offen[id(self)] = w

        def poll(self):
            return self.returncode

        def terminate(self):
            self.returncode = -15
            w = offen.pop(id(self), None)
            if w is not None:
                _os.close(w)

        def wait(self, timeout=None):
            return self.returncode
    lese4, schreib4 = _os.pipe()
    W4 = B.Bruecke(schreib4, ["fueller"], lambda u, t, n: ["zub", u],
                   lambda: ("u-neu", None), erste_url="u1", name="#h",
                   popen=_H, luecke_s=0.3, neustart_min_s=0.05, neustart_max_s=0.05,
                   anlauf_s=5.0)
    W4.start()
    ende = _t.monotonic() + 6
    while _t.monotonic() < ende and len([c for c in starts2 if c[0] == "zub"]) < 2:
        _t.sleep(0.05)
    lage4 = W4.lage()
    W4.stop()
    for w in list(offen.values()):
        _os.close(w)
    _os.close(lese4)
    zubs = [c for c in starts2 if c[0] == "zub"]
    assert len(zubs) >= 2, ("der verstummte Zubringer wurde nicht ersetzt", zubs, lage4)
    assert zubs[1] == ["zub", "u1"], ("Haenger loest neu auf statt die Adresse zu behalten", zubs)
    # Die Quelle war auf Sendung — sonst waere oben die Anlaufzeit (5 s)
    # gemessen worden und nicht die Luecke (0,3 s).
    assert lage4["wechsel"] >= 1, lage4

    # ── (10) HEVC: die PMT sagt „kein H.264" — der Zubringer wird beendet und
    # mit Neukodieren neu gestartet, und zwar mit DERSELBEN Adresse.
    starts5 = []
    offen5 = {}

    class _HEVC(_H):
        def __init__(self, cmd, **kw):
            starts5.append(cmd)
            self.cmd, self.returncode = cmd, None
            r, w = _os.pipe()
            self.stdout = _os.fdopen(r, "rb")
            r2, w2 = _os.pipe()
            _os.close(w2)
            self.stderr = _os.fdopen(r2, "rb")
            if cmd[0] == "zub" and not cmd[2]:
                for q in (_w130_pat(), _w130_pmt([(0x100, B.HEVC), (0x101, B.AAC_ADTS)])):
                    _os.write(w, q)
            offen5[id(self)] = w

        def terminate(self):
            self.returncode = -15
            w = offen5.pop(id(self), None)
            if w is not None:
                _os.close(w)
    lese5, schreib5 = _os.pipe()
    W5 = B.Bruecke(schreib5, ["fueller"], lambda u, t, n: ["zub", u, n],
                   lambda: ("u-neu", None), erste_url="u1", name="#hevc",
                   popen=_HEVC, neustart_min_s=0.05, neustart_max_s=0.05)
    W5.start()
    ende = _t.monotonic() + 5
    while _t.monotonic() < ende and not any(c[0] == "zub" and c[2] for c in starts5):
        _t.sleep(0.05)
    W5.stop()
    for w in list(offen5.values()):
        _os.close(w)
    _os.close(lese5)
    nk = [c for c in starts5 if c[0] == "zub" and c[2]]
    assert nk, ("HEVC-Quelle nie auf Neukodieren umgestellt", starts5[:4])
    assert nk[0][1] == "u1", ("fuers Neukodieren wurde neu aufgeloest", starts5[:4])

    # ── (11) Review #169: Popen scheitert beim Zubringer (fd-/Prozessgrenze).
    # Die Wache darf daran nicht sterben — sonst laeuft das Pausenbild ewig
    # weiter, und niemand versucht die Quelle wieder.
    versuche = []

    class _Zickig(_H):
        def __init__(self, cmd, **kw):
            if cmd[0] == "zub":
                versuche.append(cmd)
                if len(versuche) == 1:
                    raise OSError(24, "Too many open files")
            super().__init__(cmd, **kw)
    del starts2[:]
    lese6, schreib6 = _os.pipe()
    W6 = B.Bruecke(schreib6, ["fueller"], lambda u, t, n: ["zub", u],
                   lambda: ("u-neu", None), erste_url="u1", name="#zickig",
                   popen=_Zickig, neustart_min_s=0.05, neustart_max_s=0.05)
    W6.start()
    ende = _t.monotonic() + 5
    while _t.monotonic() < ende and len(versuche) < 2:
        _t.sleep(0.05)
    W6.stop()
    for w in list(offen.values()):
        _os.close(w)
    offen.clear()
    _os.close(lese6)
    assert len(versuche) >= 2, "nach einem Popen-Fehler versucht die Bruecke es nie wieder"

    # ── (12) Review #169: stop() waehrend die Aufloesung laeuft. Liefert sie
    # danach noch eine Adresse, darf KEIN Zubringer mehr starten — er bliebe
    # als Waise stehen, weil das Aufraeumen schon durch ist.
    import threading as _th
    frei = _th.Event()
    gestoppt = _th.Event()
    starts7 = []

    class _Zaehl(_H):
        def __init__(self, cmd, **kw):
            starts7.append(cmd)
            super().__init__(cmd, **kw)

    def langsam():
        frei.set()
        gestoppt.wait(5)
        return "u-spaet", None
    lese7, schreib7 = _os.pipe()
    W7 = B.Bruecke(schreib7, ["fueller"], lambda u, t, n: ["zub", u], langsam,
                   name="#spaet", popen=_Zaehl)
    W7.start()
    assert frei.wait(5), "die Aufloesung wurde nie gefragt"
    W7.stop()
    gestoppt.set()
    _t.sleep(0.5)
    for w in list(offen.values()):
        _os.close(w)
    offen.clear()
    _os.close(lese7)
    assert not [c for c in starts7 if c[0] == "zub"], \
        "nach stop() startete noch ein Zubringer — eine Waise"

    # ── (13) Die Grenzen der Aufloesung, ohne Threads (uhr von aussen).
    uhr8 = [1000.0]
    antworten = []

    def quelle8():
        a = antworten.pop(0)
        if isinstance(a, Exception):
            raise a
        return a
    W8 = B.Bruecke(None, [], None, quelle8, name="#a", uhr=lambda: uhr8[0],
                   neustart_min_s=0.0, neustart_max_s=0.0, offline_s=60, unklar_s=600)
    antworten[:] = [RuntimeError("Aufloesung kaputt")]
    assert W8._adresse() is None and W8.ende is None, "ein Absturz der Aufloesung beendet die Bruecke"
    W8._tonlos = W8._neukodieren = True
    antworten[:] = [("u-neu", None)]
    assert W8._adresse() == "u-neu"
    assert not W8._tonlos and not W8._neukodieren, "eine neue Adresse erbt die Lehren der alten"
    antworten[:] = [(None, "offline"), (None, "offline")]
    assert W8._adresse() is None and W8.ende is None, "erstes offline beendet sofort"
    uhr8[0] += 61
    assert W8._adresse() is None and W8.ende and "offline" in W8.ende, W8.ende
    W9 = B.Bruecke(None, [], None, lambda: (None, "unknown"), name="#u",
                   uhr=lambda: uhr8[0], neustart_min_s=0.0, neustart_max_s=0.0,
                   unklar_s=600)
    assert W9._adresse() is None and W9.ende is None
    uhr8[0] += 601
    assert W9._adresse() is None and W9.ende and "keine abspielbare Quelle" in W9.ende, \
        "ohne Grenze stuende das Pausenbild ewig, waehrend TikTok blockt"

    # ── (14) Der Sender ist weg: die Weiche merkt es am Schreiben.
    lese10, schreib10 = _os.pipe()
    W10 = B.Bruecke(schreib10, [], None, None, name="#tot")
    W10.daten(B.FUELLER, _w130_pat())
    W10.daten(B.FUELLER, _w130_pmt([(0x100, B.H264), (0x101, B.AAC_ADTS)]))
    W10._fueller_frei = True
    _os.close(lese10)
    assert not W10.daten(B.FUELLER, _w130_pes(0x100, 3000, 0, rai=True))
    assert W10.ende and "Sender" in W10.ende and W10._halt.is_set()
    W10._schliessen()

    # ── (15) Der Leser richtet sich am Sync-Byte aus — die Pipe zerteilt
    # Pakete beliebig, und ein Rest wird beim naechsten Lesen angesetzt.
    pakete = [_w130_pat(), _w130_pmt([(0x100, B.H264), (0x101, B.AAC_ADTS)])] + \
        [_w130_pes(0x100, 3000 * (i + 1), 3000 * i, rai=(i == 0)) for i in range(4)]
    strom = b"\x00\x13" + b"".join(pakete)
    stuecke = [strom[:100], strom[100:500], strom[500:777], strom[777:]]

    class _Strom:
        def read1(self, n):
            return stuecke.pop(0) if stuecke else b""
        read = read1
    gesehen = []
    W11 = B.Bruecke(None, [], None, None, name="#lies")
    W11.daten = lambda wer, p: gesehen.append(bytes(p))
    W11._lies(B.QUELLE, type("P", (), {"stdout": _Strom()})())
    assert gesehen == pakete, ("Pakete beim Lesen zerteilt oder verschoben", len(gesehen))

    # ── (16) Was KEIN Treffer ist, muss als solcher erkannt werden — sonst
    # liest der Parser Zeitstempel oder Stroeme aus beliebigen Nutzdaten.
    ohne_start = _w130_pes(0x100, 3000, pusi=False)
    assert B.pes_zeit(ohne_start) == (None, None)
    kein_pes = bytes([0x47, 0x41, 0x00, 0x10]) + b"\xab" * 184
    assert B.pes_zeit(kein_pes) == (None, None), "Nutzdaten ohne PES-Kopf als Zeitstempel gelesen"
    assert B._abschnitt_daten(ohne_start) is None
    assert B.pat_pmt_pid(_w130_pmt([(0x100, B.H264)])) is None, "PMT als PAT gelesen"
    assert B.pmt_stroeme(_w130_pat()) is None, "PAT als PMT gelesen"
    assert B.pat_pmt_pid(_w130_psi(0, bytes([0x00, 0xB0, 13, 0, 1, 0xC1, 0, 0, 0, 0, 0xE0, 0x10]) + b"\0" * 4)) is None, \
        "Programm 0 (Netzwerk-PID) als PMT genommen"
    assert B.video_pid({0x101: B.AAC_ADTS}) is None
    W12 = B.Bruecke(None, [], None, None, name="#zu")
    W12._fueller_frei = True
    assert W12.daten(B.FUELLER, _w130_pes(0x100, 3000, 0, rai=True)) is False, \
        "nach dem Schliessen wird noch geschrieben"
    voll = bytes([0x47, 0x40, 0x00, 0x30, 183]) + b"\x00" * 183   # Anpassungsfeld fuellt alles
    assert B._abschnitt_daten(voll) is None and B.pes_zeit(voll) == (None, None)
    # Die Weiche reicht ein verworfenes Paket nicht an den Sender weiter.
    lese15, schreib15 = _os.pipe()
    _os.set_blocking(lese15, False)
    W15 = B.Bruecke(schreib15, [], None, None, name="#verwurf")
    W15._fueller_frei = True
    assert W15.daten(B.FUELLER, _w130_pes(0x101, 90000))
    assert W15.daten(B.FUELLER, _w130_pes(0x101, 1000)) is False, \
        "ein rueckwaerts laufendes Tonpaket ging an den Sender"
    assert len(_os.read(lese15, 4096)) == 188
    W15._schliessen(); _os.close(lese15)

    # ── (17) Aufraeumen und Lesefehler: still im Ergebnis, laut im Log.
    class _Stur:
        returncode = None
        getoetet = False

        def poll(self):
            return None

        def terminate(self):
            pass

        def wait(self, timeout=None):
            raise _sp.TimeoutExpired("ffmpeg", timeout)

        def kill(self):
            self.getoetet = True
    stur = _Stur()
    B.Bruecke._beende(stur)
    assert stur.getoetet, "ein Prozess, der SIGTERM ignoriert, bleibt stehen"

    class _Weg(_Stur):
        def terminate(self):
            raise ProcessLookupError(3, "No such process")
    B.Bruecke._beende(_Weg())                      # darf nicht werfen
    W13 = B.Bruecke(None, [], None, None, name="#fehler")

    class _Kaputt:
        def readline(self, *_):
            raise OSError(9, "Bad file descriptor")
        read1 = read = readline
    W13._stderr(B.QUELLE, type("P", (), {"stderr": _Kaputt()})())
    W13._lies(B.QUELLE, type("P", (), {"stdout": _Kaputt()})())
    r13, w13 = _os.pipe()
    _os.close(w13)
    W13._fd = w13                                  # schon zu
    W13._schliessen()                              # darf nicht werfen
    _os.close(r13)
    # Die Wache endet, wenn die Bruecke aufgibt, und schliesst den Sender-Eingang.
    lese14, schreib14 = _os.pipe()
    folge14 = [(None, "unknown"), (None, "offline")]
    W14 = B.Bruecke(schreib14, [], None, lambda: folge14.pop(0) if folge14 else (None, "offline"),
                    name="#ende", offline_s=0, neustart_min_s=0.0, neustart_max_s=0.0)
    W14._wache()
    assert W14.ende and W14._fd is None, "die Wache laeuft nach dem Aufgeben weiter"
    assert _os.read(lese14, 10) == b"", "der Sender bekommt kein EOF"
    _os.close(lese14)

    if not (_sh.which("ffmpeg") and _sh.which("ffprobe")):
        ok("W130: Sendebruecke (rein); ffmpeg fehlt — echter Lauf uebersprungen")
        return
    _w130_echter_lauf(R)
    ok("W130: Sendebruecke — eine Verbindung ueber zwei Quellwechsel, "
       "Zeitstempel monoton, Ton lueckenlos, Groesse von der Quelle")


def _w130_echter_lauf(R):
    """Echter ffmpeg: lokaler RTMP-Empfaenger, zwei HTTP-FLV-Quellen, die
    nach 3 s abbrechen wie eine abgelaufene TikTok-Adresse — die erste
    1080x1920 mit Mono-Ton in 48 kHz, also genau nicht das Zielformat."""
    import collections as _col
    import os as _os
    import socket as _so
    import subprocess as _sp
    import time as _t
    import pruefhilfen as P
    from nc import sendebruecke as B

    def frei():
        s = _so.socket(); s.bind(("127.0.0.1", 0)); p = s.getsockname()[1]; s.close()
        return p
    heim = P.verzeichnis()
    aus = _os.path.join(heim, "senke.flv")
    senke_url = "rtmp://127.0.0.1:%d/live/k" % frei()
    senke = _sp.Popen(["ffmpeg", "-v", "error", "-y", "-listen", "1", "-i", senke_url,
                       "-c", "copy", "-f", "flv", aus], stdin=_sp.DEVNULL)
    _t.sleep(0.8)
    lese, schreib = _os.pipe()
    sender = _sp.Popen(R.build("pipe:0", "", "", transcode=True, rid=1,
                               targets=[("kick", senke_url)], bruecke=True),
                       stdin=lese, stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
    _os.close(lese)
    quellen = []

    def quelle():
        port = frei()
        groesse = "1080x1920" if not quellen else "720x1280"
        quellen.append(_sp.Popen(
            ["ffmpeg", "-v", "error", "-re", "-f", "lavfi", "-i", "testsrc2=s=%s:r=30" % groesse,
             "-f", "lavfi", "-i", "sine=r=48000:f=440", "-t", "3", "-ac", "1",
             "-c:v", "libx264", "-preset", "ultrafast", "-g", "30", "-c:a", "aac",
             "-f", "flv", "-listen", "1", "http://127.0.0.1:%d/l.flv" % port],
            stdin=_sp.DEVNULL))
        _t.sleep(0.4)
        return "http://127.0.0.1:%d/l.flv" % port, None
    br = B.Bruecke(schreib, R.fueller(), R.zubringer, quelle, erste_url=quelle()[0],
                   luecke_s=3.0, name="#vertrag")
    try:
        br.start()
        _t.sleep(11)
        lage = br.lage()
    finally:
        br.stop()
        for p in [sender, senke] + quellen:
            try:
                p.wait(timeout=15)
            except _sp.TimeoutExpired:
                p.kill(); p.wait()
    assert senke.returncode == 0 and sender.returncode == 0, (senke.returncode, sender.returncode)
    assert lage["wechsel"] >= 3, ("kein Quellwechsel im Lauf", lage)

    def pakete(sel):
        r = _sp.run(["ffprobe", "-v", "error", "-select_streams", sel, "-show_entries",
                     "packet=pts_time,flags", "-of", "csv=p=0", aus],
                    capture_output=True, text=True, timeout=30)
        z = [l.strip(",").split(",") for l in r.stdout.split()]
        return [(float(a[0]), "K" in (a[1] if len(a) > 1 else "")) for a in z
                if a and a[0] not in ("", "N/A")]
    v, a = pakete("v:0"), pakete("a:0")
    vt, at = [x[0] for x in v], [x[0] for x in a]
    # Eine Verbindung, lueckenlos ueber zwei Quellwechsel: das ist die Aussage.
    assert vt[-1] - vt[0] > 8, ("Empfaenger bekam zu wenig — Verbindung abgerissen?", vt[-1])
    assert not [b - x for x, b in zip(vt, vt[1:]) if b - x > 0.2 or b < x], "Bildluecke"
    assert not [b - x for x, b in zip(at, at[1:]) if b - x > 0.2 or b < x], "Tonluecke"
    # 44100/1024 = 43 Tonpakete je Sekunde. Der gemessene Fehlerfall waren 629.
    je_s = _col.Counter(int(x) for x in at)
    assert max(je_s.values()) <= 50, ("Tonschwall an einer Umschaltung", je_s.most_common(3))
    kf = [x[0] for x in v if x[1]]
    assert max(b - x for x, b in zip(kf, kf[1:])) <= 2.1, "Keyframe-Abstand ueber 2 s"
    r = _sp.run(["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries",
                 "stream=width,height", "-of", "csv=p=0", aus], capture_output=True, text=True)
    assert r.stdout.strip().startswith("1080,1920"), \
        ("das Pausenbild hat die Bildgroesse festgelegt", r.stdout)


def _test_v42_w131_aufnahme_haenger():
    """v4.2-W131: eine haengende Aufnahme wird nach 25 s erkannt, nicht nach 45-105 s.

    Gemessen, nicht geschaetzt: eine GESUNDE Aufnahme (fragmentiertes MP4,
    2-s-Fragmente) waechst bei FLV spaetestens alle ~2 s, bei HLS spaetestens
    nach einer Segmentlaenge. Der alte Aufschlag „I/O-Pausen beim Flushen des
    MP4-Containers" passt zu einem wachsenden moov, nicht zu diesem Format.
    """
    import ast as _ast
    import shutil as _sh
    from nc import aufnahmefolge as F
    from nc import reccmd as RC

    # ── (1) Die Grenze.
    assert F.stall_grenze(0) == 25 and F.STALL_TAKT_S <= 5
    assert F.stall_grenze(500 * 1024 * 1024) == 35
    assert F.stall_grenze(10 * 1024 ** 3) == F.STALL_MAX_S == 40, "Deckel fehlt"
    assert F.stall_grenze(0, "3") == 10, "eine Grenze unter einem HLS-Segment schiesst gesunde Aufnahmen ab"
    assert F.stall_grenze(0, "60") == 60, "REC_STALL_S wird nicht beachtet"
    for kaputt in ("", "  ", "abc", "2.5"):
        assert F.stall_grenze(0, kaputt) == F.STALL_BASIS_S, \
            ("REC_STALL_S=%r laesst den Waechter sterben (Review #170)" % kaputt)
    # Schlimmster Fall bis zum Abschuss: Grenze + ein Takt. Vorher 90 + 15.
    assert F.stall_grenze(10 * 1024 ** 3) + F.STALL_TAKT_S <= 45

    # ── (2) ffmpeg meldet sich VOR dem Waechter (B56): sonst stirbt die
    # Aufnahme mit leerem stderr, und niemand sieht die Ursache.
    alt = (RC._cookie_header, RC._pick_pull_proxy)
    RC._cookie_header, RC._pick_pull_proxy = (lambda: ""), (lambda: None)
    try:
        for url in ("https://pull.tiktok.com/x.m3u8", "https://pull.tiktok.com/x.flv"):
            c = RC._build_native_cmd(url, "/rec/a.mp4", 60)
            rw = int(c[c.index("-rw_timeout") + 1]) / 1e6
            assert rw < F.stall_grenze(0), ("rw_timeout nicht unter der Waechtergrenze", rw)
    finally:
        RC._cookie_header, RC._pick_pull_proxy = alt

    # ── (3) Die Verdrahtung im Waechter und im Neustart — im Syntaxbaum.
    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    hrf = next(n for n in baum.body if isinstance(n, _ast.AsyncFunctionDef)
               and n.name == "handle_recording_finished")
    wd = next(n for n in _ast.walk(hrf) if isinstance(n, _ast.AsyncFunctionDef)
              and n.name == "_stall_watchdog")
    rufe = [_ast.unparse(c.func) for c in _ast.walk(wd) if isinstance(c, _ast.Call)]
    assert rufe.count("_nc_folge.stall_grenze") >= 2, "Grenze nicht aus aufnahmefolge"
    zuw = {_ast.unparse(z.targets[0]): _ast.unparse(z.value) for z in _ast.walk(wd)
           if isinstance(z, _ast.Assign) and len(z.targets) == 1}
    assert zuw.get("CHECK_EVERY") == "_nc_folge.STALL_TAKT_S", zuw.get("CHECK_EVERY")
    assert "BASE_STALL" not in zuw and "MAX_STALL" not in zuw, "alte Grenze steht noch"
    sofort = [i for i in _ast.walk(hrf) if isinstance(i, _ast.If)
              and any(_ast.unparse(z.targets[0]) == "_NEXT_CHECK_AT[tid]"
                      and _ast.unparse(z.value) == "0"
                      for z in _ast.walk(i) if isinstance(z, _ast.Assign))]
    assert any("stall_killed[0]" in _ast.unparse(i.test) for i in sofort), \
        "nach einem Haenger mit Daten wartet der Neustart wieder das regulaere Intervall ab"
    assert "REC_STALL_S=" in open(".env.example", encoding="utf-8").read()

    if not (_sh.which("ffmpeg")):
        ok("W131: Haenger-Grenze (rein); ffmpeg fehlt — Messung uebersprungen")
        return
    _w131_gesund_misst(RC, F)
    ok("W131: Aufnahme-Haenger nach %d s statt bis 105 s; gesunde Aufnahme "
       "schweigt gemessen weit kuerzer" % F.stall_grenze(0))


def _w131_gesund_misst(RC, F):
    """Die Messung hinter der Grenze, als Vertrag: eine gesunde HLS-Aufnahme
    mit 4-s-Segmenten (der echte Bauer) schweigt nie laenger als die halbe
    Grenze. Faellt das, ist die Grenze zu knapp — nicht der Vertrag."""
    import os as _os
    import socket as _so
    import subprocess as _sp
    import sys as _sys
    import time as _t
    import pruefhilfen as P
    heim = P.verzeichnis()
    s = _so.socket(); s.bind(("127.0.0.1", 0)); port = s.getsockname()[1]; s.close()
    q = _sp.Popen(["ffmpeg", "-v", "error", "-re", "-f", "lavfi", "-i", "testsrc2=s=320x568:r=30",
                   "-f", "lavfi", "-i", "sine=r=44100", "-t", "30", "-c:v", "libx264",
                   "-preset", "ultrafast", "-g", "120", "-c:a", "aac", "-f", "hls",
                   "-hls_time", "4", "-hls_list_size", "6", _os.path.join(heim, "l.m3u8")],
                  stdin=_sp.DEVNULL)
    srv = _sp.Popen([_sys.executable, "-m", "http.server", str(port), "--bind", "127.0.0.1"],
                    cwd=heim, stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
    alt = (RC._cookie_header, RC._pick_pull_proxy)
    RC._cookie_header, RC._pick_pull_proxy = (lambda: ""), (lambda: None)
    aus = _os.path.join(heim, "a.mp4")
    try:
        _t.sleep(9)
        p = _sp.Popen(RC._build_native_cmd("http://127.0.0.1:%d/l.m3u8" % port, aus, 14),
                      stdin=_sp.DEVNULL, stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
        t0 = _t.monotonic(); last = -1; seit = t0; laengste = 0.0
        while p.poll() is None and _t.monotonic() - t0 < 25:
            g = _os.path.getsize(aus) if _os.path.exists(aus) else 0
            jetzt = _t.monotonic()
            if g != last:
                if last > 0:
                    laengste = max(laengste, jetzt - seit)
                last, seit = g, jetzt
            _t.sleep(0.2)
        p.kill(); p.wait()
    finally:
        RC._cookie_header, RC._pick_pull_proxy = alt
        for x in (q, srv):
            x.kill(); x.wait()
    assert last > 0, "die Messaufnahme hat nichts geschrieben"
    assert laengste < F.stall_grenze(0) / 2, \
        ("gesunde Aufnahme schwieg %.1f s — die Grenze ist zu knapp" % laengste)


def _test_v42_w131_aufnahme_luecken():
    """v4.2-W131: zwei Wege, auf denen Aufnahme verloren ging, ohne dass etwas
    abstuerzte.

    (1) Die Sperre „eine Aufnahme je Tracking" gab erst das finally von
    handle_recording_finished frei — NACH Tonpruefung, Datenbank und dem
    Telegram-Upload an alle Chats. Bis dahin endete jeder Neustart mit „Lock
    nicht bekommen … Skip.", bei jedem geplanten URL-Schnitt und nach jedem
    Haenger. (2) „Reste aufraeumen" hielt die LAUFENDE Aufnahme fuer verwaist:
    sie hat erst nach dem Ende eine Zeile in `recordings`.
    """
    import ast as _ast
    import os as _os
    import time as _t
    from nc import ctx as _ncctx
    from nc.routes import recordings as rt
    import pruefhilfen as P

    # ── (1) Die Reihenfolge in handle_recording_finished — im Syntaxbaum.
    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    hrf = next(n for n in baum.body if isinstance(n, _ast.AsyncFunctionDef)
               and n.name == "handle_recording_finished")

    def zeilen(name):
        return sorted(c.lineno for c in _ast.walk(hrf) if isinstance(c, _ast.Call)
                      and _ast.unparse(c.func).split(".")[-1] == name)
    frei = zeilen("_aufnahme_platz_frei")
    assert frei, "die Sperre wird erst im finally frei — nach dem Upload"
    # ANKER GEWANDERT (v4.2-W158): `sichern` laeuft im benannten Schritt
    # _aufnahme_fertigmachen (Tonspur, dann Chat einbrennen). Gerade das
    # Einbrennen dauert — der Platz muss davor frei sein.
    # ANKER GEWANDERT (v4.2-W175): der Upload laeuft in _aufnahme_verteilen.
    for spaeter in ("_aufnahme_fertigmachen", "add_recording", "_aufnahme_verteilen"):
        assert zeilen(spaeter) and frei[0] < zeilen(spaeter)[0], \
            "Sperre wird erst nach %s frei" % spaeter
    kommunikation = zeilen("communicate")
    assert kommunikation and max(kommunikation) < frei[0], \
        "Sperre frei, bevor ffmpeg beendet ist — zwei Aufnahmen desselben Streams"
    # Das finally darf die Sperre nicht ein zweites Mal raeumen: inzwischen
    # kann dieselbe Tracking-ID die NAECHSTE Aufnahme halten.
    fin = [t for t in _ast.walk(hrf) if isinstance(t, _ast.Try) and t.finalbody]
    rufe_fin = [(c, i) for t in fin for i in t.finalbody for c in _ast.walk(i)
                if isinstance(c, _ast.Call) and _ast.unparse(c.func) == "clear_recording"]
    assert rufe_fin, "clear_recording fehlt im finally — Fehlerpfade gaeben die Sperre nie frei"
    for _c, stmt in rufe_fin:
        assert isinstance(stmt, _ast.If) and "platz_frei" in _ast.unparse(stmt.test), \
            "clear_recording im finally ungeschuetzt — nimmt der Folgeaufnahme die Sperre"
    pf = next(n for n in baum.body if isinstance(n, _ast.AsyncFunctionDef)
              and n.name == "_aufnahme_platz_frei")
    assert "asyncio.to_thread(clear_recording, tid)" in _ast.unparse(pf), \
        "Datenbankzugriff auf dem Loop (W117)"
    assert "active_processes.remove" in _ast.unparse(pf), \
        "der beendete Prozess zaehlt weiter gegen den Aufnahme-Deckel"

    # ── (2) Aufraeumen trifft keine laufende und keine frische Aufnahme.
    heim = P.verzeichnis()
    auf = _os.path.join(heim, "aufnahmen")
    _os.makedirs(auf)
    laeuft = P.attrappe(_os.path.join(auf, "laeuft.mp4"), 4096)
    P.attrappe(_os.path.join(auf, "frisch.mp4"), 4096)
    alt = P.attrappe(_os.path.join(auf, "alt.mp4"), 4096)
    bekannt = P.attrappe(_os.path.join(auf, "bekannt.mp4"), 4096)
    vorher = _t.time() - rt.FRISCH_S - 60
    for pfad in (laeuft, alt, bekannt):
        _os.utime(pfad, (vorher, vorher))

    class _Zeilen(list):
        def fetchall(self): return self

    # Relativ in der Datenbank, absolut im Scan — dieselbe Falle wie W98.
    _rel = _os.path.relpath(laeuft)

    class _Conn:
        def execute(self, sql, args=()):
            if "trackings" in sql:
                assert "recording=1" in sql.replace(" ", "")
                return _Zeilen([{"output_file": _rel}, {"output_file": None}])
            return _Zeilen([{"filepath": _os.path.relpath(bekannt)}, {"filepath": None}])
        def __enter__(self): return self
        def __exit__(self, *a): return False

    alt_ctx = _ncctx._CTX
    echt_db = rt.db_conn
    _ncctx.configure(recordings_dir=auf, log=type("L", (), {"warning": print, "info": print,
                                                           "error": print, "debug": print})(),
                     log_event=lambda *a, **k: None, arg_int=lambda *a, **k: 0,
                     ffmpeg_threads_bg=1, ffmpeg_nice_bg=10)
    try:
        rt.db_conn = lambda: _Conn()
        namen = {o["name"] for o in rt._find_orphans()}
        assert rt._frisch(_os.path.join(auf, "gibt_es_nicht.mp4")), \
            "eine nicht lesbare Datei gilt als loeschbar"
    finally:
        rt.db_conn = echt_db
        _ncctx._CTX = alt_ctx
    assert "laeuft.mp4" not in namen, "die laufende Aufnahme gilt als verwaist und wuerde geloescht"
    assert "frisch.mp4" not in namen, \
        "eine eben beendete, noch nicht eingetragene Aufnahme gilt als verwaist"
    assert "bekannt.mp4" not in namen, "relativer Datenbankpfad gegen absoluten Scan verglichen"
    assert namen == {"alt.mp4"}, ("die echte Waise wird nicht mehr gefunden", namen)
    ok("W131: Aufnahme-Sperre frei nach Prozessende, nicht nach dem Upload; "
       "Aufraeumen schont laufende und frische Aufnahmen")


def _test_v42_w132_versandziel_und_doppelstart():
    """v4.2-W132: Befunde aus dem Log vom 30.10. — Versand an eine Discord-Guild,
    Doppelstart eines Restreams, Wettlauf im Lagebild.

    Die Discord-Guild 1521964594653036677 stand als Tracking-"Gruppe" in der
    Datenbank, und jede Aufnahme wurde erst vollstaendig zerlegt, bevor
    Telegram 'chat not found' sagte. Restream #5 startete zweimal binnen zwei
    Sekunden und sendete zweimal auf denselben Kick-Key.
    """
    import ast as _ast
    import asyncio as _aio
    import tempfile as _tf
    import types as _ty
    from nc import telegramfehler as TF
    from nc import restream_util as RU

    # ── (1) Telegram-ID oder nicht — die Grenze aus der Bot-API (52 Bit).
    for gut in (6999266953, -1002058519599, "-100123", "@kanal", (1 << 52) - 1):
        assert TF.ist_telegram_chat(gut), gut
    for schlecht in (1521964594653036677, 1 << 52, 0, None, True, "", "@",
                     "abc", "12a", 1.5, "١٢٣"):
        assert not TF.ist_telegram_chat(schlecht), schlecht

    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    tot = next(n for n in baum.body if isinstance(n, _ast.FunctionDef)
               and n.name == "_is_dead")
    erste = tot.body[0]
    assert isinstance(erste, _ast.If) and "ist_telegram_chat" in _ast.unparse(erste.test), \
        "_is_dead fragt nicht zuerst, ob das ueberhaupt ein Telegram-Chat ist"

    # ── (2) Ein gesperrter Chat kostet kein Zerlegen. Die Attrappe fuer
    # videoteil wirft bei JEDEM Zugriff — auch dem auf die Groessengrenze.
    # telegram gestubbt wie in _test_v42_w19_versandweg (Begruendung dort).
    import sys as _sys
    if "telegram" not in _sys.modules:
        _tg = _ty.ModuleType("telegram")
        _err = _ty.ModuleType("telegram.error")
        _con = _ty.ModuleType("telegram.constants")
        for _n in ("TelegramError",):
            setattr(_err, _n, type(_n, (Exception,), {}))
        # ANKER GEWANDERT (v4.2-W175): telegramversand faengt ChatMigrated.
        for _n in ("BadRequest", "ChatMigrated", "Forbidden", "NetworkError", "RetryAfter"):
            setattr(_err, _n, type(_n, (_err.TelegramError,), {}))
        _con.ParseMode = _ty.SimpleNamespace(HTML="HTML")
        _sys.modules.update({"telegram": _tg, "telegram.error": _err,
                             "telegram.constants": _con})
    import telegramversand as _tv

    class _Verboten:
        def __getattr__(self, name):
            raise AssertionError("videoteil.%s vor der Sperrpruefung benutzt" % name)

    texte = []

    async def _safe_send(bot, chat_id, text, **kw):
        texte.append(text)
        return False

    async def _ensure_topic(*a):
        raise AssertionError("Forum-Thema fuer einen gesperrten Chat angelegt")

    alt_vt = _tv._nc_videoteil
    # ANKER GEWANDERT (v4.2-W175): sechster Pflicht-Helfer chat_migriert.
    async def _chat_migriert(alt, neu):
        raise AssertionError("ein gesperrter Chat wurde migriert")
    _tv.konfiguriere(chat_migriert=_chat_migriert,
                     ensure_topic=_ensure_topic, is_dead=lambda c: True,
                     mark_dead=lambda c: None, safe_send=_safe_send,
                     topic_forget=lambda c, u: None)
    _tv._nc_videoteil = _Verboten()
    try:
        with _tf.TemporaryDirectory() as d:
            gross = os.path.join(d, "gross.mp4")
            _ph.attrappe(gross, 1500 * 1024 * 1024)
            _aio.run(_tv.split_and_send_video(1521964594653036677, gross,
                                              _ty.SimpleNamespace(bot=None), "x"))
            assert os.path.exists(gross), "die Aufnahme ist weg"
    finally:
        _tv._nc_videoteil = alt_vt
    assert texte and "gesperrt" in texte[0] and "TELEGRAM_CHAT_ID" in texte[0], texte

    # ── (3) Ein Start je Ziel. Der zweite Aufruf kommt, waehrend der erste
    # noch auf die Quelle wartet — genau die Luecke vom 30.10.
    class _Mgr:
        def __init__(self):
            self._procs = {}
            self.laeufe = 0

        @RU.ein_start_je_ziel
        async def start(self, rid, _attempts=0):
            self.laeufe += 1
            await self.tor.wait()
            self._procs[rid] = {"proc": 1}
            RU.freigeben(self, rid)
            await self.nach.wait()          # Aufraeumen nach dem Spawn
            return {"ok": True}

    async def _ablauf():
        m = _Mgr()
        m.tor, m.nach = _aio.Event(), _aio.Event()
        erst = _aio.ensure_future(m.start(5))
        await _aio.sleep(0)
        assert 5 in RU.startend(m), "laufender Start nicht vermerkt"
        zweit = await m.start(5)
        assert zweit.get("already") and m.laeufe == 1, (zweit, m.laeufe)
        anderes = _aio.ensure_future(m.start(7))   # anderes Ziel: frei
        await _aio.sleep(0)
        assert m.laeufe == 2, "die Sperre gilt fuer alle Ziele statt je Ziel"
        m.tor.set()
        await _aio.sleep(0)
        await _aio.sleep(0)
        # Prozess steht, erster Start raeumt noch auf: ein Wiederanlauf
        # darf jetzt nicht an der Startsperre haengen.
        assert 5 not in RU.startend(m), "Sperre haelt ueber den Spawn hinaus"
        m._procs.pop(5)
        m.tor = _aio.Event()
        dritt = _aio.ensure_future(m.start(5))
        await _aio.sleep(0)
        assert m.laeufe == 3, "Wiederanlauf blockiert"
        m.tor.set()
        m.nach.set()
        await _aio.gather(erst, anderes, dritt)
        assert RU.startend(m) == {}, RU.startend(m)
        # Eine Ausnahme im Start gibt die Sperre ebenfalls frei.
        class _Kaputt(_Mgr):
            @RU.ein_start_je_ziel
            async def start(self, rid):
                raise RuntimeError("boom")
        k = _Kaputt()
        try:
            await k.start(1)
        except RuntimeError:
            pass
        else:
            raise AssertionError("Ausnahme verschluckt")
        assert RU.startend(k) == {}, "Sperre bleibt nach Ausnahme stehen"
    _aio.run(_ablauf())

    rm = next(n for n in baum.body if isinstance(n, _ast.ClassDef)
              and n.name == "RestreamManager")
    st = next(n for n in rm.body if isinstance(n, _ast.AsyncFunctionDef)
              and n.name == "start")
    assert any("ein_start_je_ziel" in _ast.unparse(d) for d in st.decorator_list), \
        "RestreamManager.start ist nicht gegen den Doppelstart gesperrt"
    rufe = [_ast.unparse(c) for c in _ast.walk(st) if isinstance(c, _ast.Call)]
    assert any(r.startswith("_nc_rutil.freigeben(self, rid)") for r in rufe), \
        "die Sperre wird nach dem Spawn nicht geloest"
    status = next(n for n in rm.body if isinstance(n, _ast.FunctionDef)
                  and n.name == "status")
    schleifen = [_ast.unparse(f.iter) for f in _ast.walk(status)
                 if isinstance(f, (_ast.For, _ast.comprehension))]
    assert "list(self._procs.items())" in schleifen, \
        "status() iteriert _procs ohne Kopie (Flask-Thread gegen Event-Loop)"
    ok("W132: keine Uploads an Nicht-Telegram-IDs, kein Zerlegen fuer gesperrte "
       "Chats, ein Start je Restream-Ziel")


def _test_v42_w132_log_und_geheimnisse():
    """v4.2-W132: Bot-Token aus dem Log, zwei Logger hinter die Schleuse,
    Cookie-Leser haelt den letzten Stand, Redis-Passwort maskiert."""
    import logging as _lg
    import queue as _q
    import sys as _sys
    import tempfile as _tf
    from nc import logschleuse as L
    from nc import cookies as C
    from nc.proxyutil import _tunnel_mask

    # ── (1) Token geschwaerzt — in der Nachricht UND im Traceback.
    # Zur Laufzeit gebaut: als Literal traefe der Geheimnis-Scanner der CI
    # ("Kein Geheimnis im Diff") genau diese Attrappe — zu Recht.
    tok = "1234567890:" + "AA" + "Falsch" * 5 + "_00"
    zeile = "POST https://api.telegram.org/bot%s/getUpdates" % tok
    assert tok not in L.schwaerzen(zeile) and "bot1234567890:" in L.schwaerzen(zeile)
    for harmlos in ("22:17:23,069 | INFO", "Room-ID 7702564757634681633", ""):
        assert L.schwaerzen(harmlos) == harmlos
    try:
        raise ValueError("Fehler bei " + zeile)
    except ValueError:
        info = _sys.exc_info()
    rec = _lg.LogRecord("httpx", _lg.ERROR, __file__, 1, "Anfrage %s",
                        (zeile,), info)
    fertig = L.Schleuse(_q.Queue()).prepare(rec)
    assert tok not in fertig.getMessage(), "Token steht noch in der Zeile"
    assert "ValueError" in fertig.getMessage(), "Traceback verloren"
    from nc import logfilters as LF
    import collections as _co
    LF.configure_logfilters(_co.deque(maxlen=5))
    LF._DiscordErrorHandler().emit(_lg.LogRecord(
        "x", _lg.ERROR, __file__, 1, zeile, None, None))
    assert tok not in LF._DC_ERR_QUEUE[-1]["msg"], "Token geht nach Discord"

    # ── (2) Konsolen-Handler der genannten Logger wandern hinter die
    # Schleuse; eine Datei bleibt, ein fremder Logger bleibt unberuehrt.
    name, fremd = "w132_probe", "w132_fremd"
    lg, lf = _lg.getLogger(name), _lg.getLogger(fremd)
    konsole = _lg.StreamHandler(_sys.stderr)
    with _tf.TemporaryDirectory() as d:
        datei = _lg.FileHandler(os.path.join(d, "x.log"), delay=True)
        lg.addHandler(konsole)
        lg.addHandler(datei)
        lg.propagate = False
        fh = _lg.StreamHandler(_sys.stderr)
        lf.addHandler(fh)
        lf.propagate = False
        alt = L._HORCHER[0]
        try:
            L._HORCHER[0] = None
            assert L.einreihen((name,)) == 0 and konsole in lg.handlers, \
                "ohne Schleuse umgehaengt — der Gewinn waere null"
            L._HORCHER[0] = object()
            assert L.einreihen((name, "w132_gibtsnicht")) == 1
            assert konsole not in lg.handlers and datei in lg.handlers
            assert lg.propagate is True
            assert fh in lf.handlers and lf.propagate is False
            assert L.einreihen((name,)) == 0, "zweiter Lauf haengt erneut um"
        finally:
            L._HORCHER[0] = alt
            for h in (konsole, datei):
                lg.removeHandler(h)
            lf.removeHandler(fh)
            datei.close()
    assert set(L.EINREIHEN) == {"TikTokLive", "huggingface_hub"}

    # ── (3) Der Cookie-Leser verliert seinen Stand nicht, wenn yt-dlp die
    # Datei gerade neu schreibt.
    alt_konf = dict(C._KONF)
    alt_cache = dict(C._COOKIES_CACHE)
    with _tf.TemporaryDirectory() as d:
        pfad = os.path.join(d, "c.txt")
        with open(pfad, "w", encoding="utf-8") as f:
            f.write("# Netscape HTTP Cookie File\n"
                    ".tiktok.com\tTRUE\t/\tTRUE\t0\tsessionid\tabc\n")
        try:
            C.configure(datei=pfad, log=_lg.getLogger("w132_cookies"))
            C._COOKIES_CACHE.clear()
            assert C.load_dict() == {"sessionid": "abc"}
            with open(pfad, "w", encoding="utf-8") as f:
                f.write("")                     # yt-dlp hat gerade gekuerzt
            st = os.stat(pfad)
            os.utime(pfad, (st.st_atime, st.st_mtime + 5))
            assert C.load_dict() == {"sessionid": "abc"}, \
                "eine halb geschriebene Datei loescht die Cookies"
            C._COOKIES_CACHE.clear()
            assert C.load_dict() == {}, "ohne Vorstand darf nichts erfunden werden"
        finally:
            C._KONF.clear()
            C._KONF.update(alt_konf)
            C._COOKIES_CACHE.clear()
            C._COOKIES_CACHE.update(alt_cache)

    # ── (4) Redis-Form ohne Benutzer: das Passwort verschwindet.
    assert "geheim" not in _tunnel_mask("redis://:geheim@localhost:6379/0")
    assert _tunnel_mask("redis://localhost:6379/0") == "redis://localhost:6379/0"
    assert "pw" not in _tunnel_mask("http://nutzer:pw@h:8118")
    ok("W132: Bot-Token geschwaerzt, TikTokLive/huggingface_hub hinter der "
       "Schleuse, Cookie-Stand ueberlebt den yt-dlp-Rueckschrieb, Redis maskiert")


def _test_v42_w133_kickchat_und_abbau():
    """v4.2-W133: Befunde aus dem Log vom 31.10.

    Der Kick-Chat baute knapp jede Sekunde neu auf (11975-mal in 3,5 h), weil
    ein ordentlich geschlossener Websocket keine Ausnahme warf. Und der Abbau
    hing neun Minuten an einem Arbeiter-Thread in urlopen, waehrend der
    Loop-Waechter einen eingefrorenen Loop meldete.
    """
    import ast as _ast
    import threading as _th
    from nc import kickapi as FG
    from nc import betriebslage as BL

    # ── (1) Das stille Ende hat einen Namen.
    assert FG.pusher_fehler({"event": "pusher:error",
                             "data": {"code": 4200, "message": "reconnect"}}) == "4200 reconnect"
    assert FG.pusher_fehler({"event": "pusher:error",
                             "data": '{"code":4001,"message":"App key x"}'}) == "4001 App key x"
    assert FG.pusher_fehler({"event": "pusher:error", "data": "roh"}) == "roh"
    assert FG.pusher_fehler({"event": "pusher:error"}) == "pusher:error ohne Text"
    for kein in ({"event": "App\\Events\\ChatMessageEvent"}, None, "x", {}):
        assert FG.pusher_fehler(kein) == "", kein
    assert "1000" in FG.schliessgrund(1000) and "unbekannt" in FG.schliessgrund(None)
    assert "4200 x" in FG.schliessgrund(1000, "4200 x")

    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    km = next(n for n in baum.body if isinstance(n, _ast.ClassDef)
              and n.name == "KickModerator")
    ws = next(n for n in km.body if isinstance(n, _ast.AsyncFunctionDef)
              and n.name == "_ws_loop")
    mit = next(n for n in _ast.walk(ws) if isinstance(n, _ast.AsyncWith))
    folge = [type(n).__name__ for n in mit.body]
    i_for = folge.index("AsyncFor")
    nach = mit.body[i_for + 1:]
    assert any(isinstance(n, _ast.If) and "self.running" in _ast.unparse(n.test)
               and any(isinstance(r, _ast.Raise) and "schliessgrund" in _ast.unparse(r)
                       for r in _ast.walk(n)) for n in nach), \
        "ein ordentlich geschlossener Kick-Websocket baut wieder ohne Pause neu auf"
    assert "pusher_fehler" in _ast.unparse(mit), "pusher:error wird nicht gelesen"

    # ── (2) Die Abschiedswache: beendet mit dem vorgesehenen Code, nennt die
    # haengenden Threads und tut nichts, wenn sie abgeschaltet ist.
    tor = _th.Event()
    haenger = _th.Thread(target=tor.wait, name="w133_haenger")   # nicht-Daemon
    geist = _th.Thread(target=tor.wait, name="w133_daemon", daemon=True)
    haenger.start()
    geist.start()
    try:
        assert "w133_haenger" in BL.haengende_threads()
        assert "w133_daemon" not in BL.haengende_threads(), \
            "ein Daemon haelt das Beenden nicht auf und gehoert nicht in die Meldung"
        ende, texte, schlaf = [], [], []
        t = BL.abschiedswache(4, 7.0, ende.append, melden=texte.append,
                              schlafen=schlaf.append)
        t.join(5)
        assert schlaf == [7.0] and ende == [4], (schlaf, ende)
        assert texte and "w133_haenger" in texte[0] and "Exitcode 4" in texte[0], texte
        assert "abschiedswache" not in texte[0], "die Wache nennt sich selbst"
        ende.clear()
        assert BL.abschiedswache(0, 0, ende.append) is None and ende == []
    finally:
        tor.set()
        haenger.join(5)
        geist.join(5)
    assert "w133_haenger" not in BL.haengende_threads()

    hauptf = next(n for n in baum.body if isinstance(n, _ast.AsyncFunctionDef)
                  and n.name == "main")
    # Zeilennummern, nicht ast.walk: das liefert Breitensuche, nicht die
    # Reihenfolge im Quelltext.
    zeile = {}
    for c in _ast.walk(hauptf):
        if isinstance(c, _ast.Call):
            zeile.setdefault(_ast.unparse(c.func), c.lineno)
    assert "_abschied_wachen" in zeile and zeile["_aufraeumen"] < \
        zeile["_abschied_wachen"] < zeile["_abschluss"], \
        "die Wache steht nicht zwischen Aufraeumen und Abschluss"
    aw = next(n for n in baum.body if isinstance(n, _ast.FunctionDef)
              and n.name == "_abschied_wachen")
    assert "4 if fatal is not None else 0" in _ast.unparse(aw), \
        "die Wache macht aus einem gestorbenen Telegram-Teil ein sauberes Ende (W100)"
    wd = next(n for n in baum.body if isinstance(n, _ast.FunctionDef)
              and n.name == "_loop_watchdog_thread")
    assert any(isinstance(n, _ast.If) and "_IM_ABBAU" in _ast.unparse(n.test)
               for n in _ast.walk(wd)), "Loop-Waechter meldet das Ende als Stillstand"
    ok("W133: Kick-Chat baut nach ordentlichem Ende mit Backoff neu auf; ein "
       "haengender Arbeiter haelt den Abbau nicht mehr fest")


def _test_v42_w133_drossel_und_loop():
    """v4.2-W133: CrowdSec gedrosselt, Scanner-505 kein ERROR, drei
    Plattenzugriffe neben dem Loop, eine beschaedigte brain.db laut."""
    import ast as _ast
    import logging as _lg
    from nc import logfilters as LF

    baum = _ast.parse(open("bot.py", encoding="utf-8").read())

    def _fn(name):
        return next(n for n in baum.body if isinstance(n, (_ast.FunctionDef,
                    _ast.AsyncFunctionDef)) and n.name == name)

    cs = _ast.unparse(_fn("_crowdsec_status"))
    assert "_nc_meldetakt.melden('crowdsec'" in cs, "CrowdSec-Warnung ungedrosselt"
    assert cs.count("_nc_meldetakt.zuruecksetzen('crowdsec')") == 2, \
        "der Erfolgspfad (LAPI und cscli) setzt die Drossel nicht zurueck"

    rec = _lg.LogRecord("werkzeug", _lg.ERROR, __file__, 1,
                        "code 505, message Invalid HTTP version (2.0)", None, None)
    LF._WerkzeugScannerFilter().filter(rec)
    assert rec.levelno == _lg.DEBUG, "ein HTTP/2-Scanner steht weiter im Fehlerlog"

    for fn, ziel in (("_piper_say", "_piper_pick_model"),
                     ("_stats_loop", "_nc_usage.flush"),
                     ("_stats_loop", "_nc_usage.configure"),
                     # ANKER GEWANDERT (v4.2-W175): das Einreihen steht in den
                     # benannten Schritten des Uploads.
                     ("_aufnahme_verteilen", "_upload_queue_add"),
                     ("_upload_rest_sichern", "_upload_queue_add")):
        rufe = [c for c in _ast.walk(_fn(fn)) if isinstance(c, _ast.Call)]
        im_thread = [c for c in rufe if _ast.unparse(c.func) == "asyncio.to_thread"
                     and c.args and _ast.unparse(c.args[0]) == ziel]
        direkt = [c for c in rufe if _ast.unparse(c.func) == ziel]
        assert im_thread and not direkt, "%s ruft %s auf dem Loop" % (fn, ziel)

    sb = _ast.unparse(_fn("_system_backup"))
    assert "brain.db ist beschaedigt" in sb and "'.recover'" in sb, \
        "eine beschaedigte brain.db steht weiter nur als Warnung im Log"
    ok("W133: CrowdSec gedrosselt, Scanner-505 auf DEBUG, Piper/Usage/"
       "Upload-Warteschlange neben dem Loop, brain.db-Schaden laut")


def _test_v42_w135_lockfile_gegen_untergrenzen():
    """v4.2-W135: das Lockfile vom Server und die Untergrenzen werden
    verglichen. Am 31.10. fehlte waitress auf dem Server ganz, und W134 hatte
    acht Grenzen angehoben — ohne Abgleich faellt beides niemandem auf."""
    import sys as _sys
    import tempfile as _tf
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import abhaengigkeiten as A

    assert A._fassung("3.14.5") > A._fassung("3.14.4")
    assert A._fassung("3.14.10") > A._fassung("3.14.9"), "Text- statt Zahlenvergleich"
    assert A._fassung("2.9.0.post0") == (2, 9, 0)
    assert A._fassung("2.0.0b7") == (2, 0, 0)
    assert A._norm("PyMySQL") == A._norm("pymysql") == "pymysql"
    assert A._norm("websockets_proxy") == A._norm("websockets-proxy")
    assert A._norm("python_dotenv") == A._norm("Python.Dotenv")

    with _tf.TemporaryDirectory() as d:
        req, lock = os.path.join(d, "r.txt"), os.path.join(d, "l.txt")
        with open(req, "w", encoding="utf-8") as f:
            f.write("# Kopf\n"
                    "Flask >= 3.1.3   # Dashboard\n"
                    "aiohttp >= 3.14.4\n"
                    "waitress >= 3.0.1\n"
                    "PyMySQL >= 1.1.1  # [optional] nur bei MariaDB\n"
                    "uvloop >= 0.19; sys_platform != \"win32\"\n"
                    "python_dotenv >= 1.2.2\n")
        with open(lock, "w", encoding="utf-8") as f:
            f.write("Flask==3.1.3\naiohttp==3.14.1\npython-dotenv==1.2.10\n")
        befund = {n: (lage, g, ist) for n, lage, g, ist in A.lock_abgleich(req, lock)}
    assert befund.get("aiohttp") == ("unter_grenze", "3.14.4", "3.14.1"), befund
    assert befund.get("waitress") == ("fehlt", "3.0.1", ""), befund
    assert "flask" not in befund, "gleiche Fassung gilt als zu alt"
    assert "python-dotenv" not in befund, "1.2.10 wurde textuell unter 1.2.2 einsortiert"
    assert "pymysql" not in befund and "uvloop" not in befund, \
        "optionale Pakete und solche mit Umgebungsmarke sind kein Befund"
    assert set(befund) == {"aiohttp", "waitress"}, befund
    ok("W135: Lockfile gegen Untergrenzen — zu alt und fehlend erkannt, "
       "optional und Umgebungsmarke ausgenommen")


def _test_v42_w136_pusher_protokoll():
    """v4.2-W136: der Kick-Chat behandelt Pusher-Schliesscodes nach Protokoll.

    Am 31.10. antwortete Pusher mit 4001 ("App key not in this cluster"), und
    die Schleife versuchte es alle zehn Sekunden erneut — 250 Warnungen in
    46 Minuten, der Kick-Chat lief nie.
    """
    import ast as _ast
    import sys as _sys
    from nc import kickapi as K

    # ── (1) Lage und Pause nach Pusher-Protokoll.
    for code, lage in ((4001, "konfig"), (4000, "konfig"), (4099, "konfig"),
                       (4100, "backoff"), (4199, "backoff"), (4200, "sofort"),
                       (4299, "sofort"), (1000, "gewoehnlich"), (1006, "gewoehnlich"),
                       (None, "gewoehnlich"), (4300, "gewoehnlich"), ("4001", "gewoehnlich")):
        assert K.pusher_lage(code) == lage, (code, K.pusher_lage(code), lage)
    assert K.pusher_pause(4001, 1) == K.PUSHER_KONFIG_PAUSE_S >= 600, \
        "eine falsche Konfiguration wird weiter im Sekundentakt probiert"
    assert [K.pusher_pause(4100, n) for n in (1, 2, 3, 4)] == [1, 2, 4, 8]
    assert K.pusher_pause(4100, 30) == K.PUSHER_BACKOFF_MAX_S, "Backoff ohne Deckel"
    assert K.pusher_pause(4200, 5) == 1
    assert K.pusher_pause(None, 9) == K.PUSHER_GEWOEHNLICH_S == 10
    e = K.PusherGeschlossen(4001, "x")
    assert isinstance(e, ConnectionError) and e.code == 4001 and str(e) == "x"
    # Nach Bestandteilen statt per Textvergleich: ein startswith() auf eine
    # URL prueft nicht, wohin sie zeigt (CodeQL "incomplete URL substring
    # sanitization", zu Recht auch in einem Vertrag).
    from urllib.parse import urlsplit as _us, parse_qs as _pq
    u = _us(K.pusher_url("abc", " EU "))
    assert (u.scheme, u.netloc, u.path) == ("wss", "ws-eu.pusher.com", "/app/abc"), u
    assert _pq(u.query).get("protocol") == ["7"], u.query
    assert _us(K.pusher_url("abc", "")).netloc == "ws-us2.pusher.com", "leerer Cluster"

    # ── (2) Verdrahtung: Adresse aus Key UND Cluster, Schliesscode wird
    # mitgegeben, die Pause kommt aus _kick_ws_pause und nicht mehr fest 10.
    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    km = next(n for n in baum.body if isinstance(n, _ast.ClassDef)
              and n.name == "KickModerator")
    ws = next(n for n in km.body if isinstance(n, _ast.AsyncFunctionDef)
              and n.name == "_ws_loop")
    # ANKER GEWANDERT (v4.2-W154, nicht der Vertrag): die Adresse baut jetzt
    # _KickClusterSuche, weil sie nach 4001 den Cluster weiterschaltet. Der
    # Vertrag bleibt: Ausgangspunkt ist KICK_PUSHER_CLUSTER, nichts Festes.
    rufe = {_ast.unparse(c.func): c for c in _ast.walk(ws) if isinstance(c, _ast.Call)}
    assert "_suche.url" in rufe, "der Cluster ist wieder fest verdrahtet"
    ks = next(n for n in baum.body if isinstance(n, _ast.ClassDef)
              and n.name == "_KickClusterSuche")
    ks_rufe = {_ast.unparse(c.func) for c in _ast.walk(ks) if isinstance(c, _ast.Call)}
    assert "_nc_kickapi.pusher_url" in ks_rufe and "KICK_PUSHER_CLUSTER" in _ast.unparse(ks), \
        "der Cluster ist wieder fest verdrahtet"
    assert any(isinstance(r, _ast.Raise) and "PusherGeschlossen" in _ast.unparse(r)
               for r in _ast.walk(ws)), "der Schliesscode geht verloren"
    schlaf = [c for c in _ast.walk(ws) if isinstance(c, _ast.Call)
              and _ast.unparse(c.func) == "asyncio.sleep"]
    assert schlaf and all(_ast.unparse(c.args[0]) == "_pause" for c in schlaf), \
        [_ast.unparse(c) for c in schlaf]
    assert "_kick_ws_pause" in rufe
    erfolg = [n for n in _ast.walk(ws) if isinstance(n, _ast.If)
              and "pusher_internal:subscription_succeeded" in _ast.unparse(n.test)]
    assert erfolg and any(
        isinstance(z, _ast.Assign) and "_folge" in _ast.unparse(z.targets[0])
        for z in erfolg[0].body), \
        "nach einer gesunden Verbindung beginnt der Backoff nicht wieder klein"
    kp = next(n for n in baum.body if isinstance(n, _ast.FunctionDef)
              and n.name == "_kick_ws_pause")
    kq = _ast.unparse(kp)
    assert "folge[1] += 1" in kq and "_nc_kickapi.pusher_pause(code, folge[1])" in kq, \
        "die Folge zaehlt nicht mit — der Backoff waechst nie"
    assert "_nc_meldetakt.melden('kick-pusher'" in kq and "log.error" in kq, \
        "ein 4000er-Code steht nicht laut und gedrosselt im Fehlerlog"

    # ── (3) Das Pruefwerkzeug verdaechtigt den Key nur, wenn Pusher geantwortet hat.
    hier = os.path.dirname(os.path.abspath(__file__))
    if os.path.join(hier, "tools") not in _sys.path:
        _sys.path.insert(0, os.path.join(hier, "tools"))
    import kickpusher as KP
    alt = KP._alle
    try:
        async def _netz(key):
            return [(c, "netz", "DNS") for c in KP.CLUSTER]

        async def _abgelehnt(key):
            return [(c, "abgelehnt", "4001") for c in KP.CLUSTER]

        async def _einer(key):
            return [(c, "ok" if c == "eu" else "abgelehnt", "") for c in KP.CLUSTER]
        for fake, rc in ((_netz, 2), (_abgelehnt, 1), (_einer, 0)):
            KP._alle = fake
            assert KP.main(["--key", "abcd1234"]) == rc, fake.__name__
    finally:
        KP._alle = alt
    ok("W136: Pusher-Schliesscodes nach Protokoll, Cluster einstellbar, "
       "Pruefwerkzeug ohne falschen Verdacht")


def _test_v42_w137_kontrast_thema():
    """v4.2-W137: das Kontrast-Thema haelt, was es zusagt — WCAG AAA (7:1)
    fuer jede Text- und Akzentfarbe auf dem Panel, nachgerechnet aus dem CSS
    selbst. Ein Kommentar ueber die Farben ist kein Beweis ueber die Farben."""
    import re as _re
    h = open("templates/dashboard.html", encoding="utf-8").read()
    blk = _re.search(r'html\[data-theme="kontrast"\]\{(.*?)\n\}', h, _re.S)
    assert blk, "Kontrast-Thema fehlt"
    tok = dict(_re.findall(r"--([a-z0-9-]+):\s*(#[0-9A-Fa-f]{6})\s*;", blk.group(1)))

    def _lum(x):
        c = [int(x[i:i + 2], 16) / 255 for i in (1, 3, 5)]
        c = [v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4 for v in c]
        return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]

    def _ratio(a, b):
        la, lb = sorted((_lum(a), _lum(b)), reverse=True)
        return (la + 0.05) / (lb + 0.05)

    for name in ("text", "text-dim", "text-faint", "neon", "neon-dim", "cyan",
                 "magenta", "amber", "red", "ok"):
        assert name in tok, "Token --%s fehlt im Kontrast-Thema" % name
        r = _ratio(tok[name], tok["panel"])
        assert r >= 7.0, "--%s %s auf dem Panel nur %.1f:1 (AAA verlangt 7:1)" % (
            name, tok[name], r)
    assert "--glow:          none" in blk.group(1), "Glow kostet Kontrast"
    # Erreichbar ueber den Knopf, und das System darf es anfordern.
    # v4.2-W140: geprueft wird die MITGLIEDSCHAFT, nicht die woertliche
    # Liste — sonst faellt dieser Vertrag bei jedem neuen Thema, obwohl
    # Kontrast weiter erreichbar ist.
    _liste = _re.search(r"var NC_THEMEN=(\[[^\]]*\]);", h)
    assert _liste and "kontrast" in __import__("json").loads(_liste.group(1))
    assert 'matchMedia("(prefers-contrast: more)")' in h
    assert 'html[data-theme="kontrast"] :focus-visible' in h, "Fokus nicht sichtbar"
    ok("W137: Kontrast-Thema — alle Farben WCAG AAA aus dem CSS nachgerechnet, "
       "per Knopf und prefers-contrast erreichbar")


def _test_v42_w138_profil_und_prueflage():
    """v4.2-W138: das Profil-Popup laedt, das Profil sagt mehr, Discord zeigt
    es lesbar, und das Deck unterscheidet „unbekannt" von „offline"."""
    import ast as _ast
    import asyncio as _aio
    import json as _json
    import html as _html

    # (1) Der eigentliche Bug: fetch_profile auf der SESSION. Gemessen im
    # Syntaxbaum — kein Aufruf von .fetch_profile darf auf scraper_session()
    # haengen, und er muss auf get_scraper() haengen.
    baum = _ast.parse(open("nc/routes/beobachtung.py", encoding="utf-8").read())
    for n in _ast.walk(baum):
        if isinstance(n, _ast.Attribute) and n.attr == "fetch_profile":
            assert "scraper_session" not in _ast.unparse(n.value), \
                "fetch_profile auf der aiohttp-Session — die hat die Methode nicht"
    assert any(isinstance(n, _ast.Attribute) and n.attr == "mit_session"
               for n in _ast.walk(baum)), "Popup baut keinen Scraper"
    from nc.scraper import TikTokScraper as _TS
    _s = object()
    assert _TS.mit_session(_s).session is _s

    # (2) Scraper: Ablehnung mit Grund statt leerem „ok"-Profil.
    from nc.scraper import TikTokScraper

    def _seite(scope):
        roh = _json.dumps({"__DEFAULT_SCOPE__": scope})
        return ('<html><script id="__UNIVERSAL_DATA_FOR_REHYDRATION__" '
                'type="application/json">%s</script></html>' % _html.escape(roh))

    class _Resp:
        def __init__(self, text):
            self.status, self._t = 200, text
        async def text(self):
            return self._t
        def release(self):
            pass

    def _hole(text):
        sc = TikTokScraper.__new__(TikTokScraper)
        async def _req(url, **kw):
            return _Resp(text)
        sc._request = _req
        return _aio.run(sc.fetch_profile("probe"))

    r = _hole(_seite({"webapp.user-detail": {
        "statusCode": 10221, "statusMsg": "user banned",
        "userInfo": {"user": {}, "stats": {}}}}))
    assert not r["ok"], "leeres user-Objekt galt als Treffer"
    assert "statusCode 10221" in r["error"] and "user banned" in r["error"], r["error"]

    r = _hole('<html><div id="tiktok-verify-page">captcha</div></html>')
    assert not r["ok"] and "Captcha" in r["error"], r["error"]

    r = _hole(_seite({"webapp.user-detail": {"statusCode": 0, "userInfo": {
        "user": {"id": "7", "uniqueId": "probe", "nickname": "P",
                 "language": "de", "bioLink": {"link": "example.org"},
                 "commerceUserInfo": {"commerceUser": True, "category": "Gaming"},
                 "roomId": "7300", "createTime": 1600000000},
        "stats": {"followerCount": 1000, "followingCount": 10,
                  "heartCount": 2147483647, "videoCount": 100},
        "statsV2": {"heartCount": "5000000000"}}}}))
    assert r["ok"], r
    assert r["heart_count"] == 5000000000, "statsV2 nicht bevorzugt"
    assert (r["language"], r["bio_link"], r["commerce"], r["category"], r["room_id"]) \
        == ("de", "example.org", True, "Gaming", "7300"), r

    # (3) Kennzahlen und Verlauf.
    from nc import profildetail as P
    kz = P.kennzahlen(r)
    assert kz["likes_pro_video"] == 50000000 and kz["follower_pro_folgt"] == 100.0
    assert P.kennzahlen({"follower_count": 5, "video_count": 0})["likes_pro_video"] is None
    assert P.kontotyp(r) == "Business · Gaming"
    jetzt = 1_800_000_000
    iso = lambda s: __import__("datetime").datetime.fromtimestamp(
        jetzt - s, __import__("datetime").timezone.utc).isoformat()
    # Ein Schnappschuss von vor zehn Minuten ist KEIN Tageswert.
    v = P.verlauf([{"follower_count": 990, "captured_at": iso(600)}],
                  {"follower_count": 1000}, jetzt)
    assert v["tag"] is None and v["woche"] is None, v
    v = P.verlauf([{"follower_count": 900, "captured_at": iso(2 * 86400)},
                   {"follower_count": 500, "captured_at": iso(8 * 86400)}],
                  {"follower_count": 1000}, jetzt)
    assert (v["tag"], v["woche"]) == (100, 500), v

    # (4) Pruefstand: unbekannt ist nicht offline, und nicht live.
    from nc import prueflage as L
    L._STAND.clear()
    t0 = 1_000_000.0
    assert L.lage(1, True, jetzt=t0)["zustand"] == "ausstehend"
    L.merken(1, "live", jetzt=t0)
    L.merken(1, "unknown", jetzt=t0 + 60)
    assert L.lage(1, True, jetzt=t0 + 120)["zustand"] == "live", \
        "ein einzelnes unknown darf den Punkt nicht flackern lassen"
    L.merken(1, "unknown", jetzt=t0 + L.UNSICHER_AB_S + 30)
    la = L.lage(1, True, jetzt=t0 + L.UNSICHER_AB_S + 40)
    assert la["zustand"] == "unbekannt", "seit >10 min nur unknown, steht aber als LIVE da"
    assert la["sicher_vor_s"] == L.UNSICHER_AB_S + 40
    L.merken(1, "offline", jetzt=t0 + 2000)
    assert L.lage(1, False, jetzt=t0 + 2010)["zustand"] == "offline"
    assert L.lage(1, False, jetzt=t0 + 2000 + L.UEBERFAELLIG_AB_S + 1)["ueberfaellig"]
    assert not L.lage(1, False, paused=True,
                      jetzt=t0 + 2000 + L.UEBERFAELLIG_AB_S + 1)["ueberfaellig"]
    assert L.lage(1, False, recording=True, jetzt=t0 + 2010)["zustand"] == "rec"
    L._STAND.clear()
    src = open("bot.py", encoding="utf-8").read()
    assert "_nc_prueflage.merken(tracking_id, last_status)" in src
    assert '"pruefung": _nc_prueflage.lage(' in open(
        "nc/routes/trackings.py", encoding="utf-8").read()

    # (5) Discord: <pre> wird Codeblock, nicht Fettdruck; Entitaeten weg.
    from nc import tgmarkdown as M
    md = M.html_zu_md('<b>PROFIL · @a&amp;b</b>\n<pre>Follower   1.2K\nLikes *  9</pre>'
                      '\n<a href="https://x.y/">Link &lt;1&gt;</a>'
                      '\n<blockquote expandable>Bio\nZeile</blockquote>')
    assert "**PROFIL · @a&b**" in md, md
    assert "```\nFollower   1.2K\nLikes *  9\n```" in md, md
    assert "[Link <1>](https://x.y/)" in md and "> Bio\n> Zeile" in md, md
    assert "<" not in md.replace("<1>", ""), md
    tabelle = "```\n" + "\n".join("Zeile %02d   %s" % (i, "x" * 40) for i in range(20)) + "\n```"
    stuecke = M.teilen(("Kopf\n\n" + tabelle + "\n\n") * 4, 1900)
    assert all(len(x) <= 1900 for x in stuecke)
    assert all(x.count("```") % 2 == 0 for x in stuecke), "Codeblock zerschnitten"
    assert "_nc_tgmd.html_zu_md(out)" in open("discordbot.py", encoding="utf-8").read()

    # (6) Telegram-Report: Verhaeltnisse da, Bio-Link nur mit http(s).
    from nc.scoring import build_report
    rep = build_report(dict(r, bio_link="javascript:alert(1)"), {"is_live": False})
    assert "Verhältnisse" in rep and "Business · Gaming" in rep
    assert 'href="https://javascript:alert(1)"' in rep, "fremdes Schema im Link"
    ok("W138: Popup holt den Scraper, Profil mit Grund/Details/Verlauf, Discord "
       "als Markdown, unbekannt ≠ offline im Deck")


def _test_v42_w138_profil_route():
    """v4.2-W138: der Popup-Pfad selbst — Scraper auf der geteilten Session,
    Verlauf aus der Datenbank, Fehler mit Grund. Und die Randfaelle der
    reinen Helfer, damit die Ueberdeckung nicht nur den Erfolgspfad kennt."""
    import asyncio as _aio
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz
    import nc.ctx as _ncctx
    import nc.scraper as _sc
    from nc import restreamstate as _rs
    import nc.routes.beobachtung as R
    from nc.dbwrap import db_conn as _db

    class _Log:
        def __init__(self): self.zeilen = []
        def _s(self, *a, **k): self.zeilen.append(a[0] % a[1:] if len(a) > 1 else str(a[0]))
        warning = info = error = debug = _s
    protokoll = _Log()
    sitzung = object()
    alt_ctx = _ncctx._CTX
    alt_fp = _sc.TikTokScraper.fetch_profile
    alt_rg, alt_rs = _rs.REDIS_GET["fn"], _rs.REDIS_SET["fn"]
    gesehen = []

    async def _fp(self, username):
        gesehen.append(self.session)
        return {"ok": True, "username": username, "follower_count": 1500,
                "following_count": 30, "heart_count": 9000, "video_count": 90,
                "commerce": True, "create_time": 1600000000}

    async def _rget(key):
        return None

    async def _rset(key, wert, ttl=0):
        return None
    try:
        _ncctx.configure(log=protokoll, scraper_session=lambda: sitzung,
                         run_async=lambda coro, timeout=0: _aio.run(coro))
        _sc.TikTokScraper.fetch_profile = _fp
        _rs.REDIS_GET["fn"], _rs.REDIS_SET["fn"] = _rget, _rset
        alt = (_dt.now(_tz.utc) - _td(days=2)).isoformat()
        with _db() as c:
            # Die Testdatenbank kennt nicht jede Tabelle; Spalten wie in
            # nc/schema.py (profile_snapshots).
            c.execute("CREATE TABLE IF NOT EXISTS profile_snapshots ("
                      "id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL,"
                      " payload TEXT NOT NULL, follower_count INT, heart_count BIGINT,"
                      " video_count INT, captured_at TEXT NOT NULL)")
            c.execute("DELETE FROM profile_snapshots WHERE username='w138probe'")
            c.execute("INSERT INTO profile_snapshots (username, payload, follower_count,"
                      " heart_count, video_count, captured_at) VALUES (?,?,?,?,?,?)",
                      ("w138probe", "{}", 1200, 0, 0, alt))
            c.commit()
        p = R._tiktok_profil("w138probe")
        assert gesehen == [sitzung], "Scraper nicht auf der geteilten Session gebaut"
        assert p["follower_count"] == 1500 and p["kontotyp"] == "Business", p
        assert p["verlauf"]["tag"] == 300 and p["verlauf"]["woche"] is None, p["verlauf"]
        assert p["erstellt"] == "2020-09-13" and p["kennzahlen"]["likes_pro_video"] == 100

        async def _fp_nein(self, username):
            return {"ok": False, "error": "TikTok meldet statusCode 10221"}
        _sc.TikTokScraper.fetch_profile = _fp_nein
        assert R._tiktok_profil("w138probe") == {"error": "TikTok meldet statusCode 10221"}
        _ncctx.configure(log=protokoll, scraper_session=lambda: None,
                         run_async=lambda coro, timeout=0: _aio.run(coro))
        assert "error" in R._tiktok_profil("w138probe")
    finally:
        _ncctx._CTX = alt_ctx
        _sc.TikTokScraper.fetch_profile = alt_fp
        _rs.REDIS_GET["fn"], _rs.REDIS_SET["fn"] = alt_rg, alt_rs
        with _db() as c:
            c.execute("DELETE FROM profile_snapshots WHERE username='w138probe'")
            c.commit()

    # Randfaelle der reinen Helfer.
    from nc import profildetail as P
    assert [P._zahl(v) for v in (True, 3.7, " 42 ", "1.2K", None)] == [None, 3, 42, None, None]
    assert P.datum(0) is None and P.datum(1700000000000) is None
    assert P.datum("1600000000") == "2020-09-13"
    assert P.kontotyp({"organization": True}) == "Organisation"
    assert P.kontotyp({"seller": True}) == "Shop" and P.kontotyp({}) is None
    f = P.felder({"verified": 1, "nickname": "N", "geheim": "x"})
    assert f["verified"] is True and f["nickname"] == "N" and "geheim" not in f
    assert P.verlauf([], {"follower_count": None})["messpunkte"] == 0
    import logging as _lg
    zeilen = []
    class _H(_lg.Handler):
        def emit(self, r): zeilen.append(r.getMessage())
    h = _H(); P.log.addHandler(h)
    try:
        assert P._ts("kein-datum") is None and P._ts("") is None
    finally:
        P.log.removeHandler(h)
    assert any("unlesbar" in z for z in zeilen), "kaputter Zeitstempel fiel still durch"

    from nc import prueflage as L
    L.merken(99, "live", jetzt=1.0); L.vergessen(99)
    assert L.lage(99, True, jetzt=2.0)["zustand"] == "ausstehend"
    from nc import tgmarkdown as M
    assert M.teilen("x" * 5000, 1900) == ["x" * 1900, "x" * 1900, "x" * 1200]
    assert M.html_zu_md(None) == ""
    ok("W138: Popup-Pfad mit Scraper auf geteilter Session, Verlauf aus der DB, "
       "Ablehnung mit Grund; Randfaelle der Helfer gedeckt")


def _test_v42_w139_spanisch():
    """v4.2-W139: Spanisch ist eine volle Sprache, kein halber Katalog.
    Gleiche Schluessel wie Englisch, und jeder Platzhalter, den der Code
    einsetzt ({0}, %s, **…**), steht auch im spanischen Text — sonst
    verschwindet zur Laufzeit ein Name oder eine Zahl, ohne Fehlermeldung."""
    import json as _json
    import re as _re
    import subprocess as _sp
    from nc import i18n as I
    assert "es" in I.SPRACHEN and I.KATALOGDATEI["es"] == "es.json"
    assert I.SPRACHNAMEN["es"] == "Español"
    en = _json.load(open("locales/en.json", encoding="utf-8"))["strings"]
    es = _json.load(open("locales/es.json", encoding="utf-8"))["strings"]
    assert set(en) == set(es), "es und en haben verschiedene Schluessel"
    marke = _re.compile(r"\{\d+\}|%[sd]|&mdash;|\*\*")
    for k in en:
        assert sorted(marke.findall(en[k])) == sorted(marke.findall(es[k])), \
            "Platzhalter weichen ab: %r -> %r" % (en[k], es[k])
        assert es[k].strip(), "leere Uebersetzung fuer %r" % k
        # Ein Bruchstueck, das mit "@" oder "·" endet, wird zur Laufzeit
        # zusammengesetzt — das Spanische muss an derselben Naht enden.
        for z in "@·(":
            assert en[k].endswith(z) == es[k].endswith(z), (k, en[k], es[k])
    # Wirklich uebersetzt, nicht kopiert: hoechstens Marken und Namen gleich.
    gleich = [k for k in en if en[k] == es[k] and _re.search(r"[a-z]{4}", en[k])]
    assert len(gleich) < 40, "zu viele unveraenderte Eintraege: %r" % gleich[:10]
    assert I.aus_accept_language("es-ES,es;q=0.9") == "es"
    assert I.normalisieren("es-MX") == "es"
    # In einem eigenen Kontext: sprache_setzen schreibt eine ContextVar, und
    # die soll nicht in die folgenden Vertraege durchsickern.
    import contextvars as _cv

    def _auf_spanisch():
        I.sprache_setzen("es")
        return I.t("Profil-Analyse eines TikTok-Accounts")
    assert _cv.copy_context().run(_auf_spanisch) == "Análisis del perfil de una cuenta de TikTok"
    # Shell-Werkzeuge: kein tools.es.tsv, also Englisch statt Deutsch.
    r = _sp.run(["bash", "-c", "NC_LANG=es; . tools/lib/i18n.sh; printf %s \"$NC_LANG_EFF\""],
                capture_output=True, text=True, timeout=20)
    assert r.stdout.strip() == "en", (r.stdout, r.stderr)
    ok("W139: Spanisch — 1557 Eintraege, Platzhalter und Naehte wie im Englischen, "
       "Browsererkennung, Shell faellt auf Englisch")


def _test_v42_w140_phosphor_thema():
    """v4.2-W140: das vierte Thema. Dunkel und gruen — und gerade deshalb
    nachgerechnet: jede Text- und Signalfarbe mindestens WCAG AA (4,5:1) auf
    dem Panel, und Rot muss rot bleiben (ein Fehler darf in einem gruenen
    Thema nicht gruen aussehen)."""
    import json as _json
    import re as _re
    h = open("templates/dashboard.html", encoding="utf-8").read()
    blk = _re.search(r'html\[data-theme="phosphor"\]\{(.*?)\n\}', h, _re.S)
    assert blk, "Phosphor-Thema fehlt"
    tok = dict(_re.findall(r"--([a-z0-9-]+):\s*(#[0-9A-Fa-f]{6})\s*;", blk.group(1)))

    def _lum(x):
        x = x.lstrip("#")
        c = [int(x[i:i + 2], 16) / 255 for i in (0, 2, 4)]
        c = [v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4 for v in c]
        return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]

    def _ratio(a, b):
        la, lb = _lum(a), _lum(b)
        return (max(la, lb) + 0.05) / (min(la, lb) + 0.05)
    for name in ("text", "text-dim", "text-faint", "neon", "neon-dim", "cyan",
                 "magenta", "amber", "red", "ok"):
        assert name in tok, "--%s fehlt im Phosphor-Thema" % name
        r = _ratio(tok[name], tok["panel-solid"])
        assert r >= 4.5, "--%s %s auf dem Panel nur %.1f:1 (AA verlangt 4,5:1)" % (
            name, tok[name], r)
    rot = [int(tok["red"].lstrip("#")[i:i + 2], 16) for i in (0, 2, 4)]
    assert rot[0] > rot[1] * 1.5, "--red %s ist im Phosphor-Thema nicht mehr rot" % tok["red"]
    themen = _json.loads(_re.search(r"var NC_THEMEN=(\[[^\]]*\]);", h).group(1))
    namen = _json.loads(_re.search(r"var NC_THEMA_NAME=(\{[^}]*\});", h).group(1))
    zeichen = _json.loads(_re.search(r"var NC_THEMA_ZEICHEN=(\{[^}]*\});", h).group(1))
    assert "phosphor" in themen, "per Knopf nicht erreichbar"
    assert set(themen) == set(namen) == set(zeichen), "Thema ohne Name oder Zeichen"
    assert len(set(zeichen.values())) == len(zeichen), "zwei Themen mit demselben Zeichen"
    # Jedes Thema der Liste hat einen Token-Block — sonst waehlte der Knopf
    # ein Thema, das aussieht wie die Vorgabe.
    for t in themen:
        assert ('html[data-theme="%s"]{' % t) in h, "Thema %s ohne Token-Block" % t
    ok("W140: Phosphor-Thema — alle Farben ≥ AA aus dem CSS nachgerechnet, Rot "
       "bleibt rot, alle Themen mit Name, Zeichen und Token-Block")


def _test_v42_w141_dritte_form():
    """v4.2-W141: „keiner wird restreamt, angeblich keine flv oder hls" — die
    Kette liest jetzt auch CMAF/DASH/MP4, streicht kurzlebige Adressen
    einzeln statt alle, und sagt im Deck und in /healthz, was los ist."""
    import ast as _ast
    from nc import streamsel as S, ytdlpurl as Y, livefolge as L
    from nc import restreamcmd as R, quellstat as Q
    C = "https://pull-cmaf-f1.tiktokcdn.com/stage/stream-1/index.mp4?expire=9999999999"
    D = "https://pull-dash.tiktokcdn.com/stage/stream-1/index.mpd?expire=9999999999"
    F = "https://pull-flv-l1.tiktokcdn.com/stage/stream-1.flv?expire=9999999999"
    # (1) stream_data: eine Qualitaet NUR mit cmaf wird gelesen …
    nur = S.select_stream_from_data_section({"hd": {"main": {"cmaf": C, "sdk_params": "{}"}}})
    assert nur and nur["other_url"] == C and nur["other_kind"] == "cmaf", nur
    # … steht aber hinter jeder Qualitaet mit FLV/HLS, auch einer schlechteren.
    gemischt = S.select_stream_from_data_section({
        "origin": {"main": {"cmaf": C}}, "sd": {"main": {"flv": F}}})
    assert gemischt["flv_url"] == F and gemischt["quality"] == "sd", gemischt
    knoten = {"liveCoreSDKData": {"pull_data": {"stream_data": __import__("json").dumps(
        {"data": {"hd": {"main": {"dash": D}}}})}}}
    k = S.extract_urls_from_streamurl_node(knoten)
    assert k and k["other_url"] == D and k["other_kind"] == "dash", k
    # (2) yt-dlp: DASH wird nicht mehr verworfen, aber nur ohne FLV/HLS genommen.
    y = Y.urls_aus_json({"formats": [{"url": D, "protocol": "http_dash_segments", "ext": "mp4"}]})
    assert y.get("other_url") == D and y.get("other_kind") == "dash", y
    y2 = Y.urls_aus_json({"formats": [{"url": D, "protocol": "http_dash_segments"},
                                       {"url": F, "ext": "flv"}]})
    assert y2.get("flv_url") == F and "other_url" not in y2, y2
    assert Y._andere_art("file:///etc/passwd.mp4") == "", "fremdes Schema als Quelle"
    # (3) kurzlebig wird EINZELN gestrichen.
    ttl = {"F": 30, "H": 3000}
    fr = Y.nur_frische({"flv_url": "F", "hls_url": "H", "via": "ytdlp"},
                       lambda u: ttl.get(u), 120)
    assert fr.get("hls_url") == "H" and "flv_url" not in fr and fr["verworfen"] == ["flv 30s"], fr
    assert "verworfen" not in Y.nur_frische({"hls_url": "X"}, lambda u: None, 120)
    # (4) Annahme und Reihenfolge.
    assert L.hat_stream_url({"other_url": C}) and not L.hat_stream_url({"other_url": ""})
    assert L.beste_url({"hls_url": "h", "other_url": "o"}) == "h"
    assert L.beste_url({"flv_url": "f", "hls_url": "h"}) == "f"
    assert L.beste_url({"other_url": "o"}) == "o" and L.beste_url({}) is None
    # (5) segmentierte Eingaenge bekommen die B60-Zeitstempel-Flags.
    assert R._ist_segmentiert(D) and R._ist_segmentiert(C) and not R._ist_segmentiert(F)
    assert not R._ist_hls(D), "_ist_hls muss eng bleiben (aac_adtstoasc)"
    # (6) Quellen-Statistik: gleitend, und „nichts gezaehlt" ist nicht 0 %.
    Q.zuruecksetzen()
    assert Q.lage(jetzt=10.0)["ohne_url_anteil"] is None
    for a, t in (("api", 0.0), ("keiner", 1.0), ("keiner", 2.0), ("ytdlp", 3.0)):
        Q.zaehlen(a, jetzt=t)
    la = Q.lage(jetzt=10.0)
    assert (la["api"], la["keiner"], la["gesamt"], la["ohne_url_anteil"]) == (1, 2, 4, 0.5), la
    assert Q.lage(jetzt=Q.FENSTER_S + 2.5)["gesamt"] == 1, "Fenster gleitet nicht"
    Q.zuruecksetzen()
    try:
        Q.zaehlen("erfunden")
        raise AssertionError("unbekannter Ausgang still gezaehlt")
    except ValueError:
        pass
    # (7) bot.py: Grund ins Panel, kein stilles pass, Schreiben neben dem Loop,
    # Statistik in /healthz und an allen vier Ausgaengen gezaehlt.
    src = open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(src)
    fn = next(n for n in _ast.walk(baum) if isinstance(n, _ast.FunctionDef)
              and n.name == "_reflect_source_status")
    assert "last_error=?" in _ast.unparse(fn), "Grund wird nicht ins Panel geschrieben"
    assert not any(isinstance(h, _ast.ExceptHandler) and all(
        isinstance(b, _ast.Pass) for b in h.body) for h in _ast.walk(fn)), "stilles pass"
    aufrufe = [n for n in _ast.walk(baum) if isinstance(n, _ast.Call)
               and _ast.unparse(n.func).endswith("_reflect_source_status")]
    assert not aufrufe, "_reflect_source_status direkt auf dem Loop gerufen"
    assert src.count("asyncio.to_thread(self._reflect_source_status") == 3
    zaehl = {n.args[0].value for n in _ast.walk(baum) if isinstance(n, _ast.Call)
             and _ast.unparse(n.func) == "_nc_quellstat.zaehlen"
             and n.args and isinstance(n.args[0], _ast.Constant)}
    assert zaehl == set(Q.AUSGAENGE), zaehl
    assert "quellen=_nc_quellstat.lage()" in src
    ok("W141: CMAF/DASH/MP4 als dritte Form (stream_data, yt-dlp, Restream), "
       "Kurzlebiges einzeln gestrichen, Grund im Panel, Quellen-Statistik")


def _test_v42_w141_quellprobe():
    """v4.2-W141: das Messwerkzeug fuer den Server — es darf nichts Geheimes
    ausgeben und muss aus den Befunden die richtige Abhilfe ableiten."""
    # v4.2-W142: der Kern liegt in nc/ (fuer /quelle), tools/ ruft ihn nur auf.
    from nc import quellprobe as QP
    assert "from nc.quellprobe import main" in open(
        "tools/quellprobe.py", encoding="utf-8").read()
    assert QP.maske("http://nutzer:geheim@1.2.3.4:8118") == "http://***@1.2.3.4:8118"
    assert QP.maske("nutzer:geheim@1.2.3.4:8118") == "***@1.2.3.4:8118", "schemalos unmaskiert"
    assert QP.maske("socks5://1.2.3.4:1080") == "socks5://1.2.3.4:1080"
    assert QP.ttl("https://x/y.flv?expire=1100", jetzt=1000) == 100
    assert QP.ttl("https://x/y.flv") is None
    k = QP.kurz("https://pull.tiktokcdn.com/a/b.flv?expire=9999999999&sign=GEHEIM")
    assert "GEHEIM" not in k and k.startswith("pull.tiktokcdn.com …flv"), k
    assert QP.form("https://h/x.m3u8") == "hls" and QP.form("https://h/x.mpd") == "dash"
    E = QP.empfehlung
    assert "FLV/HLS-Adresse ist ziehbar" in E({"kandidaten": [{"form": "hls", "ffprobe_ok": True}]})
    assert "dritte Form (dash)" in E({"kandidaten": [{"form": "dash", "ffprobe_ok": True}]})
    # ANKER GEWANDERT (v4.2-W148): die Empfehlung nennt nicht mehr einen
    # Zubringer, den man bauen muesste, sondern den Durchreicher, den der
    # Restream seither von selbst nimmt — und den Schalter dazu.
    _dr = E({"kandidaten": [{"form": "flv", "ffprobe_ok": False}], "durchreicher_bytes": 5})
    assert "Durchreicher" in _dr and "RESTREAM_DURCHREICHER" in _dr, _dr
    assert "RECORD_PROXY" in E({"kandidaten": [{"form": "flv", "ffprobe_ok": False}]})
    assert "Kein Weg" in E({})
    ok("W141: tools/quellprobe.py — Zugangsdaten maskiert, Signaturen gekuerzt, "
       "Abhilfe aus den Befunden")


def _test_v42_w142_zehn_punkte():
    """v4.2-W142: zehn Verbesserungen quer durch das Projekt, jede mit einer
    Zusicherung, die faellt, wenn sie zurueckgedreht wird."""
    import ast as _ast
    import io as _io
    import os as _os
    import tarfile as _tar
    import shutil as _sh
    src = open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(src)

    def _fn(name):
        return next(n for n in _ast.walk(baum)
                    if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef)) and n.name == name)

    # (1) /quelle — in beiden Plattformen, im Thread, hoechstens eine.
    from nc import befehle as B
    b = next(x for x in B.BEFEHLE if x.name == "quelle")
    assert B.TG in b.plattformen and B.DC in b.plattformen and b.tg_handler == "quelle"
    q = _ast.unparse(_fn("quelle"))
    assert "asyncio.to_thread(_nc_quellprobe.messen" in q, "Quellprobe auf dem Loop"
    assert "_QUELLPROBE['laeuft']" in q or '_QUELLPROBE["laeuft"]' in q
    from nc import quellprobe as QP
    alt = (QP.probe_ytdlp, QP.probe_html, QP.probe_ffprobe, QP.probe_durchreicher)
    try:
        QP.probe_ytdlp = lambda n, p, c: ([{"weg": "yt-dlp", "id": "x", "form": "hls",
                                            "url": "https://cdn.x/a.m3u8?sign=GEHEIM"}], None)
        QP.probe_html = lambda n, p: ([], "keine Stream-Adresse im HTML")
        QP.probe_ffprobe = lambda u, p: (True, "video=h264")
        QP.probe_durchreicher = lambda n, p, c: 0
        zeilen = []
        bef = QP.messen("probe", "", None, zeilen.append)
    finally:
        QP.probe_ytdlp, QP.probe_html, QP.probe_ffprobe, QP.probe_durchreicher = alt
    assert "FLV/HLS" in bef["empfehlung"] and zeilen[-1].startswith("EMPFEHLUNG:")
    assert "GEHEIM" not in repr(bef) and "GEHEIM" not in "\n".join(zeilen), "Signatur im Ergebnis"

    # (2)+(3) /tracklist: Pruefstand und neben dem Loop.
    t = _ast.unparse(_fn("tracklist"))
    assert "asyncio.to_thread(get_trackings_for_group" in t
    assert "_nc_prueflage.lage(" in t and "'unbekannt'" in t

    # (4)+(5) Uebersicht, /healthz ohne Namen, Selbstmeldung in der Pruefschleife.
    from nc import prueflage as L
    L._STAND.clear()
    L.LETZTE["uebersicht"] = None
    assert L.fuer_healthz() is None, "vor der ersten Runde ist das keine 0"
    L.merken(1, "live", jetzt=1000.0)
    L.merken(2, "unknown", jetzt=1000.0)
    u = L.uebersicht([(1, "a"), (2, "b"), (3, "c")], laeuft_seit_s=60, jetzt=1000.0 + 30)
    assert (u["aktiv"], u["unbekannt"], u["ausstehend"], u["ueberfaellig"]) == (3, 1, 1, 0), u
    assert not u["ausstehend_befund"], "kurz nach dem Start ist 'nie geprueft' normal"
    u = L.uebersicht([(1, "a"), (3, "c")], laeuft_seit_s=L.AUSSTEHEND_NORMAL_S + 1,
                     jetzt=1000.0 + L.UEBERFAELLIG_AB_S + 5)
    assert u["ueberfaellig"] == 1 and u["auffaellig"]["ueberfaellig"] == ["a"] and u["ausstehend_befund"]
    L.LETZTE["uebersicht"] = u
    assert "auffaellig" not in L.fuer_healthz(), "Nutzernamen in /healthz"
    L._STAND.clear()
    L.LETZTE["uebersicht"] = None
    assert "pruefung=_nc_prueflage.fuer_healthz()" in src
    pm = _ast.unparse(_fn("_pruefstand_melden"))
    assert "log.error" in pm and "_nc_meldetakt.melden('pruefstand'" in pm
    schleife = _ast.unparse(_fn("_pruef_runde"))   # ANKER GEWANDERT (v4.2-W176)
    assert "_pruefstand_melden(trackings)" in schleife

    # (6) Deck zeigt die Quellen-Statistik.
    h = open("templates/dashboard.html", encoding="utf-8").read()
    assert 'id="sv_quellen"' in h and "apiGet('/healthz')" in h and "q.ohne_url_anteil" in h

    # (7) Sicherung: Platzhalter, Abbruch und fehlender Dump fallen auf.
    from nc import sicherungspruefung as S
    d = _ph.verzeichnis("nc-pruef-w142-")
    try:
        gut = _os.path.join(d, "gut.sql")
        open(gut, "w").write("BEGIN TRANSACTION;\nCREATE TABLE t(x);\nCOMMIT;\n")
        platz = _os.path.join(d, "platz.sql")
        open(platz, "w").write("-- mysqldump nicht installiert — kein Dump möglich\n")
        halb = _os.path.join(d, "halb.sql")
        open(halb, "w").write("BEGIN TRANSACTION;\nINSERT INTO t VALUES('abgeschn")
        assert S.dump_vollstaendig(gut)[0]
        assert not S.dump_vollstaendig(platz, "mariadb")[0], "mysqldump-Platzhalter galt als Dump"
        assert not S.dump_vollstaendig(halb)[0], "abgebrochener Dump galt als vollstaendig"
        arch = _os.path.join(d, "a.tar.gz")
        with _tar.open(arch, "w:gz") as tf:
            tf.add(gut, arcname="db/gut.sql")
        assert S.pruefen(arch, gut)["ok"]
        ohne = _os.path.join(d, "o.tar.gz")
        with _tar.open(ohne, "w:gz") as tf:
            info = _tar.TarInfo("README"); daten = b"x"; info.size = len(daten)
            tf.addfile(info, _io.BytesIO(daten))
        r = S.pruefen(ohne, halb)
        assert not r["ok"] and len(r["gruende"]) == 2, r
        kaputt = _os.path.join(d, "k.tar.gz")
        open(kaputt, "wb").write(open(arch, "rb").read()[:20])
        assert not S.archiv_lesbar(kaputt)[0], "abgeschnittenes Archiv galt als lesbar"
    finally:
        _sh.rmtree(d, ignore_errors=True)
    sb = _ast.unparse(_fn("_system_backup"))
    assert "_nc_sicherung.pruefen(tar_tmp, dump_path, DB_BACKEND)" in sb
    assert "'ok': pruefung['ok']" in sb, "ok haengt nicht an der Pruefung"
    # Kein `try: tar.add(...) except: pass` mehr — die Datei fehlte sonst still.
    for n in _ast.walk(_fn("_system_backup")):
        if isinstance(n, _ast.Try) and any(
                "tar.add(fp" in _ast.unparse(x) for x in n.body):
            assert not any(all(isinstance(y, _ast.Pass) for y in h.body)
                           for h in n.handlers), "tar.add mit stillem pass"
    assert "nicht_gesichert.append(" in sb

    # (8) Pruefsummen am Release.
    br = open("tools/build_release.py", encoding="utf-8").read()
    assert ".hexdigest()[:16]" not in br
    # Im Syntaxbaum: ein open(..., "SHA256SUMS" ..., "w") muss es geben — der
    # Name allein steht auch in der Ausschlussliste (die erste Fassung dieses
    # Vertrags las genau die und liess eine entfernte Schreibstelle durch).
    _br = _ast.parse(br)
    assert any(isinstance(n, _ast.Call) and getattr(n.func, "id", "") == "open" and n.args
               and "'SHA256SUMS'" in _ast.unparse(n.args[0])
               and any(isinstance(x, _ast.Constant) and x.value == "w" for x in n.args[1:])
               for n in _ast.walk(_br)), "SHA256SUMS wird nicht geschrieben"
    assert 'AUS = {".env", "stats.json", "SHA256SUMS"}' in br
    rel = open(".github/workflows/release.yml", encoding="utf-8").read()
    assert rel.count("SHA256SUMS") >= 3 and "sha256sum -c SHA256SUMS" in rel

    # (9) Profil-Schnappschuesse: hoechstens einer je Stunde und Nutzer.
    import nc.routes.beobachtung as R
    from nc.dbwrap import db_conn as _db
    with _db() as c:
        c.execute("CREATE TABLE IF NOT EXISTS profile_snapshots ("
                  "id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL,"
                  " payload TEXT NOT NULL, follower_count INT, heart_count BIGINT,"
                  " video_count INT, captured_at TEXT NOT NULL)")
        c.execute("DELETE FROM profile_snapshots WHERE username='w142probe'")
        c.commit()
    try:
        a = R.save_profile_snapshot("w142probe", {"follower_count": 1})
        b = R.save_profile_snapshot("w142probe", {"follower_count": 2})
        assert a and a == b, "zweiter Klick legte einen zweiten Schnappschuss an"
        with _db() as c:
            n = c.execute("SELECT COUNT(*) FROM profile_snapshots WHERE username='w142probe'"
                          ).fetchone()[0]
        assert n == 1, n
    finally:
        with _db() as c:
            c.execute("DELETE FROM profile_snapshots WHERE username='w142probe'")
            c.commit()

    # (10) Doku und Skill kennen vier Themen und drei Sprachen.
    sk = open(".claude/skills/html-templates/SKILL.md", encoding="utf-8").read()
    assert "Kontrast" in sk and "Phosphor" in sk and "_test_v42_w140_phosphor_thema" in sk
    assert "de.json, en.json, es.json" in open("CLAUDE.md", encoding="utf-8").read()
    ok("W142: /quelle, Pruefstand in /tracklist und /healthz, Selbstmeldung, "
       "Quellen im Deck, geprueftes Backup, SHA256SUMS, Schnappschuss-Drossel, Doku")


def _test_v42_w142_quellprobe_wege():
    """v4.2-W142: die Probe-Wege selbst — yt-dlp, Live-Seite, ffprobe,
    Durchreicher — mit Attrappen statt Netz. Seit der Kern in nc/ liegt, zaehlt
    er zur Ueberdeckung; ungeprueft waeren genau die Fehlerpfade, an denen der
    Betreiber die Abhilfe abliest."""
    import contextlib as _cl
    import io as _io
    import json as _json
    import os as _os
    import subprocess as _sp
    from nc import quellprobe as QP

    alt = (QP.shutil.which, QP.subprocess.run, QP.subprocess.Popen,
           QP.urllib.request.build_opener, QP.time.sleep)

    class _Lauf:
        def __init__(self, rc, out="", err=""):
            self.returncode, self.stdout, self.stderr = rc, out, err

    def _run_mit(*antworten):
        it = iter(antworten)
        def _run(cmd, **kw):
            a = next(it)
            if isinstance(a, BaseException):
                raise a
            return a
        return _run
    try:
        # yt-dlp fehlt: ehrliche Auskunft statt leerer Liste ohne Grund.
        QP.shutil.which = lambda n: None
        assert QP.probe_ytdlp("x", "", None) == ([], "yt-dlp nicht installiert")
        assert QP.probe_ffprobe("https://h/x.flv", "")[1] == "ffprobe nicht installiert"
        assert QP.probe_durchreicher("x", "", None) == 0
        QP.shutil.which = lambda n: "/usr/bin/" + n
        # yt-dlp: Formate gelesen, Proxy und Cookies weitergereicht.
        gesehen = []
        def _run_fmt(cmd, **kw):
            gesehen.append(cmd)
            return _Lauf(0, _json.dumps({"formats": [
                {"url": "https://h/a.flv?expire=1", "ext": "flv", "format_id": "f"},
                {"manifest_url": "https://h/a.mpd", "protocol": "http_dash_segments"}]}))
        QP.subprocess.run = _run_fmt
        f, fehler = QP.probe_ytdlp("x", "http://u:p@1.2.3.4:8", "/c.txt")
        assert fehler is None and [k["form"] for k in f] == ["flv", "dash"], f
        assert "--proxy" in gesehen[0] and "--cookies" in gesehen[0]
        # Fehlermeldung von yt-dlp: Zugangsdaten maskiert.
        QP.subprocess.run = _run_mit(_Lauf(1, "", "x\nERROR: proxy http://u:geheim@h:8 refused"))
        f, fehler = QP.probe_ytdlp("x", "", None)
        assert f == [] and "geheim" not in fehler and "***@" in fehler, fehler
        QP.subprocess.run = _run_mit(_sp.TimeoutExpired("yt-dlp", 40))
        assert QP.probe_ytdlp("x", "", None)[1].startswith("Zeitüberschreitung")
        # ffprobe: Spuren, Fehler, Zeitueberschreitung.
        QP.subprocess.run = _run_mit(_Lauf(0, _json.dumps({"streams": [
            {"codec_type": "video", "codec_name": "h264"},
            {"codec_type": "audio", "codec_name": "aac"}]})))
        assert QP.probe_ffprobe("https://h/x.flv", "http://p:8") == (True, "audio=aac, video=h264")
        QP.subprocess.run = _run_mit(_Lauf(1, "", "HTTP error 403 Forbidden"))
        assert QP.probe_ffprobe("https://h/x.flv", "") == (False, "HTTP error 403 Forbidden")
        QP.subprocess.run = _run_mit(_sp.TimeoutExpired("ffprobe", 30))
        assert QP.probe_ffprobe("https://h/x.flv", "") == (False, "Zeitüberschreitung")

        # Live-Seite: SOCKS ehrlich abgelehnt, Netzfehler mit Grund,
        # eingebettete Adresse gefunden, Captcha erkannt.
        assert "SOCKS" in QP.probe_html("x", "socks5://h:1")[1]

        class _Opener:
            def __init__(self, inhalt=None, fehler=None):
                self.inhalt, self.fehler = inhalt, fehler
            def open(self, req, timeout=0):
                if self.fehler:
                    raise self.fehler
                return _io.BytesIO(self.inhalt.encode())
        QP.urllib.request.build_opener = lambda *h: _Opener(fehler=OSError("verbindung weg"))
        assert QP.probe_html("x", "http://p:8") == ([], "OSError: verbindung weg")
        seite = ('<script type="application/json">kein json</script>'
                 '<script id="SIGI" type="application/json">%s</script>' % _json.dumps(
                     {"LiveRoom": {"streamUrl": {"hls_pull_url": "https://h/l.m3u8"}}}))
        QP.urllib.request.build_opener = lambda *h: _Opener(seite)
        f, fehler = QP.probe_html("x", "")
        assert fehler is None and f[0]["form"] == "hls", (f, fehler)
        QP.urllib.request.build_opener = lambda *h: _Opener("<div>captcha</div>")
        assert "Captcha" in QP.probe_html("x", "")[1]
        QP.urllib.request.build_opener = lambda *h: _Opener("<html></html>")
        assert QP.probe_html("x", "")[1] == "keine Stream-Adresse im HTML"

        # Durchreicher: zaehlt Bytes, raeumt den Prozess immer ab.
        lesefd, schreibfd = _os.pipe()
        _os.write(schreibfd, b"x" * 3000)
        _os.close(schreibfd)

        class _P:
            stdout = _os.fdopen(lesefd, "rb")
            beendet = []
            def poll(self):
                return None
            def kill(self):
                self.beendet.append("kill")
            def wait(self, timeout=0):
                self.stdout.close()
        QP.subprocess.Popen = lambda *a, **k: _P()
        QP.time.sleep = lambda s: None
        assert QP.probe_durchreicher("x", "http://p:8", "/c.txt", grenze=2000, frist=5) >= 2000
        assert _P.beendet == ["kill"], "yt-dlp-Prozess nicht beendet"
    finally:
        (QP.shutil.which, QP.subprocess.run, QP.subprocess.Popen,
         QP.urllib.request.build_opener, QP.time.sleep) = alt

    # Kommandozeile: --json gibt das Ergebnis aus, --ohne-proxy wirkt.
    alt_m, alt_e = QP.messen, QP._env
    try:
        aufrufe = []
        QP._env = lambda: ("http://p:8", None)
        QP.messen = lambda n, p, c, ausgabe=print: aufrufe.append((n, p)) or {"empfehlung": "e"}
        puffer = _io.StringIO()
        with _cl.redirect_stdout(puffer):
            assert QP.main(["@probe", "--ohne-proxy", "--json"]) == 0
        assert aufrufe == [("probe", "")] and '"empfehlung": "e"' in puffer.getvalue()
    finally:
        QP.messen, QP._env = alt_m, alt_e
    p, c = QP._env()
    assert isinstance(p, str) and (c is None or c.endswith("tiktok_cookies.txt"))

    # Sicherungspruefung: fehlender und leerer Dump.
    from nc import sicherungspruefung as S
    d = _ph.verzeichnis("nc-pruef-w142b-")
    leer = _os.path.join(d, "leer.sql")
    open(leer, "w").close()
    assert S.dump_vollstaendig(_os.path.join(d, "fehlt.sql")) == (False, "Dump fehlt")
    assert S.dump_vollstaendig(leer) == (False, "Dump ist leer")
    ok("W142: Quellprobe-Wege mit Attrappen — Fehlerpfade mit Grund, Zugangsdaten "
       "maskiert, Prozess immer beendet; Kommandozeile und Sicherungs-Randfaelle")


# MariaDB-Schluesselwoerter, die als Spaltenname vorkommen koennten. Zwei davon
# (`lines`, `trigger`) standen im Schema und brachen JEDEN MariaDB-Start (1064).
_W143_RESERVIERT = {
    "lines", "trigger", "key", "keys", "order", "group", "range", "read", "write",
    "interval", "condition", "usage", "signal", "index", "desc", "option",
    "release", "references", "match", "limit", "load", "lock", "change", "column",
    "check", "default", "delete", "select", "table", "to", "update", "values",
    "where", "with", "primary", "schema", "div", "mod", "sql", "starting",
    "separator", "leading", "trailing", "both", "rlike", "regexp", "return",
    "row_number", "over", "window", "recursive", "except", "intersect",
}


def _w143_schema_mariadb():
    """Das Schema, wie es gegen MariaDB ginge — mitgeschnitten, ohne Server."""
    import logging as _lg
    from nc import schema as S

    class _R:
        def fetchall(self):
            return []

        def fetchone(self):
            return None

        def __iter__(self):
            return iter([])

    class _C:
        def __init__(self):
            self.sql = []

        def execute(self, q, p=()):
            self.sql.append(q)
            return _R()

        def commit(self):
            pass

        def cursor(self):
            return self

    c = _C()
    S.anlegen(c, backend="mariadb", mariadb_db="x", log=_lg.getLogger("w143"))
    return c.sql


def _w143_tabellen(sqls):
    """{tabelle: {spalte: (typ, gequotet)}} und [(tabelle, [schluesselspalten])]."""
    import re as _re
    spalten, schluessel = {}, []
    for q in sqls:
        m = _re.match(r"\s*CREATE TABLE IF NOT EXISTS\s+(\w+)\s*\((.*)\)[^)]*$", q, _re.S)
        if m:
            t, rumpf = m.group(1), m.group(2)
            teile, tiefe, akt = [], 0, ""
            for ch in rumpf:
                tiefe += (ch == "(") - (ch == ")")
                if ch == "," and tiefe == 0:
                    teile.append(akt)
                    akt = ""
                else:
                    akt += ch
            teile.append(akt)
            sp = spalten.setdefault(t, {})
            for teil in (x.strip() for x in teile if x.strip()):
                k = _re.match(r"(?:PRIMARY KEY|UNIQUE(?: KEY)?|KEY|INDEX)\s*\w*\s*\(([^)]*)\)",
                              teil, _re.I)
                if k:
                    schluessel.append((t, [x.strip(" `").split("(")[0]
                                           for x in k.group(1).split(",")]))
                    continue
                if _re.match(r"(FOREIGN|CONSTRAINT|CHECK)\b", teil, _re.I):
                    continue
                n = _re.match(r"(`?)(\w+)\1\s+(.*)", teil, _re.S)
                name, typ = n.group(2), n.group(3)
                sp[name] = (typ.split()[0].upper(), bool(n.group(1)))
                if _re.search(r"\b(PRIMARY KEY|UNIQUE)\b", typ, _re.I):
                    schluessel.append((t, [name]))
            continue
        m = _re.match(r"\s*CREATE (?:UNIQUE )?INDEX\s+\w+\s+ON\s+(\w+)\s*\(([^)]*)\)", q, _re.I)
        if m:
            schluessel.append((m.group(1), [x.strip(" `").split("(")[0].split()[0]
                                            for x in m.group(2).split(",")]))
    return spalten, schluessel


def _test_v42_w143_mariadb_schema_und_dialekt():
    """v4.2-W143: das MariaDB-Schema war nie lauffaehig.

    Gemessen beim ersten Umzug gegen einen echten MariaDB 10.11: zwei Spalten
    hiessen wie reservierte Woerter (`lines`, `trigger` — 1064), und neun
    indizierte Spalten waren TEXT (1071, Schluessel zu lang). Der Bot haette
    auf MariaDB keinen einzigen Start ueberstanden; die Verlagerung ins
    Schema-Modul hatte das nur nie gegen einen Server gefahren. Dazu zwei
    Upserts in reinem SQLite (`ON CONFLICT`), die auf MariaDB still nie
    buchten. Gesichert wird hier ohne Server — die Aussagen sind statisch."""
    import ast as _ast
    import glob as _glob
    import sqlite3 as _sq
    from nc import sqldialekt as D

    sqls = _w143_schema_mariadb()
    spalten, schluessel = _w143_tabellen(sqls)
    assert len(spalten) >= 40, "Schema-Mitschnitt zu klein: %d Tabellen" % len(spalten)

    # (1) Kein Schluessel auf einer TEXT-Spalte (1071).
    text = {"TEXT", "MEDIUMTEXT", "LONGTEXT", "BLOB"}
    falsch = sorted({"%s.%s=%s" % (t, c, spalten[t][c][0]) for t, cols in schluessel
                     for c in cols if t in spalten and c in spalten[t]
                     and spalten[t][c][0] in text})
    assert not falsch, "indizierte TEXT-Spalten (MariaDB 1071): %s" % falsch
    assert sum(len(c) for _, c in schluessel) >= 40, "Schluessel-Erkennung erfasst zu wenig"

    # (2) Kein reserviertes Wort als ungequoteter Spaltenname (1064).
    roh = sorted("%s.%s" % (t, c) for t, sp in spalten.items() for c, (_, q) in sp.items()
                 if c.lower() in _W143_RESERVIERT and not q)
    assert not roh, "reservierte Spaltennamen ohne Backticks (MariaDB 1064): %s" % roh
    assert spalten["stream_memories"]["lines"][1] and spalten["evolution_log"]["trigger"][1]

    # (3) Die Platzhalter: auf SQLite bleibt alles TEXT — keine Bedeutungsaenderung.
    from nc import schema as S
    ps, pm = S.parameter("sqlite"), S.parameter("mariadb")
    assert ps["ts"] == ps["txt_idx"] == ps["txt_long"] == "TEXT"
    assert pm["ts"].startswith("VARCHAR") and pm["txt_idx"].startswith("VARCHAR")

    # (4) Der Upsert-Baustein in beiden Dialekten — und die SQLite-Form laeuft.
    assert D.bei_konflikt("sqlite", "k", ["a=excluded.a"]) == \
        "ON CONFLICT(k) DO UPDATE SET a=excluded.a"
    assert D.bei_konflikt("mariadb", "g,u", ["a=excluded.a", "b=b+?"]) == \
        "ON DUPLICATE KEY UPDATE a=VALUES(a), b=b+?"
    con = _sq.connect(":memory:")
    con.execute("CREATE TABLE lp (k TEXT PRIMARY KEY, name TEXT, points INT)")
    q = ("INSERT INTO lp (k, name, points) VALUES (?,?,?) "
         + D.bei_konflikt("sqlite", "k", ["points=points+?", "name=?"]))
    for _ in range(2):
        con.execute(q, ("a", "n", 5, 5, "n2"))
    assert con.execute("SELECT name, points FROM lp").fetchall() == [("n2", 10)]

    # (5) Keine Schreibstelle spricht mehr ON CONFLICT am Baustein vorbei —
    # gemessen in Zeichenketten-Tokens, nicht im Rohtext (die Kommentare
    # nennen das Wort, W102-Lehre).
    roh_upsert = []
    for p in ["bot.py", "discordbot.py", "brain_bridge.py"] + _glob.glob("nc/**/*.py", recursive=True):
        if p.replace("\\", "/") == "nc/sqldialekt.py":
            continue
        for n in _ast.walk(_ast.parse(open(p, encoding="utf-8").read())):
            if isinstance(n, _ast.Constant) and isinstance(n.value, str) \
                    and "ON CONFLICT" in n.value.upper() and "INSERT" in n.value.upper():
                roh_upsert.append("%s:%d" % (p, n.lineno))
    assert not roh_upsert, "ON CONFLICT am Dialekt-Baustein vorbei: %s" % roh_upsert
    for p, tab in (("bot.py", "loyalty_points"), ("discordbot.py", "discord_daily")):
        src = open(p, encoding="utf-8").read()
        i = src.index("INSERT INTO %s" % tab)
        assert "_nc_sqldialekt.bei_konflikt(" in rumpf_ab(src, i), "%s: %s ohne Baustein" % (p, tab)

    # (6) Die Abfragen auf die umbenannt-gequoteten Spalten quoten ebenfalls.
    for p in ("nc/evolution.py", "nc/routes/evolution.py", "bot.py"):
        for n in _ast.walk(_ast.parse(open(p, encoding="utf-8").read())):
            if isinstance(n, _ast.Constant) and isinstance(n.value, str):
                v = n.value
                for tab, sp in (("evolution_log", "trigger"), ("stream_memories", "lines")):
                    if tab in v and ("SELECT" in v or "INSERT" in v) and " %s" % sp in v.replace(",", " "):
                        raise AssertionError("%s:%d: %s.%s ungequotet" % (p, n.lineno, tab, sp))
    ok("W143: MariaDB-Schema ohne 1064/1071, Upserts in beiden Dialekten")


def _w143_quelle(pfad, extra=False):
    """Eine SQLite-Quelle mit echtem Schema und ein paar Zeilen."""
    import logging as _lg
    from nc import dbwrap as W
    from nc import schema as S
    W.configure_db(db_path=pfad, backend="sqlite")
    with W.db_conn() as c:
        S.anlegen(c, backend="sqlite", mariadb_db="", log=_lg.getLogger("w143"))
        for i in range(3):
            c.execute("INSERT INTO trackings (group_id, username, created_at) VALUES (?,?,?)",
                      (100 + i, "nutzer_%d" % i, "2026-11-05T10:00:0%d" % i))
        c.execute("INSERT INTO evolution_log (`trigger`, ts) VALUES (?,?)", ("probe", "2026-11-05"))
        c.execute("INSERT INTO loyalty_points (k, name, points, updated) VALUES (?,?,?,?)",
                  ("tt:a", "A 'mit' Quote", 7, "2026-11-05"))
        if extra:
            c.execute("CREATE TABLE altlast (x TEXT)")
            c.execute("INSERT INTO altlast VALUES ('weg')")


def _test_v42_w143_umzug_kette():
    """v4.2-W143: der Umzug als Kette — dieselbe wie gegen MariaDB, mit einer
    zweiten SQLite-Datei als Ziel. Jede Abbruchstelle ist eine, an der vorher
    still etwas verloren ging oder doppelt kam."""
    import io as _io
    import contextlib as _cl
    import importlib.util as _iu
    import logging as _lg
    import os as _os
    import stat as _st
    import time as _t
    from nc import dbwrap as W
    from nc import mariadbumzug as U

    alt = (W.DB_PATH, W.DB_BACKEND)
    log = _lg.getLogger("w143")
    d = _ph.verzeichnis()
    try:
        src, dst = _os.path.join(d, "quelle.db"), _os.path.join(d, "ziel.db")
        _w143_quelle(src)
        vorher = open(src, "rb").read()
        aus = []
        b = U.umziehen(sqlite_pfad=src, ziel_backend="sqlite", mariadb={"db_path": dst},
                       log=log, ausgabe=aus.append, trotzdem_aktiv=True)
        assert b["trocken"] is False and b["zeilen"] >= 5, b
        q, z = U.quelle_zaehlen(src), None
        W.configure_db(db_path=dst, backend="sqlite")
        z = U.ziel_zaehlen(q)
        assert U.vergleichen(q, z) == [] and z["trackings"] == 3, (q, z)
        assert U.vergleichen({"a": 2, "b": 1}, {"a": 1, "b": 1}) == [("a", 2, 1)]
        assert U.vergleichen({"a": 0}, {}) == [("a", 0, None)], "fehlende Tabelle gilt als gleich"
        with W.db_conn() as c:
            r = c.execute("SELECT name, points FROM loyalty_points").fetchone()
        assert (r["name"], r["points"]) == ("A 'mit' Quote", 7), dict(r)
        assert open(src, "rb").read() == vorher, "die Quelle wurde veraendert"

        # (0) Haelt jemand die Quelle offen, wird nicht umgezogen — vor jedem
        # Schreibzugriff, und ohne dass das Ziel entsteht.
        alt_ib = U.in_benutzung
        try:
            U.in_benutzung = lambda pfad: True
            try:
                U.umziehen(sqlite_pfad=src, ziel_backend="sqlite",
                           mariadb={"db_path": _os.path.join(d, "offen.db")}, log=log,
                           ausgabe=aus.append)
                raise AssertionError("Umzug lief, waehrend die Quelle offen war")
            except U.UmzugAbgebrochen as e:
                assert "Dienst stoppen" in str(e), e
            assert not _os.path.exists(_os.path.join(d, "offen.db")), "Ziel trotz Abbruch angelegt"
        finally:
            U.in_benutzung = alt_ib

        # (a) Ein nicht leeres Ziel wird nicht ueberschrieben — der zweite Lauf
        # bricht ab, statt jede Zeile doppelt einzutragen.
        try:
            U.umziehen(sqlite_pfad=src, ziel_backend="sqlite", mariadb={"db_path": dst},
                       log=log, ausgabe=aus.append, trotzdem_aktiv=True)
            raise AssertionError("zweiter Umzug ins volle Ziel lief durch")
        except U.UmzugAbgebrochen as e:
            assert "nicht leer" in str(e) and "trackings=3" in str(e), e

        # (b) Trockenlauf: Ziel geprueft, nichts geschrieben.
        dst2 = _os.path.join(d, "trocken.db")
        b = U.umziehen(sqlite_pfad=src, ziel_backend="sqlite", mariadb={"db_path": dst2},
                       log=log, ausgabe=aus.append, trotzdem_aktiv=True, trocken=True)
        assert b["trocken"] is True
        W.configure_db(db_path=dst2, backend="sqlite")
        assert all(n is None for n in U.ziel_zaehlen(q).values()), "Trockenlauf hat geschrieben"

        # (c) Tabellen, die das Schema nicht kennt: Abbruch mit Abhilfe, dann
        # bewusst ausgelassen — derselbe Zielordner ist danach weiter nutzbar.
        src3, dst3 = _os.path.join(d, "alt.db"), _os.path.join(d, "ziel3.db")
        _w143_quelle(src3, extra=True)
        try:
            U.umziehen(sqlite_pfad=src3, ziel_backend="sqlite", mariadb={"db_path": dst3},
                       log=log, ausgabe=aus.append, trotzdem_aktiv=True)
            raise AssertionError("unbekannte Tabelle zog still nicht mit")
        except U.UmzugAbgebrochen as e:
            assert "altlast" in str(e) and "--auslassen altlast" in str(e), e
        b = U.umziehen(sqlite_pfad=src3, ziel_backend="sqlite", mariadb={"db_path": dst3},
                       log=log, ausgabe=aus.append, trotzdem_aktiv=True, auslassen=["altlast"])
        assert b["trocken"] is False

        # (d) Kaputte und fehlende Quelle: ein Satz mit Abhilfe, kein Traceback.
        kaputt = _os.path.join(d, "kaputt.db")
        with open(kaputt, "wb") as f:
            f.write(b"\x16\x03\x01\x00\x2d" + b"x" * 4096)
        for pfad, text in ((kaputt, "nicht lesbar"), (_os.path.join(d, "nix.db"), "nicht gefunden")):
            try:
                U.quelle_zaehlen(pfad)
                raise AssertionError("%s ohne Abbruch" % pfad)
            except U.UmzugAbgebrochen as e:
                assert text in str(e), e

        # (e) „Laeuft der Bot noch?" — ein offenes Handle, nicht die mtime.
        proc = _os.path.join(d, "proc")
        _os.makedirs(_os.path.join(proc, "4711", "fd"))
        _os.makedirs(_os.path.join(proc, "4712", "fd"))
        _os.symlink(_os.path.realpath(src) + "-wal", _os.path.join(proc, "4711", "fd", "3"))
        _os.symlink("/dev/null", _os.path.join(proc, "4712", "fd", "0"))
        _os.makedirs(_os.path.join(proc, "self"))
        assert U.geoeffnet_von(src, proc=proc) == [4711]
        assert U.in_benutzung(src, proc=proc) is True
        _os.remove(_os.path.join(proc, "4711", "fd", "3"))
        # Frisch gestoppt heisst: Datei gerade geschrieben, aber niemand haelt
        # sie. Die mtime-Regel verweigerte genau diesen sicheren Fall.
        _os.utime(src, None)
        assert U.in_benutzung(src, proc=proc) is False
        # Ein Prozess, dessen Handles wir nicht lesen duerfen: „keiner
        # gefunden" waere gelogen — unbekannt, also gilt die Zeitregel.
        _os.makedirs(_os.path.join(proc, "4713", "fd"))
        alt_fd = U._fd_ziele

        def _gesperrt(fd_dir):
            if fd_dir.endswith(_os.path.join("4713", "fd")):
                raise PermissionError(13, "Permission denied", fd_dir)
            return alt_fd(fd_dir)
        try:
            U._fd_ziele = _gesperrt
            assert U.geoeffnet_von(src, proc=proc) is None
            _os.symlink(_os.path.realpath(src), _os.path.join(proc, "4712", "fd", "4"))
            assert U.geoeffnet_von(src, proc=proc) == [4712], "Fund trotz Unlesbarem verworfen"
            _os.remove(_os.path.join(proc, "4712", "fd", "4"))
        finally:
            U._fd_ziele = alt_fd
        _os.rmdir(_os.path.join(proc, "4713", "fd"))
        _os.rmdir(_os.path.join(proc, "4713"))
        ohne = _os.path.join(d, "kein-proc")
        assert U.geoeffnet_von(src, proc=ohne) is None
        m = _os.path.getmtime(src)
        assert U.in_benutzung(src, jetzt=m + 5, proc=ohne) is True
        assert U.in_benutzung(src, jetzt=m + U.RUHE_S + 5, proc=ohne) is False

        # (f) Verbindungsrat: jede bekannte Lage mit Abhilfe.
        mdb = {"host": "h", "port": 1, "db": "ncdb"}
        for fehler, erwartet in (
                (ImportError("No module named 'pymysql'"), "PyMySQL fehlt"),
                (Exception("(1045, 'Access denied')"), "MARIADB_PASSWORD"),
                (Exception("(1049, \"Unknown database\")"), "'ncdb'"),
                (Exception("(2003, \"Can't connect\")"), "systemctl status mariadb"),
                (Exception("sonstwas"), "MariaDB nicht nutzbar")):
            assert erwartet in U._verbindungsrat(fehler, mdb), (fehler, U._verbindungsrat(fehler, mdb))

        # (g) env_setzen: letzter Schluessel gewinnt, Rest unveraendert,
        # Sicherung mit denselben Rechten, atomar (kein Rest).
        env = _os.path.join(d, ".env")
        with open(env, "w") as f:
            f.write("DB_BACKEND=sqlite\nBOT_TOKEN=geheim\n# DB_BACKEND=kommentar\n"
                    "DB_BACKEND = sqlite2\n")
        _os.chmod(env, 0o600)
        sich = U.env_setzen(env, {"DB_BACKEND": "mariadb", "MARIADB_HOST": "127.0.0.1",
                                  "NICHT_IM_SATZ": "x"}, jetzt=_t.time())
        neu = open(env).read().splitlines()
        assert neu == ["DB_BACKEND=sqlite", "BOT_TOKEN=geheim", "# DB_BACKEND=kommentar",
                       "DB_BACKEND=mariadb", "MARIADB_HOST=127.0.0.1"], neu
        assert open(sich).read().startswith("DB_BACKEND=sqlite\nBOT_TOKEN=geheim")
        assert ".vor-mariadb-" in sich
        assert _st.S_IMODE(_os.stat(env).st_mode) == 0o600
        assert _st.S_IMODE(_os.stat(sich).st_mode) == 0o600
        assert not _os.path.exists(env + ".tmp-umzug")

        # (h) tools/zu_mariadb.py: die .env wird NUR nach gelungenem Umzug
        # umgestellt, das Passwort steht nie in der Ausgabe.
        spec = _iu.spec_from_file_location("w143_zu_mariadb", "tools/zu_mariadb.py")
        Z = _iu.module_from_spec(spec)
        spec.loader.exec_module(Z)
        inst = _os.path.join(d, "inst")
        _os.makedirs(inst)
        ienv = _os.path.join(inst, ".env")

        def _env(text):
            with open(ienv, "w") as f:
                f.write(text)

        gerufen = []
        alt_um = Z.U.umziehen
        try:
            Z.U.umziehen = lambda **kw: gerufen.append(kw) or {"trocken": kw.get("trocken")}
            _env("DB_BACKEND=sqlite\nMARIADB_PASSWORD='PW_GEHEIM_43'\nDB_PATH=bot.db\n")
            puffer = _io.StringIO()
            with _cl.redirect_stdout(puffer), _cl.redirect_stderr(puffer):
                assert Z.main(["--dir", inst, "--dry-run"]) == 0
                assert "DB_BACKEND=sqlite" in open(ienv).read(), "Trockenlauf stellte um"
                assert Z.main(["--dir", inst, "--auslassen", "a,b"]) == 0
            assert "PW_GEHEIM_43" not in puffer.getvalue(), "Passwort in der Ausgabe"
            assert gerufen[-1]["sqlite_pfad"] == _os.path.join(inst, "bot.db")
            assert gerufen[-1]["mariadb"]["password"] == "PW_GEHEIM_43"
            assert gerufen[-1]["auslassen"] == ["a", "b"]
            e = Z._env_lesen(ienv)
            assert e["DB_BACKEND"] == "mariadb" and e["MARIADB_PASSWORD"] == "PW_GEHEIM_43", e
            with _cl.redirect_stdout(puffer):
                assert Z.main(["--dir", inst]) == 0          # schon auf MariaDB
            _env("DB_BACKEND=sqlite\n")
            with _cl.redirect_stderr(puffer):
                assert Z.main(["--dir", inst]) == 2          # kein Passwort

            def _bricht(**kw):
                raise U.UmzugAbgebrochen("Grund mit Abhilfe")
            Z.U.umziehen = _bricht
            _env("DB_BACKEND=sqlite\nMARIADB_PASSWORD=x\n")
            with _cl.redirect_stderr(puffer):
                assert Z.main(["--dir", inst]) == 1
            assert "DB_BACKEND=sqlite" in open(ienv).read(), "Abbruch stellte trotzdem um"
            with _cl.redirect_stderr(puffer):
                assert Z.main(["--dir", _os.path.join(d, "leer")]) == 2   # keine .env
        finally:
            Z.U.umziehen = alt_um
    finally:
        W.configure_db(db_path=alt[0], backend=alt[1])
    ok("W143: Umzug zaehlt nach, ueberschreibt nichts, stellt die .env erst danach um")


def _test_v42_w143_update_mariadb():
    """v4.2-W143: update.sh fragt nach Zusatzfunktionen und zieht auf Wunsch um.

    Zwei Zusagen, an denen der Rest haengt: ein Zeitplan (kein Terminal, kein
    Schalter) loest NIE einen Umzug aus, und das Datenbank-Passwort steht nie
    in einer Befehlszeile — auch nicht im Trockenlauf."""
    import subprocess as _sp
    d, ziel, proto, umg = _w123_sandbox(fehlt=())
    with open(os.path.join(ziel, ".env"), "w") as f:
        f.write("DB_BACKEND=sqlite\nMARIADB_PASSWORD=PW_GEHEIM_W143\n")
    with open(os.path.join(ziel, "tiktok_bot.db"), "wb") as f:
        f.write(b"SQLite format 3\0" + b"\0" * 100)

    rc, aus = _w123_update(ziel, umg, "--dry-run")
    assert rc == 0, (rc, aus)
    assert "Zusatzfunktionen" in aus and "Datenbank: SQLite" in aus, aus
    assert "zu_mariadb.py" not in aus, "ohne Schalter und ohne Terminal im Plan: Umzug"

    rc, aus = _w123_update(ziel, umg, "--dry-run", "--mariadb")
    assert rc == 0, (rc, aus)
    assert "nc_mariadb_sql nightcrawler nightcrawler *** |" in aus, aus
    assert "NC_MARIADB_PASSWORD=***" in aus and "zu_mariadb.py --dir %s" % ziel in aus, aus
    assert "PW_GEHEIM_W143" not in aus, "Passwort in der Ausgabe des Trockenlaufs"
    assert open(proto).read() == "", "Trockenlauf hat etwas ausgefuehrt: %r" % open(proto).read()
    # PyMySQL kommt im Umzug selbst, VOR dem Stopp — nicht ueber PY_FEHLT, das
    # nur mit --python-deps laeuft (Codex, PR #191).
    # Das venv der Attrappe kennt pymysql bewusst NICHT — sonst hinge die
    # Aussage davon ab, ob die pruefende Maschine es zufaellig hat.
    vpy = os.path.join(ziel, ".venv", "bin", "python")
    roh = open(vpy).read()
    with open(vpy, "w") as f:
        f.write(roh.replace('exec "', 'case "$*" in *"import pymysql"*) exit 1;; esac\nexec "', 1))
    for schalter in (("--mariadb",), ("--mariadb", "--system")):
        rc2, aus2 = _w123_update(ziel, umg, "--dry-run", *schalter)
        assert rc2 == 0, (schalter, aus2)
        i = aus2.find("-m pip install PyMySQL>=1.1.1")
        assert 0 <= i < aus2.index("zu_mariadb.py --dir"), \
            "%s: PyMySQL fehlt im Plan oder kommt erst nach dem Umzug" % (schalter,)
    # Und echt, nicht nur im Plan: pip laeuft VOR dem Umzug. Die Attrappe
    # protokolliert pip und kennt pymysql danach immer noch nicht — also
    # muss der Umzug mit Grund abbrechen und die .env auf sqlite lassen.
    with open(proto, "w"):
        pass
    cli = os.path.join(umg["PATH"], "mariadb")
    with open(cli, "w") as f:
        f.write("#!/bin/sh\ncat >/dev/null\nexit 0\n")
    os.chmod(cli, 0o755)
    rc3, aus3 = _w123_update(ziel, umg, "-y", "--mariadb")
    p3 = open(proto).read()
    assert "pip -m pip install PyMySQL>=1.1.1" in p3, (p3, aus3)
    # Welcher Riegel greift, haengt an der Maschine (ohne lesbares /proc
    # zuerst die Zeitregel, sonst das fehlende PyMySQL) — abgebrochen wird so
    # oder so, und zwar mit Grund.
    assert rc3 == 1 and "Umzug abgebrochen" in aus3 and "ABGEBROCHEN:" in aus3, (rc3, aus3)
    assert "DB_BACKEND=sqlite" in open(os.path.join(ziel, ".env")).read(), "Abbruch stellte trotzdem um"
    with open(vpy, "w") as f:
        f.write(roh)

    with open(os.path.join(ziel, ".env"), "w") as f:
        f.write("DB_BACKEND=mariadb\n")
    rc, aus = _w123_update(ziel, umg, "--dry-run", "--mariadb")
    assert rc == 0 and "schon auf mariadb" in aus and "zu_mariadb.py" not in aus, aus

    # Das SQL fuer Datenbank und Nutzer: Anfuehrungszeichen verdoppelt, ein
    # zweiter Lauf gleicht nur an.
    r = _sp.run(["bash", "-c", '. tools/lib/system.sh; nc_mariadb_sql ncdb ncnu "a\'b\\\\c"'],
                capture_output=True, text=True, timeout=30)
    assert r.returncode == 0, r.stderr
    # Anfuehrungszeichen verdoppelt, Backslash verdoppelt (sonst ein Escape).
    assert "IDENTIFIED BY 'a''b\\\\c'" in r.stdout, r.stdout
    assert "CREATE DATABASE IF NOT EXISTS `ncdb`" in r.stdout
    # Drei Hosts (Codex, PR #191): mit skip-name-resolve passt eine
    # TCP-Verbindung von 127.0.0.1 nicht auf @'localhost' (1130).
    for h in ("localhost", "127.0.0.1", "::1"):
        assert "ALTER USER 'ncnu'@'%s'" % h in r.stdout and "TO 'ncnu'@'%s'" % h in r.stdout, h

    # Der Installer schaltet nicht auf eine leere MariaDB um, wenn in SQLite
    # schon Daten liegen — er verweist auf den Umzug.
    inst = open("tools/installer.sh", encoding="utf-8").read()
    i = inst.index("f_datenbank(){")
    rumpf = inst[i:inst.index("\n}\n", i)]
    # ANKER GEWANDERT (v5.3-W194, nicht der Vertrag): seit MariaDB die Vorgabe
    # ist, vergleicht der Riegel gegen den STAND der .env, nicht gegen die
    # Vorgabe — "vor" waere bei einer neuen Installation jetzt mariadb.
    assert '[ "$(env_bisher DB_BACKEND | tr \'A-Z\' \'a-z\')" != "mariadb" ] && [ -s "$_sq" ]' in rumpf, \
        "Installer-Riegel fehlt"
    assert "update.sh --mariadb" in rumpf
    assert "nc_mariadb_sql" in inst and "IDENTIFIED BY" not in inst, \
        "Installer baut das Nutzer-SQL wieder selbst"
    ok("W143: update.sh zieht nur auf Wunsch um, nie mit Passwort in der Zeile")


def _test_v42_w144_jeder_messwert_ein_panel():
    """v4.2-W144: „alles maximal detailliert" — als Zusage, nicht als Eindruck.

    Das Dashboard aus W127 zeigte 32 der 52 Messwerte, und /metrics selbst
    kannte die Haelfte dessen nicht, was /healthz wusste: Pruefstand der
    Trackings, woher die Stream-Adressen kamen, Tunnel, Update-Lage, Schema.
    Jetzt traegt der Schnappschuss diese Werte, und dieser Vertrag faellt,
    sobald ein Messwert ohne Panel bleibt — ein neuer Wert, den niemand
    anzeigt, ist derselbe Fall wie vorher, nur eine Welle spaeter."""
    import ast as _ast
    import json as _json
    import re as _re
    from nc import (gegendruck, kennzahlen as kz, kindprozess, livecache, looplag,
                    speicherpflege)

    # (1) Die Schluessel des Schnappschusses sind die, mit denen gemessen wird.
    baum = _ast.parse(open("bot.py", encoding="utf-8").read())

    def _schluessel(fn, ziel_name=None):
        f = next(n for n in baum.body if isinstance(n, _ast.FunctionDef) and n.name == fn)
        for n in _ast.walk(f):
            if isinstance(n, _ast.Dict) and n.keys and all(isinstance(k, _ast.Constant) for k in n.keys):
                if ziel_name is None or ziel_name in [k.value for k in n.keys]:
                    return [k.value for k in n.keys]
        raise AssertionError("kein Woerterbuch in %s" % fn)

    zusatz = _w144_schnappschuss_zusatz()
    basis = ["loop_lag", "gegendruck", "livecache", "kinder", "speicher", "log", "prozess",
             "betrieb", "start_s"]
    assert _schluessel("_leistung_erheben", "loop_lag") == basis + ["quellen", "pruefung", "zustand"]
    assert set(_schluessel("_zustand_kennzahlen")) == set(zusatz["zustand"]), \
        "Vertrag und bot._zustand_kennzahlen laufen auseinander"
    assert tuple(_schluessel("_speicher_maps")) == _W144_MAPS

    # (2) Alle Namen, die /metrics liefert …
    rb = _ast.parse(open("nc/routes/beobachtung.py", encoding="utf-8").read())
    namen = {n.args[0].value for n in _ast.walk(rb)
             if isinstance(n, _ast.Call) and getattr(n.func, "id", "") == "metric"
             and n.args and isinstance(n.args[0], _ast.Constant)}
    daten = {"loop_lag": looplag.lage(), "gegendruck": gegendruck.lage(1, 4, 0, 10),
             "livecache": livecache.statistik(0, 0), "kinder": kindprozess.lage(),
             "speicher": speicherpflege.groessen({}), "log": {"wartend": 0, "verloren": 0},
             "prozess": kz.prozess(), "betrieb": {"restreams": 0, "chat_clients": 0, "aufnahmen": 0},
             "start_s": 1.0}
    daten.update(zusatz)
    namen |= set(_re.findall(r"^(nightcrawler_\w+) ", kz.prometheus(daten, alter_s=1), _re.M))
    assert len(namen) >= 70, len(namen)

    # … stehen in mindestens einem Panel.
    dash = _json.load(open("deploy/observability/grafana/dashboards/nightcrawler.json", encoding="utf-8"))
    ausdruecke = " ".join(t["expr"] for p in dash["panels"] for t in p.get("targets", []))
    benutzt = set(_re.findall(r"nightcrawler_\w+", ausdruecke))
    ohne = sorted(namen - benutzt)
    assert not ohne, "Messwerte ohne Panel: %s" % ohne
    # Jedes Panel ausser den Reihen hat eine Erklaerung — ein Diagramm ohne
    # Satz dazu sagt dem Betreiber nicht, ab wann es ein Befund ist.
    stumm = [p["title"] for p in dash["panels"] if p["type"] != "row"
             and p["id"] > 24 and not p.get("description")]
    assert not stumm, "Panels ohne Beschreibung: %s" % stumm
    gp = [(p["gridPos"]["x"], p["gridPos"]["y"]) for p in dash["panels"]]
    assert len(gp) == len(set(gp)), "zwei Panels auf demselben Platz"
    assert all(p["gridPos"]["x"] + p["gridPos"]["w"] <= 24 for p in dash["panels"])

    # (3) Zustaende als 0/1 — immer alle, Unbekanntes unter "sonstig".
    assert kz.einwertig("ok", ("ok", "fehler")) == {"ok": 1, "fehler": 0, "sonstig": 0}
    assert kz.einwertig("neu", ("ok", "fehler")) == {"ok": 0, "fehler": 0, "sonstig": 1}
    t = kz.prometheus({"zustand": {"tunnel": kz.einwertig("fehler", ("ok", "fehler"))}})
    assert "nightcrawler_zustand_tunnel_fehler 1" in t and "nightcrawler_zustand_tunnel_ok 0" in t

    # (4) Die Regeln fuer die neuen Zustaende gibt es — und sie fragen nur
    # Namen, die /metrics liefert (das prueft W127 fuer alle).
    import yaml as _yaml
    regeln = {r["alert"]: r for g in _yaml.safe_load(open(
        "deploy/observability/rules/nightcrawler.yml", encoding="utf-8"))["groups"] for r in g["rules"]}
    for n in ("NightcrawlerTrackingsUeberfaellig", "NightcrawlerOhneStreamAdresse",
              "NightcrawlerTunnelFehler", "NightcrawlerUpdateNichtWirksam",
              "NightcrawlerSchemaNeuerAlsCode", "NightcrawlerLogSynchron"):
        assert n in regeln, n
    assert regeln["NightcrawlerOhneStreamAdresse"]["expr"].startswith("max(100 *"), \
        "der Anteil muss links stehen — `and` liefert den linken Wert"
    ok("W144: jeder Messwert aus /metrics hat ein Panel, Zustaende als Zahlen, sechs neue Regeln")


def _test_v42_w144_envdatei_und_grafana():
    """v4.2-W144: Prometheus und Grafana stehen in der .env, Grafana nicht
    mehr auf admin/admin — und das Passwort taucht nirgends in einer Ausgabe
    oder Befehlszeile auf."""
    import io as _io
    import os as _os
    import stat as _st
    import subprocess as _sp
    from nc import envdatei as E

    # (1) nc/envdatei: dieselben Regeln wie beim Umzug, plus Riegel gegen
    # eingeschleuste Zeilen.
    d = _ph.verzeichnis()
    env = _os.path.join(d, ".env")
    with open(env, "w") as f:
        f.write("A=1\n# B=kommentar\nB=2\nB = 3\n")
    _os.chmod(env, 0o600)
    s = E.setzen(env, {"B": "neu", "C": "x y"}, "probe")
    assert open(env).read() == "A=1\n# B=kommentar\nB=2\nB=neu\nC=x y\n", open(env).read()
    assert ".probe-" in s and _st.S_IMODE(_os.stat(env).st_mode) == 0o600
    assert E.lesen(env) == {"A": "1", "B": "neu", "C": "x y"}
    for boese in ({"D": "1\nBOT_TOKEN=gekapert"}, {"D": "1\r"}, {"D E": "1"}, {"": "1"}):
        try:
            E.setzen(env, boese, "probe")
            raise AssertionError("angenommen: %r" % boese)
        except E.EnvdateiFehler:
            pass
    assert "gekapert" not in open(env).read()
    aus = _io.StringIO()
    import contextlib as _cl
    with _cl.redirect_stdout(aus):
        assert E.main([env, "probe"], stdin=_io.StringIO("C=x y\nGEHEIM=pw_w144\n")) == 0
        assert E.main([env, "probe"], stdin=_io.StringIO("GEHEIM=pw_w144\n")) == 0
    assert "pw_w144" not in aus.getvalue() and "gesetzt: GEHEIM" in aus.getvalue()
    assert "unveraendert" in aus.getvalue(), "zweiter Lauf schrieb trotzdem"
    with _cl.redirect_stderr(_io.StringIO()):
        assert E.main([_os.path.join(d, "fehlt"), "x"], stdin=_io.StringIO("")) == 2
        assert E.main([env, "probe"], stdin=_io.StringIO("D E=1\n")) == 1
        assert E.main(["nur-eins"]) == 2

    # (2) observability.sh in einer Attrappe: Prometheus-URL, und eine
    # bestehende Grafana bekommt ein erzeugtes Passwort ueber stdin.
    heim = _ph.verzeichnis()
    ziel = _os.path.join(heim, "bot")
    _os.makedirs(ziel)
    _os.symlink(_os.path.abspath("deploy"), _os.path.join(ziel, "deploy"))
    wurzel = _os.path.join(heim, "w")
    fake = _os.path.join(heim, "bin")
    _os.makedirs(fake)
    gpw = _os.path.join(heim, "grafana_pw")
    gargv = _os.path.join(heim, "grafana_argv")
    for name, rumpf in (
            ("systemctl", 'eval "u=\\${$#}"\ncase "$1" in\n'
                          '  list-unit-files) case "$*" in *grafana-server*) echo "grafana-server.service enabled";; esac; exit 0;;\n'
                          '  enable) touch "%s/aktiv.$u";;\n  is-active) [ -f "%s/aktiv.$u" ]; exit $?;;\n'
                          '  is-enabled) exit 1;;\nesac\nexit 0' % (heim, heim)),
            ("prometheus", "exit 0"),
            ("grafana", 'echo "$*" > "%s"\ncat > "%s"\nexit 0' % (gargv, gpw)),
            ("curl", "exit 7")):
        p = _os.path.join(fake, name)
        with open(p, "w") as f:
            f.write("#!/bin/sh\n" + rumpf + "\n")
        _os.chmod(p, 0o755)
    umg = dict(_os.environ, PATH=fake + ":" + _os.environ["PATH"], NC_OBS_WURZEL=wurzel,
               NC_INIT="systemd", NC_PKG="apt", NC_OBS_WARTEN="0", NC_LANG="de", NC_OBS_SUDO="")
    ienv = _os.path.join(ziel, ".env")
    with open(ienv, "w") as f:
        f.write("BOT_TOKEN=x\n")
    _os.chmod(ienv, 0o600)

    def lauf(*a):
        r = _sp.run(["bash", "tools/observability.sh", "--dir", ziel, "--no-color", *a],
                    capture_output=True, text=True, env=umg, timeout=120)
        return r.returncode, r.stdout + r.stderr

    rc, aus = lauf("--unattended", "--grafana", "--dry-run")
    assert ".env: PROMETHEUS_URL" in aus and "GF_SECURITY_ADMIN_PASSWORD=***" in aus, aus
    assert E.lesen(ienv) == {"BOT_TOKEN": "x"}, "Trockenlauf schrieb die .env"

    # Der Dienst liest seinen Datenpfad aus /etc/default/grafana-server —
    # bewusst NICHT die Vorgabe, damit die Probe sieht, dass er gelesen wird.
    _os.makedirs(_os.path.join(wurzel, "etc", "default"), exist_ok=True)
    with open(_os.path.join(wurzel, "etc", "default", "grafana-server"), "w") as f:
        f.write('GRAFANA_USER=grafana\nDATA_DIR="/srv/grafana-daten"\n')
    rc, aus = lauf("--unattended", "--grafana")
    e = E.lesen(ienv)
    assert e.get("PROMETHEUS_URL") == "http://127.0.0.1:9099", (e, aus)
    pw = e.get("GRAFANA_ADMIN_PASSWORD", "")
    assert len(pw) >= 20 and e.get("GRAFANA_URL") == "http://127.0.0.1:3000" \
        and e.get("GRAFANA_ADMIN_USER") == "admin", (e, aus)
    assert open(gpw).read().strip() == pw, "grafana cli bekam ein anderes Passwort"
    assert "--password-from-stdin" in open(gargv).read() and pw not in open(gargv).read(), \
        "Passwort in der Befehlszeile"
    # Dieselbe Datenbank wie der Dienst (Codex, PR #192) — sonst setzt die
    # CLI das Passwort in einer Grafana-Datenbank, die niemand benutzt.
    assert "cfg:default.paths.data=/srv/grafana-daten" in open(gargv).read(), open(gargv).read()
    assert pw not in aus, "Passwort in der Ausgabe"
    pd = _os.path.join(wurzel, "etc", "nightcrawler", "grafana.env")
    assert _st.S_IMODE(_os.stat(pd).st_mode) == 0o600 and pw in open(pd).read()
    assert _st.S_IMODE(_os.stat(ienv).st_mode) == 0o600, "Rechte der .env veraendert"
    assert "BOT_TOKEN=x" in open(ienv).read()
    assert "EnvironmentFile=-/etc/nightcrawler/grafana.env" in open(_os.path.join(
        wurzel, "etc", "systemd", "system", "grafana-server.service.d", "nightcrawler.conf")).read()

    # Zweiter Lauf: ein vorhandenes Passwort wird nie ueberschrieben.
    _os.remove(gpw)
    rc, aus = lauf("--unattended", "--grafana")
    assert E.lesen(ienv)["GRAFANA_ADMIN_PASSWORD"] == pw and not _os.path.exists(gpw), aus
    rc, aus = lauf("--check", "--grafana")
    assert "PROMETHEUS_URL fehlt" not in aus and "GRAFANA_ADMIN_PASSWORD fehlt" not in aus, aus
    with open(ienv, "w") as f:
        f.write("BOT_TOKEN=x\n")
    rc, aus = lauf("--check", "--no-grafana")
    assert rc == 1 and "PROMETHEUS_URL fehlt in der .env" in aus, aus

    # (3) Das Deck liest die Eintraege: fragt Prometheus nach up fuer den
    # Bot, Grafana nach /api/health — jede Lage mit eigenem Satz.
    from nc import beobachtungslage as BL
    import json as _json

    def _antwort(*werte):
        return lambda url: (200, _json.dumps({"data": {"result": [
            {"value": [0, w]} for w in werte]}}))

    def _tot(url):
        raise OSError("refused")
    assert BL.prometheus("", _antwort("1"))["grund"].startswith("PROMETHEUS_URL fehlt")
    r = BL.prometheus("http://p:9099/", _antwort("1"))
    assert r["liest_bot"] is True and r["erreichbar"] and not r["grund"], r
    gefragt = []
    BL.prometheus("http://p:9099/", lambda u: gefragt.append(u) or (200, '{"data":{"result":[]}}'))
    assert gefragt[0].startswith("http://p:9099/api/v1/query?query=up%7Bjob") and "//api" not in gefragt[0]
    assert BL.prometheus("http://p", _antwort("0"))["liest_bot"] is False
    assert "up=0" in BL.prometheus("http://p", _antwort("0"))["grund"]
    assert BL.prometheus("http://p", _antwort())["liest_bot"] is None
    assert "nicht lesbar" in BL.prometheus("http://p", lambda u: (200, "kaputt"))["grund"]
    assert "antwortet nicht" in BL.prometheus("http://p", _tot)["grund"]
    # Uebersetzt wird die VORLAGE, dann werden die Werte eingesetzt.
    r = BL.prometheus("http://p", _tot, _t=lambda s: "EN<" + s.split(" (")[0] + " (%s: %s)>")
    assert r["grund"] == "EN<Prometheus antwortet nicht (OSError: refused)>", r["grund"]
    g = BL.grafana("http://g:3000", False, lambda u: (200, "{}"))
    assert g["erreichbar"] and "GRAFANA_ADMIN_PASSWORD fehlt" in g["grund"], g
    assert not BL.grafana("http://g:3000", True, lambda u: (200, "{}"))["grund"]
    assert "antwortet nicht" in BL.grafana("http://g", True, _tot)["grund"]
    assert "nicht eingerichtet" in BL.grafana("", False)["grund"]
    alt = {k: _os.environ.get(k) for k in ("PROMETHEUS_URL", "GRAFANA_URL", "GRAFANA_ADMIN_PASSWORD")}
    try:
        _os.environ.update(PROMETHEUS_URL="http://p", GRAFANA_URL="http://g",
                           GRAFANA_ADMIN_PASSWORD="pw_nie_im_deck")
        l = BL.lage(holen=lambda u: (200, '{"data":{"result":[{"value":[0,"1"]}]}}'))
        assert l["prometheus"]["liest_bot"] and l["grafana"]["passwort_hinterlegt"], l
        assert "pw_nie_im_deck" not in _json.dumps(l), "Passwort in der Antwort ans Deck"
    finally:
        for k, v in alt.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v
    ok("W144: .env traegt Prometheus und Grafana, Passwort erzeugt, nie in argv oder Ausgabe")


def _test_v42_w145_einstellungen_regeln():
    """v4.2-W145: was das Deck setzen darf, was es nie sieht — und wo geladen wird.

    Der Betreiber wollte „alles im Dashboard einstellen". Alles geht nicht:
    UPDATE_REPO auf ein fremdes Repo, und die Update-Funktion spielt fremden
    Code ein; *_BIN auf ein beliebiges Programm; TRUSTED_PROXIES so, dass jede
    Anfrage als Loopback ohne Anmeldung gilt. Diese Grenze ist hier
    festgehalten — und abgeleitet, nicht nur aufgezaehlt: was die Vorlage
    selbst als Geheimnis fuehrt, muss das Deck verbergen."""
    import ast as _ast
    import re as _re
    from nc import einstellungen as E

    kat = {k["name"]: k for k in E.katalog(".env.example")}
    assert len(kat) >= 500, len(kat)
    assert kat["AI_PROVIDER"]["vorgabe"] == "auto" and kat["AI_PROVIDER"]["beschreibung"]
    assert not any("<" in n for n in kat), "Muster-Namen im Katalog"

    # (1) Geschuetzt — mit dem Grund, der im Deck steht.
    for n in ("UPDATE_REPO", "UPDATE_BRANCH", "UPDATE_RESTART_CMD", "UPDATE_ENABLED",
              "TRUSTED_PROXIES", "WEB_HOST", "DASHBOARD_TOKEN", "DASHBOARD_PIN",
              "DASHBOARD_OFFEN_ERLAUBEN", "DASHBOARD_PORT", "DASHBOARD_TLS_CERT",
              "DB_BACKEND", "DB_PATH", "MARIADB_PASSWORD", "MARIADB_HOST", "PIPER_BIN",
              "SWAP_CLEAR_CMD", "RECORDINGS_DIR", "ARCHIVE_DIR", "SERVICE_NAME"):
        assert E.schutzgrund(n), "%s ist aus dem Deck setzbar" % n
        assert E.SCHUTZ_TEXT[E.schutzgrund(n)]
    for n in ("ALERT_DISK_PCT", "AI_PROVIDER", "BOT_TOKEN", "KICK_STREAM_KEY", "RECORD_PROXY"):
        assert not E.schutzgrund(n), "%s waere ohne Grund gesperrt" % n
    # Jeder Name, der nach Befehl, Programm oder Pfad aussieht, ist geschuetzt.
    offen = sorted(n for n in kat if _re.search(r"(_CMD|_BIN|_DIR|_PATH|_EXE)$", n)
                   and not E.schutzgrund(n))
    assert not offen, "Befehle/Pfade aus dem Deck setzbar: %s" % offen

    # (2) Geheim — abgeleitet aus der Vorlage. Drei Namen trifft deren Muster
    # nur zufaellig (MAX_TOKENS ist eine Zahl, PING ist kein PIN).
    gen = _re.compile(r'(TOKEN|KEY|SECRET|PASSWORD|_PIN|WEBHOOK|CLIENT_SECRET|ACCESS)')
    zufall = {"BRAIN_LLM_MAX_TOKENS", "COMMUNITY_LIVE_PING_ENABLED", "COMMUNITY_LIVE_PING_MIN_GAP_S"}
    sichtbar = sorted(n for n in kat if gen.search(n) and n not in zufall
                      and not E.geheim(n) and not E.schutzgrund(n))
    assert not sichtbar, "Geheimnis mit Wert im Deck: %s" % sichtbar
    for n in ("KICK_STREAM_KEY_BACKUP", "BOT_TOKEN", "RECORD_PROXY", "PROXY_LIST", "REDIS_URL",
              "DISCORD_WEBHOOK_URL", "GRAFANA_ADMIN_PASSWORD", "ANTHROPIC_API_KEY"):
        assert E.geheim(n), n
    # Die Namensteile einzeln — im Katalog traegt kaum ein Name jeden davon.
    for n in ("X_PIN", "X_PASS", "X_KEY_2", "X_SID", "X_SECRET", "X_PRIVATE_KEY", "X_APIKEY"):
        assert E.geheim(n), n
    for n in ("COOKIE_AUTO_FETCH", "COMMUNITY_LIVE_PING_ENABLED", "BRAIN_LLM_MAX_TOKENS",
              "X_KEYWORDS", "X_PINNED", "X_PASSES"):
        assert not E.geheim(n), "%s ist kein Geheimnis, nur ein Schalter" % n

    # (3) Pruefung eines Werts.
    for name, wert in (("kleingeschrieben", "1"), ("A B", "1"), ("1A", "1"), ("X", 5),
                       ("X", "a\nB=1"), ("X", "a\r"), ("X", "a\0"), ("X", "x" * 4097),
                       ("UPDATE_REPO", "boese/repo")):
        try:
            E.pruefen(name, wert)
            raise AssertionError("angenommen: %r=%r" % (name, wert))
        except E.Abgelehnt:
            pass
    E.pruefen("ALERT_DISK_PCT", "95")

    # (4) bot.py laedt DIREKT nach load_dotenv() — vor der ersten Lesung auf
    # Modul-Ebene. Eine Zeile spaeter waere jede Konstante schon eingefroren.
    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    zeilen = {"dotenv": None, "einst": None, "getenv": None}
    for n in baum.body:
        q = _ast.unparse(n)
        if zeilen["dotenv"] is None and q.startswith("load_dotenv("):
            zeilen["dotenv"] = n.lineno
        elif zeilen["einst"] is None and "_nc_einst.in_umgebung_laden(" in q:
            zeilen["einst"] = n.lineno
        elif zeilen["getenv"] is None and "os.getenv(" in q and zeilen["dotenv"]:
            zeilen["getenv"] = n.lineno
    assert zeilen["dotenv"] < zeilen["einst"] < zeilen["getenv"], zeilen
    # Der Start-Leser oeffnet SQLite nur lesend: er darf weder eine Datei
    # anlegen noch ein Journal auf eine fremde Datei schreiben (W92).
    eb = _ast.parse(open("nc/einstellungen.py", encoding="utf-8").read())
    fn = next(n for n in eb.body if isinstance(n, _ast.FunctionDef) and n.name == "_start_lesen")
    aufrufe = [c for c in _ast.walk(fn) if isinstance(c, _ast.Call)
               and _ast.unparse(c.func) == "sqlite3.connect"]
    assert aufrufe and all("mode=ro" in _ast.unparse(c.args[0]) and
                           any(k.arg == "uri" for k in c.keywords) for c in aufrufe), \
        "Start-Leser oeffnet SQLite schreibend"
    ok("W145: Deck setzt nur Erlaubtes, Geheimnisse bleiben verborgen, Laden vor der ersten Konstante")


def _test_v42_w145_einstellungen_ablauf():
    """v4.2-W145: der Weg einer Einstellung — Deck → Datenbank → naechster Start.

    Mit einer eigenen SQLite-Datei, dem echten Schema und der echten Route."""
    import io as _io
    import json as _json
    import logging as _lg
    import os as _os
    import sys as _sys
    import types as _types
    from flask import Flask
    from nc import dbwrap as W
    from nc import einstellungen as E
    from nc import schema as S
    import nc.routes.einstellungen as R

    alt = (W.DB_PATH, W.DB_BACKEND)
    alt_zustand = dict(E._ZUSTAND)
    d = _ph.verzeichnis()
    db, envp = _os.path.join(d, "t.db"), _os.path.join(d, ".env")
    with open(envp, "w") as f:
        f.write("ALERT_DISK_PCT=80\nBOT_TOKEN=tok_w145_geheim\nUPDATE_REPO=x/y\nLEER=\n")
    puffer = _io.StringIO()
    h = _lg.StreamHandler(puffer)
    lg = _lg.getLogger("TikTokBot")
    lg.addHandler(h)
    alt_stufe = lg.level
    lg.setLevel(_lg.INFO)
    try:
        # (1) Erster Start ohne Datei: nichts angelegt, kein Fehler.
        env = {"DB_PATH": db}
        b = E.in_umgebung_laden(env, envp, ".env.example")
        assert b["geladen"] == 0 and not b["fehler"] and not _os.path.exists(db), b
        W.configure_db(db_path=db, backend="sqlite")
        with W.db_conn() as c:
            S.anlegen(c, backend="sqlite", mariadb_db="", log=_lg.getLogger("w145"))
        assert "Tabelle" not in E.in_umgebung_laden(env, envp, ".env.example")["quelle"]

        # (2) Uebernehmen: geschuetzte bleiben, leere nicht, nichts doppelt.
        u = E.uebernehmen()
        assert u == {"uebernommen": 2, "vorhanden": 0, "geschuetzt": 1}, u
        assert E.uebernehmen()["vorhanden"] == 2, "zweiter Lauf hat ueberschrieben"
        assert set(E.db_werte()) == {"ALERT_DISK_PCT", "BOT_TOKEN"}

        # (3) Setzen: in Tabelle und laufender Umgebung; Geheimnis nie im Log.
        E.setzen("ALERT_DISK_PCT", "95", env=env)
        E.setzen("BOT_TOKEN", "tok_neu_w145", env=env)
        assert env["ALERT_DISK_PCT"] == "95" and E.db_werte()["ALERT_DISK_PCT"]["wert"] == "95"
        assert "tok_neu_w145" not in puffer.getvalue() and "'95'" in puffer.getvalue()

        # (4) Naechster Start: die Datenbank ueberstimmt die .env; ein am
        # Deck vorbei eingetragener geschuetzter Schluessel wird ignoriert.
        with W.db_conn() as c:
            c.execute("INSERT INTO einstellungen (schluessel, wert) VALUES ('UPDATE_REPO','boese/r')")
        env2 = {"DB_PATH": db, "ALERT_DISK_PCT": "80", "UPDATE_REPO": "x/y"}
        b = E.in_umgebung_laden(env2, envp, ".env.example")
        assert env2["ALERT_DISK_PCT"] == "95" and env2["UPDATE_REPO"] == "x/y", env2
        assert b["ignoriert"] == ["UPDATE_REPO"] and "ALERT_DISK_PCT" in b["ueberstimmt"], b
        assert "geschuetzte Schluessel in der Datenbank ignoriert (UPDATE_REPO)" in puffer.getvalue()

        # (5) Die Uebersicht: Quelle stimmt, kein Geheimnis im JSON.
        ue = E.uebersicht(env2)
        x = {e["name"]: e for e in ue["eintraege"]}
        assert x["ALERT_DISK_PCT"]["quelle"] == "datenbank" and x["ALERT_DISK_PCT"]["wert"] == "95"
        assert x["UPDATE_REPO"]["quelle"] == "env" and x["UPDATE_REPO"]["geschuetzt"]
        assert "wert" not in x["BOT_TOKEN"] and x["BOT_TOKEN"]["gesetzt"]
        assert x["LEER"]["gruppe"] == "SONSTIGE", "Name aus der .env ohne Vorlage fehlt"
        blob = _json.dumps(ue)
        assert "tok_neu_w145" not in blob and "tok_w145_geheim" not in blob, "Geheimnis in der Uebersicht"
        assert "ALERT_DISK_PCT" in ue["neustart"]

        # (6) Zuruecksetzen: wieder .env, und ohne .env-Zeile die Vorgabe.
        E.zuruecksetzen("ALERT_DISK_PCT", env=env2)
        assert env2["ALERT_DISK_PCT"] == "80" and "ALERT_DISK_PCT" not in E.db_werte()
        E.setzen("AI_PROVIDER", "cloud", env=env2)
        E.zuruecksetzen("AI_PROVIDER", env=env2)
        assert "AI_PROVIDER" not in env2
        for name in ("UPDATE_REPO", "kaputt"):
            try:
                E.zuruecksetzen(name, env=env2)
                raise AssertionError(name)
            except E.Abgelehnt:
                pass

        # (7) Eine kaputte Datenbank beim Start: nicht fatal, aber laut.
        kaputt = _os.path.join(d, "kaputt.db")
        with open(kaputt, "wb") as f:
            f.write(b"\x16\x03\x01" + b"x" * 4096)
        b = E.in_umgebung_laden({"DB_PATH": kaputt}, envp, ".env.example")
        assert b["fehler"] and "NICHT geladen" in puffer.getvalue(), b

        # (8) MariaDB-Zweig mit einer pymysql-Attrappe: dieselben Regeln.
        class _Cur:
            def __init__(self):
                self.q = None

            def execute(self, q, a=None):
                self.q = q

            def fetchone(self):
                return (1,)

            def fetchall(self):
                return [("ALERT_DISK_PCT", "70"), ("DB_BACKEND", "sqlite")]

        class _Con:
            def cursor(self):
                return _Cur()

            def close(self):
                pass
        gefragt = {}
        attrappe = _types.SimpleNamespace(connect=lambda **kw: gefragt.update(kw) or _Con())
        alt_mod = _sys.modules.get("pymysql")
        _sys.modules["pymysql"] = attrappe
        try:
            env3 = {"DB_BACKEND": "mariadb", "MARIADB_PASSWORD": "pw", "MARIADB_DB": "ncdb"}
            b = E.in_umgebung_laden(env3, envp, ".env.example")
        finally:
            if alt_mod is None:
                _sys.modules.pop("pymysql", None)
            else:
                _sys.modules["pymysql"] = alt_mod
        assert env3["ALERT_DISK_PCT"] == "70" and env3["DB_BACKEND"] == "mariadb", env3
        assert b["ignoriert"] == ["DB_BACKEND"] and gefragt["database"] == "ncdb", (b, gefragt)

        # (9) Die Route: nur JSON, Schutz als Antwort, kein Geheimnis.
        E._ZUSTAND.update(env_pfad=envp, beispiel_pfad=".env.example")
        app = Flask(__name__)
        app.register_blueprint(R.bp)
        with app.test_client() as cl:
            r = cl.get("/api/einstellungen")
            assert r.status_code == 200 and "tok_neu_w145" not in r.get_data(as_text=True)
            r = cl.post("/api/einstellungen", data="name=ALERT_DISK_PCT&wert=1",
                        content_type="application/x-www-form-urlencoded")
            assert r.status_code == 415, "Formular einer fremden Seite angenommen"
            # Gueltiges JSON, aber als text/plain — so sendet eine fremde
            # Seite ohne CORS-Vorabfrage. Der Rumpf darf nicht gelesen werden.
            roh = _json.dumps({"name": "ALERT_DISK_PCT", "wert": "1"})
            for pfad in ("/api/einstellungen", "/api/einstellungen/zuruecksetzen",
                         "/api/einstellungen/uebernehmen"):
                assert cl.post(pfad, data=roh, content_type="text/plain").status_code == 415, pfad
            r = cl.post("/api/einstellungen", json={"name": "TRUSTED_PROXIES", "wert": "0.0.0.0/0"})
            assert r.status_code == 400 and "Deck erreicht" in r.get_json()["error"], r.get_json()
            r = cl.post("/api/einstellungen", json={"name": "ALERT_DISK_PCT", "wert": "91"})
            assert r.status_code == 200 and r.get_json()["neustart"], r.get_json()
            assert cl.post("/api/einstellungen/zuruecksetzen",
                           json={"name": "ALERT_DISK_PCT"}).status_code == 200
            assert cl.post("/api/einstellungen/zuruecksetzen",
                           json={"name": "WEB_HOST"}).status_code == 400
            r = cl.post("/api/einstellungen/uebernehmen", json={})
            assert r.status_code == 200 and r.get_json()["ok"], r.get_json()
    finally:
        lg.removeHandler(h)
        lg.setLevel(alt_stufe)
        E._ZUSTAND.clear()
        E._ZUSTAND.update(alt_zustand)
        W.configure_db(db_path=alt[0], backend=alt[1])
    ok("W145: Deck → Datenbank → naechster Start; Schutz haelt, nichts Geheimes im Log oder JSON")


def _test_v42_w145_einstellungen_deck():
    """v4.2-W145: der Reiter im Deck baut mit DOM-Knoten, nie mit innerHTML —
    Namen, Beschreibungen und Werte kommen aus Datenbank und .env."""
    import re as _re
    src = open("templates/dashboard.html", encoding="utf-8").read()
    assert 'data-view="einstellungen"' in src and 'id="view-einstellungen"' in src
    assert "VIEW_LOADERS['einstellungen']=einstLoad" in src
    i = src.index("var _ES={")
    j = src.index("VIEW_LOADERS['einstellungen']", i)
    block = src[i:j]
    assert "innerHTML" not in block, "Einstellungen bauen HTML aus Fremdtext"
    for fn in ("einstLoad", "einstZeigen", "einstSetzen", "einstZurueck", "einstUebernehmen"):
        assert _re.search(r"function %s\(" % fn, block), fn
    # Ein leeres Geheimnis-Feld heisst „unveraendert" — es darf nie als
    # leerer Wert gespeichert werden.
    assert "if(e.geheim&&!wert)" in block
    assert "apiPost('/api/einstellungen'" in block
    ok("W145: Einstellungs-Reiter ohne innerHTML, leeres Geheimnis bleibt unveraendert")


def _test_v42_w146_datenbank_waechter():
    """v4.2-W146: der vierzehnte Waechter — die Datenbank.

    Seit W143 kann sie MariaDB sein, seit W145 traegt sie die Einstellungen
    des Decks. /healthz fragt `SELECT 1` und sagt ja oder nein; der Waechter
    misst, was vorher schiefgeht."""
    import logging as _lg
    import os as _os
    from brain.agents import DatabaseAgent
    from nc import dbgesundheit as G
    from nc import dbwrap as W
    from nc import schema as S

    # (1) Die Messung gegen eine echte SQLite-Datei mit echtem Schema.
    alt = (W.DB_PATH, W.DB_BACKEND)
    d = _ph.verzeichnis()
    db = _os.path.join(d, "t.db")
    try:
        W.configure_db(db_path=db, backend="sqlite")
        with W.db_conn() as c:
            S.anlegen(c, backend="sqlite", mariadb_db="", log=_lg.getLogger("w146"))
            c.execute("INSERT INTO einstellungen (schluessel, wert) VALUES ('A','1')")
        m = G.messen(W.db_conn, "sqlite", db, 3, 3, {"fehler": None})
        assert m["ok"] and m["latenz_ms"] is not None and m["tabellen"] >= 40, m
        assert m["einstellungen"] == 1 and m["groesse_b"] > 0 and m["wal_b"] is not None, m
        # Ohne Verbindung: nicht ok, mit Grund — und die Dateigroesse trotzdem.

        def _tot():
            raise RuntimeError("database is locked")
        m2 = G.messen(_tot, "sqlite", db)
        assert not m2["ok"] and "locked" in m2["fehler"] and m2["groesse_b"] > 0, m2
    finally:
        W.configure_db(db_path=alt[0], backend=alt[1])

    # (2) Der Waechter: jede Lage mit eigenem Befund, gesund ist still.
    class _Mem:
        def __init__(self):
            self.m = {}

        def record_metric(self, k, v):
            self.m[k] = v

    class _B:
        memory = _Mem()

    def _ag(**mess):
        basis = {"ok": True, "backend": "sqlite", "latenz_ms": 2.0, "groesse_b": 10_000_000,
                 "wal_b": 1_000_000, "schema_stand": 3, "schema_erwartet": 3, "einst_fehler": None}
        basis.update(mess)
        return DatabaseAgent(_B(), db_health=lambda: basis)

    assert _ag().run({}) == [], "gesunde Datenbank meldet etwas"
    assert _B.memory.m["db_latency_ms"] == 2.0 and _B.memory.m["db_size_mb"] == 10.0
    b = _ag(ok=False, fehler="OperationalError: x").run({})
    assert b[0]["level"] == "crit" and "antwortet nicht" in b[0]["text"], b
    assert _ag(latenz_ms=800.0).run({})[0]["level"] == "warn"
    assert _ag(latenz_ms=5000.0).run({})[0]["level"] == "crit"
    w = _ag(wal_b=300_000_000).run({})
    assert w[0]["level"] == "warn" and "Checkpoint" in w[0]["text"], w
    assert _ag(wal_b=2_000_000_000).run({})[0]["level"] == "crit"
    assert _ag(schema_stand=5).run({})[0]["level"] == "crit"
    assert "Einstellungen" in _ag(einst_fehler="x").run({})[0]["text"]
    assert _ag(backend="mariadb", wal_b=None).run({}) == []
    # Zuwachs: zwei Runden, die zweite deutlich groesser.
    a = _ag()
    a.run({})
    a._last = (a._last[0] - 3600, a._last[1])
    a._mess = lambda: {"ok": True, "backend": "sqlite", "latenz_ms": 1.0,
                       "groesse_b": 10_000_000 + 300_000_000, "wal_b": 0}
    assert any("waechst" in f["text"] for f in a.run({}))
    assert DatabaseAgent(_B()).run({}) == [], "ohne Accessor etwas erfunden"
    k = DatabaseAgent(_B(), db_health=lambda: 1 / 0).run({})
    assert k[0]["level"] == "warn" and "ZeroDivisionError" in k[0]["text"]

    # (3) Verdrahtet: im Bot uebergeben, in der Bruecke registriert, im
    # Lagebild an einer eigenen Station.
    src = open("bot.py", encoding="utf-8").read()
    assert "db_health=_brain_db_health" in src
    br = open("brain_bridge.py", encoding="utf-8").read()
    assert 'DatabaseAgent(b, db_health=_ctx.get("db_health"))' in br
    from nc import lagebild as L
    assert L.ORT["datenbank"] == "datenbank" and "datenbank" in L.STATIONEN
    ok("W146: Datenbank-Waechter misst Latenz, Journal, Zuwachs, Schema und Einstellungen")


def _test_v42_w146_lagebild_profi():
    """v4.2-W146: „sieht aus als hätte es ein Kind gezeichnet" — die Spinne
    in der Mitte ist weg, die Farben kommen aus dem Thema, und das Bild
    entsteht auch, bevor der Uebersetzer geladen ist."""
    import re as _re
    h = open("templates/dashboard.html", encoding="utf-8").read()
    i = h.index("var ncLagebild=(function(){")
    js = _re.sub(r"/\*.*?\*/", "", h[i:h.index("\n})();", i)], flags=_re.S)
    # Keine Beine, keine Augen: die alte Figur zeichnete acht Linien je Seite
    # und zwei Kreise mit F.red/F.neon im Kern.
    assert "for(var i=0;i<8;i++)" not in js, "die Spinne ist zurueck"
    assert "quadraticCurveTo" not in js, "schwingende Kurven statt Leitungen"
    # Farben aus dem Thema, nicht fest dunkel — sonst ist Blaupause unlesbar.
    assert not _re.search(r"rgba\((?:6,9,11|8,12,14)", js), "feste Dunkelflaeche"
    assert "flaeche:C('--panel-solid'" in js and "function hilfe(" in js
    # Ausgenommen ist nur der Rueckfall in hilfe() selbst (Thema ohne --text).
    ohne_hilfe = js[:js.index("function hilfe(a)")] + js[js.index("var F={};"):]
    assert not _re.search(r"'rgba\(255,255,255,", ohne_hilfe), "weisse Hilfslinie auf hellem Thema"
    # T() existiert vor dem ersten Skript, das es braucht (Uebersetzer: defer).
    kopf = h[:h.index("var ncLagebild=")]
    j = kopf.index("if(typeof window.T!=='function') window.T=function(s){return s;};")
    assert j < kopf.index("<script>", kopf.index("<script>") + 1) or j < kopf.index("ncThemaKnopf"), \
        "T-Ersatz steht nicht vor den Skripten"
    assert "datenbank:{a:" in js and "datenbank:T('Datenbankwache')" in js
    ok("W146: Lagebild ohne Figur, Themenfarben, T() vor dem ersten Gebrauch")



def _test_v42_w148_ausfuehrungsrecht():
    """v4.2-W148: „sudo ./update.sh — Permission denied (os error 13)".

    Zwei Ursachen, beide gesichert: im Git-Baum standen tools/update.sh,
    deploy.sh und notify_failure.sh auf 644, und die Update-Funktion schrieb
    JEDE Datei mit den Vorgaberechten — und fasste eine Datei mit gleichem
    Inhalt gar nicht erst an."""
    import os as _os
    import stat as _stat
    import subprocess as _sp
    import zipfile as _zf
    from nc import updater as U

    # (1) Jedes ausfuehrbare Skript unter tools/ steht im Git-Baum auf 755.
    # tools/lib/*.sh werden nur per `.` eingelesen und bleiben 644.
    try:
        zeilen = _sp.run(["git", "ls-files", "-s", "tools"], capture_output=True,
                         text=True, timeout=30).stdout.splitlines()
    except OSError:
        zeilen = []
    if zeilen:
        falsch = []
        for z in zeilen:
            modus, _h, _n, pfad = z.split(None, 3)
            if pfad.endswith(".sh") and "/lib/" not in pfad:
                with open(pfad, "rb") as f:
                    if f.read(2) == b"#!" and modus != "100755":
                        falsch.append(pfad)
        assert not falsch, "im Git-Baum nicht ausfuehrbar: %s" % falsch

    # (2) Das Archiv-Recht wird gelesen, wie GitHub es ablegt (obere 16 Bit).
    zi = _zf.ZipInfo("x/tools/a.sh")
    zi.external_attr = (0o100755 << 16)
    assert U.ausfuehrbar_im_archiv(zi)
    zi.external_attr = (0o100644 << 16)
    assert not U.ausfuehrbar_im_archiv(zi)
    assert not U.ausfuehrbar_im_archiv(object())

    if _os.name != "posix":
        ok("W148: Ausfuehrungsrecht im Git-Baum (Dateirechte nur unter POSIX pruefbar)")
        return
    d = _ph.verzeichnis()
    alt = U._CFG.root
    try:
        U.configure(root=d)
        # (3) Neu und ausfuehrbar laut Archiv -> 755-artig; laut Archiv nicht
        # -> kein x; None -> wie die bisherige Datei.
        U._write_file("tools/a.sh", b"#!/bin/sh\n", True)
        assert _os.stat(_os.path.join(d, "tools/a.sh")).st_mode & 0o100, "neu, aber nicht ausfuehrbar"
        U._write_file("tools/a.sh", b"#!/bin/sh\necho\n", None)
        assert _os.stat(_os.path.join(d, "tools/a.sh")).st_mode & 0o100, "Recht beim Ueberschreiben verloren"
        U._write_file("tools/a.sh", b"x\n", False)
        assert not _os.stat(_os.path.join(d, "tools/a.sh")).st_mode & 0o111
        # (4) Gleicher Inhalt, aber 644 auf der Platte und 755 im Archiv: das
        # ist genau der Bestand nach einem Update vor W148.
        p = _os.path.join(d, "tools/update.sh")
        with open(p, "wb") as f:
            f.write(b"#!/bin/sh\n")
        _os.chmod(p, 0o644)
        zi = _zf.ZipInfo("repo-main/tools/update.sh")
        zi.external_attr = (0o100755 << 16)
        zn = _zf.ZipInfo("repo-main/nc/x.py")
        zn.external_attr = (0o100644 << 16)
        aus = U.rechte_angleichen([("tools/update.sh", 10, "h", zi), ("nc/x.py", 0, "h", zn)])
        assert aus == ["tools/update.sh"], aus
        assert _stat.S_IMODE(_os.stat(p).st_mode) == 0o755, oct(_os.stat(p).st_mode)
        assert U.rechte_angleichen([("tools/update.sh", 10, "h", zi)]) == [], "zweimal angeglichen"
        # Geschuetztes bleibt unberuehrt, auch wenn das Archiv x traegt.
        e = _os.path.join(d, ".env")
        with open(e, "w") as f:
            f.write("A=1\n")
        _os.chmod(e, 0o600)
        ze = _zf.ZipInfo("repo-main/.env")
        ze.external_attr = (0o100755 << 16)
        assert U.rechte_angleichen([(".env", 4, "h", ze)]) == []
        assert _stat.S_IMODE(_os.stat(e).st_mode) == 0o600
        # (4b) Der zweite Riegel in _write_file (normpath + startswith, fuer
        # CodeQL sichtbar) haelt auch allein: der erste wird abgeschaltet.
        alt_unter = U._nc_sicherpfad.unter
        U._nc_sicherpfad.unter = lambda wurzel, pfad: True
        try:
            # Name je Lauf eindeutig: ein Rest aus einem frueheren (mutierten)
            # Lauf duerfte das Ergebnis nicht vorwegnehmen.
            raus = "draussen-%s.txt" % _os.path.basename(d)
            ziel = _os.path.join(_os.path.dirname(d), raus)
            for boese in ("../" + raus, "tools/../../" + raus):
                try:
                    U._write_file(boese, b"x", False)
                except ValueError:
                    pass
                else:
                    for rest in (ziel, ziel + ".ncnew"):
                        if _os.path.exists(rest):
                            _os.remove(rest)
                    raise AssertionError("ausserhalb der Wurzel geschrieben: " + boese)
            assert not _os.path.exists(ziel)
        finally:
            U._nc_sicherpfad.unter = alt_unter
    finally:
        U.configure(root=alt)
    # (5) Verdrahtet: run_update gleicht an, BEVOR „Alles aktuell" zurueckkehrt
    # — sonst bliebe genau der gemeldete Fall liegen.
    import ast as _ast
    baum = _ast.parse(open("nc/updater.py", encoding="utf-8").read())
    fn = next(n for n in baum.body if isinstance(n, _ast.FunctionDef) and n.name == "run_update")
    aufrufe = [n.lineno for n in _ast.walk(fn) if isinstance(n, _ast.Call)
               and getattr(n.func, "id", "") == "rechte_angleichen"]
    frueh = [n.lineno for n in _ast.walk(fn) if isinstance(n, _ast.Constant)
             and n.value == "Alles aktuell — keine Datei zu ersetzen."]
    assert aufrufe and frueh and aufrufe[0] < frueh[0], (aufrufe, frueh)
    schreib = [n for n in _ast.walk(baum) if isinstance(n, _ast.Call)
               and getattr(n.func, "id", "") == "_write_file"]
    assert schreib and all(len(n.args) == 3 for n in schreib), "ein _write_file ohne Archiv-Recht"
    ok("W148: Ausfuehrungsrecht im Git-Baum, beim Schreiben und fuer unveraenderte Dateien")


def _test_v42_w148_durchreicher():
    """v4.2-W148: „Für die restreams werden angeblich keine links gepullt die
    Gültigkeit haben". Gibt TikTok keine ziehbare Adresse heraus, zieht
    yt-dlp (ersatzweise streamlink) den Stream selbst und reicht ihn an den
    ueblichen Zubringer-ffmpeg durch."""
    import os as _os
    import signal as _signal
    import subprocess as _sp
    import sys as _sys
    from nc import durchreicher as D
    from nc import restreamcmd as RC

    # (1) Adresse: nur gueltige TikTok-Namen, sonst kaeme ein Befehlsteil durch.
    a = D.adresse("anna.b_1")
    assert D.ist(a) and D.nutzer_aus(a) == "anna.b_1"
    for boese in ("", "a b", "--exec=x", "a/../b", "x" * 65, "a;rm"):
        try:
            D.adresse(boese)
        except ValueError:
            pass
        else:
            raise AssertionError("angenommen: %r" % boese)
    assert not D.ist("https://x/y.flv") and not D.ist(None)
    try:
        D.nutzer_aus(D.SCHEMA + "a;b")
        raise AssertionError("nutzer_aus nahm einen ungueltigen Namen")
    except ValueError:
        pass

    # (2) Werkzeug: yt-dlp vor streamlink, None ohne beide.
    assert D.werkzeug(lambda n: "/x/" + n if n == "streamlink" else None) == ("streamlink", "/x/streamlink")
    assert D.werkzeug(lambda n: "/x/yt-dlp" if n in ("yt-dlp", "streamlink") else None)[0] == "yt-dlp"
    assert D.werkzeug(lambda n: None) is None

    # (3) Befehle: nach stdout, mit Seite des Nutzers — der Proxy NIE in argv.
    y = D.zieher_cmd("yt-dlp", "/x/yt-dlp", "anna", cookies=None)
    assert y[0] == "/x/yt-dlp" and y[y.index("-o") + 1] == "-" and y[-1] == "https://www.tiktok.com/@anna/live"
    assert "--cookies" not in y, "Cookie-Datei, die es nicht gibt"
    s = D.zieher_cmd("streamlink", "/x/sl", "anna")
    assert "--stdout" in s and s[-2:] == ["https://www.tiktok.com/@anna/live", "best"]
    env = D.zieher_umgebung({"RECORD_PROXY": "nutzer:geheim@h:8118", "PATH": "/bin"})
    assert env["HTTPS_PROXY"] == env["http_proxy"] == "http://nutzer:geheim@h:8118"
    assert D.zieher_umgebung({"PATH": "/bin"}).get("HTTPS_PROXY") is None
    assert not any("geheim" in t for t in y + s)

    # (4) Der Zubringer der Bruecke: liest pipe:0, ohne -re, ohne Netz-Optionen,
    # eingewickelt in den Durchreicher — und eine echte URL bleibt wie sie war.
    RC.configure(
        cookie_header=lambda: "sid=GEHEIM", pick_pull_proxy=lambda: "",
        restream_overlay_files=lambda rid=None: {}, FFMPEG_THREADS_LIVE=3,
        FFMPEG_THREADS_RELAY=2, RESTREAM_AVATAR="", RESTREAM_BITRATE_K=4500,
        RESTREAM_AVATAR_ALPHA="", RESTREAM_AVATAR_H=170, RESTREAM_AVATAR_LOOP="",
        RESTREAM_CANVAS_H=720, RESTREAM_CANVAS_W=1280, RESTREAM_FONT="",
        RESTREAM_FPS=30, RESTREAM_LOW_LATENCY=True, RESTREAM_OVERLAY=False,
        RESTREAM_OVERLAY_HTML_FPS=1, RESTREAM_RELAY_BITRATE_K=3500,
        RESTREAM_RELAY_PRESET="ultrafast", RESTREAM_X264_PRESET="veryfast",
        RESTREAM_UA="UA/1.0", TTS_CH=2, TTS_SR=44100, TTS_VOICE_GAIN="1.8")
    z = RC.zubringer(a)
    assert "GEHEIM" not in " ".join(z), "Cookie-Kopf in der Befehlszeile des Durchreichers"
    assert z[0] == _sys.executable and z[1].endswith("durchreicher.py") and z[2] == "anna.b_1"
    ff = z[z.index("--") + 1:]
    assert ff[0] == "ffmpeg" and ff[ff.index("-i") + 1] == "pipe:0" and "-re" not in ff
    assert ff[-1] == "pipe:1" and not any(t.startswith("-reconnect") for t in ff)
    u = RC.zubringer("https://pull.example/live.flv")
    assert u[0] == "ffmpeg" and "-re" in u and "durchreicher.py" not in " ".join(u)

    # (5) Preflight probt keine Pseudo-Adresse per HTTP.
    import asyncio as _aio
    from nc import preflight as P
    # Ohne den Riegel scheitert aiohttp an der Pseudo-Adresse, und der
    # Preflight meldet „Weg nach aussen gestoert" — ein falscher Alarm je Start.
    vorher = dict(P._PREFLIGHT_STATS)
    assert _aio.run(P._preflight_url(a, "anna")) == a
    assert dict(P._PREFLIGHT_STATS) == vorher, "Pseudo-Adresse per HTTP geprobt"

    # (6) main() mit Attrappen: Aufrufpruefung, fehlendes Werkzeug, Verkettung.
    assert D.main(["anna", "-"]) == 2
    assert D.main(["a;b", "-", "--", "ffmpeg"]) == 2
    assert D.main(["anna", "-", "--", "ffmpeg"], which=lambda n: None) == 3
    gestartet = []

    class _P:
        def __init__(self, cmd, **kw):
            self.cmd, self.kw, self.beendet = cmd, kw, False
            self.stdout = _sp.PIPE if kw.get("stdout") is _sp.PIPE else None
            gestartet.append(self)
            if self.stdout is _sp.PIPE:
                class _R:
                    zu = False

                    def close(s):
                        s.zu = True
                self.stdout = _R()

        def poll(self):
            return 0 if self.beendet else None

        def wait(self, timeout=None):
            self.beendet = True
            return 7

        def terminate(self):
            self.beendet = True

    alt = (_signal.getsignal(_signal.SIGTERM), _signal.getsignal(_signal.SIGINT))
    try:
        rc = D.main(["anna", "-", "--", "ffmpeg", "-i", "pipe:0"], popen=_P,
                    which=lambda n: "/x/yt-dlp" if n == "yt-dlp" else None)
        # Der Kern des Versprechens: SIGTERM von der Bruecke beendet BEIDE.
        # Der Griff, den main() eingehaengt hat, wird hier direkt ausgeloest.
        _griff = _signal.getsignal(_signal.SIGTERM)
        _w_alt = _griff.__closure__
        assert _w_alt, "kein eigener SIGTERM-Griff"
        # ANKER GEWANDERT (v4.2-W167, nicht der Vertrag): der Griff haelt das
        # LAUFENDE Paar in einem Merker, weil main() seit W167 ein zweites
        # Werkzeug versuchen kann.
        _zellen = {v for c in _w_alt if isinstance(c.cell_contents, dict)
                   for v in c.cell_contents.values() if isinstance(v, _P)}
        assert len(_zellen) == 2, "Griff haelt nicht Zieher UND ffmpeg"
        for q in _zellen:
            q.beendet = False
        try:
            _griff(_signal.SIGTERM, None)
        except SystemExit as _e:
            assert _e.code == 0
        else:
            raise AssertionError("SIGTERM-Griff beendet das Programm nicht")
        assert all(q.beendet for q in _zellen), "SIGTERM liess ein Kind weiterlaufen"
    finally:
        _signal.signal(_signal.SIGTERM, alt[0])
        _signal.signal(_signal.SIGINT, alt[1])
    assert rc == 7, "Exitcode nicht der des ffmpeg"
    zieher, wandler = [q for q in _zellen if q.kw.get("stdout") is _sp.PIPE] + \
        [q for q in _zellen if q.kw.get("stdout") is not _sp.PIPE]
    assert zieher.cmd[0] == "/x/yt-dlp" and wandler.cmd[:2] == ["ffmpeg", "-i"]
    assert wandler.kw["stdin"] is zieher.stdout and zieher.stdout.zu, "Leitung nicht verkettet/geschlossen"
    assert zieher.beendet, "Zieher laeuft nach dem Ende des ffmpeg weiter"

    # (7) Echt, als Programm: ein Ersatz-yt-dlp im PATH liefert Bytes, ein
    # Ersatz-ffmpeg zaehlt sie. Der Proxy steht in der Umgebung, nicht in argv.
    if _os.name == "posix":
        d = _ph.verzeichnis()
        zeuge = _os.path.join(d, "zeuge.txt")
        yt = _os.path.join(d, "yt-dlp")
        with open(yt, "w") as f:
            f.write("#!%s\nimport os, sys\nopen(%r, 'w').write(repr(sys.argv) + '|' + "
                    "os.environ.get('HTTPS_PROXY', ''))\nsys.stdout.buffer.write(b'X' * 4096)\n"
                    % (_sys.executable, zeuge))
        _os.chmod(yt, 0o755)
        zaehler = [_sys.executable, "-c", "import sys; print(len(sys.stdin.buffer.read()))"]
        r = _sp.run([_sys.executable, D.__file__, "anna", "-", "--"] + zaehler,
                    capture_output=True, text=True, timeout=60,
                    env=dict(_os.environ, PATH=d + _os.pathsep + _os.environ.get("PATH", ""),
                             RECORD_PROXY="nutzer:geheim@h:8118"))
        assert r.returncode == 0 and r.stdout.strip() == "4096", (r.returncode, r.stdout, r.stderr)
        argv, proxy = open(zeuge).read().split("|")
        assert "geheim" not in argv and proxy == "http://nutzer:geheim@h:8118", (argv, proxy)

    # (8) Im Bot: kein beste_url -> der Durchreicher, jeder Grund laut.
    import ast as _ast
    src = open("bot.py", encoding="utf-8").read()
    baum = _ast.parse(src)
    fn = next(n for n in baum.body if isinstance(n, _ast.FunctionDef) and n.name == "_restream_durchreicher")
    texte = [n.value for n in _ast.walk(fn) if isinstance(n, _ast.Constant) and isinstance(n.value, str)]
    for teil in ("RESTREAM_DURCHREICHER=0", "RESTREAM_BRUECKE=0", "yt-dlp noch streamlink",
                 "RESTREAM_MULTI_MODE=independent"):
        assert any(teil in t for t in texte), teil
    # Codex #194: der unabhaengige Modus sagt nein, BEVOR eine Adresse entsteht
    # — die Pruefung steht vor dem Aufruf von adresse().
    _ind = next(n.lineno for n in _ast.walk(fn) if isinstance(n, _ast.Compare)
                and any(isinstance(c, _ast.Constant) and c.value == "independent" for c in n.comparators))
    _adr = next(n.lineno for n in _ast.walk(fn) if isinstance(n, _ast.Call)
                and getattr(n.func, "attr", "") == "adresse")
    assert _ind < _adr, (_ind, _adr)
    # Und der Start selbst: eine Durchreicher-Adresse ohne Bruecke bricht ab,
    # statt an ein gewoehnliches ffmpeg zu gehen.
    _riegel = [n for n in _ast.walk(baum) if isinstance(n, _ast.If)
               and "_nc_durch.ist(src)" in _ast.unparse(n.test)
               and "not _bruecke_an" in _ast.unparse(n.test)]
    assert _riegel and any(isinstance(z, _ast.Return) for z in _riegel[0].body), \
        "Start ohne Riegel gegen Durchreicher ohne Bruecke"
    assert sum(1 for n in _ast.walk(fn) if isinstance(n, _ast.Attribute) and n.attr == "melden") == 2
    rs = next(n for n in _ast.walk(baum) if isinstance(n, _ast.AsyncFunctionDef) and n.name == "_resolve_source") \
        if any(isinstance(n, _ast.AsyncFunctionDef) and n.name == "_resolve_source" for n in _ast.walk(baum)) \
        else next(n for n in _ast.walk(baum) if isinstance(n, _ast.FunctionDef) and n.name == "_resolve_source")
    assert any(isinstance(n, _ast.Call) and getattr(n.func, "id", "") == "_restream_durchreicher"
               for n in _ast.walk(rs)), "_resolve_source nutzt den Durchreicher nicht"
    ok("W148: Durchreicher — Adresse, Befehle ohne Proxy in argv, Verkettung, Bruecke, Bot")


def _test_v42_w148_beobachtungs_waechter():
    """v4.2-W148: „wenn grafana und Prometheus installiert sind auch diese 2
    extra agenten/Wächter bekommen und grafana / Prometheus vollständig
    verwalten / steuern"."""
    import json as _json
    from brain.agents import GrafanaAgent, PrometheusAgent
    from nc import beobachtungsdienst as B

    # (1) Installiert heisst: URL in der .env.
    assert B.installiert({}) == {"prometheus": False, "grafana": False}
    assert B.installiert({"PROMETHEUS_URL": "http://x", "GRAFANA_URL": " "}) == {"prometheus": True, "grafana": False}

    # (2) Prometheus-Lage gegen eine Attrappe der HTTP-API.
    def _prom(antworten):
        def holen(url, kopf=None):
            for teil, (st, d) in antworten.items():
                if teil in url:
                    if isinstance(d, Exception):
                        raise d
                    return st, d if isinstance(d, str) else _json.dumps(d)
            return 404, ""
        return holen
    gesund = {
        "/-/ready": (200, "ready"),
        "/api/v1/query": (200, {"data": {"result": [{"value": [1, "1"]}]}}),
        "/api/v1/targets": (200, {"data": {"activeTargets": [
            {"health": "up", "labels": {"job": "nightcrawler"}},
            {"health": "down", "labels": {"job": "node"}, "lastError": "connection refused"}]}}),
        "/api/v1/rules": (200, {"data": {"groups": [{"rules": [
            {"name": "A", "health": "ok"}, {"name": "B", "health": "err", "lastError": "bad"}]}]}}),
        "/api/v1/status/runtimeinfo": (200, {"data": {"reloadConfigSuccess": False}}),
        "/api/v1/alerts": (200, {"data": {"alerts": [
            {"state": "firing", "labels": {"alertname": "BotTot", "severity": "critical"},
             "annotations": {"summary": "weg"}},
            {"state": "pending", "labels": {"alertname": "Bald"}}]}}),
        "/api/v1/status/tsdb": (200, {"data": {"headStats": {"numSeries": 1234}}}),
    }
    m = B.prometheus_lage("http://p/", holen=_prom(gesund))
    assert m["erreichbar"] and m["liest_bot"] is True and m["config_ok"] is False and m["serien"] == 1234, m
    assert m["ziele_aus"] == [{"job": "node", "fehler": "connection refused"}], m
    assert [r["regel"] for r in m["regeln_aus"]] == ["B"]
    assert [a["name"] for a in m["alarme"]] == ["BotTot"], "ein wartender Alarm zaehlt als feuernd"
    tot = B.prometheus_lage("http://p", holen=_prom({"/-/ready": (0, ConnectionRefusedError("x"))}))
    assert not tot["erreichbar"] and "ConnectionRefusedError" in tot["fehler"]
    assert B.prometheus_lage("", holen=_prom({}))["fehler"] == "PROMETHEUS_URL fehlt"
    unbekannt = dict(gesund, **{"/api/v1/query": (200, {"data": {"result": []}})})
    assert B.prometheus_lage("http://p", holen=_prom(unbekannt))["liest_bot"] is None, "kein Abruf ist kein up=0"

    # (3) Grafana-Lage: das Passwort geht nur als Basic-Kopf hinaus, nie in
    # die Antwort.
    gesehen = []

    def _gf(url, kopf=None):
        gesehen.append((url, kopf))
        if url.endswith("/api/health"):
            return 200, '{"database":"ok"}'
        if kopf is None:
            return 401, ""
        if url.endswith("/api/user"):
            return 200, "{}"
        if "/datasources/uid/" in url:
            return 200, '{"status":"OK"}'
        return 404, ""
    g = B.grafana_lage("http://g", "admin", "s3cret", holen=_gf)
    assert g["erreichbar"] and g["db_ok"] and g["anmeldung_ok"] and g["quelle_ok"] and g["dashboard_da"] is False, g
    assert "s3cret" not in _json.dumps(g)
    assert all("s3cret" not in u for u, _k in gesehen)
    ohne = B.grafana_lage("http://g", "admin", "", holen=_gf)
    assert ohne["anmeldung_ok"] is None, "ohne Passwort eine Anmeldung behauptet"

    # (4) Steuern: nur feste Befehle, immer `sudo -n`, kein Fremdteil.
    laeufe = []

    class _R:
        def __init__(self, rc, err=""):
            self.returncode, self.stderr, self.stdout = rc, err, ""

    def _run(cmd, **kw):
        laeufe.append(cmd)
        return _R(0)
    r = B.steuern("prometheus", "neu_laden", run=_run)
    assert r["ok"] and laeufe[-1] == ["sudo", "-n", "systemctl", "reload", "nightcrawler-prometheus.service"]
    assert not B.steuern("prometheus", "; rm -rf /", run=_run)["ok"] and len(laeufe) == 1
    assert not B.steuern("tiktok-bot", "neu_starten", run=_run)["ok"] and len(laeufe) == 1
    r = B.steuern("grafana", "neu_starten", run=lambda c, **k: _R(1, "sudo: a password is required"))
    assert not r["ok"] and "observability.sh" in r["text"], r
    for befehl in B.STEUERUNG.values():
        assert befehl[0] == "systemctl" and befehl[1] in ("reload", "restart"), befehl
    # Arch: der Dienst heisst grafana.service — erkannt am Drop-in von observability.sh.
    import os as _os
    d = _ph.verzeichnis()
    assert B.grafana_unit(d) == "grafana-server.service"
    _os.makedirs(_os.path.join(d, "etc/systemd/system/grafana.service.d"))
    open(_os.path.join(d, "etc/systemd/system/grafana.service.d/nightcrawler.conf"), "w").close()
    assert B.grafana_unit(d) == "grafana.service"
    B.steuern("grafana", "neu_starten", run=_run, wurzel=d)
    assert laeufe[-1][-1] == "grafana.service"

    # (5) Selbstheilung: Vorgabe AN, abschaltbar.
    alt = {k: _os.environ.get(k) for k in ("BRAIN_ACT_PROMETHEUS", "BRAIN_ACT_GRAFANA")}
    try:
        for k in alt:
            _os.environ.pop(k, None)
        assert B.selbstheilung_erlaubt("prometheus") and B.selbstheilung_erlaubt("grafana")
        _os.environ["BRAIN_ACT_GRAFANA"] = "0"
        assert not B.selbstheilung_erlaubt("grafana")
        assert not B.selbstheilung_erlaubt("tiktok")
    finally:
        for k, v in alt.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v

    # (6) Die Waechter: Befunde je Lage, Neustart erst in der zweiten Runde,
    # hoechstens einmal je Ruhezeit, nie ohne Gate.
    class _Mem:
        def __init__(self):
            self.m = {}

        def record_metric(self, k, v):
            self.m[k] = v

    class _Hirn:
        memory = _Mem()
    p = PrometheusAgent(_Hirn(), lage=lambda: m)
    f = p.run({})
    texte = " ".join(x["text"] for x in f)
    assert "abgelehnt" in texte and "node" in texte and "B " in texte + " " and "BotTot" in texte, texte
    assert next(x for x in f if x.get("alarm") == "BotTot")["level"] == "crit"
    assert _Hirn.memory.m["prometheus_series"] == 1234
    gestartet = []

    def _st(dienst, aktion):
        gestartet.append((dienst, aktion))
        return {"ok": True, "befehl": "systemctl restart x"}
    weg = PrometheusAgent(_Hirn(), lage=lambda: {"erreichbar": False, "fehler": "refused"},
                          steuern=_st, act_check=lambda n: n == "prometheus")
    eins = weg.run({})
    assert eins[0]["level"] == "crit" and "kein Alarm" in eins[0]["text"] and not gestartet
    zwei = weg.run({})
    assert gestartet == [("prometheus", "neu_starten")] and "neu gestartet" in zwei[-1]["text"], zwei
    weg.run({})
    assert len(gestartet) == 1, "Neustart innerhalb der Ruhezeit wiederholt"
    gesperrt = PrometheusAgent(_Hirn(), lage=lambda: {"erreichbar": False}, steuern=_st)
    gesperrt.run({}), gesperrt.run({})
    assert len(gestartet) == 1, "Neustart ohne Gate"
    gs = GrafanaAgent(_Hirn(), lage=lambda: {"erreichbar": True, "db_ok": True, "anmeldung_ok": False,
                                             "quelle_ok": False, "dashboard_da": False})
    gt = " ".join(x["text"] for x in gs.run({}))
    assert "GRAFANA_ADMIN_PASSWORD" in gt and "Datenquelle" in gt and "Dashboard" in gt, gt
    assert GrafanaAgent(_Hirn(), lage=lambda: {"erreichbar": True, "db_ok": True}).run({}) == []
    assert PrometheusAgent(_Hirn()).run({}) == []
    k = PrometheusAgent(_Hirn(), lage=lambda: 1 / 0).run({})
    assert k[0]["level"] == "warn" and "ZeroDivisionError" in k[0]["text"]

    # (7) Registriert nur, wenn eingerichtet.
    import brain_bridge as BB
    reg = []

    class _Ag:
        def register(self, a):
            reg.append(a.name)

    class _Hb:
        agents = _Ag()
    alt = {k: _os.environ.get(k) for k in ("PROMETHEUS_URL", "GRAFANA_URL")}
    try:
        for k in alt:
            _os.environ.pop(k, None)
        BB._register_beobachtung(_Hb())
        assert reg == [], reg
        _os.environ["PROMETHEUS_URL"] = "http://127.0.0.1:9099"
        BB._register_beobachtung(_Hb())
        assert reg == ["prometheus"], reg
        _os.environ["GRAFANA_URL"] = "http://127.0.0.1:3000"
        BB._register_beobachtung(_Hb())
        assert reg == ["prometheus", "prometheus", "grafana"], reg
    finally:
        for k, v in alt.items():
            if v is None:
                _os.environ.pop(k, None)
            else:
                _os.environ[k] = v

    # (8) Die Routen: nur Schluessel aus STEUERUNG, sonst 400; nicht
    # eingerichtet 409 — und nie ein Befehl aus der Anfrage.
    from flask import Flask
    from nc.routes import beobachtung as R
    app = Flask(__name__)
    app.register_blueprint(R.bp)
    alt_st = B.steuern
    aufgerufen = []
    try:
        B.steuern = lambda d, a: (aufgerufen.append((d, a)) or {"ok": True, "befehl": "x"})
        _os.environ.pop("PROMETHEUS_URL", None)
        with app.test_client() as cl:
            assert cl.post("/api/beobachtung/steuern", json={"dienst": "prometheus", "aktion": "rm -rf"}).status_code == 400
            assert cl.post("/api/beobachtung/steuern", json={"dienst": "prometheus", "aktion": "neu_laden"}).status_code == 409
            _os.environ["PROMETHEUS_URL"] = "http://127.0.0.1:1"
            assert cl.post("/api/beobachtung/steuern", json={"dienst": "prometheus", "aktion": "neu_laden"}).status_code == 200
            j = cl.get("/api/beobachtung/dienste").get_json()
        # CodeQL #194: die Antwort traegt nie `fehler` (Ausnahmetext), nur den
        # festen Grund — und eine gescheiterte Steuerung nur ihren Grund.
        assert "fehler" not in j["prometheus"] and j["prometheus"]["grund"], j["prometheus"]
        B.steuern = lambda d, a: {"ok": False, "befehl": "x", "grund": B.GRUND_RC,
                                  "grund_wert": 7, "text": "rc=7: /etc/geheim: Permission denied"}
        with app.test_client() as cl:
            e = cl.post("/api/beobachtung/steuern", json={"dienst": "prometheus", "aktion": "neu_laden"})
        assert e.status_code == 502 and "geheim" not in e.get_data(as_text=True), e.get_json()
        assert "rc=7" in e.get_json()["error"], e.get_json()
        assert aufgerufen == [("prometheus", "neu_laden")], aufgerufen
        assert j["ok"] and j["installiert"]["prometheus"] and j["grafana"] is None
        assert not j["prometheus"]["erreichbar"] and "prometheus/neu_laden" in j["steuerung"]
    finally:
        B.steuern = alt_st
        if alt["PROMETHEUS_URL"] is None:
            _os.environ.pop("PROMETHEUS_URL", None)
        else:
            _os.environ["PROMETHEUS_URL"] = alt["PROMETHEUS_URL"]

    # (9) observability.sh legt die Steuerregel an — genau die drei Befehle,
    # mit visudo geprueft, mit 440, und --remove nimmt sie wieder weg.
    sh = open("tools/observability.sh", encoding="utf-8").read()
    assert 'SUDOERS="$W/etc/sudoers.d/nightcrawler-beobachtung"' in sh
    assert "visudo -cqf" in sh and 'install -m 440 "$_regel" "$SUDOERS"' in sh
    assert 'reload nightcrawler-prometheus.service, %s restart nightcrawler-prometheus.service' in sh
    assert '"$GF_PWDATEI" "$SUDOERS"; do' in sh
    # Deck: Knoepfe schicken nur Dienst und Aktion.
    h = open("templates/dashboard.html", encoding="utf-8").read()
    i = h.index("async function beobSteuern(")
    assert "apiPost('/api/beobachtung/steuern',{dienst:dienst,aktion:aktion})" in h[i:h.index("\n}", i)]
    ok("W148: Prometheus- und Grafana-Waechter messen, heilen hinter dem Gate, Deck steuert nur feste Befehle")



def _test_v42_w148_codex_193():
    """v4.2-W148: zwei Befunde aus dem Codex-Review von #193, beide nachgestellt.

    (1) Die Einstellungen beim Start verbanden sich unter MariaDB mit den
    Vorgaben "nightcrawler" — der Bot nimmt "tiktok_bot". Mit Vorgabewerten
    wirkten die Deck-Einstellungen damit nie, still auf die .env zurueck.
    (2) envdatei.lesen() schnitt ` #` auch in Anfuehrungszeichen ab; der
    gekuerzte Wert landete per uebernehmen() in der Datenbank."""
    import ast as _ast
    import os as _os
    import sys as _sys
    import types as _types
    from nc import einstellungen as E
    from nc import envdatei as V

    # (1) Gemessen am Aufruf, nicht am Text: eine pymysql-Attrappe faengt die
    # Verbindungsdaten, und die Vorgaben des Bots stehen im Baum von bot.py.
    baum = _ast.parse(open("bot.py", encoding="utf-8").read())
    vorgabe = {}
    for n in baum.body:
        if isinstance(n, _ast.Assign) and isinstance(n.value, _ast.Call) \
                and getattr(n.value.func, "attr", "") == "getenv" and len(n.value.args) == 2 \
                and isinstance(n.value.args[0], _ast.Constant) \
                and str(n.value.args[0].value).startswith("MARIADB_"):
            vorgabe[n.value.args[0].value] = n.value.args[1].value
    assert vorgabe.get("MARIADB_USER") and vorgabe.get("MARIADB_DB"), vorgabe
    gefangen = {}

    class _Halt(Exception):
        pass

    def _connect(**kw):
        gefangen.update(kw)
        raise _Halt()
    alt = _sys.modules.get("pymysql")
    _sys.modules["pymysql"] = _types.SimpleNamespace(connect=_connect)
    try:
        try:
            E._start_lesen({"DB_BACKEND": "mariadb"})
        except _Halt:
            pass
    finally:
        if alt is None:
            _sys.modules.pop("pymysql", None)
        else:
            _sys.modules["pymysql"] = alt
    assert gefangen["user"] == vorgabe["MARIADB_USER"], gefangen
    assert gefangen["database"] == vorgabe["MARIADB_DB"], gefangen
    assert gefangen["host"] == vorgabe["MARIADB_HOST"], gefangen

    # (2) Werte wie python-dotenv — gegengeprueft mit dotenv selbst, wenn da.
    d = _ph.verzeichnis()
    f = _os.path.join(d, ".env")
    with open(f, "w", encoding="utf-8") as fh:
        fh.write('PROMPT="answer #1"\nB=x # kommentar\nC=\'a # b\' # k\n'
                 'D="a\\"b"\nexport E=frei\nG="mit #hash" # dahinter\n')
    w = V.lesen(f)
    assert w == {"PROMPT": "answer #1", "B": "x", "C": "a # b", "D": 'a"b',
                 "E": "frei", "G": "mit #hash"}, w
    # Codex #194: in '…' gelten \\' und \\\\, in "…" auch \\n/\\t;
    # \\n in '…' bleibt woertlich.
    f2 = _os.path.join(d, "q.env")
    with open(f2, "w", encoding="utf-8") as fh:
        fh.write("A='It\\'s # live'\nB='a\\\\b'\nC='x\\ny'\nD=\"x\\ny\"\nE=\"t\\tz\"\n")
    w2 = V.lesen(f2)
    assert w2 == {"A": "It's # live", "B": "a\\b", "C": "x\\ny", "D": "x\ny", "E": "t\tz"}, w2
    # Ohne schliessendes Zeichen: nur das oeffnende weg, wie bisher.
    assert V.wert_lesen('"offen') == "offen" and V.wert_lesen("'offen ") == "offen"
    try:
        from dotenv import dotenv_values
    except ImportError:
        dotenv_values = None
    if dotenv_values is not None:
        assert dict(dotenv_values(f)) == w, (dict(dotenv_values(f)), w)
        assert dict(dotenv_values(f2)) == w2, (dict(dotenv_values(f2)), w2)
    ok("W148: Codex #193 — MariaDB-Vorgaben wie der Bot, .env-Werte wie python-dotenv")


def _test_v42_w148_beobachtung_fehlerpfade():
    """v4.2-W148: die Fehlerpfade der beiden Waechter und des Durchreichers.

    Die Ueberdeckungssperre fiel mit +15 — und alle 15 waren Fehlerpfade,
    genau die Klasse aus W89 („alle fuenf waren die neuen Fehlerpfade").
    Gedeckt statt die Grundlinie zu heben."""
    import http.server as _hs
    import os as _os
    import subprocess as _sp
    import threading as _th
    from brain.agents import GrafanaAgent, PrometheusAgent
    from nc import beobachtungsdienst as B
    from nc import durchreicher as D

    # (1) Der echte Abruf gegen einen lokalen Server: 200 mit Text, 404 als
    # Antwort (kein Ausfall), Kopf geht mit, JSON-Fehler -> None.
    gesehen = []

    class _H(_hs.BaseHTTPRequestHandler):
        def do_GET(self):
            gesehen.append(self.headers.get("Authorization"))
            code = 200 if self.path.startswith("/ok") else 404
            self.send_response(code)
            self.end_headers()
            self.wfile.write(b"kein json" if code == 200 else b"weg")

        def log_message(self, *a):
            pass
    srv = _hs.HTTPServer(("127.0.0.1", 0), _H)
    _th.Thread(target=srv.serve_forever, daemon=True).start()
    try:
        basis = "http://127.0.0.1:%d" % srv.server_address[1]
        assert B._holen(basis + "/ok") == (200, "kein json")
        assert B._holen(basis + "/fehlt", {"Authorization": "Basic x"})[0] == 404
        assert gesehen[-1] == "Basic x"
        assert B._json(B._holen, basis + "/ok") == (200, None)
        # /-/ready mit 404: der Dienst lebt, ist aber nicht bereit.
        nb = B.prometheus_lage(basis)
        assert not nb["erreichbar"] and "HTTP 404" in nb["fehler"], nb
        gn = B.grafana_lage(basis, "admin", "x")
        assert not gn["erreichbar"] and "HTTP 404" in gn["fehler"], gn
    finally:
        srv.shutdown()
        srv.server_close()

    # (2) Eine Teilabfrage scheitert: der Rest bleibt, der Grund steht da.
    def _halb(url, kopf=None):
        if url.endswith("/-/ready") or url.endswith("/api/health"):
            return 200, '{"database":"ok"}'
        raise TimeoutError("zu langsam")
    t = B.prometheus_lage("http://p", holen=_halb)
    assert t["erreichbar"] and "TimeoutError" in t["fehler"], t
    g = B.grafana_lage("http://g", "admin", "pw", holen=_halb)
    assert g["erreichbar"] and g["db_ok"] and "TimeoutError" in g["fehler"], g
    assert B.grafana_lage("", holen=_halb)["fehler"] == "GRAFANA_URL fehlt"

    def _tot(url, kopf=None):
        raise ConnectionRefusedError("aus")
    assert "ConnectionRefusedError" in B.grafana_lage("http://g", holen=_tot)["fehler"]
    # Abgelehnte Anmeldung: keine weiteren Fragen mit falschem Passwort.
    fragen = []

    def _abgelehnt(url, kopf=None):
        fragen.append(url)
        return (200, '{"database":"ok"}') if url.endswith("/api/health") else (401, "")
    a = B.grafana_lage("http://g", "admin", "falsch", holen=_abgelehnt)
    assert a["anmeldung_ok"] is False and a["quelle_ok"] is None and len(fragen) == 2, (a, fragen)

    # (3) Steuern: OSError und Timeout sind Antworten mit Grund, kein Absturz.
    def _oserr(cmd, **kw):
        raise FileNotFoundError("sudo")

    def _zeit(cmd, **kw):
        raise _sp.TimeoutExpired(cmd, 60)
    assert not B.steuern("prometheus", "neu_starten", run=_oserr)["ok"]
    r = B.steuern("prometheus", "neu_starten", run=_zeit)
    assert not r["ok"] and "TimeoutExpired" in r["text"], r

    class _R:
        returncode, stderr, stdout = 5, "", ""
    assert "rc=5" in B.steuern("prometheus", "neu_laden", run=lambda c, **k: _R())["text"]

    # (4) Die Werte von JETZT: ohne URL kein Netz, mit Grund.
    alt = {k: _os.environ.get(k) for k in ("PROMETHEUS_URL", "GRAFANA_URL")}
    try:
        for k in alt:
            _os.environ.pop(k, None)
        assert B.prometheus_jetzt()["fehler"] == "PROMETHEUS_URL fehlt"
        assert B.grafana_jetzt()["fehler"] == "GRAFANA_URL fehlt"
    finally:
        for k, v in alt.items():
            if v is not None:
                _os.environ[k] = v

    # (5) Die Waechter: gescheiterter Neustart ist crit, Grafana-Ausfall heilt,
    # defekte Grafana-Datenbank ist crit, ohne Accessor still.
    class _Mem:
        def record_metric(self, k, v):
            pass

    class _Hirn:
        memory = _Mem()
    p = PrometheusAgent(_Hirn(), lage=lambda: {"erreichbar": True, "liest_bot": False})
    assert "up=0" in p.run({})[0]["text"]
    w = PrometheusAgent(_Hirn(), lage=lambda: {"erreichbar": False},
                        steuern=lambda d, a: {"ok": False, "text": "sudo verlangt ein Passwort"},
                        act_check=lambda n: True)
    w.run({})
    f = w.run({})
    assert f[-1]["level"] == "crit" and "Passwort" in f[-1]["text"], f
    gst = []
    gw = GrafanaAgent(_Hirn(), lage=lambda: {"erreichbar": False},
                      steuern=lambda d, a: gst.append(d) or {"ok": True, "befehl": "x"},
                      act_check=lambda n: n == "grafana")
    gw.run({})
    assert "neu gestartet" in gw.run({})[-1]["text"] and gst == ["grafana"]
    assert GrafanaAgent(_Hirn(), lage=lambda: {"erreichbar": True, "db_ok": False}).run({})[0]["level"] == "crit"
    assert GrafanaAgent(_Hirn()).run({}) == []
    assert GrafanaAgent(_Hirn(), lage=lambda: 1 / 0).run({})[0]["level"] == "warn"

    # (6) Durchreicher: Cookie-Datei geht mit, ffmpeg startet nicht -> der
    # Zieher wird beendet; ein Zieher, der nicht endet, wird getoetet.
    d = _ph.verzeichnis()
    keks = _os.path.join(d, "c.txt")
    open(keks, "w").close()
    y = D.zieher_cmd("yt-dlp", "/x/yt-dlp", "anna", cookies=keks)
    assert y[y.index("--cookies") + 1] == keks
    env = D.zieher_umgebung({"RECORD_PROXY": "http://h:1"})
    assert env["HTTPS_PROXY"] == "http://h:1", "Schema doppelt vorangestellt"

    class _Stur:
        def __init__(self):
            self.getoetet = False
            self.stdout = None

        def poll(self):
            return None

        def terminate(self):
            pass

        def wait(self, timeout=None):
            if timeout is not None and not self.getoetet:
                raise _sp.TimeoutExpired("x", timeout)
            return 0

        def kill(self):
            self.getoetet = True
    stur = _Stur()
    D._beende(stur)
    assert stur.getoetet, "ein Zieher, der SIGTERM ignoriert, laeuft weiter"
    D._beende(None)

    class _Weg(_Stur):
        def terminate(self):
            raise ProcessLookupError("schon weg")
    D._beende(_Weg())          # schon beendet: kein Fehler, nichts zu tun
    gestartet = []

    def _popen(cmd, **kw):
        if gestartet:
            raise OSError("ffmpeg fehlt")
        z = _Stur()
        gestartet.append(z)
        return z
    assert D.main(["anna", "-", "--", "ffmpeg"], popen=_popen,
                  which=lambda n: "/x/yt-dlp" if n == "yt-dlp" else None) == 2
    assert gestartet[0].getoetet, "Zieher nach gescheitertem ffmpeg nicht beendet"
    ok("W148: Fehlerpfade — echter Abruf, Teilabfragen, Steuerfehler, gescheiterter Neustart, sturer Zieher")

def _test_v42_w149_tiefengrund():
    """v4.2-W149: Tiefengrund-Bughunt — elf Befunde, jeder mit Gegenprobe.

    Der teuerste: hinter dem nginx, den der Installer im Zugang "proxy"
    selbst einrichtet, kam jede Anfrage aus dem Internet als 127.0.0.1 an,
    und `_auth_guard` liess Loopback ohne PIN und Token durch. Das ganze Deck
    war offen — genau in der Betriebsart, die fuer den Zugriff von aussen
    gebaut ist.
    """
    import io as _io
    import os as _os
    import sqlite3 as _sq
    from nc import clientip as CI
    from nc import ledger as L
    from nc import donations as DN
    from nc import envdatei as EV
    from nc import retention as RET
    from nc import storage as ST
    from nc import updater as UP
    from nc import dbwrap as _dbw
    from nc.routes import wartung as WA

    # (1) Lokal ist nur, wer KEINEN Weiterleitungskopf traegt.
    LB = ("127.0.0.1", "localhost", "::1")
    assert CI.ist_lokal("127.0.0.1", {}, set(), LB) is True, "SSH-Tunnel ausgesperrt"
    assert CI.ist_lokal("127.0.0.1", {"X-Forwarded-For": "203.0.113.9"}, set(), LB) is False, \
        "Anfrage ueber den lokalen Proxy gilt als Loopback — Deck ohne Anmeldung offen"
    assert CI.ist_lokal("127.0.0.1", {"X-Forwarded-For": "203.0.113.9"},
                        {"127.0.0.1"}, LB) is False
    assert CI.ist_lokal("127.0.0.1", {"X-Forwarded-For": "127.0.0.1, 203.0.113.9"},
                        {"127.0.0.1"}, LB) is False, \
        "ein vom Client vorangestelltes 127.0.0.1 oeffnet das Deck"
    assert CI.ist_lokal("127.0.0.1", {"X-Forwarded-For": "127.0.0.1"},
                        {"127.0.0.1"}, LB) is True, "curl auf dem Rechner durch den Proxy"
    assert CI.ist_lokal("127.0.0.1", {"X-Real-IP": "203.0.113.9"}, {"127.0.0.1"}, LB) is False
    assert CI.ist_lokal("198.51.100.1", {}, set(), LB) is False
    # (2) XFF von rechts: der linke Eintrag gehoert dem Client.
    assert CI.echte_ip("127.0.0.1", "1.2.3.4, 203.0.113.9", {"127.0.0.1"}) == "203.0.113.9", \
        "PIN-Sperre per gefaelschtem X-Forwarded-For umgehbar"
    assert CI.echte_ip("198.51.100.1", "1.2.3.4", {"127.0.0.1"}) == "198.51.100.1"
    assert CI.echte_ip("127.0.0.1", "203.0.113.9, 10.0.0.2", {"127.0.0.1", "10.0.0.2"}) \
        == "203.0.113.9", "zweistufiger Proxy"
    src = open("bot.py", encoding="utf-8").read()
    g = src[src.index("def _auth_guard("):src.index("def _auth_cookie(")]
    assert "_ist_lokal()" in g and "remote_addr" not in g, "Guard prueft wieder remote_addr"
    assert g.index("_AUTH_EXEMPT_EXACT") < g.index("if not DASHBOARD_TOKEN and not DASHBOARD_PIN:"), \
        "ohne Geheimnis muessen die Ausnahmen (OAuth, /healthz) weiter frei sein"
    assert "erlaubt_offen()" in g, "ohne Geheimnis ist ueber den Proxy wieder alles offen"
    r = src[src.index("def _rate_guard("):src.index("def _pwa_dir(")]
    assert "_ist_lokal()" in r and "remote_addr or \"\") in _LOOPBACK" not in r
    ok("W149: hinter dem lokalen Proxy gilt keine Anfrage mehr als Loopback, XFF von rechts")

    # (3) Steuer-Journal: eine Storno-Buchung aus dem Deck (storno_of als
    # Zeichenkette) brach die Hash-Kette.
    c = _sq.connect(":memory:")
    c.row_factory = _sq.Row
    L.add_entry(c, "2026-01-05", "kick", "100")
    L.add_entry(c, "2026-01-06", "kick", "-100", kind="correction", storno_of="1")
    assert L.verify_chain(c)["ok"] is True, "Storno aus dem Deck meldet die Kette als gebrochen"
    # Neue Buchungen haengen NICHT am Altbestand-Ausweg: ihr Hash stimmt mit
    # der Ganzzahl, so wie sie in der Tabelle steht (Mutationsprobe W149).
    z = c.execute("SELECT * FROM revenue_entries WHERE id=2").fetchone()
    assert L._hash_row(z["prev_hash"], L._payload_of(z)) == z["row_hash"], \
        "storno_of wird weiter als Zeichenkette gehasht"
    for args, kw in ((("2026-13-45", "kick", "1"), {}), (("2026-01-01", "kick", "nan"), {}),
                     (("2026-01-01", "kick", "inf"), {}),
                     (("2026-01-01", "kick", "10"), {"fee_eur": "-5"}),
                     (("2026-01-01", "kick", "-1"), {"kind": "correction", "storno_of": "99"}),
                     (("2026-01-01", "kick", "-1"), {"kind": "correction", "storno_of": "x"})):
        try:
            L.add_entry(c, *args, **kw)
            raise AssertionError("gebucht: %r %r" % (args, kw))
        except L.LedgerError:
            pass
    # Altbestand: Hash ueber die Zeichenkette gilt weiter, eine Betrags-
    # aenderung faellt trotzdem auf.
    c.execute("DELETE FROM revenue_entries WHERE id=2")
    prev = c.execute("SELECT row_hash FROM revenue_entries WHERE id=1").fetchone()[0]
    alt = {"seq_year": 2026, "seq_no": 2, "booked_on": "2026-01-06", "platform": "kick",
           "kind": "correction", "gross_eur": -100.0, "fee_eur": 0.0, "net_eur": -100.0,
           "currency": "EUR", "doc_ref": "", "storno_of": "1"}
    c.execute("INSERT INTO revenue_entries (seq_year,seq_no,booked_on,platform,kind,gross_eur,"
              "fee_eur,net_eur,currency,storno_of,created_at,prev_hash,row_hash) VALUES "
              "(2026,2,'2026-01-06','kick','correction',-100,0,-100,'EUR','1','x',?,?)",
              (prev, L._hash_row(prev, alt)))
    assert L.verify_chain(c)["ok"] is True, "Altbestand-Storno als Manipulation gemeldet"
    c.execute("UPDATE revenue_entries SET gross_eur=-50 WHERE id=3")
    assert L.verify_chain(c)["ok"] is False, "Manipulation am Altbestand bleibt unentdeckt"
    # (4) Die Gegenprobe zaehlt keine Zeilen ohne Plattform (B138-GELD).
    c2 = _sq.connect(":memory:")
    c2.row_factory = _sq.Row
    # ANKER GEWANDERT (v4.2-W178): die Gegenprobe rechnet ueber to_eur und
    # liest dafuer auch `message` (Sub ohne Betrag) — die Spalte hat die echte
    # Tabelle seit jeher, nur diese Attrappe nicht.
    c2.execute("CREATE TABLE overlay_events (kind TEXT, platform TEXT, amount TEXT, ts TEXT, "
               "message TEXT)")
    c2.executemany("INSERT INTO overlay_events VALUES ('donation',?,?,?,'')",
                   [(None, "500", "2026-03-01"), ("kick", "20", "2026-03-01")])
    cc = L.crosscheck(c2, 2026, "('kick','twitch','youtube','manuell')")
    assert cc["overlay_estimate_eur"] == 20.0, "TikTok-Altbestand ohne Plattform zaehlt als Kick: %r" % cc
    ok("W149: Storno haelt die Hash-Kette, nan/inf/13. Monat/Phantom-Storno abgelehnt")

    # (5) Spenden: die Waehrung des Betrags schlaegt "bits" in der Nachricht.
    assert DN.to_eur("$50.00", "youtube", "fuer 100 bits Spass") == 46.0
    assert DN.to_eur("100 Bits", "twitch") == 1.0
    assert DN.to_eur("", "twitch", "bits: 500") == 5.0, "Docstring-Form 'bits: 500' greift nicht"
    ok("W149: Superchat mit 'bits' im Text zaehlt in seiner Waehrung")

    # (6) Retention und stuendliches Aufraeumen lassen markierte Aufnahmen stehen.
    heim = _ph.verzeichnis()
    rec = _os.path.join(heim, "rec")
    _os.makedirs(rec)
    dbp = _os.path.join(heim, "w149.sqlite")
    k = _sq.connect(dbp)
    k.execute("CREATE TABLE recordings (id INTEGER PRIMARY KEY, filepath TEXT, created_at TEXT, "
              "starred INT DEFAULT 0, file_size INT, deleted_at TEXT)")
    stern = _ph.attrappe(_os.path.join(rec, "stern.mp4"), 1000)
    weg = _ph.attrappe(_os.path.join(rec, "weg.mp4"), 2000)
    k.executemany("INSERT INTO recordings (filepath, created_at, starred) VALUES (?,?,?)",
                  [(stern, "2020-01-01T00:00:00+00:00", 1), (weg, "2020-01-01T00:00:00+00:00", 0)])
    k.commit()
    k.close()
    for f in (stern, weg):
        _os.utime(f, (1_500_000_000, 1_500_000_000))
    alt_pfad, alt_backend = _dbw.DB_PATH, _dbw.DB_BACKEND
    try:
        configure_db(db_path=dbp, backend="sqlite")
        e = ST.cleanup(rec, days=30, dry_run=True)
        assert e["would_delete"] == 1, "stuendliches Aufraeumen trifft die markierte: %r" % e
        r = RET.scan(30, rec, delete=True)
        assert r["count"] == 1 and _os.path.isfile(stern) and not _os.path.exists(weg), \
            "Retention loescht die markierte Aufnahme: %r" % r
        configure_db(db_path=_os.path.join(heim, "fehlt", "x.db"), backend="sqlite")
        e = ST.cleanup(rec, days=30)
        assert e["deleted"] == 0 and e.get("error") and _os.path.isfile(stern), \
            "ohne Datenbank wird geraten statt abgebrochen: %r" % e
    finally:
        configure_db(db_path=alt_pfad, backend=alt_backend)
    ok("W149: markierte Aufnahmen ueberleben Retention und Aufraeumen; ohne DB kein Raten")

    # (7) days=0 faellt nicht still auf 30 Tage Loeschung zurueck.
    assert WA._tage_aus(None, 0) == (30, False) and WA._tage_aus("", 7) == (7, False)
    assert WA._tage_aus("0", 7) == (0, False) and WA._tage_aus(0, 7) == (0, False), \
        "days=0 wird zur Vorgabe"
    assert WA._tage_aus("abc", 7)[1] is True and WA._tage_aus(True, 7)[1] is True
    ok("W149: Retention-Lauf mit days=0 wird abgelehnt statt mit 30 Tagen ausgefuehrt")

    # (8) .env: geschrieben wird, was dotenv genauso zurueckliest.
    # python-dotenv steht nicht in jedem CI-Job; wo es fehlt, halten die
    # festen Schreibweisen und der eigene Leser die Aussage, wo es da ist,
    # liest der Bot-Leser selbst gegen.
    try:
        from dotenv import dotenv_values
    except ImportError:
        dotenv_values = None
    fest = {"abc #12": "'abc #12'", "'q": "'\\'q'", " rand": "' rand'",
            "x y": "x y", "http://127.0.0.1:3000": "http://127.0.0.1:3000", "#x": "#x"}
    for v, erwartet in fest.items():
        assert EV.wert_schreiben(v) == erwartet, (v, EV.wert_schreiben(v))
    for v in ("abc #12", "'q", "a\\b'c", " rand", "x y", "http://127.0.0.1:3000", "#x"):
        zeile = "K=" + EV.wert_schreiben(v)
        if dotenv_values is not None:
            assert dotenv_values(stream=_io.StringIO(zeile))["K"] == v, (v, zeile)
        assert EV.wert_lesen(EV.wert_schreiben(v)) == v, v
    env = _os.path.join(heim, ".env")
    with open(env, "w") as f:
        f.write("A=1\n")
    try:
        EV.setzen(env, {"P": "x${HOME}"}, "probe")
        raise AssertionError("${ geschrieben — load_dotenv wertet es aus")
    except EV.EnvdateiFehler:
        pass
    ok("W149: .env-Werte mit ' #', Anfuehrungszeichen und Rand-Leerzeichen kommen heil zurueck")

    # (9) Das Update laedt genau den gemeldeten Commit.
    alt_open = UP._open
    gesehen = []

    class _Antwort:
        headers = {}
        def __enter__(self): return self
        def __exit__(self, *a): return False
        def read(self, n=-1): return b""
    try:
        UP._open = lambda url, accept: (gesehen.append(url), _Antwort())[1]
        UP.download_zip(sha="abc123")
    finally:
        UP._open = alt_open
    assert gesehen and gesehen[0].endswith("/zip/abc123"), gesehen
    assert 'sha=rem.get("sha")' in open("nc/updater.py", encoding="utf-8").read()
    ok("W149: das Update spielt den Commit ein, dessen SHA es sich merkt")

    # (10) Archiv: wer die Datei nicht loeschen kann, loescht die Zeile nicht.
    q = open("nc/archive.py", encoding="utf-8").read()
    rumpf = q[q.index("def delete_archive_entry("):]
    rumpf = rumpf[:rumpf.index('return True, ""')]
    # Gemessen an der Rueckgabe, nicht am Kommentar: der zitiert den alten Satz.
    assert 'return False, f"Datei nicht' in rumpf, "Zeile faellt trotz liegengebliebener Datei"
    # (11) Dubletten-Loeschen: die Wurzel kommt vom Server.
    a = open("nc/routes/archive.py", encoding="utf-8").read()
    d = a[a.index("def api_archive_duplicates_delete("):a.index("def api_archive():")]
    assert 'payload.get("scan_root"' not in d and "_scan_wurzel()" in d and "realpath" in d, \
        "scan_root aus der Anfrage — Loeschwerkzeug fuer das ganze Dateisystem"
    r = open("nc/routes/recordings.py", encoding="utf-8").read()
    r = r[r.index("def api_rec_retention_apply("):]
    assert "_nc_sicherpfad.unter(rec_root, fp)" in r[:3000], "Regel-Retention ohne Pfad-Riegel"
    ok("W149: Archiv- und Regel-Loeschung nur im eigenen Ordner, Spur bleibt bei Fehlschlag")

    # (12) OAuth-Rueckruf: ohne ausgegebenen state kein Tausch, jeder state
    # genau einmal. Der Rueckruf ist ohne Anmeldung erreichbar.
    import asyncio as _aio
    from nc import twitchoauth as TW
    from nc import ytoauth as YT
    for M in (TW, YT):
        alt = M._state["csrf"]
        try:
            M._state["csrf"] = ""
            okk, txt = _aio.run(M.exchange_code("fremder-code", "", None))
            assert okk is False and "CSRF" in txt, "%s tauscht ohne laufenden Flow" % M.__name__
            M._state["csrf"] = "s1"
            okk, _ = _aio.run(M.exchange_code("c", "falsch", None))
            assert okk is False and M._state["csrf"] == "s1", \
                "%s: ein falscher Rueckruf bricht den laufenden Flow ab (Codex #195)" % M.__name__
            _aio.run(M.exchange_code("c", "s1", None))      # Treffer verbraucht ihn
            assert M._state["csrf"] == "", "%s: state nach Treffer nicht verbraucht" % M.__name__
            okk, txt = _aio.run(M.exchange_code("c", "s1", None))
            assert okk is False and "CSRF" in txt, "%s: verbrauchter state gilt erneut" % M.__name__
        finally:
            M._state["csrf"] = alt
    ok("W149: OAuth-Rueckruf ohne laufenden Flow abgelehnt, state nur einmal gueltig")


def _test_v42_w150_umzug_mit_journal_und_archiv():
    """v4.2-W150: der Umzug nach MariaDB brach beim Betreiber ab.

        ABGEBROCHEN: Diese Tabellen der Quelle kennt das Schema nicht:
        intel_transcript_meta, intel_transcript_seg, lost_and_found,
        revenue_entries — Altbestand einer frueheren Fassung.

    Keine davon war Altbestand. Steuer-Journal und Stream-Archiv legen ihre
    Tabellen selbst an, beim ersten Gebrauch — sie standen in keinem Schema,
    das der Umzug kennt. Der angebotene Ausweg `--auslassen` haette die
    gebuchten Auszahlungen samt Hash-Kette zurueckgelassen. `lost_and_found`
    ist der Rest von `sqlite3 .recover`, dem Rettungsweg, den der Bot selbst
    empfiehlt.

    Gegen eine echte MariaDB 10.11 nachgefahren, drei weitere Befunde
    dahinter: das Journal-DDL war auf MariaDB nie lauffaehig
    (AUTOINCREMENT), jedes `%` in einem Datensatz liess den Import scheitern,
    und das Archiv schickte `%%s` an pymysql — keine Abfrage lief."""
    import logging as _lg
    import os as _os
    import sqlite3 as _sq
    from nc import dbwrap as W
    from nc import ledger as L
    from nc import mariadbumzug as U
    from nc.intel import transcripts as T
    from nc.sqlutil import _translate_sql

    # (1) Das MariaDB-Schema traegt Journal und Archiv — lauffaehig.
    sqls = _w143_schema_mariadb()
    spalten, _ = _w143_tabellen(sqls)
    for t in ("revenue_entries", "intel_transcript_meta", "intel_transcript_seg"):
        assert t in spalten, "%s fehlt im MariaDB-Schema" % t
    roh = [q for q in sqls if "revenue_entries" in q or "intel_transcript" in q]
    assert not [q for q in roh if "AUTOINCREMENT" in q], "SQLite-DDL fuer MariaDB (1064)"
    for c in ("booked_on", "platform", "kind", "currency", "created_at"):
        assert spalten["revenue_entries"][c][0].startswith("VARCHAR"), c
    ok("W150: Steuer-Journal und Archiv stehen im Schema, das MariaDB-DDL ist lauffaehig")

    # (2) Die Kette mit einer Quelle wie beim Betreiber.
    alt = (W.DB_PATH, W.DB_BACKEND)
    log = _lg.getLogger("w150")
    d = _ph.verzeichnis()
    try:
        src, dst = _os.path.join(d, "quelle.db"), _os.path.join(d, "ziel.db")
        _w143_quelle(src)
        W.configure_db(db_path=src, backend="sqlite")
        with W.db_conn() as c:
            L.add_entry(c, "2026-03-01", "kick", "120,50", fee_eur="2", note="100% Anteil")
            L.add_entry(c, "2026-03-02", "kick", "-120.50", kind="correction", storno_of="1")
            T.save_segments(c, 7, [{"start": 0, "end": 1, "text": "50% mehr"}],
                            lang="de", paramstyle="qmark")
        r = _sq.connect(src)
        r.execute("CREATE TABLE lost_and_found(rootpgno INTEGER, pgno INTEGER, "
                  "nfield INTEGER, id INTEGER, c0, c1)")
        r.execute("INSERT INTO lost_and_found VALUES (3, 7, 2, NULL, 'frag', x'00ff')")
        r.commit()
        r.close()
        aus = []
        b = U.umziehen(sqlite_pfad=src, ziel_backend="sqlite", mariadb={"db_path": dst},
                       log=log, ausgabe=aus.append, trotzdem_aktiv=True)
        assert b["trocken"] is False, b
        assert any("lost_and_found" in z and ".recover" in z for z in aus), aus
        W.configure_db(db_path=dst, backend="sqlite")
        with W.db_conn() as c:
            assert c.execute("SELECT COUNT(*) AS n FROM revenue_entries").fetchone()["n"] == 2
            assert L.verify_chain(c)["ok"] is True, "Hash-Kette nach dem Umzug gebrochen"
            assert c.execute("SELECT text FROM intel_transcript_seg").fetchone()["text"] == "50% mehr"
            da = {x["name"] for x in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        assert "lost_and_found" not in da, "der .recover-Rest ist mitgezogen"
        r = _sq.connect(src)
        assert r.execute("SELECT COUNT(*) FROM lost_and_found").fetchone()[0] == 1, \
            "der .recover-Rest ist aus der Quelle verschwunden"
        r.close()
    finally:
        W.configure_db(db_path=alt[0], backend=alt[1])
    ok("W150: Umzug nimmt Journal (Kette intakt) und Archiv mit, .recover-Rest bleibt in der Quelle")

    # (3) '%' unter pymysql: mit Parametern ueberall verdoppelt, ohne gar nicht.
    assert _translate_sql("INSERT INTO x VALUES ('100% w', ?)") == \
        "INSERT INTO x VALUES ('100%% w', %s)"
    assert _translate_sql("INSERT INTO x VALUES ('100% w')", mit_parametern=False) == \
        "INSERT INTO x VALUES ('100% w')"
    assert _translate_sql("SELECT 1 WHERE a LIKE '%b%' AND c=?") == \
        "SELECT 1 WHERE a LIKE '%%b%%' AND c=%s"

    class _Cur:
        lastrowid = rowcount = 0

        def execute(self, q, a):
            self.q, self.a = q, a
    k = W._MariaDBCursorWrap(_Cur())
    k.execute("INSERT INTO x VALUES ('100% w')")
    assert k._c.a is None and k._c.q == "INSERT INTO x VALUES ('100% w')", (k._c.q, k._c.a)
    k.execute("SELECT ? AS v", (1,))
    assert k._c.a == (1,) and k._c.q == "SELECT %s AS v"
    # (4) Das Archiv spricht qmark — db_conn uebersetzt selbst.
    src_bot = open("bot.py", encoding="utf-8").read()
    assert '\n_INTEL_PS = "qmark"\n' in src_bot, "Archiv schickt %s durch die Uebersetzung (%%s)"
    assert "_nc_schema.modultabellen(conn, backend=DB_BACKEND, log=log)" in src_bot
    ok("W150: Prozentzeichen in Daten und LIKE ueberleben pymysql, das Archiv laeuft auf MariaDB")


def _test_v42_w151_mariadb_vergleicht_bytegenau():
    """v4.2-W151: der Umzug brach an 1062 auf loyalty_points ab.

        Duplicate entry 'tiktok:nora' for key 'PRIMARY'
        Duplicate entry 'tiktok:ängie' … 'tiktok:ｊａｎａ' … 'tiktok:ℍ'

    SQLite vergleicht bytegenau, MariaDB mit utf8mb4_unicode_ci nicht:
    gross/klein, Akzente und Schmuckschrift gelten dort als gleich. Gegen eine
    echte MariaDB 10.11 gemessen: 'ängie' = 'angie' unter unicode_ci, und
    utf8mb4_bin vergleicht 'a' = 'a ' (PAD SPACE). Nur utf8mb4_nopad_bin
    trennt alles, was SQLite trennt."""
    import logging as _lg
    from nc import schema as S
    from nc import ledger as L

    assert S.KOLLATION == "utf8mb4_nopad_bin"
    assert S.KOLLATION in S.parameter("mariadb")["tbl_opts"]
    assert "COLLATE=" + S.KOLLATION in L._SCHEMA_MARIADB
    ddl = [q for q in _w143_schema_mariadb() if "CREATE TABLE" in q]
    assert ddl and not [q for q in ddl if "unicode_ci" in q or "general_ci" in q], \
        "eine Tabelle vergleicht nicht bytegenau"
    sh = open("tools/lib/system.sh", encoding="utf-8").read()
    assert "unicode_ci" not in sh and "COLLATE utf8mb4_nopad_bin" in sh

    # Schon angelegte Tabellen (abgebrochener Umzug, aeltere Fassung) werden
    # angeglichen — CREATE TABLE IF NOT EXISTS allein fasst sie nie an.
    class _R:
        def __init__(self, rows):
            self.rows = rows

        def fetchall(self):
            return self.rows

    class _C:
        def __init__(self):
            self.sql = []

        def execute(self, q, p=()):
            self.sql.append(q)
            if "information_schema.TABLES" in q:
                return _R([{"t": "loyalty_points", "k": "utf8mb4_unicode_ci"},
                           {"t": "trackings", "k": S.KOLLATION}])
            return _R([])

        def commit(self):
            pass

        def cursor(self):
            return self
    c = _C()
    assert S.kollation_angleichen(c, log=_lg.getLogger("w151")) == ["loyalty_points"]
    assert any("ALTER TABLE `loyalty_points` CONVERT TO CHARACTER SET utf8mb4 COLLATE "
               "utf8mb4_nopad_bin" in q for q in c.sql), c.sql
    assert not any("`trackings`" in q for q in c.sql), "eine passende Tabelle wird umgebaut"
    c = _C()
    S.anlegen(c, backend="mariadb", mariadb_db="x", log=_lg.getLogger("w151"))
    assert any("CONVERT TO CHARACTER SET" in q for q in c.sql), "der Umzug gleicht nicht an"
    b = open("bot.py", encoding="utf-8").read()
    assert "_nc_schema.kollation_angleichen(conn, log=log)" in b
    assert '_nc_schema.parameter("mariadb")["tbl_opts"]' in b
    ok("W151: MariaDB vergleicht bytegenau wie SQLite, alte Tabellen werden angeglichen")


def _test_v42_w152_cookies_pin_rollback():
    """v4.2-W152: drei kleine Befunde aus der zweiten Runde.

    (1) Die Sitzungs-Cookies trugen `Secure` nur bei DASHBOARD_TLS_CERT. Hinter
    dem nginx des Installers terminiert der Proxy das TLS — das Deck sah http
    und schickte PIN- und Token-Cookie ohne `Secure`. (2) compare_digest auf
    str wirft TypeError bei Nicht-ASCII: ein "ä" im PIN-Feld gab HTTP 500 und
    zaehlte nicht als Fehlversuch. (3) Ein Rollback konnte neben einem
    laufenden Update schreiben."""
    from nc import clientip as CI
    from nc import updater as UP
    import hmac as _hm

    T = {"127.0.0.1"}
    assert CI.ist_https("127.0.0.1", {"X-Forwarded-Proto": "https"}, T) is True
    assert CI.ist_https("127.0.0.1", {"X-Forwarded-Proto": "http"}, T) is False
    assert CI.ist_https("203.0.113.9", {"X-Forwarded-Proto": "https"}, T) is False, \
        "X-Forwarded-Proto von einem Fremden geglaubt"
    assert CI.ist_https("127.0.0.1", {}, set(), tls_direkt=True) is True
    assert CI.ist_https("127.0.0.1", {}, set(), schema="https") is True
    src = open("bot.py", encoding="utf-8").read()
    assert src.count("secure=_cookie_sicher())") == 2, "ein Sitzungs-Cookie ohne Proxy-Erkennung"
    assert 'secure=bool(os.getenv("DASHBOARD_TLS_CERT"' not in src

    try:
        _hm.compare_digest("ä", "1234")
        raise AssertionError("compare_digest nimmt Nicht-ASCII-str — der Befund ist hinfaellig")
    except TypeError:
        pass
    assert 'compare_digest(given.encode("utf-8"), DASHBOARD_PIN.encode("utf-8"))' in src
    assert 'compare_digest(str(given).encode("utf-8"),' in src

    alt = (dict(UP._JOB), UP._CFG.enabled)
    try:
        UP._CFG.enabled = True
        UP._JOB["running"] = True
        r = UP.rollback("nc_update_x.zip")
        assert r["ok"] is False and "Update" in r["error"], r
        UP._JOB["running"] = False
        UP._JOB["phase"] = "done"
        r = UP.rollback("kein_backup.zip")
        assert r["ok"] is False and UP._JOB["running"] is False and UP._JOB["phase"] == "done", \
            "der Rollback hinterlaesst den Job-Merker"
    finally:
        UP._JOB.clear()
        UP._JOB.update(alt[0])
        UP._CFG.enabled = alt[1]

    m = open("nc/routes/money.py", encoding="utf-8").read()
    rumpf = m[m.index("def api_donations_summary("):m.index("def api_finanzamt_entries(")]
    assert "except Exception:\n                pass" not in rumpf, \
        "die Liste liest nach einem Fehler das Ergebnis der vorigen Abfrage"
    # (4) Einstellungen auf dem Handy: das starre Raster gab der Eingabe
    # mindestens 220px, und das Feld lag ueber dem Variablennamen.
    h = open("templates/dashboard.html", encoding="utf-8").read()
    z = h[h.index("function _esZeile(e)"):h.index("function einstZeigen()")]
    assert "grid-template-columns" not in z and "flex-wrap:wrap" in z, "starres Raster zurueck"
    assert z.count("min-width:0") >= 3 and "overflow-wrap:anywhere" in z
    ok("W152: Secure-Cookies hinter dem Proxy, Nicht-ASCII-PIN ohne 500, kein Rollback neben dem Update")


def _test_v42_w153_discord_bereiche_folgen_den_trackings():
    """v4.2-W153: gemeldet „discord, wo alle getrackten User einen Channel
    bekommen sollten und die, die nicht mehr getrackt sind, die Channel
    sollten gelöscht werden". Bis hierher nur /setup_targets: von Hand, nur
    anlegend, gedeckelt, ohne pausierte Trackings."""
    import ast as _ast
    from nc import discordziele as Z

    # (1)–(5) Anlegen/Loeschen je Nutzer: abgeloest durch W168 (ein Clip-Kanal,
    # Bereiche werden umgezogen statt angelegt) — dort geprueft.
    assert not hasattr(Z, "plan"), "W168: es werden wieder Nutzer-Bereiche geplant"

    # (6) Verdrahtung: eigene Schleife, /setup_targets nutzt denselben Abgleich,
    # pausierte Trackings zaehlen mit.
    d = open("discordbot.py", encoding="utf-8").read()
    baum = _ast.parse(d)
    oben = {n.name for n in baum.body if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}
